# 热路径别名：Layer / _matmul 每次调用都要用到 operator.mul
_mul = operator.mul

# GELU 的 tanh 近似常数：sqrt(2/pi)
_GELU_C = math.sqrt(2.0 / math.pi)
# SiLU / Mish / ELU / SELU 的标量实现（Layer 与 FeedForward / SwiGLU 共用，
# 保证同一种激活在各处数值完全一致）
_SELU_LAMBDA = 1.0507009873554805
_SELU_ALPHA = 1.6732632423543772
_ELU_ALPHA = 1.0


def _silu_scalar(z: float) -> float:
    """SiLU / Swish：z * sigmoid(z)（LLaMA 的门控激活）"""
    if z >= 0.0:
        return z / (1.0 + math.exp(-z))
    e = math.exp(z)
    return z * e / (1.0 + e)


def _dsilu_scalar(z: float) -> float:
    if z >= 0.0:
        s = 1.0 / (1.0 + math.exp(-z))
    else:
        e = math.exp(z)
        s = e / (1.0 + e)
    return s * (1.0 + z * (1.0 - s))


def _softplus_scalar(z: float) -> float:
    """softplus(z) = log(1+exp(z))，z 很大时退化成 z（避免 exp 溢出）"""
    if z > 30.0:
        return z
    return math.log1p(math.exp(z))


def _mish_scalar(z: float) -> float:
    return z * math.tanh(_softplus_scalar(z))


def _dmish_scalar(z: float) -> float:
    sp = _softplus_scalar(z)
    t = math.tanh(sp)
    if z >= 0.0:
        s = 1.0 / (1.0 + math.exp(-z))
    else:
        e = math.exp(z)
        s = e / (1.0 + e)
    return t + z * (1.0 - t * t) * s


def _elu_scalar(z: float) -> float:
    return z if z > 0.0 else _ELU_ALPHA * (math.exp(z) - 1.0)


def _delu_scalar(z: float) -> float:
    return 1.0 if z > 0.0 else _ELU_ALPHA * math.exp(z)


def _selu_scalar(z: float) -> float:
    if z > 0.0:
        return _SELU_LAMBDA * z
    return _SELU_LAMBDA * _SELU_ALPHA * (math.exp(z) - 1.0)


def _dselu_scalar(z: float) -> float:
    if z > 0.0:
        return _SELU_LAMBDA
    return _SELU_LAMBDA * _SELU_ALPHA * math.exp(z)


# ============================================================================
#  Layer & MLP
# ============================================================================

class Layer:
    """一个全连接层 + 激活函数"""

    def __init__(self, fan_in: int, fan_out: int,
                 activation: str = "leaky_relu", is_output: bool = False):
        self.fan_in = fan_in
        self.fan_out = fan_out
        self.is_output = is_output

        # He 初始化
        std = math.sqrt(2.0 / fan_in)
        self.weights = [
            [random.gauss(0, std) for _ in range(fan_in)]
            for _ in range(fan_out)
        ]
        self.biases = [0.0] * fan_out

        # Adam 状态
        self.m_w = [[0.0] * fan_in for _ in range(fan_out)]
        self.v_w = [[0.0] * fan_in for _ in range(fan_out)]
        self.m_b = [0.0] * fan_out
        self.v_b = [0.0] * fan_out

        # 前向缓存
        self.input = None
        self.z = None
        self.a = None

        # 激活函数分发
        if activation == "leaky_relu":
            self.act_fn = self._leaky_relu
            self.act_deriv = self._leaky_relu_deriv
        elif activation == "relu":
            self.act_fn = self._relu
            self.act_deriv = self._relu_deriv
        elif activation == "softmax":
            self.act_fn = self._softmax
            self.act_deriv = self._softmax_deriv
        elif activation == "linear":
            self.act_fn = self._linear
            self.act_deriv = self._linear_deriv
        elif activation == "gelu":
            self.act_fn = self._gelu
            self.act_deriv = self._gelu_deriv
        elif activation == "sigmoid":
            self.act_fn = self._sigmoid
            self.act_deriv = self._sigmoid_deriv
        elif activation == "silu":
            self.act_fn = self._silu
            self.act_deriv = self._silu_deriv
        elif activation == "mish":
            self.act_fn = self._mish
            self.act_deriv = self._mish_deriv
        elif activation == "elu":
            self.act_fn = self._elu
            self.act_deriv = self._elu_deriv
        elif activation == "selu":
            self.act_fn = self._selu
            self.act_deriv = self._selu_deriv
        else:
            raise ValueError(f"Unknown activation: {activation}")

        # 记录激活函数名字符串（save_model 持久化 / 激活与损失的搭配校验用）
        self.activation_name = activation

# ============================================================================
#  激活函数
# ============================================================================
    def _linear(self, z):
        return z

    def _linear_deriv(self, z):
        return [1.0] * len(z)

    def _relu(self, z):
        return [max(0, zi) for zi in z]

    def _relu_deriv(self, z):
        return [1.0 if zi > 0 else 0.0 for zi in z]

    def _leaky_relu(self, z):
        return [zi if zi > 0 else 0.01 * zi for zi in z]

    def _leaky_relu_deriv(self, z):
        return [1.0 if zi > 0 else 0.01 for zi in z]

    def _gelu(self, z):
        # tanh 近似：0.5*z*(1+tanh(sqrt(2/pi)*(z+0.044715 z^3)))
        # 纯标准库没有 erf，GPT-2 用的 tanh 近似与精确 erf 版差异 < 2e-3
        out = []
        for zi in z:
            u = _GELU_C * (zi + 0.044715 * zi * zi * zi)
            out.append(0.5 * zi * (1.0 + math.tanh(u)))
        return out

    def _gelu_deriv(self, z):
        out = []
        for zi in z:
            u = _GELU_C * (zi + 0.044715 * zi * zi * zi)
            t = math.tanh(u)
            du = _GELU_C * (1.0 + 3.0 * 0.044715 * zi * zi)
            out.append(0.5 * (1.0 + t) + 0.5 * zi * (1.0 - t * t) * du)
        return out

    def _sigmoid(self, z):
        # 分支写法：x 很负时 exp(x) 不溢出（C 侧同一写法，逐位一致）
        out = []
        for zi in z:
            if zi >= 0:
                out.append(1.0 / (1.0 + math.exp(-zi)))
            else:
                e = math.exp(zi)
                out.append(e / (1.0 + e))
        return out

    def _sigmoid_deriv(self, z):
        s = self._sigmoid(z)
        return [si * (1.0 - si) for si in s]

    def _silu(self, z):
        return [_silu_scalar(zi) for zi in z]

    def _silu_deriv(self, z):
        return [_dsilu_scalar(zi) for zi in z]

    def _mish(self, z):
        return [_mish_scalar(zi) for zi in z]

    def _mish_deriv(self, z):
        return [_dmish_scalar(zi) for zi in z]

    def _elu(self, z):
        return [_elu_scalar(zi) for zi in z]

    def _elu_deriv(self, z):
        return [_delu_scalar(zi) for zi in z]

    def _selu(self, z):
        return [_selu_scalar(zi) for zi in z]

    def _selu_deriv(self, z):
        return [_dselu_scalar(zi) for zi in z]

    def _softmax(self, z):
        max_z = max(z)
        exp_z = [math.exp(zi - max_z) for zi in z]
        sum_exp = sum(exp_z)
        return [e / sum_exp for e in exp_z]

    def _softmax_deriv(self, z):
        """softmax 的「联合梯度约定」占位：恒返回 1，不乘 Jacobian。

        cross_entropy_loss / focal_loss 已直接返回 softmax+CE（或 focal）的联合梯度
        (pred - one_hot)，因此 softmax 层反向时不需要再乘 softmax 的 Jacobian。
        这个约定只对「输出层 softmax + 联合梯度损失」成立；把 softmax 放到隐藏层、
        或搭配 mse 等逐元素损失时，梯度会静默错误。对应防线：
        MLP 构造时拒绝隐藏层 softmax；Model 构造时拒绝 softmax + mse，并兜底拦截
        隐藏层 softmax。确实需要 softmax Jacobian 的场景请在自定义训练循环里
        显式实现，不要依赖这个类。
        """
        return [1.0] * len(z)

# ============================================================================
#  前向 / 反向
# ============================================================================
    def forward(self, x):
        # 维度不符时 map 会静默截断（少算或多算），必须早失败
        if len(x) != self.fan_in:
            hint = ""
            if x and isinstance(x[0], (list, tuple)):
                hint = "（输入看起来是图像/批量，请先用 Flatten 展平）"
            raise ValueError(
                f"Layer.forward: 输入长度 {len(x)} 与本层 fan_in={self.fan_in} 不一致"
                f"（本层 fan_out={self.fan_out}，激活={getattr(self, 'activation_name', '?')}"
                f"，is_output={getattr(self, 'is_output', '?')}）{hint}"
            )
        # 权重形状只在对象被替换后检查一次（Adam 只改元素、不换行对象），
        # 避免每次前向都做 O(fan_out) 的遍历
        if self.__dict__.get("_w_checked_for") is not self.weights:
            bad = (len(self.weights) != self.fan_out
                   or any(len(row) != self.fan_in for row in self.weights))
            if bad:
                raise ValueError(
                    f"Layer.forward: 权重形状应为 {self.fan_out}×{self.fan_in}，"
                    f"实际 {len(self.weights)} 行（首行 {len(self.weights[0]) if self.weights else 0} 列），"
                    f"模型可能已损坏（请检查加载的文件）"
                )
            self.__dict__["_w_checked_for"] = self.weights
        self.input = x
        # sum(map(mul, row, x)) 走 C 层的 map/sum，比 sum(w*xi for ...) 快约 1.8 倍
        W, b = self.weights, self.biases
        self.z = [sum(map(_mul, W[j], x)) + b[j] for j in range(self.fan_out)]
        self.a = self.act_fn(self.z)
        return self.a

    def backward(self, delta):
        """delta: 本层输出的梯度

        返回 **(grad_w, grad_b, next_delta)** —— 三元组，最后一个元素才是传给
        上一层的 delta。容器（`Sequential` / `ResidualBlock`）通过模块的
        `delta_index` 属性决定取哪一项（默认 -1；`BatchNorm1d` 的 dx 在第 0 位）。
        """
        if self.z is None:
            raise RuntimeError("Layer.backward: 必须先调用 forward()（没有缓存的 z）")
        if len(delta) != self.fan_out:
            raise ValueError(
                f"Layer.backward: delta 长度 {len(delta)} 与本层输出维度 {self.fan_out} 不一致"
            )
        d_act = self.act_deriv(self.z)

        # delta * d_act 同时是 grad_b 与回传给上一层的权重向量，只算一次
        w = [delta[j] * d_act[j] for j in range(self.fan_out)]
        grad_w = [[s * xi for xi in self.input] for s in w]
        grad_b = list(w)

        # 传给上一层的 delta = W^T · (delta * d_act)
        # zip(*W) 在 C 层完成转置，再用 map(mul) 做点积，比双重索引的 genexpr 快约 1.9 倍
        next_delta = [sum(map(_mul, col, w)) for col in zip(*self.weights)]

        return grad_w, grad_b, next_delta


class Linear(Layer):
    """无激活的全连接层：y = Wx + b

    等价于 Layer(..., activation="linear")，单独命名是为了让"纯投影"在代码里
    一目了然（也与 PyTorch nn.Linear 的语义对齐）。
    """

    def __init__(self, fan_in: int, fan_out: int):
        super().__init__(fan_in, fan_out, activation="linear")


# ============================================================================
#  初始化族（全部是"显式调用才生效"的工具函数，不改变任何默认路径）
# ============================================================================

def _init_layers(target):
    """把 Layer / MLP / 层列表统一成层列表（只收带 2D `weights` 的对象）"""
    if hasattr(target, "layers"):
        layers = list(target.layers)
    elif isinstance(target, (list, tuple)):
        layers = list(target)
    else:
        layers = [target]
    out = []
    for i, layer in enumerate(layers):
        w = getattr(layer, "weights", None)
        if not w or not isinstance(w[0], (list, tuple)):
            raise TypeError(
                f"初始化函数: 第 {i} 个对象没有 2D `weights`（需要 Layer，"
                f"收到 {type(layer).__name__}）")
        out.append(layer)
    if not out:
        raise ValueError("初始化函数: 目标里没有可初始化的层")
    return out


def init_lecun_normal(target, fan_in: Optional[int] = None):
    """LeCun 正态初始化：std = sqrt(1/fan_in)

    `fan_in` 显式给出时用它（同一个系数套用到所有层），否则逐层取 `layer.fan_in`。
    """
    if fan_in is not None:
        if isinstance(fan_in, bool) or not isinstance(fan_in, int) or fan_in < 1:
            raise ValueError(f"init_lecun_normal: fan_in 必须是正整数，收到 {fan_in!r}")
    for layer in _init_layers(target):
        n = fan_in if fan_in is not None else layer.fan_in
        std = math.sqrt(1.0 / n)
        for i in range(len(layer.weights)):
            for j in range(len(layer.weights[i])):
                layer.weights[i][j] = random.gauss(0.0, std)
    return target


def init_lecun_uniform(target, fan_in: Optional[int] = None):
    """LeCun 均匀初始化：U(-b, b)，b = sqrt(3/fan_in)（与正态同方差）"""
    if fan_in is not None:
        if isinstance(fan_in, bool) or not isinstance(fan_in, int) or fan_in < 1:
            raise ValueError(f"init_lecun_uniform: fan_in 必须是正整数，收到 {fan_in!r}")
    for layer in _init_layers(target):
        n = fan_in if fan_in is not None else layer.fan_in
        bound = math.sqrt(3.0 / n)
        for i in range(len(layer.weights)):
            for j in range(len(layer.weights[i])):
                layer.weights[i][j] = random.uniform(-bound, bound)
    return target


def init_orthogonal(target, gain: float = 1.0):
    """正交初始化：行（fan_out <= fan_in 时）或列（否则）两两正交、模长 = gain

    用 Gram-Schmidt 逐行正交化；`fan_out > fan_in` 时行不可能全部正交，
    改为对列做正交化并保持每行模长 = gain（与 PyTorch 的处理一致：
    在较大的那个维度上做正交化）。
    """
    if not isinstance(gain, (int, float)) or isinstance(gain, bool):
        raise TypeError(f"init_orthogonal: gain 必须是数字，收到 {type(gain).__name__}")
    if not math.isfinite(float(gain)):
        raise ValueError(f"init_orthogonal: gain 必须是有限数，收到 {gain!r}")
    for layer in _init_layers(target):
        rows = len(layer.weights)
        cols = len(layer.weights[0])
        if rows <= cols:
            # 逐行正交化
            for i in range(rows):
                vec = [random.gauss(0.0, 1.0) for _ in range(cols)]
                for k in range(i):
                    prev = layer.weights[k]
                    dot = sum(vec[j] * prev[j] for j in range(cols))
                    sq = sum(prev[j] * prev[j] for j in range(cols))
                    if sq < 1e-24:
                        continue
                    coef = dot / sq
                    for j in range(cols):
                        vec[j] -= coef * prev[j]
                nrm = math.sqrt(sum(v * v for v in vec))
                if nrm < 1e-12:
                    # 退化时退回到单位向量方向（极低概率），保证不产生 NaN
                    vec = [1.0 if j == i % cols else 0.0 for j in range(cols)]
                    nrm = 1.0
                scale = gain / nrm
                layer.weights[i] = [v * scale for v in vec]
        else:
            # 行比列多：按列正交化，再逐行缩放
            mat = [[random.gauss(0.0, 1.0) for _ in range(rows)] for _ in range(cols)]
            for i in range(cols):
                for k in range(i):
                    dot = sum(mat[i][r] * mat[k][r] for r in range(rows))
                    sq = sum(mat[k][r] * mat[k][r] for r in range(rows))
                    if sq < 1e-24:
                        continue
                    coef = dot / sq
                    for r in range(rows):
                        mat[i][r] -= coef * mat[k][r]
                nrm = math.sqrt(sum(v * v for v in mat[i]))
                if nrm < 1e-12:
                    mat[i] = [1.0 if r == i % rows else 0.0 for r in range(rows)]
                    nrm = 1.0
                mat[i] = [v / nrm for v in mat[i]]
            for i in range(rows):
                layer.weights[i] = [mat[j][i] * gain for j in range(cols)]
    return target


def init_sparse(target, sparsity: float = 0.9, std: Optional[float] = None):
    """稀疏初始化（Martens 2010）：以 `sparsity` 比例置零，非零项方差放大 1/(1-sparsity)

    `std` 不给时用 LeCun 正态的系数 sqrt(1/fan_in) 再除以 sqrt(1-sparsity)，
    使整体方差与稠密初始化同量级。
    """
    if not isinstance(sparsity, (int, float)) or isinstance(sparsity, bool):
        raise TypeError(f"init_sparse: sparsity 必须是数字，收到 {type(sparsity).__name__}")
    if not (0.0 <= float(sparsity) < 1.0):
        raise ValueError(f"init_sparse: sparsity 必须在 [0, 1) 内，收到 {sparsity!r}")
    if std is not None:
        if not isinstance(std, (int, float)) or isinstance(std, bool) or std < 0:
            raise ValueError(f"init_sparse: std 必须是非负数，收到 {std!r}")
    p = float(sparsity)
    for layer in _init_layers(target):
        base = float(std) if std is not None else math.sqrt(1.0 / layer.fan_in)
        for i in range(len(layer.weights)):
            for j in range(len(layer.weights[i])):
                if random.random() < p:
                    layer.weights[i][j] = 0.0
                else:
                    layer.weights[i][j] = random.gauss(0.0, base)
    return target


def init_trunc_normal(target, std: float = 0.02, cutoff: float = 2.0,
                      max_tries: int = 100):
    """截断正态初始化：|w| <= cutoff*std，且方差近似 std²

    用拒绝采样（ViT 的 trunc_normal_ 同思路）。`max_tries` 次都没采到就取边界值，
    保证一定终止（截断到 ±2σ 时单次接受率约 95%，连拒 100 次概率可忽略）。
    """
    for name, value in (("std", std), ("cutoff", cutoff)):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError(f"init_trunc_normal: {name} 必须是数字，收到 {type(value).__name__}")
        if not math.isfinite(float(value)) or float(value) <= 0:
            raise ValueError(f"init_trunc_normal: {name} 必须是正的有限数，收到 {value!r}")
    if isinstance(max_tries, bool) or not isinstance(max_tries, int) or max_tries < 1:
        raise ValueError(f"init_trunc_normal: max_tries 必须是正整数，收到 {max_tries!r}")
    limit = float(cutoff) * float(std)
    for layer in _init_layers(target):
        for i in range(len(layer.weights)):
            for j in range(len(layer.weights[i])):
                v = None
                for _ in range(max_tries):
                    cand = random.gauss(0.0, float(std))
                    if abs(cand) <= limit:
                        v = cand
                        break
                if v is None:
                    v = limit if random.random() < 0.5 else -limit
                layer.weights[i][j] = v
    return target


def zero_bias(target):
    """把（所有层的）偏置清零 —— 缩放技巧里常与权重零初始化配套使用"""
    layers = _init_layers(target)
    for layer in layers:
        b = getattr(layer, "biases", None)
        if b is not None:
            for i in range(len(b)):
                b[i] = 0.0
    return target


def zero_init_residual(block):
    """残差分支零初始化：把分支里**最后一个** BatchNorm 的 gamma 置零

    这样训练开始时残差分支输出恰为 0，块退化为 `out = act(x)`（恒等捷径），
    是 ResNet 论文里的 zero-init residual（Goyal et al. 2017 推广的做法）。
    支持 `BasicBlock2d`（零 `bn2.gamma`）与 `Bottleneck2d`（零 `bn3.gamma`），
    识别方式是"块里有 bn1/bn2/... 这类 BatchNorm2d 属性"，取其中**最后**一个；
    捷径投影的 `short_bn` 不属于分支，不会被清零。
    """
    # 只认分支内的 BN；short_bn 属于捷径投影，零它等于改捷径，不是 zero-init residual
    bn_names = ("bn1", "bn2", "bn3")
    found = [n for n in bn_names if hasattr(block, n)]
    if not found:
        raise TypeError(
            f"zero_init_residual: {type(block).__name__} 里没有 BatchNorm2d 分支"
            f"（查找 {bn_names}）")
    last = getattr(block, found[-1])
    gamma = getattr(last, "gamma", None)
    if gamma is None:
        raise TypeError(
            f"zero_init_residual: {found[-1]} 没有 gamma（不是 BatchNorm2d？）")
    for i in range(len(gamma)):
        gamma[i] = 0.0
    return block


def lsuv_init(target, x, tol: float = 1e-2, max_iter: int = 20):
    """LSUV（Layer-sequential unit-variance）初始化

    数据驱动：逐层前向真实样本，把该层的**预激活**（`W·x + b`，激活函数之前）
    整批拉成均值 0、标准差 1，然后再交给下一层。权重只整体缩放（保持方向），
    所以不破坏已有的正交性。

    为什么必须在预激活上做：如果拿 `relu(W·x)` 的输出算 std，偏置平移会把一半
    值压成 0，scale 调到位后 std 仍小于 1（实测 0.79），永远收敛不到 1。标准的
    LSUV 是在线性层输出上做的，本函数照此实现 —— 收敛后 `std_after` 应 ≈ 1。

    `target` 可以是单个 `Layer`，也可以是 `MLP`（按层顺序处理）。
    `x` 可以是单个样本，也可以是一批样本（`[[...], [...]]`）—— 用一批更稳，
    单样本时「逐单元标准差」只有一个数，容易退化。

    返回每层的 `{"layer", "scale", "bias_shift", "std_before", "std_after", "iters"}`。
    """
    if isinstance(target, MLP):
        layers = list(target.layers)
    elif isinstance(target, Layer):
        layers = [target]
    else:
        raise TypeError(
            f"lsuv_init: 只接受 Layer 或 MLP，收到 {type(target).__name__}")
    if isinstance(tol, bool) or not isinstance(tol, (int, float)):
        raise TypeError(f"lsuv_init: tol 必须是数字，收到 {type(tol).__name__}")
    if not math.isfinite(float(tol)) or tol <= 0:
        raise ValueError(f"lsuv_init: tol 必须是正有限数，收到 {tol!r}")
    if isinstance(max_iter, bool) or not isinstance(max_iter, int):
        raise TypeError(
            f"lsuv_init: max_iter 必须是 int，收到 {type(max_iter).__name__}")
    if max_iter < 1:
        raise ValueError(f"lsuv_init: max_iter 必须 >= 1，收到 {max_iter!r}")

    if x and isinstance(x[0], (list, tuple)):
        batch = [list(sample) for sample in x]
        if not batch:
            raise ValueError("lsuv_init: 样本批不能为空")
        width = len(batch[0])
        if any(len(sample) != width for sample in batch):
            raise ValueError("lsuv_init: 批里各样本长度必须一致")
    else:
        batch = [list(x)]

    def _preact(layer, samples):
        fan_in = len(layer.weights[0]) if layer.weights else 0
        for sample in samples:
            if len(sample) != fan_in:
                raise ValueError(
                    f"lsuv_init: 样本长度 {len(sample)} 与该层输入维度 {fan_in} 不一致")
        vals = []
        for sample in samples:
            for i in range(len(layer.weights)):
                acc = layer.biases[i]
                wi = layer.weights[i]
                for j in range(len(wi)):
                    acc += wi[j] * sample[j]
                vals.append(acc)
        d = len(vals)
        mean = sum(vals) / d
        var = sum((v - mean) ** 2 for v in vals) / d
        return math.sqrt(var), mean

    report = []
    for idx, layer in enumerate(layers):
        if not isinstance(layer, Layer):
            raise TypeError(
                f"lsuv_init: 第 {idx} 层是 {type(layer).__name__}，"
                "只有带 weights/biases 的 Layer 支持 LSUV")
        std, mean = _preact(layer, batch)
        before = std
        scale = 1.0
        iters = 0
        while abs(std - 1.0) > tol and std > 1e-12 and iters < max_iter:
            f = 1.0 / std
            for i in range(len(layer.weights)):
                for j in range(len(layer.weights[i])):
                    layer.weights[i][j] *= f
            scale *= f
            std, mean = _preact(layer, batch)
            iters += 1
        shift = -mean
        for i in range(len(layer.biases)):
            layer.biases[i] += shift
        std2, mean2 = _preact(layer, batch)
        report.append({"layer": idx, "scale": scale, "bias_shift": shift,
                       "std_before": before, "std_after": std2, "iters": iters})
        batch = [layer.forward(sample) for sample in batch]
    return report


def fixup_init(target, num_blocks: Optional[int] = None):
    """Fixup 初始化（残差分支缩放 + 该层偏置置零）

    Fixup 的可移植内核是：残差分支的**最后一层**按 `1/sqrt(块数)` 缩放，且该层
    偏置为 0（这样残差分支初始接近恒等，深层也能训）。本库的残差结构是
    `BasicBlock2d`（conv2）、`Bottleneck2d`（conv3）、`DenseBlock`（每层的 conv）
    与带 skip 的 `MLP` 无关，所以这里作用在块对象上。

    `target` 可以是单个块、也可以是块的列表；`num_blocks` 不给时按 `sqrt(len(块))`
    推断（传进来的块数就是总块数的常见用法）。返回 `{"scales": [...], "num_blocks"}`。
    """
    if isinstance(target, (BasicBlock2d, Bottleneck2d, DenseBlock)):
        blocks = [target]
    elif isinstance(target, (list, tuple)):
        blocks = list(target)
        if not blocks:
            raise ValueError("fixup_init: 块列表不能为空")
    else:
        raise TypeError(
            "fixup_init: 只接受 BasicBlock2d / Bottleneck2d / DenseBlock 或其列表，"
            f"收到 {type(target).__name__}")
    for b in blocks:
        if not isinstance(b, (BasicBlock2d, Bottleneck2d, DenseBlock)):
            raise TypeError(
                f"fixup_init: 列表里出现了 {type(b).__name__}，"
                "只支持 BasicBlock2d / Bottleneck2d / DenseBlock")
    if num_blocks is None:
        n = len(blocks)
    else:
        if isinstance(num_blocks, bool) or not isinstance(num_blocks, int):
            raise TypeError(
                f"fixup_init: num_blocks 必须是 int，收到 {type(num_blocks).__name__}")
        if num_blocks < 1:
            raise ValueError(f"fixup_init: num_blocks 必须 >= 1，收到 {num_blocks!r}")
        n = num_blocks
    scale = 1.0 / math.sqrt(n)
    scales = []
    for b in blocks:
        if isinstance(b, BasicBlock2d):
            last = b.conv2
        elif isinstance(b, Bottleneck2d):
            last = b.conv3
        else:
            last = b.convs[-1]
        # Conv2d 的 weights 是 [out][in][kh][kw] 四层嵌套，得逐个叶子缩放
        for i in range(len(last.weights)):
            for j in range(len(last.weights[i])):
                w = last.weights[i][j]
                if isinstance(w, list):
                    for a in range(len(w)):
                        for b in range(len(w[a])):
                            w[a][b] *= scale
                else:
                    last.weights[i][j] = w * scale
        for i in range(len(last.biases)):
            last.biases[i] = 0.0
        scales.append(scale)
    return {"scales": scales, "num_blocks": n}


def mimic_init(student, teacher):
    """Mimic Init（NET2NET 的宽度/深度迁移，只支持 MLP）

    宽度：学生比老师宽时，把老师的权重块复制到左上角、其余用 `1/sqrt(fan_in)`
    量级的小随机补齐（保持输出方差不炸）；比老师窄时截断。
    深度：学生比老师深时，按顺序复制前 `len(teacher)` 层，多出的层用 Xavier 初始化。

    两层 `Layer` 的激活必须一致，否则报错（复制权重但换激活没有意义）。
    返回 `{"widths": [...], "depth_copied": k}`。
    """
    if not isinstance(student, MLP) or not isinstance(teacher, MLP):
        raise TypeError("mimic_init: student 与 teacher 都必须是 MLP")
    if len(student.layers) != len(teacher.layers):
        n = min(len(student.layers), len(teacher.layers))
    else:
        n = len(student.layers)
    widths = []
    for k in range(n):
        sl = student.layers[k]
        tl = teacher.layers[k]
        if sl.activation_name != tl.activation_name:
            raise ValueError(
                f"mimic_init: 第 {k} 层激活不一致（学生 {sl.activation_name} / "
                f"老师 {tl.activation_name}），复制权重没有意义")
        so = len(sl.weights)
        si = len(sl.weights[0])
        to = len(tl.weights)
        ti = len(tl.weights[0])
        fan_in = si
        std = math.sqrt(1.0 / max(1, fan_in))
        rng = random.Random(0)
        for i in range(min(so, to)):
            for j in range(min(si, ti)):
                sl.weights[i][j] = tl.weights[i][j]
            for j in range(ti, si):
                sl.weights[i][j] = rng.gauss(0.0, std)
        for i in range(to, so):
            for j in range(si):
                sl.weights[i][j] = rng.gauss(0.0, std)
        for i in range(min(so, to)):
            sl.biases[i] = tl.biases[i]
        widths.append((so, si, to, ti))
    return {"widths": widths, "depth_copied": n}


class MLP:
    """多层感知机（PyTorch 风格）"""

    def __init__(self, layer_sizes: List[int],
                 activations: Optional[List[str]] = None):
        if len(layer_sizes) < 2:
            raise ValueError(f"MLP: layer_sizes 至少需要 2 个维度（输入+输出），收到 {layer_sizes}")
        if any(d <= 0 for d in layer_sizes):
            raise ValueError(f"MLP: 每一维都必须 >= 1，收到 {layer_sizes}")
        self.layer_sizes = layer_sizes

        if activations is None:
            activations = ["leaky_relu"] * (len(layer_sizes) - 2)
            activations.append("linear")

        # 必须在默认填充之后校验：否则 activations=None 时这里就 len(None) 崩了
        if len(activations) != len(layer_sizes) - 1:
            raise ValueError(
                f"MLP: 需要 {len(layer_sizes) - 1} 个激活函数（层数 = 维度数-1），"
                f"收到 {len(activations)} 个"
            )

        # 隐藏层 softmax 会在反向时静默算错：Layer._softmax_deriv 恒返回 1，
        # 只在「输出层 softmax + 联合梯度损失（CE / focal）」下成立。放在隐藏层
        # 或搭配 mse 等逐元素损失时梯度不自洽（有限差分相对误差可达 100%），
        # 因此在构造时就拒绝，而不是等训练时训歪。
        for i, name in enumerate(activations[:-1]):
            if name == "softmax":
                raise ValueError(
                    f"MLP: 第 {i + 1} 层是隐藏层却使用 softmax 激活——"
                    "softmax 只能作为最后一层（输出层），并搭配 cross_entropy / focal "
                    "等联合梯度损失；隐藏层请改用 relu / leaky_relu / tanh 等。"
                )

        self.layers = []
        for i in range(1, len(layer_sizes)):
            is_output = (i == len(layer_sizes) - 1)
            layer = Layer(
                fan_in=layer_sizes[i - 1],
                fan_out=layer_sizes[i],
                activation=activations[i - 1],
                is_output=is_output,
            )
            self.layers.append(layer)

        # 前向/反向 hook：{层索引: 回调}。没注册时下面只多一次真假判断，
        # 不影响任何数值（注册了也只观察，不参与计算）
        self._fhooks = {}
        self._bhooks = {}

    def forward(self, x):
        for i, layer in enumerate(self.layers):
            x = layer.forward(x)
            if self._fhooks:
                fn = self._fhooks.get(i)
                if fn is not None:
                    fn(layer, x)
        return x

# ── hook（调试/可视化用，注册了才生效）

    def register_forward_hook(self, index: int, fn):
        """在第 index 层前向后调用 fn(layer, output)；返回 fn 本身便于保存"""
        if not callable(fn):
            raise TypeError(f"MLP.register_forward_hook: fn 必须可调用，收到 {fn!r}")
        if not isinstance(index, int) or isinstance(index, bool):
            raise TypeError(f"MLP.register_forward_hook: index 必须是整数，收到 {index!r}")
        if not 0 <= index < len(self.layers):
            raise ValueError(
                f"MLP.register_forward_hook: index={index} 越界（共 {len(self.layers)} 层）"
            )
        self._fhooks[index] = fn
        return fn

    def register_backward_hook(self, index: int, fn):
        """在第 index 层反向后调用 fn(layer, delta_in, grad_w, grad_b)"""
        if not callable(fn):
            raise TypeError(f"MLP.register_backward_hook: fn 必须可调用，收到 {fn!r}")
        if not isinstance(index, int) or isinstance(index, bool):
            raise TypeError(f"MLP.register_backward_hook: index 必须是整数，收到 {index!r}")
        if not 0 <= index < len(self.layers):
            raise ValueError(
                f"MLP.register_backward_hook: index={index} 越界（共 {len(self.layers)} 层）"
            )
        self._bhooks[index] = fn
        return fn

    def remove_hook(self, index: int, kind: str = 'forward'):
        """注销某一层的 hook（kind 取 'forward' / 'backward'）"""
        table = self._fhooks if kind == 'forward' else self._bhooks
        if kind not in ('forward', 'backward'):
            raise ValueError(f"MLP.remove_hook: kind 只能是 'forward'/'backward'，收到 {kind!r}")
        table.pop(index, None)

    def clear_hooks(self):
        """注销全部 hook"""
        self._fhooks.clear()
        self._bhooks.clear()

    def get_parameters(self):
        params = []
        for layer in self.layers:
            params.append((layer.weights, layer.biases))
        return params

# ── 参数量与模型瘦身（与 C 引擎 c_model.cpp 的实现语义一致）

    def param_count(self):
        """可训练参数总数（权重 + 偏置）"""
        return sum(l.fan_in * l.fan_out + l.fan_out for l in self.layers)

    def sparsity(self):
        """权重中恰好为 0 的比例（剪枝后用来看稀疏度）"""
        total = sum(l.fan_in * l.fan_out for l in self.layers)
        if total == 0:
            return 0.0
        zeros = sum(1 for l in self.layers for row in l.weights for w in row if w == 0.0)
        return zeros / total

    def prune_magnitude(self, threshold):
        """幅度剪枝：把 |w| < threshold 的权重置 0，返回被剪掉的个数"""
        if threshold <= 0:
            return 0
        pruned = 0
        for l in self.layers:
            for j in range(l.fan_out):
                row = l.weights[j]
                for i in range(l.fan_in):
                    if abs(row[i]) < threshold:
                        row[i] = 0.0
                        pruned += 1
        return pruned

    def quantize_weights(self, bits):
        """权重定点量化：按全局 min/max 均匀分档，返回量化步长（bits 需在 2..24）"""
        if not (2 <= bits <= 24):
            return -1.0
        vals = [w for l in self.layers for row in l.weights for w in row]
        if not vals:
            return -1.0
        lo, hi = min(vals), max(vals)
        if hi <= lo:
            return -1.0
        step = (hi - lo) / ((1 << bits) - 1)
        for l in self.layers:
            for j in range(l.fan_out):
                row = l.weights[j]
                for i in range(l.fan_in):
                    row[i] = lo + round((row[i] - lo) / step) * step
        return step

    def merge_weights(self, other, w_self=0.5, w_other=0.5):
        """权重线性合并：self = w_self*self + w_other*other（结构必须一致）

        做 K 折权重平均时各折必须从同一初值出发，否则隐藏单元排列不同，
        直接平均会得到无意义的模型（这一点在 C 引擎的 CLI 里踩过）。
        """
        if self.layer_sizes != other.layer_sizes:
            raise ValueError(f"结构不一致: {self.layer_sizes} vs {other.layer_sizes}")
        for la, lb in zip(self.layers, other.layers):
            for j in range(la.fan_out):
                ra, rb = la.weights[j], lb.weights[j]
                for i in range(la.fan_in):
                    ra[i] = w_self * ra[i] + w_other * rb[i]
                la.biases[j] = w_self * la.biases[j] + w_other * lb.biases[j]
        return self

    def __repr__(self):
        return f"MLP({self.layer_sizes})"


# ============================================================================
#  CNN: Conv2d / MaxPool2d / Flatten
# ============================================================================

class Conv2d:
    """2D 卷积层 (im2col 实现, 纯 Python 列表)"""

    def __init__(self, in_channels: int, out_channels: int,
                 kernel_size, stride=1, padding=0, groups: int = 1,
                 dilation=1):
        if not isinstance(groups, int) or isinstance(groups, bool) or groups < 1:
            raise ValueError(f"Conv2d: groups 必须是 >=1 的整数，收到 {groups!r}")
        if in_channels % groups != 0:
            raise ValueError(
                f"Conv2d: in_channels={in_channels} 必须能被 groups={groups} 整除"
            )
        if out_channels % groups != 0:
            raise ValueError(
                f"Conv2d: out_channels={out_channels} 必须能被 groups={groups} 整除"
            )
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.groups = groups
        # 每个输出通道只连本组的 C/groups 个输入通道（groups=1 时就是原来的 C）
        self.cg = in_channels // groups
        self.og = out_channels // groups
        self.kernel_size = (kernel_size, kernel_size) if isinstance(kernel_size, int) else kernel_size
        self.stride = (stride, stride) if isinstance(stride, int) else stride
        self.padding = (padding, padding) if isinstance(padding, int) else padding
        self.dilation = ((dilation, dilation) if isinstance(dilation, int)
                         else tuple(dilation))
        self.kh, self.kw = self.kernel_size
        self.sh, self.sw = self.stride
        if self.kh <= 0 or self.kw <= 0:
            raise ValueError(f"Conv2d: kernel_size 必须为正，收到 {self.kernel_size}")
        if self.sh <= 0 or self.sw <= 0:
            raise ValueError(f"Conv2d: stride 必须为正，收到 {self.stride}")
        if min(self.padding) < 0:
            raise ValueError(f"Conv2d: padding 不能为负，收到 {self.padding}")
        if len(self.dilation) != 2 or min(self.dilation) <= 0:
            raise ValueError(f"Conv2d: dilation 必须是正数（或二元组），收到 {dilation!r}")
        self.ph, self.pw = self.padding
        self.dh, self.dw = self.dilation
        # 空洞卷积的等效感受野：(k-1)*d + 1
        self.kh_eff = (self.kh - 1) * self.dh + 1
        self.kw_eff = (self.kw - 1) * self.dw + 1

        # He 初始化（groups=1 时 fan_in 与原来的 in_channels*kh*kw 相同）
        fan_in = self.cg * self.kh * self.kw
        std = math.sqrt(2.0 / fan_in)
        self.weights = [
            [[[random.gauss(0, std) for _ in range(self.kw)]
              for _ in range(self.kh)]
             for _ in range(self.cg)]
            for _ in range(out_channels)
        ]
        self.biases = [0.0] * out_channels

        # Adam 状态
        self.m_w = [[[[0.0] * self.kw for _ in range(self.kh)]
                      for _ in range(self.cg)] for _ in range(out_channels)]
        self.v_w = [[[[0.0] * self.kw for _ in range(self.kh)]
                      for _ in range(self.cg)] for _ in range(out_channels)]
        self.m_b = [0.0] * out_channels
        self.v_b = [0.0] * out_channels

        # 前向缓存
        self.x_col = None
        self.x_shape = None

        self.zero_grad()

    def zero_grad(self):
        """初始化/清零梯度缓冲区（保留前向缓存 h_out/w_out 供 backward 使用）"""
        self.grad_w = [
            [[[0.0] * self.kw for _ in range(self.kh)]
             for _ in range(self.cg)]
            for _ in range(self.out_channels)
        ]
        self.grad_b = [0.0] * self.out_channels

# ============================================================================
#  辅助
# ============================================================================
    def _img_shape(self, H, W):
        ho = (H + 2 * self.ph - self.kh_eff) // self.sh + 1
        wo = (W + 2 * self.pw - self.kw_eff) // self.sw + 1
        # 输入比卷积核还小时 ho/wo 会是 0 或负数，原实现返回空输出而不报错
        if ho <= 0 or wo <= 0:
            raise ValueError(
                f"Conv2d: 输入 {H}x{W} 配 kernel {self.kh}x{self.kw}"
                f"（dilation {self.dh}/{self.dw} → 等效 {self.kh_eff}x{self.kw_eff}）、"
                f"padding {self.ph}/{self.pw}、stride {self.sh}/{self.sw} "
                f"得到输出 {ho}x{wo}，必须都 > 0"
            )
        return ho, wo

    def _pad(self, x):
        """对 (C, H, W) 做 zero-padding"""
        C = len(x)
        H = len(x[0])
        W = len(x[0][0])
        Hp = H + 2 * self.ph
        Wp = W + 2 * self.pw
        padded = [[[0.0] * Wp for _ in range(Hp)] for _ in range(C)]
        for c in range(C):
            for h in range(H):
                for w in range(W):
                    padded[c][h + self.ph][w + self.pw] = x[c][h][w]
        return padded

    def _im2col(self, x_padded, ho, wo):
        """将 padded (C, Hp, Wp) 转为 im2col 矩阵: (C*kh*kw, ho*wo)"""
        C = len(x_padded)
        col_rows = C * self.kh * self.kw
        col_cols = ho * wo
        col = [[0.0] * col_cols for _ in range(col_rows)]

        if self.sh == 1 and self.sw == 1:
            # stride=1 时每一行就是被卷积核在宽度方向上的连续切片，
            # 直接切片赋值（每个位置的值与逐元素写法完全相同）
            for c in range(C):
                ch = x_padded[c]
                for kh in range(self.kh):
                    for kw in range(self.kw):
                        row = c * self.kh * self.kw + kh * self.kw + kw
                        dst = col[row]
                        for oh in range(ho):
                            # 空洞：第 kh 行取输入的 kh*dh 行，列偏移 kw*dw
                            dst[oh * wo:(oh + 1) * wo] = ch[oh + kh * self.dh][
                                kw * self.dw:kw * self.dw + wo]
            return col

        for c in range(C):
            ch = x_padded[c]                      # 局部化，省掉每元素的二次索引
            for kh in range(self.kh):
                for kw in range(self.kw):
                    row = c * self.kh * self.kw + kh * self.kw + kw
                    dst = col[row]
                    for oh in range(ho):
                        src = ch[oh * self.sh + kh * self.dh]
                        off = oh * wo
                        for ow in range(wo):
                            dst[off + ow] = src[ow * self.sw + kw * self.dw]
        return col

    def _col2im(self, dcol, x_padded_shape, ho, wo):
        """将 dcol 梯度转回图像梯度 (C, Hp, Wp)"""
        C, Hp, Wp = x_padded_shape
        dx = [[[0.0] * Wp for _ in range(Hp)] for _ in range(C)]
        for c in range(C):
            for kh in range(self.kh):
                for kw in range(self.kw):
                    row = c * self.kh * self.kw + kh * self.kw + kw
                    for oh in range(ho):
                        for ow in range(wo):
                            ih = oh * self.sh + kh * self.dh
                            iw = ow * self.sw + kw * self.dw
                            dx[c][ih][iw] += dcol[row][oh * wo + ow]
        return dx

    def _flatten_weights(self, oc):
        """把第 oc 个输出通道的卷积核展平成 (cg*kh*kw,)，顺序与 im2col 的行一致"""
        out = []
        for ic in range(self.cg):
            for kh in range(self.kh):
                for kw in range(self.kw):
                    out.append(self.weights[oc][ic][kh][kw])
        return out

    def _unpad(self, dx_padded, H, W):
        """去掉 padding"""
        C = len(dx_padded)
        dx = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        for c in range(C):
            for h in range(H):
                for w in range(W):
                    dx[c][h][w] = dx_padded[c][h + self.ph][w + self.pw]
        return dx

# ============================================================================
#  前向 / 反向
# ============================================================================
    def forward(self, x):
        """x: (C, H, W) -> 输出 (out_channels, Ho, Wo)"""
        if len(x) != self.in_channels:
            raise ValueError(
                f"Conv2d.forward: 输入通道 {len(x)} != in_channels={self.in_channels}"
            )
        C, H, W = len(x), len(x[0]), len(x[0][0])
        ho, wo = self._img_shape(H, W)
        self.h_out, self.w_out = ho, wo
        self.x_shape = (C, H, W)

        # 分组卷积：每组只把本组的 C/groups 个输入通道卷进本组的 out/groups 个输出通道。
        # groups=1 时循环只跑一次，运算与原来逐位相同。
        self.cols = []
        outs = []
        for g in range(self.groups):
            xg = x if self.groups == 1 else x[g * self.cg:(g + 1) * self.cg]
            xg_pad = self._pad(xg) if (self.ph > 0 or self.pw > 0) else xg
            col = self._im2col(xg_pad, ho, wo)      # (cg*kh*kw, ho*wo)
            self.cols.append(col)

            # 一次 matmul 算出本组输出: (og, cg*kh*kw) × (cg*kh*kw, ho*wo)
            W_row = [self._flatten_weights(oc)
                     for oc in range(g * self.og, (g + 1) * self.og)]
            flat = _matmul(W_row, col)
            outs.append([
                [[flat[oc - g * self.og][oh * wo + ow] + self.biases[oc]
                  for ow in range(wo)]
                 for oh in range(ho)]
                for oc in range(g * self.og, (g + 1) * self.og)
            ])

        # 兼容旧代码（多处直接读 self.x_col）：单组时仍然指向那一份 col
        self.x_col = self.cols[0] if len(self.cols) == 1 else None
        if self.groups == 1:
            return outs[0]
        return [ch for grp in outs for ch in grp]

    def backward(self, dout):
        """
        dout: (out_channels, Ho, Wo) 梯度
        返回 dx: (C, H, W)
        内部累积 grad_w, grad_b
        """
        C, H, W = self.x_shape
        ho, wo = self.h_out, self.w_out

        # 把 dout 展成 (out_channels, ho*wo)
        dout_flat = []
        for oc in range(self.out_channels):
            flat = []
            for oh in range(ho):
                for ow in range(wo):
                    flat.append(dout[oc][oh][ow])
            dout_flat.append(flat)

        dx_groups = []
        for g in range(self.groups):
            col = self.cols[g]

            # grad_w: dW = dout_flat × col^T（累积到内部梯度缓冲区）
            # 即: grad_w[oc][ic][kh][kw] += sum over ho,wo: dout[oc][oh][ow] * col_row[oh*wo]
            # 点积交给 C 层的 map(mul)/sum，求和顺序与逐元素累加一致
            for oc in range(g * self.og, (g + 1) * self.og):
                d = dout_flat[oc]
                for ic in range(self.cg):
                    for kh in range(self.kh):
                        for kw in range(self.kw):
                            row = ic * self.kh * self.kw + kh * self.kw + kw
                            self.grad_w[oc][ic][kh][kw] += sum(map(_mul, d, col[row]))

            for oc in range(g * self.og, (g + 1) * self.og):
                self.grad_b[oc] += sum(dout_flat[oc])

            # dx: col2im  dcol = W_flat^T × dout_flat  (cg*kh*kw, ho*wo)
            dcol = [[0.0] * (ho * wo) for _ in range(len(col))]
            for oc in range(g * self.og, (g + 1) * self.og):
                d = dout_flat[oc]
                w_flat = self._flatten_weights(oc)
                for row in range(len(w_flat)):
                    w = w_flat[row]
                    # 累加顺序仍是「外层 oc、内层逐元素」，与原写法逐位一致
                    dcol[row] = [a + w * b for a, b in zip(dcol[row], d)]

            dx_padded = self._col2im(
                dcol, (self.cg, H + 2 * self.ph, W + 2 * self.pw), ho, wo)

            if self.ph > 0 or self.pw > 0:
                dx_groups.append(self._unpad(dx_padded, H, W))
            else:
                dx_groups.append(dx_padded)

        if self.groups == 1:
            return dx_groups[0]
        return [ch for grp in dx_groups for ch in grp]


class Conv1d:
    """1D 卷积层（输入 (C, L)，权重 [oc][cg][k]，He 初始化）

    没有走 im2col：1D 的核很小，直接滑动窗口累加比先展开成矩阵更省内存。
    groups 语义与 Conv2d 一致（每组只连本组的 C/groups 个输入通道）。
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, groups: int = 1):
        if not isinstance(groups, int) or isinstance(groups, bool) or groups < 1:
            raise ValueError(f"Conv1d: groups 必须是 >=1 的整数，收到 {groups!r}")
        if in_channels % groups != 0:
            raise ValueError(
                f"Conv1d: in_channels={in_channels} 必须能被 groups={groups} 整除"
            )
        if out_channels % groups != 0:
            raise ValueError(
                f"Conv1d: out_channels={out_channels} 必须能被 groups={groups} 整除"
            )
        if not isinstance(kernel_size, int) or isinstance(kernel_size, bool) or kernel_size <= 0:
            raise ValueError(f"Conv1d: kernel_size 必须是正整数，收到 {kernel_size!r}")
        if not isinstance(stride, int) or isinstance(stride, bool) or stride <= 0:
            raise ValueError(f"Conv1d: stride 必须是正整数，收到 {stride!r}")
        if not isinstance(padding, int) or isinstance(padding, bool) or padding < 0:
            raise ValueError(f"Conv1d: padding 必须是非负整数，收到 {padding!r}")

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.groups = groups
        self.cg = in_channels // groups
        self.og = out_channels // groups
        self.kernel_size = kernel_size
        self.k = kernel_size
        self.stride = stride
        self.s = stride
        self.padding = padding
        self.p = padding

        fan_in = self.cg * self.k
        std = math.sqrt(2.0 / fan_in)
        self.weights = [[[random.gauss(0, std) for _ in range(self.k)]
                         for _ in range(self.cg)]
                        for _ in range(out_channels)]
        self.biases = [0.0] * out_channels

        self.m_w = [[[0.0] * self.k for _ in range(self.cg)]
                    for _ in range(out_channels)]
        self.v_w = [[[0.0] * self.k for _ in range(self.cg)]
                    for _ in range(out_channels)]
        self.m_b = [0.0] * out_channels
        self.v_b = [0.0] * out_channels

        self.x = None
        self.l_out = 0

        self.zero_grad()

    def zero_grad(self):
        """清零梯度缓冲区"""
        self.grad_w = [[[0.0] * self.k for _ in range(self.cg)]
                       for _ in range(self.out_channels)]
        self.grad_b = [0.0] * self.out_channels

    def _out_len(self, L):
        lo = (L + 2 * self.p - self.k) // self.s + 1
        if lo <= 0:
            raise ValueError(
                f"Conv1d: 输入长度 {L} 配 kernel {self.k}、padding {self.p}、"
                f"stride {self.s} 得到输出长度 {lo}，必须 > 0"
            )
        return lo

    def forward(self, x):
        """x: (C, L) -> (out_channels, Lo)"""
        if len(x) != self.in_channels:
            raise ValueError(
                f"Conv1d.forward: 输入通道 {len(x)} != in_channels={self.in_channels}"
            )
        L = len(x[0])
        for c in range(len(x)):
            if len(x[c]) != L:
                raise ValueError("Conv1d.forward: 各通道长度必须一致")
        lo = self._out_len(L)
        self.x = x
        self.l_out = lo

        out = []
        for oc in range(self.out_channels):
            w_oc = self.weights[oc]
            ic0 = (oc // self.og) * self.cg
            row = [0.0] * lo
            for o in range(lo):
                total = self.biases[oc]
                base = o * self.s - self.p
                for ic in range(self.cg):
                    wic = w_oc[ic]
                    xc = x[ic0 + ic]
                    for k in range(self.k):
                        idx = base + k
                        if 0 <= idx < L:
                            total += wic[k] * xc[idx]
                row[o] = total
            out.append(row)
        return out

    def backward(self, dout):
        """dout: (out_channels, Lo) -> dx: (C, L)，内部累积 grad_w / grad_b"""
        if self.x is None:
            raise RuntimeError("Conv1d.backward: 请先调用 forward")
        L = len(self.x[0])
        lo = self.l_out
        dx = [[0.0] * L for _ in range(self.in_channels)]

        for oc in range(self.out_channels):
            d = dout[oc]
            self.grad_b[oc] += sum(d)
            w_oc = self.weights[oc]
            gw_oc = self.grad_w[oc]
            ic0 = (oc // self.og) * self.cg
            for o in range(lo):
                base = o * self.s - self.p
                dv = d[o]
                for ic in range(self.cg):
                    wic = w_oc[ic]
                    gwic = gw_oc[ic]
                    xc = self.x[ic0 + ic]
                    dxi = dx[ic0 + ic]
                    for k in range(self.k):
                        idx = base + k
                        if 0 <= idx < L:
                            gwic[k] += dv * xc[idx]
                            dxi[idx] += dv * wic[k]
        return dx


class ConvTranspose2d:
    """2D 转置卷积（反卷积）层：输入 (Cin, H, W) -> (Cout, Ho, Wo)

    输出尺寸 Ho = (H-1)*stride - 2*padding + kernel + output_padding。
    权重布局 [cin][og][kh][kw]，与 PyTorch 的 (in, out/groups, kh, kw) 一致。
    forward 把每个输入元素按核散开累加到输出，backward 与之对称。
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size,
                 stride=1, padding=0, output_padding=0, groups: int = 1):
        if not isinstance(groups, int) or isinstance(groups, bool) or groups < 1:
            raise ValueError(f"ConvTranspose2d: groups 必须是 >=1 的整数，收到 {groups!r}")
        if in_channels % groups != 0:
            raise ValueError(
                f"ConvTranspose2d: in_channels={in_channels} 必须能被 groups={groups} 整除"
            )
        if out_channels % groups != 0:
            raise ValueError(
                f"ConvTranspose2d: out_channels={out_channels} 必须能被 groups={groups} 整除"
            )
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.groups = groups
        self.cg = in_channels // groups
        self.og = out_channels // groups
        self.kernel_size = (kernel_size, kernel_size) if isinstance(kernel_size, int) else tuple(kernel_size)
        self.stride = (stride, stride) if isinstance(stride, int) else tuple(stride)
        self.padding = (padding, padding) if isinstance(padding, int) else tuple(padding)
        self.output_padding = ((output_padding, output_padding)
                               if isinstance(output_padding, int) else tuple(output_padding))
        self.kh, self.kw = self.kernel_size
        self.sh, self.sw = self.stride
        self.ph, self.pw = self.padding
        self.oph, self.opw = self.output_padding
        if self.kh <= 0 or self.kw <= 0:
            raise ValueError(f"ConvTranspose2d: kernel_size 必须为正，收到 {self.kernel_size}")
        if self.sh <= 0 or self.sw <= 0:
            raise ValueError(f"ConvTranspose2d: stride 必须为正，收到 {self.stride}")
        if self.ph < 0 or self.pw < 0:
            raise ValueError(f"ConvTranspose2d: padding 不能为负，收到 {self.padding}")
        if self.oph < 0 or self.opw < 0:
            raise ValueError(
                f"ConvTranspose2d: output_padding 不能为负，收到 {self.output_padding}"
            )
        # 与 PyTorch 一致：output_padding 必须小于 stride
        if self.oph >= self.sh or self.opw >= self.sw:
            raise ValueError(
                f"ConvTranspose2d: output_padding {self.output_padding} "
                f"必须小于 stride {self.stride}"
            )

        fan_in = self.cg * self.kh * self.kw
        std = math.sqrt(2.0 / fan_in)
        self.weights = [
            [[[random.gauss(0, std) for _ in range(self.kw)]
              for _ in range(self.kh)]
             for _ in range(self.og)]
            for _ in range(in_channels)
        ]
        self.biases = [0.0] * out_channels

        self.m_w = [[[[0.0] * self.kw for _ in range(self.kh)]
                     for _ in range(self.og)] for _ in range(in_channels)]
        self.v_w = [[[[0.0] * self.kw for _ in range(self.kh)]
                     for _ in range(self.og)] for _ in range(in_channels)]
        self.m_b = [0.0] * out_channels
        self.v_b = [0.0] * out_channels

        self.x = None
        self.x_shape = None
        self.h_out = 0
        self.w_out = 0

        self.zero_grad()

    def zero_grad(self):
        """清零梯度缓冲区"""
        self.grad_w = [[[[0.0] * self.kw for _ in range(self.kh)]
                        for _ in range(self.og)] for _ in range(self.in_channels)]
        self.grad_b = [0.0] * self.out_channels

    def sgd_step(self, lr):
        """按当前梯度做一次 SGD（权重布局 `[cin][og][kh][kw]`，与 `Conv2d` 不同）"""
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(
                f"ConvTranspose2d.sgd_step: lr 必须是非负数，收到 {lr!r}")
        lr = float(lr)
        for ci in range(self.in_channels):
            w_ci = self.weights[ci]
            g_ci = self.grad_w[ci]
            for og in range(self.og):
                w_og = w_ci[og]
                g_og = g_ci[og]
                for a in range(self.kh):
                    for b in range(self.kw):
                        w_og[a][b] -= lr * g_og[a][b]
        for o in range(self.out_channels):
            self.biases[o] -= lr * self.grad_b[o]

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        """按当前梯度做一次 Adam（矩估计复用 `m_w`/`v_w`/`m_b`/`v_b`）"""
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(
                f"ConvTranspose2d.adam_step: lr 必须是非负数，收到 {lr!r}")
        lr = float(lr)
        self._adam_t = getattr(self, '_adam_t', 0) + 1
        t = self._adam_t
        c1 = 1.0 - beta1 ** t
        c2 = 1.0 - beta2 ** t
        for ci in range(self.in_channels):
            for og in range(self.og):
                for a in range(self.kh):
                    for b in range(self.kw):
                        g = self.grad_w[ci][og][a][b]
                        self.m_w[ci][og][a][b] = beta1 * self.m_w[ci][og][a][b] + (1 - beta1) * g
                        self.v_w[ci][og][a][b] = beta2 * self.v_w[ci][og][a][b] + (1 - beta2) * g * g
                        mh = self.m_w[ci][og][a][b] / c1
                        vh = self.v_w[ci][og][a][b] / c2
                        self.weights[ci][og][a][b] -= lr * mh / (math.sqrt(vh) + eps)
        for o in range(self.out_channels):
            g = self.grad_b[o]
            self.m_b[o] = beta1 * self.m_b[o] + (1 - beta1) * g
            self.v_b[o] = beta2 * self.v_b[o] + (1 - beta2) * g * g
            mh = self.m_b[o] / c1
            vh = self.v_b[o] / c2
            self.biases[o] -= lr * mh / (math.sqrt(vh) + eps)

    def _out_shape(self, H, W):
        ho = (H - 1) * self.sh - 2 * self.ph + self.kh + self.oph
        wo = (W - 1) * self.sw - 2 * self.pw + self.kw + self.opw
        if ho <= 0 or wo <= 0:
            raise ValueError(
                f"ConvTranspose2d: 输入 {H}x{W} 配 kernel {self.kh}x{self.kw}、"
                f"stride {self.sh}/{self.sw}、padding {self.ph}/{self.pw} "
                f"得到输出 {ho}x{wo}，必须都 > 0"
            )
        return ho, wo

    def forward(self, x):
        """x: (Cin, H, W) -> (Cout, Ho, Wo)"""
        if len(x) != self.in_channels:
            raise ValueError(
                f"ConvTranspose2d.forward: 输入通道 {len(x)} != "
                f"in_channels={self.in_channels}"
            )
        H, W = len(x[0]), len(x[0][0])
        for c in range(len(x)):
            if len(x[c]) != H or len(x[c][0]) != W:
                raise ValueError("ConvTranspose2d.forward: 各通道尺寸必须一致")
        ho, wo = self._out_shape(H, W)
        self.x = x
        self.x_shape = (len(x), H, W)
        self.h_out, self.w_out = ho, wo

        out = [[[self.biases[co] for _ in range(wo)] for _ in range(ho)]
               for co in range(self.out_channels)]
        for ci in range(self.in_channels):
            co0 = (ci // self.cg) * self.og
            for co in range(self.og):
                w = self.weights[ci][co]
                out_c = out[co0 + co]
                for oh in range(H):
                    xrow = x[ci][oh]
                    base_h = oh * self.sh - self.ph
                    for ow in range(W):
                        v = xrow[ow]
                        base_w = ow * self.sw - self.pw
                        for kh in range(self.kh):
                            ih = base_h + kh
                            if ih < 0 or ih >= ho:
                                continue
                            wrow = w[kh]
                            dst = out_c[ih]
                            for kw in range(self.kw):
                                iw = base_w + kw
                                if 0 <= iw < wo:
                                    dst[iw] += v * wrow[kw]
        return out

    def backward(self, dout):
        """dout: (Cout, Ho, Wo) -> dx: (Cin, H, W)，内部累积 grad_w / grad_b"""
        if self.x_shape is None:
            raise RuntimeError("ConvTranspose2d.backward: 请先调用 forward")
        C, H, W = self.x_shape
        ho, wo = self.h_out, self.w_out

        dx = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        for ci in range(C):
            co0 = (ci // self.cg) * self.og
            for co in range(self.og):
                out_c = dout[co0 + co]
                w = self.weights[ci][co]
                g_w = self.grad_w[ci][co]
                for oh in range(H):
                    xrow = self.x[ci][oh]
                    dxrow = dx[ci][oh]
                    base_h = oh * self.sh - self.ph
                    for ow in range(W):
                        base_w = ow * self.sw - self.pw
                        xv = xrow[ow]
                        acc = 0.0
                        for kh in range(self.kh):
                            ih = base_h + kh
                            if ih < 0 or ih >= ho:
                                continue
                            drow = out_c[ih]
                            g_row = g_w[kh]
                            for kw in range(self.kw):
                                iw = base_w + kw
                                if iw < 0 or iw >= wo:
                                    continue
                                dv = drow[iw]
                                g_row[kw] += dv * xv
                                acc += dv * w[kh][kw]
                        dxrow[ow] += acc
        # 偏置梯度每次反向只加一遍：同一组的输入通道共享同一张输出图，
        # 原来写在 ci 循环里会按 cin/groups 倍放大（实测 cin=2 时 2 倍、cin=3 时 3 倍）
        for _co0 in range(0, self.out_channels, self.og):
            for _co in range(self.og):
                self.grad_b[_co0 + _co] += sum(sum(row) for row in dout[_co0 + _co])
        return dx


class MaxPool2d:
    """2D 最大池化层"""

    def __init__(self, kernel_size, stride=None):
        self.kernel_size = (kernel_size, kernel_size) if isinstance(kernel_size, int) else kernel_size
        self.stride = self.kernel_size if stride is None else (
            (stride, stride) if isinstance(stride, int) else stride
        )
        self.kh, self.kw = self.kernel_size
        self.sh, self.sw = self.stride
        # Conv2d 有同样的校验，MaxPool2d 原先没有：kernel=0 会返回全 -inf（内层循环不执行），
        # stride=0 会除零
        if self.kh <= 0 or self.kw <= 0:
            raise ValueError(f"MaxPool2d: kernel_size 必须为正，收到 {self.kernel_size}")
        if self.sh <= 0 or self.sw <= 0:
            raise ValueError(f"MaxPool2d: stride 必须为正，收到 {self.stride}")
        self.mask = None
        self.x_shape = None

    def forward(self, x):
        """x: (C, H, W) -> (C, Ho, Wo)"""
        C, H, W = len(x), len(x[0]), len(x[0][0])
        self.x_shape = (C, H, W)
        ho = (H - self.kh) // self.sh + 1
        wo = (W - self.kw) // self.sw + 1
        if ho <= 0 or wo <= 0:
            raise ValueError(
                f"MaxPool2d: 输入 {H}x{W} 配 kernel {self.kh}x{self.kw}、"
                f"stride {self.sh}/{self.sw} 得到输出 {ho}x{wo}，必须都 > 0"
            )
        self.mask = [[[(0, 0)] * wo for _ in range(ho)] for _ in range(C)]

        out = [[[0.0] * wo for _ in range(ho)] for _ in range(C)]
        for c in range(C):
            for oh in range(ho):
                for ow in range(wo):
                    max_val = -float("inf")
                    max_pos = (0, 0)
                    for kh in range(self.kh):
                        for kw in range(self.kw):
                            ih = oh * self.sh + kh
                            iw = ow * self.sw + kw
                            if x[c][ih][iw] > max_val:
                                max_val = x[c][ih][iw]
                                max_pos = (kh, kw)
                    out[c][oh][ow] = max_val
                    self.mask[c][oh][ow] = max_pos
        return out

    def backward(self, dout):
        """dout: (C, Ho, Wo) -> dx: (C, H, W)"""
        C, H, W = self.x_shape
        ho = len(dout[0])
        wo = len(dout[0][0])
        dx = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        for c in range(C):
            for oh in range(ho):
                for ow in range(wo):
                    kh, kw = self.mask[c][oh][ow]
                    ih = oh * self.sh + kh
                    iw = ow * self.sw + kw
                    dx[c][ih][iw] += dout[c][oh][ow]
        return dx


class AvgPool2d:
    """2D 平均池化层（接口与 MaxPool2d 一致：forward 收 (C,H,W)，backward 收 dout）"""

    def __init__(self, kernel_size, stride=None):
        self.kernel_size = (kernel_size, kernel_size) if isinstance(kernel_size, int) else tuple(kernel_size)
        self.stride = self.kernel_size if stride is None else (
            (stride, stride) if isinstance(stride, int) else tuple(stride)
        )
        self.kh, self.kw = self.kernel_size
        self.sh, self.sw = self.stride
        if self.kh <= 0 or self.kw <= 0:
            raise ValueError(f"AvgPool2d: kernel_size 必须为正，收到 {self.kernel_size}")
        if self.sh <= 0 or self.sw <= 0:
            raise ValueError(f"AvgPool2d: stride 必须为正，收到 {self.stride}")
        self.x_shape = None

    def forward(self, x):
        """x: (C, H, W) -> (C, Ho, Wo)，每个窗口取均值"""
        C, H, W = len(x), len(x[0]), len(x[0][0])
        self.x_shape = (C, H, W)
        ho = (H - self.kh) // self.sh + 1
        wo = (W - self.kw) // self.sw + 1
        if ho <= 0 or wo <= 0:
            raise ValueError(
                f"AvgPool2d: 输入 {H}x{W} 配 kernel {self.kh}x{self.kw}、"
                f"stride {self.sh}/{self.sw} 得到输出 {ho}x{wo}，必须都 > 0"
            )
        area = float(self.kh * self.kw)
        out = [[[0.0] * wo for _ in range(ho)] for _ in range(C)]
        for c in range(C):
            for oh in range(ho):
                for ow in range(wo):
                    total = 0.0
                    for kh in range(self.kh):
                        for kw in range(self.kw):
                            total += x[c][oh * self.sh + kh][ow * self.sw + kw]
                    out[c][oh][ow] = total / area
        return out

    def backward(self, dout):
        """dout: (C, Ho, Wo) -> dx: (C, H, W)，每个窗口均分到所有输入位置"""
        C, H, W = self.x_shape
        area = float(self.kh * self.kw)
        dx = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        for c in range(C):
            for oh in range(len(dout[0])):
                for ow in range(len(dout[0][0])):
                    g = dout[c][oh][ow] / area
                    for kh in range(self.kh):
                        for kw in range(self.kw):
                            dx[c][oh * self.sh + kh][ow * self.sw + kw] += g
        return dx


class GlobalAvgPool2d:
    """全局平均池化：(C, H, W) -> (C,)，等价于 kernel 覆盖整张特征图"""

    def __init__(self):
        self.x_shape = None

    def forward(self, x):
        C, H, W = len(x), len(x[0]), len(x[0][0])
        self.x_shape = (C, H, W)
        area = float(H * W)
        return [sum(sum(row) for row in x[c]) / area for c in range(C)]

    def backward(self, dout):
        C, H, W = self.x_shape
        area = float(H * W)
        return [[[dout[c] / area] * W for _ in range(H)] for c in range(C)]


class AdaptiveAvgPool2d:
    """自适应平均池化：(C, H, W) -> (C, out_h, out_w)，输出尺寸由参数指定。

    分箱规则与 PyTorch 一致：第 oh 个输出格子覆盖输入行区间
    [floor(oh*H/out_h), ceil((oh+1)*H/out_h))，列同理。所以当 H 不能被 out_h
    整除时各格大小不同（相邻格会重叠 1 行），每格按自己的实际面积取均值。
    对任意 H、W 都能把输出固定成 out_size，方便接在任意尺寸的卷积后面。

    `out_size=(1, 1)` 与 `GlobalAvgPool2d` 等价（数值逐位相同）。
    """

    def __init__(self, out_size):
        if isinstance(out_size, int):
            out_size = (out_size, out_size)
        out_size = tuple(out_size)
        if len(out_size) != 2:
            raise ValueError(f"AdaptiveAvgPool2d: out_size 必须是 1 个或 2 个整数，收到 {out_size}")
        oh, ow = out_size
        for name, v in (("out_h", oh), ("out_w", ow)):
            if isinstance(v, bool) or not isinstance(v, int):
                raise ValueError(f"AdaptiveAvgPool2d: {name} 必须是整数，收到 {v!r}")
            if v <= 0:
                raise ValueError(f"AdaptiveAvgPool2d: {name} 必须为正，收到 {v}")
        self.out_size = (oh, ow)
        self.x_shape = None
        self._bins = None      # ((rows, cols), ...) 每个输出格子的输入区间

    @staticmethod
    def _bin_range(size, n_out, i):
        start = (i * size) // n_out
        end = -(-((i + 1) * size) // n_out)     # ceil
        return start, end

    def forward(self, x):
        """x: (C, H, W) -> (C, out_h, out_w)"""
        if not x or not x[0] or not x[0][0]:
            raise ValueError("AdaptiveAvgPool2d: 输入不能为空")
        C, H, W = len(x), len(x[0]), len(x[0][0])
        for c in range(C):
            if len(x[c]) != H:
                raise ValueError(f"AdaptiveAvgPool2d: 第 {c} 个通道高度不一致")
            for row in x[c]:
                if len(row) != W:
                    raise ValueError(f"AdaptiveAvgPool2d: 第 {c} 个通道宽度不一致")
        oh, ow = self.out_size
        self.x_shape = (C, H, W)
        row_bins = [self._bin_range(H, oh, i) for i in range(oh)]
        col_bins = [self._bin_range(W, ow, i) for i in range(ow)]
        self._bins = (row_bins, col_bins)
        out = [[[0.0] * ow for _ in range(oh)] for _ in range(C)]
        for c in range(C):
            for i, (h0, h1) in enumerate(row_bins):
                for j, (w0, w1) in enumerate(col_bins):
                    area = float((h1 - h0) * (w1 - w0))
                    # 行内用 sum()（CPython 的补偿求和），再对行求和 —— 与
                    # GlobalAvgPool2d 的 sum(sum(row) for row in x[c]) 完全同序，
                    # 因此 out_size=(1, 1) 时两者逐位相同
                    total = sum(sum(x[c][h][w0:w1]) for h in range(h0, h1))
                    out[c][i][j] = total / area
        return out

    def backward(self, dout):
        """dout: (C, out_h, out_w) -> dx: (C, H, W)，每格把梯度按面积均分回输入位置"""
        if self.x_shape is None or self._bins is None:
            raise RuntimeError("AdaptiveAvgPool2d.backward: 必须先调用 forward")
        C, H, W = self.x_shape
        row_bins, col_bins = self._bins
        dx = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        for c in range(C):
            for i, (h0, h1) in enumerate(row_bins):
                for j, (w0, w1) in enumerate(col_bins):
                    area = float((h1 - h0) * (w1 - w0))
                    g = dout[c][i][j] / area
                    for h in range(h0, h1):
                        row = dx[c][h]
                        for w in range(w0, w1):
                            row[w] += g
        return dx


def _w2_channel_means(x):
    """(C, H, W) -> 每个通道的均值列表"""
    C, H, W = len(x), len(x[0]), len(x[0][0])
    area = float(H * W)
    return [sum(sum(row) for row in x[c]) / area for c in range(C)]


def _w2_count(params):
    """统计 (name, 参数) 序列里的元素个数（支持二维/一维）"""
    total = 0
    for _, v in params:
        if v and isinstance(v[0], list):
            for row in v:
                total += len(row)
        else:
            total += len(v)
    return total


class GlobalMaxPool2d:
    """全局最大池化：(C, H, W) -> (C,)，反向只把梯度给最大值那个位置"""

    def __init__(self):
        self.x_shape = None
        self._arg = None

    def forward(self, x):
        if not x or not x[0] or not x[0][0]:
            raise ValueError("GlobalMaxPool2d: 输入不能为空")
        C, H, W = len(x), len(x[0]), len(x[0][0])
        self.x_shape = (C, H, W)
        out, arg = [], []
        for c in range(C):
            best, where = None, (0, 0)
            for h in range(H):
                row = x[c][h]
                for w in range(W):
                    if best is None or row[w] > best:
                        best, where = row[w], (h, w)
            out.append(best)
            arg.append(where)
        self._arg = arg
        return out

    def backward(self, dout):
        if self.x_shape is None:
            raise RuntimeError("GlobalMaxPool2d.backward: 必须先调用 forward")
        C, H, W = self.x_shape
        dx = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        for c in range(C):
            h, w = self._arg[c]
            dx[c][h][w] = dout[c]
        return dx


class AdaptiveMaxPool2d:
    """自适应最大池化：(C, H, W) -> (C, out_h, out_w)，分箱规则与 AdaptiveAvgPool2d 一致"""

    def __init__(self, out_size):
        if isinstance(out_size, int):
            out_size = (out_size, out_size)
        out_size = tuple(out_size)
        if len(out_size) != 2:
            raise ValueError(f"AdaptiveMaxPool2d: out_size 必须是 1 个或 2 个整数，收到 {out_size}")
        oh, ow = out_size
        for n, v in (("out_h", oh), ("out_w", ow)):
            if isinstance(v, bool) or not isinstance(v, int):
                raise ValueError(f"AdaptiveMaxPool2d: {n} 必须是整数，收到 {v!r}")
            if v <= 0:
                raise ValueError(f"AdaptiveMaxPool2d: {n} 必须为正，收到 {v}")
        self.out_size = (oh, ow)
        self.x_shape = None
        self._arg = None

    _bin_range = staticmethod(AdaptiveAvgPool2d._bin_range)

    def forward(self, x):
        if not x or not x[0] or not x[0][0]:
            raise ValueError("AdaptiveMaxPool2d: 输入不能为空")
        C, H, W = len(x), len(x[0]), len(x[0][0])
        oh, ow = self.out_size
        self.x_shape = (C, H, W)
        row_bins = [self._bin_range(H, oh, i) for i in range(oh)]
        col_bins = [self._bin_range(W, ow, i) for i in range(ow)]
        out = [[[0.0] * ow for _ in range(oh)] for _ in range(C)]
        arg = [[[None] * ow for _ in range(oh)] for _ in range(C)]
        for c in range(C):
            for i, (h0, h1) in enumerate(row_bins):
                for j, (w0, w1) in enumerate(col_bins):
                    best, where = None, None
                    for h in range(h0, h1):
                        row = x[c][h]
                        for w in range(w0, w1):
                            if best is None or row[w] > best:
                                best, where = row[w], (h, w)
                    out[c][i][j] = best
                    arg[c][i][j] = where
        self._arg = arg
        return out

    def backward(self, dout):
        if self.x_shape is None:
            raise RuntimeError("AdaptiveMaxPool2d.backward: 必须先调用 forward")
        C, H, W = self.x_shape
        oh, ow = self.out_size
        dx = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        for c in range(C):
            for i in range(oh):
                for j in range(ow):
                    h, w = self._arg[c][i][j]
                    dx[c][h][w] += dout[c][i][j]
        return dx


class LPPool2d:
    """Lp 池化：(Σ|x|^p / area)^(1/p)；p=1 为「平均绝对值」，p 很大时逼近最大池化"""

    def __init__(self, norm_type, kernel_size, stride=None):
        if isinstance(norm_type, bool) or not isinstance(norm_type, (int, float)):
            raise ValueError(f"LPPool2d: norm_type 必须是正数，收到 {norm_type!r}")
        v = float(norm_type)
        if not (v > 0) or v != v or v == float("inf"):
            raise ValueError(f"LPPool2d: norm_type 必须是有限正数，收到 {norm_type!r}")
        self.norm_type = v
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        for n, k in (("kernel_size", self.kernel_size), ("stride", self.stride)):
            if isinstance(k, bool) or not isinstance(k, int) or k <= 0:
                raise ValueError(f"LPPool2d: {n} 必须是正整数，收到 {k!r}")
        self.x_shape = None
        self._out_shape = None

    def forward(self, x):
        if not x or not x[0] or not x[0][0]:
            raise ValueError("LPPool2d: 输入不能为空")
        C, H, W = len(x), len(x[0]), len(x[0][0])
        k, st, pw = self.kernel_size, self.stride, self.norm_type
        oh = (H - k) // st + 1
        ow = (W - k) // st + 1
        if oh <= 0 or ow <= 0:
            raise ValueError(f"LPPool2d: 输入 {H}x{W} 容不下 kernel {k}")
        self.x_shape = (C, H, W)
        self._out_shape = (oh, ow)
        self._x = [[[x[c][h][w] for w in range(W)] for h in range(H)] for c in range(C)]
        inv_p = 1.0 / pw
        out = [[[0.0] * ow for _ in range(oh)] for _ in range(C)]
        for c in range(C):
            for i in range(oh):
                for j in range(ow):
                    acc = 0.0
                    for h in range(i * st, i * st + k):
                        row = x[c][h]
                        for w in range(j * st, j * st + k):
                            acc += abs(row[w]) ** pw
                    out[c][i][j] = (acc / float(k * k)) ** inv_p
        return out

    def backward(self, dout):
        if self.x_shape is None:
            raise RuntimeError("LPPool2d.backward: 必须先调用 forward")
        C, H, W = self.x_shape
        oh, ow = self._out_shape
        x = self._x
        k, st, pw = self.kernel_size, self.stride, self.norm_type
        area = float(k * k)
        dx = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        for c in range(C):
            for i in range(oh):
                for j in range(ow):
                    acc = 0.0
                    for h in range(i * st, i * st + k):
                        row = x[c][h]
                        for w in range(j * st, j * st + k):
                            acc += abs(row[w]) ** pw
                    y = (acc / area) ** (1.0 / pw)
                    if y == 0.0:
                        continue
                    coef = dout[c][i][j] / (area * (y ** (pw - 1.0)))
                    for h in range(i * st, i * st + k):
                        row = x[c][h]
                        drow = dx[c][h]
                        for w in range(j * st, j * st + k):
                            v = row[w]
                            drow[w] += coef * (abs(v) ** (pw - 1.0)) * (1.0 if v >= 0 else -1.0)
        return dx


class SEBlock:
    """Squeeze-and-Excitation：GAP -> 瓶颈 MLP -> sigmoid 得到通道权重，逐通道乘回输入

    `forward((C,H,W)) -> (C,H,W)`；`backward(dout) -> dx`，四个参数的梯度留在
    `self.grads`（`W1/b1/W2/b2`），`sgd_step`/`adam_step` 只更新这四个。
    """

    def __init__(self, channels, reduction=16):
        for n, v in (("channels", channels), ("reduction", reduction)):
            if isinstance(v, bool) or not isinstance(v, int) or v <= 0:
                raise ValueError(f"SEBlock: {n} 必须是正整数，收到 {v!r}")
        self.channels = channels
        self.reduction = reduction
        self.hidden = max(1, channels // reduction)
        std1 = (2.0 / channels) ** 0.5
        std2 = (2.0 / self.hidden) ** 0.5
        self.W1 = [[random.gauss(0.0, std1) for _ in range(channels)] for _ in range(self.hidden)]
        self.b1 = [0.0] * self.hidden
        self.W2 = [[random.gauss(0.0, std2) for _ in range(self.hidden)] for _ in range(channels)]
        self.b2 = [0.0] * channels
        self.training = True
        self._cache = None
        self._init_adam()
        self.zero_grad()

    def _params(self):
        return (("W1", self.W1), ("b1", self.b1), ("W2", self.W2), ("b2", self.b2))

    def _init_adam(self):
        self._adam_m = {k: _zeros_like(v) for k, v in self._params()}
        self._adam_v = {k: _zeros_like(v) for k, v in self._params()}
        self._adam_t = 0

    def zero_grad(self):
        self.grads = {k: _zeros_like(v) for k, v in self._params()}

    def sgd_step(self, lr):
        """原地 SGD：`param -= lr * grad`（参数在 `_params()` 里）"""
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"SEBlock: lr 必须是非负数字，收到 {lr!r}")
        for key, param in self._params():
            _sgd_apply(param, self.grads[key], float(lr))

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        """原地 Adam；步数记在 `_adam_t`，矩在 `_adam_m` / `_adam_v`"""
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"SEBlock: lr 必须是非负数字，收到 {lr!r}")
        self._adam_t += 1
        for key, param in self._params():
            _adam_apply(param, self.grads[key], self._adam_m[key],
                        self._adam_v[key], self._adam_t, float(lr),
                        beta1, beta2, eps)

    def param_count(self):
        return _w2_count(self._params())

    def train(self):
        self.training = True

    def eval(self):
        self.training = False

    def forward(self, x):
        if not x or not x[0] or not x[0][0]:
            raise ValueError("SEBlock: 输入不能为空")
        C, H, W = len(x), len(x[0]), len(x[0][0])
        if C != self.channels:
            raise ValueError(f"SEBlock: 输入通道数 {C} 与 channels={self.channels} 不符")
        z = _w2_channel_means(x)
        a1 = [sum(map(_mul, self.W1[k], z)) + self.b1[k] for k in range(self.hidden)]
        r1 = [v if v > 0.0 else 0.0 for v in a1]
        a2 = [sum(map(_mul, self.W2[c], r1)) + self.b2[c] for c in range(C)]
        s = [_sigmoid_scalar(v) for v in a2]
        out = [[[x[c][h][w] * s[c] for w in range(W)] for h in range(H)] for c in range(C)]
        self._cache = (x, s, r1, a1)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("SEBlock.backward: 必须先调用 forward")
        x, s, r1, a1 = self._cache
        C, H, W = len(x), len(x[0]), len(x[0][0])
        if (len(dout) != C or len(dout[0]) != H or len(dout[0][0]) != W):
            raise ValueError(
                f"SEBlock.backward: dout 形状 {(len(dout), len(dout[0]), len(dout[0][0]))} "
                f"与输入 {(C, H, W)} 不符")
        area = float(H * W)
        da2 = [0.0] * C
        for c in range(C):
            inner = 0.0
            for h in range(H):
                for w in range(W):
                    inner += dout[c][h][w] * x[c][h][w]
            da2[c] = inner * s[c] * (1.0 - s[c])
            for k in range(self.hidden):
                self.grads["W2"][c][k] += da2[c] * r1[k]
            self.grads["b2"][c] += da2[c]
        dz = [0.0] * C
        for k in range(self.hidden):
            dr1 = sum(da2[c] * self.W2[c][k] for c in range(C))
            da1 = dr1 if a1[k] > 0.0 else 0.0
            for c in range(C):
                self.grads["W1"][k][c] += da1 * _w2_channel_means(x)[c]
            self.grads["b1"][k] += da1
            for c in range(C):
                dz[c] += da1 * self.W1[k][c]
        dx = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        for c in range(C):
            g = dz[c] / area
            for h in range(H):
                for w in range(W):
                    dx[c][h][w] = dout[c][h][w] * s[c] + g
        return dx
class ECABlock:
    """ECA 通道注意力：GAP 后用一条 `kernel_size` 宽的 1D 卷积（零填充）跨通道混权重，

    再 sigmoid 乘回输入。比 SE 省掉降维 MLP，只多 `kernel_size` 个参数。
    """

    def __init__(self, channels, kernel_size=3):
        for n, v in (("channels", channels), ("kernel_size", kernel_size)):
            if isinstance(v, bool) or not isinstance(v, int) or v <= 0:
                raise ValueError(f"ECABlock: {n} 必须是正整数，收到 {v!r}")
        if kernel_size % 2 == 0:
            raise ValueError(f"ECABlock: kernel_size 必须是奇数（保证两侧对称填充），收到 {kernel_size}")
        self.channels = channels
        self.kernel_size = kernel_size
        self.half = kernel_size // 2
        self.w = [0.0] * kernel_size
        for i in range(kernel_size):
            self.w[i] = 1.0 / kernel_size
        self.training = True
        self.grads = {"w": [0.0] * kernel_size}
        self._cache = None
        self._adam_m = {"w": [0.0] * kernel_size}
        self._adam_v = {"w": [0.0] * kernel_size}
        self._adam_t = 0

    def zero_grad(self):
        self.grads = {"w": [0.0] * self.kernel_size}

    def param_count(self):
        return self.kernel_size

    def train(self):
        self.training = True

    def eval(self):
        self.training = False

    def forward(self, x):
        if not x or not x[0] or not x[0][0]:
            raise ValueError("ECABlock: 输入不能为空")
        C, H, W = len(x), len(x[0]), len(x[0][0])
        if C != self.channels:
            raise ValueError(f"ECABlock: 输入通道数 {C} 与 channels={self.channels} 不符")
        z = _w2_channel_means(x)
        e = []
        for c in range(C):
            acc = 0.0
            for k in range(self.kernel_size):
                src = c + k - self.half
                if 0 <= src < C:
                    acc += self.w[k] * z[src]
            e.append(acc)
        s = [_sigmoid_scalar(v) for v in e]
        out = [[[x[c][h][w] * s[c] for w in range(W)] for h in range(H)] for c in range(C)]
        self._cache = (x, z, s)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("ECABlock.backward: 必须先调用 forward")
        x, z, s = self._cache
        C, H, W = len(x), len(x[0]), len(x[0][0])
        if len(dout) != C or len(dout[0]) != H or len(dout[0][0]) != W:
            raise ValueError(
                f"ECABlock.backward: dout 形状 {(len(dout), len(dout[0]), len(dout[0][0]))} "
                f"与输入 {(C, H, W)} 不符")
        area = float(H * W)
        de = [0.0] * C
        for c in range(C):
            inner = 0.0
            for h in range(H):
                for w in range(W):
                    inner += dout[c][h][w] * x[c][h][w]
            de[c] = inner * s[c] * (1.0 - s[c])
        for k in range(self.kernel_size):
            acc = 0.0
            for c in range(C):
                src = c + k - self.half
                if 0 <= src < C:
                    acc += de[c] * z[src]
            self.grads["w"][k] += acc
        dz = [0.0] * C
        for k in range(self.kernel_size):
            for c in range(C):
                src = c + k - self.half
                if 0 <= src < C:
                    dz[src] += de[c] * self.w[k]
        dx = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        for c in range(C):
            g = dz[c] / area
            for h in range(H):
                for w in range(W):
                    dx[c][h][w] = dout[c][h][w] * s[c] + g
        return dx


def _conv_param_count(layer):
    """Conv2d / Conv1d / ConvTranspose2d 的参数量（权重 + 偏置）"""
    w = layer.weights

    def count(node):
        if isinstance(node, list):
            return sum(count(v) for v in node)
        return 1

    return count(w) + len(layer.biases)


def _conv_sgd(layer, lr):
    """原地 SGD 更新一个卷积层的 weights/biases"""
    W, B, gw, gb = layer.weights, layer.biases, layer.grad_w, layer.grad_b
    oc = len(W)
    for o in range(oc):
        B[o] -= lr * gb[o]
        for ic in range(len(W[o])):
            row_w, row_g = W[o][ic], gw[o][ic]
            if isinstance(row_w, list) and row_w and isinstance(row_w[0], list):
                for a in range(len(row_w)):
                    for b in range(len(row_w[a])):
                        row_w[a][b] -= lr * row_g[a][b]
            else:
                for k in range(len(row_w)):
                    row_w[k] -= lr * row_g[k]


def _check_adam_betas(beta1, beta2, who):
    """校验 Adam 的 beta1/beta2 落在 [0,1)，否则偏差修正会除以 0"""
    for name, v in (("beta1", beta1), ("beta2", beta2)):
        if isinstance(v, bool) or not isinstance(v, (int, float)) \
                or not 0.0 <= v < 1.0:
            raise ValueError(
                f"{who}: {name} 必须在 [0,1) 内，收到 {v!r}")


def _conv_adam(layer, lr, beta1=0.9, beta2=0.999, eps=1e-8):
    """原地 Adam 更新一个卷积层；步数记在 layer._conv_adam_t 上"""
    _check_adam_betas(beta1, beta2, "_conv_adam")
    t = getattr(layer, "_conv_adam_t", 0) + 1
    layer._conv_adam_t = t
    c1 = 1.0 - beta1 ** t
    c2 = 1.0 - beta2 ** t
    o1, o2 = 1.0 - beta1, 1.0 - beta2
    W, B, gw, gb = layer.weights, layer.biases, layer.grad_w, layer.grad_b
    mw, vw = layer.m_w, layer.v_w
    mb, vb = layer.m_b, layer.v_b
    for o in range(len(W)):
        g = gb[o]
        m = beta1 * mb[o] + o1 * g
        v = beta2 * vb[o] + o2 * g * g
        mb[o], vb[o] = m, v
        B[o] -= lr * (m / c1) / (math.sqrt(v / c2) + eps)
        for ic in range(len(W[o])):
            row_w, row_g = W[o][ic], gw[o][ic]
            row_m, row_v = mw[o][ic], vw[o][ic]
            if isinstance(row_w, list) and row_w and isinstance(row_w[0], list):
                for a in range(len(row_w)):
                    for b in range(len(row_w[a])):
                        g = row_g[a][b]
                        m = beta1 * row_m[a][b] + o1 * g
                        v = beta2 * row_v[a][b] + o2 * g * g
                        row_m[a][b], row_v[a][b] = m, v
                        row_w[a][b] -= lr * (m / c1) / (math.sqrt(v / c2) + eps)
            else:
                for k in range(len(row_w)):
                    g = row_g[k]
                    m = beta1 * row_m[k] + o1 * g
                    v = beta2 * row_v[k] + o2 * g * g
                    row_m[k], row_v[k] = m, v
                    row_w[k] -= lr * (m / c1) / (math.sqrt(v / c2) + eps)


class DepthwiseSeparableConv2d:
    """深度可分离卷积：`depthwise Conv2d(groups=in_channels)` + `pointwise 1x1 Conv2d`

    参数量约为标准卷积的 `1/out_channels + 1/(k*k)`；两个子卷积各自维护
    `grad_w`/`grad_b`，本层的 `zero_grad`/`sgd_step`/`adam_step` 转发给它们。
    """

    def __init__(self, in_channels, out_channels, kernel_size, stride=1, padding=0):
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.dw = Conv2d(in_channels, in_channels, kernel_size,
                         stride=stride, padding=padding, groups=in_channels)
        self.pw = Conv2d(in_channels, out_channels, 1, stride=1, padding=0)
        self.training = True

    @property
    def grads(self):
        return self.grads_dict()

    def grads_dict(self):
        return {"dw_w": self.dw.grad_w, "dw_b": self.dw.grad_b,
                "pw_w": self.pw.grad_w, "pw_b": self.pw.grad_b}

    def zero_grad(self):
        self.dw.zero_grad()
        self.pw.zero_grad()

    def param_count(self):
        return _conv_param_count(self.dw) + _conv_param_count(self.pw)

    def train(self):
        self.training = True

    def eval(self):
        self.training = False

    def sgd_step(self, lr):
        _conv_sgd(self.dw, lr)
        _conv_sgd(self.pw, lr)

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        _conv_adam(self.dw, lr, beta1, beta2, eps)
        _conv_adam(self.pw, lr, beta1, beta2, eps)

    def forward(self, x):
        return self.pw.forward(self.dw.forward(x))

    def backward(self, dout):
        return self.dw.backward(self.pw.backward(dout))


class BasicBlock2d:
    """ResNet BasicBlock：`conv3x3 -> BN -> ReLU -> conv3x3 -> BN -> (+x) -> ReLU`

    只支持 stride=1 的恒等捷径（通道与尺寸不变）——stride>1 时需要 1x1 投影，
    那个留给 Bottleneck。BN 的 gamma/beta 梯度收在 `self.bn_grads` 里。
    """

    def __init__(self, channels, kernel_size=3, use_bn=True):
        for n, v in (("channels", channels), ("kernel_size", kernel_size)):
            if isinstance(v, bool) or not isinstance(v, int) or v <= 0:
                raise ValueError(f"BasicBlock2d: {n} 必须是正整数，收到 {v!r}")
        self.channels = channels
        self.kernel_size = kernel_size
        self.use_bn = bool(use_bn)
        pad = kernel_size // 2
        self.conv1 = Conv2d(channels, channels, kernel_size, stride=1, padding=pad)
        self.conv2 = Conv2d(channels, channels, kernel_size, stride=1, padding=pad)
        self.bn1 = BatchNorm2d(channels) if self.use_bn else None
        self.bn2 = BatchNorm2d(channels) if self.use_bn else None
        self.training = True
        self.bn_grads = {"bn1_gamma": [0.0] * channels, "bn1_beta": [0.0] * channels,
                         "bn2_gamma": [0.0] * channels, "bn2_beta": [0.0] * channels}
        self._cache = None

    def zero_grad(self):
        self.conv1.zero_grad()
        self.conv2.zero_grad()
        for k in self.bn_grads:
            self.bn_grads[k] = [0.0] * self.channels

    def param_count(self):
        total = _conv_param_count(self.conv1) + _conv_param_count(self.conv2)
        if self.use_bn:
            total += 4 * self.channels
        return total

    def train(self):
        self.training = True
        if self.bn1 is not None:
            self.bn1.train()
            self.bn2.train()

    def eval(self):
        self.training = False
        if self.bn1 is not None:
            self.bn1.eval()
            self.bn2.eval()

    def sgd_step(self, lr):
        _conv_sgd(self.conv1, lr)
        _conv_sgd(self.conv2, lr)

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        _conv_adam(self.conv1, lr, beta1, beta2, eps)
        _conv_adam(self.conv2, lr, beta1, beta2, eps)

    def forward(self, x):
        if not x or not x[0] or not x[0][0]:
            raise ValueError("BasicBlock2d: 输入不能为空")
        C, H, W = len(x), len(x[0]), len(x[0][0])
        if C != self.channels:
            raise ValueError(f"BasicBlock2d: 输入通道数 {C} 与 channels={self.channels} 不符")
        h1 = self.conv1.forward(x)
        a1 = self.bn1.forward(h1) if self.use_bn else h1
        r1 = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in a1]
        h2 = self.conv2.forward(r1)
        a2 = self.bn2.forward(h2) if self.use_bn else h2
        pre = [[[a2[c][h][w] + x[c][h][w] for w in range(W)] for h in range(H)] for c in range(C)]
        out = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in pre]
        self._cache = (x, a1, r1, pre)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("BasicBlock2d.backward: 必须先调用 forward")
        x, a1, r1, pre = self._cache
        C, H, W = len(x), len(x[0]), len(x[0][0])
        if len(dout) != C or len(dout[0]) != H or len(dout[0][0]) != W:
            raise ValueError(
                f"BasicBlock2d.backward: dout 形状 {(len(dout), len(dout[0]), len(dout[0][0]))} "
                f"与输入 {(C, H, W)} 不符")
        dpre = [[[dout[c][h][w] if pre[c][h][w] > 0.0 else 0.0 for w in range(W)]
                 for h in range(H)] for c in range(C)]
        if self.use_bn:
            da2, g2, b2 = self.bn2.backward(dpre)
            for c in range(C):
                self.bn_grads["bn2_gamma"][c] += g2[c]
                self.bn_grads["bn2_beta"][c] += b2[c]
        else:
            da2 = dpre
        dh2 = self.conv2.backward(da2)
        dr1 = [[[dh2[c][h][w] if a1[c][h][w] > 0.0 else 0.0 for w in range(W)]
                for h in range(H)] for c in range(C)]
        if self.use_bn:
            da1, g1, b1 = self.bn1.backward(dr1)
            for c in range(C):
                self.bn_grads["bn1_gamma"][c] += g1[c]
                self.bn_grads["bn1_beta"][c] += b1[c]
        else:
            da1 = dr1
        dh1 = self.conv1.backward(da1)
        return [[[dh1[c][h][w] + dpre[c][h][w] for w in range(W)] for h in range(H)]
                for c in range(C)]
class Bottleneck2d:
    """ResNet Bottleneck：`1x1 降维 -> 3x3 -> 1x1 升维` + 残差

    `mid = max(1, out_channels // 4)`；捷径在 `stride=1 且 in==out` 时是恒等，
    否则用 `1x1 Conv2d + BatchNorm2d` 投影。三个 BN 的 gamma/beta 梯度收在
    `self.bn_grads`（键 `bn1_*`/`bn2_*`/`bn3_*`/`short_*`，没有捷径 BN 时没有 `short_*`）。
    """

    def __init__(self, in_channels, out_channels, stride=1):
        for n, v in (("in_channels", in_channels), ("out_channels", out_channels),
                     ("stride", stride)):
            if isinstance(v, bool) or not isinstance(v, int) or v <= 0:
                raise ValueError(f"Bottleneck2d: {n} 必须是正整数，收到 {v!r}")
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.stride = stride
        self.mid = max(1, out_channels // 4)
        self.conv1 = Conv2d(in_channels, self.mid, 1, stride=1, padding=0)
        self.bn1 = BatchNorm2d(self.mid)
        self.conv2 = Conv2d(self.mid, self.mid, 3, stride=stride, padding=1)
        self.bn2 = BatchNorm2d(self.mid)
        self.conv3 = Conv2d(self.mid, out_channels, 1, stride=1, padding=0)
        self.bn3 = BatchNorm2d(out_channels)
        self.proj = None
        self.short_bn = None
        if not (stride == 1 and in_channels == out_channels):
            self.proj = Conv2d(in_channels, out_channels, 1, stride=stride, padding=0)
            self.short_bn = BatchNorm2d(out_channels)
        self.training = True
        keys = ["bn1_gamma", "bn1_beta", "bn2_gamma", "bn2_beta", "bn3_gamma", "bn3_beta"]
        if self.short_bn is not None:
            keys += ["short_gamma", "short_beta"]
        self.bn_grads = {k: [0.0] * (self.mid if "bn1" in k or "bn2" in k else out_channels)
                         for k in keys}
        self._cache = None

    def zero_grad(self):
        self.conv1.zero_grad()
        self.conv2.zero_grad()
        self.conv3.zero_grad()
        if self.proj is not None:
            self.proj.zero_grad()
        for k in self.bn_grads:
            self.bn_grads[k] = [0.0] * len(self.bn_grads[k])

    def param_count(self):
        total = (_conv_param_count(self.conv1) + _conv_param_count(self.conv2)
                 + _conv_param_count(self.conv3))
        total += 4 * self.mid + 2 * self.out_channels
        if self.proj is not None:
            total += _conv_param_count(self.proj) + 2 * self.out_channels
        return total

    def train(self):
        self.training = True
        for bn in (self.bn1, self.bn2, self.bn3, self.short_bn):
            if bn is not None:
                bn.train()

    def eval(self):
        self.training = False
        for bn in (self.bn1, self.bn2, self.bn3, self.short_bn):
            if bn is not None:
                bn.eval()

    def sgd_step(self, lr):
        for c in (self.conv1, self.conv2, self.conv3, self.proj):
            if c is not None:
                _conv_sgd(c, lr)

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        for c in (self.conv1, self.conv2, self.conv3, self.proj):
            if c is not None:
                _conv_adam(c, lr, beta1, beta2, eps)

    @staticmethod
    def _relu(x):
        return [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in x]

    def forward(self, x):
        if not x or not x[0] or not x[0][0]:
            raise ValueError("Bottleneck2d: 输入不能为空")
        C = len(x)
        if C != self.in_channels:
            raise ValueError(
                f"Bottleneck2d: 输入通道数 {C} 与 in_channels={self.in_channels} 不符")
        h1 = self.bn1.forward(self.conv1.forward(x))
        r1 = self._relu(h1)
        h2 = self.bn2.forward(self.conv2.forward(r1))
        r2 = self._relu(h2)
        h3 = self.bn3.forward(self.conv3.forward(r2))
        if self.proj is None:
            short = x
        else:
            short = self.short_bn.forward(self.proj.forward(x))
        H, W = len(h3[0]), len(h3[0][0])
        SH, SW = len(short[0]), len(short[0][0])
        if (SH, SW) != (H, W):
            raise ValueError(
                f"Bottleneck2d: 捷径空间尺寸 {(SH, SW)} 与主干 {(H, W)} 不符")
        pre = [[[h3[c][h][w] + short[c][h][w] for w in range(W)] for h in range(H)]
               for c in range(self.out_channels)]
        out = self._relu(pre)
        self._cache = (x, h1, r1, h2, r2, h3, short, pre)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("Bottleneck2d.backward: 必须先调用 forward")
        x, h1, r1, h2, r2, h3, short, pre = self._cache
        C_out, H, W = len(pre), len(pre[0]), len(pre[0][0])
        if len(dout) != C_out or len(dout[0]) != H or len(dout[0][0]) != W:
            raise ValueError(
                f"Bottleneck2d.backward: dout 形状 {(len(dout), len(dout[0]), len(dout[0][0]))} "
                f"与输出 {(C_out, H, W)} 不符")
        dpre = [[[dout[c][h][w] if pre[c][h][w] > 0.0 else 0.0 for w in range(W)]
                 for h in range(H)] for c in range(C_out)]
        dh3, g3, b3 = self.bn3.backward(dpre)
        for c in range(C_out):
            self.bn_grads["bn3_gamma"][c] += g3[c]
            self.bn_grads["bn3_beta"][c] += b3[c]
        dr2 = self.conv3.backward(dh3)
        dh2 = [[[dr2[c][h][w] if r2[c][h][w] > 0.0 else 0.0 for w in range(len(r2[0][0]))]
                for h in range(len(r2[0]))] for c in range(self.mid)]
        dr2b, g2, b2 = self.bn2.backward(dh2)
        for c in range(self.mid):
            self.bn_grads["bn2_gamma"][c] += g2[c]
            self.bn_grads["bn2_beta"][c] += b2[c]
        dr1 = self.conv2.backward(dr2b)
        # conv1 的输出空间 = 本 block 的输入空间；stride>1 时它与输出空间 (H, W) 不同，
        # 必须用 r1 自己的尺寸裁剪梯度（否则 stride=2 的 block 会越界）
        H1, W1 = len(r1[0]), len(r1[0][0])
        dh1 = [[[dr1[c][h][w] if r1[c][h][w] > 0.0 else 0.0 for w in range(W1)]
                for h in range(H1)] for c in range(self.mid)]
        dxc, g1, b1 = self.bn1.backward(dh1)
        for c in range(self.mid):
            self.bn_grads["bn1_gamma"][c] += g1[c]
            self.bn_grads["bn1_beta"][c] += b1[c]
        dx_main = self.conv1.backward(dxc)
        if self.proj is None:
            d_short = dpre
        else:
            dshort_bn, gs, bs = self.short_bn.backward(dpre)
            for c in range(C_out):
                self.bn_grads["short_gamma"][c] += gs[c]
                self.bn_grads["short_beta"][c] += bs[c]
            d_short = self.proj.backward(dshort_bn)
        return [[[dx_main[c][h][w] + d_short[c][h][w] for w in range(len(dx_main[0][0]))]
                 for h in range(len(dx_main[0]))] for c in range(self.in_channels)]


class AdaIN:
    """Adaptive Instance Normalization：按通道做实例归一化，再用外部给的
    `gamma`/`beta`（风格向量）缩放平移：`y = gamma_c * (x-mean_c)/sqrt(var_c+eps) + beta_c`

    `x` 可以是 `(C,H,W)` 或长度为 `C` 的特征向量；`set_style(gamma, beta)` 换风格。
    `backward` 返回 `(dx, d_gamma, d_beta)` —— 梯度按「外部参数」返回，不内部累积。
    """

    def __init__(self, channels, eps=1e-5):
        if isinstance(channels, bool) or not isinstance(channels, int) or channels < 1:
            raise ValueError(f"AdaIN: channels 必须是正整数，收到 {channels!r}")
        if not (eps > 0):
            raise ValueError(f"AdaIN: eps 必须 > 0，收到 {eps!r}")
        self.channels = channels
        self.eps = eps
        self.gamma = [1.0] * channels
        self.beta = [0.0] * channels
        self._cache = None

    def set_style(self, gamma, beta):
        if len(gamma) != self.channels or len(beta) != self.channels:
            raise ValueError(
                f"AdaIN.set_style: gamma/beta 长度必须都是 {self.channels}，"
                f"收到 {len(gamma)}/{len(beta)}")
        self.gamma = [float(g) for g in gamma]
        self.beta = [float(b) for b in beta]

    def forward(self, x):
        if not x:
            raise ValueError("AdaIN.forward: 输入不能为空")
        if len(x) != self.channels:
            raise ValueError(f"AdaIN: 通道数 {len(x)} 与 channels={self.channels} 不符")
        out = []
        stats = []
        if isinstance(x[0], list):
            H, W = len(x[0]), len(x[0][0])
            n = H * W
            for c in range(self.channels):
                flat = [x[c][h][w] for h in range(H) for w in range(W)]
                mean = sum(flat) / n
                var = sum((v - mean) ** 2 for v in flat) / n
                inv = 1.0 / math.sqrt(var + self.eps)
                stats.append((mean, inv, flat))
                out.append([[self.gamma[c] * (x[c][h][w] - mean) * inv + self.beta[c]
                             for w in range(W)] for h in range(H)])
        else:
            n = 1
            for c in range(self.channels):
                flat = [x[c]]
                mean = x[c]
                var = 0.0
                inv = 1.0 / math.sqrt(var + self.eps)
                stats.append((mean, inv, flat))
                out.append(self.gamma[c] * (x[c] - mean) * inv + self.beta[c])
        self._cache = (x, stats)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("AdaIN.backward: 必须先调用 forward")
        x, stats = self._cache
        d_gamma = [0.0] * self.channels
        d_beta = [0.0] * self.channels
        nested = isinstance(x[0], list)
        if not nested:
            # 单向量时 mean=x、var=0 ⇒ x_hat ≡ 0，输出恒为 beta[c]：
            # dx 与 d_gamma 都是 0，只有 d_beta 有梯度
            return [0.0] * self.channels, [0.0] * self.channels, [dout[c] for c in range(self.channels)]
        H, W = len(x[0]), len(x[0][0])
        n = H * W
        dx = [[[0.0] * W for _ in range(H)] for _ in range(self.channels)]
        for c in range(self.channels):
            mean, inv, flat = stats[c]
            dh = [[dout[c][h][w] * self.gamma[c] for w in range(W)] for h in range(H)]
            d_gamma[c] = sum(dout[c][h][w] * (x[c][h][w] - mean) * inv
                             for h in range(H) for w in range(W))
            d_beta[c] = sum(dout[c][h][w] for h in range(H) for w in range(W))
            dflat = [dh[h][w] for h in range(H) for w in range(W)]
            s1 = sum(dflat)
            s2 = sum(d * (x[c][h][w] - mean) for d, h, w in
                     ((dflat[h * W + w], h, w) for h in range(H) for w in range(W)))
            for h in range(H):
                for w in range(W):
                    dx[c][h][w] = inv * (dflat[h * W + w]
                                         - s1 / n
                                         - (x[c][h][w] - mean) * inv * inv * s2 / n)
        return dx, d_gamma, d_beta


class FiLM:
    """Feature-wise Linear Modulation：`y = gamma * x + beta`（逐特征，可选分组）

    `groups=1` 时 gamma/beta 是整向量；`groups>1` 时把特征切成若干段、各段共享
    一组 gamma/beta（条件向量比特征维度短时用）。
    """

    def __init__(self, features, groups=1):
        for n, v in (("features", features), ("groups", groups)):
            if isinstance(v, bool) or not isinstance(v, int) or v < 1:
                raise ValueError(f"FiLM: {n} 必须是正整数，收到 {v!r}")
        if features % groups != 0:
            raise ValueError(f"FiLM: features={features} 必须能被 groups={groups} 整除")
        self.features = features
        self.groups = groups
        self.group_size = features // groups
        self.gamma = [1.0] * groups
        self.beta = [0.0] * groups
        self._x = None

    def set_params(self, gamma, beta):
        if len(gamma) != self.groups or len(beta) != self.groups:
            raise ValueError(
                f"FiLM.set_params: gamma/beta 长度必须都是 {self.groups}，"
                f"收到 {len(gamma)}/{len(beta)}")
        self.gamma = [float(g) for g in gamma]
        self.beta = [float(b) for b in beta]

    def forward(self, x):
        if len(x) != self.features:
            raise ValueError(f"FiLM: 输入长度 {len(x)} 与 features={self.features} 不符")
        self._x = list(x)
        out = [0.0] * self.features
        for i in range(self.features):
            g = self.gamma[i // self.group_size]
            b = self.beta[i // self.group_size]
            out[i] = g * x[i] + b
        return out

    def backward(self, dout):
        if self._x is None:
            raise RuntimeError("FiLM.backward: 必须先调用 forward")
        if len(dout) != self.features:
            raise ValueError(f"FiLM.backward: dout 长度 {len(dout)} != {self.features}")
        dx = [0.0] * self.features
        d_gamma = [0.0] * self.groups
        d_beta = [0.0] * self.groups
        for i in range(self.features):
            g_i = i // self.group_size
            dx[i] = dout[i] * self.gamma[g_i]
            d_gamma[g_i] += dout[i] * self._x[i]
            d_beta[g_i] += dout[i]
        return dx, d_gamma, d_beta
class ConvTranspose1d:
    """1D 转置卷积：输入 (Cin, L) -> (Cout, Lo)，`Lo = (L-1)*s - 2p + k + output_padding`

    前向就是「把每个输入点乘上整条核、按 stride 摆到输出网格上累加」；反向对应
    `dx` 与 `grad_w` 两次同样的累加。权重 `[out][in][k]`（转置卷积不做 groups）。
    """

    def __init__(self, in_channels, out_channels, kernel_size, stride=1,
                 padding=0, output_padding=0):
        for n, v, lo in (("in_channels", in_channels, 1), ("out_channels", out_channels, 1),
                         ("kernel_size", kernel_size, 1), ("stride", stride, 1),
                         ("padding", padding, 0), ("output_padding", output_padding, 0)):
            if isinstance(v, bool) or not isinstance(v, int) or v < lo:
                raise ValueError(f"ConvTranspose1d: {n} 必须是 >= {lo} 的整数，收到 {v!r}")
        if output_padding >= stride:
            raise ValueError(
                f"ConvTranspose1d: output_padding={output_padding} 必须 < stride={stride}")
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.k = kernel_size
        self.s = stride
        self.p = padding
        self.op = output_padding
        fan_in = in_channels * self.k
        std = math.sqrt(2.0 / fan_in)
        self.weights = [[[random.gauss(0, std) for _ in range(self.k)]
                         for _ in range(in_channels)] for _ in range(out_channels)]
        self.biases = [0.0] * out_channels
        self.m_w = [[[0.0] * self.k for _ in range(in_channels)] for _ in range(out_channels)]
        self.v_w = [[[0.0] * self.k for _ in range(in_channels)] for _ in range(out_channels)]
        self.m_b = [0.0] * out_channels
        self.v_b = [0.0] * out_channels
        self.x = None
        self.lo = 0
        self.zero_grad()

    def zero_grad(self):
        self.grad_w = [[[0.0] * self.k for _ in range(self.in_channels)]
                       for _ in range(self.out_channels)]
        self.grad_b = [0.0] * self.out_channels

    def _out_len(self, L):
        lo = (L - 1) * self.s - 2 * self.p + self.k + self.op
        if lo <= 0:
            raise ValueError(
                f"ConvTranspose1d: 输入长度 {L} 配 kernel {self.k}、stride {self.s}、"
                f"padding {self.p}、output_padding {self.op} 得到输出长度 {lo}，必须 > 0")
        return lo

    def forward(self, x):
        if not x or len(x) != self.in_channels:
            raise ValueError(
                f"ConvTranspose1d.forward: 输入通道 {len(x) if x else 0} "
                f"!= in_channels={self.in_channels}")
        L = len(x[0])
        for c in range(len(x)):
            if len(x[c]) != L:
                raise ValueError("ConvTranspose1d.forward: 各通道长度必须一致")
        lo = self._out_len(L)
        self.x = x
        self.lo = lo
        out = [[self.biases[oc]] * lo for oc in range(self.out_channels)]
        out = [list(row) for row in out]
        for oc in range(self.out_channels):
            w_oc = self.weights[oc]
            for ic in range(self.in_channels):
                w = w_oc[ic]
                xc = x[ic]
                for o in range(L):
                    v = xc[o]
                    if v == 0.0:
                        continue
                    base = o * self.s - self.p
                    for k in range(self.k):
                        idx = base + k
                        if 0 <= idx < lo:
                            out[oc][idx] += v * w[k]
        return out

    def backward(self, dout):
        if self.x is None:
            raise RuntimeError("ConvTranspose1d.backward: 请先调用 forward")
        L = len(self.x[0])
        lo = self.lo
        dx = [[0.0] * L for _ in range(self.in_channels)]
        for oc in range(self.out_channels):
            d = dout[oc]
            self.grad_b[oc] += sum(d)
            w_oc = self.weights[oc]
            gw_oc = self.grad_w[oc]
            for ic in range(self.in_channels):
                w = w_oc[ic]
                gw = gw_oc[ic]
                xc = self.x[ic]
                dxi = dx[ic]
                for o in range(L):
                    base = o * self.s - self.p
                    acc = 0.0
                    for k in range(self.k):
                        idx = base + k
                        if 0 <= idx < lo:
                            dv = d[idx]
                            acc += dv * w[k]
                            gw[k] += xc[o] * dv
                    dxi[o] += acc
        return dx


class MaxPool1d:
    """一维最大池化：`(C, L) -> (C, Lo)`，反向只回传每个窗口的最大值位置"""

    def __init__(self, kernel_size, stride=None, padding=0):
        for n, v, lo in (("kernel_size", kernel_size, 1), ("padding", padding, 0)):
            if isinstance(v, bool) or not isinstance(v, int) or v < lo:
                raise ValueError(f"MaxPool1d: {n} 必须是 >= {lo} 的整数，收到 {v!r}")
        if stride is None:
            stride = kernel_size
        if isinstance(stride, bool) or not isinstance(stride, int) or stride < 1:
            raise ValueError(f"MaxPool1d: stride 必须是正整数，收到 {stride!r}")
        if padding >= kernel_size:
            raise ValueError(
                f"MaxPool1d: padding={padding} 必须 < kernel_size={kernel_size}")
        self.k = kernel_size
        self.s = stride
        self.p = padding
        self._cache = None

    def _out_len(self, L):
        lo = (L + 2 * self.p - self.k) // self.s + 1
        if lo <= 0:
            raise ValueError(f"MaxPool1d: 输入长度 {L} 太小，输出长度 {lo}")
        return lo

    def forward(self, x):
        if not x:
            raise ValueError("MaxPool1d.forward: 输入不能为空")
        L = len(x[0])
        for c in range(len(x)):
            if len(x[c]) != L:
                raise ValueError("MaxPool1d.forward: 各通道长度必须一致")
        lo = self._out_len(L)
        out = []
        idxs = []
        for c in range(len(x)):
            row = []
            ridx = []
            for o in range(lo):
                base = o * self.s - self.p
                best = None
                best_i = -1
                for k in range(self.k):
                    i = base + k
                    if 0 <= i < L:
                        v = x[c][i]
                        if best is None or v > best:
                            best, best_i = v, i
                row.append(best if best is not None else 0.0)
                ridx.append(best_i)
            out.append(row)
            idxs.append(ridx)
        self._cache = (len(x), L, idxs)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("MaxPool1d.backward: 必须先调用 forward")
        C, L, idxs = self._cache
        lo = len(dout[0])
        dx = [[0.0] * L for _ in range(C)]
        for c in range(C):
            for o in range(lo):
                i = idxs[c][o]
                if 0 <= i < L:
                    dx[c][i] += dout[c][o]
        return dx


class AvgPool1d:
    """一维平均池化：`(C, L) -> (C, Lo)`，反向把梯度均分回窗口（含 padding 的零位不接收梯度）"""

    def __init__(self, kernel_size, stride=None, padding=0):
        for n, v, lo in (("kernel_size", kernel_size, 1), ("padding", padding, 0)):
            if isinstance(v, bool) or not isinstance(v, int) or v < lo:
                raise ValueError(f"AvgPool1d: {n} 必须是 >= {lo} 的整数，收到 {v!r}")
        if stride is None:
            stride = kernel_size
        if isinstance(stride, bool) or not isinstance(stride, int) or stride < 1:
            raise ValueError(f"AvgPool1d: stride 必须是正整数，收到 {stride!r}")
        if padding >= kernel_size:
            raise ValueError(
                f"AvgPool1d: padding={padding} 必须 < kernel_size={kernel_size}")
        self.k = kernel_size
        self.s = stride
        self.p = padding
        self._cache = None

    def _out_len(self, L):
        lo = (L + 2 * self.p - self.k) // self.s + 1
        if lo <= 0:
            raise ValueError(f"AvgPool1d: 输入长度 {L} 太小，输出长度 {lo}")
        return lo

    def forward(self, x):
        if not x:
            raise ValueError("AvgPool1d.forward: 输入不能为空")
        L = len(x[0])
        lo = self._out_len(L)
        out = []
        for c in range(len(x)):
            row = []
            for o in range(lo):
                base = o * self.s - self.p
                acc = 0.0
                for k in range(self.k):
                    i = base + k
                    if 0 <= i < L:
                        acc += x[c][i]
                row.append(acc / self.k)
            out.append(row)
        self._cache = (len(x), L, lo)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("AvgPool1d.backward: 必须先调用 forward")
        C, L, lo = self._cache
        dx = [[0.0] * L for _ in range(C)]
        inv = 1.0 / self.k
        for c in range(C):
            for o in range(lo):
                base = o * self.s - self.p
                for k in range(self.k):
                    i = base + k
                    if 0 <= i < L:
                        dx[c][i] += dout[c][o] * inv
        return dx


class MaxPool3d:
    """三维最大池化：`(C, D, H, W) -> (C, Do, Ho, Wo)`，反向只回传最大值位置"""

    def __init__(self, kernel_size, stride=None, padding=0):
        for n, v, lo in (("kernel_size", kernel_size, 1), ("padding", padding, 0)):
            if isinstance(v, bool) or not isinstance(v, int) or v < lo:
                raise ValueError(f"MaxPool3d: {n} 必须是 >= {lo} 的整数，收到 {v!r}")
        if stride is None:
            stride = kernel_size
        if isinstance(stride, bool) or not isinstance(stride, int) or stride < 1:
            raise ValueError(f"MaxPool3d: stride 必须是正整数，收到 {stride!r}")
        self.k = kernel_size
        self.s = stride
        self.p = padding
        self._cache = None

    def _out_len(self, n):
        o = (n + 2 * self.p - self.k) // self.s + 1
        if o <= 0:
            raise ValueError(f"MaxPool3d: 输入尺寸 {n} 太小，输出 {o}")
        return o

    def forward(self, x):
        if not x or not x[0] or not x[0][0]:
            raise ValueError("MaxPool3d.forward: 输入必须是 (C, D, H, W)")
        C, D, H, W = len(x), len(x[0]), len(x[0][0]), len(x[0][0][0])
        Do, Ho, Wo = self._out_len(D), self._out_len(H), self._out_len(W)
        out = [[[[0.0] * Wo for _ in range(Ho)] for _ in range(Do)] for _ in range(C)]
        idxs = [[[[(-1, -1, -1)] * Wo for _ in range(Ho)] for _ in range(Do)] for _ in range(C)]
        for c in range(C):
            for od in range(Do):
                for oh in range(Ho):
                    for ow in range(Wo):
                        best = None
                        pos = (-1, -1, -1)
                        for kd in range(self.k):
                            d = od * self.s - self.p + kd
                            if not (0 <= d < D):
                                continue
                            for kh in range(self.k):
                                h = oh * self.s - self.p + kh
                                if not (0 <= h < H):
                                    continue
                                for kw in range(self.k):
                                    w = ow * self.s - self.p + kw
                                    if not (0 <= w < W):
                                        continue
                                    v = x[c][d][h][w]
                                    if best is None or v > best:
                                        best, pos = v, (d, h, w)
                        out[c][od][oh][ow] = best if best is not None else 0.0
                        idxs[c][od][oh][ow] = pos
        self._cache = (C, D, H, W, idxs)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("MaxPool3d.backward: 必须先调用 forward")
        C, D, H, W, idxs = self._cache
        dx = [[[[0.0] * W for _ in range(H)] for _ in range(D)] for _ in range(C)]
        Do, Ho, Wo = len(dout[0]), len(dout[0][0]), len(dout[0][0][0])
        for c in range(C):
            for od in range(Do):
                for oh in range(Ho):
                    for ow in range(Wo):
                        d, h, w = idxs[c][od][oh][ow]
                        if d >= 0:
                            dx[c][d][h][w] += dout[c][od][oh][ow]
        return dx


class AvgPool3d:
    """三维平均池化：`(C, D, H, W) -> (C, Do, Ho, Wo)`，反向把梯度均分回窗口"""

    def __init__(self, kernel_size, stride=None, padding=0):
        for n, v, lo in (("kernel_size", kernel_size, 1), ("padding", padding, 0)):
            if isinstance(v, bool) or not isinstance(v, int) or v < lo:
                raise ValueError(f"AvgPool3d: {n} 必须是 >= {lo} 的整数，收到 {v!r}")
        if stride is None:
            stride = kernel_size
        if isinstance(stride, bool) or not isinstance(stride, int) or stride < 1:
            raise ValueError(f"AvgPool3d: stride 必须是正整数，收到 {stride!r}")
        self.k = kernel_size
        self.s = stride
        self.p = padding
        self._cache = None

    def _out_len(self, n):
        o = (n + 2 * self.p - self.k) // self.s + 1
        if o <= 0:
            raise ValueError(f"AvgPool3d: 输入尺寸 {n} 太小，输出 {o}")
        return o

    def forward(self, x):
        if not x or not x[0] or not x[0][0]:
            raise ValueError("AvgPool3d.forward: 输入必须是 (C, D, H, W)")
        C, D, H, W = len(x), len(x[0]), len(x[0][0]), len(x[0][0][0])
        Do, Ho, Wo = self._out_len(D), self._out_len(H), self._out_len(W)
        out = [[[[0.0] * Wo for _ in range(Ho)] for _ in range(Do)] for _ in range(C)]
        for c in range(C):
            for od in range(Do):
                for oh in range(Ho):
                    for ow in range(Wo):
                        acc = 0.0
                        for kd in range(self.k):
                            d = od * self.s - self.p + kd
                            if not (0 <= d < D):
                                continue
                            for kh in range(self.k):
                                h = oh * self.s - self.p + kh
                                if not (0 <= h < H):
                                    continue
                                for kw in range(self.k):
                                    w = ow * self.s - self.p + kw
                                    if 0 <= w < W:
                                        acc += x[c][d][h][w]
                        out[c][od][oh][ow] = acc / (self.k ** 3)
        self._cache = (C, D, H, W, Do, Ho, Wo)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("AvgPool3d.backward: 必须先调用 forward")
        C, D, H, W, Do, Ho, Wo = self._cache
        dx = [[[[0.0] * W for _ in range(H)] for _ in range(D)] for _ in range(C)]
        inv = 1.0 / (self.k ** 3)
        for c in range(C):
            for od in range(Do):
                for oh in range(Ho):
                    for ow in range(Wo):
                        g = dout[c][od][oh][ow] * inv
                        for kd in range(self.k):
                            d = od * self.s - self.p + kd
                            if not (0 <= d < D):
                                continue
                            for kh in range(self.k):
                                h = oh * self.s - self.p + kh
                                if not (0 <= h < H):
                                    continue
                                for kw in range(self.k):
                                    w = ow * self.s - self.p + kw
                                    if 0 <= w < W:
                                        dx[c][d][h][w] += g
        return dx
def _conv3d_zeros(out_channels, in_channels, kd, kh, kw):
    """构造 [oc][ic][kd][kh][kw] 的全零嵌套列表（用循环，避免推导式括号层数出错）"""
    out = []
    for _ in range(out_channels):
        per_oc = []
        for _ in range(in_channels):
            per_ic = []
            for _ in range(kd):
                per_kd = []
                for _ in range(kh):
                    per_kd.append([0.0] * kw)
                per_ic.append(per_kd)
            per_oc.append(per_ic)
        out.append(per_oc)
    return out


def _conv3d_random(out_channels, in_channels, kd, kh, kw, std):
    """He 初始化用的随机核，结构与 _conv3d_zeros 相同"""
    out = _conv3d_zeros(out_channels, in_channels, kd, kh, kw)
    for oc in range(out_channels):
        for ic in range(in_channels):
            for a in range(kd):
                for b in range(kh):
                    for c in range(kw):
                        out[oc][ic][a][b][c] = random.gauss(0, std)
    return out


class Conv3d:
    """3D 卷积层（输入 (C, D, H, W)，权重 [oc][ic][kd][kh][kw]，He 初始化）

    直接滑动窗口累加，不走 im2col：三维展开的矩阵通常是 im2col 的几十倍，
    而这层主要处理小体数据（医学影像 patch、视频片段），直接循环更省内存。
    不做 groups —— 分组三维卷积用不到，先不引入这层复杂度。
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size,
                 stride=1, padding=0):
        for name, v in (("in_channels", in_channels),
                        ("out_channels", out_channels)):
            if not isinstance(v, int) or isinstance(v, bool) or v <= 0:
                raise ValueError(f"Conv3d: {name} 必须是正整数，收到 {v!r}")
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = ((kernel_size, ) * 3 if isinstance(kernel_size, int)
                            else tuple(kernel_size))
        self.stride = ((stride, ) * 3 if isinstance(stride, int) else tuple(stride))
        self.padding = ((padding, ) * 3 if isinstance(padding, int)
                        else tuple(padding))
        if len(self.kernel_size) != 3 or min(self.kernel_size) <= 0:
            raise ValueError(
                f"Conv3d: kernel_size 必须是三个正数，收到 {kernel_size!r}")
        if len(self.stride) != 3 or min(self.stride) <= 0:
            raise ValueError(f"Conv3d: stride 必须是三个正数，收到 {stride!r}")
        if len(self.padding) != 3 or min(self.padding) < 0:
            raise ValueError(f"Conv3d: padding 必须是三个非负数，收到 {padding!r}")
        self.kd, self.kh, self.kw = self.kernel_size
        self.sd, self.sh, self.sw = self.stride
        self.pd, self.ph, self.pw = self.padding

        fan_in = in_channels * self.kd * self.kh * self.kw
        std = math.sqrt(2.0 / fan_in)
        self.weights = _conv3d_random(out_channels, in_channels,
                                      self.kd, self.kh, self.kw, std)
        self.biases = [0.0] * out_channels
        self.m_w = _conv3d_zeros(out_channels, in_channels,
                                 self.kd, self.kh, self.kw)
        self.v_w = _conv3d_zeros(out_channels, in_channels,
                                 self.kd, self.kh, self.kw)
        self.m_b = [0.0] * out_channels
        self.v_b = [0.0] * out_channels
        self.x_shape = None
        self.out_shape = None
        self.zero_grad()

    def zero_grad(self):
        """清零梯度缓冲区（保留 x_shape/out_shape 供 backward 使用）"""
        self.grad_w = _conv3d_zeros(self.out_channels, self.in_channels,
                                    self.kd, self.kh, self.kw)
        self.grad_b = [0.0] * self.out_channels

    def param_count(self):
        """可训练参数个数（权重 + 偏置）"""
        return (self.out_channels * self.in_channels * self.kd * self.kh * self.kw
                + self.out_channels)

    def _out_shape(self, D, H, W):
        od = (D + 2 * self.pd - self.kd) // self.sd + 1
        oh = (H + 2 * self.ph - self.kh) // self.sh + 1
        ow = (W + 2 * self.pw - self.kw) // self.sw + 1
        if od <= 0 or oh <= 0 or ow <= 0:
            raise ValueError(
                f"Conv3d: 输入 {D}x{H}x{W} 配 kernel {self.kernel_size}、"
                f"padding {self.padding}、stride {self.stride} 得到输出 "
                f"{od}x{oh}x{ow}，必须都 > 0"
            )
        return od, oh, ow

    def _pad(self, x):
        """对 (C, D, H, W) 做 zero-padding"""
        C, D, H, W = len(x), len(x[0]), len(x[0][0]), len(x[0][0][0])
        Dp, Hp, Wp = D + 2 * self.pd, H + 2 * self.ph, W + 2 * self.pw
        padded = []
        for _ in range(C):
            per_c = []
            for _ in range(Dp):
                per_d = []
                for _ in range(Hp):
                    per_d.append([0.0] * Wp)
                per_c.append(per_d)
            padded.append(per_c)
        for c in range(C):
            for d in range(D):
                for h in range(H):
                    for w in range(W):
                        padded[c][d + self.pd][h + self.ph][w + self.pw] = x[c][d][h][w]
        return padded

    def forward(self, x):
        """x: (C, D, H, W) -> (out_channels, Od, Oh, Ow)"""
        if not x or not isinstance(x[0], list) or not isinstance(x[0][0], list):
            raise ValueError("Conv3d.forward: 输入必须是 (C, D, H, W) 嵌套列表")
        if len(x) != self.in_channels:
            raise ValueError(
                f"Conv3d.forward: 输入通道 {len(x)} != in_channels={self.in_channels}"
            )
        C, D, H, W = len(x), len(x[0]), len(x[0][0]), len(x[0][0][0])
        od, oh, ow = self._out_shape(D, H, W)
        self.x_shape = (C, D, H, W)
        self.out_shape = (self.out_channels, od, oh, ow)
        xp = self._pad(x)
        self._xp = xp

        out = []
        for oc in range(self.out_channels):
            woc = self.weights[oc]
            bias = self.biases[oc]
            plane = []
            for o_d in range(od):
                slab = []
                for o_h in range(oh):
                    row = []
                    for o_w in range(ow):
                        acc = 0.0
                        for ic in range(C):
                            wic = woc[ic]
                            xc = xp[ic]
                            for kd in range(self.kd):
                                xd = xc[o_d * self.sd + kd]
                                wd = wic[kd]
                                for kh in range(self.kh):
                                    xh = xd[o_h * self.sh + kh]
                                    wh = wd[kh]
                                    for kw in range(self.kw):
                                        acc += wh[kw] * xh[o_w * self.sw + kw]
                        row.append(acc + bias)
                    slab.append(row)
                plane.append(slab)
            out.append(plane)
        return out

    def backward(self, dout):
        """dout: (out_channels, Od, Oh, Ow) -> dx: (C, D, H, W)"""
        if self.x_shape is None:
            raise RuntimeError("Conv3d.backward: 需要先调用 forward")
        C, D, H, W = self.x_shape
        _, od, oh, ow = self.out_shape
        Dp, Hp, Wp = D + 2 * self.pd, H + 2 * self.ph, W + 2 * self.pw
        xp = self._xp
        dxp = []
        for _ in range(C):
            per_c = []
            for _ in range(Dp):
                per_d = []
                for _ in range(Hp):
                    per_d.append([0.0] * Wp)
                per_c.append(per_d)
            dxp.append(per_c)

        for oc in range(self.out_channels):
            woc = self.weights[oc]
            doc = dout[oc]
            for o_d in range(od):
                for o_h in range(oh):
                    row = doc[o_d][o_h]
                    self.grad_b[oc] += sum(row)
                    for o_w in range(ow):
                        g = row[o_w]
                        for ic in range(C):
                            wic = woc[ic]
                            gic = self.grad_w[oc][ic]
                            xc = xp[ic]
                            dc = dxp[ic]
                            for kd in range(self.kd):
                                i_d = o_d * self.sd + kd
                                xd = xc[i_d]
                                dd = dc[i_d]
                                gd = gic[kd]
                                wd = wic[kd]
                                for kh in range(self.kh):
                                    i_h = o_h * self.sh + kh
                                    xh = xd[i_h]
                                    dh = dd[i_h]
                                    gh = gd[kh]
                                    wh = wd[kh]
                                    for kw in range(self.kw):
                                        i_w = o_w * self.sw + kw
                                        gh[kw] += g * xh[i_w]
                                        dh[i_w] += g * wh[kw]

        if min(self.padding) == 0:
            return dxp
        dx = []
        for _ in range(C):
            per_c = []
            for _ in range(D):
                per_d = []
                for _ in range(H):
                    per_d.append([0.0] * W)
                per_c.append(per_d)
            dx.append(per_c)
        for c in range(C):
            for d in range(D):
                for h in range(H):
                    for w in range(W):
                        dx[c][d][h][w] = dxp[c][d + self.pd][h + self.ph][w + self.pw]
        return dx


class ConvTranspose3d:
    """3D 转置卷积（输入 (Cin, D, H, W) -> (Cout, Od, Oh, Ow)）

    每个维度的输出尺寸 `(D-1)*sd - 2*pd + kd + opd`（三轴独立）。前向把每个
    输入点乘上卷积核后按 stride 摆到输出网格累加，反向对 dx 与 grad_w 做同样
    的散射；`output_padding` 只影响输出尺寸，不引入额外参数。
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size,
                 stride=1, padding=0, output_padding=0):
        for name, v in (("in_channels", in_channels),
                        ("out_channels", out_channels)):
            if not isinstance(v, int) or isinstance(v, bool) or v <= 0:
                raise ValueError(f"ConvTranspose3d: {name} 必须是正整数，收到 {v!r}")
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = ((kernel_size, ) * 3 if isinstance(kernel_size, int)
                            else tuple(kernel_size))
        self.stride = ((stride, ) * 3 if isinstance(stride, int) else tuple(stride))
        self.padding = ((padding, ) * 3 if isinstance(padding, int)
                        else tuple(padding))
        self.output_padding = ((output_padding, ) * 3
                               if isinstance(output_padding, int)
                               else tuple(output_padding))
        if len(self.kernel_size) != 3 or min(self.kernel_size) <= 0:
            raise ValueError(
                f"ConvTranspose3d: kernel_size 必须是三个正数，收到 {kernel_size!r}")
        if len(self.stride) != 3 or min(self.stride) <= 0:
            raise ValueError(
                f"ConvTranspose3d: stride 必须是三个正数，收到 {stride!r}")
        if len(self.padding) != 3 or min(self.padding) < 0:
            raise ValueError(
                f"ConvTranspose3d: padding 必须是三个非负数，收到 {padding!r}")
        if len(self.output_padding) != 3 or min(self.output_padding) < 0:
            raise ValueError(
                f"ConvTranspose3d: output_padding 必须是三个非负数，"
                f"收到 {output_padding!r}")
        self.kd, self.kh, self.kw = self.kernel_size
        self.sd, self.sh, self.sw = self.stride
        self.pd, self.ph, self.pw = self.padding
        self.opd, self.oph, self.opw = self.output_padding
        for name, op, st in (("D", self.opd, self.sd), ("H", self.oph, self.sh),
                             ("W", self.opw, self.sw)):
            if op >= st:
                raise ValueError(
                    f"ConvTranspose3d: 维度 {name} 的 output_padding={op} "
                    f"必须小于 stride={st}"
                )

        fan_in = in_channels * self.kd * self.kh * self.kw
        std = math.sqrt(2.0 / fan_in)
        self.weights = _conv3d_random(out_channels, in_channels,
                                      self.kd, self.kh, self.kw, std)
        self.biases = [0.0] * out_channels
        self.m_w = _conv3d_zeros(out_channels, in_channels,
                                 self.kd, self.kh, self.kw)
        self.v_w = _conv3d_zeros(out_channels, in_channels,
                                 self.kd, self.kh, self.kw)
        self.m_b = [0.0] * out_channels
        self.v_b = [0.0] * out_channels
        self.x_shape = None
        self.out_shape = None
        self.zero_grad()

    def zero_grad(self):
        self.grad_w = _conv3d_zeros(self.out_channels, self.in_channels,
                                    self.kd, self.kh, self.kw)
        self.grad_b = [0.0] * self.out_channels

    def param_count(self):
        return (self.out_channels * self.in_channels * self.kd * self.kh * self.kw
                + self.out_channels)

    def _out_shape(self, D, H, W):
        od = (D - 1) * self.sd - 2 * self.pd + self.kd + self.opd
        oh = (H - 1) * self.sh - 2 * self.ph + self.kh + self.oph
        ow = (W - 1) * self.sw - 2 * self.pw + self.kw + self.opw
        if od <= 0 or oh <= 0 or ow <= 0:
            raise ValueError(
                f"ConvTranspose3d: 输入 {D}x{H}x{W} 得到输出 {od}x{oh}x{ow}，"
                f"必须都 > 0（检查 kernel/stride/padding/output_padding）"
            )
        return od, oh, ow

    def forward(self, x):
        """x: (Cin, D, H, W) -> (Cout, Od, Oh, Ow)"""
        if not x or not isinstance(x[0], list) or not isinstance(x[0][0], list):
            raise ValueError(
                "ConvTranspose3d.forward: 输入必须是 (Cin, D, H, W) 嵌套列表")
        if len(x) != self.in_channels:
            raise ValueError(
                f"ConvTranspose3d.forward: 输入通道 {len(x)} "
                f"!= in_channels={self.in_channels}"
            )
        C, D, H, W = len(x), len(x[0]), len(x[0][0]), len(x[0][0][0])
        od, oh, ow = self._out_shape(D, H, W)
        self.x_shape = (C, D, H, W)
        self.out_shape = (self.out_channels, od, oh, ow)
        self._x = x

        # 每个输出位置先放上偏置，再把输入点散射累加进去
        out = []
        for oc in range(self.out_channels):
            b = float(self.biases[oc])
            per_oc = []
            for _ in range(od):
                per_d = []
                for _ in range(oh):
                    per_d.append([b] * ow)
                per_oc.append(per_d)
            out.append(per_oc)

        for ic in range(C):
            xc = x[ic]
            for i_d in range(D):
                for i_h in range(H):
                    for i_w in range(W):
                        v = xc[i_d][i_h][i_w]
                        if v == 0.0:
                            continue
                        for oc in range(self.out_channels):
                            woc = self.weights[oc][ic]
                            for kd in range(self.kd):
                                o_d = i_d * self.sd - self.pd + kd
                                if o_d < 0 or o_d >= od:
                                    continue
                                for kh in range(self.kh):
                                    o_h = i_h * self.sh - self.ph + kh
                                    if o_h < 0 or o_h >= oh:
                                        continue
                                    dd = out[oc][o_d][o_h]
                                    wr = woc[kd][kh]
                                    for kw in range(self.kw):
                                        o_w = i_w * self.sw - self.pw + kw
                                        if 0 <= o_w < ow:
                                            dd[o_w] += v * wr[kw]
        return out

    def backward(self, dout):
        """dout: (Cout, Od, Oh, Ow) -> dx: (Cin, D, H, W)"""
        if self.x_shape is None:
            raise RuntimeError("ConvTranspose3d.backward: 需要先调用 forward")
        C, D, H, W = self.x_shape
        _, od, oh, ow = self.out_shape
        x = self._x

        for oc in range(self.out_channels):
            doc = dout[oc]
            self.grad_b[oc] += sum(doc[d][h][w]
                                   for d in range(od) for h in range(oh)
                                   for w in range(ow))

        dx = []
        for _ in range(C):
            per_c = []
            for _ in range(D):
                per_d = []
                for _ in range(H):
                    per_d.append([0.0] * W)
                per_c.append(per_d)
            dx.append(per_c)

        for ic in range(C):
            xc = x[ic]
            for i_d in range(D):
                for i_h in range(H):
                    for i_w in range(W):
                        acc = 0.0
                        v = xc[i_d][i_h][i_w]
                        for oc in range(self.out_channels):
                            woc = self.weights[oc][ic]
                            doc = dout[oc]
                            wg = self.grad_w[oc][ic]
                            for kd in range(self.kd):
                                o_d = i_d * self.sd - self.pd + kd
                                if o_d < 0 or o_d >= od:
                                    continue
                                for kh in range(self.kh):
                                    o_h = i_h * self.sh - self.ph + kh
                                    if o_h < 0 or o_h >= oh:
                                        continue
                                    for kw in range(self.kw):
                                        o_w = i_w * self.sw - self.pw + kw
                                        if 0 <= o_w < ow:
                                            g = doc[o_d][o_h][o_w]
                                            acc += g * woc[kd][kh][kw]
                                            wg[kd][kh][kw] += g * v
                        dx[ic][i_d][i_h][i_w] = acc
        return dx


class CBAMBlock:
    """CBAM 注意力：先通道注意力（SE 式瓶颈 MLP），再空间注意力（通道池化 + k×k 卷积）

    `forward((C,H,W)) -> (C,H,W)`：`u = x ⊙ s_c`（逐通道），`y = u ⊙ s_sp`（逐位置）。
    空间注意力对 `u` 做通道维的 mean/max 池化得到两张 `(H,W)` 图，拼接后过一层
    `k×k`（零填充）单输出卷积再 sigmoid。梯度全部留在 `self.grads`：
    `W1/b1/W2/b2`（通道支路）与 `sp_w/sp_b`（空间支路）。
    """

    def __init__(self, channels, reduction=16, kernel_size=7):
        for n, v in (("channels", channels), ("reduction", reduction),
                     ("kernel_size", kernel_size)):
            if isinstance(v, bool) or not isinstance(v, int) or v <= 0:
                raise ValueError(f"CBAMBlock: {n} 必须是正整数，收到 {v!r}")
        if kernel_size % 2 == 0:
            raise ValueError(f"CBAMBlock: kernel_size 必须是奇数，收到 {kernel_size}")
        self.channels = channels
        self.reduction = reduction
        self.kernel_size = kernel_size
        self.half = kernel_size // 2
        self.hidden = max(1, channels // reduction)
        std1 = (2.0 / channels) ** 0.5
        std2 = (2.0 / self.hidden) ** 0.5
        self.W1 = [[random.gauss(0.0, std1) for _ in range(channels)]
                   for _ in range(self.hidden)]
        self.b1 = [0.0] * self.hidden
        self.W2 = [[random.gauss(0.0, std2) for _ in range(self.hidden)]
                   for _ in range(channels)]
        self.b2 = [0.0] * channels
        k = kernel_size
        std3 = (2.0 / (2 * k * k)) ** 0.5
        self.sp_w = [[random.gauss(0.0, std3) for _ in range(k)] for _ in range(k)]
        self.sp_b = [0.0]  # 单元素列表：Adam/计数辅助只吃序列
        self.training = True
        self._cache = None
        self._adam_m = {k2: _zeros_like(v) for k2, v in self._params()}
        self._adam_v = {k2: _zeros_like(v) for k2, v in self._params()}
        self._adam_t = 0
        self.zero_grad()

    def _params(self):
        return (("W1", self.W1), ("b1", self.b1), ("W2", self.W2), ("b2", self.b2),
                ("sp_w", self.sp_w), ("sp_b", self.sp_b))

    def zero_grad(self):
        self.grads = {k: _zeros_like(v) for k, v in self._params()}

    def sgd_step(self, lr):
        """原地 SGD：`param -= lr * grad`（参数在 `_params()` 里）"""
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"CBAMBlock: lr 必须是非负数字，收到 {lr!r}")
        for key, param in self._params():
            _sgd_apply(param, self.grads[key], float(lr))

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        """原地 Adam；步数记在 `_adam_t`，矩在 `_adam_m` / `_adam_v`"""
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"CBAMBlock: lr 必须是非负数字，收到 {lr!r}")
        self._adam_t += 1
        for key, param in self._params():
            _adam_apply(param, self.grads[key], self._adam_m[key],
                        self._adam_v[key], self._adam_t, float(lr),
                        beta1, beta2, eps)

    def param_count(self):
        return _w2_count(self._params())

    def train(self):
        self.training = True

    def eval(self):
        self.training = False

    def _spatial_conv(self, pooled):
        """pooled: (2,H,W) -> (H,W) 的 k×k 零填充卷积 + 偏置（未过 sigmoid）"""
        H, W = len(pooled[0]), len(pooled[0][0])
        k, half = self.kernel_size, self.half
        out = [[self.sp_b[0] for _ in range(W)] for _ in range(H)]
        for h in range(H):
            for w in range(W):
                acc = 0.0
                for a in range(k):
                    ih = h + a - half
                    if ih < 0 or ih >= H:
                        continue
                    prow = pooled
                    wrow = self.sp_w[a]
                    for b in range(k):
                        iw = w + b - half
                        if iw < 0 or iw >= W:
                            continue
                        acc += wrow[b] * (prow[0][ih][iw] + prow[1][ih][iw])
                out[h][w] += acc
        return out

    def forward(self, x):
        if not x or not x[0] or not x[0][0]:
            raise ValueError("CBAMBlock: 输入不能为空")
        C, H, W = len(x), len(x[0]), len(x[0][0])
        if C != self.channels:
            raise ValueError(
                f"CBAMBlock: 输入通道数 {C} 与 channels={self.channels} 不符")
        # 通道注意力
        z = _w2_channel_means(x)
        a1 = [sum(map(_mul, self.W1[k], z)) + self.b1[k] for k in range(self.hidden)]
        r1 = [v if v > 0.0 else 0.0 for v in a1]
        a2 = [sum(map(_mul, self.W2[c], r1)) + self.b2[c] for c in range(C)]
        s_c = [_sigmoid_scalar(v) for v in a2]
        u = [[[x[c][h][w] * s_c[c] for w in range(W)] for h in range(H)]
             for c in range(C)]
        # 空间注意力：通道维 mean / max 池化
        mean_map = [[0.0] * W for _ in range(H)]
        max_map = [[0.0] * W for _ in range(H)]
        arg_map = [[0] * W for _ in range(H)]
        for h in range(H):
            for w in range(W):
                best = u[0][h][w]
                arg = 0
                total = u[0][h][w]
                for c in range(1, C):
                    v = u[c][h][w]
                    total += v
                    if v > best:
                        best = v
                        arg = c
                mean_map[h][w] = total / C
                max_map[h][w] = best
                arg_map[h][w] = arg
        pooled = [mean_map, max_map]
        z_sp = self._spatial_conv(pooled)
        s_sp = [[_sigmoid_scalar(z_sp[h][w]) for w in range(W)] for h in range(H)]
        out = [[[u[c][h][w] * s_sp[h][w] for w in range(W)] for h in range(H)]
               for c in range(C)]
        self._cache = (x, u, s_c, r1, a1, z, mean_map, max_map, arg_map, s_sp)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("CBAMBlock.backward: 必须先调用 forward")
        x, u, s_c, r1, a1, z, mean_map, max_map, arg_map, s_sp = self._cache
        C, H, W = len(x), len(x[0]), len(x[0][0])
        if (len(dout) != C or len(dout[0]) != H or len(dout[0][0]) != W):
            raise ValueError(
                f"CBAMBlock.backward: dout 形状 "
                f"{(len(dout), len(dout[0]), len(dout[0][0]))} "
                f"与输入 {(C, H, W)} 不符")

        # 1) 经空间注意力的链
        du = [[[dout[c][h][w] * s_sp[h][w] for w in range(W)] for h in range(H)]
              for c in range(C)]
        ds_sp = [[0.0] * W for _ in range(H)]
        for h in range(H):
            for w in range(W):
                acc = 0.0
                for c in range(C):
                    acc += dout[c][h][w] * u[c][h][w]
                ds_sp[h][w] = acc
        dz_sp = [[ds_sp[h][w] * s_sp[h][w] * (1.0 - s_sp[h][w]) for w in range(W)]
                 for h in range(H)]
        k, half = self.kernel_size, self.half
        d_mean = [[0.0] * W for _ in range(H)]
        d_max = [[0.0] * W for _ in range(H)]
        db_sp = 0.0
        for h in range(H):
            for w in range(W):
                g = dz_sp[h][w]
                if g == 0.0:
                    continue
                db_sp += g
                for a in range(k):
                    ih = h + a - half
                    if ih < 0 or ih >= H:
                        continue
                    for b in range(k):
                        iw = w + b - half
                        if iw < 0 or iw >= W:
                            continue
                        self.grads["sp_w"][a][b] += g * (mean_map[ih][iw]
                                                        + max_map[ih][iw])
        self.grads["sp_b"][0] += db_sp
        # dL/dpooled[i][j] = Σ_{a,b} sp_w[a][b] · dz_sp[i - a + half][j - b + half]
        # （对 z = conv(pooled) 求反卷积；下标方向写反会在核不对称时差一个翻转）
        for h in range(H):
            for w in range(W):
                acc = 0.0
                for a in range(k):
                    ih = h - a + half
                    if ih < 0 or ih >= H:
                        continue
                    for b in range(k):
                        iw = w - b + half
                        if iw < 0 or iw >= W:
                            continue
                        acc += dz_sp[ih][iw] * self.sp_w[a][b]
                d_mean[h][w] = acc
                d_max[h][w] = acc
        for h in range(H):
            for w in range(W):
                du[arg_map[h][w]][h][w] += d_max[h][w]
                share = d_mean[h][w] / C
                for c in range(C):
                    du[c][h][w] += share

        # 2) 经通道注意力的链
        area = float(H * W)
        ds_c = [0.0] * C
        for c in range(C):
            acc = 0.0
            for h in range(H):
                for w in range(W):
                    acc += du[c][h][w] * x[c][h][w]
            ds_c[c] = acc
        da2 = [ds_c[c] * s_c[c] * (1.0 - s_c[c]) for c in range(C)]
        for c in range(C):
            for kk in range(self.hidden):
                self.grads["W2"][c][kk] += da2[c] * r1[kk]
            self.grads["b2"][c] += da2[c]
        dz_ch = [0.0] * C
        for kk in range(self.hidden):
            dr1 = sum(da2[c] * self.W2[c][kk] for c in range(C))
            da1 = dr1 if a1[kk] > 0.0 else 0.0
            for c in range(C):
                self.grads["W1"][kk][c] += da1 * z[c]
            self.grads["b1"][kk] += da1
            for c in range(C):
                dz_ch[c] += da1 * self.W1[kk][c]
        dx = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        for c in range(C):
            g = dz_ch[c] / area
            for h in range(H):
                for w in range(W):
                    dx[c][h][w] = du[c][h][w] * s_c[c] + g
        return dx


def _gelu_scalar(z):
    """GELU（tanh 近似），与 Layer._gelu 同一公式，逐位一致"""
    u = _GELU_C * (z + 0.044715 * z * z * z)
    return 0.5 * z * (1.0 + math.tanh(u))


def _dgelu_scalar(z):
    """GELU 的导数，与 Layer._gelu_deriv 同一公式"""
    u = _GELU_C * (z + 0.044715 * z * z * z)
    t = math.tanh(u)
    du = _GELU_C * (1.0 + 3.0 * 0.044715 * z * z)
    return 0.5 * (1.0 + t) + 0.5 * z * (1.0 - t * t) * du


def _w2_concat(a, b):
    """(Ca,H,W) + (Cb,H,W) -> (Ca+Cb,H,W)"""
    return [list(ch) for ch in a] + [list(ch) for ch in b]


class DenseBlock:
    """DenseNet 稠密块：每层 `BN -> ReLU -> 3x3 Conv`，输出与输入在通道维拼接

    `forward((Cin,H,W)) -> (Cin + growth_rate*num_layers, H, W)`；
    第 i 层的输入是前面所有层输出的拼接（通道维），因此 `bns[i]` 的通道数逐层增长。
    BN 的 gamma/beta 梯度收在 `self.bn_grads`，键 `L{i}_gamma` / `L{i}_beta`。
    """

    def __init__(self, in_channels, growth_rate=4, num_layers=3, kernel_size=3):
        for n, v in (("in_channels", in_channels), ("growth_rate", growth_rate),
                     ("num_layers", num_layers), ("kernel_size", kernel_size)):
            if isinstance(v, bool) or not isinstance(v, int) or v <= 0:
                raise ValueError(f"DenseBlock: {n} 必须是正整数，收到 {v!r}")
        self.in_channels = in_channels
        self.growth_rate = growth_rate
        self.num_layers = num_layers
        self.kernel_size = kernel_size
        pad = kernel_size // 2
        self.convs = []
        self.bns = []
        cur = in_channels
        for _ in range(num_layers):
            self.bns.append(BatchNorm2d(cur))
            self.convs.append(Conv2d(cur, growth_rate, kernel_size, stride=1, padding=pad))
            cur += growth_rate
        self.out_channels = cur
        self.training = True
        self.bn_grads = {}
        for i in range(num_layers):
            self.bn_grads["L%d_gamma" % i] = [0.0] * self.bns[i].c
            self.bn_grads["L%d_beta" % i] = [0.0] * self.bns[i].c
        self._cache = None

    def zero_grad(self):
        for conv in self.convs:
            conv.zero_grad()
        for i, bn in enumerate(self.bns):
            self.bn_grads["L%d_gamma" % i] = [0.0] * bn.c
            self.bn_grads["L%d_beta" % i] = [0.0] * bn.c

    def param_count(self):
        total = sum(_conv_param_count(c) for c in self.convs)
        total += 2 * sum(bn.c for bn in self.bns)
        return total

    def train(self):
        self.training = True
        for bn in self.bns:
            bn.train()

    def eval(self):
        self.training = False
        for bn in self.bns:
            bn.eval()

    def sgd_step(self, lr):
        for conv in self.convs:
            _conv_sgd(conv, lr)

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        for conv in self.convs:
            _conv_adam(conv, lr, beta1, beta2, eps)

    def forward(self, x):
        if not x or not x[0] or not x[0][0]:
            raise ValueError("DenseBlock: 输入不能为空")
        C, H, W = len(x), len(x[0]), len(x[0][0])
        if C != self.in_channels:
            raise ValueError(
                f"DenseBlock: 输入通道数 {C} 与 in_channels={self.in_channels} 不符")
        cur = x
        cache = []
        for i in range(self.num_layers):
            a = self.bns[i].forward(cur)
            r = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in a]
            h = self.convs[i].forward(r)
            cache.append((cur, a, r))
            cur = _w2_concat(cur, h)
        self._cache = (cache, C, H, W)
        return cur

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("DenseBlock.backward: 必须先调用 forward")
        cache, C, H, W = self._cache
        if (len(dout) != self.out_channels or len(dout[0]) != H
                or len(dout[0][0]) != W):
            raise ValueError(
                f"DenseBlock.backward: dout 形状 "
                f"{(len(dout), len(dout[0]), len(dout[0][0]))} 与输出 "
                f"{(self.out_channels, H, W)} 不符")
        dcum = dout
        for i in range(self.num_layers - 1, -1, -1):
            cur, a, r = cache[i]
            cin = len(cur)
            d_prev = dcum[:cin]
            d_new = dcum[cin:]
            if len(d_new) != self.growth_rate:
                raise ValueError("DenseBlock.backward: 梯度通道数与 growth_rate 不符")
            dh = self.convs[i].backward(d_new)
            dr = [[[dh[c][h][w] if a[c][h][w] > 0.0 else 0.0 for w in range(W)]
                   for h in range(H)] for c in range(cin)]
            da, g, b = self.bns[i].backward(dr)
            for c in range(cin):
                self.bn_grads["L%d_gamma" % i][c] += g[c]
                self.bn_grads["L%d_beta" % i][c] += b[c]
            dcum = [[[d_prev[c][h][w] + da[c][h][w] for w in range(W)]
                     for h in range(H)] for c in range(cin)]
        if len(dcum) != C:
            raise ValueError("DenseBlock.backward: 回传到输入的通道数不符")
        return dcum


class ConvNeXtBlock:
    """ConvNeXt 块：`7x7 depthwise Conv -> LayerNorm(跨通道) -> 1x1 升维 -> GELU -> 1x1 降维` + 残差

    数据布局是 channels-first 的 `(C,H,W)`，所以"LayerNorm"是在**每个空间位置上
    跨通道**做归一化（等价于 channels-last 的 LayerNorm）。gamma/beta 长度 C，
    梯度收在 `self.norm_grads["gamma"]` / `["beta"]`。
    """

    def __init__(self, channels, kernel_size=7, expansion=4, eps=1e-6):
        for n, v in (("channels", channels), ("kernel_size", kernel_size),
                     ("expansion", expansion)):
            if isinstance(v, bool) or not isinstance(v, int) or v <= 0:
                raise ValueError(f"ConvNeXtBlock: {n} 必须是正整数，收到 {v!r}")
        if isinstance(eps, bool) or not isinstance(eps, (int, float)) or eps <= 0:
            raise ValueError(f"ConvNeXtBlock: eps 必须是正数，收到 {eps!r}")
        self.channels = channels
        self.kernel_size = kernel_size
        self.expansion = expansion
        self.hidden = channels * expansion
        self.eps = float(eps)
        self.dw = Conv2d(channels, channels, kernel_size, stride=1,
                         padding=kernel_size // 2, groups=channels)
        self.pw1 = Conv2d(channels, self.hidden, 1)
        self.pw2 = Conv2d(self.hidden, channels, 1)
        self.gamma = [1.0] * channels
        self.beta = [0.0] * channels
        self.norm_grads = {"gamma": [0.0] * channels, "beta": [0.0] * channels}
        self.training = True
        self._cache = None

    def zero_grad(self):
        self.dw.zero_grad()
        self.pw1.zero_grad()
        self.pw2.zero_grad()
        self.norm_grads["gamma"] = [0.0] * self.channels
        self.norm_grads["beta"] = [0.0] * self.channels

    def param_count(self):
        return (_conv_param_count(self.dw) + _conv_param_count(self.pw1)
                + _conv_param_count(self.pw2) + 2 * self.channels)

    def train(self):
        self.training = True

    def eval(self):
        self.training = False

    def sgd_step(self, lr):
        _conv_sgd(self.dw, lr)
        _conv_sgd(self.pw1, lr)
        _conv_sgd(self.pw2, lr)

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        _conv_adam(self.dw, lr, beta1, beta2, eps)
        _conv_adam(self.pw1, lr, beta1, beta2, eps)
        _conv_adam(self.pw2, lr, beta1, beta2, eps)

    def forward(self, x):
        if not x or not x[0] or not x[0][0]:
            raise ValueError("ConvNeXtBlock: 输入不能为空")
        C, H, W = len(x), len(x[0]), len(x[0][0])
        if C != self.channels:
            raise ValueError(
                f"ConvNeXtBlock: 输入通道数 {C} 与 channels={self.channels} 不符")
        u = self.dw.forward(x)
        n = float(C)
        var = [0.0] * 0
        xhat = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        inv = [[0.0] * W for _ in range(H)]
        for h in range(H):
            for w in range(W):
                total = 0.0
                for c in range(C):
                    total += u[c][h][w]
                mu = total / n
                acc = 0.0
                for c in range(C):
                    d = u[c][h][w] - mu
                    acc += d * d
                v = acc / n
                iv = 1.0 / math.sqrt(v + self.eps)
                inv[h][w] = iv
                for c in range(C):
                    xhat[c][h][w] = (u[c][h][w] - mu) * iv
        z = [[[self.gamma[c] * xhat[c][h][w] + self.beta[c] for w in range(W)]
              for h in range(H)] for c in range(C)]
        g1 = self.pw1.forward(z)
        act = [[[ _gelu_scalar(v) for v in row] for row in ch] for ch in g1]
        g2 = self.pw2.forward(act)
        out = [[[g2[c][h][w] + x[c][h][w] for w in range(W)] for h in range(H)]
               for c in range(C)]
        self._cache = (x, u, xhat, inv, z, g1, act)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("ConvNeXtBlock.backward: 必须先调用 forward")
        x, u, xhat, inv, z, g1, act = self._cache
        C, H, W = len(x), len(x[0]), len(x[0][0])
        if len(dout) != C or len(dout[0]) != H or len(dout[0][0]) != W:
            raise ValueError(
                f"ConvNeXtBlock.backward: dout 形状 "
                f"{(len(dout), len(dout[0]), len(dout[0][0]))} 与输入 {(C, H, W)} 不符")
        dact = self.pw2.backward(dout)
        # 注意：这里是升维后的 hidden 个通道，不是输入的 C 个
        dg1 = [[[dact[c][h][w] * _dgelu_scalar(g1[c][h][w]) for w in range(W)]
                for h in range(H)] for c in range(self.hidden)]
        dz = self.pw1.backward(dg1)
        n = float(C)
        du = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        for h in range(H):
            for w in range(W):
                dg = [dz[c][h][w] for c in range(C)]
                for c in range(C):
                    self.norm_grads["gamma"][c] += dg[c] * xhat[c][h][w]
                    self.norm_grads["beta"][c] += dg[c]
                iv = inv[h][w]
                mean_dxhat = 0.0
                mean_dxhat_xhat = 0.0
                for c in range(C):
                    dxhat = dg[c] * self.gamma[c]
                    mean_dxhat += dxhat
                    mean_dxhat_xhat += dxhat * xhat[c][h][w]
                mean_dxhat /= n
                mean_dxhat_xhat /= n
                for c in range(C):
                    dxhat = dg[c] * self.gamma[c]
                    du[c][h][w] = (dxhat - mean_dxhat
                                   - xhat[c][h][w] * mean_dxhat_xhat) * iv
        ddw = self.dw.backward(du)
        return [[[ddw[c][h][w] + dout[c][h][w] for w in range(W)] for h in range(H)]
                for c in range(C)]


class FractionalMaxPool2d:
    """分数最大池化：输出尺寸由比例决定，每个输出格在一个**重叠的随机窗口**里取最大值

    `FractionalMaxPool2d(output_ratio=(0.5, 0.5), rng=None)`
    `forward((C,H,W)) -> (C, max(1,int(H*rh)), max(1,int(W*rw)))`

    每个输出位置对应的输入跨度是 `alpha = H/out_h`（一般非整数），窗口长度取
    `floor(alpha)`，起点在 `[oh*alpha, (oh+1)*alpha - k]` 里均匀随机取整 —— 相邻窗口
    因此重叠，这一点与 `AdaptiveMaxPool2d`（不重叠、确定性）不同。随机源可注入
    `random.Random` 实例以保证可复现；不给就用全局 `random`（与 `Dropout` 一致）。
    """

    def __init__(self, output_ratio=(0.5, 0.5), rng=None):
        if isinstance(output_ratio, (int, float)) and not isinstance(output_ratio, bool):
            output_ratio = (output_ratio, output_ratio)
        if not isinstance(output_ratio, (tuple, list)) or len(output_ratio) != 2:
            raise ValueError(
                "FractionalMaxPool2d: output_ratio 必须是数字或二元组，收到 %r"
                % (output_ratio,))
        for v in output_ratio:
            if isinstance(v, bool) or not isinstance(v, (int, float)) or not (0.0 < v <= 1.0):
                raise ValueError(
                    "FractionalMaxPool2d: output_ratio 每项必须在 (0, 1] 内，收到 %r" % (v,))
        self.output_ratio = (float(output_ratio[0]), float(output_ratio[1]))
        self.rng = random if rng is None else rng
        self.mask = None
        self.x_shape = None
        self.out_shape = None

    def forward(self, x):
        """x: (C, H, W) -> (C, Ho, Wo)"""
        if not x or not x[0] or not x[0][0] or isinstance(x[0][0][0], (list, tuple)):
            raise ValueError("FractionalMaxPool2d: 输入必须是 (C,H,W) 非空嵌套 list")
        C, H, W = len(x), len(x[0]), len(x[0][0])
        rh, rw = self.output_ratio
        ho = max(1, int(H * rh))
        wo = max(1, int(W * rw))
        alpha_h = H / float(ho)
        alpha_w = W / float(wo)
        kh = max(1, int(alpha_h))
        kw = max(1, int(alpha_w))
        self.x_shape = (C, H, W)
        self.out_shape = (ho, wo)
        self.mask = [[[(0, 0)] * wo for _ in range(ho)] for _ in range(C)]
        out = [[[0.0] * wo for _ in range(ho)] for _ in range(C)]
        starts_h = []
        for oh in range(ho):
            lo = oh * alpha_h
            hi = min(float(H - kh), (oh + 1) * alpha_h - kh)
            start = int(lo + self.rng.random() * max(0.0, hi - lo))
            if start < 0:
                start = 0
            if start > H - kh:
                start = H - kh
            starts_h.append(start)
        starts_w = []
        for ow in range(wo):
            lo = ow * alpha_w
            hi = min(float(W - kw), (ow + 1) * alpha_w - kw)
            start = int(lo + self.rng.random() * max(0.0, hi - lo))
            if start < 0:
                start = 0
            if start > W - kw:
                start = W - kw
            starts_w.append(start)
        for c in range(C):
            for oh in range(ho):
                sh = starts_h[oh]
                for ow in range(wo):
                    sw = starts_w[ow]
                    best = None
                    best_pos = (sh, sw)
                    for i in range(kh):
                        for j in range(kw):
                            v = x[c][sh + i][sw + j]
                            if best is None or v > best:
                                best = v
                                best_pos = (sh + i, sw + j)
                    out[c][oh][ow] = best
                    self.mask[c][oh][ow] = best_pos
        return out

    def backward(self, dout):
        """只把梯度回传给每个窗口里被选中的那个位置"""
        if self.mask is None:
            raise RuntimeError("FractionalMaxPool2d.backward: 必须先调用 forward")
        C, H, W = self.x_shape
        ho, wo = self.out_shape
        if len(dout) != C or len(dout[0]) != ho or len(dout[0][0]) != wo:
            raise ValueError(
                "FractionalMaxPool2d.backward: dout 形状与输出 (%d, %d, %d) 不符"
                % (C, ho, wo))
        dx = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        for c in range(C):
            for oh in range(ho):
                for ow in range(wo):
                    ih, iw = self.mask[c][oh][ow]
                    dx[c][ih][iw] += dout[c][oh][ow]
        return dx


class StochasticPool2d:
    """随机池化：每个窗口按激活值归一化后的概率**采样一个元素**（Zeiler & Fergus 2013）

    `StochasticPool2d(kernel_size, stride=None, rng=None)`
    `forward((C,H,W)) -> (C,Ho,Wo)`

    训练时窗口内权重 `p_i = relu(x_i) / Σ relu(x_j)`（全非正时退化为均匀），按 p 采样
    一个位置、输出它的**原值**，反向只回传该位置并乘上 `p_i`。
    `eval()` 关闭随机性：输出是概率加权期望 `Σ p_i x_i`，反向对每个位置都乘 `p_i`。
    """

    def __init__(self, kernel_size, stride=None, rng=None, eps=1e-12):
        ks = (kernel_size, kernel_size) if isinstance(kernel_size, int) else kernel_size
        if not isinstance(ks, (tuple, list)) or len(ks) != 2:
            raise ValueError("StochasticPool2d: kernel_size 非法，收到 %r" % (kernel_size,))
        self.kh, self.kw = int(ks[0]), int(ks[1])
        if self.kh <= 0 or self.kw <= 0:
            raise ValueError("StochasticPool2d: kernel_size 必须为正，收到 %r" % (ks,))
        st = ks if stride is None else (
            (stride, stride) if isinstance(stride, int) else stride)
        self.sh, self.sw = int(st[0]), int(st[1])
        if self.sh <= 0 or self.sw <= 0:
            raise ValueError("StochasticPool2d: stride 必须为正，收到 %r" % (st,))
        if isinstance(eps, bool) or not isinstance(eps, (int, float)) or eps <= 0:
            raise ValueError("StochasticPool2d: eps 必须是正数，收到 %r" % (eps,))
        self.eps = float(eps)
        self.rng = random if rng is None else rng
        self.training = True
        self.x_shape = None
        self.out_shape = None
        self.tag = None
        self.probs = None

    def train(self):
        self.training = True
        return self

    def eval(self):
        self.training = False
        return self

    def _window_probs(self, x, c, oh, ow):
        vals = []
        for i in range(self.kh):
            for j in range(self.kw):
                v = x[c][oh * self.sh + i][ow * self.sw + j]
                vals.append(v if v > 0.0 else 0.0)
        total = 0.0
        for v in vals:
            total += v
        n = len(vals)
        if total <= self.eps:
            return [1.0 / n] * n
        return [v / total for v in vals]

    def forward(self, x):
        if not x or not x[0] or not x[0][0] or isinstance(x[0][0][0], (list, tuple)):
            raise ValueError("StochasticPool2d: 输入必须是 (C,H,W) 非空嵌套 list")
        C, H, W = len(x), len(x[0]), len(x[0][0])
        ho = (H - self.kh) // self.sh + 1
        wo = (W - self.kw) // self.sw + 1
        if ho <= 0 or wo <= 0:
            raise ValueError(
                "StochasticPool2d: 输入 %dx%d 配 kernel %dx%d、stride %d/%d 得到输出 "
                "%dx%d，必须都 > 0" % (H, W, self.kh, self.kw, self.sh, self.sw, ho, wo))
        self.x_shape = (C, H, W)
        self.out_shape = (ho, wo)
        self.probs = [[[None] * wo for _ in range(ho)] for _ in range(C)]
        self.tag = [[[0] * wo for _ in range(ho)] for _ in range(C)]
        out = [[[0.0] * wo for _ in range(ho)] for _ in range(C)]
        for c in range(C):
            for oh in range(ho):
                for ow in range(wo):
                    probs = self._window_probs(x, c, oh, ow)
                    self.probs[c][oh][ow] = probs
                    vals = [x[c][oh * self.sh + i][ow * self.sw + j]
                            for i in range(self.kh) for j in range(self.kw)]
                    if self.training:
                        r = self.rng.random()
                        acc = 0.0
                        pick = len(probs) - 1
                        for idx in range(len(probs)):
                            acc += probs[idx]
                            if r < acc:
                                pick = idx
                                break
                        self.tag[c][oh][ow] = pick
                        out[c][oh][ow] = vals[pick]
                    else:
                        acc = 0.0
                        for idx in range(len(probs)):
                            acc += probs[idx] * vals[idx]
                        out[c][oh][ow] = acc
        return out

    def backward(self, dout):
        if self.probs is None:
            raise RuntimeError("StochasticPool2d.backward: 必须先调用 forward")
        C, H, W = self.x_shape
        ho, wo = self.out_shape
        if len(dout) != C or len(dout[0]) != ho or len(dout[0][0]) != wo:
            raise ValueError(
                "StochasticPool2d.backward: dout 形状与输出 (%d, %d, %d) 不符"
                % (C, ho, wo))
        dx = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        for c in range(C):
            for oh in range(ho):
                for ow in range(wo):
                    probs = self.probs[c][oh][ow]
                    d = dout[c][oh][ow]
                    if self.training:
                        idx = self.tag[c][oh][ow]
                        i, j = divmod(idx, self.kw)
                        dx[c][oh * self.sh + i][ow * self.sw + j] += d * probs[idx]
                    else:
                        idx = 0
                        for i in range(self.kh):
                            for j in range(self.kw):
                                dx[c][oh * self.sh + i][ow * self.sw + j] += d * probs[idx]
                                idx += 1
        return dx


class ConditionalNorm:
    """条件归一化：把条件向量投影成 gamma/beta，再对特征做层归一化后仿射

    `ConditionalNorm(features, cond_dim, eps=1e-5)`；
    用法：`set_cond(cond)` 之后 `forward(x)`，`x` 是长度 `features` 的一维向量。
    `gamma = 1 + W_g·cond + b_g`，`beta = W_b·cond + b_b`，`y = gamma ⊙ xhat + beta`
    （`xhat` 是 x 的层归一化）。

    梯度留在 `self.grads`（`W_g`/`b_g`/`W_b`/`b_b`），对条件向量的梯度在 `self.grad_cond`。
    """

    def __init__(self, features, cond_dim, eps=1e-5):
        for n, v in (("features", features), ("cond_dim", cond_dim)):
            if isinstance(v, bool) or not isinstance(v, int) or v <= 0:
                raise ValueError("ConditionalNorm: %s 必须是正整数，收到 %r" % (n, v))
        if isinstance(eps, bool) or not isinstance(eps, (int, float)) or eps <= 0:
            raise ValueError("ConditionalNorm: eps 必须是正数，收到 %r" % (eps,))
        self.features = features
        self.cond_dim = cond_dim
        self.eps = float(eps)
        std = (1.0 / cond_dim) ** 0.5
        self.W_g = [[random.gauss(0.0, std) for _ in range(cond_dim)]
                    for _ in range(features)]
        self.b_g = [0.0] * features
        self.W_b = [[random.gauss(0.0, std) for _ in range(cond_dim)]
                    for _ in range(features)]
        self.b_b = [0.0] * features
        self.cond = None
        self._cache = None
        self._adam_m = {k: _zeros_like(v) for k, v in self._params()}
        self._adam_v = {k: _zeros_like(v) for k, v in self._params()}
        self._adam_t = 0
        self.zero_grad()

    def _params(self):
        return (("W_g", self.W_g), ("b_g", self.b_g),
                ("W_b", self.W_b), ("b_b", self.b_b))

    def zero_grad(self):
        self.grads = {k: _zeros_like(v) for k, v in self._params()}
        self.grad_cond = [0.0] * self.cond_dim

    def param_count(self):
        return _w2_count(self._params())

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError("ConditionalNorm: lr 必须是非负数字，收到 %r" % (lr,))
        for key, param in self._params():
            _sgd_apply(param, self.grads[key], float(lr))

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError("ConditionalNorm: lr 必须是非负数字，收到 %r" % (lr,))
        self._adam_t += 1
        for key, param in self._params():
            _adam_apply(param, self.grads[key], self._adam_m[key],
                        self._adam_v[key], self._adam_t, float(lr),
                        beta1, beta2, eps)

    def set_cond(self, cond):
        if not isinstance(cond, (list, tuple)) or len(cond) != self.cond_dim:
            raise ValueError(
                "ConditionalNorm.set_cond: 条件向量长度必须是 %d，收到 %r"
                % (self.cond_dim, cond))
        self.cond = [float(v) for v in cond]
        return self

    def forward(self, x):
        if not isinstance(x, (list, tuple)) or len(x) != self.features:
            raise ValueError(
                "ConditionalNorm.forward: 输入长度必须是 %d" % self.features)
        for v in x:
            if isinstance(v, (list, tuple)):
                raise ValueError("ConditionalNorm.forward: 只支持一维特征向量")
        if self.cond is None:
            raise RuntimeError("ConditionalNorm.forward: 必须先调用 set_cond")
        n = float(self.features)
        mu = 0.0
        for v in x:
            mu += v
        mu /= n
        var = 0.0
        for v in x:
            d = v - mu
            var += d * d
        var /= n
        inv = 1.0 / math.sqrt(var + self.eps)
        xhat = [(v - mu) * inv for v in x]
        gamma = []
        beta = []
        for c in range(self.features):
            acc_g = 1.0 + self.b_g[c]
            acc_b = self.b_b[c]
            row_g = self.W_g[c]
            row_b = self.W_b[c]
            for j in range(self.cond_dim):
                acc_g += row_g[j] * self.cond[j]
                acc_b += row_b[j] * self.cond[j]
            gamma.append(acc_g)
            beta.append(acc_b)
        out = [gamma[c] * xhat[c] + beta[c] for c in range(self.features)]
        self._cache = (xhat, inv, gamma)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("ConditionalNorm.backward: 必须先调用 forward")
        xhat, inv, gamma = self._cache
        n = self.features
        if len(dout) != n:
            raise ValueError(
                "ConditionalNorm.backward: dout 长度必须是 %d，收到 %d" % (n, len(dout)))
        for c in range(n):
            dg = dout[c] * xhat[c]
            db = dout[c]
            self.grads["b_g"][c] += dg
            self.grads["b_b"][c] += db
            row_g = self.grads["W_g"][c]
            row_b = self.grads["W_b"][c]
            for j in range(self.cond_dim):
                row_g[j] += dg * self.cond[j]
                row_b[j] += db * self.cond[j]
        for j in range(self.cond_dim):
            acc = 0.0
            for c in range(n):
                acc += (dout[c] * xhat[c] * self.W_g[c][j]
                        + dout[c] * self.W_b[c][j])
            self.grad_cond[j] = acc
        dxhat = [dout[c] * gamma[c] for c in range(n)]
        total = 0.0
        for v in dxhat:
            total += v
        total_x = 0.0
        for c in range(n):
            total_x += dxhat[c] * xhat[c]
        mean_d = total / n
        mean_dx = total_x / n
        return [(dxhat[c] - mean_d - xhat[c] * mean_dx) * inv for c in range(n)]


class PReLU:
    """参数化 ReLU：y_i = x_i (x_i > 0) 否则 a_i * x_i

    `a` 逐特征（per-channel）可学习。`init` 是小正数（默认 0.25，与 PyTorch 一致），
    负数输出不会被完全压死。x_i == 0 时按正分支处理（导数为 1）。
    """

    def __init__(self, num_features: int, init: float = 0.25):
        if isinstance(num_features, bool) or not isinstance(num_features, int):
            raise TypeError(
                f"PReLU: num_features 必须是 int，收到 {type(num_features).__name__}")
        if num_features < 1:
            raise ValueError(f"PReLU: num_features 必须 >= 1，收到 {num_features!r}")
        if not isinstance(init, (int, float)) or isinstance(init, bool):
            raise TypeError(f"PReLU: init 必须是数字，收到 {type(init).__name__}")
        if not math.isfinite(float(init)):
            raise ValueError(f"PReLU: init 必须是有限数，收到 {init!r}")
        self.d = num_features
        self.a = [float(init)] * self.d
        self.x = None
        self.grad_a = [0.0] * self.d
        self.m_a = [0.0] * self.d
        self.v_a = [0.0] * self.d
        self._adam_t = 0
        self.training = True

    def forward(self, x):
        if len(x) != self.d:
            raise ValueError(
                f"PReLU.forward: 特征维度 {len(x)} 与本层 {self.d} 不一致")
        self.x = x
        return [x[i] if x[i] > 0.0 else self.a[i] * x[i] for i in range(self.d)]

    def backward(self, dout):
        if self.x is None:
            raise RuntimeError("PReLU.backward: 必须先调用 forward()")
        if len(dout) != self.d:
            raise ValueError(
                f"PReLU.backward: dout 长度 {len(dout)} 与本层维度 {self.d} 不一致")
        for i in range(self.d):
            if self.x[i] > 0.0:
                self.grad_a[i] += 0.0
            else:
                self.grad_a[i] += dout[i] * self.x[i]
        return [dout[i] if self.x[i] > 0.0 else dout[i] * self.a[i]
                for i in range(self.d)]

    def zero_grad(self):
        self.grad_a = [0.0] * self.d

    def param_count(self):
        return self.d

    def train(self):
        self.training = True
        return self

    def eval(self):
        self.training = False
        return self

    def sgd_step(self, lr):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"PReLU.sgd_step: lr 必须是非负数，收到 {lr!r}")
        for i in range(self.d):
            self.a[i] -= lr * self.grad_a[i]
        self.zero_grad()

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"PReLU.adam_step: lr 必须是非负数，收到 {lr!r}")
        self._adam_t += 1
        _adam_apply(self.a, self.grad_a, self.m_a, self.v_a, self._adam_t,
                    lr, beta1, beta2, eps)
        self.zero_grad()


class Snake:
    """Snake 激活（Ziyin et al. 2020）：y_i = x_i + sin²(a_i·x_i)/a_i

    周期激活，在周期性/音频类数据上比 GELU 更好。`a_i` 逐特征可学习，
    `a → 0` 时退化为恒等映射（这里按极限 `y ≈ x + a·x²` 处理，避免 0/0）。

    导数：dy/dx = 1 + sin(2 a x)，dy/da = 2 sin(a x)cos(a x)x/a − sin²(a x)/a²。
    """

    def __init__(self, num_features: int, init: float = 1.0):
        if isinstance(num_features, bool) or not isinstance(num_features, int):
            raise TypeError(
                f"Snake: num_features 必须是 int，收到 {type(num_features).__name__}")
        if num_features < 1:
            raise ValueError(f"Snake: num_features 必须 >= 1，收到 {num_features!r}")
        if not isinstance(init, (int, float)) or isinstance(init, bool):
            raise TypeError(f"Snake: init 必须是数字，收到 {type(init).__name__}")
        if not math.isfinite(float(init)):
            raise ValueError(f"Snake: init 必须是有限数，收到 {init!r}")
        self.d = num_features
        self.a = [float(init)] * self.d
        self.x = None
        self.grad_a = [0.0] * self.d
        self.m_a = [0.0] * self.d
        self.v_a = [0.0] * self.d
        self._adam_t = 0
        self.training = True

    def forward(self, x):
        if len(x) != self.d:
            raise ValueError(
                f"Snake.forward: 特征维度 {len(x)} 与本层 {self.d} 不一致")
        self.x = x
        out = []
        for i in range(self.d):
            a = self.a[i]
            if abs(a) < 1e-8:
                out.append(x[i])
            else:
                sv = math.sin(a * x[i])
                out.append(x[i] + sv * sv / a)
        return out

    def backward(self, dout):
        if self.x is None:
            raise RuntimeError("Snake.backward: 必须先调用 forward()")
        if len(dout) != self.d:
            raise ValueError(
                f"Snake.backward: dout 长度 {len(dout)} 与本层维度 {self.d} 不一致")
        dx = []
        for i in range(self.d):
            a = self.a[i]
            xv = self.x[i]
            if abs(a) < 1e-8:
                dx.append(dout[i])
                self.grad_a[i] += dout[i] * xv * xv
            else:
                sv = math.sin(a * xv)
                cv = math.cos(a * xv)
                dx.append(dout[i] * (1.0 + 2.0 * sv * cv))
                self.grad_a[i] += dout[i] * (2.0 * sv * cv * xv / a
                                             - sv * sv / (a * a))
        return dx

    def zero_grad(self):
        self.grad_a = [0.0] * self.d

    def param_count(self):
        return self.d

    def train(self):
        self.training = True
        return self

    def eval(self):
        self.training = False
        return self

    def sgd_step(self, lr):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"Snake.sgd_step: lr 必须是非负数，收到 {lr!r}")
        for i in range(self.d):
            self.a[i] -= lr * self.grad_a[i]
        self.zero_grad()

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"Snake.adam_step: lr 必须是非负数，收到 {lr!r}")
        self._adam_t += 1
        _adam_apply(self.a, self.grad_a, self.m_a, self.v_a, self._adam_t,
                    lr, beta1, beta2, eps)
        self.zero_grad()


class Maxout:
    """Maxout：out_i = max_k (a_ki * x_i + b_ki)

    每个特征位置上并行 `num_pieces` 条仿射支路，取最大。凸的、分段线性，
    可以逼近任何凸函数。梯度只流向被选中的那条支路（argmax 路由）。
    """

    def __init__(self, num_features: int, num_pieces: int = 2):
        if isinstance(num_features, bool) or not isinstance(num_features, int):
            raise TypeError(
                f"Maxout: num_features 必须是 int，收到 {type(num_features).__name__}")
        if num_features < 1:
            raise ValueError(f"Maxout: num_features 必须 >= 1，收到 {num_features!r}")
        if isinstance(num_pieces, bool) or not isinstance(num_pieces, int):
            raise TypeError(
                f"Maxout: num_pieces 必须是 int，收到 {type(num_pieces).__name__}")
        if num_pieces < 2:
            raise ValueError(
                f"Maxout: num_pieces 必须 >= 2（否则退化成单条仿射），收到 {num_pieces!r}")
        self.d = num_features
        self.k = num_pieces
        # 第 0 条支路是恒等（a=1,b=0），其余是 0.5 斜率 —— 确定性初始化，
        # 相当于一个"软" LeakyReLU 起点
        self.a = [[1.0 if k == 0 else 0.5 for _ in range(self.d)]
                  for k in range(self.k)]
        self.b = [[0.0] * self.d for _ in range(self.k)]
        self.x = None
        self.arg = None
        self.grad_a = [[0.0] * self.d for _ in range(self.k)]
        self.grad_b = [[0.0] * self.d for _ in range(self.k)]
        self.m_a = [[0.0] * self.d for _ in range(self.k)]
        self.v_a = [[0.0] * self.d for _ in range(self.k)]
        self.m_b = [[0.0] * self.d for _ in range(self.k)]
        self.v_b = [[0.0] * self.d for _ in range(self.k)]
        self._adam_t = 0
        self.training = True

    def forward(self, x):
        if len(x) != self.d:
            raise ValueError(
                f"Maxout.forward: 特征维度 {len(x)} 与本层 {self.d} 不一致")
        self.x = x
        out = [0.0] * self.d
        arg = [0] * self.d
        for i in range(self.d):
            best = self.a[0][i] * x[i] + self.b[0][i]
            best_k = 0
            for k in range(1, self.k):
                v = self.a[k][i] * x[i] + self.b[k][i]
                if v > best:
                    best = v
                    best_k = k
            out[i] = best
            arg[i] = best_k
        self.arg = arg
        return out

    def backward(self, dout):
        if self.x is None:
            raise RuntimeError("Maxout.backward: 必须先调用 forward()")
        if len(dout) != self.d:
            raise ValueError(
                f"Maxout.backward: dout 长度 {len(dout)} 与本层维度 {self.d} 不一致")
        self.zero_grad()
        dx = [0.0] * self.d
        for i in range(self.d):
            k = self.arg[i]
            self.grad_a[k][i] += dout[i] * self.x[i]
            self.grad_b[k][i] += dout[i]
            dx[i] = dout[i] * self.a[k][i]
        return dx

    def zero_grad(self):
        self.grad_a = [[0.0] * self.d for _ in range(self.k)]
        self.grad_b = [[0.0] * self.d for _ in range(self.k)]

    def param_count(self):
        return 2 * self.d * self.k

    def train(self):
        self.training = True
        return self

    def eval(self):
        self.training = False
        return self

    def _check_lr(self, lr, who):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"{who}: lr 必须是非负数，收到 {lr!r}")
        return float(lr)

    def sgd_step(self, lr):
        lr = self._check_lr(lr, "Maxout.sgd_step")
        for k in range(self.k):
            for i in range(self.d):
                self.a[k][i] -= lr * self.grad_a[k][i]
                self.b[k][i] -= lr * self.grad_b[k][i]
        self.zero_grad()

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        lr = self._check_lr(lr, "Maxout.adam_step")
        self._adam_t += 1
        for k in range(self.k):
            for i in range(self.d):
                ga = self.grad_a[k][i]
                gb = self.grad_b[k][i]
                self.m_a[k][i] = beta1 * self.m_a[k][i] + (1 - beta1) * ga
                self.v_a[k][i] = beta2 * self.v_a[k][i] + (1 - beta2) * ga * ga
                mh = self.m_a[k][i] / (1 - beta1 ** self._adam_t)
                vh = self.v_a[k][i] / (1 - beta2 ** self._adam_t)
                self.a[k][i] -= lr * mh / (math.sqrt(vh) + eps)
                self.m_b[k][i] = beta1 * self.m_b[k][i] + (1 - beta1) * gb
                self.v_b[k][i] = beta2 * self.v_b[k][i] + (1 - beta2) * gb * gb
                mh = self.m_b[k][i] / (1 - beta1 ** self._adam_t)
                vh = self.v_b[k][i] / (1 - beta2 ** self._adam_t)
                self.b[k][i] -= lr * mh / (math.sqrt(vh) + eps)
        self.zero_grad()


class DynamicReLU:
    """动态 ReLU（DY-ReLU-A 的逐特征简化版）

    负分支的斜率不是固定参数，而是由**输入自身的全局上下文**（各特征均值）
    线性预测：`a_i = w_i * z + b_i`，`z = mean(x)`。于是 `a` 随样本而变，
    这是它和 PReLU 的本质区别。

    注意 dx 耦合：改 x_j 会改变 z，进而改变**所有**负分支的斜率，所以
    `dx_j` 里有一项 `w_j * x_j/d * sum_{i: x_i<=0} dout_i * x_i`。
    """

    def __init__(self, num_features: int, init_slope: float = 0.25):
        if isinstance(num_features, bool) or not isinstance(num_features, int):
            raise TypeError(
                f"DynamicReLU: num_features 必须是 int，收到 {type(num_features).__name__}")
        if num_features < 1:
            raise ValueError(
                f"DynamicReLU: num_features 必须 >= 1，收到 {num_features!r}")
        if isinstance(init_slope, bool) or not isinstance(init_slope, (int, float)):
            raise TypeError(
                f"DynamicReLU: init_slope 必须是数字，收到 {type(init_slope).__name__}")
        if not math.isfinite(float(init_slope)):
            raise ValueError(
                f"DynamicReLU: init_slope 必须是有限数，收到 {init_slope!r}")
        self.d = num_features
        # w=0、b=init_slope ⇒ 初始时 a 恒为 init_slope（退化成一个 LeakyReLU 起点）
        self.w = [0.0] * self.d
        self.b = [float(init_slope)] * self.d
        self.x = None
        self.z = 0.0
        self.slope = None
        self.grad_w = [0.0] * self.d
        self.grad_b = [0.0] * self.d
        self.m_w = [0.0] * self.d
        self.v_w = [0.0] * self.d
        self.m_b = [0.0] * self.d
        self.v_b = [0.0] * self.d
        self._adam_t = 0
        self.training = True

    def forward(self, x):
        if len(x) != self.d:
            raise ValueError(
                f"DynamicReLU.forward: 特征维度 {len(x)} 与本层 {self.d} 不一致")
        self.x = x
        self.z = sum(x) / self.d
        self.slope = [self.w[i] * self.z + self.b[i] for i in range(self.d)]
        return [x[i] if x[i] > 0.0 else self.slope[i] * x[i] for i in range(self.d)]

    def backward(self, dout):
        if self.x is None:
            raise RuntimeError("DynamicReLU.backward: 必须先调用 forward()")
        if len(dout) != self.d:
            raise ValueError(
                f"DynamicReLU.backward: dout 长度 {len(dout)} 与本层维度 {self.d} 不一致")
        self.zero_grad()
        # 负分支的斜率 a_i = w_i*z + b_i 依赖 z = mean(x)，所以 ∂y_i/∂x_j 里有
        # x_i*w_i/d 这一项 —— 它对**所有** j 都非零（不只是 i == j）。
        # 聚合起来：dx_j = (正分支 ? dout_j : dout_j*a_j) + (1/d)*Σ_{i∈负} dout_i*x_i*w_i
        s_coup = 0.0
        for i in range(self.d):
            if self.x[i] <= 0.0:
                s_coup += dout[i] * self.x[i] * self.w[i]
        dx = [0.0] * self.d
        for i in range(self.d):
            if self.x[i] > 0.0:
                dx[i] = dout[i]
            else:
                dx[i] = dout[i] * self.slope[i]
                self.grad_w[i] += dout[i] * self.x[i] * self.z
                self.grad_b[i] += dout[i] * self.x[i]
        for i in range(self.d):
            dx[i] += s_coup / self.d
        return dx

    def zero_grad(self):
        self.grad_w = [0.0] * self.d
        self.grad_b = [0.0] * self.d

    def param_count(self):
        return 2 * self.d

    def train(self):
        self.training = True
        return self

    def eval(self):
        self.training = False
        return self

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"DynamicReLU.sgd_step: lr 必须是非负数，收到 {lr!r}")
        for i in range(self.d):
            self.w[i] -= lr * self.grad_w[i]
            self.b[i] -= lr * self.grad_b[i]
        self.zero_grad()

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"DynamicReLU.adam_step: lr 必须是非负数，收到 {lr!r}")
        self._adam_t += 1
        for i in range(self.d):
            for holder, grad, m, v in ((self.w, self.grad_w[i], self.m_w, self.v_w),
                                       (self.b, self.grad_b[i], self.m_b, self.v_b)):
                m[i] = beta1 * m[i] + (1 - beta1) * grad
                v[i] = beta2 * v[i] + (1 - beta2) * grad * grad
                mh = m[i] / (1 - beta1 ** self._adam_t)
                vh = v[i] / (1 - beta2 ** self._adam_t)
                holder[i] -= lr * mh / (math.sqrt(vh) + eps)
        self.zero_grad()


class FReLU:
    """FReLU（漏斗激活）：y = max(x, T(x))

    `T` 是逐通道的 k×k 深度卷积（零填充、边界保持），于是激活形状是
    **二维漏斗**而不是一条直线。`w`/`b` 全零初始化时 `T(x) == 0`，
    本层严格退化成 ReLU —— 这是可测的恒等性质。
    """

    def __init__(self, channels: int, kernel_size: int = 3):
        if isinstance(channels, bool) or not isinstance(channels, int):
            raise TypeError(
                f"FReLU: channels 必须是 int，收到 {type(channels).__name__}")
        if channels < 1:
            raise ValueError(f"FReLU: channels 必须 >= 1，收到 {channels!r}")
        if isinstance(kernel_size, bool) or not isinstance(kernel_size, int):
            raise TypeError(
                f"FReLU: kernel_size 必须是 int，收到 {type(kernel_size).__name__}")
        if kernel_size < 1 or kernel_size % 2 == 0:
            raise ValueError(
                f"FReLU: kernel_size 必须是正奇数，收到 {kernel_size!r}")
        self.c = channels
        self.k = kernel_size
        self.pad = kernel_size // 2
        self.w = [[[0.0] * self.k for _ in range(self.k)] for _ in range(self.c)]
        self.b = [0.0] * self.c
        self.x = None
        self.mask = None
        self.grad_w = [[[0.0] * self.k for _ in range(self.k)] for _ in range(self.c)]
        self.grad_b = [0.0] * self.c
        self.m_w = [[[0.0] * self.k for _ in range(self.k)] for _ in range(self.c)]
        self.v_w = [[[0.0] * self.k for _ in range(self.k)] for _ in range(self.c)]
        self.m_b = [0.0] * self.c
        self.v_b = [0.0] * self.c
        self._adam_t = 0
        self.training = True

    def _pad(self, x):
        h = len(x[0])
        w = len(x[0][0])
        p = self.pad
        out = [[[0.0] * (w + 2 * p) for _ in range(h + 2 * p)] for _ in range(self.c)]
        for c in range(self.c):
            for i in range(h):
                for j in range(w):
                    out[c][i + p][j + p] = x[c][i][j]
        return out, h, w

    def forward(self, x):
        if len(x) != self.c:
            raise ValueError(
                f"FReLU.forward: 通道数 {len(x)} 与本层 {self.c} 不一致")
        h = len(x[0])
        w = len(x[0][0])
        for c in range(self.c):
            if len(x[c]) != h or len(x[c][0]) != w:
                raise ValueError("FReLU.forward: 各通道空间尺寸必须一致")
        self.x = x
        xp, _, _ = self._pad(x)
        out = [[[0.0] * w for _ in range(h)] for _ in range(self.c)]
        mask = [[[False] * w for _ in range(h)] for _ in range(self.c)]
        for c in range(self.c):
            for i in range(h):
                for j in range(w):
                    t = self.b[c]
                    for a in range(self.k):
                        for bb in range(self.k):
                            t += self.w[c][a][bb] * xp[c][i + a][j + bb]
                    xv = x[c][i][j]
                    if t > xv:
                        out[c][i][j] = t
                        mask[c][i][j] = True
                    else:
                        out[c][i][j] = xv
        self.mask = mask
        return out

    def backward(self, dout):
        if self.x is None:
            raise RuntimeError("FReLU.backward: 必须先调用 forward()")
        h = len(self.x[0])
        w = len(self.x[0][0])
        if len(dout) != self.c or len(dout[0]) != h or len(dout[0][0]) != w:
            raise ValueError("FReLU.backward: dout 形状必须与 forward 的输入一致")
        self.zero_grad()
        xp, _, _ = self._pad(self.x)
        dx = [[[0.0] * w for _ in range(h)] for _ in range(self.c)]
        dz = [[[0.0] * w for _ in range(h)] for _ in range(self.c)]
        for c in range(self.c):
            for i in range(h):
                for j in range(w):
                    if self.mask[c][i][j]:
                        dz[c][i][j] = dout[c][i][j]
                    else:
                        dx[c][i][j] += dout[c][i][j]
        for c in range(self.c):
            for i in range(h):
                for j in range(w):
                    g = dz[c][i][j]
                    if g == 0.0:
                        continue
                    self.grad_b[c] += g
                    for a in range(self.k):
                        for bb in range(self.k):
                            self.grad_w[c][a][bb] += g * xp[c][i + a][j + bb]
        # 把卷积支路的梯度散射回输入
        for c in range(self.c):
            for i in range(h):
                for j in range(w):
                    g = dz[c][i][j]
                    if g == 0.0:
                        continue
                    for a in range(self.k):
                        for bb in range(self.k):
                            xi = i + a - self.pad
                            xj = j + bb - self.pad
                            if 0 <= xi < h and 0 <= xj < w:
                                dx[c][xi][xj] += g * self.w[c][a][bb]
        return dx

    def zero_grad(self):
        self.grad_w = [[[0.0] * self.k for _ in range(self.k)] for _ in range(self.c)]
        self.grad_b = [0.0] * self.c

    def param_count(self):
        return self.c * self.k * self.k + self.c

    def train(self):
        self.training = True
        return self

    def eval(self):
        self.training = False
        return self

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"FReLU.sgd_step: lr 必须是非负数，收到 {lr!r}")
        for c in range(self.c):
            for a in range(self.k):
                for bb in range(self.k):
                    self.w[c][a][bb] -= lr * self.grad_w[c][a][bb]
            self.b[c] -= lr * self.grad_b[c]
        self.zero_grad()

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"FReLU.adam_step: lr 必须是非负数，收到 {lr!r}")
        self._adam_t += 1
        for c in range(self.c):
            for a in range(self.k):
                for bb in range(self.k):
                    g = self.grad_w[c][a][bb]
                    self.m_w[c][a][bb] = beta1 * self.m_w[c][a][bb] + (1 - beta1) * g
                    self.v_w[c][a][bb] = beta2 * self.v_w[c][a][bb] + (1 - beta2) * g * g
                    mh = self.m_w[c][a][bb] / (1 - beta1 ** self._adam_t)
                    vh = self.v_w[c][a][bb] / (1 - beta2 ** self._adam_t)
                    self.w[c][a][bb] -= lr * mh / (math.sqrt(vh) + eps)
            g = self.grad_b[c]
            self.m_b[c] = beta1 * self.m_b[c] + (1 - beta1) * g
            self.v_b[c] = beta2 * self.v_b[c] + (1 - beta2) * g * g
            mh = self.m_b[c] / (1 - beta1 ** self._adam_t)
            vh = self.v_b[c] / (1 - beta2 ** self._adam_t)
            self.b[c] -= lr * mh / (math.sqrt(vh) + eps)
        self.zero_grad()


def _dense_param_count(layer):
    """`Layer` 的参数量（权重 + 偏置）；`Layer` 本身没有 `param_count()`"""
    return len(layer.weights) * len(layer.weights[0]) + len(layer.biases)


def _dense_apply_sgd(layer, grads, lr):
    """把 `backward` 返回的 `(grad_w, grad_b)` 原地 SGD 到 `Layer` 上"""
    if grads is None:
        raise RuntimeError("_dense_apply_sgd: 必须先调用 backward()")
    gw, gb = grads
    for i in range(len(layer.weights)):
        wi = layer.weights[i]
        for j in range(len(wi)):
            wi[j] -= lr * gw[i][j]
    for i in range(len(layer.biases)):
        layer.biases[i] -= lr * gb[i]


def _dense_apply_adam(layer, grads, lr, beta1=0.9, beta2=0.999, eps=1e-8):
    """把 `backward` 的梯度原地 Adam 到 `Layer`（矩复用 layer 自带的 `m_*`/`v_*`）"""
    if grads is None:
        raise RuntimeError("_dense_apply_adam: 必须先调用 backward()")
    _check_adam_betas(beta1, beta2, "_dense_apply_adam")
    gw, gb = grads
    layer._dense_adam_t = getattr(layer, '_dense_adam_t', 0) + 1
    t = layer._dense_adam_t
    c1 = 1.0 - beta1 ** t
    c2 = 1.0 - beta2 ** t
    for i in range(len(layer.weights)):
        wi, gw_i = layer.weights[i], gw[i]
        mw_i, vw_i = layer.m_w[i], layer.v_w[i]
        for j in range(len(wi)):
            g = gw_i[j]
            mw_i[j] = beta1 * mw_i[j] + (1 - beta1) * g
            vw_i[j] = beta2 * vw_i[j] + (1 - beta2) * g * g
            wi[j] -= lr * (mw_i[j] / c1) / (math.sqrt(vw_i[j] / c2) + eps)
    for i in range(len(layer.biases)):
        g = gb[i]
        layer.m_b[i] = beta1 * layer.m_b[i] + (1 - beta1) * g
        layer.v_b[i] = beta2 * layer.v_b[i] + (1 - beta2) * g * g
        layer.biases[i] -= lr * (layer.m_b[i] / c1) / (
            math.sqrt(layer.v_b[i] / c2) + eps)


def _norm_param_count(norm):
    """`LayerNorm` 的参数量（gamma + beta）"""
    return 2 * len(norm.gamma)


def _norm_apply_sgd(norm, grads, lr):
    """把 `LayerNorm.backward` 的 `(grad_gamma, grad_beta)` 原地 SGD"""
    if grads is None:
        raise RuntimeError("_norm_apply_sgd: 必须先调用 backward()")
    gg, gbeta = grads
    for i in range(len(norm.gamma)):
        norm.gamma[i] -= lr * gg[i]
        norm.beta[i] -= lr * gbeta[i]


def _norm_apply_adam(norm, grads, lr, beta1=0.9, beta2=0.999, eps=1e-8):
    if grads is None:
        raise RuntimeError("_norm_apply_adam: 必须先调用 backward()")
    _check_adam_betas(beta1, beta2, "_norm_apply_adam")
    gg, gbeta = grads
    norm._dense_adam_t = getattr(norm, '_dense_adam_t', 0) + 1
    t = norm._dense_adam_t
    c1 = 1.0 - beta1 ** t
    c2 = 1.0 - beta2 ** t
    for i in range(len(norm.gamma)):
        g = gg[i]
        norm.m_gamma[i] = beta1 * norm.m_gamma[i] + (1 - beta1) * g
        norm.v_gamma[i] = beta2 * norm.v_gamma[i] + (1 - beta2) * g * g
        norm.gamma[i] -= lr * (norm.m_gamma[i] / c1) / (
            math.sqrt(norm.v_gamma[i] / c2) + eps)
        g = gbeta[i]
        norm.m_beta[i] = beta1 * norm.m_beta[i] + (1 - beta1) * g
        norm.v_beta[i] = beta2 * norm.v_beta[i] + (1 - beta2) * g * g
        norm.beta[i] -= lr * (norm.m_beta[i] / c1) / (
            math.sqrt(norm.v_beta[i] / c2) + eps)


class ReZero:
    """ReZero：`y = x + alpha * f(x)`，`alpha` 从 0 开始可学

    分支初始乘 0 ⇒ 整块初始就是恒等映射，深层网络一开始不会爆也不会消。
    `f` 必须是有 `(grad_w, grad_b, delta)` 三元组反向的 `Layer`。
    """

    def __init__(self, layer: "Layer", init_alpha: float = 0.0):
        if not isinstance(layer, Layer):
            raise TypeError(
                f"ReZero: layer 必须是 Layer，收到 {type(layer).__name__}")
        if isinstance(init_alpha, bool) or not isinstance(init_alpha, (int, float)):
            raise TypeError(
                f"ReZero: init_alpha 必须是数字，收到 {type(init_alpha).__name__}")
        if not math.isfinite(float(init_alpha)):
            raise ValueError(f"ReZero: init_alpha 必须是有限数，收到 {init_alpha!r}")
        self.layer = layer
        self.d = layer.fan_in
        self.alpha = [float(init_alpha)]
        self.x = None
        self.branch = None
        self.grad_alpha = [0.0]
        self.m_alpha = [0.0]
        self.v_alpha = [0.0]
        self._adam_t = 0
        self.inner_grads = None
        self.training = True

    def forward(self, x):
        if len(x) != self.d:
            raise ValueError(
                f"ReZero.forward: 输入长度 {len(x)} 与本层 {self.d} 不一致")
        self.x = x
        b = self.layer.forward(x)
        self.branch = b
        a = self.alpha[0]
        return [x[i] + a * b[i] for i in range(self.d)]

    def backward(self, dout):
        if self.x is None:
            raise RuntimeError("ReZero.backward: 必须先调用 forward()")
        if len(dout) != self.d:
            raise ValueError(
                f"ReZero.backward: dout 长度 {len(dout)} 与本层 {self.d} 不一致")
        a = self.alpha[0]
        gw, gb, delta = self.layer.backward([a * v for v in dout])
        self.inner_grads = (gw, gb)
        self.grad_alpha = [sum(dout[i] * self.branch[i] for i in range(self.d))]
        return [dout[i] + delta[i] for i in range(self.d)]

    def zero_grad(self):
        self.grad_alpha = [0.0]
        self.inner_grads = None

    def param_count(self):
        return _dense_param_count(self.layer) + 1

    def train(self):
        self.training = True
        self.layer.train()
        return self

    def eval(self):
        self.training = False
        self.layer.eval()
        return self

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"ReZero.sgd_step: lr 必须是非负数，收到 {lr!r}")
        self.alpha[0] -= lr * self.grad_alpha[0]
        _dense_apply_sgd(self.layer, self.inner_grads, lr)
        self.zero_grad()

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"ReZero.adam_step: lr 必须是非负数，收到 {lr!r}")
        self._adam_t += 1
        g = self.grad_alpha[0]
        self.m_alpha[0] = beta1 * self.m_alpha[0] + (1 - beta1) * g
        self.v_alpha[0] = beta2 * self.v_alpha[0] + (1 - beta2) * g * g
        mh = self.m_alpha[0] / (1 - beta1 ** self._adam_t)
        vh = self.v_alpha[0] / (1 - beta2 ** self._adam_t)
        self.alpha[0] -= lr * mh / (math.sqrt(vh) + eps)
        _dense_apply_adam(self.layer, self.inner_grads, lr, beta1, beta2, eps)
        self.zero_grad()


class SkipInit:
    """SkipInit：`y = x + beta * f(x)`，`beta = 1/sqrt(num_blocks)` **固定**

    和 ReZero 的区别是缩放系数不可学、按块数预先定死（原论文的做法），
    目的是让残差分支的累积方差与块数无关。
    """

    def __init__(self, layer: "Layer", num_blocks: int = 1):
        if not isinstance(layer, Layer):
            raise TypeError(
                f"SkipInit: layer 必须是 Layer，收到 {type(layer).__name__}")
        if isinstance(num_blocks, bool) or not isinstance(num_blocks, int):
            raise TypeError(
                f"SkipInit: num_blocks 必须是 int，收到 {type(num_blocks).__name__}")
        if num_blocks < 1:
            raise ValueError(
                f"SkipInit: num_blocks 必须 >= 1，收到 {num_blocks!r}")
        self.layer = layer
        self.d = layer.fan_in
        self.num_blocks = num_blocks
        self.beta = 1.0 / math.sqrt(num_blocks)
        self.x = None
        self.inner_grads = None
        self.training = True

    def forward(self, x):
        if len(x) != self.d:
            raise ValueError(
                f"SkipInit.forward: 输入长度 {len(x)} 与本层 {self.d} 不一致")
        self.x = x
        b = self.layer.forward(x)
        return [x[i] + self.beta * b[i] for i in range(self.d)]

    def backward(self, dout):
        if self.x is None:
            raise RuntimeError("SkipInit.backward: 必须先调用 forward()")
        if len(dout) != self.d:
            raise ValueError(
                f"SkipInit.backward: dout 长度 {len(dout)} 与本层 {self.d} 不一致")
        gw, gb, delta = self.layer.backward([self.beta * v for v in dout])
        self.inner_grads = (gw, gb)
        return [dout[i] + delta[i] for i in range(self.d)]

    def zero_grad(self):
        self.inner_grads = None

    def param_count(self):
        return _dense_param_count(self.layer)

    def train(self):
        self.training = True
        self.layer.train()
        return self

    def eval(self):
        self.training = False
        self.layer.eval()
        return self

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"SkipInit.sgd_step: lr 必须是非负数，收到 {lr!r}")
        _dense_apply_sgd(self.layer, self.inner_grads, lr)
        self.zero_grad()

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"SkipInit.adam_step: lr 必须是非负数，收到 {lr!r}")
        _dense_apply_adam(self.layer, self.inner_grads, lr, beta1, beta2, eps)
        self.zero_grad()


class PreNormResidual:
    """Pre-LN 残差：`y = x + f(LN(x))`

    归一化放在分支入口，主路是干净的单位通路 —— 深层梯度不会在 LN 处衰减，
    这是现在主流 Transformer 的摆法（Post-LN 是原始实现）。
    """

    def __init__(self, layer: "Layer", eps: float = 1e-5):
        if not isinstance(layer, Layer):
            raise TypeError(
                f"PreNormResidual: layer 必须是 Layer，收到 {type(layer).__name__}")
        self.layer = layer
        self.d = layer.fan_in
        self.norm = LayerNorm(self.d, eps)
        self.x = None
        self.inner_grads = None
        self.norm_grads = None
        self.training = True

    def forward(self, x):
        if len(x) != self.d:
            raise ValueError(
                f"PreNormResidual.forward: 输入长度 {len(x)} 与本层 {self.d} 不一致")
        self.x = x
        n = self.norm.forward(x)
        b = self.layer.forward(n)
        return [x[i] + b[i] for i in range(self.d)]

    def backward(self, dout):
        if self.x is None:
            raise RuntimeError("PreNormResidual.backward: 必须先调用 forward()")
        if len(dout) != self.d:
            raise ValueError(
                f"PreNormResidual.backward: dout 长度 {len(dout)} 与本层 {self.d} 不一致")
        gw, gb, delta = self.layer.backward(dout)
        self.inner_grads = (gw, gb)
        gg, gbeta, dnorm = self.norm.backward(delta)
        self.norm_grads = (gg, gbeta)
        return [dout[i] + dnorm[i] for i in range(self.d)]

    def zero_grad(self):
        self.inner_grads = None
        self.norm_grads = None

    def param_count(self):
        return _dense_param_count(self.layer) + _norm_param_count(self.norm)

    def train(self):
        self.training = True
        self.layer.train()
        self.norm.train()
        return self

    def eval(self):
        self.training = False
        self.layer.eval()
        self.norm.eval()
        return self

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"PreNormResidual.sgd_step: lr 必须是非负数，收到 {lr!r}")
        _dense_apply_sgd(self.layer, self.inner_grads, lr)
        _norm_apply_sgd(self.norm, self.norm_grads, lr)
        self.zero_grad()

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(
                f"PreNormResidual.adam_step: lr 必须是非负数，收到 {lr!r}")
        _dense_apply_adam(self.layer, self.inner_grads, lr, beta1, beta2, eps)
        _norm_apply_adam(self.norm, self.norm_grads, lr, beta1, beta2, eps)
        self.zero_grad()


class PostNormResidual:
    """Post-LN 残差：`y = LN(x + f(x))`（Transformer 原始论文的摆法）"""

    def __init__(self, layer: "Layer", eps: float = 1e-5):
        if not isinstance(layer, Layer):
            raise TypeError(
                f"PostNormResidual: layer 必须是 Layer，收到 {type(layer).__name__}")
        self.layer = layer
        self.d = layer.fan_in
        self.norm = LayerNorm(self.d, eps)
        self.x = None
        self.summed = None
        self.inner_grads = None
        self.norm_grads = None
        self.training = True

    def forward(self, x):
        if len(x) != self.d:
            raise ValueError(
                f"PostNormResidual.forward: 输入长度 {len(x)} 与本层 {self.d} 不一致")
        self.x = x
        b = self.layer.forward(x)
        s = [x[i] + b[i] for i in range(self.d)]
        self.summed = s
        return self.norm.forward(s)

    def backward(self, dout):
        if self.x is None:
            raise RuntimeError("PostNormResidual.backward: 必须先调用 forward()")
        if len(dout) != self.d:
            raise ValueError(
                f"PostNormResidual.backward: dout 长度 {len(dout)} 与本层 {self.d} 不一致")
        gg, gbeta, ds = self.norm.backward(dout)
        self.norm_grads = (gg, gbeta)
        gw, gb, delta = self.layer.backward(ds)
        self.inner_grads = (gw, gb)
        return [ds[i] + delta[i] for i in range(self.d)]

    def zero_grad(self):
        self.inner_grads = None
        self.norm_grads = None

    def param_count(self):
        return _dense_param_count(self.layer) + _norm_param_count(self.norm)

    def train(self):
        self.training = True
        self.layer.train()
        self.norm.train()
        return self

    def eval(self):
        self.training = False
        self.layer.eval()
        self.norm.eval()
        return self

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(
                f"PostNormResidual.sgd_step: lr 必须是非负数，收到 {lr!r}")
        _dense_apply_sgd(self.layer, self.inner_grads, lr)
        _norm_apply_sgd(self.norm, self.norm_grads, lr)
        self.zero_grad()

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(
                f"PostNormResidual.adam_step: lr 必须是非负数，收到 {lr!r}")
        _dense_apply_adam(self.layer, self.inner_grads, lr, beta1, beta2, eps)
        _norm_apply_adam(self.norm, self.norm_grads, lr, beta1, beta2, eps)
        self.zero_grad()


class Highway:
    """Highway：`y = g ⊙ x + (1 - g) ⊙ tanh(w ⊙ x + b)`，`g = sigmoid(W_g x + b_g)`

    门控是**逐特征**的，并且依赖整条输入（`W_g` 是矩阵），所以 `dx` 里有一项
    要把 dout 通过门控传回所有输入维度。变换支路用逐特征权重 `w`（对角），
    这样保留"每个通道自己的变换"语义。
    """

    def __init__(self, num_features: int):
        if isinstance(num_features, bool) or not isinstance(num_features, int):
            raise TypeError(
                f"Highway: num_features 必须是 int，收到 {type(num_features).__name__}")
        if num_features < 1:
            raise ValueError(
                f"Highway: num_features 必须 >= 1，收到 {num_features!r}")
        self.d = num_features
        rng = random.Random(1234)
        std = math.sqrt(1.0 / self.d)
        self.wg = [[rng.gauss(0.0, std) for _ in range(self.d)] for _ in range(self.d)]
        self.bg = [0.0] * self.d
        self.w = [rng.gauss(0.0, std) for _ in range(self.d)]
        self.b = [0.0] * self.d
        self.grad_wg = [[0.0] * self.d for _ in range(self.d)]
        self.grad_bg = [0.0] * self.d
        self.grad_w = [0.0] * self.d
        self.grad_b = [0.0] * self.d
        self._init_adam()
        self.x = None
        self.g = None
        self.h = None
        self.training = True

    def _init_adam(self):
        self.m_wg = [[0.0] * self.d for _ in range(self.d)]
        self.v_wg = [[0.0] * self.d for _ in range(self.d)]
        self.m_bg = [0.0] * self.d
        self.v_bg = [0.0] * self.d
        self.m_w = [0.0] * self.d
        self.v_w = [0.0] * self.d
        self.m_b = [0.0] * self.d
        self.v_b = [0.0] * self.d
        self._adam_t = 0

    def forward(self, x):
        if len(x) != self.d:
            raise ValueError(
                f"Highway.forward: 输入长度 {len(x)} 与本层 {self.d} 不一致")
        self.x = x
        g = []
        for i in range(self.d):
            acc = self.bg[i]
            for j in range(self.d):
                acc += self.wg[i][j] * x[j]
            g.append(1.0 / (1.0 + math.exp(-acc)) if acc >= 0 else
                     math.exp(acc) / (1.0 + math.exp(acc)))
        h = [math.tanh(self.w[i] * x[i] + self.b[i]) for i in range(self.d)]
        self.g = g
        self.h = h
        return [g[i] * x[i] + (1.0 - g[i]) * h[i] for i in range(self.d)]

    def backward(self, dout):
        if self.x is None:
            raise RuntimeError("Highway.backward: 必须先调用 forward()")
        if len(dout) != self.d:
            raise ValueError(
                f"Highway.backward: dout 长度 {len(dout)} 与本层 {self.d} 不一致")
        self.zero_grad()
        # 门控的局部梯度：dg_i = dout_i * (x_i - h_i)
        dg_pre = [dout[i] * (self.x[i] - self.h[i]) * self.g[i] * (1.0 - self.g[i])
                  for i in range(self.d)]
        for i in range(self.d):
            self.grad_bg[i] += dg_pre[i]
            for j in range(self.d):
                self.grad_wg[i][j] += dg_pre[i] * self.x[j]
        dpre_h = [dout[i] * (1.0 - self.g[i]) * (1.0 - self.h[i] ** 2)
                  for i in range(self.d)]
        for i in range(self.d):
            self.grad_w[i] += dpre_h[i] * self.x[i]
            self.grad_b[i] += dpre_h[i]
        dx = [0.0] * self.d
        for j in range(self.d):
            acc = dout[j] * self.g[j]
            for i in range(self.d):
                acc += dg_pre[i] * self.wg[i][j]
            acc += dpre_h[j] * self.w[j]
            dx[j] = acc
        return dx

    def zero_grad(self):
        self.grad_wg = [[0.0] * self.d for _ in range(self.d)]
        self.grad_bg = [0.0] * self.d
        self.grad_w = [0.0] * self.d
        self.grad_b = [0.0] * self.d

    def param_count(self):
        return self.d * self.d + self.d + 2 * self.d

    def train(self):
        self.training = True
        return self

    def eval(self):
        self.training = False
        return self

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"Highway.sgd_step: lr 必须是非负数，收到 {lr!r}")
        for i in range(self.d):
            for j in range(self.d):
                self.wg[i][j] -= lr * self.grad_wg[i][j]
            self.bg[i] -= lr * self.grad_bg[i]
            self.w[i] -= lr * self.grad_w[i]
            self.b[i] -= lr * self.grad_b[i]
        self.zero_grad()

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"Highway.adam_step: lr 必须是非负数，收到 {lr!r}")
        self._adam_t += 1
        t = self._adam_t
        for i in range(self.d):
            for j in range(self.d):
                gv = self.grad_wg[i][j]
                self.m_wg[i][j] = beta1 * self.m_wg[i][j] + (1 - beta1) * gv
                self.v_wg[i][j] = beta2 * self.v_wg[i][j] + (1 - beta2) * gv * gv
                mh = self.m_wg[i][j] / (1 - beta1 ** t)
                vh = self.v_wg[i][j] / (1 - beta2 ** t)
                self.wg[i][j] -= lr * mh / (math.sqrt(vh) + eps)
            for holder, grad, m, v in ((self.bg, self.grad_bg[i], self.m_bg, self.v_bg),
                                       (self.w, self.grad_w[i], self.m_w, self.v_w),
                                       (self.b, self.grad_b[i], self.m_b, self.v_b)):
                m[i] = beta1 * m[i] + (1 - beta1) * grad
                v[i] = beta2 * v[i] + (1 - beta2) * grad * grad
                mh = m[i] / (1 - beta1 ** t)
                vh = v[i] / (1 - beta2 ** t)
                holder[i] -= lr * mh / (math.sqrt(vh) + eps)
        self.zero_grad()


def _count_floats(obj):
    """递归统计嵌套列表里 float/int 的个数（用于 param_count）"""
    if isinstance(obj, (int, float)) and not isinstance(obj, bool):
        return 1
    if isinstance(obj, (list, tuple)):
        return sum(_count_floats(v) for v in obj)
    return 0


class PatchEmbedding:
    """把 `(C,H,W)` 图像切成不重叠的 patch，每个 patch 映射成一个 `d_model` 维 token

    本质就是 `Conv2d(in_channels, d_model, kernel_size=patch_size,
    stride=patch_size)`，只是把输出张量 `(d_model, gh, gw)` 按**行优先**摊平成
   长度 `gh*gw` 的 token 列表 —— 这是 ViT 的第一步。
    """

    def __init__(self, in_channels: int, patch_size: int, d_model: int):
        if isinstance(in_channels, bool) or not isinstance(in_channels, int):
            raise TypeError(
                f"PatchEmbedding: in_channels 必须是 int，收到 {type(in_channels).__name__}")
        if in_channels < 1:
            raise ValueError(f"PatchEmbedding: in_channels 必须 >= 1，收到 {in_channels!r}")
        if isinstance(patch_size, bool) or not isinstance(patch_size, int):
            raise TypeError(
                f"PatchEmbedding: patch_size 必须是 int，收到 {type(patch_size).__name__}")
        if patch_size < 1:
            raise ValueError(f"PatchEmbedding: patch_size 必须 >= 1，收到 {patch_size!r}")
        if isinstance(d_model, bool) or not isinstance(d_model, int):
            raise TypeError(
                f"PatchEmbedding: d_model 必须是 int，收到 {type(d_model).__name__}")
        if d_model < 1:
            raise ValueError(f"PatchEmbedding: d_model 必须 >= 1，收到 {d_model!r}")
        self.in_channels = in_channels
        self.patch_size = patch_size
        self.d_model = d_model
        self.conv = Conv2d(in_channels, d_model, patch_size, stride=patch_size)
        self.grid = None
        self.training = True

    def forward(self, x):
        """`(C,H,W)` → `list[list[float]]`（每个 token 长度 d_model）"""
        if not x or not x[0] or not x[0][0]:
            raise ValueError("PatchEmbedding.forward: 输入不能为空")
        c, h, w = len(x), len(x[0]), len(x[0][0])
        if c != self.in_channels:
            raise ValueError(
                f"PatchEmbedding.forward: 输入通道数 {c} 与 in_channels="
                f"{self.in_channels} 不符")
        p = self.patch_size
        if h % p != 0 or w % p != 0:
            raise ValueError(
                f"PatchEmbedding.forward: 图像尺寸 {(h, w)} 必须能被 patch_size="
                f"{p} 整除")
        out = self.conv.forward(x)          # (d_model, gh, gw)
        gh, gw = len(out[0]), len(out[0][0])
        self.grid = (self.d_model, gh, gw)
        return [[out[c][i][j] for c in range(self.d_model)]
                for i in range(gh) for j in range(gw)]

    def backward(self, dtokens):
        """`list[token 梯度]` → `(C,H,W)` 的输入梯度；卷积的 `grad_w`/`grad_b` 就地填充"""
        if self.grid is None:
            raise RuntimeError("PatchEmbedding.backward: 必须先调用 forward()")
        dm, gh, gw = self.grid
        if len(dtokens) != gh * gw:
            raise ValueError(
                f"PatchEmbedding.backward: token 数 {len(dtokens)} 与 forward 的 "
                f"{gh * gw} 不一致")
        grid = [[[0.0] * gw for _ in range(gh)] for _ in range(dm)]
        for i in range(gh):
            for j in range(gw):
                tok = dtokens[i * gw + j]
                if len(tok) != dm:
                    raise ValueError(
                        f"PatchEmbedding.backward: token 梯度长度 {len(tok)} 与 "
                        f"d_model={dm} 不一致")
                for c in range(dm):
                    grid[c][i][j] = tok[c]
        return self.conv.backward(grid)

    def zero_grad(self):
        self.conv.zero_grad()

    def param_count(self):
        return _conv_param_count(self.conv)

    def train(self):
        self.training = True
        return self

    def eval(self):
        self.training = False
        return self

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"PatchEmbedding.sgd_step: lr 必须是非负数，收到 {lr!r}")
        _conv_sgd(self.conv, float(lr))

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"PatchEmbedding.adam_step: lr 必须是非负数，收到 {lr!r}")
        _conv_adam(self.conv, float(lr), beta1, beta2, eps)


class AttentionPooling:
    """注意力池化：可学习查询向量给每个 token 打分，softmax 后加权求和

    `score_t = q·x_t / sqrt(d)`、`w = softmax(score)`、`out = Σ_t w_t x_t`。
    和 `GlobalAvgPool2d` 的区别是权重由内容决定，所以模型能学会"只看重要的补丁"。
    """

    def __init__(self, d_model: int):
        if isinstance(d_model, bool) or not isinstance(d_model, int):
            raise TypeError(
                f"AttentionPooling: d_model 必须是 int，收到 {type(d_model).__name__}")
        if d_model < 1:
            raise ValueError(f"AttentionPooling: d_model 必须 >= 1，收到 {d_model!r}")
        self.d = d_model
        rng = random.Random(20240001)
        std = math.sqrt(1.0 / d_model)
        self.q = [rng.gauss(0.0, std) for _ in range(d_model)]
        self.grad_q = [0.0] * d_model
        self.m_q = [0.0] * d_model
        self.v_q = [0.0] * d_model
        self._adam_t = 0
        self.tokens = None
        self.weights = None
        self.training = True

    def _scale(self):
        return 1.0 / math.sqrt(self.d)

    def forward(self, tokens):
        """`list[token]` → 长度 d_model 的向量"""
        if not tokens:
            raise ValueError("AttentionPooling.forward: token 列表不能为空")
        n = len(tokens)
        if len(tokens[0]) != self.d:
            raise ValueError(
                f"AttentionPooling.forward: token 长度 {len(tokens[0])} 与 "
                f"d_model={self.d} 不一致")
        sc = self._scale()
        scores = []
        for t in tokens:
            if len(t) != self.d:
                raise ValueError(
                    f"AttentionPooling.forward: token 长度 {len(t)} 与 "
                    f"d_model={self.d} 不一致")
            scores.append(sum(self.q[i] * t[i] for i in range(self.d)) * sc)
        m = max(scores)
        ex = [math.exp(v - m) for v in scores]
        z = sum(ex)
        w = [v / z for v in ex]
        out = [0.0] * self.d
        for t_i in range(n):
            wt = w[t_i]
            tok = tokens[t_i]
            for j in range(self.d):
                out[j] += wt * tok[j]
        self.tokens = tokens
        self.weights = w
        return out

    def backward(self, dout):
        if self.tokens is None:
            raise RuntimeError("AttentionPooling.backward: 必须先调用 forward()")
        if len(dout) != self.d:
            raise ValueError(
                f"AttentionPooling.backward: dout 长度 {len(dout)} 与 "
                f"d_model={self.d} 不一致")
        n = len(self.tokens)
        sc = self._scale()
        w = self.weights
        dw = [sum(dout[j] * self.tokens[t][j] for j in range(self.d))
              for t in range(n)]
        mean_dw = sum(w[t] * dw[t] for t in range(n))
        dscore = [w[t] * (dw[t] - mean_dw) for t in range(n)]
        self.grad_q = [sc * sum(dscore[t] * self.tokens[t][i] for t in range(n))
                       for i in range(self.d)]
        dx = []
        for t in range(n):
            g = sc * dscore[t]
            dx.append([dout[j] * w[t] + g * self.q[j] for j in range(self.d)])
        return dx

    def zero_grad(self):
        self.grad_q = [0.0] * self.d

    def param_count(self):
        return self.d

    def train(self):
        self.training = True
        return self

    def eval(self):
        self.training = False
        return self

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"AttentionPooling.sgd_step: lr 必须是非负数，收到 {lr!r}")
        _sgd_apply(self.q, self.grad_q, float(lr))

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"AttentionPooling.adam_step: lr 必须是非负数，收到 {lr!r}")
        self._adam_t += 1
        _adam_apply(self.q, self.grad_q, self.m_q, self.v_q, self._adam_t,
                    float(lr), beta1, beta2, eps)


class GeMPooling:
    """广义平均池化（GeM）：`y_c = (mean_{h,w}(x^p))^(1/p)`

    `p=1` 是平均池化、`p→∞` 趋近最大池化，所以一个可调超参就能在两者之间
    连续插值 —— 检索里常用的池化头。要求输入非负（前面接 ReLU 即可）。
    前向与反向都在 log 空间里算，`p` 取到几千也不会溢出。
    """

    def __init__(self, p: float = 3.0):
        if isinstance(p, bool) or not isinstance(p, (int, float)):
            raise TypeError(f"GeMPooling: p 必须是数字，收到 {type(p).__name__}")
        if not math.isfinite(float(p)) or p <= 0:
            raise ValueError(f"GeMPooling: p 必须是正有限数，收到 {p!r}")
        self.p = float(p)
        self.x = None
        self.y = None
        self.training = True

    def forward(self, x):
        """`(C,H,W)` → `(C,)`"""
        if not x or not x[0] or not x[0][0]:
            raise ValueError("GeMPooling.forward: 输入不能为空")
        c, h, w = len(x), len(x[0]), len(x[0][0])
        n = h * w
        out = []
        for ch in range(c):
            row = x[ch]
            # log 空间：先减最大值再 exp，p 很大（如 2000）也不会溢出
            top = 0.0
            for i in range(h):
                for j in range(w):
                    v = row[i][j]
                    if v < 0:
                        raise ValueError(
                            "GeMPooling.forward: 输入必须非负（x^p 无意义），"
                            f"通道 {ch} 位置 {(i, j)} 是 {v!r}")
                    if v > top:
                        top = v
            if top == 0.0:
                out.append(0.0)
                continue
            log_top = math.log(top)
            acc = 0.0
            for i in range(h):
                for j in range(w):
                    v = row[i][j]
                    if v > 0.0:
                        acc += math.exp(self.p * (math.log(v) - log_top))
            out.append(math.exp(log_top + math.log(acc / n) / self.p))
        self.x = x
        self.y = out
        return out

    def backward(self, dout):
        if self.x is None:
            raise RuntimeError("GeMPooling.backward: 必须先调用 forward()")
        c, h, w = len(self.x), len(self.x[0]), len(self.x[0][0])
        if len(dout) != c:
            raise ValueError(
                f"GeMPooling.backward: dout 长度 {len(dout)} 与通道数 {c} 不一致")
        n = h * w
        p = self.p
        dx = [[[0.0] * w for _ in range(h)] for _ in range(c)]
        for ch in range(c):
            y = self.y[ch]
            g = dout[ch]
            if y == 0.0:
                continue
            log_y = math.log(y)
            row = self.x[ch]
            for i in range(h):
                for j in range(w):
                    v = row[i][j]
                    if v <= 0.0:
                        dx[ch][i][j] = 0.0
                        continue
                    # (y^(1-p)·v^(p-1))/n = exp((p-1)(log v - log y))/n；v<=y 故该指数 <=0
                    dx[ch][i][j] = (g / n) * math.exp(
                        (p - 1.0) * (math.log(v) - log_y))
        return dx

    def zero_grad(self):
        pass

    def param_count(self):
        return 0

    def train(self):
        self.training = True
        return self

    def eval(self):
        self.training = False
        return self

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"GeMPooling.sgd_step: lr 必须是非负数，收到 {lr!r}")

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"GeMPooling.adam_step: lr 必须是非负数，收到 {lr!r}")


class ViT:
    """视觉 Transformer（编码器式）：patch 化 → CLS + 位置编码 → N 层编码器 → 分类头

    结构：
    `PatchEmbedding` 切出 `n` 个 patch token → 前面拼一个可学习的 `CLS` → 加可学习
    位置编码 → `TransformerEncoder`（非因果）→ 取 `CLS` 那一位 → `LayerNorm` →
    线性分类头（输出 logits，配 `cross_entropy` 用）。

    `backward` 接收 logits 的梯度、返回 `(C,H,W)` 的输入梯度，所有内部梯度就地填好。
    **梯度是累加的**（与 `TransformerEncoder` 等组件一致）：一个 batch 里连续调用多次
    `backward` 会累加，更新前先 `zero_grad()`，或按 batch 大小自行缩放学习率。
    参数更新走 `sgd_step()`（Transformer 系列在本项目里只提供 SGD；需要 Adam 时由
    外部循环自己组合 `Model` 之外的部分）。
    """

    def __init__(self, in_channels: int = 3, image_size=8, patch_size: int = 4,
                 d_model: int = 16, num_heads: int = 4, d_ff: int = 32,
                 num_layers: int = 2, num_classes: int = 10, dropout: float = 0.0):
        if isinstance(image_size, int) and not isinstance(image_size, bool):
            image_size = (image_size, image_size)
        if not isinstance(image_size, (tuple, list)) or len(image_size) != 2:
            raise TypeError(
                f"ViT: image_size 必须是 int 或 (H, W)，收到 {image_size!r}")
        img_h, img_w = int(image_size[0]), int(image_size[1])
        if img_h < 1 or img_w < 1:
            raise ValueError(f"ViT: image_size 必须为正，收到 {image_size!r}")
        if img_h % patch_size != 0 or img_w % patch_size != 0:
            raise ValueError(
                f"ViT: image_size={(img_h, img_w)} 必须能被 patch_size="
                f"{patch_size} 整除")
        for name, val in (("in_channels", in_channels), ("d_model", d_model),
                          ("num_heads", num_heads), ("num_layers", num_layers),
                          ("num_classes", num_classes)):
            if isinstance(val, bool) or not isinstance(val, int) or val < 1:
                raise ValueError(f"ViT: {name} 必须是 >=1 的整数，收到 {val!r}")
        if d_model % num_heads != 0:
            raise ValueError(
                f"ViT: d_model={d_model} 必须能被 num_heads={num_heads} 整除")
        self.in_channels = in_channels
        self.image_size = (img_h, img_w)
        self.patch_size = patch_size
        self.d_model = d_model
        self.num_classes = num_classes
        self.grid = (img_h // patch_size, img_w // patch_size)
        self.num_patches = self.grid[0] * self.grid[1]

        self.patch_embed = PatchEmbedding(in_channels, patch_size, d_model)
        rng = random.Random(20240501)
        std = math.sqrt(1.0 / d_model)
        self.cls = [rng.gauss(0.0, std) for _ in range(d_model)]
        self.pos = [[rng.gauss(0.0, std) for _ in range(d_model)]
                    for _ in range(self.num_patches + 1)]
        self.encoder = TransformerEncoder(d_model, num_heads, d_ff,
                                          num_layers=num_layers, dropout=dropout)
        self.norm = LayerNorm(d_model)
        self.head = Layer(d_model, num_classes, "linear")
        self.head.grad_w = [[0.0] * d_model for _ in range(num_classes)]
        self.head.grad_b = [0.0] * num_classes

        self.grad_cls = [0.0] * d_model
        self.grad_pos = [[0.0] * d_model for _ in range(self.num_patches + 1)]
        self.norm_grads = ([0.0] * d_model, [0.0] * d_model)
        self.seq = None
        self.logits = None
        self.training = True

    def forward(self, x):
        """`(C,H,W)` → 长度 num_classes 的 logits"""
        c = len(x)
        if c != self.in_channels:
            raise ValueError(
                f"ViT.forward: 输入通道数 {c} 与 in_channels={self.in_channels} 不符")
        if (len(x[0]), len(x[0][0])) != self.image_size:
            raise ValueError(
                f"ViT.forward: 输入尺寸 {(len(x[0]), len(x[0][0]))} 与 "
                f"image_size={self.image_size} 不符")
        patches = self.patch_embed.forward(x)
        if len(patches) != self.num_patches:
            raise ValueError(
                f"ViT.forward: patch 数 {len(patches)} 与预期 {self.num_patches} 不符")
        seq = [list(self.cls)] + [list(t) for t in patches]
        for i in range(len(seq)):
            row = seq[i]
            pos_i = self.pos[i]
            for j in range(self.d_model):
                row[j] += pos_i[j]
        self.seq = seq
        out = self.encoder.forward(seq)
        h = self.norm.forward(out[0])
        self.logits = self.head.forward(h)
        return self.logits

    def backward(self, dlogits):
        if self.seq is None:
            raise RuntimeError("ViT.backward: 必须先调用 forward()")
        if len(dlogits) != self.num_classes:
            raise ValueError(
                f"ViT.backward: dlogits 长度 {len(dlogits)} 与 num_classes="
                f"{self.num_classes} 不一致")
        gw, gb, dh = self.head.backward(dlogits)
        for i in range(self.num_classes):
            row = self.head.grad_w[i]
            grow = gw[i]
            for j in range(self.d_model):
                row[j] += grow[j]
            self.head.grad_b[i] += gb[i]
        gg, gbeta, dcls = self.norm.backward(dh)
        for j in range(self.d_model):
            self.norm_grads[0][j] += gg[j]
            self.norm_grads[1][j] += gbeta[j]
        dseq = [[0.0] * self.d_model for _ in range(len(self.seq))]
        dseq[0] = dcls
        dseq = self.encoder.backward(dseq)
        for j in range(self.d_model):
            self.grad_cls[j] += dseq[0][j]
        for t in range(self.num_patches + 1):
            row = self.grad_pos[t]
            grow = dseq[t]
            for j in range(self.d_model):
                row[j] += grow[j]
        return self.patch_embed.backward(dseq[1:])

    def zero_grad(self):
        self.patch_embed.zero_grad()
        self.encoder.zero_grad()
        self.head.grad_w = [[0.0] * self.d_model for _ in range(self.num_classes)]
        self.head.grad_b = [0.0] * self.num_classes
        self.norm_grads = ([0.0] * self.d_model, [0.0] * self.d_model)
        self.grad_cls = [0.0] * self.d_model
        self.grad_pos = [[0.0] * self.d_model for _ in range(self.num_patches + 1)]

    def _layer_params(self):
        """[(名字, 参数张量)]，用于统计与 SGD 更新"""
        out = [("head.w", self.head.weights), ("head.b", self.head.biases),
               ("norm.gamma", self.norm.gamma), ("norm.beta", self.norm.beta),
               ("cls", self.cls), ("pos", self.pos)]
        for li, layer in enumerate(self.encoder.layers):
            mha = layer.self_attn
            out += [(f"L{li}.W_q", mha.W_q), (f"L{li}.b_q", mha.b_q),
                    (f"L{li}.W_k", mha.W_k), (f"L{li}.b_k", mha.b_k),
                    (f"L{li}.W_v", mha.W_v), (f"L{li}.b_v", mha.b_v),
                    (f"L{li}.W_o", mha.W_o), (f"L{li}.b_o", mha.b_o),
                    (f"L{li}.W1", layer.ffn.W1), (f"L{li}.b1", layer.ffn.b1),
                    (f"L{li}.W2", layer.ffn.W2), (f"L{li}.b2", layer.ffn.b2),
                    (f"L{li}.ln1.gamma", layer.ln1.gamma),
                    (f"L{li}.ln1.beta", layer.ln1.beta),
                    (f"L{li}.ln2.gamma", layer.ln2.gamma),
                    (f"L{li}.ln2.beta", layer.ln2.beta)]
        return out

    def param_count(self):
        total = self.patch_embed.param_count()
        for _name, tensor in self._layer_params():
            total += _count_floats(tensor)
        return total

    def train(self):
        self.training = True
        self.encoder.train()
        return self

    def eval(self):
        self.training = False
        self.encoder.eval()
        return self

    def sgd_step(self, lr):
        """对编码器、patch 卷积、位置编码、CLS 与分类头做一次 SGD"""
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"ViT.sgd_step: lr 必须是非负数，收到 {lr!r}")
        lr = float(lr)
        self.patch_embed.sgd_step(lr)
        self.encoder.sgd_step(lr)
        _dense_apply_sgd(self.head, (self.head.grad_w, self.head.grad_b), lr)
        _norm_apply_sgd(self.norm, self.norm_grads, lr)
        for i in range(self.d_model):
            self.cls[i] -= lr * self.grad_cls[i]
        for t in range(self.num_patches + 1):
            row = self.pos[t]
            grow = self.grad_pos[t]
            for j in range(self.d_model):
                row[j] -= lr * grow[j]

    def fit(self, images, labels, epochs=30, lr=0.01, shuffle=True, seed=None,
            verbose=False):
        """微调入口：在（可选的）预训练权重上做图像分类训练。

        逐样本 forward → cross_entropy → backward → SGD；返回每个 epoch 的
        平均 loss（列表）。`shuffle=True` 时每个 epoch 打乱样本顺序。
        """
        if not isinstance(images, (list, tuple)) or not images:
            raise ValueError("ViT.fit: images 必须是非空列表")
        if not isinstance(labels, (list, tuple)) or len(labels) != len(images):
            raise ValueError(
                f"ViT.fit: labels 长度 {len(labels)} 与 images 长度 {len(images)} 不一致")
        if isinstance(epochs, bool) or not isinstance(epochs, int) or epochs < 1:
            raise ValueError(f"ViT.fit: epochs 必须是正整数，收到 {epochs!r}")
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"ViT.fit: lr 必须是非负数，收到 {lr!r}")
        for y in labels:
            if isinstance(y, bool) or not isinstance(y, int) \
                    or not 0 <= y < self.num_classes:
                raise ValueError(
                    f"ViT.fit: 标签必须是 [0, {self.num_classes}) 内的整数，收到 {y!r}")
        rng = random.Random(seed)
        order = list(range(len(images)))
        losses = []
        for epoch in range(epochs):
            if shuffle:
                rng.shuffle(order)
            total = 0.0
            for i in order:
                self.zero_grad()
                logits = self.forward(images[i])
                loss, grads = cross_entropy_loss(logits, int(labels[i]))
                total += loss
                self.backward(grads)
                self.sgd_step(lr)
            losses.append(total / len(images))
            if verbose:
                print(f"  [ViT 微调] epoch {epoch + 1}/{epochs} "
                      f"loss {losses[-1]:.6f}")
        return losses

    def pretrain(self, images, epochs=30, lr=0.01, mask_ratio=0.5, seed=None,
                 verbose=False):
        """预训练入口：简化的 MAE 式掩码 patch 重建。

        每张图随机遮住 `mask_ratio` 比例的 patch，编码器只看 CLS + 可见 patch；
        重建头（首次调用时创建）以 CLS 表示 + 被遮 patch 的位置编码为输入，
        回归被遮 patch 的像素。只训练编码器与重建头，不更新 patch 卷积 / 分类头。
        返回每个 epoch 的平均重建 loss（MSE）。
        """
        if not isinstance(images, (list, tuple)) or not images:
            raise ValueError("ViT.pretrain: images 必须是非空列表")
        if isinstance(epochs, bool) or not isinstance(epochs, int) or epochs < 1:
            raise ValueError(
                f"ViT.pretrain: epochs 必须是正整数，收到 {epochs!r}")
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"ViT.pretrain: lr 必须是非负数，收到 {lr!r}")
        if isinstance(mask_ratio, bool) \
                or not isinstance(mask_ratio, (int, float)) \
                or not 0.0 < float(mask_ratio) < 1.0:
            raise ValueError(
                f"ViT.pretrain: mask_ratio 必须在 (0,1) 之间，收到 {mask_ratio!r}")
        if self.num_patches < 2:
            raise ValueError("ViT.pretrain: 至少需要 2 个 patch 才能做掩码重建")
        ps = self.patch_size
        c = self.in_channels
        patch_dim = c * ps * ps
        if not hasattr(self, "_mae_dec1"):
            self._mae_dec1 = Layer(self.d_model, 2 * self.d_model, "gelu")
            self._mae_dec2 = Layer(2 * self.d_model, patch_dim, "linear")
        dec1 = self._mae_dec1
        dec2 = self._mae_dec2
        rng = random.Random(seed)
        n_mask = max(1, int(round(self.num_patches * float(mask_ratio))))
        n_mask = min(n_mask, self.num_patches - 1)
        losses = []
        for epoch in range(epochs):
            total = 0.0
            for img in images:
                targets = []
                for r in range(self.grid[0]):
                    for cc in range(self.grid[1]):
                        vec = []
                        for ch in range(c):
                            for a in range(ps):
                                vec.extend(
                                    img[ch][r * ps + a][cc * ps:(cc + 1) * ps])
                        targets.append(vec)
                patches = self.patch_embed.forward(img)
                order = list(range(self.num_patches))
                rng.shuffle(order)
                masked = sorted(order[:n_mask])
                visible = sorted(order[n_mask:])
                seq = [list(self.cls)]
                for i in visible:
                    seq.append([patches[i][j] + self.pos[i + 1][j]
                                for j in range(self.d_model)])
                self.zero_grad()
                enc = self.encoder.forward(seq)
                latent = enc[0]
                dec_inputs = []
                for t in masked:
                    dec_inputs.append(
                        [latent[j] + self.pos[t + 1][j]
                         for j in range(self.d_model)])
                h1, cache1 = _dense_rows_forward(dec1, dec_inputs)
                preds, cache2 = _dense_rows_forward(dec2, h1)
                d_preds = []
                loss = 0.0
                for idx, t in enumerate(masked):
                    tgt = targets[t]
                    diff = [preds[idx][j] - tgt[j] for j in range(patch_dim)]
                    loss += sum(v * v for v in diff)
                    d_preds.append(
                        [2.0 * diff[j] / (patch_dim * n_mask)
                         for j in range(patch_dim)])
                loss /= (patch_dim * n_mask)
                gw2, gb2, d_h1 = _dense_rows_backward(dec2, cache2, d_preds)
                gw1, gb1, d_latent = _dense_rows_backward(dec1, cache1, d_h1)
                d_latent_total = [sum(d_latent[k][j] for k in range(n_mask))
                                  for j in range(self.d_model)]
                dseq = [[0.0] * self.d_model for _ in range(len(seq))]
                dseq[0] = d_latent_total
                self.encoder.backward(dseq)
                self.encoder.sgd_step(lr)
                _dense_apply_sgd(dec1, (gw1, gb1), lr)
                _dense_apply_sgd(dec2, (gw2, gb2), lr)
                total += loss
            losses.append(total / len(images))
            if verbose:
                print(f"  [ViT 预训练] epoch {epoch + 1}/{epochs} "
                      f"recon {losses[-1]:.6f}")
        return losses


class UNet:
    """U-Net（简化版，2 级下采样）：编码 → 瓶颈 → 解码 + 跳跃连接

    结构（输入 `(Cin,H,W)`，要求 `H`、`W` 能被 4 整除）：

        e0: Conv(Cin→c0, 3x3)  → relu       h0: (c0, H, W)
        p0: MaxPool2d(2)                    (c0, H/2, W/2)
        e1: Conv(c0→2c0, 3x3)  → relu       h1: (2c0, H/2, W/2)
        p1: MaxPool2d(2)                    (2c0, H/4, W/4)
        bot: Conv(2c0→4c0, 3x3) → relu      (4c0, H/4, W/4)
        up1: ConvTranspose2d(4c0→2c0, 2, s=2) → 与 h1 通道拼接 → Conv(4c0→2c0,3x3)→relu
        up0: ConvTranspose2d(2c0→c0, 2, s=2) → 与 h0 通道拼接 → Conv(2c0→c0,3x3)→relu
        out: Conv(c0→num_classes, 1x1)

    `use_bn=True` 时每个卷积后接 `BatchNorm2d`（训练/推理模式由 `train()`/`eval()` 控制）。
    返回 `(num_classes, H, W)` 的 logits；`backward` 返回输入梯度，内部梯度就地累加。
    """

    def __init__(self, in_channels: int = 1, num_classes: int = 2,
                 base_channels: int = 4, use_bn: bool = False):
        for name, val in (("in_channels", in_channels),
                          ("num_classes", num_classes),
                          ("base_channels", base_channels)):
            if isinstance(val, bool) or not isinstance(val, int) or val < 1:
                raise ValueError(f"UNet: {name} 必须是 >=1 的整数，收到 {val!r}")
        self.in_channels = in_channels
        self.num_classes = num_classes
        self.base_channels = base_channels
        self.use_bn = bool(use_bn)

        c0 = base_channels
        c1 = base_channels * 2
        c2 = base_channels * 4
        self.e0 = Conv2d(in_channels, c0, 3, padding=1)
        self.e1 = Conv2d(c0, c1, 3, padding=1)
        self.bot = Conv2d(c1, c2, 3, padding=1)
        self.d1 = Conv2d(c2, c1, 3, padding=1)
        self.d0 = Conv2d(c1, c0, 3, padding=1)
        self.out = Conv2d(c0, num_classes, 1)
        self.up1 = ConvTranspose2d(c2, c1, 2, stride=2)
        self.up0 = ConvTranspose2d(c1, c0, 2, stride=2)
        self.pool0 = MaxPool2d(2)
        self.pool1 = MaxPool2d(2)

        self._convs = [self.e0, self.e1, self.bot, self.d1, self.d0, self.out]
        self._ups = [self.up1, self.up0]
        self._pools = [self.pool0, self.pool1]
        self.bns = []
        if self.use_bn:
            self.bn0 = BatchNorm2d(c0)
            self.bn1 = BatchNorm2d(c1)
            self.bn2 = BatchNorm2d(c2)
            self.bn3 = BatchNorm2d(c1)
            self.bn4 = BatchNorm2d(c0)
            self.bns = [self.bn0, self.bn1, self.bn2, self.bn3, self.bn4]
        self.bn_grads = {}
        self._cache = None
        self.training = True

    def train(self):
        self.training = True
        for bn in self.bns:
            bn.train()
        return self

    def eval(self):
        self.training = False
        for bn in self.bns:
            bn.eval()
        return self

    def _norm(self, bn, h, backward_grad=None):
        """BN + relu 的 forward/backward 小工具（bn 为 None 时只做 relu）"""
        if bn is None:
            if backward_grad is None:
                return [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in h]
            raise RuntimeError("UNet: 内部错误（bn 为 None 时不应走反向）")
        return None

    def forward(self, x):
        c = len(x)
        if c != self.in_channels:
            raise ValueError(
                f"UNet.forward: 输入通道数 {c} 与 in_channels={self.in_channels} 不符")
        h, w = len(x[0]), len(x[0][0])
        if h % 4 != 0 or w % 4 != 0:
            raise ValueError(
                f"UNet.forward: 输入尺寸 {(h, w)} 必须能被 4 整除")
        z0 = self.e0.forward(x)
        if self.use_bn:
            z0 = self.bn0.forward(z0)
        h0 = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in z0]

        p0 = self.pool0.forward(h0)
        z1 = self.e1.forward(p0)
        if self.use_bn:
            z1 = self.bn1.forward(z1)
        h1 = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in z1]

        p1 = self.pool1.forward(h1)
        zb = self.bot.forward(p1)
        if self.use_bn:
            zb = self.bn2.forward(zb)
        hb = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in zb]

        u1 = self.up1.forward(hb)
        cat1 = [list(ch) for ch in h1] + [list(ch) for ch in u1]
        z2 = self.d1.forward(cat1)
        if self.use_bn:
            z2 = self.bn3.forward(z2)
        hd1 = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in z2]

        u0 = self.up0.forward(hd1)
        cat0 = [list(ch) for ch in h0] + [list(ch) for ch in u0]
        z3 = self.d0.forward(cat0)
        if self.use_bn:
            z3 = self.bn4.forward(z3)
        hd0 = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in z3]

        logits = self.out.forward(hd0)
        self._cache = (z0, h0, p0, z1, h1, p1, zb, hb, u1, cat1, z2, hd1,
                       u0, cat0, z3, hd0)
        return logits

    @staticmethod
    def _relu_back(dv, z):
        return [[[dv[c][i][j] if z[c][i][j] > 0.0 else 0.0
                  for j in range(len(z[0][0]))]
                 for i in range(len(z[0]))] for c in range(len(z))]

    def backward(self, dlogits):
        if self._cache is None:
            raise RuntimeError("UNet.backward: 必须先调用 forward()")
        (z0, h0, p0, z1, h1, p1, zb, hb, u1, cat1, z2, hd1,
         u0, cat0, z3, hd0) = self._cache
        n_out = len(dlogits)
        if n_out != self.num_classes:
            raise ValueError(
                f"UNet.backward: dlogits 通道数 {n_out} 与 num_classes="
                f"{self.num_classes} 不符")
        c0 = self.base_channels
        c1 = c0 * 2

        dhd0 = self.out.backward(dlogits)
        dz3 = self._relu_back(dhd0, z3)
        if self.use_bn:
            dz3, _g, _b = self.bn4.backward(dz3)
            self.bn_grads[4] = (_g, _b)
        dcat0 = self.d0.backward(dz3)
        dh0 = dcat0[:c0]
        du0 = dcat0[c0:]
        dhd1 = self.up0.backward(du0)

        dz2 = self._relu_back(dhd1, z2)
        if self.use_bn:
            dz2, _g, _b = self.bn3.backward(dz2)
            self.bn_grads[3] = (_g, _b)
        dcat1 = self.d1.backward(dz2)
        dh1 = dcat1[:c1]
        du1 = dcat1[c1:]
        dhb = self.up1.backward(du1)

        dzb = self._relu_back(dhb, zb)
        if self.use_bn:
            dzb, _g, _b = self.bn2.backward(dzb)
            self.bn_grads[2] = (_g, _b)
        dp1 = self.bot.backward(dzb)
        dh1 = [[[dh1[c][i][j] + g for j, g in enumerate(row)]
                for i, row in enumerate(ch)] for c, ch in enumerate(self.pool1.backward(dp1))]

        dz1 = self._relu_back(dh1, z1)
        if self.use_bn:
            dz1, _g, _b = self.bn1.backward(dz1)
            self.bn_grads[1] = (_g, _b)
        dp0 = self.e1.backward(dz1)
        dp0u = self.pool0.backward(dp0)
        dh0 = [[[dh0[c][i][j] + g for j, g in enumerate(row)]
                for i, row in enumerate(ch)] for c, ch in enumerate(dp0u)]

        dz0 = self._relu_back(dh0, z0)
        if self.use_bn:
            dz0, _g, _b = self.bn0.backward(dz0)
            self.bn_grads[0] = (_g, _b)
        return self.e0.backward(dz0)

    def zero_grad(self):
        for layer in self._convs + self._ups:
            layer.zero_grad()
        self.bn_grads = {}

    def param_count(self):
        total = sum(_conv_param_count(layer) for layer in self._convs + self._ups)
        for bn in self.bns:
            total += 2 * len(bn.gamma)
        return total

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"UNet.sgd_step: lr 必须是非负数，收到 {lr!r}")
        for layer in self._convs:
            _conv_sgd(layer, float(lr))
        for layer in self._ups:
            layer.sgd_step(float(lr))
        for i, bn in enumerate(self.bns):
            if i in self.bn_grads:
                _norm_apply_sgd(bn, self.bn_grads[i], float(lr))

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"UNet.adam_step: lr 必须是非负数，收到 {lr!r}")
        for layer in self._convs:
            _conv_adam(layer, float(lr), beta1, beta2, eps)
        for layer in self._ups:
            layer.adam_step(float(lr), beta1, beta2, eps)
        for i, bn in enumerate(self.bns):
            if i in self.bn_grads:
                _norm_apply_adam(bn, self.bn_grads[i], float(lr), beta1, beta2, eps)


def _up2(x):
    """最近邻 2× 上采样：`(C,h,w) -> (C,2h,2w)`"""
    out = []
    for ch in x:
        rows = []
        for row in ch:
            new = []
            for v in row:
                new.append(v)
                new.append(v)
            rows.append(new)
            rows.append(list(new))
        out.append(rows)
    return out


def _up2_back(d, h, w):
    """`_up2` 的反向：把 `(C,2h,2w)` 的梯度按 2x2 块求和回 `(C,h,w)`"""
    out = []
    for ch in d:
        rows = []
        for i in range(h):
            row = []
            for j in range(w):
                row.append(ch[2 * i][2 * j] + ch[2 * i][2 * j + 1]
                           + ch[2 * i + 1][2 * j] + ch[2 * i + 1][2 * j + 1])
            rows.append(row)
        out.append(rows)
    return out


def _unpool2(x, pool, H, W):
    """按 `MaxPool2d` 记录的索引把 `(C,ho,wo)` 填回 `(C,H,W)`

    `MaxPool2d.mask[c][oh][ow]` 存的是**窗口内相对位置** `(kh, kw)`，
    绝对位置要按 `oh * stride + kh` 换算；非选中位置保持 0。
    """
    C = len(x)
    ho, wo = len(x[0]), len(x[0][0])
    out = [[[0.0] * W for _ in range(H)] for _ in range(C)]
    for c in range(C):
        for i in range(ho):
            for j in range(wo):
                kh, kw = pool.mask[c][i][j]
                ih = i * pool.sh + kh
                iw = j * pool.sw + kw
                out[c][ih][iw] = x[c][i][j]
    return out


def _unpool2_back(d, pool):
    """`_unpool2` 的反向：只把梯度收回各窗口被选中的位置"""
    C = len(d)
    ho, wo = len(pool.mask[0]), len(pool.mask[0][0])
    out = [[[0.0] * wo for _ in range(ho)] for _ in range(C)]
    for c in range(C):
        for i in range(ho):
            for j in range(wo):
                kh, kw = pool.mask[c][i][j]
                ih = i * pool.sh + kh
                iw = j * pool.sw + kw
                out[c][i][j] = d[c][ih][iw]
    return out


class FPN:
    """特征金字塔（top-down 路径 + 横向连接）

    输入是从细到粗的特征图列表 `[F0, F1, ..., F{L-1}]`（空间尺寸逐级减半，通道数任意）。
    每个 `Fi` 先过 1x1 横向卷积压到 `out_channels`，再从最粗一级往上做：
    `P_i = lateral_i(F_i) + upsample2x(P_{i+1})`，最后每级过 3x3 平滑卷积
    （`smooth=False` 可关掉）。输出与输入等长的特征图列表，尺寸与输入一致。

    要求相邻特征的尺寸严格是 2 倍关系，否则上采样后无法相加。
    """

    def __init__(self, in_channels_list, out_channels: int = 8, smooth: bool = True):
        if not isinstance(in_channels_list, (list, tuple)) or len(in_channels_list) < 2:
            raise TypeError(
                f"FPN: in_channels_list 必须是长度 >=2 的列表，收到 {in_channels_list!r}")
        chans = []
        for c in in_channels_list:
            if isinstance(c, bool) or not isinstance(c, int) or c < 1:
                raise ValueError(f"FPN: 输入通道数必须是 >=1 的整数，收到 {c!r}")
            chans.append(c)
        if isinstance(out_channels, bool) or not isinstance(out_channels, int) or out_channels < 1:
            raise ValueError(
                f"FPN: out_channels 必须是 >=1 的整数，收到 {out_channels!r}")
        self.in_channels_list = chans
        self.out_channels = out_channels
        self.num_levels = len(chans)
        self.smooth_enabled = bool(smooth)
        self.lateral = [Conv2d(c, out_channels, 1) for c in chans]
        self.smooth = ([Conv2d(out_channels, out_channels, 3, padding=1)
                        for _ in range(self.num_levels)]
                       if self.smooth_enabled else [])
        self._cache = None

    def train(self):
        return self

    def eval(self):
        return self

    def forward(self, feats):
        n = self.num_levels
        if not isinstance(feats, (list, tuple)) or len(feats) != n:
            raise ValueError(
                f"FPN.forward: 需要 {n} 级特征，收到 "
                f"{len(feats) if isinstance(feats, (list, tuple)) else type(feats).__name__}")
        shapes = []
        for i, f in enumerate(feats):
            if len(f) != self.in_channels_list[i]:
                raise ValueError(
                    f"FPN.forward: 第 {i} 级通道数 {len(f)} 与 "
                    f"in_channels_list[{i}]={self.in_channels_list[i]} 不符")
            shapes.append((len(f[0]), len(f[0][0])))
        for i in range(n - 1):
            hi, wi = shapes[i]
            hj, wj = shapes[i + 1]
            if hi != 2 * hj or wi != 2 * wj:
                raise ValueError(
                    f"FPN.forward: 第 {i} 级尺寸 {(hi, wi)} 必须是第 {i + 1} 级 "
                    f"{(hj, wj)} 的 2 倍")

        laterals = [self.lateral[i].forward(feats[i]) for i in range(n)]
        merged = [None] * n
        merged[n - 1] = laterals[n - 1]
        for i in range(n - 2, -1, -1):
            up = _up2(merged[i + 1])
            hi, wi = shapes[i]
            if (len(up[0]), len(up[0][0])) != (hi, wi):
                raise ValueError(
                    f"FPN.forward: 第 {i + 1} 级上采样到 {(len(up[0]), len(up[0][0]))} "
                    f"与第 {i} 级 {(hi, wi)} 不一致")
            base = laterals[i]
            merged[i] = [[[base[c][a][b] + up[c][a][b] for b in range(wi)]
                          for a in range(hi)] for c in range(self.out_channels)]

        outs = ([self.smooth[i].forward(merged[i]) for i in range(n)]
                if self.smooth_enabled else merged)
        self._cache = (shapes, laterals, merged)
        return outs

    def backward(self, douts):
        if self._cache is None:
            raise RuntimeError("FPN.backward: 必须先调用 forward()")
        shapes, laterals, merged = self._cache
        n = self.num_levels
        if not isinstance(douts, (list, tuple)) or len(douts) != n:
            raise ValueError(f"FPN.backward: 需要 {n} 级梯度，收到 {len(douts)}")

        if self.smooth_enabled:
            dmerged = [self.smooth[i].backward(douts[i]) for i in range(n)]
        else:
            dmerged = [douts[i] for i in range(n)]

        acc = [None] * n
        dxs = [None] * n
        for i in range(n):
            g = dmerged[i]
            if acc[i] is not None:
                rows = len(g[0])
                cols = len(g[0][0])
                g = [[[g[c][a][b] + acc[i][c][a][b] for b in range(cols)]
                      for a in range(rows)] for c in range(len(g))]
            dxs[i] = self.lateral[i].backward(g)
            if i + 1 < n:
                hi, wi = shapes[i + 1]
                dup = _up2_back(g, hi, wi)
                if acc[i + 1] is None:
                    acc[i + 1] = dup
                else:
                    acc[i + 1] = [[[acc[i + 1][c][a][b] + dup[c][a][b]
                                    for b in range(wi)] for a in range(hi)]
                                  for c in range(len(dup))]
        return dxs

    def zero_grad(self):
        for layer in self.lateral + self.smooth:
            layer.zero_grad()

    def param_count(self):
        return sum(_conv_param_count(layer) for layer in self.lateral + self.smooth)

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"FPN.sgd_step: lr 必须是非负数，收到 {lr!r}")
        for layer in self.lateral + self.smooth:
            _conv_sgd(layer, float(lr))

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"FPN.adam_step: lr 必须是非负数，收到 {lr!r}")
        for layer in self.lateral + self.smooth:
            _conv_adam(layer, float(lr), beta1, beta2, eps)


class SegNet:
    """SegNet（简化，2 级）：编码用 `MaxPool2d`，解码用**池化索引**还原位置

    结构（输入 `(Cin,H,W)`，要求 `H`、`W` 能被 4 整除）：

        conv1 (Cin→c0)  → relu → h0 (c0,H,W)    → pool0 → p0 (c0,H/2,W/2)
        conv2 (c0→2c0)  → relu → h1 (2c0,H/2,W/2) → pool1 → p1 (2c0,H/4,W/4)
        conv3 (2c0→2c0) → relu → b  (2c0,H/4,W/4)
        unpool1(b) → conv4 (2c0→c0) → relu → (c0,H/2,W/2)
        unpool0    → conv5 (c0→c0)  → relu → (c0,H,W)
        out: conv 1x1 (c0→num_classes)

    与 U-Net 的区别：解码不做跳跃拼接，且上采样是「把值放回最大池化选中的位置」。
    """

    def __init__(self, in_channels: int = 1, num_classes: int = 2,
                 base_channels: int = 4):
        for name, val in (("in_channels", in_channels),
                          ("num_classes", num_classes),
                          ("base_channels", base_channels)):
            if isinstance(val, bool) or not isinstance(val, int) or val < 1:
                raise ValueError(f"SegNet: {name} 必须是 >=1 的整数，收到 {val!r}")
        self.in_channels = in_channels
        self.num_classes = num_classes
        self.base_channels = base_channels
        c0 = base_channels
        c1 = base_channels * 2
        self.conv1 = Conv2d(in_channels, c0, 3, padding=1)
        self.conv2 = Conv2d(c0, c1, 3, padding=1)
        self.conv3 = Conv2d(c1, c1, 3, padding=1)
        self.conv4 = Conv2d(c1, c0, 3, padding=1)
        self.conv5 = Conv2d(c0, c0, 3, padding=1)
        self.out = Conv2d(c0, num_classes, 1)
        self.pool0 = MaxPool2d(2)
        self.pool1 = MaxPool2d(2)
        self._convs = [self.conv1, self.conv2, self.conv3, self.conv4,
                       self.conv5, self.out]
        self._cache = None

    def train(self):
        return self

    def eval(self):
        return self

    @staticmethod
    def _relu(z):
        return [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in z]

    @staticmethod
    def _relu_back(d, z, rows, cols):
        return [[[d[c][a][b] if z[c][a][b] > 0.0 else 0.0 for b in range(cols)]
                 for a in range(rows)] for c in range(len(z))]

    def forward(self, x):
        c = len(x)
        if c != self.in_channels:
            raise ValueError(
                f"SegNet.forward: 输入通道数 {c} 与 in_channels={self.in_channels} 不符")
        H, W = len(x[0]), len(x[0][0])
        if H % 4 != 0 or W % 4 != 0:
            raise ValueError(f"SegNet.forward: 输入尺寸 {(H, W)} 必须能被 4 整除")
        H2, W2 = H // 2, W // 2
        z1 = self.conv1.forward(x)
        h0 = self._relu(z1)
        p0 = self.pool0.forward(h0)
        z2 = self.conv2.forward(p0)
        h1 = self._relu(z2)
        p1 = self.pool1.forward(h1)
        z3 = self.conv3.forward(p1)
        hb = self._relu(z3)
        u1 = _unpool2(hb, self.pool1, H2, W2)
        z4 = self.conv4.forward(u1)
        h4 = self._relu(z4)
        u0 = _unpool2(h4, self.pool0, H, W)
        z5 = self.conv5.forward(u0)
        h5 = self._relu(z5)
        logits = self.out.forward(h5)
        self._cache = (z1, z2, z3, z4, z5)
        return logits

    def backward(self, dlogits):
        if self._cache is None:
            raise RuntimeError("SegNet.backward: 必须先调用 forward()")
        if len(dlogits) != self.num_classes:
            raise ValueError(
                f"SegNet.backward: dlogits 通道数 {len(dlogits)} 与 num_classes="
                f"{self.num_classes} 不符")
        z1, z2, z3, z4, z5 = self._cache
        c0 = self.base_channels
        c1 = c0 * 2
        H = len(z1[0])
        W = len(z1[0][0])
        H2, W2 = H // 2, W // 2
        H4, W4 = H // 4, W // 4

        dh5 = self.out.backward(dlogits)
        dz5 = self._relu_back(dh5, z5, H, W)
        du0 = self.conv5.backward(dz5)
        dh4 = _unpool2_back(du0, self.pool0)
        dz4 = self._relu_back(dh4, z4, H2, W2)
        du1 = self.conv4.backward(dz4)
        dhb = _unpool2_back(du1, self.pool1)
        dz3 = self._relu_back(dhb, z3, H4, W4)
        dp1 = self.conv3.backward(dz3)
        dh1 = self.pool1.backward(dp1)
        dz2 = self._relu_back(dh1, z2, H2, W2)
        dp0 = self.conv2.backward(dz2)
        dh0 = self.pool0.backward(dp0)
        dz1 = self._relu_back(dh0, z1, H, W)
        return self.conv1.backward(dz1)

    def zero_grad(self):
        for layer in self._convs:
            layer.zero_grad()

    def param_count(self):
        return sum(_conv_param_count(layer) for layer in self._convs)

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"SegNet.sgd_step: lr 必须是非负数，收到 {lr!r}")
        for layer in self._convs:
            _conv_sgd(layer, float(lr))

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"SegNet.adam_step: lr 必须是非负数，收到 {lr!r}")
        for layer in self._convs:
            _conv_adam(layer, float(lr), beta1, beta2, eps)


def _layer_zero_grads(layer):
    """`Layer` 的零梯度缓冲：`(grad_w, grad_b)`"""
    return ([[0.0] * len(row) for row in layer.weights],
            [0.0] * len(layer.biases))


def _layer_add_grads(acc, new):
    """把 `backward` 返回的 `(gw, gb)` 累加进缓冲"""
    gw, gb = acc
    ngw, ngb = new
    for i in range(len(gw)):
        for j in range(len(gw[i])):
            gw[i][j] += ngw[i][j]
    for i in range(len(gb)):
        gb[i] += ngb[i]


def _dense_rows_forward(layer, rows):
    """把 `layer` 逐行应用（不写 layer 的缓存），返回 (out_rows, cache)。

    `MLPMixer` 这类"同一层按通道/按 token 复用"的结构必须用这个版本：
    `Layer.forward` 只保留最后一次的 `input`/`z`，循环调用会让反向全用同一份缓存。
    """
    W, b = layer.weights, layer.biases
    act = layer.act_fn
    out, cache = [], []
    for row in rows:
        z = [sum(map(_mul, Wi, row)) + bi for Wi, bi in zip(W, b)]
        out.append(act(z))
        cache.append((row, z))
    return out, cache


def _dense_rows_backward(layer, cache, drows):
    """`_dense_rows_forward` 的反向，返回 (grad_w, grad_b, dx_rows)"""
    W = layer.weights
    deriv = layer.act_deriv
    grad_w = [[0.0] * layer.fan_in for _ in range(layer.fan_out)]
    grad_b = [0.0] * layer.fan_out
    dx_rows = []
    for (x, z), drow in zip(cache, drows):
        if len(drow) != layer.fan_out:
            raise ValueError(
                f"{type(layer).__name__} 反向: 行梯度长度 {len(drow)} 与输出维度 "
                f"{layer.fan_out} 不一致")
        d_act = deriv(z)
        w = [drow[j] * d_act[j] for j in range(layer.fan_out)]
        for i in range(layer.fan_out):
            wi = w[i]
            grad_b[i] += wi
            grow = grad_w[i]
            for j in range(layer.fan_in):
                grow[j] += wi * x[j]
        dx_rows.append([sum(map(_mul, col, w)) for col in zip(*W)])
    return grad_w, grad_b, dx_rows


def _norm_rows_forward(norm, rows):
    """把 `norm`（LayerNorm）逐行应用，返回 (out_rows, cache)。"""
    d = norm.d
    g, be, eps = norm.gamma, norm.beta, norm.eps
    out, cache = [], []
    for row in rows:
        if len(row) != d:
            raise ValueError(
                f"LayerNorm 前向: 长度 {len(row)} 与特征数 {d} 不一致")
        mean = sum(row) / d
        var = sum((xi - mean) ** 2 for xi in row) / d
        inv = 1.0 / math.sqrt(var + eps)
        xhat = [(xi - mean) * inv for xi in row]
        out.append([g[c] * xhat[c] + be[c] for c in range(d)])
        cache.append((xhat, inv))
    return out, cache


def _norm_rows_backward(norm, cache, drows):
    """`_norm_rows_forward` 的反向，返回 (grad_gamma, grad_beta, dx_rows)"""
    d = norm.d
    g = norm.gamma
    grad_g = [0.0] * d
    grad_b = [0.0] * d
    dx_rows = []
    for (xhat, inv), drow in zip(cache, drows):
        if len(drow) != d:
            raise ValueError(
                f"LayerNorm 反向: 梯度长度 {len(drow)} 与特征数 {d} 不一致")
        for c in range(d):
            grad_g[c] += drow[c] * xhat[c]
            grad_b[c] += drow[c]
        dg = [drow[c] * g[c] for c in range(d)]
        m1 = sum(dg) / d
        m2 = sum(dg[c] * xhat[c] for c in range(d)) / d
        dx_rows.append([inv * (dg[c] - m1 - xhat[c] * m2) for c in range(d)])
    return grad_g, grad_b, dx_rows


class _MixerBlock:
    """MLP-Mixer 的一个 block：token 混合 + 通道混合，两段都是 pre-LN 残差"""

    def __init__(self, d_model, n_tokens, token_hidden, channel_hidden, eps=1e-5):
        self.d_model = d_model
        self.n_tokens = n_tokens
        self.ln1 = LayerNorm(d_model, eps)
        self.t1 = Layer(n_tokens, token_hidden, "gelu")
        self.t2 = Layer(token_hidden, n_tokens, "linear")
        self.ln2 = LayerNorm(d_model, eps)
        self.c1 = Layer(d_model, channel_hidden, "gelu")
        self.c2 = Layer(channel_hidden, d_model, "linear")
        self._cache = None
        self.zero_grad()

    def zero_grad(self):
        self.grads = {"t1": _layer_zero_grads(self.t1),
                      "t2": _layer_zero_grads(self.t2),
                      "c1": _layer_zero_grads(self.c1),
                      "c2": _layer_zero_grads(self.c2)}
        self.norm_grads = {"ln1": ([0.0] * self.d_model, [0.0] * self.d_model),
                           "ln2": ([0.0] * self.d_model, [0.0] * self.d_model)}

    def forward(self, x):
        n, d = len(x), len(x[0])
        if n != self.n_tokens:
            raise ValueError(
                f"_MixerBlock.forward: token 数 {n} 与 n_tokens={self.n_tokens} 不符")
        ln1, ln1_cache = _norm_rows_forward(self.ln1, x)
        xt = [[ln1[t][c] for t in range(n)] for c in range(d)]
        mixed_rows, t_cache = _dense_rows_forward(self.t1, xt)
        rows, t2_cache = _dense_rows_forward(self.t2, mixed_rows)
        mixed = [[rows[c][t] for c in range(d)] for t in range(n)]
        x1 = [[x[t][c] + mixed[t][c] for c in range(d)] for t in range(n)]

        ln2, ln2_cache = _norm_rows_forward(self.ln2, x1)
        hid, c1_cache = _dense_rows_forward(self.c1, ln2)
        ch, c2_cache = _dense_rows_forward(self.c2, hid)
        out = [[x1[t][c] + ch[t][c] for c in range(d)] for t in range(n)]
        self._cache = (ln1_cache, xt, t_cache, t2_cache, ln2_cache, c1_cache,
                       c2_cache, x1)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("_MixerBlock.backward: 必须先调用 forward()")
        (ln1_cache, xt, t_cache, t2_cache, ln2_cache, c1_cache, c2_cache,
         x1) = self._cache
        n, d = self.n_tokens, self.d_model
        # 通道分支：逐 token 的 MLP
        g2w, g2b, dch = _dense_rows_backward(self.c2, c2_cache, dout)
        _layer_add_grads(self.grads["c2"], (g2w, g2b))
        g1w, g1b, dhid = _dense_rows_backward(self.c1, c1_cache, dch)
        _layer_add_grads(self.grads["c1"], (g1w, g1b))
        ggn, gbn, dln2 = _norm_rows_backward(self.ln2, ln2_cache, dhid)
        ng2 = self.norm_grads["ln2"]
        for c in range(d):
            ng2[0][c] += ggn[c]
            ng2[1][c] += gbn[c]
        dx1 = [[dout[t][c] + dln2[t][c] for c in range(d)] for t in range(n)]
        # token 分支：逐通道的 MLP（输入是 ln1 的转置）
        dmixed = [[dx1[t][c] for t in range(n)] for c in range(d)]
        g2tw, g2tb, da = _dense_rows_backward(self.t2, t2_cache, dmixed)
        _layer_add_grads(self.grads["t2"], (g2tw, g2tb))
        g1tw, g1tb, dxt = _dense_rows_backward(self.t1, t_cache, da)
        _layer_add_grads(self.grads["t1"], (g1tw, g1tb))
        dln1 = [[dxt[c][t] for c in range(d)] for t in range(n)]
        ggl, gbl, dpre = _norm_rows_backward(self.ln1, ln1_cache, dln1)
        ng1 = self.norm_grads["ln1"]
        for c in range(d):
            ng1[0][c] += ggl[c]
            ng1[1][c] += gbl[c]
        return [[dx1[t][c] + dpre[t][c] for c in range(d)] for t in range(n)]

    def param_count(self):
        return (sum(_dense_param_count(layer)
                    for layer in (self.t1, self.t2, self.c1, self.c2))
                + _norm_param_count(self.ln1) + _norm_param_count(self.ln2))

    def sgd_step(self, lr):
        for name, layer in (("t1", self.t1), ("t2", self.t2),
                            ("c1", self.c1), ("c2", self.c2)):
            _dense_apply_sgd(layer, self.grads[name], lr)
        _norm_apply_sgd(self.ln1, self.norm_grads["ln1"], lr)
        _norm_apply_sgd(self.ln2, self.norm_grads["ln2"], lr)

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        for name, layer in (("t1", self.t1), ("t2", self.t2),
                            ("c1", self.c1), ("c2", self.c2)):
            _dense_apply_adam(layer, self.grads[name], lr, beta1, beta2, eps)
        _norm_apply_adam(self.ln1, self.norm_grads["ln1"], lr, beta1, beta2, eps)
        _norm_apply_adam(self.ln2, self.norm_grads["ln2"], lr, beta1, beta2, eps)


class MLPMixer:
    """MLP-Mixer：patch 化 + 交替的 token 混合 / 通道混合 MLP

    结构（输入 `(C,H,W)`，`H`、`W` 必须能被 `patch_size` 整除）：

        `PatchEmbedding` -> `n` 个 `d_model` 维 token
        每个 block：`x = x + tokenMLP(LN(x))` 然后 `x = x + channelMLP(LN(x))`
        结尾：每个 token 过 `LayerNorm` -> 对 token 取平均 -> 线性分类头

    token 混合在「token 轴」上做 MLP（把 `(n,d)` 转成 `(d,n)` 后逐行过 `n -> h -> n`），
    与 `ViT` 的自注意力形成对照：这里**没有任何注意力**，只有 MLP。
    梯度语义与 `ViT` 一致：`backward` 累加，更新前先 `zero_grad()`。
    """

    def __init__(self, in_channels: int = 3, image_size=8, patch_size: int = 4,
                 d_model: int = 16, num_layers: int = 2, token_hidden: int = 32,
                 channel_hidden: int = 32, num_classes: int = 10, eps: float = 1e-5):
        for name, val in (("in_channels", in_channels), ("patch_size", patch_size),
                          ("d_model", d_model), ("num_layers", num_layers),
                          ("token_hidden", token_hidden),
                          ("channel_hidden", channel_hidden),
                          ("num_classes", num_classes)):
            if isinstance(val, bool) or not isinstance(val, int) or val < 1:
                raise ValueError(f"MLPMixer: {name} 必须是 >=1 的整数，收到 {val!r}")
        if isinstance(image_size, (list, tuple)):
            if len(image_size) != 2:
                raise ValueError(
                    f"MLPMixer: image_size 必须是 int 或 (H,W)，收到 {image_size!r}")
            H, W = image_size
        else:
            H = W = image_size
        for name, val in (("image_size.H", H), ("image_size.W", W)):
            if isinstance(val, bool) or not isinstance(val, int) or val < 1:
                raise ValueError(f"MLPMixer: {name} 必须是 >=1 的整数，收到 {val!r}")
        if H % patch_size != 0 or W % patch_size != 0:
            raise ValueError(
                f"MLPMixer: 输入尺寸 {(H, W)} 必须能被 patch_size={patch_size} 整除")
        self.in_channels = in_channels
        self.image_size = (H, W)
        self.patch_size = patch_size
        self.d_model = d_model
        self.num_classes = num_classes
        self.num_layers = num_layers
        self.patch_embed = PatchEmbedding(in_channels, patch_size, d_model)
        self.n_tokens = (H // patch_size) * (W // patch_size)
        self.blocks = [_MixerBlock(d_model, self.n_tokens, token_hidden,
                                   channel_hidden, eps) for _ in range(num_layers)]
        self.norm = LayerNorm(d_model, eps)
        self.head = Layer(d_model, num_classes, "linear")
        self._cache = None
        self.zero_grad()

    def train(self):
        return self

    def eval(self):
        return self

    def forward(self, x):
        if len(x) != self.in_channels:
            raise ValueError(
                f"MLPMixer.forward: 输入通道数 {len(x)} 与 in_channels="
                f"{self.in_channels} 不符")
        H, W = len(x[0]), len(x[0][0])
        if (H, W) != self.image_size:
            raise ValueError(
                f"MLPMixer.forward: 输入尺寸 {(H, W)} 与 image_size="
                f"{self.image_size} 不符")
        tokens = self.patch_embed.forward(x)
        for blk in self.blocks:
            tokens = blk.forward(tokens)
        normed, norm_cache = _norm_rows_forward(self.norm, tokens)
        n = len(normed)
        pooled = [sum(normed[t][c] for t in range(n)) / n
                  for c in range(self.d_model)]
        logits = self.head.forward(pooled)
        self._cache = (tokens, normed, n, norm_cache)
        return logits

    def backward(self, dlogits):
        if self._cache is None:
            raise RuntimeError("MLPMixer.backward: 必须先调用 forward()")
        if len(dlogits) != self.num_classes:
            raise ValueError(
                f"MLPMixer.backward: dlogits 长度 {len(dlogits)} 与 num_classes="
                f"{self.num_classes} 不符")
        tokens, normed, n, norm_cache = self._cache
        gw, gb, dpooled = self.head.backward(dlogits)
        _layer_add_grads(self.head_grads, (gw, gb))
        dnormed = [[dpooled[c] / n for c in range(self.d_model)]
                   for _ in range(n)]
        ggn, gbn, dtokens = _norm_rows_backward(self.norm, norm_cache, dnormed)
        for c in range(self.d_model):
            self.norm_grads[0][c] += ggn[c]
            self.norm_grads[1][c] += gbn[c]
        for blk in reversed(self.blocks):
            dtokens = blk.backward(dtokens)
        return self.patch_embed.backward(dtokens)

    def zero_grad(self):
        self.head_grads = _layer_zero_grads(self.head)
        self.norm_grads = ([0.0] * self.d_model, [0.0] * self.d_model)
        for blk in self.blocks:
            blk.zero_grad()
        self.patch_embed.zero_grad()

    def param_count(self):
        total = _dense_param_count(self.head) + _norm_param_count(self.norm)
        total += self.patch_embed.param_count()
        for blk in self.blocks:
            total += blk.param_count()
        return total

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"MLPMixer.sgd_step: lr 必须是非负数，收到 {lr!r}")
        self.patch_embed.sgd_step(lr)
        for blk in self.blocks:
            blk.sgd_step(lr)
        _dense_apply_sgd(self.head, self.head_grads, lr)
        _norm_apply_sgd(self.norm, self.norm_grads, lr)

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"MLPMixer.adam_step: lr 必须是非负数，收到 {lr!r}")
        self.patch_embed.adam_step(lr, beta1, beta2, eps)
        for blk in self.blocks:
            blk.adam_step(lr, beta1, beta2, eps)
        _dense_apply_adam(self.head, self.head_grads, lr, beta1, beta2, eps)
        _norm_apply_adam(self.norm, self.norm_grads, lr, beta1, beta2, eps)


def _win_partition(gh, gw, ws, shift):
    """按窗口切 (gh,gw) 网格；shift>0 时先循环 roll（右下）。

    返回 perm：rolled 网格第 i 个位置对应的**原始**下标（长度 gh*gw）。
    """
    perm = [0] * (gh * gw)
    for r in range(gh):
        sr = (r - shift) % gh
        for c in range(gw):
            sc = (c - shift) % gw
            perm[r * gw + c] = sr * gw + sc
    windows = []
    for wr in range(gh // ws):
        for wc in range(gw // ws):
            idx = []
            for i in range(ws):
                base = (wr * ws + i) * gw + wc * ws
                idx.extend(range(base, base + ws))
            windows.append(idx)
    return perm, windows


def _win_attention_masks(gh, gw, ws, perm, windows):
    """按原始窗口归属生成每个窗口的加性 attention mask（0 / -inf）。

    `perm[pos]` 是 rolled 网格第 pos 个位置对应的原始下标；原始下标属于哪个
    原始窗口由 `(row // ws, col // ws)` 决定。同一原始窗口内的 token 可以互相关注，
    不同原始窗口之间被 mask 掉（避免移位窗口把跨边界的 token 混进来）。
    """
    n_win_cols = gw // ws
    regions = []
    for pos in range(gh * gw):
        orig = perm[pos]
        orow, ocol = divmod(orig, gw)
        regions.append((orow // ws) * n_win_cols + (ocol // ws))
    masks = []
    for idx in windows:
        n = len(idx)
        row = []
        for i in range(n):
            ri = regions[idx[i]]
            row.append([0.0 if ri == regions[idx[j]] else -math.inf
                        for j in range(n)])
        masks.append(row)
    return masks


def _win_attn_forward(q, k, v, windows, num_heads, d_model, masks=None):
    """窗口内的缩放点积注意力；q/k/v 已按 rolled 顺序给好。

    `masks` 为 None 或与 windows 等长的列表，每项是 n×n 的加性 mask
    （0 或 -inf），softmax 前加到 logits 上。返回 (ctx, cache)；
    cache 存每个窗口的 softmax 概率（被 mask 的位置概率恰为 0），反向直接用。
    """
    dk = d_model // num_heads
    scale = 1.0 / math.sqrt(dk)
    if masks is not None and len(masks) != len(windows):
        raise ValueError(
            f"_win_attn_forward: masks 长度 {len(masks)} 与窗口数 {len(windows)} 不一致")
    ctx = [[0.0] * d_model for _ in range(len(q))]
    cache = []
    for wi, idx in enumerate(windows):
        n = len(idx)
        probs_win = []
        for hh in range(num_heads):
            lo = hh * dk
            for i in range(n):
                ii = idx[i]
                qi = q[ii][lo:lo + dk]
                row_mask = masks[wi][i] if masks is not None else None
                logits = []
                for j in range(n):
                    kj = k[idx[j]][lo:lo + dk]
                    t = sum(map(_mul, qi, kj)) * scale
                    if row_mask is not None:
                        t += row_mask[j]
                    logits.append(t)
                mx = max(logits)
                ex = [math.exp(t - mx) for t in logits]
                s = sum(ex)
                pr = [e / s for e in ex]
                probs_win.append(pr)
                ci = ctx[ii]
                for j in range(n):
                    w = pr[j]
                    if w == 0.0:
                        continue
                    vj = v[idx[j]]
                    for t in range(dk):
                        ci[lo + t] += w * vj[lo + t]
        cache.append(probs_win)
    return ctx, cache


def _win_attn_backward(dctx, q, k, v, windows, cache, num_heads, d_model):
    """窗口内注意力反向，返回 (dq, dk, dv)，形状与 q/k/v 相同"""
    dk = d_model // num_heads
    scale = 1.0 / math.sqrt(dk)
    dq = [[0.0] * d_model for _ in range(len(q))]
    dk_ = [[0.0] * d_model for _ in range(len(k))]
    dv = [[0.0] * d_model for _ in range(len(v))]
    for wi, idx in enumerate(windows):
        n = len(idx)
        probs_win = cache[wi]
        for hh in range(num_heads):
            lo = hh * dk
            for i in range(n):
                ii = idx[i]
                pr = probs_win[hh * n + i]
                dci = dctx[ii][lo:lo + dk]
                qi = q[ii][lo:lo + dk]
                dot = []
                for j in range(n):
                    vj = v[idx[j]][lo:lo + dk]
                    dot.append(sum(map(_mul, dci, vj)))
                avg = sum(pr[s] * dot[s] for s in range(n))
                for j in range(n):
                    g = pr[j] * (dot[j] - avg) * scale
                    jj = idx[j]
                    kj = k[jj][lo:lo + dk]
                    vj = v[jj][lo:lo + dk]
                    dqi = dq[ii]
                    dkj = dk_[jj]
                    dvj = dv[jj]
                    for t in range(dk):
                        dqi[lo + t] += g * kj[t]
                        dkj[lo + t] += g * qi[t]
                        dvj[lo + t] += pr[j] * dci[t]
    return dq, dk_, dv


class SwinBlock:
    """Swin 的单 stage block：窗口注意力 + 两层 MLP（都是 pre-LN 残差）

    `shift=0` 是普通窗口；`shift=window_size//2` 是移位窗口。
    """

    def __init__(self, d_model, num_heads, d_ff, window_size, shift=0, eps=1e-5):
        if isinstance(num_heads, bool) or not isinstance(num_heads, int) or num_heads < 1:
            raise ValueError(f"SwinBlock: num_heads 必须是正整数，收到 {num_heads!r}")
        if d_model % num_heads != 0:
            raise ValueError(
                f"SwinBlock: d_model={d_model} 必须能被 num_heads={num_heads} 整除")
        if isinstance(window_size, bool) or not isinstance(window_size, int) or window_size < 1:
            raise ValueError(
                f"SwinBlock: window_size 必须是正整数，收到 {window_size!r}")
        if isinstance(shift, bool) or not isinstance(shift, int) or shift < 0:
            raise ValueError(f"SwinBlock: shift 必须是非负整数，收到 {shift!r}")
        self.d_model = d_model
        self.num_heads = num_heads
        self.window_size = window_size
        self.shift = shift
        self.ln1 = LayerNorm(d_model, eps)
        self.ln2 = LayerNorm(d_model, eps)
        self.q = Layer(d_model, d_model, "linear")
        self.k = Layer(d_model, d_model, "linear")
        self.v = Layer(d_model, d_model, "linear")
        self.o = Layer(d_model, d_model, "linear")
        self.f1 = Layer(d_model, d_ff, "gelu")
        self.f2 = Layer(d_ff, d_model, "linear")
        self._cache = None
        self.zero_grad()

    def zero_grad(self):
        d = self.d_model
        self.grads = {
            "q": _layer_zero_grads(self.q),
            "k": _layer_zero_grads(self.k),
            "v": _layer_zero_grads(self.v),
            "o": _layer_zero_grads(self.o),
            "f1": _layer_zero_grads(self.f1),
            "f2": _layer_zero_grads(self.f2),
        }
        self.norm_grads = {"ln1": ([0.0] * d, [0.0] * d),
                           "ln2": ([0.0] * d, [0.0] * d)}

    def forward(self, tokens, gh, gw):
        ws = self.window_size
        if gh % ws or gw % ws:
            raise ValueError(
                f"SwinBlock.forward: 网格 {(gh, gw)} 必须能被 window_size={ws} 整除")
        perm, windows = _win_partition(gh, gw, ws, self.shift)
        masks = (_win_attention_masks(gh, gw, ws, perm, windows)
                 if self.shift else None)
        rolled = [tokens[i] for i in perm]
        a, ln1_cache = _norm_rows_forward(self.ln1, rolled)
        q, qc = _dense_rows_forward(self.q, a)
        k, kc = _dense_rows_forward(self.k, a)
        v, vc = _dense_rows_forward(self.v, a)
        ctx, attn_cache = _win_attn_forward(q, k, v, windows, self.num_heads,
                                            self.d_model, masks)
        o, oc = _dense_rows_forward(self.o, ctx)
        merged = [[rolled[t][c] + o[t][c] for c in range(self.d_model)]
                  for t in range(len(rolled))]
        b, ln2_cache = _norm_rows_forward(self.ln2, merged)
        h, f1c = _dense_rows_forward(self.f1, b)
        ff, f2c = _dense_rows_forward(self.f2, h)
        out_rolled = [[merged[t][c] + ff[t][c] for c in range(self.d_model)]
                      for t in range(len(merged))]
        out = [None] * len(tokens)
        for i, si in enumerate(perm):
            out[si] = out_rolled[i]
        self._cache = (perm, windows, gh, gw, rolled, ln1_cache, q, k, v,
                       qc, kc, vc, attn_cache, oc, merged, ln2_cache, h, f1c,
                       f2c)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("SwinBlock.backward: 必须先调用 forward()")
        (perm, windows, gh, gw, rolled, ln1_cache, q, k, v, qc, kc, vc,
         attn_cache, oc, merged, ln2_cache, h, f1c, f2c) = self._cache
        d = self.d_model
        n = len(rolled)
        d_rolled = [dout[i] for i in perm]
        # ---- MLP 分支 ----
        g2, b2, dh = _dense_rows_backward(self.f2, f2c, d_rolled)
        _layer_add_grads(self.grads["f2"], (g2, b2))
        g1, b1, db = _dense_rows_backward(self.f1, f1c, dh)
        _layer_add_grads(self.grads["f1"], (g1, b1))
        ggl, gbl, dmerged_ln = _norm_rows_backward(self.ln2, ln2_cache, db)
        ng2 = self.norm_grads["ln2"]
        for c in range(d):
            ng2[0][c] += ggl[c]
            ng2[1][c] += gbl[c]
        dmerged = [[d_rolled[t][c] + dmerged_ln[t][c] for c in range(d)]
                   for t in range(n)]
        # ---- 注意力分支 ----
        go, gbo2, dctx = _dense_rows_backward(self.o, oc, dmerged)
        _layer_add_grads(self.grads["o"], (go, gbo2))
        dq, dk_, dv = _win_attn_backward(dctx, q, k, v, windows, attn_cache,
                                         self.num_heads, d)
        gq, bq, da_q = _dense_rows_backward(self.q, qc, dq)
        _layer_add_grads(self.grads["q"], (gq, bq))
        gk, bk, da_k = _dense_rows_backward(self.k, kc, dk_)
        _layer_add_grads(self.grads["k"], (gk, bk))
        gv, bv, da_v = _dense_rows_backward(self.v, vc, dv)
        _layer_add_grads(self.grads["v"], (gv, bv))
        da = [[da_q[t][c] + da_k[t][c] + da_v[t][c] for c in range(d)]
              for t in range(n)]
        ggl1, gbl1, dpre = _norm_rows_backward(self.ln1, ln1_cache, da)
        ng1 = self.norm_grads["ln1"]
        for c in range(d):
            ng1[0][c] += ggl1[c]
            ng1[1][c] += gbl1[c]
        out = [None] * n
        for i, si in enumerate(perm):
            out[si] = [dmerged[i][c] + dpre[i][c] for c in range(d)]
        return out

    def param_count(self):
        total = sum(_dense_param_count(getattr(self, name))
                    for name in ("q", "k", "v", "o", "f1", "f2"))
        return total + _norm_param_count(self.ln1) + _norm_param_count(self.ln2)

    def train(self):
        pass

    def eval(self):
        pass

    def sgd_step(self, lr):
        for name in ("q", "k", "v", "o", "f1", "f2"):
            _dense_apply_sgd(getattr(self, name), self.grads[name], lr)
        _norm_apply_sgd(self.ln1, self.norm_grads["ln1"], lr)
        _norm_apply_sgd(self.ln2, self.norm_grads["ln2"], lr)

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        for name in ("q", "k", "v", "o", "f1", "f2"):
            _dense_apply_adam(getattr(self, name), self.grads[name], lr,
                              beta1, beta2, eps)
        _norm_apply_adam(self.ln1, self.norm_grads["ln1"], lr, beta1, beta2, eps)
        _norm_apply_adam(self.ln2, self.norm_grads["ln2"], lr, beta1, beta2, eps)


class PatchMerging:
    """Swin 的 patch merging：2×2 邻块拼接 → LayerNorm → 线性降到一半通道

    forward 输入 tokens（长度 gh*gw、维度 C），把 2×2 邻块拼成 4C 维，再线性
    降到 2C；输出网格 (gh/2, gw/2)。backward 反推回原 tokens。
    """

    def __init__(self, in_channels, eps=1e-5):
        if isinstance(in_channels, bool) or not isinstance(in_channels, int) \
                or in_channels < 1:
            raise ValueError(
                f"PatchMerging: in_channels 必须是正整数，收到 {in_channels!r}")
        self.in_channels = in_channels
        self.out_channels = 2 * in_channels
        self.norm = LayerNorm(4 * in_channels, eps)
        self.reduction = Layer(4 * in_channels, 2 * in_channels, "linear")
        self._cache = None
        self.zero_grad()

    def zero_grad(self):
        d = 4 * self.in_channels
        self.norm_grads = ([0.0] * d, [0.0] * d)
        self.reduction_grads = _layer_zero_grads(self.reduction)

    def forward(self, tokens, gh, gw):
        if not isinstance(gh, int) or not isinstance(gw, int) or gh < 1 or gw < 1:
            raise ValueError(f"PatchMerging.forward: 网格 ({gh!r}, {gw!r}) 非法")
        if len(tokens) != gh * gw:
            raise ValueError(
                f"PatchMerging.forward: token 数 {len(tokens)} 与网格 "
                f"{(gh, gw)} 不一致")
        for t in tokens:
            if len(t) != self.in_channels:
                raise ValueError(
                    f"PatchMerging.forward: token 维度 {len(t)} 与 "
                    f"in_channels={self.in_channels} 不一致")
        if gh % 2 or gw % 2:
            raise ValueError(
                f"PatchMerging.forward: 网格 {(gh, gw)} 必须都是偶数才能 2×2 合并")
        c = self.in_channels
        rows = []
        for r in range(gh // 2):
            for cc in range(gw // 2):
                base = (2 * r) * gw + 2 * cc
                idx4 = [base, base + 1, base + gw, base + gw + 1]
                rows.append([v for i in idx4 for v in tokens[i]])
        normed, norm_cache = _norm_rows_forward(self.norm, rows)
        out, dense_cache = _dense_rows_forward(self.reduction, normed)
        self._cache = (tokens, gh, gw, norm_cache, dense_cache)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("PatchMerging.backward: 必须先调用 forward()")
        tokens, gh, gw, norm_cache, dense_cache = self._cache
        if len(dout) != (gh // 2) * (gw // 2):
            raise ValueError(
                f"PatchMerging.backward: 梯度 token 数 {len(dout)} 与输出网格 "
                f"{(gh // 2, gw // 2)} 不一致")
        gw_, gb_, d_normed = _dense_rows_backward(self.reduction, dense_cache, dout)
        _layer_add_grads(self.reduction_grads, (gw_, gb_))
        ggn, gbn, d_rows = _norm_rows_backward(self.norm, norm_cache, d_normed)
        for c in range(4 * self.in_channels):
            self.norm_grads[0][c] += ggn[c]
            self.norm_grads[1][c] += gbn[c]
        c = self.in_channels
        d_tokens = [[0.0] * c for _ in range(len(tokens))]
        oi = 0
        for r in range(gh // 2):
            for cc in range(gw // 2):
                base = (2 * r) * gw + 2 * cc
                idx4 = [base, base + 1, base + gw, base + gw + 1]
                drow = d_rows[oi]
                for k, ti in enumerate(idx4):
                    dt = d_tokens[ti]
                    for ch in range(c):
                        dt[ch] += drow[k * c + ch]
                oi += 1
        return d_tokens

    def param_count(self):
        return (_norm_param_count(self.norm)
                + _dense_param_count(self.reduction))

    def train(self):
        pass

    def eval(self):
        pass

    def sgd_step(self, lr):
        _norm_apply_sgd(self.norm, self.norm_grads, lr)
        _dense_apply_sgd(self.reduction, self.reduction_grads, lr)

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        _norm_apply_adam(self.norm, self.norm_grads, lr, beta1, beta2, eps)
        _dense_apply_adam(self.reduction, self.reduction_grads, lr,
                          beta1, beta2, eps)


class SwinTransformer:
    """Swin Transformer：PatchEmbedding → 多 stage 窗口注意力 → 池化 → 线性头

    - 每个 stage 交替「普通窗口 / 移位窗口」块（`shift = window_size // 2`）；
    - 移位窗口注意力按原始窗口归属加 attention mask（`_win_attention_masks`），
      避免跨窗口信息混入；
    - `depths` 给出多个 stage 的深度时，stage 之间用 `PatchMerging` 做 2×2
      下采样并把通道翻倍（层级式 Swin）；只给一个深度时就是单 stage 版本。
    """

    def __init__(self, in_channels=3, image_size=8, patch_size=4, d_model=16,
                 num_heads=4, d_ff=32, num_layers=2, window_size=2,
                 num_classes=10, eps=1e-5, depths=None):
        for name, v in (("in_channels", in_channels), ("patch_size", patch_size),
                        ("d_model", d_model), ("num_heads", num_heads),
                        ("d_ff", d_ff), ("num_layers", num_layers),
                        ("window_size", window_size),
                        ("num_classes", num_classes)):
            if isinstance(v, bool) or not isinstance(v, int) or v < 1:
                raise ValueError(
                    f"SwinTransformer: {name} 必须是正整数，收到 {v!r}")
        if depths is None:
            depths = (num_layers,)
        else:
            if not isinstance(depths, (tuple, list)) or not depths:
                raise ValueError(
                    f"SwinTransformer: depths 必须是非空 tuple/list，收到 {depths!r}")
            for v in depths:
                if isinstance(v, bool) or not isinstance(v, int) or v < 1:
                    raise ValueError(
                        f"SwinTransformer: depths 的元素必须是正整数，收到 {v!r}")
            depths = tuple(depths)
        if isinstance(image_size, int):
            size = (image_size, image_size)
        else:
            if len(image_size) != 2:
                raise ValueError("SwinTransformer: image_size 必须是 int 或 (H, W)")
            size = (image_size[0], image_size[1])
        if size[0] % patch_size or size[1] % patch_size:
            raise ValueError(
                f"SwinTransformer: image_size={size} 必须能被 patch_size="
                f"{patch_size} 整除")
        if d_model % num_heads != 0:
            raise ValueError(
                f"SwinTransformer: d_model={d_model} 必须能被 num_heads="
                f"{num_heads} 整除")
        gh, gw = size[0] // patch_size, size[1] // patch_size
        if gh % window_size or gw % window_size:
            raise ValueError(
                f"SwinTransformer: patch 网格 {(gh, gw)} 必须能被 window_size="
                f"{window_size} 整除")
        self.in_channels = in_channels
        self.image_size = size
        self.patch_size = patch_size
        self.d_model = d_model
        self.num_heads = num_heads
        self.num_layers = num_layers
        self.window_size = window_size
        self.num_classes = num_classes
        self.depths = depths
        self.grid = (gh, gw)
        self.stage_grids = []
        self.stages = []
        self.merges = []
        grid = (gh, gw)
        dim = d_model
        for si, depth in enumerate(depths):
            if grid[0] % window_size or grid[1] % window_size:
                raise ValueError(
                    f"SwinTransformer: 第 {si} 个 stage 的网格 {grid} 必须能被 "
                    f"window_size={window_size} 整除")
            self.stage_grids.append(grid)
            blocks = []
            for i in range(depth):
                shift = 0 if i % 2 == 0 else window_size // 2
                blocks.append(
                    SwinBlock(dim, num_heads, d_ff, window_size, shift, eps))
            self.stages.append(blocks)
            if si < len(depths) - 1:
                if grid[0] % 2 or grid[1] % 2:
                    raise ValueError(
                        f"SwinTransformer: 第 {si} 个 stage 的网格 {grid} 必须"
                        f"都是偶数才能做 patch merging")
                self.merges.append(PatchMerging(dim, eps))
                grid = (grid[0] // 2, grid[1] // 2)
                dim *= 2
        self.d_model_final = dim
        self.patch_embed = PatchEmbedding(in_channels, patch_size, d_model)
        self.norm = LayerNorm(dim, eps)
        self.head = Layer(dim, num_classes, "linear")
        # 兼容旧接口：blocks 指第一个 stage 的块
        self.blocks = self.stages[0]
        self._cache = None
        self.zero_grad()

    def zero_grad(self):
        self.norm_grads = ([0.0] * self.d_model_final,
                           [0.0] * self.d_model_final)
        self.head_grads = _layer_zero_grads(self.head)
        for blocks in self.stages:
            for blk in blocks:
                blk.zero_grad()
        for mg in self.merges:
            mg.zero_grad()
        self.patch_embed.zero_grad()

    def forward(self, x):
        if len(x) != self.in_channels:
            raise ValueError(
                f"SwinTransformer.forward: 输入通道数 {len(x)} 与 in_channels="
                f"{self.in_channels} 不符")
        if (len(x[0]), len(x[0][0])) != self.image_size:
            raise ValueError(
                f"SwinTransformer.forward: 输入尺寸 {(len(x[0]), len(x[0][0]))} "
                f"与 image_size={self.image_size} 不符")
        tokens = self.patch_embed.forward(x)
        for si, blocks in enumerate(self.stages):
            gh, gw = self.stage_grids[si]
            for blk in blocks:
                tokens = blk.forward(tokens, gh, gw)
            if si < len(self.merges):
                tokens = self.merges[si].forward(tokens, gh, gw)
        normed, norm_cache = _norm_rows_forward(self.norm, tokens)
        n = len(normed)
        pooled = [sum(normed[t][c] for t in range(n)) / n
                  for c in range(self.d_model_final)]
        logits = self.head.forward(pooled)
        self._cache = (tokens, n, norm_cache)
        return logits

    def backward(self, dlogits):
        if self._cache is None:
            raise RuntimeError("SwinTransformer.backward: 必须先调用 forward()")
        if len(dlogits) != self.num_classes:
            raise ValueError(
                f"SwinTransformer.backward: dlogits 长度 {len(dlogits)} 与 "
                f"num_classes={self.num_classes} 不符")
        tokens, n, norm_cache = self._cache
        gw, gb, dpooled = self.head.backward(dlogits)
        _layer_add_grads(self.head_grads, (gw, gb))
        dnormed = [[dpooled[c] / n for c in range(self.d_model_final)]
                   for _ in range(n)]
        ggn, gbn, dtokens = _norm_rows_backward(self.norm, norm_cache, dnormed)
        for c in range(self.d_model_final):
            self.norm_grads[0][c] += ggn[c]
            self.norm_grads[1][c] += gbn[c]
        for si in reversed(range(len(self.stages))):
            for blk in reversed(self.stages[si]):
                dtokens = blk.backward(dtokens)
            if si > 0:
                dtokens = self.merges[si - 1].backward(dtokens)
        return self.patch_embed.backward(dtokens)

    def param_count(self):
        total = (self.patch_embed.param_count()
                 + _dense_param_count(self.head)
                 + _norm_param_count(self.norm))
        for mg in self.merges:
            total += mg.param_count()
        for blocks in self.stages:
            for blk in blocks:
                total += blk.param_count()
        return total

    def train(self):
        pass

    def eval(self):
        pass

    def sgd_step(self, lr):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"SwinTransformer.sgd_step: lr 必须是非负数，收到 {lr!r}")
        self.patch_embed.sgd_step(lr)
        for blocks in self.stages:
            for blk in blocks:
                blk.sgd_step(lr)
        for mg in self.merges:
            mg.sgd_step(lr)
        _dense_apply_sgd(self.head, self.head_grads, lr)
        _norm_apply_sgd(self.norm, self.norm_grads, lr)

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"SwinTransformer.adam_step: lr 必须是非负数，收到 {lr!r}")
        self.patch_embed.adam_step(lr, beta1, beta2, eps)
        for blocks in self.stages:
            for blk in blocks:
                blk.adam_step(lr, beta1, beta2, eps)
        for mg in self.merges:
            mg.adam_step(lr, beta1, beta2, eps)
        _dense_apply_adam(self.head, self.head_grads, lr, beta1, beta2, eps)
        _norm_apply_adam(self.norm, self.norm_grads, lr, beta1, beta2, eps)


def _g_act(name: str):
    """按名字返回 (逐行激活函数, 逐行导数)，供图网络层使用。

    只支持不依赖行内其它位置的激活（relu / leaky_relu / elu / selu /
    gelu / silu / mish / tanh / sigmoid / linear）；softmax 这类依赖整行的
    激活不开放，避免在图读出时产生歧义。
    """
    if not isinstance(name, str):
        raise TypeError('图网络层的 activation 必须是字符串，收到 %r' % (name,))
    key = name.lower()
    if key == 'relu':
        return (lambda z: [v if v > 0.0 else 0.0 for v in z],
                lambda z: [1.0 if v > 0.0 else 0.0 for v in z])
    if key == 'leaky_relu':
        return (lambda z: [v if v >= 0.0 else 0.01 * v for v in z],
                lambda z: [1.0 if v >= 0.0 else 0.01 for v in z])
    if key == 'linear':
        return (lambda z: list(z), lambda z: [1.0] * len(z))
    if key == 'tanh':
        return (lambda z: [math.tanh(v) for v in z],
                lambda z: [1.0 - math.tanh(v) ** 2 for v in z])
    if key == 'sigmoid':
        def _sig_row(z):
            out = []
            for v in z:
                if v >= 0.0:
                    out.append(1.0 / (1.0 + math.exp(-v)))
                else:
                    e = math.exp(v)
                    out.append(e / (1.0 + e))
            return out

        def _dsig_row(z, _s=_sig_row):
            return [s * (1.0 - s) for s in _s(z)]

        return (_sig_row, _dsig_row)
    if key in ('gelu', 'silu', 'mish', 'elu', 'selu'):
        row_fn = _G_ACT_ROW[key]
        row_der = _G_ACT_ROW_DERIV[key]
        return (row_fn, row_der)
    raise ValueError("不支持的激活 %r（可选 relu / leaky_relu / linear / tanh / "
                     "sigmoid / gelu / silu / mish / elu / selu）" % (name,))



_G_ACT_ROW = {
    'gelu': lambda z: [_gelu_scalar(v) for v in z],
    'silu': lambda z: [v * _silu_scalar(v) for v in z],
    'mish': lambda z: [v * math.tanh(math.log1p(math.exp(v))) if v < 20.0
                       else v for v in z],
    'elu': lambda z: [v if v > 0.0 else math.exp(v) - 1.0 for v in z],
    'selu': lambda z: [1.0507009873554805 * (v if v > 0.0
                                             else 1.6732632423543772 * (math.exp(v) - 1.0))
                       for v in z],
}

_G_ACT_ROW_DERIV = {
    'gelu': lambda z: [_dgelu_scalar(v) for v in z],
    'silu': lambda z: [_silu_scalar(v) + v * _silu_scalar(v) * (1.0 - _silu_scalar(v))
                       for v in z],
    'mish': lambda z: [(math.tanh(math.log1p(math.exp(v)))
                        + v * (1.0 - math.tanh(math.log1p(math.exp(v))) ** 2)
                        * _silu_scalar(v)) if v < 20.0 else 1.0 for v in z],
    'elu': lambda z: [1.0 if v > 0.0 else math.exp(v) for v in z],
    'selu': lambda z: [1.0507009873554805 if v > 0.0
                       else 1.0507009873554805 * 1.6732632423543772 * math.exp(v)
                       for v in z],
}

def _g_check_x(X, who: str) -> int:
    """校验节点特征矩阵并返回节点数"""
    if not isinstance(X, list) or not X:
        raise ValueError('%s: X 必须是非空的节点列表' % who)
    if not isinstance(X[0], list) or not X[0]:
        raise ValueError('%s: X 的每个节点必须是特征列表' % who)
    dim = len(X[0])
    for i, row in enumerate(X):
        if not isinstance(row, list) or len(row) != dim:
            raise ValueError('%s: X 第 %d 行的特征维度不是 %d' % (who, i, dim))
        for v in row:
            if not _is_num(v):
                raise ValueError('%s: X[%d] 含非有限数值 %r' % (who, i, v))
    return len(X)


def _g_check_adj(adj, n: int, who: str):
    """校验邻接矩阵：n x n、对称性不强制、权重必须有限"""
    if not isinstance(adj, list) or len(adj) != n:
        raise ValueError('%s: adj 必须是 %d x %d 矩阵' % (who, n, n))
    for i, row in enumerate(adj):
        if not isinstance(row, list) or len(row) != n:
            raise ValueError('%s: adj 第 %d 行长度不是 %d' % (who, i, n))
        for v in row:
            if not _is_num(v):
                raise ValueError('%s: adj[%d] 含非有限数值 %r' % (who, i, v))


def _g_adj_norm(adj, self_loops: bool = True):
    """返回 ``D^{-1/2} (A + I) D^{-1/2}``（不再保证对称归一化以外的性质）"""
    n = len(adj)
    a = [[float(adj[i][j]) for j in range(n)] for i in range(n)]
    if self_loops:
        for i in range(n):
            a[i][i] += 1.0
    deg = [sum(a[i]) for i in range(n)]
    inv = [(1.0 / math.sqrt(d)) if d > 0.0 else 0.0 for d in deg]
    return [[a[i][j] * inv[i] * inv[j] for j in range(n)] for i in range(n)]


def _g_row_mean(adj):
    """行归一化邻接矩阵 ``D^{-1} A``（只在有边时归一化）"""
    n = len(adj)
    out = [[0.0] * n for _ in range(n)]
    for i in range(n):
        deg = sum(adj[i])
        if deg <= 0.0:
            continue
        inv = 1.0 / deg
        for j in range(n):
            out[i][j] = adj[i][j] * inv
    return out


def _g_scale_rows(a, b):
    """逐元素相乘（a、b 同长度的行向量）"""
    return [x * y for x, y in zip(a, b)]


def _g_matmul(M, X):
    """(N x N) @ (N x F)"""
    n = len(M)
    f = len(X[0])
    out = [[0.0] * f for _ in range(n)]
    for i in range(n):
        mi = M[i]
        oi = out[i]
        for j in range(n):
            w = mi[j]
            if w == 0.0:
                continue
            xj = X[j]
            for k in range(f):
                oi[k] += w * xj[k]
    return out


def _g_matmul_t(M, D):
    """(N x N)^T @ (N x F)"""
    n = len(M)
    f = len(D[0])
    out = [[0.0] * f for _ in range(n)]
    for i in range(n):
        oi = out[i]
        for j in range(n):
            w = M[j][i]
            if w == 0.0:
                continue
            dj = D[j]
            for k in range(f):
                oi[k] += w * dj[k]
    return out


class _GDense:
    """图网络内部的小型全连接层（自带梯度与优化器状态）"""

    def __init__(self, fan_in: int, fan_out: int, rng, std: Optional[float] = None):
        self.fan_in = fan_in
        self.fan_out = fan_out
        scale = (1.0 / math.sqrt(max(1, fan_in))) if std is None else float(std)
        self.W = [[rng.gauss(0.0, scale) for _ in range(fan_in)]
                  for _ in range(fan_out)]
        self.b = [0.0] * fan_out
        self.gW = [[0.0] * fan_in for _ in range(fan_out)]
        self.gb = [0.0] * fan_out
        self.mW = [[0.0] * fan_in for _ in range(fan_out)]
        self.vW = [[0.0] * fan_in for _ in range(fan_out)]
        self.mb = [0.0] * fan_out
        self.vb = [0.0] * fan_out
        self._t = 0
        self._x = None

    def forward(self, X):
        self._x = [list(r) for r in X]
        out = []
        for row in X:
            o = list(self.b)
            for k in range(self.fan_in):
                v = row[k]
                if v == 0.0:
                    continue
                for h in range(self.fan_out):
                    o[h] += self.W[h][k] * v
            out.append(o)
        return out

    def backward(self, dout):
        x = self._x
        n = len(x)
        for h in range(self.fan_out):
            gh = self.gW[h]
            for k in range(self.fan_in):
                acc = 0.0
                for i in range(n):
                    acc += dout[i][h] * x[i][k]
                gh[k] += acc
        for h in range(self.fan_out):
            acc = 0.0
            for i in range(n):
                acc += dout[i][h]
            self.gb[h] += acc
        dx = [[0.0] * self.fan_in for _ in range(n)]
        for i in range(n):
            di = dout[i]
            dxi = dx[i]
            for h in range(self.fan_out):
                w = di[h]
                if w == 0.0:
                    continue
                wh = self.W[h]
                for k in range(self.fan_in):
                    dxi[k] += w * wh[k]
        return dx

    def zero_grad(self):
        self.gW = [[0.0] * self.fan_in for _ in range(self.fan_out)]
        self.gb = [0.0] * self.fan_out

    def param_count(self) -> int:
        return self.fan_in * self.fan_out + self.fan_out

    def sgd_step(self, lr: float):
        lr = _la_check_lr(lr, '_GDense.sgd_step')
        _la_apply_sgd(self.W, self.gW, lr)
        _la_apply_sgd(self.b, self.gb, lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        lr = _la_check_lr(lr, '_GDense.adam_step')
        _check_adam_betas(beta1, beta2, '_GDense.adam_step')
        self._t += 1
        c1 = 1.0 - beta1 ** self._t
        c2 = 1.0 - beta2 ** self._t
        _la_apply_adam(self.W, self.gW, self.mW, self.vW, lr, c1, c2,
                       beta1, beta2, eps)
        _la_apply_adam(self.b, self.gb, self.mb, self.vb, lr, c1, c2,
                       beta1, beta2, eps)


class GCNLayer:
    """图卷积：``H = sigma(A_hat X W + b)``，``A_hat = D^{-1/2}(A+I)D^{-1/2}``

    ``adj`` 是 ``N x N`` 的加权密集矩阵。邻接矩阵不参与反向（视为常量）。
    """

    def __init__(self, in_features: int, out_features: int,
                 activation: str = 'relu', self_loops: bool = True,
                 bias: bool = True, seed: int = 0):
        _ck_int(in_features, 'GCNLayer(in_features)', 1)
        _ck_int(out_features, 'GCNLayer(out_features)', 1)
        self.in_features = in_features
        self.out_features = out_features
        self.activation_name = activation
        self.self_loops = bool(self_loops)
        self.act_fn, self.act_deriv = _g_act(activation)
        self.dense = _GDense(in_features, out_features, random.Random(seed))
        self._cache = None

    def forward(self, X, adj):
        n = _g_check_x(X, 'GCNLayer.forward')
        _g_check_adj(adj, n, 'GCNLayer.forward')
        an = _g_adj_norm(adj, self.self_loops)
        ax = _g_matmul(an, X)
        z = self.dense.forward(ax)
        out = [self.act_fn(z[i]) for i in range(n)] if self.act_fn else z
        self._cache = (an, ax, z)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError('GCNLayer.backward: 需要先 forward')
        an, ax, z = self._cache
        n = len(dout)
        dz = ([_g_scale_rows(self.act_deriv(z[i]), dout[i]) for i in range(n)]
              if self.act_fn else dout)
        dax = self.dense.backward(dz)
        return _g_matmul_t(an, dax)

    def zero_grad(self):
        self.dense.zero_grad()

    def param_count(self) -> int:
        return self.dense.param_count()

    def sgd_step(self, lr: float):
        self.dense.sgd_step(lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        self.dense.adam_step(lr, beta1, beta2, eps)

    def train(self):
        return self

    def eval(self):
        return self


class GraphSAGELayer:
    """GraphSAGE 的均值聚合：``h_i' = sigma(W [x_i || mean_{j in N(i)} x_j])``

    ``concat=True`` 时把自特征与邻居均值拼起来（2F），否则只用邻居均值（F）。
    """

    def __init__(self, in_features: int, out_features: int,
                 activation: str = 'relu', concat: bool = True,
                 self_loops: bool = False, seed: int = 0):
        _ck_int(in_features, 'GraphSAGELayer(in_features)', 1)
        _ck_int(out_features, 'GraphSAGELayer(out_features)', 1)
        self.in_features = in_features
        self.out_features = out_features
        self.activation_name = activation
        self.concat = bool(concat)
        self.self_loops = bool(self_loops)
        self.act_fn, self.act_deriv = _g_act(activation)
        width = in_features * 2 if self.concat else in_features
        self.dense = _GDense(width, out_features, random.Random(seed + 1))
        self._cache = None

    def forward(self, X, adj):
        n = _g_check_x(X, 'GraphSAGELayer.forward')
        _g_check_adj(adj, n, 'GraphSAGELayer.forward')
        a = [list(r) for r in adj]
        if self.self_loops:
            for i in range(n):
                a[i][i] += 1.0
        rn = _g_row_mean(a)
        mean = _g_matmul(rn, X)
        cat = [[mean[i][k] for k in range(self.in_features)]
               + ([X[i][k] for k in range(self.in_features)] if self.concat else [])
               for i in range(n)]
        z = self.dense.forward(cat)
        out = [self.act_fn(z[i]) for i in range(n)] if self.act_fn else z
        self._cache = (rn, mean, z)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError('GraphSAGELayer.backward: 需要先 forward')
        rn, mean, z = self._cache
        n = len(dout)
        dz = ([_g_scale_rows(self.act_deriv(z[i]), dout[i]) for i in range(n)]
              if self.act_fn else dout)
        dcat = self.dense.backward(dz)
        f = self.in_features
        dmean = [[dcat[i][k] for k in range(f)] for i in range(n)]
        dself = ([[dcat[i][f + k] for k in range(f)] for i in range(n)]
                 if self.concat else [[0.0] * f for _ in range(n)])
        dm = _g_matmul_t(rn, dmean)
        return [[dm[i][k] + dself[i][k] for k in range(f)] for i in range(n)]

    def zero_grad(self):
        self.dense.zero_grad()

    def param_count(self) -> int:
        return self.dense.param_count()

    def sgd_step(self, lr: float):
        self.dense.sgd_step(lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        self.dense.adam_step(lr, beta1, beta2, eps)

    def train(self):
        return self

    def eval(self):
        return self


class GINLayer:
    """GIN：``h_i' = MLP((1 + eps) x_i + sum_{j in N(i)} x_j)``

    ``eps`` 默认不可学（``train_eps=False``），打开后作为标量参数参与优化。
    """

    def __init__(self, in_features: int, hidden: int, out_features: int,
                 activation: str = 'relu', eps: float = 0.0,
                 train_eps: bool = False, seed: int = 0):
        _ck_int(in_features, 'GINLayer(in_features)', 1)
        _ck_int(hidden, 'GINLayer(hidden)', 1)
        _ck_int(out_features, 'GINLayer(out_features)', 1)
        if not _is_num(eps):
            raise ValueError('GINLayer: eps 必须是有限数字')
        rng = random.Random(seed + 2)
        self.activation_name = activation
        self.act_fn, self.act_deriv = _g_act(activation)
        self.l1 = _GDense(in_features, hidden, rng)
        self.l2 = _GDense(hidden, out_features, rng)
        self.train_eps = bool(train_eps)
        self._eps = [float(eps)]
        self.g_eps = [0.0]
        self.m_eps = [0.0]
        self.v_eps = [0.0]
        self._cache = None

    def forward(self, X, adj):
        n = _g_check_x(X, 'GINLayer.forward')
        _g_check_adj(adj, n, 'GINLayer.forward')
        f = len(X[0])
        agg = [[0.0] * f for _ in range(n)]
        for i in range(n):
            for j in range(n):
                w = adj[i][j]
                if w == 0.0:
                    continue
                xj = X[j]
                ai = agg[i]
                for k in range(f):
                    ai[k] += w * xj[k]
        eps = self._eps[0]
        h = [[(1.0 + eps) * X[i][k] + agg[i][k] for k in range(f)]
             for i in range(n)]
        z1 = self.l1.forward(h)
        a1 = [self.act_fn(z1[i]) for i in range(n)] if self.act_fn else z1
        out = self.l2.forward(a1)
        self._cache = (X, agg, h, z1, a1, [list(r) for r in adj])
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError('GINLayer.backward: 需要先 forward')
        X, agg, h, z1, a1, adj = self._cache
        n = len(dout)
        da1 = self.l2.backward(dout)
        dz1 = ([_g_scale_rows(self.act_deriv(z1[i]), da1[i]) for i in range(n)]
               if self.act_fn else da1)
        dh = self.l1.backward(dz1)
        f = len(X[0])
        eps = self._eps[0]
        g_eps = 0.0
        for i in range(n):
            for k in range(f):
                g_eps += dh[i][k] * X[i][k]
        self.g_eps[0] += g_eps
        # 对邻居的贡献：agg[i] 由 x_j 汇总而来 -> 按 adj 反向散射
        dx = [[(1.0 + eps) * dh[i][k] for k in range(f)] for i in range(n)]
        for i in range(n):
            dhi = dh[i]
            for j in range(n):
                w = adj[i][j]
                if w == 0.0:
                    continue
                dxj = dx[j]
                for k in range(f):
                    dxj[k] += w * dhi[k]
        if not self.train_eps:
            self.g_eps[0] = 0.0
        return dx

    def zero_grad(self):
        self.l1.zero_grad()
        self.l2.zero_grad()
        self.g_eps[0] = 0.0

    def param_count(self) -> int:
        return self.l1.param_count() + self.l2.param_count() + (
            1 if self.train_eps else 0)

    def sgd_step(self, lr: float):
        lr = _la_check_lr(lr, 'GINLayer.sgd_step')
        self.l1.sgd_step(lr)
        self.l2.sgd_step(lr)
        if self.train_eps:
            _la_apply_sgd(self._eps, self.g_eps, lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        lr = _la_check_lr(lr, 'GINLayer.adam_step')
        self.l1.adam_step(lr, beta1, beta2, eps)
        self.l2.adam_step(lr, beta1, beta2, eps)
        if self.train_eps:
            _check_adam_betas(beta1, beta2, 'GINLayer.adam_step')
            self._eps_t = getattr(self, '_eps_t', 0) + 1
            c1 = 1.0 - beta1 ** self._eps_t
            c2 = 1.0 - beta2 ** self._eps_t
            _la_apply_adam(self._eps, self.g_eps, self.m_eps, self.v_eps,
                           lr, c1, c2, beta1, beta2, eps)

    def train(self):
        return self

    def eval(self):
        return self


class GraphReadout:
    """图级读出：把 ``N x F`` 的节点特征聚成一个 ``F`` 维向量。

    ``mode='mean'`` / ``'sum'`` / ``'max'``。反向按模式分发梯度
    （max 只回传给取到最大值的位置）。
    """

    def __init__(self, mode: str = 'mean'):
        if mode not in ('mean', 'sum', 'max'):
            raise ValueError("GraphReadout: mode 只能是 'mean'/'sum'/'max'")
        self.mode = mode
        self._cache = None

    def forward(self, X):
        n = _g_check_x(X, 'GraphReadout.forward')
        f = len(X[0])
        if self.mode == 'sum':
            out = [sum(X[i][k] for i in range(n)) for k in range(f)]
            self._cache = (n, None)
        elif self.mode == 'mean':
            out = [sum(X[i][k] for i in range(n)) / n for k in range(f)]
            self._cache = (n, None)
        else:
            out = []
            arg = []
            for k in range(f):
                best = X[0][k]
                pos = 0
                for i in range(1, n):
                    if X[i][k] > best:
                        best = X[i][k]
                        pos = i
                out.append(best)
                arg.append(pos)
            self._cache = (n, arg)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError('GraphReadout.backward: 需要先 forward')
        n, arg = self._cache
        f = len(dout)
        if self.mode == 'sum':
            return [[dout[k] for k in range(f)] for _ in range(n)]
        if self.mode == 'mean':
            return [[dout[k] / n for k in range(f)] for _ in range(n)]
        dx = [[0.0] * f for _ in range(n)]
        for k in range(f):
            dx[arg[k]][k] += dout[k]
        return dx

    def zero_grad(self):
        pass

    def param_count(self) -> int:
        return 0

    def sgd_step(self, lr: float):
        pass

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        pass

    def train(self):
        return self

    def eval(self):
        return self


def _g_zeros(shape):
    """按 tuple 形状造嵌套零列表"""
    if len(shape) == 1:
        return [0.0] * shape[0]
    return [_g_zeros(shape[1:]) for _ in range(shape[0])]


class GATLayer:
    """图注意力（单图、多头）：``alpha_ij = softmax_j(LeakyReLU(a_s·z_i + a_d·z_j))``

    ``adj[i][j] > 0`` 视为存在边（**权重本身不参与** softmax，只当存在性用，
    权重图请改用 ``GCNLayer``）；默认把自环加进邻居集合。多头输出默认拼接，
    ``concat=False`` 时取平均。
    """

    def __init__(self, in_features: int, out_features: int, num_heads: int = 1,
                 activation: str = 'elu', negative_slope: float = 0.2,
                 concat: bool = True, self_loops: bool = True, seed: int = 0):
        _ck_int(in_features, 'GATLayer(in_features)', 1)
        _ck_int(out_features, 'GATLayer(out_features)', 1)
        _ck_int(num_heads, 'GATLayer(num_heads)', 1)
        if not _is_num(negative_slope) or negative_slope <= 0.0:
            raise ValueError('GATLayer: negative_slope 必须是正有限数字')
        rng = random.Random(seed + 21)
        self.in_features = in_features
        self.out_features = out_features
        self.num_heads = num_heads
        self.concat = bool(concat)
        self.self_loops = bool(self_loops)
        self.negative_slope = float(negative_slope)
        self.activation_name = activation
        if activation == 'linear':
            self.act_fn, self.act_deriv = None, None
        else:
            self.act_fn, self.act_deriv = _g_act(activation)
        width = out_features * num_heads
        self.width = width
        std = 1.0 / math.sqrt(max(1, in_features))
        self.W = [[[rng.gauss(0.0, std) for _ in range(in_features)]
                   for _ in range(out_features)] for _ in range(num_heads)]
        self.b = [[0.0] * out_features for _ in range(num_heads)]
        self.a_src = [[rng.gauss(0.0, std) for _ in range(out_features)]
                      for _ in range(num_heads)]
        self.a_dst = [[rng.gauss(0.0, std) for _ in range(out_features)]
                      for _ in range(num_heads)]
        self.gW = [[[0.0] * in_features for _ in range(out_features)]
                   for _ in range(num_heads)]
        self.gb = [[0.0] * out_features for _ in range(num_heads)]
        self.ga_src = [[0.0] * out_features for _ in range(num_heads)]
        self.ga_dst = [[0.0] * out_features for _ in range(num_heads)]
        self._m = {}
        self._v = {}
        self._t = 0
        self._init_adam()
        self._cache = None

    def _init_adam(self):
        for name, shape in (('W', (self.num_heads, self.out_features, self.in_features)),
                            ('b', (self.num_heads, self.out_features)),
                            ('a_src', (self.num_heads, self.out_features)),
                            ('a_dst', (self.num_heads, self.out_features))):
            self._m[name] = _g_zeros(shape)
            self._v[name] = _g_zeros(shape)

    def forward(self, X, adj):
        n = _g_check_x(X, 'GATLayer.forward')
        _g_check_adj(adj, n, 'GATLayer.forward')
        neigh = []
        for i in range(n):
            nb = [j for j in range(n) if adj[i][j] > 0.0]
            if self.self_loops and i not in nb:
                nb = sorted(nb + [i])
            if not nb:
                nb = [i]
            neigh.append(nb)
        zs = []
        alphas = []
        ctxs = []
        for h in range(self.num_heads):
            Wh, bh = self.W[h], self.b[h]
            z = [[sum(Wh[r][k] * X[i][k] for k in range(self.in_features)) + bh[r]
                  for r in range(self.out_features)] for i in range(n)]
            al = [[0.0] * n for _ in range(n)]
            for i in range(n):
                nb = neigh[i]
                sc = []
                zi = z[i]
                for j in nb:
                    zj = z[j]
                    asum = 0.0
                    dsum = 0.0
                    for r in range(self.out_features):
                        asum += self.a_src[h][r] * zi[r]
                        dsum += self.a_dst[h][r] * zj[r]
                    v = asum + dsum
                    sc.append(v if v >= 0.0 else self.negative_slope * v)
                mx = max(sc)
                ex = [math.exp(v - mx) for v in sc]
                tot = sum(ex)
                for pos, j in enumerate(nb):
                    al[i][j] = ex[pos] / tot
            ctx = [[0.0] * self.out_features for _ in range(n)]
            for i in range(n):
                for j in neigh[i]:
                    w = al[i][j]
                    if w == 0.0:
                        continue
                    zj = z[j]
                    ci = ctx[i]
                    for r in range(self.out_features):
                        ci[r] += w * zj[r]
            zs.append(z)
            alphas.append(al)
            ctxs.append(ctx)
        if self.concat:
            cat = [[0.0] * self.width for _ in range(n)]
            for h in range(self.num_heads):
                for i in range(n):
                    for r in range(self.out_features):
                        cat[i][h * self.out_features + r] = ctxs[h][i][r]
            out = [self.act_fn(cat[i]) if self.act_fn else cat[i] for i in range(n)]
            self._cache = (X, neigh, zs, alphas, cat, 'concat')
        else:
            avg = [[0.0] * self.out_features for _ in range(n)]
            for h in range(self.num_heads):
                for i in range(n):
                    for r in range(self.out_features):
                        avg[i][r] += ctxs[h][i][r] / self.num_heads
            out = [self.act_fn(avg[i]) if self.act_fn else avg[i] for i in range(n)]
            self._cache = (X, neigh, zs, alphas, avg, 'mean')
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError('GATLayer.backward: 需要先 forward')
        X, neigh, zs, alphas, agg, mode = self._cache
        n = len(dout)
        if self.act_fn:
            pre = agg
            dagg = [_g_scale_rows(self.act_deriv(pre[i]), dout[i]) for i in range(n)]
        else:
            dagg = [list(r) for r in dout]
        dz_all = [[[0.0] * self.out_features for _ in range(n)]
                  for _ in range(self.num_heads)]
        for h in range(self.num_heads):
            z = zs[h]
            al = alphas[h]
            scale = 1.0 if mode == 'concat' else 1.0 / self.num_heads
            dctx = []
            for i in range(n):
                if mode == 'concat':
                    dctx.append([dagg[i][h * self.out_features + r]
                                 for r in range(self.out_features)])
                else:
                    dctx.append([dagg[i][r] * scale for r in range(self.out_features)])
            # dv 只依赖 alpha；ds 走 softmax 雅可比
            for i in range(n):
                nb = neigh[i]
                dalpha = []
                for j in nb:
                    zj = z[j]
                    acc = 0.0
                    for r in range(self.out_features):
                        acc += dctx[i][r] * zj[r]
                    dalpha.append(acc)
                for pos, j in enumerate(nb):
                    w = al[i][j]
                    if w == 0.0:
                        continue
                    zj = z[j]
                    dzj = dz_all[h][j]
                    for r in range(self.out_features):
                        dzj[r] += w * dctx[i][r]
                    total = 0.0
                    for q in range(len(nb)):
                        total += al[i][nb[q]] * dalpha[q]
                    ds = w * (dalpha[pos] - total)
                    zi = z[i]
                    pre = 0.0
                    for r2 in range(self.out_features):
                        pre += self.a_src[h][r2] * zi[r2] + self.a_dst[h][r2] * zj[r2]
                    slope = 1.0 if pre >= 0.0 else self.negative_slope
                    dsl = ds * slope
                    for r in range(self.out_features):
                        self.ga_src[h][r] += dsl * zi[r]
                        self.ga_dst[h][r] += dsl * zj[r]
                    dzi = dz_all[h][i]
                    for r in range(self.out_features):
                        dzi[r] += dsl * self.a_src[h][r]
                        dzj[r] += dsl * self.a_dst[h][r]
        dx = [[0.0] * self.in_features for _ in range(n)]
        for h in range(self.num_heads):
            Wh = self.W[h]
            for i in range(n):
                dzi = dz_all[h][i]
                for r in range(self.out_features):
                    g = dzi[r]
                    if g == 0.0:
                        continue
                    self.gW[h][r] = [self.gW[h][r][k] + g * X[i][k]
                                     for k in range(self.in_features)]
                    self.gb[h][r] += g
                    for k in range(self.in_features):
                        dx[i][k] += g * Wh[r][k]
        return dx

    def zero_grad(self):
        self.gW = [[[0.0] * self.in_features for _ in range(self.out_features)]
                   for _ in range(self.num_heads)]
        self.gb = [[0.0] * self.out_features for _ in range(self.num_heads)]
        self.ga_src = [[0.0] * self.out_features for _ in range(self.num_heads)]
        self.ga_dst = [[0.0] * self.out_features for _ in range(self.num_heads)]

    def param_count(self) -> int:
        per = self.out_features * self.in_features + self.out_features
        return self.num_heads * (per + 2 * self.out_features)

    def sgd_step(self, lr: float):
        lr = _la_check_lr(lr, 'GATLayer.sgd_step')
        for h in range(self.num_heads):
            _la_apply_sgd(self.W[h], self.gW[h], lr)
            _la_apply_sgd(self.b[h], self.gb[h], lr)
            _la_apply_sgd(self.a_src[h], self.ga_src[h], lr)
            _la_apply_sgd(self.a_dst[h], self.ga_dst[h], lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        lr = _la_check_lr(lr, 'GATLayer.adam_step')
        _check_adam_betas(beta1, beta2, 'GATLayer.adam_step')
        self._t += 1
        c1 = 1.0 - beta1 ** self._t
        c2 = 1.0 - beta2 ** self._t
        for h in range(self.num_heads):
            _la_apply_adam(self.W[h], self.gW[h], self._m['W'][h], self._v['W'][h],
                           lr, c1, c2, beta1, beta2, eps)
            _la_apply_adam(self.b[h], self.gb[h], self._m['b'][h], self._v['b'][h],
                           lr, c1, c2, beta1, beta2, eps)
            _la_apply_adam(self.a_src[h], self.ga_src[h], self._m['a_src'][h],
                           self._v['a_src'][h], lr, c1, c2, beta1, beta2, eps)
            _la_apply_adam(self.a_dst[h], self.ga_dst[h], self._m['a_dst'][h],
                           self._v['a_dst'][h], lr, c1, c2, beta1, beta2, eps)

    def train(self):
        return self

    def eval(self):
        return self


class APPNPLayer:
    """APPNP：``H0 = σ(XW+b)``，``H^{k+1} = (1-alpha) Â H^k + alpha H0``，输出 ``H^K``"""

    def __init__(self, in_features: int, out_features: int, K: int = 2,
                 alpha: float = 0.1, activation: str = 'relu',
                 self_loops: bool = True, seed: int = 0):
        _ck_int(in_features, 'APPNPLayer(in_features)', 1)
        _ck_int(out_features, 'APPNPLayer(out_features)', 1)
        _ck_int(K, 'APPNPLayer(K)', 1)
        if not _is_num(alpha) or not (0.0 <= alpha <= 1.0):
            raise ValueError('APPNPLayer: alpha 必须在 [0, 1] 内')
        self.in_features = in_features
        self.out_features = out_features
        self.K = K
        self.alpha = float(alpha)
        self.self_loops = bool(self_loops)
        self.activation_name = activation
        if activation == 'linear':
            self.act_fn, self.act_deriv = None, None
        else:
            self.act_fn, self.act_deriv = _g_act(activation)
        self.dense = _GDense(in_features, out_features, random.Random(seed + 31))
        self._cache = None

    def forward(self, X, adj):
        n = _g_check_x(X, 'APPNPLayer.forward')
        _g_check_adj(adj, n, 'APPNPLayer.forward')
        an = _g_adj_norm(adj, self.self_loops)
        z0 = self.dense.forward(X)
        h0 = [self.act_fn(z0[i]) if self.act_fn else list(z0[i]) for i in range(n)]
        hs = [h0]
        for _ in range(self.K):
            prev = hs[-1]
            ah = _g_matmul(an, prev)
            hs.append([[(1.0 - self.alpha) * ah[i][r] + self.alpha * h0[i][r]
                        for r in range(self.out_features)] for i in range(n)])
        self._cache = (an, z0, hs)
        return hs[-1]

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError('APPNPLayer.backward: 需要先 forward')
        an, z0, hs = self._cache
        n = len(dout)
        f = self.out_features
        dh = [list(dout[i]) for i in range(n)]
        dh0_extra = [[0.0] * f for _ in range(n)]
        for k in range(self.K - 1, -1, -1):
            # H^{k+1} = (1-a) Â H^k + a H0
            trans = _g_matmul_t(an, dh)
            for i in range(n):
                for r in range(f):
                    dh0_extra[i][r] += self.alpha * dh[i][r]
                    trans[i][r] *= (1.0 - self.alpha)
            dh = trans
        for i in range(n):
            for r in range(f):
                dh[i][r] += dh0_extra[i][r]
        if self.act_fn:
            dz0 = [_g_scale_rows(self.act_deriv(z0[i]), dh[i]) for i in range(n)]
        else:
            dz0 = dh
        return self.dense.backward(dz0)

    def zero_grad(self):
        self.dense.zero_grad()

    def param_count(self) -> int:
        return self.dense.param_count()

    def sgd_step(self, lr: float):
        self.dense.sgd_step(lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        self.dense.adam_step(lr, beta1, beta2, eps)

    def train(self):
        return self

    def eval(self):
        return self


class JKNet:
    """JK-Net：把多层输出按 ``mode`` 汇总（``concat`` / ``last`` / ``max``）

    逐层用同一份 ``adj`` 传播（每层吃上一层的输出），然后把 ``layers`` 的输出
    汇总。``backward`` 需要把汇总的梯度按模式拆回各层再依次回传。
    """

    def __init__(self, layers, mode: str = 'concat'):
        if not isinstance(layers, (list, tuple)) or not layers:
            raise ValueError('JKNet: layers 必须是非空列表')
        for k, lyr in enumerate(layers):
            if not hasattr(lyr, 'forward') or not hasattr(lyr, 'backward'):
                raise TypeError('JKNet: 第 %d 个元素不是可用的图网络层' % k)
        if mode not in ('concat', 'last', 'max'):
            raise ValueError("JKNet: mode 只能是 'concat'/'last'/'max'")
        self.layers = list(layers)
        self.mode = mode
        self._cache = None

    def forward(self, X, adj):
        n = _g_check_x(X, 'JKNet.forward')
        _g_check_adj(adj, n, 'JKNet.forward')
        h = X
        outs = []
        for lyr in self.layers:
            h = lyr.forward(h, adj)
            outs.append(h)
        if self.mode == 'last':
            out = outs[-1]
        elif self.mode == 'concat':
            out = []
            for i in range(n):
                row = []
                for o in outs:
                    row.extend(o[i])
                out.append(row)
        else:
            out = []
            for i in range(n):
                row = list(outs[0][i])
                for o in outs[1:]:
                    for r in range(len(row)):
                        if o[i][r] > row[r]:
                            row[r] = o[i][r]
                out.append(row)
        self._cache = (outs, n)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError('JKNet.backward: 需要先 forward')
        outs, n = self._cache
        grads = []
        if self.mode == 'last':
            grads = [None] * (len(outs) - 1) + [dout]
        else:
            widths = [len(o[0]) for o in outs]
            if self.mode == 'concat':
                for idx in range(len(outs)):
                    off = sum(widths[:idx])
                    grads.append([[dout[i][off + r] for r in range(widths[idx])]
                                  for i in range(n)])
            else:
                for idx in range(len(outs)):
                    g = []
                    for i in range(n):
                        row = []
                        for r in range(widths[idx]):
                            best = outs[0][i][r]
                            who = 0
                            for k2 in range(1, len(outs)):
                                if outs[k2][i][r] > best:
                                    best = outs[k2][i][r]
                                    who = k2
                            row.append(dout[i][r] if who == idx else 0.0)
                        g.append(row)
                    grads.append(g)
        # 从后往前携带：第 k 层的输入梯度就是第 k-1 层输出的额外梯度
        carry = None
        for idx in range(len(self.layers) - 1, -1, -1):
            g = grads[idx]
            if g is None:
                total = carry
            elif carry is None:
                total = g
            else:
                total = [[g[i][k2] + carry[i][k2] for k2 in range(len(g[i]))]
                         for i in range(n)]
            if total is None:
                continue
            carry = self.layers[idx].backward(total)
        return carry

    def zero_grad(self):
        for lyr in self.layers:
            lyr.zero_grad()

    def param_count(self) -> int:
        return sum(lyr.param_count() for lyr in self.layers)

    def sgd_step(self, lr: float):
        for lyr in self.layers:
            lyr.sgd_step(lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        for lyr in self.layers:
            lyr.adam_step(lr, beta1, beta2, eps)

    def train(self):
        for lyr in self.layers:
            lyr.train()
        return self

    def eval(self):
        for lyr in self.layers:
            lyr.eval()
        return self


class MPNNLayer:
    """消息传递网络（MPNN）：``m_ij = MLP_msg([x_i || x_j || e_ij])``、
    ``agg_i = Aggregate_{j in N(i)} m_ij``、``h_i = MLP_upd([x_i || agg_i])``

    ``adj[i][j] > 0`` 只表示存在边（权重不参与计算）；``edge`` 是可选密集
    边特征 ``edge[i][j]``（长度 ``edge_features`` 的向量），视为常量不反向。
    ``aggregation`` 支持 ``sum`` / ``mean``。
    """

    def __init__(self, in_features: int, hidden: int, out_features: int,
                 edge_features: int = 0, activation: str = 'relu',
                 aggregation: str = 'sum', seed: int = 0):
        _ck_int(in_features, 'MPNNLayer(in_features)', 1)
        _ck_int(hidden, 'MPNNLayer(hidden)', 1)
        _ck_int(out_features, 'MPNNLayer(out_features)', 1)
        _ck_int(edge_features, 'MPNNLayer(edge_features)', 0)
        if aggregation not in ('sum', 'mean'):
            raise ValueError("MPNNLayer(aggregation) 只支持 'sum' 或 'mean'，"
                             "收到 %r" % (aggregation,))
        self.in_features = in_features
        self.hidden = hidden
        self.out_features = out_features
        self.edge_features = edge_features
        self.aggregation = aggregation
        self.activation_name = activation
        self.act_fn, self.act_deriv = _g_act(activation)
        rng = random.Random(seed)
        self.msg1 = _GDense(2 * in_features + edge_features, hidden, rng)
        self.msg2 = _GDense(hidden, out_features, rng)
        self.upd1 = _GDense(in_features + out_features, hidden, rng)
        self.upd2 = _GDense(hidden, out_features, rng)
        self._cache = None

    def forward(self, X, adj, edge=None):
        n = _g_check_x(X, 'MPNNLayer.forward')
        _g_check_adj(adj, n, 'MPNNLayer.forward')
        E = self.edge_features
        if E:
            if not isinstance(edge, list) or len(edge) != n:
                raise ValueError('MPNNLayer.forward: 需要 N x N 的边特征矩阵')
            for row in edge:
                if not isinstance(row, list) or len(row) != n:
                    raise ValueError('MPNNLayer.forward: 边特征矩阵不是 N x N')
                for cell in row:
                    if not isinstance(cell, list) or len(cell) != E:
                        raise ValueError(
                            'MPNNLayer.forward: 每个 edge[i][j] 要有 %d 个分量' % E)
                    for v in cell:
                        if not _is_num(v):
                            raise ValueError('MPNNLayer.forward: 边特征必须是有限数字')
        pairs = []
        inputs = []
        for i in range(n):
            for j in range(n):
                if adj[i][j] > 0.0:
                    row = list(X[i]) + list(X[j])
                    if E:
                        row += [float(v) for v in edge[i][j]]
                    inputs.append(row)
                    pairs.append((i, j))
        if pairs:
            z1 = self.msg1.forward(inputs)
            a1 = [self.act_fn(r) for r in z1]
            z2 = self.msg2.forward(a1)
            msgs = [self.act_fn(r) for r in z2]
        else:
            z1, a1, z2, msgs = [], [], [], []
        agg = [[0.0] * self.out_features for _ in range(n)]
        cnt = [0] * n
        for p, (i, j) in enumerate(pairs):
            cnt[i] += 1
            m = msgs[p]
            for r in range(self.out_features):
                agg[i][r] += m[r]
        if self.aggregation == 'mean':
            for i in range(n):
                c = cnt[i]
                if c:
                    for r in range(self.out_features):
                        agg[i][r] /= c
        uin = [[X[i][k] for k in range(self.in_features)]
               + agg[i] for i in range(n)]
        z_u1 = self.upd1.forward(uin)
        a_u1 = [self.act_fn(r) for r in z_u1]
        z_u2 = self.upd2.forward(a_u1)
        out = [self.act_fn(r) for r in z_u2]
        self._cache = (pairs, cnt, z1, z2, z_u1, z_u2)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError('MPNNLayer.backward: 需要先 forward')
        pairs, cnt, z1, z2, z_u1, z_u2 = self._cache
        n = len(dout)
        inf = self.in_features
        dz_u2 = [_g_scale_rows(self.act_deriv(z_u2[i]), dout[i])
                 for i in range(n)]
        da_u1 = self.upd2.backward(dz_u2)
        dz_u1 = [_g_scale_rows(self.act_deriv(z_u1[i]), da_u1[i])
                 for i in range(n)]
        duin = self.upd1.backward(dz_u1)
        dX = [[duin[i][k] for k in range(inf)] for i in range(n)]
        dagg = [[duin[i][inf + r] for r in range(self.out_features)]
                for i in range(n)]
        if self.aggregation == 'mean':
            for i in range(n):
                c = cnt[i]
                if c:
                    for r in range(self.out_features):
                        dagg[i][r] /= c
        P = len(pairs)
        dmsg = [list(dagg[i]) for (i, _j) in pairs]
        dz2 = [_g_scale_rows(self.act_deriv(z2[p]), dmsg[p]) for p in range(P)]
        da1 = self.msg2.backward(dz2) if P else []
        dz1 = [_g_scale_rows(self.act_deriv(z1[p]), da1[p]) for p in range(P)]
        dinp = self.msg1.backward(dz1) if P else []
        for p, (i, j) in enumerate(pairs):
            row = dinp[p]
            for k in range(inf):
                dX[i][k] += row[k]
                dX[j][k] += row[inf + k]
        return dX

    def zero_grad(self):
        for layer in (self.msg1, self.msg2, self.upd1, self.upd2):
            layer.zero_grad()

    def param_count(self) -> int:
        return sum(layer.param_count()
                   for layer in (self.msg1, self.msg2, self.upd1, self.upd2))

    def sgd_step(self, lr: float):
        for layer in (self.msg1, self.msg2, self.upd1, self.upd2):
            layer.sgd_step(lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        for layer in (self.msg1, self.msg2, self.upd1, self.upd2):
            layer.adam_step(lr, beta1, beta2, eps)

    def train(self):
        return self

    def eval(self):
        return self


class GCNIILayer:
    """GCNII：``H^{l+1} = sigma(((1-alpha) A_hat H^l + alpha H^0)((1-beta_l) I + beta_l W))``

    ``beta_l = log(lam / l + 1)``（``layer_index`` 即 l）。与原始论文一致，
    要求输入输出同宽（各层共享宽度），``H^0`` 由调用方作为第三个参数传入
    （缺省用本层输入）。
    """

    def __init__(self, in_features: int, alpha: float = 0.1, lam: float = 0.5,
                 layer_index: int = 0, activation: str = 'relu',
                 self_loops: bool = True, seed: int = 0):
        _ck_int(in_features, 'GCNIILayer(in_features)', 1)
        if not _is_num(alpha) or not (0.0 <= float(alpha) <= 1.0):
            raise ValueError('GCNIILayer(alpha) 必须是 [0, 1] 内的有限数字')
        if not _is_num(lam) or float(lam) < 0.0:
            raise ValueError('GCNIILayer(lam) 必须是非负有限数字')
        _ck_int(layer_index, 'GCNIILayer(layer_index)', 0)
        d = in_features
        self.in_features = d
        self.out_features = d
        self.alpha = float(alpha)
        self.lam = float(lam)
        self.layer_index = layer_index
        self.self_loops = bool(self_loops)
        self.activation_name = activation
        self.act_fn, self.act_deriv = _g_act(activation)
        rng = random.Random(seed)
        scale = 1.0 / math.sqrt(d)
        self.W = [[rng.gauss(0.0, scale) for _ in range(d)] for _ in range(d)]
        self.gW = [[0.0] * d for _ in range(d)]
        self.mW = [[0.0] * d for _ in range(d)]
        self.vW = [[0.0] * d for _ in range(d)]
        self._t = 0
        self.grad_h0 = [[0.0] * d for _ in range(0)]
        self._cache = None

    def beta(self) -> float:
        return math.log(self.lam / (self.layer_index + 1.0) + 1.0)

    def _mix_matrix(self):
        b = self.beta()
        d = self.in_features
        M = []
        for a in range(d):
            row = []
            for c in range(d):
                v = b * self.W[a][c]
                if a == c:
                    v += 1.0 - b
                row.append(v)
            M.append(row)
        return M

    def forward(self, X, adj, H0=None):
        n = _g_check_x(X, 'GCNIILayer.forward')
        _g_check_adj(adj, n, 'GCNIILayer.forward')
        d = self.in_features
        if H0 is None:
            H0 = X
        if not isinstance(H0, list) or len(H0) != n:
            raise ValueError('GCNIILayer.forward: H0 要有 %d 行' % n)
        for row in H0:
            if not isinstance(row, list) or len(row) != d:
                raise ValueError('GCNIILayer.forward: H0 每行要有 %d 个分量' % d)
        an = _g_adj_norm(adj, self.self_loops)
        ax = _g_matmul(an, X)
        mix = [[(1.0 - self.alpha) * ax[i][r] + self.alpha * H0[i][r]
                for r in range(d)] for i in range(n)]
        M = self._mix_matrix()
        z = _g_matmul_dense(mix, M)
        out = [self.act_fn(z[i]) for i in range(n)]
        self._cache = (an, mix, z, M)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError('GCNIILayer.backward: 需要先 forward')
        an, mix, z, M = self._cache
        n = len(dout)
        d = self.in_features
        dz = [_g_scale_rows(self.act_deriv(z[i]), dout[i]) for i in range(n)]
        b = self.beta()
        dM = [[0.0] * d for _ in range(d)]
        for a in range(d):
            for c in range(d):
                acc = 0.0
                for i in range(n):
                    acc += mix[i][a] * dz[i][c]
                dM[a][c] = acc
                self.gW[a][c] += b * acc
        dmix = [[0.0] * d for _ in range(n)]
        for i in range(n):
            for a in range(d):
                acc = 0.0
                for c in range(d):
                    acc += dz[i][c] * M[a][c]
                dmix[i][a] = acc
        k = 1.0 - self.alpha
        dax = [[k * dmix[i][r] for r in range(d)] for i in range(n)]
        self.grad_h0 = [[self.alpha * dmix[i][r] for r in range(d)]
                        for i in range(n)]
        return _g_matmul_t(an, dax)

    def zero_grad(self):
        d = self.in_features
        self.gW = [[0.0] * d for _ in range(d)]

    def param_count(self) -> int:
        return self.in_features * self.out_features

    def sgd_step(self, lr: float):
        lr = _la_check_lr(lr, 'GCNIILayer.sgd_step')
        _la_apply_sgd(self.W, self.gW, lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        lr = _la_check_lr(lr, 'GCNIILayer.adam_step')
        _check_adam_betas(beta1, beta2, 'GCNIILayer.adam_step')
        self._t += 1
        t = self._t
        c1 = 1.0 - beta1 ** t
        c2 = 1.0 - beta2 ** t
        _la_apply_adam(self.W, self.gW, self.mW, self.vW, lr, c1, c2,
                       beta1, beta2, eps)

    def train(self):
        return self

    def eval(self):
        return self


def _g_matmul_dense(A, B):
    """通用矩阵乘 ``(n x k) @ (k x m)``（``_g_matmul`` 只处理方阵邻接）"""
    n = len(A)
    k = len(A[0])
    m = len(B[0])
    if len(B) != k:
        raise ValueError('_g_matmul_dense: 维度不匹配 (%d x %d) @ (%d x %d)'
                         % (n, k, len(B), m))
    out = [[0.0] * m for _ in range(n)]
    for i in range(n):
        ai = A[i]
        oi = out[i]
        for t in range(k):
            w = ai[t]
            if w == 0.0:
                continue
            bt = B[t]
            for j in range(m):
                oi[j] += w * bt[j]
    return out


def _g_matmul_dense_t(B, A):
    """``A @ B^T``，用于把梯度回传给左乘矩阵的行"""
    n = len(A)
    k = len(A[0])
    m = len(B)
    out = [[0.0] * m for _ in range(n)]
    for i in range(n):
        ai = A[i]
        oi = out[i]
        for j in range(m):
            bj = B[j]
            acc = 0.0
            for t in range(k):
                acc += ai[t] * bj[t]
            oi[j] = acc
    return out


def _g_submatrix(M, idx):
    """按节点下标取出密集矩阵的子块"""
    return [[M[i][j] for j in idx] for i in idx]


def _g_topk_indices(scores, k):
    """按分数取前 k 个节点下标（分数相同按原顺序）"""
    order = sorted(range(len(scores)), key=lambda i: (-scores[i], i))
    return sorted(order[:k])


class TopKPool:
    """Top-K 图池化（Graph U-Net 风格）：``score_i = W x_i + b``、``g_i = sigmoid(score_i)``

    保留分数最大的 ``k = max(1, round(ratio * N))`` 个节点，特征按 gate 缩放
    ``x'_i = g_i * x_i``，邻接取对应子块。``backward`` 只回传给被选中的节点。
    """

    def __init__(self, in_features: int, ratio: float = 0.5, seed: int = 0):
        _ck_int(in_features, 'TopKPool(in_features)', 1)
        if not _is_num(ratio) or not (0.0 < float(ratio) <= 1.0):
            raise ValueError('TopKPool(ratio) 必须在 (0, 1] 内')
        self.in_features = in_features
        self.ratio = float(ratio)
        self.score = _GDense(in_features, 1, random.Random(seed))
        self._cache = None

    def forward(self, X, adj):
        n = _g_check_x(X, 'TopKPool.forward')
        _g_check_adj(adj, n, 'TopKPool.forward')
        raw = self.score.forward(X)
        s = [r[0] for r in raw]
        g = [1.0 / (1.0 + math.exp(-v)) if v >= 0.0
             else math.exp(v) / (1.0 + math.exp(v)) for v in s]
        k = max(1, int(round(self.ratio * n)))
        idx = _g_topk_indices(s, k)
        out = [[g[i] * X[i][j] for j in range(self.in_features)] for i in idx]
        self._cache = (idx, g, X)
        return out, _g_submatrix(adj, idx)

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError('TopKPool.backward: 需要先 forward')
        idx, g, X = self._cache
        n = len(X)
        d = self.in_features
        dX = [[0.0] * d for _ in range(n)]
        dscore = [[0.0] for _ in range(n)]
        for p, i in enumerate(idx):
            gi = g[i]
            acc = 0.0
            for j in range(d):
                dX[i][j] = dout[p][j] * gi
                acc += dout[p][j] * X[i][j]
            dscore[i][0] = acc * gi * (1.0 - gi)
        dg = self.score.backward(dscore)
        for i in range(n):
            for j in range(d):
                dX[i][j] += dg[i][j]
        return dX

    def zero_grad(self):
        self.score.zero_grad()

    def param_count(self) -> int:
        return self.score.param_count()

    def sgd_step(self, lr: float):
        self.score.sgd_step(lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        self.score.adam_step(lr, beta1, beta2, eps)

    def train(self):
        return self

    def eval(self):
        return self


class SAGPool:
    """自注意力图池化（SAGPool）：用一层 GCN 打分 ``s = tanh(GCN(X, A))``，
    保留前 ``k`` 个节点并按 ``s`` 缩放特征，邻接取子块。
    """

    def __init__(self, in_features: int, ratio: float = 0.5, seed: int = 0):
        _ck_int(in_features, 'SAGPool(in_features)', 1)
        if not _is_num(ratio) or not (0.0 < float(ratio) <= 1.0):
            raise ValueError('SAGPool(ratio) 必须在 (0, 1] 内')
        self.in_features = in_features
        self.ratio = float(ratio)
        self.gcn = GCNLayer(in_features, 1, activation='linear', seed=seed)
        self._cache = None

    def forward(self, X, adj):
        n = _g_check_x(X, 'SAGPool.forward')
        _g_check_adj(adj, n, 'SAGPool.forward')
        z = self.gcn.forward(X, adj)
        s = [math.tanh(r[0]) for r in z]
        k = max(1, int(round(self.ratio * n)))
        idx = _g_topk_indices(s, k)
        out = [[s[i] * X[i][j] for j in range(self.in_features)] for i in idx]
        self._cache = (idx, s, X)
        return out, _g_submatrix(adj, idx)

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError('SAGPool.backward: 需要先 forward')
        idx, s, X = self._cache
        n = len(X)
        d = self.in_features
        dX = [[0.0] * d for _ in range(n)]
        dz = [[0.0] for _ in range(n)]
        for p, i in enumerate(idx):
            si = s[i]
            acc = 0.0
            for j in range(d):
                dX[i][j] = dout[p][j] * si
                acc += dout[p][j] * X[i][j]
            dz[i][0] = acc * (1.0 - si * si)
        dg = self.gcn.backward(dz)
        for i in range(n):
            for j in range(d):
                dX[i][j] += dg[i][j]
        return dX

    def zero_grad(self):
        self.gcn.zero_grad()

    def param_count(self) -> int:
        return self.gcn.param_count()

    def sgd_step(self, lr: float):
        self.gcn.sgd_step(lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        self.gcn.adam_step(lr, beta1, beta2, eps)

    def train(self):
        return self

    def eval(self):
        return self


class DiffPool:
    """DiffPool 软分配池化：``Z = GCN_embed(X, A)``、``S = softmax(GCN_pool(X, A))``

    池化输出 ``X' = Sᵀ Z``（``n_clusters x out_features``）与
    ``A' = Sᵀ A S``（``n_clusters x n_clusters``）。``S`` 每行和为 1（软分配），
    所以 ``X'`` 是「按簇归属加权的节点特征」、``A'`` 是簇间连边的加权和。
    与 ``TopKPool``/``SAGPool`` 的硬选择不同，所有节点都参与，梯度因此能回到
    未选中节点——这也是 DiffPool 要两层 GCN（embed + pool）的原因。

    ``backward(dout, d_adj=None)`` 返回输入特征梯度 ``dX``；邻接矩阵被视为
    结构常量（与 ``GCNLayer`` 一致），它对 ``A`` 的梯度是 ``S dA' Sᵀ``，
    不向下传。``d_adj`` 给 ``A'`` 提供上游梯度（例如图级损失用到 ``A'`` 时）。
    """

    def __init__(self, in_features: int, out_features: int, n_clusters: int = 2,
                 seed: int = 0):
        _ck_int(in_features, 'DiffPool(in_features)', 1)
        _ck_int(out_features, 'DiffPool(out_features)', 1)
        _ck_int(n_clusters, 'DiffPool(n_clusters)', 1)
        self.in_features = in_features
        self.out_features = out_features
        self.n_clusters = n_clusters
        self.embed = GCNLayer(in_features, out_features, activation='linear',
                              seed=seed)
        self.pool = GCNLayer(in_features, n_clusters, activation='linear',
                             seed=seed + 1)
        self._cache = None

    @staticmethod
    def _softmax_row(row):
        mx = max(row)
        ex = [math.exp(v - mx) for v in row]
        tot = sum(ex)
        return [v / tot for v in ex]

    def forward(self, X, adj):
        n = _g_check_x(X, 'DiffPool.forward')
        _g_check_adj(adj, n, 'DiffPool.forward')
        k = self.n_clusters
        d = self.out_features
        Z = self.embed.forward(X, adj)
        logits = self.pool.forward(X, adj)
        S = [self._softmax_row(logits[i]) for i in range(n)]
        xp = [[0.0] * d for _ in range(k)]
        for i in range(n):
            si = S[i]
            zi = Z[i]
            for p in range(k):
                w = si[p]
                row = xp[p]
                for j in range(d):
                    row[j] += w * zi[j]
        a_s = [[0.0] * k for _ in range(n)]
        for i in range(n):
            ai = adj[i]
            row = a_s[i]
            for j in range(n):
                w = ai[j]
                if w == 0.0:
                    continue
                sj = S[j]
                for q in range(k):
                    row[q] += w * sj[q]
        ap = [[0.0] * k for _ in range(k)]
        for i in range(n):
            si = S[i]
            asi = a_s[i]
            for p in range(k):
                w = si[p]
                if w == 0.0:
                    continue
                row = ap[p]
                for q in range(k):
                    row[q] += w * asi[q]
        self._cache = (X, adj, S, Z, a_s)
        return xp, ap

    def backward(self, dout, d_adj=None):
        if self._cache is None:
            raise RuntimeError('DiffPool.backward: 需要先 forward')
        X, adj, S, Z, a_s = self._cache
        n = len(X)
        k = self.n_clusters
        d = self.out_features
        if not isinstance(dout, list) or len(dout) != k:
            raise ValueError('DiffPool.backward: dout 要有 %d 行' % k)
        for row in dout:
            if not isinstance(row, list) or len(row) != d:
                raise ValueError('DiffPool.backward: dout 每行要有 %d 个分量' % d)
        if d_adj is None:
            dap = [[0.0] * k for _ in range(k)]
        else:
            if not isinstance(d_adj, list) or len(d_adj) != k:
                raise ValueError('DiffPool.backward: d_adj 要有 %d 行' % k)
            for row in d_adj:
                if not isinstance(row, list) or len(row) != k:
                    raise ValueError('DiffPool.backward: d_adj 每行要有 %d 个分量' % k)
            dap = d_adj
        dz = [[0.0] * d for _ in range(n)]
        for i in range(n):
            si = S[i]
            row = dz[i]
            for p in range(k):
                w = si[p]
                if w == 0.0:
                    continue
                dp = dout[p]
                for j in range(d):
                    row[j] += w * dp[j]
        ds = [[0.0] * k for _ in range(n)]
        for i in range(n):
            zi = Z[i]
            row = ds[i]
            for p in range(k):
                acc = 0.0
                dp = dout[p]
                for j in range(d):
                    acc += dp[j] * zi[j]
                row[p] = acc
        for i in range(n):
            ai = adj[i]
            row = ds[i]
            for p in range(k):
                acc = 0.0
                for j in range(n):
                    w = ai[j]
                    if w == 0.0:
                        continue
                    # (A S dAp^T)_{ip} = sum_j A_ij * sum_q S_jq * dAp_pq
                    sj = S[j]
                    for q in range(k):
                        acc += w * sj[q] * dap[p][q]
                row[p] += acc
        # A 对称的常见情形仍用通用式，避免依赖对称性
        for i in range(n):
            si = S[i]
            row = ds[i]
            for p in range(k):
                acc = 0.0
                for j in range(n):
                    w = adj[j][i]
                    if w == 0.0:
                        continue
                    sj = S[j]
                    for q in range(k):
                        acc += w * sj[q] * dap[q][p]
                row[p] += acc
        dlogits = [[0.0] * k for _ in range(n)]
        for i in range(n):
            si = S[i]
            di = ds[i]
            dot = 0.0
            for p in range(k):
                dot += di[p] * si[p]
            out = dlogits[i]
            for p in range(k):
                out[p] = si[p] * (di[p] - dot)
        dx = self.embed.backward(dz)
        dxp = self.pool.backward(dlogits)
        for i in range(n):
            for j in range(self.in_features):
                dx[i][j] += dxp[i][j]
        return dx

    def zero_grad(self):
        self.embed.zero_grad()
        self.pool.zero_grad()

    def param_count(self) -> int:
        return self.embed.param_count() + self.pool.param_count()

    def sgd_step(self, lr: float):
        self.embed.sgd_step(lr)
        self.pool.sgd_step(lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        self.embed.adam_step(lr, beta1, beta2, eps)
        self.pool.adam_step(lr, beta1, beta2, eps)

    def train(self):
        return self

    def eval(self):
        return self


def _w7c_ids(ids, who):
    """校验一维 token 序列（非空、非负整数、不接受 bool）"""
    if not isinstance(ids, list) or not ids:
        raise ValueError('%s: ids 必须是非空列表' % who)
    for v in ids:
        if not isinstance(v, int) or isinstance(v, bool) or v < 0:
            raise ValueError('%s: token 必须是非负整数，收到 %r' % (who, v))
    return list(ids)


def _w7c_vec(vec, who):
    """校验一维数值向量（拒绝 NaN / inf）"""
    if not isinstance(vec, list) or not vec:
        raise ValueError('%s: 向量必须是非空列表' % who)
    out = []
    for v in vec:
        if not _is_num(v):
            raise ValueError('%s: 向量分量必须是数字，收到 %r' % (who, v))
        out.append(float(v))
    return out


def _w7c_cos(a, b):
    """余弦相似度；任一侧为零向量时返回 0.0（避免除零）"""
    na = math.sqrt(sum(v * v for v in a))
    nb = math.sqrt(sum(v * v for v in b))
    if na <= 0.0 or nb <= 0.0:
        return 0.0
    return sum(x * y for x, y in zip(a, b)) / (na * nb)


def contrastive_select(logits, hiddens, history, alpha: float = 0.6, top_k: int = 5):
    """对比搜索的单步选择（Su et al. 2022）：``score = (1-α)·p − α·reward``

    `hiddens` 是 `{候选 token: 该候选的隐状态}`（只需覆盖概率前 `top_k` 的 token），
    每个候选的退化惩罚是它与 `history` 中任一隐状态余弦相似度的**最大值**——
    惩罚必须按候选各自的隐状态算，否则所有候选同罚、选择就退化成 argmax。
    返回 `{'token', 'score', 'prob', 'reward', 'candidates'}`。
    """
    lg = _w7c_vec(logits, 'contrastive_select(logits)')
    if not isinstance(hiddens, dict) or not hiddens:
        raise ValueError('contrastive_select(hiddens) 必须是非空 dict')
    if not _is_num(alpha) or not (0.0 <= float(alpha) <= 1.0):
        raise ValueError('contrastive_select(alpha) 必须在 [0, 1] 内')
    _ck_int(top_k, 'contrastive_select(top_k)', 1)
    if history is None:
        history = []
    if not isinstance(history, list):
        raise ValueError('contrastive_select(history) 必须是列表')
    hist = [_w7c_vec(h, 'contrastive_select(history[])') for h in history]
    probs = _softmax_row(lg)
    order = sorted(range(len(probs)), key=lambda i: (-probs[i], i))[:top_k]
    cands = []
    for tok in order:
        if tok not in hiddens:
            raise ValueError('contrastive_select: hiddens 缺少候选 token %d 的隐状态'
                             % tok)
        hv = _w7c_vec(hiddens[tok], 'contrastive_select(hiddens[])')
        if hist and len(hv) != len(hist[0]):
            raise ValueError('contrastive_select: 候选隐状态宽度必须与 history 一致')
        reward = max([_w7c_cos(hv, h) for h in hist]) if hist else 0.0
        score = (1.0 - alpha) * probs[tok] - alpha * reward
        cands.append({'token': tok, 'score': score, 'prob': probs[tok],
                      'reward': reward})
    best = cands[0]
    for c in cands[1:]:
        if c['score'] > best['score']:
            best = c
    return {'token': best['token'], 'score': best['score'], 'prob': best['prob'],
            'reward': best['reward'], 'candidates': cands}


def contrastive_search(model, prompt_ids, max_new_tokens: int = 8, top_k: int = 5,
                       alpha: float = 0.6):
    """对比搜索生成（要求模型有 ``forward(ids) -> (T, V) logits`` 与 ``h``（T×d 隐状态））

    每一步：取当前分布的 top-k 候选，**对每个候选各前向一次**拿到它自己的隐状态，
    再用 `contrastive_select` 打分挑一个。因此每生成一个 token 要 k+1 次前向
    （教学实现，不复用 KV cache），docstring 明写这个代价。
    """
    ids = _w7c_ids(prompt_ids, 'contrastive_search(prompt_ids)')
    _ck_int(max_new_tokens, 'contrastive_search(max_new_tokens)', 1)
    _ck_int(top_k, 'contrastive_search(top_k)', 1)
    if not _is_num(alpha) or not (0.0 <= float(alpha) <= 1.0):
        raise ValueError('contrastive_search(alpha) 必须在 [0, 1] 内')
    if not hasattr(model, 'forward') or not hasattr(model, 'h'):
        raise ValueError('contrastive_search(model): 模型需要有 forward(ids) 与 h 属性')
    model.eval()
    cur = list(ids)
    logits = model.forward(cur)
    hidden = _w7c_vec(list(model.h[-1]), 'contrastive_search(model.h)')
    history = [_w7c_vec(list(row), 'contrastive_search(model.h)')
               for row in model.h[:-1]]
    picks = []
    for _ in range(max_new_tokens):
        last = _w7c_vec(list(logits[-1]), 'contrastive_search(logits)')
        probs = _softmax_row(last)
        order = sorted(range(len(probs)), key=lambda i: (-probs[i], i))[:top_k]
        hiddens = {}
        cache = {}
        for tok in order:
            logits_tok = model.forward(cur + [tok])
            h_tok = _w7c_vec(list(model.h[-1]), 'contrastive_search(model.h)')
            hiddens[tok] = h_tok
            cache[tok] = (logits_tok, h_tok)
        pick = contrastive_select(last, hiddens, history, alpha=alpha, top_k=top_k)
        tok = pick['token']
        history.append(hidden)
        cur.append(tok)
        logits, hidden = cache[tok]
        picks.append({'token': tok, 'score': pick['score'],
                      'prob': pick['prob'], 'reward': pick['reward']})
    return {'ids': cur, 'picks': picks}


def diverse_beam_select(entries, num_select: int, diversity_penalty: float = 0.5):
    """多样束搜索的**单步**选择：先取最高分，之后对「与已选下一步 token 相同」的候选扣分

    `entries` 是 `[{'token': int, 'score': float}, ...]`（同一批扩展候选）；
    返回被选中条目的下标列表。扣分是 `penalty × 该 token 在已选集合里的出现次数`。
    """
    if not isinstance(entries, list) or not entries:
        raise ValueError('diverse_beam_select(entries) 必须是非空列表')
    _ck_int(num_select, 'diverse_beam_select(num_select)', 1)
    if not _is_num(diversity_penalty) or float(diversity_penalty) < 0.0:
        raise ValueError('diverse_beam_select(diversity_penalty) 必须是非负数')
    num_select = min(num_select, len(entries))
    cleaned = []
    for i, e in enumerate(entries):
        if not isinstance(e, dict) or 'token' not in e or 'score' not in e:
            raise ValueError('diverse_beam_select: 每条要含 token 与 score')
        tok = e['token']
        if not isinstance(tok, int) or isinstance(tok, bool) or tok < 0:
            raise ValueError('diverse_beam_select: token 必须是非负整数')
        if not _is_num(e['score']):
            raise ValueError('diverse_beam_select: score 必须是数字')
        cleaned.append({'index': i, 'token': tok, 'score': float(e['score'])})
    remaining = list(cleaned)
    selected = []
    used = {}
    while len(selected) < num_select and remaining:
        best = None
        best_adj = None
        for c in remaining:
            adj = c['score'] - float(diversity_penalty) * used.get(c['token'], 0)
            if best is None or adj > best_adj or (adj == best_adj
                                                 and c['index'] < best['index']):
                best = c
                best_adj = adj
        remaining.remove(best)
        selected.append(best['index'])
        used[best['token']] = used.get(best['token'], 0) + 1
    return selected


def diverse_beam_search(step_logprobs, prompt_ids, num_beams: int = 4,
                        num_return: int = 2, max_new_tokens: int = 8,
                        diversity_penalty: float = 0.5, eos_id=None):
    """多样束搜索（不依赖具体模型）：``step_logprobs(ids) -> 逐步 log 概率``

    所有 beam 从同一个前缀出发；每步对每个 beam 取 `2*num_beams` 个候选，
    第一条 beam 直接取最高分，其余用 `diverse_beam_select` 的扣分规则挑不同 token
    （Diverse Beam Search 的组间惩罚项，这里简化为单组）。命中 `eos_id` 的序列
    立刻进 `finished`，不再扩展。
    """
    prompt = _w7c_ids(prompt_ids, 'diverse_beam_search(prompt_ids)')
    _ck_int(num_beams, 'diverse_beam_search(num_beams)', 1)
    _ck_int(num_return, 'diverse_beam_search(num_return)', 1)
    _ck_int(max_new_tokens, 'diverse_beam_search(max_new_tokens)', 1)
    if not callable(step_logprobs):
        raise ValueError('diverse_beam_search(step_logprobs) 必须是可调用对象')
    if num_return > num_beams:
        raise ValueError('diverse_beam_search: num_return 不能大于 num_beams')
    beams = [list(prompt) for _ in range(num_beams)]
    scores = [0.0 for _ in range(num_beams)]
    finished = []
    for _ in range(max_new_tokens):
        entries = []
        for bi, seq in enumerate(beams):
            lps = _w7c_vec(list(step_logprobs(seq)),
                           'diverse_beam_search(step_logprobs)')
            order = sorted(range(len(lps)), key=lambda i: (-lps[i], i))
            for tok in order[:2 * num_beams]:
                entries.append({'token': tok, 'score': scores[bi] + lps[tok],
                                'beam': bi})
        order = sorted(range(len(entries)),
                       key=lambda i: (-entries[i]['score'], i))
        ranked = [entries[i] for i in order]
        keep = diverse_beam_select(ranked, num_beams,
                                   diversity_penalty=diversity_penalty)
        new_beams = []
        new_scores = []
        for pos in keep:
            item = ranked[pos]
            seq = list(beams[item['beam']]) + [item['token']]
            if eos_id is not None and item['token'] == eos_id:
                finished.append((seq, item['score']))
                continue
            new_beams.append(seq)
            new_scores.append(item['score'])
        if not new_beams:
            beams, scores = [], []
            break
        beams, scores = new_beams, new_scores
    finished.extend(list(zip(beams, scores)))
    finished.sort(key=lambda pair: (-pair[1], pair[0]))
    return {'sequences': [s for s, _ in finished[:num_return]],
            'scores': [sc for _, sc in finished[:num_return]]}


def diverse_beam_generate(model, prompt_ids, num_beams: int = 4, num_return: int = 2,
                          max_new_tokens: int = 8, diversity_penalty: float = 0.5,
                          eos_id=None):
    """`CausalLM` 上的多样束搜索封装：把模型前向包装成 `step_logprobs`"""
    if not hasattr(model, 'forward'):
        raise ValueError('diverse_beam_generate(model): 模型需要有 forward(ids)')

    def step_logprobs(ids):
        logits = model.forward(list(ids))
        return _log_softmax_row(list(logits[-1]))

    return diverse_beam_search(step_logprobs, prompt_ids, num_beams=num_beams,
                               num_return=num_return,
                               max_new_tokens=max_new_tokens,
                               diversity_penalty=diversity_penalty,
                               eos_id=eos_id)


#  领域应用：语法约束解码（正则 NFA / CFG Earley / JSON 语法）
# =====================================================================

def _w7e_char_predicate(spec):
    """把字符类说明（'digit' / 'alpha' / 单字符串）变成 predicate。"""
    if callable(spec):
        return spec
    if not isinstance(spec, str) or not spec:
        raise TypeError("_w7e_char_predicate: 需要非空字符串或可调用对象")
    table = {
        "digit": lambda ch: ch.isdigit(),
        "alpha": lambda ch: ch.isalpha(),
        "alnum": lambda ch: ch.isalnum(),
        "space": lambda ch: ch.isspace(),
        "lower": lambda ch: ch.islower(),
        "upper": lambda ch: ch.isupper(),
        "any": lambda ch: True,
    }
    if spec in table:
        return table[spec]
    return lambda ch, _s=spec: ch in _s


class _W7eNfa:
    """Thompson NFA：状态是整数，边是 (predicate, target) 或 epsilon。"""

    def __init__(self):
        self.edges = []
        self.eps = []
        self.start = None
        self.accept = None

    def new_state(self):
        self.edges.append([])
        self.eps.append([])
        return len(self.edges) - 1

    def add(self, src, pred, dst):
        self.edges[src].append((pred, dst))

    def add_eps(self, src, dst):
        self.eps[src].append(dst)

    def closure(self, states):
        out = set(states)
        stack = list(states)
        while stack:
            cur = stack.pop()
            for nxt in self.eps[cur]:
                if nxt not in out:
                    out.add(nxt)
                    stack.append(nxt)
        return out

    def step(self, states, token):
        out = set()
        for cur in self.closure(states):
            for pred, dst in self.edges[cur]:
                if pred(token):
                    out.add(dst)
        return self.closure(out)

    def live_states(self):
        """能到达接受态的状态集合（反向可达）。"""
        rev = [[] for _ in range(len(self.edges))]
        for src in range(len(self.edges)):
            for _, dst in self.edges[src]:
                rev[dst].append(src)
            for dst in self.eps[src]:
                rev[dst].append(src)
        live = {self.accept}
        stack = [self.accept]
        while stack:
            cur = stack.pop()
            for pre in rev[cur]:
                if pre not in live:
                    live.add(pre)
                    stack.append(pre)
        return live


def _w7e_regex_parse(pattern):
    """极简正则解析：字面量、. ^ $ * + ? 与 [..] 字符类、| 与分组。"""
    if not isinstance(pattern, str):
        raise TypeError("RegexGrammar: pattern 必须是字符串")
    if not pattern:
        raise ValueError("RegexGrammar: pattern 不能为空")
    pos = [0]

    def peek():
        return pattern[pos[0]] if pos[0] < len(pattern) else None

    def take():
        ch = peek()
        pos[0] += 1
        return ch

    def parse_alt():
        branches = [parse_concat()]
        while peek() == "|":
            take()
            branches.append(parse_concat())
        return branches[0] if len(branches) == 1 else ("alt", branches)

    def parse_concat():
        items = []
        while peek() is not None and peek() not in (")", "|"):
            items.append(parse_repeat())
        return ("cat", items) if items else ("cat", [])

    def parse_atom():
        ch = take()
        if ch == ".":
            return ("set", _w7e_char_predicate("any"))
        if ch == "\\":
            nxt = take()
            if nxt is None:
                raise ValueError("RegexGrammar: 结尾多了反斜杠")
            if nxt == "d":
                return ("set", _w7e_char_predicate("digit"))
            if nxt == "w":
                return ("set", _w7e_char_predicate("alnum"))
            if nxt == "s":
                return ("set", _w7e_char_predicate("space"))
            return ("lit", nxt)
        if ch == "[":
            body = []
            negate = False
            if peek() == "^":
                take()
                negate = True
            first = True
            while True:
                cur = take()
                if cur is None:
                    raise ValueError("RegexGrammar: 字符类没有闭合 ]")
                if cur == "]" and not first:
                    break
                if cur == "\\":
                    nxt = take()
                    if nxt is None:
                        raise ValueError("RegexGrammar: 字符类里的转义不完整")
                    cur = nxt
                # 区间：a-z（'-' 后面不是 ']' 才当区间）
                if peek() == "-" and pos[0] + 1 < len(pattern) and pattern[pos[0] + 1] != "]":
                    take()
                    hi = take()
                    if hi is None:
                        raise ValueError("RegexGrammar: 字符类区间缺少上界")
                    if ord(hi) < ord(cur):
                        raise ValueError("RegexGrammar: 字符类区间 %r-%r 上界小于下界"
                                         % (cur, hi))
                    body.extend(chr(c) for c in range(ord(cur), ord(hi) + 1))
                else:
                    body.append(cur)
                first = False
            allowed = set(body)

            def pred(ch, _a=allowed, _n=negate):
                hit = ch in _a
                return (not hit) if _n else hit

            return ("set", pred)
        if ch == "(":
            inner = parse_alt()
            if take() != ")":
                raise ValueError("RegexGrammar: 分组没有闭合 )")
            return inner
        return ("lit", ch)

    def parse_repeat():
        atom = parse_atom()
        while True:
            cur = peek()
            if cur == "*":
                take()
                atom = ("star", atom)
            elif cur == "+":
                take()
                atom = ("plus", atom)
            elif cur == "?":
                take()
                atom = ("opt", atom)
            else:
                return atom

    ast = parse_alt()
    if pos[0] != len(pattern):
        raise ValueError("RegexGrammar: 第 %d 个字符处无法解析（多余 %r）"
                         % (pos[0], pattern[pos[0]:]))
    return ast


def _w7e_compile(ast, nfa):
    kind = ast[0]
    if kind == "lit":
        a = nfa.new_state()
        b = nfa.new_state()
        ch = ast[1]
        nfa.add(a, lambda t, _c=ch: t == _c, b)
        return a, b
    if kind == "set":
        a = nfa.new_state()
        b = nfa.new_state()
        pred = ast[1]
        nfa.add(a, lambda t, _p=pred: len(t) == 1 and _p(t), b)
        return a, b
    if kind == "cat":
        a = nfa.new_state()
        cur = a
        for item in ast[1]:
            si, ei = _w7e_compile(item, nfa)
            nfa.add_eps(cur, si)
            cur = ei
        return a, cur
    if kind == "alt":
        a = nfa.new_state()
        b = nfa.new_state()
        for branch in ast[1]:
            si, ei = _w7e_compile(branch, nfa)
            nfa.add_eps(a, si)
            nfa.add_eps(ei, b)
        return a, b
    if kind in ("star", "plus", "opt"):
        a = nfa.new_state()
        b = nfa.new_state()
        si, ei = _w7e_compile(ast[1], nfa)
        nfa.add_eps(a, si)
        nfa.add_eps(ei, b)
        if kind in ("star", "opt"):
            nfa.add_eps(a, b)
        if kind in ("star", "plus"):
            nfa.add_eps(ei, si)
        return a, b
    raise ValueError("_w7e_compile: 未知节点 %r" % (kind,))


class RegexGrammar:
    """用一个正则约束「下一个 token 能不能接」。

    实现了字面量、`.`、`*` `+` `?`、`[abc]` / `[^abc]`、`\\d` `\\w` `\\s`、
    `|` 与括号分组；编译成 Thompson NFA 后逐 token 推进。
    只支持「整段匹配」（相当于 `re.fullmatch`），不处理 `^` `$`（可省）。
    """

    def __init__(self, pattern):
        self.pattern = pattern
        self._nfa = _W7eNfa()
        ast = _w7e_regex_parse(pattern)
        a, b = _w7e_compile(ast, self._nfa)
        self._nfa.start = a
        self._nfa.accept = b
        self._live = self._nfa.live_states()

    def _advance(self, prefix, tokens):
        states = {self._nfa.start}
        for tok in tokens:
            states = self._nfa.step(states, tok)
            if not states:
                return None
        return states

    def state(self, prefix):
        if isinstance(prefix, str):
            prefix = list(prefix)
        states = self._advance(None, prefix)
        if states is None:
            raise ValueError("RegexGrammar.state: 前缀 %r 已经不可能匹配" % (prefix,))
        return states

    def viable(self, prefix):
        states = self._advance(None, list(prefix))
        return bool(states) and bool(states & self._live)

    def accepts(self, tokens):
        states = self._advance(None, list(tokens))
        return bool(states) and self._nfa.accept in states

    def allowed(self, prefix, vocabulary):
        states = self._advance(None, list(prefix))
        if states is None:
            return []
        out = []
        for tok in vocabulary:
            nxt = self._nfa.step(states, tok)
            if nxt & self._live:
                out.append(tok)
        return out

    def choices(self):
        """一个可用的字符级词表（仅用于演示/测试）。"""
        return [chr(c) for c in range(32, 127)]


class CFGGrammar:
    """Earley 解析器驱动的 CFG 语法约束。

    `productions` 形如 `{"S": [["A", "b"], []]}`（右部为空 list 表示 ε）；
    出现在 `productions` 键里的符号是**非终结符**，其余按终结符处理：
    字符串终结符精确匹配，可调用终结符当谓词（`token -> bool`）。
    """

    def __init__(self, productions, start):
        if not isinstance(productions, dict) or not productions:
            raise ValueError("CFGGrammar: productions 必须是非空 dict")
        if start not in productions:
            raise ValueError("CFGGrammar: 起始符号 %r 不在 productions 里" % (start,))
        self.rules = []
        self.by_lhs = {}
        for lhs, alts in productions.items():
            if not isinstance(lhs, str) or not lhs:
                raise ValueError("CFGGrammar: 非终结符名必须是非空字符串")
            if not isinstance(alts, (list, tuple)):
                raise ValueError("CFGGrammar: %r 的右部必须是列表" % (lhs,))
            for alt in alts:
                if not isinstance(alt, (list, tuple)):
                    raise ValueError("CFGGrammar: %r 的每条右部必须是列表" % (lhs,))
                idx = len(self.rules)
                self.rules.append((lhs, list(alt)))
                self.by_lhs.setdefault(lhs, []).append(idx)
        self.start = start
        self.nonterminals = set(productions)

    def _match(self, symbol, token):
        if callable(symbol):
            return bool(symbol(token))
        return symbol == token

    def _chart(self, tokens):
        n = len(tokens)
        chart = [set() for _ in range(n + 1)]

        def add(i, state):
            if state not in chart[i]:
                chart[i].add(state)

        for idx in self.by_lhs[self.start]:
            add(0, (idx, 0, 0))
        for i in range(n + 1):
            changed = True
            while changed:
                changed = False
                for state in list(chart[i]):
                    idx, dot, origin = state
                    lhs, rhs = self.rules[idx]
                    if dot < len(rhs):
                        sym = rhs[dot]
                        if sym in self.nonterminals:
                            for nidx in self.by_lhs[sym]:
                                new = (nidx, 0, i)
                                if new not in chart[i]:
                                    add(i, new)
                                    changed = True
                    else:
                        for pidx, pdot, porigin in list(chart[origin]):
                            plhs, prhs = self.rules[pidx]
                            if pdot < len(prhs) and prhs[pdot] == lhs:
                                new = (pidx, pdot + 1, porigin)
                                if new not in chart[i]:
                                    add(i, new)
                                    changed = True
            if i < n:
                token = tokens[i]
                for idx, dot, origin in list(chart[i]):
                    lhs, rhs = self.rules[idx]
                    if dot < len(rhs):
                        sym = rhs[dot]
                        if sym not in self.nonterminals and self._match(sym, token):
                            new = (idx, dot + 1, origin)
                            if new not in chart[i + 1]:
                                add(i + 1, new)
        return chart

    def accepts(self, tokens):
        tokens = list(tokens)
        chart = self._chart(tokens)
        n = len(tokens)
        for idx, dot, origin in chart[n]:
            lhs, rhs = self.rules[idx]
            if dot == len(rhs) and origin == 0 and lhs == self.start:
                return True
        return False

    def expected(self, tokens):
        """当前前缀下所有「可以接下去」的终结符说明（可能是谓词）。"""
        tokens = list(tokens)
        chart = self._chart(tokens)
        i = len(tokens)
        out = []
        for idx, dot, origin in chart[i]:
            lhs, rhs = self.rules[idx]
            if dot < len(rhs) and rhs[dot] not in self.nonterminals:
                sym = rhs[dot]
                if not any(sym is o for o in out):
                    out.append(sym)
        return out

    def allowed(self, prefix, vocabulary):
        tokens = list(prefix)
        chart = self._chart(tokens)
        i = len(tokens)
        expected = []
        for idx, dot, origin in chart[i]:
            lhs, rhs = self.rules[idx]
            if dot < len(rhs) and rhs[dot] not in self.nonterminals:
                sym = rhs[dot]
                if not any(sym is o for o in expected):
                    expected.append(sym)
        out = []
        for tok in vocabulary:
            for sym in expected:
                if self._match(sym, tok):
                    out.append(tok)
                    break
        return out


def _w7e_json_pred_string(tok):
    return tok == '"' or tok == "STR"


def json_grammar():
    """JSON 的结构语法（对象/数组/值），字符串与数字用词表里的类别 token 表示。

    终结符：`{` `}` `[` `]` `:` `,` `true` `false` `null`；
    以及三个谓词终结符 `STR`（形如 `"..."`）、`NUM`（形如 `-?digits(.digits)?`）、
    `LIT`（`true`/`false`/`null`）。演示里直接把类别名当 token 用即可。
    """
    str_tok = lambda t: t == "STR" or (len(t) >= 2 and t[0] == '"' and t[-1] == '"')

    def num_tok(t):
        if t == "NUM":
            return True
        if not isinstance(t, str) or not t:
            return False
        body = t[1:] if t[0] == "-" else t
        if not body:
            return False
        if body.count(".") == 0:
            return body.isdigit()
        if body.count(".") != 1:
            return False
        head, tail = body.split(".")
        return head.isdigit() and tail.isdigit()

    lit_tok = lambda t: t in ("true", "false", "null", "LIT")
    return CFGGrammar({
        "V": [["OBJ"], ["ARR"], [str_tok], [num_tok], [lit_tok]],
        "OBJ": [["{", "}"], ["{", "MEMBERS", "}"]],
        "MEMBERS": [["PAIR"], ["MEMBERS", ",", "PAIR"]],
        "PAIR": [[str_tok, ":", "V"]],
        "ARR": [["[", "]"], ["[", "ELEMS", "]"]],
        "ELEMS": [["V"], ["ELEMS", ",", "V"]],
    }, "V")


def json_tokens(text):
    """把一段 JSON 文本切成语法 token（字符串整体一个 token）。"""
    import json as _json
    if not isinstance(text, str):
        raise TypeError("json_tokens: 需要字符串")
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch in "{}[]:,":
            tokens.append(ch)
            i += 1
        elif ch.isspace():
            i += 1
        elif ch == '"':
            j = i + 1
            while j < n:
                if text[j] == "\\":
                    j += 2
                    continue
                if text[j] == '"':
                    break
                j += 1
            if j >= n:
                raise ValueError("json_tokens: 字符串没有闭合")
            tokens.append(text[i:j + 1])
            i = j + 1
        else:
            j = i
            while j < n and (text[j].isalnum() or text[j] in "-+.eE"):
                j += 1
            tokens.append(text[i:j])
            i = j
    return tokens


def grammar_allowed(grammar, prefix, vocabulary):
    if not isinstance(grammar, (RegexGrammar, CFGGrammar)):
        raise TypeError("grammar_allowed: 需要 RegexGrammar 或 CFGGrammar")
    return grammar.allowed(prefix, vocabulary)


def grammar_mask(grammar, prefix, vocabulary):
    allowed = set(grammar_allowed(grammar, prefix, vocabulary))
    return [tok in allowed for tok in vocabulary]


def grammar_pick(grammar, prefix, logits, vocabulary):
    """在 gramm ar 允许的候选里取 logit 最大者（同分取小下标）。"""
    if len(logits) != len(vocabulary):
        raise ValueError("grammar_pick: logits 长度 %d 与词表 %d 不一致"
                         % (len(logits), len(vocabulary)))
    allowed = set(grammar_allowed(grammar, prefix, vocabulary))
    best = None
    for i, tok in enumerate(vocabulary):
        if tok not in allowed:
            continue
        if best is None or logits[i] > logits[best]:
            best = i
    if best is None:
        raise ValueError("grammar_pick: 没有可用的下一个 token（前缀 %r 已无解）"
                         % (list(prefix),))
    return best, vocabulary[best]


def grammar_generate(grammar, logits_fn, vocabulary, max_len=16, stop=None):
    """greedy 语法约束生成：每步只在语法允许的 token 里取最大 logit。"""
    out = []
    for _ in range(max_len):
        logits = logits_fn(list(out))
        if len(logits) != len(vocabulary):
            raise ValueError("grammar_generate: logits_fn 返回长度与词表不一致")
        idx, tok = grammar_pick(grammar, out, logits, vocabulary)
        out.append(tok)
        if stop is not None and out == list(stop):
            break
        if grammar.accepts(out):
            break
    return out


# ============================================================================
#  领域应用：完整草稿-验证循环（自投机 / Medusa / EAGLE 的机制说明）
# ============================================================================

def _w7f_ids(ids, who):
    if not isinstance(ids, (list, tuple)) or not ids:
        raise ValueError(f"{who}: ids 必须是非空列表")
    out = []
    for i, t in enumerate(ids):
        if isinstance(t, bool) or not isinstance(t, int):
            raise ValueError(f"{who}: ids[{i}] 必须是整数，收到 {t!r}")
        out.append(int(t))
    return out


def _w7f_probs(fn, ids, vocab_size=None, who="speculative_decode"):
    """调用用户的「下一个 token 概率」回调并校验。"""
    row = fn(list(ids))
    if not isinstance(row, (list, tuple)) or not row:
        raise ValueError(f"{who}: 概率回调必须返回非空列表")
    vals = []
    for j, p in enumerate(row):
        if isinstance(p, bool) or not isinstance(p, (int, float)):
            raise ValueError(f"{who}: 概率[{j}] 必须是数字，收到 {p!r}")
        p = float(p)
        if p != p or p < 0.0 or p == float("inf"):
            raise ValueError(f"{who}: 概率[{j}] 必须是有限非负数，收到 {p!r}")
        vals.append(p)
    if vocab_size is not None and len(vals) != vocab_size:
        raise ValueError(f"{who}: 概率长度 {len(vals)} 与词表 {vocab_size} 不一致")
    total = sum(vals)
    if total <= 0.0:
        raise ValueError(f"{who}: 概率之和必须 > 0")
    if abs(total - 1.0) > 1e-6:
        raise ValueError(f"{who}: 概率之和必须为 1，实测 {total:.6f}")
    return vals


def _w7f_sample(probs, rng):
    """按累积分布采样一个下标（浮点误差兜底到最后一个非零项）。"""
    u = rng.random()
    acc = 0.0
    last = 0
    for i, p in enumerate(probs):
        if p > 0.0:
            last = i
        acc += p
        if u < acc:
            return i
    return last


def speculative_decode(draft_probs_fn, target_probs_fn, prompt_ids,
                       max_new_tokens=8, gamma=4, seed=None, eos_id=None):
    """完整的草稿-验证循环（与 ``speculative_accept`` 配套）

    ``draft_probs_fn(ids) -> probs`` 和 ``target_probs_fn(ids) -> probs`` 是
    「下一个 token 的概率分布」回调；每轮草稿连出至多 ``gamma`` 个 token，
    再用 ``speculative_accept`` 做拒绝采样：接受前 k 个，第一个被拒位置用残差
    ``max(0, p_target - p_draft)`` 重采样。

    与 ``speculative_generate``（要求草稿模型有 ``generate``）的区别：
    这里只要求两个纯回调，因此可以拿任意合成分布做端到端校验，也不依赖模型类。

    返回 ``{"ids", "stats"}``；``stats`` 含 ``rounds`` / ``proposed`` /
    ``accepted`` / ``draft_calls`` / ``target_calls`` / ``accept_rate`` /
    ``tokens_per_target_call``。``target_calls`` 是目标模型被调用的次数——
    这正是投机解码要省的资源，比值越高质量越好。
    """
    prompt = _w7f_ids(prompt_ids, "speculative_decode")
    if not callable(draft_probs_fn) or not callable(target_probs_fn):
        raise ValueError("speculative_decode: 两个概率回调都必须可调用")
    if not isinstance(max_new_tokens, int) or isinstance(max_new_tokens, bool) \
            or max_new_tokens < 1:
        raise ValueError(
            f"speculative_decode: max_new_tokens 必须是 >=1 的整数，收到 {max_new_tokens!r}")
    if not isinstance(gamma, int) or isinstance(gamma, bool) or gamma < 1:
        raise ValueError(f"speculative_decode: gamma 必须是 >=1 的整数，收到 {gamma!r}")
    if eos_id is not None and (isinstance(eos_id, bool) or not isinstance(eos_id, int)
                               or eos_id < 0):
        raise ValueError(f"speculative_decode: eos_id 必须是非负整数，收到 {eos_id!r}")

    rng = random.Random(seed)
    ids = list(prompt)
    produced = 0
    rounds = 0
    proposed = 0
    accepted_total = 0
    draft_calls = 0
    target_calls = 0
    vocab = None

    while produced < max_new_tokens:
        want = min(gamma, max_new_tokens - produced)
        drafted = []
        draft_probs = []
        ctx = list(ids)
        for _ in range(want):
            p = _w7f_probs(draft_probs_fn, ctx, vocab)
            draft_calls += 1
            if vocab is None:
                vocab = len(p)
            tok = _w7f_sample(p, rng)
            drafted.append(tok)
            draft_probs.append(p)
            ctx = ctx + [tok]
        rounds += 1
        proposed += len(drafted)

        target_probs = []
        for k in range(len(drafted)):
            p = _w7f_probs(target_probs_fn, ids + drafted[:k], vocab)
            target_calls += 1
            target_probs.append(p)

        n_ok, resid = speculative_accept(drafted, draft_probs, target_probs, rng=rng)
        ids.extend(drafted[:n_ok])
        accepted_total += n_ok
        produced += n_ok
        if resid is not None and produced < max_new_tokens:
            ids.append(int(resid))
            produced += 1
        if eos_id is not None and eos_id in ids[len(prompt):]:
            break

    stats = {
        "rounds": rounds,
        "proposed": proposed,
        "accepted": accepted_total,
        "draft_calls": draft_calls,
        "target_calls": target_calls,
        "accept_rate": (accepted_total / proposed) if proposed else 0.0,
        "tokens_per_target_call": (produced / target_calls) if target_calls else 0.0,
    }
    return {"ids": ids, "stats": stats}


def _w7f_partial_logits(model, ids, n_layers):
    """只跑前 ``n_layers`` 个编码器块（自投机草稿的机制演示）。"""
    for name in ("embedding", "pos", "encoder", "W_out", "b_out", "vocab_size"):
        if not hasattr(model, name):
            raise ValueError(
                f"self_speculative_probs: 模型缺少 {name}，需要 CausalLM 这类结构")
    emb = model.embedding.forward(list(ids))
    x = model.pos.forward(emb) if getattr(model, "use_abs_pos", False) else emb
    layers = model.encoder.layers
    if not isinstance(n_layers, int) or isinstance(n_layers, bool) \
            or not 1 <= n_layers <= len(layers):
        raise ValueError(
            f"self_speculative_probs: draft_layers 必须在 1..{len(layers)}，收到 {n_layers!r}")
    for layer in layers[:n_layers]:
        x = layer.forward(x)
    logits = _matmul(x, _transpose(model.W_out))
    for t in range(len(x)):
        for v in range(model.vocab_size):
            logits[t][v] += model.b_out[v]
    return logits


def self_speculative_probs(model, draft_layers=1):
    """自投机解码的草稿回调：用同一模型的前 ``draft_layers`` 个块当草稿。

    这是「自投机（self-speculative）」的最小机制演示：草稿与目标共享词嵌入与
    输出头，只少跑几层 Transformer，所以不需要第二个模型；代价是草稿质量随层数
    下降，接受率也随之下降。返回 ``fn(ids) -> probs``，可直接传给
    ``speculative_decode``。

    Medusa（多个解码头 + 树状验证）与 EAGLE（在特征空间上做草稿）本库**只解释
    机制、不实现**：前者需要训练额外的头，后者需要特征级对齐，都不是纯前向
    能演示的，README 里写清了这条边界。
    """
    if not isinstance(draft_layers, int) or isinstance(draft_layers, bool) \
            or draft_layers < 1:
        raise ValueError(
            f"self_speculative_probs: draft_layers 必须是 >=1 的整数，收到 {draft_layers!r}")
    layers = getattr(getattr(model, "encoder", None), "layers", None)
    if layers is not None and draft_layers > len(layers):
        raise ValueError(
            f"self_speculative_probs: draft_layers={draft_layers} 超过模型的 "
            f"{len(layers)} 个编码器块")

    def probs_fn(ids):
        logits = _w7f_partial_logits(model, ids, draft_layers)
        return _softmax_row(list(logits[-1]))

    return probs_fn


def target_probs(model):
    """把模型的完整前向包装成 ``fn(ids) -> probs``（目标模型侧回调）。"""
    if not hasattr(model, "forward"):
        raise ValueError("target_probs: 模型必须有 forward")

    def probs_fn(ids):
        logits = model.forward(list(ids))
        row = logits[-1] if isinstance(logits, (list, tuple)) and logits and \
            isinstance(logits[0], (list, tuple)) else logits
        return _softmax_row(list(row))

    return probs_fn


# ============================================================================
#  GAN 变体族（DCGAN / WGAN-GP / StyleGAN 简化 / CycleGAN 简化 /
#        Pix2Pix / Progressive Growing）
# ============================================================================
#  诚实边界（同时写在 README 与各 docstring 里）：
#  * DCGAN 生成器 / 判别器是**真能训练**的小卷积网络（前向 + 手写反向 + SGD）。
#    没有 BatchNorm——本库 BN2d 反向返回三元组，混进这条手写链会让梯度约定变复杂，
#    因此它是 "DCGAN 风格的最小卷积 GAN"，不是论文复刻。
#  * StyleGAN / CycleGAN / Pix2Pix / Progressive 只提供**构件与损失**：
#    AdaIN 调制、截断技巧、循环一致性、identity 映射、patch 判别器目标、
#    淡入混合与逐阶段调度。完整的风格网络 / 双生成器循环 / U-Net 跳连 / 逐阶段
#    增长都需要成对训练基础设施，本库不提供空壳接口。
#  * WGAN-GP 的罚项是**真算**的：用手写反向对输入求 ∇_x D，而不是数值差分。

def _w8a_channels(value, who):
    """通道元组校验：正整数序列"""
    if not isinstance(value, (list, tuple)) or not value:
        raise ValueError(f"{who}: channels 必须是非空 list/tuple，收到 {value!r}")
    out = []
    for c in value:
        if isinstance(c, bool) or not isinstance(c, int) or c < 1:
            raise ValueError(f"{who}: channels 里必须都是 >=1 的整数，收到 {c!r}")
        out.append(c)
    return tuple(out)


def _w8a_pos_int(value, name, who, minimum=1):
    if isinstance(value, bool) or not isinstance(value, int) or value < minimum:
        raise ValueError(f"{who}: {name} 必须是 >= {minimum} 的整数，收到 {value!r}")
    return value


def _w8a_image(x, channels, who):
    """校验 (C, H, W) 并返回 (H, W)"""
    if not isinstance(x, (list, tuple)) or len(x) != channels:
        raise ValueError(
            f"{who}: 输入必须是 {channels} 通道的 (C, H, W)，收到 {type(x).__name__}")
    if not x or not x[0] or not x[0][0]:
        raise ValueError(f"{who}: 图像不能为空")
    h, w = len(x[0]), len(x[0][0])
    for c in range(channels):
        if len(x[c]) != h:
            raise ValueError(f"{who}: 通道 {c} 高度 {len(x[c])} 与第 0 通道 {h} 不一致")
        for r in range(h):
            if len(x[c][r]) != w:
                raise ValueError(
                    f"{who}: 通道 {c} 第 {r} 行宽 {len(x[c][r])} 与 {w} 不一致")
            for v in x[c][r]:
                if isinstance(v, bool) or not isinstance(v, (int, float)):
                    raise ValueError(f"{who}: 像素必须是数字，收到 {v!r}")
    return h, w


def _w8a_zeros(shape):
    c, h, w = shape
    return [[[0.0] * w for _ in range(h)] for _ in range(c)]


def _w8a_relu(x):
    """逐元素 ReLU，返回 (y, mask)"""
    y = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in x]
    mask = [[[1.0 if v > 0.0 else 0.0 for v in row] for row in ch] for ch in x]
    return y, mask


def _w8a_leaky(x, slope=0.2):
    """LeakyReLU，返回 (y, mask)（负数位置的 mask 记 slope）"""
    y = [[[v if v > 0.0 else slope * v for v in row] for row in ch] for ch in x]
    mask = [[[1.0 if v > 0.0 else slope for v in row] for row in ch] for ch in x]
    return y, mask


def _w8a_tanh(x):
    return [[[math.tanh(v) for v in row] for row in ch] for ch in x]


def _w8a_mask_grad(dout, mask):
    """按元素乘 mask（形状须一致）"""
    c, h, w = len(dout), len(dout[0]), len(dout[0][0])
    return [[[dout[k][i][j] * mask[k][i][j] for j in range(w)] for i in range(h)]
            for k in range(c)]


def _w8a_flat(x):
    out = []
    for ch in x:
        for row in ch:
            out.extend(float(v) for v in row)
    return out


def _w8a_unflat(flat, shape):
    c, h, w = shape
    if len(flat) != c * h * w:
        raise ValueError(
            f"_w8a_unflat: 需要 {c * h * w} 个元素，收到 {len(flat)}")
    out = _w8a_zeros(shape)
    p = 0
    for k in range(c):
        for i in range(h):
            for j in range(w):
                out[k][i][j] = float(flat[p])
                p += 1
    return out


def _w8a_is_conv(layer):
    return isinstance(layer, (Conv2d, ConvTranspose2d))


def _w8a_layer_params(layer):
    """权重 + 偏置个数（Layer / Conv2d / ConvTranspose2d 三种布局）"""
    if isinstance(layer, Layer):
        return layer.fan_in * layer.fan_out + layer.fan_out
    if isinstance(layer, ConvTranspose2d):
        return (layer.in_channels * layer.og * layer.kh * layer.kw
                + layer.out_channels)
    if isinstance(layer, Conv2d):
        return (layer.out_channels * layer.cg * layer.kh * layer.kw
                + layer.out_channels)
    raise ValueError(f"_w8a_layer_params: 不认识的层 {type(layer).__name__}")


def _w8a_accum_layer(layer, gw, gb):
    """把 `(grad_w, grad_b)` 累加进 Layer 的梯度缓冲

    `Layer.backward` 只返回三元组、**不保存**梯度（库内约定），而
    `ConvTranspose2d` / `Conv2d` 会自己累积。所以手写反向的容器要替
    Layer 建缓冲，否则 `sgd_step` 无从下手。
    """
    if getattr(layer, "grad_w", None) is None:
        layer.grad_w = [[0.0] * layer.fan_in for _ in range(layer.fan_out)]
        layer.grad_b = [0.0] * layer.fan_out
    for j in range(layer.fan_out):
        row = layer.grad_w[j]
        g_row = gw[j]
        for i in range(layer.fan_in):
            row[i] += g_row[i]
        layer.grad_b[j] += gb[j]


def _w8a_sgd_layer(layer, lr):
    """对单层做一步 SGD；Layer 用自建缓冲，卷积层用它自己的 sgd_step

    返回是否真的更新了（Layer 从未反向过时返回 False）。
    """
    if isinstance(layer, Layer):
        gw = getattr(layer, "grad_w", None)
        gb = getattr(layer, "grad_b", None)
        if gw is None or gb is None:
            return False
        for j in range(layer.fan_out):
            w_row = layer.weights[j]
            g_row = gw[j]
            for i in range(layer.fan_in):
                w_row[i] -= lr * g_row[i]
            layer.biases[j] -= lr * gb[j]
        return True
    layer.sgd_step(lr)
    return True


def _w8a_zero_grad_layer(layer):
    """把 grad_w / grad_b 清零（Layer 与两种卷积层）

    Layer 的梯度缓冲要等第一次 backward 才存在，所以在没跑过反向时
    这里应当安静地什么都不做，而不是 AttributeError。
    """
    if isinstance(layer, Layer):
        gw = getattr(layer, "grad_w", None)
        gb = getattr(layer, "grad_b", None)
        if gw is None or gb is None:
            return
        for j in range(layer.fan_out):
            for i in range(layer.fan_in):
                gw[j][i] = 0.0
            gb[j] = 0.0
        return
    for ci in range(layer.in_channels if isinstance(layer, ConvTranspose2d)
                    else layer.out_channels):
        g_w = layer.grad_w[ci]
        slot = g_w if isinstance(layer, ConvTranspose2d) else g_w
        if isinstance(layer, ConvTranspose2d):
            for og in range(layer.og):
                for a in range(layer.kh):
                    for b in range(layer.kw):
                        slot[og][a][b] = 0.0
        else:
            for g in slot:
                for a in range(len(g)):
                    for b in range(len(g[a])):
                        g[a][b] = 0.0
    for o in range(layer.out_channels):
        layer.grad_b[o] = 0.0


def upsample_nearest2d(x, scale=2):
    """最近邻上采样：每个像素复制成 scale×scale 的块"""
    c = len(x) if isinstance(x, (list, tuple)) else 1
    h, w = _w8a_image(x, c, "upsample_nearest2d")
    scale = _w8a_pos_int(scale, "scale", "upsample_nearest2d")
    out = _w8a_zeros((c, h * scale, w * scale))
    for k in range(c):
        for i in range(h):
            for j in range(w):
                v = float(x[k][i][j])
                for di in range(scale):
                    for dj in range(scale):
                        out[k][i * scale + di][j * scale + dj] = v
    return out


def fade_in(low_res, high_res, alpha):
    """Progressive growing 的淡入：`(1-α)·上采样(低分辨率) + α·高分辨率`"""
    if isinstance(alpha, bool) or not isinstance(alpha, (int, float)):
        raise ValueError(f"fade_in: alpha 必须是数字，收到 {alpha!r}")
    a = float(alpha)
    if not (0.0 <= a <= 1.0):
        raise ValueError(f"fade_in: alpha 必须在 [0, 1]，收到 {alpha!r}")
    c = len(low_res)
    lh, lw = _w8a_image(low_res, c, "fade_in(low_res)")
    hh, hw = _w8a_image(high_res, c, "fade_in(high_res)")
    if (hh, hw) != (lh * 2, lw * 2):
        raise ValueError(
            f"fade_in: 高分辨率必须是低分辨率的 2 倍，收到 {lh}x{lw} 与 {hh}x{hw}")
    up = upsample_nearest2d(low_res, 2)
    return [[[(1.0 - a) * up[k][i][j] + a * float(high_res[k][i][j])
              for j in range(hw)] for i in range(hh)] for k in range(c)]


def progressive_alpha(step, total):
    """淡入系数：`step/total` 夹到 [0, 1]"""
    for name, value in (("step", step), ("total", total)):
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError(
                f"progressive_alpha: {name} 必须是 >=0 的整数，收到 {value!r}")
    if total < 1:
        raise ValueError(f"progressive_alpha: total 必须 >= 1，收到 {total!r}")
    return min(1.0, max(0.0, step / float(total)))


def progressive_stages(resolutions, fade_steps=10):
    """把递增的分辨率序列展开成 `[(low, high, alpha), ...]` 的逐阶段调度"""
    if not isinstance(resolutions, (list, tuple)) or len(resolutions) < 2:
        raise ValueError("progressive_stages: resolutions 至少要有两个分辨率")
    res = []
    for r in resolutions:
        r = _w8a_pos_int(r, "resolution", "progressive_stages")
        if res and r <= res[-1]:
            raise ValueError(f"progressive_stages: 分辨率必须递增，收到 {res + [r]}")
        res.append(r)
    fade_steps = _w8a_pos_int(fade_steps, "fade_steps", "progressive_stages")
    stages = []
    for i in range(1, len(res)):
        for s in range(fade_steps):
            stages.append((res[i - 1], res[i], progressive_alpha(s, fade_steps)))
        stages.append((res[i - 1], res[i], 1.0))
    return stages


class DCGANGenerator:
    """DCGAN 风格的最小卷积生成器：`z -> 线性 -> 逐级 ConvTranspose2d -> tanh`

    `channels=(c0, c1, ...)`：潜变量先线性升到 `c0 × base × base`，
    再对每个后续通道做一次 `ConvTranspose2d(k=4, stride=2, padding=1)`（分辨率翻倍），
    中间 ReLU，最后再翻倍一次到 `out_channels` 并 `tanh` 到 [-1, 1]。
    """

    def __init__(self, latent_dim=8, channels=(8, 4), out_channels=1, base=2,
                 seed=None):
        self.name = "DCGANGenerator"
        self.latent_dim = _w8a_pos_int(latent_dim, "latent_dim", self.name)
        self.channels = _w8a_channels(channels, self.name)
        self.out_channels = _w8a_pos_int(out_channels, "out_channels", self.name)
        self.base = _w8a_pos_int(base, "base", self.name)
        if seed is not None and (isinstance(seed, bool) or not isinstance(seed, int)):
            raise ValueError(f"{self.name}: seed 必须是整数或 None")
        prev = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.fc = Layer(self.latent_dim, self.channels[0] * self.base * self.base,
                            activation="relu")
            self.convs = []
            cur = self.channels[0]
            for nxt in self.channels[1:]:
                self.convs.append(ConvTranspose2d(cur, nxt, 4, stride=2, padding=1))
                cur = nxt
            self.out_conv = ConvTranspose2d(cur, self.out_channels, 4, stride=2,
                                            padding=1)
        finally:
            if seed is not None:
                random.setstate(prev)
        self._cache = None

    def out_shape(self):
        """生成图像形状 `(C, H, W)`"""
        side = self.base * (2 ** (len(self.convs) + 1))
        return (self.out_channels, side, side)

    def forward(self, z):
        if not isinstance(z, (list, tuple)) or len(z) != self.latent_dim:
            got = len(z) if isinstance(z, (list, tuple)) else type(z).__name__
            raise ValueError(f"{self.name}.forward: z 维度应为 {self.latent_dim}，收到 {got}")
        for v in z:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f"{self.name}.forward: z 里必须是数字，收到 {v!r}")
        h = self.fc.forward(list(z))
        x = _w8a_unflat(h, (self.channels[0], self.base, self.base))
        masks = []
        for conv in self.convs:
            x = conv.forward(x)
            x, m = _w8a_relu(x)
            masks.append(m)
        x = self.out_conv.forward(x)
        out = _w8a_tanh(x)
        self._cache = (masks, out)
        return out

    def backward(self, dout):
        """返回对 z 的梯度；参数梯度累加在各自层里（与库内一致）"""
        if self._cache is None:
            raise ValueError(f"{self.name}.backward: 必须先 forward")
        masks, out = self._cache
        _w8a_image(dout, self.out_channels, f"{self.name}.backward")
        d = [[[(1.0 - o * o) * g for o, g in zip(ro, rg)]
              for ro, rg in zip(co, cg)] for co, cg in zip(out, dout)]
        d = self.out_conv.backward(d)
        for conv, m in zip(reversed(self.convs), reversed(masks)):
            d = _w8a_mask_grad(d, m)
            d = conv.backward(d)
        gw, gb, dz = self.fc.backward(_w8a_flat(d))
        _w8a_accum_layer(self.fc, gw, gb)
        return dz

    def layers(self):
        return [self.fc] + list(self.convs) + [self.out_conv]

    def zero_grad(self):
        for layer in self.layers():
            _w8a_zero_grad_layer(layer)

    def param_count(self):
        return sum(_w8a_layer_params(layer) for layer in self.layers())

    def sgd_step(self, lr):
        for layer in self.layers():
            _w8a_sgd_layer(layer, lr)


class DCGANDiscriminator:
    """DCGAN 风格的最小卷积判别器：`Conv2d(stride=2) × n -> Flatten -> 线性分数`

    输出是**裸分数**（不是概率），可直接接 hinge / WGAN 损失；要概率就
    `prob(x)`（内部取 sigmoid）。
    """

    def __init__(self, in_channels=1, channels=(4, 8), base=8, seed=None):
        self.name = "DCGANDiscriminator"
        self.in_channels = _w8a_pos_int(in_channels, "in_channels", self.name)
        self.channels = _w8a_channels(channels, self.name)
        self.base = _w8a_pos_int(base, "base", self.name)
        div = 2 ** len(self.channels)
        if self.base % div != 0:
            raise ValueError(f"{self.name}: base={self.base} 必须能被 2^{len(self.channels)} 整除")
        if seed is not None and (isinstance(seed, bool) or not isinstance(seed, int)):
            raise ValueError(f"{self.name}: seed 必须是整数或 None")
        prev = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.convs = []
            cur = self.in_channels
            for nxt in self.channels:
                self.convs.append(Conv2d(cur, nxt, 4, stride=2, padding=1))
                cur = nxt
            side = self.base // div
            self._feat_shape = (self.channels[-1], side, side)
            self.out = Layer(self.channels[-1] * side * side, 1, activation="linear")
        finally:
            if seed is not None:
                random.setstate(prev)
        self._cache = None

    def forward(self, x):
        _w8a_image(x, self.in_channels, f"{self.name}.forward")
        masks = []
        h = x
        for conv in self.convs:
            h = conv.forward(h)
            h, m = _w8a_leaky(h)
            masks.append(m)
        flat = _w8a_flat(h)
        score = self.out.forward(flat)[0]
        self._cache = (masks, flat)
        return score

    def prob(self, x):
        return _sigmoid_scalar(self.forward(x))

    def backward(self, dscore):
        """返回对输入图像的梯度；参数梯度累加在各层里"""
        if self._cache is None:
            raise ValueError(f"{self.name}.backward: 必须先 forward")
        if isinstance(dscore, bool) or not isinstance(dscore, (int, float)):
            raise ValueError(f"{self.name}.backward: dscore 必须是数字，收到 {dscore!r}")
        masks, _ = self._cache
        gw, gb, d_flat = self.out.backward([float(dscore)])
        _w8a_accum_layer(self.out, gw, gb)
        d = _w8a_unflat(d_flat, self._feat_shape)
        for conv, m in zip(reversed(self.convs), reversed(masks)):
            d = _w8a_mask_grad(d, m)
            d = conv.backward(d)
        return d

    def layers(self):
        return list(self.convs) + [self.out]

    def zero_grad(self):
        for layer in self.layers():
            _w8a_zero_grad_layer(layer)

    def param_count(self):
        return sum(_w8a_layer_params(layer) for layer in self.layers())

    def sgd_step(self, lr):
        for layer in self.layers():
            _w8a_sgd_layer(layer, lr)


def _w8a_interpolate(real, fake, eps):
    """逐像素线性插值 `x̂ = ε·real + (1-ε)·fake`，并返回形状"""
    c = len(real)
    h, w = _w8a_image(real, c, "wgan_gp_penalty(real)")
    hf, wf = _w8a_image(fake, c, "wgan_gp_penalty(fake)")
    if (hf, wf) != (h, w):
        raise ValueError(f"wgan_gp_penalty: real 与 fake 形状不一致 ({h}x{w} vs {hf}x{wf})")
    out = [[[eps * float(real[k][i][j]) + (1.0 - eps) * float(fake[k][i][j])
             for j in range(w)] for i in range(h)] for k in range(c)]
    return out


def wgan_gp_penalty(discriminator, real, fake, lambda_gp=10.0, seed=None):
    """WGAN-GP 梯度罚项：`λ·(‖∇_x D(x̂)‖₂ − 1)²`，`x̂` 在 real/fake 连线上随机取

    梯度是**真算**的（对输入手写反向），不是数值差分。注意：为了取 ∇_x D，
    这里会调用 `discriminator.backward`，因此**会污染判别器的参数梯度缓冲**，
    调用前请先 `discriminator.zero_grad()`、调用后再清零（文档已说明）。
    返回 `{"penalty", "grad_norms", "penalty_unscaled"}`。
    """
    if isinstance(lambda_gp, bool) or not isinstance(lambda_gp, (int, float)) or lambda_gp < 0:
        raise ValueError(f"wgan_gp_penalty: lambda_gp 必须是非负数，收到 {lambda_gp!r}")
    if seed is not None and (isinstance(seed, bool) or not isinstance(seed, int)):
        raise ValueError("wgan_gp_penalty: seed 必须是整数或 None")
    rng = random.Random(seed)
    eps = rng.random()
    x_hat = _w8a_interpolate(real, fake, eps)
    # 必须先对 x_hat 前向：否则 backward 用的是上一次 forward 的缓存，
    # 梯度会落在别的输入点上（实测 ‖∇D‖ 1.1661 vs 真实 1.3400）
    discriminator.forward(x_hat)
    d = discriminator.backward(1.0)
    norms = []
    for ch in d:
        for row in ch:
            for v in row:
                norms.append(float(v) * float(v))
    norm = math.sqrt(sum(norms))
    penalty = lambda_gp * (norm - 1.0) ** 2
    return {"penalty": penalty, "grad_norms": norm,
            "penalty_unscaled": (norm - 1.0) ** 2, "eps": eps}


def adain_style(features, style, eps=1e-5):
    """AdaIN：按通道把 features 标准化后再用 style 的 (scale, bias) 调制

    `style` 是长度 `2*C` 的 list（前半 scale、后半 bias），返回 `(out, cache)`
    以便调用方需要时手写反向；本函数只做前向。
    """
    c = len(features)
    h, w = _w8a_image(features, c, "adain_style")
    if not isinstance(style, (list, tuple)) or len(style) != 2 * c:
        raise ValueError(f"adain_style: style 长度应为 {2 * c}，收到 "
                         f"{len(style) if isinstance(style, (list, tuple)) else type(style).__name__}")
    if isinstance(eps, bool) or not isinstance(eps, (int, float)) or eps <= 0:
        raise ValueError(f"adain_style: eps 必须是正数，收到 {eps!r}")
    out = _w8a_zeros((c, h, w))
    stats = []
    for k in range(c):
        vals = [float(v) for row in features[k] for v in row]
        mean = sum(vals) / len(vals)
        var = sum((v - mean) ** 2 for v in vals) / len(vals)
        std = math.sqrt(var + float(eps))
        stats.append((mean, std))
        scale, bias = float(style[k]), float(style[c + k])
        for i in range(h):
            for j in range(w):
                out[k][i][j] = (float(features[k][i][j]) - mean) / std * scale + bias
    return out, stats


def truncation_trick(w, w_avg, psi=0.7):
    """StyleGAN 截断：`w' = w_avg + ψ·(w − w_avg)`，ψ∈[0,1] 越小越"平均脸\""""
    if isinstance(psi, bool) or not isinstance(psi, (int, float)):
        raise ValueError(f"truncation_trick: psi 必须是数字，收到 {psi!r}")
    if not (0.0 <= float(psi) <= 1.0):
        raise ValueError(f"truncation_trick: psi 必须在 [0, 1]，收到 {psi!r}")
    if not isinstance(w, (list, tuple)) or not isinstance(w_avg, (list, tuple)):
        raise ValueError("truncation_trick: w 与 w_avg 都必须是序列")
    if len(w) != len(w_avg):
        raise ValueError(f"truncation_trick: 维度不一致，{len(w)} vs {len(w_avg)}")
    p = float(psi)
    out = []
    for a, b in zip(w, w_avg):
        if isinstance(a, bool) or not isinstance(a, (int, float)) or \
                isinstance(b, bool) or not isinstance(b, (int, float)):
            raise ValueError("truncation_trick: w 与 w_avg 里必须是数字")
        out.append(float(b) + p * (float(a) - float(b)))
    return out


def cycle_consistency_loss(a, a_rec, b, b_rec, lambda_cycle=10.0):
    """CycleGAN 循环一致性：`λ·(‖a − a_rec‖₁ + ‖b − b_rec‖₁)`，并返回两侧梯度"""
    if isinstance(lambda_cycle, bool) or not isinstance(lambda_cycle, (int, float)) \
            or lambda_cycle < 0:
        raise ValueError(
            f"cycle_consistency_loss: lambda_cycle 必须是非负数，收到 {lambda_cycle!r}")
    for name, x, y in (("a", a, a_rec), ("b", b, b_rec)):
        c = len(x)
        h, w = _w8a_image(x, c, f"cycle_consistency_loss({name})")
        hy, wy = _w8a_image(y, c, f"cycle_consistency_loss({name}_rec)")
        if (hy, wy) != (h, w):
            raise ValueError(
                f"cycle_consistency_loss: {name} 与重建形状不一致 ({h}x{w} vs {hy}x{wy})")
    total = 0.0
    grads = []
    for x, y, sign in ((a, a_rec, 1.0), (b, b_rec, 1.0)):
        c = len(x)
        h, w = len(x[0]), len(x[0][0])
        n = c * h * w
        g = _w8a_zeros((c, h, w))
        for k in range(c):
            for i in range(h):
                for j in range(w):
                    diff = float(x[k][i][j]) - float(y[k][i][j])
                    total += abs(diff)
                    g[k][i][j] = sign * (1.0 if diff > 0 else (-1.0 if diff < 0 else 0.0))
        grads.append([[[v * lambda_cycle / n for v in row] for row in ch] for ch in g])
    return lambda_cycle * total, grads


def identity_mapping_loss(a, g_ba, b, g_ab, lambda_identity=5.0):
    """CycleGAN identity 映射：`λ·(‖G_BA(a) − a‖₁ + ‖G_AB(b) − b‖₁)`"""
    if isinstance(lambda_identity, bool) or \
            not isinstance(lambda_identity, (int, float)) or lambda_identity < 0:
        raise ValueError("identity_mapping_loss: lambda_identity 必须是非负数，"
                         f"收到 {lambda_identity!r}")
    total = 0.0
    for x, y in ((a, g_ba), (b, g_ab)):
        c = len(x)
        h, w = _w8a_image(x, c, "identity_mapping_loss(x)")
        hy, wy = _w8a_image(y, c, "identity_mapping_loss(y)")
        if (hy, wy) != (h, w):
            raise ValueError("identity_mapping_loss: 形状不一致 "
                             f"({h}x{w} vs {hy}x{wy})")
        for k in range(c):
            for i in range(h):
                for j in range(w):
                    total += abs(float(x[k][i][j]) - float(y[k][i][j]))
    return lambda_identity * total


def patchgan_targets(height, width, real=True):
    """PatchGAN 判别器目标：全 real 填 1、全 fake 填 0 的 patch 网格"""
    height = _w8a_pos_int(height, "height", "patchgan_targets")
    width = _w8a_pos_int(width, "width", "patchgan_targets")
    if not isinstance(real, bool):
        raise ValueError(f"patchgan_targets: real 必须是 bool，收到 {real!r}")
    v = 1.0 if real else 0.0
    return [[v] * width for _ in range(height)]


def pix2pix_g_loss(fake_scores, fake_image, real_image, lambda_l1=100.0):
    """Pix2Pix 生成器损失：`BCE(D(fake), 1) + λ·L1(fake, real)`

    `fake_scores` 是 patch 分数网格（裸分数，内部取 sigmoid）。
    """
    if isinstance(lambda_l1, bool) or not isinstance(lambda_l1, (int, float)) \
            or lambda_l1 < 0:
        raise ValueError(f"pix2pix_g_loss: lambda_l1 必须是非负数，收到 {lambda_l1!r}")
    if not isinstance(fake_scores, (list, tuple)) or not fake_scores:
        raise ValueError("pix2pix_g_loss: fake_scores 必须是非空网格")
    bce = 0.0
    n = 0
    for row in fake_scores:
        for v in row:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f"pix2pix_g_loss: 分数必须是数字，收到 {v!r}")
            p = min(max(_sigmoid_scalar(float(v)), 1e-12), 1.0 - 1e-12)
            bce -= math.log(p)
            n += 1
    bce /= n
    c = len(fake_image)
    h, w = _w8a_image(fake_image, c, "pix2pix_g_loss(fake_image)")
    hr, wr = _w8a_image(real_image, c, "pix2pix_g_loss(real_image)")
    if (hr, wr) != (h, w):
        raise ValueError(f"pix2pix_g_loss: 图像形状不一致 ({h}x{w} vs {hr}x{wr})")
    l1 = 0.0
    for k in range(c):
        for i in range(h):
            for j in range(w):
                l1 += abs(float(fake_image[k][i][j]) - float(real_image[k][i][j]))
    l1 /= (c * h * w)
    return bce + float(lambda_l1) * l1

"""Pix2Pix 可训练基础设施：小型图像到图像生成器 + PatchGAN 判别器。"""


def _p2p_image(x, channels, who, minimum=4):
    if not isinstance(x, (list, tuple)) or len(x) != channels:
        raise ValueError(f"{who}: 输入必须是 {channels} 通道的 (C, H, W)")
    if not x or not x[0] or not x[0][0]:
        raise ValueError(f"{who}: 图像不能为空")
    h, w = len(x[0]), len(x[0][0])
    if h < minimum or w < minimum:
        raise ValueError(f"{who}: 高宽必须 >= {minimum}，收到 {h}x{w}")
    for c in range(channels):
        if len(x[c]) != h:
            raise ValueError(f"{who}: 通道 {c} 高度不一致")
        for r in range(h):
            if len(x[c][r]) != w:
                raise ValueError(f"{who}: 通道 {c} 第 {r} 行宽度不一致")
            for v in x[c][r]:
                if isinstance(v, bool) or not isinstance(v, (int, float)):
                    raise TypeError(f"{who}: 像素必须是数字，收到 {v!r}")
    return h, w


def _p2p_zeros_like(x):
    return [[[0.0 for _ in row] for row in ch] for ch in x]


def _p2p_sigmoid(v):
    if v >= 0.0:
        return 1.0 / (1.0 + math.exp(-v))
    e = math.exp(v)
    return e / (1.0 + e)


def _p2p_leaky_mask(x):
    return [[[1.0 if v > 0.0 else 0.0 for v in row] for row in ch] for ch in x]


def _p2p_apply_mask(d, mask, slope=0.2):
    return [[[d[c][i][j] * (mask[c][i][j] + slope * (1.0 - mask[c][i][j]))
              for j in range(len(d[c][i]))] for i in range(len(d[c]))] for c in range(len(d))]


def _p2p_sgd_layer(layer, lr):
    """Conv2d / ConvTranspose2d 通用 SGD 更新：递归更新权重，再按 biases 长度更新偏置。"""
    def upd(w, g):
        for i in range(len(w)):
            if isinstance(w[i], list):
                upd(w[i], g[i])
            else:
                w[i] -= lr * g[i]
    upd(layer.weights, layer.grad_w)
    for i in range(len(layer.biases)):
        layer.biases[i] -= lr * layer.grad_b[i]


def _p2p_bce(scores, target):
    """裸 logit 网格的 BCE，返回 (loss, dscore)。"""
    total = 0.0
    n = 0
    for row in scores:
        for v in row:
            p = _p2p_sigmoid(float(v))
            p = min(max(p, 1e-12), 1.0 - 1e-12)
            total -= target * math.log(p) + (1.0 - target) * math.log(1.0 - p)
            n += 1
    d = [[( _p2p_sigmoid(float(v)) - target) / n for v in row] for row in scores]
    return total / n if n else 0.0, d


class PatchDiscriminator:
    """三层小 PatchGAN：输入图像 → 分数网格（裸 logit）。"""

    def __init__(self, in_channels=1, base=4, seed=None):
        for name, v in (("in_channels", in_channels), ("base", base)):
            if isinstance(v, bool) or not isinstance(v, int) or v < 1:
                raise ValueError(f"PatchDiscriminator: {name} 必须是正整数，收到 {v!r}")
        self.in_channels = in_channels
        self.base = base
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.conv1 = Conv2d(in_channels, base, 3, stride=2, padding=1)
            self.conv2 = Conv2d(base, 2 * base, 3, stride=2, padding=1)
            self.conv3 = Conv2d(2 * base, 1, 3, padding=1)
        finally:
            random.setstate(state)
        self._cache = None

    def zero_grad(self):
        for c in (self.conv1, self.conv2, self.conv3):
            c.zero_grad()

    def param_count(self):
        return sum(_conv_param_count(c) for c in (self.conv1, self.conv2, self.conv3))

    def sgd_step(self, lr):
        for c in (self.conv1, self.conv2, self.conv3):
            _p2p_sgd_layer(c, lr)

    def forward(self, image):
        h, w = _p2p_image(image, self.in_channels, "PatchDiscriminator.forward")
        o1 = self.conv1.forward(image)
        m1 = _p2p_leaky_mask(o1)
        a1 = [[[v if v > 0.0 else 0.2 * v for v in row] for row in ch] for ch in o1]
        o2 = self.conv2.forward(a1)
        m2 = _p2p_leaky_mask(o2)
        a2 = [[[v if v > 0.0 else 0.2 * v for v in row] for row in ch] for ch in o2]
        o3 = self.conv3.forward(a2)
        scores = [[o3[0][i][j] for j in range(len(o3[0][0]))] for i in range(len(o3[0]))]
        self._cache = {"m1": m1, "m2": m2, "scores": scores}
        return scores

    def backward(self, dscore):
        if self._cache is None:
            raise RuntimeError("PatchDiscriminator.backward: 先调用 forward")
        scores = self._cache["scores"]
        hh, ww = len(scores), len(scores[0])
        if not isinstance(dscore, (list, tuple)) or len(dscore) != hh or len(dscore[0]) != ww:
            raise ValueError("PatchDiscriminator.backward: dscore 形状与分数网格不一致")
        d_o3 = [[[float(dscore[i][j]) for j in range(ww)] for i in range(hh)]]
        d_a2 = self.conv3.backward(d_o3)
        d_o2 = _p2p_apply_mask(d_a2, self._cache["m2"])
        d_a1 = self.conv2.backward(d_o2)
        d_o1 = _p2p_apply_mask(d_a1, self._cache["m1"])
        return self.conv1.backward(d_o1)


class Pix2PixGenerator:
    """小型图像到图像生成器：两次 stride-2 卷积编码 + 两次转置卷积解码。"""

    def __init__(self, in_channels=1, out_channels=1, base=4, seed=None):
        for name, v in (("in_channels", in_channels), ("out_channels", out_channels),
                        ("base", base)):
            if isinstance(v, bool) or not isinstance(v, int) or v < 1:
                raise ValueError(f"Pix2PixGenerator: {name} 必须是正整数，收到 {v!r}")
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.base = base
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.enc1 = Conv2d(in_channels, base, 3, stride=2, padding=1)
            self.enc2 = Conv2d(base, 2 * base, 3, stride=2, padding=1)
            self.dec1 = ConvTranspose2d(2 * base, base, 4, stride=2, padding=1)
            self.dec2 = ConvTranspose2d(base, out_channels, 4, stride=2, padding=1)
        finally:
            random.setstate(state)
        self._cache = None

    def zero_grad(self):
        for c in (self.enc1, self.enc2, self.dec1, self.dec2):
            c.zero_grad()

    def param_count(self):
        return sum(_conv_param_count(c) for c in (self.enc1, self.enc2, self.dec1, self.dec2))

    def sgd_step(self, lr):
        for name in ("enc1", "enc2", "dec1", "dec2"):
            _p2p_sgd_layer(getattr(self, name), lr)

    def forward(self, image):
        _p2p_image(image, self.in_channels, "Pix2PixGenerator.forward")
        o1 = self.enc1.forward(image)
        m1 = _p2p_leaky_mask(o1)
        a1 = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in o1]
        o2 = self.enc2.forward(a1)
        m2 = _p2p_leaky_mask(o2)
        a2 = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in o2]
        o3 = self.dec1.forward(a2)
        m3 = _p2p_leaky_mask(o3)
        a3 = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in o3]
        out = self.dec2.forward(a3)
        y = [[[math.tanh(v) for v in row] for row in ch] for ch in out]
        self._cache = {"m1": m1, "m2": m2, "m3": m3, "y": y}
        return y

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("Pix2PixGenerator.backward: 先调用 forward")
        y = self._cache["y"]
        h, w = len(y[0]), len(y[0][0])
        if not isinstance(dout, (list, tuple)) or len(dout) != len(y) \
                or len(dout[0]) != h or len(dout[0][0]) != w:
            raise ValueError("Pix2PixGenerator.backward: dout 形状与输出不一致")
        d_out = [[[float(dout[c][i][j]) * (1.0 - y[c][i][j] * y[c][i][j])
                   for j in range(w)] for i in range(h)] for c in range(len(y))]
        d_a3 = self.dec2.backward(d_out)
        d_o3 = _p2p_apply_mask(d_a3, self._cache["m3"], slope=0.0)
        d_a2 = self.dec1.backward(d_o3)
        d_o2 = _p2p_apply_mask(d_a2, self._cache["m2"], slope=0.0)
        d_a1 = self.enc2.backward(d_o2)
        d_o1 = _p2p_apply_mask(d_a1, self._cache["m1"], slope=0.0)
        return self.enc1.backward(d_o1)


def _p2p_l1_and_grad(fake, real, weight):
    c = len(fake)
    h, w = len(fake[0]), len(fake[0][0])
    n = c * h * w
    total = 0.0
    d = [[[0.0 for _ in range(w)] for _ in range(h)] for _ in range(c)]
    for k in range(c):
        for i in range(h):
            for j in range(w):
                diff = float(fake[k][i][j]) - float(real[k][i][j])
                total += abs(diff)
                d[k][i][j] = weight * (1.0 if diff > 0 else (-1.0 if diff < 0 else 0.0)) / n
    return weight * total / n, d


def train_pix2pix_step(generator, discriminator, source, target,
                       lambda_l1=100.0, lr_g=1e-3, lr_d=1e-3):
    """一步 Pix2Pix 训练：先更新判别器，再更新生成器，返回两项损失。"""
    if not isinstance(generator, Pix2PixGenerator):
        raise TypeError("train_pix2pix_step: generator 必须是 Pix2PixGenerator")
    if not isinstance(discriminator, PatchDiscriminator):
        raise TypeError("train_pix2pix_step: discriminator 必须是 PatchDiscriminator")
    if isinstance(lambda_l1, bool) or not isinstance(lambda_l1, (int, float)) or lambda_l1 < 0:
        raise ValueError("train_pix2pix_step: lambda_l1 必须是非负数")
    h, w = _p2p_image(source, generator.in_channels, "train_pix2pix_step(source)")
    h2, w2 = _p2p_image(target, generator.out_channels, "train_pix2pix_step(target)")
    if (h2, w2) != (h, w):
        raise ValueError("train_pix2pix_step: source 与 target 形状不一致")

    # 1) 判别器：真图目标 1、假图目标 0
    fake = generator.forward(source)
    discriminator.zero_grad()
    real_scores = discriminator.forward(target)
    loss_d_real, d_real = _p2p_bce(real_scores, 1.0)
    discriminator.backward(d_real)
    fake_scores = discriminator.forward(fake)
    loss_d_fake, d_fake = _p2p_bce(fake_scores, 0.0)
    discriminator.backward(d_fake)
    discriminator.sgd_step(lr_d)
    loss_d = 0.5 * (loss_d_real + loss_d_fake)

    # 2) 生成器：BCE(D(fake), 1) + λ·L1(fake, target)
    generator.zero_grad()
    discriminator.zero_grad()
    fake = generator.forward(source)
    fake_scores = discriminator.forward(fake)
    loss_bce, d_score = _p2p_bce(fake_scores, 1.0)
    l1, d_l1 = _p2p_l1_and_grad(fake, target, lambda_l1)
    d_fake = discriminator.backward(d_score)
    for k in range(len(d_fake)):
        for i in range(len(d_fake[k])):
            for j in range(len(d_fake[k][i])):
                d_fake[k][i][j] += d_l1[k][i][j]
    generator.backward(d_fake)
    generator.sgd_step(lr_g)
    return {"d_loss": loss_d, "g_loss": loss_bce + l1}


def fit_pix2pix(generator, discriminator, pairs, steps=30, lambda_l1=100.0,
                lr_g=1e-3, lr_d=1e-3, seed=None):
    """在固定的 (source, target) 对上循环训练，返回每步损失。"""
    if not isinstance(pairs, (list, tuple)) or not pairs:
        raise ValueError("fit_pix2pix: pairs 不能为空")
    rng = random.Random(seed) if seed is not None else random
    history = []
    for _ in range(steps):
        source, target = pairs[rng.randrange(len(pairs))]
        history.append(train_pix2pix_step(
            generator, discriminator, source, target,
            lambda_l1=lambda_l1, lr_g=lr_g, lr_d=lr_d))
    return history

# =============================================================================
"""StyleGAN 轻量可训练生成器：映射网络 + 常数输入 + AdaIN 风格调制 + 逐级上采样。"""


def _sg_check_int(value, name, minimum=1):
    if isinstance(value, bool) or not isinstance(value, int) or value < minimum:
        raise ValueError(f"{name} 必须是 >= {minimum} 的整数，收到 {value!r}")
    return value


def _sg_scale_check(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or value <= 0:
        raise ValueError(f"{name} 必须是正数，收到 {value!r}")
    return float(value)


def _sg_zeros(channels, h, w):
    return [[[0.0 for _ in range(w)] for _ in range(h)] for _ in range(channels)]


def _sg_upsample(x):
    c, h, w = len(x), len(x[0]), len(x[0][0])
    out = _sg_zeros(c, 2 * h, 2 * w)
    for k in range(c):
        for i in range(h):
            for j in range(w):
                v = x[k][i][j]
                out[k][2 * i][2 * j] = v
                out[k][2 * i][2 * j + 1] = v
                out[k][2 * i + 1][2 * j] = v
                out[k][2 * i + 1][2 * j + 1] = v
    return out


def _sg_upsample_backward(dout, h, w):
    c = len(dout)
    out = _sg_zeros(c, h, w)
    for k in range(c):
        for i in range(h):
            for j in range(w):
                out[k][i][j] = (dout[k][2 * i][2 * j] + dout[k][2 * i][2 * j + 1]
                                + dout[k][2 * i + 1][2 * j] + dout[k][2 * i + 1][2 * j + 1])
    return out


def _sg_adain_backward(dout, cache):
    x, mean, std, scale, bias = cache["x"], cache["mean"], cache["std"], cache["scale"], cache["bias"]
    c, h, w = len(x), len(x[0]), len(x[0][0])
    n = h * w
    d_xhat = [[[dout[k][i][j] * scale[k] for j in range(w)] for i in range(h)] for k in range(c)]
    d_scale = [sum(dout[k][i][j] * (x[k][i][j] - mean[k]) / std[k]
                   for i in range(h) for j in range(w)) for k in range(c)]
    d_bias = [sum(dout[k][i][j] for i in range(h) for j in range(w)) for k in range(c)]
    dx = _sg_zeros(c, h, w)
    for k in range(c):
        m1 = sum(d_xhat[k][i][j] for i in range(h) for j in range(w)) / n
        m2 = sum(d_xhat[k][i][j] * (x[k][i][j] - mean[k]) / std[k]
                 for i in range(h) for j in range(w)) / n
        for i in range(h):
            for j in range(w):
                xhat = (x[k][i][j] - mean[k]) / std[k]
                dx[k][i][j] = (d_xhat[k][i][j] - m1 - xhat * m2) / std[k]
    d_style = d_scale + d_bias
    return dx, d_style


class StyleGANGenerator:
    """简化 StyleGAN：z → 映射网络 w；常数 4×4 特征逐级 AdaIN 调制并上采样到 16×16。"""

    def __init__(self, latent_dim=8, d_model=8, base=4, out_channels=1, seed=None):
        _sg_check_int(latent_dim, "StyleGANGenerator.latent_dim")
        _sg_check_int(d_model, "StyleGANGenerator.d_model")
        _sg_check_int(base, "StyleGANGenerator.base")
        _sg_check_int(out_channels, "StyleGANGenerator.out_channels")
        self.latent_dim = latent_dim
        self.d_model = d_model
        self.base = base
        self.out_channels = out_channels
        self.latent_dim = latent_dim
        self.num_blocks = 2
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.mapping = MLP([latent_dim, d_model, d_model], ["relu", "linear"])
            std = math.sqrt(2.0 / (base * 16))
            self.const = [[[random.gauss(0.0, std) for _ in range(4)] for _ in range(4)]
                          for _ in range(base)]
            self.conv1 = Conv2d(base, base, 3, padding=1)
            self.conv2 = Conv2d(base, base, 3, padding=1)
            self.style1 = Layer(d_model, 2 * base, "linear")
            self.style2 = Layer(d_model, 2 * base, "linear")
            self.to_rgb = Conv2d(base, out_channels, 3, padding=1)
        finally:
            random.setstate(state)
        self.grads_style = None
        self.grads_map = None
        self._cache = None

    def zero_grad(self):
        for c in (self.conv1, self.conv2, self.to_rgb):
            c.zero_grad()
        self.grads_style = None
        self.grads_map = None

    def param_count(self):
        return (self.base * 16
                + _conv_param_count(self.conv1)
                + _conv_param_count(self.conv2)
                + _dense_param_count(self.style1)
                + _dense_param_count(self.style2)
                + _conv_param_count(self.to_rgb)
                + sum(_dense_param_count(l) for l in self.mapping.layers))

    def _style(self, layer, w):
        out, cache = _dense_rows_forward(layer, [w])
        style = out[0]
        c = self.base
        return [style[:c], style[c:]], cache

    def forward(self, z):
        if not isinstance(z, (list, tuple)) or len(z) != self.latent_dim:
            raise ValueError(f"StyleGANGenerator.forward: z 长度必须是 {self.latent_dim}")
        for v in z:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError("StyleGANGenerator.forward: z 必须是数字列表")
        w = self.mapping.forward(list(z))
        (scale1, bias1), cache_s1 = self._style(self.style1, w)
        (scale2, bias2), cache_s2 = self._style(self.style2, w)
        p1 = self.conv1.forward(self.const)
        a1, p1_stats = adain_style(p1, scale1 + bias1)
        r1 = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in a1]
        m1 = [[[1.0 if v > 0.0 else 0.0 for v in row] for row in ch] for ch in a1]
        u1 = _sg_upsample(r1)
        p2 = self.conv2.forward(u1)
        a2, p2_stats = adain_style(p2, scale2 + bias2)
        r2 = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in a2]
        m2 = [[[1.0 if v > 0.0 else 0.0 for v in row] for row in ch] for ch in a2]
        u2 = _sg_upsample(r2)
        rgb = self.to_rgb.forward(u2)
        y = [[[math.tanh(v) for v in row] for row in ch] for ch in rgb]
        self._cache = {
            "w": w, "z": list(z),
            "p1": p1, "a1": a1, "m1": m1, "scale1": scale1, "bias1": bias1,
            "p2": p2, "a2": a2, "m2": m2, "scale2": scale2, "bias2": bias2,
            "u1": u1, "u2": u2, "y": y, "cache_s1": cache_s1, "cache_s2": cache_s2,
            "p1_stats": p1_stats, "p2_stats": p2_stats,
        }
        return y

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("StyleGANGenerator.backward: 先调用 forward")
        cache = self._cache
        y = cache["y"]
        c, h, w = len(y), len(y[0]), len(y[0][0])
        if not isinstance(dout, (list, tuple)) or len(dout) != c \
                or len(dout[0]) != h or len(dout[0][0]) != w:
            raise ValueError("StyleGANGenerator.backward: dout 形状与输出不一致")
        d_rgb = [[[float(dout[k][i][j]) * (1.0 - y[k][i][j] * y[k][i][j])
                   for j in range(w)] for i in range(h)] for k in range(c)]
        d_u2 = self.to_rgb.backward(d_rgb)
        d_r2 = _sg_upsample_backward(d_u2, len(cache["p2"][0]), len(cache["p2"][0][0]))
        d_a2 = [[[d_r2[k][i][j] * cache["m2"][k][i][j] for j in range(len(d_r2[0][0]))]
                 for i in range(len(d_r2[0]))] for k in range(len(d_r2))]
        a2_cache = {"x": cache["p2"], "mean": [s[0] for s in cache["p2_stats"]],
                    "std": [s[1] for s in cache["p2_stats"]],
                    "scale": cache["scale2"], "bias": cache["bias2"]}
        d_p2, d_style2 = _sg_adain_backward(d_a2, a2_cache)
        d_u1 = self.conv2.backward(d_p2)
        d_r1 = _sg_upsample_backward(d_u1, len(cache["p1"][0]), len(cache["p1"][0][0]))
        d_a1 = [[[d_r1[k][i][j] * cache["m1"][k][i][j] for j in range(len(d_r1[0][0]))]
                 for i in range(len(d_r1[0]))] for k in range(len(d_r1))]
        a1_cache = {"x": cache["p1"], "mean": [s[0] for s in cache["p1_stats"]],
                    "std": [s[1] for s in cache["p1_stats"]],
                    "scale": cache["scale1"], "bias": cache["bias1"]}
        d_p1, d_style1 = _sg_adain_backward(d_a1, a1_cache)
        self.conv1.backward(d_p1)

        gs = []
        for layer, cache_s, d_style in ((self.style1, cache["cache_s1"], d_style1),
                                        (self.style2, cache["cache_s2"], d_style2)):
            gw, gb, _ = _dense_rows_backward(layer, cache_s, [d_style])
            gs.append((gw, gb))
        self.grads_style = gs

        d_w = [0.0] * self.d_model
        for layer, cache_s, d_style in ((self.style1, cache["cache_s1"], d_style1),
                                        (self.style2, cache["cache_s2"], d_style2)):
            gw, gb, dx = _dense_rows_backward(layer, cache_s, [d_style])
            for k in range(self.d_model):
                d_w[k] += dx[0][k]
        self.grads_map = _mlp_backward(self.mapping, d_w)
        return None

    def sample(self, z):
        return self.forward(z)

    @staticmethod
    def average_w(generator, zs):
        if not isinstance(zs, (list, tuple)) or not zs:
            raise ValueError("StyleGANGenerator.average_w: zs 不能为空")
        ws = [generator.mapping.forward(list(z)) for z in zs]
        n = len(ws)
        return [sum(w[k] for w in ws) / n for k in range(len(ws[0]))]

    def truncate(self, z, w_avg, psi=0.7):
        if self._cache is None or self._cache.get("z") != list(z):
            self.forward(z)
        w = self.mapping.forward(list(z))
        return truncation_trick(w, w_avg, psi)

    def sgd_step(self, lr):
        for c in (self.conv1, self.conv2, self.to_rgb):
            _p2p_sgd_layer(c, lr)
        if self.grads_style is not None:
            _dense_apply_sgd(self.style1, self.grads_style[0], lr)
            _dense_apply_sgd(self.style2, self.grads_style[1], lr)
        if self.grads_map is not None:
            for layer, grad in zip(self.mapping.layers, self.grads_map):
                _dense_apply_sgd(layer, grad, lr)

"""CycleGAN 训练步：两个生成器（A→B、B→A）与两个判别器，循环一致性 + identity 约束。"""


def _cg_add_grads(dst, src):
    for k in range(len(dst)):
        for i in range(len(dst[k])):
            for j in range(len(dst[k][i])):
                dst[k][i][j] += src[k][i][j]
    return dst


def _cg_cycle_loss(rec, real, weight):
    return _p2p_l1_and_grad(rec, real, weight)


def train_cyclegan_step(g_ab, g_ba, d_a, d_b, real_a, real_b,
                        lambda_cycle=10.0, lambda_identity=5.0, lr_g=1e-3, lr_d=1e-3):
    """一步 CycleGAN：先更新两个判别器，再更新两个生成器。"""
    if not isinstance(g_ab, Pix2PixGenerator) or not isinstance(g_ba, Pix2PixGenerator):
        raise TypeError("train_cyclegan_step: g_ab/g_ba 必须是 Pix2PixGenerator")
    if not isinstance(d_a, PatchDiscriminator) or not isinstance(d_b, PatchDiscriminator):
        raise TypeError("train_cyclegan_step: d_a/d_b 必须是 PatchDiscriminator")
    for name, value in (("lambda_cycle", lambda_cycle), ("lambda_identity", lambda_identity),
                        ("lr_g", lr_g), ("lr_d", lr_d)):
        if isinstance(value, bool) or not isinstance(value, (int, float)) or value < 0:
            raise ValueError(f"train_cyclegan_step: {name} 必须是非负数")
    for name, value in (("lr_g", lr_g), ("lr_d", lr_d)):
        if value <= 0:
            raise ValueError(f"train_cyclegan_step: {name} 必须为正数")
    h, w = _p2p_image(real_a, g_ab.in_channels, "train_cyclegan_step(real_a)")
    _p2p_image(real_b, g_ba.in_channels, "train_cyclegan_step(real_b)")
    h2, w2 = _p2p_image(real_a, g_ba.in_channels, "train_cyclegan_step(real_a→g_ba)")
    if (h2, w2) != (h, w):
        raise ValueError("train_cyclegan_step: 两个域的图像形状必须一致")

    fake_b = g_ab.forward(real_a)
    fake_a = g_ba.forward(real_b)

    # 1) 判别器 D_A / D_B：真图目标 1、假图目标 0
    d_a.zero_grad()
    loss_d_real_a, d = _p2p_bce(d_a.forward(real_a), 1.0)
    d_a.backward(d)
    loss_d_fake_a, d = _p2p_bce(d_a.forward(fake_a), 0.0)
    d_a.backward(d)
    d_a.sgd_step(lr_d)

    d_b.zero_grad()
    loss_d_real_b, d = _p2p_bce(d_b.forward(real_b), 1.0)
    d_b.backward(d)
    loss_d_fake_b, d = _p2p_bce(d_b.forward(fake_b), 0.0)
    d_b.backward(d)
    d_b.sgd_step(lr_d)
    loss_d = 0.5 * (loss_d_real_a + loss_d_fake_a + loss_d_real_b + loss_d_fake_b)

    # 2) 生成器：对抗 + 循环一致性 + identity
    g_ab.zero_grad()
    g_ba.zero_grad()
    fake_b = g_ab.forward(real_a)
    fake_a = g_ba.forward(real_b)

    d_b.zero_grad()
    loss_adv_b, d_score = _p2p_bce(d_b.forward(fake_b), 1.0)
    d_fake_b = d_b.backward(d_score)
    d_a.zero_grad()
    loss_adv_a, d_score = _p2p_bce(d_a.forward(fake_a), 1.0)
    d_fake_a = d_a.backward(d_score)

    rec_a = g_ba.forward(fake_b)
    loss_cyc_a, d_rec_a = _cg_cycle_loss(rec_a, real_a, lambda_cycle)
    d_fake_b = _cg_add_grads(d_fake_b, g_ba.backward(d_rec_a))

    rec_b = g_ab.forward(fake_a)
    loss_cyc_b, d_rec_b = _cg_cycle_loss(rec_b, real_b, lambda_cycle)
    d_fake_a = _cg_add_grads(d_fake_a, g_ab.backward(d_rec_b))

    id_b = g_ab.forward(real_b)
    loss_id_b, d_id_b = _cg_cycle_loss(id_b, real_b, lambda_identity)
    g_ab.backward(d_id_b)
    id_a = g_ba.forward(real_a)
    loss_id_a, d_id_a = _cg_cycle_loss(id_a, real_a, lambda_identity)
    g_ba.backward(d_id_a)

    g_ab.forward(fake_b)
    g_ab.backward(d_fake_b)
    g_ba.forward(fake_a)
    g_ba.backward(d_fake_a)
    g_ab.sgd_step(lr_g)
    g_ba.sgd_step(lr_g)

    d_a.zero_grad()
    d_b.zero_grad()
    loss_g = loss_adv_a + loss_adv_b + loss_cyc_a + loss_cyc_b + loss_id_a + loss_id_b
    return {"d_loss": loss_d, "g_loss": loss_g,
            "adv_loss": loss_adv_a + loss_adv_b,
            "cycle_loss": loss_cyc_a + loss_cyc_b,
            "identity_loss": loss_id_a + loss_id_b}


def fit_cyclegan(g_ab, g_ba, d_a, d_b, pairs, steps=30,
                 lambda_cycle=10.0, lambda_identity=5.0, lr_g=1e-3, lr_d=1e-3, seed=None):
    """在固定的 (A, B) 图像对集合上循环训练，返回每步损失。"""
    if not isinstance(pairs, (list, tuple)) or not pairs:
        raise ValueError("fit_cyclegan: pairs 不能为空")
    rng = random.Random(seed) if seed is not None else random
    history = []
    for _ in range(steps):
        real_a, real_b = pairs[rng.randrange(len(pairs))]
        history.append(train_cyclegan_step(
            g_ab, g_ba, d_a, d_b, real_a, real_b,
            lambda_cycle=lambda_cycle, lambda_identity=lambda_identity,
            lr_g=lr_g, lr_d=lr_d))
    return history

#  研究前沿：Score-based 生成（NCSN / VP·VE SDE / 概率流 ODE）与 EBM
# =============================================================================
#  这一节的共同点是「只依赖一个可调用的 score / energy 函数」，因此不需要
#  额外训练一个网络就能验证数学：探针里用高斯数据的**闭式 score** 做端到端
#  采样，与理论方差对照。真实训练时把 score_fn 换成 MLP(x, sigma) -> list 即可。


def _w8b_vec(x, who):
    """把 x 规范成「数字列表」，拒 bool/NaN/inf。"""
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError("%s: 需要非空的一维列表，收到 %r" % (who, type(x).__name__))
    out = []
    for i, v in enumerate(x):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError("%s: 第 %d 个元素不是数字（%r）" % (who, i, v))
        fv = float(v)
        if fv != fv or fv in (float("inf"), float("-inf")):
            raise ValueError("%s: 第 %d 个元素不是有限数（%r）" % (who, i, v))
        out.append(fv)
    return out


def _w8b_scalar(v, who, minimum=None):
    if isinstance(v, bool) or not isinstance(v, (int, float)):
        raise ValueError("%s: 需要数字，收到 %r" % (who, type(v).__name__))
    fv = float(v)
    if fv != fv or fv in (float("inf"), float("-inf")):
        raise ValueError("%s: 需要有限数，收到 %r" % (who, v))
    if minimum is not None and fv < minimum:
        raise ValueError("%s: 需要 >= %r，收到 %r" % (who, minimum, v))
    return fv


def _w8b_sigmas(sigmas, who="sigmas"):
    """噪声等级序列：正数、严格递减（NCSN 的退火前提）。"""
    if not isinstance(sigmas, (list, tuple)) or not sigmas:
        raise ValueError("%s: 需要非空序列" % who)
    out = [_w8b_scalar(s, "%s[%d]" % (who, i), minimum=0.0) for i, s in enumerate(sigmas)]
    for i, s in enumerate(out):
        if s <= 0.0:
            raise ValueError("%s[%d] 必须 > 0（收到 %r）" % (who, i, sigmas[i]))
    for i in range(1, len(out)):
        if not out[i] < out[i - 1]:
            raise ValueError("%s 必须严格递减（第 %d 项 %r 不小于前一项 %r）"
                             % (who, i, out[i], out[i - 1]))
    return out


def _w8b_call_score(score_fn, x, sigma):
    """调用 score 函数并校验形状与有限性。"""
    if not callable(score_fn):
        raise TypeError("score_fn 必须可调用，收到 %r" % type(score_fn).__name__)
    out = score_fn(list(x), sigma)
    vec = _w8b_vec(out, "score_fn 的返回值")
    if len(vec) != len(x):
        raise ValueError("score_fn 返回长度 %d 与输入长度 %d 不一致"
                         % (len(vec), len(x)))
    return vec


# ---------------------------------------------------------------- 扩散系数 --
def vp_beta(t, beta_min=0.1, beta_max=20.0):
    """VP-SDE 的线性 beta 调度：beta(t) = beta_min + t (beta_max - beta_min)。"""
    tt = _w8b_scalar(t, "t", minimum=0.0)
    if tt > 1.0:
        raise ValueError("t: 需要 0 <= t <= 1，收到 %r" % t)
    bmin = _w8b_scalar(beta_min, "beta_min", minimum=0.0)
    bmax = _w8b_scalar(beta_max, "beta_max", minimum=0.0)
    if not bmax > bmin:
        raise ValueError("beta_max 必须大于 beta_min（收到 %r / %r）" % (beta_max, beta_min))
    return bmin + tt * (bmax - bmin)


def vp_diffusion(t, beta_min=0.1, beta_max=20.0):
    """VP-SDE 的扩散系数 g(t) = sqrt(beta(t))。"""
    return math.sqrt(vp_beta(t, beta_min, beta_max))


def vp_drift(x, t, beta_min=0.1, beta_max=20.0):
    """VP-SDE 的漂移 f(x, t) = -0.5 beta(t) x。"""
    vec = _w8b_vec(x, "vp_drift.x")
    half_beta = 0.5 * vp_beta(t, beta_min, beta_max)
    return [-half_beta * v for v in vec]


def vp_marginal_std(t, beta_min=0.1, beta_max=20.0):
    """VP-SDE 的边缘标准差：sqrt(1 - exp(-∫beta))，t=0 时为 0。"""
    tt = _w8b_scalar(t, "t", minimum=0.0)
    if tt > 1.0:
        raise ValueError("t: 需要 0 <= t <= 1，收到 %r" % t)
    bmin = _w8b_scalar(beta_min, "beta_min", minimum=0.0)
    bmax = _w8b_scalar(beta_max, "beta_max", minimum=0.0)
    # ∫_0^t beta(s) ds = bmin t + 0.5 (bmax - bmin) t^2
    integral = bmin * tt + 0.5 * (bmax - bmin) * tt * tt
    return math.sqrt(1.0 - math.exp(-integral))


def ve_sigma(t, sigma_min=0.01, sigma_max=50.0):
    """VE-SDE 的噪声尺度 sigma(t) = sigma_min (sigma_max/sigma_min)^t（几何插值）。"""
    tt = _w8b_scalar(t, "t", minimum=0.0)
    if tt > 1.0:
        raise ValueError("t: 需要 0 <= t <= 1，收到 %r" % t)
    smin = _w8b_scalar(sigma_min, "sigma_min", minimum=0.0)
    smax = _w8b_scalar(sigma_max, "sigma_max", minimum=0.0)
    if smin <= 0.0 or not smax > smin:
        raise ValueError("需要 0 < sigma_min < sigma_max（收到 %r / %r）" % (sigma_min, sigma_max))
    return smin * (smax / smin) ** tt


def ve_diffusion(t, sigma_min=0.01, sigma_max=50.0):
    """VE-SDE 的扩散系数 g(t) = sqrt(2 sigma(t) sigma'(t))。"""
    tt = _w8b_scalar(t, "t", minimum=0.0)
    sigma = ve_sigma(tt, sigma_min, sigma_max)
    # sigma'(t) = sigma(t) * ln(smax/smin)
    log_ratio = math.log(float(sigma_max) / float(sigma_min))
    return math.sqrt(2.0 * sigma * sigma * log_ratio)


# --------------------------------------------------------- 反向 SDE / ODE --
def reverse_sde_step(x, t, score, dt, noise=None, kind="ve",
                     beta_min=0.1, beta_max=20.0, sigma_min=0.01, sigma_max=50.0):
    """反向 SDE 单步：dx = [f - g² score] dt + g sqrt(|dt|) z（dt 应为负）。

    VP 用 `f(x,t) = -0.5 beta(t) x`；VE 的 f 是 0。返回新列表，不改入参。
    """
    vec = _w8b_vec(x, "reverse_sde_step.x")
    d = _w8b_scalar(dt, "dt")
    if d == 0.0:
        raise ValueError("dt 不能为 0")
    if d > 0.0:
        raise ValueError("反向扩散的 dt 应为负（收到 %r）" % dt)
    sc = _w8b_call_score(score, vec, t)
    kind = str(kind).lower()
    if kind == "vp":
        f = vp_drift(vec, t, beta_min, beta_max)
        g = vp_diffusion(t, beta_min, beta_max)
    elif kind == "ve":
        f = [0.0] * len(vec)
        g = ve_diffusion(t, sigma_min, sigma_max)
    else:
        raise ValueError("kind: 只支持 'vp' 或 've'，收到 %r" % kind)
    if noise is None:
        noise_vec = [0.0] * len(vec)
    else:
        noise_vec = _w8b_vec(noise, "reverse_sde_step.noise")
        if len(noise_vec) != len(vec):
            raise ValueError("noise 长度 %d 与 x 长度 %d 不一致"
                             % (len(noise_vec), len(vec)))
    step = math.sqrt(abs(d))
    out = []
    for i, xi in enumerate(vec):
        drift = f[i] - (g * g) * sc[i]
        out.append(xi + drift * d + g * step * noise_vec[i])
    return out


def probability_flow_step(x, t, score, dt, kind="ve",
                          beta_min=0.1, beta_max=20.0,
                          sigma_min=0.01, sigma_max=50.0):
    """概率流 ODE 单步（无噪声）：dx = [f - 0.5 g² score] dt。"""
    vec = _w8b_vec(x, "probability_flow_step.x")
    d = _w8b_scalar(dt, "dt")
    sc = _w8b_call_score(score, vec, t)
    kind = str(kind).lower()
    if kind == "vp":
        f = vp_drift(vec, t, beta_min, beta_max)
        g = vp_diffusion(t, beta_min, beta_max)
    elif kind == "ve":
        f = [0.0] * len(vec)
        g = ve_diffusion(t, sigma_min, sigma_max)
    else:
        raise ValueError("kind: 只支持 'vp' 或 've'，收到 %r" % kind)
    out = []
    for i, xi in enumerate(vec):
        out.append(xi + (f[i] - 0.5 * (g * g) * sc[i]) * d)
    return out


# ----------------------------------------------------- NCSN（去噪分数匹配） --
def ncsn_loss(score_fn, xs, sigmas=(1.0, 0.5, 0.2), seed=None):
    """去噪分数匹配（NCSN）：每个噪声等级上回归 `-eps/sigma`。

    `sigma^2 * || s(x + sigma eps, sigma) + eps/sigma ||^2 / 2`，对所有样本与
    所有 sigma 取平均（各 sigma 的系数被 sigma^2 抵消，与论文的
    `lambda(sigma) = sigma^2` 一致）。返回 `(loss, info)`，`info` 给出每个
    sigma 上的分项损失，便于观察哪个噪声等级没学好。
    """
    if not isinstance(xs, (list, tuple)) or not xs:
        raise ValueError("xs: 需要非空样本列表")
    if not callable(score_fn):
        raise TypeError("score_fn 必须可调用，收到 %r" % type(score_fn).__name__)
    levels = _w8b_sigmas(sigmas)
    dim = None
    rows = []
    for i, x in enumerate(xs):
        vec = _w8b_vec(x, "xs[%d]" % i)
        if dim is None:
            dim = len(vec)
        elif len(vec) != dim:
            raise ValueError("xs 各样本维度不一致（第 %d 个是 %d，应为 %d）"
                             % (i, len(vec), dim))
        rows.append(vec)
    rng = random.Random(seed)
    per_sigma = [0.0] * len(levels)
    for li, sigma in enumerate(levels):
        total = 0.0
        for row in rows:
            eps = [rng.gauss(0.0, 1.0) for _ in range(dim)]
            noisy = [row[i] + sigma * eps[i] for i in range(dim)]
            sc = _w8b_call_score(score_fn, noisy, sigma)
            acc = 0.0
            for i in range(dim):
                target = -eps[i] / sigma
                diff = sc[i] - target
                acc += diff * diff
            total += 0.5 * (sigma * sigma) * acc
        per_sigma[li] = total / len(rows)
    loss = sum(per_sigma) / len(per_sigma)
    return loss, {"sigmas": list(levels), "per_sigma": per_sigma,
                  "n_samples": len(rows), "dim": dim}


def annealed_langevin_sample(score_fn, x0, sigmas=(1.0, 0.5, 0.2, 0.1),
                             steps_per_sigma=10, epsilon=0.01, seed=None):
    """退火 Langevin 采样（NCSN 的采样器）。

    在 sigma_i 上跑 `steps_per_sigma` 步：
    `x += step * score(x, sigma_i) + sqrt(2 step) z`，其中
    `step = epsilon * (sigma_i / sigma_last)^2`。返回最后一次迭代的样本。
    """
    vec = _w8b_vec(x0, "annealed_langevin_sample.x0")
    levels = _w8b_sigmas(sigmas)
    steps = _w8b_scalar(steps_per_sigma, "steps_per_sigma", minimum=1.0)
    if int(steps) != steps:
        raise ValueError("steps_per_sigma 需要整数，收到 %r" % steps_per_sigma)
    eps = _w8b_scalar(epsilon, "epsilon", minimum=0.0)
    if eps <= 0.0:
        raise ValueError("epsilon 必须 > 0")
    rng = random.Random(seed)
    x = list(vec)
    scale = eps / (levels[-1] * levels[-1])
    for sigma in levels:
        step = scale * sigma * sigma
        for _ in range(int(steps)):
            sc = _w8b_call_score(score_fn, x, sigma)
            nxt = []
            for i in range(len(x)):
                z = rng.gauss(0.0, 1.0)
                nxt.append(x[i] + step * sc[i] + math.sqrt(2.0 * step) * z)
            x = nxt
    return x


# ---------------------------------------------------------------- EBM ------
def ebm_langevin(grad_energy, x0, steps=20, step_size=0.01, noise=0.01, seed=None):
    """能量模型的 Langevin 采样：`x -= step * gradE(x) + noise * z`。

    注意这里的 `noise` 是**每次迭代的噪声幅度**（不是温度），与
    `annealed_langevin_sample` 里的 `sqrt(2 step)` 口径不同，二者不混用。
    """
    vec = _w8b_vec(x0, "ebm_langevin.x0")
    if not callable(grad_energy):
        raise TypeError("grad_energy 必须可调用，收到 %r" % type(grad_energy).__name__)
    n = _w8b_scalar(steps, "steps", minimum=1.0)
    if int(n) != n:
        raise ValueError("steps 需要整数，收到 %r" % steps)
    step = _w8b_scalar(step_size, "step_size", minimum=0.0)
    if step <= 0.0:
        raise ValueError("step_size 必须 > 0")
    sd = _w8b_scalar(noise, "noise", minimum=0.0)
    rng = random.Random(seed)
    x = list(vec)
    for _ in range(int(n)):
        g = _w8b_vec(grad_energy(list(x)), "grad_energy 的返回值")
        if len(g) != len(x):
            raise ValueError("grad_energy 返回长度 %d 与输入长度 %d 不一致"
                             % (len(g), len(x)))
        x = [x[i] - step * g[i] + sd * rng.gauss(0.0, 1.0) for i in range(len(x))]
    return x


def ebm_contrastive_divergence(energy_fn, grad_energy, x_data, steps=20,
                               step_size=0.01, noise=0.01, seed=None):
    """对比散度（CD-k）：`loss = mean E(x_data) - mean E(x_neg)`。

    返回 `(loss, info)`，`info` 含负样本与两侧能量均值。这里是**标量损失**，
    不含参数梯度——那是具体 EBM 实现（能量函数自己的 backward）的事，本库
    不为它造一个空壳。`loss > 0` 表示数据能量高于负样本，是训练早期的常态。
    """
    if not callable(energy_fn) or not callable(grad_energy):
        raise TypeError("energy_fn 与 grad_energy 都必须可调用")
    if not isinstance(x_data, (list, tuple)) or not x_data:
        raise ValueError("x_data: 需要非空样本列表")
    pos = [_w8b_vec(x, "x_data[%d]" % i) for i, x in enumerate(x_data)]
    dim = len(pos[0])
    for i, row in enumerate(pos):
        if len(row) != dim:
            raise ValueError("x_data 各样本维度不一致（第 %d 个是 %d，应为 %d）"
                             % (i, len(row), dim))
    neg = []
    for i, row in enumerate(pos):
        neg.append(ebm_langevin(grad_energy, row, steps=steps, step_size=step_size,
                                noise=noise, seed=None if seed is None else seed + i))
    e_pos = []
    for row in pos:
        val = energy_fn(list(row))
        e_pos.append(_w8b_scalar(val, "energy_fn 的返回值"))
    e_neg = []
    for row in neg:
        val = energy_fn(list(row))
        e_neg.append(_w8b_scalar(val, "energy_fn 的返回值"))
    loss = sum(e_pos) / len(e_pos) - sum(e_neg) / len(e_neg)
    return loss, {"mean_energy_data": sum(e_pos) / len(e_pos),
                  "mean_energy_negative": sum(e_neg) / len(e_neg),
                  "negative_samples": neg, "steps": int(steps)}


# --------------------------------------------------------- 一致性模型 ------
def _w8b_call_net(fn, x, t, who="net"):
    if not callable(fn):
        raise TypeError("%s 必须可调用，收到 %r" % (who, type(fn).__name__))
    out = fn(list(x), t)
    return _w8b_vec(out, "%s 的返回值" % who)


def consistency_model_loss(student, teacher, xs, t_high=0.8, t_low=0.2,
                     sigma_data=0.5, seed=None):
    """一致性训练损失（简化版，无需 EDM 的完整前后向系数）。

    `x_t = x + t * sigma_data * eps`，目标为 `teacher(x_{t_high}, t_high)`，
    学生从 `x_{t_low}` 出发要一步回到同一个点：

        `loss = mean || student(x_{t_low}, t_low) - teacher(x_{t_high}, t_high) ||^2`

    `teacher` 通常是学生的 EMA 副本（用 `AI.EMA` 或自己维护）。返回
    `(loss, info)`，`t_high > t_low` 必须成立。真实一致性模型还有
    `c_skip/c_out` 与 `lambda(t)` 加权，这里刻意保留最小形式并写明差异。
    """
    hi = _w8b_scalar(t_high, "t_high", minimum=0.0)
    lo = _w8b_scalar(t_low, "t_low", minimum=0.0)
    if not hi > lo:
        raise ValueError("需要 t_high > t_low（收到 %r / %r）" % (t_high, t_low))
    sd = _w8b_scalar(sigma_data, "sigma_data", minimum=0.0)
    if sd <= 0.0:
        raise ValueError("sigma_data 必须 > 0")
    if not isinstance(xs, (list, tuple)) or not xs:
        raise ValueError("xs: 需要非空样本列表")
    rows = [_w8b_vec(x, "xs[%d]" % i) for i, x in enumerate(xs)]
    dim = len(rows[0])
    for i, row in enumerate(rows):
        if len(row) != dim:
            raise ValueError("xs 各样本维度不一致（第 %d 个是 %d）" % (i, len(row)))
    rng = random.Random(seed)
    total = 0.0
    for row in rows:
        eps = [rng.gauss(0.0, 1.0) for _ in range(dim)]
        x_hi = [row[i] + hi * sd * eps[i] for i in range(dim)]
        x_lo = [row[i] + lo * sd * eps[i] for i in range(dim)]
        target = _w8b_call_net(teacher, x_hi, hi, "teacher")
        pred = _w8b_call_net(student, x_lo, lo, "student")
        acc = 0.0
        for i in range(dim):
            d = pred[i] - target[i]
            acc += d * d
        total += acc
    return total / len(rows), {"t_high": hi, "t_low": lo, "n_samples": len(rows)}


def consistency_sample(student, x_noisy, t=0.8):
    """一致性模型的一步采样：`x0 = student(x_T, T)`（这就是它的卖点）。"""
    return _w8b_call_net(student, x_noisy, t, "student")


# ------------------------------------------------- 多尺度 Glow（组合） ------
def _w8b_flow_det(blocks):
    total = 0.0
    for b in blocks:
        total += _w8b_scalar(b.logdet(), "block.logdet()")
    return total


class ComposedGlow:
    """单尺度 Glow：`ActNorm -> InvertibleLinear -> RealNVP(耦合)` 堆叠 `blocks` 次。

    `forward(x)` 返回 `(z, logdet)`，`inverse(z)` 返回 `x`，
    `log_prob(x)` 用高斯先验算真密度。`logdet` 是**逐块相加**——这正是
    「组合多个可逆块」最容易写错的地方（漏掉某一项、或把 `logdet` 当成
    与输入相关）。
    """

    def __init__(self, dim, hidden_dim=16, num_layers=2, blocks=2, seed=0):
        d = int(_w8b_scalar(dim, "ComposedGlow.dim", minimum=1.0))
        if d < 2:
            raise ValueError("ComposedGlow.dim 需要 >= 2，收到 %r" % dim)
        nb = int(_w8b_scalar(blocks, "ComposedGlow.blocks", minimum=1.0))
        self.dim = d
        self.blocks = []
        for i in range(nb):
            self.blocks.append(ActNorm(d))
            self.blocks.append(InvertibleLinear(d, seed=int(seed) + 1000 * i + 1))
            self.blocks.append(RealNVP(d, hidden_dim=hidden_dim,
                                       num_layers=num_layers, seed=int(seed) + 7 * i))

    def forward(self, x):
        vec = _w8b_vec(x, "ComposedGlow.forward.x")
        if len(vec) != self.dim:
            raise ValueError("ComposedGlow.forward: 输入长度 %d 与 dim=%d 不一致"
                             % (len(vec), self.dim))
        cur = list(vec)
        total = 0.0
        for b in self.blocks:
            out = b.forward(cur)
            if isinstance(out, tuple):
                cur, ld = out
                total += float(ld)
            else:
                cur = out
                total += float(b.logdet())
        return cur, total

    def inverse(self, z):
        vec = _w8b_vec(z, "ComposedGlow.inverse.z")
        if len(vec) != self.dim:
            raise ValueError("ComposedGlow.inverse: 输入长度 %d 与 dim=%d 不一致"
                             % (len(vec), self.dim))
        cur = list(vec)
        for b in reversed(self.blocks):
            cur = b.inverse(cur)
        return cur

    def log_prob(self, x):
        z, logdet = self.forward(x)
        acc = 0.0
        for v in z:
            acc += v * v
        # 标准高斯先验：-0.5|z|^2 - 0.5 d log(2pi) + logdet
        return -0.5 * acc - 0.5 * self.dim * math.log(2.0 * math.pi) + logdet

    def nll(self, x):
        return -self.log_prob(x)

    def sample(self, seed=None):
        rng = random.Random(seed)
        return self.inverse([rng.gauss(0.0, 1.0) for _ in range(self.dim)])

    def param_count(self):
        return sum(b.param_count() for b in self.blocks)


class MultiScaleGlow:
    """多尺度 Glow：每层「`ComposedGlow` → 通道对半拆 → 一半进潜变量」。

    这是把多尺度结构从 Glow 论文里抽成可测形式的最小版本：`forward` 返回
    `(z_list, logdet)`，`inverse` 用 `z_list` 重建输入，`log_prob` 是各尺度
    密度之和。拆分的规则固定为「取前 `dim//2` 个元素进潜变量、其余继续流」，
    不引入学习到的 split（那是 StyleGAN/Glow 的 `split` 层，需额外参数）。
    """

    def __init__(self, dim, scales=2, hidden_dim=16, num_layers=2, blocks=1, seed=0):
        d = int(_w8b_scalar(dim, "MultiScaleGlow.dim", minimum=2.0))
        sc = int(_w8b_scalar(scales, "MultiScaleGlow.scales", minimum=1.0))
        if sc > 4:
            raise ValueError("MultiScaleGlow.scales: 最多 4 层（每层减半），收到 %r" % scales)
        cur = d
        self.scales = []
        dims = []
        for i in range(sc):
            if cur < 2:
                raise ValueError("MultiScaleGlow: 第 %d 层的维度降到 %d，无法再拆半"
                                 % (i + 1, cur))
            self.scales.append(ComposedGlow(cur, hidden_dim=hidden_dim,
                                            num_layers=num_layers, blocks=blocks,
                                            seed=int(seed) + 31 * i))
            dims.append(cur)
            cur = cur // 2
        self.dim = d
        self.dims = dims
        self.rest = cur
        self.hidden = self.scales[-1]

    def forward(self, x):
        vec = _w8b_vec(x, "MultiScaleGlow.forward.x")
        if len(vec) != self.dim:
            raise ValueError("MultiScaleGlow.forward: 输入长度 %d 与 dim=%d 不一致"
                             % (len(vec), self.dim))
        cur = list(vec)
        zs = []
        total = 0.0
        for i, flow in enumerate(self.scales):
            cur, ld = flow.forward(cur)
            total += ld
            if i < len(self.scales) - 1:
                half = len(cur) // 2
                zs.append(cur[:half])
                cur = cur[half:]
        zs.append(cur)
        return zs, total

    def inverse(self, zs):
        if not isinstance(zs, (list, tuple)) or not zs:
            raise ValueError("MultiScaleGlow.inverse: 需要非空潜变量列表")
        if len(zs) != len(self.scales):
            raise ValueError("MultiScaleGlow.inverse: 需要 %d 个尺度，收到 %d"
                             % (len(self.scales), len(zs)))
        cur = _w8b_vec(zs[-1], "MultiScaleGlow.inverse 的最后一层")
        for i in range(len(self.scales) - 1, -1, -1):
            flow = self.scales[i]
            if len(cur) != flow.dim:
                raise ValueError("MultiScaleGlow.inverse: 第 %d 层需要 %d 维，收到 %d"
                                 % (i + 1, flow.dim, len(cur)))
            cur = flow.inverse(cur)
            if i > 0:
                part = _w8b_vec(zs[i - 1], "MultiScaleGlow.inverse 的第 %d 层" % i)
                if len(part) + len(cur) != self.dims[i - 1]:
                    raise ValueError("MultiScaleGlow.inverse: 第 %d 层潜变量 %d 维 + "
                                     "重建的 %d 维 != 上一层 %d 维"
                                     % (i, len(part), len(cur), self.dims[i - 1]))
                cur = part + cur
        return cur

    def log_prob(self, x):
        zs, logdet = self.forward(x)
        acc = 0.0
        total_dim = 0
        for z in zs:
            for v in z:
                acc += v * v
            total_dim += len(z)
        return -0.5 * acc - 0.5 * total_dim * math.log(2.0 * math.pi) + logdet

    def nll(self, x):
        return -self.log_prob(x)

    def sample(self, seed=None):
        rng = random.Random(seed)
        zs = []
        for flow in self.scales:
            if flow is not self.scales[-1]:
                zs.append([rng.gauss(0.0, 1.0) for _ in range(flow.dim // 2)])
            else:
                zs.append([rng.gauss(0.0, 1.0) for _ in range(flow.dim)])
        return self.inverse(zs)

    def param_count(self):
        return sum(flow.param_count() for flow in self.scales)


# --------------------------------------------------- PixelCNN / WaveNet ----
def pixelcnn_mask(kernel_size=3, kind="A"):
    """PixelCNN 的掩码卷积核掩码（`kind='A'` 不遮中心，`'B'` 遮中心）。

    返回 `kernel_size x kernel_size` 的 0/1 列表。约定：行索引 < 中心行时
    整行可见；等于中心行时只看列 < 中心列（`'A'` 还包含中心本身）。
    `'A'` 用于输入层（不能用当前像素预测自己），`'B'` 用于后续层。
    """
    k = int(_w8b_scalar(kernel_size, "kernel_size", minimum=1.0))
    if k % 2 == 0:
        raise ValueError("kernel_size 必须是奇数（收到 %r）" % kernel_size)
    kind = str(kind).upper()
    if kind not in ("A", "B"):
        raise ValueError("kind: 只支持 'A' 或 'B'，收到 %r" % kind)
    c = k // 2
    mask = []
    for i in range(k):
        row = []
        for j in range(k):
            if i < c:
                row.append(1)
            elif i == c:
                row.append(1 if (j < c or (kind == "A" and j == c)) else 0)
            else:
                row.append(0)
        mask.append(row)
    return mask


def masked_conv2d(x, kernel, mask):
    """单通道、stride=1、same padding 的掩码卷积（用于验证因果性）。

    `x` 是 `H x W` 的二维列表，`kernel` 与 `mask` 都是 `k x k`。输出同尺寸；
    越界位置按 0 处理。它不是训练用的层（没有参数梯度），只用来检查「输出
    (i,j) 不依赖 (i,j) 之后的位置」这条因果性。
    """
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError("masked_conv2d.x: 需要非空二维列表")
    h = len(x)
    w = len(x[0]) if isinstance(x[0], (list, tuple)) else 0
    if w == 0:
        raise ValueError("masked_conv2d.x: 每行必须是非空列表")
    grid = []
    for i, row in enumerate(x):
        if not isinstance(row, (list, tuple)) or len(row) != w:
            raise ValueError("masked_conv2d.x: 第 %d 行长度与首行 %d 不一致" % (i, w))
        grid.append([_w8b_scalar(v, "masked_conv2d.x[%d][%d]" % (i, j)) for j, v in enumerate(row)])
    if not isinstance(kernel, (list, tuple)) or not kernel:
        raise ValueError("masked_conv2d.kernel: 需要非空二维列表")
    k = len(kernel)
    for i, row in enumerate(kernel):
        if not isinstance(row, (list, tuple)) or len(row) != k:
            raise ValueError("masked_conv2d.kernel: 必须是 %d x %d 方阵" % (k, k))
    if not isinstance(mask, (list, tuple)) or len(mask) != k:
        raise ValueError("masked_conv2d.mask: 必须是 %d x %d" % (k, k))
    for i, row in enumerate(mask):
        if not isinstance(row, (list, tuple)) or len(row) != k:
            raise ValueError("masked_conv2d.mask: 必须与 kernel 同形")
    c = k // 2
    out = []
    for i in range(h):
        row_out = []
        for j in range(w):
            acc = 0.0
            for ki in range(k):
                for kj in range(k):
                    if not mask[ki][kj]:
                        continue
                    ii = i + ki - c
                    jj = j + kj - c
                    if 0 <= ii < h and 0 <= jj < w:
                        acc += float(kernel[ki][kj]) * grid[ii][jj]
            row_out.append(acc)
        out.append(row_out)
    return out


def wavenet_dilations(levels=4, kernel_size=2):
    """WaveNet 的膨胀序列 `1,2,4,...` 与感受到的接受野宽度。

    返回 `(dilations, receptive_field)`；`receptive_field = 1 + (k-1)*sum(d)`。
    """
    n = int(_w8b_scalar(levels, "levels", minimum=1.0))
    k = int(_w8b_scalar(kernel_size, "kernel_size", minimum=2.0))
    d = [2 ** i for i in range(n)]
    rf = 1 + (k - 1) * sum(d)
    return d, rf


# ------------------------------------------------------ 潜空间扩散（组合） --
def latent_diffusion_shapes(image_shape, downsample=4):
    """潜空间扩散的尺寸换算：`(C,H,W) -> (C, H//ds, W//ds)`。"""
    if not isinstance(image_shape, (list, tuple)) or len(image_shape) != 3:
        raise ValueError("image_shape: 需要 (C,H,W)，收到 %r" % (image_shape,))
    c = int(_w8b_scalar(image_shape[0], "image_shape[0]", minimum=1.0))
    h = int(_w8b_scalar(image_shape[1], "image_shape[1]", minimum=1.0))
    w = int(_w8b_scalar(image_shape[2], "image_shape[2]", minimum=1.0))
    ds = int(_w8b_scalar(downsample, "downsample", minimum=1.0))
    ho = h // ds
    wo = w // ds
    if ho < 1 or wo < 1:
        raise ValueError("downsample=%d 时潜空间尺寸为 %dx%d，至少要是 1x1" % (ds, ho, wo))
    return (c, ho, wo)


def latent_diffusion_pipeline(encode, decode, diffusion, image):
    """潜空间扩散的组装：`encode -> diffusion -> decode`。

    `encode(image)`/`decode(latent)`/`diffusion` 都要求可调用（`diffusion` 接收
    潜变量并返回同形状的新潜变量，比如 `DDPM.sample` 的包装）。返回
    `(reconstruction, info)`，`info` 给出潜空间形状与压缩比。
    """
    if not callable(encode) or not callable(decode) or not callable(diffusion):
        raise TypeError("encode / decode / diffusion 都必须可调用")
    if not isinstance(image, (list, tuple)) or not image:
        raise ValueError("image: 需要非空样本列表")
    latent = encode(list(image))
    if isinstance(latent, tuple):
        latent = latent[0]
    latent = _w8b_vec(latent, "encode 的返回值")
    new_latent = diffusion(list(latent))
    if isinstance(new_latent, tuple):
        new_latent = new_latent[0]
    new_latent = _w8b_vec(new_latent, "diffusion 的返回值")
    if len(new_latent) != len(latent):
        raise ValueError("diffusion 改变了潜变量维度（%d -> %d）"
                         % (len(latent), len(new_latent)))
    rec = decode(list(new_latent))
    if isinstance(rec, tuple):
        rec = rec[0]
    rec = _w8b_vec(rec, "decode 的返回值")
    if len(rec) != len(image):
        raise ValueError("decode 输出的维度 %d 与输入图像维度 %d 不一致"
                         % (len(rec), len(image)))
    n_img = len(image)
    n_lat = len(latent)
    return rec, {"latent_dim": n_lat, "image_dim": n_img,
                 "compression": (float(n_img) / n_lat) if n_lat else float("inf")}

class PromptTuning:
    """软提示（Prompt Tuning）：把 ``num_tokens`` 个可学习向量拼在序列前面

    ``forward(seq)`` 返回 ``prompt + seq``（形状 ``num_tokens + T``），反向把
    前缀部分的梯度累加进 ``g_prompt``、其余原样回传给序列。
    """

    def __init__(self, num_tokens: int, d_model: int, seed: int = 0,
                 init=None):
        _ck_int(num_tokens, 'PromptTuning(num_tokens)', 1)
        _ck_int(d_model, 'PromptTuning(d_model)', 1)
        self.num_tokens = num_tokens
        self.d_model = d_model
        if init is None:
            rng = random.Random(seed)
            scale = 1.0 / math.sqrt(d_model)
            self.prompt = [[rng.gauss(0.0, scale) for _ in range(d_model)]
                           for _ in range(num_tokens)]
        else:
            if not isinstance(init, list) or len(init) != num_tokens:
                raise ValueError('PromptTuning(init) 要有 %d 行' % num_tokens)
            for row in init:
                if not isinstance(row, list) or len(row) != d_model:
                    raise ValueError('PromptTuning(init) 每行要有 %d 个分量'
                                     % d_model)
                for v in row:
                    if not _is_num(v):
                        raise ValueError('PromptTuning(init) 必须是有限数字')
            self.prompt = [list(row) for row in init]
        self.g_prompt = [[0.0] * d_model for _ in range(num_tokens)]
        self.m_prompt = [[0.0] * d_model for _ in range(num_tokens)]
        self.v_prompt = [[0.0] * d_model for _ in range(num_tokens)]
        self._t = 0
        self._cache = None

    def forward(self, seq):
        if not isinstance(seq, list):
            raise ValueError('PromptTuning.forward: seq 必须是列表')
        for row in seq:
            if not isinstance(row, list) or len(row) != self.d_model:
                raise ValueError('PromptTuning.forward: seq 每行要有 %d 个分量'
                                 % self.d_model)
        self._cache = len(seq)
        return [list(r) for r in self.prompt] + [list(r) for r in seq]

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError('PromptTuning.backward: 需要先 forward')
        n = self.num_tokens
        if not isinstance(dout, list) or len(dout) != n + self._cache:
            raise ValueError('PromptTuning.backward: dout 要有 %d 行'
                             % (n + self._cache))
        for t in range(n):
            for j in range(self.d_model):
                self.g_prompt[t][j] += dout[t][j]
        return [list(dout[n + i]) for i in range(self._cache)]

    def zero_grad(self):
        self.g_prompt = [[0.0] * self.d_model for _ in range(self.num_tokens)]

    def param_count(self) -> int:
        return self.num_tokens * self.d_model

    def sgd_step(self, lr: float):
        lr = _la_check_lr(lr, 'PromptTuning.sgd_step')
        _la_apply_sgd(self.prompt, self.g_prompt, lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        lr = _la_check_lr(lr, 'PromptTuning.adam_step')
        _check_adam_betas(beta1, beta2, 'PromptTuning.adam_step')
        self._t += 1
        c1 = 1.0 - beta1 ** self._t
        c2 = 1.0 - beta2 ** self._t
        _la_apply_adam(self.prompt, self.g_prompt, self.m_prompt, self.v_prompt,
                       lr, c1, c2, beta1, beta2, eps)

    def train(self):
        return self

    def eval(self):
        return self


class P_Tuning:
    """P-Tuning（v2 风格）：软提示由 ``tanh(anchor·W1 + b1)·W2 + b2`` 生成

    只有 ``anchor``、``W1/b1``、``W2/b2`` 可学习；前向把生成的 prompt 拼在
    序列前面，反向沿 MLP 链把梯度回传到 anchor 与两层权重。
    """

    def __init__(self, num_tokens: int, d_model: int,
                 hidden: Optional[int] = None, seed: int = 0):
        _ck_int(num_tokens, 'P_Tuning(num_tokens)', 1)
        _ck_int(d_model, 'P_Tuning(d_model)', 1)
        h = d_model if hidden is None else hidden
        _ck_int(h, 'P_Tuning(hidden)', 1)
        self.num_tokens = num_tokens
        self.d_model = d_model
        self.hidden = h
        rng = random.Random(seed)
        s1 = 1.0 / math.sqrt(d_model)
        s2 = 1.0 / math.sqrt(h)
        self.anchor = [[rng.gauss(0.0, s1) for _ in range(d_model)]
                       for _ in range(num_tokens)]
        self.W1 = [[rng.gauss(0.0, s1) for _ in range(d_model)]
                   for _ in range(h)]
        self.b1 = [0.0] * h
        self.W2 = [[rng.gauss(0.0, s2) for _ in range(h)]
                   for _ in range(d_model)]
        self.b2 = [0.0] * d_model
        self.zero_grad()
        self.m_anchor = _zeros_like(self.anchor)
        self.v_anchor = _zeros_like(self.anchor)
        self.m_W1 = _zeros_like(self.W1)
        self.v_W1 = _zeros_like(self.W1)
        self.m_b1 = [0.0] * h
        self.v_b1 = [0.0] * h
        self.m_W2 = _zeros_like(self.W2)
        self.v_W2 = _zeros_like(self.W2)
        self.m_b2 = [0.0] * d_model
        self.v_b2 = [0.0] * d_model
        self._t = 0
        self._cache = None

    def prompt_matrix(self):
        rows = []
        for t in range(self.num_tokens):
            z1 = [_dot_row(self.W1[r], self.anchor[t]) + self.b1[r]
                  for r in range(self.hidden)]
            act = [math.tanh(v) for v in z1]
            out = [_dot_row(self.W2[j], act) + self.b2[j]
                   for j in range(self.d_model)]
            rows.append((z1, act, out))
        return [r[2] for r in rows], rows

    def forward(self, seq):
        if not isinstance(seq, list):
            raise ValueError('P_Tuning.forward: seq 必须是列表')
        for row in seq:
            if not isinstance(row, list) or len(row) != self.d_model:
                raise ValueError('P_Tuning.forward: seq 每行要有 %d 个分量'
                                 % self.d_model)
        prompt, rows = self.prompt_matrix()
        self._cache = (len(seq), rows, prompt)
        return [list(r) for r in prompt] + [list(r) for r in seq]

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError('P_Tuning.backward: 需要先 forward')
        n = self.num_tokens
        t_len, rows, prompt = self._cache
        if not isinstance(dout, list) or len(dout) != n + t_len:
            raise ValueError('P_Tuning.backward: dout 要有 %d 行' % (n + t_len))
        for t in range(n):
            z1, act, _out = rows[t]
            dprompt = dout[t]
            dz1 = [0.0] * self.hidden
            for j in range(self.d_model):
                g = dprompt[j]
                if g == 0.0:
                    continue
                self.g_b2[j] += g
                for r in range(self.hidden):
                    self.g_W2[j][r] += g * act[r]
                    dz1[r] += g * self.W2[j][r]
            for r in range(self.hidden):
                dz = dz1[r] * (1.0 - act[r] * act[r])
                self.g_b1[r] += dz
                for k in range(self.d_model):
                    self.g_W1[r][k] += dz * self.anchor[t][k]
                    self.g_anchor[t][k] += dz * self.W1[r][k]
        return [list(dout[n + i]) for i in range(t_len)]

    def zero_grad(self):
        self.g_anchor = [[0.0] * self.d_model for _ in range(self.num_tokens)]
        self.g_W1 = [[0.0] * self.d_model for _ in range(self.hidden)]
        self.g_b1 = [0.0] * self.hidden
        self.g_W2 = [[0.0] * self.hidden for _ in range(self.d_model)]
        self.g_b2 = [0.0] * self.d_model

    def param_count(self) -> int:
        return (self.num_tokens * self.d_model
                + self.hidden * self.d_model + self.hidden
                + self.d_model * self.hidden + self.d_model)

    def _params(self):
        return ((self.anchor, self.g_anchor), (self.W1, self.g_W1),
                (self.b1, self.g_b1), (self.W2, self.g_W2),
                (self.b2, self.g_b2))

    def sgd_step(self, lr: float):
        lr = _la_check_lr(lr, 'P_Tuning.sgd_step')
        for param, grad in self._params():
            _la_apply_sgd(param, grad, lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        lr = _la_check_lr(lr, 'P_Tuning.adam_step')
        _check_adam_betas(beta1, beta2, 'P_Tuning.adam_step')
        self._t += 1
        c1 = 1.0 - beta1 ** self._t
        c2 = 1.0 - beta2 ** self._t
        pairs = (((self.anchor, self.g_anchor), (self.m_anchor, self.v_anchor)),
                 ((self.W1, self.g_W1), (self.m_W1, self.v_W1)),
                 ((self.b1, self.g_b1), (self.m_b1, self.v_b1)),
                 ((self.W2, self.g_W2), (self.m_W2, self.v_W2)),
                 ((self.b2, self.g_b2), (self.m_b2, self.v_b2)))
        for (param, grad), (m, v) in pairs:
            _la_apply_adam(param, grad, m, v, lr, c1, c2, beta1, beta2, eps)

    def train(self):
        return self

    def eval(self):
        return self


def _dot_row(a, b):
    """两个等长行向量的点积"""
    acc = 0.0
    for i in range(len(a)):
        acc += a[i] * b[i]
    return acc


def _is_nonneg_int(v):
    """判断是否为非负整数（bool 不算）"""
    return isinstance(v, int) and not isinstance(v, bool) and v >= 0


def sequence_packing(sequences, pad_id: int = 0):
    """把多条 token 序列打包成一条（不插入分隔符）

    返回 ``dict(tokens, segment_ids, position_ids, segments, length)``：
    ``segment_ids`` 标记每个位置属于第几条序列，``position_ids`` 在每条序列
    内部从 0 重新计数（配合旋转/绝对位置编码时等价于按段重置）。
    """
    if not isinstance(sequences, list) or not sequences:
        raise ValueError('sequence_packing: sequences 必须是非空列表')
    if not _is_nonneg_int(pad_id) or pad_id < 0:
        raise ValueError('sequence_packing: pad_id 必须是非负整数')
    tokens = []
    seg = []
    pos = []
    segments = []
    for sid, seq in enumerate(sequences):
        if not isinstance(seq, list) or not seq:
            raise ValueError('sequence_packing: 第 %d 条序列必须是非空列表'
                             % sid)
        start = len(tokens)
        for p, tok in enumerate(seq):
            if not _is_nonneg_int(tok) or tok < 0:
                raise ValueError('sequence_packing: token 必须是非负整数，'
                                 '第 %d 条序列位置 %d 收到 %r' % (sid, p, tok))
            tokens.append(tok)
            seg.append(sid)
            pos.append(p)
        segments.append((start, len(tokens)))
    return {'tokens': tokens, 'segment_ids': seg, 'position_ids': pos,
            'segments': segments, 'length': len(tokens)}


def packed_causal_mask(segment_ids, causal: bool = True):
    """打包序列的注意力掩码：只允许同段（``causal=True`` 时再加 ``j <= i``）"""
    if not isinstance(segment_ids, list) or not segment_ids:
        raise ValueError('packed_causal_mask: segment_ids 必须是非空列表')
    for sid in segment_ids:
        if not _is_nonneg_int(sid) or sid < 0:
            raise ValueError('packed_causal_mask: segment id 必须是非负整数')
    n = len(segment_ids)
    mask = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if segment_ids[i] != segment_ids[j]:
                continue
            if causal and j > i:
                continue
            mask[i][j] = 1.0
    return mask


class PrefixCache:
    """逐层 KV 前缀缓存（可持久化）

    每层存 ``keys`` / ``values`` 两张 ``(len, d)`` 的行表；``set`` 覆盖某层、
    ``get`` 取出、``truncate`` 截断到指定长度、``merge`` 追加另一份缓存的同层
    内容，``to_dict`` / ``from_dict`` / ``save`` / ``load`` 做 JSON 持久化。
    """

    def __init__(self, num_layers: int, d_model: int):
        _ck_int(num_layers, 'PrefixCache(num_layers)', 1)
        _ck_int(d_model, 'PrefixCache(d_model)', 1)
        self.num_layers = num_layers
        self.d_model = d_model
        self.keys = [[] for _ in range(num_layers)]
        self.values = [[] for _ in range(num_layers)]

    def set(self, layer: int, keys, values):
        self._check_layer(layer)
        ks = self._check_rows(keys, 'PrefixCache.set(keys)')
        vs = self._check_rows(values, 'PrefixCache.set(values)')
        if len(ks) != len(vs):
            raise ValueError('PrefixCache.set: keys 与 values 长度必须一致')
        self.keys[layer] = ks
        self.values[layer] = vs

    def get(self, layer: int):
        self._check_layer(layer)
        return ([list(r) for r in self.keys[layer]],
                [list(r) for r in self.values[layer]])

    def length(self, layer: int) -> int:
        self._check_layer(layer)
        return len(self.keys[layer])

    def truncate(self, new_len: int):
        _ck_int(new_len, 'PrefixCache.truncate(new_len)', 0)
        for layer in range(self.num_layers):
            if len(self.keys[layer]) > new_len:
                self.keys[layer] = self.keys[layer][:new_len]
                self.values[layer] = self.values[layer][:new_len]

    def merge(self, other):
        if not isinstance(other, PrefixCache):
            raise TypeError('PrefixCache.merge: 需要另一个 PrefixCache')
        if (other.num_layers != self.num_layers
                or other.d_model != self.d_model):
            raise ValueError('PrefixCache.merge: 层数或维度不一致')
        for layer in range(self.num_layers):
            self.keys[layer] = self.keys[layer] + [list(r) for r in other.keys[layer]]
            self.values[layer] = (self.values[layer]
                                  + [list(r) for r in other.values[layer]])

    def to_dict(self):
        return {'num_layers': self.num_layers, 'd_model': self.d_model,
                'keys': [list(r) for r in self.keys],
                'values': [list(r) for r in self.values]}

    @classmethod
    def from_dict(cls, data):
        if not isinstance(data, dict):
            raise ValueError('PrefixCache.from_dict: 需要字典')
        for key in ('num_layers', 'd_model', 'keys', 'values'):
            if key not in data:
                raise ValueError('PrefixCache.from_dict: 缺少字段 %r' % key)
        obj = cls(data['num_layers'], data['d_model'])
        if (not isinstance(data['keys'], list)
                or len(data['keys']) != obj.num_layers):
            raise ValueError('PrefixCache.from_dict: keys 要以层为单位')
        for layer in range(obj.num_layers):
            obj.set(layer, data['keys'][layer], data['values'][layer])
        return obj

    def save(self, path: str):
        payload = json.dumps(self.to_dict(), ensure_ascii=False,
                             allow_nan=False)
        with io.open(path, 'w', encoding='utf-8') as f:
            f.write(payload)

    def load(self, path: str):
        with io.open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        other = PrefixCache.from_dict(data)
        self.keys = other.keys
        self.values = other.values
        return self

    def _check_layer(self, layer):
        if not _is_nonneg_int(layer) or layer < 0 or layer >= self.num_layers:
            raise ValueError('PrefixCache: layer 必须在 [0, %d) 内'
                             % self.num_layers)

    def _check_rows(self, rows, who):
        if not isinstance(rows, list):
            raise ValueError('%s 必须是行列表' % who)
        out = []
        for row in rows:
            if not isinstance(row, list) or len(row) != self.d_model:
                raise ValueError('%s 每行要有 %d 个分量'
                                 % (who, self.d_model))
            for v in row:
                if not _is_num(v):
                    raise ValueError('%s 必须是有限数字' % who)
            out.append([float(v) for v in row])
        return out


class DoRALinear:
    """DoRA：把权重拆成「幅度 × 方向」，LoRA 只作用在方向上

    ``Weff = V + scaling*B A``、``W' = m / (||Weff||_row + eps) * Weff``、
    ``y = W' x + b``。``V`` 初始化为原层权重、``m`` 初始化为原层行范数，所以
    ``B=0`` 时输出与原层**逐位相同**。相比纯 LoRA，幅度与方向解耦后小秩也有足够
    的表达能力。
    """

    def __init__(self, layer: Layer, rank: int = 4, alpha: float = None,
                 eps: float = 1e-8):
        if not isinstance(layer, Layer):
            raise TypeError('DoRALinear: layer 必须是 Layer 实例，收到 %s'
                            % type(layer).__name__)
        if isinstance(rank, bool) or not isinstance(rank, int) or rank < 1:
            raise ValueError('DoRALinear: rank 必须是正整数，收到 %r' % (rank,))
        if not _is_num(eps) or eps <= 0.0:
            raise ValueError('DoRALinear: eps 必须 > 0，收到 %r' % (eps,))
        self.layer = layer
        self.rank = rank
        self.fan_in = layer.fan_in
        self.fan_out = layer.fan_out
        self.alpha = float(rank if alpha is None else alpha)
        if self.alpha <= 0.0:
            raise ValueError('DoRALinear: alpha 必须 > 0，收到 %r' % (alpha,))
        self.scaling = self.alpha / rank
        self.eps = float(eps)
        self.V = [list(row) for row in layer.weights]
        self.b = list(layer.biases)
        self.m = [math.sqrt(sum(v * v for v in row)) for row in self.V]
        std = 1.0 / math.sqrt(self.fan_in)
        self.A = [[random.gauss(0.0, std) for _ in range(self.fan_in)]
                  for _ in range(self.rank)]
        self.B = [[0.0] * self.rank for _ in range(self.fan_out)]
        self.zero_grad()
        self._cache = None

    def _den(self, n):
        """归一化分母：只在范数为 0 时用 eps 兜底（不污染正常路径，保证 B=0 逐位一致）"""
        return n if n > self.eps else self.eps

    def _weff(self):
        out = []
        norms = []
        for j in range(self.fan_out):
            row = list(self.V[j])
            for r in range(self.rank):
                g = self.scaling * self.B[j][r]
                if g == 0.0:
                    continue
                ar = self.A[r]
                for i in range(self.fan_in):
                    row[i] += g * ar[i]
            out.append(row)
            norms.append(math.sqrt(sum(v * v for v in row)))
        return out, norms

    def denormalized(self):
        """当前的有效权重 ``W'``"""
        weff, norms = self._weff()
        return [[self.m[j] * weff[j][i] / self._den(norms[j])
                 for i in range(self.fan_in)] for j in range(self.fan_out)]

    def forward(self, x):
        weff, norms = self._weff()
        c = [self.m[j] / self._den(norms[j]) for j in range(self.fan_out)]
        w = [[c[j] * weff[j][i] for i in range(self.fan_in)]
             for j in range(self.fan_out)]
        out = [sum(map(_mul, w[j], x)) + self.b[j] for j in range(self.fan_out)]
        self._cache = (x, weff, norms, c, w)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError('DoRALinear.backward: 必须先调用 forward()')
        x, weff, norms, c, w = self._cache
        dweff = [[0.0] * self.fan_in for _ in range(self.fan_out)]
        for j in range(self.fan_out):
            dj = dout[j]
            n_j = self._den(norms[j])
            proj = sum(map(_mul, weff[j], x))
            coef = c[j] * dj
            dcoe = dj * proj
            self.g_m[j] += dcoe / n_j
            k = -dcoe * self.m[j] / (n_j ** 3)
            row = dweff[j]
            for i in range(self.fan_in):
                row[i] = coef * x[i] + k * weff[j][i]
                self.g_V[j][i] += row[i]
        for j in range(self.fan_out):
            for r in range(self.rank):
                if self.B[j][r] == 0.0:
                    continue
                acc = 0.0
                for i in range(self.fan_in):
                    acc += self.scaling * self.A[r][i] * dweff[j][i]
                self.g_B[j][r] += acc
        for r in range(self.rank):
            for i in range(self.fan_in):
                acc = 0.0
                for j in range(self.fan_out):
                    acc += self.scaling * self.B[j][r] * dweff[j][i]
                self.g_A[r][i] += acc
        dx = [0.0] * self.fan_in
        for j in range(self.fan_out):
            dj = dout[j]
            row = w[j]
            for i in range(self.fan_in):
                dx[i] += row[i] * dj
        return dx

    def zero_grad(self):
        self.g_V = [[0.0] * self.fan_in for _ in range(self.fan_out)]
        self.g_m = [0.0] * self.fan_out
        self.g_A = [[0.0] * self.fan_in for _ in range(self.rank)]
        self.g_B = [[0.0] * self.rank for _ in range(self.fan_out)]

    def params(self):
        return [(self.V, self.g_V), (self.m, self.g_m),
                (self.A, self.g_A), (self.B, self.g_B)]

    def param_count(self) -> int:
        return (self.fan_out + self.rank * self.fan_in
                + self.fan_out * self.rank)

    def trainable_count(self) -> int:
        return self.param_count()

    def merge(self):
        """把幅度与方向折回原层权重（之后 ``forward`` 走原层）"""
        w = self.denormalized()
        for j in range(self.fan_out):
            for i in range(self.fan_in):
                self.layer.weights[j][i] = w[j][i]
        self.merged = True
        return self

    def train(self):
        return self

    def eval(self):
        return self


class AdaLoRALinear:
    """AdaLoRA（简化版）：按秩重要性自适应收缩秩预算

    ``y = layer(x) + scaling * B A x``，每秩维护重要性 ``imp[r]``（``|A_r|`` 与
    ``|B_:,r|`` 范数乘积的 EMA）。``prune(keep)`` 只保留最重要的 ``keep`` 个秩，
    其余把 A 的行与 B 的列整体置零并停止接收梯度；``active_ranks()`` 返回存活秩。
    """

    def __init__(self, layer: Layer, rank: int = 8, alpha: float = None,
                 ema: float = 0.9, seed: int = 0):
        if not isinstance(layer, Layer):
            raise TypeError('AdaLoRALinear: layer 必须是 Layer 实例，收到 %s'
                            % type(layer).__name__)
        if isinstance(rank, bool) or not isinstance(rank, int) or rank < 1:
            raise ValueError('AdaLoRALinear: rank 必须是正整数，收到 %r' % (rank,))
        if not _is_num(ema) or not (0.0 <= float(ema) < 1.0):
            raise ValueError('AdaLoRALinear: ema 必须在 [0,1) 内，收到 %r' % (ema,))
        self.layer = layer
        self.rank = rank
        self.fan_in = layer.fan_in
        self.fan_out = layer.fan_out
        self.alpha = float(rank if alpha is None else alpha)
        if self.alpha <= 0.0:
            raise ValueError('AdaLoRALinear: alpha 必须 > 0，收到 %r' % (alpha,))
        self.scaling = self.alpha / rank
        self.ema = float(ema)
        rng = random.Random(seed)
        std = 1.0 / math.sqrt(self.fan_in)
        self.A = [[rng.gauss(0.0, std) for _ in range(self.fan_in)]
                  for _ in range(rank)]
        self.B = [[0.0] * rank for _ in range(self.fan_out)]
        self.imp = [0.0] * rank
        self.seen = [False] * rank
        self.alive = [True] * rank
        self.zero_grad()
        self._cache = None

    def active_ranks(self):
        return [r for r in range(self.rank) if self.alive[r]]

    def forward(self, x):
        base = self.layer.forward(x)
        h = [sum(map(_mul, self.A[r], x)) if self.alive[r] else 0.0
             for r in range(self.rank)]
        out = []
        for j in range(self.fan_out):
            acc = base[j]
            for r in range(self.rank):
                if not self.alive[r]:
                    continue
                acc += self.scaling * self.B[j][r] * h[r]
            out.append(acc)
        self._cache = (x, h)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError('AdaLoRALinear.backward: 必须先调用 forward()')
        x, h = self._cache
        dx = self.layer.backward(dout)[-1]
        for j in range(self.fan_out):
            for r in range(self.rank):
                if not self.alive[r]:
                    continue
                self.g_B[j][r] += self.scaling * dout[j] * h[r]
        for r in range(self.rank):
            if not self.alive[r]:
                continue
            for i in range(self.fan_in):
                acc = 0.0
                for j in range(self.fan_out):
                    acc += self.scaling * self.B[j][r] * dout[j]
                self.g_A[r][i] += acc * x[i]
            na = math.sqrt(sum(v * v for v in self.A[r]))
            nb = math.sqrt(sum(self.B[j][r] ** 2 for j in range(self.fan_out)))
            cur = na * nb
            if self.seen[r]:
                self.imp[r] = self.ema * self.imp[r] + (1.0 - self.ema) * cur
            else:
                self.imp[r] = cur
                self.seen[r] = True
        for r in range(self.rank):
            if not self.alive[r]:
                continue
            for i in range(self.fan_in):
                acc = 0.0
                for j in range(self.fan_out):
                    acc += self.scaling * self.B[j][r] * dout[j]
                dx[i] += acc * self.A[r][i]
        return dx

    def prune(self, keep: int):
        """只保留重要性最高的 ``keep`` 个秩（其余 A 行、B 列置零）"""
        if isinstance(keep, bool) or not isinstance(keep, int) or keep < 1:
            raise ValueError('AdaLoRALinear.prune: keep 必须是正整数，收到 %r'
                             % (keep,))
        if keep > self.rank:
            raise ValueError('AdaLoRALinear.prune: keep 不能超过 rank=%d'
                             % self.rank)
        order = sorted(range(self.rank), key=lambda r: (-self.imp[r], r))
        keep_set = set(order[:keep])
        for r in range(self.rank):
            if r in keep_set:
                self.alive[r] = True
                continue
            self.alive[r] = False
            for i in range(self.fan_in):
                self.A[r][i] = 0.0
                self.g_A[r][i] = 0.0
            for j in range(self.fan_out):
                self.B[j][r] = 0.0
                self.g_B[j][r] = 0.0
        return self.active_ranks()

    def zero_grad(self):
        self.g_A = [[0.0] * self.fan_in for _ in range(self.rank)]
        self.g_B = [[0.0] * self.rank for _ in range(self.fan_out)]

    def params(self):
        return [(self.A, self.g_A), (self.B, self.g_B)]

    def param_count(self) -> int:
        return self.rank * self.fan_in + self.fan_out * self.rank

    def merge(self):
        W = self.layer.weights
        for r in range(self.rank):
            if not self.alive[r]:
                continue
            for j in range(self.fan_out):
                g = self.scaling * self.B[j][r]
                if g == 0.0:
                    continue
                for i in range(self.fan_in):
                    W[j][i] += g * self.A[r][i]
        self.merged = True
        return self

    def train(self):
        return self

    def eval(self):
        return self


def _check_mass(mass, who):
    if isinstance(mass, bool) or not isinstance(mass, (int, float)):
        raise ValueError('%s: mass 必须是数字，收到 %r' % (who, mass))
    mass = float(mass)
    if mass != mass or not (0.0 < mass <= 1.0):
        raise ValueError('%s: mass 必须在 (0,1] 内，收到 %r' % (who, mass))
    return mass


def _apply_keep_mask(logits, keep):
    if not keep:
        raise ValueError('_apply_keep_mask: 过滤后没有任何 token 可用')
    return [v if i in keep else float('-inf') for i, v in enumerate(logits)]


def typical_filter(logits, mass: float = 0.9):
    """typical sampling：保留「惊讶度最接近条件熵」的 token 直到累计概率 >= mass"""
    mass = _check_mass(mass, 'typical_filter(mass)')
    probs = _softmax_row(logits)
    entropy = -sum(p * math.log(p) for p in probs if p > 0.0)
    cand = sorted((abs(-math.log(p) - entropy), i)
                  for i, p in enumerate(probs) if p > 0.0)
    keep = set()
    acc = 0.0
    for _score, i in cand:
        keep.add(i)
        acc += probs[i]
        if acc >= mass:
            break
    return _apply_keep_mask(logits, keep)


def top_a_filter(logits, top_a: float = 0.1):
    """top-a：阈值 ``top_a * p_max²``（``top_a=0`` 时不过滤）"""
    if isinstance(top_a, bool) or not isinstance(top_a, (int, float)):
        raise ValueError('top_a_filter: top_a 必须是数字，收到 %r' % (top_a,))
    top_a = float(top_a)
    if top_a != top_a or not (0.0 <= top_a <= 1.0):
        raise ValueError('top_a_filter: top_a 必须在 [0,1] 内，收到 %r' % (top_a,))
    if top_a == 0.0:
        return list(logits)
    probs = _softmax_row(logits)
    peak = max(probs)
    thresh = top_a * peak * peak
    keep = set(i for i, p in enumerate(probs) if p >= thresh)
    return _apply_keep_mask(logits, keep)


def eta_filter(logits, eta: float = 0.3):
    """eta 采样：丢弃概率 <= eta 的 token（至少保留 argmax）"""
    if isinstance(eta, bool) or not isinstance(eta, (int, float)):
        raise ValueError('eta_filter: eta 必须是数字，收到 %r' % (eta,))
    eta = float(eta)
    if eta != eta or not (0.0 <= eta < 1.0):
        raise ValueError('eta_filter: eta 必须在 [0,1) 内，收到 %r' % (eta,))
    probs = _softmax_row(logits)
    top = max(range(len(probs)), key=lambda i: probs[i])
    keep = set(i for i, p in enumerate(probs) if p > eta)
    keep.add(top)
    return _apply_keep_mask(logits, keep)


def mirostat_filter(logits, mu: float = 5.0):
    """Mirostat 掩码：保留 ``-log p <= mu`` 的 token（至少保留 argmax）

    返回 ``(masked_logits, 保留集的熵)``，配合 ``mirostat_update`` 迭代即可。
    """
    if isinstance(mu, bool) or not isinstance(mu, (int, float)):
        raise ValueError('mirostat_filter: mu 必须是数字，收到 %r' % (mu,))
    mu = float(mu)
    if mu != mu or mu < 0.0:
        raise ValueError('mirostat_filter: mu 必须 >= 0，收到 %r' % (mu,))
    probs = _softmax_row(logits)
    top = max(range(len(probs)), key=lambda i: probs[i])
    keep = set(i for i, p in enumerate(probs) if p > 0.0 and -math.log(p) <= mu)
    keep.add(top)
    total = sum(probs[i] for i in keep)
    ent = 0.0
    for i in keep:
        q = probs[i] / total
        ent -= q * math.log(q)
    return _apply_keep_mask(logits, keep), ent


def mirostat_update(mu: float, observed_surprisal: float,
                    target_entropy: float = 2.0, strength: float = 0.2) -> float:
    """Mirostat 的 mu 更新：``mu -= strength * (observed - target)``，下限 0"""
    for name, val in (('mu', mu), ('observed_surprisal', observed_surprisal),
                      ('target_entropy', target_entropy),
                      ('strength', strength)):
        if isinstance(val, bool) or not isinstance(val, (int, float)):
            raise ValueError('mirostat_update: %s 必须是数字，收到 %r'
                             % (name, val))
        val = float(val)
        if val != val or val in (float('inf'), float('-inf')):
            raise ValueError('mirostat_update: %s 必须是有限值，收到 %r'
                             % (name, val))
    if target_entropy < 0.0:
        raise ValueError('mirostat_update: target_entropy 必须 >= 0')
    if strength < 0.0:
        raise ValueError('mirostat_update: strength 必须 >= 0')
    return max(0.0, float(mu) - float(strength)
               * (float(observed_surprisal) - float(target_entropy)))


def tail_free_filter(logits, tft: float = 0.5):
    """Tail-free 采样（Zhu et al.）：按 log 概率曲线的二阶差分截断长尾

    步骤：softmax → 按概率降序 → 对 ``log p`` 取一阶/二阶差分 → 用二阶差分的
    最大绝对值归一化 → 找到第一个「归一化二阶差分 < ``tft``」的位置，保留它及其之前
    的 token（至少保留 argmax）。返回**新的** logits，未保留的位置为 ``-inf``。

    ``tft`` 越小保留越多，越大保留越少（最少 1 个）。这是纯函数，不修改入参。
    """
    if isinstance(tft, bool) or not isinstance(tft, (int, float)):
        raise ValueError('tail_free_filter: tft 必须是数字，收到 %r' % (tft,))
    tft = float(tft)
    if tft != tft or tft in (float('inf'), float('-inf')):
        raise ValueError('tail_free_filter: tft 必须是有限值')
    if tft <= 0.0:
        raise ValueError('tail_free_filter: tft 必须 > 0，收到 %r' % (tft,))
    if not isinstance(logits, (list, tuple)) or not logits:
        raise ValueError('tail_free_filter: logits 必须是非空列表')
    for v in logits:
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError('tail_free_filter: logits 元素必须是数字，收到 %r'
                             % (v,))
        if v != v or v in (float('inf'), float('-inf')):
            raise ValueError('tail_free_filter: logits 必须都是有限值')
    vals = [float(v) for v in logits]
    n = len(vals)
    if n <= 2:
        return list(vals)
    probs = _softmax_row(vals)
    order = sorted(range(n), key=lambda i: (-probs[i], i))
    lp = [math.log(probs[i]) if probs[i] > 0.0 else -745.0 for i in order]
    d1 = [lp[i + 1] - lp[i] for i in range(n - 1)]
    d2 = [d1[i + 1] - d1[i] for i in range(n - 2)]
    scale = max(abs(v) for v in d2)
    if scale <= 0.0:
        keep = 1
    else:
        # 头部几项的二阶差分恰好为 0（log 概率曲线在头部是线性的），若从 0 开始找
        # 会立刻截断，所以从第 1 项起找第一个「归一化二阶差分 < tft」的位置
        keep = n
        for i in range(1, len(d2)):
            if d2[i] / scale < tft:
                keep = i + 2
                break
    keep = max(1, min(keep, n))
    allowed = order[:keep]
    return _apply_keep_mask(vals, allowed)


class PagedKVCache:
    """PagedAttention 的块表（数据结构演示，不做真实显存管理）

    把每条请求的 KV 缓存切成固定大小的块（``block_size`` 个 token 一块），
    逻辑位置到物理块的映射记在块表里，因此请求的物理块**不必连续**，
    释放后可以立刻被别的请求复用。

    - ``new_request()`` / ``append(rid, layer, key, value)`` / ``get(rid, layer)``
    - ``length(rid)``：已写入的 token 数
    - ``free(rid)``：归还全部物理块
    - ``stats()``：``{'tokens', 'blocks_used', 'blocks_free', 'slots_used',
      'slots_capacity', 'fragmentation'}``

    ``key``/``value`` 的形状是 ``(num_heads, head_dim)``，对应**一个** token。
    ``fragmentation`` = 已分配但尚未写入的槽位比例（越小说明块用得越满）。
    """

    def __init__(self, num_layers: int, num_heads: int, head_dim: int,
                 block_size: int = 4, max_blocks: int = 16):
        for name, val in (('num_layers', num_layers), ('num_heads', num_heads),
                          ('head_dim', head_dim), ('block_size', block_size),
                          ('max_blocks', max_blocks)):
            if isinstance(val, bool) or not isinstance(val, int) or val < 1:
                raise ValueError('PagedKVCache: %s 必须是正整数，收到 %r'
                                 % (name, val))
        self.num_layers = num_layers
        self.num_heads = num_heads
        self.head_dim = head_dim
        self.block_size = block_size
        self.max_blocks = max_blocks
        self._blocks = {}          # 物理块号 -> {layer: [(k, v), ...]}
        self._free = list(range(max_blocks))
        self._tables = {}          # rid -> [物理块号, ...]（逻辑顺序）
        self._lens = {}            # rid -> token 数
        self._seq = 0

    # ---------- 内部 ----------
    @staticmethod
    def _check_rid(rid, tables, who):
        if rid not in tables:
            raise ValueError('%s: 未知请求 %r' % (who, rid))

    def _check_layer(self, layer, who):
        if isinstance(layer, bool) or not isinstance(layer, int):
            raise ValueError('%s: layer 必须是整数，收到 %r' % (who, layer))
        if not 0 <= layer < self.num_layers:
            raise ValueError('%s: layer 越界 %r（共 %d 层）'
                             % (who, layer, self.num_layers))

    def _check_row(self, row, name, who):
        if not isinstance(row, (list, tuple)) or len(row) != self.num_heads:
            raise ValueError('%s: %s 必须是长度 %d 的列表，收到 %r'
                             % (who, name, self.num_heads, row))
        out = []
        for h in row:
            if not isinstance(h, (list, tuple)) or len(h) != self.head_dim:
                raise ValueError('%s: %s 的每行必须是长度 %d 的列表'
                                 % (who, name, self.head_dim))
            out.append([float(v) for v in h])
        return out

    # ---------- 对外 ----------
    def new_request(self):
        rid = self._seq
        self._seq += 1
        self._tables[rid] = []
        self._lens[rid] = 0
        return rid

    def length(self, rid):
        self._check_rid(rid, self._tables, 'PagedKVCache.length')
        return self._lens[rid]

    def append(self, rid, layer, key, value):
        """写入一个 token 的 K/V；块不够时抛 ValueError（模拟显存耗尽）"""
        who = 'PagedKVCache.append'
        self._check_rid(rid, self._tables, who)
        self._check_layer(layer, who)
        k = self._check_row(key, 'key', who)
        v = self._check_row(value, 'value', who)
        table = self._tables[rid]
        pos = self._lens[rid]
        need = pos // self.block_size + 1
        while len(table) < need:
            if not self._free:
                raise ValueError('%s: 物理块已用尽（max_blocks=%d）'
                                 % (who, self.max_blocks))
            table.append(self._free.pop(0))
        blk = self._blocks.setdefault(table[need - 1], {})
        rows = blk.setdefault(layer, [])
        rows.append((k, v))
        self._lens[rid] = pos + 1

    def get(self, rid, layer):
        """按逻辑顺序返回 ``{'key': [...], 'value': [...]}``（各 T 行）"""
        who = 'PagedKVCache.get'
        self._check_rid(rid, self._tables, who)
        self._check_layer(layer, who)
        keys, vals = [], []
        remain = self._lens[rid]
        for bid in self._tables[rid]:
            rows = self._blocks.get(bid, {}).get(layer, [])
            for k, v in rows:
                if remain <= 0:
                    break
                keys.append([list(r) for r in k])
                vals.append([list(r) for r in v])
                remain -= 1
        return {'key': keys, 'value': vals}

    def free(self, rid):
        who = 'PagedKVCache.free'
        self._check_rid(rid, self._tables, who)
        for bid in self._tables[rid]:
            self._blocks.pop(bid, None)
            self._free.append(bid)
        self._free.sort()
        del self._tables[rid]
        del self._lens[rid]

    def stats(self):
        used = len(self._blocks)
        slots = used * self.block_size
        tokens = sum(self._lens.values())
        frag = 0.0 if slots == 0 else 1.0 - tokens / slots
        return {'tokens': tokens, 'blocks_used': used,
                'blocks_free': len(self._free), 'slots_used': tokens,
                'slots_capacity': slots, 'fragmentation': frag}


def token_id_mask(logits, allowed):
    """约束解码：只保留 ``allowed`` 里的 token id，其余置 ``-inf``

    返回新的 logits 列表，不修改入参；``allowed`` 为空、越界或元素不是整数都报
    ``ValueError``。与现有采样器（``top_k`` / ``top_p`` / ``min_p`` …）可直接叠加。
    """
    n = len(logits)
    ids = _check_allowed_ids(allowed, n, 'token_id_mask(allowed)')
    if not ids:
        raise ValueError('token_id_mask: allowed 不能为空')
    return [v if i in ids else float('-inf') for i, v in enumerate(logits)]


def token_prefix_mask(logits, generated, sequences, eos_id=None):
    """约束解码：只允许「仍然可能是 ``sequences`` 之一的前缀」的下一个 token

    ``sequences`` 是若干 token-id 列表。``generated`` 必须已经是某条序列的前缀，
    否则报 ``ValueError``；当 ``generated`` 已等于某条完整序列时，若给了 ``eos_id``
    就只允许它，否则抛出 ``ValueError``（说明该收尾了）。
    """
    ids = _check_allowed_ids(generated, len(logits), 'token_prefix_mask(generated)')
    if not ids and generated:
        raise ValueError('token_prefix_mask: generated 里没有合法的 token id')
    seqs = _check_token_sequences(sequences)
    hits = [q for q in seqs if len(q) >= len(ids) and q[:len(ids)] == ids]
    if not hits:
        raise ValueError('token_prefix_mask: generated 不是任何序列的前缀')
    allowed = set()
    done = False
    for q in hits:
        if len(q) == len(ids):
            done = True
            if eos_id is not None:
                allowed.add(int(eos_id))
        else:
            allowed.add(q[len(ids)])
    if not allowed:
        raise ValueError('token_prefix_mask: 序列已完整且未提供 eos_id，'
                         '没有可继续的 token（done=%s）' % done)
    for i in allowed:
        if i < 0 or i >= len(logits):
            raise ValueError('token_prefix_mask: 允许的 token id %d 越界（词表 %d）'
                             % (i, len(logits)))
    return [v if i in allowed else float('-inf') for i, v in enumerate(logits)]


def speculative_accept(draft_ids, draft_probs, target_probs, uniforms=None,
                       rng=None):
    """投机解码的接受判定（拒绝采样）

    对草稿模型给出的每个 token 位置，按 ``min(1, p_target/p_draft)`` 接受；遇到第一个
    被拒的位置时，从残差分布 ``max(0, p_target - p_draft)`` 重采样一个新 token。

    返回 ``(接受个数, 重采样出的 token 或 None)``。``uniforms`` 可注入（逐位置的
    ``[0,1)`` 均匀数）以便确定性测试，缺省用 ``rng``（默认全局 ``random``）。
    """
    if not isinstance(draft_ids, (list, tuple)):
        raise ValueError('speculative_accept: draft_ids 必须是列表')
    n = len(draft_ids)
    if n == 0:
        raise ValueError('speculative_accept: draft_ids 不能为空')
    for i, t in enumerate(draft_ids):
        if isinstance(t, bool) or not isinstance(t, int) or t < 0:
            raise ValueError('speculative_accept: draft_ids[%d] 必须是非负整数，'
                             '收到 %r' % (i, t))
    for name, seq in (('draft_probs', draft_probs), ('target_probs', target_probs)):
        if not isinstance(seq, (list, tuple)) or len(seq) != n:
            raise ValueError('speculative_accept: %s 长度必须等于 draft_ids（%d）'
                             % (name, n))
    for i in range(n):
        for name, seq in (('draft_probs', draft_probs), ('target_probs', target_probs)):
            row = seq[i]
            if not isinstance(row, (list, tuple)) or not row:
                raise ValueError('speculative_accept: %s[%d] 必须是非空概率向量'
                                 % (name, i))
            for j, p in enumerate(row):
                if isinstance(p, bool) or not isinstance(p, (int, float)):
                    raise ValueError('speculative_accept: %s[%d][%d] 必须是数字'
                                     % (name, i, j))
                if p != p or p < 0.0:
                    raise ValueError('speculative_accept: %s[%d][%d] 必须是有限'
                                     '非负数，收到 %r' % (name, i, j, p))
            if abs(sum(row) - 1.0) > 1e-6:
                raise ValueError('speculative_accept: %s[%d] 概率和必须为 1，'
                                 '实测 %.6f' % (name, i, sum(row)))
    for i, t in enumerate(draft_ids):
        for name, seq in (('draft_probs', draft_probs),
                          ('target_probs', target_probs)):
            if t >= len(seq[i]):
                raise ValueError('speculative_accept: draft_ids[%d]=%d 超出 %s[%d] '
                                 '的类别数 %d' % (i, t, name, i, len(seq[i])))
    if uniforms is None:
        src = random if rng is None else rng
        uniforms = [src.random() for _ in range(n)]
    else:
        if len(uniforms) != n:
            raise ValueError('speculative_accept: uniforms 长度必须等于 draft_ids')
        for u in uniforms:
            if isinstance(u, bool) or not isinstance(u, (int, float)):
                raise ValueError('speculative_accept: uniforms 必须是数字')
            if not (0.0 <= float(u) < 1.0):
                raise ValueError('speculative_accept: uniforms 必须在 [0,1) 内')
    accepted = 0
    for i in range(n):
        t = draft_ids[i]
        q = draft_probs[i][t]
        p = target_probs[i][t]
        if p < 0.0 or q < 0.0:
            raise ValueError('speculative_accept: 概率不能为负')
        if q == 0.0:
            ratio = float('inf') if p > 0.0 else 0.0
        else:
            ratio = p / q
        if uniforms[i] < min(1.0, ratio):
            accepted += 1
            continue
        resid = [max(0.0, target_probs[i][j] - draft_probs[i][j])
                 for j in range(len(target_probs[i]))]
        total = sum(resid)
        if total <= 0.0:
            continue
        src = random if rng is None else rng
        u = src.random() * total
        acc = 0.0
        for j, w in enumerate(resid):
            acc += w
            if u <= acc:
                return accepted, j
        return accepted, len(resid) - 1
    return accepted, None


def _check_allowed_ids(ids, vocab_size, who):
    if not isinstance(ids, (list, tuple, set)):
        raise ValueError('%s: 必须是列表 / 元组 / 集合，收到 %s'
                         % (who, type(ids).__name__))
    out = []
    for v in ids:
        if isinstance(v, bool) or not isinstance(v, int):
            raise ValueError('%s: 元素必须是非负整数，收到 %r' % (who, v))
        if v < 0 or v >= vocab_size:
            raise ValueError('%s: token id %d 越界（词表 %d）' % (who, v, vocab_size))
        out.append(v)
    return out


def _check_token_sequences(sequences):
    if not isinstance(sequences, (list, tuple)) or not sequences:
        raise ValueError('_check_token_sequences: sequences 必须是非空列表')
    out = []
    for k, q in enumerate(sequences):
        if not isinstance(q, (list, tuple)) or not q:
            raise ValueError('_check_token_sequences: sequences[%d] 必须是非空列表'
                             % k)
        row = []
        for v in q:
            if isinstance(v, bool) or not isinstance(v, int) or v < 0:
                raise ValueError('_check_token_sequences: sequences[%d] 的元素必须是'
                                 '非负整数，收到 %r' % (k, v))
            row.append(v)
        out.append(row)
    return out


class ContinuousBatcher:
    """连续批处理调度器：请求随时进出，每步按容量重新组批

    与「等一整批跑完再收下一批」的静态批处理不同，这里每步都会把已经结束的请求移出、
    把排队的请求补进来，因此一条短请求不会被同批的长请求拖住。本类只做**调度与记账**，
    真正的下一步 token 由调用方通过 ``step(tokens)`` 喂进来，所以它不依赖任何模型实现。

    - ``add(prompt, max_new=4, request_id=None)``：入队，返回请求 id。
    - ``batch()``：当前应当送进模型前向的 ``[(id, ids), ...]``（``ids`` 含提示词与已生成）。
    - ``step(tokens)``：给每个运行中的请求喂一个 token（``{id: token}``），处理结束与补位，
      返回 ``[(id, token), ...]``；缺 token、未知 id、重复 id 都报错。
    - ``running`` / ``waiting`` / ``finished``：当前状态快照（列表副本）。
    """

    def __init__(self, max_batch: int = 2, max_total_tokens: int = None):
        if isinstance(max_batch, bool) or not isinstance(max_batch, int) or max_batch < 1:
            raise ValueError('ContinuousBatcher: max_batch 必须是正整数，收到 %r'
                             % (max_batch,))
        if max_total_tokens is not None:
            if (isinstance(max_total_tokens, bool)
                    or not isinstance(max_total_tokens, int)
                    or max_total_tokens < 1):
                raise ValueError('ContinuousBatcher: max_total_tokens 必须是正整数'
                                 '或 None，收到 %r' % (max_total_tokens,))
        self.max_batch = max_batch
        self.max_total_tokens = max_total_tokens
        self._seq = 0
        self._running = []
        self._waiting = []
        self._finished = []
        self._ids = {}
        self._used = 0
        self._generated = 0

    # ---------- 内部 ----------
    @staticmethod
    def _check_ids(prompt, who):
        if not isinstance(prompt, (list, tuple)) or not prompt:
            raise ValueError('%s: prompt 必须是非空 token 列表' % who)
        out = []
        for v in prompt:
            if isinstance(v, bool) or not isinstance(v, int) or v < 0:
                raise ValueError('%s: prompt 元素必须是非负整数，收到 %r' % (who, v))
            out.append(v)
        return out

    def _admit(self):
        while self._waiting:
            rid = self._waiting[0]
            rec = self._ids[rid]
            if len(self._running) >= self.max_batch:
                break
            if (self.max_total_tokens is not None
                    and self._used + rec['base'] > self.max_total_tokens):
                break
            self._waiting.pop(0)
            self._running.append(rid)
            self._used += rec['base']

    def _retire(self, rid):
        self._running.remove(rid)
        rec = self._ids[rid]
        self._used -= rec['base']
        self._finished.append(rid)

    # ---------- 对外 ----------
    def add(self, prompt, max_new: int = 4, request_id=None):
        ids = self._check_ids(prompt, 'ContinuousBatcher.add(prompt)')
        if isinstance(max_new, bool) or not isinstance(max_new, int) or max_new < 1:
            raise ValueError('ContinuousBatcher.add: max_new 必须是正整数，收到 %r'
                             % (max_new,))
        if request_id is None:
            request_id = self._seq
            self._seq += 1
        if request_id in self._ids:
            raise ValueError('ContinuousBatcher.add: request_id %r 已存在'
                             % (request_id,))
        self._ids[request_id] = {'ids': list(ids), 'max_new': max_new,
                                 'new': 0, 'base': len(ids)}
        self._waiting.append(request_id)
        self._admit()
        return request_id

    def batch(self):
        return [(rid, list(self._ids[rid]['ids'])) for rid in self._running]

    @property
    def running(self):
        return list(self._running)

    @property
    def waiting(self):
        return list(self._waiting)

    @property
    def finished(self):
        return list(self._finished)

    def result(self, request_id):
        if request_id in self._finished:
            return list(self._ids[request_id]['ids'])
        if request_id in self._ids:
            raise ValueError('ContinuousBatcher.result: 请求 %r 尚未结束'
                             % (request_id,))
        raise ValueError('ContinuousBatcher.result: 未知请求 %r' % (request_id,))

    def step(self, tokens):
        if not isinstance(tokens, dict):
            raise ValueError('ContinuousBatcher.step: tokens 必须是 {id: token} 字典')
        if not self._running:
            raise ValueError('ContinuousBatcher.step: 当前没有运行中的请求')
        for rid in list(tokens):
            if rid not in self._ids:
                raise ValueError('ContinuousBatcher.step: 未知请求 %r' % (rid,))
            if rid in self._finished:
                raise ValueError('ContinuousBatcher.step: 请求 %r 已结束' % (rid,))
            if rid not in self._running:
                raise ValueError('ContinuousBatcher.step: 请求 %r 不在运行集中'
                                 % (rid,))
        out = []
        for rid in list(self._running):
            if rid not in tokens:
                raise ValueError('ContinuousBatcher.step: 运行中的请求 %r 缺少 token'
                                 % (rid,))
            tok = tokens[rid]
            if isinstance(tok, bool) or not isinstance(tok, int) or tok < 0:
                raise ValueError('ContinuousBatcher.step: token 必须是非负整数，'
                                 '收到 %r' % (tok,))
            rec = self._ids[rid]
            rec['ids'].append(tok)
            rec['new'] += 1
            self._generated += 1
            out.append((rid, tok))
            if rec['new'] >= rec['max_new']:
                self._retire(rid)
        self._admit()
        return out

    def stats(self):
        return {'running': len(self._running), 'waiting': len(self._waiting),
                'finished': len(self._finished), 'used_tokens': self._used,
                'generated': self._generated}


class Flatten:
    """将 (C, H, W) 展平为 (C*H*W,)"""

    def __init__(self):
        self.x_shape = None

    def forward(self, x):
        """x: (C, H, W) -> 一维列表"""
        C, H, W = len(x), len(x[0]), len(x[0][0])
        self.x_shape = (C, H, W)
        flat = []
        for c in range(C):
            for h in range(H):
                for w in range(W):
                    flat.append(x[c][h][w])
        return flat

    def backward(self, delta):
        """delta: 一维列表 -> (C, H, W)"""
        C, H, W = self.x_shape
        dx = [[[0.0] * W for _ in range(H)] for _ in range(C)]
        idx = 0
        for c in range(C):
            for h in range(H):
                for w in range(W):
                    dx[c][h][w] = delta[idx]
                    idx += 1
        return dx


# ============================================================================
#  Regularization: Dropout / BatchNorm1d / LayerNorm
# ============================================================================

class Dropout:
    """随机丢弃神经元（Inverted Dropout），防止过拟合

    训练时以概率 p 将神经元置零，保留的神经元乘以 1/(1-p) 保持期望不变。
    """

    def __init__(self, p: float = 0.5):
        # p 越界会产生除零（p=1）、全零（p>1）或放大（p<0），必须早失败
        if not isinstance(p, (int, float)) or not (0.0 <= p < 1.0):
            raise ValueError(f"Dropout: p 必须在 [0, 1) 内，收到 {p!r}")
        self.p = p
        self.mask = None
        self.training = True

    def train(self):
        """切到训练模式（dropout 生效）"""
        self.training = True
        return self

    def eval(self):
        """切到推理模式（dropout 关闭，输出确定）

        默认是训练模式，所以在推理前必须显式调用 eval()，
        否则同一输入的两次预测结果会不同。
        """
        self.training = False
        return self

    def forward(self, x):
        if self.training:
            scale = 1.0 / (1.0 - self.p)
            self.mask = [scale if random.random() > self.p else 0.0 for _ in x]
            # 用 zip 一次遍历，省掉 range 索引（数值与逐元素乘法完全一致）
            return [xi * m for xi, m in zip(x, self.mask)]
        self.mask = [1.0] * len(x)
        return x

    def backward(self, delta):
        return [delta[i] * self.mask[i] for i in range(len(delta))]


class SpatialDropout1d:
    """按**通道**丢弃（1D 序列）：整条时间轴上同一个通道一起丢

    输入形如 ``(T, C)``（每个时间步一个 ``C`` 维向量）。与 ``Dropout`` 的区别：
    ``Dropout`` 每个元素独立掷硬币，这里一个通道只有一个掩码值 —— 同一个通道在
    所有时间步上要么全留、要么全丢，等价于 Keras 的 ``SpatialDropout1D``。
    训练时保留通道乘 ``1/(1-p)``（inverted），``eval()`` 后恒等。
    """

    def __init__(self, p: float = 0.2):
        if not isinstance(p, (int, float)) or isinstance(p, bool) or not (0.0 <= p < 1.0):
            raise ValueError(f"SpatialDropout1d: p 必须在 [0, 1) 内，收到 {p!r}")
        self.p = float(p)
        self.mask = None
        self.channels = None
        self.training = True

    def train(self):
        """训练模式：按通道丢弃"""
        self.training = True
        return self

    def eval(self):
        """推理模式：恒等映射"""
        self.training = False
        return self

    def forward(self, x):
        if not x:
            raise ValueError("SpatialDropout1d.forward: 输入不能为空")
        if not isinstance(x[0], list):
            raise ValueError("SpatialDropout1d.forward: 输入形状必须是 (T, C)")
        c = len(x[0])
        if c == 0 or any(len(step) != c for step in x):
            raise ValueError(f"SpatialDropout1d.forward: 每个时间步长度必须一致且非空，"
                             f"收到首步 {c} 维")
        self.channels = c
        if not self.training:
            self.mask = [1.0] * c
            return x
        scale = 1.0 / (1.0 - self.p)
        self.mask = [scale if random.random() > self.p else 0.0 for _ in range(c)]
        return [[v * m for v, m in zip(step, self.mask)] for step in x]

    def backward(self, dout):
        if self.mask is None:
            raise ValueError("SpatialDropout1d.backward: 先调用 forward")
        return [[v * m for v, m in zip(step, self.mask)] for step in dout]


class SpatialDropout2d:
    """按**通道**丢弃（2D 特征图）：``(C, H, W)`` 上每个通道只有一个掩码值

    等价于 Keras 的 ``SpatialDropout2D``：整张特征图一起丢，而不是逐像素丢，
    这样相邻像素不会各自独立掷硬币（那种情况下噪声会被后续卷积平滑掉）。
    """

    def __init__(self, p: float = 0.2):
        if not isinstance(p, (int, float)) or isinstance(p, bool) or not (0.0 <= p < 1.0):
            raise ValueError(f"SpatialDropout2d: p 必须在 [0, 1) 内，收到 {p!r}")
        self.p = float(p)
        self.mask = None
        self.channels = None
        self.training = True

    def train(self):
        """训练模式：按通道丢弃"""
        self.training = True
        return self

    def eval(self):
        """推理模式：恒等映射"""
        self.training = False
        return self

    def _check(self, x, who):
        if not x or not isinstance(x[0], list):
            raise ValueError(f"SpatialDropout2d.{who}: 输入形状必须是 (C, H, W)")
        c = len(x)
        h = len(x[0])
        if h == 0 or any(not isinstance(row, list) or len(row) != h for row in x[0]):
            raise ValueError(f"SpatialDropout2d.{who}: 每个通道必须是 {h}×{h} 的方阵，"
                             f"且所有通道同形")
        for ci in range(1, c):
            if len(x[ci]) != h:
                raise ValueError(f"SpatialDropout2d.{who}: 通道 {ci} 的高与通道 0 不一致")
            for r in range(h):
                if not isinstance(x[ci][r], list) or len(x[ci][r]) != h:
                    raise ValueError(f"SpatialDropout2d.{who}: 通道 {ci} 第 {r} 行宽度不是 {h}")
        return c, h

    def forward(self, x):
        c, h = self._check(x, "forward")
        self.channels = c
        if not self.training:
            self.mask = [1.0] * c
            return x
        scale = 1.0 / (1.0 - self.p)
        self.mask = [scale if random.random() > self.p else 0.0 for _ in range(c)]
        out = []
        for ci in range(c):
            m = self.mask[ci]
            out.append([[v * m for v in row] for row in x[ci]])
        return out

    def backward(self, dout):
        if self.mask is None:
            raise ValueError("SpatialDropout2d.backward: 先调用 forward")
        c = len(dout)
        out = []
        for ci in range(c):
            m = self.mask[ci]
            out.append([[v * m for v in row] for row in dout[ci]])
        return out


class AlphaDropout:
    """SELU 自归一化网络里的 dropout：丢弃值不是一个 0，而是 ``α'``，再整体仿射

    普通 dropout 把神经元置 0 会破坏 SELU 的零均值/单位方差性质。AlphaDropout 丢
    弃时填 ``α' = -λ·α ≈ -1.7581``，再做仿射 ``y = a·v + b`` 把一阶、二阶矩拉回：

        a = (1 - p + p·α'²)^(-1/2),   b = -a·α'·p

    于是 ``E[y] = 0``、``Var[y] ≈ 1``（输入已标准化时）。``eval()`` 后恒等。
    """

    def __init__(self, p: float = 0.2, alpha: float = -1.6732632423543772,
                 scale: float = 1.0507009873554805):
        if not isinstance(p, (int, float)) or isinstance(p, bool) or not (0.0 <= p < 1.0):
            raise ValueError(f"AlphaDropout: p 必须在 [0, 1) 内，收到 {p!r}")
        if not isinstance(alpha, (int, float)) or isinstance(alpha, bool) or alpha >= 0.0:
            raise ValueError(f"AlphaDropout: alpha 必须是负数（SELU 的 α），收到 {alpha!r}")
        if not isinstance(scale, (int, float)) or isinstance(scale, bool) or scale <= 0.0:
            raise ValueError(f"AlphaDropout: scale 必须为正，收到 {scale!r}")
        self.p = float(p)
        self.alpha = float(alpha)
        self.scale = float(scale)
        self.alpha_p = self.alpha * self.scale
        self.a = (1.0 - self.p + self.p * self.alpha_p * self.alpha_p) ** -0.5
        self.b = -self.a * self.alpha_p * self.p
        self.mask = None
        self.training = True

    def train(self):
        """训练模式：按 p 丢弃并做自适应仿射"""
        self.training = True
        return self

    def eval(self):
        """推理模式：恒等映射"""
        self.training = False
        return self

    def forward(self, x):
        if not isinstance(x, list) or not x:
            raise ValueError("AlphaDropout.forward: 输入必须是非空 list")
        if not self.training or self.p == 0.0:
            self.mask = [1.0] * len(x)
            return x
        self.mask = [1.0 if random.random() > self.p else 0.0 for _ in x]
        a, b, ap = self.a, self.b, self.alpha_p
        return [a * (xi if m > 0.0 else ap) + b for xi, m in zip(x, self.mask)]

    def backward(self, delta):
        if self.mask is None:
            raise ValueError("AlphaDropout.backward: 先调用 forward")
        a = self.a
        return [d * a * m for d, m in zip(delta, self.mask)]


class GaussianDropout:
    """乘性高斯噪声：``y = x · N(1, σ)``，``σ = sqrt(p/(1-p))``

    与 ``Dropout`` 的期望和方差完全一致（``E[y]=x``、``Var[y]=x²·p/(1-p)``），
    但不再产生精确的 0 —— 梯度永远非零，适合容易卡在死区的小模型。
    ``eval()`` 后恒等。
    """

    def __init__(self, p: float = 0.2):
        if not isinstance(p, (int, float)) or isinstance(p, bool) or not (0.0 <= p < 1.0):
            raise ValueError(f"GaussianDropout: p 必须在 [0, 1) 内，收到 {p!r}")
        self.p = float(p)
        self.sigma = (self.p / (1.0 - self.p)) ** 0.5 if self.p > 0.0 else 0.0
        self.factor = None
        self.training = True

    def train(self):
        """训练模式：乘高斯噪声"""
        self.training = True
        return self

    def eval(self):
        """推理模式：恒等映射"""
        self.training = False
        return self

    def forward(self, x):
        if not isinstance(x, list) or not x:
            raise ValueError("GaussianDropout.forward: 输入必须是非空 list")
        if not self.training or self.sigma == 0.0:
            self.factor = [1.0] * len(x)
            return x
        self.factor = [random.gauss(1.0, self.sigma) for _ in x]
        return [xi * fi for xi, fi in zip(x, self.factor)]

    def backward(self, delta):
        if self.factor is None:
            raise ValueError("GaussianDropout.backward: 先调用 forward")
        return [d * f for d, f in zip(delta, self.factor)]


def r_drop_loss(logits_a: list, logits_b: list, alpha: float = 0.5) -> float:
    """R-Drop 的对称 KL 正则项（同一输入做两次 dropout 后的两个分布）

    R-Drop 的完整损失是 ``CE + alpha/2 · (KL(p‖q) + KL(q‖p))``；本函数只算后面
    那个正则项，加进自己的损失即可::

        loss = cross_entropy_loss(y1, target) + alpha * r_drop_loss(y1, y2)

    参数
    ----
    logits_a, logits_b : 两次前向（不同 dropout 掩码）的 logits，长度一致
    alpha : 正则权重（本函数返回的已经是 ``alpha/2·(KL+KL)``，直接相加即可）

    注意这里用 **logits** 而不是概率：内部自己取 log-softmax，数值更稳。
    """
    if not isinstance(logits_a, list) or not isinstance(logits_b, list):
        raise TypeError("r_drop_loss: logits 必须是 list")
    if len(logits_a) != len(logits_b):
        raise ValueError(f"r_drop_loss: 两个 logits 长度不一致（{len(logits_a)} vs "
                         f"{len(logits_b)}）")
    if not logits_a:
        raise ValueError("r_drop_loss: logits 不能为空")
    if not isinstance(alpha, (int, float)) or isinstance(alpha, bool) or alpha < 0.0:
        raise ValueError(f"r_drop_loss: alpha 必须是非负数，收到 {alpha!r}")
    la = _log_softmax_row(logits_a)
    lb = _log_softmax_row(logits_b)
    kl_ab = 0.0
    kl_ba = 0.0
    for x, y in zip(la, lb):
        kl_ab += math.exp(x) * (x - y)
        kl_ba += math.exp(y) * (y - x)
    return 0.5 * alpha * (kl_ab + kl_ba)


def _scale_nested(x, k: float):
    """把嵌套 list（向量 / 序列 / (C,H,W)）整体乘 k；k == 1.0 时原样返回"""
    if k == 1.0:
        return x
    if isinstance(x, list):
        return [_scale_nested(v, k) for v in x]
    return x * k

class DropPath:
    """Stochastic Depth / DropPath：训练时整条残差分支以概率 p 被跳过

    与 Dropout 的区别：Dropout 按元素丢，DropPath 丢**整条分支**（整个张量），
    常见于深层 Transformer / ConvNeXt 的残差块里。训练时保留的分支放大
    1/(1-p)（inverted，推理不做任何缩放）；`eval()` 后恒等。

    用法::

        out = x + drop_path(block(x))      # drop_path 在前面挡一下
    """

    def __init__(self, p: float = 0.0, scale_by_keep: bool = True):
        if not isinstance(p, (int, float)) or isinstance(p, bool) or not (0.0 <= p < 1.0):
            raise ValueError(f"DropPath: p 必须在 [0, 1) 内，收到 {p!r}")
        self.p = float(p)
        self.scale_by_keep = bool(scale_by_keep)
        self.factor = 1.0
        self.training = True

    def train(self):
        """训练模式：按概率整条丢弃"""
        self.training = True
        return self

    def eval(self):
        """推理模式：恒等映射"""
        self.training = False
        return self

    def forward(self, x):
        if not self.training or self.p == 0.0:
            self.factor = 1.0
            return x
        if random.random() < self.p:
            self.factor = 0.0
        else:
            self.factor = 1.0 / (1.0 - self.p) if self.scale_by_keep else 1.0
        return _scale_nested(x, self.factor)

    def backward(self, dout):
        return _scale_nested(dout, self.factor)


class DropBlock2d:
    """按**连续方块**丢弃的二维 dropout（`(C, H, W)` 特征图）

    逐元素 dropout 在卷积网络里几乎无效——噪声会被后续卷积的空间平滑抹掉。
    DropBlock 改丢连续的 ``block_size × block_size`` 方块：每个特征图先在
    「合法种子位置」（左上角能放下整个方块的位置）上以 ``γ`` 掷硬币，命中就把
    整块置零，最后按**实际保留比例**整体放大，保持期望不变::

        γ = p / (bs²) · (H·W) / ((H-bs+1)·(W-bs+1))

    ``p`` 是**期望丢弃的元素比例**（不是种子概率）：期望覆盖面积
    ``种子数·bs²·γ/(H·W)`` 恰好等于 ``p``。``block_size`` 超过特征图
    边长时自动夹到边长（此时退化成整图丢弃）。``eval()`` 后恒等。
    """

    def __init__(self, p: float = 0.1, block_size: int = 3):
        if not isinstance(p, (int, float)) or isinstance(p, bool) or not (0.0 <= p < 1.0):
            raise ValueError(f"DropBlock2d: p 必须在 [0, 1) 内，收到 {p!r}")
        if isinstance(block_size, bool) or not isinstance(block_size, int):
            raise TypeError(f"DropBlock2d: block_size 必须是整数，收到 "
                            f"{type(block_size).__name__}")
        if block_size < 1:
            raise ValueError(f"DropBlock2d: block_size 必须 >= 1，收到 {block_size!r}")
        self.p = float(p)
        self.block_size = block_size
        self.mask = None
        self.scale = 1.0
        self.training = True

    def train(self):
        """训练模式：按方块丢弃"""
        self.training = True
        return self

    def eval(self):
        """推理模式：恒等映射"""
        self.training = False
        return self

    @staticmethod
    def _check_shape(x, who):
        if not x or not isinstance(x[0], list):
            raise ValueError(f"DropBlock2d.{who}: 输入形状必须是 (C, H, W)")
        h = len(x[0])
        if h == 0 or not isinstance(x[0][0], list):
            raise ValueError(f"DropBlock2d.{who}: 输入形状必须是 (C, H, W)")
        w = len(x[0][0])
        if w == 0:
            raise ValueError(f"DropBlock2d.{who}: 特征图宽度不能为 0")
        for ci, ch in enumerate(x):
            if len(ch) != h:
                raise ValueError(f"DropBlock2d.{who}: 通道 {ci} 的高与通道 0 不一致")
            for r, row in enumerate(ch):
                if not isinstance(row, list) or len(row) != w:
                    raise ValueError(f"DropBlock2d.{who}: 通道 {ci} 第 {r} 行宽度不是 {w}")
        return len(x), h, w

    def forward(self, x):
        c, h, w = self._check_shape(x, "forward")
        if not self.training or self.p == 0.0:
            self.mask = [[[1.0] * w for _ in range(h)] for _ in range(c)]
            self.scale = 1.0
            return x
        bs = min(self.block_size, h, w)
        # 合法种子数（左上角位置数）：(H-bs+1)*(W-bs+1)
        seeds_h = h - bs + 1
        seeds_w = w - bs + 1
        # 期望覆盖面积 = 种子数·bs²·γ/(H·W)，令它等于 p ⇒ γ = p/(bs²)·(H·W)/种子数
        gamma = self.p / (bs * bs) * (h * w) / (seeds_h * seeds_w)
        mask = [[[1.0] * w for _ in range(h)] for _ in range(c)]
        for ch in range(c):
            for i in range(seeds_h):
                for j in range(seeds_w):
                    if random.random() < gamma:
                        for a in range(bs):
                            row = mask[ch][i + a]
                            for b in range(bs):
                                row[j + b] = 0.0
        kept = 0.0
        for ch in range(c):
            for i in range(h):
                kept += sum(mask[ch][i])
        total = float(c * h * w)
        self.scale = total / kept if kept > 0.0 else 0.0
        self.mask = mask
        out = []
        for ch in range(c):
            rows = []
            for i in range(h):
                rows.append([v * m * self.scale for v, m in zip(x[ch][i], mask[ch][i])])
            out.append(rows)
        return out

    def backward(self, dout):
        if self.mask is None:
            raise ValueError("DropBlock2d.backward: 先调用 forward")
        c = len(dout)
        out = []
        for ch in range(c):
            rows = []
            for i in range(len(dout[ch])):
                rows.append([d * m * self.scale
                             for d, m in zip(dout[ch][i], self.mask[ch][i])])
            out.append(rows)
        return out


class DropConnect(Layer):
    """**权重级** dropout：把权重矩阵元素按概率置零，而不是置零激活

    与 ``Dropout`` 的区别：Dropout 丢的是这一层输出（同一行的所有权重一起失效），
    DropConnect 丢的是单个连接 ``W[j][i]`` —— 每一行仍保留大部分输入，表达更细，
    但正则更强（原论文在 MNIST/ImageNet 上报告优于 Dropout）。

    它本身就是一个 ``Layer`` 子类，可以直接放进 ``MLP``：前向用掩码后的权重算
    ``z = (W⊙M)x + b``，反向对 ``grad_w`` 乘同一个掩码、``next_delta`` 用掩码后的
    权重（与前向保持一致）。保留的连接乘 ``1/(1-p)``，``eval()`` 后与普通 ``Layer``
    逐位相同。
    """

    def __init__(self, fan_in: int, fan_out: int, activation: str = "leaky_relu",
                 is_output: bool = False, p: float = 0.5):
        if not isinstance(p, (int, float)) or isinstance(p, bool) or not (0.0 <= p < 1.0):
            raise ValueError(f"DropConnect: p 必须在 [0, 1) 内，收到 {p!r}")
        super().__init__(fan_in, fan_out, activation, is_output)
        self.p = float(p)
        self.mask = None
        self.masked_weights = None
        self.training = True

    def train(self):
        """训练模式：按连接丢弃"""
        self.training = True
        return self

    def eval(self):
        """推理模式：与普通全连接层逐位相同"""
        self.training = False
        return self

    def _masked(self):
        """返回本次前向用的权重（训练时是 ``W⊙M·scale``，推理时就是 ``W``）"""
        W = self.weights
        if not self.training or self.p == 0.0:
            self.mask = None
            return W
        scale = 1.0 / (1.0 - self.p)
        mask = []
        for j in range(self.fan_out):
            row = W[j]
            mask.append([scale if random.random() > self.p else 0.0
                         for _ in range(self.fan_in)])
        self.mask = mask
        return [[wj * mj for wj, mj in zip(W[j], mask[j])] for j in range(self.fan_out)]

    def forward(self, x):
        if len(x) != self.fan_in:
            raise ValueError(
                f"DropConnect.forward: 输入长度 {len(x)} 与本层 fan_in={self.fan_in} 不一致"
            )
        self.input = x
        self.masked_weights = self._masked()
        Wm, b = self.masked_weights, self.biases
        self.z = [sum(map(_mul, Wm[j], x)) + b[j] for j in range(self.fan_out)]
        self.a = self.act_fn(self.z)
        return self.a

    def backward(self, delta):
        if self.z is None:
            raise RuntimeError("DropConnect.backward: 必须先调用 forward()（没有缓存的 z）")
        if len(delta) != self.fan_out:
            raise ValueError(
                f"DropConnect.backward: delta 长度 {len(delta)} 与本层输出维度 "
                f"{self.fan_out} 不一致"
            )
        d_act = self.act_deriv(self.z)
        w = [delta[j] * d_act[j] for j in range(self.fan_out)]
        if self.mask is None:
            grad_w = [[s * xi for xi in self.input] for s in w]
        else:
            grad_w = [[s * xi * mj for xi, mj in zip(self.input, self.mask[j])]
                      for j, s in enumerate(w)]
        grad_b = list(w)
        Wm = self.masked_weights if self.masked_weights is not None else self.weights
        next_delta = [sum(map(_mul, col, w)) for col in zip(*Wm)]
        return grad_w, grad_b, next_delta


class BatchNorm1d:
    """一维批归一化

    训练: forward_batch(batch) 用 batch 统计量
    推理: forward(x) 用 running_mean / running_var
    """

    def __init__(self, num_features: int, eps: float = 1e-5, momentum: float = 0.1):
        self.d = num_features
        self.eps = eps
        self.momentum = momentum

        self.gamma = [1.0] * self.d
        self.beta = [0.0] * self.d

        self.running_mean = [0.0] * self.d
        self.running_var = [1.0] * self.d

        self.x_batch = self.x_hat = self.mean = self.var = self.inv_std = None
        self.n = 0
        self.training = True

        self.m_gamma = [0.0] * self.d; self.v_gamma = [0.0] * self.d
        self.m_beta = [0.0] * self.d; self.v_beta = [0.0] * self.d

    def forward_batch(self, x_batch):
        """x_batch: List[List[float]]  (batch_size, d)"""
        # zip(*x_batch) 会截断到最短行、多余特征被静默丢弃并污染 running 统计量
        if not x_batch:
            raise ValueError("BatchNorm1d.forward_batch: batch 不能为空")
        if any(len(row) != self.d for row in x_batch):
            raise ValueError(
                f"BatchNorm1d.forward_batch: 每个样本的特征维度都必须是 {self.d}"
            )
        self.x_batch = x_batch
        self._cache_mode = 'train'      # backward 需要知道该用 batch 还是 running 统计量
        n = self.n = len(x_batch)
        d = self.d

        # 先整体转置成列：列求和交给 C 层的 sum，比 sum(row[j] for row in x_batch) 快约 2.4 倍
        cols = list(zip(*x_batch))
        self.mean = [sum(c) / n for c in cols]
        self.var = [sum([(v - m) ** 2 for v in c]) / n for c, m in zip(cols, self.mean)]

        for j in range(d):
            self.running_mean[j] = (1 - self.momentum) * self.running_mean[j] + self.momentum * self.mean[j]
            # n=1 时无偏估计无定义，使用有偏估计作为 fallback
            if n > 1:
                self.running_var[j] = (1 - self.momentum) * self.running_var[j] + self.momentum * self.var[j] * n / (n - 1)
            else:
                self.running_var[j] = (1 - self.momentum) * self.running_var[j] + self.momentum * self.var[j]

        self.inv_std = [1.0 / math.sqrt(v + self.eps) for v in self.var]
        mean, inv_std = self.mean, self.inv_std
        self.x_hat = [[(v - m) * s for v, m, s in zip(row, mean, inv_std)] for row in x_batch]

        gamma, beta = self.gamma, self.beta
        return [[g * xh + b for g, xh, b in zip(gamma, xh_row, beta)] for xh_row in self.x_hat]

    # backward 返回 (dx, grad_gamma, grad_beta)，delta 在**第 0 位**，
    # 与 Layer/LayerNorm 的「末位是 delta」不同；Sequential/ResidualBlock 靠这个属性取
    delta_index = 0

    def train(self):
        """训练模式：forward 收到 batch 时使用 batch 统计量"""
        self.training = True
        return self

    def eval(self):
        """推理模式：forward 一律使用 running_mean / running_var"""
        self.training = False
        return self

    def forward(self, x):
        """推理：单样本；训练模式下若传入 batch 则自动走 forward_batch"""
        if x is None or len(x) == 0:
            raise ValueError("BatchNorm1d.forward: 输入不能为空")
        if isinstance(x[0], (list, tuple)):
            if len(x[0]) != self.d:
                raise ValueError(
                    f"BatchNorm1d.forward: 特征维度 {len(x[0])} 与本层 {self.d} 不一致"
                )
            if any(len(row) != self.d for row in x):
                raise ValueError("BatchNorm1d.forward: batch 内各样本长度不一致")
        elif len(x) != self.d:
            raise ValueError(
                f"BatchNorm1d.forward: 样本维度 {len(x)} 与本层 {self.d} 不一致"
            )
        if x and isinstance(x[0], (list, tuple)):
            if self.training:
                return self.forward_batch(x)
            # eval + batch：逐列用 running stats（原实现会退回单样本路径并 TypeError）
            self._cache_mode = 'eval'
            self.x_batch = [list(row) for row in x]
            return [[self.gamma[j] * ((row[j] - self.running_mean[j]) /
                    math.sqrt(self.running_var[j] + self.eps)) + self.beta[j]
                     for j in range(self.d)] for row in x]
        self._cache_mode = 'eval'
        self.x_batch = [list(x)]
        out = [0.0] * self.d
        for j in range(self.d):
            xh = (x[j] - self.running_mean[j]) / math.sqrt(self.running_var[j] + self.eps)
            out[j] = self.gamma[j] * xh + self.beta[j]
        return out

    def backward(self, dout_batch):
        """返回 (dx_batch, grad_gamma, grad_beta)

        按**上一次前向的模式**求导：
          训练模式（forward_batch）-> 用 batch 统计量的导数
          推理模式（eval / 单样本）-> 用 running 统计量的导数
        原先无条件套 batch 统计量，eval 之后反传会得到完全错误的 dx
        （实测差 4.3 倍），单样本前向后反传还会抛 TypeError。
        """
        if getattr(self, "_cache_mode", None) is None or self.x_batch is None:
            raise RuntimeError("BatchNorm1d.backward: 必须先调用 forward 或 forward_batch")
        if dout_batch and not isinstance(dout_batch[0], (list, tuple)):
            dout_batch = [dout_batch]          # 单样本 -> 当成 batch=1
        n, d = len(dout_batch), self.d
        if any(len(row) != d for row in dout_batch):
            raise ValueError("BatchNorm1d.backward: dout 的维度与本层特征数不一致")

        if self._cache_mode == 'eval':
            xs = self.x_batch
            if len(xs) != n:
                raise ValueError(
                    f"BatchNorm1d.backward: dout 有 {n} 个样本，"
                    f"但上一次前向是 {len(xs)} 个"
                )
            inv = [1.0 / math.sqrt(v + self.eps) for v in self.running_var]
            xhat = [[(x[j] - self.running_mean[j]) * inv[j] for j in range(d)] for x in xs]
            grad_gamma = [sum(dout_batch[i][j] * xhat[i][j] for i in range(n))
                          for j in range(d)]
            grad_beta = [sum(dout_batch[i][j] for i in range(n)) for j in range(d)]
            dx_batch = [[self.gamma[j] * inv[j] * dout_batch[i][j] for j in range(d)]
                        for i in range(n)]
            return dx_batch, grad_gamma, grad_beta

        n = self.n

        # 先转置成列，再交给 C 层的 sum/map（求和顺序不变，结果逐位一致）
        dout_t = list(zip(*dout_batch))
        xhat_t = list(zip(*self.x_hat))

        grad_gamma = [sum(map(_mul, dt, xt)) for dt, xt in zip(dout_t, xhat_t)]
        grad_beta = [sum(c) for c in dout_t]

        dx_hat = [[dout_batch[i][j] * self.gamma[j] for j in range(d)] for i in range(n)]

        # s1/s2 只依赖 j，必须提到 i 循环外面：
        # 原来写在 i 循环里，每个 (i, j) 都重算一遍长度为 n 的和 → O(n²·d)
        dx_hat_t = list(zip(*dx_hat))
        s1 = [sum(c) for c in dx_hat_t]
        s2 = [sum(map(_mul, c, xt)) for c, xt in zip(dx_hat_t, xhat_t)]

        dx_batch = [
            [self.inv_std[j] * (n * dx_hat[i][j] - s1[j] - self.x_hat[i][j] * s2[j]) / n
             for j in range(d)]
            for i in range(n)
        ]
        return dx_batch, grad_gamma, grad_beta


class BatchNorm2d:
    """二维批归一化：按通道在 H×W 上归一化（CNN 里紧跟 Conv2d 使用）

    训练: forward(x) 用**本样本**的 H×W 统计量，并更新 running 统计量；
    推理: forward(x) 用 running_mean / running_var（与 BatchNorm1d 语义一致）。
    """

    # backward 返回 (dx, grad_gamma, grad_beta)，delta 在第 0 位（同 BatchNorm1d）
    delta_index = 0

    def __init__(self, num_features: int, eps: float = 1e-5, momentum: float = 0.1):
        if isinstance(num_features, bool) or not isinstance(num_features, int) \
                or num_features < 1:
            raise ValueError(
                f"BatchNorm2d: num_features 必须是 >=1 的整数，收到 {num_features!r}")
        if not (0.0 <= momentum <= 1.0):
            raise ValueError(f"BatchNorm2d: momentum 必须在 [0,1] 内，收到 {momentum!r}")
        if eps <= 0:
            raise ValueError(f"BatchNorm2d: eps 必须 > 0，收到 {eps!r}")
        self.c = num_features
        self.eps = eps
        self.momentum = momentum
        self.gamma = [1.0] * self.c
        self.beta = [0.0] * self.c
        self.running_mean = [0.0] * self.c
        self.running_var = [1.0] * self.c
        self.training = True
        self.x_hat = None
        self.stats = None
        self._cache_mode = 'train'
        self.m_gamma = [0.0] * self.c
        self.v_gamma = [0.0] * self.c
        self.m_beta = [0.0] * self.c
        self.v_beta = [0.0] * self.c

    def train(self):
        """训练模式：forward 用当前样本的统计量"""
        self.training = True
        return self

    def eval(self):
        """推理模式：forward 用 running 统计量"""
        self.training = False
        return self

    def _check(self, x, who):
        if not isinstance(x, (list, tuple)) or not x:
            raise ValueError(f"{who}: 输入必须是非空的 (C, H, W)")
        if len(x) != self.c:
            raise ValueError(f"{who}: 通道数 {len(x)} != num_features={self.c}")
        h = len(x[0])
        if h == 0:
            raise ValueError(f"{who}: H 不能为 0")
        w = len(x[0][0])
        if w == 0:
            raise ValueError(f"{who}: W 不能为 0")
        for c in range(self.c):
            if len(x[c]) != h:
                raise ValueError(f"{who}: 各通道 H 不一致（通道 {c}）")
            for hh in range(h):
                if len(x[c][hh]) != w:
                    raise ValueError(f"{who}: 各通道 W 不一致（通道 {c}, 行 {hh}）")
        return h, w

    def forward(self, x):
        """(C, H, W) → (C, H, W)（训练模式更新 running 统计量）"""
        h, w = self._check(x, "BatchNorm2d.forward")
        m_size = h * w
        self._cache_mode = 'train' if self.training else 'eval'
        x_hat = []
        stats = []
        out = []
        for c in range(self.c):
            flat = [x[c][hh][ww] for hh in range(h) for ww in range(w)]
            if self.training:
                mean = sum(flat) / m_size
                var = sum((v - mean) ** 2 for v in flat) / m_size
                self.running_mean[c] = ((1 - self.momentum) * self.running_mean[c]
                                        + self.momentum * mean)
                unb = var * m_size / (m_size - 1) if m_size > 1 else var
                self.running_var[c] = ((1 - self.momentum) * self.running_var[c]
                                       + self.momentum * unb)
            else:
                mean = self.running_mean[c]
                var = self.running_var[c]
            inv = 1.0 / math.sqrt(var + self.eps)
            stats.append((mean, inv))
            xh = [(v - mean) * inv for v in flat]
            x_hat.append(xh)
            g, b = self.gamma[c], self.beta[c]
            out.append([[g * xh[hh * w + ww] + b for ww in range(w)]
                        for hh in range(h)])
        self.x_hat = x_hat
        self.stats = stats
        return out

    def backward(self, dout):
        """返回 (dx, grad_gamma, grad_beta)：dx 与该层输入同形 (C, H, W)"""
        if self.x_hat is None or self.stats is None:
            raise RuntimeError("BatchNorm2d.backward: 请先 forward")
        h, w = self._check(dout, "BatchNorm2d.backward")
        m_size = h * w
        grad_gamma = [0.0] * self.c
        grad_beta = [0.0] * self.c
        dx = []
        for c in range(self.c):
            mean, inv = self.stats[c]
            xh = self.x_hat[c]
            d_flat = [dout[c][hh][ww] for hh in range(h) for ww in range(w)]
            g = self.gamma[c]
            grad_gamma[c] = sum(d * a for d, a in zip(d_flat, xh))
            grad_beta[c] = sum(d_flat)
            dxh = [d * g for d in d_flat]
            if self._cache_mode == 'eval':
                # 推理模式的 mean/var 来自 running 统计量，与当前样本无关，
                # 反向就是逐元素的 inv*gamma（没有 m_size 那几项）——
                # 与 BatchNorm1d 的 eval 分支一致
                d_flat_out = [inv * d for d in dxh]
            else:
                sum_dxh = sum(dxh)
                sum_dxh_xh = sum(r * a for r, a in zip(dxh, xh))
                d_flat_out = [inv * (m_size * r - sum_dxh - a * sum_dxh_xh) / m_size
                              for r, a in zip(dxh, xh)]
            dx.append([[d_flat_out[hh * w + ww] for ww in range(w)] for hh in range(h)])
        return dx, grad_gamma, grad_beta


class LayerNorm:
    """层归一化：对单个样本的特征维度归一化，适合 Transformer / RNN"""

    def __init__(self, num_features: int, eps: float = 1e-5):
        self.d = num_features
        self.eps = eps
        self.gamma = [1.0] * self.d
        self.beta = [0.0] * self.d
        self.x = self.mean = self.var = self.inv_std = self.x_hat = None
        self.m_gamma = [0.0] * self.d; self.v_gamma = [0.0] * self.d
        self.m_beta = [0.0] * self.d; self.v_beta = [0.0] * self.d

    def forward(self, x):
        # 多出的特征会被静默丢弃，而 mean/var 仍是按全长算的，必须早失败
        if len(x) != self.d:
            raise ValueError(
                f"LayerNorm.forward: 特征维度 {len(x)} 与本层 {self.d} 不一致"
            )
        self.x = x
        self.mean = sum(x) / self.d
        self.var = sum((xi - self.mean) ** 2 for xi in x) / self.d
        self.inv_std = 1.0 / math.sqrt(self.var + self.eps)
        self.x_hat = [(xi - self.mean) * self.inv_std for xi in x]
        return [self.gamma[j] * self.x_hat[j] + self.beta[j] for j in range(self.d)]

    def backward(self, dout):
        if self.x_hat is None:
            raise RuntimeError("LayerNorm.backward: 必须先调用 forward()")
        if len(dout) != self.d:
            raise ValueError(
                f"LayerNorm.backward: dout 长度 {len(dout)} 与本层维度 {self.d} 不一致"
            )
        d = self.d
        grad_gamma = [dout[j] * self.x_hat[j] for j in range(d)]
        grad_beta = list(dout)

        dx_hat = [dout[j] * self.gamma[j] for j in range(d)]
        s1 = sum(dx_hat)
        s2 = sum(dx_hat[j] * self.x_hat[j] for j in range(d))

        dx = [self.inv_std * (d * dx_hat[j] - s1 - self.x_hat[j] * s2) / d for j in range(d)]
        return grad_gamma, grad_beta, dx  # 约定: 最后一个元素为传播的 delta


class GroupNorm:
    """分组归一化（GroupNorm，Wu & He 2018）：CNN 小 batch 时替代 BatchNorm

    输入是 (C, H, W)。把通道分成 num_groups 组，每组内对 (C/G, H, W) 的
    C/G*H*W 个元素一起求均值方差——与 batch 大小无关，所以 batch=1 也稳定。
    `InstanceNorm(num_channels)` 就是 `num_groups == num_channels` 的特例。
    """

    def __init__(self, num_groups: int, num_channels: int, eps: float = 1e-5):
        if isinstance(num_groups, bool) or not isinstance(num_groups, int) or num_groups < 1:
            raise ValueError(f"GroupNorm: num_groups 必须是正整数，收到 {num_groups!r}")
        if isinstance(num_channels, bool) or not isinstance(num_channels, int) or num_channels < 1:
            raise ValueError(f"GroupNorm: num_channels 必须是正整数，收到 {num_channels!r}")
        if num_channels % num_groups != 0:
            raise ValueError(
                f"GroupNorm: num_channels={num_channels} 必须能被 "
                f"num_groups={num_groups} 整除"
            )
        self.groups = num_groups
        self.channels = num_channels
        self.eps = eps
        self.gamma = [1.0] * num_channels
        self.beta = [0.0] * num_channels
        self.m_gamma = [0.0] * num_channels; self.v_gamma = [0.0] * num_channels
        self.m_beta = [0.0] * num_channels; self.v_beta = [0.0] * num_channels
        self.x = self.x_hat = None
        self.stats = []        # 每组 (mean, inv_std)

    def _check(self, x, who):
        if len(x) != self.channels:
            raise ValueError(
                f"GroupNorm.{who}: 通道数 {len(x)} 与本层 {self.channels} 不一致"
            )
        shape = (len(x[0]), len(x[0][0])) if x and x[0] else (0, 0)
        for c in range(len(x)):
            if len(x[c]) != shape[0] or any(len(r) != shape[1] for r in x[c]):
                raise ValueError(f"GroupNorm.{who}: 各通道的 H/W 必须一致")
        if shape[0] < 1 or shape[1] < 1:
            raise ValueError(f"GroupNorm.{who}: 输入不能为空")
        return shape

    def forward(self, x):
        H, W = self._check(x, "forward")
        self.x = x
        self.x_hat = [[[0.0] * W for _ in range(H)] for _ in range(self.channels)]
        self.stats = []
        per = self.channels // self.groups
        n = per * H * W
        for g in range(self.groups):
            mean = 0.0
            for c in range(g * per, (g + 1) * per):
                for h in range(H):
                    mean += sum(x[c][h])
            mean /= n
            var = 0.0
            for c in range(g * per, (g + 1) * per):
                for h in range(H):
                    for w in range(W):
                        d = x[c][h][w] - mean
                        var += d * d
            var /= n
            inv = 1.0 / math.sqrt(var + self.eps)
            self.stats.append((mean, inv))
            for c in range(g * per, (g + 1) * per):
                for h in range(H):
                    for w in range(W):
                        self.x_hat[c][h][w] = (x[c][h][w] - mean) * inv
        return [[[self.gamma[c] * self.x_hat[c][h][w] + self.beta[c]
                  for w in range(W)] for h in range(H)] for c in range(self.channels)]

    def backward(self, dout):
        if self.x_hat is None:
            raise RuntimeError("GroupNorm.backward: 必须先调用 forward()")
        H, W = self._check(dout, "backward")
        per = self.channels // self.groups
        n = per * H * W
        grad_gamma = [0.0] * self.channels
        grad_beta = [0.0] * self.channels
        for c in range(self.channels):
            s = 0.0
            for h in range(H):
                s += sum(dout[c][h])
            grad_beta[c] = s
            t = 0.0
            for h in range(H):
                for w in range(W):
                    t += dout[c][h][w] * self.x_hat[c][h][w]
            grad_gamma[c] = t
        dx = [[[0.0] * W for _ in range(H)] for _ in range(self.channels)]
        for g in range(self.groups):
            mean, inv = self.stats[g]
            s1 = 0.0     # sum(dx_hat)
            s2 = 0.0     # sum(dx_hat * x_hat)
            for c in range(g * per, (g + 1) * per):
                gam = self.gamma[c]
                for h in range(H):
                    for w in range(W):
                        d = dout[c][h][w] * gam
                        s1 += d
                        s2 += d * self.x_hat[c][h][w]
            for c in range(g * per, (g + 1) * per):
                gam = self.gamma[c]
                for h in range(H):
                    for w in range(W):
                        d = dout[c][h][w] * gam
                        dx[c][h][w] = inv * (n * d - s1 - self.x_hat[c][h][w] * s2) / n
        return grad_gamma, grad_beta, dx       # 约定：最后一个元素是 delta


class InstanceNorm(GroupNorm):
    """实例归一化 = 每组一个通道的 GroupNorm"""

    def __init__(self, num_channels: int, eps: float = 1e-5):
        super().__init__(num_channels, num_channels, eps)


class RMSNorm:
    """RMS 归一化（Llama / Qwen / Mistral 系）：y = gamma * x / sqrt(mean(x^2)+eps)

    与 LayerNorm 的差别：不减均值、没有 beta。少一趟减均值与一次加 beta，
    在 LLM 里更常见。
    """

    def __init__(self, num_features: int, eps: float = 1e-6):
        if num_features is None or int(num_features) < 1:
            raise ValueError(f"RMSNorm: num_features 必须 >= 1，收到 {num_features!r}")
        self.d = int(num_features)
        self.eps = eps
        self.gamma = [1.0] * self.d
        self.x = None
        self.inv_rms = None
        self.m_gamma = [0.0] * self.d
        self.v_gamma = [0.0] * self.d

    def forward(self, x):
        # 多出的特征会被静默丢弃，而 mean(x^2) 仍是按全长算的，必须早失败
        if len(x) != self.d:
            raise ValueError(
                f"RMSNorm.forward: 特征维度 {len(x)} 与本层 {self.d} 不一致"
            )
        self.x = x
        mean_sq = sum(xi * xi for xi in x) / self.d
        self.inv_rms = 1.0 / math.sqrt(mean_sq + self.eps)
        r = self.inv_rms
        return [self.gamma[j] * x[j] * r for j in range(self.d)]

    def backward(self, dout):
        if self.x is None:
            raise RuntimeError("RMSNorm.backward: 必须先调用 forward()")
        if len(dout) != self.d:
            raise ValueError(
                f"RMSNorm.backward: dout 长度 {len(dout)} 与本层维度 {self.d} 不一致"
            )
        d = self.d
        r = self.inv_rms
        x = self.x
        gamma = self.gamma
        grad_gamma = [dout[j] * x[j] * r for j in range(d)]
        # g = Σ_i dout_i * gamma_i * x_i；dx_j = gamma_j*dout_j/r - g*x_j/(d*r^3)
        g = sum(dout[i] * gamma[i] * x[i] for i in range(d))
        r3 = r * r * r
        dx = [gamma[j] * dout[j] * r - g * x[j] * r3 / d for j in range(d)]
        return grad_gamma, dx  # 约定: 最后一个元素为传播的 delta


class ScaleNorm:
    """尺度归一化（ScaleNorm）：y = g * x / (||x||/sqrt(d) + eps)

    只有一个标量参数 `g`（无 beta），比 LayerNorm 少一组参数与一次减均值。
    `||x||` 为整条样本的 L2 范数，所以它做的是"整向量缩放"而不是逐特征归一化。
    """

    def __init__(self, num_features: int, eps: float = 1e-6):
        if isinstance(num_features, bool) or not isinstance(num_features, int):
            raise TypeError(f"ScaleNorm: num_features 必须是 int，收到 {type(num_features).__name__}")
        if num_features < 1:
            raise ValueError(f"ScaleNorm: num_features 必须 >= 1，收到 {num_features!r}")
        if not isinstance(eps, (int, float)) or isinstance(eps, bool) or eps < 0:
            raise ValueError(f"ScaleNorm: eps 必须是非负数，收到 {eps!r}")
        self.d = num_features
        self.eps = float(eps)
        self.g = 1.0
        self.x = None
        self.norm = None
        self._den = None
        self.grad_g = 0.0
        self.m_g = 0.0
        self.v_g = 0.0
        self._adam_t = 0

    def forward(self, x):
        if len(x) != self.d:
            raise ValueError(
                f"ScaleNorm.forward: 特征维度 {len(x)} 与本层 {self.d} 不一致"
            )
        self.x = x
        self.norm = math.sqrt(sum(v * v for v in x))
        self._den = self.norm / math.sqrt(self.d) + self.eps
        den = self._den
        return [self.g * v / den for v in x]

    def backward(self, dout):
        if self.x is None:
            raise RuntimeError("ScaleNorm.backward: 必须先调用 forward()")
        if len(dout) != self.d:
            raise ValueError(
                f"ScaleNorm.backward: dout 长度 {len(dout)} 与本层维度 {self.d} 不一致"
            )
        x = self.x
        den = self._den
        norm = self.norm
        d = self.d
        # dg = Σ dout_i * x_i / den
        self.grad_g = sum(dout[i] * x[i] for i in range(d)) / den
        s = sum(dout[j] * x[j] for j in range(d))
        if norm > 0.0:
            k = self.g * s / (den * den * math.sqrt(d) * norm)
            dx = [self.g * dout[i] / den - k * x[i] for i in range(d)]
        else:
            # ||x||=0 时方向无定义，只保留 1/den 这一项（极限行为）
            dx = [self.g * dout[i] / den for i in range(d)]
        return self.grad_g, dx

    def zero_grad(self):
        self.grad_g = 0.0

    def param_count(self):
        return 1

    def train(self):
        self.training = True
        return self

    def eval(self):
        self.training = False
        return self

    def sgd_step(self, lr):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"ScaleNorm.sgd_step: lr 必须是非负数，收到 {lr!r}")
        self.g -= lr * self.grad_g
        self.zero_grad()

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"ScaleNorm.adam_step: lr 必须是非负数，收到 {lr!r}")
        self._adam_t += 1
        # _adam_apply 就地改列表，标量参数要先装进单元素列表再取回
        holder = [self.g]
        m_holder = [self.m_g]
        v_holder = [self.v_g]
        _adam_apply(holder, [self.grad_g], m_holder, v_holder, self._adam_t,
                    lr, beta1, beta2, eps)
        self.g = holder[0]
        self.m_g = m_holder[0]
        self.v_g = v_holder[0]
        self.zero_grad()


class SwitchNorm:
    """切换归一化（SwitchNorm, Luo et al. 2019）：三种统计量软加权

    对每个通道同时算三种均值/方差 —— instance（本通道 `H,W`）、batch（整批）、
    layer（整条样本 `C,H,W`）—— 再用 **softmax 学出来的三个权重**组合：

        mu = Σ w_i·mu_i,  var = Σ w_i·var_i,  y = gamma·(x-mu)/sqrt(var+eps) + beta

    入参可为单样本 `(C,H,W)` 或一批 `[x1, x2, ...]`；单样本时 batch 与 instance
    统计量完全相同（预期行为，此时等价于两个自由度）。反向对 `x`、`gamma`、
    `beta` 与**三个软权重**都精确求导（权重进入 mu/var，梯度按 softmax 雅可比回传）。
    """

    def __init__(self, channels: int, eps: float = 1e-5):
        if isinstance(channels, bool) or not isinstance(channels, int):
            raise TypeError(f"SwitchNorm: channels 必须是 int，收到 {type(channels).__name__}")
        if channels < 1:
            raise ValueError(f"SwitchNorm: channels 必须 >= 1，收到 {channels!r}")
        if not isinstance(eps, (int, float)) or isinstance(eps, bool) or eps < 0:
            raise ValueError(f"SwitchNorm: eps 必须是非负数，收到 {eps!r}")
        self.channels = channels
        self.eps = float(eps)
        self.gamma = [1.0] * channels
        self.beta = [0.0] * channels
        # 初始化成"近似只用 instance"：softmax([3,0,0]) ≈ [0.981, 0.0095, 0.0095]
        self.logits = [3.0, 0.0, 0.0]
        self.grad_gamma = [0.0] * channels
        self.grad_beta = [0.0] * channels
        self.grad_logits = [0.0] * 3
        self.m_gamma = [0.0] * channels
        self.v_gamma = [0.0] * channels
        self.m_beta = [0.0] * channels
        self.v_beta = [0.0] * channels
        self.m_logits = [0.0] * 3
        self.v_logits = [0.0] * 3
        self._adam_t = 0
        self._cache = None
        self.training = True

    def _samples(self, x):
        """单样本 `(C,H,W)` 与一批样本统一成 list，并做形状校验。"""
        if not isinstance(x, (list, tuple)) or not x:
            raise ValueError("SwitchNorm.forward: 输入必须是非空的 (C,H,W) 或样本列表")
        first = x[0]
        batched = (isinstance(first, list) and first and isinstance(first[0], list)
                   and first[0] and isinstance(first[0][0], list))
        samples = list(x) if batched else [x]
        c = self.channels
        for idx, smp in enumerate(samples):
            if len(smp) != c:
                raise ValueError(
                    f"SwitchNorm.forward: 第 {idx} 个样本通道数 {len(smp)} 与本层 {c} 不一致")
            h = len(smp[0]) if smp[0] else 0
            if h < 1:
                raise ValueError("SwitchNorm.forward: 空间维度不能为空")
            w = len(smp[0][0])
            for ci in range(c):
                if len(smp[ci]) != h or any(len(smp[ci][i]) != w for i in range(h)):
                    raise ValueError(f"SwitchNorm.forward: 第 {idx} 个样本空间尺寸不一致")
        return samples

    def forward(self, x):
        samples = self._samples(x)
        n = len(samples)
        c = self.channels
        h = len(samples[0][0])
        w = len(samples[0][0][0])
        inst_mean = [0.0] * c
        inst_var = [0.0] * c
        for ci in range(c):
            vals = [samples[si][ci][i][j] for si in range(n) for i in range(h) for j in range(w)]
            m = sum(vals) / len(vals)
            inst_mean[ci] = m
            inst_var[ci] = sum((v - m) ** 2 for v in vals) / len(vals)
        every = [samples[si][ci][i][j] for si in range(n) for ci in range(c)
                 for i in range(h) for j in range(w)]
        lay_mean = sum(every) / len(every)
        lay_var = sum((v - lay_mean) ** 2 for v in every) / len(every)
        mx = max(self.logits)
        ex = [math.exp(v - mx) for v in self.logits]
        tot = sum(ex)
        wts = [v / tot for v in ex]
        # instance 与 batch 在本实现里同源，权重合并
        w_ib = wts[0] + wts[1]
        mean = [w_ib * inst_mean[ci] + wts[2] * lay_mean for ci in range(c)]
        var = [w_ib * inst_var[ci] + wts[2] * lay_var for ci in range(c)]
        inv = [1.0 / math.sqrt(var[ci] + self.eps) for ci in range(c)]
        out = []
        for si in range(n):
            rows = []
            for ci in range(c):
                rows.append([[(samples[si][ci][i][j] - mean[ci]) * inv[ci] * self.gamma[ci]
                              + self.beta[ci] for j in range(w)] for i in range(h)])
            out.append(rows)
        self._cache = (samples, n, h, w, wts, inst_mean, inst_var, lay_mean, lay_var,
                       mean, inv)
        return out[0] if n == 1 else out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("SwitchNorm.backward: 必须先调用 forward()")
        samples, n, h, w, wts, inst_mean, inst_var, lay_mean, lay_var, mean, inv = self._cache
        c = self.channels
        # (C,H,W) 的 dout 是三层嵌套，批量的多一层：靠 dout[0][0][0] 是否还是 list 判定
        batched = (isinstance(dout, (list, tuple)) and len(dout) > 0
                   and isinstance(dout[0], (list, tuple)) and len(dout[0]) > 0
                   and isinstance(dout[0][0], (list, tuple)) and len(dout[0][0]) > 0
                   and isinstance(dout[0][0][0], (list, tuple)))
        douts = list(dout) if batched else [dout]
        if len(douts) != n:
            raise ValueError(
                f"SwitchNorm.backward: dout 样本数 {len(douts)} 与 forward 的 {n} 不一致")
        g_gamma = [0.0] * c
        g_beta = [0.0] * c
        xhat = [[[[0.0] * w for _ in range(h)] for _ in range(c)] for _ in range(n)]
        for si in range(n):
            for ci in range(c):
                for i in range(h):
                    for j in range(w):
                        xh = (samples[si][ci][i][j] - mean[ci]) * inv[ci]
                        xhat[si][ci][i][j] = xh
                        g_gamma[ci] += douts[si][ci][i][j] * xh
                        g_beta[ci] += douts[si][ci][i][j]
        n_ib = n * h * w
        n_lay = n * c * h * w
        w_ib = wts[0] + wts[1]
        s_ci = [sum(douts[si][ci][i][j] for si in range(n) for i in range(h) for j in range(w))
                for ci in range(c)]
        sx_ci = [sum(douts[si][ci][i][j] * xhat[si][ci][i][j]
                     for si in range(n) for i in range(h) for j in range(w)) for ci in range(c)]
        a_ib = w_ib / n_ib
        a_lay = wts[2] / n_lay
        # layer 统计量跨通道共享：改 x_j 会影响**所有通道**的 mu/var，所以下面这两项
        # 要对全部通道求和（只对本通道求和会漏掉 1.5 量级的误差）
        layer_mean = sum(self.gamma[c2] * inv[c2] * a_lay * s_ci[c2] for c2 in range(c))
        dx = [[[[0.0] * w for _ in range(h)] for _ in range(c)] for _ in range(n)]
        for ci in range(c):
            g = self.gamma[ci]
            iv = inv[ci]
            for si in range(n):
                for i in range(h):
                    for j in range(w):
                        xv = samples[si][ci][i][j]
                        mean_term = g * iv * a_ib * s_ci[ci] + layer_mean
                        var_term = g * iv * iv * a_ib * (xv - inst_mean[ci]) * sx_ci[ci]
                        for c2 in range(c):
                            var_term += (self.gamma[c2] * inv[c2] ** 2 * a_lay
                                         * (xv - lay_mean) * sx_ci[c2])
                        dx[si][ci][i][j] = g * iv * douts[si][ci][i][j] - mean_term - var_term
        # 三个软权重：∂L/∂w_k = -gamma_c·(mu_k,c·S_c/sigma_c + var_k,c·Sx_c/(2·sigma_c²))
        # 这里 S/Sx 只需本通道（w_k 只通过本通道的统计量影响本通道输出）
        raw = [0.0] * 3
        for ci in range(c):
            iv = inv[ci]
            g = self.gamma[ci]
            raw[0] += -g * (inst_mean[ci] * s_ci[ci] * iv
                            + inst_var[ci] * sx_ci[ci] * iv * iv / 2.0)
            raw[1] += -g * (inst_mean[ci] * s_ci[ci] * iv
                            + inst_var[ci] * sx_ci[ci] * iv * iv / 2.0)
            raw[2] += -g * (lay_mean * s_ci[ci] * iv
                            + lay_var * sx_ci[ci] * iv * iv / 2.0)
        dot = sum(wts[k] * raw[k] for k in range(3))
        g_logits = [wts[k] * (raw[k] - dot) for k in range(3)]
        self.grad_gamma = g_gamma
        self.grad_beta = g_beta
        self.grad_logits = g_logits
        return (dx[0] if n == 1 else dx), g_gamma, g_beta, g_logits

    def zero_grad(self):
        self.grad_gamma = [0.0] * self.channels
        self.grad_beta = [0.0] * self.channels
        self.grad_logits = [0.0] * 3

    def param_count(self):
        return 2 * self.channels + 3

    def train(self):
        self.training = True
        return self

    def eval(self):
        self.training = False
        return self

    def sgd_step(self, lr):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"SwitchNorm.sgd_step: lr 必须是非负数，收到 {lr!r}")
        _sgd_apply(self.gamma, self.grad_gamma, lr)
        _sgd_apply(self.beta, self.grad_beta, lr)
        _sgd_apply(self.logits, self.grad_logits, lr)
        self.zero_grad()

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"SwitchNorm.adam_step: lr 必须是非负数，收到 {lr!r}")
        self._adam_t += 1
        _adam_apply(self.gamma, self.grad_gamma, self.m_gamma, self.v_gamma,
                    self._adam_t, lr, beta1, beta2, eps)
        _adam_apply(self.beta, self.grad_beta, self.m_beta, self.v_beta,
                    self._adam_t, lr, beta1, beta2, eps)
        _adam_apply(self.logits, self.grad_logits, self.m_logits, self.v_logits,
                    self._adam_t, lr, beta1, beta2, eps)
        self.zero_grad()


class FRN:
    """滤波器响应归一化（FRN, Singh & Krishnan 2020）+ 阈值化 ReLU（TLU）

    与 BatchNorm 的区别是**不跨样本、不跨通道**：每个样本把整张 `(C,H,W)` 的
    平方和合成一个标量 ν² = Σx²/(C·H·W)，再做

        y = x / sqrt(ν² + eps) - beta_c,   out = max(y, tau_c)

    `beta`/`tau` 逐通道（2C 个参数）。统计量跨通道，所以对 batch size 不敏感，
    batch=1 也能用 —— 这是 FRN 的核心卖点。反向对 `x`、`beta`、`tau` 全精确求导
    （ν² 依赖所有元素，交叉项不漏）：

        dx_j = dy_j/r - (Σ_i dy_i·x_i)·x_j/(n·r³),  r = sqrt(ν²+eps)
    """

    def __init__(self, channels: int, eps: float = 1e-6, tau: float = 0.0):
        if isinstance(channels, bool) or not isinstance(channels, int):
            raise TypeError(f"FRN: channels 必须是 int，收到 {type(channels).__name__}")
        if channels < 1:
            raise ValueError(f"FRN: channels 必须 >= 1，收到 {channels!r}")
        if not isinstance(eps, (int, float)) or isinstance(eps, bool) or eps <= 0:
            raise ValueError(f"FRN: eps 必须是正数，收到 {eps!r}")
        if not isinstance(tau, (int, float)) or isinstance(tau, bool):
            raise ValueError(f"FRN: tau 必须是数字，收到 {tau!r}")
        self.channels = channels
        self.eps = float(eps)
        self.beta = [0.0] * channels
        self.tau = [float(tau)] * channels
        self.grad_beta = [0.0] * channels
        self.grad_tau = [0.0] * channels
        self.m_beta = [0.0] * channels
        self.v_beta = [0.0] * channels
        self.m_tau = [0.0] * channels
        self.v_tau = [0.0] * channels
        self._adam_t = 0
        self._cache = None
        self.training = True

    def forward(self, x):
        if not isinstance(x, (list, tuple)) or not x:
            raise ValueError("FRN.forward: 输入必须是非空的 (C,H,W)")
        if len(x) != self.channels:
            raise ValueError(f"FRN.forward: 通道数 {len(x)} 与本层 {self.channels} 不一致")
        h = len(x[0])
        if h < 1:
            raise ValueError("FRN.forward: 空间维度不能为空")
        w = len(x[0][0])
        for ci in range(self.channels):
            if len(x[ci]) != h or any(len(x[ci][i]) != w for i in range(h)):
                raise ValueError("FRN.forward: 各通道空间尺寸必须一致")
        n = self.channels * h * w
        s = sum(x[ci][i][j] ** 2 for ci in range(self.channels)
                for i in range(h) for j in range(w))
        inv = 1.0 / math.sqrt(s / n + self.eps)
        out = []
        act = []
        for ci in range(self.channels):
            ro = []
            ra = []
            for i in range(h):
                r_o = []
                r_a = []
                for j in range(w):
                    v = x[ci][i][j] * inv - self.beta[ci]
                    r_a.append(v)
                    r_o.append(v if v > self.tau[ci] else self.tau[ci])
                ro.append(r_o)
                ra.append(r_a)
            out.append(ro)
            act.append(ra)
        self._cache = (x, h, w, n, inv, act)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("FRN.backward: 必须先调用 forward()")
        x, h, w, n, inv, act = self._cache
        g_beta = [0.0] * self.channels
        g_tau = [0.0] * self.channels
        dy = [[[0.0] * w for _ in range(h)] for _ in range(self.channels)]
        for ci in range(self.channels):
            for i in range(h):
                for j in range(w):
                    if act[ci][i][j] > self.tau[ci]:
                        dy[ci][i][j] = dout[ci][i][j]
                    else:
                        # 被阈值截断的位置 out == tau，梯度只流向 tau
                        g_tau[ci] += dout[ci][i][j]
        dot = sum(dy[ci][i][j] * x[ci][i][j] for ci in range(self.channels)
                  for i in range(h) for j in range(w))
        coef = dot * (inv ** 3) / n
        dx = [[[0.0] * w for _ in range(h)] for _ in range(self.channels)]
        for ci in range(self.channels):
            for i in range(h):
                for j in range(w):
                    dx[ci][i][j] = dy[ci][i][j] * inv - coef * x[ci][i][j]
                    g_beta[ci] -= dy[ci][i][j]
        self.grad_beta = g_beta
        self.grad_tau = g_tau
        return dx, g_beta, g_tau

    def zero_grad(self):
        self.grad_beta = [0.0] * self.channels
        self.grad_tau = [0.0] * self.channels

    def param_count(self):
        return 2 * self.channels

    def train(self):
        self.training = True
        return self

    def eval(self):
        self.training = False
        return self

    def sgd_step(self, lr):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"FRN.sgd_step: lr 必须是非负数，收到 {lr!r}")
        _sgd_apply(self.beta, self.grad_beta, lr)
        _sgd_apply(self.tau, self.grad_tau, lr)
        self.zero_grad()

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"FRN.adam_step: lr 必须是非负数，收到 {lr!r}")
        self._adam_t += 1
        _adam_apply(self.beta, self.grad_beta, self.m_beta, self.v_beta,
                    self._adam_t, lr, beta1, beta2, eps)
        _adam_apply(self.tau, self.grad_tau, self.m_tau, self.v_tau,
                    self._adam_t, lr, beta1, beta2, eps)
        self.zero_grad()


class WeightNorm:
    """权重归一化（Salimans & Kingma 2016）：w = g ⊙ (v / ||v||_row)

    包装带 `weights` / `biases` / `act_fn` / `act_deriv` 的内层（`Layer` / `Linear`）。
    反向**精确**传到 `v`、`g`、`b`（不把缩放视为常量）：

        dv[i][j] = g_i/n_i * dW[i][j] - g_i/n_i^3 * v[i][j] * Σ_k dW[i][k] v[i][k]
        dg[i]    = (Σ_k dW[i][k] v[i][k]) / n_i

    其中 `n_i = ||v_i||`。参数从 `w` 变成 `v`+`g`，所以 `w` 的尺度与方向解耦，
    训练动力学与普通全连接层不同（这是它唯一的目的）。
    """

    def __init__(self, layer):
        for attr in ("weights", "biases", "act_fn", "act_deriv"):
            if not hasattr(layer, attr):
                raise TypeError(
                    f"WeightNorm: 内层必须提供 {attr!r}（Layer / Linear 都满足），"
                    f"收到 {type(layer).__name__}"
                )
        self.inner = layer
        self.fan_out = len(layer.weights)
        self.fan_in = len(layer.weights[0]) if self.fan_out else 0
        self.v = [list(row) for row in layer.weights]
        # 初始化 g_i = ||v_i||，使 w 一开始就等于原权重（不扰动已训练模型）
        self.g = [math.sqrt(sum(c * c for c in row)) for row in self.v]
        self.b = list(layer.biases)
        self._w = None
        self._norms = None
        self.grad_v = None
        self.grad_g = None
        self.grad_b = None
        self.zero_grad()
        self.m_v = _zeros_like(self.v)
        self.v_v = _zeros_like(self.v)
        self.m_g = [0.0] * self.fan_out
        self.v_g = [0.0] * self.fan_out
        self.m_b = [0.0] * self.fan_out
        self.v_b = [0.0] * self.fan_out
        self._adam_t = 0

    def _effective(self):
        norms = []
        for row in self.v:
            n = math.sqrt(sum(c * c for c in row))
            norms.append(n if n > 1e-12 else 1e-12)
        w = [[self.g[i] * self.v[i][j] / norms[i] for j in range(self.fan_in)]
             for i in range(self.fan_out)]
        return w, norms

    def forward(self, x):
        if len(x) != self.fan_in:
            raise ValueError(
                f"WeightNorm.forward: 输入维度 {len(x)} 与 fan_in={self.fan_in} 不一致"
            )
        w, norms = self._effective()
        self._w, self._norms = w, norms
        saved = self.inner.weights
        self.inner.weights = w
        try:
            return self.inner.forward(x)
        finally:
            self.inner.weights = saved

    def backward(self, dout):
        if self._w is None:
            raise RuntimeError("WeightNorm.backward: 必须先调用 forward()")
        saved = self.inner.weights
        self.inner.weights = self._w
        try:
            dW, db, dx = self.inner.backward(dout)
        finally:
            self.inner.weights = saved
        dv = [[0.0] * self.fan_in for _ in range(self.fan_out)]
        dg = [0.0] * self.fan_out
        for i in range(self.fan_out):
            n = self._norms[i]
            dot = sum(dW[i][k] * self.v[i][k] for k in range(self.fan_in))
            coef = self.g[i] / (n * n * n)
            for j in range(self.fan_in):
                dv[i][j] = self.g[i] / n * dW[i][j] - coef * self.v[i][j] * dot
            dg[i] = dot / n
        self.grad_v = dv
        self.grad_g = dg
        self.grad_b = list(db)
        return dx

    def zero_grad(self):
        self.grad_v = [[0.0] * self.fan_in for _ in range(self.fan_out)]
        self.grad_g = [0.0] * self.fan_out
        self.grad_b = [0.0] * self.fan_out

    def param_count(self):
        return len(_param_leaves(self.v)) + self.fan_out + self.fan_out

    def train(self):
        self.training = True
        if hasattr(self.inner, "train"):
            self.inner.train()
        return self

    def eval(self):
        self.training = False
        if hasattr(self.inner, "eval"):
            self.inner.eval()
        return self

    def sgd_step(self, lr):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"WeightNorm.sgd_step: lr 必须是非负数，收到 {lr!r}")
        for i in range(self.fan_out):
            for j in range(self.fan_in):
                self.v[i][j] -= lr * self.grad_v[i][j]
            self.g[i] -= lr * self.grad_g[i]
            self.b[i] -= lr * self.grad_b[i]
        self.zero_grad()

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"WeightNorm.adam_step: lr 必须是非负数，收到 {lr!r}")
        self._adam_t += 1
        _adam_apply(self.v, self.grad_v, self.m_v, self.v_v, self._adam_t,
                    lr, beta1, beta2, eps)
        _adam_apply(self.g, self.grad_g, self.m_g, self.v_g, self._adam_t,
                    lr, beta1, beta2, eps)
        _adam_apply(self.b, self.grad_b, self.m_b, self.v_b, self._adam_t,
                    lr, beta1, beta2, eps)
        self.zero_grad()


class SpectralNorm:
    """谱归一化（Miyato et al. 2018）：w = v / sigma(v)

    `sigma(v)` 用幂迭代（`power_iter` 次）估计最大奇异值，逐次 forward 里更新
    `u`/`v_hat` 两个方向向量（它们不是参数，是缓存）。

    梯度约定：默认把 `sigma` 视为**常量**（`detach_sigma=True`），这是谱归一化在
    实践中的常见做法 —— `dv = dW / sigma`。若需要严格的端到端梯度，先调用
    `freeze_sigma()` 冻结当前的 sigma，此时 `v` 是唯一变量、反向与中心差分逐位一致。
    """

    def __init__(self, layer, power_iter: int = 1, eps: float = 1e-12):
        for attr in ("weights", "biases", "act_fn", "act_deriv"):
            if not hasattr(layer, attr):
                raise TypeError(
                    f"SpectralNorm: 内层必须提供 {attr!r}（Layer / Linear 都满足），"
                    f"收到 {type(layer).__name__}"
                )
        if isinstance(power_iter, bool) or not isinstance(power_iter, int):
            raise TypeError(f"SpectralNorm: power_iter 必须是 int，收到 {type(power_iter).__name__}")
        if power_iter < 0:
            raise ValueError(f"SpectralNorm: power_iter 必须 >= 0，收到 {power_iter!r}")
        self.inner = layer
        self.power_iter = power_iter
        self.eps = float(eps)
        self.fan_out = len(layer.weights)
        self.fan_in = len(layer.weights[0]) if self.fan_out else 0
        self.v = [list(row) for row in layer.weights]
        self.b = list(layer.biases)
        # u 长度 fan_out，vh 长度 fan_in（随机单位向量，只做幂迭代起点）
        self.u = [random.gauss(0.0, 1.0) for _ in range(self.fan_out)]
        self.vh = [random.gauss(0.0, 1.0) for _ in range(self.fan_in)]
        self._unit(self.u)
        self._unit(self.vh)
        self.sigma = 1.0
        self._frozen = False
        self._w = None
        self.grad_v = None
        self.grad_b = None
        self.zero_grad()
        self.m_v = _zeros_like(self.v)
        self.v_v = _zeros_like(self.v)
        self.m_b = [0.0] * self.fan_out
        self.v_b = [0.0] * self.fan_out
        self._adam_t = 0
        self._estimate()

    def _unit(self, vec):
        n = math.sqrt(sum(c * c for c in vec))
        if n > 0.0:
            for i in range(len(vec)):
                vec[i] /= n

    def _estimate(self):
        """幂迭代估计最大奇异值；把 u/vh 更新到收敛方向"""
        if self.fan_out == 0 or self.fan_in == 0:
            self.sigma = 1.0
            return self.sigma
        for _ in range(self.power_iter):
            # u <- v·vh ; vh <- vᵀ·u
            self.u = [sum(self.v[i][j] * self.vh[j] for j in range(self.fan_in))
                      for i in range(self.fan_out)]
            self._unit(self.u)
            self.vh = [sum(self.v[i][j] * self.u[i] for i in range(self.fan_out))
                       for j in range(self.fan_in)]
            self._unit(self.vh)
        s = sum(self.u[i] * sum(self.v[i][j] * self.vh[j] for j in range(self.fan_in))
                for i in range(self.fan_out))
        self.sigma = max(abs(s), self.eps)
        return self.sigma

    def freeze_sigma(self):
        """冻结当前 sigma：此后 forward 不再估计，反向可精确对齐中心差分"""
        self._estimate()
        self._frozen = True
        return self.sigma

    def _effective(self):
        if not self._frozen:
            self._estimate()
        s = self.sigma
        return [[c / s for c in row] for row in self.v]

    def forward(self, x):
        if len(x) != self.fan_in:
            raise ValueError(
                f"SpectralNorm.forward: 输入维度 {len(x)} 与 fan_in={self.fan_in} 不一致"
            )
        w = self._effective()
        self._w = w
        saved = self.inner.weights
        self.inner.weights = w
        try:
            return self.inner.forward(x)
        finally:
            self.inner.weights = saved

    def backward(self, dout):
        if self._w is None:
            raise RuntimeError("SpectralNorm.backward: 必须先调用 forward()")
        saved = self.inner.weights
        self.inner.weights = self._w
        try:
            dW, db, dx = self.inner.backward(dout)
        finally:
            self.inner.weights = saved
        s = self.sigma
        self.grad_v = [[c / s for c in row] for row in dW]
        self.grad_b = list(db)
        return dx

    def zero_grad(self):
        self.grad_v = [[0.0] * self.fan_in for _ in range(self.fan_out)]
        self.grad_b = [0.0] * self.fan_out

    def param_count(self):
        return self.fan_out * self.fan_in + self.fan_out

    def train(self):
        self.training = True
        if hasattr(self.inner, "train"):
            self.inner.train()
        return self

    def eval(self):
        self.training = False
        if hasattr(self.inner, "eval"):
            self.inner.eval()
        return self

    def sgd_step(self, lr):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"SpectralNorm.sgd_step: lr 必须是非负数，收到 {lr!r}")
        for i in range(self.fan_out):
            for j in range(self.fan_in):
                self.v[i][j] -= lr * self.grad_v[i][j]
            self.b[i] -= lr * self.grad_b[i]
        self.zero_grad()

    def adam_step(self, lr, beta1=0.9, beta2=0.999, eps=1e-8):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"SpectralNorm.adam_step: lr 必须是非负数，收到 {lr!r}")
        self._adam_t += 1
        _adam_apply(self.v, self.grad_v, self.m_v, self.v_v, self._adam_t,
                    lr, beta1, beta2, eps)
        _adam_apply(self.b, self.grad_b, self.m_b, self.v_b, self._adam_t,
                    lr, beta1, beta2, eps)
        self.zero_grad()


# ============================================================================
#  RNN / LSTM
# ============================================================================

class _StepCacheMixin:
    """BPTT 辅助：把 cell 的前向缓存做成快照，反向时直接恢复，避免重跑一遍前向。

    cell 的 forward 会把中间量写进 self（x / h_prev / z / 各个门…），backward 依赖它们。
    若只保存 hidden state，反向时就必须对每个时间步重新 forward 一次来"恢复缓存"。
    这里把需要的属性列进 _CACHE_FIELDS，RNN/LSTM/GRU 的 forward 会把每一步、每一层的
    快照存进 self.step_cache，训练循环里直接

        cell.restore_cache(step_cache[t][layer])

    即可复用，省掉整轮重复前向。
    """

    _CACHE_FIELDS = ()

    def cache_snapshot(self):
        return tuple(getattr(self, name) for name in self._CACHE_FIELDS)

    def restore_cache(self, snapshot):
        for name, value in zip(self._CACHE_FIELDS, snapshot):
            setattr(self, name, value)


class RNNCell(_StepCacheMixin):
    """单步 RNN 单元: h_t = tanh(W_ih·x_t + b_ih + W_hh·h_{t-1} + b_hh)"""

    _CACHE_FIELDS = ("x", "h_prev", "z")

    def __init__(self, input_size: int, hidden_size: int):
        self.input_size = input_size
        self.hidden_size = hidden_size

        # Xavier 初始化
        std_ih = math.sqrt(1.0 / input_size)
        std_hh = math.sqrt(1.0 / hidden_size)

        self.W_ih = [[random.gauss(0, std_ih) for _ in range(input_size)] for _ in range(hidden_size)]
        self.W_hh = [[random.gauss(0, std_hh) for _ in range(hidden_size)] for _ in range(hidden_size)]
        self.b_ih = [0.0] * hidden_size
        self.b_hh = [0.0] * hidden_size

        # Adam 状态
        self._init_adam()

        # 梯度缓冲区（由 zero_grad 初始化）
        self.zero_grad()

        # 缓存
        self.x = None
        self.h_prev = None
        self.z = None  # 激活前

    def zero_grad(self):
        """初始化/清零所有参数梯度"""
        self.grad_W_ih = [[0.0] * self.input_size for _ in range(self.hidden_size)]
        self.grad_W_hh = [[0.0] * self.hidden_size for _ in range(self.hidden_size)]
        self.grad_b_ih = [0.0] * self.hidden_size
        self.grad_b_hh = [0.0] * self.hidden_size

    def _init_adam(self):
        def zeros(shape):
            if isinstance(shape[0], list):
                return [zeros(row) for row in shape]
            return [0.0] * len(shape)

        self.m_W_ih = zeros(self.W_ih)
        self.v_W_ih = zeros(self.W_ih)
        self.m_W_hh = zeros(self.W_hh)
        self.v_W_hh = zeros(self.W_hh)
        self.m_b_ih = [0.0] * self.hidden_size
        self.v_b_ih = [0.0] * self.hidden_size
        self.m_b_hh = [0.0] * self.hidden_size
        self.v_b_hh = [0.0] * self.hidden_size

    def forward(self, x, h_prev=None):
        """x: (input_size,)  h_prev: (hidden_size,)  -> h: (hidden_size,)"""
        self.x = x
        self.h_prev = h_prev if h_prev is not None else [0.0] * self.hidden_size

        self.z = [0.0] * self.hidden_size
        for j in range(self.hidden_size):
            s = self.b_ih[j] + self.b_hh[j]
            for i in range(self.input_size):
                s += self.W_ih[j][i] * x[i]
            for i in range(self.hidden_size):
                s += self.W_hh[j][i] * self.h_prev[i]
            self.z[j] = s

        # tanh
        h = [math.tanh(zj) for zj in self.z]
        return h

    def backward(self, dh):
        """
        dh: (hidden_size,) 输出梯度
        返回 (dx, dh_prev), 内部累积梯度
        """
        # tanh 导数: 1 - tanh^2
        d_tanh = [1.0 - math.tanh(zj) ** 2 for zj in self.z]
        dz = [dh[j] * d_tanh[j] for j in range(self.hidden_size)]

        # dx
        dx = [0.0] * self.input_size
        for i in range(self.input_size):
            s = 0.0
            for j in range(self.hidden_size):
                s += self.W_ih[j][i] * dz[j]
            dx[i] = s

        # dh_prev
        dh_prev = [0.0] * self.hidden_size
        for i in range(self.hidden_size):
            s = 0.0
            for j in range(self.hidden_size):
                s += self.W_hh[j][i] * dz[j]
            dh_prev[i] = s

        # 累积梯度
        for j in range(self.hidden_size):
            self.grad_b_ih[j] += dz[j]
            self.grad_b_hh[j] += dz[j]
            for i in range(self.input_size):
                self.grad_W_ih[j][i] += dz[j] * self.x[i]
            for i in range(self.hidden_size):
                self.grad_W_hh[j][i] += dz[j] * self.h_prev[i]

        return dx, dh_prev

    def get_grads(self):
        return self.grad_W_ih, self.grad_W_hh, self.grad_b_ih, self.grad_b_hh


class LSTMCell(_StepCacheMixin):
    """单步 LSTM 单元 (无 peephole)"""

    _CACHE_FIELDS = ("x", "h_prev", "c_prev", "i", "f", "g", "o", "c")

    def __init__(self, input_size: int, hidden_size: int):
        self.input_size = input_size
        self.hidden_size = hidden_size

        # 合并 W_ih (4*hidden_size, input_size) 和 W_hh (4*hidden_size, hidden_size)
        gate_size = 4 * hidden_size
        std_ih = math.sqrt(1.0 / input_size)
        std_hh = math.sqrt(1.0 / hidden_size)

        self.W_ih = [[random.gauss(0, std_ih) for _ in range(input_size)] for _ in range(gate_size)]
        self.W_hh = [[random.gauss(0, std_hh) for _ in range(hidden_size)] for _ in range(gate_size)]
        self.b_ih = [0.0] * gate_size
        self.b_hh = [0.0] * gate_size

        self._init_adam()

        # 梯度缓冲区（由 zero_grad 初始化）
        self.zero_grad()

        # 缓存
        self.x = None
        self.h_prev = None
        self.c_prev = None
        self.i = self.f = self.g = self.o = None  # gates
        self.c = None  # cell state

    def zero_grad(self):
        """初始化/清零所有参数梯度"""
        hs = self.hidden_size
        gate_size = 4 * hs
        self.grad_W_ih = [[0.0] * self.input_size for _ in range(gate_size)]
        self.grad_W_hh = [[0.0] * hs for _ in range(gate_size)]
        self.grad_b_ih = [0.0] * gate_size
        self.grad_b_hh = [0.0] * gate_size

    def _init_adam(self):
        gate_size = 4 * self.hidden_size

        def zeros(shape):
            if isinstance(shape[0], list):
                return [zeros(row) for row in shape]
            return [0.0] * len(shape)

        self.m_W_ih = zeros(self.W_ih)
        self.v_W_ih = zeros(self.W_ih)
        self.m_W_hh = zeros(self.W_hh)
        self.v_W_hh = zeros(self.W_hh)
        self.m_b_ih = [0.0] * gate_size
        self.v_b_ih = [0.0] * gate_size
        self.m_b_hh = [0.0] * gate_size
        self.v_b_hh = [0.0] * gate_size

    def _sigmoid(self, x):
        # 分支写法：xi<0 时用 exp(xi)/(1+exp(xi))，避免 math.exp(-xi) 在大负数上溢出
        return [1.0 / (1.0 + math.exp(-xi)) if xi >= 0
            else math.exp(xi) / (1.0 + math.exp(xi)) for xi in x]

    def forward(self, x, h_prev=None, c_prev=None):
        """x: (input_size,) -> h: (hidden_size,), c: (hidden_size,)"""
        self.x = x
        hs = self.hidden_size
        self.h_prev = h_prev if h_prev is not None else [0.0] * hs
        self.c_prev = c_prev if c_prev is not None else [0.0] * hs

        # 预激活: gates = W_ih·x + b_ih + W_hh·h_prev + b_hh
        gates = [0.0] * (4 * hs)
        for j in range(4 * hs):
            s = self.b_ih[j] + self.b_hh[j]
            for i in range(self.input_size):
                s += self.W_ih[j][i] * x[i]
            for i in range(hs):
                s += self.W_hh[j][i] * self.h_prev[i]
            gates[j] = s

        # 分解四个门
        i_gate = gates[0:hs]
        f_gate = gates[hs:2 * hs]
        g_gate = gates[2 * hs:3 * hs]
        o_gate = gates[3 * hs:4 * hs]

        self.i = self._sigmoid(i_gate)  # input gate
        self.f = self._sigmoid(f_gate)  # forget gate
        self.g = [math.tanh(zj) for zj in g_gate]  # cell gate
        self.o = self._sigmoid(o_gate)  # output gate

        # cell state: c = f * c_prev + i * g
        self.c = [self.f[j] * self.c_prev[j] + self.i[j] * self.g[j] for j in range(hs)]

        # hidden: h = o * tanh(c)
        h = [self.o[j] * math.tanh(self.c[j]) for j in range(hs)]

        return h, self.c

    def backward(self, dh, dc_next=None):
        """
        dh: (hidden_size,) 输出梯度
        dc_next: (hidden_size,) 来自下一时间步的 cell gradient
        返回 (dx, dh_prev, dc_prev)
        """
        hs = self.hidden_size
        dc_next = dc_next if dc_next is not None else [0.0] * hs

        # dc = dh * o * (1 - tanh^2(c)) + dc_next
        dc = [0.0] * hs
        for j in range(hs):
            tanh_c = math.tanh(self.c[j])
            dc[j] = dh[j] * self.o[j] * (1.0 - tanh_c * tanh_c) + dc_next[j]

        # 各门梯度
        di = [dc[j] * self.g[j] * self.i[j] * (1.0 - self.i[j]) for j in range(hs)]
        df = [dc[j] * self.c_prev[j] * self.f[j] * (1.0 - self.f[j]) for j in range(hs)]
        dg = [dc[j] * self.i[j] * (1.0 - self.g[j] * self.g[j]) for j in range(hs)]
        do = [dh[j] * math.tanh(self.c[j]) * self.o[j] * (1.0 - self.o[j]) for j in range(hs)]

        d_gates = di + df + dg + do  # (4*hidden_size,)

        # 累积梯度
        for j in range(4 * hs):
            self.grad_b_ih[j] += d_gates[j]
            self.grad_b_hh[j] += d_gates[j]
            for i in range(self.input_size):
                self.grad_W_ih[j][i] += d_gates[j] * self.x[i]
            for i in range(hs):
                self.grad_W_hh[j][i] += d_gates[j] * self.h_prev[i]

        # dx
        dx = [0.0] * self.input_size
        for i in range(self.input_size):
            s = 0.0
            for j in range(4 * hs):
                s += self.W_ih[j][i] * d_gates[j]
            dx[i] = s

        # dh_prev
        dh_prev = [0.0] * hs
        for i in range(hs):
            s = 0.0
            for j in range(4 * hs):
                s += self.W_hh[j][i] * d_gates[j]
            dh_prev[i] = s

        # dc_prev
        dc_prev = [dc[j] * self.f[j] for j in range(hs)]

        return dx, dh_prev, dc_prev

    def get_grads(self):
        return self.grad_W_ih, self.grad_W_hh, self.grad_b_ih, self.grad_b_hh


class RNN:
    """多层 RNN（堆叠多个 RNNCell）"""

    def __init__(self, input_size: int, hidden_size: int, num_layers: int = 1):
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.num_layers = num_layers

        self.cells = []
        for l in range(num_layers):
            sz_in = input_size if l == 0 else hidden_size
            self.cells.append(RNNCell(sz_in, hidden_size))

    def forward(self, x_seq, h0=None):
        """
        x_seq: List[(input_size,)]  时间序列
        h0: List[(hidden_size,)] 每层初始 hidden
        返回 outputs: List[(hidden_size,)]  最后一层全部时间步
        """
        if h0 is None:
            h0 = [[0.0] * self.hidden_size for _ in range(self.num_layers)]

        outputs = []
        h = list(h0)
        self.step_cache = []  # 每步每层的前向缓存快照，BPTT 时可 restore_cache 复用
        for xt in x_seq:
            layer_in = xt
            step = []
            for l in range(self.num_layers):
                h[l] = self.cells[l].forward(layer_in, h[l])
                step.append(self.cells[l].cache_snapshot())
                layer_in = h[l]
            self.step_cache.append(step)
            outputs.append(list(h[-1]))
        return outputs, h


class LSTM:
    """多层 LSTM（堆叠多个 LSTMCell）"""

    def __init__(self, input_size: int, hidden_size: int, num_layers: int = 1):
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.num_layers = num_layers

        self.cells = []
        for l in range(num_layers):
            sz_in = input_size if l == 0 else hidden_size
            self.cells.append(LSTMCell(sz_in, hidden_size))

    def forward(self, x_seq, h0=None, c0=None):
        """
        x_seq: List[(input_size,)]
        h0, c0: List[(hidden_size,)] 每层初始状态
        返回 outputs, (h_n, c_n)
        """
        if h0 is None:
            h0 = [[0.0] * self.hidden_size for _ in range(self.num_layers)]
        if c0 is None:
            c0 = [[0.0] * self.hidden_size for _ in range(self.num_layers)]

        outputs = []
        h = list(h0)
        c = list(c0)
        self.step_cache = []  # 每步每层的前向缓存快照（含 c / 各门），BPTT 时复用
        for xt in x_seq:
            layer_in = xt
            step = []
            for l in range(self.num_layers):
                h[l], c[l] = self.cells[l].forward(layer_in, h[l], c[l])
                step.append(self.cells[l].cache_snapshot())
                layer_in = h[l]
            self.step_cache.append(step)
            outputs.append(list(h[-1]))
        return outputs, (h, c)


# ============================================================================
#  Matrix helpers (用于 Transformer)
# ============================================================================

def _matmul(A, B):
    """矩阵乘法 A(m×n) × B(n×p) → (m×p)，纯 Python 实现"""
    m, n = len(A), len(A[0])
    n2, p = len(B), len(B[0])
    if n != n2:
        # 不能用 assert：python -O 会把它去掉，错误形状会被静默截断
        raise ValueError(f"_matmul: 维度不匹配 ({m},{n}) × ({n2},{p})")
    # 先把 B 转置一次，让每一列成为元组，再用 C 层的 map(mul) / sum 做点积：
    # 与逐个元素 += 的三重循环结果完全一致，但快约 1.6 倍
    Bt = list(zip(*B))
    return [[sum(map(_mul, row, col)) for col in Bt] for row in A]


def _transpose(M):
    """转置 (m×n) → (n×m)"""
    m, n = len(M), len(M[0])
    return [[M[i][j] for i in range(m)] for j in range(n)]


def _reject_nan_row(v, who):
    """softmax 前置检查：NaN 无法通过「取最大值」被发现，必须显式扫一遍"""
    for i, x in enumerate(v):
        if x != x:
            raise ValueError("%s: 第 %d 个 logit 是 NaN" % (who, i))


def _softmax_row(v):
    """对一维列表做 softmax（整行都是 -inf 时返回全 0，避免 exp(-inf-(-inf))=NaN）

    数值边界：含 NaN 抛 ValueError；含 +inf 时把概率均分给所有 +inf 项
    （否则 exp(inf-inf)=NaN）；整行 -inf 返回全 0。
    """
    _reject_nan_row(v, "_softmax_row")
    mx = max(v)
    if mx == float("-inf"):
        return [0.0] * len(v)
    if mx == float("inf"):
        hits = sum(1 for x in v if x == float("inf"))
        share = 1.0 / hits
        return [(share if x == float("inf") else 0.0) for x in v]
    exps = [math.exp(x - mx) for x in v]
    s = sum(exps)
    return [e / s for e in exps]


# ============================================================================
#  GRU (Gated Recurrent Unit)
# ============================================================================

class GRUCell(_StepCacheMixin):
    """单步 GRU 单元

    z_t = σ(W_iz·x_t + b_iz + W_hz·h_{t-1} + b_hz)        (update gate)
    r_t = σ(W_ir·x_t + b_ir + W_hr·h_{t-1} + b_hr)        (reset gate)
    n_t = tanh(W_in·x_t + b_in + r_t ⊙ (W_hn·h_{t-1} + b_hn))  (new gate)
    h_t = (1 - z_t) ⊙ n_t + z_t ⊙ h_{t-1}
    """

    _CACHE_FIELDS = ("x", "h_prev", "z", "r", "n_ih", "n_hh", "z_a", "r_a", "n_val")

    def __init__(self, input_size: int, hidden_size: int):
        self.input_size = input_size
        self.hidden_size = hidden_size
        hs, ins = hidden_size, input_size

        std_ih = math.sqrt(1.0 / ins)
        std_hh = math.sqrt(1.0 / hs)

        self.W_ih = [[random.gauss(0, std_ih) for _ in range(ins)] for _ in range(3 * hs)]
        self.W_hh = [[random.gauss(0, std_hh) for _ in range(hs)] for _ in range(3 * hs)]
        self.b_ih = [0.0] * (3 * hs)
        self.b_hh = [0.0] * (3 * hs)

        self._init_adam()

        # 梯度缓冲区（由 zero_grad 初始化）
        self.zero_grad()

        # 缓存
        self.x = self.h_prev = None
        self.z = self.r = None                      # 两组门预激活值（n 门无预激活变量）
        self.z_a = self.r_a = None                   # sigmoid(z), sigmoid(r)
        self.n_val = None                            # tanh(n_ih + r_a * n_hh)
        self.n_ih = self.n_hh = None                 # n 的 ih 和 hh 分量（分离存储用于反向）

    def zero_grad(self):
        """初始化/清零所有参数梯度"""
        hs = self.hidden_size
        self.grad_W_ih = [[0.0] * self.input_size for _ in range(3 * hs)]
        self.grad_W_hh = [[0.0] * hs for _ in range(3 * hs)]
        self.grad_b_ih = [0.0] * (3 * hs)
        self.grad_b_hh = [0.0] * (3 * hs)

    def _init_adam(self):
        hs = self.hidden_size
        def zeros(shape):
            if isinstance(shape[0], list):
                return [zeros(row) for row in shape]
            return [0.0] * len(shape)
        self.m_W_ih = zeros(self.W_ih); self.v_W_ih = zeros(self.W_ih)
        self.m_W_hh = zeros(self.W_hh); self.v_W_hh = zeros(self.W_hh)
        self.m_b_ih = [0.0] * (3 * hs); self.v_b_ih = [0.0] * (3 * hs)
        self.m_b_hh = [0.0] * (3 * hs); self.v_b_hh = [0.0] * (3 * hs)

    def _sigmoid(self, x):
        # 分支写法：xi<0 时用 exp(xi)/(1+exp(xi))，避免 math.exp(-xi) 在大负数上溢出
        return [1.0 / (1.0 + math.exp(-xi)) if xi >= 0
            else math.exp(xi) / (1.0 + math.exp(xi)) for xi in x]

    def forward(self, x, h_prev=None):
        hs = self.hidden_size
        self.x = x
        self.h_prev = h_prev if h_prev is not None else [0.0] * hs

        # 分离三组门权重: [z: 0:hs], [r: hs:2*hs], [n: 2*hs:3*hs]
        def _linear(W_slice, b_slice, inp, size):
            out = [b_slice[j] for j in range(size)]
            for j in range(size):
                for i in range(len(inp)):
                    out[j] += W_slice[j][i] * inp[i]
            return out

        z_ih = _linear(self.W_ih[:hs], self.b_ih[:hs], x, hs)
        z_hh = _linear(self.W_hh[:hs], self.b_hh[:hs], self.h_prev, hs)
        self.z = [z_ih[j] + z_hh[j] for j in range(hs)]

        r_ih = _linear(self.W_ih[hs:2*hs], self.b_ih[hs:2*hs], x, hs)
        r_hh = _linear(self.W_hh[hs:2*hs], self.b_hh[hs:2*hs], self.h_prev, hs)
        self.r = [r_ih[j] + r_hh[j] for j in range(hs)]

        self.n_ih = _linear(self.W_ih[2*hs:3*hs], self.b_ih[2*hs:3*hs], x, hs)
        self.n_hh = _linear(self.W_hh[2*hs:3*hs], self.b_hh[2*hs:3*hs], self.h_prev, hs)

        self.z_a = self._sigmoid(self.z)
        self.r_a = self._sigmoid(self.r)
        self.n_val = [math.tanh(self.n_ih[j] + self.r_a[j] * self.n_hh[j]) for j in range(hs)]

        h = [(1 - self.z_a[j]) * self.n_val[j] + self.z_a[j] * self.h_prev[j] for j in range(hs)]
        return h

    def backward(self, dh):
        """BPTT 单步反向，返回 (dx, dh_prev)，内部累积梯度"""
        hs = self.hidden_size

        # h = (1 - z_a) * n_val + z_a * h_prev
        dz_a = [dh[j] * (self.h_prev[j] - self.n_val[j]) for j in range(hs)]
        dn = [dh[j] * (1 - self.z_a[j]) for j in range(hs)]
        dh_prev_direct = [dh[j] * self.z_a[j] for j in range(hs)]

        # n_val = tanh(n_ih + r_a * n_hh)
        dn_pre = [dn[j] * (1 - self.n_val[j] * self.n_val[j]) for j in range(hs)]
        d_n_ih = list(dn_pre)
        d_n_hh = [dn_pre[j] * self.r_a[j] for j in range(hs)]
        dr_a_from_n = [dn_pre[j] * self.n_hh[j] for j in range(hs)]

        # r_a = sigmoid(r)：r_a 不受 z 直接影响，梯度仅来自 n
        dr = [dr_a_from_n[j] * self.r_a[j] * (1 - self.r_a[j]) for j in range(hs)]

        # z_a = sigmoid(z)
        dz = [dz_a[j] * self.z_a[j] * (1 - self.z_a[j]) for j in range(hs)]

        # 累积参数梯度
        # 更新门 z: rows [0:hs]
        for j in range(hs):
            self.grad_b_ih[j] += dz[j]
            self.grad_b_hh[j] += dz[j]
            for i in range(self.input_size):
                self.grad_W_ih[j][i] += dz[j] * self.x[i]
            for i in range(hs):
                self.grad_W_hh[j][i] += dz[j] * self.h_prev[i]

        # 重置门 r: rows [hs:2*hs]
        for j in range(hs):
            rj = hs + j
            self.grad_b_ih[rj] += dr[j]
            self.grad_b_hh[rj] += dr[j]
            for i in range(self.input_size):
                self.grad_W_ih[rj][i] += dr[j] * self.x[i]
            for i in range(hs):
                self.grad_W_hh[rj][i] += dr[j] * self.h_prev[i]

        # 新门 n: rows [2*hs:3*hs]
        for j in range(hs):
            nj = 2 * hs + j
            self.grad_b_ih[nj] += d_n_ih[j]
            self.grad_b_hh[nj] += d_n_hh[j]
            for i in range(self.input_size):
                self.grad_W_ih[nj][i] += d_n_ih[j] * self.x[i]
            for i in range(hs):
                self.grad_W_hh[nj][i] += d_n_hh[j] * self.h_prev[i]

        # dx 和 dh_prev 通过三个门权重反传
        # 注: dx 经过 n_ih (W_ih_n)，dh_prev 经过 n_hh (W_hh_n)，需用不同的 n-门梯度分量
        d_all_gates = [0.0] * (3 * hs)
        for j in range(hs):
            d_all_gates[j] = dz[j]
            d_all_gates[hs + j] = dr[j]
            d_all_gates[2 * hs + j] = d_n_ih[j]       # dx 走 n_ih 路径
        dx = [sum(self.W_ih[j][i] * d_all_gates[j] for j in range(3 * hs)) for i in range(self.input_size)]

        # dh_prev: 直接路径 h = (1-z)*n + z*h_prev → dh * z  + 通过三个门 hh 权重反传
        for j in range(hs):
            d_all_gates[2 * hs + j] = d_n_hh[j]       # dh_prev 走 n_hh 路径（含 r_a 因子）
        dh_prev = [dh_prev_direct[i] + sum(self.W_hh[j][i] * d_all_gates[j] for j in range(3 * hs)) for i in range(hs)]

        return dx, dh_prev

    def get_grads(self):
        return self.grad_W_ih, self.grad_W_hh, self.grad_b_ih, self.grad_b_hh


class GRU:
    """多层 GRU（堆叠多个 GRUCell）"""

    def __init__(self, input_size: int, hidden_size: int, num_layers: int = 1):
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.num_layers = num_layers

        self.cells = []
        for l in range(num_layers):
            sz_in = input_size if l == 0 else hidden_size
            self.cells.append(GRUCell(sz_in, hidden_size))

    def forward(self, x_seq, h0=None):
        if h0 is None:
            h0 = [[0.0] * self.hidden_size for _ in range(self.num_layers)]

        outputs = []
        h = list(h0)
        self.step_cache = []  # 每步每层的前向缓存快照，BPTT 时可 restore_cache 复用
        for xt in x_seq:
            layer_in = xt
            step = []
            for l in range(self.num_layers):
                h[l] = self.cells[l].forward(layer_in, h[l])
                step.append(self.cells[l].cache_snapshot())
                layer_in = h[l]
            self.step_cache.append(step)
            outputs.append(list(h[-1]))
        return outputs, h


# ============================================================================
#  Transformer 组件
# ============================================================================

def rope_inv_freqs(d_k: int, base: float = 10000.0, scaling: str = None,
                   factor: float = 8.0, original_max: int = 512,
                   beta_fast: float = 32.0, beta_slow: float = 1.0):
    """RoPE 的逐对逆频率（长度 d_k//2），支持三种长度外推缩放

    第 i 对的原始频率是 `base ** (-2i/d_k)`，波长 `2*pi/freq`（单位：token）。
    scaling:

    - None / 'none'：原始频率，与旧版逐位一致（默认）。
    - 'linear'：位置整体除以 factor（`pos -> pos/factor`），等价于所有频率
      除以 factor。最简单，但会压缩所有频率、损失局部细节。
    - 'ntk'：NTK-aware 插值，改底数 `base_eff = base * factor ** (d_k/(d_k-2))`。
      低频（长波长）被拉得更长、高频几乎不动，比 linear 保留更多局部信息。
    - 'yarn'：YaRN 的分段插值——按"在 original_max 长度内转了几圈"
      `rotations = original_max * freq / (2*pi)` 做平滑过渡：转得多的
      （高频）用 linear 缩放，转得少的（低频）保持原样，中间用 smoothstep 混合。
      `beta_fast` / `beta_slow` 是两端的转折圈数。

    YaRN 论文里的注意力温度 `mscale` 不在这里实现：本函数只负责频率，
    `MultiHeadAttention` 在 `rope_scaling='yarn'` 时把 `mscale` 乘到 softmax
    前的分数上。
    """
    if isinstance(d_k, bool) or not isinstance(d_k, int):
        raise ValueError(f"rope_inv_freqs: d_k 必须是正整数，收到 {d_k!r}")
    if d_k < 2:
        raise ValueError(f"rope_inv_freqs: d_k 至少为 2，收到 {d_k}")
    if isinstance(base, bool) or not isinstance(base, (int, float)):
        raise ValueError(f"rope_inv_freqs: base 必须是正数，收到 {base!r}")
    base = float(base)
    if not (base > 0.0) or base != base or base == float('inf'):
        raise ValueError(f"rope_inv_freqs: base 必须是有限正数，收到 {base!r}")
    explicit_none = scaling == 'none'
    if scaling is None:
        scaling = 'none'
    if scaling not in ('none', 'linear', 'ntk', 'yarn'):
        raise ValueError(
            "rope_inv_freqs: scaling 只能是 None/'none'/'linear'/'ntk'/'yarn'，"
            f"收到 {scaling!r}"
        )
    if isinstance(factor, bool) or not isinstance(factor, (int, float)):
        raise ValueError(f"rope_inv_freqs: factor 必须是 >=1 的数字，收到 {factor!r}")
    factor = float(factor)
    if not (factor >= 1.0) or factor != factor or factor == float('inf'):
        raise ValueError(f"rope_inv_freqs: factor 必须是有限且 >=1，收到 {factor!r}")
    if scaling == 'none':
        # factor 在 none 下不起作用；默认参数就是 8.0，不能因此报错。
        # 只有显式写 'none' 又给了非 1 的 factor 才提示，免得"以为开了缩放其实没开"。
        if explicit_none and factor != 1.0:
            raise ValueError("rope_inv_freqs: scaling='none' 时 factor 必须为 1.0")
        return [1.0 / (base ** (2.0 * i / d_k)) for i in range(d_k // 2)]

    if isinstance(original_max, bool) or not isinstance(original_max, int):
        raise ValueError(
            f"rope_inv_freqs: original_max 必须是正整数，收到 {original_max!r}"
        )
    if original_max < 1:
        raise ValueError(f"rope_inv_freqs: original_max 必须 >= 1，收到 {original_max}")

    if scaling == 'linear':
        return [(1.0 / (base ** (2.0 * i / d_k))) / factor
                for i in range(d_k // 2)]

    if scaling == 'ntk':
        base_eff = base * (factor ** (d_k / (d_k - 2.0)))
        return [1.0 / (base_eff ** (2.0 * i / d_k)) for i in range(d_k // 2)]

    # yarn
    if isinstance(beta_fast, bool) or not isinstance(beta_fast, (int, float)):
        raise ValueError(
            f"rope_inv_freqs: beta_fast 必须是正数，收到 {beta_fast!r}"
        )
    if isinstance(beta_slow, bool) or not isinstance(beta_slow, (int, float)):
        raise ValueError(
            f"rope_inv_freqs: beta_slow 必须是正数，收到 {beta_slow!r}"
        )
    beta_fast = float(beta_fast)
    beta_slow = float(beta_slow)
    if not (beta_fast > beta_slow > 0.0):
        raise ValueError(
            "rope_inv_freqs: 需要 beta_fast > beta_slow > 0，收到 "
            f"beta_fast={beta_fast}, beta_slow={beta_slow}"
        )
    two_pi = 2.0 * math.pi
    out = []
    for i in range(d_k // 2):
        f0 = 1.0 / (base ** (2.0 * i / d_k))
        rotations = original_max * f0 / two_pi
        if rotations >= beta_fast:
            ramp = 1.0
        elif rotations <= beta_slow:
            ramp = 0.0
        else:
            u = (rotations - beta_slow) / (beta_fast - beta_slow)
            ramp = u * u * (3.0 - 2.0 * u)      # smoothstep
        out.append((1.0 - ramp) * f0 + ramp * (f0 / factor))
    return out


class MultiHeadAttention:
    """多头自注意力 (Multi-Head Self-Attention)

    输入: (seq_len, d_model) 的序列
    输出: (seq_len, d_model)
    """

    def __init__(self, d_model: int, num_heads: int, dropout: float = 0.0,
                 causal: bool = False, rope: bool = False, rope_base: float = 10000.0,
                 window: int = None, num_kv_heads: int = None, alibi: bool = False,
                 rope_scaling: str = None, rope_factor: float = 8.0,
                 rope_original_max: int = 512, rope_beta_fast: float = 32.0,
                 rope_beta_slow: float = 1.0, relative_bias=None,
                 yarn_mscale: float = None):
        """dropout: 注意力权重上的 dropout（训练模式下生效，eval() 关闭）。

        实现方式是「对 softmax 后的权重逐元素做 inverted dropout」：训练时每个
        权重以 1/(1-p) 的概率保留并放大，推理时不缩放。反向要乘同一个 mask。

        causal: 为 True 时加因果掩码——位置 t 只能看到 0..t，看不到未来。
        这是自回归语言模型（GPT 式）的必要条件；默认 False 保持双向注意力。

        window: 滑动窗口（Mistral 式局部因果）。设了就隐含因果——位置 t 只能看到
        最近 window 个位置（含自己），更早的一律屏蔽；显存/算力从 O(T²) 降到
        O(T·window)。默认 None 表示全注意力，行为与旧版逐位一致。

        rope: 为 True 时给 Q/K 加旋转位置编码（RoPE，Llama 系）。旋转是正交变换，
        只改"方向"不改模长，attention 分数里自然带上相对位置信息，外推性比
        固定 sin/cos 绝对位置编码好得多。默认 False 时与原行为逐位一致。

        num_kv_heads: GQA / MQA 的 KV 头数（Llama-2 70B、Mistral 用）。设成小于
        num_heads 时，多个 Q 头共享同一组 K/V：`W_k`/`W_v` 的输出维度从 d_model
        缩到 num_kv_heads*d_k，KV cache 同比例变小。默认 None 等于 num_heads，
        即普通 MHA——此时所有张量形状、随机数抽取顺序都与旧版一致。

        alibi: 为 True 时给注意力分数加 ALiBi 线性偏置（Attention with Linear
        Biases）：第 h 个头加 `slope_h * (t - j)`，slope_h = 2^(-8*(h+1)/num_heads)。
        距离越远惩罚越大，天然带「近处优先」，且无需位置编码就能外推更长的序列。
        偏置是常数、不参与求导，所以反向不需要额外分支。

        rope_scaling: RoPE 的长度外推缩放，见 `rope_inv_freqs`。
        'linear' / 'ntk' / 'yarn' 三选一，默认 None 表示原始频率——此时
        `rope_freqs` 与旧版逐位一致，反向/前向都不变。
        `rope_factor` 是外推倍数（想从 512 撑到 4096 就是 8.0），
        `rope_original_max` 是预训练长度（YaRN 用它算每个维度的旋转圈数），
        `rope_beta_fast` / `rope_beta_slow` 是 YaRN 的转折圈数。
        `rope_scaling='yarn'` 时还会把 YaRN 的注意力温度
        `mscale = 0.1*ln(rope_factor)+1` 乘到 softmax 前的分数上（可用
        `yarn_mscale` 显式覆盖；默认 1.0 时数值与旧版逐位一致）。
        """
        if not (0.0 <= dropout < 1.0):
            raise ValueError(f"MultiHeadAttention: dropout 必须在 [0,1) 内，收到 {dropout!r}")
        self.dropout = dropout
        self.causal = bool(causal)
        self.rope = bool(rope)
        self.rope_base = float(rope_base)
        # 滑动窗口（Mistral 式局部因果）：只看最近 window 个位置（含自己）。
        # 设了 window 就隐含因果——未来位置一律屏蔽；None 表示全注意力。
        if window is None:
            self.window = None
        else:
            if isinstance(window, bool) or not isinstance(window, int):
                raise ValueError(
                    f"MultiHeadAttention: window 必须是正整数或 None，收到 {window!r}"
                )
            if window < 1:
                raise ValueError(f"MultiHeadAttention: window 必须 >= 1，收到 {window!r}")
            self.window = window
        self.alibi = bool(alibi)
        self.relative_bias = relative_bias   # 可选：T5RelativeBias 实例
        self.training = True
        self.rng = random            # 可注入（测试里换成 random.Random(seed) 复现 mask）
        # 每次 forward 重建；反向只读这几个列表
        self.attn_dropped = []       # 实际参与 attn@V 的权重（含 dropout 缩放）
        self.attn_masks = []         # 对应掩码；None 表示本次没做 dropout
        if d_model % num_heads != 0:
            raise ValueError(
                f"MultiHeadAttention: d_model={d_model} 必须能被 num_heads={num_heads} 整除"
            )
        self.d_model = d_model
        self.num_heads = num_heads
        self.d_k = d_model // num_heads
        self.dropout_p = dropout
        # GQA / MQA：KV 头数可以少于 Q 头数，每 num_heads/num_kv_heads 个 Q 头
        # 共享同一组 K/V。None = num_heads（普通 MHA，形状与旧版完全一致）。
        if num_kv_heads is None:
            num_kv_heads = num_heads
        if isinstance(num_kv_heads, bool) or not isinstance(num_kv_heads, int):
            raise ValueError(
                f"MultiHeadAttention: num_kv_heads 必须是正整数，收到 {num_kv_heads!r}"
            )
        if num_kv_heads < 1 or num_kv_heads > num_heads:
            raise ValueError(
                f"MultiHeadAttention: num_kv_heads 必须在 1..{num_heads} 内，收到 {num_kv_heads}"
            )
        if num_heads % num_kv_heads != 0:
            raise ValueError(
                f"MultiHeadAttention: num_heads={num_heads} 必须能被 "
                f"num_kv_heads={num_kv_heads} 整除"
            )
        self.num_kv_heads = num_kv_heads
        self.kv_dim = num_kv_heads * self.d_k   # W_k/W_v 的输出维度（KV cache 宽度）
        self.kv_group = num_heads // num_kv_heads
        # RoPE 的成对频率：第 i 对默认用 base^(-2i/d_k)（与 Llama 一致），
        # 也可按 rope_scaling 做 linear / NTK / YaRN 外推缩放。
        self.rope_scaling = rope_scaling
        self.rope_factor = float(rope_factor)
        self.rope_freqs = rope_inv_freqs(
            self.d_k, self.rope_base, rope_scaling, rope_factor,
            rope_original_max, rope_beta_fast, rope_beta_slow,
        )
        # YaRN 的注意力温度 mscale = 0.1*ln(factor)+1：乘在 softmax 前的分数上。
        # 非 yarn 缩放默认 1.0（数值路径与旧版逐位一致）；显式传值则无条件生效。
        if yarn_mscale is None:
            yarn_mscale = (0.1 * math.log(self.rope_factor) + 1.0
                           if self.rope_scaling == 'yarn' else 1.0)
        if (isinstance(yarn_mscale, bool)
                or not isinstance(yarn_mscale, (int, float))
                or not math.isfinite(float(yarn_mscale))
                or float(yarn_mscale) <= 0.0):
            raise ValueError(
                f"MultiHeadAttention: yarn_mscale 必须是正数，收到 {yarn_mscale!r}")
        self.yarn_mscale = float(yarn_mscale)
        # ALiBi 的逐头斜率：2^(-8*(h+1)/num_heads)，与论文/CausalLM 实现一致
        self.alibi_slopes = [2.0 ** (-8.0 * (h + 1) / num_heads)
                             for h in range(num_heads)]

        std = math.sqrt(2.0 / d_model)
        self.W_q = [[random.gauss(0, std) for _ in range(d_model)] for _ in range(d_model)]
        self.W_k = [[random.gauss(0, std) for _ in range(d_model)] for _ in range(self.kv_dim)]
        self.W_v = [[random.gauss(0, std) for _ in range(d_model)] for _ in range(self.kv_dim)]
        self.W_o = [[random.gauss(0, std) for _ in range(d_model)] for _ in range(d_model)]

        self.b_q = [0.0] * d_model
        self.b_k = [0.0] * self.kv_dim
        self.b_v = [0.0] * self.kv_dim
        self.b_o = [0.0] * d_model

        self._init_adam()
        self.zero_grad()

        # 缓存
        self.x = None       # (seq_len, d_model)
        self.seq_len = 0
        self.Q = self.K = self.V = None           # per-head: List[(seq_len, d_k)] × num_heads
        self.attn_weights = None   # List[(seq_len, seq_len)] × num_heads
        self.head_out = None       # List[(seq_len, d_k)] × num_heads
        self.concat = None         # (seq_len, d_model)

    def zero_grad(self):
        """初始化/清零所有参数梯度"""
        d = self.d_model
        def zeros_2d(r, c):
            return [[0.0] * c for _ in range(r)]
        kv = self.kv_dim
        self.grads = {
            "W_q": zeros_2d(d, d), "b_q": [0.0] * d,
            "W_k": zeros_2d(kv, d), "b_k": [0.0] * kv,
            "W_v": zeros_2d(kv, d), "b_v": [0.0] * kv,
            "W_o": zeros_2d(d, d), "b_o": [0.0] * d,
        }
        if self.relative_bias is not None:
            self.relative_bias.zero_grad()

    def _init_adam(self):
        d = self.d_model
        def zeros_2d(r, c):
            return [[0.0] * c for _ in range(r)]
        kv = self.kv_dim
        self.m_W_q = zeros_2d(d, d); self.v_W_q = zeros_2d(d, d)
        self.m_W_k = zeros_2d(kv, d); self.v_W_k = zeros_2d(kv, d)
        self.m_W_v = zeros_2d(kv, d); self.v_W_v = zeros_2d(kv, d)
        self.m_W_o = zeros_2d(d, d); self.v_W_o = zeros_2d(d, d)
        self.m_b_q = [0.0] * d; self.v_b_q = [0.0] * d
        self.m_b_k = [0.0] * kv; self.v_b_k = [0.0] * kv
        self.m_b_v = [0.0] * kv; self.v_b_v = [0.0] * kv
        self.m_b_o = [0.0] * d; self.v_b_o = [0.0] * d

    def train(self):
        """训练模式：注意力权重 dropout 生效"""
        self.training = True
        return self

    def eval(self):
        """推理模式：关闭 dropout（与 Dropout 的约定一致）"""
        self.training = False
        return self

    def _rope_apply(self, vec, pos: int, sign: float = 1.0):
        """对单个头的向量做 RoPE 旋转；sign=-1 即逆旋转（反向传播用）

        第 i 维与第 i+half 维配对（GPT-NeoX 版式）。d_k 为奇数时中间那维不旋转。
        """
        half = self.d_k // 2
        out = list(vec)
        for i in range(half):
            theta = pos * self.rope_freqs[i]
            c = math.cos(theta)
            s = sign * math.sin(theta)
            x0 = vec[i]
            x1 = vec[i + half]
            out[i] = x0 * c - x1 * s
            out[i + half] = x0 * s + x1 * c
        return out

    def forward_step(self, x_t, cache):
        """单 token 增量前向（推理专用，不写反向缓存）

        cache: dict，本层一份；存 `K`/`V`（每头一个 [t][d_k] 列表）与 `pos`。
        只对"没在滑动窗口里"的情况保证与 forward 的最后一行逐位一致：
        位置编码/因果掩码都依赖绝对位置，窗口滑动后必须重建 cache。
        """
        d = self.d_model
        h = self.num_heads
        d_k = self.d_k
        kv = self.kv_dim
        q = [sum(map(_mul, self.W_q[j], x_t)) + self.b_q[j] for j in range(d)]
        k = [sum(map(_mul, self.W_k[j], x_t)) + self.b_k[j] for j in range(kv)]
        v = [sum(map(_mul, self.W_v[j], x_t)) + self.b_v[j] for j in range(kv)]
        pos = cache.get("pos", 0)
        cache["pos"] = pos + 1
        n_kv = self.num_kv_heads
        K = cache.setdefault("K", [[] for _ in range(n_kv)])
        V = cache.setdefault("V", [[] for _ in range(n_kv)])
        scale = 1.0 / math.sqrt(d_k)
        concat = [0.0] * d
        # 增量前向只需要 query 位置 pos 的那一行相对偏置桶
        rel_bias = (self.relative_bias.forward(pos + 1, klen=pos + 1)
                    if self.relative_bias is not None else None)
        for head in range(h):
            off = head * d_k
            # GQA：每 kv_group 个 Q 头共享一组 K/V（cache 也按 kv 头存）
            kv_head = head // self.kv_group
            kv_off = kv_head * d_k
            qh = q[off:off + d_k]
            kh = k[kv_off:kv_off + d_k]
            vh = v[kv_off:kv_off + d_k]
            if self.rope:
                qh = self._rope_apply(qh, pos)
                kh = self._rope_apply(kh, pos)
            if len(K[kv_head]) == pos:
                # 同一组的第一个 Q 头负责写入，后续 Q 头复用（不重复 append）
                K[kv_head].append(kh)
                V[kv_head].append(vh)
            keys = K[kv_head]
            scores = [sum(map(_mul, qh, keys[j])) * scale * self.yarn_mscale
                      for j in range(len(keys))]
            if self.alibi:
                slope = self.alibi_slopes[head]
                for j in range(len(scores)):
                    scores[j] += slope * (pos - j)
            if rel_bias is not None:
                brow = rel_bias[head][pos]
                for j in range(len(scores)):
                    scores[j] += brow[j]
            if self.window is not None:
                # 增量前向只有「过去 + 自己」，窗口外的更早位置要屏蔽（与 forward 一致）
                for j in range(max(0, pos - self.window + 1)):
                    scores[j] = float("-inf")
            attn = _softmax_row(scores)
            cols = list(zip(*V[kv_head]))
            out = [sum(map(_mul, attn, col)) for col in cols]
            concat[off:off + d_k] = out
        return [sum(map(_mul, self.W_o[j], concat)) + self.b_o[j] for j in range(d)]

    def forward(self, x_seq, key_mask=None):
        """x_seq: List[List[float]]  (seq_len, d_model)

        key_mask: 长度 seq_len 的 0/1 列表，0 表示该位置是填充、不能当 key
        （分数置 -inf，softmax 后权重恰为 0，反向自动为 0）。
        None 表示全有效，行为与旧版逐位相同。
        """
        if key_mask is not None:
            if len(key_mask) != len(x_seq):
                raise ValueError(
                    f"MultiHeadAttention.forward: key_mask 长度 {len(key_mask)} "
                    f"与 seq_len={len(x_seq)} 不一致")
            if not any(key_mask):
                raise ValueError("MultiHeadAttention.forward: key_mask 至少要有 1 个有效位置")
        self.key_mask = key_mask
        # 复制一份，避免调用者之后原地修改 x_seq 污染反向传播缓存
        self.x = [list(row) for row in x_seq]
        self.seq_len = len(x_seq)
        d_k = self.d_k
        h = self.num_heads

        # 线性投影 Q, K, V
        kv = self.kv_dim
        q_full = _matmul(x_seq, _transpose(self.W_q))  # (seq_len, d_model)
        k_full = _matmul(x_seq, _transpose(self.W_k))  # (seq_len, kv_dim)
        v_full = _matmul(x_seq, _transpose(self.W_v))
        # 加 bias
        for t in range(self.seq_len):
            for j in range(self.d_model):
                q_full[t][j] += self.b_q[j]
            for j in range(kv):
                k_full[t][j] += self.b_k[j]
                v_full[t][j] += self.b_v[j]

        # 拆分为多头: (seq_len, d_model) → h × (seq_len, d_k)
        self.Q = []
        self.K = []
        self.V = []
        for head in range(h):
            offset = head * d_k
            # GQA：Q 头按组映射到 KV 头（num_kv_heads == num_heads 时即 head 本身）
            kv_off = (head // self.kv_group) * d_k
            q_h = [[q_full[t][offset + j] for j in range(d_k)] for t in range(self.seq_len)]
            k_h = [[k_full[t][kv_off + j] for j in range(d_k)] for t in range(self.seq_len)]
            v_h = [[v_full[t][kv_off + j] for j in range(d_k)] for t in range(self.seq_len)]
            if self.rope:
                # 每个位置用自己的绝对位置角旋转（q 与 k 都转，v 不动）
                q_h = [self._rope_apply(q_h[t], t) for t in range(self.seq_len)]
                k_h = [self._rope_apply(k_h[t], t) for t in range(self.seq_len)]
            self.Q.append(q_h)
            self.K.append(k_h)
            self.V.append(v_h)

        # 各头分别计算注意力
        scale = 1.0 / math.sqrt(d_k)
        self.attn_weights = []
        self.attn_dropped = []
        self.attn_masks = []
        self.head_out = []
        self.concat = [[0.0] * self.d_model for _ in range(self.seq_len)]

        # T5 式相对位置偏置：整段前向一次算好 (num_heads, T, T)，各头共用。
        self._rel_bias = (self.relative_bias.forward(self.seq_len)
                          if self.relative_bias is not None else None)

        for head in range(h):
            q_h, k_h, v_h = self.Q[head], self.K[head], self.V[head]

            # scores = Q @ K^T / sqrt(d_k)  (seq_len, seq_len)
            k_t = _transpose(k_h)  # (d_k, seq_len)
            scores = [[v * scale * self.yarn_mscale for v in row]
                      for row in _matmul(q_h, k_t)]

            # ALiBi：按「距离」加线性偏置（常数，不参与求导）
            if self.alibi:
                slope = self.alibi_slopes[head]
                for t in range(self.seq_len):
                    row = scores[t]
                    for j in range(self.seq_len):
                        if j <= t:
                            row[j] += slope * (t - j)

            # T5 式可学习相对位置偏置：加在 softmax 前的分数上；
            # 被掩码的列稍后会被置 -inf（softmax 权重为 0，梯度也自动为 0）。
            if self._rel_bias is not None:
                brow = self._rel_bias[head]
                for t in range(self.seq_len):
                    row = scores[t]
                    bt = brow[t]
                    for j in range(self.seq_len):
                        row[j] += bt[j]

            # 因果掩码：位置 t 只能看到 j <= t。屏蔽位置置 -inf，
            # softmax 后权重恰为 0；反向的 d_scores = attn * (...) 在那些位置
            # 也自动为 0，所以 backward 不需要任何额外分支。
            if self.causal or self.window is not None:
                for t in range(self.seq_len):
                    row = scores[t]
                    # 未来一律不可见；设了 window 时同样按因果处理（局部因果）
                    for j in range(t + 1, self.seq_len):
                        row[j] = float("-inf")
                    if self.window is not None:
                        # 只看最近 window 个位置：更早的也屏蔽
                        for j in range(max(0, t - self.window + 1)):
                            row[j] = float("-inf")

            # 填充位置不能当 key：所有 query 行都要屏蔽这些列
            if key_mask is not None:
                for t in range(self.seq_len):
                    row = scores[t]
                    for j in range(self.seq_len):
                        if not key_mask[j]:
                            row[j] = float("-inf")

            # softmax per row：attn 是「干净」权重，反向的 softmax 雅可比必须用它
            attn = [_softmax_row(row) for row in scores]

            # 注意力权重 dropout（训练模式且 p>0）：mask 已含 1/(1-p) 缩放。
            # 反向时梯度要乘同一个 mask——被丢掉的连接对 dV/dK/dQ 的贡献为 0。
            mask = None
            used = attn
            if self.training and self.dropout > 0.0:
                keep = 1.0 - self.dropout
                inv = 1.0 / keep
                mask = [[inv if self.rng.random() < keep else 0.0
                         for _ in range(self.seq_len)] for _ in range(self.seq_len)]
                used = [[attn[t][j] * mask[t][j] for j in range(self.seq_len)]
                        for t in range(self.seq_len)]

            # output = attn_dropped @ V  (seq_len, d_k)
            out = _matmul(used, v_h)

            self.attn_weights.append(attn)   # 干净权重（softmax 反向用）
            self.attn_dropped.append(used)   # 实际参与 attn@V 的权重
            self.attn_masks.append(mask)     # None = 本次没做 dropout
            self.head_out.append(out)

            # 拼回 d_model
            offset = head * d_k
            for t in range(self.seq_len):
                for j in range(d_k):
                    self.concat[t][offset + j] = out[t][j]

        # 输出投影
        output = _matmul(self.concat, _transpose(self.W_o))
        for t in range(self.seq_len):
            for j in range(self.d_model):
                output[t][j] += self.b_o[j]
        return output

    def backward(self, dout_seq):
        """dout_seq: (seq_len, d_model) → 返回 dx_seq: (seq_len, d_model)"""
        h = self.num_heads
        d_k = self.d_k
        d_model = self.d_model
        kv = self.kv_dim
        seq_len = self.seq_len

        # 1. d_output → d_concat (通过 W_o)
        d_concat = _matmul(dout_seq, self.W_o)  # (seq_len, d_model)

        # 前向是 output = concat @ W_o^T，即 W_o[j][i] 表示「输入 i → 输出 j」，
        # 所以 grad_W_o[j][i] = sum_t dout[t][j] * concat[t][i]，即 dout^T @ concat。
        # （数值梯度校验过：这一行与原实现一致；concat^T @ dout 会得到转置，是错的）
        grad_W_o = _matmul(_transpose(dout_seq), self.concat)
        grad_b_o = [sum(dout_seq[t][j] for t in range(seq_len)) for j in range(d_model)]

        # 2. 拆回各头
        d_head_out = []
        for head in range(h):
            offset = head * d_k
            d_h = [[d_concat[t][offset + j] for j in range(d_k)] for t in range(seq_len)]
            d_head_out.append(d_h)

        # 3. 各头分别反向传播
        dQ_list, dK_list, dV_list = [], [], []
        dbias = [] if self.relative_bias is not None else None
        for head in range(h):
            attn = self.attn_weights[head]          # 干净权重（softmax 输出）
            attn_used = self.attn_dropped[head]     # 实际参与 attn@V 的权重
            mask = self.attn_masks[head]
            V_h = self.V[head]
            Q_h = self.Q[head]
            K_h = self.K[head]
            d_out = d_head_out[head]

            dV = _matmul(_transpose(attn_used), d_out)

            # d_attn = d_out @ V^T  (seq_len, seq_len)
            d_attn = _matmul(d_out, _transpose(V_h))
            if mask is not None:
                # dropout 的直通：d(attn_dropped) → d(attn_clean) 逐元素乘 mask
                for t in range(seq_len):
                    row_d, row_m = d_attn[t], mask[t]
                    for j in range(seq_len):
                        row_d[j] *= row_m[j]


            # softmax backward: d_scores[t][j] = attn[t][j] * (d_attn[t][j] - sum_i attn[t][i] * d_attn[t][i])
            # 行内点积只依赖 t，必须提到 j 循环外面（原来每个 (t, j) 都重算一遍 → O(seq²) 冗余）
            # softmax 反向：d_soft 是对 softmax 输入（叠加了偏置的分数）的梯度，
            # 相对偏置表的梯度正是 d_soft；对 QK^T 的梯度还要再乘 1/sqrt(d_k)。
            scale = 1.0 / math.sqrt(d_k)
            d_soft = []
            for t in range(seq_len):
                row_a, row_d = attn[t], d_attn[t]
                s = sum(map(_mul, row_a, row_d))
                d_soft.append([row_a[j] * (row_d[j] - s) for j in range(seq_len)])
            if self.relative_bias is not None:
                dbias.append(d_soft)
            d_scores = [[v * scale * self.yarn_mscale for v in row]
                        for row in d_soft]

            # dQ = d_scores @ K  (seq_len, d_k)
            dQ = _matmul(d_scores, K_h)

            # dK = d_scores^T @ Q  (seq_len, d_k)
            dK = _matmul(_transpose(d_scores), Q_h)

            if self.rope:
                # 前向 q' = R·q，所以 dL/dq = R^T·dL/dq'（反向旋转）
                dQ = [self._rope_apply(dQ[t], t, -1.0) for t in range(seq_len)]
                dK = [self._rope_apply(dK[t], t, -1.0) for t in range(seq_len)]

            dQ_list.append(dQ)
            dK_list.append(dK)
            dV_list.append(dV)

        if self.relative_bias is not None:
            self.relative_bias.backward(dbias)

        # 4. 拼接各头的 dQ, dK, dV → (seq_len, d_model)
        kv = self.kv_dim
        dQ_full = [[0.0] * d_model for _ in range(seq_len)]
        dK_full = [[0.0] * kv for _ in range(seq_len)]
        dV_full = [[0.0] * kv for _ in range(seq_len)]
        share_kv = self.num_kv_heads != h
        for head in range(h):
            offset = head * d_k
            kv_off = (head // self.kv_group) * d_k
            for t in range(seq_len):
                for j in range(d_k):
                    dQ_full[t][offset + j] = dQ_list[head][t][j]
                    if share_kv:
                        # 多个 Q 头共享同一组 K/V：它们的梯度要相加
                        dK_full[t][kv_off + j] += dK_list[head][t][j]
                        dV_full[t][kv_off + j] += dV_list[head][t][j]
                    else:
                        dK_full[t][kv_off + j] = dK_list[head][t][j]
                        dV_full[t][kv_off + j] = dV_list[head][t][j]

        # 5. 通过投影矩阵反传梯度
        # 前向是 q_full = x @ W_q^T，即 W_q[b][a] 表示「输入 a → 输出 b」，
        # 所以 grad_W_q[b][a] = sum_t dQ_full[t][b] * x[t][a]，即 dQ_full^T @ x。
        # （不能写成 x^T @ dQ_full：那是正确梯度的转置，方阵下不会报错但会静默训歪）
        grad_W_q = _matmul(_transpose(dQ_full), self.x)  # (d_model, d_model)
        grad_W_k = _matmul(_transpose(dK_full), self.x)
        grad_W_v = _matmul(_transpose(dV_full), self.x)
        grad_b_q = [sum(dQ_full[t][j] for t in range(seq_len)) for j in range(d_model)]
        grad_b_k = [sum(dK_full[t][j] for t in range(seq_len)) for j in range(kv)]
        grad_b_v = [sum(dV_full[t][j] for t in range(seq_len)) for j in range(kv)]

        # d_x = dQ_full @ W_q^T + dK_full @ W_k^T + dV_full @ W_v^T
        dx_q = _matmul(dQ_full, self.W_q)
        dx_k = _matmul(dK_full, self.W_k)
        dx_v = _matmul(dV_full, self.W_v)
        dx_seq = [[dx_q[t][j] + dx_k[t][j] + dx_v[t][j] for j in range(d_model)]
                   for t in range(seq_len)]

        # 6. 累积梯度
        for i in range(self.d_model):
            for j in range(self.d_model):
                self.grads["W_q"][i][j] += grad_W_q[i][j]
                self.grads["W_o"][i][j] += grad_W_o[i][j]
            self.grads["b_q"][i] += grad_b_q[i]
            self.grads["b_o"][i] += grad_b_o[i]
        for i in range(kv):
            for j in range(self.d_model):
                self.grads["W_k"][i][j] += grad_W_k[i][j]
                self.grads["W_v"][i][j] += grad_W_v[i][j]
            self.grads["b_k"][i] += grad_b_k[i]
            self.grads["b_v"][i] += grad_b_v[i]
        return dx_seq


class FeedForward:
    """Transformer 前馈网络: Linear → 激活 → Linear

    activation 默认 "relu"（与原实现逐位一致）；"gelu" 是 GPT/LLaMA 的常用选择。
    激活只作用于中间层，输出层仍是线性。
    """

    def __init__(self, d_model: int, d_ff: int, activation: str = "relu"):
        if activation not in ("relu", "gelu", "sigmoid", "linear",
                              "silu", "mish", "elu", "selu"):
            raise ValueError(
                f"FeedForward: 不支持的激活 {activation!r}；"
                f"可选 relu/gelu/sigmoid/linear/silu/mish/elu/selu"
            )
        self.activation = activation
        self.d_model = d_model
        self.d_ff = d_ff

        std1 = math.sqrt(2.0 / d_model)
        std2 = math.sqrt(2.0 / d_ff)
        self.W1 = [[random.gauss(0, std1) for _ in range(d_model)] for _ in range(d_ff)]
        self.b1 = [0.0] * d_ff
        self.W2 = [[random.gauss(0, std2) for _ in range(d_ff)] for _ in range(d_model)]
        self.b2 = [0.0] * d_model

        self._init_adam()
        self.zero_grad()
        self.x = self.h = None  # 缓存
        self.z = None           # 非 relu 时需要留中间层线性输出

    def _init_adam(self):
        def z2(r, c):
            return [[0.0] * c for _ in range(r)]
        self.m_W1 = z2(self.d_ff, self.d_model); self.v_W1 = z2(self.d_ff, self.d_model)
        self.m_W2 = z2(self.d_model, self.d_ff); self.v_W2 = z2(self.d_model, self.d_ff)
        self.m_b1 = [0.0] * self.d_ff; self.v_b1 = [0.0] * self.d_ff
        self.m_b2 = [0.0] * self.d_model; self.v_b2 = [0.0] * self.d_model

    def zero_grad(self):
        """初始化/清零所有参数梯度"""
        self.grads = {
            "W1": [[0.0] * self.d_model for _ in range(self.d_ff)],
            "b1": [0.0] * self.d_ff,
            "W2": [[0.0] * self.d_ff for _ in range(self.d_model)],
            "b2": [0.0] * self.d_model,
        }

    def forward(self, x_seq):
        """x_seq: (seq_len, d_model)"""
        self.x = x_seq
        self.seq_len = len(x_seq)
        # W1 @ x + b1 → 激活 → W2 @ x + b2
        h = _matmul(x_seq, _transpose(self.W1))
        if self.activation == "relu":
            for t in range(self.seq_len):
                for j in range(self.d_ff):
                    h[t][j] = max(0, h[t][j] + self.b1[j])  # ReLU
        else:
            z = [[h[t][j] + self.b1[j] for j in range(self.d_ff)]
                 for t in range(self.seq_len)]
            self.z = z
            act = self._act_scalar
            for t in range(self.seq_len):
                zt, ht = z[t], h[t]
                for j in range(self.d_ff):
                    ht[j] = act(zt[j])
        self.h = h
        out = _matmul(h, _transpose(self.W2))
        for t in range(self.seq_len):
            for j in range(self.d_model):
                out[t][j] += self.b2[j]
        return out

    def _act_scalar(self, z: float) -> float:
        """中间层激活（标量版，供非 relu 路径使用）"""
        a = self.activation
        if a == "relu":
            return z if z > 0.0 else 0.0
        if a == "gelu":
            u = _GELU_C * (z + 0.044715 * z * z * z)
            return 0.5 * z * (1.0 + math.tanh(u))
        if a == "sigmoid":
            if z >= 0.0:
                return 1.0 / (1.0 + math.exp(-z))
            e = math.exp(z)
            return e / (1.0 + e)
        if a == "silu":
            return _silu_scalar(z)
        if a == "mish":
            return _mish_scalar(z)
        if a == "elu":
            return _elu_scalar(z)
        if a == "selu":
            return _selu_scalar(z)
        return z  # linear

    def _dact_scalar(self, z: float) -> float:
        """中间层激活的导数（标量版）"""
        a = self.activation
        if a == "relu":
            return 1.0 if z > 0.0 else 0.0
        if a == "gelu":
            u = _GELU_C * (z + 0.044715 * z * z * z)
            t = math.tanh(u)
            du = _GELU_C * (1.0 + 3.0 * 0.044715 * z * z)
            return 0.5 * (1.0 + t) + 0.5 * z * (1.0 - t * t) * du
        if a == "sigmoid":
            s = self._act_scalar(z)
            return s * (1.0 - s)
        if a == "silu":
            return _dsilu_scalar(z)
        if a == "mish":
            return _dmish_scalar(z)
        if a == "elu":
            return _delu_scalar(z)
        if a == "selu":
            return _dselu_scalar(z)
        return 1.0  # linear

    def backward(self, dout_seq):
        """dout_seq: (seq_len, d_model) → dx_seq: (seq_len, d_model)"""
        seq_len = self.seq_len

        # dout → W2:  dW2 = dout^T @ h  (d_model, seq_len) @ (seq_len, d_ff) = (d_model, d_ff)
        grad_W2 = _matmul(_transpose(dout_seq), self.h)
        grad_b2 = [sum(dout_seq[t][j] for t in range(seq_len)) for j in range(self.d_model)]

        # d_h = dout @ W2
        dh = _matmul(dout_seq, self.W2)  # (seq_len, d_ff)

        # 激活反向：relu 走原分支（读 h，保持逐位一致）；其它用中间层 z
        if self.activation == "relu":
            for t in range(seq_len):
                for j in range(self.d_ff):
                    if self.h[t][j] <= 0:
                        dh[t][j] = 0.0
        else:
            dact = self._dact_scalar
            z = self.z
            for t in range(seq_len):
                zt, dht = z[t], dh[t]
                for j in range(self.d_ff):
                    dht[j] *= dact(zt[j])

        # W1 backward: dW1 = dh^T @ x  (d_ff, seq_len) @ (seq_len, d_model) = (d_ff, d_model)
        grad_W1 = _matmul(_transpose(dh), self.x)
        grad_b1 = [sum(dh[t][j] for t in range(seq_len)) for j in range(self.d_ff)]

        # dx = dh @ W1
        dx_seq = _matmul(dh, self.W1)

        # 累积梯度
        for i in range(self.d_ff):
            for j in range(self.d_model):
                self.grads["W1"][i][j] += grad_W1[i][j]
            self.grads["b1"][i] += grad_b1[i]
        for i in range(self.d_model):
            for j in range(self.d_ff):
                self.grads["W2"][i][j] += grad_W2[i][j]
            self.grads["b2"][i] += grad_b2[i]
        return dx_seq



class SwiGLU:
    """门控前馈网络（LLaMA / PaLM 用的 SwiGLU）

    out = (silu(x W_g) ⊙ (x W_1)) W_2 + b_2

    与 `FeedForward` 的区别：多一路门控投影 `W_g`，两个分支逐元素相乘
    （SwiGLU = Swish-Gated Linear Unit）。表达力更强，LLaMA 用它替代 ReLU-FFN。
    d_ff 通常取 FeedForward 的 2/3 左右效果相当（这里由调用者决定）。

    `gate` 可选 `"swish"`（默认，即 SwiGLU）/ `"silu"`（同 swish）/ `"gelu"`
    （GeGLU）/ `"relu"`（ReGLU）/ `"bilinear"`（Bilinear GLU，门控就是恒等）。
    """

    #: 门控激活选择：名字 → (激活, 导数)
    GATES = ("swish", "silu", "gelu", "relu", "bilinear")

    def __init__(self, d_model: int, d_ff: int, gate: str = "swish"):
        if isinstance(d_model, bool) or not isinstance(d_model, int) or d_model < 1:
            raise ValueError(f"SwiGLU: d_model 必须是正整数，收到 {d_model!r}")
        if isinstance(d_ff, bool) or not isinstance(d_ff, int) or d_ff < 1:
            raise ValueError(f"SwiGLU: d_ff 必须是正整数，收到 {d_ff!r}")
        if not isinstance(gate, str):
            raise TypeError(f"SwiGLU: gate 必须是字符串，收到 {type(gate).__name__}")
        if gate not in SwiGLU.GATES:
            raise ValueError(
                f"SwiGLU: gate 必须是 {SwiGLU.GATES} 之一，收到 {gate!r}")
        # gate 表在 __init__ 里现查，避免依赖定义顺序（_gelu_scalar 在后面才定义）
        table = {
            "swish": (_silu_scalar, _dsilu_scalar),
            "silu": (_silu_scalar, _dsilu_scalar),
            "gelu": (_gelu_scalar, _dgelu_scalar),
            "relu": (lambda z: z if z > 0.0 else 0.0,
                     lambda z: 1.0 if z > 0.0 else 0.0),
            "bilinear": (lambda z: z, lambda z: 1.0),
        }
        self.gate = gate
        self._gate_fn, self._gate_deriv = table[gate]
        self.d_model = d_model
        self.d_ff = d_ff
        std1 = math.sqrt(2.0 / d_model)
        std2 = math.sqrt(2.0 / d_ff)
        self.W1 = [[random.gauss(0, std1) for _ in range(d_model)] for _ in range(d_ff)]
        self.b1 = [0.0] * d_ff
        self.Wg = [[random.gauss(0, std1) for _ in range(d_model)] for _ in range(d_ff)]
        self.bg = [0.0] * d_ff
        self.W2 = [[random.gauss(0, std2) for _ in range(d_ff)] for _ in range(d_model)]
        self.b2 = [0.0] * d_model
        self.training = True
        self._init_adam()
        self.zero_grad()
        self.x = self.h1 = self.g = self.zg = self.h = None
        self.seq_len = 0

    def _init_adam(self):
        def z2(r, c):
            return [[0.0] * c for _ in range(r)]
        self.m_W1 = z2(self.d_ff, self.d_model); self.v_W1 = z2(self.d_ff, self.d_model)
        self.m_Wg = z2(self.d_ff, self.d_model); self.v_Wg = z2(self.d_ff, self.d_model)
        self.m_W2 = z2(self.d_model, self.d_ff); self.v_W2 = z2(self.d_model, self.d_ff)
        self.m_b1 = [0.0] * self.d_ff; self.v_b1 = [0.0] * self.d_ff
        self.m_bg = [0.0] * self.d_ff; self.v_bg = [0.0] * self.d_ff
        self.m_b2 = [0.0] * self.d_model; self.v_b2 = [0.0] * self.d_model

    def zero_grad(self):
        """初始化/清零所有参数梯度"""
        self.grads = {
            "W1": [[0.0] * self.d_model for _ in range(self.d_ff)],
            "b1": [0.0] * self.d_ff,
            "Wg": [[0.0] * self.d_model for _ in range(self.d_ff)],
            "bg": [0.0] * self.d_ff,
            "W2": [[0.0] * self.d_ff for _ in range(self.d_model)],
            "b2": [0.0] * self.d_model,
        }

    def train(self):
        """训练模式（本模块无 dropout，接口对齐 Transformer 子模块）"""
        self.training = True
        return self

    def eval(self):
        self.training = False
        return self

    def forward(self, x_seq):
        """x_seq: (seq_len, d_model) → (seq_len, d_model)"""
        if not x_seq:
            raise ValueError("SwiGLU.forward: 输入序列为空")
        if len(x_seq[0]) != self.d_model:
            raise ValueError(
                f"SwiGLU.forward: 输入维度 {len(x_seq[0])} 与 d_model={self.d_model} 不一致")
        self.x = x_seq
        self.seq_len = len(x_seq)
        self.h1 = _matmul(x_seq, _transpose(self.W1))
        zg = _matmul(x_seq, _transpose(self.Wg))
        self.zg = zg
        gate_fn = self._gate_fn
        self.g = [[gate_fn(zg[t][j]) + self.bg[j] for j in range(self.d_ff)]
                  for t in range(self.seq_len)]
        # 门控分支的 bias 加在 silu 之后（LLaMA 无 bias，这里是通用写法）
        for t in range(self.seq_len):
            for j in range(self.d_ff):
                self.h1[t][j] += self.b1[j]
        self.h = [[self.h1[t][j] * self.g[t][j] for j in range(self.d_ff)]
                  for t in range(self.seq_len)]
        out = _matmul(self.h, _transpose(self.W2))
        for t in range(self.seq_len):
            for j in range(self.d_model):
                out[t][j] += self.b2[j]
        return out

    def backward(self, dout_seq):
        """dout_seq: (seq_len, d_model) → dx_seq: (seq_len, d_model)"""
        if self.h is None:
            raise RuntimeError("SwiGLU.backward: 必须先调用 forward()")
        T = self.seq_len
        grad_W2 = _matmul(_transpose(dout_seq), self.h)
        grad_b2 = [sum(dout_seq[t][j] for t in range(T)) for j in range(self.d_model)]
        dh = _matmul(dout_seq, self.W2)
        # 两条分支各自的梯度
        dh1 = [[dh[t][j] * self.g[t][j] for j in range(self.d_ff)] for t in range(T)]
        dg = [[dh[t][j] * self.h1[t][j] for j in range(self.d_ff)] for t in range(T)]
        # bg 是加在 silu 之后的（g = silu(z_g) + b_g），所以它的梯度不乘 silu'
        dg_pre = [row[:] for row in dg]
        # 门控分支反向：乘所选门控激活的导数（只用于 W_g 与 dx）
        gate_deriv = self._gate_deriv
        for t in range(T):
            for j in range(self.d_ff):
                dg[t][j] *= gate_deriv(self.zg[t][j])
        grad_W1 = _matmul(_transpose(dh1), self.x)
        grad_b1 = [sum(dh1[t][j] for t in range(T)) for j in range(self.d_ff)]
        grad_Wg = _matmul(_transpose(dg), self.x)
        grad_bg = [sum(dg_pre[t][j] for t in range(T)) for j in range(self.d_ff)]
        dx_seq = _matmul(dh1, self.W1)
        dx_g = _matmul(dg, self.Wg)
        for t in range(T):
            for j in range(self.d_model):
                dx_seq[t][j] += dx_g[t][j]
        # 累积梯度（与 FeedForward 一致：+= 累加，配合 zero_grad）
        for i in range(self.d_ff):
            for j in range(self.d_model):
                self.grads["W1"][i][j] += grad_W1[i][j]
                self.grads["Wg"][i][j] += grad_Wg[i][j]
            self.grads["b1"][i] += grad_b1[i]
            self.grads["bg"][i] += grad_bg[i]
        for i in range(self.d_model):
            for j in range(self.d_ff):
                self.grads["W2"][i][j] += grad_W2[i][j]
            self.grads["b2"][i] += grad_b2[i]
        return dx_seq


class MoE:
    """专家混合前馈层（Mixture of Experts）

    out_t = Σ_{e ∈ top-k} q_e · FFN_e(x_t)，其中 q 是在**被选中的专家**上做的 softmax
    （Switch/GShard 风格：路由只对被选中的专家归一化，未被选中的专家梯度为 0）。

    与 `FeedForward` 的区别：多个专家并行，每个 token 只走 top_k 条路径，
    因此参数量随专家数线性增长，计算量只按 top_k 增长。

    注意：这是一个**教学级实现**——它把 token 分组后逐专家前向，没有做批量矩阵化，
    token 数少时很快，超长序列比稠密 FFN 慢。真实的大模型实现会用 scatter/gather。
    """

    def __init__(self, d_model: int, d_ff: int, num_experts: int = 4,
                 top_k: int = 2, activation: str = "gelu"):
        for name, value in (("d_model", d_model), ("d_ff", d_ff),
                            ("num_experts", num_experts), ("top_k", top_k)):
            if isinstance(value, bool) or not isinstance(value, int) or value < 1:
                raise ValueError(f"MoE: {name} 必须是 >= 1 的整数，收到 {value!r}")
        if top_k > num_experts:
            raise ValueError(f"MoE: top_k({top_k}) 不能大于 num_experts({num_experts})")
        self.d_model = d_model
        self.d_ff = d_ff
        self.num_experts = num_experts
        self.top_k = top_k
        self.activation = activation

        self.experts = [FeedForward(d_model, d_ff, activation) for _ in range(num_experts)]
        std = math.sqrt(2.0 / d_model)
        self.W_gate = [[random.gauss(0.0, std) for _ in range(d_model)]
                       for _ in range(num_experts)]
        self.b_gate = [0.0] * num_experts

        self._init_adam()
        self.zero_grad()
        self.x = None
        self.routes = None      # 每个 token: [(expert, weight), ...]
        self.group_index = None  # 每个专家: [token 下标, ...]
        self.group_w = None

    # ---- 参数与状态
    def _named_params(self):
        for e, expert in enumerate(self.experts):
            for key in ("W1", "b1", "W2", "b2"):
                yield f"e{e}.{key}", getattr(expert, key), expert.grads[key]
        yield "W_gate", self.W_gate, self.grad_W_gate
        yield "b_gate", self.b_gate, self.grad_b_gate

    def zero_grad(self):
        for expert in self.experts:
            expert.zero_grad()
        self.grad_W_gate = _zeros_like(self.W_gate)
        self.grad_b_gate = _zeros_like(self.b_gate)

    def _init_adam(self):
        self.m = {}
        self.v = {}
        self.step_count = 0
        for expert in self.experts:
            expert._init_adam()
        self._sync_adam()

    def _sync_adam(self):
        for name, param in self._param_views():
            if self.m.get(name) is None or len(self.m[name]) != len(param):
                self.m[name] = _zeros_like(param)
                self.v[name] = _zeros_like(param)

    def _param_views(self):
        for e, expert in enumerate(self.experts):
            for key in ("W1", "b1", "W2", "b2"):
                yield f"e{e}.{key}", getattr(expert, key)
        yield "W_gate", self.W_gate
        yield "b_gate", self.b_gate

    def param_count(self):
        # W1 是 (d_ff, d_model)：行数 d_ff 才是参数行数。旧写法把
        # sum(len(row) for row in W1)（= d_ff * d_model）又乘了一次 d_model，
        # 把 W1 的参数量放大 d_model 倍（d_model=4, d_ff=6 时 405 -> 189）。
        per = len(self.experts[0].W1) * self.d_model
        per += len(self.experts[0].b1)
        per += self.d_model * len(self.experts[0].W2[0])
        per += len(self.experts[0].b2)
        return per * self.num_experts + len(self.W_gate) * self.d_model + len(self.b_gate)

    # ---- 前向
    def forward(self, x_seq):
        if not isinstance(x_seq, (list, tuple)) or not x_seq:
            raise ValueError("MoE.forward: 输入必须是非空序列")
        T = len(x_seq)
        for t, row in enumerate(x_seq):
            if not isinstance(row, (list, tuple)) or len(row) != self.d_model:
                raise ValueError(f"MoE.forward: 第 {t} 个位置维度应为 {self.d_model}")
        self.x = [list(row) for row in x_seq]

        routes = []
        for t in range(T):
            xt = self.x[t]
            logits = [sum(map(_mul, self.W_gate[e], xt)) + self.b_gate[e]
                      for e in range(self.num_experts)]
            order = sorted(range(self.num_experts), key=lambda e: -logits[e])[:self.top_k]
            picked = [logits[e] for e in order]
            probs = _softmax_row(picked)
            routes.append([(order[k], probs[k]) for k in range(self.top_k)])
        self.routes = routes

        group_index = [[] for _ in range(self.num_experts)]
        group_w = [[] for _ in range(self.num_experts)]
        group_pos = [{} for _ in range(self.num_experts)]
        for t in range(T):
            for e, w in routes[t]:
                group_pos[e][t] = len(group_index[e])
                group_index[e].append(t)
                group_w[e].append(w)
        self.group_index = group_index
        self.group_w = group_w
        self.group_pos = group_pos

        out = [[0.0] * self.d_model for _ in range(T)]
        self._last_group_out = {}
        for e in range(self.num_experts):
            idx = group_index[e]
            if not idx:
                continue
            group_out = self.experts[e].forward([self.x[t] for t in idx])
            self._last_group_out[e] = group_out
            for k, t in enumerate(idx):
                w = group_w[e][k]
                row = group_out[k]
                target = out[t]
                for j in range(self.d_model):
                    target[j] += w * row[j]
        return out

    # ---- 反向
    def backward(self, dout_seq):
        if self.x is None:
            raise RuntimeError("MoE.backward: 必须先 forward")
        T = len(self.x)
        if not isinstance(dout_seq, (list, tuple)) or len(dout_seq) != T:
            raise ValueError(f"MoE.backward: dout 长度应为 {T}")
        for t in range(T):
            if len(dout_seq[t]) != self.d_model:
                raise ValueError(f"MoE.backward: 第 {t} 行梯度维度应为 {self.d_model}")

        dx = [[0.0] * self.d_model for _ in range(T)]

        # 1) 各专家的输入梯度：dL/dout_t 乘路由权重后按组回传
        for e in range(self.num_experts):
            idx = self.group_index[e]
            if not idx:
                continue
            dgroup = []
            for k, t in enumerate(idx):
                w = self.group_w[e][k]
                dgroup.append([w * v for v in dout_seq[t]])
            dx_group = self.experts[e].backward(dgroup)
            for k, t in enumerate(idx):
                row = dx_group[k]
                for j in range(self.d_model):
                    dx[t][j] += row[j]

        # 2) 路由梯度：被选中专家的 softmax
        for t in range(T):
            route = self.routes[t]
            c = []
            for e, _w in route:
                gpos = self.group_pos[e][t]
                c.append(sum(map(_mul, dout_seq[t], self._last_group_out[e][gpos])))
            # p 已归一化在选中集合上：dz_j = p_j (c_j - Σ_k p_k c_k)
            q = [w for _e, w in route]
            base = sum(q[k] * c[k] for k in range(len(route)))
            xt = self.x[t]
            for k, (e, _w) in enumerate(route):
                dz = q[k] * (c[k] - base)
                self.grad_b_gate[e] += dz
                gw = self.grad_W_gate[e]
                for j in range(self.d_model):
                    gw[j] += dz * xt[j]
                    dx[t][j] += dz * self.W_gate[e][j]
        return dx

    # ---- 优化
    def sgd_step(self, lr: float = 0.01):
        for _name, param, grad in self._named_params():
            if isinstance(param[0], list):
                for i in range(len(param)):
                    for j in range(len(param[i])):
                        param[i][j] -= lr * grad[i][j]
            else:
                for i in range(len(param)):
                    param[i] -= lr * grad[i]

    def adam_step(self, lr: float = 1e-3, b1: float = 0.9, b2: float = 0.999,
                  eps: float = 1e-8):
        self.step_count += 1
        t = self.step_count
        for name, param, grad in self._named_params():
            _adam_apply(param, grad, self.m[name], self.v[name], t, lr, b1, b2, eps)

    def train(self):
        for expert in self.experts:
            expert.train()
        return self

    def eval(self):
        for expert in self.experts:
            expert.eval()
        return self


def _sgd_apply(param, grad, lr):
    """就地 SGD 更新参数: 支持 1D / 2D 列表（param 与 grad 结构一致）"""
    if grad and isinstance(grad[0], (list, tuple)):
        for i in range(len(param)):
            for j in range(len(param[i])):
                param[i][j] -= lr * grad[i][j]
    else:
        for i in range(len(param)):
            param[i] -= lr * grad[i]


class TransformerEncoderLayer:
    """单层 Transformer Encoder: Self-Attn + Residual + LN + FFN + Residual + LN"""

    def __init__(self, d_model: int, num_heads: int, d_ff: int, dropout: float = 0.1,
                 causal: bool = False, rope: bool = False, window: int = None,
                 num_kv_heads: int = None, alibi: bool = False):
        # causal=True 时自注意力加因果掩码（自回归语言模型用）；
        # dropout 同时作用在注意力权重（MHA 内部）和两个残差子层（dropout1/2）
        self.self_attn = MultiHeadAttention(d_model, num_heads, dropout,
                                            causal=causal, rope=rope, window=window,
                                            num_kv_heads=num_kv_heads, alibi=alibi)
        self.causal = self.self_attn.causal
        self.ffn = FeedForward(d_model, d_ff)
        self.ln1 = LayerNorm(d_model)
        self.ln2 = LayerNorm(d_model)
        self.dropout1 = Dropout(dropout)
        self.dropout2 = Dropout(dropout)

        self.zero_grad()

        # 缓存残差 及 逐 token dropout mask
        self.x = self.res1 = self.res2 = None
        self.dropout1_masks = self.dropout2_masks = None

    def train(self):
        """训练模式：注意力权重 dropout 与两个 Dropout 都生效"""
        self.self_attn.train()
        self.dropout1.train()
        self.dropout2.train()
        return self

    def eval(self):
        """推理模式：关闭全部 dropout，保证同一输入输出确定"""
        self.self_attn.eval()
        self.dropout1.eval()
        self.dropout2.eval()
        return self

    def zero_grad(self):
        """初始化/清零 LayerNorm 梯度、同时重置子模块梯度"""
        d = self.self_attn.d_model
        self.grads = {
            "ln1_gamma": [0.0] * d, "ln1_beta": [0.0] * d,
            "ln2_gamma": [0.0] * d, "ln2_beta": [0.0] * d,
        }
        self.self_attn.zero_grad()
        self.ffn.zero_grad()

    def forward_step(self, x_t, cache):
        """单 token 增量前向（推理用，eval 模式下与 forward 的最后一行逐位一致）"""
        d_model = self.self_attn.d_model
        attn_out = self.self_attn.forward_step(x_t, cache)
        res1 = [x_t[j] + attn_out[j] for j in range(d_model)]
        ln1_out = self.ln1.forward(res1)
        ffn_out = self.ffn.forward([ln1_out])[0]
        res2 = [ln1_out[j] + ffn_out[j] for j in range(d_model)]
        return self.ln2.forward(res2)

    def forward(self, x_seq, key_mask=None):
        self.x = x_seq
        d_model = self.self_attn.d_model
        # Self-Attention + Dropout1（逐 token 存储 mask）
        attn_out = self.self_attn.forward(x_seq, key_mask)
        self.dropout1_masks = []
        attn_dropped = []
        for a in attn_out:
            dropped = self.dropout1.forward(a)
            attn_dropped.append(dropped)
            self.dropout1_masks.append(list(self.dropout1.mask))
        attn_out = attn_dropped
        # Residual + LN1
        self.res1 = [[x_seq[t][j] + attn_out[t][j] for j in range(d_model)]
                      for t in range(len(x_seq))]
        ln1_out = [self.ln1.forward(v) for v in self.res1]
        # FFN + Dropout2（逐 token 存储 mask）
        ffn_out = self.ffn.forward(ln1_out)
        self.dropout2_masks = []
        ffn_dropped = []
        for f in ffn_out:
            dropped = self.dropout2.forward(f)
            ffn_dropped.append(dropped)
            self.dropout2_masks.append(list(self.dropout2.mask))
        ffn_out = ffn_dropped
        # Residual + LN2
        self.res2 = [[ln1_out[t][j] + ffn_out[t][j] for j in range(d_model)]
                      for t in range(len(x_seq))]
        return [self.ln2.forward(v) for v in self.res2]

    def backward(self, dout_seq):
        seq_len = len(self.x)
        d_model = self.self_attn.d_model

        # LN2 backward（逐 token）
        # 注意：LayerNorm 只保存「最后一次 forward」的单槽缓存，而 forward 里
        # ln2 是对每个 token 各调一次（见上面的 [self.ln2.forward(v) for v in self.res2]），
        # 缓存里只剩最后一个 token。因此这里必须先把该 token 的前向缓存重放回去，
        # 否则 token 0..T-2 会用最后一个 token 的 mean/var 反传 —— 梯度整体是错的
        # （seq_len=1 时恰好正确，所以只在小序列上看不出来）。
        d_res2 = []
        g_ln2_gamma = [0.0] * d_model; g_ln2_beta = [0.0] * d_model
        for t in range(seq_len):
            self.ln2.forward(self.res2[t])          # 重放缓存
            gg, gb, dx = self.ln2.backward(dout_seq[t])
            d_res2.append(dx)
            for j in range(d_model):
                g_ln2_gamma[j] += gg[j]
                g_ln2_beta[j] += gb[j]
        # Residual 2 的梯度分叉: 一路给 FFN，一路直通
        d_ffn = list(d_res2)
        # Dropout2 backward（逐 token 应用存储的 mask）
        if self.dropout2_masks is not None:
            d_ffn = [[d_ffn[t][j] * self.dropout2_masks[t][j]
                      for j in range(d_model)] for t in range(seq_len)]
        # FFN backward
        d_ln1 = self.ffn.backward(d_ffn)
        for t in range(seq_len):
            for j in range(d_model):
                d_ln1[t][j] += d_res2[t][j]
        # LN1 backward（逐 token）：同样要重放该 token 的缓存（原因见上面的 LN2）
        d_res1 = []
        g_ln1_gamma = [0.0] * d_model; g_ln1_beta = [0.0] * d_model
        for t in range(seq_len):
            self.ln1.forward(self.res1[t])          # 重放缓存
            gg, gb, dx = self.ln1.backward(d_ln1[t])
            d_res1.append(dx)
            for j in range(d_model):
                g_ln1_gamma[j] += gg[j]
                g_ln1_beta[j] += gb[j]
        # Residual 1: 注意力分支 和 直通分支
        d_attn = list(d_res1)
        d_x = list(d_res1)
        # Dropout1 backward（逐 token 应用存储的 mask）
        if self.dropout1_masks is not None:
            d_attn = [[d_attn[t][j] * self.dropout1_masks[t][j]
                       for j in range(d_model)] for t in range(seq_len)]
        # Self-Attn backward
        d_attn_out = self.self_attn.backward(d_attn)
        for t in range(seq_len):
            for j in range(d_model):
                d_x[t][j] += d_attn_out[t][j]

        for j in range(d_model):
            self.grads["ln1_gamma"][j] += g_ln1_gamma[j]
            self.grads["ln1_beta"][j] += g_ln1_beta[j]
            self.grads["ln2_gamma"][j] += g_ln2_gamma[j]
            self.grads["ln2_beta"][j] += g_ln2_beta[j]
        return d_x

    def sgd_step(self, lr: float):
        """用累积的梯度做一次 SGD 参数更新（self_attn / ffn / LayerNorm）"""
        attn = self.self_attn
        for name in ("W_q", "W_k", "W_v", "W_o"):
            _sgd_apply(getattr(attn, name), attn.grads[name], lr)
        for name in ("b_q", "b_k", "b_v", "b_o"):
            _sgd_apply(getattr(attn, name), attn.grads[name], lr)

        ffn = self.ffn
        _sgd_apply(ffn.W1, ffn.grads["W1"], lr)
        _sgd_apply(ffn.b1, ffn.grads["b1"], lr)
        _sgd_apply(ffn.W2, ffn.grads["W2"], lr)
        _sgd_apply(ffn.b2, ffn.grads["b2"], lr)

        _sgd_apply(self.ln1.gamma, self.grads["ln1_gamma"], lr)
        _sgd_apply(self.ln1.beta, self.grads["ln1_beta"], lr)
        _sgd_apply(self.ln2.gamma, self.grads["ln2_gamma"], lr)
        _sgd_apply(self.ln2.beta, self.grads["ln2_beta"], lr)


class TransformerEncoder:
    """堆叠多个 TransformerEncoderLayer"""

    def __init__(self, d_model: int, num_heads: int, d_ff: int,
                 num_layers: int = 6, dropout: float = 0.1, causal: bool = False,
                 rope: bool = False, window: int = None, num_kv_heads: int = None,
                 alibi: bool = False):
        """causal=True: 每层自注意力都加因果掩码（供 CausalLM 使用）"""
        self.causal = bool(causal)
        self.layers = [
            TransformerEncoderLayer(d_model, num_heads, d_ff, dropout,
                                    causal=causal, rope=rope, window=window,
                                    num_kv_heads=num_kv_heads, alibi=alibi)
            for _ in range(num_layers)
        ]

    def zero_grad(self):
        """重置所有层的梯度"""
        for layer in self.layers:
            layer.zero_grad()

    def train(self):
        """训练模式（转发给每一层）"""
        for layer in self.layers:
            layer.train()
        return self

    def eval(self):
        """推理模式（转发给每一层，关闭 Dropout）"""
        for layer in self.layers:
            layer.eval()
        return self

    def forward_step(self, x_t, caches):
        """单 token 增量前向；caches 每层一个 dict（见 MHA.forward_step）"""
        for li, layer in enumerate(self.layers):
            x_t = layer.forward_step(x_t, caches[li])
        return x_t

    def forward(self, x_seq, key_mask=None):
        for layer in self.layers:
            x_seq = layer.forward(x_seq, key_mask)
        return x_seq

    def backward(self, dout_seq):
        for layer in reversed(self.layers):
            dout_seq = layer.backward(dout_seq)
        return dout_seq

    def sgd_step(self, lr: float):
        """对每一层做一次 SGD 参数更新"""
        for layer in self.layers:
            layer.sgd_step(lr)


class CrossAttention:
    """多头交叉注意力（encoder-decoder 的 decoder 端）

    Q 来自解码器自己的序列 x_seq `(Tq, d_model)`，K/V 来自编码器输出
    memory `(Tk, d_model)`：两者长度可以不同，也不需要 causal 掩码——
    解码器对整段 memory 是全可见的。所以这里没有 causal / window / rope
    参数（位置信息由各自那侧的注入方式决定）。

    backward 返回 `(dx, dmemory)`：既要把梯度传回解码器上一层，也要传回
    编码器（多层 decoder 共享同一份 memory，各层的 dmemory 相加）。

    `delta_index = 0` 显式声明「往回传的是第 0 项」：容器（Sequential 等）
    默认取 -1，会把 dmemory 当成输入梯度，静默拿错。
    """

    delta_index = 0

    def __init__(self, d_model: int, num_heads: int, dropout: float = 0.0):
        """dropout: 交叉注意力权重上的 inverted dropout（训练模式生效）"""
        if not (0.0 <= dropout < 1.0):
            raise ValueError(
                f"CrossAttention: dropout 必须在 [0,1) 内，收到 {dropout!r}")
        if d_model % num_heads != 0:
            raise ValueError(
                f"CrossAttention: d_model={d_model} 必须能被 num_heads={num_heads} 整除")
        self.d_model = d_model
        self.num_heads = num_heads
        self.d_k = d_model // num_heads
        self.dropout = dropout
        self.training = True
        self.rng = random

        std = math.sqrt(2.0 / d_model)
        self.W_q = [[random.gauss(0, std) for _ in range(d_model)] for _ in range(d_model)]
        self.W_k = [[random.gauss(0, std) for _ in range(d_model)] for _ in range(d_model)]
        self.W_v = [[random.gauss(0, std) for _ in range(d_model)] for _ in range(d_model)]
        self.W_o = [[random.gauss(0, std) for _ in range(d_model)] for _ in range(d_model)]
        self.b_q = [0.0] * d_model
        self.b_k = [0.0] * d_model
        self.b_v = [0.0] * d_model
        self.b_o = [0.0] * d_model

        self._init_adam()
        self.zero_grad()

        self.x = None          # (Tq, d_model) 解码器侧输入
        self.memory = None     # (Tk, d_model) 编码器输出
        self.Q = self.K = self.V = None
        self.attn_weights = None
        self.attn_dropped = None
        self.attn_masks = None
        self.concat = None

    def zero_grad(self):
        """初始化/清零所有参数梯度"""
        d = self.d_model
        zeros_2d = lambda r, c: [[0.0] * c for _ in range(r)]
        self.grads = {
            "W_q": zeros_2d(d, d), "b_q": [0.0] * d,
            "W_k": zeros_2d(d, d), "b_k": [0.0] * d,
            "W_v": zeros_2d(d, d), "b_v": [0.0] * d,
            "W_o": zeros_2d(d, d), "b_o": [0.0] * d,
        }

    def _init_adam(self):
        d = self.d_model
        zeros_2d = lambda r, c: [[0.0] * c for _ in range(r)]
        self.m_W_q = zeros_2d(d, d); self.v_W_q = zeros_2d(d, d)
        self.m_W_k = zeros_2d(d, d); self.v_W_k = zeros_2d(d, d)
        self.m_W_v = zeros_2d(d, d); self.v_W_v = zeros_2d(d, d)
        self.m_W_o = zeros_2d(d, d); self.v_W_o = zeros_2d(d, d)
        self.m_b_q = [0.0] * d; self.v_b_q = [0.0] * d
        self.m_b_k = [0.0] * d; self.v_b_k = [0.0] * d
        self.m_b_v = [0.0] * d; self.v_b_v = [0.0] * d
        self.m_b_o = [0.0] * d; self.v_b_o = [0.0] * d

    def train(self):
        """训练模式：注意力权重 dropout 生效"""
        self.training = True
        return self

    def eval(self):
        """推理模式：关闭 dropout"""
        self.training = False
        return self

    def forward(self, x_seq, memory, memory_mask=None):
        """x_seq: (Tq, d_model) 解码器输入；memory: (Tk, d_model) 编码器输出

        memory_mask: 长度 Tk 的 0/1 列表，0 表示该位置是填充、不能参与注意力
        （批量训练时右填充的源序列）。
        """
        if len(x_seq) == 0:
            raise ValueError("CrossAttention: x_seq 不能为空")
        if len(memory) == 0:
            raise ValueError("CrossAttention: memory 不能为空")
        for t, row in enumerate(x_seq):
            if len(row) != self.d_model:
                raise ValueError(
                    f"CrossAttention: x_seq[{t}] 长度 {len(row)} != d_model {self.d_model}")
        for t, row in enumerate(memory):
            if len(row) != self.d_model:
                raise ValueError(
                    f"CrossAttention: memory[{t}] 长度 {len(row)} != d_model {self.d_model}")
        if memory_mask is not None:
            memory_mask = _check_pad_mask(memory_mask, len(memory), "CrossAttention")
        self.x = [list(row) for row in x_seq]
        self.memory = [list(row) for row in memory]
        tq, tk = len(x_seq), len(memory)
        d, h, d_k = self.d_model, self.num_heads, self.d_k

        q_full = _matmul(x_seq, _transpose(self.W_q))
        k_full = _matmul(memory, _transpose(self.W_k))
        v_full = _matmul(memory, _transpose(self.W_v))
        for t in range(tq):
            for j in range(d):
                q_full[t][j] += self.b_q[j]
        for t in range(tk):
            for j in range(d):
                k_full[t][j] += self.b_k[j]
                v_full[t][j] += self.b_v[j]

        self.Q, self.K, self.V = [], [], []
        for head in range(h):
            off = head * d_k
            self.Q.append([[q_full[t][off + j] for j in range(d_k)] for t in range(tq)])
            self.K.append([[k_full[t][off + j] for j in range(d_k)] for t in range(tk)])
            self.V.append([[v_full[t][off + j] for j in range(d_k)] for t in range(tk)])

        scale = 1.0 / math.sqrt(d_k)
        self.attn_weights, self.attn_dropped, self.attn_masks = [], [], []
        self.concat = [[0.0] * d for _ in range(tq)]
        keep = 1.0 - self.dropout
        inv = 1.0 / keep if keep > 0 else 1.0
        for head in range(h):
            q_h, k_h, v_h = self.Q[head], self.K[head], self.V[head]
            scores = [[v * scale for v in row] for row in _matmul(q_h, _transpose(k_h))]
            # 交叉注意力没有因果掩码：解码器位置能看到整段 memory；
            # 但批量训练时被填充的 memory 位置必须屏蔽（softmax 后权重恰为 0，
            # 反向无需额外分支）
            if memory_mask is not None:
                for t in range(tq):
                    row = scores[t]
                    for j in range(tk):
                        if not memory_mask[j]:
                            row[j] = float("-inf")
            attn = [_softmax_row(row) for row in scores]
            mask = None
            used = attn
            if self.training and self.dropout > 0.0:
                mask = [[inv if self.rng.random() < keep else 0.0 for _ in range(tk)]
                        for _ in range(tq)]
                used = [[attn[t][j] * mask[t][j] for j in range(tk)] for t in range(tq)]
            out = _matmul(used, v_h)
            self.attn_weights.append(attn)
            self.attn_dropped.append(used)
            self.attn_masks.append(mask)
            off = head * d_k
            for t in range(tq):
                for j in range(d_k):
                    self.concat[t][off + j] = out[t][j]

        output = _matmul(self.concat, _transpose(self.W_o))
        for t in range(tq):
            for j in range(d):
                output[t][j] += self.b_o[j]
        return output

    def backward(self, dout_seq):
        """dout_seq: (Tq, d_model) → (dx_seq (Tq, d_model), dmemory (Tk, d_model))"""
        tq, tk = len(self.x), len(self.memory)
        d, h, d_k = self.d_model, self.num_heads, self.d_k
        scale = 1.0 / math.sqrt(d_k)

        d_concat = _matmul(dout_seq, self.W_o)
        grad_W_o = _matmul(_transpose(dout_seq), self.concat)
        grad_b_o = [sum(dout_seq[t][j] for t in range(tq)) for j in range(d)]

        dQ_full = [[0.0] * d for _ in range(tq)]
        dK_full = [[0.0] * d for _ in range(tk)]
        dV_full = [[0.0] * d for _ in range(tk)]
        for head in range(h):
            off = head * d_k
            attn = self.attn_weights[head]
            used = self.attn_dropped[head]
            mask = self.attn_masks[head]
            V_h, Q_h, K_h = self.V[head], self.Q[head], self.K[head]
            d_out = [[d_concat[t][off + j] for j in range(d_k)] for t in range(tq)]

            dV = _matmul(_transpose(used), d_out)          # (Tk, d_k)
            d_attn = _matmul(d_out, _transpose(V_h))       # (Tq, Tk)
            if mask is not None:
                for t in range(tq):
                    row_d, row_m = d_attn[t], mask[t]
                    for j in range(tk):
                        row_d[j] *= row_m[j]
            d_scores = []
            for t in range(tq):
                row_a, row_d = attn[t], d_attn[t]
                s = sum(map(_mul, row_a, row_d))
                d_scores.append([row_a[j] * (row_d[j] - s) * scale for j in range(tk)])
            dQ = _matmul(d_scores, K_h)                     # (Tq, d_k)
            dK = _matmul(_transpose(d_scores), Q_h)         # (Tk, d_k)
            for t in range(tq):
                for j in range(d_k):
                    dQ_full[t][off + j] = dQ[t][j]
            for t in range(tk):
                for j in range(d_k):
                    dK_full[t][off + j] = dK[t][j]
                    dV_full[t][off + j] = dV[t][j]

        grad_W_q = _matmul(_transpose(dQ_full), self.x)
        grad_W_k = _matmul(_transpose(dK_full), self.memory)
        grad_W_v = _matmul(_transpose(dV_full), self.memory)
        grad_b_q = [sum(dQ_full[t][j] for t in range(tq)) for j in range(d)]
        grad_b_k = [sum(dK_full[t][j] for t in range(tk)) for j in range(d)]
        grad_b_v = [sum(dV_full[t][j] for t in range(tk)) for j in range(d)]

        dx_seq = _matmul(dQ_full, self.W_q)
        dmem_k = _matmul(dK_full, self.W_k)
        dmem_v = _matmul(dV_full, self.W_v)
        dmemory = [[dmem_k[t][j] + dmem_v[t][j] for j in range(d)] for t in range(tk)]

        for i in range(d):
            for j in range(d):
                self.grads["W_q"][i][j] += grad_W_q[i][j]
                self.grads["W_k"][i][j] += grad_W_k[i][j]
                self.grads["W_v"][i][j] += grad_W_v[i][j]
                self.grads["W_o"][i][j] += grad_W_o[i][j]
            self.grads["b_q"][i] += grad_b_q[i]
            self.grads["b_k"][i] += grad_b_k[i]
            self.grads["b_v"][i] += grad_b_v[i]
            self.grads["b_o"][i] += grad_b_o[i]
        return dx_seq, dmemory

    def sgd_step(self, lr: float):
        """用累积的梯度做一次 SGD 参数更新"""
        for name in ("W_q", "W_k", "W_v", "W_o"):
            _sgd_apply(getattr(self, name), self.grads[name], lr)
        for name in ("b_q", "b_k", "b_v", "b_o"):
            _sgd_apply(getattr(self, name), self.grads[name], lr)


class TransformerDecoderLayer:
    """单层 Transformer Decoder：因果自注意力 → 交叉注意力 → FFN

    三个子层各带「残差 + LayerNorm」：res1 = x + self_attn(x)；
    res2 = ln1 + cross_attn(ln1, memory)；res3 = ln2 + ffn(ln2)。
    结构与 TransformerEncoderLayer 保持一致（残差加的是子层输入），
    多出来的第三块是交叉注意力。
    """

    def __init__(self, d_model: int, num_heads: int, d_ff: int, dropout: float = 0.1,
                 causal: bool = True, window: int = None):
        self.self_attn = MultiHeadAttention(d_model, num_heads, dropout,
                                            causal=causal, window=window)
        self.cross_attn = CrossAttention(d_model, num_heads, dropout)
        self.ffn = FeedForward(d_model, d_ff)
        self.ln1 = LayerNorm(d_model)
        self.ln2 = LayerNorm(d_model)
        self.ln3 = LayerNorm(d_model)
        self.dropout1 = Dropout(dropout)
        self.dropout2 = Dropout(dropout)
        self.dropout3 = Dropout(dropout)
        self.d_model = d_model

        self.zero_grad()
        self.x = self.res1 = self.res2 = self.res3 = None
        self.memory = None
        self.dropout1_masks = self.dropout2_masks = self.dropout3_masks = None

    def train(self):
        """训练模式：三处 Dropout 与注意力 dropout 全部生效"""
        self.self_attn.train()
        self.cross_attn.train()
        self.dropout1.train()
        self.dropout2.train()
        self.dropout3.train()
        return self

    def eval(self):
        """推理模式：关闭全部 dropout"""
        self.self_attn.eval()
        self.cross_attn.eval()
        self.dropout1.eval()
        self.dropout2.eval()
        self.dropout3.eval()
        return self

    def zero_grad(self):
        """清零 LayerNorm 梯度，同时重置子模块梯度"""
        d = self.d_model
        self.grads = {
            "ln1_gamma": [0.0] * d, "ln1_beta": [0.0] * d,
            "ln2_gamma": [0.0] * d, "ln2_beta": [0.0] * d,
            "ln3_gamma": [0.0] * d, "ln3_beta": [0.0] * d,
        }
        self.self_attn.zero_grad()
        self.cross_attn.zero_grad()
        self.ffn.zero_grad()

    def forward(self, x_seq, memory, memory_mask=None):
        d = self.d_model
        self.x = [list(row) for row in x_seq]
        self.memory = [list(row) for row in memory]
        n = len(self.x)

        attn_out = self.self_attn.forward(self.x)
        self.dropout1_masks = []
        attn_dropped = []
        for a in attn_out:
            dropped = self.dropout1.forward(a)
            attn_dropped.append(dropped)
            self.dropout1_masks.append(list(self.dropout1.mask))
        self.res1 = [[self.x[t][j] + attn_dropped[t][j] for j in range(d)]
                     for t in range(n)]
        ln1_out = [self.ln1.forward(v) for v in self.res1]

        cross_out = self.cross_attn.forward(ln1_out, memory, memory_mask)
        self.dropout2_masks = []
        cross_dropped = []
        for c in cross_out:
            dropped = self.dropout2.forward(c)
            cross_dropped.append(dropped)
            self.dropout2_masks.append(list(self.dropout2.mask))
        self.res2 = [[ln1_out[t][j] + cross_dropped[t][j] for j in range(d)]
                     for t in range(n)]
        ln2_out = [self.ln2.forward(v) for v in self.res2]

        ffn_out = self.ffn.forward(ln2_out)
        self.dropout3_masks = []
        ffn_dropped = []
        for f in ffn_out:
            dropped = self.dropout3.forward(f)
            ffn_dropped.append(dropped)
            self.dropout3_masks.append(list(self.dropout3.mask))
        self.res3 = [[ln2_out[t][j] + ffn_dropped[t][j] for j in range(d)]
                     for t in range(n)]
        return [self.ln3.forward(v) for v in self.res3]

    def backward(self, dout_seq):
        """dout_seq: (Tq, d_model) → (dx (Tq, d_model), dmemory (Tk, d_model))"""
        n = len(self.x)
        d = self.d_model

        def ln_backward(ln, res, d_in, key):
            d_out = []
            gg = [0.0] * d
            gb = [0.0] * d
            for t in range(n):
                ln.forward(res[t])          # 重放该 token 的缓存
                g_gamma, g_beta, dx = ln.backward(d_in[t])
                d_out.append(dx)
                for j in range(d):
                    gg[j] += g_gamma[j]
                    gb[j] += g_beta[j]
            for j in range(d):
                self.grads[key + "_gamma"][j] += gg[j]
                self.grads[key + "_beta"][j] += gb[j]
            return d_out

        d_res3 = ln_backward(self.ln3, self.res3, dout_seq, "ln3")
        d_ffn = [list(row) for row in d_res3]
        if self.dropout3_masks is not None:
            d_ffn = [[d_ffn[t][j] * self.dropout3_masks[t][j] for j in range(d)]
                     for t in range(n)]
        d_ln2 = self.ffn.backward(d_ffn)
        for t in range(n):
            for j in range(d):
                d_ln2[t][j] += d_res3[t][j]

        d_res2 = ln_backward(self.ln2, self.res2, d_ln2, "ln2")
        d_cross = [list(row) for row in d_res2]
        if self.dropout2_masks is not None:
            d_cross = [[d_cross[t][j] * self.dropout2_masks[t][j] for j in range(d)]
                       for t in range(n)]
        d_ln1_cross, dmemory = self.cross_attn.backward(d_cross)
        d_ln1 = [[d_ln1_cross[t][j] + d_res2[t][j] for j in range(d)] for t in range(n)]

        d_res1 = ln_backward(self.ln1, self.res1, d_ln1, "ln1")
        d_attn = [list(row) for row in d_res1]
        if self.dropout1_masks is not None:
            d_attn = [[d_attn[t][j] * self.dropout1_masks[t][j] for j in range(d)]
                      for t in range(n)]
        d_attn_out = self.self_attn.backward(d_attn)
        d_x = [[d_res1[t][j] + d_attn_out[t][j] for j in range(d)] for t in range(n)]
        return d_x, dmemory

    def sgd_step(self, lr: float):
        """对三个子层与三个 LayerNorm 各做一次 SGD 更新"""
        attn = self.self_attn
        for name in ("W_q", "W_k", "W_v", "W_o", "b_q", "b_k", "b_v", "b_o"):
            _sgd_apply(getattr(attn, name), attn.grads[name], lr)
        cross = self.cross_attn
        for name in ("W_q", "W_k", "W_v", "W_o", "b_q", "b_k", "b_v", "b_o"):
            _sgd_apply(getattr(cross, name), cross.grads[name], lr)
        ffn = self.ffn
        for name in ("W1", "b1", "W2", "b2"):
            _sgd_apply(getattr(ffn, name), ffn.grads[name], lr)
        for ln_name, ln in (("ln1", self.ln1), ("ln2", self.ln2), ("ln3", self.ln3)):
            _sgd_apply(ln.gamma, self.grads[ln_name + "_gamma"], lr)
            _sgd_apply(ln.beta, self.grads[ln_name + "_beta"], lr)


class TransformerDecoder:
    """堆叠多个 TransformerDecoderLayer（encoder-decoder 的 decoder）"""

    def __init__(self, d_model: int, num_heads: int, d_ff: int,
                 num_layers: int = 6, dropout: float = 0.1, causal: bool = True,
                 window: int = None):
        if isinstance(num_layers, bool) or not isinstance(num_layers, int) or num_layers < 1:
            raise ValueError(
                f"TransformerDecoder: num_layers 必须是正整数，收到 {num_layers!r}")
        self.causal = bool(causal)
        self.layers = [
            TransformerDecoderLayer(d_model, num_heads, d_ff, dropout,
                                    causal=causal, window=window)
            for _ in range(num_layers)
        ]

    def zero_grad(self):
        """重置所有层的梯度"""
        for layer in self.layers:
            layer.zero_grad()

    def train(self):
        """训练模式（转发给每一层）"""
        for layer in self.layers:
            layer.train()
        return self

    def eval(self):
        """推理模式（转发给每一层）"""
        for layer in self.layers:
            layer.eval()
        return self

    def forward(self, x_seq, memory, memory_mask=None):
        for layer in self.layers:
            x_seq = layer.forward(x_seq, memory, memory_mask)
        return x_seq

    def backward(self, dout_seq):
        """返回 (dx_seq, dmemory)；各层的 dmemory 相加（共享同一份 memory）"""
        d_memory = None
        for layer in reversed(self.layers):
            dout_seq, dm = layer.backward(dout_seq)
            if d_memory is None:
                d_memory = dm
            else:
                for t in range(len(dm)):
                    for j in range(len(dm[0])):
                        d_memory[t][j] += dm[t][j]
        return dout_seq, d_memory

    def sgd_step(self, lr: float):
        """对每一层做一次 SGD 参数更新"""
        for layer in self.layers:
            layer.sgd_step(lr)


class PositionalEncoding:
    """正弦/余弦位置编码，加到输入序列上"""

    def __init__(self, d_model: int, max_len: int = 5000):
        """max_len: **初始预计算的行数（容量），不是长度上限**。

        forward 遇到更长序列时会按需扩展编码表（`_ensure_len`），不会截断。
        调大它可以提前分配、省掉运行期扩展。
        """
        self.d_model = d_model
        self.pe = [[0.0] * d_model for _ in range(max_len)]
        for pos in range(max_len):
            for i in range(0, d_model, 2):
                div = math.exp(i * -math.log(10000.0) / d_model)
                self.pe[pos][i] = math.sin(pos * div)
                if i + 1 < d_model:
                    self.pe[pos][i + 1] = math.cos(pos * div)

    def _ensure_len(self, n: int):
        """按需把位置编码表扩展到 n 行（原实现超过 max_len 会静默截断）"""
        for pos in range(len(self.pe), n):
            row = [0.0] * self.d_model
            for i in range(0, self.d_model, 2):
                div = math.exp(i * -math.log(10000.0) / self.d_model)
                row[i] = math.sin(pos * div)
                if i + 1 < self.d_model:
                    row[i + 1] = math.cos(pos * div)
            self.pe.append(row)

    def forward(self, x_seq):
        """x_seq: (seq_len, d_model) → x_seq + PE（超过 max_len 时自动扩展）"""
        for t, row in enumerate(x_seq):
            if len(row) != self.d_model:
                raise ValueError(
                    f"PositionalEncoding.forward: 第 {t} 个 token 的维度 {len(row)} "
                    f"与 d_model={self.d_model} 不一致"
                )
        self._ensure_len(len(x_seq))
        return [[x_seq[t][j] + self.pe[t][j] for j in range(self.d_model)]
                for t in range(len(x_seq))]

    def backward(self, dout_seq):
        return dout_seq  # 无参数，直通


# ============================================================================
#  Embedding / Residual / Sequential
# ============================================================================

class _SparseAttention:
    """稀疏注意力基类：只算「被允许的 (t, j) 对」，其余位置权重恒 0

    标准注意力要算 T×T 个分数，长序列下这是平方项。BigBird / Longformer /
    Reformer 的共同思路都是**事先决定哪些位置可以互相看见**，然后只在
    这个稀疏图上做 softmax：

        out_t = sum_{j in A(t)} softmax_j(q_t·k_j/sqrt(d)) v_j

    `A(t)` 就是子类的 `_allow(x_seq, T)` 返回的「第 t 个位置能看见的下标列表」。
    被排除的位置连分数都不算，softmax 归一化只在 A(t) 内进行——这和「先算完整
    再屏蔽」不同，后者要到 O(T^2) 的分数全部算完才知道该屏蔽谁。

    反向也是标准的：设 `p` 是稀疏权重矩阵（不允许的位置为 0），

        dv_j = sum_t p_tj dout_t
        dp_tj = dout_t·v_j
        ds_tj = p_tj (dp_tj - sum_s p_ts dp_ts)
        dq_t = scale * sum_j ds_tj k_j         dk_j = scale * sum_t ds_tj q_t

    被屏蔽位置 `p = 0` ⇒ `ds = 0`，自动不产生梯度，不需要额外分支。

    子类只需要实现 `_allow`：(T, d_model) 的输入 → 长度 T 的列表，第 t 项是
    t 能看见的下标列表（**必须包含 t 自己**，否则 softmax 分母为 0）。
    """

    def __init__(self, d_model: int, num_heads: int, causal: bool = False):
        if isinstance(d_model, bool) or not isinstance(d_model, int):
            raise ValueError("%s: d_model 必须是正整数，收到 %r"
                             % (type(self).__name__, d_model))
        if d_model < 1:
            raise ValueError("%s: d_model 必须 >= 1，收到 %r"
                             % (type(self).__name__, d_model))
        if isinstance(num_heads, bool) or not isinstance(num_heads, int):
            raise ValueError("%s: num_heads 必须是正整数，收到 %r"
                             % (type(self).__name__, num_heads))
        if num_heads < 1:
            raise ValueError("%s: num_heads 必须 >= 1，收到 %r"
                             % (type(self).__name__, num_heads))
        if d_model % num_heads != 0:
            raise ValueError(
                "%s: d_model=%d 必须能被 num_heads=%d 整除"
                % (type(self).__name__, d_model, num_heads))
        self.d_model = d_model
        self.num_heads = num_heads
        self.d_k = d_model // num_heads
        self.causal = bool(causal)
        std = math.sqrt(2.0 / d_model)
        self.W_q = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.W_k = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.W_v = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.W_o = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.b_q = [0.0] * d_model
        self.b_k = [0.0] * d_model
        self.b_v = [0.0] * d_model
        self.b_o = [0.0] * d_model
        self._init_adam()
        self.zero_grad()
        self.seq_len = 0
        self.x = None
        self.concat = None
        self._cache = None

    def zero_grad(self):
        """清零所有参数梯度"""
        d = self.d_model

        def zeros_2d(r, c):
            return [[0.0] * c for _ in range(r)]

        self.grads = {
            "W_q": zeros_2d(d, d), "b_q": [0.0] * d,
            "W_k": zeros_2d(d, d), "b_k": [0.0] * d,
            "W_v": zeros_2d(d, d), "b_v": [0.0] * d,
            "W_o": zeros_2d(d, d), "b_o": [0.0] * d,
        }

    def _init_adam(self):
        d = self.d_model
        for name in ("W_q", "W_k", "W_v", "W_o"):
            setattr(self, "m_" + name, [[0.0] * d for _ in range(d)])
            setattr(self, "v_" + name, [[0.0] * d for _ in range(d)])
        for name in ("b_q", "b_k", "b_v", "b_o"):
            setattr(self, "m_" + name, [0.0] * d)
            setattr(self, "v_" + name, [0.0] * d)
        self._adam_t = 0

    def train(self):
        """稀疏注意力没有 dropout，空操作（保持接口统一）"""
        return self

    def eval(self):
        """稀疏注意力没有 dropout，空操作（保持接口统一）"""
        return self

    def _allow(self, x_seq, T):
        """子类返回：长度 T 的列表，第 t 项是 t 能看见的下标（必须含 t）"""
        raise NotImplementedError("%s: 必须实现 _allow" % (type(self).__name__,))

    def _proj(self, W, b, x_t):
        return [sum(map(_mul, W[r], x_t)) + b[r] for r in range(self.d_model)]

    def _check_allow(self, allow, T):
        """校验子类产出的稀疏模式（含 t 自己、下标合法、去重有序）"""
        who = type(self).__name__
        if not isinstance(allow, list) or len(allow) != T:
            raise ValueError("%s._allow: 必须返回长度 %d 的列表，收到 %r"
                             % (who, T, allow))
        for t in range(T):
            idx = allow[t]
            if not idx:
                raise ValueError("%s._allow: 第 %d 个位置没有任何可见位置" % (who, t))
            if t not in idx:
                raise ValueError("%s._allow: 第 %d 个位置的可见集合必须包含自己"
                                 % (who, t))
            for j in idx:
                if isinstance(j, bool) or not isinstance(j, int):
                    raise ValueError("%s._allow: 下标必须是整数，收到 %r" % (who, j))
                if j < 0 or j >= T:
                    raise ValueError("%s._allow: 下标 %d 越界（T=%d）" % (who, j, T))
        return allow

    def forward(self, x_seq):
        """x_seq: (T, d_model) → (T, d_model)"""
        who = type(self).__name__
        if not x_seq:
            raise ValueError("%s.forward: 输入序列不能为空" % who)
        d = self.d_model
        for t, row in enumerate(x_seq):
            if len(row) != d:
                raise ValueError(
                    "%s.forward: 第 %d 个 token 的维度 %d 与 d_model=%d 不一致"
                    % (who, t, len(row), d))
        T = len(x_seq)
        q_all = [self._proj(self.W_q, self.b_q, xt) for xt in x_seq]
        k_all = [self._proj(self.W_k, self.b_k, xt) for xt in x_seq]
        v_all = [self._proj(self.W_v, self.b_v, xt) for xt in x_seq]
        allow = self._check_allow(self._allow(x_seq, T), T)
        d_k = self.d_k
        scale = 1.0 / math.sqrt(d_k)
        concat = [[0.0] * d for _ in range(T)]
        cache = []
        for head in range(self.num_heads):
            off = head * d_k
            qh = [q_all[t][off:off + d_k] for t in range(T)]
            kh = [k_all[t][off:off + d_k] for t in range(T)]
            vh = [v_all[t][off:off + d_k] for t in range(T)]
            p = [[0.0] * T for _ in range(T)]
            outs = []
            for t in range(T):
                idx = allow[t]
                qt = qh[t]
                scores = []
                for j in idx:
                    kj = kh[j]
                    acc = 0.0
                    for r in range(d_k):
                        acc += qt[r] * kj[r]
                    scores.append(acc * scale)
                mx = max(scores)
                ex = [math.exp(sc - mx) for sc in scores]
                tot = 0.0
                for e in ex:
                    tot += e
                prow = p[t]
                for pos, j in enumerate(idx):
                    prow[j] = ex[pos] / tot
                out = []
                for r in range(d_k):
                    acc = 0.0
                    for pos, j in enumerate(idx):
                        acc += prow[j] * vh[j][r]
                    out.append(acc)
                outs.append(out)
            for t in range(T):
                for r in range(d_k):
                    concat[t][off + r] = outs[t][r]
            cache.append({"q": qh, "k": kh, "v": vh, "p": p, "allow": allow})
        y = [[sum(map(_mul, self.W_o[r], concat[t])) + self.b_o[r] for r in range(d)]
             for t in range(T)]
        self.seq_len = T
        self.x = [list(row) for row in x_seq]
        self.concat = concat
        self._cache = cache
        return y

    def backward(self, dout_seq):
        """dout_seq: (T, d_model) → (T, d_model) 输入梯度"""
        who = type(self).__name__
        if self._cache is None:
            raise RuntimeError("%s.backward: 必须先 forward" % who)
        if len(dout_seq) != self.seq_len:
            raise ValueError(
                "%s.backward: dout 长度 %d 与 forward 的 %d 不一致"
                % (who, len(dout_seq), self.seq_len))
        d = self.d_model
        T = self.seq_len
        d_k = self.d_k
        scale = 1.0 / math.sqrt(d_k)
        dconcat = [[sum(dout_seq[t][j] * self.W_o[j][r] for j in range(d))
                    for r in range(d)] for t in range(T)]
        for r in range(d):
            wrow = self.grads["W_o"][r]
            sb = 0.0
            for t in range(T):
                dt = dout_seq[t][r]
                sb += dt
                if dt == 0.0:
                    continue
                crow = self.concat[t]
                for c in range(d):
                    wrow[c] += dt * crow[c]
            self.grads["b_o"][r] += sb
        dq_all = [[0.0] * d for _ in range(T)]
        dk_all = [[0.0] * d for _ in range(T)]
        dv_all = [[0.0] * d for _ in range(T)]
        for head in range(self.num_heads):
            off = head * d_k
            c = self._cache[head]
            qh, kh, vh, p, allow = c["q"], c["k"], c["v"], c["p"], c["allow"]
            dqh = [[0.0] * d_k for _ in range(T)]
            dkh = [[0.0] * d_k for _ in range(T)]
            dvh = [[0.0] * d_k for _ in range(T)]
            ds = [[0.0] * T for _ in range(T)]
            for t in range(T):
                dout = dconcat[t][off:off + d_k]
                prow = p[t]
                idx = allow[t]
                dp = {}
                tot = 0.0
                for j in idx:
                    pj = prow[j]
                    if pj == 0.0:
                        continue
                    vj = vh[j]
                    acc = 0.0
                    for r in range(d_k):
                        acc += dout[r] * vj[r]
                    dp[j] = acc
                    tot += pj * acc
                dsrow = ds[t]
                for j in idx:
                    pj = prow[j]
                    if pj == 0.0:
                        continue
                    dsrow[j] = pj * (dp[j] - tot)
            # dv 只依赖「权重 p」，与 ds 是否为 0 无关：
            # causal 下 t=0 只有一个可见位置，ds 恒为 0，但 dv 仍然非零。
            for t in range(T):
                prow = p[t]
                dout = dconcat[t][off:off + d_k]
                for j in allow[t]:
                    pj = prow[j]
                    if pj == 0.0:
                        continue
                    dvj = dvh[j]
                    for r in range(d_k):
                        dvj[r] += pj * dout[r]
            for t in range(T):
                dsrow = ds[t]
                kj_all = kh
                dqt = dqh[t]
                for j in allow[t]:
                    g = dsrow[j]
                    if g == 0.0:
                        continue
                    kj = kj_all[j]
                    for r in range(d_k):
                        dqt[r] += scale * g * kj[r]
            for t in range(T):
                qt = qh[t]
                for j in allow[t]:
                    g = ds[t][j]
                    if g == 0.0:
                        continue
                    dkt = dkh[j]
                    for r in range(d_k):
                        dkt[r] += scale * g * qt[r]
            for t in range(T):
                for r in range(d_k):
                    dq_all[t][off + r] = dqh[t][r]
                    dk_all[t][off + r] = dkh[t][r]
                    dv_all[t][off + r] = dvh[t][r]
        for r in range(d):
            wq = self.grads["W_q"][r]
            wk = self.grads["W_k"][r]
            wv = self.grads["W_v"][r]
            sbq = sbk = sbv = 0.0
            for t in range(T):
                xt = self.x[t]
                dqr = dq_all[t][r]
                dkr = dk_all[t][r]
                dvr = dv_all[t][r]
                sbq += dqr
                sbk += dkr
                sbv += dvr
                if dqr != 0.0:
                    for cc in range(d):
                        wq[cc] += dqr * xt[cc]
                if dkr != 0.0:
                    for cc in range(d):
                        wk[cc] += dkr * xt[cc]
                if dvr != 0.0:
                    for cc in range(d):
                        wv[cc] += dvr * xt[cc]
            self.grads["b_q"][r] += sbq
            self.grads["b_k"][r] += sbk
            self.grads["b_v"][r] += sbv
        dx = [[0.0] * d for _ in range(T)]
        for t in range(T):
            xrow = dx[t]
            for r in range(d):
                dqr = dq_all[t][r]
                dkr = dk_all[t][r]
                dvr = dv_all[t][r]
                if dqr == 0.0 and dkr == 0.0 and dvr == 0.0:
                    continue
                wq = self.W_q[r]
                wk = self.W_k[r]
                wv = self.W_v[r]
                for cc in range(d):
                    xrow[cc] += dqr * wq[cc] + dkr * wk[cc] + dvr * wv[cc]
        return dx

    def param_count(self):
        """参数量：四个 d×d 投影 + 四个 d 维偏置（稀疏模式本身不带参数）"""
        d = self.d_model
        return 4 * d * d + 4 * d

    def sgd_step(self, lr: float):
        """SGD 更新"""
        lr = _la_check_lr(lr, "%s.sgd_step" % type(self).__name__)
        for name in ("W_q", "W_k", "W_v", "W_o"):
            _la_apply_sgd(getattr(self, name), self.grads[name], lr)
        for name in ("b_q", "b_k", "b_v", "b_o"):
            param = getattr(self, name)
            grad = self.grads[name]
            for i in range(len(param)):
                param[i] -= lr * grad[i]

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        """Adam 更新"""
        who = "%s.adam_step" % type(self).__name__
        lr = _la_check_lr(lr, who)
        _check_adam_betas(beta1, beta2, who)
        self._adam_t += 1
        t = self._adam_t
        c1 = 1.0 - beta1 ** t
        c2 = 1.0 - beta2 ** t
        for name in ("W_q", "W_k", "W_v", "W_o"):
            _la_apply_adam(getattr(self, name), self.grads[name],
                           getattr(self, "m_" + name), getattr(self, "v_" + name),
                           lr, c1, c2, beta1, beta2, eps)
        for name in ("b_q", "b_k", "b_v", "b_o"):
            param = getattr(self, name)
            grad = self.grads[name]
            m = getattr(self, "m_" + name)
            v = getattr(self, "v_" + name)
            for i in range(len(param)):
                g = grad[i]
                m[i] = beta1 * m[i] + (1.0 - beta1) * g
                v[i] = beta2 * v[i] + (1.0 - beta2) * g * g
                param[i] -= lr * (m[i] / c1) / (math.sqrt(v[i] / c2) + eps)


class BigBirdAttention(_SparseAttention):
    """BigBird 稀疏注意力（Beltagy et al. 2020）：三种连接拼起来

    每个位置 t 只能看见三类位置：

    * **窗口**：`[t-w, t+w]` 内的邻居，负责局部语法
    * **全局**：固定的前 `num_global` 个 token（默认 `[0]`，常放 `[CLS]`），
      所有位置都能看见它们，它们也能看见所有位置——这是「用 O(T) 条边
      换到全局可达性」的关键
    * **随机**：每个位置再随机连 `num_random` 个位置，让信息有机会跳过
      中间层（论文里这一步把理论上的表达能力补回来）

    稀疏模式由 `seed` 决定，`forward` 里用 `random.Random(seed + T)` 现算并缓存，
    反向复用同一份（随机连边是不可导的离散结构，梯度只走注意力权重）。
    `causal=True` 时再把 `j > t` 全部去掉（自回归场景）。
    """

    def __init__(self, d_model: int, num_heads: int, window_size: int = 2,
                 num_global: int = 1, num_random: int = 1,
                 causal: bool = False, seed: int = 0):
        super(BigBirdAttention, self).__init__(d_model, num_heads, causal)
        for name, val in (("window_size", window_size), ("num_global", num_global),
                          ("num_random", num_random)):
            if isinstance(val, bool) or not isinstance(val, int):
                raise ValueError("BigBirdAttention: %s 必须是非负整数，收到 %r"
                                 % (name, val))
            if val < 0:
                raise ValueError("BigBirdAttention: %s 必须 >= 0，收到 %r"
                                 % (name, val))
        if num_global < 0:
            raise ValueError("BigBirdAttention: num_global 不能为负")
        if isinstance(seed, bool) or not isinstance(seed, int):
            raise ValueError("BigBirdAttention: seed 必须是整数，收到 %r" % (seed,))
        self.window_size = window_size
        self.num_global = num_global
        self.num_random = num_random
        self.seed = seed

    def _allow(self, x_seq, T):
        """窗口 + 全局 + 随机三类连接"""
        rng = random.Random(self.seed * 1000003 + T)
        glob = list(range(min(self.num_global, T)))
        allow = []
        for t in range(T):
            seen = set()
            lo = t - self.window_size
            hi = t + self.window_size
            if lo < 0:
                lo = 0
            if hi > T - 1:
                hi = T - 1
            for j in range(lo, hi + 1):
                seen.add(j)
            for g in glob:
                seen.add(g)
            for _ in range(self.num_random):
                seen.add(rng.randrange(T))
            if self.causal:
                seen = set(j for j in seen if j <= t)
            seen.add(t)
            allow.append(sorted(seen))
        return allow


class LongformerAttention(_SparseAttention):
    """Longformer 稀疏注意力（Beltagy et al. 2020）：滑窗 + 全局 token

    和 BigBird 的区别是「随机连边」换成「由调用方指定的全局 token」：

    * 普通位置只看窗口 `[t-w, t+w]` 与全部全局 token
    * 全局 token（默认 `[0]`）看所有位置

    这样一段长文本里可以把问题句、标题等少数位置标成全局，信息就能跨
    整个序列传播，而注意力代价仍是 O(T·w)。`causal=True` 时普通位置只看
    `j <= t`，但**全局 token 仍能看见整条序列**（它们本来就是摘要位）。
    """

    def __init__(self, d_model: int, num_heads: int, window_size: int = 2,
                 global_tokens=None, causal: bool = False):
        super(LongformerAttention, self).__init__(d_model, num_heads, causal)
        if isinstance(window_size, bool) or not isinstance(window_size, int):
            raise ValueError("LongformerAttention: window_size 必须是整数，收到 %r"
                             % (window_size,))
        if window_size < 0:
            raise ValueError("LongformerAttention: window_size 必须 >= 0，收到 %r"
                             % (window_size,))
        if global_tokens is None:
            global_tokens = [0]
        if isinstance(global_tokens, int) and not isinstance(global_tokens, bool):
            global_tokens = list(range(global_tokens))
        if not isinstance(global_tokens, (list, tuple)):
            raise ValueError("LongformerAttention: global_tokens 必须是下标列表，收到 %r"
                             % (global_tokens,))
        idx = []
        for g in global_tokens:
            if isinstance(g, bool) or not isinstance(g, int):
                raise ValueError("LongformerAttention: 全局 token 下标必须是整数，收到 %r"
                                 % (g,))
            if g < 0:
                raise ValueError("LongformerAttention: 全局 token 下标不能为负，收到 %r"
                                 % (g,))
            idx.append(g)
        self.window_size = window_size
        self.global_tokens = sorted(set(idx))

    def _allow(self, x_seq, T):
        """滑窗 + 全局 token"""
        glob = [g for g in self.global_tokens if g < T]
        if not glob:
            glob = [0]
        gset = set(glob)
        allow = []
        for t in range(T):
            seen = set(glob)
            lo = t - self.window_size
            hi = t + self.window_size
            if lo < 0:
                lo = 0
            if hi > T - 1:
                hi = T - 1
            for j in range(lo, hi + 1):
                seen.add(j)
            if self.causal and t not in gset:
                seen = set(j for j in seen if j <= t or j in gset)
            if t in gset:
                # 全局 token 的特殊之处：它能看见整条序列（包括未来的位置），
                # 这样信息才能一步跨过整个窗口半径。
                seen = set(range(T))
            seen.add(t)
            allow.append(sorted(seen))
        return allow


class ReformerAttention(_SparseAttention):
    """Reformer 的 LSH 注意力（Kitaev et al. 2020）：只和同桶位置算注意力

    做法是**用随机投影给每个位置分桶**，然后只在桶内做注意力：

        h_t = argmax_r (R x_t)_r          # R 是固定的随机投影
        A(t) = {j : h_j = h_t, j <= t (causal)}

    理想情况下「q·k 大」的位置会落进同一个桶，于是桶内 softmax 能近似
    全局 softmax，但每个位置只跟桶内 ~T/num_buckets 个位置交互，代价从
    O(T^2) 降到 O(T^2/num_buckets)。

    两个简化（都写进文档，不藏）：

    1. 真实的 LSH 用「多轮哈希 + 取众数」找最近邻桶，这里用单次随机投影
       的 argmax，桶内成员的语义相关性弱一些；
    2. 分桶是离散操作，**梯度只走注意力权重**，不经过 `R`（这与原论文一致）。

    空桶不会出现（每个位置至少和自己同桶）。
    """

    def __init__(self, d_model: int, num_heads: int, num_buckets: int = 2,
                 causal: bool = False, seed: int = 0):
        super(ReformerAttention, self).__init__(d_model, num_heads, causal)
        if isinstance(num_buckets, bool) or not isinstance(num_buckets, int):
            raise ValueError("ReformerAttention: num_buckets 必须是正整数，收到 %r"
                             % (num_buckets,))
        if num_buckets < 1:
            raise ValueError("ReformerAttention: num_buckets 必须 >= 1，收到 %r"
                             % (num_buckets,))
        if isinstance(seed, bool) or not isinstance(seed, int):
            raise ValueError("ReformerAttention: seed 必须是整数，收到 %r" % (seed,))
        self.num_buckets = num_buckets
        self.seed = seed
        rng = random.Random(seed * 1000003 + d_model * 31 + num_buckets)
        self.hash_proj = [[rng.gauss(0.0, 1.0 / math.sqrt(d_model))
                           for _ in range(d_model)] for _ in range(num_buckets)]
        self._buckets = None
        self._buckets_len = 0

    def _bucketize(self, x_seq):
        """用固定的随机投影把每个位置分到 num_buckets 个桶之一"""
        buckets = []
        for t, row in enumerate(x_seq):
            best = 0
            best_val = None
            for r, wrow in enumerate(self.hash_proj):
                acc = 0.0
                for c in range(len(row)):
                    acc += wrow[c] * row[c]
                if best_val is None or acc > best_val:
                    best_val = acc
                    best = r
            buckets.append(best)
        self._buckets = buckets
        self._buckets_len = len(buckets)
        return buckets

    def _allow(self, x_seq, T):
        """同桶 + （causal 时）j <= t"""
        buckets = self._bucketize(x_seq)
        allow = []
        for t in range(T):
            b = buckets[t]
            seen = [j for j in range(T) if buckets[j] == b]
            if self.causal:
                seen = [j for j in seen if j <= t]
            if t not in seen:
                seen.append(t)
            allow.append(sorted(set(seen)))
        return allow


class FlashAttention(_SparseAttention):
    """FlashAttention 的分块 + 在线 softmax（Dao et al. 2022）

    **先说清楚：在纯 Python 里它不会更快，反而更慢。** 这里实现的是算法的
    *数据流*——把 `softmax(QK^T)V` 拆成若干块，边扫边归一化，从而**不需要
    物化 T×T 的注意力矩阵**。真实 GPU 上的收益来自「矩阵块常驻 SRAM、
    减少 HBM 往返」，纯 Python 的循环开销远大于省下的内存访问，所以
    这里的价值是「把算法讲对、并且能验证」，不是加速。

    核心是「在线 softmax」：设已经扫过的键块给出的行最大值为 `m`、指数和为
    `l`、未归一化输出为 `acc`，遇到新块时

        m_new = max(m, rowmax(S_block))
        acc  *= exp(m - m_new)          # 把旧累积量按新最大值重新缩放
        l    *= exp(m - m_new)
        p     = exp(S_block - m_new)
        l    += rowsum(p)
        acc  += p @ V_block

    扫完后 `out = acc / l`。数值上它和稠密 softmax 只差**求和顺序**，
    所以不是逐位相同（实测相对差 ~1e-16 量级），这一点在文档里如实写。

    反向不保存 T×T 概率矩阵，而是用缓存的 `(m, l)` **重算**每个块的 `p`
    ——这正是原论文「backward 重算」的做法：

        dv_j = sum_i p_ij dout_i
        dp_ij = dout_i·v_j
        ds_ij = p_ij (dp_ij - sum_j p_ij dp_ij)
        dq_i = scale * sum_j ds_ij k_j      dk_j = scale * sum_i ds_ij q_i

    `block_size` 只影响内存占用与求和顺序，不影响数学结果。
    """

    def __init__(self, d_model: int, num_heads: int, causal: bool = False,
                 block_size: int = 2):
        super(FlashAttention, self).__init__(d_model, num_heads, causal)
        if isinstance(block_size, bool) or not isinstance(block_size, int):
            raise ValueError("FlashAttention: block_size 必须是正整数，收到 %r"
                             % (block_size,))
        if block_size < 1:
            raise ValueError("FlashAttention: block_size 必须 >= 1，收到 %r"
                             % (block_size,))
        self.block_size = block_size

    def _allow(self, x_seq, T):
        """FlashAttention 不稀疏：全连通（causal 时下三角）"""
        if self.causal:
            return [list(range(t + 1)) for t in range(T)]
        return [list(range(T)) for _ in range(T)]

    def forward(self, x_seq):
        """分块 + 在线 softmax，不物化 T×T"""
        who = 'FlashAttention'
        if not x_seq:
            raise ValueError("%s.forward: 输入序列不能为空" % who)
        d = self.d_model
        for t, row in enumerate(x_seq):
            if len(row) != d:
                raise ValueError(
                    "%s.forward: 第 %d 个 token 的维度 %d 与 d_model=%d 不一致"
                    % (who, t, len(row), d))
        T = len(x_seq)
        q_all = [self._proj(self.W_q, self.b_q, xt) for xt in x_seq]
        k_all = [self._proj(self.W_k, self.b_k, xt) for xt in x_seq]
        v_all = [self._proj(self.W_v, self.b_v, xt) for xt in x_seq]
        d_k = self.d_k
        scale = 1.0 / math.sqrt(d_k)
        bs = self.block_size
        concat = [[0.0] * d for _ in range(T)]
        cache = []
        for head in range(self.num_heads):
            off = head * d_k
            qh = [q_all[t][off:off + d_k] for t in range(T)]
            kh = [k_all[t][off:off + d_k] for t in range(T)]
            vh = [v_all[t][off:off + d_k] for t in range(T)]
            m_row = [0.0] * T
            l_row = [1.0] * T
            for qs in range(0, T, bs):
                qe = min(qs + bs, T)
                rows = list(range(qs, qe))
                nb = len(rows)
                m = [float('-inf')] * nb
                l = [0.0] * nb
                acc = [[0.0] * d_k for _ in range(nb)]
                if self.causal:
                    ks_end = qe
                else:
                    ks_end = T
                for ks in range(0, ks_end, bs):
                    ke = min(ks + bs, ks_end)
                    keys = list(range(ks, ke))
                    nk = len(keys)
                    # 本块分数
                    sblk = []
                    for a, qi in enumerate(rows):
                        qt = qh[qi]
                        srow = []
                        for kb in range(nk):
                            kj = kh[keys[kb]]
                            acc2 = 0.0
                            for r in range(d_k):
                                acc2 += qt[r] * kj[r]
                            sc = acc2 * scale
                            if self.causal and keys[kb] > qi:
                                sc = float('-inf')
                            srow.append(sc)
                        sblk.append(srow)
                    # 在线更新
                    for a in range(nb):
                        srow = sblk[a]
                        finite = [v for v in srow if v != float('-inf')]
                        if not finite:
                            continue
                        rowmax = max(finite)
                        m_new = m[a] if m[a] > rowmax else rowmax
                        corr = math.exp(m[a] - m_new) if m[a] != float('-inf') else 0.0
                        if corr != 1.0:
                            l[a] *= corr
                            accrow = acc[a]
                            for r in range(d_k):
                                accrow[r] *= corr
                        m[a] = m_new
                        accrow = acc[a]
                        for kb in range(nk):
                            sc = srow[kb]
                            if sc == float('-inf'):
                                continue
                            pv = math.exp(sc - m_new)
                            l[a] += pv
                            vj = vh[keys[kb]]
                            for r in range(d_k):
                                accrow[r] += pv * vj[r]
                for a, qi in enumerate(rows):
                    m_row[qi] = m[a]
                    l_row[qi] = l[a]
                    denom = l[a] if l[a] != 0.0 else 1.0
                    for r in range(d_k):
                        concat[qi][off + r] = acc[a][r] / denom
            cache.append({"q": qh, "k": kh, "v": vh,
                          "m": m_row, "l": l_row})
        y = [[sum(map(_mul, self.W_o[r], concat[t])) + self.b_o[r] for r in range(d)]
             for t in range(T)]
        self.seq_len = T
        self.x = [list(row) for row in x_seq]
        self.concat = concat
        self._cache = cache
        return y

    def backward(self, dout_seq):
        """用缓存的 (m, l) 逐块**重算** p，不保存 T×T"""
        who = 'FlashAttention'
        if self._cache is None:
            raise RuntimeError("%s.backward: 必须先 forward" % who)
        if len(dout_seq) != self.seq_len:
            raise ValueError(
                "%s.backward: dout 长度 %d 与 forward 的 %d 不一致"
                % (who, len(dout_seq), self.seq_len))
        d = self.d_model
        T = self.seq_len
        d_k = self.d_k
        scale = 1.0 / math.sqrt(d_k)
        bs = self.block_size
        dconcat = [[sum(dout_seq[t][j] * self.W_o[j][r] for j in range(d))
                    for r in range(d)] for t in range(T)]
        for r in range(d):
            wrow = self.grads["W_o"][r]
            sb = 0.0
            for t in range(T):
                dt = dout_seq[t][r]
                sb += dt
                if dt == 0.0:
                    continue
                crow = self.concat[t]
                for c in range(d):
                    wrow[c] += dt * crow[c]
            self.grads["b_o"][r] += sb
        dq_all = [[0.0] * d for _ in range(T)]
        dk_all = [[0.0] * d for _ in range(T)]
        dv_all = [[0.0] * d for _ in range(T)]
        for head in range(self.num_heads):
            off = head * d_k
            c = self._cache[head]
            qh, kh, vh = c["q"], c["k"], c["v"]
            m_row, l_row = c["m"], c["l"]
            dqh = [[0.0] * d_k for _ in range(T)]
            dkh = [[0.0] * d_k for _ in range(T)]
            dvh = [[0.0] * d_k for _ in range(T)]
            for qs in range(0, T, bs):
                qe = min(qs + bs, T)
                rows = list(range(qs, qe))
                ks_end = qe if self.causal else T
                # 第一遍：把 tot_i = sum_j p_ij dp_ij 跨**所有**键块累加起来。
                # （原来算在单个键块里，单块时恰好对，多块就漏了其它块。）
                tot_row = [0.0] * len(rows)
                for ks in range(0, ks_end, bs):
                    ke = min(ks + bs, ks_end)
                    keys = list(range(ks, ke))
                    for a, qi in enumerate(rows):
                        qt = qh[qi]
                        mi = m_row[qi]
                        li = l_row[qi] if l_row[qi] != 0.0 else 1.0
                        dout = dconcat[qi][off:off + d_k]
                        acc_tot = 0.0
                        for kj in keys:
                            if self.causal and kj > qi:
                                continue
                            kvec = kh[kj]
                            acc2 = 0.0
                            for r in range(d_k):
                                acc2 += qt[r] * kvec[r]
                            pv = math.exp(acc2 * scale - mi) / li
                            if pv == 0.0:
                                continue
                            dp = 0.0
                            vj = vh[kj]
                            for r in range(d_k):
                                dp += dout[r] * vj[r]
                            acc_tot += pv * dp
                        tot_row[a] += acc_tot
                # 第二遍：逐块重算 p，用全局 tot 算 ds 并累加梯度
                for ks in range(0, ks_end, bs):
                    ke = min(ks + bs, ks_end)
                    keys = list(range(ks, ke))
                    for a, qi in enumerate(rows):
                        qt = qh[qi]
                        mi = m_row[qi]
                        li = l_row[qi] if l_row[qi] != 0.0 else 1.0
                        dout = dconcat[qi][off:off + d_k]
                        dqt = dqh[qi]
                        tot = tot_row[a]
                        for kb in range(len(keys)):
                            kj = keys[kb]
                            if self.causal and kj > qi:
                                continue
                            kvec = kh[kj]
                            acc2 = 0.0
                            for r in range(d_k):
                                acc2 += qt[r] * kvec[r]
                            pv = math.exp(acc2 * scale - mi) / li
                            if pv == 0.0:
                                continue
                            vj = vh[kj]
                            dvj = dvh[kj]
                            for r in range(d_k):
                                dvj[r] += pv * dout[r]
                            dp = 0.0
                            for r in range(d_k):
                                dp += dout[r] * vj[r]
                            ds = pv * (dp - tot)
                            if ds == 0.0:
                                continue
                            for r in range(d_k):
                                dqt[r] += scale * ds * kvec[r]
                            dkt = dkh[kj]
                            for r in range(d_k):
                                dkt[r] += scale * ds * qt[r]
            for t in range(T):
                for r in range(d_k):
                    dq_all[t][off + r] = dqh[t][r]
                    dk_all[t][off + r] = dkh[t][r]
                    dv_all[t][off + r] = dvh[t][r]
        for r in range(d):
            wq = self.grads["W_q"][r]
            wk = self.grads["W_k"][r]
            wv = self.grads["W_v"][r]
            sbq = sbk = sbv = 0.0
            for t in range(T):
                xt = self.x[t]
                dqr = dq_all[t][r]
                dkr = dk_all[t][r]
                dvr = dv_all[t][r]
                sbq += dqr
                sbk += dkr
                sbv += dvr
                if dqr != 0.0:
                    for cc in range(d):
                        wq[cc] += dqr * xt[cc]
                if dkr != 0.0:
                    for cc in range(d):
                        wk[cc] += dkr * xt[cc]
                if dvr != 0.0:
                    for cc in range(d):
                        wv[cc] += dvr * xt[cc]
            self.grads["b_q"][r] += sbq
            self.grads["b_k"][r] += sbk
            self.grads["b_v"][r] += sbv
        dx = [[0.0] * d for _ in range(T)]
        for t in range(T):
            xrow = dx[t]
            for r in range(d):
                dqr = dq_all[t][r]
                dkr = dk_all[t][r]
                dvr = dv_all[t][r]
                if dqr == 0.0 and dkr == 0.0 and dvr == 0.0:
                    continue
                wq = self.W_q[r]
                wk = self.W_k[r]
                wv = self.W_v[r]
                for cc in range(d):
                    xrow[cc] += dqr * wq[cc] + dkr * wk[cc] + dvr * wv[cc]
        return dx


def _is_num(v) -> bool:
    """有限实数（bool 不算）"""
    return isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v)


def _ck_int(v, name: str, minimum: int):
    """正整数校验（bool 不算整数），返回 int"""
    if isinstance(v, bool) or not isinstance(v, int):
        raise TypeError('%s 必须是整数，收到 %r' % (name, v))
    if v < minimum:
        raise ValueError('%s 必须 >= %d，收到 %d' % (name, minimum, v))
    return int(v)


def t5_relative_buckets(qlen: int, klen: int, num_buckets: int = 32,
                        max_distance: int = 128,
                        bidirectional: bool = True) -> List[List[int]]:
    """T5 的相对位置分桶（与论文/原实现同公式，纯整数运算）。

    返回 ``(qlen, klen)`` 的桶编号矩阵。相对位置 ``i - j`` 先按正负切成
    「远/近」两半，近端线性分桶、远端按 ``log`` 增速分桶，再截断到
    ``max_distance``。``bidirectional=False`` 时只保留 ``j <= i`` 的一半
    （因果语言模型用），负相对位置被折回同一套桶。
    """
    _ck_int(qlen, 't5_relative_buckets(qlen)', 1)
    _ck_int(klen, 't5_relative_buckets(klen)', 1)
    _ck_int(num_buckets, 't5_relative_buckets(num_buckets)', 4)
    _ck_int(max_distance, 't5_relative_buckets(max_distance)', 1)
    if not isinstance(bidirectional, bool):
        raise TypeError('t5_relative_buckets: bidirectional 必须是 bool')
    half = num_buckets // 2
    max_exact = half // 2
    ret = []
    for i in range(qlen):
        row = []
        for j in range(klen):
            rel = j - i
            if bidirectional:
                # T5 原公式：先按正负分成两个半区，每个半区内部再分
                # 「近端线性（距离 < max_exact）」与「远端对数」两段。
                n = abs(rel)
                if n < max_exact:
                    inner = n
                else:
                    inner = max_exact + int(
                        math.log(max(n, 1) / max_exact)
                        / math.log(max_distance / max_exact)
                        * (half - max_exact))
                    inner = min(inner, half - 1)
                row.append(inner + (half if rel > 0 else 0))
            else:
                # 因果版：只看左侧距离，并夹到桶表范围内
                row.append(min(abs(rel), max_distance, num_buckets - 1))
        ret.append(row)
    return ret


class T5RelativeBias:
    """T5 式相对位置偏置：可学习的 ``(num_buckets, num_heads)`` 表，加到分数上。

    ``forward(qlen, klen=None)`` 返回 ``bias[head][i][j]``；``backward(dbias)``
    把梯度累加到 ``self.grad_table``。用法::

        bias_op = T5RelativeBias(num_heads=4)
        bias = bias_op.forward(T)          # 加在 softmax 之前的 scores 上
        biases = bias_op.backward(dscores) # dscores 同形状
    """

    def __init__(self, num_heads: int, num_buckets: int = 32,
                 max_distance: int = 128, bidirectional: bool = True,
                 std: float = 0.02):
        _ck_int(num_heads, 'T5RelativeBias(num_heads)', 1)
        _ck_int(num_buckets, 'T5RelativeBias(num_buckets)', 4)
        _ck_int(max_distance, 'T5RelativeBias(max_distance)', 1)
        if not isinstance(bidirectional, bool):
            raise TypeError('T5RelativeBias: bidirectional 必须是 bool')
        if not _is_num(std) or std < 0.0:
            raise ValueError('T5RelativeBias: std 必须是非负有限数字')
        self.num_heads = num_heads
        self.num_buckets = num_buckets
        self.max_distance = max_distance
        self.bidirectional = bidirectional
        rng = random.Random(20240502 + num_heads * 1009 + num_buckets)
        self.table = [[rng.gauss(0.0, float(std)) for _ in range(num_heads)]
                      for _ in range(num_buckets)]
        self.grad_table = [[0.0] * num_heads for _ in range(num_buckets)]
        self.m_table = [[0.0] * num_heads for _ in range(num_buckets)]
        self.v_table = [[0.0] * num_heads for _ in range(num_buckets)]
        self._adam_t = 0
        self._cache = None

    def forward(self, qlen: int, klen: Optional[int] = None) -> List[List[List[float]]]:
        """返回 ``bias[head][i][j]``（bias 形状 ``(num_heads, qlen, klen)``）"""
        if klen is None:
            klen = qlen
        buckets = t5_relative_buckets(qlen, klen, self.num_buckets,
                                      self.max_distance, self.bidirectional)
        h, t = self.num_heads, qlen
        out = [[[0.0] * klen for _ in range(t)] for _ in range(h)]
        for head in range(h):
            tab = self.table
            for i in range(t):
                row = buckets[i]
                dst = out[head][i]
                for j in range(klen):
                    dst[j] = tab[row[j]][head]
        self._cache = buckets
        return out

    def backward(self, dbias: List[List[List[float]]]) -> List[List[float]]:
        """累加 ``table`` 的梯度并返回本次的梯度（形状同 table）"""
        if self._cache is None:
            raise RuntimeError('T5RelativeBias.backward: 需要先 forward')
        if not isinstance(dbias, list) or len(dbias) != self.num_heads:
            raise ValueError('T5RelativeBias.backward: dbias 头数不匹配')
        buckets = self._cache
        t = len(buckets)
        klen = len(buckets[0])
        step = [[0.0] * self.num_heads for _ in range(self.num_buckets)]
        for head in range(self.num_heads):
            dh = dbias[head]
            if not isinstance(dh, list) or len(dh) != t:
                raise ValueError('T5RelativeBias.backward: dbias 行数与 forward 不一致')
            for i in range(t):
                row = dh[i]
                if not isinstance(row, list) or len(row) != klen:
                    raise ValueError('T5RelativeBias.backward: dbias 列数与 forward 不一致')
                brow = buckets[i]
                for j in range(klen):
                    step[brow[j]][head] += row[j]
        for b in range(self.num_buckets):
            for head in range(self.num_heads):
                self.grad_table[b][head] += step[b][head]
        return step

    def zero_grad(self):
        self.grad_table = [[0.0] * self.num_heads for _ in range(self.num_buckets)]

    def param_count(self) -> int:
        return self.num_buckets * self.num_heads

    def sgd_step(self, lr: float):
        lr = _la_check_lr(lr, 'T5RelativeBias.sgd_step')
        _la_apply_sgd(self.table, self.grad_table, lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        lr = _la_check_lr(lr, 'T5RelativeBias.adam_step')
        _check_adam_betas(beta1, beta2, 'T5RelativeBias.adam_step')
        self._adam_t += 1
        c1 = 1.0 - beta1 ** self._adam_t
        c2 = 1.0 - beta2 ** self._adam_t
        _la_apply_adam(self.table, self.grad_table, self.m_table, self.v_table,
                       lr, c1, c2, beta1, beta2, eps)

    def train(self):
        return self

    def eval(self):
        return self


def xpos_factors(seq_len: int, d_k: int, base: float = 10000.0,
                 alpha: float = 1.0, offset: float = 0.0) -> List[List[float]]:
    """xPos 的位置衰减因子（简化版）：对第 ``i`` 个频率维乘以
    ``(t + 1 + offset) ** (-alpha * theta_i)``，``theta_i = base ** (-2i/d_k)``。

    位置 0 处因子为 1（与标准 RoPE 一致），越靠后衰减越多；``alpha=0``
    时退化为全 1（即「关闭 xPos」）。返回 ``seq_len x d_k`` 的乘子矩阵，
    直接逐元素乘到旋转后的 q/k 上即可。真实 xPos 还会配合长度外推的
    offset 使用，这里只实现衰减部分。
    """
    _ck_int(seq_len, 'xpos_factors(seq_len)', 1)
    _ck_int(d_k, 'xpos_factors(d_k)', 1)
    if d_k % 2 != 0:
        raise ValueError('xpos_factors: d_k 必须是偶数')
    if not _is_num(base) or base <= 0.0:
        raise ValueError('xpos_factors: base 必须是正有限数字')
    if not _is_num(alpha) or alpha < 0.0:
        raise ValueError('xpos_factors: alpha 必须是非负有限数字')
    if not _is_num(offset) or offset < 0.0:
        raise ValueError('xpos_factors: offset 必须是非负有限数字')
    pairs = d_k // 2
    theta = [float(base) ** (-2.0 * i / d_k) for i in range(pairs)]
    out = []
    for t in range(seq_len):
        pos = t + 1 + float(offset)
        row = []
        for i in range(pairs):
            f = 1.0 if alpha == 0.0 else pos ** (-alpha * theta[i])
            row.append(f)
            row.append(f)
        out.append(row)
    return out


class LinearAttention:
    """线性注意力（Katharopoulos et al. 2020）：`phi(x) = elu(x) + 1`

    标准注意力是 `softmax(QK^T)V`，要显式算 T×T 矩阵，代价 O(T^2·d)。
    这里把 softmax 换成核函数 `phi`，利用「先求和再相乘」的加法结合律：

        out_t = phi(q_t)^T · sum_{s<=t} phi(k_s) v_s^T
                / (phi(q_t)^T · sum_{s<=t} phi(k_s))

    分子/分母都是**前缀累加**（d_k×d_k 矩阵与 d_k 维向量），代价降到 O(T·d^2)，
    与序列长度线性相关。`causal=True` 时用前缀和（自回归可用），否则用全长和。

    `phi = elu + 1` 保证特征非负（分母才是正数），这也是敢直接除的前提；
    分母带 `eps` 兜底。逐头独立计算，拼回 d_model 后过输出投影。

    不支持注意力 dropout（线性注意力的权重不显式存在），`train()`/`eval()`
    是空操作——保留只为和别的层统一调用。
    """

    def __init__(self, d_model: int, num_heads: int, causal: bool = False,
                 eps: float = 1e-6):
        if isinstance(d_model, bool) or not isinstance(d_model, int):
            raise ValueError("LinearAttention: d_model 必须是正整数，收到 %r" % (d_model,))
        if d_model < 1:
            raise ValueError("LinearAttention: d_model 必须 >= 1，收到 %r" % (d_model,))
        if isinstance(num_heads, bool) or not isinstance(num_heads, int):
            raise ValueError(
                "LinearAttention: num_heads 必须是正整数，收到 %r" % (num_heads,))
        if num_heads < 1:
            raise ValueError("LinearAttention: num_heads 必须 >= 1，收到 %r" % (num_heads,))
        if d_model % num_heads != 0:
            raise ValueError(
                "LinearAttention: d_model=%d 必须能被 num_heads=%d 整除"
                % (d_model, num_heads))
        if isinstance(eps, bool) or not isinstance(eps, (int, float)):
            raise ValueError("LinearAttention: eps 必须是正数，收到 %r" % (eps,))
        eps = float(eps)
        if not (eps > 0.0) or eps != eps:
            raise ValueError("LinearAttention: eps 必须是有限正数，收到 %r" % (eps,))
        self.d_model = d_model
        self.num_heads = num_heads
        self.d_k = d_model // num_heads
        self.causal = bool(causal)
        self.eps = eps
        std = math.sqrt(2.0 / d_model)
        self.W_q = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.W_k = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.W_v = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.W_o = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.b_q = [0.0] * d_model
        self.b_k = [0.0] * d_model
        self.b_v = [0.0] * d_model
        self.b_o = [0.0] * d_model
        self._init_adam()
        self.zero_grad()
        self.seq_len = 0
        self.x = None
        self.concat = None
        self._cache = None

    def zero_grad(self):
        """清零所有参数梯度"""
        d = self.d_model

        def zeros_2d(r, c):
            return [[0.0] * c for _ in range(r)]

        self.grads = {
            "W_q": zeros_2d(d, d), "b_q": [0.0] * d,
            "W_k": zeros_2d(d, d), "b_k": [0.0] * d,
            "W_v": zeros_2d(d, d), "b_v": [0.0] * d,
            "W_o": zeros_2d(d, d), "b_o": [0.0] * d,
        }

    def _init_adam(self):
        d = self.d_model
        for name in ("W_q", "W_k", "W_v", "W_o"):
            setattr(self, "m_" + name, [[0.0] * d for _ in range(d)])
            setattr(self, "v_" + name, [[0.0] * d for _ in range(d)])
        for name in ("b_q", "b_k", "b_v", "b_o"):
            setattr(self, "m_" + name, [0.0] * d)
            setattr(self, "v_" + name, [0.0] * d)
        self._adam_t = 0

    def train(self):
        """线性注意力没有 dropout，这里是空操作（保持接口统一）"""
        return self

    def eval(self):
        """线性注意力没有 dropout，这里是空操作（保持接口统一）"""
        return self

    @staticmethod
    def phi(x):
        """特征映射 phi(x) = elu(x) + 1：非负、单射"""
        return [(math.exp(xi) - 1.0 if xi <= 0.0 else xi) + 1.0 for xi in x]

    @staticmethod
    def _dphi(x, dy):
        """phi 的反向：d elu/dx = 1 (x>0) / exp(x) (x<=0)"""
        return [(1.0 if xi > 0.0 else math.exp(xi)) * di for xi, di in zip(x, dy)]

    def _proj(self, W, b, x_t):
        return [sum(map(_mul, W[r], x_t)) + b[r] for r in range(self.d_model)]

    def forward(self, x_seq):
        """x_seq: (seq_len, d_model) → (seq_len, d_model)"""
        if not x_seq:
            raise ValueError("LinearAttention.forward: 输入序列不能为空")
        d = self.d_model
        for t, row in enumerate(x_seq):
            if len(row) != d:
                raise ValueError(
                    "LinearAttention.forward: 第 %d 个 token 的维度 %d 与 d_model=%d 不一致"
                    % (t, len(row), d))
        T = len(x_seq)
        q_all = [self._proj(self.W_q, self.b_q, xt) for xt in x_seq]
        k_all = [self._proj(self.W_k, self.b_k, xt) for xt in x_seq]
        v_all = [self._proj(self.W_v, self.b_v, xt) for xt in x_seq]
        d_k = self.d_k
        cache = []
        concat = [[0.0] * d for _ in range(T)]
        for head in range(self.num_heads):
            off = head * d_k
            qh = [q_all[t][off:off + d_k] for t in range(T)]
            kh = [k_all[t][off:off + d_k] for t in range(T)]
            vh = [v_all[t][off:off + d_k] for t in range(T)]
            phi_q = [self.phi(q) for q in qh]
            phi_k = [self.phi(k) for k in kh]
            if self.causal:
                S_use = []
                z_use = []
                acc = [[0.0] * d_k for _ in range(d_k)]
                zacc = [0.0] * d_k
                for t in range(T):
                    pk = phi_k[t]
                    vt = vh[t]
                    for i in range(d_k):
                        pki = pk[i]
                        arow = acc[i]
                        for j in range(d_k):
                            arow[j] += pki * vt[j]
                        zacc[i] += pki
                    S_use.append([list(r) for r in acc])
                    z_use.append(list(zacc))
            else:
                acc = [[0.0] * d_k for _ in range(d_k)]
                zacc = [0.0] * d_k
                for t in range(T):
                    pk = phi_k[t]
                    vt = vh[t]
                    for i in range(d_k):
                        pki = pk[i]
                        arow = acc[i]
                        for j in range(d_k):
                            arow[j] += pki * vt[j]
                        zacc[i] += pki
                S_use = [acc] * T
                z_use = [zacc] * T
            outs = []
            denoms = []
            for t in range(T):
                S = S_use[t]
                pq = phi_q[t]
                num = [sum(pq[i] * S[i][j] for i in range(d_k)) for j in range(d_k)]
                den = sum(pq[i] * z_use[t][i] for i in range(d_k)) + self.eps
                denoms.append(den)
                outs.append([v / den for v in num])
            for t in range(T):
                for j in range(d_k):
                    concat[t][off + j] = outs[t][j]
            cache.append({
                "phi_q": phi_q, "phi_k": phi_k, "v": vh,
                "S": S_use, "z": z_use, "denom": denoms, "out": outs,
            })
        y = [[sum(map(_mul, self.W_o[r], concat[t])) + self.b_o[r] for r in range(d)]
             for t in range(T)]
        self.seq_len = T
        self.x = [list(row) for row in x_seq]
        self.concat = concat
        self._cache = cache
        return y

    def backward(self, dout_seq):
        """dout_seq: (seq_len, d_model) → (seq_len, d_model) 输入梯度"""
        if self._cache is None:
            raise RuntimeError("LinearAttention.backward: 必须先 forward")
        if len(dout_seq) != self.seq_len:
            raise ValueError(
                "LinearAttention.backward: dout 长度 %d 与 forward 的 %d 不一致"
                % (len(dout_seq), self.seq_len))
        d = self.d_model
        T = self.seq_len
        d_k = self.d_k
        dconcat = [[sum(dout_seq[t][j] * self.W_o[j][r] for j in range(d))
                    for r in range(d)] for t in range(T)]
        for r in range(d):
            wrow = self.grads["W_o"][r]
            for t in range(T):
                dt = dout_seq[t][r]
                if dt != 0.0:
                    crow = self.concat[t]
                    for c in range(d):
                        wrow[c] += dt * crow[c]
            self.grads["b_o"][r] += sum(dout_seq[t][r] for t in range(T))
        dq_all = [[0.0] * d for _ in range(T)]
        dk_all = [[0.0] * d for _ in range(T)]
        dv_all = [[0.0] * d for _ in range(T)]
        for head in range(self.num_heads):
            off = head * d_k
            c = self._cache[head]
            phi_q, phi_k, vh = c["phi_q"], c["phi_k"], c["v"]
            S_use, z_use, denom, outs = c["S"], c["z"], c["denom"], c["out"]
            dphi_q = [[0.0] * d_k for _ in range(T)]
            dphi_k = [[0.0] * d_k for _ in range(T)]
            dvh = [[0.0] * d_k for _ in range(T)]
            dS = []
            dz = []
            for t in range(T):
                dout = dconcat[t][off:off + d_k]
                den = denom[t]
                out = outs[t]
                dnum = [v / den for v in dout]
                dden = -sum(dout[j] * out[j] for j in range(d_k)) / den
                S = S_use[t]
                pq = phi_q[t]
                dS.append([[pq[i] * dnum[j] for j in range(d_k)] for i in range(d_k)])
                for i in range(d_k):
                    dphi_q[t][i] += sum(S[i][j] * dnum[j] for j in range(d_k))
                    dphi_q[t][i] += dden * z_use[t][i]
                dz.append([dden * pq[i] for i in range(d_k)])
            if self.causal:
                # 前缀和：S_t 依赖 s<=t，所以 dS 要**从后往前**累加（后缀和）
                accS = [[0.0] * d_k for _ in range(d_k)]
                accz = [0.0] * d_k
                for t in range(T - 1, -1, -1):
                    dSt = dS[t]
                    for i in range(d_k):
                        arow = accS[i]
                        srow = dSt[i]
                        for j in range(d_k):
                            arow[j] += srow[j]
                        accz[i] += dz[t][i]
                    pk = phi_k[t]
                    vt = vh[t]
                    for i in range(d_k):
                        arow = accS[i]
                        dphi_k[t][i] += (sum(arow[j] * vt[j] for j in range(d_k))
                                         + accz[i])
                    for j in range(d_k):
                        dvh[t][j] += sum(accS[i][j] * pk[i] for i in range(d_k))
            else:
                # 全长和：所有位置共用同一个 S，先把 dS/dz 全加起来再一次性回传
                totS = [[0.0] * d_k for _ in range(d_k)]
                totz = [0.0] * d_k
                for t in range(T):
                    dSt = dS[t]
                    for i in range(d_k):
                        trow = totS[i]
                        srow = dSt[i]
                        for j in range(d_k):
                            trow[j] += srow[j]
                        totz[i] += dz[t][i]
                for t in range(T):
                    pk = phi_k[t]
                    vt = vh[t]
                    for i in range(d_k):
                        trow = totS[i]
                        dphi_k[t][i] += (sum(trow[j] * vt[j] for j in range(d_k))
                                         + totz[i])
                    for j in range(d_k):
                        dvh[t][j] += sum(totS[i][j] * pk[i] for i in range(d_k))
            for t in range(T):
                xt = self.x[t]
                qh = [sum(map(_mul, self.W_q[r], xt)) + self.b_q[r]
                      for r in range(off, off + d_k)]
                kh = [sum(map(_mul, self.W_k[r], xt)) + self.b_k[r]
                      for r in range(off, off + d_k)]
                dq = self._dphi(qh, dphi_q[t])
                dk = self._dphi(kh, dphi_k[t])
                for j in range(d_k):
                    dq_all[t][off + j] = dq[j]
                    dk_all[t][off + j] = dk[j]
                    dv_all[t][off + j] = dvh[t][j]
        for r in range(d):
            wq = self.grads["W_q"][r]
            wk = self.grads["W_k"][r]
            wv = self.grads["W_v"][r]
            sbq = sbk = sbv = 0.0
            for t in range(T):
                xt = self.x[t]
                dqr = dq_all[t][r]
                dkr = dk_all[t][r]
                dvr = dv_all[t][r]
                sbq += dqr
                sbk += dkr
                sbv += dvr
                if dqr != 0.0:
                    for c in range(d):
                        wq[c] += dqr * xt[c]
                if dkr != 0.0:
                    for c in range(d):
                        wk[c] += dkr * xt[c]
                if dvr != 0.0:
                    for c in range(d):
                        wv[c] += dvr * xt[c]
            self.grads["b_q"][r] += sbq
            self.grads["b_k"][r] += sbk
            self.grads["b_v"][r] += sbv
        dx = [[0.0] * d for _ in range(T)]
        for t in range(T):
            xrow = dx[t]
            for r in range(d):
                dqr = dq_all[t][r]
                dkr = dk_all[t][r]
                dvr = dv_all[t][r]
                if dqr == 0.0 and dkr == 0.0 and dvr == 0.0:
                    continue
                wq = self.W_q[r]
                wk = self.W_k[r]
                wv = self.W_v[r]
                for c in range(d):
                    xrow[c] += dqr * wq[c] + dkr * wk[c] + dvr * wv[c]
        return dx

    def param_count(self):
        """参数量：四个 d×d 投影 + 四个 d 维偏置"""
        d = self.d_model
        return 4 * d * d + 4 * d

    def sgd_step(self, lr: float):
        """SGD 更新"""
        lr = _la_check_lr(lr, "LinearAttention.sgd_step")
        for name in ("W_q", "W_k", "W_v", "W_o"):
            _la_apply_sgd(getattr(self, name), self.grads[name], lr)
        for name in ("b_q", "b_k", "b_v", "b_o"):
            param = getattr(self, name)
            grad = self.grads[name]
            for i in range(len(param)):
                param[i] -= lr * grad[i]

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        """Adam 更新"""
        lr = _la_check_lr(lr, "LinearAttention.adam_step")
        _check_adam_betas(beta1, beta2, "LinearAttention.adam_step")
        self._adam_t += 1
        t = self._adam_t
        c1 = 1.0 - beta1 ** t
        c2 = 1.0 - beta2 ** t
        for name in ("W_q", "W_k", "W_v", "W_o"):
            _la_apply_adam(getattr(self, name), self.grads[name],
                           getattr(self, "m_" + name), getattr(self, "v_" + name),
                           lr, c1, c2, beta1, beta2, eps)
        for name in ("b_q", "b_k", "b_v", "b_o"):
            param = getattr(self, name)
            grad = self.grads[name]
            m = getattr(self, "m_" + name)
            v = getattr(self, "v_" + name)
            for i in range(len(param)):
                g = grad[i]
                m[i] = beta1 * m[i] + (1.0 - beta1) * g
                v[i] = beta2 * v[i] + (1.0 - beta2) * g * g
                param[i] -= lr * (m[i] / c1) / (math.sqrt(v[i] / c2) + eps)


def _la_check_lr(lr, who):
    """线性注意力族的 lr 校验，返回 float（与别处优化器步同口径）"""
    if isinstance(lr, bool) or not isinstance(lr, (int, float)):
        raise ValueError("%s: lr 必须是数字，收到 %r" % (who, lr))
    lr = float(lr)
    if not (lr >= 0.0) or lr != lr:
        raise ValueError("%s: lr 必须是非负有限数，收到 %r" % (who, lr))
    return lr


def _la_apply_sgd(param, grad, lr):
    """逐叶 SGD（就地修改嵌套 list）"""
    for i in range(len(param)):
        if isinstance(param[i], list):
            _la_apply_sgd(param[i], grad[i], lr)
        else:
            param[i] -= lr * grad[i]


def _la_apply_adam(param, grad, m, v, lr, c1, c2, beta1, beta2, eps):
    """逐叶 Adam（就地修改嵌套 list）"""
    for i in range(len(param)):
        if isinstance(param[i], list):
            _la_apply_adam(param[i], grad[i], m[i], v[i], lr, c1, c2,
                           beta1, beta2, eps)
        else:
            g = grad[i]
            m[i] = beta1 * m[i] + (1.0 - beta1) * g
            v[i] = beta2 * v[i] + (1.0 - beta2) * g * g
            param[i] -= lr * (m[i] / c1) / (math.sqrt(v[i] / c2) + eps)


class LinformerAttention:
    """Linformer（Wang et al. 2020）：把 K/V 沿**序列维**压到 k 个 token

    标准注意力要算 T×T 的分数矩阵。Linformer 的观察是：注意力矩阵实际是低秩的，
    所以可以先用两个可学习投影 `E`/`F`（形状都是 `k×T`，T 是序列长度）把 K/V
    投影成 `k×d_k`，再算 `q·(E k)^T`——分数矩阵变成 `T×k`：

        out = softmax(q (E k)^T / sqrt(d_k)) · (F v)

    代价从 O(T²·d) 降到 O(T·k·d)，k << T 时常数很小。

    限制（文档明确）：
    - **不支持 causal**：E/F 用了整条序列的信息，做自回归会泄漏未来。
      构造时传 `causal=True` 直接报 `ValueError`。
    - `E`/`F` 的形状依赖序列长度 T，所以**同一个实例只能处理固定长度**；
      forward 发现 T 与构造时（或首次 forward）不一致会报错，不会静默截断。
    - 无注意力 dropout（与线性注意力一致）；`train()`/`eval()` 是空操作。
    """

    def __init__(self, d_model: int, num_heads: int, seq_len: int,
                 num_proj: int = None):
        if isinstance(d_model, bool) or not isinstance(d_model, int):
            raise ValueError("LinformerAttention: d_model 必须是正整数，收到 %r"
                             % (d_model,))
        if d_model < 1:
            raise ValueError("LinformerAttention: d_model 必须 >= 1，收到 %r"
                             % (d_model,))
        if isinstance(num_heads, bool) or not isinstance(num_heads, int):
            raise ValueError("LinformerAttention: num_heads 必须是正整数，收到 %r"
                             % (num_heads,))
        if num_heads < 1:
            raise ValueError("LinformerAttention: num_heads 必须 >= 1，收到 %r"
                             % (num_heads,))
        if d_model % num_heads != 0:
            raise ValueError(
                "LinformerAttention: d_model=%d 必须能被 num_heads=%d 整除"
                % (d_model, num_heads))
        if isinstance(seq_len, bool) or not isinstance(seq_len, int):
            raise ValueError("LinformerAttention: seq_len 必须是正整数，收到 %r"
                             % (seq_len,))
        if seq_len < 1:
            raise ValueError("LinformerAttention: seq_len 必须 >= 1，收到 %r"
                             % (seq_len,))
        if num_proj is None:
            num_proj = max(1, seq_len // 4)
        if isinstance(num_proj, bool) or not isinstance(num_proj, int):
            raise ValueError("LinformerAttention: num_proj 必须是正整数，收到 %r"
                             % (num_proj,))
        if num_proj < 1:
            raise ValueError("LinformerAttention: num_proj 必须 >= 1，收到 %r"
                             % (num_proj,))
        if num_proj > seq_len:
            raise ValueError(
                "LinformerAttention: num_proj=%d 不能大于 seq_len=%d"
                % (num_proj, seq_len))
        self.d_model = d_model
        self.num_heads = num_heads
        self.d_k = d_model // num_heads
        self.seq_len = seq_len
        self.num_proj = num_proj
        self.causal = False
        std = math.sqrt(2.0 / d_model)
        self.W_q = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.W_k = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.W_v = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.W_o = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.b_q = [0.0] * d_model
        self.b_k = [0.0] * d_model
        self.b_v = [0.0] * d_model
        self.b_o = [0.0] * d_model
        # E / F：(k, T)，k<<T；用 1/sqrt(T) 缩放，初始接近「平均池化」
        pstd = 1.0 / math.sqrt(float(seq_len))
        self.E = [[random.gauss(0, pstd) for _ in range(seq_len)]
                  for _ in range(num_proj)]
        self.F = [[random.gauss(0, pstd) for _ in range(seq_len)]
                  for _ in range(num_proj)]
        self._init_adam()
        self.zero_grad()
        self.x = None
        self.concat = None
        self._cache = None

    def zero_grad(self):
        """清零所有参数梯度"""
        d = self.d_model
        k = self.num_proj
        T = self.seq_len

        def zeros_2d(r, c):
            return [[0.0] * c for _ in range(r)]

        self.grads = {
            "W_q": zeros_2d(d, d), "b_q": [0.0] * d,
            "W_k": zeros_2d(d, d), "b_k": [0.0] * d,
            "W_v": zeros_2d(d, d), "b_v": [0.0] * d,
            "W_o": zeros_2d(d, d), "b_o": [0.0] * d,
            "E": zeros_2d(k, T), "F": zeros_2d(k, T),
        }

    def _init_adam(self):
        d = self.d_model
        k = self.num_proj
        T = self.seq_len
        for name in ("W_q", "W_k", "W_v", "W_o"):
            setattr(self, "m_" + name, [[0.0] * d for _ in range(d)])
            setattr(self, "v_" + name, [[0.0] * d for _ in range(d)])
        for name in ("b_q", "b_k", "b_v", "b_o"):
            setattr(self, "m_" + name, [0.0] * d)
            setattr(self, "v_" + name, [0.0] * d)
        for name in ("E", "F"):
            setattr(self, "m_" + name, [[0.0] * T for _ in range(k)])
            setattr(self, "v_" + name, [[0.0] * T for _ in range(k)])
        self._adam_t = 0

    def train(self):
        """无 dropout，空操作（保持接口统一）"""
        return self

    def eval(self):
        """无 dropout，空操作（保持接口统一）"""
        return self

    def _proj(self, W, b, x_t):
        return [sum(map(_mul, W[r], x_t)) + b[r] for r in range(self.d_model)]

    def forward(self, x_seq):
        """x_seq: (seq_len, d_model) → (seq_len, d_model)"""
        if not x_seq:
            raise ValueError("LinformerAttention.forward: 输入序列不能为空")
        d = self.d_model
        T = len(x_seq)
        if T != self.seq_len:
            raise ValueError(
                "LinformerAttention.forward: 本层构造时 seq_len=%d，收到长度 %d"
                "（E/F 的形状依赖序列长度，不能变长）" % (self.seq_len, T))
        for t, row in enumerate(x_seq):
            if len(row) != d:
                raise ValueError(
                    "LinformerAttention.forward: 第 %d 个 token 的维度 %d 与 d_model=%d 不一致"
                    % (t, len(row), d))
        q_all = [self._proj(self.W_q, self.b_q, xt) for xt in x_seq]
        k_all = [self._proj(self.W_k, self.b_k, xt) for xt in x_seq]
        v_all = [self._proj(self.W_v, self.b_v, xt) for xt in x_seq]
        d_k = self.d_k
        kk = self.num_proj
        scale = 1.0 / math.sqrt(d_k)
        cache = []
        concat = [[0.0] * d for _ in range(T)]
        for head in range(self.num_heads):
            off = head * d_k
            qh = [q_all[t][off:off + d_k] for t in range(T)]
            kh = [k_all[t][off:off + d_k] for t in range(T)]
            vh = [v_all[t][off:off + d_k] for t in range(T)]
            # 低秩投影：k_proj[i][j] = sum_t E[i][t] * kh[t][j]
            k_proj = [[sum(self.E[i][t] * kh[t][j] for t in range(T))
                       for j in range(d_k)] for i in range(kk)]
            v_proj = [[sum(self.F[i][t] * vh[t][j] for t in range(T))
                       for j in range(d_k)] for i in range(kk)]
            scores = [[sum(qh[t][j] * k_proj[i][j] for j in range(d_k)) * scale
                       for i in range(kk)] for t in range(T)]
            probs = []
            for t in range(T):
                m = max(scores[t])
                ex = [math.exp(s - m) for s in scores[t]]
                # softmax 分母至少含 exp(0)=1，恒 >= 1，不需要 eps 平滑
                tot = sum(ex)
                probs.append([e / tot for e in ex])
            outs = [[sum(probs[t][i] * v_proj[i][j] for i in range(kk)) * 1.0
                     for j in range(d_k)] for t in range(T)]
            for t in range(T):
                for j in range(d_k):
                    concat[t][off + j] = outs[t][j]
            cache.append({"q": qh, "k": kh, "v": vh, "k_proj": k_proj,
                          "v_proj": v_proj, "probs": probs, "out": outs})
        y = [[sum(map(_mul, self.W_o[r], concat[t])) + self.b_o[r] for r in range(d)]
             for t in range(T)]
        self.x = [list(row) for row in x_seq]
        self.concat = concat
        self._cache = cache
        return y

    def backward(self, dout_seq):
        """dout_seq: (seq_len, d_model) → (seq_len, d_model) 输入梯度"""
        if self._cache is None:
            raise RuntimeError("LinformerAttention.backward: 必须先 forward")
        d = self.d_model
        T = self.seq_len
        if len(dout_seq) != T:
            raise ValueError(
                "LinformerAttention.backward: dout 长度 %d 与 forward 的 %d 不一致"
                % (len(dout_seq), T))
        d_k = self.d_k
        kk = self.num_proj
        scale = 1.0 / math.sqrt(d_k)
        dconcat = [[sum(dout_seq[t][j] * self.W_o[j][r] for j in range(d))
                    for r in range(d)] for t in range(T)]
        for r in range(d):
            wrow = self.grads["W_o"][r]
            for t in range(T):
                dt = dout_seq[t][r]
                if dt != 0.0:
                    crow = self.concat[t]
                    for c in range(d):
                        wrow[c] += dt * crow[c]
            self.grads["b_o"][r] += sum(dout_seq[t][r] for t in range(T))
        dq_all = [[0.0] * d for _ in range(T)]
        dk_all = [[0.0] * d for _ in range(T)]
        dv_all = [[0.0] * d for _ in range(T)]
        for head in range(self.num_heads):
            off = head * d_k
            c = self._cache[head]
            qh, kh, vh = c["q"], c["k"], c["v"]
            k_proj, v_proj = c["k_proj"], c["v_proj"]
            probs = c["probs"]
            dout = [dconcat[t][off:off + d_k] for t in range(T)]
            dv_proj = [[sum(probs[t][i] * dout[t][j] for t in range(T))
                        for j in range(d_k)] for i in range(kk)]
            dprobs = [[sum(dout[t][j] * v_proj[i][j] for j in range(d_k))
                       for i in range(kk)] for t in range(T)]
            dscores = [[0.0] * kk for _ in range(T)]
            for t in range(T):
                dot = sum(probs[t][i] * dprobs[t][i] for i in range(kk))
                for i in range(kk):
                    dscores[t][i] = probs[t][i] * (dprobs[t][i] - dot)
            dq = [[sum(dscores[t][i] * k_proj[i][j] for i in range(kk)) * scale
                   for j in range(d_k)] for t in range(T)]
            dk_proj = [[sum(dscores[t][i] * qh[t][j] for t in range(T)) * scale
                        for j in range(d_k)] for i in range(kk)]
            for i in range(kk):
                erow = self.grads["E"][i]
                frow = self.grads["F"][i]
                for t in range(T):
                    erow[t] += sum(dk_proj[i][j] * kh[t][j] for j in range(d_k))
                    frow[t] += sum(dv_proj[i][j] * vh[t][j] for j in range(d_k))
            dkh = [[sum(self.E[i][t] * dk_proj[i][j] for i in range(kk))
                    for j in range(d_k)] for t in range(T)]
            dvh = [[sum(self.F[i][t] * dv_proj[i][j] for i in range(kk))
                    for j in range(d_k)] for t in range(T)]
            for t in range(T):
                for j in range(d_k):
                    dq_all[t][off + j] = dq[t][j]
                    dk_all[t][off + j] = dkh[t][j]
                    dv_all[t][off + j] = dvh[t][j]
        for r in range(d):
            wq = self.grads["W_q"][r]
            wk = self.grads["W_k"][r]
            wv = self.grads["W_v"][r]
            sbq = sbk = sbv = 0.0
            for t in range(T):
                xt = self.x[t]
                dqr = dq_all[t][r]
                dkr = dk_all[t][r]
                dvr = dv_all[t][r]
                sbq += dqr
                sbk += dkr
                sbv += dvr
                if dqr != 0.0:
                    for c2 in range(d):
                        wq[c2] += dqr * xt[c2]
                if dkr != 0.0:
                    for c2 in range(d):
                        wk[c2] += dkr * xt[c2]
                if dvr != 0.0:
                    for c2 in range(d):
                        wv[c2] += dvr * xt[c2]
            self.grads["b_q"][r] += sbq
            self.grads["b_k"][r] += sbk
            self.grads["b_v"][r] += sbv
        dx = [[0.0] * d for _ in range(T)]
        for t in range(T):
            xrow = dx[t]
            for r in range(d):
                dqr = dq_all[t][r]
                dkr = dk_all[t][r]
                dvr = dv_all[t][r]
                if dqr == 0.0 and dkr == 0.0 and dvr == 0.0:
                    continue
                wq = self.W_q[r]
                wk = self.W_k[r]
                wv = self.W_v[r]
                for c2 in range(d):
                    xrow[c2] += dqr * wq[c2] + dkr * wk[c2] + dvr * wv[c2]
        return dx

    def param_count(self):
        """参数量：四个 d×d 投影 + 四个偏置 + E/F（各 k×T）"""
        d = self.d_model
        return 4 * d * d + 4 * d + 2 * self.num_proj * self.seq_len

    def sgd_step(self, lr: float):
        """SGD 更新"""
        lr = _la_check_lr(lr, "LinformerAttention.sgd_step")
        for name in ("W_q", "W_k", "W_v", "W_o", "E", "F"):
            _la_apply_sgd(getattr(self, name), self.grads[name], lr)
        for name in ("b_q", "b_k", "b_v", "b_o"):
            param = getattr(self, name)
            grad = self.grads[name]
            for i in range(len(param)):
                param[i] -= lr * grad[i]

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        """Adam 更新"""
        lr = _la_check_lr(lr, "LinformerAttention.adam_step")
        _check_adam_betas(beta1, beta2, "LinformerAttention.adam_step")
        self._adam_t += 1
        t = self._adam_t
        c1 = 1.0 - beta1 ** t
        c2 = 1.0 - beta2 ** t
        for name in ("W_q", "W_k", "W_v", "W_o", "E", "F"):
            _la_apply_adam(getattr(self, name), self.grads[name],
                           getattr(self, "m_" + name), getattr(self, "v_" + name),
                           lr, c1, c2, beta1, beta2, eps)
        for name in ("b_q", "b_k", "b_v", "b_o"):
            param = getattr(self, name)
            grad = self.grads[name]
            m = getattr(self, "m_" + name)
            v = getattr(self, "v_" + name)
            for i in range(len(param)):
                g = grad[i]
                m[i] = beta1 * m[i] + (1.0 - beta1) * g
                v[i] = beta2 * v[i] + (1.0 - beta2) * g * g
                param[i] -= lr * (m[i] / c1) / (math.sqrt(v[i] / c2) + eps)


class PerformerAttention:
    """Performer（Choromanski 2020）：用随机特征近似 softmax 核

    softmax 注意力可以写成核形式 `exp(q·k / sqrt(d))` 的加权平均。
    Performer 用随机特征近似这个核：

        phi(x) = exp(W x - |x|^2 / 2) / sqrt(m)

    其中 `W` 是 `m×d_k` 的随机矩阵（`m` 是特征数）。有了正的近似特征，
    注意力就能用「前缀累加矩阵」算，复杂度从 O(T^2·d) 降到 O(T·d·m)：

        S_t = S_{t-1} + phi(k_t) v_t^T,   z_t = z_{t-1} + phi(k_t)
        out_t = phi(q_t)^T S_t / (phi(q_t)^T z_t + eps)

    实现选择（文档明确）：
    - `W` 用**独立高斯**采样（每头一份），不是论文里方差更优的「正交随机特征」。
      近似质量因此略差，但方向正确、数值稳定，梯度可用中心差分验证。
      实测（d=8、4 个随机 token、与真实 softmax 注意力比相对 L2）：
      `m=4` 时误差约 92%，`m=64` 时约 35%——特征越多越准，但这份实现
      **不追求**与 softmax 数值一致，它的价值是 O(T·d·m) 的复杂度。
    - `causal=True` 时用前缀累加（只看 <=t 的 K/V），可做自回归。
    - `phi` 非线性且不是逐元素的，所以反向要把 `dL/dphi` 经过
      `dphi_i/dx_j = phi_i(x)·(W[i][j] - x_j)` 回传到 x——这是与
      `LinearAttention`（elu+1 逐元素）最大的实现差异。
    """

    def __init__(self, d_model: int, num_heads: int, num_features: int = 16,
                 causal: bool = False, eps: float = 1e-6, seed: int = 0):
        if isinstance(d_model, bool) or not isinstance(d_model, int):
            raise ValueError("PerformerAttention: d_model 必须是正整数，收到 %r"
                             % (d_model,))
        if d_model < 1:
            raise ValueError("PerformerAttention: d_model 必须 >= 1，收到 %r"
                             % (d_model,))
        if isinstance(num_heads, bool) or not isinstance(num_heads, int):
            raise ValueError("PerformerAttention: num_heads 必须是正整数，收到 %r"
                             % (num_heads,))
        if num_heads < 1:
            raise ValueError("PerformerAttention: num_heads 必须 >= 1，收到 %r"
                             % (num_heads,))
        if d_model % num_heads != 0:
            raise ValueError(
                "PerformerAttention: d_model=%d 必须能被 num_heads=%d 整除"
                % (d_model, num_heads))
        if isinstance(num_features, bool) or not isinstance(num_features, int):
            raise ValueError("PerformerAttention: num_features 必须是正整数，收到 %r"
                             % (num_features,))
        if num_features < 1:
            raise ValueError("PerformerAttention: num_features 必须 >= 1，收到 %r"
                             % (num_features,))
        if not isinstance(causal, bool):
            raise ValueError("PerformerAttention: causal 必须是 bool，收到 %r"
                             % (causal,))
        if isinstance(eps, bool) or not isinstance(eps, (int, float)):
            raise ValueError("PerformerAttention: eps 必须是正数，收到 %r" % (eps,))
        eps = float(eps)
        if not (eps > 0.0) or eps != eps:
            raise ValueError("PerformerAttention: eps 必须是有限正数，收到 %r"
                             % (eps,))
        if isinstance(seed, bool) or not isinstance(seed, int):
            raise ValueError("PerformerAttention: seed 必须是整数，收到 %r" % (seed,))
        self.d_model = d_model
        self.num_heads = num_heads
        self.d_k = d_model // num_heads
        self.num_features = num_features
        self.causal = causal
        self.eps = eps
        self.seed = seed
        std = math.sqrt(2.0 / d_model)
        self.W_q = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.W_k = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.W_v = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.W_o = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.b_q = [0.0] * d_model
        self.b_k = [0.0] * d_model
        self.b_v = [0.0] * d_model
        self.b_o = [0.0] * d_model
        # 随机特征矩阵：每头一份 (m, d_k)，固定不训练
        rng = random.Random(seed)
        self.omega = [[[rng.gauss(0.0, 1.0) for _ in range(self.d_k)]
                       for _ in range(num_features)]
                      for _ in range(num_heads)]
        self._init_adam()
        self.zero_grad()
        self.x = None
        self.concat = None
        self._cache = None

    def zero_grad(self):
        """清零所有参数梯度（W 与偏置；omega 不训练）"""
        d = self.d_model

        def zeros_2d(r, c):
            return [[0.0] * c for _ in range(r)]

        self.grads = {
            "W_q": zeros_2d(d, d), "b_q": [0.0] * d,
            "W_k": zeros_2d(d, d), "b_k": [0.0] * d,
            "W_v": zeros_2d(d, d), "b_v": [0.0] * d,
            "W_o": zeros_2d(d, d), "b_o": [0.0] * d,
        }

    def _init_adam(self):
        d = self.d_model
        for name in ("W_q", "W_k", "W_v", "W_o"):
            setattr(self, "m_" + name, [[0.0] * d for _ in range(d)])
            setattr(self, "v_" + name, [[0.0] * d for _ in range(d)])
        for name in ("b_q", "b_k", "b_v", "b_o"):
            setattr(self, "m_" + name, [0.0] * d)
            setattr(self, "v_" + name, [0.0] * d)
        self._adam_t = 0

    def train(self):
        """无 dropout，空操作（保持接口统一）"""
        return self

    def eval(self):
        """无 dropout，空操作（保持接口统一）"""
        return self

    def _proj(self, W, b, x_t):
        return [sum(map(_mul, W[r], x_t)) + b[r] for r in range(self.d_model)]

    def _phi(self, head, vec):
        """随机特征：phi(x)_i = exp(w_i·x - |x|^2/2) / sqrt(m)"""
        om = self.omega[head]
        m = self.num_features
        half = 0.5 * sum(v * v for v in vec)
        scale = 1.0 / math.sqrt(float(m))
        out = [0.0] * m
        for i in range(m):
            wi = om[i]
            dot = 0.0
            for j in range(self.d_k):
                dot += wi[j] * vec[j]
            out[i] = math.exp(dot - half) * scale
        return out

    def forward(self, x_seq):
        """x_seq: (T, d_model) → (T, d_model)"""
        if not x_seq:
            raise ValueError("PerformerAttention.forward: 输入序列不能为空")
        d = self.d_model
        T = len(x_seq)
        for t, row in enumerate(x_seq):
            if len(row) != d:
                raise ValueError(
                    "PerformerAttention.forward: 第 %d 个 token 的维度 %d 与 d_model=%d 不一致"
                    % (t, len(row), d))
        q_all = [self._proj(self.W_q, self.b_q, xt) for xt in x_seq]
        k_all = [self._proj(self.W_k, self.b_k, xt) for xt in x_seq]
        v_all = [self._proj(self.W_v, self.b_v, xt) for xt in x_seq]
        d_k = self.d_k
        m = self.num_features
        cache = []
        concat = [[0.0] * d for _ in range(T)]
        for head in range(self.num_heads):
            off = head * d_k
            qh = [q_all[t][off:off + d_k] for t in range(T)]
            kh = [k_all[t][off:off + d_k] for t in range(T)]
            vh = [v_all[t][off:off + d_k] for t in range(T)]
            pq = [self._phi(head, qh[t]) for t in range(T)]
            pk = [self._phi(head, kh[t]) for t in range(T)]
            S = [[0.0] * d_k for _ in range(m)]
            z = [0.0] * m
            out_h = [[0.0] * d_k for _ in range(T)]
            den_all = [0.0] * T
            for t in range(T):
                if self.causal:
                    # 前缀累加：只吸收 k_t / v_t
                    for i in range(m):
                        w = pk[t][i]
                        if w != 0.0:
                            Srow = S[i]
                            vt = vh[t]
                            for j in range(d_k):
                                Srow[j] += w * vt[j]
                        z[i] += w
                else:
                    # 非 causal：整条序列共用同一个全局和
                    pass
                if self.causal:
                    num = [0.0] * d_k
                    den = self.eps
                    for i in range(m):
                        w = pq[t][i]
                        if w == 0.0:
                            continue
                        den += w * z[i]
                        Srow = S[i]
                        for j in range(d_k):
                            num[j] += w * Srow[j]
                    den_all[t] = den
                    for j in range(d_k):
                        out_h[t][j] = num[j] / den
            if not self.causal:
                for s in range(T):
                    for i in range(m):
                        w = pk[s][i]
                        if w != 0.0:
                            Srow = S[i]
                            vs = vh[s]
                            for j in range(d_k):
                                Srow[j] += w * vs[j]
                        z[i] += w
                for t in range(T):
                    num = [0.0] * d_k
                    den = self.eps
                    for i in range(m):
                        w = pq[t][i]
                        if w == 0.0:
                            continue
                        den += w * z[i]
                        Srow = S[i]
                        for j in range(d_k):
                            num[j] += w * Srow[j]
                    den_all[t] = den
                    for j in range(d_k):
                        out_h[t][j] = num[j] / den
            for t in range(T):
                for j in range(d_k):
                    concat[t][off + j] = out_h[t][j]
            cache.append({"q": qh, "k": kh, "v": vh, "pq": pq, "pk": pk,
                          "out": out_h, "den": den_all})
        y = [[sum(map(_mul, self.W_o[r], concat[t])) + self.b_o[r] for r in range(d)]
             for t in range(T)]
        self.x = [list(row) for row in x_seq]
        self.concat = concat
        self._cache = cache
        return y

    def backward(self, dout_seq):
        """dout_seq: (T, d_model) → (T, d_model) 输入梯度"""
        if self._cache is None:
            raise RuntimeError("PerformerAttention.backward: 必须先 forward")
        d = self.d_model
        T = len(self.x)
        if len(dout_seq) != T:
            raise ValueError(
                "PerformerAttention.backward: dout 长度 %d 与 forward 的 %d 不一致"
                % (len(dout_seq), T))
        d_k = self.d_k
        m = self.num_features
        dconcat = [[0.0] * d for _ in range(T)]
        for t in range(T):
            dr = dout_seq[t]
            for r in range(d):
                dconcat[t][r] = sum(dr[j] * self.W_o[j][r] for j in range(d))
        for r in range(d):
            wrow = self.grads["W_o"][r]
            sb = 0.0
            for t in range(T):
                dt = dout_seq[t][r]
                sb += dt
                if dt != 0.0:
                    crow = self.concat[t]
                    for c in range(d):
                        wrow[c] += dt * crow[c]
            self.grads["b_o"][r] += sb
        dq_all = [[0.0] * d for _ in range(T)]
        dk_all = [[0.0] * d for _ in range(T)]
        dv_all = [[0.0] * d for _ in range(T)]
        for head in range(self.num_heads):
            off = head * d_k
            c = self._cache[head]
            qh, kh, vh = c["q"], c["k"], c["v"]
            pq, pk, out_h, den_all = c["pq"], c["pk"], c["out"], c["den"]
            dout = [dconcat[t][off:off + d_k] for t in range(T)]
            # 逐位置 dphi_q 与 dS/dz 的贡献
            dphi_q = [[0.0] * m for _ in range(T)]
            dS_t = [[[0.0] * d_k for _ in range(m)] for _ in range(T)]
            dz_t = [[0.0] * m for _ in range(T)]
            # 重放前向状态（与 forward 完全相同的累加顺序，保证逐位一致）
            S = [[0.0] * d_k for _ in range(m)]
            z = [0.0] * m
            S_hist = []
            z_hist = []
            for t in range(T):
                if self.causal:
                    for i in range(m):
                        w = pk[t][i]
                        if w != 0.0:
                            Srow = S[i]
                            vt = vh[t]
                            for j in range(d_k):
                                Srow[j] += w * vt[j]
                        z[i] += w
                    S_hist.append([list(row) for row in S])
                    z_hist.append(list(z))
            if not self.causal:
                for s in range(T):
                    for i in range(m):
                        w = pk[s][i]
                        if w != 0.0:
                            Srow = S[i]
                            vs = vh[s]
                            for j in range(d_k):
                                Srow[j] += w * vs[j]
                        z[i] += w
                S_hist = [[list(row) for row in S] for _ in range(T)]
                z_hist = [list(z) for _ in range(T)]
            for t in range(T):
                den = den_all[t]
                dnum = [dout[t][j] / den for j in range(d_k)]
                dden = -sum(out_h[t][j] * dout[t][j] for j in range(d_k)) / den
                Sp = S_hist[t]
                zp = z_hist[t]
                for i in range(m):
                    w = pq[t][i]
                    if w != 0.0:
                        Srow = dS_t[t][i]
                        for j in range(d_k):
                            Srow[j] += w * dnum[j]
                    dz_t[t][i] += w * dden
                    dphi_q[t][i] += sum(Sp[i][j] * dnum[j] for j in range(d_k))
                    dphi_q[t][i] += zp[i] * dden
            # 把逐位置 dS/dz 汇总成对 phi_k 的梯度
            dphi_k = [[0.0] * m for _ in range(T)]
            dv = [[0.0] * d_k for _ in range(T)]
            if self.causal:
                accS = [[0.0] * d_k for _ in range(m)]
                accz = [0.0] * m
                for s in range(T - 1, -1, -1):
                    for i in range(m):
                        dSt = dS_t[s][i]
                        Srow = accS[i]
                        for j in range(d_k):
                            Srow[j] += dSt[j]
                        accz[i] += dz_t[s][i]
                    for i in range(m):
                        Srow = accS[i]
                        dphi_k[s][i] = sum(Srow[j] * vh[s][j] for j in range(d_k))
                        dphi_k[s][i] += accz[i]
                    for j in range(d_k):
                        dv[s][j] = sum(accS[i][j] * pk[s][i] for i in range(m))
            else:
                totS = [[0.0] * d_k for _ in range(m)]
                totz = [0.0] * m
                for s in range(T):
                    for i in range(m):
                        dSt = dS_t[s][i]
                        Srow = totS[i]
                        for j in range(d_k):
                            Srow[j] += dSt[j]
                        totz[i] += dz_t[s][i]
                for s in range(T):
                    for i in range(m):
                        dphi_k[s][i] = sum(totS[i][j] * vh[s][j] for j in range(d_k))
                        dphi_k[s][i] += totz[i]
                    for j in range(d_k):
                        dv[s][j] = sum(totS[i][j] * pk[s][i] for i in range(m))
            # 经过 phi 的非线性把 dphi 传回 q/k
            dq = [[0.0] * d_k for _ in range(T)]
            dkh = [[0.0] * d_k for _ in range(T)]
            om = self.omega[head]
            for t in range(T):
                for j in range(d_k):
                    acc = 0.0
                    for i in range(m):
                        acc += dphi_q[t][i] * pq[t][i] * (om[i][j] - qh[t][j])
                    dq[t][j] = acc
                    acc2 = 0.0
                    for i in range(m):
                        acc2 += dphi_k[t][i] * pk[t][i] * (om[i][j] - kh[t][j])
                    dkh[t][j] = acc2
            for t in range(T):
                for j in range(d_k):
                    dq_all[t][off + j] = dq[t][j]
                    dk_all[t][off + j] = dkh[t][j]
                    dv_all[t][off + j] = dv[t][j]
        for r in range(d):
            wq = self.grads["W_q"][r]
            wk = self.grads["W_k"][r]
            wv = self.grads["W_v"][r]
            sbq = sbk = sbv = 0.0
            for t in range(T):
                xt = self.x[t]
                dqr = dq_all[t][r]
                dkr = dk_all[t][r]
                dvr = dv_all[t][r]
                sbq += dqr
                sbk += dkr
                sbv += dvr
                if dqr != 0.0:
                    for c2 in range(d):
                        wq[c2] += dqr * xt[c2]
                if dkr != 0.0:
                    for c2 in range(d):
                        wk[c2] += dkr * xt[c2]
                if dvr != 0.0:
                    for c2 in range(d):
                        wv[c2] += dvr * xt[c2]
            self.grads["b_q"][r] += sbq
            self.grads["b_k"][r] += sbk
            self.grads["b_v"][r] += sbv
        dx = [[0.0] * d for _ in range(T)]
        for t in range(T):
            xrow = dx[t]
            for r in range(d):
                dqr = dq_all[t][r]
                dkr = dk_all[t][r]
                dvr = dv_all[t][r]
                if dqr == 0.0 and dkr == 0.0 and dvr == 0.0:
                    continue
                wq = self.W_q[r]
                wk = self.W_k[r]
                wv = self.W_v[r]
                for c2 in range(d):
                    xrow[c2] += dqr * wq[c2] + dkr * wk[c2] + dvr * wv[c2]
        return dx

    def param_count(self):
        """参数量：四个 d×d 投影 + 四个偏置（随机特征不训练）"""
        d = self.d_model
        return 4 * d * d + 4 * d

    def sgd_step(self, lr: float):
        """SGD 更新"""
        lr = _la_check_lr(lr, "PerformerAttention.sgd_step")
        for name in ("W_q", "W_k", "W_v", "W_o"):
            _la_apply_sgd(getattr(self, name), self.grads[name], lr)
        for name in ("b_q", "b_k", "b_v", "b_o"):
            param = getattr(self, name)
            grad = self.grads[name]
            for i in range(len(param)):
                param[i] -= lr * grad[i]

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        """Adam 更新"""
        lr = _la_check_lr(lr, "PerformerAttention.adam_step")
        _check_adam_betas(beta1, beta2, "PerformerAttention.adam_step")
        self._adam_t += 1
        t = self._adam_t
        c1 = 1.0 - beta1 ** t
        c2 = 1.0 - beta2 ** t
        for name in ("W_q", "W_k", "W_v", "W_o"):
            _la_apply_adam(getattr(self, name), self.grads[name],
                           getattr(self, "m_" + name), getattr(self, "v_" + name),
                           lr, c1, c2, beta1, beta2, eps)
        for name in ("b_q", "b_k", "b_v", "b_o"):
            param = getattr(self, name)
            grad = self.grads[name]
            mv = getattr(self, "m_" + name)
            vv = getattr(self, "v_" + name)
            for i in range(len(param)):
                g = grad[i]
                mv[i] = beta1 * mv[i] + (1.0 - beta1) * g
                vv[i] = beta2 * vv[i] + (1.0 - beta2) * g * g
                param[i] -= lr * (mv[i] / c1) / (math.sqrt(vv[i] / c2) + eps)


class MLAttention:
    """MLA 简化版：把 K/V 压到低秩潜在向量，再上投影回每头

    标准多头注意力每层要为每个 token 缓存 `2·H·d_k` 个 K/V 数。
    MLA（DeepSeek-V2）的想法是：K/V 其实来自同一个低秩空间，于是

        c_t   = W_dkv x_t + b_dkv              # (d_c)，d_c << H·d_k
        k_th  = W_uk[h] c_t + b_uk[h]          # 每头 (d_k)
        v_th  = W_uv[h] c_t + b_uv[h]

    这样 **KV cache 只需存 c_t**——`T·d_c` 个数，而不是 `T·2·H·d_k`。
    本实现保留 Q 的全秩投影（`W_q`）与标准缩放点积注意力，也保留 causal，
    所以它是「低秩 KV」而不是完整的 DeepSeek-V2 MLA（后者还会压缩 Q、
    并把 RoPE 部分解耦出去）。

    反向最需要注意的是 `c_t` 是 K 和 V 两条链的汇合点：
    `dc_t = W_uk^T dk_t + W_uv^T dv_t`，两条链都要带上。
    """

    def __init__(self, d_model: int, num_heads: int, latent_dim: int = None,
                 causal: bool = False, eps: float = 1e-8):
        if isinstance(d_model, bool) or not isinstance(d_model, int):
            raise ValueError("MLAttention: d_model 必须是正整数，收到 %r" % (d_model,))
        if d_model < 1:
            raise ValueError("MLAttention: d_model 必须 >= 1，收到 %r" % (d_model,))
        if isinstance(num_heads, bool) or not isinstance(num_heads, int):
            raise ValueError("MLAttention: num_heads 必须是正整数，收到 %r"
                             % (num_heads,))
        if num_heads < 1:
            raise ValueError("MLAttention: num_heads 必须 >= 1，收到 %r"
                             % (num_heads,))
        if d_model % num_heads != 0:
            raise ValueError(
                "MLAttention: d_model=%d 必须能被 num_heads=%d 整除"
                % (d_model, num_heads))
        d_k = d_model // num_heads
        if latent_dim is None:
            latent_dim = d_k
        if isinstance(latent_dim, bool) or not isinstance(latent_dim, int):
            raise ValueError("MLAttention: latent_dim 必须是正整数，收到 %r"
                             % (latent_dim,))
        if latent_dim < 1:
            raise ValueError("MLAttention: latent_dim 必须 >= 1，收到 %r"
                             % (latent_dim,))
        if not isinstance(causal, bool):
            raise ValueError("MLAttention: causal 必须是 bool，收到 %r" % (causal,))
        if isinstance(eps, bool) or not isinstance(eps, (int, float)):
            raise ValueError("MLAttention: eps 必须是正数，收到 %r" % (eps,))
        eps = float(eps)
        if not (eps > 0.0) or eps != eps:
            raise ValueError("MLAttention: eps 必须是有限正数，收到 %r" % (eps,))
        self.d_model = d_model
        self.num_heads = num_heads
        self.d_k = d_k
        self.latent_dim = latent_dim
        self.causal = causal
        self.eps = eps
        std = math.sqrt(2.0 / d_model)
        self.W_q = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.b_q = [0.0] * d_model
        # 下投影：d_model -> latent_dim
        self.W_dkv = [[random.gauss(0, std) for _ in range(d_model)]
                      for _ in range(latent_dim)]
        self.b_dkv = [0.0] * latent_dim
        # 上投影：latent_dim -> H*d_k（K 与 V 各一套）
        self.W_uk = [[random.gauss(0, std) for _ in range(latent_dim)]
                     for _ in range(num_heads * d_k)]
        self.b_uk = [0.0] * (num_heads * d_k)
        self.W_uv = [[random.gauss(0, std) for _ in range(latent_dim)]
                     for _ in range(num_heads * d_k)]
        self.b_uv = [0.0] * (num_heads * d_k)
        self.W_o = [[random.gauss(0, std) for _ in range(d_model)]
                    for _ in range(d_model)]
        self.b_o = [0.0] * d_model
        self._init_adam()
        self.zero_grad()
        self.x = None
        self.latent = None
        self.concat = None
        self._cache = None
        self.attn_weights = None

    def zero_grad(self):
        """清零所有参数梯度"""
        d = self.d_model
        dc = self.latent_dim
        hk = self.num_heads * self.d_k

        def z2(r, c):
            return [[0.0] * c for _ in range(r)]

        self.grads = {
            "W_q": z2(d, d), "b_q": [0.0] * d,
            "W_dkv": z2(dc, d), "b_dkv": [0.0] * dc,
            "W_uk": z2(hk, dc), "b_uk": [0.0] * hk,
            "W_uv": z2(hk, dc), "b_uv": [0.0] * hk,
            "W_o": z2(d, d), "b_o": [0.0] * d,
        }

    def _init_adam(self):
        d = self.d_model
        dc = self.latent_dim
        hk = self.num_heads * self.d_k
        shapes = {"W_q": (d, d), "b_q": (d,), "W_dkv": (dc, d), "b_dkv": (dc,),
                  "W_uk": (hk, dc), "b_uk": (hk,), "W_uv": (hk, dc), "b_uv": (hk,),
                  "W_o": (d, d), "b_o": (d,)}
        for name, shp in shapes.items():
            if len(shp) == 1:
                setattr(self, "m_" + name, [0.0] * shp[0])
                setattr(self, "v_" + name, [0.0] * shp[0])
            else:
                setattr(self, "m_" + name, [[0.0] * shp[1] for _ in range(shp[0])])
                setattr(self, "v_" + name, [[0.0] * shp[1] for _ in range(shp[0])])
        self._adam_t = 0

    def train(self):
        """无 dropout，空操作（保持接口统一）"""
        return self

    def eval(self):
        """无 dropout，空操作（保持接口统一）"""
        return self

    def kv_cache_size(self, seq_len: int) -> int:
        """长度为 seq_len 的序列在 KV cache 里要存多少个标量（MLA 是 T·d_c）"""
        return int(seq_len) * self.latent_dim

    def full_kv_cache_size(self, seq_len: int) -> int:
        """同样长度下标准多头注意力要存多少（T·2·H·d_k），用于对比"""
        return int(seq_len) * 2 * self.num_heads * self.d_k

    def forward(self, x_seq):
        """x_seq: (T, d_model) → (T, d_model)"""
        if not x_seq:
            raise ValueError("MLAttention.forward: 输入序列不能为空")
        d = self.d_model
        dc = self.latent_dim
        d_k = self.d_k
        H = self.num_heads
        T = len(x_seq)
        for t, row in enumerate(x_seq):
            if len(row) != d:
                raise ValueError(
                    "MLAttention.forward: 第 %d 个 token 的维度 %d 与 d_model=%d 不一致"
                    % (t, len(row), d))
        q_all = [[sum(map(_mul, self.W_q[r], xt)) + self.b_q[r] for r in range(d)]
                 for xt in x_seq]
        latent = [[sum(map(_mul, self.W_dkv[r], xt)) + self.b_dkv[r]
                   for r in range(dc)] for xt in x_seq]
        k_all = [[sum(map(_mul, self.W_uk[r], ct)) + self.b_uk[r] for r in range(H * d_k)]
                 for ct in latent]
        v_all = [[sum(map(_mul, self.W_uv[r], ct)) + self.b_uv[r] for r in range(H * d_k)]
                 for ct in latent]
        scale = 1.0 / math.sqrt(d_k)
        concat = [[0.0] * d for _ in range(T)]
        cache = []
        weights_all = []
        for head in range(H):
            off = head * d_k
            qh = [q_all[t][off:off + d_k] for t in range(T)]
            kh = [k_all[t][off:off + d_k] for t in range(T)]
            vh = [v_all[t][off:off + d_k] for t in range(T)]
            rows = []
            outs = []
            for t in range(T):
                scores = []
                for s in range(T):
                    if self.causal and s > t:
                        scores.append(None)
                        continue
                    scores.append(sum(qh[t][j] * kh[s][j] for j in range(d_k)) * scale)
                m = max(v for v in scores if v is not None)
                ex = [None if v is None else math.exp(v - m) for v in scores]
                tot = sum(v for v in ex if v is not None) + self.eps
                probs = [0.0 if v is None else v / tot for v in ex]
                rows.append(probs)
                outs.append([sum(probs[s] * vh[s][j] for s in range(T))
                             for j in range(d_k)])
            for t in range(T):
                for j in range(d_k):
                    concat[t][off + j] = outs[t][j]
            cache.append({"q": qh, "k": kh, "v": vh, "probs": rows, "out": outs})
            weights_all.append(rows)
        y = [[sum(map(_mul, self.W_o[r], concat[t])) + self.b_o[r] for r in range(d)]
             for t in range(T)]
        self.x = [list(r) for r in x_seq]
        self.latent = latent
        self.concat = concat
        self._cache = cache
        self.attn_weights = weights_all
        return y

    def backward(self, dout_seq):
        """dout_seq: (T, d_model) → (T, d_model) 输入梯度"""
        if self._cache is None:
            raise RuntimeError("MLAttention.backward: 必须先 forward")
        d = self.d_model
        dc = self.latent_dim
        d_k = self.d_k
        H = self.num_heads
        T = len(self.x)
        if len(dout_seq) != T:
            raise ValueError(
                "MLAttention.backward: dout 长度 %d 与 forward 的 %d 不一致"
                % (len(dout_seq), T))
        scale = 1.0 / math.sqrt(d_k)
        dconcat = [[sum(dout_seq[t][j] * self.W_o[j][r] for j in range(d))
                    for r in range(d)] for t in range(T)]
        for r in range(d):
            wrow = self.grads["W_o"][r]
            sb = 0.0
            for t in range(T):
                dt = dout_seq[t][r]
                sb += dt
                if dt != 0.0:
                    crow = self.concat[t]
                    for c in range(d):
                        wrow[c] += dt * crow[c]
            self.grads["b_o"][r] += sb
        dq_all = [[0.0] * d for _ in range(T)]
        dk_all = [[0.0] * (H * d_k) for _ in range(T)]
        dv_all = [[0.0] * (H * d_k) for _ in range(T)]
        for head in range(H):
            off = head * d_k
            c = self._cache[head]
            qh, kh, vh = c["q"], c["k"], c["v"]
            probs, outs = c["probs"], c["out"]
            dout = [dconcat[t][off:off + d_k] for t in range(T)]
            dprobs = [[0.0] * T for _ in range(T)]
            dvh = [[0.0] * d_k for _ in range(T)]
            for t in range(T):
                for s in range(T):
                    if self.causal and s > t:
                        continue
                    dvh[s] = [dvh[s][j] + probs[t][s] * dout[t][j] for j in range(d_k)]
                    dprobs[t][s] = sum(dout[t][j] * vh[s][j] for j in range(d_k))
            dscores = [[0.0] * T for _ in range(T)]
            for t in range(T):
                dot = 0.0
                for s in range(T):
                    if self.causal and s > t:
                        continue
                    dot += probs[t][s] * dprobs[t][s]
                for s in range(T):
                    if self.causal and s > t:
                        continue
                    dscores[t][s] = probs[t][s] * (dprobs[t][s] - dot)
            dqh = [[0.0] * d_k for _ in range(T)]
            dkh = [[0.0] * d_k for _ in range(T)]
            for t in range(T):
                for s in range(T):
                    if self.causal and s > t:
                        continue
                    g = dscores[t][s] * scale
                    if g == 0.0:
                        continue
                    for j in range(d_k):
                        dqh[t][j] += g * kh[s][j]
                        dkh[s][j] += g * qh[t][j]
            for t in range(T):
                for j in range(d_k):
                    dq_all[t][off + j] = dqh[t][j]
                    dk_all[t][off + j] = dkh[t][j]
                    dv_all[t][off + j] = dvh[t][j]
        # 上投影：dk_all/dv_all -> W_uk/W_uv 的梯度与 dc
        dlatent = [[0.0] * dc for _ in range(T)]
        for r in range(H * d_k):
            wuk = self.grads["W_uk"][r]
            wuv = self.grads["W_uv"][r]
            sbk = sbv = 0.0
            for t in range(T):
                dkr = dk_all[t][r]
                dvr = dv_all[t][r]
                sbk += dkr
                sbv += dvr
                if dkr == 0.0 and dvr == 0.0:
                    continue
                ct = self.latent[t]
                drow = dlatent[t]
                if dkr != 0.0:
                    for c2 in range(dc):
                        wuk[c2] += dkr * ct[c2]
                        drow[c2] += dkr * self.W_uk[r][c2]
                if dvr != 0.0:
                    for c2 in range(dc):
                        wuv[c2] += dvr * ct[c2]
                        drow[c2] += dvr * self.W_uv[r][c2]
            self.grads["b_uk"][r] += sbk
            self.grads["b_uv"][r] += sbv
        # 下投影：dc -> W_dkv 的梯度与 dx
        for r in range(dc):
            wrow = self.grads["W_dkv"][r]
            sb = 0.0
            for t in range(T):
                dr = dlatent[t][r]
                sb += dr
                if dr != 0.0:
                    xt = self.x[t]
                    for c2 in range(d):
                        wrow[c2] += dr * xt[c2]
            self.grads["b_dkv"][r] += sb
        # W_q 与 dx
        for r in range(d):
            wrow = self.grads["W_q"][r]
            sb = 0.0
            for t in range(T):
                dr = dq_all[t][r]
                sb += dr
                if dr != 0.0:
                    xt = self.x[t]
                    for c2 in range(d):
                        wrow[c2] += dr * xt[c2]
            self.grads["b_q"][r] += sb
        dx = [[0.0] * d for _ in range(T)]
        for t in range(T):
            xrow = dx[t]
            for r in range(d):
                dqr = dq_all[t][r]
                if dqr != 0.0:
                    wq = self.W_q[r]
                    for c2 in range(d):
                        xrow[c2] += dqr * wq[c2]
            for r in range(dc):
                dr = dlatent[t][r]
                if dr != 0.0:
                    wd = self.W_dkv[r]
                    for c2 in range(d):
                        xrow[c2] += dr * wd[c2]
        return dx

    def param_count(self):
        """参数量：Q/O 各 d²+d，下投影 d_c·d，上投影 2·H·d_k·d_c + 2·H·d_k"""
        d = self.d_model
        dc = self.latent_dim
        hk = self.num_heads * self.d_k
        return (2 * d * d + 2 * d) + dc * d + dc + 2 * hk * dc + 2 * hk

    def sgd_step(self, lr: float):
        """SGD 更新"""
        lr = _la_check_lr(lr, "MLAttention.sgd_step")
        for name in ("W_q", "W_dkv", "W_uk", "W_uv", "W_o"):
            _la_apply_sgd(getattr(self, name), self.grads[name], lr)
        for name in ("b_q", "b_dkv", "b_uk", "b_uv", "b_o"):
            param = getattr(self, name)
            grad = self.grads[name]
            for i in range(len(param)):
                param[i] -= lr * grad[i]

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        """Adam 更新"""
        lr = _la_check_lr(lr, "MLAttention.adam_step")
        _check_adam_betas(beta1, beta2, "MLAttention.adam_step")
        self._adam_t += 1
        t = self._adam_t
        c1 = 1.0 - beta1 ** t
        c2 = 1.0 - beta2 ** t
        for name in ("W_q", "W_dkv", "W_uk", "W_uv", "W_o"):
            _la_apply_adam(getattr(self, name), self.grads[name],
                           getattr(self, "m_" + name), getattr(self, "v_" + name),
                           lr, c1, c2, beta1, beta2, eps)
        for name in ("b_q", "b_dkv", "b_uk", "b_uv", "b_o"):
            param = getattr(self, name)
            grad = self.grads[name]
            mv = getattr(self, "m_" + name)
            vv = getattr(self, "v_" + name)
            for i in range(len(param)):
                g = grad[i]
                mv[i] = beta1 * mv[i] + (1.0 - beta1) * g
                vv[i] = beta2 * vv[i] + (1.0 - beta2) * g * g
                param[i] -= lr * (mv[i] / c1) / (math.sqrt(vv[i] / c2) + eps)


class LearnedPositionalEncoding:
    """可学习的位置编码表（BERT / GPT-2 式）：`out[t] = x[t] + table[t]`

    `table` 形状 (max_len, d_model)，随机初始化后与模型一起训练。
    与 `PositionalEncoding`（固定 sin/cos、无参数）的区别就是**位置向量可学**。

    forward 超长时按需扩展表格（新行用同分布的随机数填充并记录梯度位置），
    不会静默截断；backward 返回 `(dx, d_table)`，其中 `d_table` 只覆盖本次
    用到的前 seq_len 行。
    """

    def __init__(self, d_model: int, max_len: int = 5000, std: float = None):
        if isinstance(d_model, bool) or not isinstance(d_model, int):
            raise ValueError(
                f"LearnedPositionalEncoding: d_model 必须是正整数，收到 {d_model!r}"
            )
        if d_model < 1:
            raise ValueError(
                f"LearnedPositionalEncoding: d_model 必须 >= 1，收到 {d_model}"
            )
        if isinstance(max_len, bool) or not isinstance(max_len, int):
            raise ValueError(
                f"LearnedPositionalEncoding: max_len 必须是正整数，收到 {max_len!r}"
            )
        if max_len < 1:
            raise ValueError(
                f"LearnedPositionalEncoding: max_len 必须 >= 1，收到 {max_len}"
            )
        if std is None:
            std = 0.02
        if isinstance(std, bool) or not isinstance(std, (int, float)):
            raise ValueError(
                f"LearnedPositionalEncoding: std 必须是正数，收到 {std!r}"
            )
        std = float(std)
        if not (std > 0.0) or std != std:
            raise ValueError(
                f"LearnedPositionalEncoding: std 必须是有限正数，收到 {std!r}"
            )
        self.d_model = d_model
        self.std = std
        self.table = [[random.gauss(0.0, std) for _ in range(d_model)]
                      for _ in range(max_len)]
        self.m_table = [[0.0] * d_model for _ in range(max_len)]
        self.v_table = [[0.0] * d_model for _ in range(max_len)]
        self._adam_t = 0
        self.grad_table = [[0.0] * d_model for _ in range(max_len)]
        self.seq_len = 0

    def _ensure_len(self, n: int):
        """按需扩展编码表：新行随机初始化，同时扩展梯度/Adam 状态"""
        while len(self.table) < n:
            self.table.append([random.gauss(0.0, self.std)
                               for _ in range(self.d_model)])
            self.m_table.append([0.0] * self.d_model)
            self.v_table.append([0.0] * self.d_model)
            self.grad_table.append([0.0] * self.d_model)

    def zero_grad(self):
        """清零位置编码的梯度"""
        self.grad_table = [[0.0] * self.d_model for _ in range(len(self.table))]

    def forward(self, x_seq):
        """x_seq: (seq_len, d_model) → x_seq + table[:seq_len]"""
        for t, row in enumerate(x_seq):
            if len(row) != self.d_model:
                raise ValueError(
                    "LearnedPositionalEncoding.forward: 第 %d 个 token 的维度 %d "
                    "与 d_model=%d 不一致" % (t, len(row), self.d_model)
                )
        self._ensure_len(len(x_seq))
        self.seq_len = len(x_seq)
        return [[x_seq[t][j] + self.table[t][j] for j in range(self.d_model)]
                for t in range(len(x_seq))]

    def backward(self, dout_seq):
        """返回 (dx, d_table)；位置编码对每个位置的偏导就是该位置的 dout"""
        if len(dout_seq) != self.seq_len:
            raise ValueError(
                "LearnedPositionalEncoding.backward: dout 的序列长度 %d 与 forward "
                "的 %d 不一致" % (len(dout_seq), self.seq_len)
            )
        dx = [list(row) for row in dout_seq]
        for t in range(self.seq_len):
            for j in range(self.d_model):
                self.grad_table[t][j] += dout_seq[t][j]
        return dx, [list(row) for row in self.grad_table[:self.seq_len]]

    def param_count(self):
        """参数量：表格总元素数"""
        return len(self.table) * self.d_model

    def sgd_step(self, lr: float):
        """SGD 更新位置编码表"""
        if isinstance(lr, bool) or not isinstance(lr, (int, float)):
            raise ValueError(f"LearnedPositionalEncoding.sgd_step: lr 必须是数字，收到 {lr!r}")
        lr = float(lr)
        if not (lr >= 0.0) or lr != lr:
            raise ValueError(
                f"LearnedPositionalEncoding.sgd_step: lr 必须是非负有限数，收到 {lr!r}"
            )
        for t in range(len(self.table)):
            row = self.table[t]
            grad = self.grad_table[t]
            for j in range(self.d_model):
                row[j] -= lr * grad[j]

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        """Adam 更新位置编码表"""
        if isinstance(lr, bool) or not isinstance(lr, (int, float)):
            raise ValueError(f"LearnedPositionalEncoding.adam_step: lr 必须是数字，收到 {lr!r}")
        lr = float(lr)
        if not (lr >= 0.0) or lr != lr:
            raise ValueError(
                f"LearnedPositionalEncoding.adam_step: lr 必须是非负有限数，收到 {lr!r}"
            )
        _check_adam_betas(beta1, beta2, "LearnedPositionalEncoding.adam_step")
        self._adam_t += 1
        t = self._adam_t
        c1 = 1.0 - beta1 ** t
        c2 = 1.0 - beta2 ** t
        for r in range(len(self.table)):
            row = self.table[r]
            grad = self.grad_table[r]
            mrow = self.m_table[r]
            vrow = self.v_table[r]
            for j in range(self.d_model):
                g = grad[j]
                mrow[j] = beta1 * mrow[j] + (1.0 - beta1) * g
                vrow[j] = beta2 * vrow[j] + (1.0 - beta2) * g * g
                row[j] -= lr * (mrow[j] / c1) / (math.sqrt(vrow[j] / c2) + eps)


class Embedding:
    """词嵌入层：查表操作，将索引映射为稠密向量"""

    def __init__(self, vocab_size: int, embed_dim: int):
        self.vocab_size = vocab_size
        self.embed_dim = embed_dim
        std = math.sqrt(2.0 / vocab_size)
        self.weight = [[random.gauss(0, std) for _ in range(embed_dim)] for _ in range(vocab_size)]
        self.zero_grad()
        self.indices = None  # 缓存查询的索引列表

    def forward(self, indices):
        """indices: List[int] → List[List[float]] (seq_len, embed_dim)"""
        # 负数索引会静默回绕到词表末尾，必须拦掉
        for t, idx in enumerate(indices):
            if not isinstance(idx, int) or not 0 <= idx < self.vocab_size:
                raise ValueError(
                    f"Embedding.forward: 第 {t} 个索引 {idx!r} 越界"
                    f"（词表大小 {self.vocab_size}）"
                )
        self.indices = indices
        return [list(self.weight[idx]) for idx in indices]

    def zero_grad(self):
        """初始化/清零梯度缓冲区"""
        self.grad_weight = [[0.0] * self.embed_dim for _ in range(self.vocab_size)]

    def backward(self, dout_seq):
        """dout_seq: (seq_len, embed_dim) → 返回 None（无输入梯度），内部累积 grad_weight"""
        for t, idx in enumerate(self.indices):
            for j in range(self.embed_dim):
                self.grad_weight[idx][j] += dout_seq[t][j]
        return None

    def sgd_step(self, lr: float):
        """对词向量做一次 SGD 更新（原实现只累积梯度、权重永远不变）"""
        for idx, row in enumerate(self.grad_weight):
            wrow = self.weight[idx]
            for j in range(self.embed_dim):
                wrow[j] -= lr * row[j]
        self.zero_grad()


# 因果语言模型 (CausalLM)：causal mask 的直接用途。
# 它组合 Embedding + PositionalEncoding + TransformerEncoder(causal=True)，
# 所以紧跟在 Embedding 之后定义（三个依赖类都在上面）。

def _zeros_like(p):
    """按参数结构生成同形状的零数组（Adam 的一阶/二阶矩用）"""
    if p and isinstance(p[0], (list, tuple)):
        return [[0.0] * len(row) for row in p]
    return [0.0] * len(p)


def _adam_apply(param, grad, m, v, t, lr, b1=0.9, b2=0.999, eps=1e-8):
    """就地 Adam 更新；param / grad / m / v 结构一致（1D 或 2D 列表）"""
    c1 = 1.0 - b1 ** t
    c2 = 1.0 - b2 ** t
    if param and isinstance(param[0], (list, tuple)):
        for i in range(len(param)):
            pi, gi, mi, vi = param[i], grad[i], m[i], v[i]
            for j in range(len(pi)):
                g = gi[j]
                mi[j] = b1 * mi[j] + (1.0 - b1) * g
                vi[j] = b2 * vi[j] + (1.0 - b2) * g * g
                pi[j] -= lr * (mi[j] / c1) / (math.sqrt(vi[j] / c2) + eps)
    else:
        for i in range(len(param)):
            g = grad[i]
            m[i] = b1 * m[i] + (1.0 - b1) * g
            v[i] = b2 * v[i] + (1.0 - b2) * g * g
            param[i] -= lr * (m[i] / c1) / (math.sqrt(v[i] / c2) + eps)


def _log_softmax_row(v):
    """对一维列表做 log-softmax（数值稳定版，供束搜索累加对数概率用）

    数值边界：含 NaN 抛 ValueError；含 +inf 时 +inf 项得 -log(个数)、
    其余得 -inf；整行 -inf 返回全 -inf。
    """
    _reject_nan_row(v, "_log_softmax_row")
    mx = max(v)
    if mx == float("-inf"):
        return [float("-inf")] * len(v)
    if mx == float("inf"):
        hits = sum(1 for x in v if x == float("inf"))
        share = -math.log(hits)
        return [(share if x == float("inf") else float("-inf")) for x in v]
    exps = [math.exp(x - mx) for x in v]
    log_s = math.log(sum(exps)) + mx
    return [x - log_s for x in v]


def _lm_copy_into(cur, saved, name):
    """递归把存档里的嵌套 list 写进 cur，顺带校验形状、类型与有限性"""
    if not isinstance(cur, list):
        raise ValueError(f"LM 参数 {name}: 无法写入标量槽位")
    if not isinstance(saved, list):
        raise ValueError(f"LM 参数 {name}: 期望数组，存档里是 {type(saved).__name__}")
    if len(cur) != len(saved):
        raise ValueError(
            f"LM 参数 {name}: 长度不符（模型 {len(cur)}，存档 {len(saved)}）")
    for i in range(len(cur)):
        if isinstance(cur[i], list):
            _lm_copy_into(cur[i], saved[i], name)
            continue
        val = saved[i]
        if isinstance(val, bool) or not isinstance(val, (int, float)):
            raise ValueError(f"LM 参数 {name}: 期望数值，存档里是 {val!r}")
        val = float(val)
        if val != val or val in (float("inf"), float("-inf")):
            raise ValueError(f"LM 参数 {name}: 存档里有非有限值 {val!r}")
        cur[i] = val


def _lm_save(lm, kind, filepath, include_optimizer=False, quiet=False):
    """把 LM 的配置 + 全部参数（可选 Adam 状态）写成 JSON"""
    if not isinstance(filepath, str) or not filepath:
        raise ValueError(f"save: filepath 必须是非空字符串，收到 {filepath!r}")
    data = {
        "format": "ai_lm_v1",
        "kind": kind,
        "config": lm._config(),
        "params": {name: param for name, param, _ in lm._named_params()},
    }
    if include_optimizer:
        data["optimizer"] = {
            "step_count": int(getattr(lm, "step_count", 0)),
            "m": {k: v for k, v in getattr(lm, "_adam_m", {}).items()},
            "v": {k: v for k, v in getattr(lm, "_adam_v", {}).items()},
        }
    with io.open(filepath, "w", encoding="utf-8") as f:
        # allow_nan=False：参数发散成 NaN/Inf 时宁可保存失败，也不写出
        # 不合 RFC-4627 的 JSON（save_model 一直是这样做的）
        json.dump(data, f, ensure_ascii=False, indent=2, allow_nan=False)
    if not quiet:
        print(f"已保存 {kind} 模型: {filepath}")
    return filepath


def _lm_load(filepath, restore_optimizer=False):
    """从 `_lm_save` 写出的 JSON 恢复 LM（结构与参数逐位还原）"""
    with io.open(filepath, "r", encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, dict) or data.get("format") != "ai_lm_v1":
        raise ValueError(f"load: {filepath} 不是 ai_lm_v1 格式的 LM 存档")
    kind = data.get("kind")
    classes = {"causal": CausalLM, "seq2seq": Seq2SeqLM}
    if kind not in classes:
        raise ValueError(f"load: 未知的模型类型 {kind!r}（支持 {sorted(classes)}）")
    cfg = data.get("config") or {}
    # 存档里 window/num_kv_heads 可能是 null，构造器接受 None
    try:
        model = classes[kind](**cfg)
    except TypeError as e:
        raise ValueError(f"load: 存档的配置与构造器不匹配（{e}）")
    saved_params = data.get("params") or {}
    named = {name: param for name, param, _ in model._named_params()}
    missing = sorted(set(named) - set(saved_params))
    extra = sorted(set(saved_params) - set(named))
    if missing or extra:
        raise ValueError(
            f"load: 参数块与存档不一致（缺 {missing[:3]}，多 {extra[:3]}）")
    for name, param in named.items():
        _lm_copy_into(param, saved_params[name], name)
    if restore_optimizer:
        opt = data.get("optimizer")
        if not opt:
            raise ValueError(
                "load: 存档里没有优化器状态（保存时需要 include_optimizer=True），"
                "无法 restore_optimizer=True")
        model.step_count = int(opt.get("step_count", 0))
        for key, store in (("m", model._adam_m), ("v", model._adam_v)):
            saved_bufs = opt.get(key) or {}
            store.clear()
            for name, param, _ in model._named_params():
                if name not in saved_bufs:
                    raise ValueError(f"load: 优化器状态缺少参数块 {name!r}")
                buf = _zeros_like(param)
                _lm_copy_into(buf, saved_bufs[name], f"optimizer.{key}.{name}")
                store[name] = buf
    return model


def _check_pad_mask(mask, length, who):
    """校验 pad_mask：与序列等长的 0/1 列表，至少一个有效位；返回 bool 列表

    只支持**右填充**（有效位在前、0 在后）：CausalLM 用 `valid[:-1]` 当 key_mask，
    左填充会把 key_mask 截错位置，算出来的 loss 是错的但不会报错。
    """
    if not isinstance(mask, (list, tuple)):
        raise ValueError(f"{who}: pad_mask 必须是列表，收到 {type(mask).__name__}")
    if len(mask) != length:
        raise ValueError(f"{who}: pad_mask 长度 {len(mask)} 与序列长度 {length} 不一致")
    out = []
    for i, m in enumerate(mask):
        if isinstance(m, bool):
            out.append(m)
        elif isinstance(m, int) and m in (0, 1):
            out.append(bool(m))
        else:
            raise ValueError(f"{who}: pad_mask[{i}] 必须是 0 或 1，收到 {m!r}")
    if not any(out):
        raise ValueError(f"{who}: pad_mask 至少要有 1 个有效位置")
    seen_pad = False
    for i, m in enumerate(out):
        if not m:
            seen_pad = True
        elif seen_pad:
            raise ValueError(
                f"{who}: pad_mask 只支持右填充（0 之后不能再出现 1，位置 {i}）")
    return out


def _check_top_k(top_k, who):
    """校验 top_k：非负整数（0 表示不过滤）

    float/bool/负数都会让 `order[:int(top_k)]` 静默退化成空集或差一位，
    采样结果变成「永远是最后一个 token」或丢掉最高概率项，所以一律拒绝。
    """
    if isinstance(top_k, bool) or not isinstance(top_k, int):
        raise ValueError(f"{who}: top_k 必须是 >= 0 的整数（0 表示不过滤），收到 {top_k!r}")
    if top_k < 0:
        raise ValueError(f"{who}: top_k 必须 >= 0，收到 {top_k!r}")
    return top_k


def _check_token_ids(ids, vocab_size, who):
    """校验一串 token id 都在 [0, vocab_size) 内

    Python 的负索引会让 `probs[-1]` 静默指向「最后一类」，loss 与梯度全算在错类上；
    越界的正数反而抛 IndexError。统一在这里报 ValueError。
    """
    if not isinstance(ids, (list, tuple)):
        raise ValueError(f"{who}: token id 序列必须是列表，收到 {type(ids).__name__}")
    out = []
    for i, v in enumerate(ids):
        if isinstance(v, bool) or not isinstance(v, int) or not 0 <= v < vocab_size:
            raise ValueError(
                f"{who}: 第 {i} 个 token id 非法（{v!r}），必须在 [0, {vocab_size}) 内")
        out.append(v)
    return out


def _check_finite_logits(logits, who):
    """logits 出现 NaN/Inf 说明参数已经坏了；直接报错，别让它被 loss 的 clamp 掩盖"""
    for t, row in enumerate(logits):
        for v in row:
            if v != v or v == float("inf") or v == float("-inf"):
                raise ValueError(f"{who}: 第 {t} 行 logits 含 NaN/Inf，参数可能已损坏")


def _check_penalty_args(repetition_penalty, presence_penalty, frequency_penalty,
                        no_repeat_ngram_size, who):
    """校验生成惩罚参数（重复/存在/频率/禁重复 n-gram）"""
    for name, val in (("repetition_penalty", repetition_penalty),
                      ("presence_penalty", presence_penalty),
                      ("frequency_penalty", frequency_penalty)):
        if isinstance(val, bool) or not isinstance(val, (int, float)):
            raise ValueError(f"{who}: {name} 必须是数字，收到 {val!r}")
        if val != val or val in (float("inf"), float("-inf")):
            raise ValueError(f"{who}: {name} 必须是有限值，收到 {val!r}")
    if repetition_penalty <= 0:
        raise ValueError(
            f"{who}: repetition_penalty 必须 > 0，收到 {repetition_penalty!r}")
    if isinstance(no_repeat_ngram_size, bool) or not isinstance(no_repeat_ngram_size, int) \
            or no_repeat_ngram_size < 0:
        raise ValueError(
            f"{who}: no_repeat_ngram_size 必须是 >= 0 的整数，收到 {no_repeat_ngram_size!r}")
    if no_repeat_ngram_size == 1:
        # n=1 会把所有已出现的 token 全禁掉，等于只能输出新 token，几乎必然无解
        raise ValueError(f"{who}: no_repeat_ngram_size=1 没有意义（会禁用所有已出现的 token）")


def _mask_min_p(logits, min_p: float):
    """把概率低于 min_p * max_prob 的 token 置 -inf（min_p<=0 时原样返回）"""
    if min_p <= 0.0:
        return logits
    probs = _softmax_row(logits)
    peak = max(probs)
    thresh = min_p * peak
    return [v if probs[i] >= thresh else float("-inf") for i, v in enumerate(logits)]


def _check_min_p(min_p, who):
    """校验 min_p（(0,1) 内的阈值；0 表示不过滤）"""
    if isinstance(min_p, bool) or not isinstance(min_p, (int, float)):
        raise ValueError(f"{who}: min_p 必须是数字，收到 {min_p!r}")
    if min_p != min_p or not (0.0 <= min_p < 1.0):
        raise ValueError(f"{who}: min_p 必须在 [0,1) 内，收到 {min_p!r}")
    return float(min_p)


def _apply_generation_penalties(logits, ids, repetition_penalty: float = 1.0,
                                presence_penalty: float = 0.0,
                                frequency_penalty: float = 0.0,
                                no_repeat_ngram_size: int = 0):
    """按已生成的 token 调整 logits（默认参数下原样返回，保证旧行为逐位不变）

    - repetition_penalty: >1 抑制重复（正 logit 除以它、负 logit 乘以它）
    - presence_penalty: 出现过就扣一次
    - frequency_penalty: 按出现次数扣
    - no_repeat_ngram_size=n: 禁止让末尾 (n-1)-gram 立刻再重复一次
    """
    has_ngram = no_repeat_ngram_size and no_repeat_ngram_size >= 2
    if (repetition_penalty == 1.0 and presence_penalty == 0.0
            and frequency_penalty == 0.0 and not has_ngram):
        return logits

    out = list(logits)
    vocab = len(out)
    counts = {}
    for tok in ids:
        if isinstance(tok, int) and not isinstance(tok, bool) and 0 <= tok < vocab:
            counts[tok] = counts.get(tok, 0) + 1

    if repetition_penalty != 1.0:
        for tok in counts:
            if out[tok] > 0:
                out[tok] = out[tok] / repetition_penalty
            else:
                out[tok] = out[tok] * repetition_penalty
    if presence_penalty:
        for tok in counts:
            out[tok] -= presence_penalty
    if frequency_penalty:
        for tok, c in counts.items():
            out[tok] -= frequency_penalty * c
    if has_ngram:
        n = int(no_repeat_ngram_size)
        if len(ids) >= n - 1:
            prefix = list(ids[len(ids) - (n - 1):])
            for i in range(len(ids) - (n - 1)):
                if list(ids[i:i + n - 1]) == prefix:
                    nxt = ids[i + n - 1]
                    if isinstance(nxt, int) and not isinstance(nxt, bool) and 0 <= nxt < vocab:
                        out[nxt] = float("-inf")
    return out


class MaskedLM:
    """掩码语言模型（BERT 式）：Embedding → 位置编码 → **双向** Transformer → 词表头

    与 `CausalLM` 的区别只有两点：
      1. 注意力**不加因果掩码**，每个位置都能看到左右上下文；
      2. 训练目标是「还原被遮住的位置」，而不是预测下一个 token。

    遮罩策略与 BERT 一致：随机选 `mask_prob` 比例的位置，其中 80% 换成
    `mask_id`、10% 换成随机 token、10% 保持不变（保持不变的位置仍然要预测，
    否则模型会只学会「看到 mask 才输出」）。`mask_id` 默认取 `vocab_size`
    （额外占一行词向量），不会与真实 token 冲突。

    用法::

        lm = MaskedLM(vocab_size=10, d_model=16, num_heads=2, num_layers=1)
        lm.fit([[1, 2, 3, 4, 5, 6]], epochs=200, lr=0.01)
        lm.predict([1, 9, 3, 4, 9, 6], [1, 4])   # 填空
    """

    def __init__(self, vocab_size: int, d_model: int = 32, num_heads: int = 4,
                 d_ff: int = 64, num_layers: int = 2, max_len: int = 64,
                 dropout: float = 0.0, mask_prob: float = 0.15,
                 replace_prob: float = 0.1):
        if not isinstance(vocab_size, int) or isinstance(vocab_size, bool) or vocab_size < 1:
            raise ValueError(f"MaskedLM: vocab_size 必须是正整数，收到 {vocab_size!r}")
        if not isinstance(max_len, int) or isinstance(max_len, bool) or max_len < 1:
            raise ValueError(f"MaskedLM: max_len 必须 >= 1，收到 {max_len!r}")
        if not isinstance(num_layers, int) or isinstance(num_layers, bool) or num_layers < 1:
            raise ValueError(f"MaskedLM: num_layers 必须 >= 1，收到 {num_layers!r}")
        for name, val in (("mask_prob", mask_prob), ("replace_prob", replace_prob)):
            if isinstance(val, bool) or not isinstance(val, (int, float)) or not 0.0 < float(val) < 1.0:
                raise ValueError(f"MaskedLM: {name} 必须在 (0,1) 内，收到 {val!r}")
        self.vocab_size = vocab_size
        self.d_model = d_model
        self.max_len = max_len
        self.num_heads = num_heads
        self.d_ff = d_ff
        self.num_layers = num_layers
        self.dropout = dropout
        self.mask_prob = float(mask_prob)
        self.replace_prob = float(replace_prob)
        # mask 用一个词表之外的 id，避免和真实 token 混淆
        self.mask_id = vocab_size

        self.embedding = Embedding(vocab_size + 1, d_model)
        self.pos = PositionalEncoding(d_model, max_len)
        self.encoder = TransformerEncoder(d_model, num_heads, d_ff, num_layers,
                                          dropout, causal=False)

        std = math.sqrt(2.0 / d_model)
        self.W_out = [[random.gauss(0, std) for _ in range(d_model)] for _ in range(vocab_size)]
        self.b_out = [0.0] * vocab_size
        self.zero_grad()
        self.step_count = 0
        self._adam_m = {}
        self._adam_v = {}
        self.h = None

    def train(self):
        """训练模式（Dropout 生效）"""
        self.encoder.train()
        return self

    def eval(self):
        """推理模式（关闭 Dropout，同一输入输出确定）"""
        self.encoder.eval()
        return self

    def zero_grad(self):
        """清零全部梯度"""
        self.embedding.zero_grad()
        self.encoder.zero_grad()
        self.grads = {
            "W_out": [[0.0] * self.d_model for _ in range(self.vocab_size)],
            "b_out": [0.0] * self.vocab_size,
        }

    def _named_params(self):
        """产出 (名字, 参数, 梯度)；必须在 `zero_grad()` 之后调用"""
        yield "emb.weight", self.embedding.weight, self.embedding.grad_weight
        for li, layer in enumerate(self.encoder.layers):
            attn = layer.self_attn
            for k in ("W_q", "W_k", "W_v", "W_o", "b_q", "b_k", "b_v", "b_o"):
                yield f"L{li}.attn.{k}", getattr(attn, k), attn.grads[k]
            ffn = layer.ffn
            for k in ("W1", "b1", "W2", "b2"):
                yield f"L{li}.ffn.{k}", getattr(ffn, k), ffn.grads[k]
            yield f"L{li}.ln1.gamma", layer.ln1.gamma, layer.grads["ln1_gamma"]
            yield f"L{li}.ln1.beta", layer.ln1.beta, layer.grads["ln1_beta"]
            yield f"L{li}.ln2.gamma", layer.ln2.gamma, layer.grads["ln2_gamma"]
            yield f"L{li}.ln2.beta", layer.ln2.beta, layer.grads["ln2_beta"]
        yield "out.W", self.W_out, self.grads["W_out"]
        yield "out.b", self.b_out, self.grads["b_out"]

    def param_count(self):
        """参数总数（标量个数）"""
        return sum(len(p) if not isinstance(p[0], list) else
                   sum(len(r) for r in p)
                   for _, p, _ in self._named_params())

    def mask_tokens(self, ids, rng=None):
        """按 BERT 策略遮罩，返回 (corrupted_ids, positions, targets)

        positions 是**被遮住的位置下标**（升序），targets 是对应位置的原始 token。
        至少遮一个位置：短序列随机选时可能一个都没选中，这里强制补一个。
        """
        ids = _check_token_ids(ids, self.vocab_size, "MaskedLM.mask_tokens")
        rng = random if rng is None else rng
        if not ids:
            raise ValueError("MaskedLM.mask_tokens: ids 不能为空")
        positions = [t for t in range(len(ids)) if rng.random() < self.mask_prob]
        if not positions:
            positions = [rng.randrange(len(ids))]
        corrupted = list(ids)
        for t in positions:
            r = rng.random()
            if r < 0.8:
                corrupted[t] = self.mask_id
            elif r < 0.9:
                corrupted[t] = rng.randrange(self.vocab_size)
            # 剩下 10% 保持原样（但仍计入预测目标）
        return corrupted, positions, [ids[t] for t in positions]

    def forward(self, ids):
        """ids: List[int] → logits (seq_len, vocab_size)（bidirectional，无因果掩码）"""
        if not ids:
            raise ValueError("MaskedLM.forward: ids 不能为空")
        if len(ids) > self.max_len:
            raise ValueError(
                f"MaskedLM.forward: 序列长度 {len(ids)} 超过 max_len={self.max_len}")
        ids = _check_token_ids(ids, self.vocab_size + 1, "MaskedLM.forward")
        emb = self.embedding.forward(ids)
        x = self.pos.forward(emb)
        h = self.encoder.forward(x)
        self.h = h
        logits = _matmul(h, _transpose(self.W_out))
        for t in range(len(h)):
            for v in range(self.vocab_size):
                logits[t][v] += self.b_out[v]
        return logits

    def _loss_and_backward(self, ids, positions, targets, grad_scale: float = 1.0):
        """只在 positions 上算交叉熵并反传，返回该条序列的平均 loss

        ids 是**遮罩后**的输入，targets 是对应位置上的原始 token
        （两者必须分开传：遮罩位置上的 ids 是 mask_id，不能当答案）。
        """
        if not isinstance(positions, (list, tuple)) or not positions:
            raise ValueError("MaskedLM._loss_and_backward: positions 不能为空")
        if not isinstance(targets, (list, tuple)) or len(targets) != len(positions):
            raise ValueError(
                "MaskedLM._loss_and_backward: targets 必须与 positions 等长"
                f"（{len(positions)} 个位置，收到 {targets!r}）")
        pos = []
        for p in positions:
            if isinstance(p, bool) or not isinstance(p, int):
                raise ValueError(f"MaskedLM._loss_and_backward: 位置必须是整数，收到 {p!r}")
            if not 0 <= p < len(ids):
                raise ValueError(
                    f"MaskedLM._loss_and_backward: 位置 {p} 越界（序列长 {len(ids)}）")
            pos.append(p)
        ids = _check_token_ids(ids, self.vocab_size + 1, "MaskedLM._loss_and_backward")
        logits = self.forward(ids)
        _check_finite_logits(logits, "MaskedLM._loss_and_backward")

        d_logits = [[0.0] * self.vocab_size for _ in range(len(ids))]
        loss = 0.0
        n = len(pos)
        for j, t in enumerate(pos):
            probs = _softmax_row(logits[t])
            target = targets[j]
            if isinstance(target, bool) or not isinstance(target, int) or \
                    not 0 <= target < self.vocab_size:
                raise ValueError(
                    f"MaskedLM._loss_and_backward: 位置 {t} 的目标 {target!r} 越界"
                    f"（词表 {self.vocab_size}）")
            p = probs[target]
            loss += -math.log(p if p > 1e-12 else 1e-12)
            row = d_logits[t]
            row[:] = probs
            row[target] -= 1.0
        loss /= n
        inv = grad_scale / n
        d_logits = [[v * inv for v in row] for row in d_logits]

        h = self.h
        for v in range(self.vocab_size):
            g_row = self.grads["W_out"][v]
            for t in range(len(h)):
                d = d_logits[t][v]
                if d != 0.0:
                    for j in range(self.d_model):
                        g_row[j] += d * h[t][j]
        for v in range(self.vocab_size):
            s = 0.0
            for t in range(len(h)):
                d = d_logits[t][v]
                if d != 0.0:
                    s += d
            self.grads["b_out"][v] += s

        dh = []
        for t in range(len(h)):
            row = [0.0] * self.d_model
            dl = d_logits[t]
            for j in range(self.d_model):
                s = 0.0
                for v in range(self.vocab_size):
                    d = dl[v]
                    if d != 0.0:
                        s += d * self.W_out[v][j]
                row[j] = s
            dh.append(row)

        d_emb = self.encoder.backward(dh)
        self.embedding.backward(d_emb)
        return loss

    def adam_step(self, lr: float):
        """对全部参数做一次 Adam 更新（梯度已由 `_loss_and_backward` 累积）"""
        self.step_count += 1
        t = self.step_count
        for name, param, grad in self._named_params():
            m = self._adam_m.get(name)
            v = self._adam_v.get(name)
            if m is None:
                m = _zeros_like(param)
                v = _zeros_like(param)
                self._adam_m[name] = m
                self._adam_v[name] = v
            _adam_apply(param, grad, m, v, t, lr)

    def fit(self, sentences, epochs: int = 1, lr: float = 3e-3,
            shuffle: bool = True, seed=None, verbose: bool = False):
        """在若干条 token 序列上做掩码语言建模，返回每个 epoch 的平均 loss

        每个 epoch 对每条序列**重新采样一次遮罩**（与 BERT 一样），
        所以同一句话会反复以不同遮罩出现。
        """
        seqs = [list(s) for s in sentences]
        if not seqs:
            raise ValueError("MaskedLM.fit: sentences 不能为空")
        for s in seqs:
            if not s:
                raise ValueError("MaskedLM.fit: 每条序列不能为空")
            if len(s) > self.max_len:
                raise ValueError(
                    f"MaskedLM.fit: 序列长度 {len(s)} 超过 max_len={self.max_len}")
        if epochs < 0:
            raise ValueError(f"MaskedLM.fit: epochs 不能为负，收到 {epochs!r}")
        rng = random.Random(seed) if seed is not None else random
        history = []
        self.train()
        for ep in range(int(epochs)):
            order = list(range(len(seqs)))
            if shuffle:
                rng.shuffle(order)
            total = 0.0
            for i in order:
                corrupted, positions, targets = self.mask_tokens(seqs[i], rng)
                self.zero_grad()
                total += self._loss_and_backward(corrupted, positions, targets)
                self.adam_step(lr)
            avg = total / len(seqs)
            history.append(avg)
            if verbose:
                print(f"epoch {ep + 1}/{epochs} loss={avg:.4f}")
        return history

    def evaluate(self, sentences, seed: int = 0):
        """不更新参数的掩码 loss（eval 模式）

        固定 seed 让遮罩可复现，从而不同模型/不同轮次之间可比。
        """
        seqs = [list(s) for s in sentences]
        if not seqs:
            raise ValueError("MaskedLM.evaluate: sentences 不能为空")
        rng = random.Random(seed)
        was_training = self.encoder.layers[0].self_attn.training
        self.eval()
        try:
            total = 0.0
            for s in seqs:
                corrupted, positions, _targets = self.mask_tokens(s, random.Random(seed))
                logits = self.forward(corrupted)
                _check_finite_logits(logits, "MaskedLM.evaluate")
                for t, p in enumerate(positions):
                    probs = _softmax_row(logits[p])
                    target = s[p]
                    total += -math.log(probs[target] if probs[target] > 1e-12 else 1e-12)
            return total / max(1, sum(1 for _ in seqs))
        finally:
            if was_training:
                self.train()
            else:
                self.eval()

    def predict(self, ids, positions):
        """把 positions 处的 token 预测出来（argmax），返回 List[int]"""
        if not isinstance(positions, (list, tuple)) or not positions:
            raise ValueError("MaskedLM.predict: positions 不能为空")
        logits = self.forward(ids)
        out = []
        for p in positions:
            if isinstance(p, bool) or not isinstance(p, int) or not 0 <= p < len(ids):
                raise ValueError(f"MaskedLM.predict: 位置 {p!r} 非法")
            row = logits[p]
            best = 0
            for v in range(1, self.vocab_size):
                if row[v] > row[best]:
                    best = v
            out.append(best)
        return out


class CausalLM:
    """字符/词级因果语言模型（GPT 式）：Embedding → 位置编码 → 因果 Transformer → 词表头

    关键在 `MultiHeadAttention(causal=True)`：位置 t 只能看到 0..t，
    因此**一次前向就能并行算出所有位置的「下一个 token」预测**，
    不需要 RNN 那样串行递推 —— 这正是 LLM 预训练的做法。

    训练目标：给定 ids，位置 t 的 logits 与 ids[t+1] 做交叉熵。
    参数：Adam（内部实现，超参 0.9/0.999/1e-8）。

    用法::

        lm = CausalLM(vocab_size=3, d_model=16, num_heads=2, num_layers=1)
        lm.fit([[0, 1, 2, 0, 1, 2]], epochs=60, lr=0.01)
        lm.generate([0], max_new_tokens=6)
    """

    def __init__(self, vocab_size: int, d_model: int = 32, num_heads: int = 4,
                 d_ff: int = 64, num_layers: int = 2, max_len: int = 256,
                 dropout: float = 0.0, rope: bool = False, use_abs_pos=None,
                 window: int = None, num_kv_heads: int = None,
                 alibi: bool = False):
        if not isinstance(vocab_size, int) or isinstance(vocab_size, bool) or vocab_size < 1:
            raise ValueError(f"CausalLM: vocab_size 必须是正整数，收到 {vocab_size!r}")
        if not isinstance(max_len, int) or isinstance(max_len, bool) or max_len < 1:
            raise ValueError(f"CausalLM: max_len 必须 >= 1，收到 {max_len!r}")
        if not isinstance(num_layers, int) or isinstance(num_layers, bool) or num_layers < 1:
            raise ValueError(f"CausalLM: num_layers 必须 >= 1，收到 {num_layers!r}")
        self.vocab_size = vocab_size
        self.d_model = d_model
        self.max_len = max_len
        self.num_heads = num_heads
        self.d_ff = d_ff
        self.num_layers = num_layers
        self.dropout = dropout
        self.window = window
        self.num_kv_heads = num_kv_heads

        self.rope = bool(rope)
        # RoPE 已自带相对位置信息，默认就不再叠加绝对位置编码（Llama 的做法）；
        # 想两者都用可以显式传 use_abs_pos=True
        self.use_abs_pos = (not self.rope) if use_abs_pos is None else bool(use_abs_pos)

        self.embedding = Embedding(vocab_size, d_model)
        self.pos = PositionalEncoding(d_model, max_len)
        self.alibi = bool(alibi)
        self.encoder = TransformerEncoder(d_model, num_heads, d_ff, num_layers,
                                          dropout, causal=True, rope=self.rope,
                                          window=window, num_kv_heads=num_kv_heads,
                                          alibi=self.alibi)

        std = math.sqrt(2.0 / d_model)
        self.W_out = [[random.gauss(0, std) for _ in range(d_model)] for _ in range(vocab_size)]
        self.b_out = [0.0] * vocab_size
        self.zero_grad()
        self.step_count = 0
        self._adam_m = {}
        self._adam_v = {}
        self.h = None    # 最近一次 forward 的编码器输出（反向要用）

    def train(self):
        """训练模式（Dropout 生效）"""
        self.encoder.train()
        return self

    def eval(self):
        """推理模式（关闭 Dropout，同一输入输出确定）"""
        self.encoder.eval()
        return self

    def zero_grad(self):
        """清零全部梯度（词向量、各层、输出头）"""
        self.embedding.zero_grad()
        self.encoder.zero_grad()
        self.grads = {
            "W_out": [[0.0] * self.d_model for _ in range(self.vocab_size)],
            "b_out": [0.0] * self.vocab_size,
        }

    def _named_params(self):
        """产出 (名字, 参数, 梯度)；名字让 Adam 的一阶/二阶矩跨步保持

        必须在 `zero_grad()` 之后调用：各子模块的 grads 是重建成的新列表，
        直接持有旧引用会更新到过期的缓冲区上。
        """
        yield "emb.weight", self.embedding.weight, self.embedding.grad_weight
        for li, layer in enumerate(self.encoder.layers):
            attn = layer.self_attn
            for k in ("W_q", "W_k", "W_v", "W_o", "b_q", "b_k", "b_v", "b_o"):
                yield f"L{li}.attn.{k}", getattr(attn, k), attn.grads[k]
            ffn = layer.ffn
            for k in ("W1", "b1", "W2", "b2"):
                yield f"L{li}.ffn.{k}", getattr(ffn, k), ffn.grads[k]
            yield f"L{li}.ln1.gamma", layer.ln1.gamma, layer.grads["ln1_gamma"]
            yield f"L{li}.ln1.beta", layer.ln1.beta, layer.grads["ln1_beta"]
            yield f"L{li}.ln2.gamma", layer.ln2.gamma, layer.grads["ln2_gamma"]
            yield f"L{li}.ln2.beta", layer.ln2.beta, layer.grads["ln2_beta"]
        yield "out.W", self.W_out, self.grads["W_out"]
        yield "out.b", self.b_out, self.grads["b_out"]

    def param_count(self):
        """参数总数（标量个数）"""
        return sum(len(p) if not isinstance(p[0], list) else
                   sum(len(r) for r in p)
                   for _, p, _ in self._named_params())

    def forward(self, ids, pad_mask=None):
        """ids: List[int] → logits (seq_len, vocab_size)（未经 softmax）

        pad_mask: 与 ids 等长的 0/1 列表，0 表示填充位置（不当 key）。
        填充必须靠右，真实 token 的位置编号才不会被挪动。None 时行为与旧版一致。
        """
        if not ids:
            raise ValueError("CausalLM.forward: ids 不能为空")
        if len(ids) > self.max_len:
            raise ValueError(
                f"CausalLM.forward: 序列长度 {len(ids)} 超过 max_len={self.max_len}"
            )
        key_mask = None
        if pad_mask is not None:
            valid = _check_pad_mask(pad_mask, len(ids), "CausalLM.forward")
            key_mask = valid
        emb = self.embedding.forward(ids)
        x = self.pos.forward(emb) if self.use_abs_pos else emb
        h = self.encoder.forward(x, key_mask)
        self.h = h
        logits = _matmul(h, _transpose(self.W_out))
        for t in range(len(h)):
            for v in range(self.vocab_size):
                logits[t][v] += self.b_out[v]
        return logits

    def _forward_step(self, token_id: int, pos: int, caches):
        """单 token 增量前向：返回该位置 logits（长度 vocab_size）

        caches: 每层一个 dict；pos 是该 token 在**当前窗口**里的位置。
        与 `forward(窗口)[-1]` 逐位一致（前提：窗口没有滑动，位置未变）。
        """
        d = self.d_model
        if not isinstance(token_id, int) or not 0 <= token_id < self.vocab_size:
            raise ValueError(
                f"CausalLM._forward_step: token {token_id!r} 越界（词表 {self.vocab_size}）")
        row = self.embedding.weight[token_id]
        if self.use_abs_pos:
            self.pos._ensure_len(pos + 1)
            pe = self.pos.pe[pos]
            x = [row[j] + pe[j] for j in range(d)]
        else:
            x = list(row)
        x = self.encoder.forward_step(x, caches)
        return [sum(map(_mul, self.W_out[v], x)) + self.b_out[v]
                for v in range(self.vocab_size)]

    def _loss_and_backward(self, ids, pad_mask=None, grad_scale: float = 1.0):
        """单条序列的交叉熵（对**有效**预测位置取平均），并累积全部梯度；返回 loss

        pad_mask: 与 ids 等长的 0/1 列表，0 表示填充。
          - 填充位置不当 key（注意力里屏蔽）
          - loss 只在目标位置有效处计入，除以有效目标数
          - 梯度额外乘 grad_scale（批量训练时按 token 数加权）
        pad_mask=None 时与旧版逐位相同。
        """
        if len(ids) < 2:
            raise ValueError("CausalLM: 序列至少要有 2 个 token 才能训练（输入 + 目标）")
        ids = _check_token_ids(ids, self.vocab_size, "CausalLM._loss_and_backward")
        if pad_mask is None:
            valid = None
            key_mask = None
            n = len(ids) - 1
        else:
            valid = _check_pad_mask(pad_mask, len(ids), "CausalLM._loss_and_backward")
            key_mask = valid[:-1]
            n = sum(valid[1:])
            if n < 1:
                raise ValueError(
                    "CausalLM._loss_and_backward: pad_mask 里没有有效的目标位置（序列至少 2 个真实 token）")
        logits = self.forward(ids[:-1], key_mask)
        _check_finite_logits(logits, "CausalLM._loss_and_backward")
        d_logits = []
        loss = 0.0
        for t in range(len(ids) - 1):
            if valid is not None and not valid[t + 1]:
                d_logits.append([0.0] * self.vocab_size)
                continue
            probs = _softmax_row(logits[t])
            target = ids[t + 1]
            p = probs[target]
            loss += -math.log(p if p > 1e-12 else 1e-12)
            row = list(probs)
            row[target] -= 1.0
            d_logits.append(row)
        loss /= n
        inv = grad_scale / n
        d_logits = [[v * inv for v in row] for row in d_logits]

        h = self.h
        seq_len = len(h)
        # 输出头反向: grad_W_out[v][j] = sum_t d_logits[t][v] * h[t][j]
        for v in range(self.vocab_size):
            g_row = self.grads["W_out"][v]
            gb = 0.0
            for t in range(seq_len):
                d = d_logits[t][v]
                gb += d
                ht = h[t]
                for j in range(self.d_model):
                    g_row[j] += d * ht[j]
            self.grads["b_out"][v] += gb
        # d_h[t][j] = sum_v d_logits[t][v] * W_out[v][j]
        dh = [[0.0] * self.d_model for _ in range(seq_len)]
        for t in range(seq_len):
            dl = d_logits[t]
            for j in range(self.d_model):
                s = 0.0
                for v in range(self.vocab_size):
                    s += dl[v] * self.W_out[v][j]
                dh[t][j] = s
        d_seq = self.encoder.backward(dh)
        self.embedding.backward(d_seq)   # 位置编码无参数，直通
        return loss

    def adam_step(self, lr: float):
        """对全部参数做一次 Adam 更新（梯度已由 `_loss_and_backward` 累积）"""
        self.step_count += 1
        t = self.step_count
        for name, param, grad in self._named_params():
            m = self._adam_m.get(name)
            v = self._adam_v.get(name)
            if m is None:
                m = _zeros_like(param)
                v = _zeros_like(param)
                self._adam_m[name] = m
                self._adam_v[name] = v
            _adam_apply(param, grad, m, v, t, lr)

    def fit(self, sequences, epochs: int = 1, lr: float = 3e-3,
            shuffle: bool = True, seed=None, verbose: bool = False,
            batch_size: int = 1):
        """在若干条 token 序列上做 teacher-forcing 训练，返回每个 epoch 的平均 loss

        sequences: List[List[int]]，每条至少 2 个 token，长度可以不同。
        batch_size=1（默认）时每个序列单独一步，与旧版逐位相同；
        batch_size>1 时把一批序列右侧补齐成同一长度、用 pad_mask 屏蔽填充，
        梯度按 token 数加权、每批一次 Adam。
        """
        if isinstance(batch_size, bool) or not isinstance(batch_size, int):
            raise ValueError(f"CausalLM.fit: batch_size 必须是正整数，收到 {batch_size!r}")
        if batch_size < 1:
            raise ValueError(f"CausalLM.fit: batch_size 必须 >= 1，收到 {batch_size!r}")
        seqs = [list(s) for s in sequences]
        if not seqs:
            raise ValueError("CausalLM.fit: sequences 不能为空")
        for s in seqs:
            if len(s) < 2:
                raise ValueError("CausalLM.fit: 每条序列至少 2 个 token")
        if epochs < 0:
            raise ValueError(f"CausalLM.fit: epochs 不能为负，收到 {epochs!r}")
        rng = random.Random(seed) if seed is not None else random
        history = []
        self.train()
        for ep in range(int(epochs)):
            order = list(range(len(seqs)))
            if shuffle:
                rng.shuffle(order)
            total = 0.0
            if batch_size == 1:
                for i in order:
                    self.zero_grad()
                    total += self._loss_and_backward(seqs[i])
                    self.adam_step(lr)
            else:
                for start in range(0, len(order), batch_size):
                    batch = order[start:start + batch_size]
                    width = max(len(seqs[i]) for i in batch)
                    n_valid = sum(len(seqs[i]) - 1 for i in batch)
                    self.zero_grad()
                    for i in batch:
                        s = seqs[i]
                        pad = width - len(s)
                        total += self._loss_and_backward(
                            s + [0] * pad,
                            [1] * len(s) + [0] * pad,
                            grad_scale=(len(s) - 1) / n_valid)
                    self.adam_step(lr)
            avg = total / len(seqs)
            history.append(avg)
            if verbose:
                print(f"epoch {ep + 1}/{epochs} loss={avg:.4f}")
        return history

    def evaluate(self, sequences):
        """不更新参数的交叉熵（eval 模式，按预测位置总数平均）"""
        seqs = [list(s) for s in sequences]
        if not seqs:
            raise ValueError("CausalLM.evaluate: sequences 不能为空")
        was_training = self.encoder.layers[0].self_attn.training
        self.eval()
        try:
            total = 0.0
            count = 0
            for s in seqs:
                if len(s) < 2:
                    raise ValueError("CausalLM.evaluate: 每条序列至少 2 个 token")
                s = _check_token_ids(s, self.vocab_size, "CausalLM.evaluate")
                logits = self.forward(s[:-1])
                _check_finite_logits(logits, "CausalLM.evaluate")
                for t in range(len(s) - 1):
                    probs = _softmax_row(logits[t])
                    p = probs[s[t + 1]]
                    total += -math.log(p if p > 1e-12 else 1e-12)
                    count += 1
            return total / count
        finally:
            if was_training:
                self.train()

    def perplexity(self, sequences):
        """困惑度 = exp(交叉熵)。语言模型常用指标，越小越好"""
        loss = self.evaluate(sequences)
        if loss > 700.0:          # exp(709.78) 就溢出，直接给 inf
            return float("inf")
        return math.exp(loss)


    def _config(self):
        """构造参数（存档用）；load 时原样喂回构造器"""
        return {"vocab_size": self.vocab_size, "d_model": self.d_model,
                "num_heads": self.num_heads, "d_ff": self.d_ff,
                "num_layers": self.num_layers, "max_len": self.max_len,
                "dropout": self.dropout, "rope": self.rope,
                "use_abs_pos": self.use_abs_pos, "window": self.window,
                "num_kv_heads": self.num_kv_heads}

    def save(self, filepath: str, include_optimizer: bool = False,
             quiet: bool = False):
        """把结构与参数写成 JSON（纯标准库）

        include_optimizer=True 时连 Adam 的一阶/二阶矩和步数一起存，
        `load(..., restore_optimizer=True)` 之后可以逐位接着训练。
        """
        return _lm_save(self, "causal", filepath, include_optimizer, quiet)

    @staticmethod
    def load(filepath: str, restore_optimizer: bool = False):
        """从 `save` 写出的 JSON 恢复 CausalLM（参数逐位还原）"""
        return _lm_load(filepath, restore_optimizer)

    def _generate_beam(self, ids, max_new_tokens, num_beams, top_k, min_p: float = 0.0,
                       repetition_penalty: float = 1.0, presence_penalty: float = 0.0,
                       frequency_penalty: float = 0.0, no_repeat_ngram_size: int = 0):
        """束搜索：每步保留累计对数概率最高的 num_beams 条前缀（不用随机数）

        num_beams=1 时与贪心解码（`generate(top_k=1)`）逐位相同。
        top_k>0 时每步只展开概率最高的 top_k 个候选，否则展开 num_beams 个。
        min_p 也在这里生效（对每条前缀各自的分布过滤）。
        """
        beams = [(0.0, list(ids))]
        for _ in range(max_new_tokens):
            cands = []
            for score, toks in beams:
                window = toks[-self.max_len:]
                logits = _apply_generation_penalties(
                    self.forward(window)[-1], toks, repetition_penalty,
                    presence_penalty, frequency_penalty, no_repeat_ngram_size)
                logits = _mask_min_p(logits, min_p)
                logp = _log_softmax_row(logits)
                order = sorted(range(self.vocab_size),
                               key=lambda v: logp[v], reverse=True)
                take = order[:int(top_k)] if top_k else order[:num_beams]
                for v in take:
                    cands.append((score + logp[v], toks + [v]))
            if not cands:
                break
            cands.sort(key=lambda c: c[0], reverse=True)
            beams = cands[:num_beams]
        return beams[0][1]

    def generate(self, prompt_ids, max_new_tokens: int = 16, temperature: float = 1.0,
                 top_k: int = 0, rng=None, use_cache: bool = True, top_p: float = 1.0,
                 num_beams: int = 1, min_p: float = 0.0,
                 repetition_penalty: float = 1.0, presence_penalty: float = 0.0,
                 frequency_penalty: float = 0.0, no_repeat_ngram_size: int = 0):
        """自回归生成：返回 prompt + 新 token 的索引列表（调用后保持 eval 模式）

        temperature: >1 更随机，<1 更确定；top_k>0 时只在最可能的 k 个里采样。
        top_p: nucleus 采样阈值（(0,1]，默认 1.0 = 不过滤，与旧行为逐位相同）。

        num_beams: >1 时改用束搜索（确定性，不抽随机数），返回最优的一条完整序列。

        use_cache: True（默认）走 KV cache —— 每个新 token 只前向一次，复用之前
        各层 K/V，生成 N 个 token 的代价从 O(N·T²) 降到 O(N·T)。与 use_cache=False
        的**结果逐位相同**（cache 路径前向的行与整段前向的最后一行一致）。

        抗重复 / 截尾：min_p（(0,1)，相对最大概率截尾）、repetition_penalty（>1 抑制
        重复 token）、presence_penalty / frequency_penalty（按出现与否/次数扣分）、
        no_repeat_ngram_size（禁止 n-gram 立刻重复）。默认值全部等于「不干预」，
        与旧行为逐位相同。
        """
        if max_new_tokens < 0:
            raise ValueError(f"CausalLM.generate: max_new_tokens 不能为负，收到 {max_new_tokens!r}")
        if temperature <= 0:
            raise ValueError(f"CausalLM.generate: temperature 必须 > 0，收到 {temperature!r}")
        if not (0.0 < top_p <= 1.0):
            raise ValueError(f"CausalLM.generate: top_p 必须在 (0,1] 内，收到 {top_p!r}")
        top_k = _check_top_k(top_k, "CausalLM.generate")
        if isinstance(num_beams, bool) or not isinstance(num_beams, int) or num_beams < 1:
            raise ValueError(
                f"CausalLM.generate: num_beams 必须是 >= 1 的整数，收到 {num_beams!r}")
        min_p = _check_min_p(min_p, "CausalLM.generate")
        _check_penalty_args(repetition_penalty, presence_penalty, frequency_penalty,
                            no_repeat_ngram_size, "CausalLM.generate")
        ids = list(prompt_ids)
        if not ids:
            raise ValueError("CausalLM.generate: prompt_ids 不能为空")
        rng = rng or random
        self.eval()
        n_new = int(max_new_tokens)
        if num_beams > 1:
            return self._generate_beam(ids, n_new, num_beams, top_k, min_p,
                                       repetition_penalty, presence_penalty,
                                       frequency_penalty, no_repeat_ngram_size)
        if use_cache and n_new > 0:
            return self._generate_cached(ids, n_new, temperature, top_k, rng, top_p, min_p,
                                         repetition_penalty, presence_penalty,
                                         frequency_penalty, no_repeat_ngram_size)
        for _ in range(n_new):
            window = ids[-self.max_len:]
            logits = _apply_generation_penalties(
                self.forward(window)[-1], ids, repetition_penalty,
                presence_penalty, frequency_penalty, no_repeat_ngram_size)
            ids.append(self._sample(logits, temperature, top_k, rng, top_p, min_p))
        return ids

    def _sample(self, logits, temperature, top_k, rng, top_p: float = 1.0,
                min_p: float = 0.0):
        """从 logits 采一个 token（top_k / top_p / min_p 过滤 + 温度 + 累积分布采样）

        top_p（nucleus 采样）：按概率从高到低累加，只保留累计概率刚好覆盖 top_p
        的头部集合。top_p=1.0（默认）不做过滤，与旧行为逐位相同。
        min_p：在 top_k/top_p 之后再按「概率 >= min_p * 最大概率」截尾（0 = 关闭）。
        """
        if not (0.0 < top_p <= 1.0):
            raise ValueError(f"CausalLM._sample: top_p 必须在 (0,1] 内，收到 {top_p!r}")
        min_p = _check_min_p(min_p, "CausalLM._sample")
        top_k = _check_top_k(top_k, "CausalLM._sample")
        if top_k and top_k < self.vocab_size:
            order = sorted(range(self.vocab_size), key=lambda v: logits[v], reverse=True)
            keep = set(order[:int(top_k)])
            logits = [v if i in keep else float("-inf") for i, v in enumerate(logits)]
        if top_p < 1.0:
            # nucleus：按温度缩放后的概率排序，保留累计概率刚好覆盖 top_p 的头部
            probs_raw = _softmax_row([v / temperature for v in logits])
            order = sorted(range(self.vocab_size), key=lambda v: probs_raw[v], reverse=True)
            keep = set()
            acc_p = 0.0
            for v in order:
                keep.add(v)
                acc_p += probs_raw[v]
                if acc_p >= top_p:
                    break
            logits = [v if i in keep else float("-inf") for i, v in enumerate(logits)]
        if min_p > 0.0:
            peak = max(_softmax_row([v / temperature for v in logits]))
            thresh = float(min_p) * peak
            probs_now = _softmax_row([v / temperature for v in logits])
            logits = [v if probs_now[i] >= thresh else float("-inf")
                      for i, v in enumerate(logits)]
        probs = _softmax_row([v / temperature for v in logits])
        # 累积分布采样（不依赖 random.choices，可注入 rng 复现）
        u = rng.random()
        acc = 0.0
        pick = self.vocab_size - 1
        for v, p in enumerate(probs):
            acc += p
            if u < acc:
                pick = v
                break
        return pick

    def _generate_cached(self, ids, max_new_tokens, temperature, top_k, rng, top_p=1.0,
                         min_p: float = 0.0, repetition_penalty: float = 1.0,
                         presence_penalty: float = 0.0, frequency_penalty: float = 0.0,
                         no_repeat_ngram_size: int = 0):
        """KV cache 版生成：先整段预填充，然后每个新 token 只做单步前向

        窗口满（len(ids) > max_len）时会整体左移，位置编码/因果掩码都依赖绝对
        位置，此时缓存失效 → 用新窗口重建一次（代价 O(max_len)，摊还后仍远小于
        每步重算整段）。
        """
        window = ids[-self.max_len:]
        caches = [{} for _ in self.encoder.layers]
        pos = 0
        logits = None
        for tok in window:
            logits = self._forward_step(tok, pos, caches)
            pos += 1
        for _ in range(max_new_tokens):
            cur = _apply_generation_penalties(logits, ids, repetition_penalty,
                                              presence_penalty, frequency_penalty,
                                              no_repeat_ngram_size)
            pick = self._sample(cur, temperature, top_k, rng, top_p, min_p)
            ids.append(pick)
            new_window = ids[-self.max_len:]
            if len(new_window) == len(window) + 1:
                logits = self._forward_step(pick, pos, caches)
                pos += 1
            else:
                # 窗口滑动：位置整体左移，旧 K/V 全部作废，按新窗口重建
                caches = [{} for _ in self.encoder.layers]
                pos = 0
                for tok in new_window:
                    logits = self._forward_step(tok, pos, caches)
                    pos += 1
            window = new_window
        return ids


class Seq2SeqLM:
    """编码器-解码器序列到序列模型（翻译 / 改写 / 复制类任务）

    数据流::

        src_ids → Embedding → PositionalEncoding → TransformerEncoder ─┐
                                                                        │ memory
        tgt_ids(右移一位) → Embedding → PosEnc → TransformerDecoder ────┘
                                              ↓
                                        词表头 → logits

    解码器每一层先用因果自注意力看自己已生成的前缀，再用交叉注意力读整段
    编码器输出；训练用 teacher forcing（把目标右移一位当输入），推理时逐 token
    生成并把结果接回输入。

    BOS 用「词表外的一个 id」（即 `tgt_vocab` 本身），所以目标端 embedding 有
    `tgt_vocab + 1` 行：这样既能区分句首和真实 token，又不用改目标词表大小。
    """

    def __init__(self, src_vocab: int, tgt_vocab: int, d_model: int = 32,
                 num_heads: int = 4, d_ff: int = 64, num_layers: int = 2,
                 max_len: int = 64, dropout: float = 0.0):
        for name, val in (("src_vocab", src_vocab), ("tgt_vocab", tgt_vocab),
                          ("max_len", max_len), ("num_layers", num_layers)):
            if isinstance(val, bool) or not isinstance(val, int) or val < 1:
                raise ValueError(f"Seq2SeqLM: {name} 必须是正整数，收到 {val!r}")
        self.src_vocab = src_vocab
        self.tgt_vocab = tgt_vocab
        self.d_model = d_model
        self.max_len = max_len
        self.bos_id = tgt_vocab          # 词表外的 BOS
        self.num_heads = num_heads
        self.d_ff = d_ff
        self.num_layers = num_layers
        self.dropout = dropout
        self.step_count = 0
        self._adam_m = {}
        self._adam_v = {}

        self.src_embedding = Embedding(src_vocab, d_model)
        self.tgt_embedding = Embedding(tgt_vocab + 1, d_model)
        self.pos = PositionalEncoding(d_model, max_len)
        self.encoder = TransformerEncoder(d_model, num_heads, d_ff, num_layers, dropout)
        self.decoder = TransformerDecoder(d_model, num_heads, d_ff, num_layers,
                                          dropout, causal=True)

        std = math.sqrt(2.0 / d_model)
        self.W_out = [[random.gauss(0, std) for _ in range(d_model)]
                      for _ in range(tgt_vocab)]
        self.b_out = [0.0] * tgt_vocab

        self.zero_grad()
        self.h = None       # 最近一次前向的解码器输出（反向要用）
        self.enc = None     # 最近一次前向的编码器输出

    def train(self):
        """训练模式：编码器、解码器的 Dropout 全部生效"""
        self.encoder.train()
        self.decoder.train()
        return self

    def eval(self):
        """推理模式：关闭全部 Dropout"""
        self.encoder.eval()
        self.decoder.eval()
        return self

    def zero_grad(self):
        """清零全部梯度（两个词表、编码器、解码器、输出头）"""
        self.src_embedding.zero_grad()
        self.tgt_embedding.zero_grad()
        self.encoder.zero_grad()
        self.decoder.zero_grad()
        self.grads = {
            "W_out": [[0.0] * self.d_model for _ in range(self.tgt_vocab)],
            "b_out": [0.0] * self.tgt_vocab,
        }

    def _named_params(self):
        """产出 (名字, 参数, 梯度)；名字保证 Adam 的矩跨步稳定

        必须在 `zero_grad()` 之后调用（各模块的 grads 是重建的新列表）。
        """
        yield "src_emb.weight", self.src_embedding.weight, self.src_embedding.grad_weight
        yield "tgt_emb.weight", self.tgt_embedding.weight, self.tgt_embedding.grad_weight
        for li, layer in enumerate(self.encoder.layers):
            attn = layer.self_attn
            for k in ("W_q", "W_k", "W_v", "W_o", "b_q", "b_k", "b_v", "b_o"):
                yield f"enc.L{li}.attn.{k}", getattr(attn, k), attn.grads[k]
            ffn = layer.ffn
            for k in ("W1", "b1", "W2", "b2"):
                yield f"enc.L{li}.ffn.{k}", getattr(ffn, k), ffn.grads[k]
            for ln in ("ln1", "ln2"):
                mod = getattr(layer, ln)
                yield f"enc.L{li}.{ln}.gamma", mod.gamma, layer.grads[ln + "_gamma"]
                yield f"enc.L{li}.{ln}.beta", mod.beta, layer.grads[ln + "_beta"]
        for li, layer in enumerate(self.decoder.layers):
            attn = layer.self_attn
            for k in ("W_q", "W_k", "W_v", "W_o", "b_q", "b_k", "b_v", "b_o"):
                yield f"dec.L{li}.attn.{k}", getattr(attn, k), attn.grads[k]
            cross = layer.cross_attn
            for k in ("W_q", "W_k", "W_v", "W_o", "b_q", "b_k", "b_v", "b_o"):
                yield f"dec.L{li}.cross.{k}", getattr(cross, k), cross.grads[k]
            ffn = layer.ffn
            for k in ("W1", "b1", "W2", "b2"):
                yield f"dec.L{li}.ffn.{k}", getattr(ffn, k), ffn.grads[k]
            for ln in ("ln1", "ln2", "ln3"):
                mod = getattr(layer, ln)
                yield f"dec.L{li}.{ln}.gamma", mod.gamma, layer.grads[ln + "_gamma"]
                yield f"dec.L{li}.{ln}.beta", mod.beta, layer.grads[ln + "_beta"]
        yield "out.W", self.W_out, self.grads["W_out"]
        yield "out.b", self.b_out, self.grads["b_out"]

    def param_count(self):
        """参数总数（标量个数）"""
        return sum(len(p) if not isinstance(p[0], list) else
                   sum(len(r) for r in p)
                   for _, p, _ in self._named_params())

    def _encode(self, src_ids, src_mask=None):
        """编码器前向，返回 memory (Ts, d_model)

        src_mask: 长度 Ts 的 0/1 列表，0 表示右填充的位置（批量训练用）
        """
        emb = self.src_embedding.forward(src_ids)
        x = self.pos.forward(emb)
        return self.encoder.forward(x, key_mask=src_mask)

    def _decode(self, tgt_ids, memory, memory_mask=None):
        """解码器前向，返回 logits (Tt, tgt_vocab)（未经 softmax）"""
        emb = self.tgt_embedding.forward(tgt_ids)
        x = self.pos.forward(emb)
        h = self.decoder.forward(x, memory, memory_mask)
        self.h = h
        logits = _matmul(h, _transpose(self.W_out))
        for t in range(len(h)):
            for v in range(self.tgt_vocab):
                logits[t][v] += self.b_out[v]
        return logits

    def forward(self, src_ids, tgt_in_ids, src_mask=None):
        """完整前向：返回 (Tt, tgt_vocab) 的 logits

        src_mask: 长度 len(src_ids) 的 0/1 列表，0 表示右填充位置；
                  同时用于「编码器自注意力的 key」与「解码器的 memory」。
        """
        if not src_ids:
            raise ValueError("Seq2SeqLM.forward: src_ids 不能为空")
        if not tgt_in_ids:
            raise ValueError("Seq2SeqLM.forward: tgt_in_ids 不能为空")
        if len(src_ids) > self.max_len:
            raise ValueError(
                f"Seq2SeqLM.forward: 源序列长度 {len(src_ids)} 超过 max_len={self.max_len}")
        if len(tgt_in_ids) > self.max_len:
            raise ValueError(
                f"Seq2SeqLM.forward: 目标序列长度 {len(tgt_in_ids)} 超过 max_len={self.max_len}")
        self.enc = self._encode(src_ids, src_mask)
        return self._decode(tgt_in_ids, self.enc, src_mask)

    def _loss_and_backward(self, src_ids, tgt_ids, src_mask=None, tgt_mask=None,
                           grad_scale: float = 1.0):
        """单对序列的 teacher-forcing 交叉熵（对目标 token 数取平均）并累积梯度

        src_mask / tgt_mask: 批量训练时的右填充掩码（None 时行为与之前完全一致）
        grad_scale:          梯度整体缩放（批量训练里按 token 数加权用）
        """
        if len(tgt_ids) < 1:
            raise ValueError("Seq2SeqLM: 目标序列不能为空")
        src_ids = _check_token_ids(src_ids, self.src_vocab, "Seq2SeqLM._loss_and_backward")
        tgt_ids = _check_token_ids(tgt_ids, self.tgt_vocab, "Seq2SeqLM._loss_and_backward")
        if tgt_mask is not None:
            tgt_mask = _check_pad_mask(tgt_mask, len(tgt_ids), "Seq2SeqLM._loss_and_backward")
        tgt_in = [self.bos_id] + list(tgt_ids[:-1])
        logits = self.forward(src_ids, tgt_in, src_mask=src_mask)
        _check_finite_logits(logits, "Seq2SeqLM._loss_and_backward")
        n = len(tgt_ids) if tgt_mask is None else sum(1 for v in tgt_mask if v)
        if n <= 0:
            raise ValueError("Seq2SeqLM: 目标序列至少要有一个非填充位置")
        d_logits = []
        loss = 0.0
        for t in range(len(tgt_ids)):
            if tgt_mask is not None and not tgt_mask[t]:
                d_logits.append([0.0] * self.tgt_vocab)
                continue
            probs = _softmax_row(logits[t])
            target = tgt_ids[t]
            p = probs[target]
            loss += -math.log(p if p > 1e-12 else 1e-12)
            row = list(probs)
            row[target] -= 1.0
            d_logits.append(row)
        loss /= n
        inv = grad_scale / n
        d_logits = [[v * inv for v in row] for row in d_logits]

        h = self.h
        seq_len = len(h)
        for v in range(self.tgt_vocab):
            g_row = self.grads["W_out"][v]
            gb = 0.0
            for t in range(seq_len):
                d = d_logits[t][v]
                gb += d
                ht = h[t]
                for j in range(self.d_model):
                    g_row[j] += d * ht[j]
            self.grads["b_out"][v] += gb
        dh = [[0.0] * self.d_model for _ in range(seq_len)]
        for t in range(seq_len):
            dl = d_logits[t]
            for j in range(self.d_model):
                s = 0.0
                for v in range(self.tgt_vocab):
                    s += dl[v] * self.W_out[v][j]
                dh[t][j] = s

        d_dec_in, d_enc = self.decoder.backward(dh)
        self.tgt_embedding.backward(d_dec_in)      # 位置编码无参数，直通
        d_src = self.encoder.backward(d_enc)
        self.src_embedding.backward(d_src)
        return loss

    def adam_step(self, lr: float):
        """对全部参数做一次 Adam 更新（梯度由 `_loss_and_backward` 累积）"""
        self.step_count += 1
        t = self.step_count
        for name, param, grad in self._named_params():
            m = self._adam_m.get(name)
            v = self._adam_v.get(name)
            if m is None:
                m = _zeros_like(param)
                v = _zeros_like(param)
                self._adam_m[name] = m
                self._adam_v[name] = v
            _adam_apply(param, grad, m, v, t, lr)

    def fit(self, pairs, epochs: int = 1, lr: float = 3e-3,
            shuffle: bool = True, seed=None, verbose: bool = False,
            batch_size: int = 1):
        """在若干 (src_ids, tgt_ids) 上训练，返回每个 epoch 的平均 loss

        batch_size > 1 时把长度不同的样本右填充成一批，用 pad 掩码屏蔽填充位，
        梯度按 token 数加权（等价于把整批的目标 token 拉平后取平均），
        每批做一次 Adam 更新。默认 batch_size=1 时行为与之前完全一致。
        """
        items = [(list(s), list(t)) for s, t in pairs]
        if not items:
            raise ValueError("Seq2SeqLM.fit: pairs 不能为空")
        for s, t in items:
            if not s or not t:
                raise ValueError("Seq2SeqLM.fit: 每对的源/目标都不能为空")
        if isinstance(epochs, bool) or not isinstance(epochs, int) or epochs < 0:
            raise ValueError(f"Seq2SeqLM.fit: epochs 不能为负，收到 {epochs!r}")
        if isinstance(batch_size, bool) or not isinstance(batch_size, int) or batch_size < 1:
            raise ValueError(f"Seq2SeqLM.fit: batch_size 必须是 >=1 的整数，收到 {batch_size!r}")
        rng = random.Random(seed) if seed is not None else random
        history = []
        self.train()
        for ep in range(epochs):
            order = list(range(len(items)))
            if shuffle:
                rng.shuffle(order)
            total = 0.0
            if batch_size == 1:
                for i in order:
                    self.zero_grad()
                    total += self._loss_and_backward(items[i][0], items[i][1])
                    self.adam_step(lr)
            else:
                for start in range(0, len(order), batch_size):
                    group = [items[i] for i in order[start:start + batch_size]]
                    width_src = max(len(s) for s, _ in group)
                    width_tgt = max(len(t) for _, t in group)
                    if width_src > self.max_len or width_tgt > self.max_len:
                        raise ValueError(
                            "Seq2SeqLM.fit: 批量补齐后超过 max_len="
                            f"{self.max_len}（源 {width_src}、目标 {width_tgt}）"
                        )
                    n_total = sum(len(t) for _, t in group)
                    self.zero_grad()
                    for s, t in group:
                        pad_s = list(s) + [0] * (width_src - len(s))
                        pad_t = list(t) + [0] * (width_tgt - len(t))
                        src_mask = [1] * len(s) + [0] * (width_src - len(s))
                        tgt_mask = [1] * len(t) + [0] * (width_tgt - len(t))
                        total += self._loss_and_backward(
                            pad_s, pad_t, src_mask=src_mask, tgt_mask=tgt_mask,
                            grad_scale=len(t) / n_total)
                    self.adam_step(lr)
            avg = total / len(items)
            history.append(avg)
            if verbose:
                print(f"epoch {ep + 1}/{epochs} loss={avg:.4f}")
        return history

    def evaluate(self, pairs):
        """不更新参数的 teacher-forcing 交叉熵（按目标 token 总数平均）"""
        items = [(list(s), list(t)) for s, t in pairs]
        if not items:
            raise ValueError("Seq2SeqLM.evaluate: pairs 不能为空")
        was_training = self.decoder.layers[0].self_attn.training
        self.eval()
        try:
            total = 0.0
            count = 0
            for s, t in items:
                if not s or not t:
                    raise ValueError("Seq2SeqLM.evaluate: 每对的源/目标都不能为空")
                s = _check_token_ids(s, self.src_vocab, "Seq2SeqLM.evaluate")
                t = _check_token_ids(t, self.tgt_vocab, "Seq2SeqLM.evaluate")
                tgt_in = [self.bos_id] + list(t[:-1])
                logits = self.forward(s, tgt_in)
                _check_finite_logits(logits, "Seq2SeqLM.evaluate")
                for i in range(len(t)):
                    probs = _softmax_row(logits[i])
                    p = probs[t[i]]
                    total += -math.log(p if p > 1e-12 else 1e-12)
                    count += 1
            return total / count
        finally:
            if was_training:
                self.train()

    def _sample(self, logits, temperature, top_k, rng, top_p, vocab_size,
                min_p: float = 0.0):
        """从 logits 采一个 token（top_k / top_p / min_p + 温度 + 累积分布）"""
        if not (0.0 < top_p <= 1.0):
            raise ValueError(f"Seq2SeqLM._sample: top_p 必须在 (0,1] 内，收到 {top_p!r}")
        min_p = _check_min_p(min_p, "Seq2SeqLM._sample")
        top_k = _check_top_k(top_k, "Seq2SeqLM._sample")
        if top_k and top_k < vocab_size:
            order = sorted(range(vocab_size), key=lambda v: logits[v], reverse=True)
            keep = set(order[:int(top_k)])
            logits = [v if i in keep else float("-inf") for i, v in enumerate(logits)]
        if top_p < 1.0:
            probs_raw = _softmax_row([v / temperature for v in logits])
            order = sorted(range(vocab_size), key=lambda v: probs_raw[v], reverse=True)
            keep = set()
            acc_p = 0.0
            for v in order:
                keep.add(v)
                acc_p += probs_raw[v]
                if acc_p >= top_p:
                    break
            logits = [v if i in keep else float("-inf") for i, v in enumerate(logits)]
        if min_p > 0.0:
            probs_now = _softmax_row([v / temperature for v in logits])
            thresh = float(min_p) * max(probs_now)
            logits = [v if probs_now[i] >= thresh else float("-inf")
                      for i, v in enumerate(logits)]
        probs = _softmax_row([v / temperature for v in logits])
        u = rng.random()
        acc = 0.0
        pick = vocab_size - 1
        for v, p in enumerate(probs):
            acc += p
            if u < acc:
                pick = v
                break
        return pick

    def _config(self):
        """构造参数（存档用）"""
        return {"src_vocab": self.src_vocab, "tgt_vocab": self.tgt_vocab,
                "d_model": self.d_model, "num_heads": self.num_heads,
                "d_ff": self.d_ff, "num_layers": self.num_layers,
                "max_len": self.max_len, "dropout": self.dropout}

    def save(self, filepath: str, include_optimizer: bool = False,
             quiet: bool = False):
        """把结构与参数写成 JSON（include_optimizer=True 连 Adam 状态一起存）"""
        return _lm_save(self, "seq2seq", filepath, include_optimizer, quiet)

    @staticmethod
    def load(filepath: str, restore_optimizer: bool = False):
        """从 `save` 写出的 JSON 恢复 Seq2SeqLM（参数逐位还原）"""
        return _lm_load(filepath, restore_optimizer)

    def _generate_beam(self, src_ids, max_new_tokens, num_beams, top_k, eos_id=None,
                       min_p: float = 0.0, repetition_penalty: float = 1.0,
                       presence_penalty: float = 0.0, frequency_penalty: float = 0.0,
                       no_repeat_ngram_size: int = 0):
        """束搜索解码：编码一次，每步对每条前缀重算解码器并保留前 num_beams

        eos_id 非 None 时把以 eos 结尾的候选放进「已完成」，最后按累计对数概率
        在所有已完成/未完成候选里挑最好的。
        """
        memory = self._encode(list(src_ids))
        beams = [(0.0, [self.bos_id], [])]
        finished = []
        for _ in range(max_new_tokens):
            cands = []
            for score, tgt, out in beams:
                if len(tgt) >= self.max_len:
                    finished.append((score, out))
                    continue
                logits = _apply_generation_penalties(
                    self._decode(tgt, memory)[-1], tgt, repetition_penalty,
                    presence_penalty, frequency_penalty, no_repeat_ngram_size)
                logits = _mask_min_p(logits, min_p)
                logp = _log_softmax_row(logits)
                order = sorted(range(self.tgt_vocab),
                               key=lambda v: logp[v], reverse=True)
                take = order[:int(top_k)] if top_k else order[:num_beams]
                for v in take:
                    if eos_id is not None and v == eos_id:
                        finished.append((score + logp[v], out))
                    else:
                        cands.append((score + logp[v], tgt + [v], out + [v]))
            if not cands:
                break
            cands.sort(key=lambda c: c[0], reverse=True)
            beams = cands[:num_beams]
        best = None
        if finished:
            finished.sort(key=lambda c: c[0], reverse=True)
            best = finished[0]
        if best is not None and (not beams or best[0] >= beams[0][0]):
            return list(best[1])
        return list(beams[0][2])

    def generate(self, src_ids, max_new_tokens: int = 5, temperature: float = 1.0,
                 top_k: int = 0, top_p: float = 1.0, rng=None, eos_id=None,
                 num_beams: int = 1, min_p: float = 0.0,
                 repetition_penalty: float = 1.0, presence_penalty: float = 0.0,
                 frequency_penalty: float = 0.0, no_repeat_ngram_size: int = 0):
        """编码一次、解码逐步生成；返回生成的 token 列表（不含 BOS）

        eos_id 非 None 时遇到它立即停止（也不把它放进结果）。
        每步都对整个已生成前缀重算一次解码器（T 通常很短，实现保持简单）。

        min_p / repetition_penalty / presence_penalty / frequency_penalty /
        no_repeat_ngram_size 与 CausalLM 同义，默认值等于「不干预」。
        """
        if not src_ids:
            raise ValueError("Seq2SeqLM.generate: src_ids 不能为空")
        if isinstance(max_new_tokens, bool) or not isinstance(max_new_tokens, int) \
                or max_new_tokens < 0:
            raise ValueError(
                f"Seq2SeqLM.generate: max_new_tokens 不能为负，收到 {max_new_tokens!r}")
        if temperature <= 0:
            raise ValueError(
                f"Seq2SeqLM.generate: temperature 必须 > 0，收到 {temperature!r}")
        if isinstance(num_beams, bool) or not isinstance(num_beams, int) or num_beams < 1:
            raise ValueError(
                f"Seq2SeqLM.generate: num_beams 必须是 >= 1 的整数，收到 {num_beams!r}")
        top_k = _check_top_k(top_k, "Seq2SeqLM.generate")
        min_p = _check_min_p(min_p, "Seq2SeqLM.generate")
        _check_penalty_args(repetition_penalty, presence_penalty, frequency_penalty,
                            no_repeat_ngram_size, "Seq2SeqLM.generate")
        src_ids = _check_token_ids(src_ids, self.src_vocab, "Seq2SeqLM.generate")
        if len(src_ids) > self.max_len:
            raise ValueError(
                f"Seq2SeqLM.generate: 源序列长度 {len(src_ids)} 超过 max_len={self.max_len}")
        rng = rng or random
        self.eval()
        if num_beams > 1:
            return self._generate_beam(src_ids, int(max_new_tokens), num_beams,
                                       top_k, eos_id, min_p, repetition_penalty,
                                       presence_penalty, frequency_penalty,
                                       no_repeat_ngram_size)
        memory = self._encode(list(src_ids))
        out = []
        tgt = [self.bos_id]
        for _ in range(max_new_tokens):
            if len(tgt) >= self.max_len:
                break
            logits = _apply_generation_penalties(
                self._decode(tgt, memory)[-1], tgt, repetition_penalty,
                presence_penalty, frequency_penalty, no_repeat_ngram_size)
            pick = self._sample(logits, temperature, top_k, rng, top_p,
                                self.tgt_vocab, min_p)
            tgt.append(pick)
            if eos_id is not None and pick == eos_id:
                break
            out.append(pick)
        return out


class ResidualBlock:
    """残差连接：output = x + F(x)"""

    def __init__(self, sublayer):
        self.sublayer = sublayer
        self.x = None

    def forward(self, x):
        self.x = x
        out = self.sublayer.forward(x)
        # 形状不符时下面的逐元素相加会静默丢掉多余分量（或抛 IndexError），必须早失败
        if isinstance(x, list) and x and isinstance(x[0], list):
            if (len(out) != len(x)
                    or any(len(out[t]) != len(x[t]) for t in range(len(x)))):
                raise ValueError(
                    f"ResidualBlock.forward: 子层输出形状与输入不一致"
                    f"（输入 {len(x)}×{len(x[0])}，输出 {len(out)}"
                    f"×{len(out[0]) if out else 0}），残差相加要求形状相同"
                )
        elif len(out) != len(x):
            raise ValueError(
                f"ResidualBlock.forward: 子层输出长度 {len(out)} 与输入长度 {len(x)} 不一致，"
                f"残差相加要求形状相同（是否是子层改了维度？）"
            )
        if isinstance(x, list) and isinstance(x[0], list):
            return [[x[t][j] + out[t][j] for j in range(len(x[0]))] for t in range(len(x))]
        return [x[i] + out[i] for i in range(len(x))]

    def backward(self, dout):
        # sublayer 的 backward 返回值有两种约定（同 Sequential）：
        #   元组 (..., delta) 取其末位；list 则整体就是 delta。
        # Layer / LayerNorm 返回元组，Dropout / Embedding / 注意力等返回 list。
        result = self.sublayer.backward(dout)
        # 各模块的 delta 位置不一定相同（BatchNorm 放在第 0 位），用 delta_index 约定
        d_sublayer = (result[getattr(self.sublayer, "delta_index", -1)]
                      if isinstance(result, tuple) else result)
        if isinstance(dout, list) and isinstance(dout[0], list):
            return [[dout[t][j] + d_sublayer[t][j] for j in range(len(dout[0]))] for t in range(len(dout))]
        return [dout[i] + d_sublayer[i] for i in range(len(dout))]


class Sequential:
    """通用顺序容器，混合 Layer, Dropout, LayerNorm, Embedding 等。

    返回协议约定：
      每个 module.backward(delta) 的返回值必须是以下两种之一：
        - 非元组 (list): 直接作为上一层 delta（如 Dropout、Embedding）
        - 元组 (..., delta): 末尾元素为上一层 delta（如 Layer、LayerNorm）
      即：若返回元组则取其最后一维为 dx；否则整体作为 dx。
    """

    def __init__(self, *modules):
        # 两种写法都接受：Sequential(a, b) 与 Sequential([a, b])。
        # 后者原来会把整个列表当成一个模块，直到 forward 才炸成
        # AttributeError: 'list' object has no attribute 'forward'，现在直接摊平。
        if len(modules) == 1 and isinstance(modules[0], (list, tuple)):
            modules = tuple(modules[0])
        for _i, _m in enumerate(modules):
            if not hasattr(_m, "forward"):
                raise ValueError(
                    f"Sequential: 第 {_i} 个模块 {type(_m).__name__} 没有 forward()，"
                    f"不能放进容器"
                )
        self.modules = list(modules)

    def train(self):
        """切到训练模式（转发给实现了 train() 的子模块）"""
        for m in self.modules:
            if hasattr(m, "train"):
                m.train()
        return self

    def eval(self):
        """切到推理模式（关闭内部的 Dropout，否则推理结果随机）"""
        for m in self.modules:
            if hasattr(m, "eval"):
                m.eval()
        return self

    def forward(self, x):
        for m in self.modules:
            x = m.forward(x)
        return x

    def backward(self, delta):
        for m in reversed(self.modules):
            result = m.backward(delta)
            if result is not None:
                # delta_index 默认 -1（末位）：Layer 的 (gw, gb, dx)、LayerNorm 的
                # (dγ, dβ, dx) 都以 dx 结尾；BatchNorm2d/CrossAttention 这类
                # 「多返回值但主梯度在前」的模块自己声明 delta_index = 0
                delta = (result[getattr(m, "delta_index", -1)]
                         if isinstance(result, tuple) else result)
        return delta



class LoRA:
    """低秩适配（LoRA）：冻结原层，只训练两个小矩阵

    ``y = Layer(x) + scaling * B (A x)``，``A`` 形状 (rank, fan_in)、
    ``B`` 形状 (fan_out, rank)，``scaling = alpha / rank``（alpha 默认 = rank）。

    训练时原层参数被冻结（梯度算出来就丢弃），只更新 A/B；``merge()`` 把
    ``scaling * B A`` 折进原层权重，之后推理零额外开销。1000×1000 的层用
    rank=8 只需 16000 个新参数（0.16%）。
    """

    def __init__(self, layer: Layer, rank: int = 4, alpha: float = None):
        if not isinstance(layer, Layer):
            raise TypeError(f"LoRA: layer 必须是 Layer 实例，收到 {type(layer).__name__}")
        if isinstance(rank, bool) or not isinstance(rank, int) or rank < 1:
            raise ValueError(f"LoRA: rank 必须是正整数，收到 {rank!r}")
        self.layer = layer
        self.rank = rank
        self.alpha = float(rank if alpha is None else alpha)
        if self.alpha <= 0.0:
            raise ValueError(f"LoRA: alpha 必须 > 0，收到 {alpha!r}")
        self.scaling = self.alpha / rank
        self.fan_in = layer.fan_in
        self.fan_out = layer.fan_out
        std = 1.0 / math.sqrt(self.fan_in)
        self.A = [[random.gauss(0, std) for _ in range(self.fan_in)]
                  for _ in range(self.rank)]
        # B 初始化为 0：训练开始时适配分支输出为 0，原模型行为不变
        self.B = [[0.0] * self.rank for _ in range(self.fan_out)]
        self.merged = False
        self.zero_grad()
        self.h = self.x = None

    def zero_grad(self):
        """清零 A/B 的梯度"""
        self.grad_A = [[0.0] * self.fan_in for _ in range(self.rank)]
        self.grad_B = [[0.0] * self.rank for _ in range(self.fan_out)]

    def params(self):
        """返回 [(参数, 梯度)]，可直接喂给上面的优化器"""
        return [(self.A, self.grad_A), (self.B, self.grad_B)]

    def forward(self, x):
        base = self.layer.forward(x)
        if self.merged:
            return base
        self.x = x
        self.h = [sum(map(_mul, row, x)) for row in self.A]        # (rank,)
        delta = [sum(map(_mul, row, self.h)) for row in self.B]    # (fan_out,)
        return [base[j] + self.scaling * delta[j] for j in range(self.fan_out)]

    def backward(self, delta_out):
        """返回 dx（穿过原层与低秩分支）；原层梯度被丢弃（冻结）"""
        if self.merged:
            return self.layer.backward(delta_out)[-1]
        if self.h is None:
            raise RuntimeError("LoRA.backward: 必须先调用 forward()")
        dx_base = self.layer.backward(delta_out)[-1]
        # grad_B += scaling * outer(delta_out, h)
        for j in range(self.fan_out):
            g = self.scaling * delta_out[j]
            row = self.grad_B[j]
            for r in range(self.rank):
                row[r] += g * self.h[r]
        # dh = scaling * B^T delta_out
        dh = [0.0] * self.rank
        for r in range(self.rank):
            acc = 0.0
            for j in range(self.fan_out):
                acc += self.B[j][r] * delta_out[j]
            dh[r] = self.scaling * acc
        # grad_A += outer(dh, x)
        for r in range(self.rank):
            g = dh[r]
            row = self.grad_A[r]
            for i in range(self.fan_in):
                row[i] += g * self.x[i]
        # dx = dx_base + A^T dh
        dx = list(dx_base)
        for i in range(self.fan_in):
            acc = 0.0
            for r in range(self.rank):
                acc += self.A[r][i] * dh[r]
            dx[i] += acc
        return dx

    def merge(self):
        """把 scaling*B@A 折进原层权重，之后 forward 不再走低秩分支"""
        if self.merged:
            return self
        W = self.layer.weights
        for j in range(self.fan_out):
            for i in range(self.fan_in):
                acc = 0.0
                for r in range(self.rank):
                    acc += self.B[j][r] * self.A[r][i]
                W[j][i] += self.scaling * acc
        for j in range(self.fan_out):
            for r in range(self.rank):
                self.B[j][r] = 0.0
        self.merged = True
        return self

    def trainable_param_count(self):
        """可训练参数个数：只算 A/B（原层被冻结）"""
        return self.rank * self.fan_in + self.fan_out * self.rank

    def total_param_count(self):
        """包装后的参数总数：原层参数 + 可训练的 A/B"""
        return self.fan_out * (self.fan_in + 1) + self.trainable_param_count()



_ATTN_RAMP = " .:-=+*#%@"


class IA3:
    """IA³ 适配器：冻结原层，只训练输出通道上的缩放向量

    ``y = v * Layer(x)``，``v`` 初始化为全 1，训练开始时不影响原模型输出。
    与 LoRA 一样是包装类：``forward`` 走原层，``backward`` 把梯度穿过原层
    （原层梯度被丢弃，不更新），只有 ``v`` 参与优化。参数里每个输出通道
    只多一个标量，因此比 LoRA 更轻。
    """

    def __init__(self, layer: Layer, init: float = 1.0):
        if not isinstance(layer, Layer):
            raise TypeError(f"IA3: layer 必须是 Layer 实例，收到 {type(layer).__name__}")
        if isinstance(init, bool) or not isinstance(init, (int, float)):
            raise TypeError(f"IA3: init 必须是数字，收到 {init!r}")
        self.layer = layer
        self.fan_out = layer.fan_out
        self.v = [float(init)] * self.fan_out
        self.grad_v = [0.0] * self.fan_out
        self.base = None
        self.x = None

    def zero_grad(self):
        """清零 v 的梯度"""
        self.grad_v = [0.0] * self.fan_out

    def params(self):
        """返回 [(参数, 梯度)]，可直接喂给上面的优化器"""
        return [(self.v, self.grad_v)]

    def trainable_param_count(self):
        """可训练参数个数（每个输出通道一个缩放标量）"""
        return self.fan_out

    def total_param_count(self):
        """总参数个数（原层参数 + 缩放向量）"""
        return self.fan_out + self.layer.fan_in * self.layer.fan_out + self.fan_out

    def forward(self, x):
        base = self.layer.forward(x)
        self.base = base
        self.x = x
        return [self.v[j] * base[j] for j in range(self.fan_out)]

    def backward(self, delta_out):
        """返回 dx；原层参数只收梯度不更新"""
        if self.base is None:
            raise RuntimeError("IA3.backward: 必须先调用 forward()")
        for j in range(self.fan_out):
            self.grad_v[j] += delta_out[j] * self.base[j]
        d_base = [self.v[j] * delta_out[j] for j in range(self.fan_out)]
        return self.layer.backward(d_base)[-1]


class QLoRA:
    """QLoRA：冻结的基座权重先做低比特伪量化，再训练 LoRA 适配器。

    ``y = Q(W) x + scaling · B(A x)``，``Q`` 是 ``fake_quantize`` 的伪量化
    反量化值（前向不需要额外解包）；``A/B`` 与 :class:`LoRA` 相同，``B`` 初始
    为 0，因此训练开始时输出等于「量化后的基座」——与全精度基座的差距就是
    量化误差。这是教学用的组合：把 4/8 bit 基座与低秩适配器接在一起，不真的
    用 int4 压缩存储。
    """

    def __init__(self, layer: Layer, rank: int = 4, alpha: float = None,
                 bits: int = 4):
        if not isinstance(layer, Layer):
            raise TypeError(
                f"QLoRA: layer 必须是 Layer 实例，收到 {type(layer).__name__}")
        _w15_check_bits(bits, "QLoRA")
        self.bits = bits
        self.adapter = LoRA(layer, rank, alpha)
        self.layer = layer
        self.fan_in = layer.fan_in
        self.fan_out = layer.fan_out
        # 基座权重低比特伪量化（冻结；写回反量化值，前向路径不变）
        layer.weights = fake_quantize(layer.weights, bits=bits)
        self.merged = False

    def zero_grad(self):
        """清零 LoRA 的 A/B 梯度。"""
        self.adapter.zero_grad()

    def params(self):
        """返回 [(参数, 梯度)]，只含 LoRA 的 A/B。"""
        return self.adapter.params()

    def forward(self, x):
        return self.adapter.forward(x)

    def backward(self, delta_out):
        return self.adapter.backward(delta_out)

    def merge(self):
        """把 LoRA 分支折进（已量化的）基座权重。"""
        self.adapter.merge()
        self.merged = True
        return self

    def trainable_param_count(self):
        """可训练参数个数（只算 A/B）。"""
        return self.adapter.trainable_param_count()

    def total_param_count(self):
        """总参数个数（量化基座 + LoRA 的 A/B）。"""
        return self.fan_out * (self.fan_in + 1) + self.trainable_param_count()


class VeRA:
    """VeRA：冻结随机低秩投影，只训练缩放向量 ``d``。

    ``y = Layer(x) + scaling · B (d ⊙ (A x))``；``A (rank×fan_in)`` 与
    ``B (fan_out×rank)`` 随机初始化后冻结，``d`` 初始为 0，因此训练开始时
    与基座逐位一致。可训练参数只有 ``rank`` 个，比 LoRA 更省；``merge()``
    可以把低秩增量折进权重。
    """

    def __init__(self, layer: Layer, rank: int = 4, alpha: float = None,
                 seed=None):
        if not isinstance(layer, Layer):
            raise TypeError(
                f"VeRA: layer 必须是 Layer 实例，收到 {type(layer).__name__}")
        if isinstance(rank, bool) or not isinstance(rank, int) or rank < 1:
            raise ValueError(f"VeRA: rank 必须是正整数，收到 {rank!r}")
        self.layer = layer
        self.rank = rank
        self.alpha = float(rank if alpha is None else alpha)
        if not self.alpha > 0.0:
            raise ValueError(f"VeRA: alpha 必须 > 0，收到 {alpha!r}")
        self.scaling = self.alpha / rank
        self.fan_in = layer.fan_in
        self.fan_out = layer.fan_out
        rng = random.Random(seed)
        std_a = 1.0 / math.sqrt(self.fan_in)
        self.A = [[rng.gauss(0.0, std_a) for _ in range(self.fan_in)]
                  for _ in range(self.rank)]
        std_b = 1.0 / math.sqrt(float(self.rank))
        self.B = [[rng.gauss(0.0, std_b) for _ in range(self.rank)]
                  for _ in range(self.fan_out)]
        # d 初始为 0：训练开始时适配分支输出为 0，与基座逐位一致
        self.d = [0.0] * self.rank
        self.grad_d = [0.0] * self.rank
        self.merged = False
        self.x = None
        self.h = None

    def zero_grad(self):
        """清零 d 的梯度。"""
        self.grad_d = [0.0] * self.rank

    def params(self):
        """返回 [(d, grad_d)]，可直接喂给优化器。"""
        return [(self.d, self.grad_d)]

    def forward(self, x):
        if self.merged:
            return self.layer.forward(x)
        base = self.layer.forward(x)
        self.x = list(x)
        self.h = [sum(map(_mul, row, x)) for row in self.A]
        hd = [self.d[r] * self.h[r] for r in range(self.rank)]
        delta = [sum(self.B[j][r] * hd[r] for r in range(self.rank))
                 for j in range(self.fan_out)]
        return [base[j] + self.scaling * delta[j]
                for j in range(self.fan_out)]

    def backward(self, delta_out):
        """返回 dx；基座梯度被丢弃（冻结）。"""
        if self.merged:
            return self.layer.backward(delta_out)[-1]
        if self.h is None:
            raise RuntimeError("VeRA.backward: 必须先调用 forward()")
        dx_base = self.layer.backward(delta_out)[-1]
        dh = [0.0] * self.rank
        for r in range(self.rank):
            acc = 0.0
            for j in range(self.fan_out):
                acc += self.B[j][r] * delta_out[j]
            dh[r] = self.scaling * acc
        for r in range(self.rank):
            self.grad_d[r] += self.h[r] * dh[r]
        dx = list(dx_base)
        for i in range(self.fan_in):
            acc = 0.0
            for r in range(self.rank):
                acc += self.A[r][i] * self.d[r] * dh[r]
            dx[i] += acc
        return dx

    def merge(self):
        """把低秩增量折进基座权重。"""
        if self.merged:
            return self
        W = self.layer.weights
        for j in range(self.fan_out):
            for i in range(self.fan_in):
                acc = 0.0
                for r in range(self.rank):
                    acc += self.B[j][r] * self.d[r] * self.A[r][i]
                W[j][i] += self.scaling * acc
        self.d = [0.0] * self.rank
        self.merged = True
        return self

    def trainable_param_count(self):
        """可训练参数个数（rank 个缩放标量）。"""
        return self.rank

    def total_param_count(self):
        """总参数个数（基座 + 冻结投影 + 缩放向量）。"""
        return (self.fan_out * (self.fan_in + 1) + self.rank
                + self.rank * self.fan_in + self.fan_out * self.rank)


class ReFT:
    """ReFT / LoReFT 风格：冻结原层，只做低秩表示干预。

    ``y = Layer(x) + scaling · Pᵀ (W·Layer(x) + b)``，``P (rank×fan_out)``
    固定随机投影，``W (rank×fan_out)`` 与 ``b (rank)`` 可训练且初始为 0
    （训练开始时与基座逐位一致）。干预在层输出上而不是权重上，不能折进权重。
    """

    def __init__(self, layer: Layer, rank: int = 2, alpha: float = None,
                 seed=None):
        if not isinstance(layer, Layer):
            raise TypeError(
                f"ReFT: layer 必须是 Layer 实例，收到 {type(layer).__name__}")
        if isinstance(rank, bool) or not isinstance(rank, int) or rank < 1:
            raise ValueError(f"ReFT: rank 必须是正整数，收到 {rank!r}")
        self.layer = layer
        self.rank = rank
        self.alpha = float(rank if alpha is None else alpha)
        if not self.alpha > 0.0:
            raise ValueError(f"ReFT: alpha 必须 > 0，收到 {alpha!r}")
        self.scaling = self.alpha / rank
        self.fan_out = layer.fan_out
        rng = random.Random(seed)
        self.P = [[rng.gauss(0.0, 1.0 / math.sqrt(float(self.fan_out)))
                   for _ in range(self.fan_out)] for _ in range(self.rank)]
        self.W = [[0.0] * self.fan_out for _ in range(self.rank)]
        self.b = [0.0] * self.rank
        self.grad_W = [[0.0] * self.fan_out for _ in range(self.rank)]
        self.grad_b = [0.0] * self.rank
        self.base = None
        self.z = None

    def zero_grad(self):
        """清零 W / b 的梯度。"""
        self.grad_W = [[0.0] * self.fan_out for _ in range(self.rank)]
        self.grad_b = [0.0] * self.rank

    def params(self):
        """返回 [(W, grad_W), (b, grad_b)]。"""
        return [(self.W, self.grad_W), (self.b, self.grad_b)]

    def forward(self, x):
        base = self.layer.forward(x)
        self.base = list(base)
        self.z = [sum(self.W[r][j] * base[j] for j in range(self.fan_out))
                  + self.b[r] for r in range(self.rank)]
        delta = [sum(self.P[r][j] * self.z[r] for r in range(self.rank))
                 for j in range(self.fan_out)]
        return [base[j] + self.scaling * delta[j]
                for j in range(self.fan_out)]

    def backward(self, delta_out):
        """返回 dx；基座梯度被丢弃（冻结）。"""
        if self.base is None:
            raise RuntimeError("ReFT.backward: 必须先调用 forward()")
        dz = [0.0] * self.rank
        for r in range(self.rank):
            acc = 0.0
            for j in range(self.fan_out):
                acc += self.P[r][j] * delta_out[j]
            dz[r] = self.scaling * acc
        for r in range(self.rank):
            self.grad_b[r] += dz[r]
            for j in range(self.fan_out):
                self.grad_W[r][j] += dz[r] * self.base[j]
        d_base = list(delta_out)
        for j in range(self.fan_out):
            for r in range(self.rank):
                d_base[j] += self.W[r][j] * dz[r]
        return self.layer.backward(d_base)[-1]

    def trainable_param_count(self):
        """可训练参数个数（W 与 b）。"""
        return self.rank * self.fan_out + self.rank

    def total_param_count(self):
        """总参数个数（基座 + 固定投影 + W/b）。"""
        return (self.fan_out * (self.layer.fan_in + 1)
                + self.rank * self.fan_out * 2 + self.rank)


def _copy_attn_maps(heads, who):
    """把 MHA 缓存的每头权重整理成纯 float 的嵌套列表，并做形状自检。"""
    if heads is None:
        raise RuntimeError(f"{who}: 没有注意力缓存（先 forward 一次）")
    if not isinstance(heads, list) or not heads:
        raise RuntimeError(f"{who}: 注意力缓存为空")
    out = []
    seq = None
    for h, mat in enumerate(heads):
        if not isinstance(mat, list) or not mat:
            raise RuntimeError(f"{who}: 第 {h} 头的注意力矩阵为空")
        cols = len(mat[0])
        if seq is None:
            seq = len(mat)
        if len(mat) != seq or any(len(row) != cols for row in mat):
            raise RuntimeError(f"{who}: 第 {h} 头的注意力矩阵不是方阵")
        out.append([[float(v) for v in row] for row in mat])
    return out, seq


def attention_maps(module, x, layer_index=None):
    """跑一次前向，取回每头注意力权重（只读，不改参数）。

    支持：
      - `MultiHeadAttention`：返回 `{"num_heads", "seq_len", "maps"}`，
        其中 `maps[h][t][j]` 是第 h 头里位置 t 对位置 j 的权重（行和 1）。
      - `TransformerEncoderLayer`：取它的 `self_attn`。
      - `TransformerEncoder`：返回 `{"layers": [{"layer": i, ...}, ...]}`；
        给 `layer_index` 时只取那一层。
      - `CausalLM`：`x` 是 token id 列表，返回编码器各层的图。

    为了不受 dropout 随机遮罩影响，采样期间会把模型切到 eval，结束后恢复原模式。
    """
    if layer_index is not None and (isinstance(layer_index, bool)
                                    or not isinstance(layer_index, int)):
        raise TypeError("attention_maps: layer_index 必须是 int 或 None")

    def _grab(mha, who):
        maps, seq = _copy_attn_maps(getattr(mha, "attn_weights", None), who)
        return {"num_heads": len(maps), "seq_len": seq, "maps": maps}

    if isinstance(module, MultiHeadAttention):
        was = module.training
        module.eval()
        try:
            module.forward(x)
        finally:
            module.train() if was else module.eval()
        return _grab(module, "attention_maps(MultiHeadAttention)")

    if isinstance(module, TransformerEncoderLayer):
        was = module.self_attn.training
        module.eval()
        try:
            module.forward(x)
        finally:
            module.train() if was else module.eval()
        return _grab(module.self_attn, "attention_maps(TransformerEncoderLayer)")

    if isinstance(module, TransformerEncoder):
        was = module.layers[0].self_attn.training
        module.eval()
        try:
            module.forward(x)
        finally:
            module.train() if was else module.eval()
        layers = []
        for i, layer in enumerate(module.layers):
            if layer_index is not None and i != layer_index:
                continue
            item = _grab(layer.self_attn, f"attention_maps(encoder 第 {i} 层)")
            item["layer"] = i
            layers.append(item)
        if not layers:
            raise ValueError(
                f"attention_maps: layer_index={layer_index} 超出范围 [0, {len(module.layers)})")
        return {"layers": layers}

    if isinstance(module, CausalLM):
        was = _lm_training_state(module)
        module.eval()
        try:
            module.forward(x)
        finally:
            _lm_restore_mode(module, was)
        layers = []
        for i, layer in enumerate(module.encoder.layers):
            if layer_index is not None and i != layer_index:
                continue
            item = _grab(layer.self_attn, f"attention_maps(CausalLM 第 {i} 层)")
            item["layer"] = i
            layers.append(item)
        if not layers:
            raise ValueError(
                f"attention_maps: layer_index={layer_index} 超出范围 [0, {len(module.encoder.layers)})")
        return {"layers": layers}

    raise TypeError(
        "attention_maps: 支持 MultiHeadAttention / TransformerEncoderLayer / "
        f"TransformerEncoder / CausalLM，收到 {type(module).__name__}")


def attention_ascii(maps, head=0, max_width=48):
    """把一张注意力矩阵画成字符热图（每行归一化到自身最大值）。

    `maps` 可以是 `attention_maps` 的返回值，也可以直接是 `heads` 列表；
    返回多行字符串，含 0-9 的强度刻度说明。
    """
    if isinstance(maps, dict):
        if "maps" in maps:
            maps = maps["maps"]
        elif "layers" in maps:
            if not maps["layers"]:
                raise ValueError("attention_ascii: layers 为空")
            maps = maps["layers"][0]["maps"]
        else:
            raise ValueError("attention_ascii: 不认识的结构")
    if not isinstance(maps, (list, tuple)) or not maps:
        raise ValueError("attention_ascii: maps 必须是非空列表")
    if isinstance(head, bool) or not isinstance(head, int):
        raise TypeError("attention_ascii: head 必须是 int")
    if head < 0 or head >= len(maps):
        raise ValueError(f"attention_ascii: head={head} 越界 [0, {len(maps)})")
    if isinstance(max_width, bool) or not isinstance(max_width, int):
        raise TypeError("attention_ascii: max_width 必须是 int")
    if max_width < 1:
        raise ValueError("attention_ascii: max_width 必须 >= 1")

    mat = maps[head]
    n = len(mat)
    step = max(1, (n + max_width - 1) // max_width)
    rows = [f"head {head}  ({n}x{n}，每 {step} 个位置取一格)"]
    for t in range(0, n, step):
        row = mat[t]
        peak = max(row) if row else 0.0
        chars = []
        for j in range(0, n, step):
            v = row[j] / peak if peak > 0 else 0.0
            chars.append(_ATTN_RAMP[min(len(_ATTN_RAMP) - 1, int(v * (len(_ATTN_RAMP) - 1) + 0.5))])
        rows.append(f"{t:>4} |" + "".join(chars) + "|")
    rows.append("     " + "-" * len(range(0, n, step)))
    rows.append("     强度：'" + _ATTN_RAMP.strip() + "' = 0 -> 1（每行按自身最大值缩放）")
    return "\n".join(rows)


def profile_model(model, x, backward: bool = False, repeat: int = 3):
    """逐层统计前向（可选反向）耗时，返回 dict

    参数：
        model: `MLP` / `Model` / `Sequential`，或任何带 `.layers` 与 `.forward` 的对象
        x: 一个样本（调用方保证维度正确）
        backward: 为 True 时一并统计反向（用全 1 的 delta 起反传）
        repeat: 每种测量重复次数，取**最小值**（受调度抖动影响最小）

    返回：`{"layers": [{"index","type","forward_ms","backward_ms"}],
            "total_ms", "backward_total_ms", "params"}`

    说明：这是纯墙钟测量，不含 CUDA/内存统计；单层耗时很小（微秒级）时
    数字抖动明显，用 `repeat` 取最小值和相对占比来读更可靠。
    """
    if isinstance(repeat, bool) or not isinstance(repeat, int) or repeat < 1:
        raise ValueError(f"profile_model: repeat 必须是正整数，收到 {repeat!r}")
    net = model.model if isinstance(model, Model) else model
    if not hasattr(net, "layers") or not hasattr(net, "forward"):
        raise TypeError(
            f"profile_model: 需要带 layers/forward 的网络，收到 {type(model).__name__}")
    if not net.layers:
        raise ValueError("profile_model: 网络没有任何层")

    params = sum(getattr(l, "fan_in", 0) * getattr(l, "fan_out", 0)
                 + getattr(l, "fan_out", 0) for l in net.layers)

    # 前向：逐层测量，同时把输出串给下一层
    fwd = []
    cur = list(x)
    for layer in net.layers:
        best = None
        for _ in range(repeat):
            t0 = time.perf_counter()
            out = layer.forward(list(cur))
            dt = time.perf_counter() - t0
            best = dt if best is None else min(best, dt)
        fwd.append(best)
        cur = out

    # 反向：先整网前向一次建立每层的缓存，再从最后一层往前测
    bwd = [0.0] * len(net.layers)
    if backward:
        net.forward(list(x))
        delta = [1.0] * net.layers[-1].fan_out
        for i in range(len(net.layers) - 1, -1, -1):
            layer = net.layers[i]
            base_delta = delta          # 每次重复都用同一个输入，才能比较耗时
            best = None
            nxt = None
            for _ in range(repeat):
                t0 = time.perf_counter()
                _gw, _gb, nxt = layer.backward(base_delta)
                dt = time.perf_counter() - t0
                best = dt if best is None else min(best, dt)
            bwd[i] = best
            delta = nxt

    layers = [{
        "index": i,
        "type": type(layer).__name__,
        "forward_ms": fwd[i] * 1000.0,
        "backward_ms": bwd[i] * 1000.0,
    } for i, layer in enumerate(net.layers)]
    return {
        "layers": layers,
        "total_ms": sum(fwd) * 1000.0,
        "backward_total_ms": (sum(bwd) * 1000.0) if backward else None,
        "params": params,
    }


def ascii_flame_graph(profile, width=40, char="█"):
    """把 ``profile_model`` 的结果画成 ASCII 火焰图（按前向耗时比例条）。

    每行一个层：``索引 类型 耗时ms |bar``；条长与最慢层的耗时成比例（至少 1 格）。
    返回多行字符串；纯文本、可直接 print。``backward_ms`` 只在 profile 含反向时
    才有意义，本函数只用 ``forward_ms``，避免拿两套不同单位的数字混排。
    """
    if not isinstance(profile, dict) or not isinstance(profile.get("layers"), list):
        raise ValueError("ascii_flame_graph: profile 必须是 profile_model 返回的 dict")
    if not profile["layers"]:
        raise ValueError("ascii_flame_graph: profile 里没有任何层")
    if isinstance(width, bool) or not isinstance(width, int) or not 10 <= width <= 200:
        raise ValueError(f"ascii_flame_graph: width 必须是 [10, 200] 的整数，收到 {width!r}")
    if not isinstance(char, str) or len(char) != 1:
        raise ValueError(f"ascii_flame_graph: char 必须是单个字符，收到 {char!r}")
    times = []
    for i, row in enumerate(profile["layers"]):
        if not isinstance(row, dict):
            raise ValueError(f"ascii_flame_graph: layers[{i}] 必须是 dict")
        fwd = row.get("forward_ms")
        if isinstance(fwd, bool) or not isinstance(fwd, (int, float)):
            raise ValueError(f"ascii_flame_graph: layers[{i}].forward_ms 必须是数字")
        times.append(max(0.0, float(fwd)))
    peak = max(times)
    lines = ["索引 层类型           前向耗时     占比条"]
    for i, row in enumerate(profile["layers"]):
        t = times[i]
        bar = char * max(1, int(round(t / peak * width))) if peak > 0.0 and t > 0.0 else ""
        pct = (t / peak * 100.0) if peak > 0.0 else 0.0
        name = str(row.get("type", "?"))[:16]
        lines.append(f"{i:>3} {name:<16} {t:>9.3f}ms {pct:>5.1f}% |{bar}")
    return "\n".join(lines)


def evaluation_report_html(title, metrics, tables=None, notes=None):
    """生成一份零依赖的独立 HTML 评估报告（字符串），可直接写文件/浏览器打开。

    ``metrics`` 是 ``名称 -> 数值`` 的 dict；``tables`` 是
    ``[{"caption": str, "columns": [str, ...], "rows": [[...], ...]}, ...]``；
    ``notes`` 是字符串列表。所有内容都做 HTML 转义，不插入任何脚本。
    """
    if not isinstance(title, str) or not title.strip():
        raise ValueError("evaluation_report_html: title 必须是非空字符串")
    if not isinstance(metrics, dict):
        raise ValueError("evaluation_report_html: metrics 必须是 dict")
    if tables is None:
        tables = []
    if not isinstance(tables, list):
        raise ValueError("evaluation_report_html: tables 必须是列表")
    if notes is None:
        notes = []
    if not isinstance(notes, list) or any(not isinstance(n, str) for n in notes):
        raise ValueError("evaluation_report_html: notes 必须是字符串列表")
    esc = html.escape

    def fmt_metric(value):
        if isinstance(value, bool):
            return esc("是" if value else "否")
        if isinstance(value, float):
            return esc(f"{value:.6g}")
        if value is None:
            return "—"
        if isinstance(value, (int, str)):
            return esc(str(value))
        raise ValueError(
            f"evaluation_report_html: metrics 的值必须是数字/字符串/bool/None，收到 {type(value).__name__}"
        )

    body = [f"<h1>{esc(title)}</h1>", "<h2>指标</h2>", "<table class=\"metrics\">"]
    for name in sorted(metrics):
        if not isinstance(name, str) or not name:
            raise ValueError("evaluation_report_html: metrics 的键必须是非空字符串")
        body.append(f"<tr><th>{esc(name)}</th><td>{fmt_metric(metrics[name])}</td></tr>")
    body.append("</table>")
    for block in tables:
        if not isinstance(block, dict):
            raise ValueError("evaluation_report_html: tables 的每一项必须是 dict")
        caption = block.get("caption", "")
        columns = block.get("columns")
        rows = block.get("rows")
        if not isinstance(caption, str):
            raise ValueError("evaluation_report_html: table.caption 必须是字符串")
        if not isinstance(columns, list) or not columns or \
                any(not isinstance(c, str) or not c for c in columns):
            raise ValueError("evaluation_report_html: table.columns 必须是非空字符串列表")
        if not isinstance(rows, list):
            raise ValueError("evaluation_report_html: table.rows 必须是列表")
        body.append(f"<h2>{esc(caption)}</h2>" if caption else "<h2>表格</h2>")
        body.append("<table>")
        body.append("<tr>" + "".join(f"<th>{esc(c)}</th>" for c in columns) + "</tr>")
        for row in rows:
            if not isinstance(row, (list, tuple)) or len(row) != len(columns):
                raise ValueError("evaluation_report_html: table.rows 每行长度必须与 columns 一致")
            body.append("<tr>" + "".join(f"<td>{esc(str(v))}</td>" for v in row) + "</tr>")
        body.append("</table>")
    if notes:
        body.append("<h2>备注</h2><ul>")
        body.extend(f"<li>{esc(n)}</li>" for n in notes)
        body.append("</ul>")
    style = ("body{font-family:system-ui,-apple-system,'Segoe UI',sans-serif;max-width:960px;"
             "margin:2rem auto;padding:0 1rem;line-height:1.55;color:#222}"
             "table{border-collapse:collapse;margin:.5rem 0 1.5rem}"
             "th,td{border:1px solid #c8cdd4;padding:.3rem .7rem;text-align:left}"
             "th{background:#eef2f7}table.metrics th{width:12rem}code{background:#f3f4f6;padding:.1rem .3rem}")
    head = (f"<!DOCTYPE html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">"
            f"<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">"
            f"<title>{esc(title)}</title><style>{style}</style></head><body>")
    return head + "\n".join(body) + "</body></html>"


def dataset_version(data, store_dir=None):
    """给 Python 数据做内容寻址版本（DVC 风格，零依赖）。

    用 ``json.dumps(data, sort_keys=True, ensure_ascii=False, separators=(",", ":"))``
    的 UTF-8 字节算 SHA-256 作为版本号；``store_dir`` 给定时把内容写到
    ``<store_dir>/objects/<version[:2]>/<version[2:]>.json``（已存在则不重写），
    并向 ``<store_dir>/versions.jsonl`` 追加一行 ``{"version","bytes","created_at"}``。
    返回 ``{"version","bytes","stored"}``；``stored`` 为 None 表示只算哈希未落盘。

    局限：这是**单机教学版**，没有远端存储/垃圾回收/锁；大文件会整体读入内存。
    """
    if store_dir is not None and (not isinstance(store_dir, str) or not store_dir):
        raise ValueError("dataset_version: store_dir 必须是非空字符串或 None")
    try:
        payload = json.dumps(data, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
    except (TypeError, ValueError) as exc:
        raise ValueError(f"dataset_version: data 必须可 JSON 序列化（{exc}）")
    raw = payload.encode("utf-8")
    version = hashlib.sha256(raw).hexdigest()
    stored = None
    if store_dir is not None:
        obj_dir = os.path.join(store_dir, "objects", version[:2])
        path = os.path.join(obj_dir, version[2:] + ".json")
        os.makedirs(obj_dir, exist_ok=True)
        if not os.path.exists(path):
            with io.open(path, "w", encoding="utf-8", newline="\n") as f:
                f.write(payload)
        manifest = os.path.join(store_dir, "versions.jsonl")
        with io.open(manifest, "a", encoding="utf-8", newline="\n") as f:
            f.write(json.dumps({"version": version, "bytes": len(raw),
                                "created_at": int(time.time())}, ensure_ascii=False) + "\n")
        stored = path
    return {"version": version, "bytes": len(raw), "stored": stored}


def load_dataset_version(store_dir, version):
    """按版本号从 ``dataset_version`` 的对象库读回数据（会校验 SHA-256）。"""
    if not isinstance(store_dir, str) or not store_dir:
        raise ValueError("load_dataset_version: store_dir 必须是非空字符串")
    if not isinstance(version, str) or not re.fullmatch(r"[0-9a-f]{64}", version):
        raise ValueError(f"load_dataset_version: version 必须是 64 位小写十六进制，收到 {version!r}")
    path = os.path.join(store_dir, "objects", version[:2], version[2:] + ".json")
    if not os.path.exists(path):
        raise FileNotFoundError(f"load_dataset_version: 版本 {version[:12]}… 不存在（{path}）")
    with io.open(path, "r", encoding="utf-8") as f:
        text = f.read()
    digest = hashlib.sha256(text.encode("utf-8")).hexdigest()
    if digest != version:
        raise ValueError(
            f"load_dataset_version: 内容校验失败（期望 {version}，实际 {digest}）"
        )
    return json.loads(text)


def lr_finder(model, data=None, x=None, y=None, start_lr: float = 1e-5,
              end_lr: float = 1.0, steps: int = 60, smooth: float = 0.05,
              seed=None):
    """学习率扫描（LR range test 简化版）

    从 `start_lr` 指数增长到 `end_lr`，每步取一个样本做一次真实更新并记录 loss。
    返回 `{"history": [(lr, loss, smoothed)], "best_lr", "suggested_lr", "final_loss"}`。

    `suggested_lr` 取「平滑 loss 最低点 / 10」并夹在 `[start_lr, end_lr]` 内：
    最低点通常已在发散边缘，低一个量级更安全。

    注意：扫描会**真实修改模型权重**（与 PyTorch 的 lr_finder 一样），
    需要干净权重请先复制；结束后 `optimizer.lr` 会恢复原值。
    """
    if not isinstance(model, Model):
        raise TypeError(f"lr_finder: 需要 Model，收到 {type(model).__name__}")
    for name, val in (("start_lr", start_lr), ("end_lr", end_lr)):
        if isinstance(val, bool) or not isinstance(val, (int, float)) or not val > 0:
            raise ValueError(f"lr_finder: {name} 必须是正数，收到 {val!r}")
    if not end_lr > start_lr:
        raise ValueError(
            f"lr_finder: 要求 end_lr > start_lr，收到 {start_lr!r} -> {end_lr!r}")
    if isinstance(steps, bool) or not isinstance(steps, int) or steps < 2:
        raise ValueError(f"lr_finder: steps 必须是 >=2 的整数，收到 {steps!r}")
    if isinstance(smooth, bool) or not isinstance(smooth, (int, float)) \
            or not 0.0 < float(smooth) <= 1.0:
        raise ValueError(f"lr_finder: smooth 必须在 (0,1] 内，收到 {smooth!r}")

    if data is not None:
        dataset = [(list(a), b) for a, b in data]
    elif x is not None and y is not None:
        if isinstance(y, (int, float)) and not isinstance(y, bool):
            y = [y] * len(x)
        if len(x) != len(y):
            raise ValueError(
                f"lr_finder: x 有 {len(x)} 个样本，y 有 {len(y)} 个，数量必须一致")
        dataset = [(list(a), b) for a, b in zip(x, y)]
    else:
        raise ValueError("lr_finder: 需要 data 或 (x, y)")
    if not dataset:
        raise ValueError("lr_finder: 数据集不能为空")

    rng = random.Random(seed) if seed is not None else random
    order = list(range(len(dataset)))
    rng.shuffle(order)

    old_lr = model.optimizer.lr
    lr = float(start_lr)
    mult = (float(end_lr) / float(start_lr)) ** (1.0 / (steps - 1))
    history = []
    ema = None
    diverged_at = None
    # 单个样本的 loss 噪声太大，指数平滑也救不回来；这里每步用小批的平均值
    batch = min(8, len(dataset))
    layers = model.model.layers
    try:
        for step in range(steps):
            idxs = [order[(step * batch + t) % len(order)] for t in range(batch)]
            model.optimizer.lr = lr
            acc_w = [[[0.0] * layer.fan_in for _ in range(layer.fan_out)]
                     for layer in layers]
            acc_b = [[0.0] * layer.fan_out for layer in layers]
            loss_sum = 0.0
            for i in idxs:
                xi, yi = dataset[i]
                pred = model.forward(xi)
                loss_i, grad_i = model._loss(pred, yi)
                loss_sum += loss_i
                delta = grad_i
                li = len(layers) - 1
                for layer in reversed(layers):
                    gw, gb, delta = layer.backward(delta)
                    aw, ab = acc_w[li], acc_b[li]
                    for j in range(layer.fan_out):
                        awj, gwj = aw[j], gw[j]
                        for k in range(layer.fan_in):
                            awj[k] += gwj[k]
                        ab[j] += gb[j]
                    li -= 1
            loss = loss_sum / batch
            n = float(batch)
            grads = [([[v / n for v in row] for row in acc_w[i]],
                      [v / n for v in acc_b[i]]) for i in range(len(layers))]
            model.optimizer.step(grads)
            # 一旦 loss 变成 inf/NaN 就停：继续扫描只会污染权重，也没有信息量
            if not math.isfinite(loss):
                diverged_at = lr
                break
            ema = loss if ema is None else (1.0 - smooth) * ema + smooth * loss
            if not math.isfinite(ema):
                diverged_at = lr
                break
            history.append((lr, loss, ema))
            lr *= mult
    finally:
        model.optimizer.lr = old_lr

    # 经典 fastai 规则：取平滑 loss 的最低点，推荐它的 1/10
    # （最低点往往已在发散边缘，降一个量级更稳；这与我们的 lr_finder 探针实测一致）
    note = None
    if len(history) > 1:
        inner = history[1:] if len(history) > 4 else history   # 跳过第一步（EMA 尚未稳定）
        low_item = min(inner, key=lambda r: r[2])
    else:
        low_item = history[0]
    best_lr = low_item[0]
    if low_item is history[-1] or best_lr == history[-1][0]:
        note = "loss 到扫描末尾仍在下降，建议把 end_lr 调大后再扫一次"
    lowest = best_lr
    suggested = max(float(start_lr), min(float(end_lr), float(best_lr) / 10.0))
    return {
        "history": history,
        "best_lr": best_lr,
        "lowest_loss_lr": lowest,
        "suggested_lr": suggested,
        "final_loss": history[-1][1],
        "diverged_at": diverged_at,
        "note": note,
    }


# ============================================================================
#  Loss Functions
# ============================================================================

def _numeric_pair(pred, target, who):
    """把 (pred, target) 规范成等长 float 列表；target 允许标量（只能配单输出）

    本函数拒绝 NaN 输入：NaN 会让损失静默变成 nan（而且它还会被 ReLU 这类
    `x if x > 0 else 0` 的写法吞掉，看起来「一切正常」）。±Inf 仍按 IEEE 语义放行——
    溢出成 inf 是可见的，而 NaN 会无声扩散。
    """
    if isinstance(target, (list, tuple)):
        if len(target) != len(pred):
            raise ValueError(f"{who}: target 长度 {len(target)} != pred 长度 {len(pred)}")
        ts = [float(t) for t in target]
        ps = [float(p) for p in pred]
    else:
        ps = [float(p) for p in pred]
        if len(ps) != 1:
            raise ValueError(f"{who}: 标量 target 只能配单个输出，pred 长度是 {len(ps)}")
        ts = [float(target)]
    for i, v in enumerate(ps):
        if v != v:
            raise ValueError(f"{who}: pred 第 {i} 个值是 NaN")
    for i, v in enumerate(ts):
        if v != v:
            raise ValueError(f"{who}: target 第 {i} 个值是 NaN")
    return ts, ps


def l1_loss(pred, target):
    """L1（MAE）损失：逐元素 |p-y| 的平均值；梯度是 sign(p-y)/n

    对离群点不敏感，但在 0 附近不可导（本实现取 sign，两侧极限一致）。
    返回 (loss, grad)，grad 相对 pred。
    """
    ts, ps = _numeric_pair(pred, target, "l1_loss")
    n = len(ts)
    if n == 0:
        raise ValueError("l1_loss: pred 不能为空")
    loss = 0.0
    grad = []
    for y, p in zip(ts, ps):
        e = p - y
        loss += abs(e)
        grad.append((1.0 if e > 0 else (-1.0 if e < 0 else 0.0)) / n)
    return loss / n, grad


def log_cosh_loss(pred, target):
    """Log-Cosh 损失：log(cosh(p-y)) 的平均值；梯度 tanh(p-y)/n

    兼具 MSE 的平滑与 L1 的抗离群（对大误差近似 |e|-log2），数值实现用
    `|e| + log1p(exp(-2|e|)) - log2` 避免 cosh 溢出。返回 (loss, grad)。
    """
    ts, ps = _numeric_pair(pred, target, "log_cosh_loss")
    n = len(ts)
    if n == 0:
        raise ValueError("log_cosh_loss: pred 不能为空")
    loss = 0.0
    grad = []
    log2 = math.log(2.0)
    for y, p in zip(ts, ps):
        e = p - y
        ae = abs(e)
        loss += ae + math.log1p(math.exp(-2.0 * ae)) - log2
        grad.append(math.tanh(e) / n)
    return loss / n, grad


def quantile_loss(pred, target, quantile: float = 0.5):
    """分位数（pinball）损失：q=0.5 就是 MAE 的一半，q>0.5 偏保守（高估代价小）

    逐元素 `max(q*e, (q-1)*e)` 的平均，其中 `e = p - y`；梯度
    `-(1-q)/n`（e<0）或 `q/n`（e>=0）。返回 (loss, grad)。
    """
    q = float(quantile)
    if not 0.0 < q < 1.0:
        raise ValueError(f"quantile_loss: quantile 必须在 (0,1) 内，收到 {quantile!r}")
    ts, ps = _numeric_pair(pred, target, "quantile_loss")
    n = len(ts)
    loss = 0.0
    grad = []
    for y, p in zip(ts, ps):
        e = p - y
        loss += q * e if e >= 0 else (q - 1.0) * e
        grad.append((q if e >= 0 else (q - 1.0)) / n)
    return loss / n, grad


def smooth_l1_loss(pred, target, delta: float = 1.0):
    """Smooth L1 = Huber 的别名（PyTorch 叫法），实现直接复用 `huber_loss`"""
    return huber_loss(pred, target, delta=delta)


def _class_counts_vector(class_counts, num_classes, who):
    """把 class_counts 规范成与类别数等长的正数列表（每类样本数）"""
    try:
        counts = [float(c) for c in class_counts]
    except TypeError:
        raise TypeError(f"{who}: class_counts 必须是每类样本数的序列，收到 {class_counts!r}")
    if len(counts) != num_classes:
        raise ValueError(
            f"{who}: class_counts 长度 {len(counts)} != 类别数 {num_classes}")
    if any(c <= 0.0 for c in counts):
        raise ValueError(f"{who}: class_counts 每项都必须 > 0（样本数），收到 {list(counts)}")
    return counts


def _class_target_weights(target_idx, num_classes, weights, who):
    """按目标算样本权重：索引/one-hot 取对应类，真软标签取 Σt·w 的加权平均

    返回 (weight, target_is_index, index_or_vector)
    """
    if isinstance(target_idx, (list, tuple)):
        if len(target_idx) != num_classes:
            raise ValueError(
                f"{who}: target 长度 {len(target_idx)} != pred 长度 {num_classes}")
        ts = [float(t) for t in target_idx]
        if any(t < 0.0 for t in ts):
            raise ValueError(f"{who}: 目标向量不能含负值")
        ssum = sum(ts)
        if ssum <= 0.0:
            raise ValueError(f"{who}: 目标向量不能全 0")
        w = sum(t * c for t, c in zip(ts, weights)) / ssum
        return w, False, ts
    idx = _ce_scalar_index(target_idx, num_classes, who)
    return weights[idx], True, idx


def class_balanced_loss(pred, target_idx, class_counts, beta: float = 0.999,
                        normalize: bool = True):
    """类别均衡损失（Cui et al. 2019）：每类权重 ∝ (1-β)/(1-β^{n_c})

    `n_c` 是类别 c 的样本数，样本越多权重越小（β→1 时退化成 1/n_c）。
    `normalize=True` 再把权重归一化到「按出现频率加权后的均值为 1」，避免整体学习率被放大。
    pred 是 softmax 概率；返回 (loss, grad)，grad 是 softmax+CE 的联合梯度（配 softmax 输出层）。
    支持类别索引与 one-hot/软标签（软标签按 Σt·w/Σt 取样本权重）。
    """
    if not isinstance(normalize, bool):
        raise TypeError(f"class_balanced_loss: normalize 必须是 bool，收到 {normalize!r}")
    beta = float(beta)
    if not 0.0 <= beta < 1.0:
        raise ValueError(f"class_balanced_loss: beta 必须在 [0,1) 内，收到 {beta!r}")
    V = len(pred)
    counts = _class_counts_vector(class_counts, V, "class_balanced_loss")
    if beta == 0.0:
        raw = [1.0] * V
    else:
        raw = [(1.0 - beta) / (1.0 - beta ** n) for n in counts]
    weights = raw
    if normalize:
        total = sum(c * w for c, w in zip(counts, raw))
        mean_w = total / sum(counts)
        if mean_w <= 0.0:
            raise ValueError("class_balanced_loss: 权重归一化失败（均值为 0）")
        weights = [w / mean_w for w in raw]
    w, is_index, tgt = _class_target_weights(target_idx, V, weights, "class_balanced_loss")
    eps = 1e-15
    if is_index:
        loss = -w * math.log(max(float(pred[tgt]), eps))
        grad = [w * float(p) for p in pred]
        grad[tgt] -= w
        return loss, grad
    ssum = sum(tgt)
    loss = -w * sum(t * math.log(max(float(p), eps)) for t, p in zip(tgt, pred))
    grad = [w * (ssum * float(p) - t) for p, t in zip(pred, tgt)]
    return loss, grad


def ldam_loss(logits, target_idx, class_counts, max_m: float = 0.5, s: float = 30.0):
    """LDAM（Cao et al. 2019）：给目标类 logit 减一个与类频率相关的间隔

        m_c = max_m / n_c^{1/4},  z' = s·(z - m_y·e_y),  loss = -log softmax(z')[y]

    `s` 是 logit 缩放（论文取 30），`max_m` 是最大间隔。**输入必须是 logits**，
    因此输出层要用 `linear`（配 softmax 会在构造时被拒绝）。返回 (loss, grad)，
    grad 相对 logits，可直接经 linear 层反传。

    放进 `Model(loss_fn='ldam')` 时必须用 `loss_kwargs={'class_counts': [...]}`
    提供每类样本数（该信息无法从 pred/target 推断）。
    """
    V = len(logits)
    counts = _class_counts_vector(class_counts, V, "ldam_loss")
    max_m = float(max_m)
    if max_m < 0.0:
        raise ValueError(f"ldam_loss: max_m 必须 >= 0，收到 {max_m!r}")
    s = float(s)
    if s <= 0.0:
        raise ValueError(f"ldam_loss: s 必须 > 0，收到 {s!r}")
    y = _ce_scalar_index(target_idx, V, "ldam_loss")
    z = [s * float(v) for v in logits]
    z[y] -= s * (max_m / counts[y] ** 0.25)
    mx = max(z)
    exps = [math.exp(v - mx) for v in z]
    total = sum(exps)
    probs = [e / total for e in exps]
    loss = -(z[y] - mx - math.log(total))
    grad = [s * (p - (1.0 if k == y else 0.0)) for k, p in enumerate(probs)]
    return loss, grad


def ohem_loss(preds, targets, keep_ratio: float = 0.7):
    """OHEM（在线难例挖掘）：只保留损失最大的那一批样本

    `preds` 是**一批**概率向量（list of list），`targets` 是等长类别索引列表；
    `keep_ratio` 是保留的「容易样本」比例 (0,1)，即丢掉最容易的 `keep_ratio` 部分、
    只对最难的前 `1-keep_ratio` 训练。返回 `(loss, grads)`：`loss` 是被选中样本的
    平均损失，`grads` 与输入同形（未选中的样本梯度全 0）。

    注意：这是**批级**接口，不能塞进 `Model(loss_fn=...)`（那是逐样本接口）；
    自定义训练循环里用它替换逐样本 CE 即可。
    """
    if not isinstance(preds, (list, tuple)) or not preds:
        raise ValueError("ohem_loss: preds 必须是非空的概率向量列表")
    if not isinstance(targets, (list, tuple)) or len(targets) != len(preds):
        raise ValueError(
            f"ohem_loss: targets 长度必须与 preds 一致，收到 {len(targets) if isinstance(targets, (list, tuple)) else targets!r}")
    kr = float(keep_ratio)
    if not 0.0 <= kr < 1.0:
        raise ValueError(f"ohem_loss: keep_ratio 必须在 [0,1) 内，收到 {keep_ratio!r}")
    n = len(preds)
    losses = []
    grads = []
    for row, tgt in zip(preds, targets):
        loss, grad = cross_entropy_loss(row, tgt)
        losses.append(loss)
        grads.append(grad)
    keep = max(1, int(round((1.0 - kr) * n)))
    order = sorted(range(n), key=lambda i: losses[i], reverse=True)[:keep]
    chosen = set(order)
    out = [(grads[i] if i in chosen else [0.0] * len(grads[i])) for i in range(n)]
    mean_loss = sum(losses[i] for i in order) / keep
    return mean_loss, out


def distill_loss(student_logits, teacher_logits, T: float = 2.0):
    """知识蒸馏（soft-target KL）：`T^2 * KL(teacher_T || student_T)`

    对学生 logits 求导得到 `T * (p_student - p_teacher)`（p 是温度为 T 时的 softmax）。
    乘以 T^2 是为了让不同温度下的梯度量级可比（Hinton 等人的做法）。

    `teacher_logits` 直接作为 `Model(loss_fn='distill')` 的 target 传入即可；
    学生的输出层必须是 `linear`（本函数吃 logits，不吃概率）。

    注意 `Model.fit` 的 target 契约：每个样本的 target 必须是长度等于输出维度的
    teacher logits 向量；传普通类别索引（标量/长度 1）会在第一批就报错，请改用
    `loss_fn='cross_entropy'` 或自定义训练循环。
    """
    if not isinstance(T, (int, float)) or isinstance(T, bool) or not (T > 0.0):
        raise ValueError(f"distill_loss: T 必须是 > 0 的数字，收到 {T!r}")
    if not (T == T and T != float("inf")):
        raise ValueError("distill_loss: T 必须是有限数字")
    tgt, stud = _numeric_pair(student_logits, teacher_logits, "distill_loss")
    ps = _softmax_with_temp(stud, float(T))
    pt = _softmax_with_temp(tgt, float(T))
    loss = 0.0
    for a, b in zip(ps, pt):
        if b > 0.0:
            loss += b * math.log(b / max(a, 1e-300))
    loss *= T * T
    grad = [T * (a - b) for a, b in zip(ps, pt)]
    return loss, grad


def hint_loss(student_feat, teacher_feat, weight: float = 1.0):
    """隐藏层对齐（hint）：学生特征与教师特征的均方误差

    用于 FitNet 式的中间层蒸馏；两层维度必须一致（需要投影时自己套一层 `Layer`）。
    返回 `(loss, grad)`，`grad` 相对 `student_feat`；`weight` 用来调节与主损失的配比。
    """
    if not isinstance(weight, (int, float)) or isinstance(weight, bool):
        raise TypeError(f"hint_loss: weight 必须是数字，收到 {weight!r}")
    if not (weight >= 0.0 and weight == weight and weight != float("inf")):
        raise ValueError(f"hint_loss: weight 必须是非负有限数字，收到 {weight!r}")
    tgt, stud = _numeric_pair(student_feat, teacher_feat, "hint_loss")
    n = len(stud)
    if n == 0:
        raise ValueError("hint_loss: 特征不能为空")
    total = 0.0
    for a, b in zip(stud, tgt):
        d = a - b
        total += d * d
    loss = weight * total / n
    grad = [weight * 2.0 * (a - b) / n for a, b in zip(stud, tgt)]
    return loss, grad


def _pref_number(v, name, who):
    """偏好对齐损失的标量参数校验（拒绝 bool / 非有限 / NaN）。"""
    if not isinstance(v, (int, float)) or isinstance(v, bool):
        raise TypeError(f"{who}: {name} 必须是数字，收到 {v!r}")
    fv = float(v)
    if not (fv == fv) or fv in (float("inf"), float("-inf")):
        raise ValueError(f"{who}: {name} 必须是有限数字，收到 {v!r}")
    return fv


def _log_sigmoid(x):
    """数值稳定的 `log σ(x)`。"""
    if x >= 0.0:
        return -math.log1p(math.exp(-x))
    return x - math.log1p(math.exp(x))


def _sigmoid(x):
    """数值稳定的 sigmoid（避免 `exp` 溢出）。"""
    if x >= 0.0:
        return 1.0 / (1.0 + math.exp(-x))
    e = math.exp(x)
    return e / (1.0 + e)


def _logit_odds(logp):
    """把 log 概率换成「logit」：`log(p/(1-p))`，用于 ORPO。"""
    if not (logp < 0.0):
        raise ValueError(f"preference_loss: ORPO 需要 log 概率 < 0，收到 {logp!r}")
    p = math.exp(logp)
    return logp - math.log1p(-p)


def preference_loss(chosen_logp, rejected_logp, ref_chosen_logp=None,
                    ref_rejected_logp=None, method: str = "dpo",
                    beta: float = 0.1, margin: float = 0.0,
                    sft_weight: float = 0.1):
    """偏好对齐损失：给定「好回答/坏回答」的对数概率，返回 `(loss, d_chosen, d_rejected)`

    支持五种方法（`method`）：

    - `'dpo'`：`-log σ(β(Δ − Δ_ref))`，`Δ = log π(c) − log π(r)`（需要参考模型的 logp）
    - `'ipo'`：`(Δ − Δ_ref − 1/(2β))²`，把偏好差直接回归到目标间隔
    - `'simpo'`：`-log σ(β·Δ − margin)`，不需要参考模型（SimPO 的卖点）
    - `'cpo'`：DPO 项 + `sft_weight · (−log π(c))`，一个损失里同时做对齐与 SFT
    - `'orpo'`：`-log σ(β·(logit π(c) − logit π(r)))`，在 logit 空间比较优势

    梯度是标量，分别相对 `chosen_logp` 与 `rejected_logp`（可以直接乘到序列的
    log-prob 梯度上）。`β>0`、`margin>=0`；只有 `'simpo'` / `'orpo'` 不需要 `ref_*`。
    """
    who = "preference_loss"
    if not isinstance(method, str):
        raise TypeError(f"{who}: method 必须是字符串，收到 {method!r}")
    m = method.strip().lower()
    if m not in ("dpo", "ipo", "simpo", "cpo", "orpo"):
        raise ValueError(f"{who}: method 必须是 dpo/ipo/simpo/cpo/orpo 之一，收到 {method!r}")
    beta = _pref_number(beta, "beta", who)
    margin = _pref_number(margin, "margin", who)
    sft_weight = _pref_number(sft_weight, "sft_weight", who)
    if not (beta > 0.0):
        raise ValueError(f"{who}: beta 必须 > 0，收到 {beta!r}")
    if margin < 0.0:
        raise ValueError(f"{who}: margin 必须 >= 0，收到 {margin!r}")
    if sft_weight < 0.0:
        raise ValueError(f"{who}: sft_weight 必须 >= 0，收到 {sft_weight!r}")
    c = _pref_number(chosen_logp, "chosen_logp", who)
    r = _pref_number(rejected_logp, "rejected_logp", who)

    needs_ref = m in ("dpo", "ipo", "cpo")
    if needs_ref:
        if ref_chosen_logp is None or ref_rejected_logp is None:
            raise ValueError(f"{who}: method={m!r} 需要 ref_chosen_logp 与 ref_rejected_logp")
        rc = _pref_number(ref_chosen_logp, "ref_chosen_logp", who)
        rr = _pref_number(ref_rejected_logp, "ref_rejected_logp", who)
    else:
        rc = rr = 0.0

    delta = c - r
    if m == "dpo":
        x = beta * (delta - (rc - rr))
        loss = -_log_sigmoid(x)
        d_delta = beta * (_sigmoid(x) - 1.0)
        dc, dr = d_delta, -d_delta
    elif m == "ipo":
        target = 1.0 / (2.0 * beta)
        gap = delta - (rc - rr) - target
        loss = gap * gap
        d_delta = 2.0 * gap
        dc, dr = d_delta, -d_delta
    elif m == "simpo":
        x = beta * delta - margin
        loss = -_log_sigmoid(x)
        d_delta = beta * (_sigmoid(x) - 1.0)
        dc, dr = d_delta, -d_delta
    elif m == "orpo":
        gap = _logit_odds(c) - _logit_odds(r)
        x = beta * gap
        loss = -_log_sigmoid(x)
        d_x = _sigmoid(x) - 1.0
        # d logit_odds / d logp = 1 + p/(1-p)
        dc = beta * d_x * (1.0 + math.exp(c) / (1.0 - math.exp(c)))
        dr = -beta * d_x * (1.0 + math.exp(r) / (1.0 - math.exp(r)))
    else:  # cpo
        x = beta * (delta - (rc - rr))
        loss = -_log_sigmoid(x) + sft_weight * (-c)
        d_delta = beta * (_sigmoid(x) - 1.0)
        dc, dr = d_delta - sft_weight, -d_delta
    return loss, dc, dr


def kto_loss(logp, ref_logp, desirable: bool = True, beta: float = 0.1,
             baseline: float = 0.0):
    """KTO（Kahneman-Tversky 优化）：单条回答的二分类式对齐

    `desirable=True` 时 `loss = 1 − σ(β(z − baseline))`，`False` 时
    `loss = 1 − σ(β(baseline − z))`，其中 `z = log π − log π_ref`。
    返回 `(loss, d_logp)`；`baseline` 通常取「参考模型下的平均 KL」的估计值，
    教学实现里默认为 0。
    """
    who = "kto_loss"
    beta = _pref_number(beta, "beta", who)
    baseline = _pref_number(baseline, "baseline", who)
    if not (beta > 0.0):
        raise ValueError(f"{who}: beta 必须 > 0，收到 {beta!r}")
    if not isinstance(desirable, bool):
        raise TypeError(f"{who}: desirable 必须是 bool，收到 {desirable!r}")
    z = _pref_number(logp, "logp", who) - _pref_number(ref_logp, "ref_logp", who)

    if desirable:
        u = beta * (z - baseline)
    else:
        u = beta * (baseline - z)
    sig = _sigmoid(u)
    loss = 1.0 - sig
    # d(1 - σ(u))/du = -σ(u)(1-σ(u))
    du = -sig * (1.0 - sig)
    d_logp = du * beta if desirable else -du * beta
    return loss, d_logp


def _mt_vector(values, name, who):
    """多任务权重工具的公共入参校验：非空、每个元素是有限数字（bool 不算）。"""
    if not isinstance(values, (list, tuple)) or not values:
        raise ValueError(f"{who}: {name} 必须是非空序列")
    out = []
    for i, v in enumerate(values):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise TypeError(f"{who}: {name}[{i}] 必须是数字，收到 {type(v).__name__}")
        f = float(v)
        if not (f == f and -float("inf") < f < float("inf")):
            raise ValueError(f"{who}: {name}[{i}] 必须是有限数，收到 {f!r}")
        out.append(f)
    return out


def uncertainty_weighting(losses, log_vars):
    """Kendall 等人的多任务不确定性加权。

    ``L = Σ_i exp(-s_i)·L_i + s_i``，其中 ``s_i = log_vars[i]`` 是任务 i 的
    对数方差（可学习参数）。返回 ``(total, weights, d_losses, d_log_vars)``：
    ``weights[i] = exp(-s_i)``，``d_losses[i] = exp(-s_i)``，
    ``d_log_vars[i] = 1 - exp(-s_i)·L_i``。
    """
    ls = _mt_vector(losses, "losses", "uncertainty_weighting")
    ss = _mt_vector(log_vars, "log_vars", "uncertainty_weighting")
    if len(ls) != len(ss):
        raise ValueError(
            f"uncertainty_weighting: losses 长度 {len(ls)} 与 log_vars 长度 {len(ss)} 不一致"
        )
    weights = []
    total = 0.0
    for li, si in zip(ls, ss):
        w = math.exp(-si)
        weights.append(w)
        total += w * li + si
    d_losses = list(weights)
    d_log_vars = [1.0 - w * li for w, li in zip(weights, ls)]
    return total, weights, d_losses, d_log_vars


def gradnorm_weights(losses, grad_norms, alpha=1.5, lr=0.025,
                     weights=None, G0=None):
    """GradNorm 的一步权重更新（纯函数、无状态）。

    ``r_i = (L_i / mean(L))^alpha``、``Ḡ = mean(G_i)``，
    目标 ``target_i = Ḡ·r_i``；损失 ``L1 = Σ|G_i − target_i|``。
    ``G0`` 是参考尺度（缺省用当前 ``Ḡ``），
    权重更新 ``w_i −= lr·sign(G_i − target_i)·G0/r_i``，并归一化到均值为 1。

    返回 ``{"weights", "targets", "loss", "gradients"}``（都是 list）。
    """
    ls = _mt_vector(losses, "losses", "gradnorm_weights")
    gs = _mt_vector(grad_norms, "grad_norms", "gradnorm_weights")
    if len(ls) != len(gs):
        raise ValueError(
            f"gradnorm_weights: losses 长度 {len(ls)} 与 grad_norms 长度 {len(gs)} 不一致"
        )
    if isinstance(alpha, bool) or not isinstance(alpha, (int, float)):
        raise TypeError("gradnorm_weights: alpha 必须是数字")
    if not (alpha > 0):
        raise ValueError(f"gradnorm_weights: alpha 必须 > 0，收到 {alpha!r}")
    if isinstance(lr, bool) or not isinstance(lr, (int, float)):
        raise TypeError("gradnorm_weights: lr 必须是数字")
    if not (lr > 0):
        raise ValueError(f"gradnorm_weights: lr 必须 > 0，收到 {lr!r}")
    for x in ls:
        if x <= 0.0:
            raise ValueError(f"gradnorm_weights: losses 必须全为正，收到 {x!r}")

    if weights is None:
        ws = [1.0] * len(ls)
    else:
        ws = _mt_vector(weights, "weights", "gradnorm_weights")
        if len(ws) != len(ls):
            raise ValueError(
                f"gradnorm_weights: weights 长度 {len(ws)} 与 losses 长度 {len(ls)} 不一致"
            )
        for x in ws:
            if x <= 0.0:
                raise ValueError(f"gradnorm_weights: weights 必须全为正，收到 {x!r}")

    mean_l = sum(ls) / len(ls)
    mean_g = sum(gs) / len(gs)
    ref = mean_g if G0 is None else float(G0)
    if isinstance(G0, bool) or (G0 is not None and not isinstance(G0, (int, float))):
        raise TypeError("gradnorm_weights: G0 必须是数字或 None")
    if ref <= 0.0:
        raise ValueError(f"gradnorm_weights: G0 必须 > 0，收到 {ref!r}")

    ratios = [(li / mean_l) ** float(alpha) for li in ls]
    targets = [mean_g * r for r in ratios]
    loss = 0.0
    for gi, ti in zip(gs, targets):
        loss += abs(gi - ti)
    gradients = []
    new_w = []
    for wi, gi, ti, r in zip(ws, gs, targets, ratios):
        diff = gi - ti
        sign = 0.0 if diff == 0.0 else (1.0 if diff > 0.0 else -1.0)
        grad = sign * ref / r
        gradients.append(grad)
        new_w.append(wi - float(lr) * grad)
    # 归一化到均值为 1（保持整体尺度，免得学习率被间接改变）
    lo = min(new_w)
    if lo <= 0.0:
        shift = 1.0 - lo
        new_w = [w + shift for w in new_w]
    m = sum(new_w) / len(new_w)
    new_w = [w / m for w in new_w]
    return {"weights": new_w, "targets": targets, "loss": loss, "gradients": gradients}


def _flat_dot(a, b):
    if isinstance(a, (list, tuple)):
        if not isinstance(b, (list, tuple)) or len(a) != len(b):
            raise ValueError("pcgrad: 两个梯度的结构不一致")
        return sum(_flat_dot(x, y) for x, y in zip(a, b))
    if isinstance(a, bool) or not isinstance(a, (int, float)):
        raise TypeError("pcgrad: 梯度里只能是数字或数字列表")
    return float(a) * float(b)


def _flat_sub(a, b):
    if isinstance(a, (list, tuple)):
        return [_flat_sub(x, y) for x, y in zip(a, b)]
    return float(a) - float(b)


def _flat_scale(a, k):
    if isinstance(a, (list, tuple)):
        return [_flat_scale(x, k) for x in a]
    return float(a) * k


def pcgrad(grad_a, grad_b, eps=1e-12):
    """PCGrad：两个任务梯度冲突（内积 < 0）时互相投影掉冲突分量。

    返回 ``(grad_a_projected, grad_b_projected)``；不冲突时原样返回副本。
    梯度用「数字的嵌套 list」表示（与 ``Model.backward`` 的返回同构）。
    """
    if isinstance(eps, bool) or not isinstance(eps, (int, float)):
        raise TypeError("pcgrad: eps 必须是数字")
    if not (eps > 0):
        raise ValueError(f"pcgrad: eps 必须 > 0，收到 {eps!r}")
    dot_ab = _flat_dot(grad_a, grad_b)
    ga = [_flat_scale(x, 1.0) for x in grad_a] if isinstance(grad_a, list) else grad_a
    gb = [_flat_scale(x, 1.0) for x in grad_b] if isinstance(grad_b, list) else grad_b
    if dot_ab < 0.0:
        n_b = _flat_dot(grad_b, grad_b)
        n_a = _flat_dot(grad_a, grad_a)
        if n_b > eps:
            coef_a = dot_ab / n_b
            ga = _flat_sub(grad_a, _flat_scale(grad_b, coef_a))
        if n_a > eps:
            coef_b = dot_ab / n_a
            gb = _flat_sub(grad_b, _flat_scale(grad_a, coef_b))
    return ga, gb


def mse_loss(pred: List[float], target):
    """MSE 损失 + 对 pred 的梯度

    target 可以是序列，也可以是单个标量（单输出回归传 y=0.5 也行，
    与 Model._wrap_loss 的行为保持一致）。
    """
    if not isinstance(target, (list, tuple)):
        target = [target]
    if len(pred) == 0:
        raise ValueError("mse_loss: pred 不能为空")
    if len(pred) != len(target):
        # 不能靠 zip 静默截断：分母用的是 len(pred)，截断后会得到一个"看起来正常"的错值
        raise ValueError(
            f"mse_loss: pred 长度 {len(pred)} != target 长度 {len(target)}，"
            f"请对齐维度（单输出回归请传 y=[value]，多输出请传 y=[v1, v2, ...]）"
        )
    n = len(pred)
    # NaN 输入显式报错（±Inf 放行，平方后溢出成 inf 是可见的 IEEE 行为）
    for i in range(n):
        if float(pred[i]) != float(pred[i]):
            raise ValueError("mse_loss: pred 第 %d 个值是 NaN" % i)
        if float(target[i]) != float(target[i]):
            raise ValueError("mse_loss: target 第 %d 个值是 NaN" % i)
    # 用乘法而不是 `** 2`：CPython 的 float pow 在 |差值| >~1.34e154 时会抛
    # OverflowError（而 mse_loss([1e308],[-1e308]) 又返回 inf，行为不一致）；
    # 乘法按 IEEE 溢出成 inf，语义统一
    diffs = [p - t for p, t in zip(pred, target)]
    loss = sum(d * d for d in diffs) / n
    grad = [2 * d / n for d in diffs]
    return loss, grad


def cross_entropy_loss(pred: List[float], target_idx, label_smoothing: float = 0.0):
    """
    pred: softmax 输出 (概率分布)
    target_idx: 正确类别的索引 (int)，或 one-hot / 概率向量 (list)

    两种目标都支持：
        索引     -> loss = -log(pred[idx])，梯度 = pred - one_hot(idx)
        向量     -> loss = -Σ t·log(pred)，梯度 = pred - t
    后者用于 TextProcessor.prepare_data 产出的 one-hot 标签。

    label_smoothing > 0 时把目标分布软化成
        q = (1-ε)·target + ε/K        （K = 类别数）
    loss = -Σ q·log(pred)，梯度 = pred·Σq - q。
    ε 取值 (0,1)；默认 0 时走原来的精确路径（逐位不变）。
    """
    eps = 1e-15
    if label_smoothing:
        return _cross_entropy_smoothed(pred, target_idx, label_smoothing, eps)
    if isinstance(target_idx, (list, tuple)):
        if len(target_idx) != len(pred):
            raise ValueError(
                f"cross_entropy_loss: target 长度 {len(target_idx)} != pred 长度 {len(pred)}，"
                f"请对齐维度"
            )
        if any(float(t) < 0.0 for t in target_idx):
            raise ValueError("cross_entropy_loss: 目标向量不能含负值")
        # softmax+CE 对任意非负软标签的联合梯度是 s*p - t（s = Σt）。
        # 只在 Σt == 1 时才退化成 p - t；全 0 目标应得到全 0 梯度，
        # 原先写成 p - t 会让 loss=0 却有非零梯度。
        ssum = sum(float(t) for t in target_idx)
        loss = -sum(float(t) * math.log(max(float(p), eps))
                    for t, p in zip(target_idx, pred))
        grad = [ssum * float(p) - float(t) for p, t in zip(pred, target_idx)]
        return loss, grad
    # bool 是 int 的子类，会静默变成索引 0/1
    if isinstance(target_idx, bool):
        raise TypeError(f"cross_entropy_loss: 类别索引不能是 bool，收到 {target_idx!r}")
    if isinstance(target_idx, float):
        if not target_idx.is_integer():
            raise ValueError(f"cross_entropy_loss: 类别索引必须是整数，收到 {target_idx}")
        target_idx = int(target_idx)
    if not isinstance(target_idx, int):
        try:
            target_idx = operator.index(target_idx)
        except TypeError:
            raise TypeError(
                f"cross_entropy_loss: 目标必须是类别索引或向量，收到 {target_idx!r}"
            )
    # 负数索引在 Python 里会回绕成最后一个类，必须拦掉
    if not 0 <= target_idx < len(pred):
        raise ValueError(
            f"cross_entropy_loss: 类别索引 {target_idx} 越界（pred 长度 {len(pred)}）"
        )
    p = max(pred[target_idx], eps)
    loss = -math.log(p)
    # softmax + CE 的梯度 = pred - one_hot(target)
    grad = list(pred)
    grad[target_idx] -= 1.0
    return loss, grad


def _ce_scalar_index(target, n, who="cross_entropy_loss"):
    """把标量目标规范成合法类别索引（bool / 非整数 float / 越界都拒绝）"""
    if isinstance(target, bool):
        raise TypeError(f"{who}: 类别索引不能是 bool，收到 {target!r}")
    if isinstance(target, float):
        if not target.is_integer():
            raise ValueError(f"{who}: 类别索引必须是整数，收到 {target}")
        target = int(target)
    if not isinstance(target, int):
        try:
            target = operator.index(target)
        except TypeError:
            raise TypeError(f"{who}: 目标必须是类别索引，收到 {target!r}")
    if not 0 <= target < n:
        raise ValueError(f"{who}: 类别索引 {target} 越界（pred 长度 {n}）")
    return target


def _cross_entropy_smoothed(pred, target, smoothing, eps):
    """cross_entropy_loss 的 label_smoothing 分支（目标分布 q 见调用处文档）"""
    if not 0.0 < float(smoothing) < 1.0:
        raise ValueError(
            f"cross_entropy_loss: label_smoothing 必须在 (0,1)，收到 {smoothing!r}")
    k = len(pred)
    if isinstance(target, (list, tuple)):
        if len(target) != k:
            raise ValueError(
                f"cross_entropy_loss: target 长度 {len(target)} != pred 长度 {k}，"
                f"请对齐维度"
            )
        if any(float(t) < 0.0 for t in target):
            raise ValueError("cross_entropy_loss: 目标向量不能含负值")
        ts = [float(t) for t in target]
    else:
        idx = _ce_scalar_index(target, k)
        ts = [0.0] * k
        ts[idx] = 1.0
    uniform = float(smoothing) / k
    q = [(1.0 - float(smoothing)) * t + uniform for t in ts]
    loss = -sum(qi * math.log(max(float(p), eps)) for qi, p in zip(q, pred))
    ssum = sum(q)
    grad = [ssum * float(p) - qi for p, qi in zip(pred, q)]
    return loss, grad


def focal_loss(pred: List[float], target_idx, gamma: float = 2.0, alpha=None):
    """Focal Loss：FL = -α_t·(1-p_t)^γ·log(p_t)

    针对类别不平衡：易分样本（p_t 接近 1）的 (1-p_t)^γ 会把它的梯度压小，
    训练集中到难样本上。pred 是 softmax 概率，target 只支持类别索引
    （软标签下 focal 的定义不唯一）。alpha 可为标量或逐类列表（None=1）。

    返回 (loss, grad)，grad 已含 softmax 与 focal 的联合求导，可直接喂给
    `_softmax_deriv`（返回 1.0）那一层的 backward。
    """
    if gamma is None or gamma < 0:
        raise ValueError(f"focal_loss: gamma 必须 >= 0，收到 {gamma!r}")
    k = len(pred)
    idx = _ce_scalar_index(target_idx, k, "focal_loss")
    if isinstance(alpha, (list, tuple)):
        if len(alpha) != k:
            raise ValueError(
                f"focal_loss: alpha 长度 {len(alpha)} != pred 长度 {k}")
        a_t = float(alpha[idx])
    else:
        a_t = 1.0 if alpha is None else float(alpha)
    p = min(max(float(pred[idx]), 1e-15), 1.0)
    rest = 1.0 - p
    log_p = math.log(p)
    if rest <= 0.0:
        # p_t 恰为 1：loss 与梯度都是 0（γ>0 时）
        return 0.0, [0.0] * k
    p_gamma = rest ** gamma
    loss = -a_t * p_gamma * log_p
    # dz_j = A·(δ_tj - p_j)，A = α·[γ·p_t·(1-p_t)^(γ-1)·log(p_t) - (1-p_t)^γ]
    term = gamma * p * (rest ** (gamma - 1.0)) * log_p if gamma > 0 else 0.0
    a = a_t * (term - p_gamma)
    grad = [-a * float(pj) for pj in pred]
    grad[idx] += a
    return loss, grad


def bce_loss(pred, target, eps: float = 1e-12):
    """二元交叉熵（pred 是概率，通常来自 output 层的 sigmoid 激活）

    target 可为 0/1 标量，或与 pred 等长的 0/1 列表。
    loss 取逐元素平均；返回 (loss, grad)，grad 相对 pred
    （Layer 的 sigmoid 导数会再乘上去，所以对 logits 的梯度是对的）。

    注意：pred 越接近 0 或 1，梯度越大（数学上无界，量级约 1/eps）。
    pred 落在端点时会被 clamp 到 eps / 1-eps，此时梯度量级为 1/eps（默认 1e12）。
    这是 BCE 本身的数学性质（PyTorch 同样如此），需要数值稳定时请改用
    ``bce_with_logits_loss``，或显式传更大的 eps。
    """
    if isinstance(target, (list, tuple)):
        if len(target) != len(pred):
            raise ValueError(
                f"bce_loss: target 长度 {len(target)} != pred 长度 {len(pred)}")
        ts, ps = [float(t) for t in target], [float(p) for p in pred]
    else:
        ts, ps = [float(target)], [float(p) for p in pred]
        if len(ps) != 1:
            raise ValueError(
                f"bce_loss: 标量 target 只能配单个输出，pred 长度是 {len(ps)}；"
                f"多输出请传等长列表")
    n = len(ts)
    loss = 0.0
    grad = []
    for y, p in zip(ts, ps):
        if not 0.0 <= p <= 1.0:
            raise ValueError(f"bce_loss: pred 必须是概率 [0,1]，收到 {p}")
        q = min(max(p, eps), 1.0 - eps)
        loss += -(y * math.log(q) + (1.0 - y) * math.log(1.0 - q))
        grad.append((q - y) / (q * (1.0 - q)) / n)
    return loss / n, grad


def bce_with_logits_loss(logits, target):
    """带 logits 的二元交叉熵（数值稳定，内部做 sigmoid）

    loss = max(z,0) - z·y + log(1+exp(-|z|))，返回 (loss, grad)，grad 相对 logits
    （= sigmoid(z) - y）。target 规则同 bce_loss。
    """
    if isinstance(target, (list, tuple)):
        if len(target) != len(logits):
            raise ValueError(
                f"bce_with_logits_loss: target 长度 {len(target)} != logits 长度 {len(logits)}")
        ts, zs = [float(t) for t in target], [float(z) for z in logits]
    else:
        ts, zs = [float(target)], [float(z) for z in logits]
        if len(zs) != 1:
            raise ValueError(
                f"bce_with_logits_loss: 标量 target 只能配单个输出，logits 长度是 {len(zs)}")
    n = len(ts)
    loss = 0.0
    grad = []
    for y, z in zip(ts, zs):
        loss += max(z, 0.0) - z * y + math.log1p(math.exp(-abs(z)))
        if z >= 0:
            s = 1.0 / (1.0 + math.exp(-z))
        else:
            e = math.exp(z)
            s = e / (1.0 + e)
        grad.append((s - y) / n)
    return loss / n, grad


def huber_loss(pred, target, delta: float = 1.0):
    """Huber 损失（Smooth L1）：|e|<=delta 用 0.5e²，否则 delta(|e|-0.5delta)

    对离群点比 MSE 稳、对小误差比 MAE 光滑。target 可为标量或等长列表，
    loss 取逐元素平均；返回 (loss, grad)，grad 相对 pred。
    """
    if delta is None or delta <= 0:
        raise ValueError(f"huber_loss: delta 必须 > 0，收到 {delta!r}")
    if isinstance(target, (list, tuple)):
        if len(target) != len(pred):
            raise ValueError(
                f"huber_loss: target 长度 {len(target)} != pred 长度 {len(pred)}")
        ts, ps = [float(t) for t in target], [float(p) for p in pred]
    else:
        ts, ps = [float(target)], [float(p) for p in pred]
        if len(ps) != 1:
            raise ValueError(
                f"huber_loss: 标量 target 只能配单个输出，pred 长度是 {len(ps)}")
    n = len(ts)
    loss = 0.0
    grad = []
    for y, p in zip(ts, ps):
        e = p - y
        if abs(e) <= delta:
            loss += 0.5 * e * e
            grad.append(e / n)
        else:
            loss += delta * (abs(e) - 0.5 * delta)
            grad.append((delta if e > 0 else -delta) / n)
    return loss / n, grad


def kl_divergence(pred, target, eps: float = 1e-12):
    """KL(target ‖ pred) = Σ t·log(t/p)

    pred 是模型输出的概率分布，target 是目标分布（不要求归一化）。
    返回 (loss, grad)，grad 相对 pred（= -t/p）。

    注意：p→0 且 t>0 时梯度无界（量级约 -t/eps，默认 1e12），这是 KL 的
    数学性质，与 PyTorch 一致；需要数值稳定时请改用
    ``bce_with_logits_loss`` 这类自带 log-sum-exp 的稳定形式，
    或显式传更大的 eps。
    """
    if len(target) != len(pred):
        raise ValueError(
            f"kl_divergence: target 长度 {len(target)} != pred 长度 {len(pred)}")
    loss = 0.0
    grad = []
    for t, p in zip(target, pred):
        t, p = float(t), float(p)
        if t < 0.0:
            raise ValueError("kl_divergence: target 不能含负值")
        q = max(p, eps)
        if t > 0.0:
            loss += t * (math.log(t) - math.log(q))
        grad.append(-t / q)
    return loss, grad


def _loss_vector(v, name, who):
    """校验一维数字序列（拒绝 bool / NaN / Inf / 空）"""
    if not isinstance(v, (list, tuple)):
        raise TypeError(f"{who}: {name} 必须是序列，收到 {type(v).__name__}")
    out = []
    for x in v:
        if isinstance(x, bool) or not isinstance(x, (int, float)):
            raise TypeError(f"{who}: {name} 只能含数字，收到 {x!r}")
        x = float(x)
        if x != x or x in (float("inf"), float("-inf")):
            raise ValueError(f"{who}: {name} 不能含 NaN/Inf")
        out.append(x)
    if not out:
        raise ValueError(f"{who}: {name} 不能为空")
    return out


def _loss_norm(x):
    return math.sqrt(sum(v * v for v in x))


def triplet_loss(anchor, positive, negative, margin: float = 1.0):
    """Triplet 损失：max(0, d(a,p) - d(a,n) + margin)，d 为欧氏距离

    返回 (loss, d_anchor, d_positive, d_negative)，三个梯度都相对输入向量。
    margin 必须 > 0：等于 0 时正负样本距离相等就没有梯度，等于静默失效。
    已满足间隔时 loss 为 0、三个梯度全 0。
    """
    who = "triplet_loss"
    a = _loss_vector(anchor, "anchor", who)
    p = _loss_vector(positive, "positive", who)
    n = _loss_vector(negative, "negative", who)
    if not (len(a) == len(p) == len(n)):
        raise ValueError(f"{who}: 三个向量长度必须相同，收到 {len(a)}/{len(p)}/{len(n)}")
    margin = float(margin)
    if margin <= 0.0:
        raise ValueError(f"{who}: margin 必须 > 0，收到 {margin!r}")

    dap = _loss_norm([a[i] - p[i] for i in range(len(a))])
    dan = _loss_norm([a[i] - n[i] for i in range(len(a))])
    loss = dap - dan + margin
    if loss <= 0.0:
        zeros = [0.0] * len(a)
        return 0.0, list(zeros), list(zeros), list(zeros)

    d_anchor = [0.0] * len(a)
    d_positive = [0.0] * len(a)
    d_negative = [0.0] * len(a)
    for i in range(len(a)):
        d_anchor[i] = (a[i] - p[i]) / dap - (a[i] - n[i]) / dan
        d_positive[i] = -(a[i] - p[i]) / dap
        d_negative[i] = (a[i] - n[i]) / dan
    return loss, d_anchor, d_positive, d_negative


def info_nce_loss(anchor, positive, negatives, temperature: float = 0.07):
    """InfoNCE 对比损失：正样本 1 个 + 负样本若干

    相似度用归一化点积（余弦），loss = -log( exp(s_pos/τ) / Σ_j exp(s_j/τ) )，
    j 遍历 [positive] + negatives。
    返回 (loss, d_anchor, d_positive, d_negatives)。
    """
    who = "info_nce_loss"
    a = _loss_vector(anchor, "anchor", who)
    if not isinstance(negatives, (list, tuple)) or not negatives:
        raise ValueError(f"{who}: negatives 必须是非空序列")
    cands = [_loss_vector(positive, "positive", who)]
    for k, neg in enumerate(negatives):
        cands.append(_loss_vector(neg, f"negatives[{k}]", who))
    for k, c in enumerate(cands):
        if len(c) != len(a):
            raise ValueError(f"{who}: 第 {k} 个候选长度 {len(c)} != anchor 长度 {len(a)}")
    temperature = float(temperature)
    if temperature <= 0.0:
        raise ValueError(f"{who}: temperature 必须 > 0，收到 {temperature!r}")

    a_norm = _loss_norm(a)
    if a_norm == 0.0:
        raise ValueError(f"{who}: anchor 不能是零向量")
    c_norms = [_loss_norm(c) for c in cands]
    for k, cw in enumerate(c_norms):
        if cw == 0.0:
            raise ValueError(f"{who}: 第 {k} 个候选不能是零向量")

    sims = [sum(map(_mul, a, c)) / (a_norm * c_norms[k]) / temperature
            for k, c in enumerate(cands)]
    mx = max(sims)
    exps = [math.exp(v - mx) for v in sims]
    total = sum(exps)
    loss = -(sims[0] - mx - math.log(total))

    probs = [e / total for e in exps]
    d_anchor = [0.0] * len(a)
    d_cands = [[0.0] * len(c) for c in cands]
    for j, c in enumerate(cands):
        coeff = probs[j] - (1.0 if j == 0 else 0.0)
        if coeff == 0.0:
            continue
        inv_t = 1.0 / temperature
        for i in range(len(a)):
            d_anchor[i] += coeff * (inv_t * c[i] / (a_norm * c_norms[j])
                                    - sims[j] * a[i] / (a_norm * a_norm))
        for i in range(len(c)):
            d_cands[j][i] += coeff * (inv_t * a[i] / (a_norm * c_norms[j])
                                      - sims[j] * c[i] / (c_norms[j] ** 2))
    d_pos = d_cands[0]
    d_negs = d_cands[1:]
    return loss, d_anchor, d_pos, d_negs


def _loss_flatten(x, who):
    """把嵌套 list 摊平，返回 (flat, shape)；顺带校验形状一致与数值有限"""
    shape = []
    cur = x
    while isinstance(cur, (list, tuple)):
        shape.append(len(cur))
        if not cur:
            break
        cur = cur[0]
    flat = []

    def walk(v, depth):
        if depth == len(shape):
            if isinstance(v, (list, tuple)):
                raise ValueError(f"{who}: 嵌套层数不一致")
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError(f"{who}: 只能含数字，收到 {v!r}")
            v = float(v)
            if v != v or v in (float("inf"), float("-inf")):
                raise ValueError(f"{who}: 不能含 NaN/Inf")
            flat.append(v)
            return
        if not isinstance(v, (list, tuple)):
            raise ValueError(f"{who}: 嵌套层数不一致")
        if len(v) != shape[depth]:
            raise ValueError(f"{who}: 第 {depth} 维长度不一致（{len(v)} != {shape[depth]}）")
        for item in v:
            walk(item, depth + 1)

    walk(x, 0)
    return flat, tuple(shape)


def _loss_unflatten(flat, shape):
    if not shape:
        return flat[0]
    if len(shape) == 1:
        return list(flat)
    step = len(flat) // shape[0]
    return [_loss_unflatten(flat[i * step:(i + 1) * step], shape[1:]) for i in range(shape[0])]


def dice_loss(pred, target, eps: float = 1e-6):
    """Dice 损失（分割）：1 - (2|p∩t| + eps') / (|p| + |t| + eps')

    pred 是概率（0~1），target 是 0/1 掩码，形状需一致（(C,H,W) 或扁平列表均可）。
    返回 (loss, grad)，grad 相对 pred。全局 Dice（不是逐类平均）。
    """
    who = "dice_loss"
    flat_p, shape_p = _loss_flatten(pred, who)
    flat_t, shape_t = _loss_flatten(target, who)
    if shape_p != shape_t:
        raise ValueError(f"{who}: pred 形状 {shape_p} 与 target 形状 {shape_t} 不一致")
    if not flat_p:
        raise ValueError(f"{who}: 输入不能为空")
    eps = float(eps)
    if eps <= 0.0:
        raise ValueError(f"{who}: eps 必须 > 0，收到 {eps!r}")

    num = 2.0 * sum(p * t for p, t in zip(flat_p, flat_t))
    den = sum(flat_p) + sum(flat_t) + eps
    loss = 1.0 - num / den
    grad_flat = [-2.0 * t / den + num / (den * den) for t in flat_t]
    return loss, _loss_unflatten(grad_flat, shape_p)


def ctc_loss(log_probs, targets, blank: int = 0):
    """CTC 损失（单样本，log 空间前向后向）

    log_probs: (T, K) 的 log 概率（softmax 之后取 log）
    targets: 目标标签序列（不含 blank）
    返回 (loss, grad)，grad 相对 log_probs，形状 (T, K)。

    用 log-sum-exp 累加，长序列不会下溢；不可达的标签序列直接报错。
    """
    who = "ctc_loss"
    flat_lp, shape = _loss_flatten(log_probs, who)
    if len(shape) != 2:
        raise ValueError(f"{who}: log_probs 必须是 (T, K) 二维结构，收到形状 {shape}")
    T, K = shape
    if T <= 0 or K <= 0:
        raise ValueError(f"{who}: log_probs 不能有空维度（{T}×{K}）")
    if isinstance(blank, bool) or not isinstance(blank, int) or not 0 <= blank < K:
        raise ValueError(f"{who}: blank 必须是 [0, {K}) 的整数，收到 {blank!r}")
    if isinstance(targets, (int, float, str)) or not isinstance(targets, (list, tuple)):
        raise TypeError(f"{who}: targets 必须是序列，收到 {type(targets).__name__}")
    labels = []
    for t in targets:
        if isinstance(t, bool) or not isinstance(t, int):
            raise TypeError(f"{who}: targets 只能含整数，收到 {t!r}")
        if not 0 <= t < K:
            raise ValueError(f"{who}: targets 含越界标签 {t}（词表大小 {K}）")
        if t == blank:
            raise ValueError(f"{who}: targets 不能包含 blank={blank}（与空符号冲突）")
        labels.append(t)
    if not labels:
        raise ValueError(f"{who}: targets 不能为空")

    lp = [flat_lp[t * K:(t + 1) * K] for t in range(T)]
    L = len(labels)
    S = 2 * L + 1
    ext = [blank if s % 2 == 0 else labels[s // 2] for s in range(S)]
    NEG = float("-inf")

    def lse(vals):
        m = max(vals)
        if m == NEG:
            return NEG
        return m + math.log(sum(math.exp(v - m) for v in vals))

    alpha = [[NEG] * S for _ in range(T)]
    alpha[0][0] = lp[0][ext[0]]
    if S > 1:
        alpha[0][1] = lp[0][ext[1]]
    for t in range(1, T):
        for s in range(S):
            prev = [alpha[t - 1][s]]
            if s >= 1:
                prev.append(alpha[t - 1][s - 1])
            if s >= 2 and ext[s] != blank and ext[s] != ext[s - 2]:
                prev.append(alpha[t - 1][s - 2])
            base = lse(prev)
            alpha[t][s] = base + lp[t][ext[s]] if base != NEG else NEG

    beta = [[NEG] * S for _ in range(T)]
    beta[T - 1][S - 1] = lp[T - 1][ext[S - 1]]
    if S > 1:
        beta[T - 1][S - 2] = lp[T - 1][ext[S - 2]]
    for t in range(T - 2, -1, -1):
        for s in range(S):
            nxt = [beta[t + 1][s]]
            if s + 1 < S:
                nxt.append(beta[t + 1][s + 1])
            if s + 2 < S and ext[s + 2] != blank and ext[s + 2] != ext[s]:
                nxt.append(beta[t + 1][s + 2])
            base = lse(nxt)
            beta[t][s] = base + lp[t][ext[s]] if base != NEG else NEG

    ends = [alpha[T - 1][S - 1]]
    if S > 1:
        ends.append(alpha[T - 1][S - 2])
    log_p = lse(ends)
    if log_p == NEG:
        raise ValueError(f"{who}: 该标签序列在给定长度下不可达（T={T}, 标签 {L} 个）")

    grad = [[0.0] * K for _ in range(T)]
    for t in range(T):
        for s in range(S):
            a_t, b_t = alpha[t][s], beta[t][s]
            if a_t == NEG or b_t == NEG:
                continue
            grad[t][ext[s]] -= math.exp(a_t + b_t - log_p - lp[t][ext[s]])
    return -log_p, grad


# ============================================================================
#  Optimizer: Adam
# ============================================================================

class Adam:
    """Adam 优化器（一阶矩 + 二阶矩 + 偏差修正）

    每个参数：m = b1*m + (1-b1)*g，v = b2*v + (1-b2)*g*g，
              p -= lr * (m/(1-b1^t)) / (sqrt(v/(1-b2^t)) + eps)
    动量存在每层上（权重 m_w/v_w，偏置 m_b/v_b），`step_count` 记已更新步数。
    想精确续训要用 `_optimizer_state` / `load_optimizer_state` 连状态一起存取；
    只存权重再 load 会从 step_count=0 重新开始，偏差修正对不上。
    """

    def __init__(self, model: MLP, lr: float = 1e-3,
                 beta1: float = 0.9, beta2: float = 0.999, eps: float = 1e-8):
        self.model = model
        self.lr = lr
        self.beta1 = beta1
        self.beta2 = beta2
        self.eps = eps
        self.step_count = 0

    def step(self, all_grads):
        """
        all_grads: List[(grad_w, grad_b)] 每层一个元组
        """
        self.step_count += 1
        # 偏差修正系数只依赖 step_count，必须提到循环外：
        # 原来写在内层，每个权重都要重新算一次 beta ** step_count（pow 很贵）
        b1, b2, lr, eps = self.beta1, self.beta2, self.lr, self.eps
        c1 = 1 - b1 ** self.step_count
        c2 = 1 - b2 ** self.step_count
        o1, o2 = 1 - b1, 1 - b2
        sqrt = math.sqrt

        for (layer, (grad_w, grad_b)) in zip(self.model.layers, all_grads):
            m_w, v_w, W = layer.m_w, layer.v_w, layer.weights
            m_b, v_b, B = layer.m_b, layer.v_b, layer.biases

            for j in range(layer.fan_out):
                # bias
                g = grad_b[j]
                m = b1 * m_b[j] + o1 * g
                v = b2 * v_b[j] + o2 * g * g
                m_b[j] = m
                v_b[j] = v
                B[j] -= lr * (m / c1) / (sqrt(v / c2) + eps)

                # weight
                gwj, mwj, vwj, Wj = grad_w[j], m_w[j], v_w[j], W[j]
                for i in range(layer.fan_in):
                    g = gwj[i]
                    m = b1 * mwj[i] + o1 * g
                    v = b2 * vwj[i] + o2 * g * g
                    mwj[i] = m
                    vwj[i] = v
                    Wj[i] -= lr * (m / c1) / (sqrt(v / c2) + eps)


class AdamW:
    """AdamW：Adam + 解耦权重衰减（现代 LLM 训练的默认优化器）

    与 Adam 的区别：weight_decay 不进入梯度（不进一阶/二阶矩的自适应缩放），
    而是每步直接把参数乘上 (1 - lr*wd)，再套标准 Adam 更新。
    Adam 里的 L2 会被 sqrt(v) 归一化，导致大梯度参数实际衰减更小；AdamW 没有这个问题。
    """

    def __init__(self, model: MLP, lr: float = 1e-3,
                 beta1: float = 0.9, beta2: float = 0.999, eps: float = 1e-8,
                 weight_decay: float = 0.01):
        if weight_decay is None or weight_decay < 0:
            raise ValueError(f"AdamW: weight_decay 必须 >= 0，收到 {weight_decay!r}")
        self.model = model
        self.lr = lr
        self.beta1 = beta1
        self.beta2 = beta2
        self.eps = eps
        self.weight_decay = float(weight_decay)
        self.step_count = 0

    def step(self, all_grads):
        self.step_count += 1
        b1, b2, lr, eps = self.beta1, self.beta2, self.lr, self.eps
        decay = 1.0 - lr * self.weight_decay
        c1 = 1 - b1 ** self.step_count
        c2 = 1 - b2 ** self.step_count
        o1, o2 = 1 - b1, 1 - b2
        sqrt = math.sqrt

        for (layer, (grad_w, grad_b)) in zip(self.model.layers, all_grads):
            m_w, v_w, W = layer.m_w, layer.v_w, layer.weights
            m_b, v_b, B = layer.m_b, layer.v_b, layer.biases

            for j in range(layer.fan_out):
                g = grad_b[j]
                m = b1 * m_b[j] + o1 * g
                v = b2 * v_b[j] + o2 * g * g
                m_b[j] = m
                v_b[j] = v
                B[j] *= decay
                B[j] -= lr * (m / c1) / (sqrt(v / c2) + eps)

                gwj, mwj, vwj, Wj = grad_w[j], m_w[j], v_w[j], W[j]
                for i in range(layer.fan_in):
                    g = gwj[i]
                    m = b1 * mwj[i] + o1 * g
                    v = b2 * vwj[i] + o2 * g * g
                    mwj[i] = m
                    vwj[i] = v
                    Wj[i] *= decay
                    Wj[i] -= lr * (m / c1) / (sqrt(v / c2) + eps)


# ============================================================================
#  More Optimizers: SGD / SGD+Momentum / RMSprop
# ============================================================================

class SGD:
    """随机梯度下降（可带 Weight Decay）"""

    def __init__(self, model: MLP, lr: float = 0.01, weight_decay: float = 0.0):
        self.model = model
        self.lr = lr
        self.weight_decay = weight_decay

    def step(self, all_grads):
        lr, wd = self.lr, self.weight_decay
        for (layer, (grad_w, grad_b)) in zip(self.model.layers, all_grads):
            W, B = layer.weights, layer.biases
            for j in range(layer.fan_out):
                gb = grad_b[j]
                if wd > 0:
                    gb += wd * B[j]
                B[j] -= lr * gb
                gwj, Wj = grad_w[j], W[j]
                for i in range(layer.fan_in):
                    gw = gwj[i]
                    if wd > 0:
                        gw += wd * Wj[i]
                    Wj[i] -= lr * gw

    def zero_grad(self):
        pass


class SGDMomentum:
    """带动量的 SGD（SGD + Momentum）"""

    def __init__(self, model: MLP, lr: float = 0.01, momentum: float = 0.9):
        self.model = model
        self.lr = lr
        self.momentum = momentum
        self.v_w = [[[0.0] * layer.fan_in for _ in range(layer.fan_out)] for layer in model.layers]
        self.v_b = [[0.0] * layer.fan_out for layer in model.layers]

    def step(self, all_grads):
        lr, mu = self.lr, self.momentum
        for idx, (layer, (grad_w, grad_b)) in enumerate(zip(self.model.layers, all_grads)):
            vw, vb = self.v_w[idx], self.v_b[idx]
            W, B = layer.weights, layer.biases
            for j in range(layer.fan_out):
                v = mu * vb[j] + lr * grad_b[j]
                vb[j] = v
                B[j] -= v
                gwj, vwj, Wj = grad_w[j], vw[j], W[j]
                for i in range(layer.fan_in):
                    v = mu * vwj[i] + lr * gwj[i]
                    vwj[i] = v
                    Wj[i] -= v


class RMSprop:
    """RMSprop 优化器"""

    def __init__(self, model: MLP, lr: float = 0.01, alpha: float = 0.99, eps: float = 1e-8):
        self.model = model
        self.lr = lr
        self.alpha = alpha
        self.eps = eps
        self.s_w = [[[0.0] * layer.fan_in for _ in range(layer.fan_out)] for layer in model.layers]
        self.s_b = [[0.0] * layer.fan_out for layer in model.layers]

    def step(self, all_grads):
        lr, al, eps = self.lr, self.alpha, self.eps
        om = 1 - al
        sqrt = math.sqrt
        for idx, (layer, (grad_w, grad_b)) in enumerate(zip(self.model.layers, all_grads)):
            sw, sb = self.s_w[idx], self.s_b[idx]
            W, B = layer.weights, layer.biases
            for j in range(layer.fan_out):
                g = grad_b[j]
                s = al * sb[j] + om * g * g
                sb[j] = s
                B[j] -= lr * g / (sqrt(s) + eps)
                gwj, swj, Wj = grad_w[j], sw[j], W[j]
                for i in range(layer.fan_in):
                    g = gwj[i]
                    s = al * swj[i] + om * g * g
                    swj[i] = s
                    Wj[i] -= lr * g / (sqrt(s) + eps)




# ============================================================================
#  SGDW / Nesterov / Lookahead / SWA / EMA
#
#  前两个是「改更新式」，后三个是「在优化器之外维护一份权重」：
#  Lookahead 包住任意优化器（需要 .step/.model），SWA / EMA 各自维护影子权重，
#  训练完用 apply_to() 换进模型。三者都能被 fit(callbacks=...) 自动驱动
#  （见本节的 EMACallback / SWACallback）。
# ============================================================================

class SGDW:
    """解耦权重衰减的 SGD（SGDW，Loshchilov & Hutter 2019）

    ``p *= (1 - lr*wd)`` 与梯度步分开做，所以和 L2 正则（``g += wd*p``）
    不再是同一件事：小 lr 时惩罚力度与梯度尺度无关。

    参数
    ----
    lr, momentum, weight_decay : float
        ``momentum=0`` 时退化成纯 SGDW；``weight_decay=0`` 且 ``momentum=0``
        时与 ``SGD(lr)`` **逐位相同**。
    nesterov : bool
        Nesterov 动量：``v = mu*v + g``，更新用 ``g + mu*v``（需要 ``momentum>0``）。
    """

    def __init__(self, model: MLP, lr: float = 0.01, momentum: float = 0.0,
                 weight_decay: float = 0.01, nesterov: bool = False):
        if not _is_num(lr) or lr < 0:
            raise ValueError("SGDW: lr 必须是非负有限数字")
        if not _is_num(momentum) or not 0.0 <= momentum < 1.0:
            raise ValueError("SGDW: momentum 必须在 [0, 1) 内")
        if not _is_num(weight_decay) or weight_decay < 0:
            raise ValueError("SGDW: weight_decay 必须是非负有限数字")
        if not isinstance(nesterov, bool):
            raise ValueError("SGDW: nesterov 必须是 bool")
        if nesterov and momentum <= 0.0:
            raise ValueError("SGDW: nesterov=True 需要 momentum > 0")
        self.model = model
        self.lr = float(lr)
        self.momentum = float(momentum)
        self.weight_decay = float(weight_decay)
        self.nesterov = nesterov
        self.step_count = 0
        self.v_w = [[[0.0] * layer.fan_in for _ in range(layer.fan_out)]
                    for layer in model.layers]
        self.v_b = [[0.0] * layer.fan_out for layer in model.layers]

    def step(self, all_grads):
        lr, mu, wd = self.lr, self.momentum, self.weight_decay
        decay = 1.0 - lr * wd
        nesterov = self.nesterov
        for idx, (layer, (grad_w, grad_b)) in enumerate(zip(self.model.layers, all_grads)):
            vw, vb = self.v_w[idx], self.v_b[idx]
            W, B = layer.weights, layer.biases
            for j in range(layer.fan_out):
                g = grad_b[j]
                v = mu * vb[j] + g
                vb[j] = v
                step_b = (g + mu * v) if nesterov else v
                B[j] = B[j] * decay - lr * step_b
                gwj, vwj, Wj = grad_w[j], vw[j], W[j]
                for i in range(layer.fan_in):
                    g = gwj[i]
                    v = mu * vwj[i] + g
                    vwj[i] = v
                    step_w = (g + mu * v) if nesterov else v
                    Wj[i] = Wj[i] * decay - lr * step_w
        self.step_count += 1

    def zero_grad(self):
        pass


class NesterovSGD(SGDW):
    """带 Nesterov 动量的 SGD（默认 ``momentum=0.9``、无权重衰减）"""

    def __init__(self, model: MLP, lr: float = 0.01, momentum: float = 0.9,
                 weight_decay: float = 0.0):
        super().__init__(model, lr=lr, momentum=momentum,
                         weight_decay=weight_decay, nesterov=True)


class Lookahead:
    """Lookahead：外挂任意优化器（Zhang et al. 2019）

    ``optimizer.step()`` 照常更新快权重；每 ``k`` 步把慢权重按
    ``slow += alpha*(fast - slow)`` 混入，再令 ``fast = slow``。
    要求被包的优化器有 ``.model`` 与 ``.step(all_grads)``。
    """

    def __init__(self, optimizer, k: int = 6, alpha: float = 0.5):
        if not isinstance(optimizer, object) or not hasattr(optimizer, "step"):
            raise ValueError("Lookahead: optimizer 必须有 step(all_grads)")
        if not hasattr(optimizer, "model"):
            raise ValueError("Lookahead: optimizer 必须有 .model 属性")
        if not isinstance(k, int) or isinstance(k, bool) or k <= 0:
            raise ValueError("Lookahead: k 必须是正整数")
        if not _is_num(alpha) or not 0.0 < alpha <= 1.0:
            raise ValueError("Lookahead: alpha 必须在 (0, 1] 内")
        self.optimizer = optimizer
        self.model = optimizer.model
        self.k = int(k)
        self.alpha = float(alpha)
        self.step_count = 0
        self._slow = self._snapshot()

    def _snapshot(self):
        return [(layer.biases[:], [row[:] for row in layer.weights])
                for layer in self.model.layers]

    def step(self, all_grads):
        self.optimizer.step(all_grads)
        self.step_count += 1
        if self.step_count % self.k == 0:
            a = self.alpha
            for idx, layer in enumerate(self.model.layers):
                slow_b, slow_w = self._slow[idx]
                B, W = layer.biases, layer.weights
                for j in range(layer.fan_out):
                    slow_b[j] = slow_b[j] + a * (B[j] - slow_b[j])
                    B[j] = slow_b[j]
                    for i in range(layer.fan_in):
                        slow_w[j][i] = slow_w[j][i] + a * (W[j][i] - slow_w[j][i])
                        W[j][i] = slow_w[j][i]

    def zero_grad(self):
        if hasattr(self.optimizer, "zero_grad"):
            self.optimizer.zero_grad()

    def state_dict(self):
        return {
            "optimizer": "lookahead",
            "k": self.k,
            "alpha": self.alpha,
            "step_count": self.step_count,
            "inner": self.optimizer.state_dict() if hasattr(self.optimizer, "state_dict") else None,
            "slow": [
                {"biases": b[:], "weights": [row[:] for row in w]}
                for (b, w) in self._slow
            ],
        }

    def load_state_dict(self, st):
        if not isinstance(st, dict) or st.get("optimizer") != "lookahead":
            raise ValueError("Lookahead.load_state_dict: 需要 lookahead 的 state_dict")
        if st.get("k") != self.k or not _is_num(st.get("alpha")):
            raise ValueError("Lookahead.load_state_dict: k / alpha 与当前实例不符")
        self.step_count = int(st["step_count"])
        slow = st["slow"]
        if len(slow) != len(self.model.layers):
            raise ValueError("Lookahead.load_state_dict: 层数不符")
        for idx, layer in enumerate(self.model.layers):
            b = slow[idx]["biases"]
            w = slow[idx]["weights"]
            if len(b) != layer.fan_out or len(w) != layer.fan_out:
                raise ValueError("Lookahead.load_state_dict: 形状与模型不符")
            self._slow[idx] = (list(b), [list(row) for row in w])
        inner = st.get("inner")
        if inner is not None and hasattr(self.optimizer, "load_state_dict"):
            self.optimizer.load_state_dict(inner)


class EMA:
    """指数滑动平均权重（``shadow = decay*shadow + (1-decay)*p``）

    ``warmup>0`` 时前若干次更新用 TF 式有效衰减
    ``min(decay, (1+t)/(10+t))``，避免开头几次把影子权重拉得太偏。
    """

    def __init__(self, model: MLP, decay: float = 0.999, warmup: int = 0):
        if not _is_num(decay) or not 0.0 <= decay < 1.0:
            raise ValueError("EMA: decay 必须在 [0, 1) 内")
        if not isinstance(warmup, int) or isinstance(warmup, bool) or warmup < 0:
            raise ValueError("EMA: warmup 必须是非负整数")
        self.model = model
        self.decay = float(decay)
        self.warmup = int(warmup)
        self.step = 0
        self._shadow = [(layer.biases[:], [row[:] for row in layer.weights])
                        for layer in model.layers]

    def effective_decay(self):
        if self.warmup and self.step < self.warmup:
            return min(self.decay, (1.0 + self.step) / (10.0 + self.step))
        return self.decay

    def update(self):
        d = self.effective_decay()
        od = 1.0 - d
        self.step += 1
        for idx, layer in enumerate(self.model.layers):
            sh_b, sh_w = self._shadow[idx]
            B, W = layer.biases, layer.weights
            for j in range(layer.fan_out):
                sh_b[j] = d * sh_b[j] + od * B[j]
                for i in range(layer.fan_in):
                    sh_w[j][i] = d * sh_w[j][i] + od * W[j][i]

    def shadow(self):
        return [(b[:], [row[:] for row in w]) for (b, w) in self._shadow]

    def apply_to(self, model=None):
        target = self.model if model is None else model
        if len(target.layers) != len(self._shadow):
            raise ValueError("EMA.apply_to: 层数不符")
        for idx, layer in enumerate(target.layers):
            b, w = self._shadow[idx]
            if len(b) != layer.fan_out:
                raise ValueError("EMA.apply_to: 形状与模型不符")
            layer.biases = list(b)
            layer.weights = [list(row) for row in w]

    def state_dict(self):
        return {
            "ema": {
                "decay": self.decay,
                "warmup": self.warmup,
                "step": self.step,
                "shadow": [
                    {"biases": b[:], "weights": [row[:] for row in w]}
                    for (b, w) in self._shadow
                ],
            }
        }

    def load_state_dict(self, st):
        if not isinstance(st, dict) or "ema" not in st:
            raise ValueError("EMA.load_state_dict: 需要 {'ema': {...}}")
        d = st["ema"]
        self.decay = float(d["decay"])
        self.warmup = int(d.get("warmup", 0))
        self.step = int(d.get("step", 0))
        shadow = d["shadow"]
        if len(shadow) != len(self.model.layers):
            raise ValueError("EMA.load_state_dict: 层数不符")
        for idx, layer in enumerate(self.model.layers):
            b, w = shadow[idx]["biases"], shadow[idx]["weights"]
            if len(b) != layer.fan_out or len(w) != layer.fan_out:
                raise ValueError("EMA.load_state_dict: 形状与模型不符")
            self._shadow[idx] = (list(b), [list(row) for row in w])


class SWA:
    """随机权重平均（``avg += (snap - avg)/n``，等价于全部快照的算术平均）"""

    def __init__(self, model: MLP):
        self.model = model
        self.n = 0
        self._avg = [(layer.biases[:], [row[:] for row in layer.weights])
                     for layer in model.layers]

    def update(self):
        self.n += 1
        for idx, layer in enumerate(self.model.layers):
            av_b, av_w = self._avg[idx]
            B, W = layer.biases, layer.weights
            for j in range(layer.fan_out):
                av_b[j] = av_b[j] + (B[j] - av_b[j]) / self.n
                for i in range(layer.fan_in):
                    av_w[j][i] = av_w[j][i] + (W[j][i] - av_w[j][i]) / self.n

    def average(self):
        return [(b[:], [row[:] for row in w]) for (b, w) in self._avg]

    def apply_to(self, model=None):
        target = self.model if model is None else model
        if len(target.layers) != len(self._avg):
            raise ValueError("SWA.apply_to: 层数不符")
        for idx, layer in enumerate(target.layers):
            b, w = self._avg[idx]
            if len(b) != layer.fan_out:
                raise ValueError("SWA.apply_to: 形状与模型不符")
            layer.biases = list(b)
            layer.weights = [list(row) for row in w]

    def state_dict(self):
        return {
            "swa": {
                "n": self.n,
                "avg": [
                    {"biases": b[:], "weights": [row[:] for row in w]}
                    for (b, w) in self._avg
                ],
            }
        }

    def load_state_dict(self, st):
        if not isinstance(st, dict) or "swa" not in st:
            raise ValueError("SWA.load_state_dict: 需要 {'swa': {...}}")
        d = st["swa"]
        self.n = int(d["n"])
        avg = d["avg"]
        if len(avg) != len(self.model.layers):
            raise ValueError("SWA.load_state_dict: 层数不符")
        for idx, layer in enumerate(self.model.layers):
            b, w = avg[idx]["biases"], avg[idx]["weights"]
            if len(b) != layer.fan_out or len(w) != layer.fan_out:
                raise ValueError("SWA.load_state_dict: 形状与模型不符")
            self._avg[idx] = (list(b), [list(row) for row in w])


class Lion:
    """Lion 优化器（EvoLved Sign Momentum，Google 2023）

    只对「动量符号」做更新：``p -= lr * (sign(b1*m + (1-b1)*g) + wd*p)``，
    动量用 b2 更新。每步只存一份动量（Adam 存两份），显存减半；
    论文里在同等算力下常能追平 AdamW。

    注意：Lion 对 lr 比 Adam 敏感，通常取 AdamW 的 1/3 ~ 1/10。
    """

    def __init__(self, model: MLP, lr: float = 1e-4, beta1: float = 0.9,
                 beta2: float = 0.99, weight_decay: float = 0.0):
        if not 0.0 <= float(beta1) <= 1.0:
            raise ValueError(f"Lion: beta1 必须在 [0,1]，收到 {beta1!r}")
        if not 0.0 <= float(beta2) <= 1.0:
            raise ValueError(f"Lion: beta2 必须在 [0,1]，收到 {beta2!r}")
        if float(weight_decay) < 0.0:
            raise ValueError(f"Lion: weight_decay 必须 >= 0，收到 {weight_decay!r}")
        self.model = model
        self.lr = lr
        self.beta1 = beta1
        self.beta2 = beta2
        self.weight_decay = weight_decay
        self.step_count = 0
        self.m_w = [[[0.0] * layer.fan_in for _ in range(layer.fan_out)]
                    for layer in model.layers]
        self.m_b = [[0.0] * layer.fan_out for layer in model.layers]

    def step(self, all_grads):
        """all_grads: List[(grad_w, grad_b)]，与 Adam.step 同签名"""
        self.step_count += 1
        lr, b1, b2, wd = self.lr, self.beta1, self.beta2, self.weight_decay
        for idx, (layer, (grad_w, grad_b)) in enumerate(zip(self.model.layers, all_grads)):
            mw, mb = self.m_w[idx], self.m_b[idx]
            W, B = layer.weights, layer.biases
            for j in range(layer.fan_out):
                g = grad_b[j]
                c = b1 * mb[j] + (1.0 - b1) * g
                upd = (1.0 if c > 0.0 else (-1.0 if c < 0.0 else 0.0)) + wd * B[j]
                B[j] -= lr * upd
                mb[j] = b2 * mb[j] + (1.0 - b2) * g
                gwj, mwj, Wj = grad_w[j], mw[j], W[j]
                for i in range(layer.fan_in):
                    g = gwj[i]
                    c = b1 * mwj[i] + (1.0 - b1) * g
                    upd = (1.0 if c > 0.0 else (-1.0 if c < 0.0 else 0.0)) + wd * Wj[i]
                    Wj[i] -= lr * upd
                    mwj[i] = b2 * mwj[i] + (1.0 - b2) * g


class Adafactor:
    """Adafactor 优化器（Google 2018）：二阶矩「行列因子化」，显存 O(m+n)

    Adam 给每个元素存一份 v；对 (m,n) 权重矩阵，Adafactor 只存
    行均值 R(m) 与列均值 C(n)，近似 ``v_ij ≈ R_i * C_j / mean(R)``。
    更新量乘以相对步长 ``max(eps2, rms(g))``（论文的 relative step size），
    否则梯度很小时几乎不前进。

    没有一阶动量（省一份缓冲）——这是论文的默认配置；
    ``weight_decay`` 是解耦的（不乘进梯度）。
    """

    def __init__(self, model: MLP, lr: float = 1e-3, eps: float = 1e-30,
                 eps2: float = 1e-3, beta2: float = 0.999, weight_decay: float = 0.0):
        if float(eps) <= 0.0 or float(eps2) <= 0.0:
            raise ValueError("Adafactor: eps / eps2 必须 > 0")
        if not 0.0 <= float(beta2) < 1.0:
            raise ValueError(f"Adafactor: beta2 必须在 [0,1)，收到 {beta2!r}")
        if float(weight_decay) < 0.0:
            raise ValueError(f"Adafactor: weight_decay 必须 >= 0，收到 {weight_decay!r}")
        self.model = model
        self.lr = lr
        self.eps = eps
        self.eps2 = eps2
        self.beta2 = beta2
        self.weight_decay = weight_decay
        self.step_count = 0
        # R: 每个输出通道一行（对 fan_in 求均值）；C: 每个输入通道一列
        self.R = [[0.0] * layer.fan_out for layer in model.layers]
        self.C = [[0.0] * layer.fan_in for layer in model.layers]
        self.V_b = [[0.0] * layer.fan_out for layer in model.layers]

    def step(self, all_grads):
        self.step_count += 1
        t = self.step_count
        decay = 1.0 - (t ** -0.8)
        if decay < 0.0:
            decay = 0.0
        lr, eps, eps2, wd = self.lr, self.eps, self.eps2, self.weight_decay
        for idx, (layer, (grad_w, grad_b)) in enumerate(zip(self.model.layers, all_grads)):
            R, C, Vb = self.R[idx], self.C[idx], self.V_b[idx]
            W, B = layer.weights, layer.biases
            fo, fi = layer.fan_out, layer.fan_in
            om = 1.0 - decay
            # 1) 行列二阶矩（行均值 / 列均值）
            sq = 0.0
            for j in range(fo):
                row, gwj = R, grad_w[j]
                acc = 0.0
                for i in range(fi):
                    g = gwj[i]
                    acc += g * g
                    sq += g * g
                row[j] = decay * row[j] + om * (acc / fi)
            for i in range(fi):
                acc = 0.0
                for j in range(fo):
                    g = grad_w[j][i]
                    acc += g * g
                C[i] = decay * C[i] + om * (acc / fo)
            mean_R = sum(R) / fo if fo else 1.0
            if mean_R <= 0.0:
                mean_R = 1.0
            # 相对步长（论文的 relative step size）
            lr_t = lr * max(eps2, math.sqrt(sq / (fo * fi) if fo * fi else 0.0))
            # 2) 更新
            for j in range(fo):
                gwj, Wj = grad_w[j], W[j]
                for i in range(fi):
                    v = R[j] * C[i] / mean_R
                    # 解耦权重衰减必须用「更新前」的权重：写成单个表达式求值，
                    # 否则 wd 会作用在已经减过一次的值上（顺序错就多衰减一次）
                    Wj[i] = (Wj[i] - lr_t * gwj[i] / math.sqrt(v + eps)
                             - lr * wd * Wj[i])
                g = grad_b[j]
                Vb[j] = decay * Vb[j] + om * g * g
                B[j] = B[j] - lr_t * g / math.sqrt(Vb[j] + eps) - lr * wd * B[j]


# ============================================================================
#  More Optimizers: AdaGrad / AdaDelta / Nadam / RAdam
# ============================================================================

def _w9_check(who, lr, betas=(), eps=None):
    """优化器的公共参数校验（不接 bool，不接 nan/inf）"""
    if not _is_num(lr) or lr < 0:
        raise ValueError(f"{who}: lr 必须是非负有限数字，收到 {lr!r}")
    for name, b in betas:
        if not _is_num(b) or not 0.0 <= b < 1.0:
            raise ValueError(f"{who}: {name} 必须在 [0,1)，收到 {b!r}")
    if eps is not None and (not _is_num(eps) or eps <= 0.0):
        raise ValueError(f"{who}: eps 必须 > 0，收到 {eps!r}")


def _w9_get(a, j, i):
    return a[j] if i is None else a[j][i]


def _w9_set(a, j, i, v):
    if i is None:
        a[j] = v
    else:
        a[j][i] = v


def _w9_zeros(layer, kind):
    if kind == 'w':
        return [[0.0] * layer.fan_in for _ in range(layer.fan_out)]
    return [0.0] * layer.fan_out


def _w9_copy(obj):
    """深拷贝嵌套 list（state_dict 必须交出快照，不能交活引用）

    否则常见用法会把两个优化器**别名**到同一份状态上：
    `blob = opt_a.state_dict(); opt_b.load_state_dict(blob)` 之后
    两边共享同一批 list，进一步训练 opt_a 会顺手改掉 opt_b 的状态。
    """
    if isinstance(obj, list):
        return [_w9_copy(v) for v in obj]
    if isinstance(obj, dict):
        return {k: _w9_copy(v) for k, v in obj.items()}
    return obj


def _w9_check_state(st, layer, kind, who):
    """校验载入的状态形状与层匹配（形状不符会让 step 里静默算错）"""
    if kind == 'b':
        if not isinstance(st, list) or len(st) != layer.fan_out:
            raise ValueError(
                f"{who}: 偏置状态长度必须是 fan_out={layer.fan_out}")
        for v in st:
            if not _is_num(v):
                raise ValueError(f"{who}: 偏置状态里有非数字 {v!r}")
        return
    if not isinstance(st, list) or len(st) != layer.fan_out:
        raise ValueError(f"{who}: 权重状态行数必须是 fan_out={layer.fan_out}")
    for row in st:
        if not isinstance(row, list) or len(row) != layer.fan_in:
            raise ValueError(f"{who}: 权重状态列数必须是 fan_in={layer.fan_in}")
        for v in row:
            if not _is_num(v):
                raise ValueError(f"{who}: 权重状态里有非数字 {v!r}")


class _StatefulOptimizer:
    """带「每参数独立状态」的优化器基类

    Adam 一族把两个矩直接存在 layer 上（`m_w`/`v_w`/`m_b`/`v_b`），够用且能随
    `_optimizer_state` 一起存档。AdaGrad / AdaDelta 这类每个参数要 1–2 个**额外**
    累积量，塞进 layer 会污染层结构，因此状态放在优化器实例的 `state` 字典里，
    键是 `(层号, 'w'|'b')`，用到时才创建（惰性）。

    `state_dict()` / `load_state_dict()` 用于断点续训：Adam 那套状态挂在 layer 上
    所以能进模型存档，这套必须单独存。
    """

    name = "stateful"

    def __init__(self, model, lr):
        self.model = model
        self.lr = float(lr)
        self.step_count = 0
        self.state = {}

    def _ensure(self, idx, kind, layer):
        key = (idx, kind)
        st = self.state.get(key)
        if st is None:
            st = self._new_state(layer, kind)
            self.state[key] = st
        return st

    def _new_state(self, layer, kind):
        raise NotImplementedError

    def _prepare(self):
        """每步开头算一次只依赖 step_count 的系数（子类覆盖）"""

    def _increment(self, st, g, j, i):
        """返回该参数本步的「减量」（正数表示沿负梯度方向前进）"""
        raise NotImplementedError

    def step(self, all_grads):
        if len(all_grads) != len(self.model.layers):
            raise ValueError(
                f"{self.name}.step: 梯度层数 {len(all_grads)} 与模型层数 "
                f"{len(self.model.layers)} 不一致")
        self.step_count += 1
        self._prepare()
        for idx, (layer, (grad_w, grad_b)) in enumerate(
                zip(self.model.layers, all_grads)):
            st_b = self._ensure(idx, 'b', layer)
            st_w = self._ensure(idx, 'w', layer)
            for j in range(layer.fan_out):
                layer.biases[j] -= self._increment(st_b, grad_b[j], j, None)
                row_g, row_W = grad_w[j], layer.weights[j]
                for i in range(layer.fan_in):
                    row_W[i] -= self._increment(st_w, row_g[i], j, i)

    def state_dict(self):
        items = sorted(self.state.items(), key=lambda kv: (kv[0][0], kv[0][1]))
        return {
            "optimizer": self.name,
            "lr": self.lr,
            "step_count": self.step_count,
            "state": {f"{idx}:{kind}": _w9_copy(st)
                      for (idx, kind), st in items},
        }

    def load_state_dict(self, blob):
        if not isinstance(blob, dict):
            raise ValueError(
                f"{self.name}: state_dict 必须是 dict，收到 {type(blob).__name__}")
        owner = blob.get("optimizer")
        if owner not in (None, self.name):
            raise ValueError(f"{self.name}: state_dict 属于 {owner!r} 的优化器")
        state = blob.get("state", {})
        if not isinstance(state, dict):
            raise ValueError(f"{self.name}: state 字段必须是 dict")
        parsed = {}
        for key, st in state.items():
            idx_s, _, kind = str(key).partition(":")
            try:
                idx = int(idx_s)
            except (TypeError, ValueError):
                raise ValueError(
                    f"{self.name}: 状态键 {key!r} 不是 '层号:w|b' 形式")
            if kind not in ("w", "b"):
                raise ValueError(f"{self.name}: 状态键 {key!r} 的参数类型必须是 w/b")
            if not 0 <= idx < len(self.model.layers):
                raise ValueError(
                    f"{self.name}: 状态键 {key!r} 指向不存在的层（共 "
                    f"{len(self.model.layers)} 层）")
            copied = _w9_copy(st)
            # 每个字段（s/u/m/v）都要与层形状一致
            if not isinstance(copied, dict) or not copied:
                raise ValueError(
                    f"{self.name}: 状态键 {key!r} 的值必须是非空 dict")
            layer = self.model.layers[idx]
            for field, arr in copied.items():
                _w9_check_state(arr, layer, kind,
                                f"{self.name}.load_state_dict[{key}.{field}]")
            parsed[(idx, kind)] = copied
        t = blob.get("step_count", 0)
        if not isinstance(t, int) or isinstance(t, bool) or t < 0:
            raise ValueError(f"{self.name}: step_count 必须是非负整数，收到 {t!r}")
        self.state = parsed
        self.step_count = t
        if "lr" in blob:
            self.lr = float(blob["lr"])
        return self


class AdaGrad(_StatefulOptimizer):
    """AdaGrad（2011）：按历史梯度平方和逐参数衰减步长

    ``s += g * g``；``p -= lr * g / (sqrt(s) + eps)``。

    它是**单调不增步长**的：某个方向历史上梯度越大，之后迈的步子越小。
    好处是不用调 lr 也能在稀疏梯度上快速推进；坏处是训练中期容易过早停滞
    （s 只增不减，步长一路单调衰减），这也是后来 RMSprop/Adam 出现的原因。
    """

    name = "adagrad"

    def __init__(self, model: MLP, lr: float = 0.01, eps: float = 1e-8):
        _w9_check("AdaGrad", lr, eps=eps)
        super().__init__(model, lr)
        self.eps = float(eps)

    def _new_state(self, layer, kind):
        return {"s": _w9_zeros(layer, kind)}

    def _increment(self, st, g, j, i):
        s = _w9_get(st["s"], j, i) + g * g
        _w9_set(st["s"], j, i, s)
        return self.lr * g / (math.sqrt(s) + self.eps)


class AdaDelta(_StatefulOptimizer):
    """AdaDelta（2012）：用「更新量平方的滑动平均」替掉全局学习率

    ``s = rho * s + (1-rho) * g^2``、
    ``dx = sqrt(u + eps) / sqrt(s + eps) * g``、
    ``u = rho * u + (1-rho) * dx^2``，然后 ``p -= lr * dx``。

    分子 u 与分母 s 都是「梯度的平方」量纲，商是无量纲的，所以算法对梯度的
    整体缩放不变（把梯度乘 10，dx 乘 10 后 u 乘 100，比值不变）。因此默认
    ``lr=1.0`` 就有意义，不需要按任务调。
    """

    name = "adadelta"

    def __init__(self, model: MLP, lr: float = 1.0, rho: float = 0.95,
                 eps: float = 1e-6):
        if not _is_num(rho) or not 0.0 <= rho < 1.0:
            raise ValueError(f"AdaDelta: rho 必须在 [0,1)，收到 {rho!r}")
        _w9_check("AdaDelta", lr, eps=eps)
        super().__init__(model, lr)
        self.rho = float(rho)
        self.eps = float(eps)

    def _new_state(self, layer, kind):
        return {"s": _w9_zeros(layer, kind), "u": _w9_zeros(layer, kind)}

    def _increment(self, st, g, j, i):
        rho, eps = self.rho, self.eps
        s = rho * _w9_get(st["s"], j, i) + (1.0 - rho) * g * g
        _w9_set(st["s"], j, i, s)
        dx = math.sqrt(_w9_get(st["u"], j, i) + eps) / math.sqrt(s + eps) * g
        u = rho * _w9_get(st["u"], j, i) + (1.0 - rho) * dx * dx
        _w9_set(st["u"], j, i, u)
        return self.lr * dx


class Nadam(_StatefulOptimizer):
    """Nadam（Dozat 2016）：Adam + Nesterov 动量

    ``m = b1*m + (1-b1)*g``、``v = b2*v + (1-b2)*g^2``、
    ``m_hat = m/(1-b1^t)``、``v_hat = v/(1-b2^t)``，
    更新方向是 ``b1*m_hat + (1-b1)*g/(1-b1^t)``。

    与 Adam 的差别只在分子：除了平滑动量还额外加了一份**当前梯度**，
    等价于「先沿动量方向走半步、再按当前梯度修正」（Nesterov 的味道）。
    ``b1=0`` 时退化成 RMSprop 式（``g/(sqrt(v_hat)+eps)``）。
    """

    name = "nadam"

    def __init__(self, model: MLP, lr: float = 1e-3, beta1: float = 0.9,
                 beta2: float = 0.999, eps: float = 1e-8):
        _w9_check("Nadam", lr, (("beta1", beta1), ("beta2", beta2)), eps=eps)
        super().__init__(model, lr)
        self.beta1 = float(beta1)
        self.beta2 = float(beta2)
        self.eps = float(eps)

    def _new_state(self, layer, kind):
        return {"m": _w9_zeros(layer, kind), "v": _w9_zeros(layer, kind)}

    def _prepare(self):
        b1, b2, t = self.beta1, self.beta2, self.step_count
        self._c1 = 1.0 - b1 ** t
        self._c2 = 1.0 - b2 ** t

    def _increment(self, st, g, j, i):
        b1, b2 = self.beta1, self.beta2
        m = b1 * _w9_get(st["m"], j, i) + (1.0 - b1) * g
        v = b2 * _w9_get(st["v"], j, i) + (1.0 - b2) * g * g
        _w9_set(st["m"], j, i, m)
        _w9_set(st["v"], j, i, v)
        c1, c2 = self._c1, self._c2
        num = b1 * (m / c1) + (1.0 - b1) * g / c1
        return self.lr * num / (math.sqrt(v / c2) + self.eps)


class RAdam(_StatefulOptimizer):
    """RAdam（2019）：按「二阶矩的可信度」自动决定用不用自适应步长

    定义 ``rho_inf = 2/(1-b2) - 1``、
    ``rho_t = rho_inf - 2*t*b2^t/(1-b2^t)``。
    ``rho_t > 4`` 时二阶矩已统计到足够多方向，用带修正因子的 Adam 步：
    ``r_t = sqrt(((rho_t-4)(rho_t-2)rho_inf) / ((rho_inf-4)(rho_inf-2)rho_t))``；
    否则（训练最初几步）退化成纯动量 ``p -= lr * m_hat``。

    这样就不需要「warmup 若干步」这种手工技巧：算法自己在前几步关掉自适应缩放，
    等 v 的可信度够了再逐渐打开。
    """

    name = "radam"

    def __init__(self, model: MLP, lr: float = 1e-3, beta1: float = 0.9,
                 beta2: float = 0.999, eps: float = 1e-8):
        _w9_check("RAdam", lr, (("beta1", beta1), ("beta2", beta2)), eps=eps)
        super().__init__(model, lr)
        self.beta1 = float(beta1)
        self.beta2 = float(beta2)
        self.eps = float(eps)
        self.rho_inf = 2.0 / (1.0 - self.beta2) - 1.0
        if self.rho_inf <= 4.0:
            raise ValueError(
                f"RAdam: beta2={beta2!r} 太小时 rho_inf={self.rho_inf:.6g} 不足 4，"
                "修正因子无定义（请用 >= 0.9 的 beta2）")

    def _new_state(self, layer, kind):
        return {"m": _w9_zeros(layer, kind), "v": _w9_zeros(layer, kind)}

    def _prepare(self):
        b1, b2, t = self.beta1, self.beta2, self.step_count
        self._c1 = 1.0 - b1 ** t
        c2 = 1.0 - b2 ** t
        self._c2 = c2
        rho_t = self.rho_inf - 2.0 * t * (b2 ** t) / c2
        self._rho_t = rho_t
        ri = self.rho_inf
        if rho_t > 4.0 and ri > 4.0:
            self._rt = math.sqrt(((rho_t - 4.0) * (rho_t - 2.0) * ri)
                                 / ((ri - 4.0) * (ri - 2.0) * rho_t))
        else:
            self._rt = None

    def _increment(self, st, g, j, i):
        b1, b2 = self.beta1, self.beta2
        m = b1 * _w9_get(st["m"], j, i) + (1.0 - b1) * g
        v = b2 * _w9_get(st["v"], j, i) + (1.0 - b2) * g * g
        _w9_set(st["m"], j, i, m)
        _w9_set(st["v"], j, i, v)
        m_hat = m / self._c1
        if self._rt is None:
            return self.lr * m_hat
        return self.lr * self._rt * m_hat / (math.sqrt(v / self._c2) + self.eps)


# ============================================================================
#  Layer-wise Optimizers: LARS / LAMB / Ranger
# ============================================================================

def _w9b_check(who, name, value, minimum=None):
    """标量校验：有限数字，可选下界（bool 不算数字）"""
    if not _is_num(value):
        raise ValueError(f"{who}: {name} 必须是有限数字，收到 {value!r}")
    if minimum is not None and value < minimum:
        raise ValueError(f"{who}: {name} 必须 >= {minimum}，收到 {value!r}")
    return float(value)


def _w9b_sqsum(obj):
    """嵌套 list 的平方和（优化器只对数值求范数，不关心结构）"""
    if isinstance(obj, list):
        acc = 0.0
        for v in obj:
            acc += _w9b_sqsum(v)
        return acc
    return float(obj) * float(obj)


class _LayerwiseOptimizer:
    """按「整层」决定步长的优化器基类

    与 `_StatefulOptimizer` 的区别：LARS / LAMB 要先看这一层的权重范数与梯度
    范数，才能算出「信任比」，所以不能逐标量独立更新。状态同样存在优化器实例
    上，键是 `(层号, 'w'|'b')`，值是若干与参数同形状的嵌套列表。

    约定：信任比只按**权重**算，偏置用未缩放的 `lr`（LARS 原文就是这样做的）。
    """

    name = "layerwise"

    def __init__(self, model, lr):
        self.model = model
        self.lr = float(lr)
        self.step_count = 0
        self.state = {}

    def _new_state(self, layer, kind):
        raise NotImplementedError

    def _state_for(self, idx, kind, layer):
        key = (idx, kind)
        st = self.state.get(key)
        if st is None:
            st = self._new_state(layer, kind)
            self.state[key] = st
        return st

    def step(self, all_grads):
        if not isinstance(all_grads, list):
            raise ValueError(
                f"{self.name}.step: all_grads 必须是列表，收到 "
                f"{type(all_grads).__name__}")
        if len(all_grads) != len(self.model.layers):
            raise ValueError(
                f"{self.name}.step: 梯度层数 {len(all_grads)} 与模型层数 "
                f"{len(self.model.layers)} 不一致")
        self.step_count += 1
        for idx, (layer, (grad_w, grad_b)) in enumerate(
                zip(self.model.layers, all_grads)):
            self._update_layer(layer, grad_w, grad_b,
                               self._state_for(idx, 'w', layer),
                               self._state_for(idx, 'b', layer), idx)
        self._after_step()

    def _after_step(self):
        """每步结束后的钩子（Ranger 用它做 Lookahead 慢权重同步）"""

    def _update_layer(self, layer, grad_w, grad_b, st_w, st_b, idx):
        raise NotImplementedError

    def _check_state_field(self, key, field, arr, layer, kind):
        """校验一个状态字段的形状（子类可覆盖，例如 CAME 的 r/c 是向量）"""
        _w9_check_state(arr, layer, kind,
                         f"{self.name}.load_state_dict[{key}.{field}]")

    def state_dict(self):
        items = sorted(self.state.items(), key=lambda kv: (kv[0][0], kv[0][1]))
        return {
            "optimizer": self.name,
            "lr": self.lr,
            "step_count": self.step_count,
            "state": {f"{idx}:{kind}": _w9_copy(st)
                      for (idx, kind), st in items},
        }

    def load_state_dict(self, blob):
        if not isinstance(blob, dict):
            raise ValueError(
                f"{self.name}: state_dict 必须是 dict，收到 {type(blob).__name__}")
        owner = blob.get("optimizer")
        if owner not in (None, self.name):
            raise ValueError(f"{self.name}: state_dict 属于 {owner!r} 的优化器")
        state = blob.get("state", {})
        if not isinstance(state, dict):
            raise ValueError(f"{self.name}: state 字段必须是 dict")
        parsed = {}
        for key, st in state.items():
            idx_s, _, kind = str(key).partition(":")
            try:
                idx = int(idx_s)
            except (TypeError, ValueError):
                raise ValueError(
                    f"{self.name}: 状态键 {key!r} 不是 '层号:w|b' 形式")
            if kind not in ("w", "b"):
                raise ValueError(f"{self.name}: 状态键 {key!r} 的参数类型必须是 w/b")
            if not 0 <= idx < len(self.model.layers):
                raise ValueError(
                    f"{self.name}: 状态键 {key!r} 指向不存在的层（共 "
                    f"{len(self.model.layers)} 层）")
            copied = _w9_copy(st)
            if not isinstance(copied, dict) or not copied:
                raise ValueError(
                    f"{self.name}: 状态键 {key!r} 的值必须是非空 dict")
            layer = self.model.layers[idx]
            for field, arr in copied.items():
                self._check_state_field(key, field, arr, layer, kind)
            parsed[(idx, kind)] = copied
        t = blob.get("step_count", 0)
        if not isinstance(t, int) or isinstance(t, bool) or t < 0:
            raise ValueError(f"{self.name}: step_count 必须是非负整数，收到 {t!r}")
        self.state = parsed
        self.step_count = t
        if "lr" in blob:
            self.lr = float(blob["lr"])
        return self


class LARS(_LayerwiseOptimizer):
    """LARS（2017）：按「权重范数 / 梯度范数」给每层单独缩放学习率

    ``trust = trust_coef * ||w|| / (||g|| + wd*||w|| + eps)``，``local_lr = lr*trust``；
    然后 ``vel = momentum*vel + local_lr*(g + wd*w)``、``p -= vel``（`nesterov`
    时改成 ``p -= momentum*vel + local_lr*(g + wd*w)``）。

    信任比让各层的相对前进量大致相同，所以大 batch 训练可以把 lr 放大到 0.1~10
    量级而不炸。`||w||` 或 `||g||` 为 0（例如该层梯度恰好全零）时退化成普通
    动量 SGD（`local_lr = lr`）。
    """

    name = "lars"

    def __init__(self, model, lr=0.1, momentum=0.9, weight_decay=0.0,
                 trust_coef=0.001, eps=1e-8, nesterov=False):
        _w9_check("LARS", lr, betas=(("momentum", momentum),), eps=eps)
        super().__init__(model, lr)
        self.momentum = float(momentum)
        self.weight_decay = _w9b_check("LARS", "weight_decay", weight_decay, 0.0)
        self.trust_coef = _w9b_check("LARS", "trust_coef", trust_coef, 0.0)
        self.eps = float(eps)
        if not isinstance(nesterov, bool):
            raise ValueError("LARS: nesterov 必须是 bool")
        self.nesterov = nesterov

    def _new_state(self, layer, kind):
        return {"vel": _w9_zeros(layer, kind)}

    def _update_layer(self, layer, grad_w, grad_b, st_w, st_b, idx):
        lr, mom, wd, tc, eps = (self.lr, self.momentum, self.weight_decay,
                                self.trust_coef, self.eps)
        w_sq = _w9b_sqsum(layer.weights)
        g_sq = _w9b_sqsum(grad_w)
        w_norm = math.sqrt(w_sq)
        g_norm = math.sqrt(g_sq)
        denom = g_norm + wd * w_norm + eps
        if w_norm > 0.0 and denom > 0.0:
            local_lr = lr * tc * w_norm / denom
        else:
            local_lr = lr
        vel = st_w["vel"]
        for j in range(layer.fan_out):
            Wj, gwj, vj = layer.weights[j], grad_w[j], vel[j]
            for i in range(layer.fan_in):
                g = gwj[i] + wd * Wj[i]
                vj[i] = mom * vj[i] + local_lr * g
                if self.nesterov:
                    Wj[i] -= mom * vj[i] + local_lr * g
                else:
                    Wj[i] -= vj[i]
        vel_b = st_b["vel"]
        for j in range(layer.fan_out):
            g = grad_b[j] + wd * layer.biases[j]
            vel_b[j] = mom * vel_b[j] + lr * g
            if self.nesterov:
                layer.biases[j] -= mom * vel_b[j] + lr * g
            else:
                layer.biases[j] -= vel_b[j]


class LAMB(_LayerwiseOptimizer):
    """LAMB（2019）：Adam 的逐参数自适应 + LARS 的逐层信任比

    每层先算标准 Adam 更新 ``u = m_hat/(sqrt(v_hat)+eps) + wd*w``，再用
    ``trust = ||w|| / ||u||``（截断到 ``trust_clip``）缩放：``p -= lr*trust*u``。
    这样 BERT 那种「大 batch + 大 lr」的预训练不会因为某层梯度大就爆掉。
    """

    name = "lamb"

    def __init__(self, model, lr=1e-3, beta1=0.9, beta2=0.999, eps=1e-6,
                 weight_decay=0.0, trust_clip=10.0):
        _w9_check("LAMB", lr, betas=(("beta1", beta1), ("beta2", beta2)), eps=eps)
        super().__init__(model, lr)
        self.beta1 = float(beta1)
        self.beta2 = float(beta2)
        self.eps = float(eps)
        self.weight_decay = _w9b_check("LAMB", "weight_decay", weight_decay, 0.0)
        self.trust_clip = _w9b_check("LAMB", "trust_clip", trust_clip, 1e-12)

    def _new_state(self, layer, kind):
        return {"m": _w9_zeros(layer, kind), "v": _w9_zeros(layer, kind)}

    def _update_layer(self, layer, grad_w, grad_b, st_w, st_b, idx):
        b1, b2, lr, eps = self.beta1, self.beta2, self.lr, self.eps
        wd, clip = self.weight_decay, self.trust_clip
        t = self.step_count
        c1 = 1.0 - b1 ** t
        c2 = 1.0 - b2 ** t
        om1 = 1.0 - b1
        om2 = 1.0 - b2
        m_w, v_w = st_w["m"], st_w["v"]
        # 1) 先按 Adam 算「未缩放」的整层更新量 u（含解耦权重衰减）
        u = [[0.0] * layer.fan_in for _ in range(layer.fan_out)]
        u_sq = 0.0
        for j in range(layer.fan_out):
            gwj, mj, vj, uj = grad_w[j], m_w[j], v_w[j], u[j]
            Wj = layer.weights[j]
            for i in range(layer.fan_in):
                g = gwj[i]
                mj[i] = b1 * mj[i] + om1 * g
                vj[i] = b2 * vj[i] + om2 * g * g
                step_i = (mj[i] / c1) / (math.sqrt(vj[i] / c2) + eps)
                uj[i] = step_i + wd * Wj[i]
                u_sq += uj[i] * uj[i]
        # 2) 信任比：||w|| / ||u||，截断到 trust_clip
        w_sq = _w9b_sqsum(layer.weights)
        u_norm = math.sqrt(u_sq)
        w_norm = math.sqrt(w_sq)
        if w_norm > 0.0 and u_norm > 0.0:
            trust = w_norm / u_norm
            if trust > clip:
                trust = clip
        else:
            trust = 1.0
        scale = lr * trust
        # 3) 应用
        for j in range(layer.fan_out):
            Wj, uj = layer.weights[j], u[j]
            for i in range(layer.fan_in):
                Wj[i] -= scale * uj[i]
        m_b, v_b = st_b["m"], st_b["v"]
        for j in range(layer.fan_out):
            g = grad_b[j]
            m_b[j] = b1 * m_b[j] + om1 * g
            v_b[j] = b2 * v_b[j] + om2 * g * g
            step_j = (m_b[j] / c1) / (math.sqrt(v_b[j] / c2) + eps)
            layer.biases[j] -= lr * (step_j + wd * layer.biases[j])


class Ranger(_LayerwiseOptimizer):
    """Ranger（2020）= RAdam + Lookahead

    内层是 RAdam 的修正步长（前几步只有动量、之后才打开自适应缩放），外层是
    Lookahead：维护一份「慢权重」，每 `k` 步做 ``slow += alpha*(fast-slow)`` 再把
    快权重重置成慢权重。好处是 RAdam 的稳启动 + Lookahead 的低方差收敛。
    """

    name = "ranger"

    def __init__(self, model, lr=1e-3, beta1=0.9, beta2=0.999, eps=1e-8,
                 alpha=0.5, k=6):
        _w9_check("Ranger", lr, betas=(("beta1", beta1), ("beta2", beta2)), eps=eps)
        if not 0.0 < float(beta2) < 1.0:
            raise ValueError(f"Ranger: beta2 必须在 (0,1)，收到 {beta2!r}")
        rho_inf = 2.0 / (1.0 - float(beta2)) - 1.0
        if rho_inf <= 4.0:
            raise ValueError(
                f"Ranger: beta2={beta2!r} 太小（rho_inf={rho_inf:.3f} <= 4），"
                "修正因子无定义；请用 beta2 >= 0.8 左右")
        super().__init__(model, lr)
        self.beta1 = float(beta1)
        self.beta2 = float(beta2)
        self.eps = float(eps)
        self.rho_inf = rho_inf
        if not _is_num(alpha) or not 0.0 < alpha <= 1.0:
            raise ValueError(f"Ranger: alpha 必须在 (0,1]，收到 {alpha!r}")
        self.alpha = float(alpha)
        if not isinstance(k, int) or isinstance(k, bool) or k < 1:
            raise ValueError(f"Ranger: k 必须是 >=1 的整数，收到 {k!r}")
        self.k = k

    def _new_state(self, layer, kind):
        return {"m": _w9_zeros(layer, kind), "v": _w9_zeros(layer, kind),
                "slow": _w9_copy(layer.biases if kind == 'b' else layer.weights)}

    def _update_layer(self, layer, grad_w, grad_b, st_w, st_b, idx):
        b1, b2, lr, eps = self.beta1, self.beta2, self.lr, self.eps
        t = self.step_count
        c1 = 1.0 - b1 ** t
        c2 = 1.0 - b2 ** t
        om1 = 1.0 - b1
        om2 = 1.0 - b2
        rho_t = self.rho_inf - 2.0 * t * (b2 ** t) / c2
        if rho_t > 4.0:
            r_t = math.sqrt(((rho_t - 4.0) * (rho_t - 2.0) * self.rho_inf)
                            / ((self.rho_inf - 4.0) * (self.rho_inf - 2.0) * rho_t))
        else:
            r_t = 0.0
        m_w, v_w = st_w["m"], st_w["v"]
        for j in range(layer.fan_out):
            gwj, mj, vj, Wj = grad_w[j], m_w[j], v_w[j], layer.weights[j]
            for i in range(layer.fan_in):
                g = gwj[i]
                mj[i] = b1 * mj[i] + om1 * g
                vj[i] = b2 * vj[i] + om2 * g * g
                m_hat = mj[i] / c1
                if r_t == 0.0:
                    Wj[i] -= lr * m_hat
                else:
                    v_hat = vj[i] / c2
                    Wj[i] -= lr * r_t * m_hat / (math.sqrt(v_hat) + eps)
        m_b, v_b = st_b["m"], st_b["v"]
        for j in range(layer.fan_out):
            g = grad_b[j]
            m_b[j] = b1 * m_b[j] + om1 * g
            v_b[j] = b2 * v_b[j] + om2 * g * g
            m_hat = m_b[j] / c1
            if r_t == 0.0:
                layer.biases[j] -= lr * m_hat
            else:
                v_hat = v_b[j] / c2
                layer.biases[j] -= lr * r_t * m_hat / (math.sqrt(v_hat) + eps)

    def _after_step(self):
        """Lookahead：每 k 步把慢权重向快权重靠一步，再让快权重回跳"""
        if self.step_count % self.k != 0:
            return
        alpha = self.alpha
        for idx, layer in enumerate(self.model.layers):
            for kind, param in (('w', layer.weights), ('b', layer.biases)):
                st = self.state.get((idx, kind))
                if st is None:
                    continue
                slow = st["slow"]
                if kind == 'b':
                    for j in range(layer.fan_out):
                        slow[j] += alpha * (param[j] - slow[j])
                        param[j] = slow[j]
                else:
                    for j in range(layer.fan_out):
                        srow, prow = slow[j], param[j]
                        for i in range(layer.fan_in):
                            srow[i] += alpha * (prow[i] - srow[i])
                            prow[i] = srow[i]


# ============================================================================
#  Advanced Optimizers: Adan / Prodigy / CAME
# ============================================================================


class Adan(_LayerwiseOptimizer):
    """Adan（2022）：Nesterov 式三阶动量（梯度 / 梯度差 / 参数差）

    每组参数维护五个状态：``m``（梯度 EMA）、``v``（梯度差 EMA）、``n``（参数差 EMA）、
    ``g_prev``/``p_prev``（上一轮梯度与参数）。更新：

        diff_g = g - g_prev
        m = (1-b1)*g + b1*m
        v = (1-b2)*diff_g + b2*v
        n = (1-b3)*(p - p_prev) + b3*n
        p -= lr * (m + b2*v) / (sqrt(n + b3*(p - p_prev)^2) + eps)

    参数差项让步长对曲率有感知，这是 Adan 与 Adam 的主要区别。第一次 step 时
    ``g_prev``/``p_prev`` 用当前值初始化，第一步退化为「Nesterov 动量的 Adam」。
    """

    name = "adan"

    def __init__(self, model, lr=1e-3, beta1=0.98, beta2=0.92, beta3=0.99,
                 eps=1e-8, weight_decay=0.0):
        _w9_check("Adan", lr, betas=(("beta1", beta1), ("beta2", beta2),
                                     ("beta3", beta3)), eps=eps)
        _w9b_check("Adan", "weight_decay", weight_decay, 0.0)
        _LayerwiseOptimizer.__init__(self, model, lr)
        self.beta1 = float(beta1)
        self.beta2 = float(beta2)
        self.beta3 = float(beta3)
        self.eps = float(eps)
        self.weight_decay = float(weight_decay)

    def _new_state(self, layer, kind):
        return {"m": _w9_zeros(layer, kind), "v": _w9_zeros(layer, kind),
                "n": _w9_zeros(layer, kind), "g_prev": _w9_zeros(layer, kind),
                "p_prev": _w9_copy(layer.weights if kind == "w" else layer.biases)}

    def _first_step(self, layer, grad_w, grad_b, st_w, st_b):
        """第一步没有参数差信息，纯 Adan 公式会因 ``sqrt(0 + 0) = 0`` 放大 1/eps 倍

        所以第一步退化为**带偏差校正的 Adam**（这与官方实现的处理一致），并把
        ``g_prev``/``p_prev`` 填好，从第二步起才进入三阶动量的完整公式。
        """
        lr, b1, b2, eps = self.lr, self.beta1, self.beta2, self.eps
        wd = self.weight_decay
        c1, c2 = 1.0 - b1, 1.0 - b2
        for kind, param, grad, st in (("w", layer.weights, grad_w, st_w),
                                      ("b", layer.biases, grad_b, st_b)):
            m, v, g_prev, p_prev = st["m"], st["v"], st["g_prev"], st["p_prev"]
            if kind == "w":
                for j in range(layer.fan_out):
                    pj, gpj = param[j], grad[j]
                    mj, vj, prev_gj = m[j], v[j], g_prev[j]
                    for i in range(len(pj)):
                        g = gpj[i] + wd * pj[i]
                        mj[i] = c1 * g
                        vj[i] = c2 * g * g
                        m_hat = mj[i] / c1
                        v_hat = vj[i] / c2
                        start = pj[i]
                        pj[i] -= lr * m_hat / (math.sqrt(v_hat) + eps)
                        prev_gj[i] = g
                        p_prev[j][i] = start
            else:
                for i in range(len(param)):
                    g = grad[i] + wd * param[i]
                    m[i] = c1 * g
                    v[i] = c2 * g * g
                    m_hat = m[i] / c1
                    v_hat = v[i] / c2
                    start = param[i]
                    param[i] -= lr * m_hat / (math.sqrt(v_hat) + eps)
                    g_prev[i] = g
                    p_prev[i] = start

    def _update_layer(self, layer, grad_w, grad_b, st_w, st_b, idx):
        if self.step_count <= 1:
            return self._first_step(layer, grad_w, grad_b, st_w, st_b)
        lr, b1, b2, b3 = self.lr, self.beta1, self.beta2, self.beta3
        eps, wd = self.eps, self.weight_decay
        for kind, param, grad, st in (("w", layer.weights, grad_w, st_w),
                                      ("b", layer.biases, grad_b, st_b)):
            m, v, n = st["m"], st["v"], st["n"]
            g_prev, p_prev = st["g_prev"], st["p_prev"]
            if kind == "w":
                for j in range(layer.fan_out):
                    pj, gpj = param[j], grad[j]
                    prev_gj, prev_pj = g_prev[j], p_prev[j]
                    mj, vj, nj = m[j], v[j], n[j]
                    for i in range(len(pj)):
                        g = gpj[i] + wd * pj[i]
                        dg = g - prev_gj[i]
                        start = pj[i]
                        p_diff = start - prev_pj[i]
                        mj[i] = (1.0 - b1) * g + b1 * mj[i]
                        vj[i] = (1.0 - b2) * dg + b2 * vj[i]
                        nj[i] = (1.0 - b3) * p_diff * p_diff + b3 * nj[i]
                        denom = math.sqrt(nj[i] + b3 * p_diff * p_diff) + eps
                        pj[i] -= lr * (mj[i] + b2 * vj[i]) / denom
                        prev_gj[i] = g
                        prev_pj[i] = start
            else:
                for i in range(len(param)):
                    g = grad[i] + wd * param[i]
                    dg = g - g_prev[i]
                    start = param[i]
                    p_diff = start - p_prev[i]
                    m[i] = (1.0 - b1) * g + b1 * m[i]
                    v[i] = (1.0 - b2) * dg + b2 * v[i]
                    n[i] = (1.0 - b3) * p_diff * p_diff + b3 * n[i]
                    denom = math.sqrt(n[i] + b3 * p_diff * p_diff) + eps
                    param[i] -= lr * (m[i] + b2 * v[i]) / denom
                    g_prev[i] = g
                    p_prev[i] = start


class Prodigy(_LayerwiseOptimizer):
    """Prodigy（2023）：不需要学习率 —— 步长 ``d`` 由「上一步是否真的下降」自适应

    原论文用「梯度 × 累计位移」直接估计距离，教学实现里很容易被梯度消失带偏
    （残差让 ``d`` 一路放大）。本库保留同一目标（**无需 lr**），改用更稳的乘性自适应：

        dot = <g_prev, p − p_prev>        # 上一步是否真的沿 −g 走了
        d   = d * growth  if dot < 0 else d * shrink
        p  -= lr * d * m_hat / (sqrt(v_hat) + eps)

    ``dot < 0`` 表示上一步确实下降，于是放大步长；否则立刻缩半步（Rprop 思路）。
    ``d`` 夹在 ``[d_min, d_max]`` 内；``growth``/``shrink`` 默认 1.05 / 0.5，
    即「慢慢放大、果断缩小」。``lr`` 默认 1.0，只作整体缩放。

    与原论文的差别（README 同款说明）：估计量换成了单步位移的对齐符号，而不是
    累积位移的投影；换来的是不依赖损失、也不会因梯度趋零而发散。
    """

    name = "prodigy"

    def __init__(self, model, lr=1.0, beta1=0.9, beta2=0.999, eps=1e-8,
                 weight_decay=0.0, d_init=1e-3, growth=1.05, shrink=0.5,
                 d_min=1e-8, d_max=1.0):
        _w9_check("Prodigy", lr, betas=(("beta1", beta1), ("beta2", beta2)), eps=eps)
        for _k, _v in (("weight_decay", weight_decay), ("d_init", d_init),
                       ("d_min", d_min), ("d_max", d_max)):
            _w9b_check("Prodigy", _k, _v, 0.0)
        for _k, _v in (("growth", growth), ("shrink", shrink)):
            if isinstance(_v, bool) or not isinstance(_v, (int, float)):
                raise TypeError(
                    f"Prodigy: {_k} 必须是数值，收到 {type(_v).__name__}")
            if not (0.0 < float(_v) < 4.0):
                raise ValueError(
                    f"Prodigy: {_k} 必须在 (0, 4) 区间内，收到 {_v!r}")
        if not float(d_min) < float(d_max):
            raise ValueError(
                f"Prodigy: 要求 d_min < d_max，收到 {d_min!r} / {d_max!r}")
        if not float(d_min) <= float(d_init) <= float(d_max):
            raise ValueError(
                f"Prodigy: 要求 d_min <= d_init <= d_max，收到 "
                f"{d_min!r} / {d_init!r} / {d_max!r}")
        _LayerwiseOptimizer.__init__(self, model, lr)
        self.beta1 = float(beta1)
        self.beta2 = float(beta2)
        self.eps = float(eps)
        self.weight_decay = float(weight_decay)
        self.d = float(d_init)
        self.growth = float(growth)
        self.shrink = float(shrink)
        self.d_min = float(d_min)
        self.d_max = float(d_max)
        self._p_prev = None
        self._g_prev = None

    def _new_state(self, layer, kind):
        return {"m": _w9_zeros(layer, kind), "v": _w9_zeros(layer, kind)}

    def _flat_params(self):
        flat = []
        for layer in self.model.layers:
            for row in layer.weights:
                flat.extend(row)
            flat.extend(layer.biases)
        return flat

    def _flat_grads(self, all_grads):
        flat = []
        for grad_w, grad_b in all_grads:
            for row in grad_w:
                flat.extend(row)
            flat.extend(grad_b)
        return flat

    def step(self, all_grads):
        flat_p = self._flat_params()
        flat_g = self._flat_grads(all_grads)
        if self._g_prev is not None:
            dot = 0.0
            for gp, pp, pc in zip(self._g_prev, self._p_prev, flat_p):
                dot += gp * (pc - pp)
            factor = self.growth if dot < 0.0 else self.shrink
            self.d = min(max(self.d * factor, self.d_min), self.d_max)
        self._p_prev = flat_p
        self._g_prev = flat_g
        return _LayerwiseOptimizer.step(self, all_grads)

    def state_dict(self):
        """除基类的 ``m``/``v`` 外，还要存 ``d`` 与上一步的 (参数, 梯度) 快照

        否则「存档 → 续训」的第二步会拿不到 ``p_prev``，``d`` 也就无法按
        同一套规则调整，续训结果不可能与不间断训练逐位一致。
        """
        blob = _LayerwiseOptimizer.state_dict(self)
        blob["d"] = self.d
        blob["p_prev"] = _w9_copy(self._p_prev)
        blob["g_prev"] = _w9_copy(self._g_prev)
        return blob

    def load_state_dict(self, blob):
        _LayerwiseOptimizer.load_state_dict(self, blob)
        if "d" in blob:
            self.d = min(max(float(blob["d"]), self.d_min), self.d_max)
        if blob.get("p_prev") is not None:
            self._p_prev = _w9_copy(blob["p_prev"])
        if blob.get("g_prev") is not None:
            self._g_prev = _w9_copy(blob["g_prev"])
        return self

    def _update_layer(self, layer, grad_w, grad_b, st_w, st_b, idx):
        lr = self.lr * self.d
        b1, b2, eps, wd = self.beta1, self.beta2, self.eps, self.weight_decay
        for kind, param, grad, st in (("w", layer.weights, grad_w, st_w),
                                      ("b", layer.biases, grad_b, st_b)):
            m, v = st["m"], st["v"]
            if kind == "w":
                for j in range(layer.fan_out):
                    pj, gpj, mj, vj = param[j], grad[j], m[j], v[j]
                    for i in range(len(pj)):
                        g = gpj[i] + wd * pj[i]
                        mj[i] = b1 * mj[i] + (1.0 - b1) * g
                        vj[i] = b2 * vj[i] + (1.0 - b2) * g * g
                        pj[i] -= lr * mj[i] / (math.sqrt(vj[i]) + eps)
            else:
                for i in range(len(param)):
                    g = grad[i] + wd * param[i]
                    m[i] = b1 * m[i] + (1.0 - b1) * g
                    v[i] = b2 * v[i] + (1.0 - b2) * g * g
                    param[i] -= lr * m[i] / (math.sqrt(v[i]) + eps)



class CAME(_LayerwiseOptimizer):
    """CAME（2023）：置信度引导的因子化二阶矩（Adafactor 思路 + 不稳定维校正）

    - 二阶矩按「行 / 列」各自累计再组合：``v_ij = r_i·c_j / mean(r)``，权重状态
      因此是 O(m+n) 而不是 O(mn)；
    - **除以 ``mean(r)`` 是关键**：不做这步，``sqrt(r·c)`` 只有 ``|g|²`` 量级，
      ``m/sqrt(v)`` 会被放大 ``1/|g|`` 倍，小梯度处直接失控（实测参数飞到 1e3 量级）；
    - **不稳定维校正**：``u = |g| / sqrt(v + eps)`` 若超过 ``clip_threshold``，
      就把该位置的 ``v`` 按 ``(u/thr)²`` 放大 —— 等价于对因子化误差大的位置收缩步长；
    - 一阶矩用 ``beta1``，行/列因子分别用 ``beta2``/``beta3``；偏置退回标量形式。

    这是教学版：真正的 CAME 还有不确定性权重与逐块归一化，这里只保留
    「因子化 + 置信度校正」两个核心机制，README 里如实标注边界。
    """

    name = "came"

    def __init__(self, model, lr=2e-4, beta1=0.9, beta2=0.999, beta3=0.9999,
                 eps=1e-30, clip_threshold=1.0, weight_decay=0.0):
        _w9_check("CAME", lr, betas=(("beta1", beta1), ("beta2", beta2),
                                     ("beta3", beta3)), eps=eps)
        _w9b_check("CAME", "weight_decay", weight_decay, 0.0)
        if not _is_num(clip_threshold) or float(clip_threshold) <= 0.0:
            raise ValueError(
                f"CAME: clip_threshold 必须是正数，收到 {clip_threshold!r}")
        _LayerwiseOptimizer.__init__(self, model, lr)
        self.beta1 = float(beta1)
        self.beta2 = float(beta2)
        self.beta3 = float(beta3)
        self.eps = float(eps)
        self.clip_threshold = float(clip_threshold)
        self.weight_decay = float(weight_decay)

    def _new_state(self, layer, kind):
        if kind == "w":
            return {"m": _w9_zeros(layer, "w"),
                    "r": [0.0] * layer.fan_out,
                    "c": [0.0] * layer.fan_in}
        return {"m": _w9_zeros(layer, "b"), "v": _w9_zeros(layer, "b")}

    def _check_state_field(self, key, field, arr, layer, kind):
        """r 是长度 fan_out 的向量、c 是长度 fan_in 的向量，其余按基类矩阵校验"""
        if kind == "w" and field == "r":
            _w9_check_state(arr, layer, "b", f"{self.name}.load_state_dict[{key}.r]")
            return
        if kind == "w" and field == "c":
            if not isinstance(arr, list) or len(arr) != layer.fan_in:
                raise ValueError(
                    f"{self.name}.load_state_dict[{key}.c]: 长度必须是 "
                    f"fan_in={layer.fan_in}")
            for v in arr:
                if not _is_num(v):
                    raise ValueError(
                        f"{self.name}.load_state_dict[{key}.c]: 有非数字 {v!r}")
            return
        _w9_check_state(arr, layer, kind, f"{self.name}.load_state_dict[{key}.{field}]")

    def _update_layer(self, layer, grad_w, grad_b, st_w, st_b, idx):
        lr, b1, b2, b3 = self.lr, self.beta1, self.beta2, self.beta3
        eps, wd, thr = self.eps, self.weight_decay, self.clip_threshold
        m, r, c = st_w["m"], st_w["r"], st_w["c"]
        n_out, n_in = layer.fan_out, layer.fan_in

        # 第一遍：带上 weight decay 的梯度、行/列均值、两个因子的 EMA
        gmat = [[0.0] * n_in for _ in range(n_out)]
        col_sum = [0.0] * n_in
        for j in range(n_out):
            Wj, gwj = layer.weights[j], grad_w[j]
            row_sum = 0.0
            for i in range(n_in):
                g = gwj[i] + wd * Wj[i]
                gmat[j][i] = g
                row_sum += g * g
                col_sum[i] += g * g
            row_mean = row_sum / n_in
            r[j] = b2 * r[j] + (1.0 - b2) * row_mean
        for i in range(n_in):
            col_mean = col_sum[i] / n_out
            c[i] = b3 * c[i] + (1.0 - b3) * col_mean
        r_mean = sum(r) / n_out

        # 第二遍：按 v_ij = r_i*c_j/mean(r) 更新
        for j in range(n_out):
            Wj, mj = layer.weights[j], m[j]
            for i in range(n_in):
                g = gmat[j][i]
                mj[i] = b1 * mj[i] + (1.0 - b1) * g
                v = r[j] * c[i] / r_mean + eps if r_mean > 0.0 else eps
                u = abs(g) / math.sqrt(v)
                if u > thr:
                    v *= (u / thr) ** 2
                Wj[i] -= lr * mj[i] / math.sqrt(v)

        mb, vb = st_b["m"], st_b["v"]
        for j in range(layer.fan_out):
            g = grad_b[j] + wd * layer.biases[j]
            mb[j] = b1 * mb[j] + (1.0 - b1) * g
            vb[j] = b2 * vb[j] + (1.0 - b2) * g * g
            layer.biases[j] -= lr * mb[j] / (math.sqrt(vb[j]) + eps)




# ==== 进阶优化器：Shampoo / Sophia / L-BFGS ====
#
# 这三个都需要「整层」的信息（矩阵逆根 / Hessian 对角 / 历史位移对），
# 因此同样挂在 `_LayerwiseOptimizer` 上；只支持二维 `Layer` 权重。


def _w9b_check_sq(arr, n, who):
    """校验一个 n×n 方阵状态字段（Shampoo 的 L / R）"""
    if not isinstance(arr, list) or len(arr) != n:
        got = len(arr) if isinstance(arr, list) else type(arr).__name__
        raise ValueError(f"{who}: 必须是 {n}×{n} 方阵，收到的行数是 {got}")
    for row in arr:
        if not isinstance(row, list) or len(row) != n:
            got = len(row) if isinstance(row, list) else type(row).__name__
            raise ValueError(f"{who}: 每行必须是长度 {n} 的列表，收到 {got}")
        for v in row:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f"{who}: 元素必须是数字，收到 {v!r}")


def _w9_sq_zeros(n):
    return [[0.0] * n for _ in range(n)]


def _mat_t(a):
    """转置（空矩阵返回空）"""
    if not a or not a[0]:
        return []
    return [[a[i][j] for i in range(len(a))] for j in range(len(a[0]))]


def _mat_mul(a, b):
    """普通矩阵乘（小矩阵；顺序固定即可，不做补偿求和）"""
    if not a or not b:
        return []
    n, k, m = len(a), len(b), len(b[0])
    out = [[0.0] * m for _ in range(n)]
    for i in range(n):
        ai = a[i]
        oi = out[i]
        for p in range(k):
            aip = ai[p]
            if aip == 0.0:
                continue
            bp = b[p]
            for j in range(m):
                oi[j] += aip * bp[j]
    return out


def _jacobi_eigh(a, tol=1e-12, max_sweeps=60):
    """对称矩阵的 Jacobi 特征分解，返回 ``(eigvals, V)``，列为特征向量

    只用标准库：循环 Jacobi（Gauss 旋转）。输入按上三角对称化——调用方只会传
    ``G Gᵀ`` 这种本来就对称的矩阵。
    """
    n = len(a)
    if n == 0:
        return [], []
    A = [[0.5 * (a[i][j] + a[j][i]) for j in range(n)] for i in range(n)]
    V = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    scale = max(1.0, max(abs(A[i][i]) for i in range(n)))
    for _ in range(max_sweeps):
        off = 0.0
        for i in range(n - 1):
            for j in range(i + 1, n):
                off += A[i][j] * A[i][j]
        if math.sqrt(off) <= tol * scale:
            break
        for p in range(n - 1):
            for q in range(p + 1, n):
                apq = A[p][q]
                if abs(apq) <= 1e-18 * scale:
                    continue
                theta = (A[q][q] - A[p][p]) / (2.0 * apq)
                t = (1.0 if theta >= 0.0 else -1.0) / (
                    abs(theta) + math.sqrt(theta * theta + 1.0))
                c = 1.0 / math.sqrt(t * t + 1.0)
                s = t * c
                for k in range(n):
                    akp, akq = A[k][p], A[k][q]
                    A[k][p] = c * akp - s * akq
                    A[k][q] = s * akp + c * akq
                for k in range(n):
                    apk, aqk = A[p][k], A[q][k]
                    A[p][k] = c * apk - s * aqk
                    A[q][k] = s * apk + c * aqk
                for k in range(n):
                    vkp, vkq = V[k][p], V[k][q]
                    V[k][p] = c * vkp - s * vkq
                    V[k][q] = s * vkp + c * vkq
    return [A[i][i] for i in range(n)], V


def _sym_inv_root4(m, eps=1e-12):
    """对称半正定矩阵的 ``M^{-1/4} = V diag(max(λ,eps)^{-1/4}) Vᵀ``"""
    n = len(m)
    if n == 0:
        return []
    vals, V = _jacobi_eigh(m)
    d = [max(v, eps) ** (-0.25) for v in vals]
    out = [[0.0] * n for _ in range(n)]
    for i in range(n):
        vi = V[i]
        oi = out[i]
        for j in range(n):
            vj = V[j]
            s = 0.0
            for k in range(n):
                s += vi[k] * d[k] * vj[k]
            oi[j] = s
    return out


class Shampoo(_LayerwiseOptimizer):
    """Shampoo（2018）：对每层梯度矩阵做 ``L^{-1/4} G R^{-1/4}`` 预条件

    ``L = Σ G Gᵀ``（fan_out × fan_out）、``R = Σ Gᵀ G``（fan_in × fan_in）是
    二阶矩的矩阵形式；逆 1/4 次根用 Jacobi 特征分解算（纯标准库）。

    工程折中（docstring 与 README 都写明）：
      * 维度超过 ``max_dim`` 的层退化成**逐元素** Adam 预条件（论文的 diagonal
        版本），否则 64 维以上的 Jacobi 会拖慢训练；
      * 没有实现论文的 grafting（把 Adam 更新范数嫁接回来），所以**lr 要自己给
        合适**；矩阵分支的 lr 与 Adam 分支不是同一量纲；
      * ``precondition_every`` 控制逆根重算频率（默认每步算一次，调大可省时间）。
    """

    name = "shampoo"

    def __init__(self, model, lr=1e-2, beta1=0.9, beta2=0.999, eps=1e-8,
                 precondition_every=1, max_dim=64, weight_decay=0.0):
        _w9_check("Shampoo", lr, betas=(("beta1", beta1), ("beta2", beta2)), eps=eps)
        _w9b_check("Shampoo", "weight_decay", weight_decay, 0.0)
        if isinstance(precondition_every, bool) or not isinstance(precondition_every, int):
            raise TypeError(f"Shampoo: precondition_every 必须是整数，收到 "
                            f"{type(precondition_every).__name__}")
        if precondition_every < 1:
            raise ValueError(
                f"Shampoo: precondition_every 必须 >= 1，收到 {precondition_every!r}")
        if isinstance(max_dim, bool) or not isinstance(max_dim, int):
            raise TypeError(f"Shampoo: max_dim 必须是整数，收到 {type(max_dim).__name__}")
        if max_dim < 1:
            raise ValueError(f"Shampoo: max_dim 必须 >= 1，收到 {max_dim!r}")
        _LayerwiseOptimizer.__init__(self, model, lr)
        self.beta1 = float(beta1)
        self.beta2 = float(beta2)
        self.eps = float(eps)
        self.precondition_every = precondition_every
        self.max_dim = max_dim
        self.weight_decay = float(weight_decay)
        self._inv = {}          # idx -> (L^{-1/4}, R^{-1/4})

    def _use_matrix(self, layer):
        return max(layer.fan_out, layer.fan_in) <= self.max_dim

    def _new_state(self, layer, kind):
        if kind == "w" and self._use_matrix(layer):
            return {"L": _w9_sq_zeros(layer.fan_out),
                    "R": _w9_sq_zeros(layer.fan_in)}
        return {"m": _w9_zeros(layer, kind), "v": _w9_zeros(layer, kind)}

    def _check_state_field(self, key, field, arr, layer, kind):
        if field == "L":
            _w9b_check_sq(arr, layer.fan_out,
                          f"{self.name}.load_state_dict[{key}.L]")
            return
        if field == "R":
            _w9b_check_sq(arr, layer.fan_in,
                          f"{self.name}.load_state_dict[{key}.R]")
            return
        _w9_check_state(arr, layer, kind,
                        f"{self.name}.load_state_dict[{key}.{field}]")

    def load_state_dict(self, blob):
        _LayerwiseOptimizer.load_state_dict(self, blob)
        self._inv = {}
        return self

    def _bias_corr(self):
        t = self.step_count
        return (1.0 - self.beta1 ** t, 1.0 - self.beta2 ** t)

    def _update_layer(self, layer, grad_w, grad_b, st_w, st_b, idx):
        n, k = layer.fan_out, layer.fan_in
        wd = self.weight_decay
        c1, c2 = self._bias_corr()
        if "L" in st_w:
            L, R = st_w["L"], st_w["R"]
            G = [[grad_w[i][j] + wd * layer.weights[i][j] for j in range(k)]
                 for i in range(n)]
            for a in range(n):
                La, Ga = L[a], G[a]
                for b in range(a, n):
                    Gb = G[b]
                    s = 0.0
                    for j in range(k):
                        s += Ga[j] * Gb[j]
                    La[b] += s
                    L[b][a] = La[b]
            for a in range(k):
                Ra = R[a]
                for b in range(a, k):
                    s = 0.0
                    for i in range(n):
                        s += G[i][a] * G[i][b]
                    Ra[b] += s
                    R[b][a] = Ra[b]
            if idx not in self._inv or (self.step_count - 1) % self.precondition_every == 0:
                self._inv[idx] = (_sym_inv_root4(L, self.eps),
                                  _sym_inv_root4(R, self.eps))
            Li, Ri = self._inv[idx]
            U = _mat_mul(_mat_mul(Li, G), Ri)
            for i in range(n):
                Wi, Ui = layer.weights[i], U[i]
                for j in range(k):
                    Wi[j] -= self.lr * Ui[j]
        else:
            m, v = st_w["m"], st_w["v"]
            for i in range(n):
                Wi, gi, mi, vi = layer.weights[i], grad_w[i], m[i], v[i]
                for j in range(k):
                    g = gi[j] + wd * Wi[j]
                    mi[j] = self.beta1 * mi[j] + (1.0 - self.beta1) * g
                    vi[j] = self.beta2 * vi[j] + (1.0 - self.beta2) * g * g
                    Wi[j] -= self.lr * (mi[j] / c1) / (
                        math.sqrt(vi[j] / c2) + self.eps)

        mb, vb = st_b["m"], st_b["v"]
        for j in range(n):
            g = grad_b[j]
            mb[j] = self.beta1 * mb[j] + (1.0 - self.beta1) * g
            vb[j] = self.beta2 * vb[j] + (1.0 - self.beta2) * g * g
            layer.biases[j] -= self.lr * (mb[j] / c1) / (
                math.sqrt(vb[j] / c2) + self.eps)


class Sophia(_LayerwiseOptimizer):
    """Sophia-G（2023）：按曲率裁剪动量后再更新

    更新式：``p -= lr · clip(m / max(rho·h, eps), -1, 1)``。``h`` 是曲率对角；
    标准 Sophia 要用 Hessian-vector product（Hutchinson 估计）来维护它，而本库的
    层接口只拿得到一阶梯度，因此：

      * 默认 ``h ← β2·h + (1-β2)·g²``（Gauss-Newton 对角的廉价近似，即
        Sophia-G）。**这不等于真 Hessian**，docstring 与 README 都如实标注；
      * 需要更准的曲率时传 ``hessian_fn``（签名 ``hessian_fn(层号, 层)``，返回与
        权重同形状的对角估计，``None`` 表示该层退回 ``g²`` 近似）；
      * 也可以直接调 ``step(grads, hessian_diags=[(权重对角, 偏置对角), ...])``。

    ``clip`` 让每个元素一步最多走 ``lr``，所以 lr 是**步长上限**而不是学习率。
    """

    name = "sophia"

    def __init__(self, model, lr=1e-3, beta1=0.9, beta2=0.999, rho=0.04,
                 eps=1e-8, weight_decay=0.0, hessian_fn=None):
        _w9_check("Sophia", lr, betas=(("beta1", beta1), ("beta2", beta2)), eps=eps)
        _w9b_check("Sophia", "weight_decay", weight_decay, 0.0)
        if isinstance(rho, bool) or not isinstance(rho, (int, float)) or float(rho) <= 0.0:
            raise ValueError(f"Sophia: rho 必须是正数，收到 {rho!r}")
        if hessian_fn is not None and not callable(hessian_fn):
            raise TypeError("Sophia: hessian_fn 必须可调用（或 None）")
        _LayerwiseOptimizer.__init__(self, model, lr)
        self.beta1 = float(beta1)
        self.beta2 = float(beta2)
        self.rho = float(rho)
        self.eps = float(eps)
        self.weight_decay = float(weight_decay)
        self.hessian_fn = hessian_fn
        self._h_ext = None

    def _new_state(self, layer, kind):
        return {"m": _w9_zeros(layer, kind), "h": _w9_zeros(layer, kind)}

    def step(self, all_grads, hessian_diags=None):
        """``hessian_diags``：可选的逐层曲率对角（形如 ``[(对角_w, 对角_b), ...]``）"""
        self._h_ext = hessian_diags
        try:
            return _LayerwiseOptimizer.step(self, all_grads)
        finally:
            self._h_ext = None

    def _curvature(self, idx, layer, kind):
        """显式入参 > ``hessian_fn`` > ``None``（None 表示退回 ``g²`` 近似）"""
        if self._h_ext is not None:
            ext = self._h_ext[idx][0 if kind == "w" else 1]
            if ext is not None:
                return ext
        if self.hessian_fn is not None:
            ext = self.hessian_fn(idx, layer)
            if ext is not None:
                return ext
        return None

    def _update_layer(self, layer, grad_w, grad_b, st_w, st_b, idx):
        n, k = layer.fan_out, layer.fan_in
        wd = self.weight_decay
        b1, b2, rho, eps = self.beta1, self.beta2, self.rho, self.eps

        h_ext = self._curvature(idx, layer, "w")
        m, h = st_w["m"], st_w["h"]
        for i in range(n):
            Wi, gi = layer.weights[i], grad_w[i]
            mi, hi = m[i], h[i]
            he = h_ext[i] if h_ext is not None else None
            for j in range(k):
                g = gi[j] + wd * Wi[j]
                mi[j] = b1 * mi[j] + (1.0 - b1) * g
                if he is not None:
                    hi[j] = b2 * hi[j] + (1.0 - b2) * he[j]
                else:
                    hi[j] = b2 * hi[j] + (1.0 - b2) * g * g
                u = mi[j] / max(rho * hi[j], eps)
                if u > 1.0:
                    u = 1.0
                elif u < -1.0:
                    u = -1.0
                Wi[j] -= self.lr * u

        hb_ext = self._curvature(idx, layer, "b")
        mb, hb = st_b["m"], st_b["h"]
        for j in range(n):
            g = grad_b[j]
            mb[j] = b1 * mb[j] + (1.0 - b1) * g
            if hb_ext is not None:
                hb[j] = b2 * hb[j] + (1.0 - b2) * hb_ext[j]
            else:
                hb[j] = b2 * hb[j] + (1.0 - b2) * g * g
            u = mb[j] / max(rho * hb[j], eps)
            if u > 1.0:
                u = 1.0
            elif u < -1.0:
                u = -1.0
            layer.biases[j] -= self.lr * u


def _lb_flat_w(weights):
    out = []
    for row in weights:
        out.extend(row)
    return out


def _lb_write_w(weights, flat):
    p = 0
    for row in weights:
        for j in range(len(row)):
            row[j] = flat[p]
            p += 1


def _lb_two_loop(g, pairs, gamma):
    """L-BFGS 两循环递归，返回 ``H g``（pairs 按时间升序、元素是扁平列表）"""
    q = list(g)
    alphas = []
    for s, y in reversed(pairs):
        sy = 0.0
        for a, b in zip(s, y):
            sy += a * b
        if sy <= 0.0:
            alphas.append(0.0)
            continue
        a_i = 0.0
        for qi, si in zip(q, s):
            a_i += qi * si
        a_i /= sy
        alphas.append(a_i)
        for j in range(len(q)):
            q[j] -= a_i * y[j]
    for j in range(len(q)):
        q[j] *= gamma
    for (s, y), a_i in zip(pairs, reversed(alphas)):
        sy = 0.0
        for a, b in zip(s, y):
            sy += a * b
        if sy <= 0.0:
            continue
        beta = 0.0
        for qj, yj in zip(q, y):
            beta += qj * yj
        beta /= sy
        for j in range(len(q)):
            q[j] += s[j] * (a_i - beta)
    return q


class LBFGS(_LayerwiseOptimizer):
    """L-BFGS（有限内存拟牛顿）：两循环递归算方向，**固定步长、无 line search**

    本库的优化器接口按层更新，所以历史位移对是**逐层**保存的——等价于一个块对角
    L-BFGS，而不是全局那一个。每层：

        s_k = x_k - x_{k-1},  y_k = g_k - g_{k-1},  H₀ = (s·y)/(y·y)·I
        d = -H g（两循环递归），x ← x + lr·d

    曲率条件 ``s·y > eps`` 不满足时丢弃该对（标准保护，避免 H 非正定）。

    已知边界（docstring 与 README 都写明）：
      * 没有 line search，``lr`` 要自己调小（默认 0.1 已比 SGD 小一个量级）；
      * 逐层分块会忽略跨层耦合，比真 L-BFGS 弱、比 SGD 强；
      * 不支持 ``line_search_fn``（没有目标函数闭包可用）。
    """

    name = "lbfgs"

    def __init__(self, model, lr=0.1, history_size=10, eps=1e-12, weight_decay=0.0):
        _w9_check("LBFGS", lr)
        _w9b_check("LBFGS", "weight_decay", weight_decay, 0.0)
        _w9b_check("LBFGS", "eps", eps, 0.0)
        if isinstance(history_size, bool) or not isinstance(history_size, int):
            raise TypeError(f"LBFGS: history_size 必须是整数，收到 "
                            f"{type(history_size).__name__}")
        if history_size < 1:
            raise ValueError(f"LBFGS: history_size 必须 >= 1，收到 {history_size!r}")
        _LayerwiseOptimizer.__init__(self, model, lr)
        self.history_size = history_size
        self.eps = float(eps)
        self.weight_decay = float(weight_decay)

    def _new_state(self, layer, kind):
        base = _w9_zeros(layer, kind)
        flat = _lb_flat_w(base) if kind == "w" else list(base)
        return {"s": [], "y": [], "prev_p": list(flat), "prev_g": list(flat)}

    def _check_state_field(self, key, field, arr, layer, kind):
        who = f"{self.name}.load_state_dict[{key}.{field}]"
        want = layer.fan_out * layer.fan_in if kind == "w" else layer.fan_out
        if field in ("s", "y"):
            if not isinstance(arr, list):
                raise ValueError(f"{who}: 必须是列表，收到 {type(arr).__name__}")
            for item in arr:
                if not isinstance(item, list) or len(item) != want:
                    raise ValueError(f"{who}: 每个位移对必须是长度 {want} 的扁平列表")
                for v in item:
                    if isinstance(v, bool) or not isinstance(v, (int, float)):
                        raise ValueError(f"{who}: 元素必须是数字，"
                                         f"收到 {type(v).__name__}")
            return
        if field in ("prev_p", "prev_g"):
            if not isinstance(arr, list) or len(arr) != want:
                raise ValueError(f"{who}: 必须是长度 {want} 的扁平列表")
            for v in arr:
                if isinstance(v, bool) or not isinstance(v, (int, float)):
                    raise ValueError(f"{who}: 元素必须是数字，收到 {type(v).__name__}")
            return
        _w9_check_state(arr, layer, kind, who)

    def _update_layer(self, layer, grad_w, grad_b, st_w, st_b, idx):
        wd = self.weight_decay
        n, k = layer.fan_out, layer.fan_in

        g = []
        for i in range(n):
            Wi, gi = layer.weights[i], grad_w[i]
            g.extend(gi[j] + wd * Wi[j] for j in range(k))
        p = _lb_flat_w(layer.weights)
        self._advance(g, p, st_w)
        _lb_write_w(layer.weights, p)

        gb = [grad_b[j] for j in range(n)]
        pb = list(layer.biases)
        self._advance(gb, pb, st_b)
        layer.biases[:] = pb

    def _advance(self, g, p, st):
        """推进一层：用上一步位移对更新历史 → 两循环算方向 → 原地改 ``p``"""
        prev_g = st["prev_g"]
        prev_p = st["prev_p"]
        s = [p[j] - prev_p[j] for j in range(len(p))]
        y = [g[j] - prev_g[j] for j in range(len(p))]
        sy = 0.0
        yy = 0.0
        for a, b in zip(s, y):
            sy += a * b
            yy += b * b
        if self.step_count > 1 and sy > self.eps and yy > 0.0:
            st["s"].append(s)
            st["y"].append(y)
            if len(st["s"]) > self.history_size:
                st["s"].pop(0)
                st["y"].pop(0)
        pairs = list(zip(st["s"], st["y"]))
        gamma = 1.0
        if pairs:
            s_last, y_last = pairs[-1]
            sy_last = 0.0
            yy_last = 0.0
            for a, b in zip(s_last, y_last):
                sy_last += a * b
                yy_last += b * b
            if yy_last > 0.0:
                gamma = sy_last / yy_last
        d = _lb_two_loop(g, pairs, gamma)
        before = [p[j] for j in range(len(p))]
        for j in range(len(p)):
            p[j] -= self.lr * d[j]
        st["prev_g"] = list(g)
        st["prev_p"] = before
# ============================================================================
#  Gradient Clipping / LR Scheduler
# ============================================================================

def clip_grad_by_norm(all_grads, max_norm: float):
    """按范数裁剪梯度，防止梯度爆炸（适用于 RNN/LSTM/GRU）"""
    if max_norm is None or max_norm <= 0:
        # 负阈值会把所有梯度乘上负数，等于整体翻转符号
        raise ValueError(f"clip_grad_by_norm: max_norm 必须 > 0，收到 {max_norm!r}")
    total_sq = 0.0
    for gw, gb in all_grads:
        for row in gw:
            for g in row:
                total_sq += g * g
        for g in gb:
            total_sq += g * g
    total_norm = math.sqrt(total_sq)
    if total_norm > max_norm:
        scale = max_norm / total_norm
        for gw, gb in all_grads:
            for j in range(len(gw)):
                for i in range(len(gw[j])):
                    gw[j][i] *= scale
                gb[j] *= scale
    return total_norm


def clip_grad_by_value(all_grads, clip_val: float):
    """按值裁剪梯度"""
    if clip_val is None or clip_val < 0:
        raise ValueError(f"clip_grad_by_value: clip_val 必须 >= 0，收到 {clip_val!r}")
    for gw, gb in all_grads:
        for j in range(len(gw)):
            for i in range(len(gw[j])):
                gw[j][i] = max(-clip_val, min(clip_val, gw[j][i]))
            gb[j] = max(-clip_val, min(clip_val, gb[j]))


# ==== 学习率调度器族 ====
# 约定：epoch 从 1 开始（`Model.fit` 就是这么调的）；`step(epoch)` 直接赋值
# `optimizer.lr`，因此调度器之间可以互相嵌套（`ChainedScheduler` / `SequentialLR`）。


def _sched_epoch(epoch, who):
    """规范化 epoch：整数且 >= 1"""
    if isinstance(epoch, bool) or not isinstance(epoch, int):
        raise ValueError(f"{who}: epoch 必须是整数，收到 {epoch!r}")
    return max(epoch, 1)


def _sched_check(who, name, value, minimum=None, maximum=None):
    """校验调度器的超参：有限数字 + 可选上下界（bool 不算数字）"""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{who}: {name} 必须是数字，收到 {value!r}")
    v = float(value)
    if v != v or v in (float("inf"), float("-inf")):
        raise ValueError(f"{who}: {name} 必须是有限数字，收到 {value!r}")
    if minimum is not None and v < minimum:
        raise ValueError(f"{who}: {name} 必须 >= {minimum}，收到 {value!r}")
    if maximum is not None and v > maximum:
        raise ValueError(f"{who}: {name} 必须 <= {maximum}，收到 {value!r}")
    return v


class LambdaLR:
    """``lr = initial_lr * lr_lambda(epoch)``（PyTorch `LambdaLR`）

    `lr_lambda` 收到 1 起算的 epoch，返回值必须是非负有限数字。
    """

    def __init__(self, optimizer, lr_lambda):
        if not callable(lr_lambda):
            raise ValueError(f"LambdaLR: lr_lambda 必须可调用，收到 {lr_lambda!r}")
        self.optimizer = optimizer
        self.lr_lambda = lr_lambda
        self.initial_lr = optimizer.lr

    def step(self, epoch: int):
        epoch = _sched_epoch(epoch, "LambdaLR")
        factor = self.lr_lambda(epoch)
        factor = _sched_check("LambdaLR", "lr_lambda(epoch)", factor, minimum=0.0)
        self.optimizer.lr = self.initial_lr * factor


class MultiplicativeLR:
    """``lr *= lr_lambda(epoch)``（累积式，PyTorch `MultiplicativeLR`）

    与 `LambdaLR` 的区别：基准是**当前** lr 而不是初始 lr，所以多次调用会连乘。
    """

    def __init__(self, optimizer, lr_lambda):
        if not callable(lr_lambda):
            raise ValueError(
                f"MultiplicativeLR: lr_lambda 必须可调用，收到 {lr_lambda!r}")
        self.optimizer = optimizer
        self.lr_lambda = lr_lambda
        self.initial_lr = optimizer.lr

    def step(self, epoch: int):
        epoch = _sched_epoch(epoch, "MultiplicativeLR")
        factor = _sched_check("MultiplicativeLR", "lr_lambda(epoch)",
                              self.lr_lambda(epoch), minimum=0.0)
        self.optimizer.lr = self.optimizer.lr * factor


class MultiStepLR:
    """到 `milestones` 里的轮次就把 lr 乘一次 `gamma`（PyTorch `MultiStepLR`）

    ``lr = initial_lr * gamma ** (#{m in milestones : m <= epoch})``
    """

    def __init__(self, optimizer, milestones, gamma: float = 0.1):
        if isinstance(milestones, (int, float)) and not isinstance(milestones, bool):
            milestones = [milestones]
        if not isinstance(milestones, (list, tuple)) or not milestones:
            raise ValueError(f"MultiStepLR: milestones 必须是非空列表，收到 {milestones!r}")
        clean = []
        for m in milestones:
            if isinstance(m, bool) or not isinstance(m, int) or m < 1:
                raise ValueError(f"MultiStepLR: milestones 里的每项必须是 >=1 的整数，收到 {m!r}")
            clean.append(int(m))
        if sorted(clean) != clean or len(set(clean)) != len(clean):
            raise ValueError(f"MultiStepLR: milestones 必须严格递增，收到 {milestones!r}")
        g = _sched_check("MultiStepLR", "gamma", gamma, minimum=0.0)
        self.optimizer = optimizer
        self.milestones = list(clean)
        self.gamma = g
        self.initial_lr = optimizer.lr

    def step(self, epoch: int):
        epoch = _sched_epoch(epoch, "MultiStepLR")
        hits = sum(1 for m in self.milestones if m <= epoch)
        self.optimizer.lr = self.initial_lr * (self.gamma ** hits)


class CosineAnnealingWarmRestarts:
    """余弦退火 + 周期重启（PyTorch `CosineAnnealingWarmRestarts`）

    第 k 个周期长度 `T_0 * T_mult**k`；周期内按余弦从 `initial_lr` 退到 `eta_min`，
    周期**最后一轮**正好落在 `eta_min`（分母用 `T_i-1`，与 `CosineAnnealingLR` 一致）。
    """

    def __init__(self, optimizer, T_0: int = 10, T_mult: int = 1,
                 eta_min: float = 0.0):
        if isinstance(T_0, bool) or not isinstance(T_0, int) or T_0 < 1:
            raise ValueError(f"CosineAnnealingWarmRestarts: T_0 必须是 >=1 的整数，收到 {T_0!r}")
        if isinstance(T_mult, bool) or not isinstance(T_mult, int) or T_mult < 1:
            raise ValueError(
                f"CosineAnnealingWarmRestarts: T_mult 必须是 >=1 的整数，收到 {T_mult!r}")
        eta = _sched_check("CosineAnnealingWarmRestarts", "eta_min", eta_min, minimum=0.0)
        self.optimizer = optimizer
        self.T_0 = int(T_0)
        self.T_mult = int(T_mult)
        self.eta_min = eta
        self.initial_lr = optimizer.lr

    def cycle_of(self, epoch: int):
        """返回 (周期序号 k, 周期长度 T_k, 周期内位置 pos[1..T_k])"""
        epoch = _sched_epoch(epoch, "CosineAnnealingWarmRestarts")
        k, start, length = 0, 1, self.T_0
        while epoch >= start + length:
            start += length
            k += 1
            length = self.T_0 * (self.T_mult ** k)
        return k, length, epoch - start + 1

    def step(self, epoch: int):
        _k, length, pos = self.cycle_of(epoch)
        progress = 1.0 if length == 1 else (pos - 1) / (length - 1)
        self.optimizer.lr = self.eta_min + 0.5 * (self.initial_lr - self.eta_min) * (
            1 + math.cos(math.pi * progress))


class CyclicLR:
    """三角循环学习率（PyTorch `CyclicLR` 的三个 mode）

    `mode`：
      - `triangular`：每个周期振幅相同
      - `triangular2`：第 k 个周期振幅除以 `2**k`
      - `exp_range`：振幅乘以 `gamma**pos`

    一个周期 = `step_size_up` 轮上升 + `step_size_up` 轮下降。
    """

    MODES = ("triangular", "triangular2", "exp_range")

    def __init__(self, optimizer, base_lr: float, max_lr: float,
                 step_size_up: int = 2, mode: str = "triangular",
                 gamma: float = 1.0):
        if mode not in self.MODES:
            raise ValueError(f"CyclicLR: mode 只能是 {self.MODES}，收到 {mode!r}")
        base = _sched_check("CyclicLR", "base_lr", base_lr, minimum=0.0)
        top = _sched_check("CyclicLR", "max_lr", max_lr, minimum=0.0)
        if top < base:
            raise ValueError(f"CyclicLR: max_lr({max_lr!r}) 不能小于 base_lr({base_lr!r})")
        if isinstance(step_size_up, bool) or not isinstance(step_size_up, int) or step_size_up < 1:
            raise ValueError(f"CyclicLR: step_size_up 必须是 >=1 的整数，收到 {step_size_up!r}")
        g = _sched_check("CyclicLR", "gamma", gamma, minimum=0.0)
        self.optimizer = optimizer
        self.base_lr = base
        self.max_lr = top
        self.step_size_up = int(step_size_up)
        self.mode = mode
        self.gamma = g
        self.initial_lr = optimizer.lr

    def step(self, epoch: int):
        epoch = _sched_epoch(epoch, "CyclicLR")
        up = self.step_size_up
        period = 2 * up
        pos = (epoch - 1) % period
        cycle = (epoch - 1) // period
        frac = pos / up if pos <= up else (period - pos) / up
        if self.mode == "triangular":
            scale = frac
        elif self.mode == "triangular2":
            scale = frac / (2.0 ** cycle)
        else:
            scale = frac * (self.gamma ** pos)
        self.optimizer.lr = self.base_lr + (self.max_lr - self.base_lr) * scale


class OneCycleLR:
    """单周期学习率（PyTorch `OneCycleLR`，余弦版）

    前 `pct_start` 段从 `max_lr/div_factor` 升到 `max_lr`，之后按余弦降到
    `max_lr/div_factor/final_div_factor`。
    """

    def __init__(self, optimizer, max_lr: float, total_epochs: int,
                 pct_start: float = 0.3, div_factor: float = 25.0,
                 final_div_factor: float = 1e4):
        top = _sched_check("OneCycleLR", "max_lr", max_lr, minimum=0.0)
        if isinstance(total_epochs, bool) or not isinstance(total_epochs, int)                 or total_epochs < 1:
            raise ValueError(
                f"OneCycleLR: total_epochs 必须是 >=1 的整数，收到 {total_epochs!r}")
        pct = _sched_check("OneCycleLR", "pct_start", pct_start, minimum=0.0, maximum=1.0)
        dv = _sched_check("OneCycleLR", "div_factor", div_factor, minimum=1.0)
        fdv = _sched_check("OneCycleLR", "final_div_factor", final_div_factor, minimum=1.0)
        self.optimizer = optimizer
        self.max_lr = top
        self.total_epochs = int(total_epochs)
        self.pct_start = pct
        self.div_factor = dv
        self.final_div_factor = fdv
        self.initial_lr = optimizer.lr
        self._start_lr = top / dv
        self._end_lr = top / dv / fdv

    def step(self, epoch: int):
        epoch = _sched_epoch(epoch, "OneCycleLR")
        pos = min(epoch, self.total_epochs) / self.total_epochs
        if pos <= self.pct_start and self.pct_start > 0.0:
            frac = pos / self.pct_start
            lr = self._start_lr + (self.max_lr - self._start_lr) * 0.5 * (
                1 - math.cos(math.pi * frac))
        else:
            span = max(1e-12, 1.0 - self.pct_start)
            frac = min(1.0, (pos - self.pct_start) / span)
            lr = self._end_lr + (self.max_lr - self._end_lr) * 0.5 * (
                1 + math.cos(math.pi * frac))
        self.optimizer.lr = lr


class InverseSqrtLR:
    """反平方根衰减（Transformer 论文的副产物，实践中很稳）

    有 warmup 时：`epoch <= warmup` 线性升到 `initial_lr`；
    之后 `lr = initial_lr * sqrt(warmup / epoch)`。
    无 warmup（`warmup_epochs=0`）时：`lr = initial_lr / sqrt(epoch)`。
    """

    def __init__(self, optimizer, warmup_epochs: int = 0, start_factor: float = 0.1):
        if isinstance(warmup_epochs, bool) or not isinstance(warmup_epochs, int)                 or warmup_epochs < 0:
            raise ValueError(
                f"InverseSqrtLR: warmup_epochs 必须是 >=0 的整数，收到 {warmup_epochs!r}")
        sf = _sched_check("InverseSqrtLR", "start_factor", start_factor,
                          minimum=0.0, maximum=1.0)
        self.optimizer = optimizer
        self.warmup_epochs = int(warmup_epochs)
        self.start_factor = sf
        self.initial_lr = optimizer.lr

    def step(self, epoch: int):
        epoch = _sched_epoch(epoch, "InverseSqrtLR")
        if self.warmup_epochs > 0 and epoch <= self.warmup_epochs:
            frac = epoch / self.warmup_epochs
            self.optimizer.lr = self.initial_lr * (
                self.start_factor + (1.0 - self.start_factor) * frac)
            return
        base = max(1, epoch)
        scale = 1.0 / math.sqrt(base)
        if self.warmup_epochs > 0:
            scale = math.sqrt(self.warmup_epochs / base)
        self.optimizer.lr = self.initial_lr * scale


class NoamLR:
    """Transformer 原论文的学习率：``d_model^-0.5 · min(epoch^-0.5, epoch·warmup^-1.5)``

    注意：这个公式**自带绝对量纲**，会直接覆盖 `optimizer.lr`（与 `initial_lr` 无关）。
    """

    def __init__(self, optimizer, d_model: int, warmup_epochs: int = 100):
        if isinstance(d_model, bool) or not isinstance(d_model, int) or d_model < 1:
            raise ValueError(f"NoamLR: d_model 必须是 >=1 的整数，收到 {d_model!r}")
        if isinstance(warmup_epochs, bool) or not isinstance(warmup_epochs, int)                 or warmup_epochs < 1:
            raise ValueError(
                f"NoamLR: warmup_epochs 必须是 >=1 的整数，收到 {warmup_epochs!r}")
        self.optimizer = optimizer
        self.d_model = int(d_model)
        self.warmup_epochs = int(warmup_epochs)
        self.initial_lr = optimizer.lr

    def step(self, epoch: int):
        epoch = _sched_epoch(epoch, "NoamLR")
        scale = (self.d_model ** -0.5) * min(epoch ** -0.5,
                                             epoch * (self.warmup_epochs ** -1.5))
        self.optimizer.lr = scale


class PolynomialLR:
    """多项式衰减：``(initial_lr - min_lr)·(1 - epoch/total)^power + min_lr``"""

    def __init__(self, optimizer, total_epochs: int, power: float = 1.0,
                 min_lr: float = 0.0):
        if isinstance(total_epochs, bool) or not isinstance(total_epochs, int)                 or total_epochs < 1:
            raise ValueError(
                f"PolynomialLR: total_epochs 必须是 >=1 的整数，收到 {total_epochs!r}")
        p = _sched_check("PolynomialLR", "power", power, minimum=0.0)
        low = _sched_check("PolynomialLR", "min_lr", min_lr, minimum=0.0)
        self.optimizer = optimizer
        self.total_epochs = int(total_epochs)
        self.power = p
        self.min_lr = low
        self.initial_lr = optimizer.lr

    def step(self, epoch: int):
        epoch = _sched_epoch(epoch, "PolynomialLR")
        frac = min(1.0, epoch / self.total_epochs)
        self.optimizer.lr = (self.initial_lr - self.min_lr) * (
            (1.0 - frac) ** self.power) + self.min_lr


class WSDLR:
    """Warmup-Stable-Decay：线性 warmup → 恒定 → 尾部衰减

    `decay_epochs` 缺省时取 `max(1, total_epochs // 10)`；
    `decay_shape` 支持 `'linear'` 与 `'cos'`（cos 更平滑，线性更省算）。
    """

    SHAPES = ("linear", "cos")

    def __init__(self, optimizer, warmup_epochs: int = 1, total_epochs: int = 10,
                 decay_epochs: int = None, min_lr: float = 0.0,
                 decay_shape: str = "cos"):
        if isinstance(warmup_epochs, bool) or not isinstance(warmup_epochs, int)                 or warmup_epochs < 0:
            raise ValueError(
                f"WSDLR: warmup_epochs 必须是 >=0 的整数，收到 {warmup_epochs!r}")
        if isinstance(total_epochs, bool) or not isinstance(total_epochs, int)                 or total_epochs < 2:
            raise ValueError(
                f"WSDLR: total_epochs 必须是 >=2 的整数，收到 {total_epochs!r}")
        if decay_epochs is None:
            decay_epochs = max(1, total_epochs // 10)
        if isinstance(decay_epochs, bool) or not isinstance(decay_epochs, int)                 or decay_epochs < 1:
            raise ValueError(
                f"WSDLR: decay_epochs 必须是 >=1 的整数，收到 {decay_epochs!r}")
        if warmup_epochs + decay_epochs > total_epochs:
            raise ValueError(
                f"WSDLR: warmup({warmup_epochs}) + decay({decay_epochs}) "
                f"不能超过 total_epochs({total_epochs})")
        if decay_shape not in self.SHAPES:
            raise ValueError(f"WSDLR: decay_shape 只能是 {self.SHAPES}，收到 {decay_shape!r}")
        low = _sched_check("WSDLR", "min_lr", min_lr, minimum=0.0)
        self.optimizer = optimizer
        self.warmup_epochs = int(warmup_epochs)
        self.total_epochs = int(total_epochs)
        self.decay_epochs = int(decay_epochs)
        self.min_lr = low
        self.decay_shape = decay_shape
        self.initial_lr = optimizer.lr

    def step(self, epoch: int):
        epoch = _sched_epoch(epoch, "WSDLR")
        if self.warmup_epochs > 0 and epoch <= self.warmup_epochs:
            frac = epoch / self.warmup_epochs
            self.optimizer.lr = self.initial_lr * frac
            return
        decay_start = self.total_epochs - self.decay_epochs + 1
        if epoch < decay_start:
            self.optimizer.lr = self.initial_lr
            return
        frac = min(1.0, (epoch - decay_start + 1) / self.decay_epochs)
        if self.decay_shape == "cos":
            lr = self.min_lr + (self.initial_lr - self.min_lr) * 0.5 * (
                1 + math.cos(math.pi * frac))
        else:
            lr = self.initial_lr - (self.initial_lr - self.min_lr) * frac
        self.optimizer.lr = lr


class ChainedScheduler:
    """把多个调度器**依次**作用于同一个 optimizer（PyTorch `ChainedScheduler`）

    注意与 `SequentialLR` 的区别：这里每个调度器**每轮都会被调用**，
    所以适合「先按公式改 lr，再叠加一个上限」这类组合。
    """

    def __init__(self, *schedulers):
        if len(schedulers) == 1 and isinstance(schedulers[0], (list, tuple)):
            schedulers = tuple(schedulers[0])
        if not schedulers:
            raise ValueError("ChainedScheduler: 至少需要一个调度器")
        for s in schedulers:
            if not callable(getattr(s, "step", None)):
                raise ValueError(f"ChainedScheduler: {s!r} 没有 step 方法")
        self.schedulers = list(schedulers)
        self.optimizer = self.schedulers[0].optimizer
        self.initial_lr = self.optimizer.lr

    def step(self, epoch: int):
        for s in self.schedulers:
            s.step(epoch)


class SequentialLR:
    """按里程碑切换调度器（PyTorch `SequentialLR`）

    `milestones=[m1, m2]` 表示：epoch < m1 用第 0 个，m1 <= epoch < m2 用第 1 个，
    之后用最后一个。因此 `schedulers` 必须是 `len(milestones) + 1` 个。
    """

    def __init__(self, optimizer, schedulers, milestones):
        if not isinstance(schedulers, (list, tuple)) or not schedulers:
            raise ValueError(f"SequentialLR: schedulers 必须是非空列表，收到 {schedulers!r}")
        for s in schedulers:
            if not callable(getattr(s, "step", None)):
                raise ValueError(f"SequentialLR: {s!r} 没有 step 方法")
        if isinstance(milestones, (int, float)) and not isinstance(milestones, bool):
            milestones = [milestones]
        if not isinstance(milestones, (list, tuple)) or not milestones:
            raise ValueError(f"SequentialLR: milestones 必须是非空列表，收到 {milestones!r}")
        clean = []
        for m in milestones:
            if isinstance(m, bool) or not isinstance(m, int) or m < 1:
                raise ValueError(f"SequentialLR: milestones 里的每项必须是 >=1 的整数，收到 {m!r}")
            clean.append(int(m))
        if sorted(clean) != clean or len(set(clean)) != len(clean):
            raise ValueError(f"SequentialLR: milestones 必须严格递增，收到 {milestones!r}")
        if len(schedulers) != len(clean) + 1:
            raise ValueError(
                f"SequentialLR: schedulers 需要有 {len(clean) + 1} 个"
                f"（milestones {len(clean)} 个 + 1），收到 {len(schedulers)} 个")
        self.optimizer = optimizer
        self.schedulers = list(schedulers)
        self.milestones = list(clean)
        self.initial_lr = optimizer.lr

    def step(self, epoch: int):
        epoch = _sched_epoch(epoch, "SequentialLR")
        idx = 0
        for m in self.milestones:
            if epoch >= m:
                idx += 1
        self.schedulers[idx].step(epoch)


class StepLR:
    """每 step_size 个 epoch 将 lr 乘以 gamma"""

    def __init__(self, optimizer, step_size: int = 30, gamma: float = 0.1):
        if step_size is None or step_size <= 0:
            raise ValueError(f"StepLR: step_size 必须 >= 1，收到 {step_size!r}")
        self.optimizer = optimizer
        self.step_size = step_size
        self.gamma = gamma
        self.initial_lr = optimizer.lr

    def step(self, epoch: int):
        if epoch > 0 and epoch % self.step_size == 0:
            self.optimizer.lr = self.initial_lr * (self.gamma ** (epoch // self.step_size))


class ExponentialLR:
    """每 epoch 将 lr 乘以 gamma^epoch"""

    def __init__(self, optimizer, gamma: float = 0.99):
        self.optimizer = optimizer
        self.gamma = gamma
        self.initial_lr = optimizer.lr

    def step(self, epoch: int):
        self.optimizer.lr = self.initial_lr * (self.gamma ** epoch)


class CosineAnnealingLR:
    """余弦退火学习率调度"""

    def __init__(self, optimizer, T_max: int, eta_min: float = 0.0):
        if T_max is None or T_max <= 0:
            raise ValueError(f"CosineAnnealingLR: T_max 必须 >= 1，收到 {T_max!r}")
        self.optimizer = optimizer
        self.T_max = T_max
        self.eta_min = eta_min
        self.initial_lr = optimizer.lr

    def step(self, epoch: int):
        # 支持周期重启：epoch 每 T_max 后重新开始余弦退火周期
        # 分母用 T_max-1，使每个周期**最后一轮**正好到达 eta_min；
        # 原先除以 T_max，最低只到 eta_min + 0.0488*(initial-eta_min)，永远够不着
        # epoch 从 1 开始计数（Model.fit 就是这么调的）；单独传 0/负数时按 1 处理，
        # 否则 ((-1) % T_max) 会绕到周期末尾，第一步就落到 eta_min
        epoch = max(int(epoch), 1)
        # T_max=1 时每一轮都是一个完整周期的末尾：直接落在 eta_min
        if self.T_max == 1:
            progress = 1.0
        else:
            progress = ((epoch - 1) % self.T_max) / (self.T_max - 1)
        self.optimizer.lr = self.eta_min + 0.5 * (self.initial_lr - self.eta_min) * (
            1 + math.cos(math.pi * progress))


class WarmupLR:
    """线性 warmup + 可选后续调度器（LLM 训练标配）

    前 warmup_epochs 轮把 lr 从 initial_lr*start_factor 线性升到 initial_lr，
    之后交给 base_scheduler（StepLR / ExponentialLR / CosineAnnealingLR），
    不传则保持 initial_lr。epoch 从 1 开始计数，与 Model.fit 一致。

    不 warmup 直接上大学习率时，注意力与 LayerNorm 的早期梯度很容易把模型打散；
    LLM 训练普遍用总步数的 1%~5% 做线性 warmup。
    """

    def __init__(self, optimizer, warmup_epochs: int = 5,
                 start_factor: float = 0.0, base_scheduler=None):
        if warmup_epochs is None or int(warmup_epochs) < 1:
            raise ValueError(f"WarmupLR: warmup_epochs 必须 >= 1，收到 {warmup_epochs!r}")
        if not 0.0 <= float(start_factor) <= 1.0:
            raise ValueError(f"WarmupLR: start_factor 必须在 [0,1]，收到 {start_factor!r}")
        self.optimizer = optimizer
        self.warmup_epochs = int(warmup_epochs)
        self.start_factor = float(start_factor)
        self.base_scheduler = base_scheduler
        self.initial_lr = optimizer.lr

    def step(self, epoch: int):
        epoch = max(int(epoch), 1)
        if epoch <= self.warmup_epochs:
            frac = epoch / self.warmup_epochs
            self.optimizer.lr = self.initial_lr * (
                self.start_factor + (1.0 - self.start_factor) * frac)
            return
        # warmup 结束：先回到基准 lr，再让后续调度器按绝对 epoch 接管
        self.optimizer.lr = self.initial_lr
        if self.base_scheduler is not None:
            self.base_scheduler.step(epoch)




class ReduceLROnPlateau:
    """按验证指标停滞降学习率：``lr *= factor``（PyTorch 同名调度器）

    step(metric)：指标在 ``patience`` 轮内没有改善（相对 ``threshold``）时把
    lr 乘 ``factor``，降 ``max_reductions`` 次后停在 ``min_lr``。
    mode='min' 表示指标越小越好（loss），'max' 表示越大越好（accuracy）。
    """

    def __init__(self, optimizer, factor: float = 0.5, patience: int = 10,
                 min_lr: float = 0.0, mode: str = "min", threshold: float = 1e-4,
                 max_reductions: int = None):
        if not 0.0 < float(factor) < 1.0:
            raise ValueError(f"ReduceLROnPlateau: factor 必须在 (0,1)，收到 {factor!r}")
        if mode not in ("min", "max"):
            raise ValueError(f"ReduceLROnPlateau: mode 只能是 'min' 或 'max'，收到 {mode!r}")
        if isinstance(patience, bool) or not isinstance(patience, int) or patience < 0:
            raise ValueError(f"ReduceLROnPlateau: patience 必须是 >=0 的整数，收到 {patience!r}")
        if float(min_lr) < 0.0:
            raise ValueError(f"ReduceLROnPlateau: min_lr 必须 >= 0，收到 {min_lr!r}")
        if max_reductions is not None and (isinstance(max_reductions, bool)
                                           or not isinstance(max_reductions, int)
                                           or max_reductions < 0):
            raise ValueError("ReduceLROnPlateau: max_reductions 必须是 None 或 >=0 的整数")
        self.optimizer = optimizer
        self.factor = float(factor)
        self.patience = int(patience)
        self.min_lr = float(min_lr)
        self.mode = mode
        self.threshold = float(threshold)
        self.max_reductions = max_reductions
        self.initial_lr = optimizer.lr
        self.best = None
        self.num_bad = 0
        self.reductions = 0

    def step(self, metric: float):
        """用这一轮的验证指标调用一次；返回当前 lr"""
        m = float(metric)
        if m != m:                      # NaN 指标不参与比较
            return self.optimizer.lr
        if self.best is None:
            self.best = m
            return self.optimizer.lr
        if self.mode == "min":
            better = m < self.best - self.threshold
        else:
            better = m > self.best + self.threshold
        if better:
            self.best = m
            self.num_bad = 0
            return self.optimizer.lr
        self.num_bad += 1
        if self.num_bad > self.patience:
            if self.max_reductions is not None and self.reductions >= self.max_reductions:
                return self.optimizer.lr
            self.optimizer.lr = max(self.min_lr, self.optimizer.lr * self.factor)
            self.num_bad = 0
            self.reductions += 1
        return self.optimizer.lr



# ============================================================================
#  Data Utilities
# ============================================================================

def _grads_norm(grads):
    """把 [(grad_w, grad_b), ...] 里所有元素的平方和开根号。

    求和顺序沿用 Model.fit 里原来内联的写法（层 → 行 → 列 → 偏置），
    这样把内联改成函数调用不会改变任何一位。
    """
    sq = 0.0
    for gw_l, gb_l in grads:
        for row in gw_l:
            for v in row:
                sq += v * v
        for v in gb_l:
            sq += v * v
    return math.sqrt(sq)


def estimate_flops(model, input_shape):
    """估算前向的计算量（纯标准库，不计显存/访存）。

    model:       MLP / Model / Sequential（支持 Layer、Conv1d、Conv2d、
                 ConvTranspose2d、MaxPool2d、AvgPool2d、GlobalAvgPool2d、
                 AdaptiveAvgPool2d、Flatten、BatchNorm1d、LayerNorm、GroupNorm、
                 InstanceNorm、Dropout、DropPath；遇到不认识的模块抛 TypeError，
                 而不是静默给个错数）
    input_shape: MLP 传 [fan_in]；二维卷积/池化/归一化传 (C, H, W)；
                 Conv1d 传 (C, L)；BatchNorm1d 也接受 (C, H, W)

    返回 dict：
        {'macs': 乘加次数, 'flops': 2*macs, 'params': 参数量,
         'output_shape': 输出形状, 'by_layer': [(名字, macs), ...]}

    注意：这是**解析估算**，不是实测。卷积按 im2col 后的稠密矩阵乘法计数，
    不做 winograd/FFT 之类的算法级优化假设。
    """
    if isinstance(model, Model):
        seq = model.model
    else:
        seq = model
    if isinstance(seq, MLP):
        layers = list(seq.layers)
    elif isinstance(seq, Sequential):
        layers = list(seq.modules)
        # 允许 Sequential([a, b]) 这种把列表当唯一 module 传进来的写法
        if len(layers) == 1 and isinstance(layers[0], (list, tuple)):
            layers = list(layers[0])
    elif hasattr(seq, 'layers'):
        layers = list(seq.layers)
    else:
        raise TypeError(f"estimate_flops: 不支持的模型类型 {type(seq).__name__}")

    shape = list(input_shape)
    if not shape:
        raise ValueError("estimate_flops: input_shape 不能为空")
    by_layer = []
    macs = 0
    params = 0

    def _dense(fan_in, fan_out):
        return fan_in * fan_out

    for m in layers:
        name = type(m).__name__
        if isinstance(m, Layer):
            fan_in, fan_out = m.fan_in, m.fan_out
            if len(shape) != 1 or shape[0] != fan_in:
                raise ValueError(
                    f"estimate_flops: {fan_in} 输入的 Layer 收到了形状 {shape}"
                )
            step = _dense(fan_in, fan_out)
            shape = [fan_out]
            params += fan_in * fan_out + fan_out
        elif isinstance(m, Conv2d):
            if len(shape) != 3:
                raise ValueError(f"estimate_flops: Conv2d 需要 (C, H, W)，收到 {shape}")
            c_in, h, w = shape
            if c_in != m.in_channels:
                raise ValueError(
                    f"estimate_flops: Conv2d 期望 {m.in_channels} 通道，输入是 {c_in}"
                )
            pad_h, pad_w = m.padding
            out_h = (h + 2 * pad_h - m.kh_eff) // m.sh + 1
            out_w = (w + 2 * pad_w - m.kw_eff) // m.sw + 1
            if out_h <= 0 or out_w <= 0:
                raise ValueError(
                    f"estimate_flops: 输入 {h}x{w} 经 kernel={m.kernel_size} "
                    f"stride={m.stride} padding={m.padding} 后输出尺寸非正"
                )
            # 分组卷积每个输出通道只连 cg = in_channels/groups 个输入通道，
            # 按 in_channels 计数会把 groups>1 的 MACs/参数量成倍高估
            step = m.out_channels * m.cg * m.kh * m.kw * out_h * out_w
            shape = [m.out_channels, out_h, out_w]
            params += m.out_channels * m.cg * m.kh * m.kw + m.out_channels
        elif isinstance(m, MaxPool2d):
            if len(shape) != 3:
                raise ValueError(f"estimate_flops: MaxPool2d 需要 (C, H, W)，收到 {shape}")
            c, h, w = shape
            out_h = (h - m.kh) // m.sh + 1
            out_w = (w - m.kw) // m.sw + 1
            step = c * m.kh * m.kw * out_h * out_w  # 比较次数
            shape = [c, out_h, out_w]
        elif isinstance(m, AvgPool2d):
            if len(shape) != 3:
                raise ValueError(f"estimate_flops: AvgPool2d 需要 (C, H, W)，收到 {shape}")
            c, h, w = shape
            out_h = (h - m.kh) // m.sh + 1
            out_w = (w - m.kw) // m.sw + 1
            step = c * out_h * out_w * (m.kh * m.kw)  # 求和 + 除
            shape = [c, out_h, out_w]
        elif isinstance(m, BatchNorm2d):
            if len(shape) != 3:
                raise ValueError(f"estimate_flops: BatchNorm2d 需要 (C, H, W)，收到 {shape}")
            c, h, w = shape
            if c != m.c:
                raise ValueError(
                    f"estimate_flops: BatchNorm2d 期望 {m.c} 通道，输入是 {c}")
            # 每元素约 4 次运算（减均值、乘 inv_std、乘 gamma、加 beta）+ 统计量
            step = 4 * c * h * w
            params += 2 * m.c
            shape = [c, h, w]
        elif isinstance(m, GlobalAvgPool2d):
            if len(shape) != 3:
                raise ValueError(
                    f"estimate_flops: GlobalAvgPool2d 需要 (C, H, W)，收到 {shape}"
                )
            c, h, w = shape
            step = c * h * w
            shape = [c]
        elif isinstance(m, Conv1d):
            if len(shape) != 2:
                raise ValueError(f"estimate_flops: Conv1d 需要 (C, L)，收到 {shape}")
            c_in, length = shape
            if c_in != m.in_channels:
                raise ValueError(
                    f"estimate_flops: Conv1d 期望 {m.in_channels} 通道，输入是 {c_in}"
                )
            out_l = (length + 2 * m.p - m.k) // m.s + 1
            if out_l <= 0:
                raise ValueError(
                    f"estimate_flops: 输入长度 {length} 经 kernel={m.k} "
                    f"stride={m.s} padding={m.p} 后输出长度非正"
                )
            step = m.out_channels * m.cg * m.k * out_l
            shape = [m.out_channels, out_l]
            params += m.out_channels * m.cg * m.k + m.out_channels
        elif isinstance(m, ConvTranspose2d):
            if len(shape) != 3:
                raise ValueError(
                    f"estimate_flops: ConvTranspose2d 需要 (C, H, W)，收到 {shape}"
                )
            c_in, h, w = shape
            if c_in != m.in_channels:
                raise ValueError(
                    f"estimate_flops: ConvTranspose2d 期望 {m.in_channels} 通道，"
                    f"输入是 {c_in}"
                )
            out_h = (h - 1) * m.sh - 2 * m.ph + m.kh + m.oph
            out_w = (w - 1) * m.sw - 2 * m.pw + m.kw + m.opw
            if out_h <= 0 or out_w <= 0:
                raise ValueError(
                    f"estimate_flops: 输入 {h}x{w} 经转置卷积后输出尺寸非正"
                )
            # 每个输入元素对每个 (本组输出通道, 核位置) 贡献一次乘加
            step = m.in_channels * m.og * m.kh * m.kw * h * w
            shape = [m.out_channels, out_h, out_w]
            params += m.in_channels * m.og * m.kh * m.kw + m.out_channels
        elif isinstance(m, AdaptiveAvgPool2d):
            if len(shape) != 3:
                raise ValueError(
                    f"estimate_flops: AdaptiveAvgPool2d 需要 (C, H, W)，收到 {shape}"
                )
            c, h, w = shape
            oh, ow = m.out_size
            step = c * h * w          # 每个输入元素恰好参与一次求均
            shape = [c, oh, ow]
        elif isinstance(m, (GroupNorm, InstanceNorm)):
            if len(shape) != 3:
                raise ValueError(
                    f"estimate_flops: {name} 需要 (C, H, W)，收到 {shape}"
                )
            c, h, w = shape
            if c != m.channels:
                raise ValueError(
                    f"estimate_flops: {name} 期望 {m.channels} 通道，输入是 {c}"
                )
            step = 4 * c * h * w      # 均值 + 方差 + 归一化 + 仿射
            params += 2 * m.channels
        elif isinstance(m, DropPath):
            step = 0
        elif isinstance(m, (BatchNorm1d, LayerNorm, Dropout, Flatten)):
            if isinstance(m, Flatten):
                # Flatten.forward 要求 (C,H,W)；1 维/2 维在这里静默通过、
                # 真跑却抛 TypeError，属于「估算说能跑、实际跑不了」，直接报错
                if len(shape) != 3:
                    raise ValueError(
                        f"estimate_flops: Flatten 需要三维输入 (C,H,W)，"
                        f"当前输入形状 {shape}（一维/二维请先补维度）"
                    )
                step = 0
                shape = [shape[0] * shape[1] * shape[2]]
            elif isinstance(m, Dropout):
                step = 0
            elif isinstance(m, LayerNorm):
                step = 2 * shape[0]
            else:  # BatchNorm1d：均值 + 方差 + 归一化 + 仿射，按 4 次元素操作计
                n = 1
                for d in shape:
                    n *= d
                step = 4 * max(n, shape[0])
        else:
            raise TypeError(
                f"estimate_flops: 不认识的模块 {name}（不做静默估算，请手动计数）"
            )
        macs += step
        by_layer.append((name, step))

    return {
        'macs': macs,
        'flops': 2 * macs,
        'params': params,
        'output_shape': list(shape),
        'by_layer': by_layer,
    }


def augment_noise(x, sigma: float = 0.01, rng=None):
    """加性高斯噪声（对样本内的每个数独立采样）。

    x:    单个样本（list）或一组样本（list[list]），原样维度返回，不修改入参
    sigma: 噪声标准差，必须 >= 0（0 表示拷贝一份，逐位相同）
    """
    if not isinstance(sigma, (int, float)) or isinstance(sigma, bool) or sigma < 0:
        raise ValueError(f"augment_noise: sigma 必须是非负数，收到 {sigma!r}")
    r = random if rng is None else rng

    def _one(vec):
        if sigma == 0:
            return [float(v) for v in vec]
        return [float(v) + r.gauss(0.0, sigma) for v in vec]

    if x and isinstance(x[0], (list, tuple)):
        return [_one(list(xi)) for xi in x]
    return _one(list(x))


def augment_image(x, flip: bool = True, max_shift: int = 1, rng=None):
    """图像样本的翻转/平移增强，输入 (C, H, W)，返回同形状的新样本。

    flip:      True 时以 50% 概率左右翻转（逐通道同步）
    max_shift: 水平/垂直各在 [-max_shift, max_shift] 内随机平移，越界处补 0
    """
    if not (isinstance(x, (list, tuple)) and len(x) >= 1 and x[0]
            and isinstance(x[0][0], (list, tuple))):
        raise ValueError("augment_image: 需要 (C, H, W) 的图像样本")
    if not isinstance(max_shift, int) or isinstance(max_shift, bool) or max_shift < 0:
        raise ValueError(f"augment_image: max_shift 必须是非负整数，收到 {max_shift!r}")
    r = random if rng is None else rng
    c, h, w = len(x), len(x[0]), len(x[0][0])
    for ch in x:
        if len(ch) != h or any(len(row) != w for row in ch):
            raise ValueError("augment_image: 各通道的 H/W 必须一致")

    do_flip = flip and r.random() < 0.5
    dx = r.randint(-max_shift, max_shift) if max_shift else 0
    dy = r.randint(-max_shift, max_shift) if max_shift else 0

    out = []
    for ch in x:
        new_ch = [[0.0] * w for _ in range(h)]
        for y in range(h):
            sy = y + dy
            if not 0 <= sy < h:
                continue
            src_row = ch[sy]
            dst_row = new_ch[y]
            for xx in range(w):
                sx = xx + dx
                if not 0 <= sx < w:
                    continue
                v = float(src_row[w - 1 - sx] if do_flip else src_row[sx])
                dst_row[xx] = v
        out.append(new_ch)
    return out


def _aug_image(x, who):
    """校验并返回 (C, H, W) 的副本（不修改入参）"""
    if not isinstance(x, (list, tuple)) or len(x) < 1:
        raise ValueError(f"{who}: 输入必须是 (C,H,W) 图像，收到 {type(x).__name__}")
    out = []
    h = None
    for c in x:
        if not isinstance(c, (list, tuple)) or not c:
            raise ValueError(f"{who}: 每个通道必须是非空二维数组")
        w = None
        chan = []
        for row in c:
            if not isinstance(row, (list, tuple)) or not row:
                raise ValueError(f"{who}: 每个通道必须是非空二维数组")
            if w is None:
                w = len(row)
            elif len(row) != w:
                raise ValueError(f"{who}: 同一通道内各行长度必须相同")
            chan.append([float(v) for v in row])
        if h is None:
            h = len(c)
        elif len(c) != h:
            raise ValueError(f"{who}: 各通道高度必须相同")
        out.append(chan)
    return out


def _beta_lam(alpha, rng, who):
    """用两次 Gamma 抽样合成 Beta(alpha, alpha) 的 lam（与 mixup 一致）"""
    alpha = float(alpha)
    if alpha <= 0.0:
        raise ValueError(f"{who}: alpha 必须 > 0，收到 {alpha!r}")

    def gamma(a):
        # Marsaglia-Tsang：a >= 1 用 squeeze；a < 1 用 x^(1/a) 提升
        if a < 1.0:
            u = rng.random()
            while u == 0.0:
                u = rng.random()
            return gamma(a + 1.0) * (u ** (1.0 / a))
        d = a - 1.0 / 3.0
        c = 1.0 / math.sqrt(9.0 * d)
        while True:
            x = rng.gauss(0.0, 1.0)
            v = (1.0 + c * x) ** 3
            if v <= 0.0:
                continue
            u = rng.random()
            if u < 1.0 - 0.0331 * x ** 4:
                return d * v
            if math.log(u) < 0.5 * x * x + d * (1.0 - v + math.log(v)):
                return d * v

    g1 = gamma(alpha)
    g2 = gamma(alpha)
    return g1 / (g1 + g2)


def augment_cutmix(x1, y1, x2, y2, alpha: float = 1.0, rng=None):
    """CutMix：从 x2 剪一块矩形贴到 x1 上，标签按面积比例混合

    x1/x2: (C,H,W)；y1/y2: 标签（one-hot 或任意等长向量）。
    返回 (image, label)，label 是「按面积加权的混合标签」，和仍为 1（输入是 one-hot 时）。
    """
    who = "augment_cutmix"
    a = _aug_image(x1, who)
    b = _aug_image(x2, who)
    if len(a) != len(b) or len(a[0]) != len(b[0]) or len(a[0][0]) != len(b[0][0]):
        raise ValueError(f"{who}: 两张图的形状必须相同")
    if len(y1) != len(y2) or not y1:
        raise ValueError(f"{who}: 两个标签长度必须相同且非空")
    rng = rng or random
    lam = _beta_lam(alpha, rng, who)

    C, H, W = len(a), len(a[0]), len(a[0][0])
    cut_w = int(round(W * math.sqrt(1.0 - lam)))
    cut_h = int(round(H * math.sqrt(1.0 - lam)))
    if cut_w > 0 and cut_h > 0:
        cx = int(rng.randrange(W))
        cy = int(rng.randrange(H))
        x0, x1_ = max(0, cx - cut_w // 2), min(W, cx + cut_w // 2)
        y0, y1_ = max(0, cy - cut_h // 2), min(H, cy + cut_h // 2)
        for c in range(C):
            for yy in range(y0, y1_):
                for xx in range(x0, x1_):
                    a[c][yy][xx] = b[c][yy][xx]
        lam = 1.0 - ((x1_ - x0) * (y1_ - y0)) / float(H * W)
    else:
        lam = 1.0

    label = [lam * float(u) + (1.0 - lam) * float(v) for u, v in zip(y1, y2)]
    return a, label


def augment_cutout(x, num_holes: int = 1, hole_size: float = 0.25, fill: float = 0.0,
                   rng=None):
    """Cutout：随机抹掉 num_holes 个正方形区域（填 fill）

    hole_size 是相对短边的比例，(0,1)。返回新图像，不修改入参。
    """
    who = "augment_cutout"
    img = _aug_image(x, who)
    if isinstance(num_holes, bool) or not isinstance(num_holes, int) or num_holes < 0:
        raise ValueError(f"{who}: num_holes 必须是 >= 0 的整数，收到 {num_holes!r}")
    hole_size = float(hole_size)
    if not 0.0 < hole_size < 1.0:
        raise ValueError(f"{who}: hole_size 必须在 (0,1)，收到 {hole_size!r}")
    rng = rng or random
    C, H, W = len(img), len(img[0]), len(img[0][0])
    side = max(1, int(round(min(H, W) * hole_size)))
    for _ in range(num_holes):
        x0 = int(rng.randrange(max(1, W - side + 1)))
        y0 = int(rng.randrange(max(1, H - side + 1)))
        for c in range(C):
            for yy in range(y0, min(H, y0 + side)):
                for xx in range(x0, min(W, x0 + side)):
                    img[c][yy][xx] = float(fill)
    return img


def _aug_brightness(img, factor):
    return [[[min(1.0, max(0.0, v * factor)) for v in row] for row in ch] for ch in img]


def _aug_contrast(img, factor):
    n = sum(sum(v for v in row) for ch in img for row in ch)
    cnt = sum(len(row) for ch in img for row in ch)
    mean = n / cnt
    return [[[min(1.0, max(0.0, (v - mean) * factor + mean)) for v in row] for row in ch]
            for ch in img]


def _aug_shift(img, dy, dx):
    C, H, W = len(img), len(img[0]), len(img[0][0])
    out = []
    for c in range(C):
        chan = [[0.0] * W for _ in range(H)]
        for y in range(H):
            sy = y - dy
            if not 0 <= sy < H:
                continue
            for x in range(W):
                sx = x - dx
                if 0 <= sx < W:
                    chan[y][x] = img[c][sy][sx]
        out.append(chan)
    return out


def _aug_rotate90(img, turns):
    out = img
    for _ in range(turns % 4):
        C, H, W = len(out), len(out[0]), len(out[0][0])
        out = [[[out[c][H - 1 - x][y] for x in range(H)] for y in range(W)]
               for c in range(C)]
    return out


def augment_randaugment(x, n: int = 2, magnitude: float = 9.0, ops=None, rng=None):
    """RandAugment：随机挑 n 个操作（可重复）依次应用

    默认操作集：brightness / contrast / translate / rotate90 / identity。
    magnitude ∈ [0, 10]，线性映射到各操作强度（1 = 弱，10 = 强）。
    返回 (image, ops_applied) —— 应用了哪些操作，便于复现和记录。
    """
    who = "augment_randaugment"
    img = _aug_image(x, who)
    if isinstance(n, bool) or not isinstance(n, int) or n < 0:
        raise ValueError(f"{who}: n 必须是 >= 0 的整数，收到 {n!r}")
    magnitude = float(magnitude)
    if not 0.0 <= magnitude <= 10.0:
        raise ValueError(f"{who}: magnitude 必须在 [0,10]，收到 {magnitude!r}")
    rng = rng or random
    pool = list(ops) if ops else ["brightness", "contrast", "translate", "rotate90", "identity"]
    for op in pool:
        if op not in ("brightness", "contrast", "translate", "rotate90", "identity"):
            raise ValueError(f"{who}: 不支持的操作 {op!r}")

    scale = magnitude / 10.0
    applied = []
    for _ in range(n):
        op = pool[int(rng.randrange(len(pool)))]
        applied.append(op)
        if op == "brightness":
            img = _aug_brightness(img, 1.0 - 0.5 * scale + scale * rng.random())
        elif op == "contrast":
            img = _aug_contrast(img, 1.0 - 0.5 * scale + scale * rng.random())
        elif op == "translate":
            lim = max(1, int(round(scale * 0.25 * min(len(img[0]), len(img[0][0])))))
            img = _aug_shift(img, int(rng.randint(-lim, lim)), int(rng.randint(-lim, lim)))
        elif op == "rotate90":
            img = _aug_rotate90(img, int(rng.randrange(4)))
    return img, applied


def mixup(x1, y1, x2, y2, alpha: float = 0.2, rng=None):
    """Mixup：返回 (混合后的 x, 混合后的软标签向量)。

    lam ~ Beta(alpha, alpha)（alpha<=0 时取 lam=0.5，即固定中点）；
    y1/y2 必须是**类别索引**，返回的标签是 lam*y1 + (1-lam)*y2 的概率向量，
    可直接喂给 cross_entropy_loss 的软标签分支。
    """
    if not isinstance(alpha, (int, float)) or isinstance(alpha, bool):
        raise ValueError(f"mixup: alpha 必须是数字，收到 {alpha!r}")
    if not isinstance(y1, int) or isinstance(y1, bool) or not isinstance(y2, int) or isinstance(y2, bool):
        raise ValueError("mixup: y1/y2 必须是类别索引")
    if len(x1) != len(x2):
        raise ValueError(f"mixup: 两个样本维度不同（{len(x1)} vs {len(x2)}）")
    n_cls = max(y1, y2) + 1
    r = random if rng is None else rng
    if alpha > 0:
        # Beta(a, a) 用两个 Gamma(a) 采样相除；标准库没有 gamma，用 Marsaglia-Tsang
        def _gamma(a):
            if a < 1.0:
                return _gamma(a + 1.0) * (r.random() ** (1.0 / a))
            d = a - 1.0 / 3.0
            c = 1.0 / math.sqrt(9.0 * d)
            while True:
                while True:
                    v = r.gauss(0.0, 1.0)
                    if v > -1.0 / c:
                        break
                u = r.random()
                x = (1.0 + c * v) ** 3
                if math.log(u) < 0.5 * v * v + d - d * x + d * math.log(x):
                    return d * x
        # Beta(a, a)：用两个独立 Gamma(a) 采样相除；分母必须包含分子那一项，
        # 原来写成 _gamma(a)/(_gamma(a)+_gamma(a)) 漏了分子，实测 lam 会超过 1
        g1 = _gamma(alpha)
        g2 = _gamma(alpha)
        lam = g1 / (g1 + g2)
    else:
        lam = 0.5
    mixed_x = [lam * float(a) + (1.0 - lam) * float(b) for a, b in zip(x1, x2)]
    soft = [0.0] * n_cls
    soft[y1] += lam
    soft[y2] += 1.0 - lam
    return mixed_x, soft


def split_data(data, val_ratio: float = 0.2, test_ratio: float = 0.1, seed: int = 42,
               stratify=None):
    """将数据拆分为 train / val / test

    stratify: 与 data 等长的标签序列（如类别 id）。给出时按标签分层抽样，
        使各类别在 train/val/test 中的比例尽量与整体一致（类别极不均衡时很有用）。
    """
    if not (0.0 <= val_ratio < 1.0) or not (0.0 <= test_ratio < 1.0) \
            or val_ratio + test_ratio >= 1.0:
        raise ValueError(
            f"split_data: 比例非法（val_ratio={val_ratio}, test_ratio={test_ratio}）；"
            f"要求各自在 [0,1) 内且之和 < 1"
        )
    # 用局部 Random 实例，避免 random.seed() 污染全局随机状态
    rng = random.Random(seed)
    items = list(data)
    if stratify is not None:
        if len(stratify) != len(items):
            raise ValueError(
                f"split_data: stratify 长度 {len(stratify)} 与数据量 {len(items)} 不一致"
            )
        groups = {}
        for idx, label in enumerate(stratify):
            groups.setdefault(label, []).append(idx)
        test_idx, val_idx, train_idx = [], [], []
        for label, idxs in groups.items():
            rng.shuffle(idxs)
            k = len(idxs)
            n_t = int(k * test_ratio)
            n_v = int(k * val_ratio)
            test_idx.extend(idxs[:n_t])
            val_idx.extend(idxs[n_t:n_t + n_v])
            train_idx.extend(idxs[n_t + n_v:])
        return ([items[i] for i in train_idx], [items[i] for i in val_idx],
                [items[i] for i in test_idx])
    rng.shuffle(items)

    n = len(items)
    n_test = int(n * test_ratio)
    n_val = int(n * val_ratio)

    test_set = items[:n_test]
    val_set = items[n_test:n_test + n_val]
    train_set = items[n_test + n_val:]

    return train_set, val_set, test_set


# ============================================================================
#  Dataset 抽象 / Sampler 体系 / 长度分桶 / 预处理缓存
# ============================================================================

class Dataset:
    """数据集抽象基类：子类实现 ``__len__`` 与 ``__getitem__``"""

    def __len__(self):
        raise NotImplementedError("Dataset 子类必须实现 __len__")

    def __getitem__(self, index):
        raise NotImplementedError("Dataset 子类必须实现 __getitem__")


class ListDataset(Dataset):
    """把已有的 list 包成 Dataset（不复制数据）"""

    def __init__(self, items):
        if not isinstance(items, (list, tuple)):
            raise TypeError("ListDataset: items 必须是 list/tuple")
        self.items = items

    def __len__(self):
        return len(self.items)

    def __getitem__(self, index):
        return self.items[index]


class LazyDataset(Dataset):
    """懒加载：只有真正取到某个下标时才调用 ``loader(index)``

    可选把结果缓存起来（``cache=True``），并用 ``hits`` / ``misses`` 观察命中情况；
    ``max_cache`` 给出时按 FIFO 淘汰（本库不引第三方库，故不做 LRU 链表）。
    """

    def __init__(self, length, loader, cache=True, max_cache=None):
        if isinstance(length, bool) or not isinstance(length, int) or length < 0:
            raise ValueError(f"LazyDataset: length 必须是 >=0 的整数，收到 {length!r}")
        if not callable(loader):
            raise TypeError("LazyDataset: loader 必须可调用")
        if max_cache is not None and (isinstance(max_cache, bool)
                                      or not isinstance(max_cache, int)
                                      or max_cache < 1):
            raise ValueError(f"LazyDataset: max_cache 必须是 >=1 的整数或 None，收到 {max_cache!r}")
        self.length = length
        self.loader = loader
        self.cache = bool(cache)
        self.max_cache = max_cache
        self._store = {}
        self._order = []
        self.hits = 0
        self.misses = 0

    def __len__(self):
        return self.length

    def __getitem__(self, index):
        if isinstance(index, bool) or not isinstance(index, int):
            raise TypeError(f"LazyDataset: 下标必须是整数，收到 {type(index).__name__}")
        if index < 0:
            index += self.length
        if index < 0 or index >= self.length:
            raise IndexError(f"LazyDataset: 下标 {index} 越界（长度 {self.length}）")
        if self.cache and index in self._store:
            self.hits += 1
            return self._store[index]
        value = self.loader(index)
        if self.cache:
            self.misses += 1
            self._store[index] = value
            self._order.append(index)
            if self.max_cache is not None and len(self._order) > self.max_cache:
                old = self._order.pop(0)
                self._store.pop(old, None)
        return value

    def clear_cache(self):
        """清空缓存（命中计数保留）"""
        self._store.clear()
        self._order.clear()


class IterableDataset:
    """流式数据集基类：子类实现 ``__iter__`` 即可，**不需要** ``__len__``"""

    def __iter__(self):
        raise NotImplementedError("IterableDataset 子类必须实现 __iter__")


class Subset(Dataset):
    """按下标子集查看另一个 Dataset（与 torch.utils.data.Subset 同义）"""

    def __init__(self, dataset, indices):
        if not hasattr(dataset, "__getitem__"):
            raise TypeError("Subset: dataset 必须支持 __getitem__")
        self.dataset = dataset
        self.indices = list(indices)

    def __len__(self):
        return len(self.indices)

    def __getitem__(self, index):
        return self.dataset[self.indices[index]]


class Sampler:
    """采样器基类：``__iter__`` 产出样本下标"""

    def __iter__(self):
        raise NotImplementedError("Sampler 子类必须实现 __iter__")

    def __len__(self):
        raise NotImplementedError("Sampler 子类必须实现 __len__")


class SequentialSampler(Sampler):
    """按 0..n-1 顺序产出下标"""

    def __init__(self, n_samples):
        if isinstance(n_samples, bool) or not isinstance(n_samples, int) or n_samples < 0:
            raise ValueError(f"SequentialSampler: n_samples 必须是 >=0 的整数，收到 {n_samples!r}")
        self.n_samples = n_samples

    def __iter__(self):
        return iter(range(self.n_samples))

    def __len__(self):
        return self.n_samples


class RandomSampler(Sampler):
    """随机采样；``replacement=True`` 时可重复（有放回）"""

    def __init__(self, n_samples, replacement=False, seed=None):
        if isinstance(n_samples, bool) or not isinstance(n_samples, int) or n_samples < 0:
            raise ValueError(f"RandomSampler: n_samples 必须是 >=0 的整数，收到 {n_samples!r}")
        if replacement and n_samples == 0:
            raise ValueError("RandomSampler: 有放回采样要求 n_samples > 0")
        self.n_samples = n_samples
        self.replacement = bool(replacement)
        self._rng = random.Random(seed)

    def __iter__(self):
        if self.n_samples == 0:
            return iter([])
        if self.replacement:
            return iter([self._rng.randrange(self.n_samples) for _ in range(self.n_samples)])
        out = list(range(self.n_samples))
        self._rng.shuffle(out)
        return iter(out)

    def __len__(self):
        return self.n_samples


class WeightedSampler(Sampler):
    """按权重采样：``replacement=True`` 时是多项分布，否则用指数键做无放回加权抽样"""

    def __init__(self, weights, num_samples=None, replacement=True, seed=None):
        weights = [float(w) for w in weights]
        if not weights:
            raise ValueError("WeightedSampler: weights 不能为空")
        if any(w < 0.0 for w in weights):
            raise ValueError("WeightedSampler: weights 不能为负")
        if sum(weights) <= 0.0:
            raise ValueError("WeightedSampler: weights 之和必须 > 0")
        if num_samples is None:
            num_samples = len(weights)
        if isinstance(num_samples, bool) or not isinstance(num_samples, int) or num_samples < 1:
            raise ValueError(f"WeightedSampler: num_samples 必须是 >=1 的整数，收到 {num_samples!r}")
        if not replacement and num_samples > len(weights):
            raise ValueError(
                f"WeightedSampler: 无放回采样最多 {len(weights)} 个，收到 {num_samples}"
            )
        self.weights = weights
        self.num_samples = num_samples
        self.replacement = bool(replacement)
        self._rng = random.Random(seed)

    def __iter__(self):
        if self.replacement:
            total = sum(self.weights)
            out = []
            for _ in range(self.num_samples):
                r = self._rng.random() * total
                acc = 0.0
                for i, w in enumerate(self.weights):
                    acc += w
                    if r < acc:
                        out.append(i)
                        break
                else:
                    out.append(len(self.weights) - 1)
            return iter(out)
        # Gumbel 技巧：key = -log(u)/w，取 key 最小的 k 个即无放回加权抽样
        keys = []
        for i, w in enumerate(self.weights):
            if w <= 0.0:
                continue
            u = max(self._rng.random(), 1e-12)
            keys.append((-math.log(u) / w, i))
        keys.sort()
        return iter([i for _k, i in keys[:self.num_samples]])

    def __len__(self):
        return self.num_samples


class StratifiedSampler(Sampler):
    """分层采样：按标签轮流取，保证每个 batch 里类别尽量均衡

    实现上是「先把各类打散，再按轮次依次从每类取一个」，最后整体打乱顺序。
    """

    def __init__(self, labels, seed=None, shuffle=True):
        labels = list(labels)
        if not labels:
            raise ValueError("StratifiedSampler: labels 不能为空")
        self.labels = labels
        self.shuffle = bool(shuffle)
        self._rng = random.Random(seed)

    def __iter__(self):
        groups = {}
        for idx, label in enumerate(self.labels):
            groups.setdefault(label, []).append(idx)
        keys = sorted(groups, key=lambda v: (str(type(v)), v))
        for k in keys:
            if self.shuffle:
                self._rng.shuffle(groups[k])
        out = []
        pos = 0
        while True:
            added = False
            for k in keys:
                bucket = groups[k]
                if pos < len(bucket):
                    out.append(bucket[pos])
                    added = True
            if not added:
                break
            pos += 1
        if self.shuffle:
            self._rng.shuffle(out)
        return iter(out)

    def __len__(self):
        return len(self.labels)


class SubsetSampler(Sampler):
    """直接按给定下标序列产出（常用于把 k 折的索引接上 DataLoader）"""

    def __init__(self, indices):
        self.indices = [int(i) for i in indices]

    def __iter__(self):
        return iter(self.indices)

    def __len__(self):
        return len(self.indices)


class BatchSampler(Sampler):
    """把另一个 sampler 的下标切成 batch（``drop_last`` 尾批不足则丢弃）"""

    def __init__(self, sampler, batch_size, drop_last=False):
        if isinstance(batch_size, bool) or not isinstance(batch_size, int) or batch_size < 1:
            raise ValueError(f"BatchSampler: batch_size 必须是 >=1 的整数，收到 {batch_size!r}")
        self.sampler = sampler
        self.batch_size = batch_size
        self.drop_last = bool(drop_last)

    def __iter__(self):
        batch = []
        for idx in self.sampler:
            batch.append(idx)
            if len(batch) == self.batch_size:
                yield batch
                batch = []
        if batch and not self.drop_last:
            yield batch

    def __len__(self):
        n = len(self.sampler)
        if self.drop_last:
            return n // self.batch_size
        return (n + self.batch_size - 1) // self.batch_size


def bucket_by_length(lengths, batch_size, bucket_size_multiplier=4, shuffle=True,
                     seed=None, drop_last=False):
    """按长度分桶：把长度接近的样本放进同一个 batch，减少 padding 浪费

    做法：下标先打乱 → 按长度排序 → 每 ``batch_size * bucket_size_multiplier`` 个
    切片成一个桶 → 桶内再打乱 → 按 ``batch_size`` 切 batch。返回**下标**的列表的列表。
    """
    lengths = [int(v) for v in lengths]
    n = len(lengths)
    if n == 0:
        raise ValueError("bucket_by_length: lengths 不能为空")
    if any(v < 0 for v in lengths):
        raise ValueError("bucket_by_length: lengths 不能为负")
    if isinstance(batch_size, bool) or not isinstance(batch_size, int) or batch_size < 1:
        raise ValueError(f"bucket_by_length: batch_size 必须是 >=1 的整数，收到 {batch_size!r}")
    if (isinstance(bucket_size_multiplier, bool)
            or not isinstance(bucket_size_multiplier, int)
            or bucket_size_multiplier < 1):
        raise ValueError(
            f"bucket_by_length: bucket_size_multiplier 必须是 >=1 的整数，"
            f"收到 {bucket_size_multiplier!r}"
        )
    rng = random.Random(seed)
    order = list(range(n))
    if shuffle:
        rng.shuffle(order)
    order.sort(key=lambda i: lengths[i])
    buckets = []
    span = batch_size * bucket_size_multiplier
    for b in range(0, n, span):
        chunk = order[b:b + span]
        if shuffle:
            rng.shuffle(chunk)
        buckets.extend(chunk)
    batches = []
    for b in range(0, len(buckets), batch_size):
        batch = buckets[b:b + batch_size]
        if len(batch) < batch_size and drop_last:
            continue
        batches.append(batch)
    return batches


class PreprocessCache:
    """预处理结果的文件级缓存：键 = 源文件内容哈希 + 参数指纹

    ``get(params, build_fn)``：命中则读 JSON，否则调用 ``build_fn()`` 并把结果写盘
    （先写临时文件再 ``os.replace``，避免中断留下半个文件）。
    """

    def __init__(self, directory, files=None, hash_content=True, digest="sha256"):
        if not isinstance(directory, str) or not directory:
            raise ValueError("PreprocessCache: directory 必须是非空字符串")
        if digest not in ("sha256", "md5"):
            raise ValueError(f"PreprocessCache: digest 只支持 'sha256'/'md5'，收到 {digest!r}")
        self.directory = directory
        self.files = list(files or [])
        self.hash_content = bool(hash_content)
        self.digest = digest
        os.makedirs(directory, exist_ok=True)

    def _file_entry(self, path):
        if not os.path.isfile(path):
            raise FileNotFoundError(f"PreprocessCache: 源文件不存在 {path!r}")
        h = hashlib.new(self.digest)
        if self.hash_content:
            with io.open(path, "rb") as f:
                while True:
                    block = f.read(65536)
                    if not block:
                        break
                    h.update(block)
            return [os.path.basename(path), h.hexdigest()]
        st = os.stat(path)
        return [os.path.basename(path), st.st_size, st.st_mtime_ns]

    def key(self, params=None):
        """返回本次（文件 + 参数）的缓存键"""
        entries = [self._file_entry(p) for p in self.files]
        payload = json.dumps({"files": entries, "params": params},
                             sort_keys=True, ensure_ascii=False, default=str)
        h = hashlib.new(self.digest)
        h.update(payload.encode("utf-8"))
        return h.hexdigest()

    def path_for(self, key):
        return os.path.join(self.directory, key + ".json")

    def get(self, params=None, build_fn=None):
        """命中返回 ``(value, True)``，未命中构建后返回 ``(value, False)``"""
        key = self.key(params)
        path = self.path_for(key)
        if os.path.isfile(path):
            with io.open(path, "r", encoding="utf-8") as f:
                return json.load(f), True
        if not callable(build_fn):
            raise ValueError("PreprocessCache: 未命中缓存时必须提供可调用的 build_fn")
        value = build_fn()
        tmp = path + ".tmp"
        with io.open(tmp, "w", encoding="utf-8", newline="\n") as f:
            json.dump(value, f, ensure_ascii=False, sort_keys=True)
        os.replace(tmp, path)
        return value, False

    def clear(self):
        """删除目录里所有 ``*.json`` 缓存文件，返回删除个数"""
        removed = 0
        for name in sorted(os.listdir(self.directory)):
            if name.endswith(".json"):
                os.remove(os.path.join(self.directory, name))
                removed += 1
        return removed


# ============================================================================
#  ======================================================================
#  图像增强管道（Compose / RandomCrop / RandomResizedCrop /
#          RandomRotation / ColorJitter / GaussianBlur / Normalize）
#  ======================================================================

def _aug3_check(x, who):
    """校验 (C, H, W) 浮点图像。"""
    if not isinstance(x, list) or not x:
        raise ValueError("%s: 输入必须是 (C, H, W) 非空 list" % who)
    if not isinstance(x[0], list) or not x[0]:
        raise ValueError("%s: 输入必须是 (C, H, W) 非空 list" % who)
    h = len(x[0])
    for ch in x:
        if not isinstance(ch, list) or len(ch) != h:
            raise ValueError("%s: 各通道高度必须一致" % who)
        for row in ch:
            if not isinstance(row, list) or not row:
                raise ValueError("%s: 每一行必须是非空 list" % who)
            for v in row:
                if isinstance(v, bool) or not isinstance(v, (int, float)):
                    raise TypeError("%s: 像素必须是数字" % who)
    w = len(x[0][0])
    for ch in x:
        for row in ch:
            if len(row) != w:
                raise ValueError("%s: 各通道宽度必须一致" % who)
    return len(x), h, w


def _aug3_pair(size, who, name="size"):
    """把 int / (h, w) 统一成 (h, w)。"""
    if isinstance(size, bool):
        raise TypeError("%s: %s 不能是 bool" % (who, name))
    if isinstance(size, int):
        if size <= 0:
            raise ValueError("%s: %s 必须为正整数" % (who, name))
        return size, size
    if isinstance(size, (list, tuple)) and len(size) == 2:
        h, w = size
        for v in (h, w):
            if isinstance(v, bool) or not isinstance(v, int):
                raise TypeError("%s: %s 的元素必须是整数" % (who, name))
            if v <= 0:
                raise ValueError("%s: %s 的元素必须为正整数" % (who, name))
        return int(h), int(w)
    raise TypeError("%s: %s 必须是 int 或 (h, w)" % (who, name))


def _aug3_rng(obj, seed):
    """有 seed 就用私有 RNG（多次调用仍有随机性，但序列可复现）。"""
    if seed is None:
        return random
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise TypeError("%s: seed 必须是整数或 None" % type(obj).__name__)
    return random.Random(seed)


def _resize_bilinear(x, out_h, out_w):
    """把 (C, H, W) 双线性缩放到 (C, out_h, out_w)，align_corners=False 语义。"""
    c, h, w = _aug3_check(x, "_resize_bilinear")
    if h == out_h and w == out_w:
        return [[list(row) for row in ch] for ch in x]
    sy = (h - 1.0) / (out_h - 1.0) if out_h > 1 else 0.0
    sx = (w - 1.0) / (out_w - 1.0) if out_w > 1 else 0.0
    ys = [i * sy for i in range(out_h)]
    xs = [j * sx for j in range(out_w)]
    out = []
    for ch in x:
        new_ch = []
        for yy in ys:
            y0 = int(math.floor(yy))
            y1 = min(y0 + 1, h - 1)
            fy = yy - y0
            row = []
            for xx in xs:
                x0 = int(math.floor(xx))
                x1 = min(x0 + 1, w - 1)
                fx = xx - x0
                top = ch[y0][x0] * (1.0 - fx) + ch[y0][x1] * fx
                bot = ch[y1][x0] * (1.0 - fx) + ch[y1][x1] * fx
                row.append(top * (1.0 - fy) + bot * fy)
            new_ch.append(row)
        out.append(new_ch)
    return out


class Compose:
    """按顺序调用一串变换；每个变换都吃并返回 (C, H, W) 浮点图像。"""

    def __init__(self, transforms):
        if not isinstance(transforms, (list, tuple)) or not transforms:
            raise ValueError("Compose: transforms 必须是非空 list")
        for t in transforms:
            if not callable(t):
                raise TypeError("Compose: 每个变换都必须可调用")
        self.transforms = list(transforms)

    def __call__(self, x):
        _aug3_check(x, "Compose")
        for t in self.transforms:
            x = t(x)
        return x

    def __repr__(self):
        return "Compose([%s])" % ", ".join(type(t).__name__ for t in self.transforms)


class RandomCrop:
    """随机裁到 size；padding>0 时先补边（补 fill）。"""

    def __init__(self, size, padding=0, fill=0.0, seed=None):
        self.size = _aug3_pair(size, "RandomCrop")
        if isinstance(padding, bool) or not isinstance(padding, int):
            raise TypeError("RandomCrop: padding 必须是整数")
        if padding < 0:
            raise ValueError("RandomCrop: padding 不能为负")
        self.padding = padding
        if isinstance(fill, bool) or not isinstance(fill, (int, float)):
            raise TypeError("RandomCrop: fill 必须是数字")
        self.fill = float(fill)
        self._rng = _aug3_rng(self, seed)

    def __call__(self, x):
        c, h, w = _aug3_check(x, "RandomCrop")
        pad = self.padding
        if pad:
            base = [[[self.fill] * (w + 2 * pad) for _ in range(h + 2 * pad)] for _ in range(c)]
            for ch in range(c):
                for i in range(h):
                    for j in range(w):
                        base[ch][i + pad][j + pad] = x[ch][i][j]
            x = base
            h += 2 * pad
            w += 2 * pad
        out_h, out_w = self.size
        if out_h > h or out_w > w:
            raise ValueError(
                "RandomCrop: 裁剪尺寸 %dx%d 大于（补边后的）图像 %dx%d"
                % (out_h, out_w, h, w))
        top = self._rng.randrange(0, h - out_h + 1)
        left = self._rng.randrange(0, w - out_w + 1)
        return [[row[left:left + out_w] for row in ch[top:top + out_h]] for ch in x]


class RandomResizedCrop:
    """随机取一块（面积比例 scale、长宽比 ratio）再双线性缩放到 size。"""

    def __init__(self, size, scale=(0.08, 1.0), ratio=(3.0 / 4.0, 4.0 / 3.0), seed=None):
        self.size = _aug3_pair(size, "RandomResizedCrop")
        self.scale = self._check_pair(scale, "scale", 0.0, 1.0)
        self.ratio = self._check_pair(ratio, "ratio", 0.0, float("inf"))
        self._rng = _aug3_rng(self, seed)

    @staticmethod
    def _check_pair(pair, name, lo, hi):
        if not isinstance(pair, (list, tuple)) or len(pair) != 2:
            raise TypeError("RandomResizedCrop: %s 必须是 (low, high)" % name)
        a, b = pair
        for v in (a, b):
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("RandomResizedCrop: %s 的元素必须是数字" % name)
        a, b = float(a), float(b)
        if a <= lo or b <= lo or a > b:
            raise ValueError("RandomResizedCrop: 需要 %s 两端为正且 low<=high" % name)
        return a, b

    def __call__(self, x):
        c, h, w = _aug3_check(x, "RandomResizedCrop")
        area = h * w
        for _ in range(10):
            target = self._rng.uniform(area * self.scale[0], area * self.scale[1])
            log_r = self._rng.uniform(math.log(self.ratio[0]), math.log(self.ratio[1]))
            ar = math.exp(log_r)
            ch_ = int(round(math.sqrt(target * ar)))
            cw_ = int(round(math.sqrt(target / ar)))
            if 1 <= ch_ <= h and 1 <= cw_ <= w:
                top = self._rng.randrange(0, h - ch_ + 1)
                left = self._rng.randrange(0, w - cw_ + 1)
                crop = [[row[left:left + cw_] for row in chx[top:top + ch_]] for chx in x]
                return _resize_bilinear(crop, self.size[0], self.size[1])
        # 10 次都不合适就退化成中心裁剪
        ch_ = min(h, max(1, int(round(math.sqrt(area * 0.5)))))
        cw_ = min(w, max(1, int(round(math.sqrt(area * 0.5)))))
        top = (h - ch_) // 2
        left = (w - cw_) // 2
        crop = [[row[left:left + cw_] for row in chx[top:top + ch_]] for chx in x]
        return _resize_bilinear(crop, self.size[0], self.size[1])


class RandomRotation:
    """在 [-degrees, degrees] 里取角度做双线性旋转，边界外填 fill。"""

    def __init__(self, degrees, fill=0.0, seed=None):
        if isinstance(degrees, bool) or not isinstance(degrees, (int, float)):
            raise TypeError("RandomRotation: degrees 必须是数字")
        if degrees < 0:
            raise ValueError("RandomRotation: degrees 不能为负")
        self.degrees = float(degrees)
        if isinstance(fill, bool) or not isinstance(fill, (int, float)):
            raise TypeError("RandomRotation: fill 必须是数字")
        self.fill = float(fill)
        self._rng = _aug3_rng(self, seed)

    def __call__(self, x):
        c, h, w = _aug3_check(x, "RandomRotation")
        if self.degrees == 0:
            return [[list(row) for row in ch] for ch in x]
        theta = self._rng.uniform(-self.degrees, self.degrees) * math.pi / 180.0
        cos_t, sin_t = math.cos(theta), math.sin(theta)
        cy, cx = (h - 1) * 0.5, (w - 1) * 0.5
        out = []
        for ch in x:
            new_ch = []
            for i in range(h):
                dy = i - cy
                row = []
                for j in range(w):
                    dx = j - cx
                    sy = cos_t * dy + sin_t * dx + cy
                    sx = -sin_t * dy + cos_t * dx + cx
                    if sy < 0.0 or sy > h - 1 or sx < 0.0 or sx > w - 1:
                        row.append(self.fill)
                        continue
                    y0 = int(math.floor(sy))
                    x0 = int(math.floor(sx))
                    y1 = min(y0 + 1, h - 1)
                    x1 = min(x0 + 1, w - 1)
                    fy, fx = sy - y0, sx - x0
                    top = ch[y0][x0] * (1.0 - fx) + ch[y0][x1] * fx
                    bot = ch[y1][x0] * (1.0 - fx) + ch[y1][x1] * fx
                    row.append(top * (1.0 - fy) + bot * fy)
                new_ch.append(row)
            out.append(new_ch)
        return out


class ColorJitter:
    """亮度 / 对比度 / 饱和度 / 色相抖动；前三项选 (C,H,W)，色相需要在 0..1 区间。"""

    def __init__(self, brightness=0.0, contrast=0.0, saturation=0.0, hue=0.0, seed=None):
        for name, v in (("brightness", brightness), ("contrast", contrast),
                        ("saturation", saturation), ("hue", hue)):
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("ColorJitter: %s 必须是数字" % name)
            if v < 0:
                raise ValueError("ColorJitter: %s 不能为负" % name)
        if hue > 0.5:
            raise ValueError("ColorJitter: hue 不能超过 0.5")
        self.brightness = float(brightness)
        self.contrast = float(contrast)
        self.saturation = float(saturation)
        self.hue = float(hue)
        self._rng = _aug3_rng(self, seed)

    def _factor(self, amount):
        if amount == 0.0:
            return 1.0
        return self._rng.uniform(1.0 - amount, 1.0 + amount)

    def __call__(self, x):
        c, h, w = _aug3_check(x, "ColorJitter")
        if self.hue > 0.0 and c < 3:
            raise ValueError("ColorJitter: hue 抖动需要至少 3 个通道")
        out = [[list(row) for row in ch] for ch in x]
        if self.brightness:
            f = self._factor(self.brightness)
            out = [[[v * f for v in row] for row in ch] for ch in out]
        if self.contrast:
            f = self._factor(self.contrast)
            n = c * h * w
            gray = sum(sum(row) for ch in out for row in ch) / n
            out = [[[gray + (v - gray) * f for v in row] for row in ch] for ch in out]
        if self.saturation:
            f = self._factor(self.saturation)
            if c < 3:
                raise ValueError("ColorJitter: saturation 需要至少 3 个通道")
            new = [[list(row) for row in ch] for ch in out]
            for i in range(h):
                for j in range(w):
                    lum = 0.299 * out[0][i][j] + 0.587 * out[1][i][j] + 0.114 * out[2][i][j]
                    for ch in range(3):
                        new[ch][i][j] = lum + (out[ch][i][j] - lum) * f
            out = new
        if self.hue:
            if c < 3:
                raise ValueError("ColorJitter: hue 需要至少 3 个通道")
            d = self._rng.uniform(-self.hue, self.hue)
            cos_d, sin_d = math.cos(2.0 * math.pi * d), math.sin(2.0 * math.pi * d)
            #  行和恒为 1（cos/sin 系数各行为 0）：灰度图抖动色相后仍是同一灰度。
            #  与 PyTorch 的常数有 1e-3 量级差异，换来严格保持亮度这一可验证性质。
            m = [
                [0.299 + 0.701 * cos_d + 0.168 * sin_d,
                 0.587 - 0.587 * cos_d + 0.329 * sin_d,
                 0.114 - 0.114 * cos_d - 0.497 * sin_d],
                [0.299 - 0.299 * cos_d - 0.328 * sin_d,
                 0.587 + 0.413 * cos_d + 0.035 * sin_d,
                 0.114 - 0.114 * cos_d + 0.293 * sin_d],
                [0.299 - 0.300 * cos_d + 1.250 * sin_d,
                 0.587 - 0.588 * cos_d - 1.050 * sin_d,
                 0.114 + 0.888 * cos_d - 0.200 * sin_d],
            ]
            new = [[[0.0] * w for _ in range(h)] for _ in range(c)]
            for i in range(h):
                for j in range(w):
                    rgb = [out[k][i][j] for k in range(3)]
                    for ch in range(3):
                        new[ch][i][j] = sum(m[ch][k] * rgb[k] for k in range(3))
            out = new
        return out


class GaussianBlur:
    """可分离高斯模糊，核按 sigma=uniform(sigma_lo, sigma_hi) 现算。"""

    def __init__(self, kernel_size=3, sigma=(0.1, 2.0), seed=None):
        self.kernel_size = _aug3_pair(kernel_size, "GaussianBlur", "kernel_size")[0]
        if self.kernel_size % 2 == 0:
            raise ValueError("GaussianBlur: kernel_size 必须是奇数")
        if isinstance(sigma, (int, float)) and not isinstance(sigma, bool):
            sigma = (float(sigma), float(sigma))
        if not isinstance(sigma, (list, tuple)) or len(sigma) != 2:
            raise TypeError("GaussianBlur: sigma 必须是数字或 (low, high)")
        lo, hi = sigma
        for v in (lo, hi):
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("GaussianBlur: sigma 的元素必须是数字")
        if lo <= 0.0 or hi <= 0.0 or lo > hi:
            raise ValueError("GaussianBlur: sigma 需要两端为正且 low<=high")
        self.sigma = (float(lo), float(hi))
        self._rng = _aug3_rng(self, seed)

    def __call__(self, x):
        c, h, w = _aug3_check(x, "GaussianBlur")
        sigma = self._rng.uniform(self.sigma[0], self.sigma[1])
        radius = self.kernel_size // 2
        kernel = [math.exp(-0.5 * (k * k) / (sigma * sigma)) for k in range(-radius, radius + 1)]
        total = sum(kernel)
        kernel = [v / total for v in kernel]
        out = []
        for ch in x:
            tmp = []
            for i in range(h):
                row = []
                for j in range(w):
                    acc = 0.0
                    wsum = 0.0
                    for k in range(-radius, radius + 1):
                        jj = j + k
                        if jj < 0 or jj >= w:
                            continue
                        acc += ch[i][jj] * kernel[k + radius]
                        wsum += kernel[k + radius]
                    row.append(acc / wsum)
                tmp.append(row)
            blurred = []
            for i in range(h):
                row = []
                for j in range(w):
                    acc = 0.0
                    wsum = 0.0
                    for k in range(-radius, radius + 1):
                        ii = i + k
                        if ii < 0 or ii >= h:
                            continue
                        acc += tmp[ii][j] * kernel[k + radius]
                        wsum += kernel[k + radius]
                    row.append(acc / wsum)
                blurred.append(row)
            out.append(blurred)
        return out


class Normalize:
    """逐通道 (x - mean) / std；确定性变换，没有随机性也没有 seed。"""

    def __init__(self, mean, std):
        for name, v in (("mean", mean), ("std", std)):
            if not isinstance(v, (list, tuple)) or not v:
                raise ValueError("Normalize: %s 必须是非空 list" % name)
            for e in v:
                if isinstance(e, bool) or not isinstance(e, (int, float)):
                    raise TypeError("Normalize: %s 的元素必须是数字" % name)
        if len(mean) != len(std):
            raise ValueError("Normalize: mean 与 std 长度必须一致")
        for e in std:
            if e <= 0:
                raise ValueError("Normalize: std 必须为正")
        self.mean = [float(v) for v in mean]
        self.std = [float(v) for v in std]

    def __call__(self, x):
        c, h, w = _aug3_check(x, "Normalize")
        if c != len(self.mean):
            raise ValueError(
                "Normalize: 输入通道数 %d 与 mean/std 长度 %d 不一致"
                % (c, len(self.mean)))
        return [
            [[(v - self.mean[ch]) / self.std[ch] for v in row] for row in x[ch]]
            for ch in range(c)
        ]


#  编码器（OneHot / Label / Ordinal / Target / Frequency / WOE）
# ============================================================================

def _w11b_check_rows(x, who):
    """校验二维表：非空、每行列数一致，返回列数"""
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError(f"{who}: 输入必须是非空的二维列表")
    width = len(x[0])
    if width == 0:
        raise ValueError(f"{who}: 每行至少要有 1 列")
    for row in x:
        if not isinstance(row, (list, tuple)):
            raise ValueError(f"{who}: 每个样本必须是 list/tuple")
        if len(row) != width:
            raise ValueError(f"{who}: 各行列数不一致（{len(row)} != {width}）")
    return width


class LabelEncoder:
    """把一维类别标签映射成 0..k-1（按排序后的类别名，结果可复现）"""

    def __init__(self):
        self.classes_ = None
        self._index = None

    def fit(self, y):
        if not isinstance(y, (list, tuple)) or not y:
            raise ValueError("LabelEncoder: 输入必须是非空的一维列表")
        classes = sorted(set(y))
        self.classes_ = classes
        self._index = {c: i for i, c in enumerate(classes)}
        return self

    def transform(self, y):
        if self._index is None:
            raise ValueError("LabelEncoder: 请先 fit")
        if not isinstance(y, (list, tuple)):
            raise ValueError("LabelEncoder: 输入必须是一维列表")
        out = []
        for v in y:
            if v not in self._index:
                raise ValueError(f"LabelEncoder: 未知类别 {v!r}")
            out.append(self._index[v])
        return out

    def fit_transform(self, y):
        return self.fit(y).transform(y)

    def inverse_transform(self, codes):
        if self._index is None:
            raise ValueError("LabelEncoder: 请先 fit")
        out = []
        for c in codes:
            if isinstance(c, bool) or not isinstance(c, int):
                raise TypeError(f"LabelEncoder: 编码必须是整数，收到 {type(c).__name__}")
            if c < 0 or c >= len(self.classes_):
                raise ValueError(f"LabelEncoder: 编码 {c} 越界（共 {len(self.classes_)} 类）")
            out.append(self.classes_[c])
        return out


class OrdinalEncoder:
    """把多列类别特征按列映射成整数（每列独立编码，未见的类别报错）"""

    def __init__(self):
        self.categories_ = None
        self._index = None

    def fit(self, x):
        width = _w11b_check_rows(x, "OrdinalEncoder")
        self.categories_ = []
        self._index = []
        for j in range(width):
            cats = sorted(set(row[j] for row in x))
            self.categories_.append(cats)
            self._index.append({c: i for i, c in enumerate(cats)})
        return self

    def transform(self, x):
        if self._index is None:
            raise ValueError("OrdinalEncoder: 请先 fit")
        width = _w11b_check_rows(x, "OrdinalEncoder")
        if width != len(self._index):
            raise ValueError(
                f"OrdinalEncoder: 列数 {width} 与 fit 时的 {len(self._index)} 不一致"
            )
        out = []
        for row in x:
            codes = []
            for j, v in enumerate(row):
                if v not in self._index[j]:
                    raise ValueError(f"OrdinalEncoder: 第 {j} 列出现未知类别 {v!r}")
                codes.append(self._index[j][v])
            out.append(codes)
        return out

    def fit_transform(self, x):
        return self.fit(x).transform(x)

    def inverse_transform(self, codes):
        if self._index is None:
            raise ValueError("OrdinalEncoder: 请先 fit")
        width = _w11b_check_rows(codes, "OrdinalEncoder")
        if width != len(self.categories_):
            raise ValueError("OrdinalEncoder: 列数与 fit 时不一致")
        out = []
        for row in codes:
            values = []
            for j, c in enumerate(row):
                if c < 0 or c >= len(self.categories_[j]):
                    raise ValueError(f"OrdinalEncoder: 第 {j} 列编码 {c} 越界")
                values.append(self.categories_[j][c])
            out.append(values)
        return out


class OneHotEncoder:
    """多列类别特征 One-Hot 展开成 0/1 浮点列

    ``drop='first'`` 每列去掉第一个类别（避免共线）；``handle_unknown='ignore'``
    时未见的类别整列留 0，``'error'`` 时报错。
    """

    def __init__(self, drop=None, handle_unknown="error"):
        if drop not in (None, "first"):
            raise ValueError(f"OneHotEncoder: drop 只能是 None 或 'first'，收到 {drop!r}")
        if handle_unknown not in ("error", "ignore"):
            raise ValueError(
                f"OneHotEncoder: handle_unknown 只能是 'error'/'ignore'，收到 {handle_unknown!r}"
            )
        self.drop = drop
        self.handle_unknown = handle_unknown
        self.categories_ = None
        self._index = None

    def fit(self, x):
        width = _w11b_check_rows(x, "OneHotEncoder")
        self.categories_ = []
        self._index = []
        for j in range(width):
            cats = sorted(set(row[j] for row in x))
            if self.drop == "first" and len(cats) == 1:
                raise ValueError(
                    f"OneHotEncoder: 第 {j} 列只有 1 个类别，drop='first' 会把它整列删掉"
                )
            kept = cats[1:] if self.drop == "first" else cats
            self.categories_.append(kept)
            self._index.append({c: i for i, c in enumerate(cats)})
        return self

    def transform(self, x):
        if self._index is None:
            raise ValueError("OneHotEncoder: 请先 fit")
        width = _w11b_check_rows(x, "OneHotEncoder")
        if width != len(self._index):
            raise ValueError(
                f"OneHotEncoder: 列数 {width} 与 fit 时的 {len(self._index)} 不一致"
            )
        out = []
        for row in x:
            codes = []
            for j, v in enumerate(row):
                if v not in self._index[j]:
                    if self.handle_unknown == "error":
                        raise ValueError(f"OneHotEncoder: 第 {j} 列出现未知类别 {v!r}")
                    codes.extend([0.0] * len(self.categories_[j]))
                    continue
                idx = self._index[j][v]
                base = 0 if self.drop != "first" else 1
                width_j = len(self.categories_[j])
                vec = [0.0] * width_j
                if idx >= base:
                    vec[idx - base] = 1.0
                codes.extend(vec)
            out.append(codes)
        return out

    def fit_transform(self, x):
        return self.fit(x).transform(x)

    def get_feature_names(self):
        """返回展开后的列名，形如 ``x0=red``"""
        if self.categories_ is None:
            raise ValueError("OneHotEncoder: 请先 fit")
        names = []
        for j, cats in enumerate(self.categories_):
            for c in cats:
                names.append(f"x{j}={c}")
        return names


class TargetEncoder:
    """目标编码（带平滑）：``(sum_i + smoothing * prior) / (count_i + smoothing)``

    未见类别用全局均值。必须**只在训练集上 fit**，否则会泄漏标签。
    """

    def __init__(self, smoothing=1.0):
        if smoothing is None or isinstance(smoothing, bool) \
                or not isinstance(smoothing, (int, float)) or smoothing < 0.0:
            raise ValueError(f"TargetEncoder: smoothing 必须 >= 0，收到 {smoothing!r}")
        self.smoothing = float(smoothing)
        self.prior_ = None
        self.maps_ = None

    def fit(self, x, y):
        width = _w11b_check_rows(x, "TargetEncoder")
        if not isinstance(y, (list, tuple)) or len(y) != len(x):
            raise ValueError("TargetEncoder: y 必须与 x 等长")
        for v in y:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f"TargetEncoder: y 只能包含数值，收到 {v!r}")
        self.prior_ = sum(float(v) for v in y) / len(y)
        self.maps_ = []
        for j in range(width):
            sums = {}
            counts = {}
            for row, target in zip(x, y):
                key = row[j]
                sums[key] = sums.get(key, 0.0) + float(target)
                counts[key] = counts.get(key, 0) + 1
            table = {}
            for key, total in sums.items():
                table[key] = ((total + self.smoothing * self.prior_)
                              / (counts[key] + self.smoothing))
            self.maps_.append(table)
        return self

    def transform(self, x):
        if self.maps_ is None:
            raise ValueError("TargetEncoder: 请先 fit")
        width = _w11b_check_rows(x, "TargetEncoder")
        if width != len(self.maps_):
            raise ValueError("TargetEncoder: 列数与 fit 时不一致")
        out = []
        for row in x:
            out.append([self.maps_[j].get(row[j], self.prior_) for j in range(width)])
        return out

    def fit_transform(self, x, y):
        return self.fit(x, y).transform(x)


class FrequencyEncoder:
    """频率编码：类别出现次数 / 样本总数（未见类别记 0）"""

    def __init__(self):
        self.maps_ = None

    def fit(self, x):
        width = _w11b_check_rows(x, "FrequencyEncoder")
        n = float(len(x))
        self.maps_ = []
        for j in range(width):
            counts = {}
            for row in x:
                counts[row[j]] = counts.get(row[j], 0) + 1
            self.maps_.append({k: v / n for k, v in counts.items()})
        return self

    def transform(self, x):
        if self.maps_ is None:
            raise ValueError("FrequencyEncoder: 请先 fit")
        width = _w11b_check_rows(x, "FrequencyEncoder")
        if width != len(self.maps_):
            raise ValueError("FrequencyEncoder: 列数与 fit 时不一致")
        return [[self.maps_[j].get(row[j], 0.0) for j in range(width)] for row in x]

    def fit_transform(self, x):
        return self.fit(x).transform(x)


class WOEEncoder:
    """Weight of Evidence 编码（二分类）：

    ``WOE = log( (bad_i / bad_total) / (good_i / good_total) )``，
    ``bad`` 是 ``y=1``；加 ``smoothing`` 防止某一侧为 0 时取到 ``log(0)``。
    未见类别返回 0.0（既不支持也不反对）。
    """

    def __init__(self, smoothing=0.5):
        if smoothing is None or isinstance(smoothing, bool) \
                or not isinstance(smoothing, (int, float)) or smoothing <= 0.0:
            raise ValueError(f"WOEEncoder: smoothing 必须 > 0，收到 {smoothing!r}")
        self.smoothing = float(smoothing)
        self.maps_ = None

    def fit(self, x, y):
        width = _w11b_check_rows(x, "WOEEncoder")
        if not isinstance(y, (list, tuple)) or len(y) != len(x):
            raise ValueError("WOEEncoder: y 必须与 x 等长")
        bad = 0
        good = 0
        for v in y:
            if v not in (0, 1, 0.0, 1.0):
                raise ValueError(f"WOEEncoder: y 只能是 0/1，收到 {v!r}")
            if int(v) == 1:
                bad += 1
            else:
                good += 1
        if bad == 0 or good == 0:
            raise ValueError("WOEEncoder: y 必须同时包含 0 和 1")
        self.maps_ = []
        for j in range(width):
            stats = {}
            for row, target in zip(x, y):
                key = row[j]
                b, g = stats.get(key, (0, 0))
                if int(target) == 1:
                    b += 1
                else:
                    g += 1
                stats[key] = (b, g)
            table = {}
            for key, (b, g) in stats.items():
                p_bad = (b + self.smoothing) / (bad + 2 * self.smoothing)
                p_good = (g + self.smoothing) / (good + 2 * self.smoothing)
                table[key] = math.log(p_bad / p_good)
            self.maps_.append(table)
        return self

    def transform(self, x):
        if self.maps_ is None:
            raise ValueError("WOEEncoder: 请先 fit")
        width = _w11b_check_rows(x, "WOEEncoder")
        if width != len(self.maps_):
            raise ValueError("WOEEncoder: 列数与 fit 时不一致")
        return [[self.maps_[j].get(row[j], 0.0) for j in range(width)] for row in x]

    def fit_transform(self, x, y):
        return self.fit(x, y).transform(x)


class DataLoader:
    """简易数据加载器：按 batch 迭代，支持 shuffle / 自定义 sampler

    ``sampler``（产出下标）与 ``batch_sampler``（直接产出下标 batch）给出时，
    两者优先于 ``shuffle``；默认路径（两个都不传）的行为与旧版逐位相同。
    """

    def __init__(self, dataset: list, batch_size: int = 32, shuffle: bool = True,
                 seed=None, collate_fn=None, sampler=None, batch_sampler=None):
        if batch_sampler is None and (batch_size is None or batch_size <= 0):
            raise ValueError(f"DataLoader: batch_size 必须 >= 1，收到 {batch_size!r}")
        if sampler is not None and batch_sampler is not None:
            raise ValueError("DataLoader: sampler 与 batch_sampler 只能给一个")
        if sampler is not None and not hasattr(sampler, "__iter__"):
            raise TypeError("DataLoader: sampler 必须可迭代")
        if batch_sampler is not None and not hasattr(batch_sampler, "__iter__"):
            raise TypeError("DataLoader: batch_sampler 必须可迭代")
        self.dataset = dataset
        self.batch_size = batch_size
        self.shuffle = shuffle
        # 用局部 RNG：全局 random.shuffle 会推进调用方的随机状态，破坏可复现性
        self._rng = random.Random(seed)
        # collate_fn(batch) -> batch：自定义批次拼装（padding、转张量等）
        self.collate_fn = collate_fn
        self.sampler = sampler
        self.batch_sampler = batch_sampler

    def _collate(self, batch):
        if self.collate_fn is not None:
            return self.collate_fn(batch)
        return batch

    def __iter__(self):
        if self.batch_sampler is not None:
            for indices in self.batch_sampler:
                yield self._collate([self.dataset[i] for i in indices])
            return
        if self.sampler is not None:
            order = list(self.sampler)
        else:
            order = list(range(len(self.dataset)))
            if self.shuffle:
                self._rng.shuffle(order)
        for b in range(0, len(order), self.batch_size):
            chunk = order[b:b + self.batch_size]
            yield self._collate([self.dataset[i] for i in chunk])

    def __len__(self):
        if self.batch_sampler is not None:
            return len(self.batch_sampler)
        if self.sampler is not None:
            n = len(self.sampler)
            return (n + self.batch_size - 1) // self.batch_size
        return (len(self.dataset) + self.batch_size - 1) // self.batch_size


def k_fold_indices(n_samples: int, n_splits: int = 5, shuffle: bool = True,
                   seed: int = 42, stratify=None):
    """生成 K 折交叉验证的 (train_idx, val_idx) 列表（纯索引，不复制数据）。

    n_samples: 样本总数
    n_splits:  折数（>=2）
    stratify:  与样本等长的标签序列；给出时每折按类别分层
    """
    n_samples = int(n_samples)
    n_splits = int(n_splits)
    if n_samples <= 0:
        raise ValueError(f"k_fold_indices: n_samples 必须 > 0，收到 {n_samples}")
    if n_splits < 2:
        raise ValueError(f"k_fold_indices: n_splits 必须 >= 2，收到 {n_splits}")
    if n_splits > n_samples:
        raise ValueError(
            f"k_fold_indices: n_splits={n_splits} 超过样本数 {n_samples}"
        )
    rng = random.Random(seed)
    if stratify is not None:
        if len(stratify) != n_samples:
            raise ValueError(
                f"k_fold_indices: stratify 长度 {len(stratify)} 与样本数 {n_samples} 不一致"
            )
        groups = {}
        for idx, label in enumerate(stratify):
            groups.setdefault(label, []).append(idx)
        folds = [[] for _ in range(n_splits)]
        for label, idxs in groups.items():
            rng.shuffle(idxs)
            for i, idx in enumerate(idxs):
                folds[i % n_splits].append(idx)
    else:
        order = list(range(n_samples))
        if shuffle:
            rng.shuffle(order)
        folds = [[] for _ in range(n_splits)]
        for i, idx in enumerate(order):
            folds[i % n_splits].append(idx)
    out = []
    for k in range(n_splits):
        val_idx = sorted(folds[k])
        val_set = set(val_idx)
        train_idx = [i for i in range(n_samples) if i not in val_set]
        out.append((train_idx, val_idx))
    return out


#  ======================================================================
#  切分扩展（GroupKFold / 时间序列切分 / Purged K-Fold）
#  ======================================================================

def _w11d_int(value, who, name, minimum=None):
    """校验整数超参（bool 不算整数）。"""
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError("%s: %s 必须是整数" % (who, name))
    if minimum is not None and value < minimum:
        raise ValueError("%s: %s 必须 >= %d，收到 %d" % (who, name, minimum, value))
    return value


def group_k_fold_indices(groups, n_splits=5, seed=42):
    """按**组**切 K 折：同一组的样本永远落在同一侧，避免同组信息泄漏。

    groups: 与样本等长的组 id 序列（任意可哈希对象）
    返回 [(train_idx, val_idx)] * n_splits。

    分配是确定性的：组按「样本数降序、组 id 升序」排列后，依次塞进当前
    样本数最少的折；`seed` 目前只用于参数校验不参与分配（保留兼容位）。
    """
    if not isinstance(groups, (list, tuple)) or not groups:
        raise ValueError("group_k_fold_indices: groups 必须是非空序列")
    n_samples = len(groups)
    n_splits = _w11d_int(n_splits, "group_k_fold_indices", "n_splits", 2)
    _w11d_int(seed, "group_k_fold_indices", "seed")

    counts = {}
    for idx, g in enumerate(groups):
        try:
            counts[g] = counts.get(g, 0) + 1
        except TypeError:
            raise TypeError(
                "group_k_fold_indices: 第 %d 个组 id 不可哈希（%r）" % (idx, g))
    n_groups = len(counts)
    if n_splits > n_groups:
        raise ValueError(
            "group_k_fold_indices: n_splits=%d 超过不同组数 %d"
            % (n_splits, n_groups))

    order = sorted(counts.keys(), key=lambda g: (-counts[g], str(g)))
    fold_of = {}
    load = [0] * n_splits
    for g in order:
        best = 0
        for k in range(1, n_splits):
            if load[k] < load[best]:
                best = k
        fold_of[g] = best
        load[best] += counts[g]

    folds = [[] for _ in range(n_splits)]
    for idx, g in enumerate(groups):
        folds[fold_of[g]].append(idx)
    out = []
    for k in range(n_splits):
        val_idx = sorted(folds[k])
        val_set = set(val_idx)
        train_idx = [i for i in range(n_samples) if i not in val_set]
        out.append((train_idx, val_idx))
    return out


def time_series_split_indices(n_samples, n_splits=5, test_size=None, gap=0,
                              expanding=True, window=None):
    """时间序列切分：每一折的测试块都**在**训练块之后，绝不看未来。

    n_samples:  样本总数
    n_splits:   折数（>=1）
    test_size:  每块测试集大小；None 时取 n_samples // (n_splits + 1)
    gap:        训练块与测试块之间隔开的样本数（防标签泄漏）
    expanding:  True 时训练窗口从 0 开始扩张；False 时滚动窗口（长度默认取首折训练长）
    window:     滚动窗口长度；只在不扩张时生效
    """
    n_samples = _w11d_int(n_samples, "time_series_split_indices", "n_samples", 1)
    n_splits = _w11d_int(n_splits, "time_series_split_indices", "n_splits", 1)
    gap = _w11d_int(gap, "time_series_split_indices", "gap", 0)
    if test_size is None:
        test_size = n_samples // (n_splits + 1)
    test_size = _w11d_int(test_size, "time_series_split_indices", "test_size", 1)
    #  唯一真正的约束是「首折的训练集非空」：n_samples - n_splits*test_size - gap > 0。
    need = n_splits * test_size + gap
    if need >= n_samples:
        raise ValueError(
            "time_series_split_indices: 样本数 %d 不够（需要 > n_splits*test_size + "
            "gap = %d）" % (n_samples, need))
    if window is not None:
        window = _w11d_int(window, "time_series_split_indices", "window", 1)

    starts = [n_samples - (n_splits - k) * test_size for k in range(n_splits)]
    base_train = starts[0] - gap
    if base_train <= 0:
        raise ValueError(
            "time_series_split_indices: 首折训练集为空（test_size=%d、gap=%d、"
            "n_samples=%d）" % (test_size, gap, n_samples))
    win = base_train if window is None else window
    out = []
    for start in starts:
        train_end = start - gap
        if expanding:
            train_idx = list(range(0, train_end))
        else:
            train_idx = list(range(max(0, train_end - win), train_end))
        test_idx = list(range(start, min(start + test_size, n_samples)))
        out.append((train_idx, test_idx))
    return out


def purged_kfold_indices(n_samples, n_splits=5, purge=0, embargo=0):
    """连续分块的 K 折 + 清洗（purge）/ 禁运（embargo）。

    测试块是连续的 `[a, b)`；训练集剔除 `[a-purge, b+purge)`，再禁运测试块之后
    紧邻的 `embargo` 个样本——时间序列里模型在测试块附近「背答案」就靠这两刀。

    返回 (train_idx, val_idx) 列表，共 n_splits 个。
    """
    n_samples = _w11d_int(n_samples, "purged_kfold_indices", "n_samples", 2)
    n_splits = _w11d_int(n_splits, "purged_kfold_indices", "n_splits", 2)
    purge = _w11d_int(purge, "purged_kfold_indices", "purge", 0)
    embargo = _w11d_int(embargo, "purged_kfold_indices", "embargo", 0)
    if n_splits > n_samples:
        raise ValueError(
            "purged_kfold_indices: n_splits=%d 超过样本数 %d" % (n_splits, n_samples))

    out = []
    for k in range(n_splits):
        a = (k * n_samples) // n_splits
        b = ((k + 1) * n_samples) // n_splits
        if b <= a:
            raise ValueError(
                "purged_kfold_indices: 第 %d 折为空（n_samples=%d、n_splits=%d）"
                % (k, n_samples, n_splits))
        ban_lo = max(0, a - purge)
        ban_hi = min(n_samples, b + purge + embargo)
        val_idx = list(range(a, b))
        train_idx = [i for i in range(n_samples)
                     if i < ban_lo or i >= ban_hi]
        if not train_idx:
            raise ValueError(
                "purged_kfold_indices: 第 %d 折清洗后训练集为空（purge=%d、embargo=%d）"
                % (k, purge, embargo))
        out.append((train_idx, val_idx))
    return out


class StandardScaler:
    """逐特征标准化：(x - mean) / std（std 为 0 时按 1 处理，不做缩放）"""

    def __init__(self):
        self.mean_ = None
        self.std_ = None

    def _check(self, x):
        if not isinstance(x, (list, tuple)) or not x:
            raise ValueError("StandardScaler: 输入必须是非空的二维列表")
        width = len(x[0])
        if width == 0:
            raise ValueError("StandardScaler: 样本特征维度不能为 0")
        for row in x:
            if len(row) != width:
                raise ValueError(
                    f"StandardScaler: 各样本维度不一致（{len(row)} != {width}）"
                )
        return width

    def fit(self, x):
        width = self._check(x)
        n = len(x)
        self.mean_ = [sum(row[j] for row in x) / n for j in range(width)]
        self.std_ = []
        for j in range(width):
            var = sum((row[j] - self.mean_[j]) ** 2 for row in x) / n
            s = math.sqrt(var)
            self.std_.append(s if s > 0.0 else 1.0)
        return self

    def transform(self, x):
        if self.mean_ is None:
            raise ValueError("StandardScaler: 请先 fit")
        self._check(x)
        return [[(row[j] - self.mean_[j]) / self.std_[j]
                 for j in range(len(self.mean_))] for row in x]

    def fit_transform(self, x):
        return self.fit(x).transform(x)

    def inverse_transform(self, x):
        if self.mean_ is None:
            raise ValueError("StandardScaler: 请先 fit")
        self._check(x)
        return [[row[j] * self.std_[j] + self.mean_[j]
                 for j in range(len(self.mean_))] for row in x]


class MinMaxScaler:
    """逐特征缩放到 [feature_range]（默认 [0, 1]；极差为 0 时映射到下界）"""

    def __init__(self, feature_range=(0.0, 1.0)):
        lo, hi = feature_range
        if not (lo < hi):
            raise ValueError(
                f"MinMaxScaler: feature_range 要求 lo < hi，收到 {feature_range!r}"
            )
        self.range_ = (float(lo), float(hi))
        self.data_min_ = None
        self.data_max_ = None

    def _check(self, x):
        if not isinstance(x, (list, tuple)) or not x:
            raise ValueError("MinMaxScaler: 输入必须是非空的二维列表")
        width = len(x[0])
        if width == 0:
            raise ValueError("MinMaxScaler: 样本特征维度不能为 0")
        for row in x:
            if len(row) != width:
                raise ValueError(
                    f"MinMaxScaler: 各样本维度不一致（{len(row)} != {width}）"
                )
        return width

    def fit(self, x):
        width = self._check(x)
        self.data_min_ = [min(row[j] for row in x) for j in range(width)]
        self.data_max_ = [max(row[j] for row in x) for j in range(width)]
        return self

    def transform(self, x):
        if self.data_min_ is None:
            raise ValueError("MinMaxScaler: 请先 fit")
        self._check(x)
        lo, hi = self.range_
        out = []
        for row in x:
            new_row = []
            for j in range(len(self.data_min_)):
                span = self.data_max_[j] - self.data_min_[j]
                if span > 0.0:
                    new_row.append(lo + (row[j] - self.data_min_[j]) / span * (hi - lo))
                else:
                    new_row.append(lo)
            out.append(new_row)
        return out

    def fit_transform(self, x):
        return self.fit(x).transform(x)

    def inverse_transform(self, x):
        if self.data_min_ is None:
            raise ValueError("MinMaxScaler: 请先 fit")
        self._check(x)
        lo, hi = self.range_
        out = []
        for row in x:
            new_row = []
            for j in range(len(self.data_min_)):
                span = self.data_max_[j] - self.data_min_[j]
                if span > 0.0 and hi > lo:
                    new_row.append(
                        self.data_min_[j] + (row[j] - lo) / (hi - lo) * span
                    )
                else:
                    new_row.append(self.data_min_[j])
            out.append(new_row)
        return out


#  ======================================================================
#  文本增强（同义词 / EDA / Token Dropout）与音频增强（概念）
#  ======================================================================

def _w11h_tokens(tokens, who):
    if not isinstance(tokens, (list, tuple)):
        raise TypeError("%s: tokens 必须是列表" % who)
    if not tokens:
        raise ValueError("%s: tokens 不能为空" % who)
    for t in tokens:
        if not isinstance(t, (str, int)) or isinstance(t, bool):
            raise TypeError("%s: token 必须是字符串或整数" % who)
    return list(tokens)


def _w11h_synonyms(synonyms, who):
    if not isinstance(synonyms, dict):
        raise TypeError("%s: synonyms 必须是 dict（token -> 同义词列表）" % who)
    for key, vals in synonyms.items():
        if not isinstance(vals, (list, tuple)):
            raise TypeError("%s: 同义词表 %r 必须是列表" % (who, key))
        for v in vals:
            if not isinstance(v, (str, int)) or isinstance(v, bool):
                raise TypeError("%s: 同义词必须是字符串或整数" % who)
    return synonyms


def synonym_replace(tokens, synonyms, p=0.1, seed=None):
    """逐 token 以概率 `p` 换成同义词表里的随机一个（没有同义词的 token 跳过）。"""
    toks = _w11h_tokens(tokens, "synonym_replace")
    syn = _w11h_synonyms(synonyms, "synonym_replace")
    if isinstance(p, bool) or not isinstance(p, (int, float)):
        raise TypeError("synonym_replace: p 必须是数字")
    if not 0.0 <= p <= 1.0:
        raise ValueError("synonym_replace: p 必须在 [0, 1] 内")
    rng = random.Random(seed)
    out = []
    for t in toks:
        cands = syn.get(t)
        if cands and rng.random() < p:
            out.append(cands[rng.randrange(len(cands))])
        else:
            out.append(t)
    return out


def random_insert(tokens, synonyms, n=1, seed=None):
    """EDA 随机插入：每次随机选一个 token，把它随机的一个同义词插入随机位置。"""
    toks = _w11h_tokens(tokens, "random_insert")
    syn = _w11h_synonyms(synonyms, "random_insert")
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("random_insert: n 必须是整数")
    if n < 0:
        raise ValueError("random_insert: n 不能为负")
    rng = random.Random(seed)
    out = list(toks)
    usable = [t for t in toks if syn.get(t)]
    if n > 0 and not usable:
        raise ValueError("random_insert: 没有任何 token 有同义词，无法插入")
    for _ in range(n):
        src = usable[rng.randrange(len(usable))]
        cands = syn[src]
        new = cands[rng.randrange(len(cands))]
        out.insert(rng.randrange(len(out) + 1), new)
    return out


def random_swap(tokens, n=1, seed=None):
    """EDA 随机交换：随机挑两个不同位置交换，重复 `n` 次（多集不变）。"""
    toks = _w11h_tokens(tokens, "random_swap")
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("random_swap: n 必须是整数")
    if n < 0:
        raise ValueError("random_swap: n 不能为负")
    if len(toks) < 2:
        raise ValueError("random_swap: 至少需要 2 个 token")
    rng = random.Random(seed)
    out = list(toks)
    for _ in range(n):
        i = rng.randrange(len(out))
        j = rng.randrange(len(out) - 1)
        if j >= i:
            j += 1
        out[i], out[j] = out[j], out[i]
    return out


def random_delete(tokens, p=0.1, seed=None):
    """EDA 随机删除：逐 token 以概率 `p` 删除，至少保留 1 个 token。"""
    toks = _w11h_tokens(tokens, "random_delete")
    if isinstance(p, bool) or not isinstance(p, (int, float)):
        raise TypeError("random_delete: p 必须是数字")
    if not 0.0 <= p <= 1.0:
        raise ValueError("random_delete: p 必须在 [0, 1] 内")
    rng = random.Random(seed)
    out = [t for t in toks if rng.random() >= p]
    if not out:
        out = [toks[rng.randrange(len(toks))]]
    return out


def token_dropout(tokens, p=0.1, seed=None):
    """Token Dropout：逐 token 独立丢弃（等价于随机删除，但语义是训练期正则）。

    与 `random_delete` 的差别只在约定：本函数面向「训练时把 token 抹掉」，
    同样保证至少保留 1 个 token；要按 EDA 的 alpha 比例删除请用 `eda_augment`。
    """
    toks = _w11h_tokens(tokens, "token_dropout")
    if isinstance(p, bool) or not isinstance(p, (int, float)):
        raise TypeError("token_dropout: p 必须是数字")
    if not 0.0 <= p < 1.0:
        raise ValueError("token_dropout: p 必须在 [0, 1) 内")
    rng = random.Random(seed)
    out = [t for t in toks if rng.random() >= p]
    return out if out else [toks[rng.randrange(len(toks))]]


def eda_augment(tokens, synonyms, num_aug=4, alpha_sr=0.1, alpha_ri=0.1,
                alpha_rs=0.1, p_rd=0.1, seed=None):
    """EDA：对每个副本依次做 同义词替换 → 随机插入 → 随机交换 → 随机删除。

    每个操作的次数按 `alpha * 长度` 取整（至少 0），`p_rd` 是删除概率。
    返回 `num_aug` 个增强后的 token 列表（不含原句）。
    """
    toks = _w11h_tokens(tokens, "eda_augment")
    syn = _w11h_synonyms(synonyms, "eda_augment")
    if isinstance(num_aug, bool) or not isinstance(num_aug, int):
        raise TypeError("eda_augment: num_aug 必须是整数")
    if num_aug < 1:
        raise ValueError("eda_augment: num_aug 必须 >= 1")
    for name, v in (("alpha_sr", alpha_sr), ("alpha_ri", alpha_ri),
                    ("alpha_rs", alpha_rs), ("p_rd", p_rd)):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise TypeError("eda_augment: %s 必须是数字" % name)
        if not 0.0 <= v <= 1.0:
            raise ValueError("eda_augment: %s 必须在 [0, 1] 内" % name)
    n = len(toks)
    n_sr = max(1, int(alpha_sr * n)) if alpha_sr > 0 else 0
    n_ri = max(1, int(alpha_ri * n)) if alpha_ri > 0 else 0
    n_rs = max(1, int(alpha_rs * n)) if alpha_rs > 0 else 0
    rng = random.Random(seed)
    out = []
    for _ in range(num_aug):
        cur = list(toks)
        if n_sr:
            idxs = list(range(len(cur)))
            rng.shuffle(idxs)
            for pos in idxs[:min(n_sr, len(cur))]:
                cands = syn.get(cur[pos])
                if cands:
                    cur[pos] = cands[rng.randrange(len(cands))]
        if n_ri:
            usable = [t for t in cur if syn.get(t)]
            for _i in range(n_ri):
                if not usable:
                    break
                src = usable[rng.randrange(len(usable))]
                cands = syn[src]
                cur.insert(rng.randrange(len(cur) + 1),
                           cands[rng.randrange(len(cands))])
        if n_rs and len(cur) >= 2:
            for _i in range(n_rs):
                i = rng.randrange(len(cur))
                j = rng.randrange(len(cur) - 1)
                if j >= i:
                    j += 1
                cur[i], cur[j] = cur[j], cur[i]
        if p_rd > 0:
            kept = [t for t in cur if rng.random() >= p_rd]
            cur = kept if kept else [cur[rng.randrange(len(cur))]]
        out.append(cur)
    return out


def _w11h_wave(x, who):
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError("%s: 波形必须是非空的一维列表" % who)
    for v in x:
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise TypeError("%s: 采样值必须是数字" % who)
    return [float(v) for v in x]


def audio_gain(waveform, db=0.0):
    """按分贝缩放振幅：`out = x * 10**(db/20)`（0 dB 原样返回）。"""
    w = _w11h_wave(waveform, "audio_gain")
    if isinstance(db, bool) or not isinstance(db, (int, float)):
        raise TypeError("audio_gain: db 必须是数字")
    g = 10.0 ** (db / 20.0)
    return [v * g for v in w]


def audio_add_noise(waveform, snr_db=10.0, seed=None):
    """加高斯白噪声，按整体信号功率与噪声功率的比值控制 SNR（dB）。

    噪声幅度按 `sqrt(signal_power / noise_power * 10**(-snr/10))` 缩放；全零波形时
    直接返回原波形（没有信号功率可参照）。
    """
    w = _w11h_wave(waveform, "audio_add_noise")
    if isinstance(snr_db, bool) or not isinstance(snr_db, (int, float)):
        raise TypeError("audio_add_noise: snr_db 必须是数字")
    sig_p = sum(v * v for v in w) / len(w)
    if sig_p <= 0.0:
        return list(w)
    rng = random.Random(seed)
    noise = [rng.gauss(0.0, 1.0) for _ in w]
    noise_p = sum(v * v for v in noise) / len(noise)
    if noise_p <= 0.0:
        return list(w)
    scale = math.sqrt(sig_p / noise_p * (10.0 ** (-float(snr_db) / 10.0)))
    return [w[i] + scale * noise[i] for i in range(len(w))]


def audio_time_shift(waveform, shift=0, fill=0.0):
    """整段平移 `shift` 个采样（正数右移），空出来的位置填 `fill`。"""
    w = _w11h_wave(waveform, "audio_time_shift")
    if isinstance(shift, bool) or not isinstance(shift, int):
        raise TypeError("audio_time_shift: shift 必须是整数")
    if abs(shift) >= len(w):
        raise ValueError("audio_time_shift: |shift| 必须小于波形长度 %d" % len(w))
    if isinstance(fill, bool) or not isinstance(fill, (int, float)):
        raise TypeError("audio_time_shift: fill 必须是数字")
    n = len(w)
    out = [float(fill)] * n
    for i in range(n):
        j = i + shift
        if 0 <= j < n:
            out[j] = w[i]
    return out


def audio_clip(waveform, limit=1.0):
    """硬限幅到 `[-limit, limit]`（模拟削波失真）。"""
    w = _w11h_wave(waveform, "audio_clip")
    if isinstance(limit, bool) or not isinstance(limit, (int, float)):
        raise TypeError("audio_clip: limit 必须是数字")
    if limit <= 0:
        raise ValueError("audio_clip: limit 必须为正")
    lim = float(limit)
    return [lim if v > lim else (-lim if v < -lim else v) for v in w]


def audio_polarity_invert(waveform):
    """极性反转（相位取反），用于测试模型对绝对相位的敏感性。"""
    return [-v for v in _w11h_wave(waveform, "audio_polarity_invert")]

"""音频质量指标：STOI（可懂度）与 PESQ 轻量代理。

两者都只依赖本库的朴素 DFT / 梅尔滤波器组，不下载任何模型：
- `stoi_score` 是短时客观可懂度的简化版：按帧做频带能量包络归一化后在频带间求相关。
- `pesq_score` 是感知语音质量评分的轻量代理：对数频带谱失真映射到 [1.0, 4.5]，
  没有 PESQ 的时域对齐、心理声学模型和真实 MOS 标定，只能用于相对比较。
"""


def _au_trim_pair(clean, degraded, who, frame_length):
    a = _w11h_wave(clean, who + " clean")
    b = _w11h_wave(degraded, who + " degraded")
    n = min(len(a), len(b))
    if n < frame_length:
        raise ValueError(
            "%s: 两条波形对齐后的长度 %d 少于帧长 %d" % (who, n, frame_length))
    return a[:n], b[:n]


def _au_band_energies(frames, sample_rate, frame_length, n_bands, fmin, fmax):
    filters = mel_filterbank(sample_rate, frame_length, n_bands, fmin, fmax)
    out = []
    for fr in frames:
        mean = sum(fr) / len(fr)
        centered = [v - mean for v in fr]
        power = dft_power(centered)
        row = []
        for m in range(n_bands):
            acc = 0.0
            for i in range(len(power)):
                acc += filters[m][i] * power[i] * power[i]
            row.append(math.sqrt(acc))
        out.append(row)
    return out


def _au_check_params(who, sample_rate, frame_length, hop_length, n_bands, fmin, fmax):
    if isinstance(frame_length, bool) or not isinstance(frame_length, int):
        raise TypeError("%s: frame_length 必须是整数" % who)
    if frame_length < 32:
        raise ValueError("%s: frame_length 必须 >= 32" % who)
    _w17e_pos_int(hop_length, who, "hop_length")
    if hop_length > frame_length:
        raise ValueError("%s: hop_length 不能大于 frame_length" % who)
    if isinstance(sample_rate, bool) or not isinstance(sample_rate, int):
        raise TypeError("%s: sample_rate 必须是整数" % who)
    if sample_rate <= 0:
        raise ValueError("%s: sample_rate 必须为正" % who)
    _w17e_pos_int(n_bands, who, "n_bands")
    if n_bands > frame_length // 2 + 1:
        raise ValueError("%s: n_bands 不能超过频点数 %d" % (who, frame_length // 2 + 1))
    for name, val in (("fmin", fmin), ("fmax", fmax)):
        if val is None:
            continue
        if isinstance(val, bool) or not isinstance(val, (int, float)):
            raise TypeError("%s: %s 必须是数字或 None" % (who, name))
        if not math.isfinite(val):
            raise ValueError("%s: %s 必须是有限数字" % (who, name))
    lo = 0.0 if fmin is None else float(fmin)
    hi = sample_rate / 2.0 if fmax is None else float(fmax)
    if lo < 0.0:
        raise ValueError("%s: fmin 不能为负" % who)
    if hi <= lo:
        raise ValueError("%s: fmax 必须大于 fmin" % who)
    if hi > sample_rate / 2.0 + 1e-9:
        raise ValueError("%s: fmax 不能超过奈奎斯特频率" % who)


def stoi_score(clean, degraded, sample_rate=16000, frame_length=256,
               hop_length=128, n_bands=8, fmin=0.0, fmax=None, eps=1e-12):
    """短时客观可懂度（STOI）简化版，返回 [0, 1]（1 = 完全相同）。

    做法：两条波形按 `frame_length`/`hop_length` 切帧 → 去除每帧均值后做 DFT →
    用梅尔滤波器组合成 `n_bands` 个频带能量 → 逐频带在时间轴上做零均值单位方差
    归一化并裁剪到 [-3, 3] → 逐频带求相关系数 → 对所有有效频带取平均。
    与标准 STOI 的差异：没有 1/3 倍频程重叠频带、没有静音帧扣除、没有最终映射。
    """
    if isinstance(eps, bool) or not isinstance(eps, (int, float)) or eps <= 0:
        raise ValueError("stoi_score: eps 必须是正数")
    _au_check_params("stoi_score", sample_rate, frame_length, hop_length,
                     n_bands, fmin, fmax)
    a, b = _au_trim_pair(clean, degraded, "stoi_score", frame_length)
    fa = frame_signal(a, frame_length, hop_length, pad=False)
    fb = frame_signal(b, frame_length, hop_length, pad=False)
    ea = _au_band_energies(fa, sample_rate, frame_length, n_bands, fmin, fmax)
    eb = _au_band_energies(fb, sample_rate, frame_length, n_bands, fmin, fmax)
    t_frames = len(ea)
    if t_frames < 2:
        raise ValueError("stoi_score: 帧数 %d 太少（至少 2 帧）" % t_frames)
    mean_ea = [sum(ea[t][m] for t in range(t_frames)) / t_frames for m in range(n_bands)]
    peak = max(mean_ea) if mean_ea else 0.0
    corrs = []
    for m in range(n_bands):
        if peak > 0.0 and mean_ea[m] < 1e-3 * peak:
            continue  # 该频带在干净信号里基本是静音，包络相关只会反映噪声
        xc = [ea[t][m] for t in range(t_frames)]
        xd = [eb[t][m] for t in range(t_frames)]
        mc = sum(xc) / t_frames
        md = sum(xd) / t_frames
        vc = sum((v - mc) ** 2 for v in xc) / t_frames
        vd = sum((v - md) ** 2 for v in xd) / t_frames
        if vc <= eps or vd <= eps:
            continue
        sc = math.sqrt(vc)
        sd = math.sqrt(vd)
        nc = [max(-3.0, min(3.0, (v - mc) / sc)) for v in xc]
        nd = [max(-3.0, min(3.0, (v - md) / sd)) for v in xd]
        num = sum(nc[i] * nd[i] for i in range(t_frames))
        den = math.sqrt(sum(v * v for v in nc) * sum(v * v for v in nd))
        if den <= eps:
            continue
        corr = num / den
        corrs.append(max(-1.0, min(1.0, corr)))
    if not corrs:
        return 1.0 if a == b else 0.0
    return max(0.0, min(1.0, sum(corrs) / len(corrs)))


def pesq_score(clean, degraded, sample_rate=16000, frame_length=256,
               hop_length=128, n_bands=16, fmin=0.0, fmax=None, eps=1e-10):
    """PESQ 轻量代理，返回 [1.0, 4.5]（4.5 = 完全相同，越大越好）。

    做法：切帧 → 每帧频带能量取对数 → 对每帧求 `mean((log Ec - log Ed)^2)` →
    对所有帧平均得到谱失真 `dist` → `score = 4.5 - 2.5*min(1, sqrt(dist))`。
    没有时域对齐、心理声学模型与真实 MOS 标定，仅用于同一对信号下的相对比较。
    """
    _au_check_params("pesq_score", sample_rate, frame_length, hop_length,
                     n_bands, fmin, fmax)
    a, b = _au_trim_pair(clean, degraded, "pesq_score", frame_length)
    fa = frame_signal(a, frame_length, hop_length, pad=False)
    fb = frame_signal(b, frame_length, hop_length, pad=False)
    ea = _au_band_energies(fa, sample_rate, frame_length, n_bands, fmin, fmax)
    eb = _au_band_energies(fb, sample_rate, frame_length, n_bands, fmin, fmax)
    t_frames = len(ea)
    mean_ea = [sum(ea[t][m] for t in range(t_frames)) / t_frames for m in range(n_bands)]
    peak = max(mean_ea) if mean_ea else 0.0
    active = [m for m in range(n_bands) if peak > 0.0 and mean_ea[m] >= 1e-3 * peak]
    if not active:
        return 4.5
    total = 0.0
    for t in range(t_frames):
        row = 0.0
        for m in active:
            lc = math.log(ea[t][m] + eps)
            ld = math.log(eb[t][m] + eps)
            row += (lc - ld) ** 2
        total += row / len(active)
    count = t_frames
    dist = total / count
    env_a = [sum(ea[t][m] for m in active) for t in range(t_frames)]
    env_b = [sum(eb[t][m] for m in active) for t in range(t_frames)]
    ma = sum(env_a) / t_frames
    mb = sum(env_b) / t_frames
    va = sum((v - ma) ** 2 for v in env_a) / t_frames
    vb = sum((v - mb) ** 2 for v in env_b) / t_frames
    if va <= eps or vb <= eps:
        env_corr = 1.0 if env_a == env_b else 0.0
    else:
        num = sum((env_a[i] - ma) * (env_b[i] - mb) for i in range(t_frames))
        env_corr = num / math.sqrt(va * vb * t_frames * t_frames)
        env_corr = max(-1.0, min(1.0, env_corr))
    score = 4.5 - 2.5 * min(1.0, math.sqrt(dist)) - 1.5 * (1.0 - env_corr)
    return max(1.0, min(4.5, score))

"""感知 / 视频分布指标：LPIPS 与 FVD 的轻量代理。

两者都不依赖预训练权重：
- `lpips_lite`：多尺度下采样 + 局部梯度（相当于固定卷积特征），比较归一化后的
  特征距离；值越小越相似，完全相同为 0。
- `fvd_lite`：把每一帧压成低维表征，再算两组帧表征的 Fréchet 距离（用对角协方差
  近似，避免小样本下协方差奇异）；值越小分布越接近，完全相同的两组为 0。
"""


def _pm_image(img, who):
    if not isinstance(img, (list, tuple)) or not img:
        raise ValueError("%s: 图像必须是非空的 (C,H,W) 列表" % who)
    channels = []
    for ch in img:
        if not isinstance(ch, (list, tuple)) or not ch:
            raise ValueError("%s: 每个通道必须是非空的二维列表" % who)
        rows = []
        width = None
        for row in ch:
            if not isinstance(row, (list, tuple)) or not row:
                raise ValueError("%s: 每行必须是非空列表" % who)
            if width is None:
                width = len(row)
            elif len(row) != width:
                raise ValueError("%s: 同一通道内行宽必须一致" % who)
            vals = []
            for v in row:
                if isinstance(v, bool) or not isinstance(v, (int, float)):
                    raise TypeError("%s: 像素必须是数字" % who)
                if not math.isfinite(v):
                    raise ValueError("%s: 像素必须是有限数字" % who)
                vals.append(float(v))
            rows.append(vals)
        channels.append(rows)
    height = len(channels[0])
    for ch in channels:
        if len(ch) != height:
            raise ValueError("%s: 各通道高度必须一致" % who)
        if len(ch[0]) != len(channels[0][0]):
            raise ValueError("%s: 各通道宽度必须一致" % who)
    return channels


def _pm_gray(img):
    c = len(img)
    h = len(img[0])
    w = len(img[0][0])
    out = []
    for r in range(h):
        row = []
        for col in range(w):
            row.append(sum(img[k][r][col] for k in range(c)) / c)
        out.append(row)
    return out


def _pm_pool(gray, scale):
    h = len(gray)
    w = len(gray[0])
    if scale <= 1:
        return [list(row) for row in gray]
    oh = h // scale
    ow = w // scale
    if oh < 1 or ow < 1:
        raise ValueError("lpips_lite: 图像尺寸太小，无法在 scale=%d 下池化" % scale)
    out = []
    for r in range(oh):
        row = []
        for c in range(ow):
            acc = 0.0
            for dr in range(scale):
                for dc in range(scale):
                    acc += gray[r * scale + dr][c * scale + dc]
            row.append(acc / (scale * scale))
        out.append(row)
    return out


def _pm_gradient_feature(gray):
    h = len(gray)
    w = len(gray[0])
    feats = []
    for r in range(h):
        for c in range(w):
            gx = gray[r][c + 1] - gray[r][c] if c + 1 < w else 0.0
            gy = gray[r + 1][c] - gray[r][c] if r + 1 < h else 0.0
            feats.append(gray[r][c])
            feats.append(gx)
            feats.append(gy)
    return feats


def _pm_unit(vec, eps=1e-12):
    norm = math.sqrt(sum(v * v for v in vec))
    if norm <= eps:
        return [0.0] * len(vec)
    return [v / norm for v in vec]


def lpips_lite(img_a, img_b, scales=(1, 2, 4), weights=None, eps=1e-8):
    """LPIPS 轻量代理（越小越相似，相同图像为 0）。

    特征 = 每个尺度下「平均池化后的灰度图 + 水平/垂直梯度」，特征向量逐尺度做
    单位化后计算均方误差；默认各尺度等权。没有预训练 VGG/AlexNet 权重，
    适合做相对比较（例如比较不同失真强度），不代表真实人类感知分数。
    """
    if not isinstance(scales, (list, tuple)) or not scales:
        raise ValueError("lpips_lite: scales 必须是非空列表")
    for s in scales:
        if isinstance(s, bool) or not isinstance(s, int) or s < 1:
            raise ValueError("lpips_lite: scales 中的每个值必须是 >=1 的整数")
    a = _pm_image(img_a, "lpips_lite")
    b = _pm_image(img_b, "lpips_lite")
    if len(a) != len(b) or len(a[0]) != len(b[0]) or len(a[0][0]) != len(b[0][0]):
        raise ValueError("lpips_lite: 两张图像的形状必须一致")
    ga = _pm_gray(a)
    gb = _pm_gray(b)
    if weights is None:
        w = [1.0 / len(scales)] * len(scales)
    else:
        if not isinstance(weights, (list, tuple)) or len(weights) != len(scales):
            raise ValueError("lpips_lite: weights 长度必须与 scales 一致")
        for v in weights:
            if isinstance(v, bool) or not isinstance(v, (int, float)) or v < 0:
                raise ValueError("lpips_lite: weights 必须是非负数字")
        tot = sum(float(v) for v in weights)
        if tot <= 0.0:
            raise ValueError("lpips_lite: weights 之和必须为正")
        w = [float(v) / tot for v in weights]
    total = 0.0
    for idx, scale in enumerate(scales):
        fa = _pm_unit(_pm_gradient_feature(_pm_pool(ga, scale)), eps)
        fb = _pm_unit(_pm_gradient_feature(_pm_pool(gb, scale)), eps)
        dim = len(fa)
        mse = sum((fa[i] - fb[i]) ** 2 for i in range(dim)) / dim
        total += w[idx] * math.sqrt(mse)
    return total


def _fvd_embed_frame(frame):
    gray = _pm_gray(frame)
    return _pm_unit(_pm_gradient_feature(_pm_pool(gray, 2)))


def fvd_lite(frames_a, frames_b, embed_fn=None, eps=1e-10):
    """FVD 轻量代理（越小分布越接近，完全相同为 0）。

    `embed_fn(frame)` 把单帧 (C,H,W) 映射为特征向量；默认用 1/2 池化后的梯度特征。
    用对角协方差近似 Fréchet 距离：
    `sqrt(||μa-μb||² + Σ_i (σa_i - σb_i)²)`，不需要矩阵平方根，小样本也稳定。
    不是真正的 FVD（没有 I3D 视频特征，也没有完整协方差），只用于相对比较。
    """
    if not isinstance(frames_a, (list, tuple)) or not frames_a:
        raise ValueError("fvd_lite: frames_a 必须是非空帧列表")
    if not isinstance(frames_b, (list, tuple)) or not frames_b:
        raise ValueError("fvd_lite: frames_b 必须是非空帧列表")
    if embed_fn is None:
        embed_fn = _fvd_embed_frame
    elif not callable(embed_fn):
        raise TypeError("fvd_lite: embed_fn 必须可调用")

    def _features(frames, who):
        out = []
        for i, fr in enumerate(frames):
            f = embed_fn(fr)
            if not isinstance(f, (list, tuple)) or not f:
                raise ValueError("%s: 第 %d 帧的特征必须是非空列表" % (who, i))
            vec = []
            for v in f:
                if isinstance(v, bool) or not isinstance(v, (int, float)):
                    raise TypeError("%s: 特征必须是数字" % who)
                if not math.isfinite(v):
                    raise ValueError("%s: 特征必须是有限数字" % who)
                vec.append(float(v))
            out.append(vec)
        if len(out) < 2:
            raise ValueError("%s: 至少需要 2 帧才能估计分布" % who)
        dim = len(out[0])
        for vec in out:
            if len(vec) != dim:
                raise ValueError("%s: 所有帧的特征维度必须一致" % who)
        return out

    fa = _features(frames_a, "fvd_lite frames_a")
    fb = _features(frames_b, "fvd_lite frames_b")
    if len(fa[0]) != len(fb[0]):
        raise ValueError("fvd_lite: 两组帧的特征维度必须一致")
    dim = len(fa[0])
    mu_a = [sum(fa[t][i] for t in range(len(fa))) / len(fa) for i in range(dim)]
    mu_b = [sum(fb[t][i] for t in range(len(fb))) / len(fb) for i in range(dim)]
    var_a = [sum((fa[t][i] - mu_a[i]) ** 2 for t in range(len(fa))) / len(fa) for i in range(dim)]
    var_b = [sum((fb[t][i] - mu_b[i]) ** 2 for t in range(len(fb))) / len(fb) for i in range(dim)]
    mean_term = sum((mu_a[i] - mu_b[i]) ** 2 for i in range(dim))
    var_term = sum((math.sqrt(var_a[i] + eps) - math.sqrt(var_b[i] + eps)) ** 2 for i in range(dim))
    return math.sqrt(max(0.0, mean_term + var_term))

#  ======================================================================
#  降维 / 不平衡采样 / 特征选择
#  ======================================================================

def _w11g_matrix(x, who):
    """校验纯数值二维矩阵（不允许 None），返回 (行数, 列数)。"""
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError("%s: 输入必须是非空的二维列表" % who)
    if not isinstance(x[0], (list, tuple)) or not x[0]:
        raise ValueError("%s: 输入必须是非空的二维列表" % who)
    width = len(x[0])
    for row in x:
        if not isinstance(row, (list, tuple)) or len(row) != width:
            raise ValueError("%s: 各样本维度不一致" % who)
        for v in row:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("%s: 特征值必须是数字（不允许 None/NaN）" % who)
    return len(x), width


def _w11g_check_y(y, n, who):
    if not isinstance(y, (list, tuple)):
        raise TypeError("%s: 标签必须是列表" % who)
    if len(y) != n:
        raise ValueError("%s: 标签数 %d 与样本数 %d 不一致" % (who, len(y), n))
    for v in y:
        if isinstance(v, bool) or not isinstance(v, (int, float, str)):
            raise TypeError("%s: 标签必须是数字或字符串" % who)
    return list(y)


def _w11g_pow_iter(cov, k, seed=12345):
    """对称矩阵前 k 个特征向量（幂迭代 + 收缩），比全量 Jacobi 快很多。"""
    d = len(cov)
    k = min(k, d)
    vecs = []
    vals = []
    rng = random.Random(seed)
    for _ in range(k):
        v = [rng.uniform(-1.0, 1.0) for _ in range(d)]
        for _it in range(200):
            w = [sum(cov[i][j] * v[j] for j in range(d)) for i in range(d)]
            for u in vecs:
                dot = sum(w[i] * u[i] for i in range(d))
                w = [w[i] - dot * u[i] for i in range(d)]
            nrm = math.sqrt(sum(w[i] * w[i] for i in range(d)))
            if nrm < 1e-14:
                break
            v = [w[i] / nrm for i in range(d)]
        lam = sum(v[i] * sum(cov[i][j] * v[j] for j in range(d)) for i in range(d))
        if lam < 0.0:
            break
        # 符号归一：绝对值最大的分量为正
        big = 0
        for i in range(d):
            if abs(v[i]) > abs(v[big]):
                big = i
        if v[big] < 0:
            v = [-u for u in v]
        vecs.append(v)
        vals.append(lam)
    return vals, vecs


class PCA:
    """主成分分析（协方差 + 幂迭代），支持白化与逆变换。

    `n_components` 超过特征数时自动夹到特征数；特征向量做符号归一（绝对值最大的
    分量为正）保证结果可复现。
    """

    def __init__(self, n_components=2, whiten=False):
        if isinstance(n_components, bool) or not isinstance(n_components, int):
            raise TypeError("PCA: n_components 必须是整数")
        if n_components < 1:
            raise ValueError("PCA: n_components 必须 >= 1")
        if not isinstance(whiten, bool):
            raise TypeError("PCA: whiten 必须是 bool")
        self.n_components = n_components
        self.whiten = whiten
        self.mean_ = None
        self.components_ = None
        self.explained_variance_ = None
        self.explained_variance_ratio_ = None

    def fit(self, x):
        n, d = _w11g_matrix(x, "PCA")
        if n < 2:
            raise ValueError("PCA: 至少需要 2 个样本")
        self.mean_ = [sum(row[j] for row in x) / n for j in range(d)]
        z = [[row[j] - self.mean_[j] for j in range(d)] for row in x]
        cov = [[sum(z[i][p] * z[i][q] for i in range(n)) / (n - 1)
                for q in range(d)] for p in range(d)]
        k = min(self.n_components, d)
        vals, vecs = _w11g_pow_iter(cov, k)
        if not vals:
            raise ValueError("PCA: 无法提取主成分（数据可能是常数）")
        total = sum(cov[i][i] for i in range(d))
        self.components_ = vecs
        self.explained_variance_ = vals
        self.explained_variance_ratio_ = [(v / total if total > 0 else 0.0)
                                          for v in vals]
        self.n_components_ = len(vals)
        self._scale = [math.sqrt(v) if v > 1e-12 else 1.0 for v in vals]
        return self

    def transform(self, x):
        if self.components_ is None:
            raise ValueError("PCA: 请先 fit")
        _n, d = _w11g_matrix(x, "PCA")
        if d != len(self.mean_):
            raise ValueError("PCA: 输入列数 %d 与 fit 时的 %d 不一致"
                             % (d, len(self.mean_)))
        out = []
        for row in x:
            z = [row[j] - self.mean_[j] for j in range(d)]
            proj = [sum(z[j] * comp[j] for j in range(d))
                    for comp in self.components_]
            if self.whiten:
                proj = [proj[i] / self._scale[i] for i in range(len(proj))]
            out.append(proj)
        return out

    def fit_transform(self, x):
        return self.fit(x).transform(x)

    def inverse_transform(self, z):
        if self.components_ is None:
            raise ValueError("PCA: 请先 fit")
        if not isinstance(z, (list, tuple)) or not z:
            raise ValueError("PCA: 输入必须是非空的二维列表")
        k = len(self.components_)
        d = len(self.mean_)
        out = []
        for row in z:
            if len(row) != k:
                raise ValueError("PCA: 每行必须是 %d 维（fit 出的成分数）" % k)
            vals = list(row)
            if self.whiten:
                vals = [vals[i] * self._scale[i] for i in range(k)]
            out.append([self.mean_[j] + sum(vals[i] * self.components_[i][j]
                                            for i in range(k))
                        for j in range(d)])
        return out


def _w11g_pairwise_sq(x):
    n = len(x)
    d2 = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            s = 0.0
            for p in range(len(x[i])):
                t = x[i][p] - x[j][p]
                s += t * t
            d2[i][j] = s
            d2[j][i] = s
    return d2


def _w11g_affinities(d2, perplexity):
    """按行二分搜 sigma，使每行熵等于 log(perplexity)，再对称化。"""
    n = len(d2)
    target = math.log(perplexity)
    p = [[0.0] * n for _ in range(n)]
    for i in range(n):
        lo, hi = 1e-8, 1e8
        beta = 1.0
        for _ in range(60):
            beta = 1.0 / ((lo + hi) / 2.0)
            row = [0.0] * n
            s = 0.0
            for j in range(n):
                if j == i:
                    continue
                row[j] = math.exp(-d2[i][j] * beta)
                s += row[j]
            if s <= 0.0:
                lo = (lo + hi) / 2.0
                continue
            ent = 0.0
            for j in range(n):
                if row[j] > 0.0:
                    q = row[j] / s
                    ent -= q * math.log(q)
            if ent > target:
                # 熵偏大 ⇒ 需要更大 beta ⇒ 更小 sigma ⇒ 收缩上界
                hi = (lo + hi) / 2.0
            else:
                lo = (lo + hi) / 2.0
        s = sum(math.exp(-d2[i][j] * beta) for j in range(n) if j != i)
        for j in range(n):
            if j != i and s > 0.0:
                p[i][j] = math.exp(-d2[i][j] * beta) / s
    out = [[(p[i][j] + p[j][i]) / (2.0 * n) for j in range(n)] for i in range(n)]
    return out


class TSNE:
    """简化 t-SNE：精确定点对（O(n²)），无 Barnes-Hut、无随机森林初始化。

    `perplexity` 必须小于样本数；前 `early_exaggeration_iter` 轮乘以
    `early_exaggeration`，之后动量从 0.5 切到 0.8。
    """

    def __init__(self, n_components=2, perplexity=5.0, learning_rate=None,
                 n_iter=250, early_exaggeration=12.0,
                 early_exaggeration_iter=50, seed=42):
        if isinstance(n_components, bool) or not isinstance(n_components, int):
            raise TypeError("TSNE: n_components 必须是整数")
        if n_components < 1:
            raise ValueError("TSNE: n_components 必须 >= 1")
        for name, v in (("perplexity", perplexity),
                        ("learning_rate", learning_rate),
                        ("early_exaggeration", early_exaggeration)):
            if v is None:
                continue
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("TSNE: %s 必须是数字" % name)
            if v <= 0:
                raise ValueError("TSNE: %s 必须为正" % name)
        if isinstance(n_iter, bool) or not isinstance(n_iter, int):
            raise TypeError("TSNE: n_iter 必须是整数")
        if n_iter < 1:
            raise ValueError("TSNE: n_iter 必须 >= 1")
        if isinstance(early_exaggeration_iter, bool) or \
                not isinstance(early_exaggeration_iter, int):
            raise TypeError("TSNE: early_exaggeration_iter 必须是整数")
        if early_exaggeration_iter < 0:
            raise ValueError("TSNE: early_exaggeration_iter 不能为负")
        self.n_components = n_components
        self.perplexity = float(perplexity)
        self.learning_rate = learning_rate
        self.n_iter = n_iter
        self.early_exaggeration = float(early_exaggeration)
        self.early_exaggeration_iter = early_exaggeration_iter
        self.seed = seed
        self.embedding_ = None
        self.kl_divergence_ = None

    def fit_transform(self, x):
        n, d = _w11g_matrix(x, "TSNE")
        if n < 3:
            raise ValueError("TSNE: 至少需要 3 个样本")
        if self.perplexity >= n:
            raise ValueError("TSNE: perplexity (%g) 必须小于样本数 (%d)"
                             % (self.perplexity, n))
        d2 = _w11g_pairwise_sq(x)
        pmat = _w11g_affinities(d2, self.perplexity)
        rng = random.Random(self.seed)
        y = [[rng.gauss(0.0, 1e-4) for _ in range(self.n_components)]
             for _ in range(n)]
        lr = self.learning_rate
        if lr is None:
            lr = max(n / 12.0, 50.0)
        vel = [[0.0] * self.n_components for _ in range(n)]
        kl = 0.0
        for it in range(self.n_iter):
            exag = self.early_exaggeration if it < self.early_exaggeration_iter else 1.0
            num = [[0.0] * n for _ in range(n)]
            total = 0.0
            for i in range(n):
                for j in range(i + 1, n):
                    s = 0.0
                    for c in range(self.n_components):
                        t = y[i][c] - y[j][c]
                        s += t * t
                    q = 1.0 / (1.0 + s)
                    num[i][j] = q
                    num[j][i] = q
                    total += 2.0 * q
            if total <= 0.0:
                total = 1.0
            kl = 0.0
            for i in range(n):
                for j in range(n):
                    if i == j or pmat[i][j] <= 0.0:
                        continue
                    q = num[i][j] / total
                    kl += pmat[i][j] * math.log(pmat[i][j] / max(q, 1e-300))
            grad = [[0.0] * self.n_components for _ in range(n)]
            for i in range(n):
                for j in range(n):
                    if i == j:
                        continue
                    w = (exag * pmat[i][j] - num[i][j] / total) * num[i][j]
                    for c in range(self.n_components):
                        grad[i][c] += 4.0 * w * (y[i][c] - y[j][c])
            mom = 0.5 if it < self.early_exaggeration_iter else 0.8
            for i in range(n):
                for c in range(self.n_components):
                    vel[i][c] = mom * vel[i][c] - lr * grad[i][c]
                    y[i][c] += vel[i][c]
            if it >= 100:
                mean = [sum(y[i][c] for i in range(n)) / n
                        for c in range(self.n_components)]
                for i in range(n):
                    for c in range(self.n_components):
                        y[i][c] -= mean[c]
        self.embedding_ = [list(row) for row in y]
        self.kl_divergence_ = kl
        return [list(row) for row in y]


def _w11g_neighbors(x, i, candidates, k):
    """在 `candidates` 里找第 `i` 个样本的 k 个最近邻（平方距离升序，排除自身）。"""
    d = len(x[0])
    scored = []
    for other in candidates:
        if other == i:
            continue
        s = 0.0
        for p in range(d):
            t = x[i][p] - x[other][p]
            s += t * t
        scored.append((s, other))
    scored.sort()
    return [j for _s, j in scored[:k]]


def _w11g_classes(y):
    seen = []
    for v in y:
        if v not in seen:
            seen.append(v)
    return seen


class SMOTE:
    """SMOTE 过采样：对每个少数类，在同类 k 近邻之间线性插值到与多数类等量。"""

    def __init__(self, k_neighbors=5, random_state=42):
        if isinstance(k_neighbors, bool) or not isinstance(k_neighbors, int):
            raise TypeError("SMOTE: k_neighbors 必须是整数")
        if k_neighbors < 1:
            raise ValueError("SMOTE: k_neighbors 必须 >= 1")
        self.k_neighbors = k_neighbors
        self.random_state = random_state
        self.n_majority_ = None

    def fit_resample(self, x, y):
        n, _d = _w11g_matrix(x, "SMOTE")
        labels = _w11g_check_y(y, n, "SMOTE")
        classes = _w11g_classes(labels)
        if len(classes) < 2:
            raise ValueError("SMOTE: 至少需要 2 个类别")
        counts = {c: sum(1 for v in labels if v == c) for c in classes}
        majority = max(counts.values())
        self.n_majority_ = majority
        rng = random.Random(self.random_state)
        out_x = [list(row) for row in x]
        out_y = list(labels)
        for c in classes:
            need = majority - counts[c]
            if need <= 0:
                continue
            idx = [i for i, v in enumerate(labels) if v == c]
            if len(idx) < 2:
                continue
            kk = min(self.k_neighbors, len(idx) - 1)
            for _ in range(need):
                src = idx[rng.randrange(len(idx))]
                nb = _w11g_neighbors(x, src, idx, kk)
                if not nb:
                    continue
                dst = nb[rng.randrange(len(nb))]
                gap = rng.random()
                out_x.append([x[src][p] + gap * (x[dst][p] - x[src][p])
                              for p in range(len(x[0]))])
                out_y.append(c)
        return out_x, out_y


class ADASYN:
    """ADASYN：按「k 邻域里多数类占比」给少数类样本加权，越难分越多合成。"""

    def __init__(self, k_neighbors=5, random_state=42):
        if isinstance(k_neighbors, bool) or not isinstance(k_neighbors, int):
            raise TypeError("ADASYN: k_neighbors 必须是整数")
        if k_neighbors < 1:
            raise ValueError("ADASYN: k_neighbors 必须 >= 1")
        self.k_neighbors = k_neighbors
        self.random_state = random_state
        self.weights_ = None

    def fit_resample(self, x, y):
        n, _d = _w11g_matrix(x, "ADASYN")
        labels = _w11g_check_y(y, n, "ADASYN")
        classes = _w11g_classes(labels)
        if len(classes) < 2:
            raise ValueError("ADASYN: 至少需要 2 个类别")
        counts = {c: sum(1 for v in labels if v == c) for c in classes}
        majority_label = max(classes, key=lambda c: counts[c])
        majority = counts[majority_label]
        rng = random.Random(self.random_state)
        out_x = [list(row) for row in x]
        out_y = list(labels)
        self.weights_ = {}
        for c in classes:
            if c == majority_label:
                continue
            need = majority - counts[c]
            if need <= 0:
                continue
            idx = [i for i, v in enumerate(labels) if v == c]
            if len(idx) < 2:
                continue
            kk = min(self.k_neighbors, n - 1)
            # 每个少数样本的「多数类邻居占比」
            ratio = []
            for i in idx:
                nb = _w11g_neighbors(x, i, list(range(n)), kk)
                if not nb:
                    ratio.append(0.0)
                    continue
                ratio.append(sum(1 for j in nb if labels[j] == majority_label)
                             / float(len(nb)))
            self.weights_[c] = ratio
            tot = sum(ratio)
            if tot <= 0.0:
                probs = [1.0 / len(idx)] * len(idx)
            else:
                probs = [r / tot for r in ratio]
            # 按概率分配 need 个合成样本（确定性：先按期望取整再补余数）
            quota = [int(need * pr) for pr in probs]
            rest = need - sum(quota)
            order = sorted(range(len(idx)), key=lambda t: (-probs[t], t))
            for t in range(rest):
                quota[order[t % len(order)]] += 1
            for pos, i in enumerate(idx):
                for _ in range(quota[pos]):
                    nb = _w11g_neighbors(x, i, idx, kk)
                    if not nb:
                        break
                    dst = nb[rng.randrange(len(nb))]
                    gap = rng.random()
                    out_x.append([x[i][p] + gap * (x[dst][p] - x[i][p])
                                  for p in range(len(x[0]))])
                    out_y.append(c)
        return out_x, out_y


class VarianceThreshold:
    """按列方差筛特征（population variance，与 sklearn 一致）。"""

    def __init__(self, threshold=0.0):
        if isinstance(threshold, bool) or not isinstance(threshold, (int, float)):
            raise TypeError("VarianceThreshold: threshold 必须是数字")
        if threshold < 0:
            raise ValueError("VarianceThreshold: threshold 不能为负")
        self.threshold = float(threshold)
        self.variances_ = None
        self.support_ = None

    def fit(self, x):
        n, d = _w11g_matrix(x, "VarianceThreshold")
        self.variances_ = []
        for j in range(d):
            m = sum(row[j] for row in x) / n
            v = sum((row[j] - m) ** 2 for row in x) / n
            self.variances_.append(v)
        self.support_ = [v > self.threshold for v in self.variances_]
        if not any(self.support_):
            raise ValueError("VarianceThreshold: 没有特征满足方差阈值")
        return self

    def transform(self, x):
        if self.support_ is None:
            raise ValueError("VarianceThreshold: 请先 fit")
        _n, d = _w11g_matrix(x, "VarianceThreshold")
        if d != len(self.support_):
            raise ValueError("VarianceThreshold: 输入列数 %d 与 fit 时的 %d 不一致"
                             % (d, len(self.support_)))
        keep = [j for j in range(d) if self.support_[j]]
        return [[row[j] for j in keep] for row in x]

    def fit_transform(self, x):
        return self.fit(x).transform(x)

    def get_support(self):
        if self.support_ is None:
            raise ValueError("VarianceThreshold: 请先 fit")
        return list(self.support_)


def _w11g_score(col, y, kind):
    n = len(col)
    if kind == "pearson":
        mx = sum(col) / n
        my = sum(y) / n
        num = sum((col[i] - mx) * (y[i] - my) for i in range(n))
        dx = math.sqrt(sum((col[i] - mx) ** 2 for i in range(n)))
        dy = math.sqrt(sum((y[i] - my) ** 2 for i in range(n)))
        if dx <= 0.0 or dy <= 0.0:
            return 0.0
        return abs(num / (dx * dy))
    if kind == "f_classif":
        classes = _w11g_classes(y)
        if len(classes) < 2:
            return 0.0
        # 注意：这里的均值必须是**特征**的总均值，不是标签均值
        m_all = sum(col) / n
        between = 0.0
        within = 0.0
        for c in classes:
            vals = [col[i] for i in range(n) if y[i] == c]
            if not vals:
                continue
            mc = sum(vals) / len(vals)
            between += len(vals) * (mc - m_all) ** 2
            within += sum((v - mc) ** 2 for v in vals)
        between /= (len(classes) - 1)
        within /= max(n - len(classes), 1)
        if within <= 0.0:
            return float("inf") if between > 0.0 else 0.0
        return between / within
    raise ValueError("SelectKBest: score_func 必须是 'f_classif' 或 'pearson'")


class SelectKBest:
    """按单变量分数取前 `k` 列；`score_func='f_classif'`（离散标签）或 `'pearson'`。"""

    def __init__(self, k=10, score_func="f_classif"):
        if isinstance(k, bool) or not isinstance(k, int):
            raise TypeError("SelectKBest: k 必须是整数")
        if k < 1:
            raise ValueError("SelectKBest: k 必须 >= 1")
        if score_func not in ("f_classif", "pearson"):
            raise ValueError("SelectKBest: score_func 必须是 'f_classif' 或 'pearson'")
        self.k = k
        self.score_func = score_func
        self.scores_ = None
        self.support_ = None

    def fit(self, x, y):
        n, d = _w11g_matrix(x, "SelectKBest")
        labels = _w11g_check_y(y, n, "SelectKBest")
        if self.score_func == "pearson":
            for v in labels:
                if not isinstance(v, (int, float)):
                    raise TypeError("SelectKBest: pearson 模式要求数值标签")
        k = min(self.k, d)
        self.scores_ = [_w11g_score([row[j] for row in x], labels, self.score_func)
                        for j in range(d)]
        order = sorted(range(d), key=lambda j: (-self.scores_[j], j))
        keep = set(order[:k])
        self.support_ = [j in keep for j in range(d)]
        self.k_ = k
        return self

    def transform(self, x):
        if self.support_ is None:
            raise ValueError("SelectKBest: 请先 fit")
        _n, d = _w11g_matrix(x, "SelectKBest")
        if d != len(self.support_):
            raise ValueError("SelectKBest: 输入列数 %d 与 fit 时的 %d 不一致"
                             % (d, len(self.support_)))
        keep = [j for j in range(d) if self.support_[j]]
        return [[row[j] for j in keep] for row in x]

    def fit_transform(self, x, y):
        return self.fit(x, y).transform(x)

    def get_support(self):
        if self.support_ is None:
            raise ValueError("SelectKBest: 请先 fit")
        return list(self.support_)


class RFE:
    """递归特征消除：用岭回归系数的绝对值排序，每轮丢掉 `step` 个最小的。

    `ranking_[j] == 1` 表示保留；被消除的特征按消除顺序给更大的序号（先被消除的最大）。
    """

    def __init__(self, n_features_to_select=1, step=1):
        for name, v in (("n_features_to_select", n_features_to_select), ("step", step)):
            if isinstance(v, bool) or not isinstance(v, int):
                raise TypeError("RFE: %s 必须是整数" % name)
            if v < 1:
                raise ValueError("RFE: %s 必须 >= 1" % name)
        self.n_features_to_select = n_features_to_select
        self.step = step
        self.support_ = None
        self.ranking_ = None

    def fit(self, x, y):
        n, d = _w11g_matrix(x, "RFE")
        labels = _w11g_check_y(y, n, "RFE")
        for v in labels:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("RFE: 需要数值标签")
        target = int(self.n_features_to_select)
        if target > d:
            raise ValueError("RFE: n_features_to_select (%d) 大于特征数 (%d)"
                             % (target, d))
        remaining = list(range(d))
        ranking = [1] * d
        round_no = 0
        while len(remaining) > target:
            feats = [[row[j] for j in remaining] for row in x]
            _m, _s, coef, _b = _w11f_ridge(feats, labels, 1e-8)
            order = sorted(range(len(remaining)), key=lambda t: (abs(coef[t]), t))
            drop = min(self.step, len(remaining) - target)
            eliminated = order[:drop]
            round_no += 1
            for t in eliminated:
                ranking[remaining[t]] = round_no
            gone = set(eliminated)
            remaining = [remaining[t] for t in range(len(remaining)) if t not in gone]
        self.support_ = [j in set(remaining) for j in range(d)]
        self.ranking_ = ranking
        self.n_features_ = len(remaining)
        return self

    def transform(self, x):
        if self.support_ is None:
            raise ValueError("RFE: 请先 fit")
        _n, d = _w11g_matrix(x, "RFE")
        if d != len(self.support_):
            raise ValueError("RFE: 输入列数 %d 与 fit 时的 %d 不一致"
                             % (d, len(self.support_)))
        keep = [j for j in range(d) if self.support_[j]]
        return [[row[j] for j in keep] for row in x]

    def fit_transform(self, x, y):
        return self.fit(x, y).transform(x)

    def get_support(self):
        if self.support_ is None:
            raise ValueError("RFE: 请先 fit")
        return list(self.support_)


class L1Selector:
    """L1（Lasso）特征选择：坐标下降求稀疏解，系数非零的列被保留。

    目标：`1/(2n)·||y - Xw||² + alpha·||w||₁`（特征先标准化、截距不惩罚）。
    """

    def __init__(self, alpha=0.1, max_iter=1000, tol=1e-6):
        if isinstance(alpha, bool) or not isinstance(alpha, (int, float)):
            raise TypeError("L1Selector: alpha 必须是数字")
        if alpha <= 0:
            raise ValueError("L1Selector: alpha 必须为正")
        if isinstance(max_iter, bool) or not isinstance(max_iter, int):
            raise TypeError("L1Selector: max_iter 必须是整数")
        if max_iter < 1:
            raise ValueError("L1Selector: max_iter 必须 >= 1")
        self.alpha = float(alpha)
        self.max_iter = max_iter
        self.tol = float(tol)
        self.coef_ = None
        self.support_ = None

    def fit(self, x, y):
        n, d = _w11g_matrix(x, "L1Selector")
        labels = _w11g_check_y(y, n, "L1Selector")
        for v in labels:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("L1Selector: 需要数值标签")
        mean = [sum(row[j] for row in x) / n for j in range(d)]
        std = []
        for j in range(d):
            v = sum((row[j] - mean[j]) ** 2 for row in x) / n
            s = math.sqrt(v)
            std.append(s if s > 0.0 else 1.0)
        z = [[(row[j] - mean[j]) / std[j] for j in range(d)] for row in x]
        y_bar = sum(labels) / n
        yc = [v - y_bar for v in labels]
        sq = [sum(z[i][j] ** 2 for i in range(n)) / n for j in range(d)]
        w = [0.0] * d
        for _it in range(self.max_iter):
            delta = 0.0
            for j in range(d):
                if sq[j] <= 0.0:
                    continue
                rho = sum(z[i][j] * (yc[i] - sum(z[i][p] * w[p] for p in range(d)
                                                  if p != j))
                          for i in range(n)) / n
                new = 0.0
                if rho > self.alpha:
                    new = (rho - self.alpha) / sq[j]
                elif rho < -self.alpha:
                    new = (rho + self.alpha) / sq[j]
                delta = max(delta, abs(new - w[j]))
                w[j] = new
            if delta <= self.tol:
                break
        self.coef_ = [w[j] / std[j] for j in range(d)]
        self.support_ = [abs(w[j]) > 1e-12 for j in range(d)]
        if not any(self.support_):
            raise ValueError("L1Selector: alpha=%g 太大，所有系数都被压成 0" % self.alpha)
        return self

    def transform(self, x):
        if self.support_ is None:
            raise ValueError("L1Selector: 请先 fit")
        _n, d = _w11g_matrix(x, "L1Selector")
        if d != len(self.support_):
            raise ValueError("L1Selector: 输入列数 %d 与 fit 时的 %d 不一致"
                             % (d, len(self.support_)))
        keep = [j for j in range(d) if self.support_[j]]
        return [[row[j] for j in keep] for row in x]

    def fit_transform(self, x, y):
        return self.fit(x, y).transform(x)

    def get_support(self):
        if self.support_ is None:
            raise ValueError("L1Selector: 请先 fit")
        return list(self.support_)

#  ======================================================================
#  缺失值填补（SimpleImputer / KNNImputer / IterativeImputer）
#  ======================================================================

def _w11f_matrix(x, who):
    """校验二维矩阵，允许 `None` 表示缺失；返回 (行数, 列数, 缺失个数)。"""
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError("%s: 输入必须是非空的二维列表" % who)
    if not isinstance(x[0], (list, tuple)) or not x[0]:
        raise ValueError("%s: 输入必须是非空的二维列表" % who)
    width = len(x[0])
    missing = 0
    for row in x:
        if not isinstance(row, (list, tuple)) or len(row) != width:
            raise ValueError("%s: 各样本维度不一致" % who)
        for v in row:
            if v is None:
                missing += 1
                continue
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("%s: 特征值必须是数字或 None（缺失）" % who)
    return len(x), width, missing


def _w11f_col(x, j):
    return [row[j] for row in x]


def _w11f_stats(col, strategy, fill_value=None):
    """按策略算一个统计量；整列全缺失时 mean/median 退化为 0.0。"""
    vals = [v for v in col if v is not None]
    if strategy == "constant":
        if fill_value is None:
            raise ValueError(
                "SimpleImputer: strategy='constant' 时必须给 fill_value")
        return float(fill_value)
    if not vals:
        return 0.0
    if strategy == "mean":
        return float(sum(vals)) / len(vals)
    if strategy == "median":
        return _w11e_median(vals)
    if strategy == "most_frequent":
        counts = {}
        for v in vals:
            counts[v] = counts.get(v, 0) + 1
        best = None
        best_n = -1
        for v in sorted(counts):
            if counts[v] > best_n:
                best, best_n = v, counts[v]
        return float(best)
    raise ValueError(
        "SimpleImputer: strategy 必须是 'mean'/'median'/'most_frequent'/'constant'")


class SimpleImputer:
    """按列统计量填补 `None`：`mean` / `median` / `most_frequent` / `constant`。

    整列全缺失时 `mean` / `median` 填 0.0（docstring 已写明，不做静默丢列）。
    """

    def __init__(self, strategy="mean", fill_value=None):
        if strategy not in ("mean", "median", "most_frequent", "constant"):
            raise ValueError(
                "SimpleImputer: strategy 必须是 'mean'/'median'/'most_frequent'"
                "/'constant'")
        if strategy == "constant":
            if fill_value is None:
                raise ValueError(
                    "SimpleImputer: strategy='constant' 时必须给 fill_value")
            if isinstance(fill_value, bool) or not isinstance(fill_value, (int, float)):
                raise TypeError("SimpleImputer: fill_value 必须是数字")
        elif fill_value is not None:
            raise ValueError(
                "SimpleImputer: 只有 strategy='constant' 才接受 fill_value")
        self.strategy = strategy
        self.fill_value = fill_value
        self.statistics_ = None

    def fit(self, x):
        _n, width, _m = _w11f_matrix(x, "SimpleImputer")
        self.statistics_ = [
            _w11f_stats(_w11f_col(x, j), self.strategy, self.fill_value)
            for j in range(width)]
        return self

    def transform(self, x):
        if self.statistics_ is None:
            raise ValueError("SimpleImputer: 请先 fit")
        _n, width, _m = _w11f_matrix(x, "SimpleImputer")
        if width != len(self.statistics_):
            raise ValueError(
                "SimpleImputer: 输入列数 %d 与 fit 时的 %d 不一致"
                % (width, len(self.statistics_)))
        return [[self.statistics_[j] if v is None else float(v)
                 for j, v in enumerate(row)] for row in x]

    def fit_transform(self, x):
        return self.fit(x).transform(x)


def _w11f_distance(a, b):
    """只在两边都观测到的列上算平方距离；返回 (距离², 共享列数)。"""
    total = 0.0
    shared = 0
    for u, v in zip(a, b):
        if u is None or v is None:
            continue
        d = u - v
        total += d * d
        shared += 1
    return total, shared


class KNNImputer:
    """用最近的 k 个训练样本填补缺失值（只在共同观测到的列上算距离）。

    weights='uniform' 时取平均，'distance' 时按 1/(d+eps) 加权；没有任何邻居与
    目标行有共同观测列时退回该列的 fit 均值。
    """

    def __init__(self, n_neighbors=5, weights="uniform"):
        if isinstance(n_neighbors, bool) or not isinstance(n_neighbors, int):
            raise TypeError("KNNImputer: n_neighbors 必须是整数")
        if n_neighbors < 1:
            raise ValueError("KNNImputer: n_neighbors 必须 >= 1")
        if weights not in ("uniform", "distance"):
            raise ValueError("KNNImputer: weights 必须是 'uniform' 或 'distance'")
        self.n_neighbors = n_neighbors
        self.weights = weights
        self._train = None
        self.fill_ = None

    def fit(self, x):
        _n, width, _m = _w11f_matrix(x, "KNNImputer")
        self._train = [[None if v is None else float(v) for v in row] for row in x]
        self.fill_ = []
        for j in range(width):
            col = [row[j] for row in self._train if row[j] is not None]
            self.fill_.append(sum(col) / len(col) if col else 0.0)
        return self

    def _impute_row(self, row):
        out = list(row)
        for j, v in enumerate(row):
            if v is not None:
                continue
            cands = []
            for tr in self._train:
                d2, shared = _w11f_distance(row, tr)
                if shared == 0 or tr[j] is None:
                    continue
                cands.append((d2, tr[j]))
            if not cands:
                out[j] = self.fill_[j]
                continue
            cands.sort(key=lambda p: p[0])
            picked = cands[:self.n_neighbors]
            if self.weights == "uniform":
                out[j] = sum(v2 for _d2, v2 in picked) / len(picked)
            else:
                num = 0.0
                den = 0.0
                for d2, v2 in picked:
                    wgt = 1.0 / (math.sqrt(d2) + 1e-12)
                    num += wgt * v2
                    den += wgt
                out[j] = num / den
        return out

    def transform(self, x):
        if self._train is None:
            raise ValueError("KNNImputer: 请先 fit")
        _n, width, _m = _w11f_matrix(x, "KNNImputer")
        if width != len(self.fill_):
            raise ValueError(
                "KNNImputer: 输入列数 %d 与 fit 时的 %d 不一致"
                % (width, len(self.fill_)))
        return [self._impute_row([None if v is None else float(v) for v in row])
                for row in x]

    def fit_transform(self, x):
        return self.fit(x).transform(x)


def _w11f_solve(a, b):
    """高斯消元（列主元）解 a·x = b；a 是 n×n 的 list of list。"""
    n = len(a)
    m = [list(a[i]) + [b[i]] for i in range(n)]
    for col in range(n):
        pivot = col
        for r in range(col + 1, n):
            if abs(m[r][col]) > abs(m[pivot][col]):
                pivot = r
        if abs(m[pivot][col]) < 1e-12:
            return None
        if pivot != col:
            m[col], m[pivot] = m[pivot], m[col]
        inv = 1.0 / m[col][col]
        for j in range(col, n + 1):
            m[col][j] *= inv
        for r in range(n):
            if r == col:
                continue
            f = m[r][col]
            if f == 0.0:
                continue
            for j in range(col, n + 1):
                m[r][j] -= f * m[col][j]
    return [m[i][n] for i in range(n)]


def _w11f_ridge(feats, target, alpha):
    """带截距的岭回归闭式解（先标准化特征），返回 (mean, std, coef, intercept)。"""
    n = len(feats)
    d = len(feats[0]) if feats else 0
    mean = [sum(feats[i][j] for i in range(n)) / n for j in range(d)]
    std = []
    for j in range(d):
        v = sum((feats[i][j] - mean[j]) ** 2 for i in range(n)) / n
        s = math.sqrt(v)
        std.append(s if s > 0.0 else 1.0)
    z = [[(feats[i][j] - mean[j]) / std[j] for j in range(d)] for i in range(n)]
    y_bar = sum(target) / n
    yc = [t - y_bar for t in target]
    if d == 0:
        return mean, std, [], y_bar
    a = [[sum(z[i][p] * z[i][q] for i in range(n)) + (alpha if p == q else 0.0)
          for q in range(d)] for p in range(d)]
    b = [sum(z[i][p] * yc[i] for i in range(n)) for p in range(d)]
    coef = _w11f_solve(a, b)
    if coef is None:
        coef = [0.0] * d
    return mean, std, coef, y_bar


class IterativeImputer:
    """轮转岭回归填补：每列用其余列（含已填补值）建模，循环 `max_iter` 次。

    初始值取列均值；每轮对每列拟合 `target ~ 其他列`（特征标准化 + 岭惩罚 `alpha`），
    只把预测值写回**原本缺失**的位置。最大相对变化小于 `tol` 时提前停止。

    docstring 说明：这是**单变量轮转**的近似多重填补，不提供 `sample_posterior`。
    """

    def __init__(self, max_iter=10, tol=1e-3, alpha=1e-6):
        if isinstance(max_iter, bool) or not isinstance(max_iter, int):
            raise TypeError("IterativeImputer: max_iter 必须是整数")
        if max_iter < 1:
            raise ValueError("IterativeImputer: max_iter 必须 >= 1")
        for name, v in (("tol", tol), ("alpha", alpha)):
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("IterativeImputer: %s 必须是数字" % name)
            if v < 0:
                raise ValueError("IterativeImputer: %s 不能为负" % name)
        self.max_iter = max_iter
        self.tol = float(tol)
        self.alpha = float(alpha)
        self.n_iter_ = 0
        self.fill_ = None

    def fit(self, x):
        _n, width, _m = _w11f_matrix(x, "IterativeImputer")
        self.fill_ = []
        for j in range(width):
            col = [row[j] for row in x if row[j] is not None]
            self.fill_.append(sum(col) / len(col) if col else 0.0)
        return self

    def transform(self, x):
        if self.fill_ is None:
            raise ValueError("IterativeImputer: 请先 fit")
        _n, width, _m = _w11f_matrix(x, "IterativeImputer")
        if width != len(self.fill_):
            raise ValueError(
                "IterativeImputer: 输入列数 %d 与 fit 时的 %d 不一致"
                % (width, len(self.fill_)))
        missing = [[v is None for v in row] for row in x]
        cur = [[self.fill_[j] if v is None else float(v) for j, v in enumerate(row)]
               for row in x]
        if not any(any(r) for r in missing):
            self.n_iter_ = 0
            return cur
        n = len(cur)
        for it in range(1, self.max_iter + 1):
            delta = 0.0
            for j in range(width):
                if not any(missing[i][j] for i in range(n)):
                    continue
                others = [k for k in range(width) if k != j]
                feats = [[cur[i][k] for k in others] for i in range(n)]
                obs = [i for i in range(n) if not missing[i][j]]
                if len(obs) < 2 or not others:
                    continue
                mean, std, coef, y_bar = _w11f_ridge(
                    [feats[i] for i in obs], [cur[i][j] for i in obs], self.alpha)
                for i in range(n):
                    if not missing[i][j]:
                        continue
                    pred = y_bar + sum(coef[p] * ((feats[i][p] - mean[p]) / std[p])
                                       for p in range(len(others)))
                    delta = max(delta, abs(pred - cur[i][j]))
                    cur[i][j] = pred
            self.n_iter_ = it
            if delta <= self.tol:
                break
        return cur

    def fit_transform(self, x):
        return self.fit(x).transform(x)

#  ======================================================================
#  Scaler 族（RobustScaler / MaxAbsScaler /
#          QuantileTransformer / PowerTransformer）
#  ======================================================================

def _w11e_matrix(x, who):
    """校验二维数值矩阵，返回特征宽度。"""
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError("%s: 输入必须是非空的二维列表" % who)
    if not isinstance(x[0], (list, tuple)) or not x[0]:
        raise ValueError("%s: 输入必须是非空的二维列表" % who)
    width = len(x[0])
    for row in x:
        if not isinstance(row, (list, tuple)) or len(row) != width:
            raise ValueError("%s: 各样本维度不一致" % who)
        for v in row:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("%s: 特征值必须是数字" % who)
    return width


def _w11e_median(values):
    s = sorted(values)
    n = len(s)
    mid = n // 2
    if n % 2 == 1:
        return float(s[mid])
    return (s[mid - 1] + s[mid]) / 2.0


def _w11e_quantile(sorted_vals, q):
    """线性插值分位数（q ∈ [0, 1]），与 numpy 的 linear 一致。"""
    n = len(sorted_vals)
    if n == 1:
        return float(sorted_vals[0])
    pos = q * (n - 1)
    lo = int(math.floor(pos))
    hi = min(lo + 1, n - 1)
    frac = pos - lo
    return float(sorted_vals[lo]) * (1.0 - frac) + float(sorted_vals[hi]) * frac


class RobustScaler:
    """中位数中心化 + 四分位距缩放：对离群点不敏感。

    center_ = 中位数；scale_ = q_hi - q_lo（为 0 时按 1 处理，不做缩放）。
    """

    def __init__(self, with_centering=True, with_scaling=True,
                 quantile_range=(25.0, 75.0)):
        if not isinstance(with_centering, bool) or not isinstance(with_scaling, bool):
            raise TypeError("RobustScaler: with_centering / with_scaling 必须是 bool")
        lo, hi = quantile_range
        for v in (lo, hi):
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("RobustScaler: quantile_range 的元素必须是数字")
        if not (0.0 <= lo < hi <= 100.0):
            raise ValueError("RobustScaler: quantile_range 需要 0 <= lo < hi <= 100")
        self.with_centering = with_centering
        self.with_scaling = with_scaling
        self.quantile_range = (float(lo), float(hi))
        self.center_ = None
        self.scale_ = None

    def fit(self, x):
        width = _w11e_matrix(x, "RobustScaler")
        lo_q, hi_q = self.quantile_range
        self.center_ = []
        self.scale_ = []
        for j in range(width):
            col = sorted(row[j] for row in x)
            self.center_.append(_w11e_median(col) if self.with_centering else 0.0)
            span = _w11e_quantile(col, hi_q / 100.0) - _w11e_quantile(col, lo_q / 100.0)
            self.scale_.append(span if (self.with_scaling and span > 0.0) else 1.0)
        return self

    def transform(self, x):
        if self.center_ is None:
            raise ValueError("RobustScaler: 请先 fit")
        _w11e_matrix(x, "RobustScaler")
        return [[(row[j] - self.center_[j]) / self.scale_[j]
                 for j in range(len(self.center_))] for row in x]

    def fit_transform(self, x):
        return self.fit(x).transform(x)

    def inverse_transform(self, x):
        if self.center_ is None:
            raise ValueError("RobustScaler: 请先 fit")
        _w11e_matrix(x, "RobustScaler")
        return [[row[j] * self.scale_[j] + self.center_[j]
                 for j in range(len(self.center_))] for row in x]


class MaxAbsScaler:
    """除以每列绝对值最大值（0 时按 1 处理）；不改变稀疏结构，也不做中心化。"""

    def __init__(self):
        self.scale_ = None

    def fit(self, x):
        width = _w11e_matrix(x, "MaxAbsScaler")
        self.scale_ = []
        for j in range(width):
            m = max(abs(row[j]) for row in x)
            self.scale_.append(m if m > 0.0 else 1.0)
        return self

    def transform(self, x):
        if self.scale_ is None:
            raise ValueError("MaxAbsScaler: 请先 fit")
        _w11e_matrix(x, "MaxAbsScaler")
        return [[row[j] / self.scale_[j] for j in range(len(self.scale_))]
                for row in x]

    def fit_transform(self, x):
        return self.fit(x).transform(x)

    def inverse_transform(self, x):
        if self.scale_ is None:
            raise ValueError("MaxAbsScaler: 请先 fit")
        _w11e_matrix(x, "MaxAbsScaler")
        return [[row[j] * self.scale_[j] for j in range(len(self.scale_))]
                for row in x]


def _w11e_norm_ppf(p):
    """标准正态分位函数（stdlib 的 NormalDist 实现）。"""
    import statistics
    return statistics.NormalDist().inv_cdf(p)


class QuantileTransformer:
    """把每列映射到 [0, 1] 上均匀分布（或再映射成正态分布）。

    用 `n_quantiles` 个参考分位数（超过样本数时夹到样本数）做分段线性插值；
    `output_distribution='normal'` 时再套一次正态分位函数。
    """

    def __init__(self, n_quantiles=100, output_distribution="uniform",
                 subsample=None, seed=42):
        if isinstance(n_quantiles, bool) or not isinstance(n_quantiles, int):
            raise TypeError("QuantileTransformer: n_quantiles 必须是整数")
        if n_quantiles < 2:
            raise ValueError("QuantileTransformer: n_quantiles 必须 >= 2")
        if output_distribution not in ("uniform", "normal"):
            raise ValueError(
                "QuantileTransformer: output_distribution 必须是 'uniform' 或 'normal'")
        if subsample is not None:
            if isinstance(subsample, bool) or not isinstance(subsample, int):
                raise TypeError("QuantileTransformer: subsample 必须是整数或 None")
            if subsample < 2:
                raise ValueError("QuantileTransformer: subsample 必须 >= 2")
        if isinstance(seed, bool) or not isinstance(seed, int):
            raise TypeError("QuantileTransformer: seed 必须是整数")
        self.n_quantiles = n_quantiles
        self.output_distribution = output_distribution
        self.subsample = subsample
        self.seed = seed
        self.quantiles_ = None

    def fit(self, x):
        width = _w11e_matrix(x, "QuantileTransformer")
        rng = random.Random(self.seed)
        self.quantiles_ = []
        for j in range(width):
            col = sorted(row[j] for row in x)
            if self.subsample is not None and self.subsample < len(col):
                col = sorted(rng.sample(col, self.subsample))
            n_q = min(self.n_quantiles, len(col))
            if n_q < 2:
                raise ValueError(
                    "QuantileTransformer: 特征 %d 的有效样本数不足 2" % j)
            qs = [k / (n_q - 1.0) for k in range(n_q)]
            self.quantiles_.append([_w11e_quantile(col, q) for q in qs])
        return self

    def _to_uniform(self, v, ref):
        if v <= ref[0]:
            return 0.0
        if v >= ref[-1]:
            return 1.0
        lo, hi = 0, len(ref) - 1
        while hi - lo > 1:
            mid = (lo + hi) // 2
            if ref[mid] <= v:
                lo = mid
            else:
                hi = mid
        span = ref[hi] - ref[lo]
        frac = 0.0 if span <= 0.0 else (v - ref[lo]) / span
        step = 1.0 / (len(ref) - 1.0)
        return min(1.0, max(0.0, (lo + frac) * step))

    def transform(self, x):
        if self.quantiles_ is None:
            raise ValueError("QuantileTransformer: 请先 fit")
        _w11e_matrix(x, "QuantileTransformer")
        out = []
        for row in x:
            new_row = []
            for j, ref in enumerate(self.quantiles_):
                u = self._to_uniform(row[j], ref)
                if self.output_distribution == "normal":
                    u = min(1.0 - 1e-9, max(1e-9, u))
                    new_row.append(_w11e_norm_ppf(u))
                else:
                    new_row.append(u)
            out.append(new_row)
        return out

    def fit_transform(self, x):
        return self.fit(x).transform(x)

    def inverse_transform(self, x):
        if self.quantiles_ is None:
            raise ValueError("QuantileTransformer: 请先 fit")
        _w11e_matrix(x, "QuantileTransformer")
        out = []
        for row in x:
            new_row = []
            for j, ref in enumerate(self.quantiles_):
                u = row[j]
                if self.output_distribution == "normal":
                    u = 0.5 * (1.0 + math.erf(u / math.sqrt(2.0)))
                u = min(1.0, max(0.0, u))
                pos = u * (len(ref) - 1)
                lo = int(math.floor(pos))
                hi = min(lo + 1, len(ref) - 1)
                frac = pos - lo
                new_row.append(ref[lo] * (1.0 - frac) + ref[hi] * frac)
            out.append(new_row)
        return out


def _w11e_yj_forward(v, lam):
    if v >= 0.0:
        if abs(lam) < 1e-12:
            return math.log1p(v)
        return ((v + 1.0) ** lam - 1.0) / lam
    if abs(lam - 2.0) < 1e-12:
        return -math.log1p(-v)
    return -((1.0 - v) ** (2.0 - lam) - 1.0) / (2.0 - lam)


def _w11e_yj_inverse(z, lam):
    if z >= 0.0:
        if abs(lam) < 1e-12:
            return math.exp(z) - 1.0
        base = lam * z + 1.0
        if base <= 0.0:
            return -1.0
        return base ** (1.0 / lam) - 1.0
    if abs(lam - 2.0) < 1e-12:
        return 1.0 - math.exp(-z)
    base = -z * (2.0 - lam) + 1.0
    if base <= 0.0:
        return 1.0
    return 1.0 - base ** (1.0 / (2.0 - lam))


def _w11e_bc_forward(v, lam):
    if abs(lam) < 1e-12:
        return math.log(v)
    return (v ** lam - 1.0) / lam


def _w11e_bc_inverse(z, lam):
    if abs(lam) < 1e-12:
        return math.exp(z)
    base = lam * z + 1.0
    if base <= 0.0:
        raise ValueError("PowerTransformer: 反变换超出定义域（lambda*z + 1 <= 0）")
    return base ** (1.0 / lam)


class PowerTransformer:
    """Box-Cox / Yeo-Johnson 幂变换，每个特征单独估一个 lambda（MLE）。

    `method='yeo-js'`（默认，支持负数）或 `'box-cox'`（要求该特征全为正）。
    `standardize=True` 时变换后再做一次零均值单位方差。
    lambda 用**黄金分割搜索**在 [-5, 5] 上最大化对数似然；结果是近似 MLE，不是网格最优。
    """

    def __init__(self, method="yeo-js", standardize=True):
        if method not in ("yeo-js", "box-cox"):
            raise ValueError("PowerTransformer: method 必须是 'yeo-js' 或 'box-cox'")
        if not isinstance(standardize, bool):
            raise TypeError("PowerTransformer: standardize 必须是 bool")
        self.method = method
        self.standardize = standardize
        self.lambdas_ = None
        self.mean_ = None
        self.std_ = None

    def _forward_one(self, v, lam):
        if self.method == "box-cox":
            return _w11e_bc_forward(v, lam)
        return _w11e_yj_forward(v, lam)

    def _inverse_one(self, z, lam):
        if self.method == "box-cox":
            return _w11e_bc_inverse(z, lam)
        return _w11e_yj_inverse(z, lam)

    def _nll(self, col, lam):
        z = [self._forward_one(v, lam) for v in col]
        n = len(z)
        mean = sum(z) / n
        var = sum((v - mean) ** 2 for v in z) / n
        if var <= 0.0:
            return float("inf")
        jac = 0.0
        for v in col:
            if self.method == "box-cox":
                jac += math.log(v)
            else:
                jac += math.log1p(abs(v)) * (1.0 if v >= 0.0 else -1.0)
        return 0.5 * n * math.log(var) - (lam - 1.0) * jac

    def fit(self, x):
        width = _w11e_matrix(x, "PowerTransformer")
        self.lambdas_ = []
        cols = []
        for j in range(width):
            col = [float(row[j]) for row in x]
            if self.method == "box-cox" and min(col) <= 0.0:
                raise ValueError(
                    "PowerTransformer: box-cox 要求第 %d 个特征全为正（最小值 %.6g）"
                    % (j, min(col)))
            cols.append(col)
            lo, hi = -5.0, 5.0
            inv_phi = (math.sqrt(5.0) - 1.0) / 2.0
            a, b = hi - inv_phi * (hi - lo), lo + inv_phi * (hi - lo)
            fa, fb = self._nll(col, a), self._nll(col, b)
            for _ in range(80):
                if fa < fb:
                    hi, b, fb = b, a, fa
                    a = hi - inv_phi * (hi - lo)
                    fa = self._nll(col, a)
                else:
                    lo, a, fa = a, b, fb
                    b = lo + inv_phi * (hi - lo)
                    fb = self._nll(col, b)
                if hi - lo < 1e-6:
                    break
            self.lambdas_.append((lo + hi) / 2.0)
        z = []
        for j in range(width):
            lam = self.lambdas_[j]
            z.append([self._forward_one(v, lam) for v in cols[j]])
        if self.standardize:
            self.mean_ = [sum(r) / len(r) for r in z]
            self.std_ = []
            for r in z:
                m = self.mean_[len(self.std_)]
                s = math.sqrt(sum((v - m) ** 2 for v in r) / len(r))
                self.std_.append(s if s > 0.0 else 1.0)
        else:
            self.mean_ = [0.0] * width
            self.std_ = [1.0] * width
        return self

    def transform(self, x):
        if self.lambdas_ is None:
            raise ValueError("PowerTransformer: 请先 fit")
        _w11e_matrix(x, "PowerTransformer")
        out = []
        for row in x:
            new_row = []
            for j in range(len(self.lambdas_)):
                z = self._forward_one(float(row[j]), self.lambdas_[j])
                new_row.append((z - self.mean_[j]) / self.std_[j])
            out.append(new_row)
        return out

    def fit_transform(self, x):
        return self.fit(x).transform(x)

    def inverse_transform(self, x):
        if self.lambdas_ is None:
            raise ValueError("PowerTransformer: 请先 fit")
        _w11e_matrix(x, "PowerTransformer")
        out = []
        for row in x:
            new_row = []
            for j in range(len(self.lambdas_)):
                z = row[j] * self.std_[j] + self.mean_[j]
                new_row.append(self._inverse_one(z, self.lambdas_[j]))
            out.append(new_row)
        return out


def ascii_plot(history, keys=("train_loss", "val_loss"), width: int = 60,
               height: int = 12, title: str = None):
    """把 train_history 画成纯 ASCII 折线图（终端里直接看训练曲线）。

    history: Model.fit 填的 {'train_loss': [(epoch, loss)...], ...}
    keys:    要画的曲线名
    """
    if not isinstance(history, dict):
        raise ValueError("ascii_plot: history 必须是 dict")
    width = max(10, int(width))
    height = max(3, int(height))
    series = []
    for k in keys:
        pts = history.get(k)
        if not pts:
            continue
        clean = [(float(e), float(v)) for e, v in pts if v is not None]
        if clean:
            series.append((k, clean))
    if not series:
        return "(ascii_plot: 没有可画的数据)"
    all_vals = [v for _, pts in series for _, v in pts]
    lo, hi = min(all_vals), max(all_vals)
    if hi <= lo:
        hi = lo + 1.0
    all_epochs = [e for _, pts in series for e, _ in pts]
    e_lo, e_hi = min(all_epochs), max(all_epochs)
    span_e = (e_hi - e_lo) or 1.0
    marks = [".", "o", "*", "+", "x"]
    canvas = [[" "] * width for _ in range(height)]
    for si, (name, pts) in enumerate(series):
        ch = marks[si % len(marks)]
        for e, v in pts:
            cx = int((e - e_lo) / span_e * (width - 1))
            cy = height - 1 - int((v - lo) / (hi - lo) * (height - 1))
            canvas[cy][cx] = ch
    lines = []
    if title:
        lines.append(str(title))
    for r in range(height):
        v = hi - (hi - lo) * r / (height - 1)
        lines.append(f"{v:10.4f} |" + "".join(canvas[r]))
    lines.append(" " * 10 + " +" + "-" * width)
    lines.append(" " * 10 + f"  epoch {e_lo:g} .. {e_hi:g}")
    legend = "  ".join(f"{marks[i % len(marks)]}={name}"
                       for i, (name, _) in enumerate(series))
    lines.append("  " + legend)
    return "\n".join(lines)


def _jacobi_eigen_symmetric(matrix, sweeps=100, tol=1e-12):
    """对称矩阵的 Jacobi 特征分解，返回 (特征值, 特征向量矩阵列形式)。"""
    n = len(matrix)
    a = [row[:] for row in matrix]
    v = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    for _ in range(sweeps):
        off = 0.0
        for p in range(n):
            for q in range(p + 1, n):
                off += abs(a[p][q])
        if off <= tol:
            break
        for p in range(n):
            for q in range(p + 1, n):
                if abs(a[p][q]) <= tol:
                    continue
                theta = (a[q][q] - a[p][p]) / (2.0 * a[p][q])
                t = (1.0 if theta >= 0.0 else -1.0) / (
                    abs(theta) + math.sqrt(theta * theta + 1.0))
                c = 1.0 / math.sqrt(t * t + 1.0)
                sn = t * c
                for k in range(n):
                    akp, akq = a[k][p], a[k][q]
                    a[k][p] = c * akp - sn * akq
                    a[k][q] = sn * akp + c * akq
                for k in range(n):
                    apk, aqk = a[p][k], a[q][k]
                    a[p][k] = c * apk - sn * aqk
                    a[q][k] = sn * apk + c * aqk
                for k in range(n):
                    vkp, vkq = v[k][p], v[k][q]
                    v[k][p] = c * vkp - sn * vkq
                    v[k][q] = sn * vkp + c * vkq
    return [a[i][i] for i in range(n)], v


def _mat_check(matrix, who):
    if not isinstance(matrix, (list, tuple)) or not matrix:
        raise ValueError(f"{who}: matrix 必须是非空二维列表")
    rows = []
    width = None
    for i, row in enumerate(matrix):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"{who}: 第 {i} 行必须是非空列表")
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError(f"{who}: 矩阵各行长度必须一致")
        vals = []
        for j, x in enumerate(row):
            if isinstance(x, bool) or not isinstance(x, (int, float)):
                raise ValueError(f"{who}: 元素 [{i}][{j}] 必须是数字")
            fx = float(x)
            if fx != fx or fx in (float("inf"), float("-inf")):
                raise ValueError(f"{who}: 元素 [{i}][{j}] 必须是有限数")
            vals.append(fx)
        rows.append(vals)
    return rows


def svd_low_rank(matrix, rank=None, sweeps=100):
    """对称特征分解实现的截断 SVD：返回 {"U","S","V","rank"}。

    U 是 m×r 行列表，S 是长度 r 的降序奇异值，V 是 r×n（每行一个右奇异向量），
    因而近似 A ≈ U · diag(S) · V。rank 缺省 min(m,n)。
    """
    who = "svd_low_rank"
    a = _mat_check(matrix, who)
    m, n = len(a), len(a[0])
    if isinstance(rank, bool) or (rank is not None and not isinstance(rank, int)):
        raise ValueError(f"{who}: rank 必须是 int 或 None")
    max_rank = min(m, n)
    r = max_rank if rank is None else rank
    if r < 1 or r > max_rank:
        raise ValueError(f"{who}: rank 必须在 [1, {max_rank}]，收到 {r}")
    if isinstance(sweeps, bool) or not isinstance(sweeps, int) or sweeps < 1:
        raise ValueError(f"{who}: sweeps 必须是 >= 1 的 int")
    ata = [[0.0] * n for _ in range(n)]
    for p in range(n):
        for q in range(p, n):
            total = 0.0
            for i in range(m):
                total += a[i][p] * a[i][q]
            ata[p][q] = total
            ata[q][p] = total
    vals, vecs = _jacobi_eigen_symmetric(ata, sweeps=sweeps)
    order = sorted(range(n), key=lambda i: -vals[i])
    order = order[:r]
    sigmas = [math.sqrt(max(vals[i], 0.0)) for i in order]
    v_rows = [[vecs[k][i] for k in range(n)] for i in order]
    u_cols = []
    for t, i in enumerate(order):
        s = sigmas[t]
        col = [0.0] * m
        if s > 1e-12:
            v = v_rows[t]
            for row in range(m):
                col[row] = sum(a[row][k] * v[k] for k in range(n)) / s
        u_cols.append(col)
    u_rows = [[u_cols[t][i] for t in range(r)] for i in range(m)]
    return {"U": u_rows, "S": sigmas, "V": v_rows, "rank": r}


def low_rank_approximation(matrix, rank=None, sweeps=100):
    """用截断 SVD 重建矩阵：A_r = U · diag(S) · V（rank 默认 min(m,n)）。"""
    res = svd_low_rank(matrix, rank=rank, sweeps=sweeps)
    u, s, v = res["U"], res["S"], res["V"]
    m, n = len(u), len(v[0])
    out = [[0.0] * n for _ in range(m)]
    for t in range(len(s)):
        st = s[t]
        vt = v[t]
        for i in range(m):
            uit = u[i][t] * st
            row = out[i]
            for j in range(n):
                row[j] += uit * vt[j]
    return out


# ============================================================================
#  Text Processing（分词与文本工具）
# ============================================================================

def _bpe_pretokenize(text):
    """把文本切成词块：字母数字连续段 / 空白连续段 / 其它符号连续段

    只在词块内部学习合并，避免跨单词边界生成 「the  cat」这类没用的 token
    （GPT-2 的做法，规则简化到纯标准库能表达的程度）。
    """
    out, cur, kind = [], [], None
    for ch in text:
        if ch.isalnum():
            k = "w"
        elif ch.isspace():
            k = "s"
        else:
            k = "p"
        if k != kind:
            if cur:
                out.append("".join(cur))
            cur, kind = [ch], k
        else:
            cur.append(ch)
    if cur:
        out.append("".join(cur))
    return out


def _bpe_apply_merge(tokens, pair, new_id):
    """把 tokens 里所有不重叠的 pair 换成 new_id（从左往右）"""
    out = []
    i = 0
    n = len(tokens)
    while i < n:
        if i + 1 < n and tokens[i] == pair[0] and tokens[i + 1] == pair[1]:
            out.append(new_id)
            i += 2
        else:
            out.append(tokens[i])
            i += 1
    return out


class BytePairTokenizer:
    """字节级 BPE 分词器：任意文本都能无损往返，词表从 256 个字节值开始长

    为什么用**字节**而不是字符：任何 UTF-8 文本（中文、emoji、二进制脏数据）
    都能被 256 个基础 id 覆盖，不会出现「词表外字符」。合并规则在词块内部学习，
    所以 `encode` / `decode` 都可复现、可存档。

    用法::

        tok = BytePairTokenizer().train(text, vocab_size=512)
        ids = tok.encode("hello 世界")
        assert tok.decode(ids) == "hello 世界"
        tok.save("bpe.json")
    """

    def __init__(self, merges=None):
        if merges is not None and not isinstance(merges, (list, tuple)):
            raise ValueError(
                f"BytePairTokenizer: merges 必须是列表，收到 {type(merges).__name__}")
        try:
            self.merges = [tuple(int(x) for x in m) for m in (merges or [])]
        except (TypeError, ValueError) as e:
            raise ValueError(f"BytePairTokenizer: 合并规则必须是 (a, b) 整数对（{e}）")
        for k, m in enumerate(self.merges):
            limit = 256 + k          # 只能引用「之前已经定义」的 id
            if len(m) != 2 or not all(0 <= v < limit for v in m):
                raise ValueError(
                    f"BytePairTokenizer: 第 {k} 条合并规则 {m!r} 非法"
                    f"（只能引用已定义的 id，范围 [0,{limit})）")
        self._rebuild()

    def _rebuild(self):
        """按 merges 重建 id → 字节串 / 合并优先级表"""
        self.id_to_bytes = {i: bytes([i]) for i in range(256)}
        self.merge_rank = {}
        for k, (a, b) in enumerate(self.merges):
            self.id_to_bytes[256 + k] = self.id_to_bytes[a] + self.id_to_bytes[b]
            self.merge_rank[(a, b)] = k
        self.vocab_size = 256 + len(self.merges)

    # ------------------------------------------------------------------ 训练
    def train(self, text, vocab_size: int = 512, min_frequency: int = 2,
              verbose: bool = False):
        """在 text 上学习合并规则，直到词表达 vocab_size（或没有可合并的片段）

        min_frequency: 出现次数少于它的片段不再合并，避免为一次性片段浪费词表。
        同样的输入永远得到同样的 merges（按「出现次数降序、id 升序」挑下一个）。
        """
        if not isinstance(text, str):
            raise ValueError(f"BytePairTokenizer.train: text 必须是字符串，收到 {type(text).__name__}")
        if isinstance(vocab_size, bool) or not isinstance(vocab_size, int) or vocab_size < 256:
            raise ValueError(
                f"BytePairTokenizer.train: vocab_size 必须 >= 256（字节基数），收到 {vocab_size!r}")
        if isinstance(min_frequency, bool) or not isinstance(min_frequency, int) or min_frequency < 1:
            raise ValueError(
                f"BytePairTokenizer.train: min_frequency 必须是 >= 1 的整数，收到 {min_frequency!r}")
        words = [list(w.encode("utf-8")) for w in _bpe_pretokenize(text)]
        self.merges = []
        self._rebuild()
        target = vocab_size - 256
        for step in range(target):
            counts = {}
            for w in words:
                for i in range(len(w) - 1):
                    pair = (w[i], w[i + 1])
                    counts[pair] = counts.get(pair, 0) + 1
            if not counts:
                break
            pair, cnt = max(counts.items(), key=lambda kv: (kv[1], -kv[0][0], -kv[0][1]))
            if cnt < min_frequency:
                break
            self.merges.append(pair)
            self._rebuild()
            new_id = 255 + len(self.merges)
            words = [_bpe_apply_merge(w, pair, new_id) for w in words]
            if verbose:
                piece = self.id_to_bytes[new_id].decode("utf-8", "replace")
                print(f"merge {step + 1}/{target}: {pair} -> {new_id} ({piece!r}) x{cnt}")
        return self

    # ------------------------------------------------------------------ 编解码
    def encode(self, text: str) -> list:
        """文本 → id 列表（按学习到的优先级从高到低贪心合并）"""
        if not isinstance(text, str):
            raise ValueError(f"BytePairTokenizer.encode: text 必须是字符串，收到 {type(text).__name__}")
        ids = []
        for word in _bpe_pretokenize(text):
            toks = list(word.encode("utf-8"))
            while True:
                best_rank, best_i = None, -1
                for i in range(len(toks) - 1):
                    r = self.merge_rank.get((toks[i], toks[i + 1]))
                    if r is not None and (best_rank is None or r < best_rank):
                        best_rank, best_i = r, i
                if best_rank is None:
                    break
                toks = (toks[:best_i] + [256 + best_rank] + toks[best_i + 2:])
            ids.extend(toks)
        return ids

    def decode(self, ids) -> str:
        """id 列表 → 文本；拼出来的字节不是合法 UTF-8 时报错（而不是静默替换）"""
        chunks = []
        for i in ids:
            if isinstance(i, bool) or not isinstance(i, int) or i not in self.id_to_bytes:
                raise ValueError(
                    f"BytePairTokenizer.decode: 非法 id {i!r}（词表 {self.vocab_size}）")
            chunks.append(self.id_to_bytes[i])
        try:
            return b"".join(chunks).decode("utf-8")
        except UnicodeDecodeError:
            raise ValueError(
                "BytePairTokenizer.decode: 这些 id 拼起来不是合法 UTF-8"
                "（可能被截断，或来自另一个分词器）")

    def encode_corpus(self, text: str, seq_len: int = None) -> list:
        """把整段文本编码成 CausalLM.fit 可直接用的序列

        seq_len=None 时返回一条长序列；给定时切成不重叠的块（最后一块可能更短，
        长度 < 2 的块会被丢掉，因为语言模型至少要 2 个 token 才有预测目标）。
        """
        ids = self.encode(text)
        if seq_len is None:
            return [ids]
        if isinstance(seq_len, bool) or not isinstance(seq_len, int) or seq_len < 2:
            raise ValueError(
                f"BytePairTokenizer.encode_corpus: seq_len 必须 >= 2，收到 {seq_len!r}")
        return [ids[i:i + seq_len] for i in range(0, len(ids), seq_len)
                if len(ids[i:i + seq_len]) >= 2]

    # ------------------------------------------------------------------ 存档
    def save(self, filepath: str, quiet: bool = False):
        """把合并规则写成 JSON（纯标准库）"""
        if not isinstance(filepath, str) or not filepath:
            raise ValueError(f"BytePairTokenizer.save: filepath 必须是非空字符串，收到 {filepath!r}")
        data = {"format": "ai_bpe_v1", "merges": [list(m) for m in self.merges]}
        with io.open(filepath, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False)
        if not quiet:
            print(f"已保存分词器: {filepath}（词表 {self.vocab_size}）")
        return filepath

    @staticmethod
    def load(filepath: str):
        """从 `save` 写出的 JSON 恢复分词器"""
        with io.open(filepath, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict) or data.get("format") != "ai_bpe_v1":
            raise ValueError(f"BytePairTokenizer.load: {filepath} 不是 ai_bpe_v1 存档")
        merges = data.get("merges")
        if not isinstance(merges, list):
            raise ValueError("BytePairTokenizer.load: 存档缺少 merges 数组")
        return BytePairTokenizer(merges)

    def __len__(self):
        return self.vocab_size

    def __repr__(self):
        return f"BytePairTokenizer(vocab_size={self.vocab_size})"


#  ======================================================================
#  特殊 token 统一管理 + 批处理（pad / truncate / mask / 批量分词）
#  ======================================================================

class SpecialTokens:
    """BOS / EOS / PAD / UNK / SEP / CLS / MASK 的**统一管理**。

    只保存 token 字符串，不绑定词表；需要 id 时用 `id_of(name, vocab)` 现场查。
    默认值与 `WordPieceTokenizer` 的 `[PAD]`/`[UNK]`/`[CLS]`/`[SEP]`/`[MASK]` 兼容，
    额外的 `[BOS]`/`[EOS]` 供生成任务使用。
    """

    _NAMES = ("pad", "unk", "bos", "eos", "sep", "cls", "mask")
    _DEFAULTS = {
        "pad": "[PAD]", "unk": "[UNK]", "bos": "[BOS]", "eos": "[EOS]",
        "sep": "[SEP]", "cls": "[CLS]", "mask": "[MASK]",
    }

    def __init__(self, **kwargs):
        unknown = [k for k in kwargs if k not in self._NAMES]
        if unknown:
            raise TypeError("SpecialTokens: 未知字段 %r" % (unknown,))
        vals = []
        for name in self._NAMES:
            v = kwargs.get(name, self._DEFAULTS[name])
            if not isinstance(v, str):
                raise TypeError("SpecialTokens: %s 必须是字符串" % name)
            if not v or v.strip() != v:
                raise ValueError("SpecialTokens: %s 不能为空或带首尾空白" % name)
            vals.append(v)
        if len(set(vals)) != len(vals):
            raise ValueError("SpecialTokens: 七个特殊 token 不能重复")
        for name, v in zip(self._NAMES, vals):
            setattr(self, name, v)

    @classmethod
    def defaults(cls):
        return cls()

    @classmethod
    def from_dict(cls, mapping):
        if not isinstance(mapping, dict):
            raise TypeError("SpecialTokens.from_dict: 需要 dict")
        return cls(**mapping)

    def as_dict(self):
        return {name: getattr(self, name) for name in self._NAMES}

    def tokens(self):
        """按固定顺序返回七个 token（pad, unk, bos, eos, sep, cls, mask）。"""
        return tuple(getattr(self, name) for name in self._NAMES)

    def id_of(self, name, vocab):
        """在 `vocab`（list 或 dict）里查某个特殊 token 的 id。"""
        if name not in self._NAMES:
            raise ValueError("SpecialTokens.id_of: name 必须是 %r 之一" % (self._NAMES,))
        tok = getattr(self, name)
        if isinstance(vocab, dict):
            if tok not in vocab:
                raise KeyError("SpecialTokens.id_of: 词表里没有 %r" % (tok,))
            return vocab[tok]
        if isinstance(vocab, (list, tuple)):
            try:
                return list(vocab).index(tok)
            except ValueError:
                raise KeyError("SpecialTokens.id_of: 词表里没有 %r" % (tok,))
        raise TypeError("SpecialTokens.id_of: vocab 必须是 list 或 dict")

    def __repr__(self):
        body = ", ".join("%s=%r" % (name, getattr(self, name)) for name in self._NAMES)
        return "SpecialTokens(%s)" % body


SPECIAL_TOKENS = SpecialTokens.defaults()


def _w12_seqs(sequences, who):
    if not isinstance(sequences, (list, tuple)):
        raise TypeError("%s: sequences 必须是列表" % who)
    if not sequences:
        raise ValueError("%s: sequences 不能为空" % who)
    out = []
    for seq in sequences:
        if not isinstance(seq, (list, tuple)):
            raise TypeError("%s: 每条序列必须是列表" % who)
        row = []
        for v in seq:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("%s: 序列元素必须是 int 或 float" % who)
            row.append(v)
        out.append(row)
    return out


def _w12_side(side, who):
    if side not in ("pre", "post"):
        raise ValueError("%s: side 只能是 'pre' 或 'post'" % who)
    return side


def _w12_truncate(sequence, max_len, side="post"):
    """内部实现：裁剪一条序列（公开 API `truncate` 与 `pad_sequences` 共用）。"""
    if not isinstance(sequence, (list, tuple)):
        raise TypeError("truncate: sequence 必须是列表")
    if isinstance(max_len, bool) or not isinstance(max_len, int):
        raise TypeError("truncate: max_len 必须是整数")
    if max_len < 1:
        raise ValueError("truncate: max_len 必须 >= 1")
    _w12_side(side, "truncate")
    seq = list(sequence)
    if len(seq) <= max_len:
        return seq
    return seq[:max_len] if side == "post" else seq[-max_len:]


def truncate(sequence, max_len, side="post"):
    """把一条序列裁到 `max_len`（`side='post'` 保留前段，`'pre'` 保留后段）。"""
    return _w12_truncate(sequence, max_len, side=side)


def pad_sequences(sequences, max_len=None, pad_value=0, truncate="post",
                  padding="post"):
    """把一批序列补齐到同一长度（默认补到本批最长）。

    `max_len=None` 时取 `max(len(seq))`；给了 `max_len` 就同时裁掉超长部分。
    `pad_value` 只做校验（不是 bool），实际补齐值就是它。
    """
    rows = _w12_seqs(sequences, "pad_sequences")
    _w12_side(truncate, "pad_sequences")
    _w12_side(padding, "pad_sequences")
    if isinstance(pad_value, bool) or not isinstance(pad_value, (int, float)):
        raise TypeError("pad_sequences: pad_value 必须是数字")
    if max_len is None:
        width = max(len(r) for r in rows)
    else:
        if isinstance(max_len, bool) or not isinstance(max_len, int):
            raise TypeError("pad_sequences: max_len 必须是整数或 None")
        if max_len < 1:
            raise ValueError("pad_sequences: max_len 必须 >= 1")
        width = max_len
    out = []
    for row in rows:
        cur = _w12_truncate(row, width, side=truncate)
        need = width - len(cur)
        if need > 0:
            pad = [pad_value] * need
            cur = cur + pad if padding == "post" else pad + cur
        out.append(cur)
    return out


def attention_mask(padded, pad_value=0):
    """按**值相等**生成 0/1 掩码（1 = 有效位置，0 = 补齐位）。

    注意：如果 `pad_value` 也是合法 token 值，这个函数分不出来——那种情况请用
    `batch_sequences(...)`，它按真实长度生成掩码，不存在歧义。
    """
    rows = _w12_seqs(padded, "attention_mask")
    if isinstance(pad_value, bool) or not isinstance(pad_value, (int, float)):
        raise TypeError("attention_mask: pad_value 必须是数字")
    return [[0 if v == pad_value else 1 for v in row] for row in rows]


def batch_sequences(sequences, max_len=None, pad_value=0, truncate="post",
                    padding="post"):
    """一次拿到 `input_ids` / `attention_mask` / `lengths`（掩码按**真实长度**算）。

    `lengths` 是截断后的有效长度（不含补齐位），因此即使 `pad_value` 与真实 token
    取值相同，掩码也不会错。
    """
    rows = _w12_seqs(sequences, "batch_sequences")
    padded = pad_sequences(rows, max_len=max_len, pad_value=pad_value,
                           truncate=truncate, padding=padding)
    lengths = []
    for row in rows:
        n = len(row)
        if max_len is not None and n > max_len:
            n = max_len
        lengths.append(n)
    masks = []
    for n in lengths:
        if padding == "post":
            masks.append([1] * n + [0] * (len(padded[0]) - n))
        else:
            masks.append([0] * (len(padded[0]) - n) + [1] * n)
    return {"input_ids": padded, "attention_mask": masks, "lengths": lengths}


def tokenize_batch(tokenizer, texts, max_len=None, pad_value=0, truncate="post",
                   padding="post"):
    """对一批文本逐条 `tokenizer.encode(...)` 再走 `batch_sequences`。"""
    if not isinstance(texts, (list, tuple)):
        raise TypeError("tokenize_batch: texts 必须是列表")
    if not texts:
        raise ValueError("tokenize_batch: texts 不能为空")
    encode = getattr(tokenizer, "encode", None)
    if not callable(encode):
        raise TypeError("tokenize_batch: tokenizer 必须有 encode 方法")
    encoded = []
    for text in texts:
        if not isinstance(text, str):
            raise TypeError("tokenize_batch: 每条文本必须是字符串")
        ids = encode(text)
        if not isinstance(ids, (list, tuple)):
            raise TypeError("tokenize_batch: encode 必须返回 id 列表")
        encoded.append(list(ids))
    return batch_sequences(encoded, max_len=max_len, pad_value=pad_value,
                           truncate=truncate, padding=padding)


#  ======================================================================
#  分词器族（Whitespace / Word / Regex / SentencePiece 简化版）
#  ======================================================================

def _w12b_text(text, who):
    if not isinstance(text, str):
        raise TypeError("%s: text 必须是字符串" % who)
    return text


def _w12b_texts(texts, who):
    if isinstance(texts, str):
        texts = [texts]
    if not isinstance(texts, (list, tuple)):
        raise TypeError("%s: texts 必须是字符串或字符串列表" % who)
    if not texts:
        raise ValueError("%s: texts 不能为空" % who)
    out = []
    for t in texts:
        if not isinstance(t, str):
            raise TypeError("%s: 每条文本必须是字符串" % who)
        out.append(t)
    return out


def _w12b_ids(ids, who):
    if not isinstance(ids, (list, tuple)):
        raise TypeError("%s: ids 必须是列表" % who)
    out = []
    for v in ids:
        if isinstance(v, bool) or not isinstance(v, int):
            raise TypeError("%s: id 必须是整数" % who)
        if v < 0:
            raise ValueError("%s: id 不能为负" % who)
        out.append(v)
    return out


class _WordLevelTokenizer:
    """词级分词器公共部分：`fit` 建词表、`encode` 查 id、`decode` 拼回文本。

    子类只需实现 `tokenize(text) -> list[str]`。词表顺序固定为
    `[PAD], [UNK], 其余按 (频次降序, 字典序)`，因此 `pad_id == 0`、`unk_id == 1`，
    可以直接喂给 `batch_sequences(..., pad_value=0)`。
    """

    def __init__(self, lower=False, unk_token="[UNK]", pad_token="[PAD]"):
        if not isinstance(lower, bool):
            raise TypeError("tokenizer: lower 必须是 bool")
        for name, tok in (("unk_token", unk_token), ("pad_token", pad_token)):
            if not isinstance(tok, str):
                raise TypeError("tokenizer: %s 必须是字符串" % name)
            if not tok or tok.strip() != tok:
                raise ValueError("tokenizer: %s 不能为空或带首尾空白" % name)
        if unk_token == pad_token:
            raise ValueError("tokenizer: unk_token 与 pad_token 不能相同")
        self.lower = lower
        self.unk_token = unk_token
        self.pad_token = pad_token
        self.vocab = None
        self.token_to_id = {}
        self.id_to_token = []
        self.unk_id = None
        self.pad_id = None

    # ---------------------------------------------------------- 子类实现
    def tokenize(self, text):
        raise NotImplementedError

    # ---------------------------------------------------------- 建词表
    def fit(self, texts, min_frequency=1, max_size=None, vocab=None):
        """建词表。`vocab` 给了就直接用它（不再统计），否则按频次取前 `max_size` 个。"""
        if isinstance(min_frequency, bool) or not isinstance(min_frequency, int):
            raise TypeError("%s.fit: min_frequency 必须是整数" % type(self).__name__)
        if min_frequency < 1:
            raise ValueError("%s.fit: min_frequency 必须 >= 1" % type(self).__name__)
        if max_size is not None:
            if isinstance(max_size, bool) or not isinstance(max_size, int):
                raise TypeError("%s.fit: max_size 必须是整数或 None" % type(self).__name__)
            if max_size < 2:
                raise ValueError("%s.fit: max_size 至少为 2（要为 PAD/UNK 留位置）"
                                 % type(self).__name__)
        if vocab is not None:
            if not isinstance(vocab, (list, tuple)):
                raise TypeError("%s.fit: vocab 必须是列表" % type(self).__name__)
            toks = []
            for t in vocab:
                if not isinstance(t, str):
                    raise TypeError("%s.fit: vocab 元素必须是字符串" % type(self).__name__)
                if t not in (self.pad_token, self.unk_token) and t not in toks:
                    toks.append(t)
            if max_size is not None:
                toks = toks[:max(0, max_size - 2)]
        else:
            rows = _w12b_texts(texts, "%s.fit" % type(self).__name__)
            counts = {}
            for text in rows:
                for tok in self.tokenize(text):
                    counts[tok] = counts.get(tok, 0) + 1
            toks = [t for t, c in counts.items() if c >= min_frequency]
            toks.sort(key=lambda t: (-counts[t], t))
            if max_size is not None:
                toks = toks[:max(0, max_size - 2)]
        self.id_to_token = [self.pad_token, self.unk_token] + toks
        self.token_to_id = {t: i for i, t in enumerate(self.id_to_token)}
        self.vocab = list(self.id_to_token)
        self.pad_id = 0
        self.unk_id = 1
        return self

    def _ready(self, who):
        if self.vocab is None:
            raise ValueError("%s: 先调用 fit(...) 建词表" % who)

    # ---------------------------------------------------------- 编码/解码
    def encode(self, text):
        self._ready("%s.encode" % type(self).__name__)
        toks = self.tokenize(_w12b_text(text, "%s.encode" % type(self).__name__))
        if not isinstance(toks, (list, tuple)):
            raise TypeError("%s.encode: tokenize 必须返回列表" % type(self).__name__)
        return [self.token_to_id.get(t, self.unk_id) for t in toks]

    def decode(self, ids):
        self._ready("%s.decode" % type(self).__name__)
        vals = _w12b_ids(ids, "%s.decode" % type(self).__name__)
        out = []
        for v in vals:
            if v >= len(self.id_to_token):
                raise ValueError("%s.decode: id %d 超出词表大小 %d"
                                 % (type(self).__name__, v, len(self.id_to_token)))
            out.append(self.id_to_token[v])
        return " ".join(out)

    @property
    def vocab_size(self):
        return 0 if self.vocab is None else len(self.vocab)

    def __repr__(self):
        return "%s(vocab_size=%d)" % (type(self).__name__, self.vocab_size)


class WordTokenizer(_WordLevelTokenizer):
    """按「词 + 标点」切分（`\\w+` 与单个标点各算一个 token）。

    `split_punct=False` 时只取 `\\w+`，标点直接丢掉——两种行为都写在
    `tokenize` 的 docstring 里，不做隐式猜测。
    """

    def __init__(self, lower=False, split_punct=True, unk_token="[UNK]",
                 pad_token="[PAD]"):
        _WordLevelTokenizer.__init__(self, lower=lower, unk_token=unk_token,
                                     pad_token=pad_token)
        if not isinstance(split_punct, bool):
            raise TypeError("WordTokenizer: split_punct 必须是 bool")
        self.split_punct = split_punct

    def tokenize(self, text):
        s = _w12b_text(text, "WordTokenizer.tokenize")
        if self.lower:
            s = s.lower()
        pattern = r"\w+|[^\w\s]" if self.split_punct else r"\w+"
        return [m.group(0) for m in re.finditer(pattern, s)]


class WhitespaceTokenizer(_WordLevelTokenizer):
    """只按空白切分（`text.split()`），保留标点原样贴在词上。"""

    def tokenize(self, text):
        s = _w12b_text(text, "WhitespaceTokenizer.tokenize")
        if self.lower:
            s = s.lower()
        return s.split()


class RegexTokenizer(_WordLevelTokenizer):
    """用调用方给的正则切分（`pattern` 必须能匹配到至少一个 token）。"""

    def __init__(self, pattern=r"\w+|[^\w\s]", lower=False, unk_token="[UNK]",
                 pad_token="[PAD]"):
        _WordLevelTokenizer.__init__(self, lower=lower, unk_token=unk_token,
                                     pad_token=pad_token)
        if not isinstance(pattern, str):
            raise TypeError("RegexTokenizer: pattern 必须是字符串")
        if not pattern:
            raise ValueError("RegexTokenizer: pattern 不能为空")
        try:
            self._rx = re.compile(pattern)
        except re.error as exc:
            raise ValueError("RegexTokenizer: 非法正则 %r（%s）" % (pattern, exc))
        if not self._rx.findall("a b 1."):
            raise ValueError("RegexTokenizer: pattern %r 在样例文本上一个 token 都没匹配到"
                             % (pattern,))
        self.pattern = pattern

    def tokenize(self, text):
        s = _w12b_text(text, "RegexTokenizer.tokenize")
        if self.lower:
            s = s.lower()
        return [m.group(0) for m in self._rx.finditer(s)]


class SentencePieceTokenizer:
    """Unigram LM 的**简化版**：子串频次建 unigram 表 + Viterbi 最大似然切分。

    与真正的 SentencePiece 的差别（写进 docstring 免得误用）：
      - 没有 EM 训练、没有概率修剪，词表直接取高频子串；
      - 没有字节回退（BBPE），未登录字符退化成 `unk`；
      - 只用 `▁` 代替空格（不开 `add_dummy_prefix`/`remove_extra_whitespaces` 开关）。

    词表固定为 `[PAD]=0`、`<unk>=1`、其余子串；`max_piece_len` 同时限制训练候选长度和
    Viterbi 的跳步上限。
    """

    def __init__(self, vocab_size=512, max_piece_len=8, unk_token="<unk>",
                 pad_token="[PAD]"):
        for name, v in (("vocab_size", vocab_size), ("max_piece_len", max_piece_len)):
            if isinstance(v, bool) or not isinstance(v, int):
                raise TypeError("SentencePieceTokenizer: %s 必须是整数" % name)
            if v < 2:
                raise ValueError("SentencePieceTokenizer: %s 必须 >= 2" % name)
        for name, tok in (("unk_token", unk_token), ("pad_token", pad_token)):
            if not isinstance(tok, str) or not tok:
                raise ValueError("SentencePieceTokenizer: %s 必须是非空字符串" % name)
        if unk_token == pad_token:
            raise ValueError("SentencePieceTokenizer: unk 与 pad 不能相同")
        self.vocab_size = vocab_size
        self.max_piece_len = max_piece_len
        self.unk_token = unk_token
        self.pad_token = pad_token
        self.pieces_ = None
        self.scores_ = {}
        self.token_to_id = {}
        self.unk_id = 1
        self.pad_id = 0
        self._unk_score = -20.0

    # ---------------------------------------------------------- 归一化
    def _normalize(self, text):
        s = _w12b_text(text, "SentencePieceTokenizer")
        s = " ".join(s.split())
        if not s:
            return ""
        return "\u2581" + s.replace(" ", "\u2581")

    @staticmethod
    def _substrings(norm, max_len):
        n = len(norm)
        for i in range(n):
            for j in range(i + 1, min(n, i + max_len) + 1):
                yield norm[i:j]

    # ---------------------------------------------------------- 训练
    def train(self, texts, vocab_size=None, min_frequency=1, max_piece_len=None):
        rows = _w12b_texts(texts, "SentencePieceTokenizer.train")
        if vocab_size is None:
            vocab_size = self.vocab_size
        if isinstance(vocab_size, bool) or not isinstance(vocab_size, int):
            raise TypeError("SentencePieceTokenizer.train: vocab_size 必须是整数")
        if vocab_size < 4:
            raise ValueError("SentencePieceTokenizer.train: vocab_size 至少为 4")
        if isinstance(min_frequency, bool) or not isinstance(min_frequency, int):
            raise TypeError("SentencePieceTokenizer.train: min_frequency 必须是整数")
        if min_frequency < 1:
            raise ValueError("SentencePieceTokenizer.train: min_frequency 必须 >= 1")
        if max_piece_len is None:
            max_piece_len = self.max_piece_len
        if isinstance(max_piece_len, bool) or not isinstance(max_piece_len, int):
            raise TypeError("SentencePieceTokenizer.train: max_piece_len 必须是整数")
        if max_piece_len < 1:
            raise ValueError("SentencePieceTokenizer.train: max_piece_len 必须 >= 1")
        counts = {}
        total = 0
        chars = set()
        for text in rows:
            norm = self._normalize(text)
            for piece in self._substrings(norm, max_piece_len):
                counts[piece] = counts.get(piece, 0) + 1
                total += 1
            chars.update(norm)
        if not counts:
            raise ValueError("SentencePieceTokenizer.train: 训练文本里没有可用的字符")
        single = [c for c in sorted(chars) if c in counts]
        cand = [p for p in counts if len(p) > 1 and counts[p] >= min_frequency]
        cand.sort(key=lambda p: (-counts[p], -len(p), p))
        room = vocab_size - 2 - len(single)
        if room < 0:
            raise ValueError("SentencePieceTokenizer.train: vocab_size=%d 装不下 %d 个字符，"
                             "至少需要 %d" % (vocab_size, len(single), len(single) + 2))
        pieces = single + cand[:room]
        self.pieces_ = [self.pad_token, self.unk_token] + pieces
        self.token_to_id = {p: i for i, p in enumerate(self.pieces_)}
        denom = float(sum(counts[p] for p in pieces) + 1)
        self.scores_ = {p: math.log((counts[p] + 1) / denom) for p in pieces}
        self.unk_id = 1
        self.pad_id = 0
        self.vocab_size = len(self.pieces_)
        self.max_piece_len = max_piece_len
        return self

    def _ready(self, who):
        if self.pieces_ is None:
            raise ValueError("%s: 先调用 train(...) 训练子词表" % who)

    # ---------------------------------------------------------- 切分
    def tokenize(self, text):
        self._ready("SentencePieceTokenizer.tokenize")
        norm = self._normalize(text)
        if not norm:
            return []
        n = len(norm)
        best = [-1e18] * (n + 1)
        back = [None] * (n + 1)
        best[0] = 0.0
        for i in range(n):
            if best[i] <= -1e17:
                continue
            for j in range(i + 1, min(n, i + self.max_piece_len) + 1):
                piece = norm[i:j]
                score = self.scores_.get(piece)
                if score is None:
                    if j - i != 1:
                        continue
                    score = self._unk_score
                cand = best[i] + score
                if cand > best[j]:
                    best[j] = cand
                    back[j] = (i, piece)
        if best[n] <= -1e17:
            return [self.unk_token]
        out = []
        cur = n
        while cur > 0:
            i, piece = back[cur]
            out.append(piece if piece in self.scores_ else self.unk_token)
            cur = i
        out.reverse()
        return out

    def encode(self, text):
        toks = self.tokenize(text)
        return [self.token_to_id.get(t, self.unk_id) for t in toks]

    def decode(self, ids):
        self._ready("SentencePieceTokenizer.decode")
        vals = _w12b_ids(ids, "SentencePieceTokenizer.decode")
        out = []
        for v in vals:
            if v >= len(self.pieces_):
                raise ValueError("SentencePieceTokenizer.decode: id %d 超出词表大小 %d"
                                 % (v, len(self.pieces_)))
            if v in (self.pad_id, self.unk_id):
                continue
            out.append(self.pieces_[v])
        return "".join(out).replace("\u2581", " ").strip()

    def __repr__(self):
        return "SentencePieceTokenizer(vocab_size=%s)" % (
            0 if self.pieces_ is None else len(self.pieces_))


_WP_SPECIALS = ("[PAD]", "[UNK]", "[CLS]", "[SEP]", "[MASK]")
_WP_CONT = "##"


class WordPieceTokenizer:
    """WordPiece 分词器（BERT 风格）：词表 = 特殊标记 + 字符 + 子词。

    与 `BytePairTokenizer` 的区别：
      - 词表里存**字符串**（可读、可手写、可存档对比），不是字节序列；
      - 词内非首字符一律带 `##` 前缀，所以「词中间的子词」和「词首的子词」
        是两个不同 token —— 这也是 BERT 能把 `playing` 拆成 `play + ##ing`
        却不把 `ing` 当成独立词的原因；
      - 训练按 `频次 / (左频次 × 右频次)` 打分（BERT 原始做法），高频组合优先，
        避免 `the` 这类高频词把词表占满；
      - 编码用「最长前缀匹配」，词表外字符落到 `[UNK]`。

    词表顺序固定：`[PAD] [UNK] [CLS] [SEP] [MASK]` 在最前，`id` 即下标，
    存档/加载后 id 与训练时完全一致。
    """

    def __init__(self, vocab=None):
        if vocab is None:
            vocab = list(_WP_SPECIALS)
        self._install(vocab)

    def _install(self, vocab):
        if not isinstance(vocab, (list, tuple)):
            raise TypeError("WordPieceTokenizer: vocab 必须是 list 或 tuple")
        tokens = [self._check_token(t) for t in vocab]
        if len(set(tokens)) != len(tokens):
            raise ValueError("WordPieceTokenizer: vocab 里有重复 token")
        for name in _WP_SPECIALS:
            if name not in tokens:
                raise ValueError(f"WordPieceTokenizer: vocab 缺少特殊标记 {name}")
        self.tokens = list(tokens)
        self.token_to_id = {t: k for k, t in enumerate(self.tokens)}
        self.unk_id = self.token_to_id["[UNK]"]
        self.pad_id = self.token_to_id["[PAD]"]
        self.cls_id = self.token_to_id["[CLS]"]
        self.sep_id = self.token_to_id["[SEP]"]
        self.mask_id = self.token_to_id["[MASK]"]
        return self

    @staticmethod
    def _check_token(token):
        if not isinstance(token, str):
            raise TypeError(f"WordPieceTokenizer: token 必须是 str，收到 {type(token).__name__}")
        if not token:
            raise ValueError("WordPieceTokenizer: token 不能是空字符串")
        if token.startswith(_WP_CONT) and token == _WP_CONT:
            raise ValueError(f"WordPieceTokenizer: token {token!r} 只有前缀、没有内容")
        return token

    @property
    def vocab_size(self):
        return len(self.tokens)

    def __len__(self):
        return len(self.tokens)

    def __repr__(self):
        return f"WordPieceTokenizer(vocab_size={self.vocab_size})"

    # ---------- 切词 ----------
    @staticmethod
    def _split_words(text):
        """切成词块：字母数字连写 / 空白连写 / 其它符号连写。"""
        words = []
        cur = ""
        kind = None
        for ch in text:
            k = "w" if ch.isalnum() else ("s" if ch.isspace() else "o")
            if k == kind:
                cur += ch
            else:
                if cur:
                    words.append(cur)
                cur = ch
                kind = k
        if cur:
            words.append(cur)
        return words

    @staticmethod
    def _to_pieces(word):
        """词 -> WordPiece 初始切片：首字符原样，其余加 ##。"""
        pieces = []
        for k, ch in enumerate(word):
            pieces.append(ch if k == 0 else _WP_CONT + ch)
        return pieces

    # ---------- 训练 ----------
    def train(self, text, vocab_size=512, min_frequency=2, verbose=False):
        if not isinstance(text, str):
            raise TypeError("WordPieceTokenizer.train: text 必须是 str")
        if isinstance(vocab_size, bool) or not isinstance(vocab_size, int):
            raise TypeError("WordPieceTokenizer.train: vocab_size 必须是 int")
        if vocab_size < len(_WP_SPECIALS) + 1:
            raise ValueError(
                f"WordPieceTokenizer.train: vocab_size 至少 {len(_WP_SPECIALS) + 1}")
        if isinstance(min_frequency, bool) or not isinstance(min_frequency, int):
            raise TypeError("WordPieceTokenizer.train: min_frequency 必须是 int")
        if min_frequency < 1:
            raise ValueError("WordPieceTokenizer.train: min_frequency 必须 >= 1")

        tokens = list(_WP_SPECIALS)
        seen = set(tokens)
        words = []
        for word in self._split_words(text):
            pieces = self._to_pieces(word)
            words.append(pieces)
            for p in pieces:
                if p not in seen:
                    tokens.append(p)
                    seen.add(p)

        while len(tokens) < vocab_size:
            pair_freq = {}
            token_freq = {}
            for pieces in words:
                for t in pieces:
                    token_freq[t] = token_freq.get(t, 0) + 1
                for k in range(len(pieces) - 1):
                    pair = (pieces[k], pieces[k + 1])
                    pair_freq[pair] = pair_freq.get(pair, 0) + 1
            if not pair_freq:
                break
            best = None
            best_score = -1.0
            for (left, right), freq in pair_freq.items():
                if freq < min_frequency:
                    continue
                score = freq / float(token_freq[left] * token_freq[right])
                if score > best_score or (score == best_score and (left, right) < best):
                    best = (left, right)
                    best_score = score
            if best is None:
                break
            left, right = best
            body = right[len(_WP_CONT):] if right.startswith(_WP_CONT) else right
            merged = (left if left.startswith(_WP_CONT) else left) + body
            if merged in seen:
                break
            tokens.append(merged)
            seen.add(merged)
            new_words = []
            for pieces in words:
                out = []
                k = 0
                while k < len(pieces):
                    if k + 1 < len(pieces) and pieces[k] == left and pieces[k + 1] == right:
                        out.append(merged)
                        k += 2
                    else:
                        out.append(pieces[k])
                        k += 1
                new_words.append(out)
            words = new_words
            if verbose:
                print(f"  merge {left!r} + {right!r} -> {merged!r}  (freq={pair_freq[best]})")

        return self._install(tokens)

    # ---------- 编码 ----------
    def _encode_word(self, word, max_chars):
        if len(word) > max_chars:
            return [self.unk_id]
        ids = []
        start = 0
        n = len(word)
        while start < n:
            end = n
            found = None
            while start < end:
                piece = word[start:end]
                if start > 0:
                    piece = _WP_CONT + piece
                if piece in self.token_to_id:
                    found = piece
                    break
                end -= 1
            if found is None:
                return [self.unk_id]
            ids.append(self.token_to_id[found])
            start = end
        return ids

    def encode(self, text, max_chars_per_word=100):
        if not isinstance(text, str):
            raise TypeError("WordPieceTokenizer.encode: text 必须是 str")
        if isinstance(max_chars_per_word, bool) or not isinstance(max_chars_per_word, int):
            raise TypeError("WordPieceTokenizer.encode: max_chars_per_word 必须是 int")
        if max_chars_per_word < 1:
            raise ValueError("WordPieceTokenizer.encode: max_chars_per_word 必须 >= 1")
        ids = []
        for word in self._split_words(text):
            ids.extend(self._encode_word(word, max_chars_per_word))
        return ids

    def encode_pair(self, text_a, text_b):
        """BERT 句式输入：[CLS] a [SEP] b [SEP]。"""
        return ([self.cls_id] + self.encode(text_a) + [self.sep_id]
                + self.encode(text_b) + [self.sep_id])

    def decode(self, ids):
        if not isinstance(ids, (list, tuple)):
            raise TypeError("WordPieceTokenizer.decode: ids 必须是 list 或 tuple")
        out = []
        # 逐 token 拼接：`##xx` 直接接上，空白 token 原样输出，词首 token 视情况补空格
        for i, tid in enumerate(ids):
            if isinstance(tid, bool) or not isinstance(tid, int):
                raise TypeError(f"WordPieceTokenizer.decode: 第 {i} 个 id 不是 int")
            if tid < 0 or tid >= self.vocab_size:
                raise ValueError(
                    f"WordPieceTokenizer.decode: 第 {i} 个 id {tid} 越界 [0, {self.vocab_size})")
            token = self.tokens[tid]
            if token in _WP_SPECIALS:
                continue
            if token.startswith(_WP_CONT):
                out.append(token[len(_WP_CONT):])
                continue
            if token.strip() == "":
                out.append(token)
                continue
            # 词首 token：只有当前不在空白处才补一个空格
            if out and not out[-1].endswith((" ", "\t", "\n")):
                out.append(" ")
            out.append(token)
        return "".join(out)

    # ---------- 存档 ----------
    def save(self, filepath, quiet=False):
        payload = {"format": "ai_wordpiece_v1", "tokens": list(self.tokens)}
        with io.open(filepath, "w", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False, indent=2)
        if not quiet:
            print(f"WordPieceTokenizer 已保存: {filepath}（{self.vocab_size} 个 token）")

    @staticmethod
    def load(filepath):
        with io.open(filepath, "r", encoding="utf-8") as f:
            payload = json.load(f)
        if not isinstance(payload, dict) or payload.get("format") != "ai_wordpiece_v1":
            raise ValueError(f"WordPieceTokenizer.load: {filepath} 不是 wordpiece 存档")
        tokens = payload.get("tokens")
        if not isinstance(tokens, list):
            raise ValueError("WordPieceTokenizer.load: tokens 字段必须是 list")
        return WordPieceTokenizer(tokens)


class TextProcessor:
    """字符级文本处理器：词表构建、one-hot 编码、滑动窗口数据生成"""

    def __init__(self, text: str):
        self.chars = sorted(list(set(text)))
        self.char_to_idx = {ch: i for i, ch in enumerate(self.chars)}
        self.idx_to_char = {i: ch for i, ch in enumerate(self.chars)}
        self.vocab_size = len(self.chars)

    def encode_one_hot(self, char: str, strict: bool = False) -> list:
        """将单个字符编码为 one-hot 向量

        strict=True 时遇到词表外字符会报错，避免静默产出全 0 向量污染训练数据。
        """
        vec = [0.0] * self.vocab_size
        if char in self.char_to_idx:
            vec[self.char_to_idx[char]] = 1.0
        elif strict:
            raise ValueError(f"encode_one_hot: 字符 {char!r} 不在词表中")
        return vec

    def encode_indices(self, text: str, strict: bool = False) -> list:
        """将字符串编码为索引列表（strict=True 时未知字符报错，而非静默映射成 0）

        strict=False（默认）时未知字符会被**静默映射到索引 0**：训练数据里若有
        词表外字符会被当成第 0 个字符来学。训练/评估路径应显式传 strict=True
        （TextProcessor.prepare_index_data 内部就是这么做的）。
        """
        if strict:
            unknown = [c for c in text if c not in self.char_to_idx]
            if unknown:
                raise ValueError(f"encode_indices: 字符 {unknown[:3]!r} 不在词表中")
        return [self.char_to_idx.get(c, 0) for c in text]

    def decode_indices(self, indices: list) -> str:
        """将索引列表解码回字符串"""
        return ''.join(self.idx_to_char.get(i, '?') for i in indices)

    def prepare_data(self, text: str, window_size: int) -> list:
        """滑动窗口生成 (input_vec, target_vec) 数据集"""
        if not isinstance(window_size, int) or window_size < 1:
            raise ValueError(f"prepare_data: window_size 必须 >= 1，收到 {window_size!r}")
        data = []
        for i in range(len(text) - window_size):
            inp_chars = text[i:i + window_size]
            target_char = text[i + window_size]
            # 拼接窗口内所有字符的 one-hot 编码
            inp_vec = []
            for c in inp_chars:
                inp_vec.extend(self.encode_one_hot(c, strict=True))
            target_vec = self.encode_one_hot(target_char, strict=True)
            data.append((inp_vec, target_vec))
        return data

    def prepare_index_data(self, text: str, window_size: int) -> list:
        """滑动窗口生成 (indices_list, target_idx) 数据集（配合 Embedding 使用）

        与 prepare_data 一致：词表外字符直接报错，不再静默映射成索引 0。
        """
        data = []
        for i in range(len(text) - window_size):
            inp = self.encode_indices(text[i:i + window_size], strict=True)
            target_char = text[i + window_size]
            if target_char not in self.char_to_idx:
                raise ValueError(
                    f"prepare_index_data: 目标字符 {target_char!r} 不在词表中"
                )
            data.append((inp, self.char_to_idx[target_char]))
        return data


def _softmax_with_temp(logits: list, temperature: float = 1.0) -> list:
    """带温度参数的 Softmax：T 越小越保守，T 越大越随机"""
    if not isinstance(temperature, (int, float)) or temperature <= 0:
        raise ValueError(f"_softmax_with_temp: temperature 必须 > 0，收到 {temperature!r}")
    if temperature != 1.0:
        logits = [x / temperature for x in logits]
    mx = max(logits)
    exps = [math.exp(x - mx) for x in logits]
    s = sum(exps)
    return [e / s for e in exps]


def sample_index(probs: list) -> int:
    """根据概率分布进行随机采样（不依赖 numpy）"""
    if not probs:
        raise ValueError("sample_index: 概率分布不能为空")
    total = sum(probs)
    if not (total > 0):
        raise ValueError("sample_index: 概率之和必须 > 0")
    if abs(total - 1.0) > 1e-9:
        # 未归一化的输入会让采样区间对不上（例如 [0.2,0.3] 有 50% 概率返回末尾索引）
        probs = [p / total for p in probs]
    r = random.random()
    cumulative = 0.0
    for i, p in enumerate(probs):
        cumulative += p
        if r < cumulative:
            return i
    return len(probs) - 1


def generate_text(network, tp: TextProcessor, start_str: str,
                  length: int = 15, window_size: int = 3, temp: float = 1.0) -> str:
    """自回归文本生成（network 只需提供 forward）

    与 generate_text_with_mlp 是同一实现，保留这个名字只为兼容旧调用。
    """
    if not isinstance(length, int) or length < 0:
        raise ValueError(f"generate_text: length 必须 >= 0，收到 {length!r}")
    return generate_text_with_mlp(network, tp, start_str, length, window_size, temp)


def generate_text_with_mlp(model, tp: TextProcessor, start_str: str,
                           length: int = 15, window_size: int = 3,
                           temp: float = 1.0) -> str:
    """使用 nn_all_in_one MLP 模型进行自回归文本生成

    start_str 里的字符必须都在词表内，否则抛 ValueError（不再静默编码成全 0）。
    上下文不足 window_size 时用**零向量**占位，不引入词表里的假字符。
    """
    generated = start_str
    for _ in range(length):
        context = generated[-window_size:]
        test_vec = []
        pad = window_size - len(context)
        if pad > 0:
            # 用零向量占位：原先用 tp.chars[0] 填充，可能是换行/生僻字，
            # 且空格在中文语料里常不在词表，都会引入不存在的字符
            test_vec.extend([0.0] * (tp.vocab_size * pad))
        for c in context:
            test_vec.extend(tp.encode_one_hot(c, strict=True))
        out = model.forward(test_vec)
        if len(out) != tp.vocab_size:
            raise ValueError(
                f"generate_text_with_mlp: 模型输出维度 {len(out)} 与词表大小 "
                f"{tp.vocab_size} 不一致（采样会越界或永远采样不到部分字符）"
            )
        # 文本模型的输出层常常已经是 softmax 概率（make_classifier 就是），
        # 再套一次 softmax 会把分布压平：temp=1 时 [0.7,0.2,0.1] -> [0.46,0.28,0.25]。
        # 这里按「是否已是合法概率分布」自动区分，概率输出先取 log 还原成 logits。
        is_prob = (all(0.0 <= v <= 1.0 for v in out)
                   and abs(sum(out) - 1.0) < 1e-6)
        logits = [math.log(max(v, 1e-12)) for v in out] if is_prob else out
        probs = _softmax_with_temp(logits, temp)
        next_idx = sample_index(probs)
        generated += tp.idx_to_char[next_idx]
    return generated


# ============================================================================
#  Trainer
# ============================================================================

def train(model: MLP, loss_fn: Callable, optimizer: Adam, data: list,
          epochs: int = 2000, batch_size: int = 2, patience: int = 50,
          val_data: Optional[list] = None, verbose: bool = True,
          shuffle: bool = True, seed=None):
    """
    loss_fn: 接受 (pred, target) -> (loss, grad)
    shuffle: 每轮是否打乱训练数据（默认 True）
    seed:    打乱用的随机种子（None = 全局 random，与旧版一致；传整数则用局部
             Random，同样的调用再跑一次结果完全相同，也不推进全局随机状态）

    注意：与 Model 一样，softmax 输出层不能搭配 mse 损失——_softmax_deriv 返回全 1
    依赖 softmax+cross_entropy 的联合梯度，配 mse 会静默产生错误梯度。
    """
    # S3: 把 Model 里的 softmax/mse 校验下沉到这里，避免绕过 Model 直接训练时训歪
    last = model.layers[-1]
    last_act = getattr(last, "activation_name", None)
    if last_act is None and last.act_fn == last._softmax:
        last_act = "softmax"
    # 与 Model 的守卫保持一致：传函数对象或 functools.partial 包装都要拦住
    _is_mse = (loss_fn is mse_loss) or (getattr(loss_fn, 'func', None) is mse_loss)
    if last_act == "softmax" and _is_mse:
        raise ValueError(
            "输出层使用 softmax 时不能搭配 mse_loss：softmax 的反向用的是 "
            "softmax+cross_entropy 的联合梯度。请改用 cross_entropy_loss，"
            "或把输出层激活改成 'linear'。"
        )
    best_val_loss = float("inf")
    no_improve = 0
    history = {"train_loss": [], "val_loss": []}

    # seed 只影响本轮打乱用的随机流：不传时仍用全局 random（行为与旧版一致），
    # 传了就换成局部 Random，既不推进全局状态、也能完整复现训练过程
    rng = random.Random(seed) if seed is not None else random

    # 复制一份再打乱，避免修改调用者传入的列表顺序
    data = list(data)
    if not data:
        raise ValueError("train: 数据集为空（train_loss /= len(data) 会除零）")
    if batch_size is None or batch_size <= 0:
        # 与 Model.fit 一致：-1 / 0 表示整批（原先 range(0,n,-1) 是空循环，
        # 会静默「训练 0 步、loss 0」）
        batch_size = len(data)

    for epoch in range(1, epochs + 1):
# ============================================================================
#  训练
# ============================================================================
        if shuffle:
            rng.shuffle(data)
        train_loss = 0.0

        for b in range(0, len(data), batch_size):
            batch = data[b:b + batch_size]

            # 与 Model.fit 相同：反向传播时直接累加，不再保存每个样本的完整梯度
            acc_w = [[[0.0] * layer.fan_in for _ in range(layer.fan_out)]
                     for layer in model.layers]
            acc_b = [[0.0] * layer.fan_out for layer in model.layers]

            for x, y in batch:
                pred = model.forward(x)
                loss, grad = loss_fn(pred, y)
                train_loss += loss

                # 反向传播
                delta = grad
                idx = len(model.layers) - 1
                for layer in reversed(model.layers):
                    gw, gb, delta = layer.backward(delta)
                    gw_acc, gb_acc = acc_w[idx], acc_b[idx]
                    for j in range(layer.fan_out):
                        gwj, gwaj = gw[j], gw_acc[j]
                        for k in range(layer.fan_in):
                            gwaj[k] += gwj[k]
                        gb_acc[j] += gb[j]
                    idx -= 1

            # 累加完成后再统一平均
            B = len(batch)
            avg_grads = [
                ([[v / B for v in row] for row in acc_w[i]],
                 [v / B for v in acc_b[i]])
                for i in range(len(model.layers))
            ]

            optimizer.step(avg_grads)

        train_loss /= len(data)
        history["train_loss"].append((epoch, train_loss))

# ============================================================================
#  验证
# ============================================================================
        val_loss = None
        if val_data:
            val_loss = evaluate(model, loss_fn, val_data)
            history["val_loss"].append((epoch, val_loss))

            if patience > 0:
                if val_loss < best_val_loss:
                    best_val_loss = val_loss
                    no_improve = 0
                else:
                    no_improve += 1

                # patience=0 表示**关闭**早停（与 Model.fit 一致）；
                # 原先 0 >= 0 会立刻 break，patience=0 反而变成「只训 1 轮」
                if no_improve >= patience:
                    if verbose:
                        print(f"\nEarly stopping at epoch {epoch}")
                    break

        if verbose and epoch % 100 == 0:
            if val_loss is not None:
                print(f"Epoch {epoch} | Train: {train_loss:.6f} | Val: {val_loss:.6f}")
            else:
                print(f"Epoch {epoch} | Train: {train_loss:.6f}")

    return history


def evaluate(model: MLP, loss_fn: Callable, data: list) -> float:
    """在 `data`（样本对列表）上算平均损失，不训练、不改权重。

    `loss_fn(pred, y)` 返回 `(loss, grad)`，这里只用第一项；空数据集报 ValueError。
    只看损失、要完整指标时用 `Model.evaluate_all` / `evaluate_all`。
    """
    if not data:
        raise ValueError("evaluate: 数据集为空")
    total = 0.0
    for x, y in data:
        pred = model.forward(x)
        loss, _ = loss_fn(pred, y)
        total += loss
    return total / len(data)


# ============================================================================
#  评估指标（分类 / 回归 / 序列 / 生成）
# ============================================================================

def _metric_pairs(y_true, y_pred, who):
    """校验两个等长的标签/预测序列，返回 list 副本。"""
    if not isinstance(y_true, (list, tuple)) or not isinstance(y_pred, (list, tuple)):
        raise ValueError(f"{who}: y_true / y_pred 必须是列表")
    if len(y_true) != len(y_pred):
        raise ValueError(f"{who}: 长度不一致（{len(y_true)} vs {len(y_pred)}）")
    if not y_true:
        raise ValueError(f"{who}: 不能是空列表")
    return list(y_true), list(y_pred)


def _metric_label(v, who, i):
    """类别索引必须是非负整数（bool 不算）。"""
    if isinstance(v, bool) or not isinstance(v, int):
        raise ValueError(f"{who}: 第 {i} 个标签必须是整数类别索引，收到 {v!r}")
    if v < 0:
        raise ValueError(f"{who}: 第 {i} 个标签不能是负数，收到 {v}")
    return v


def _metric_number(v, who, i):
    """数值型指标的值必须是有限实数（bool 不算）。"""
    if isinstance(v, bool) or not isinstance(v, (int, float)):
        raise ValueError(f"{who}: 第 {i} 个值必须是数字，收到 {v!r}")
    v = float(v)
    if v != v or v in (float("inf"), float("-inf")):
        raise ValueError(f"{who}: 第 {i} 个值必须是有限数，收到 {v!r}")
    return v


def confusion_matrix(y_true, y_pred, num_classes: int = None):
    """混淆矩阵：`matrix[t][p]` = 真实类别 t 被预测成 p 的样本数。

    num_classes 省略时取 `max(标签)+1`（不够则自动给出更小的方阵）。
    返回 list[list[int]]，`len(matrix) == num_classes`。
    """
    yt, yp = _metric_pairs(y_true, y_pred, "confusion_matrix")
    labels = []
    for i, (t, p) in enumerate(zip(yt, yp)):
        labels.append(_metric_label(t, "confusion_matrix.y_true", i))
        labels.append(_metric_label(p, "confusion_matrix.y_pred", i))
    n = max(labels) + 1
    if num_classes is not None:
        if isinstance(num_classes, bool) or not isinstance(num_classes, int):
            raise ValueError(f"confusion_matrix: num_classes 必须是整数，收到 {num_classes!r}")
        if num_classes < n:
            raise ValueError(
                f"confusion_matrix: num_classes={num_classes} 小于实际类别数 {n}"
            )
        n = num_classes
    mat = [[0] * n for _ in range(n)]
    for t, p in zip(yt, yp):
        mat[t][p] += 1
    return mat


def accuracy_score(y_true, y_pred) -> float:
    """分类准确率（逐样本比较）。"""
    yt, yp = _metric_pairs(y_true, y_pred, "accuracy_score")
    hit = 0
    for i, (t, p) in enumerate(zip(yt, yp)):
        hit += 1 if _metric_label(t, "accuracy_score.y_true", i) == \
            _metric_label(p, "accuracy_score.y_pred", i) else 0
    return hit / len(yt)


def precision_recall_f1(y_true, y_pred, average: str = "macro",
                        num_classes: int = None) -> dict:
    """精确率 / 召回率 / F1。

    average: 'macro'（各类等权，默认）、'micro'（全局计数）、'weighted'（按支持数加权）
             或 'none'（只返回 per_class）。
    返回 {'precision','recall','f1','per_class':[{'precision','recall','f1','support'},...]}
    """
    if average not in ("macro", "micro", "weighted", "none"):
        raise ValueError(
            f"precision_recall_f1: average 必须是 macro/micro/weighted/none，收到 {average!r}"
        )
    mat = confusion_matrix(y_true, y_pred, num_classes)
    n = len(mat)
    per_class = []
    total_tp = total_fp = total_fn = 0
    for c in range(n):
        tp = mat[c][c]
        support = sum(mat[c])
        predicted = sum(mat[r][c] for r in range(n))
        fp = predicted - tp
        fn = support - tp
        total_tp += tp
        total_fp += fp
        total_fn += fn
        precision = tp / predicted if predicted else 0.0
        recall = tp / support if support else 0.0
        f1 = (2 * precision * recall / (precision + recall)) if (precision + recall) else 0.0
        per_class.append({
            "precision": precision, "recall": recall, "f1": f1, "support": support,
        })

    if average == "micro":
        precision = total_tp / (total_tp + total_fp) if (total_tp + total_fp) else 0.0
        recall = total_tp / (total_tp + total_fn) if (total_tp + total_fn) else 0.0
        f1 = (2 * precision * recall / (precision + recall)) if (precision + recall) else 0.0
    elif average == "weighted":
        total_support = sum(row["support"] for row in per_class)
        if total_support:
            precision = sum(row["precision"] * row["support"] for row in per_class) / total_support
            recall = sum(row["recall"] * row["support"] for row in per_class) / total_support
            f1 = sum(row["f1"] * row["support"] for row in per_class) / total_support
        else:
            precision = recall = f1 = 0.0
    else:
        # macro / none：只在「出现过」的类别上平均（支持数或预测数为 0 的类不计入）
        used = [row for row in per_class if row["support"] or row["f1"]]
        if used:
            precision = sum(row["precision"] for row in used) / len(used)
            recall = sum(row["recall"] for row in used) / len(used)
            f1 = sum(row["f1"] for row in used) / len(used)
        else:
            precision = recall = f1 = 0.0

    return {"precision": precision, "recall": recall, "f1": f1, "per_class": per_class}


def matthews_corrcoef(y_true, y_pred, num_classes: int = None) -> float:
    """多分类 MCC（二分类时即标准 MCC，取值 [-1,1]，0 表示随机）。"""
    mat = confusion_matrix(y_true, y_pred, num_classes)
    n = len(mat)
    total = sum(sum(row) for row in mat)
    if total == 0:
        raise ValueError("matthews_corrcoef: 没有样本")
    correct = sum(mat[c][c] for c in range(n))
    row_sums = [sum(mat[c]) for c in range(n)]
    col_sums = [sum(mat[r][c] for r in range(n)) for c in range(n)]
    cov_ytyp = correct * total - sum(row_sums[c] * col_sums[c] for c in range(n))
    cov_ypyp = total * total - sum(v * v for v in col_sums)
    cov_ytyt = total * total - sum(v * v for v in row_sums)
    denom = math.sqrt(cov_ypyp * cov_ytyt)
    if denom == 0:
        return 0.0
    return cov_ytyp / denom


def top_k_accuracy(y_true, y_score, k: int = 1) -> float:
    """Top-k 准确率：正确类别出现在前 k 个预测里就算对。

    y_score: 每个样本一个得分列表（长度 = 类别数，越大越可能）。
    """
    if isinstance(k, bool) or not isinstance(k, int) or k < 1:
        raise ValueError(f"top_k_accuracy: k 必须是 ≥1 的整数，收到 {k!r}")
    yt, ys = _metric_pairs(y_true, y_score, "top_k_accuracy")
    hit = 0
    for i, (t, row) in enumerate(zip(yt, ys)):
        t = _metric_label(t, "top_k_accuracy.y_true", i)
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"top_k_accuracy: 第 {i} 个得分必须是列表")
        scores = [_metric_number(v, "top_k_accuracy.y_score", i) for v in row]
        if t >= len(scores):
            raise ValueError(
                f"top_k_accuracy: 第 {i} 个样本的真实类别 {t} 超出得分长度 {len(scores)}"
            )
        order = sorted(range(len(scores)), key=lambda c: (-scores[c], c))
        if t in order[:k]:
            hit += 1
    return hit / len(yt)


def roc_auc_score(y_true, y_score) -> float:
    """二分类 ROC-AUC（用秩和/Mann-Whitney U 统计量，并列取平均秩）。"""
    yt, ys = _metric_pairs(y_true, y_score, "roc_auc_score")
    labels = [_metric_label(t, "roc_auc_score.y_true", i) for i, t in enumerate(yt)]
    scores = [_metric_number(s, "roc_auc_score.y_score", i) for i, s in enumerate(ys)]
    if any(t not in (0, 1) for t in labels):
        raise ValueError("roc_auc_score: y_true 只能是 0/1（二分类）")
    n_pos = sum(labels)
    n_neg = len(labels) - n_pos
    if n_pos == 0 or n_neg == 0:
        raise ValueError("roc_auc_score: 需要同时包含正例和负例")

    order = sorted(range(len(scores)), key=lambda i: scores[i])
    ranks = [0.0] * len(scores)
    i = 0
    while i < len(order):
        j = i
        while j + 1 < len(order) and scores[order[j + 1]] == scores[order[i]]:
            j += 1
        # 并列值取平均秩（秩从 1 开始）
        avg = (i + j) / 2.0 + 1.0
        for k in range(i, j + 1):
            ranks[order[k]] = avg
        i = j + 1
    rank_sum = sum(r for r, t in zip(ranks, labels) if t == 1)
    return (rank_sum - n_pos * (n_pos + 1) / 2.0) / (n_pos * n_neg)


def _multilabel_rows(y, who, binary):
    """把多标签矩阵校验成 list[list]（binary=True 时只收 0/1）。"""
    if not isinstance(y, (list, tuple)) or not y:
        raise ValueError(f"{who}: 不能为空")
    width = None
    rows = []
    for i, row in enumerate(y):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"{who}: 第 {i} 行必须是非空列表")
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError(
                f"{who}: 第 {i} 行长度 {len(row)} 与首行 {width} 不一致")
        if binary:
            vals = []
            for v in row:
                if isinstance(v, bool):
                    vals.append(int(v))
                elif isinstance(v, int) and v in (0, 1):
                    vals.append(v)
                else:
                    raise ValueError(
                        f"{who}: 第 {i} 行只能包含 0/1，收到 {v!r}")
        else:
            vals = [_metric_number(v, who, i) for v in row]
        rows.append(vals)
    return rows


def _multilabel_pair(y_true, y_pred, who):
    """校验多标签 y_true / y_pred 形状一致，返回两个 list[list]。"""
    t = _multilabel_rows(y_true, f"{who}.y_true", True)
    p = _multilabel_rows(y_pred, f"{who}.y_pred", True)
    if len(t) != len(p) or len(t[0]) != len(p[0]):
        raise ValueError(f"{who}: y_true / y_pred 形状不一致")
    return t, p


def multilabel_exact_match_ratio(y_true, y_pred) -> float:
    """多标签 Exact Match Ratio：整个标签向量完全一致的样本占比。"""
    t, p = _multilabel_pair(y_true, y_pred, "multilabel_exact_match_ratio")
    hit = sum(1 for a, b in zip(t, p) if a == b)
    return hit / len(t)


def multilabel_ranking_loss(y_true, y_score) -> float:
    """多标签 Ranking Loss：正类得分 <= 负类得分的 (正, 负) 对所占比例。

    每个样本先算「坏对数 / (正类数 × 负类数)」，再对**同时含正类和负类**的样本取平均；
    全都没有正类或负类的样本跳过（与 sklearn 口径一致）。
    """
    t = _multilabel_rows(y_true, "multilabel_ranking_loss.y_true", True)
    s = _multilabel_rows(y_score, "multilabel_ranking_loss.y_score", False)
    if len(t) != len(s) or len(t[0]) != len(s[0]):
        raise ValueError("multilabel_ranking_loss: y_true / y_score 形状不一致")
    total, count = 0.0, 0
    for ti, si in zip(t, s):
        pos = [j for j, v in enumerate(ti) if v == 1]
        neg = [j for j, v in enumerate(ti) if v == 0]
        if not pos or not neg:
            continue
        bad = sum(1 for a in pos for b in neg if si[a] <= si[b])
        total += bad / (len(pos) * len(neg))
        count += 1
    if count == 0:
        raise ValueError("multilabel_ranking_loss: 所有样本都缺少正类或负类")
    return total / count


def label_ranking_average_precision(y_true, y_score) -> float:
    """多标签 LRAP：按得分降序，对每个正类的 precision@rank 取平均，再对样本平均。

    LRAP 对每个正类算「到该正类为止命中几个正类 / 排名」，等价于该样本的
    平均精度（average precision）；没有正类的样本跳过。
    """
    t = _multilabel_rows(y_true, "label_ranking_average_precision.y_true", True)
    s = _multilabel_rows(y_score, "label_ranking_average_precision.y_score", False)
    if len(t) != len(s) or len(t[0]) != len(s[0]):
        raise ValueError("label_ranking_average_precision: y_true / y_score 形状不一致")
    total, count = 0.0, 0
    for ti, si in zip(t, s):
        pos = [j for j, v in enumerate(ti) if v == 1]
        if not pos:
            continue
        order = sorted(range(len(si)), key=lambda j: (-si[j], j))
        hits, precision_sum = 0, 0.0
        for rank, j in enumerate(order):
            if ti[j] == 1:
                hits += 1
                precision_sum += hits / (rank + 1)
        total += precision_sum / len(pos)
        count += 1
    if count == 0:
        raise ValueError("label_ranking_average_precision: 所有样本都没有正类")
    return total / count


def _logits_softmax(logits):
    """校验 logits 列表并返回 softmax 概率与原始值。"""
    if not isinstance(logits, (list, tuple)) or not logits:
        raise ValueError("logits 必须是非空列表")
    z = [_metric_number(v, "logits", i) for i, v in enumerate(logits)]
    top = max(z)
    ex = [math.exp(v - top) for v in z]
    total = sum(ex)
    return [e / total for e in ex], z


def msp_score(logits) -> float:
    """OOD 检测的 MSP 分数：softmax 最大概率（越高越像分布内样本）。"""
    probs, _ = _logits_softmax(logits)
    return max(probs)


def energy_score(logits, temperature: float = 1.0) -> float:
    """OOD 检测的 Energy 分数：`-T·logsumexp(logits/T)`（越低越像分布内样本）。"""
    if isinstance(temperature, bool) or not isinstance(temperature, (int, float)) \
            or not temperature > 0:
        raise ValueError(f"energy_score: temperature 必须是正数，收到 {temperature!r}")
    _, z = _logits_softmax(logits)
    scaled = [v / float(temperature) for v in z]
    top = max(scaled)
    log_sum_exp = top + math.log(sum(math.exp(v - top) for v in scaled))
    return -float(temperature) * log_sum_exp


def ood_detection_auroc(in_scores, ood_scores) -> float:
    """OOD 检测 AUROC：ID 样本记 1、OOD 记 0，分数越高越像 ID 时的 ROC-AUC。"""
    if not isinstance(in_scores, (list, tuple)) or not in_scores:
        raise ValueError("ood_detection_auroc: in_scores 不能为空")
    if not isinstance(ood_scores, (list, tuple)) or not ood_scores:
        raise ValueError("ood_detection_auroc: ood_scores 不能为空")
    labels = [1] * len(in_scores) + [0] * len(ood_scores)
    scores = list(in_scores) + list(ood_scores)
    return roc_auc_score(labels, scores)


def _binomial_two_sided_p(n, k):
    """二项分布 B(n, 0.5) 下 P(X<=k 或 X>=n-k) 的精确双尾 p 值（log 空间求和防溢出）。"""
    if n <= 0:
        return 1.0
    log_half_n = -n * math.log(2.0)
    total = 0.0
    for i in range(0, min(k, n) + 1):
        log_pmf = (math.lgamma(n + 1) - math.lgamma(i + 1)
                   - math.lgamma(n - i + 1) + log_half_n)
        total += math.exp(log_pmf)
    return min(1.0, 2.0 * total)


def mcnemar_test(y_true, y_pred_a, y_pred_b, exact=None):
    """McNemar 检验：同一批样本上两个分类器的错误率是否有显著差异。

    返回 `{"statistic", "p_value", "n10", "n01", "discordant"}`：
    `n10` = A 对且 B 错，`n01` = A 错且 B 对，`discordant = n10 + n01`。
    `exact=True` 用精确二项分布，`False` 用带连续性校正的卡方（1 自由度），
    `None` 时 `discordant <= 25` 用精确值、否则用卡方。
    """
    ta, pa = _metric_pairs(y_true, y_pred_a, "mcnemar_test")
    tb, pb = _metric_pairs(y_true, y_pred_b, "mcnemar_test")
    if len(ta) != len(tb):
        raise ValueError("mcnemar_test: 三个序列必须等长")
    n10 = n01 = 0
    for i in range(len(ta)):
        ya = _metric_label(ta[i], "mcnemar_test.y_true", i)
        a = _metric_label(pa[i], "mcnemar_test.y_pred_a", i)
        b = _metric_label(pb[i], "mcnemar_test.y_pred_b", i)
        a_ok, b_ok = (a == ya), (b == ya)
        if a_ok and not b_ok:
            n10 += 1
        elif b_ok and not a_ok:
            n01 += 1
    discordant = n10 + n01
    if discordant == 0:
        return {"statistic": 0.0, "p_value": 1.0, "n10": 0, "n01": 0,
                "discordant": 0}
    use_exact = (25 >= discordant) if exact is None else bool(exact)
    if use_exact:
        statistic = float(min(n10, n01))
        p_value = _binomial_two_sided_p(discordant, min(n10, n01))
    else:
        statistic = (abs(n10 - n01) - 1.0) ** 2 / discordant
        p_value = math.erfc(math.sqrt(statistic / 2.0))
    return {"statistic": statistic, "p_value": p_value, "n10": n10, "n01": n01,
            "discordant": discordant}


def wilcoxon_signed_rank_test(x, y=None):
    """Wilcoxon 符号秩检验（配对）：检验 `x - y` 的中位数是否为 0。

    `y` 省略时检验 `x` 本身是否以 0 为中心。返回 `{"statistic", "p_value", "n"}`，
    `statistic = min(W+, W-)`，p 值用正态近似（含并列秩校正）；`x=y` 的样本先剔除。
    """
    if not isinstance(x, (list, tuple)):
        raise ValueError("wilcoxon_signed_rank_test: x 必须是列表")
    xs = [_metric_number(v, "wilcoxon_signed_rank_test.x", i) for i, v in enumerate(x)]
    if y is None:
        diffs = [v for v in xs if v != 0.0]
    else:
        if not isinstance(y, (list, tuple)) or len(y) != len(xs):
            raise ValueError("wilcoxon_signed_rank_test: y 必须与 x 等长")
        ys = [_metric_number(v, "wilcoxon_signed_rank_test.y", i) for i, v in enumerate(y)]
        diffs = [a - b for a, b in zip(xs, ys) if a - b != 0.0]
    n = len(diffs)
    if n == 0:
        raise ValueError("wilcoxon_signed_rank_test: 全部差值都是 0，无法检验")
    order = sorted(range(n), key=lambda i: abs(diffs[i]))
    ranks = [0.0] * n
    tie_term = 0.0
    i = 0
    while i < n:
        j = i
        while j + 1 < n and abs(diffs[order[j + 1]]) == abs(diffs[order[i]]):
            j += 1
        avg = (i + j) / 2.0 + 1.0
        for k in range(i, j + 1):
            ranks[order[k]] = avg
        tie_size = j - i + 1
        tie_term += tie_size ** 3 - tie_size
        i = j + 1
    w_plus = sum(r for r, d in zip(ranks, diffs) if d > 0)
    total_rank = n * (n + 1) / 2.0
    mean = total_rank / 2.0
    var = n * (n + 1) * (2 * n + 1) / 24.0 - tie_term / 48.0
    if var <= 0:
        return {"statistic": min(w_plus, total_rank - w_plus), "p_value": 1.0, "n": n}
    z = (w_plus - mean) / math.sqrt(var)
    p_value = math.erfc(abs(z) / math.sqrt(2.0))
    return {"statistic": min(w_plus, total_rank - w_plus), "p_value": p_value, "n": n}


def bootstrap_ci(values, statistic=None, n_boot=1000, level=0.95, seed=None):
    """对样本做 bootstrap 置信区间（默认统计量：均值）。

    ``statistic`` 接收一次重采样得到的列表并返回标量（如 ``max`` / 中位数函数）。
    返回 ``(lo, hi)``，用百分位法：下界取 ``(1-level)/2`` 分位、上界取
    ``(1+level)/2`` 分位。
    """
    who = "bootstrap_ci"
    if not isinstance(values, (list, tuple)) or not values:
        raise ValueError(f"{who}: values 必须是非空列表")
    try:
        vals = [float(v) for v in values]
    except (TypeError, ValueError):
        raise ValueError(f"{who}: values 必须是数字序列")
    if statistic is None:
        def statistic(sample):
            return sum(sample) / len(sample)
    elif not callable(statistic):
        raise TypeError(f"{who}: statistic 必须是可调用对象或 None")
    if isinstance(n_boot, bool) or not isinstance(n_boot, int) or n_boot < 1:
        raise ValueError(f"{who}: n_boot 必须是 ≥1 的整数，收到 {n_boot!r}")
    if isinstance(level, bool) or not isinstance(level, (int, float)) or not 0.0 < level < 1.0:
        raise ValueError(f"{who}: level 必须在 (0,1) 内，收到 {level!r}")
    if seed is not None and (isinstance(seed, bool) or not isinstance(seed, int)):
        raise ValueError(f"{who}: seed 必须是整数或 None，收到 {seed!r}")
    rng = random.Random(seed)
    n = len(vals)
    boots = []
    for _ in range(n_boot):
        sample = [vals[rng.randrange(n)] for _ in range(n)]
        boots.append(statistic(sample))
    boots.sort()
    lo = max(0, int(math.floor((1.0 - level) / 2.0 * n_boot)))
    hi = min(n_boot - 1, int(math.ceil((1.0 + level) / 2.0 * n_boot)) - 1)
    return boots[lo], boots[hi]


def cohens_d(x, y):
    """Cohen's d 效应量（独立样本，合并标准差）。

    ``d = (mean(x) - mean(y)) / pooled_sd``；两组方差都为 0 时返回 0.0。
    常规口径：|d| < 0.2 微小、0.2~0.5 小、0.5~0.8 中、> 0.8 大。
    """
    who = "cohens_d"

    def _vector(values, name):
        if not isinstance(values, (list, tuple)) or len(values) < 2:
            raise ValueError(f"{who}: {name} 必须是长度 ≥2 的列表")
        try:
            return [float(v) for v in values]
        except (TypeError, ValueError):
            raise ValueError(f"{who}: {name} 必须是数字序列")

    xs = _vector(x, "x")
    ys = _vector(y, "y")
    n1 = len(xs)
    n2 = len(ys)
    m1 = sum(xs) / n1
    m2 = sum(ys) / n2
    v1 = sum((v - m1) ** 2 for v in xs) / (n1 - 1)
    v2 = sum((v - m2) ** 2 for v in ys) / (n2 - 1)
    pooled = ((n1 - 1) * v1 + (n2 - 1) * v2) / (n1 + n2 - 2)
    if pooled <= 0.0:
        return 0.0
    return (m1 - m2) / math.sqrt(pooled)


def temperature_scale(logits, y_true, search_points=200, refine_steps=60):
    """温度缩放校准：在验证集 logits 上拟合标量温度 T，使 NLL 最小。

    返回 ``{"temperature": T, "nll": 校准后 NLL, "nll_before": T=1 时 NLL}``。
    ``logits`` 是未 softmax 的分数行、``y_true`` 是类别下标；T<1 锐化、
    T>1 平滑。先在 [0.05, 20] 的 log 网格上粗搜，再在最优格点邻域做
    三分细化。
    """
    who = "temperature_scale"
    if not isinstance(logits, (list, tuple)) or not logits:
        raise ValueError(f"{who}: logits 必须是非空列表")
    n = len(logits)
    if not isinstance(y_true, (list, tuple)) or len(y_true) != n:
        raise ValueError(f"{who}: y_true 长度必须等于 logits 行数")
    rows = []
    for i, row in enumerate(logits):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"{who}: 第 {i} 行 logits 必须是非空列表")
        try:
            rows.append([float(v) for v in row])
        except (TypeError, ValueError):
            raise ValueError(f"{who}: 第 {i} 行 logits 必须是数字序列")
    c = len(rows[0])
    for i, row in enumerate(rows):
        if len(row) != c:
            raise ValueError(f"{who}: 第 {i} 行 logits 长度 {len(row)} != {c}")
    labels = []
    for i, y in enumerate(y_true):
        if isinstance(y, bool) or not isinstance(y, int) or not 0 <= y < c:
            raise ValueError(f"{who}: 第 {i} 个标签必须是 [0,{c}) 的整数，收到 {y!r}")
        labels.append(y)
    if isinstance(search_points, bool) or not isinstance(search_points, int) or search_points < 3:
        raise ValueError(f"{who}: search_points 必须是 ≥3 的整数")
    if isinstance(refine_steps, bool) or not isinstance(refine_steps, int) or refine_steps < 1:
        raise ValueError(f"{who}: refine_steps 必须是 ≥1 的整数")

    def nll_at(t):
        total = 0.0
        for row, y in zip(rows, labels):
            m = max(row)
            ex = [math.exp((v - m) / t) for v in row]
            total -= (row[y] - m) / t - math.log(sum(ex))
        return total / n

    best_t = 1.0
    best = nll_at(1.0)
    lo_t = math.log(0.05)
    hi_t = math.log(20.0)
    for k in range(search_points):
        t = math.exp(lo_t + (hi_t - lo_t) * k / (search_points - 1))
        v = nll_at(t)
        if v < best:
            best = v
            best_t = t
    lo = max(0.05, best_t / math.e)
    hi = min(20.0, best_t * math.e)
    for _ in range(refine_steps):
        m1 = lo + (hi - lo) / 3.0
        m2 = hi - (hi - lo) / 3.0
        if nll_at(m1) <= nll_at(m2):
            hi = m2
        else:
            lo = m1
    t = 0.5 * (lo + hi)
    return {"temperature": t, "nll": nll_at(t), "nll_before": nll_at(1.0)}


def _regression_pairs(y_true, y_pred, who):
    """把回归目标转成一维浮点列表（支持标量列表或多输出逐维平均）。"""
    yt, yp = _metric_pairs(y_true, y_pred, who)
    flat_t, flat_p = [], []
    for i, (t, p) in enumerate(zip(yt, yp)):
        # 单输出模型常返回 [v]，而标签是标量：这种「长度 1 列表 vs 标量」先摊平
        if isinstance(t, (list, tuple)) and len(t) == 1 and not isinstance(p, (list, tuple)):
            t = t[0]
        if isinstance(p, (list, tuple)) and len(p) == 1 and not isinstance(t, (list, tuple)):
            p = p[0]
        if isinstance(t, (list, tuple)) or isinstance(p, (list, tuple)):
            if not isinstance(t, (list, tuple)) or not isinstance(p, (list, tuple)):
                raise ValueError(f"{who}: 第 {i} 个样本的形式不一致（一个标量、一个向量）")
            if len(t) != len(p):
                raise ValueError(f"{who}: 第 {i} 个样本维度不同（{len(t)} vs {len(p)}）")
            for j, (tv, pv) in enumerate(zip(t, p)):
                flat_t.append(_metric_number(tv, f"{who}.y_true[{i}][{j}]", j))
                flat_p.append(_metric_number(pv, f"{who}.y_pred[{i}][{j}]", j))
        else:
            flat_t.append(_metric_number(t, f"{who}.y_true", i))
            flat_p.append(_metric_number(p, f"{who}.y_pred", i))
    if not flat_t:
        raise ValueError(f"{who}: 没有可比较的数值")
    return flat_t, flat_p


def balanced_accuracy_score(y_true, y_pred, num_classes: int = None) -> float:
    """平衡准确率 = 各类召回率的宏平均（只在真实样本数 > 0 的类上平均）。"""
    mat = confusion_matrix(y_true, y_pred, num_classes)
    n = len(mat)
    recalls = []
    for c in range(n):
        support = sum(mat[c])
        if support:
            recalls.append(mat[c][c] / support)
    if not recalls:
        raise ValueError("balanced_accuracy_score: 没有任何类别样本")
    return sum(recalls) / len(recalls)


def cohen_kappa_score(y_true, y_pred, num_classes: int = None) -> float:
    """Cohen's kappa = (po - pe) / (1 - pe)，po 是观察一致率、pe 是期望一致率。"""
    mat = confusion_matrix(y_true, y_pred, num_classes)
    n = len(mat)
    total = sum(sum(row) for row in mat)
    if total == 0:
        raise ValueError("cohen_kappa_score: 没有样本")
    po = sum(mat[c][c] for c in range(n)) / total
    pe = 0.0
    for c in range(n):
        row = sum(mat[c])
        col = sum(mat[r][c] for r in range(n))
        pe += (row / total) * (col / total)
    if pe >= 1.0:
        raise ValueError("cohen_kappa_score: 所有样本都落在同一类，kappa 无定义")
    return (po - pe) / (1.0 - pe)


def _binary_counts(y_true, y_pred, pos_label, who):
    yt, yp = _metric_pairs(y_true, y_pred, who)
    tp = fp = tn = fn = 0
    for i, (t, p) in enumerate(zip(yt, yp)):
        tv = _metric_label(t, f"{who}.y_true", i)
        pv = _metric_label(p, f"{who}.y_pred", i)
        if tv == pos_label:
            if pv == pos_label:
                tp += 1
            else:
                fn += 1
        else:
            if pv == pos_label:
                fp += 1
            else:
                tn += 1
    if tp + fn == 0:
        raise ValueError(f"{who}: 没有正类样本（pos_label={pos_label}）")
    if tn + fp == 0:
        raise ValueError(f"{who}: 没有负类样本（pos_label={pos_label}）")
    return tp, fp, tn, fn


def sensitivity_score(y_true, y_pred, pos_label: int = 1) -> float:
    """敏感度（召回率）= TP / (TP + FN)，即正类被找出来的比例。"""
    if isinstance(pos_label, bool) or not isinstance(pos_label, int):
        raise ValueError(f"sensitivity_score: pos_label 必须是整数，收到 {pos_label!r}")
    tp, _fp, _tn, fn = _binary_counts(y_true, y_pred, pos_label, "sensitivity_score")
    return tp / (tp + fn)


def specificity_score(y_true, y_pred, pos_label: int = 1) -> float:
    """特异度 = TN / (TN + FP)，即负类被正确排除的比例。"""
    if isinstance(pos_label, bool) or not isinstance(pos_label, int):
        raise ValueError(f"specificity_score: pos_label 必须是整数，收到 {pos_label!r}")
    _tp, fp, tn, _fn = _binary_counts(y_true, y_pred, pos_label, "specificity_score")
    return tn / (tn + fp)


def fbeta_score(y_true, y_pred, beta: float = 1.0, average: str = "binary",
                pos_label: int = 1, num_classes: int = None) -> float:
    """F-beta = (1+β²)·P·R / (β²·P + R)。

    average: 'binary'（只看 pos_label，默认）/ 'macro' / 'micro' / 'weighted'。
    β<1 偏精确率，β>1 偏召回率。
    """
    if isinstance(beta, bool) or not isinstance(beta, (int, float)):
        raise ValueError(f"fbeta_score: beta 必须是数字，收到 {beta!r}")
    if not float(beta) > 0.0:
        raise ValueError(f"fbeta_score: beta 必须 > 0，收到 {beta}")
    if average not in ("binary", "macro", "micro", "weighted"):
        raise ValueError(
            f"fbeta_score: average 必须是 binary/macro/micro/weighted，收到 {average!r}")
    b2 = float(beta) ** 2

    def _f(p, r):
        denom = b2 * p + r
        return (1.0 + b2) * p * r / denom if denom else 0.0

    if average == "binary":
        tp, fp, _tn, fn = _binary_counts(y_true, y_pred, pos_label, "fbeta_score")
        precision = tp / (tp + fp) if (tp + fp) else 0.0
        recall = tp / (tp + fn)
        return _f(precision, recall)

    stats = precision_recall_f1(y_true, y_pred, average="none", num_classes=num_classes)
    per_class = stats["per_class"]
    if average == "micro":
        return _f(stats["precision"], stats["recall"])
    if average == "weighted":
        total = sum(row["support"] for row in per_class)
        if not total:
            return 0.0
        return sum(_f(row["precision"], row["recall"]) * row["support"]
                   for row in per_class) / total
    used = [row for row in per_class if row["support"]]
    if not used:
        raise ValueError("fbeta_score: 没有任何类别样本")
    return sum(_f(row["precision"], row["recall"]) for row in used) / len(used)


def hamming_score(y_true, y_pred) -> float:
    """1 - 汉明损失：逐元素一致的比例（支持标量与等长嵌套标签）。"""
    yt, yp = _metric_pairs(y_true, y_pred, "hamming_score")
    hit = 0
    total = 0
    for i, (t, p) in enumerate(zip(yt, yp)):
        t_list = isinstance(t, (list, tuple))
        p_list = isinstance(p, (list, tuple))
        if t_list and p_list:
            if len(t) != len(p):
                raise ValueError(
                    f"hamming_score: 第 {i} 个样本长度不同（{len(t)} vs {len(p)}）")
            for j, (tv, pv) in enumerate(zip(t, p)):
                hit += 1 if _metric_label(tv, f"hamming_score.y_true[{i}][{j}]", j) == \
                    _metric_label(pv, f"hamming_score.y_pred[{i}][{j}]", j) else 0
                total += 1
        elif t_list or p_list:
            raise ValueError(f"hamming_score: 第 {i} 个样本一个标量一个序列")
        else:
            hit += 1 if _metric_label(t, "hamming_score.y_true", i) == \
                _metric_label(p, "hamming_score.y_pred", i) else 0
            total += 1
    if total == 0:
        raise ValueError("hamming_score: 没有可比较的元素")
    return hit / total


def jaccard_score(y_true, y_pred, average: str = "macro",
                  num_classes: int = None) -> float:
    """Jaccard（IoU）：每类 TP/(TP+FP+FN)，再按 average 聚合。"""
    if average not in ("macro", "micro", "weighted"):
        raise ValueError(
            f"jaccard_score: average 必须是 macro/micro/weighted，收到 {average!r}")
    mat = confusion_matrix(y_true, y_pred, num_classes)
    n = len(mat)
    tp_all = fp_all = fn_all = 0
    per_class = []
    for c in range(n):
        tp = mat[c][c]
        support = sum(mat[c])
        predicted = sum(mat[r][c] for r in range(n))
        fp = predicted - tp
        fn = support - tp
        tp_all += tp
        fp_all += fp
        fn_all += fn
        union = tp + fp + fn
        per_class.append((tp / union if union else 0.0, support))
    if average == "micro":
        union = tp_all + fp_all + fn_all
        if union == 0:
            raise ValueError("jaccard_score: 所有预测与标签都为空")
        return tp_all / union
    used = [v for v, s in per_class if s]
    if not used:
        raise ValueError("jaccard_score: 没有任何类别样本")
    if average == "weighted":
        total = sum(s for _v, s in per_class)
        return sum(v * s for v, s in per_class) / total
    return sum(used) / len(used)


# ============================================================================
#  校准指标（ECE / MCE / Reliability Diagram）
# ============================================================================

# ============================================================================
#  检测指标（IoU / mAP / mAP@[.5:.95] / AR）
# ============================================================================

def _det_box(box, who, tag):
    if not isinstance(box, (list, tuple)) or len(box) != 4:
        raise ValueError(f"{who}: {tag} 必须是 [x1, y1, x2, y2]")
    vals = [_metric_number(v, f"{who}.{tag}", i) for i, v in enumerate(box)]
    if vals[2] < vals[0] or vals[3] < vals[1]:
        raise ValueError(
            f"{who}: {tag} 需要 x2 >= x1 且 y2 >= y1，收到 {vals}")
    return vals


# ============================================================================
#  图像质量指标（PSNR / SSIM / MS-SSIM / FID / KID / IS）
# ============================================================================

def _img_check(a, b, who):
    """校验两张 (C, H, W) 图像形状一致且非空。"""
    if not isinstance(a, (list, tuple)) or not a:
        raise ValueError(f"{who}: 第一张图不能为空")
    if not isinstance(b, (list, tuple)) or not b:
        raise ValueError(f"{who}: 第二张图不能为空")
    if len(a) != len(b):
        raise ValueError(f"{who}: 通道数不同（{len(a)} vs {len(b)}）")
    out_a = []
    out_b = []
    height = None
    width = None
    for c in range(len(a)):
        cha, chb = a[c], b[c]
        if not isinstance(cha, (list, tuple)) or not isinstance(chb, (list, tuple)):
            raise ValueError(f"{who}: 第 {c} 个通道必须是二维列表")
        if len(cha) != len(chb):
            raise ValueError(f"{who}: 第 {c} 个通道高度不同（{len(cha)} vs {len(chb)}）")
        if not cha:
            raise ValueError(f"{who}: 第 {c} 个通道为空")
        if height is None:
            height = len(cha)
            width = len(cha[0])
        elif len(cha) != height:
            raise ValueError(f"{who}: 各通道高度不一致")
        row_a = []
        row_b = []
        for r in range(len(cha)):
            ra, rb = cha[r], chb[r]
            if not isinstance(ra, (list, tuple)) or not isinstance(rb, (list, tuple)):
                raise ValueError(f"{who}: 第 {c} 通道第 {r} 行必须是列表")
            if len(ra) != len(rb):
                raise ValueError(
                    f"{who}: 第 {c} 通道第 {r} 行宽度不同（{len(ra)} vs {len(rb)}）")
            if len(ra) != width:
                raise ValueError(f"{who}: 第 {c} 通道第 {r} 行宽度与首行不一致")
            row_a.append([_metric_number(v, f"{who}.a[{c}][{r}]", i)
                          for i, v in enumerate(ra)])
            row_b.append([_metric_number(v, f"{who}.b[{c}][{r}]", i)
                          for i, v in enumerate(rb)])
        out_a.append(row_a)
        out_b.append(row_b)
    return out_a, out_b


def _img_range(data_range, who):
    if isinstance(data_range, bool) or not isinstance(data_range, (int, float)):
        raise ValueError(f"{who}: data_range 必须是数字")
    if float(data_range) <= 0.0:
        raise ValueError(f"{who}: data_range 必须 > 0，收到 {data_range}")
    return float(data_range)


# ============================================================================
#  一致性与公平性指标（Fleiss Kappa / Krippendorff Alpha / 三项公平性）
# ============================================================================

def _cf_matrix(ratings, who, allow_none):
    """校验评分矩阵（行=评分对象，列=评分者）。"""
    if not isinstance(ratings, (list, tuple)) or not ratings:
        raise ValueError(f"{who}: ratings 不能为空")
    rows = []
    width = None
    for i, row in enumerate(ratings):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"{who}: 第 {i} 行必须是非空列表")
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError(
                f"{who}: 第 {i} 行有 {len(row)} 个评分，与首行 {width} 个不一致")
        vals = []
        for j, v in enumerate(row):
            if v is None:
                if not allow_none:
                    raise ValueError(f"{who}: ratings[{i}][{j}] 不能为 None")
                vals.append(None)
            else:
                vals.append(_metric_label(v, f"{who}.ratings[{i}]", j))
        rows.append(vals)
    return rows, width


# ============================================================================
# ============================================================================
# ============================================================================
#  多模态：CLIP 双塔 + 跨模态融合
# ============================================================================

def _cm_rows(x, who, width=None):
    """校验「行列表」：非空、每行等长、元素是有限数字。"""
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError(f"{who}: 必须是非空的行列表")
    rows = []
    for i, row in enumerate(x):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"{who}: 第 {i} 行必须是非空列表")
        vals = []
        for j, v in enumerate(row):
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f"{who}: 第 {i} 行第 {j} 列不是数字：{v!r}")
            fv = float(v)
            if fv != fv or fv in (float("inf"), float("-inf")):
                raise ValueError(f"{who}: 第 {i} 行第 {j} 列不是有限数")
            vals.append(fv)
        rows.append(vals)
    if width is not None:
        for i, row in enumerate(rows):
            if len(row) != width:
                raise ValueError(
                    f"{who}: 第 {i} 行宽度 {len(row)} 与第一个 {width} 不一致")
    return rows


def _cm_unit(row, who):
    n = math.sqrt(sum(v * v for v in row))
    if n <= 0.0:
        raise ValueError(f"{who}: 不能对全零向量做归一化")
    return [v / n for v in row], n


def clip_similarity(image_embeds, text_embeds):
    """双塔嵌入的余弦相似度矩阵 ``S[i][j] = <img_i, txt_j>``（行已归一化）。"""
    imgs = _cm_rows(image_embeds, "clip_similarity(image_embeds)")
    txts = _cm_rows(text_embeds, "clip_similarity(text_embeds)")
    if len(imgs[0]) != len(txts[0]):
        raise ValueError(
            f"clip_similarity: 图像维度 {len(imgs[0])} 与文本维度 {len(txts[0])} 不一致")
    units_i = [_cm_unit(r, "clip_similarity")[0] for r in imgs]
    units_t = [_cm_unit(r, "clip_similarity")[0] for r in txts]
    return [[sum(a * b for a, b in zip(u, v)) for v in units_t] for u in units_i]


def clip_loss(image_embeds, text_embeds, temperature=0.07):
    """对称 InfoNCE（CLIP 的对比损失），返回 ``(loss, grad_img, grad_txt)``。

    绑定关系是「第 i 张图配第 i 段文本」，所以正样本在对角线上；两侧交叉熵各占一半。
    """
    if not isinstance(temperature, (int, float)) or isinstance(temperature, bool) \
            or temperature <= 0.0:
        raise ValueError(f"clip_loss: temperature 必须 > 0，收到 {temperature!r}")
    imgs = _cm_rows(image_embeds, "clip_loss(image_embeds)")
    txts = _cm_rows(text_embeds, "clip_loss(text_embeds)")
    n = len(imgs)
    if len(txts) != n:
        raise ValueError(
            f"clip_loss: 图像 {n} 条与文本 {len(txts)} 条数量必须相同（第 i 对是正样本）")
    if len(imgs[0]) != len(txts[0]):
        raise ValueError(
            f"clip_loss: 图像维度 {len(imgs[0])} 与文本维度 {len(txts[0])} 不一致")
    ui, ni = [], []
    for r in imgs:
        u, k = _cm_unit(r, "clip_loss")
        ui.append(u)
        ni.append(k)
    ut, nt = [], []
    for r in txts:
        u, k = _cm_unit(r, "clip_loss")
        ut.append(u)
        nt.append(k)
    d = len(ui[0])
    tau = float(temperature)
    s = [[sum(a * b for a, b in zip(ui[i], ut[j])) / tau for j in range(n)]
         for i in range(n)]
    p = [_softmax_row(row) for row in s]
    cols = [[s[i][j] for i in range(n)] for j in range(n)]
    q = [_softmax_row(row) for row in cols]
    loss = 0.0
    for i in range(n):
        loss += -math.log(max(p[i][i], 1e-300))
    for j in range(n):
        loss += -math.log(max(q[j][j], 1e-300))
    loss /= (2.0 * n)
    ds = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            ds[i][j] = 0.5 * ((p[i][j] - (1.0 if i == j else 0.0)) / n
                              + (q[j][i] - (1.0 if i == j else 0.0)) / n)
    d_ui = [[sum(ds[i][j] * ut[j][k] for j in range(n)) / tau for k in range(d)]
            for i in range(n)]
    d_ut = [[sum(ds[i][j] * ui[i][k] for i in range(n)) / tau for k in range(d)]
            for j in range(n)]
    g_img = []
    for i in range(n):
        dot = sum(a * b for a, b in zip(d_ui[i], ui[i]))
        g_img.append([(d_ui[i][k] - ui[i][k] * dot) / ni[i] for k in range(d)])
    g_txt = []
    for j in range(n):
        dot = sum(a * b for a, b in zip(d_ut[j], ut[j]))
        g_txt.append([(d_ut[j][k] - ut[j][k] * dot) / nt[j] for k in range(d)])
    return loss, g_img, g_txt


def contrastive_retrieval_accuracy(image_embeds, text_embeds):
    """图文检索准确率：返回 ``{"i2t", "t2i", "mean"}``（正确配对在对角线上）。"""
    sim = clip_similarity(image_embeds, text_embeds)
    n = len(sim)
    if len(sim[0]) != n:
        raise ValueError(
            f"contrastive_retrieval_accuracy: 相似度矩阵不是方阵（{n}x{len(sim[0])}）")
    hit_i = 0
    for i in range(n):
        if max(range(n), key=lambda j: sim[i][j]) == i:
            hit_i += 1
    hit_t = 0
    for j in range(n):
        if max(range(n), key=lambda i: sim[i][j]) == j:
            hit_t += 1
    i2t = hit_i / n
    t2i = hit_t / n
    return {"i2t": i2t, "t2i": t2i, "mean": 0.5 * (i2t + t2i)}


class CLIPProjector:
    """CLIP 的两个线性投影头：``img -> embed_dim`` 与 ``txt -> embed_dim``。

    只做投影 + 损失 + 梯度，不内置编码器；梯度是**对本类参数**的解析梯度，
    可以直接喂给 `Adam` / `SGD` 的逐层接口，也可以只当参考实现。
    """

    def __init__(self, image_dim, text_dim, embed_dim=32, temperature=0.07, seed=None):
        for name, v in (("image_dim", image_dim), ("text_dim", text_dim),
                        ("embed_dim", embed_dim)):
            if not isinstance(v, int) or isinstance(v, bool) or v < 1:
                raise ValueError(f"CLIPProjector: {name} 必须是 >=1 的整数，收到 {v!r}")
        if not isinstance(temperature, (int, float)) or isinstance(temperature, bool) \
                or temperature <= 0.0:
            raise ValueError(
                f"CLIPProjector: temperature 必须 > 0，收到 {temperature!r}")
        self.image_dim = image_dim
        self.text_dim = text_dim
        self.embed_dim = embed_dim
        self.temperature = float(temperature)
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            s_img = math.sqrt(2.0 / image_dim)
            s_txt = math.sqrt(2.0 / text_dim)
            self.W_img = [[random.gauss(0.0, s_img) for _ in range(image_dim)]
                          for _ in range(embed_dim)]
            self.b_img = [0.0] * embed_dim
            self.W_txt = [[random.gauss(0.0, s_txt) for _ in range(text_dim)]
                          for _ in range(embed_dim)]
            self.b_txt = [0.0] * embed_dim
        finally:
            random.setstate(state)
        self._img_x = None
        self._txt_x = None

    def param_count(self):
        """可训练标量个数（两个权重矩阵 + 两个偏置）。"""
        return (self.embed_dim * self.image_dim + self.embed_dim
                + self.embed_dim * self.text_dim + self.embed_dim)

    def project(self, image_feats, text_feats):
        """把两组特征投到同一空间，返回 ``(img_emb, txt_emb)``（行列表）。"""
        imgs = _cm_rows(image_feats, "CLIPProjector.project(image_feats)", self.image_dim)
        txts = _cm_rows(text_feats, "CLIPProjector.project(text_feats)", self.text_dim)
        self._img_x = imgs
        self._txt_x = txts
        img_emb = [[sum(self.W_img[j][k] * row[k] for k in range(self.image_dim))
                    + self.b_img[j] for j in range(self.embed_dim)] for row in imgs]
        txt_emb = [[sum(self.W_txt[j][k] * row[k] for k in range(self.text_dim))
                    + self.b_txt[j] for j in range(self.embed_dim)] for row in txts]
        return img_emb, txt_emb

    def loss(self, image_feats, text_feats):
        """投影后算 ``clip_loss``，只返回损失值。"""
        img_emb, txt_emb = self.project(image_feats, text_feats)
        return clip_loss(img_emb, txt_emb, self.temperature)[0]

    def loss_and_grads(self, image_feats, text_feats):
        """返回 ``(loss, grads)``，``grads`` 形如 ``{"W_img","b_img","W_txt","b_txt"}``。"""
        imgs = _cm_rows(image_feats, "CLIPProjector.loss_and_grads(image_feats)",
                        self.image_dim)
        txts = _cm_rows(text_feats, "CLIPProjector.loss_and_grads(text_feats)",
                        self.text_dim)
        if len(imgs) != len(txts):
            raise ValueError(
                f"CLIPProjector: 图像 {len(imgs)} 条与文本 {len(txts)} 条必须一一配对")
        img_emb, txt_emb = self.project(imgs, txts)
        loss, g_img, g_txt = clip_loss(img_emb, txt_emb, self.temperature)
        gw_img = [[0.0] * self.image_dim for _ in range(self.embed_dim)]
        gb_img = [0.0] * self.embed_dim
        gw_txt = [[0.0] * self.text_dim for _ in range(self.embed_dim)]
        gb_txt = [0.0] * self.embed_dim
        for row, g in zip(imgs, g_img):
            for j in range(self.embed_dim):
                gb_img[j] += g[j]
                gwj = gw_img[j]
                for k in range(self.image_dim):
                    gwj[k] += g[j] * row[k]
        for row, g in zip(txts, g_txt):
            for j in range(self.embed_dim):
                gb_txt[j] += g[j]
                gwj = gw_txt[j]
                for k in range(self.text_dim):
                    gwj[k] += g[j] * row[k]
        return loss, {"W_img": gw_img, "b_img": gb_img,
                      "W_txt": gw_txt, "b_txt": gb_txt}

    def apply_grads(self, grads, lr, kind="sgd"):
        """按 ``grads`` 更新一次（``kind`` 只有 ``"sgd"`` 一种，留给手写训练循环）。"""
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr <= 0.0:
            raise ValueError(f"CLIPProjector.apply_grads: lr 必须 > 0，收到 {lr!r}")
        if kind != "sgd":
            raise ValueError(f"CLIPProjector.apply_grads: 只支持 kind='sgd'，收到 {kind!r}")
        for name, W in (("W_img", self.W_img), ("W_txt", self.W_txt)):
            if name not in grads:
                raise ValueError(f"CLIPProjector.apply_grads: grads 缺少 {name}")
            gW = grads[name]
            for j in range(len(W)):
                for k in range(len(W[j])):
                    W[j][k] -= lr * gW[j][k]
        for name, b in (("b_img", self.b_img), ("b_txt", self.b_txt)):
            if name not in grads:
                raise ValueError(f"CLIPProjector.apply_grads: grads 缺少 {name}")
            gb = grads[name]
            for j in range(len(b)):
                b[j] -= lr * gb[j]


def _cm_norm_forward(rows):
    """逐行 LayerNorm（固定 gamma=1、beta=0），返回 ``(out, caches)``。"""
    out = []
    caches = []
    for row in rows:
        d = len(row)
        mean = sum(row) / d
        var = sum((v - mean) ** 2 for v in row) / d
        inv = 1.0 / math.sqrt(var + 1e-5)
        x_hat = [(v - mean) * inv for v in row]
        out.append(list(x_hat))
        caches.append((x_hat, inv, d))
    return out, caches


def _cm_norm_backward(caches, dout):
    """逐行 LayerNorm 的输入梯度（无仿射参数）。"""
    grads = []
    for (x_hat, inv, d), dy in zip(caches, dout):
        m = sum(dy) / d
        m2 = sum(a * b for a, b in zip(dy, x_hat)) / d
        grads.append([inv * (dy[j] - m - x_hat[j] * m2) for j in range(d)])
    return grads


class CrossModalBlock:
    """跨模态融合块：文本作 query、图像作 memory 做交叉注意力，再残差 + 逐行归一化。

    不带 FFN（需要更深的融合时，把输出接给 `TransformerEncoderLayer`）。backward
    同时返回 ``(d_image, d_text)``，因为交叉注意力两侧都收到梯度。
    """

    def __init__(self, d_model, num_heads=2, dropout=0.0):
        if not isinstance(d_model, int) or isinstance(d_model, bool) or d_model < 1:
            raise ValueError(
                f"CrossModalBlock: d_model 必须是 >=1 的整数，收到 {d_model!r}")
        self.d_model = d_model
        self.attn = CrossAttention(d_model, num_heads, dropout)
        self._text = None
        self._image = None
        self._caches = None

    def zero_grad(self):
        """清零交叉注意力的参数梯度。"""
        self.attn.zero_grad()

    def forward(self, image_feats, text_feats):
        """``image_feats`` / ``text_feats`` 都是 ``(T, d_model)`` 的行列表。"""
        imgs = _cm_rows(image_feats, "CrossModalBlock.forward(image_feats)", self.d_model)
        txts = _cm_rows(text_feats, "CrossModalBlock.forward(text_feats)", self.d_model)
        attn_out = self.attn.forward(txts, imgs)
        merged = [[txts[i][j] + attn_out[i][j] for j in range(self.d_model)]
                  for i in range(len(txts))]
        fused, caches = _cm_norm_forward(merged)
        self._text = txts
        self._image = imgs
        self._caches = caches
        return fused

    def backward(self, d_fused):
        """返回 ``(d_image_feats, d_text_feats)``；同时把参数梯度累加进 ``attn.grads``。"""
        if self._caches is None:
            raise RuntimeError("CrossModalBlock.backward: 必须先调用 forward()")
        rows = _cm_rows(d_fused, "CrossModalBlock.backward", self.d_model)
        if len(rows) != len(self._text):
            raise ValueError(
                f"CrossModalBlock.backward: 梯度行数 {len(rows)} 与文本长度 "
                f"{len(self._text)} 不一致")
        d_merged = _cm_norm_backward(self._caches, rows)
        d_text_attn, d_memory = self.attn.backward(d_merged)
        d_text = [[d_merged[i][j] + d_text_attn[i][j] for j in range(self.d_model)]
                  for i in range(len(self._text))]
        return d_memory, d_text

# ============================================================================
#  自监督：预测式任务（Rotation / Jigsaw）
# ============================================================================

def rotation_targets(num_samples, seed=None):
    """Rotation 自监督的标签：每个样本随机取 0/90/180/270 度，返回角度标签列表。"""
    if not isinstance(num_samples, int) or isinstance(num_samples, bool) or num_samples < 1:
        raise ValueError(
            f"rotation_targets: num_samples 必须是 >=1 的整数，收到 {num_samples!r}")
    rng = random.Random(seed)
    return [rng.randrange(4) for _ in range(num_samples)]


def rotate_image(image, k=1):
    """把 ``(C, H, W)`` 图像逆时针旋转 ``k*90`` 度（k 取模 4）。"""
    if not isinstance(k, int) or isinstance(k, bool):
        raise ValueError(f"rotate_image: k 必须是整数，收到 {k!r}")
    rows = []
    for c, chan in enumerate(image):
        if not isinstance(chan, (list, tuple)) or not chan:
            raise ValueError(f"rotate_image: 第 {c} 个通道必须是非空列表")
        rows.append([list(r) for r in chan])
    channels = len(rows)
    height = len(rows[0])
    width = len(rows[0][0])
    for c in range(channels):
        if len(rows[c]) != height:
            raise ValueError(f"rotate_image: 第 {c} 个通道行数不一致")
        for r in rows[c]:
            if len(r) != width:
                raise ValueError(f"rotate_image: 第 {c} 个通道里有宽度不一致的行")
    kk = k % 4
    if height != width and kk % 2 == 1:
        raise ValueError(
            f"rotate_image: {height}x{width} 旋转 90/270 度会改变形状，"
            f"非方图只能旋转 0 或 180 度")
    out = [[[0.0] * width for _ in range(height)] for _ in range(channels)]
    for c in range(channels):
        for y in range(height):
            for x in range(width):
                v = float(rows[c][y][x])
                if kk == 0:
                    ny, nx = y, x
                elif kk == 1:
                    ny, nx = x, height - 1 - y
                elif kk == 2:
                    ny, nx = height - 1 - y, width - 1 - x
                else:
                    ny, nx = width - 1 - x, y
                out[c][ny][nx] = v
    return out


def jigsaw_permutations(num_patches, num_permutations=1, seed=None):
    """Jigsaw 自监督的排列：返回 ``num_permutations`` 个 ``range(num_patches)`` 的乱序副本。"""
    if not isinstance(num_patches, int) or isinstance(num_patches, bool) \
            or num_patches < 2:
        raise ValueError(
            f"jigsaw_permutations: num_patches 必须是 >=2 的整数，收到 {num_patches!r}")
    if not isinstance(num_permutations, int) or isinstance(num_permutations, bool) \
            or num_permutations < 1:
        raise ValueError(
            f"jigsaw_permutations: num_permutations 必须是 >=1 的整数，"
            f"收到 {num_permutations!r}")
    rng = random.Random(seed)
    base = list(range(num_patches))
    out = []
    seen = set()
    tries = 0
    while len(out) < num_permutations and tries < 200 * num_permutations:
        tries += 1
        perm = list(base)
        rng.shuffle(perm)
        if perm == base:
            continue
        key = tuple(perm)
        if key in seen:
            continue
        seen.add(key)
        out.append(perm)
    if len(out) < num_permutations:
        raise ValueError(
            f"jigsaw_permutations: {num_patches} 个 patch 的乱序排列不够 "
            f"{num_permutations} 个（可用 {len(out)} 个）")
    return out


def jigsaw_shuffle(patches, permutation):
    """按 ``permutation`` 重排 patch，返回新的 patch 列表（长度必须一致）。"""
    if not isinstance(patches, (list, tuple)) or not patches:
        raise ValueError("jigsaw_shuffle: patches 必须是非空列表")
    if not isinstance(permutation, (list, tuple)) or len(permutation) != len(patches):
        raise ValueError(
            f"jigsaw_shuffle: permutation 长度必须等于 patch 数 {len(patches)}")
    n = len(patches)
    if sorted(permutation) != list(range(n)):
        raise ValueError("jigsaw_shuffle: permutation 必须是 0..n-1 的一个排列")
    return [patches[permutation[i]] for i in range(n)]


def rotation_classifier_head(features, num_classes=4):
    """Rotation 自监督的预测头（线性 + softmax），返回每行四类概率。"""
    if not isinstance(features, (list, tuple)) or not features:
        raise ValueError("rotation_classifier_head: features 必须是非空行列表")
    rows = []
    for i, row in enumerate(features):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(
                f"rotation_classifier_head: 第 {i} 行必须是非空列表")
        vals = []
        for j, v in enumerate(row):
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(
                    f"rotation_classifier_head: 第 {i} 行第 {j} 列不是数字：{v!r}")
            vals.append(float(v))
        rows.append(vals)
    width = len(rows[0])
    for i, row in enumerate(rows):
        if len(row) != width:
            raise ValueError(
                f"rotation_classifier_head: 第 {i} 行宽度不一致")
    if not isinstance(num_classes, int) or isinstance(num_classes, bool) \
            or num_classes < 2:
        raise ValueError(
            f"rotation_classifier_head: num_classes 必须是 >=2 的整数，"
            f"收到 {num_classes!r}")
    if width < num_classes:
        raise ValueError(
            f"rotation_classifier_head: 特征维度 {width} 小于类别数 {num_classes}")
    out = []
    for row in rows:
        logits = list(row[:num_classes])
        out.append(_softmax_row(logits))
    return out


def rotation_loss(probs, labels):
    """Rotation 自监督的交叉熵，返回平均损失。"""
    if not isinstance(probs, (list, tuple)) or not probs:
        raise ValueError("rotation_loss: probs 必须是非空行列表")
    if not isinstance(labels, (list, tuple)) or len(labels) != len(probs):
        raise ValueError("rotation_loss: labels 长度必须等于批大小")
    total = 0.0
    for i, p in enumerate(probs):
        if not isinstance(p, (list, tuple)) or not p:
            raise ValueError(f"rotation_loss: 第 {i} 行必须是非空列表")
        t = labels[i]
        if isinstance(t, bool) or not isinstance(t, int) or not (0 <= t < len(p)):
            raise ValueError(
                f"rotation_loss: labels[{i}]={t!r} 越界（类别数 {len(p)}）")
        total += -math.log(max(float(p[t]), 1e-300))
    return total / len(probs)


def linear_probe_accuracy(scores, labels):
    """把「已排好序的得分矩阵」当作分类器，返回 argmax 命中率（Jigsaw 常用评估）。"""
    if not isinstance(scores, (list, tuple)) or not scores:
        raise ValueError("linear_probe_accuracy: scores 必须是非空行列表")
    if not isinstance(labels, (list, tuple)) or len(labels) != len(scores):
        raise ValueError("linear_probe_accuracy: labels 长度必须等于样本数")
    hit = 0
    for i, row in enumerate(scores):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"linear_probe_accuracy: 第 {i} 行必须是非空列表")
        vals = []
        for j, v in enumerate(row):
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(
                    f"linear_probe_accuracy: 第 {i} 行第 {j} 列不是数字：{v!r}")
            vals.append(float(v))
        t = labels[i]
        if isinstance(t, bool) or not isinstance(t, int) or not (0 <= t < len(vals)):
            raise ValueError(
                f"linear_probe_accuracy: labels[{i}]={t!r} 越界（类别数 {len(vals)}）")
        if max(range(len(vals)), key=lambda j: vals[j]) == t:
            hit += 1
    return hit / len(scores)

# ============================================================================
#  RL 算法（DQN 族）
# ============================================================================

class ReplayBuffer:
    """定长经验回放：满了以后按写入顺序覆盖最老的样本（FIFO）。"""

    def __init__(self, capacity=1000, seed=None):
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
            raise ValueError(
                f"ReplayBuffer: capacity 必须是 >=1 的整数，收到 {capacity!r}")
        self.capacity = capacity
        self.rng = random.Random(seed)
        self.data = []
        self.pos = 0

    def __len__(self):
        return len(self.data)

    def clear(self):
        """清空回放池。"""
        self.data = []
        self.pos = 0

    def add(self, state, action, reward, next_state, done):
        """写入一条转移；超出容量时覆盖最老的一条。"""
        state = list(state) if isinstance(state, (list, tuple)) else state
        next_state = list(next_state) if isinstance(next_state, (list, tuple)) else next_state
        if isinstance(action, bool) or not isinstance(action, int):
            raise ValueError(f"ReplayBuffer.add: action 必须是整数，收到 {action!r}")
        if isinstance(reward, bool) or not isinstance(reward, (int, float)):
            raise ValueError(f"ReplayBuffer.add: reward 必须是数字，收到 {reward!r}")
        item = (state, action, float(reward), next_state, bool(done))
        if len(self.data) < self.capacity:
            self.data.append(item)
        else:
            self.data[self.pos] = item
            self.pos = (self.pos + 1) % self.capacity

    def sample(self, batch_size):
        """有放回采样 ``batch_size`` 条，返回 ``(states, actions, rewards, next_states, dones)``。"""
        if not isinstance(batch_size, int) or isinstance(batch_size, bool) or batch_size < 1:
            raise ValueError(
                f"ReplayBuffer.sample: batch_size 必须是 >=1 的整数，收到 {batch_size!r}")
        if not self.data:
            raise ValueError("ReplayBuffer.sample: 回放池为空，先 add 一些转移")
        picks = [self.data[self.rng.randrange(len(self.data))] for _ in range(batch_size)]
        states = [p[0] for p in picks]
        actions = [p[1] for p in picks]
        rewards = [p[2] for p in picks]
        next_states = [p[3] for p in picks]
        dones = [p[4] for p in picks]
        return states, actions, rewards, next_states, dones

    def all(self):
        """按写入顺序返回全部转移（调试用）。"""
        return list(self.data)


def dqn_targets(next_q_values, rewards, dones, gamma=0.99):
    """DQN 的目标：``r + gamma * max_a Q'(s', a)``，终止状态只留 ``r``。"""
    if not isinstance(next_q_values, (list, tuple)) or not next_q_values:
        raise ValueError("dqn_targets: next_q_values 必须是非空行列表")
    n = len(next_q_values)
    if not isinstance(rewards, (list, tuple)) or len(rewards) != n:
        raise ValueError("dqn_targets: rewards 长度必须等于样本数")
    if not isinstance(dones, (list, tuple)) or len(dones) != n:
        raise ValueError("dqn_targets: dones 长度必须等于样本数")
    if not isinstance(gamma, (int, float)) or isinstance(gamma, bool) \
            or not (0.0 <= gamma <= 1.0):
        raise ValueError(f"dqn_targets: gamma 必须在 [0,1] 内，收到 {gamma!r}")
    out = []
    for i in range(n):
        row = next_q_values[i]
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"dqn_targets: 第 {i} 行必须是非空列表")
        vals = []
        for j, v in enumerate(row):
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f"dqn_targets: 第 {i} 行第 {j} 列不是数字：{v!r}")
            vals.append(float(v))
        r = rewards[i]
        if isinstance(r, bool) or not isinstance(r, (int, float)):
            raise ValueError(f"dqn_targets: rewards[{i}] 不是数字：{r!r}")
        if dones[i]:
            out.append(float(r))
        else:
            out.append(float(r) + gamma * max(vals))
    return out


def double_dqn_targets(online_next_q, target_next_q, rewards, dones, gamma=0.99):
    """Double DQN：用**在线网络**选动作、用**目标网络**评估该动作的价值。"""
    if not isinstance(online_next_q, (list, tuple)) or not online_next_q:
        raise ValueError("double_dqn_targets: online_next_q 必须是非空行列表")
    if not isinstance(target_next_q, (list, tuple)) \
            or len(target_next_q) != len(online_next_q):
        raise ValueError("double_dqn_targets: 两个 Q 的行数必须相同")
    n = len(online_next_q)
    if not isinstance(rewards, (list, tuple)) or len(rewards) != n:
        raise ValueError("double_dqn_targets: rewards 长度必须等于样本数")
    if not isinstance(dones, (list, tuple)) or len(dones) != n:
        raise ValueError("double_dqn_targets: dones 长度必须等于样本数")
    if not isinstance(gamma, (int, float)) or isinstance(gamma, bool) \
            or not (0.0 <= gamma <= 1.0):
        raise ValueError(f"double_dqn_targets: gamma 必须在 [0,1] 内，收到 {gamma!r}")
    out = []
    for i in range(n):
        row_o = online_next_q[i]
        row_t = target_next_q[i]
        if not isinstance(row_o, (list, tuple)) or not row_o:
            raise ValueError(f"double_dqn_targets: 第 {i} 行必须是非空列表")
        if not isinstance(row_t, (list, tuple)) or len(row_t) != len(row_o):
            raise ValueError(f"double_dqn_targets: 第 {i} 行两侧动作数不同")
        best = max(range(len(row_o)), key=lambda j: float(row_o[j]))
        r = rewards[i]
        if isinstance(r, bool) or not isinstance(r, (int, float)):
            raise ValueError(f"double_dqn_targets: rewards[{i}] 不是数字：{r!r}")
        if dones[i]:
            out.append(float(r))
        else:
            out.append(float(r) + gamma * float(row_t[best]))
    return out


def huber_td_loss(q_values, action, target, delta=1.0):
    """单个样本的 Huber TD 损失，返回 ``(loss, grad_q)``（梯度只落在被选动作上）。"""
    if not isinstance(q_values, (list, tuple)) or not q_values:
        raise ValueError("huber_td_loss: q_values 必须是非空列表")
    n = len(q_values)
    if isinstance(action, bool) or not isinstance(action, int) or not (0 <= action < n):
        raise ValueError(
            f"huber_td_loss: action 必须是 0..{n - 1} 的整数，收到 {action!r}")
    if isinstance(target, bool) or not isinstance(target, (int, float)):
        raise ValueError(f"huber_td_loss: target 必须是数字，收到 {target!r}")
    if not isinstance(delta, (int, float)) or isinstance(delta, bool) or delta <= 0.0:
        raise ValueError(f"huber_td_loss: delta 必须 > 0，收到 {delta!r}")
    q = [float(v) for v in q_values]
    e = q[action] - float(target)
    if abs(e) < delta:
        loss = 0.5 * e * e
        g = e
    else:
        loss = delta * (abs(e) - 0.5 * delta)
        g = delta if e > 0 else -delta
    grad = [0.0] * n
    grad[action] = g
    return loss, grad


def dueling_q_values(state_values, advantages):
    """Dueling 聚合：``Q = V + A - mean(A)``，返回 ``(q, dq_dv, dq_da)``。"""
    if not isinstance(state_values, (list, tuple)) or not state_values:
        raise ValueError("dueling_q_values: state_values 必须是非空列表")
    m = len(state_values)
    if not isinstance(advantages, (list, tuple)) or len(advantages) != m:
        raise ValueError("dueling_q_values: advantages 必须与 state_values 等长")
    for i in range(m):
        a_row = advantages[i]
        if not isinstance(a_row, (list, tuple)) or not a_row:
            raise ValueError(f"dueling_q_values: advantages[{i}] 必须是非空列表")
    k = len(advantages[0])
    for i, a_row in enumerate(advantages):
        if len(a_row) != k:
            raise ValueError(
                f"dueling_q_values: advantages[{i}] 长度 {len(a_row)} 与第一个 {k} 不一致")
    q = []
    for i in range(m):
        v = float(state_values[i])
        row = [float(x) for x in advantages[i]]
        mean = sum(row) / k
        q.append([v + row[j] - mean for j in range(k)])
    # Q_j = V_i + A_ij - mean_j(A_i)：
    #   dv[i][j] = dQ_j/dV_i = 1 当且仅当 i == j
    #   da[i][j] = dQ_j/dA_ij = 1 - 1/k
    dv = [[1.0 if i == j else 0.0 for j in range(k)] for i in range(m)]
    da = [[(1.0 if i == j else 0.0) - 1.0 / k for j in range(k)] for i in range(m)]
    return q, dv, da


class DQNNetwork:
    """Q 网络：``MLP(state_dim -> hidden... -> num_actions)`` 的薄封装。

    只做「状态向量 -> 每个动作的 Q 值」这一件事；参数梯度走 `_mlp_backward`。
    """

    def __init__(self, state_dim, num_actions, hidden=(32,), seed=None):
        for name, v in (("state_dim", state_dim), ("num_actions", num_actions)):
            if not isinstance(v, int) or isinstance(v, bool) or v < 1:
                raise ValueError(f"DQNNetwork: {name} 必须是 >=1 的整数，收到 {v!r}")
        if not isinstance(hidden, (list, tuple)):
            raise ValueError("DQNNetwork: hidden 必须是整数列表")
        for i, h in enumerate(hidden):
            if not isinstance(h, int) or isinstance(h, bool) or h < 1:
                raise ValueError(
                    f"DQNNetwork: hidden[{i}] 必须是 >=1 的整数，收到 {h!r}")
        sizes = [state_dim] + list(hidden) + [num_actions]
        acts = ["relu"] * len(hidden) + ["linear"]
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.model = MLP(sizes, activations=acts)
        finally:
            random.setstate(state)
        self.state_dim = state_dim
        self.num_actions = num_actions
        self.sizes = sizes

    def q_values(self, state):
        """返回 ``[Q(s, a)]`` 共 ``num_actions`` 个。"""
        if not isinstance(state, (list, tuple)) or len(state) != self.state_dim:
            raise ValueError(
                f"DQNNetwork.q_values: state 长度必须是 {self.state_dim}")
        return self.model.forward([float(v) for v in state])

    def q_gradients(self, delta_q):
        """对 ``delta_q`` 反传到参数，返回 ``[(grad_w, grad_b), ...]``。"""
        if not isinstance(delta_q, (list, tuple)) or len(delta_q) != self.num_actions:
            raise ValueError(
                f"DQNNetwork.q_gradients: delta_q 长度必须是 {self.num_actions}")
        return _mlp_backward(self.model, [float(v) for v in delta_q])

    def copy_from(self, other):
        """把 ``other``（同形状的 DQNNetwork）的权重复制过来（目标网络同步用）。"""
        if not isinstance(other, DQNNetwork) \
                or other.sizes != self.sizes:
            raise ValueError("DQNNetwork.copy_from: 只接受同形状的 DQNNetwork")
        for dst, src in zip(self.model.layers, other.model.layers):
            for j in range(len(dst.weights)):
                dst.weights[j][:] = src.weights[j]
            dst.biases[:] = src.biases

    def param_count(self):
        """可训练标量个数。"""
        return sum(layer.fan_out * layer.fan_in + layer.fan_out
                   for layer in self.model.layers)


class DQNAgent:
    """DQN / Double DQN / Dueling 的简化实现（价值侧）。

    - ``double=True`` 时用 Double DQN 目标（在线网络选动作、目标网络估值）
    - ``dueling=True`` 时网络输出 ``V`` 与 ``A`` 两段，再按 ``dueling_q_values`` 聚合
    - 其余照经典 DQN：经验回放 + 目标网络 + ε-greedy + Huber TD
    """

    def __init__(self, state_dim, num_actions, hidden=(32,), lr=0.01,
                 gamma=0.99, epsilon=0.1, target_sync=50, buffer_size=2000,
                 batch_size=16, double=False, dueling=False, seed=None):
        self.state_dim = state_dim
        self.num_actions = num_actions
        self.gamma = gamma
        self.epsilon = epsilon
        self.target_sync = target_sync
        self.batch_size = batch_size
        self.double = bool(double)
        self.dueling = bool(dueling)
        if not isinstance(gamma, (int, float)) or not (0.0 <= gamma <= 1.0):
            raise ValueError(f"DQNAgent: gamma 必须在 [0,1] 内，收到 {gamma!r}")
        if not isinstance(epsilon, (int, float)) or not (0.0 <= epsilon <= 1.0):
            raise ValueError(f"DQNAgent: epsilon 必须在 [0,1] 内，收到 {epsilon!r}")
        if self.dueling:
            out_dim = num_actions + 1
        else:
            out_dim = num_actions
        self.online = DQNNetwork(state_dim, out_dim, hidden, seed=seed)
        self.target = DQNNetwork(state_dim, out_dim, hidden, seed=seed)
        self.target.copy_from(self.online)
        self.optimizer = Adam(self.online.model, lr=lr)
        self.buffer = ReplayBuffer(buffer_size, seed=seed)
        self.rng = random.Random(seed)
        self.steps = 0

    def _split(self, net, state):
        """把网络输出拆成 ``(q_values, state_value, advantages)``。"""
        out = net.q_values(state)
        if not self.dueling:
            return out, None, None
        v = out[0]
        adv = list(out[1:])
        q, _, _ = dueling_q_values([v], [adv])
        return q[0], v, adv

    def q_values(self, state):
        """当前在线网络给出的 Q 值（Dueling 时已聚合）。"""
        return self._split(self.online, state)[0]

    def act(self, state, greedy=False):
        """ε-greedy（``greedy=True`` 时纯贪心）。"""
        if not greedy and self.rng.random() < self.epsilon:
            return self.rng.randrange(self.num_actions)
        q = self.q_values(state)
        return max(range(len(q)), key=lambda j: q[j])

    def observe(self, state, action, reward, next_state, done):
        """写入一条转移到回放池。"""
        self.buffer.add(state, action, reward, next_state, done)

    def sync_target(self):
        """把在线网络的权重同步到目标网络。"""
        self.target.copy_from(self.online)

    def train_step(self):
        """采一个 batch、算一次梯度并更新在线网络，返回平均 TD 损失。"""
        states, actions, rewards, next_states, dones = self.buffer.sample(self.batch_size)
        if self.double:
            online_next = [self._split(self.online, s)[0] for s in next_states]
            target_next = [self._split(self.target, s)[0] for s in next_states]
            targets = double_dqn_targets(online_next, target_next,
                                         rewards, dones, self.gamma)
        else:
            target_next = [self._split(self.target, s)[0] for s in next_states]
            targets = dqn_targets(target_next, rewards, dones, self.gamma)
        total = 0.0
        acc_w = [[[0.0] * layer.fan_in for _ in range(layer.fan_out)]
                 for layer in self.online.model.layers]
        acc_b = [[0.0] * layer.fan_out for layer in self.online.model.layers]
        for i in range(len(states)):
            q, v, adv = self._split(self.online, states[i])
            loss, g = huber_td_loss(q, actions[i], targets[i])
            total += loss
            if self.dueling:
                dq = g
                mean_dq = sum(dq) / len(dq)
                dv = sum(dq)
                da = [dq[j] - mean_dq for j in range(len(dq))]
                delta_out = [dv] + da
            else:
                delta_out = g
            grads = self.online.q_gradients(delta_out)
            for li, (gw, gb) in enumerate(grads):
                for j in range(len(gw)):
                    awj = acc_w[li][j]
                    for k in range(len(gw[j])):
                        awj[k] += gw[j][k]
                    acc_b[li][j] += gb[j]
        inv = 1.0 / len(states)
        avg_w = [[[v * inv for v in row] for row in layer] for layer in acc_w]
        avg_b = [[v * inv for v in row] for row in acc_b]
        self.optimizer.step([(w, b) for w, b in zip(avg_w, avg_b)])
        self.steps += 1
        if self.target_sync and self.steps % self.target_sync == 0:
            self.sync_target()
        return total / len(states)

    def param_count(self):
        """在线网络 + 目标网络的参数总数。"""
        return self.online.param_count() + self.target.param_count()

# ============================================================================
#  RL 基础设施（探索策略 / 多臂老虎机 / RLHF 奖励与 KL）
# ============================================================================

def epsilon_schedule(step, start=1.0, end=0.05, decay_steps=1000, kind="linear"):
    """ε 的衰减：``linear`` 线性到 ``end``，``exp`` 指数到 ``end``。

    ``step >= decay_steps`` 之后恒为 ``end``（不做 clamp 之外的抖动）。
    """
    if isinstance(step, bool) or not isinstance(step, int) or step < 0:
        raise ValueError(f"epsilon_schedule: step 必须是 >=0 的整数，收到 {step!r}")
    for name, v in (("start", start), ("end", end)):
        if isinstance(v, bool) or not isinstance(v, (int, float)) or not (0.0 <= v <= 1.0):
            raise ValueError(f"epsilon_schedule: {name} 必须在 [0,1] 内，收到 {v!r}")
    if end > start:
        raise ValueError(
            f"epsilon_schedule: end({end}) 不能大于 start({start})")
    if isinstance(decay_steps, bool) or not isinstance(decay_steps, int) or decay_steps < 1:
        raise ValueError(
            f"epsilon_schedule: decay_steps 必须是 >=1 的整数，收到 {decay_steps!r}")
    if kind not in ("linear", "exp"):
        raise ValueError(f"epsilon_schedule: kind 只支持 'linear'/'exp'，收到 {kind!r}")
    if step >= decay_steps:
        return float(end)
    frac = float(step) / float(decay_steps)
    if kind == "linear":
        return float(start) + (float(end) - float(start)) * frac
    if start <= 0.0 or end <= 0.0:
        raise ValueError("epsilon_schedule: 指数衰减要求 start 与 end 都 > 0")
    return float(start) * (float(end) / float(start)) ** frac


def epsilon_greedy_action(q_values, epsilon, seed=None):
    """ε-greedy 选动作：以 ε 概率均匀随机，否则取 Q 最大（同分取下标最小）。"""
    if not isinstance(q_values, (list, tuple)) or not q_values:
        raise ValueError("epsilon_greedy_action: q_values 必须是非空列表")
    if isinstance(epsilon, bool) or not isinstance(epsilon, (int, float)) \
            or not (0.0 <= epsilon <= 1.0):
        raise ValueError(
            f"epsilon_greedy_action: epsilon 必须在 [0,1] 内，收到 {epsilon!r}")
    rng = random.Random(seed) if seed is not None else random
    n = len(q_values)
    if rng.random() < float(epsilon):
        return rng.randrange(n)
    best = 0
    for j in range(1, n):
        if float(q_values[j]) > float(q_values[best]):
            best = j
    return best


def ucb1_action(means, counts, c=1.0):
    """UCB1：没被拉过的臂优先（按下标顺序），否则 ``mean + c*sqrt(ln N / n)``。"""
    if not isinstance(means, (list, tuple)) or not means:
        raise ValueError("ucb1_action: means 必须是非空列表")
    if not isinstance(counts, (list, tuple)) or len(counts) != len(means):
        raise ValueError("ucb1_action: counts 长度必须与 means 相同")
    if isinstance(c, bool) or not isinstance(c, (int, float)) or c <= 0.0:
        raise ValueError(f"ucb1_action: c 必须 > 0，收到 {c!r}")
    total = 0
    for i, n in enumerate(counts):
        if isinstance(n, bool) or not isinstance(n, int) or n < 0:
            raise ValueError(f"ucb1_action: counts[{i}] 必须是非负整数，收到 {n!r}")
        total += n
    for i, n in enumerate(counts):
        if n == 0:
            return i
    if total == 0:
        raise ValueError("ucb1_action: 所有臂的计数都是 0")
    best = 0
    best_score = None
    for i in range(len(means)):
        score = float(means[i]) + c * _math_sqrt(_math_log(total) / counts[i])
        if best_score is None or score > best_score:
            best_score = score
            best = i
    return best


def _math_sqrt(x):
    return math.sqrt(x)


def _math_log(x):
    return math.log(x) if x > 0.0 else 0.0


class BetaBernoulliBandit:
    """Thompson 采样的 Beta-Bernoulli 老虎机：``alpha += r``、``beta += 1 - r``。"""

    def __init__(self, num_arms, seed=None):
        if isinstance(num_arms, bool) or not isinstance(num_arms, int) or num_arms < 1:
            raise ValueError(
                f"BetaBernoulliBandit: num_arms 必须是 >=1 的整数，收到 {num_arms!r}")
        self.num_arms = num_arms
        self.alpha = [1.0] * num_arms
        self.beta = [1.0] * num_arms
        self.rng = random.Random(seed)

    def select(self):
        """按 Thompson 采样挑一个臂（各臂独立采 Beta，取最大）。"""
        best = 0
        best_draw = -1.0
        for i in range(self.num_arms):
            draw = self.rng.betavariate(self.alpha[i], self.beta[i])
            if draw > best_draw:
                best_draw = draw
                best = i
        return best

    def update(self, arm, reward):
        """用一次 ``0/1`` 奖励更新该臂的后验。"""
        if isinstance(arm, bool) or not isinstance(arm, int) \
                or not (0 <= arm < self.num_arms):
            raise ValueError(
                f"BetaBernoulliBandit.update: arm 必须在 0..{self.num_arms - 1}，收到 {arm!r}")
        if isinstance(reward, bool) or not isinstance(reward, (int, float)) \
                or not (0.0 <= float(reward) <= 1.0):
            raise ValueError(
                f"BetaBernoulliBandit.update: reward 必须在 [0,1] 内，收到 {reward!r}")
        self.alpha[arm] += float(reward)
        self.beta[arm] += 1.0 - float(reward)

    def means(self):
        """各臂后验均值。"""
        return [self.alpha[i] / (self.alpha[i] + self.beta[i])
                for i in range(self.num_arms)]


def bradley_terry_loss(chosen_scores, rejected_scores):
    """Bradley-Terry 偏好损失：``-log sigmoid(r_c - r_r)``，返回 ``(loss, d_chosen, d_rejected)``。"""
    if not isinstance(chosen_scores, (list, tuple)) or not chosen_scores:
        raise ValueError("bradley_terry_loss: chosen_scores 必须是非空列表")
    if not isinstance(rejected_scores, (list, tuple)) \
            or len(rejected_scores) != len(chosen_scores):
        raise ValueError("bradley_terry_loss: 两侧长度必须相同")
    n = len(chosen_scores)
    total = 0.0
    d_chosen = []
    d_rejected = []
    for i in range(n):
        diff = float(chosen_scores[i]) - float(rejected_scores[i])
        # softplus(-diff) = log(1 + exp(-diff))，数值稳定写法
        if diff >= 0.0:
            loss = _math_log(1.0 + _math_exp(-diff))
        else:
            loss = -diff + _math_log(1.0 + _math_exp(diff))
        total += loss
        sig = 1.0 / (1.0 + _math_exp(diff))   # sigmoid(-diff)
        d_chosen.append(-sig / n)
        d_rejected.append(sig / n)
    return total / n, d_chosen, d_rejected


def kl_penalty(logp, ref_logp):
    """逐 token 的 KL 惩罚（``logp - ref_logp`` 的求和），用于 RLHF 的奖励扣减。"""
    if not isinstance(logp, (list, tuple)) or not logp:
        raise ValueError("kl_penalty: logp 必须是非空列表")
    if not isinstance(ref_logp, (list, tuple)) or len(ref_logp) != len(logp):
        raise ValueError("kl_penalty: ref_logp 长度必须与 logp 相同")
    total = 0.0
    for i in range(len(logp)):
        total += float(logp[i]) - float(ref_logp[i])
    return total


def rlhf_reward(rewards, logps, ref_logps, beta=0.1):
    """RLHF 的逐步奖励：``r_t - beta * (logp_t - ref_logp_t)``（逐 token）。"""
    if not isinstance(rewards, (list, tuple)) or not rewards:
        raise ValueError("rlhf_reward: rewards 必须是非空列表")
    n = len(rewards)
    if not isinstance(logps, (list, tuple)) or len(logps) != n:
        raise ValueError("rlhf_reward: logps 长度必须与 rewards 相同")
    if not isinstance(ref_logps, (list, tuple)) or len(ref_logps) != n:
        raise ValueError("rlhf_reward: ref_logps 长度必须与 rewards 相同")
    if isinstance(beta, bool) or not isinstance(beta, (int, float)) or beta < 0.0:
        raise ValueError(f"rlhf_reward: beta 必须 >= 0，收到 {beta!r}")
    out = []
    for i in range(n):
        out.append(float(rewards[i]) - float(beta) * (float(logps[i]) - float(ref_logps[i])))
    return out

# ============================================================================
#  RL 策略侧（REINFORCE / A2C(GAE) / PPO）
# ============================================================================

def _rl_softmax(logits):
    """数值稳定的行 softmax（RL 内部用）。"""
    if not isinstance(logits, (list, tuple)) or not logits:
        raise ValueError("softmax: logits 必须是非空列表")
    z = [float(v) for v in logits]
    m = max(z)
    e = [_math_exp(v - m) for v in z]
    total = sum(e)
    return [v / total for v in e]


def _rl_log_softmax(logits):
    """行 log-softmax，返回与 `logits` 等长的列表。"""
    p = _rl_softmax(logits)
    out = []
    for v in p:
        out.append(_rl_log(v) if v > 0.0 else -745.0)
    return out


def policy_gradient_loss(logits, action, advantage):
    """REINFORCE / A2C 的策略梯度损失：``-A * log pi(a|s)``，返回 ``(loss, dlogits)``。

    梯度：``dL/dz_j = -A * (onehot_j - p_j)``。
    """
    if not isinstance(logits, (list, tuple)) or not logits:
        raise ValueError("policy_gradient_loss: logits 必须是非空列表")
    n = len(logits)
    if isinstance(action, bool) or not isinstance(action, int) or not (0 <= action < n):
        raise ValueError(
            f"policy_gradient_loss: action 必须是 0..{n - 1} 的整数，收到 {action!r}")
    if isinstance(advantage, bool) or not isinstance(advantage, (int, float)):
        raise ValueError(
            f"policy_gradient_loss: advantage 必须是数字，收到 {advantage!r}")
    probs = _rl_softmax(logits)
    logs = _rl_log_softmax(logits)
    loss = -float(advantage) * logs[action]
    grad = []
    for j in range(n):
        onehot = 1.0 if j == action else 0.0
        grad.append(-float(advantage) * (onehot - probs[j]))
    return loss, grad


def entropy_term(logits):
    """策略熵与它对 logits 的导数：``H = -sum p log p``，``dH/dz_j = -p_j (log p_j + H)``。"""
    if not isinstance(logits, (list, tuple)) or not logits:
        raise ValueError("entropy_term: logits 必须是非空列表")
    probs = _rl_softmax(logits)
    logs = _rl_log_softmax(logits)
    h = 0.0
    for j in range(len(probs)):
        if probs[j] > 0.0:
            h -= probs[j] * logs[j]
    grad = [-probs[j] * (logs[j] + h) for j in range(len(probs))]
    return h, grad


def value_loss(values, returns):
    """价值网络的 MSE：``0.5 * (v - R)^2``，返回 ``(loss, dvalues)``。"""
    if not isinstance(values, (list, tuple)) or not values:
        raise ValueError("value_loss: values 必须是非空列表")
    if not isinstance(returns, (list, tuple)) or len(returns) != len(values):
        raise ValueError("value_loss: returns 长度必须与 values 相同")
    total = 0.0
    grads = []
    for i, v in enumerate(values):
        e = float(v) - float(returns[i])
        total += 0.5 * e * e
        grads.append(e)
    return total / len(values), [g / len(values) for g in grads]


def gae_advantages(rewards, values, dones, gamma=0.99, lam=0.95):
    """GAE(``gamma``, ``lam``)：返回 ``(advantages, returns)``。

    ``delta_t = r_t + gamma * V(s_{t+1}) * (1 - done_t) - V(s_t)``，
    ``A_t = delta_t + gamma * lam * (1 - done_t) * A_{t+1}``；
    ``returns = advantages + values``（作为价值网络的回归目标）。
    """
    if not isinstance(rewards, (list, tuple)) or not rewards:
        raise ValueError("gae_advantages: rewards 必须是非空列表")
    n = len(rewards)
    if not isinstance(values, (list, tuple)) or len(values) != n:
        raise ValueError("gae_advantages: values 长度必须与 rewards 相同")
    if not isinstance(dones, (list, tuple)) or len(dones) != n:
        raise ValueError("gae_advantages: dones 长度必须与 rewards 相同")
    for name, v in (("gamma", gamma), ("lam", lam)):
        if isinstance(v, bool) or not isinstance(v, (int, float)) or not (0.0 <= v <= 1.0):
            raise ValueError(f"gae_advantages: {name} 必须在 [0,1] 内，收到 {v!r}")
    adv = [0.0] * n
    running = 0.0
    for t in range(n - 1, -1, -1):
        next_value = 0.0 if (t == n - 1 or dones[t]) else float(values[t + 1])
        delta = float(rewards[t]) + gamma * next_value - float(values[t])
        running = delta + gamma * lam * (0.0 if dones[t] else running)
        adv[t] = running
    returns = [adv[t] + float(values[t]) for t in range(n)]
    return adv, returns


def ppo_loss(logits, old_logp, action, advantage, clip_ratio=0.2, entropy_coef=0.0):
    """PPO 裁剪目标（单样本），返回 ``(loss, dlogits, info)``。

    ``ratio = exp(logp_new - logp_old)``，``L = -min(ratio*A, clip(ratio, 1-eps, 1+eps)*A)``；
    被裁掉时梯度为 0。``info`` 里给 ``ratio`` / ``clipped`` / ``entropy``。
    """
    if not isinstance(logits, (list, tuple)) or not logits:
        raise ValueError("ppo_loss: logits 必须是非空列表")
    n = len(logits)
    if isinstance(action, bool) or not isinstance(action, int) or not (0 <= action < n):
        raise ValueError(f"ppo_loss: action 必须是 0..{n - 1} 的整数，收到 {action!r}")
    if isinstance(old_logp, bool) or not isinstance(old_logp, (int, float)):
        raise ValueError(f"ppo_loss: old_logp 必须是数字，收到 {old_logp!r}")
    if isinstance(advantage, bool) or not isinstance(advantage, (int, float)):
        raise ValueError(f"ppo_loss: advantage 必须是数字，收到 {advantage!r}")
    if isinstance(clip_ratio, bool) or not isinstance(clip_ratio, (int, float)) \
            or not (0.0 < clip_ratio < 1.0):
        raise ValueError(
            f"ppo_loss: clip_ratio 必须在 (0,1) 内，收到 {clip_ratio!r}")
    if isinstance(entropy_coef, bool) or not isinstance(entropy_coef, (int, float)) \
            or entropy_coef < 0.0:
        raise ValueError(
            f"ppo_loss: entropy_coef 必须 >= 0，收到 {entropy_coef!r}")
    probs = _rl_softmax(logits)
    logs = _rl_log_softmax(logits)
    logp = logs[action]
    ratio = _math_exp(logp - float(old_logp))
    lo = 1.0 - clip_ratio
    hi = 1.0 + clip_ratio
    clipped_ratio = lo if ratio < lo else (hi if ratio > hi else ratio)
    unclipped_term = ratio * float(advantage)
    clipped_term = clipped_ratio * float(advantage)
    use_unclipped = unclipped_term <= clipped_term
    loss = -min(unclipped_term, clipped_term)
    grad = [0.0] * n
    if use_unclipped:
        for j in range(n):
            onehot = 1.0 if j == action else 0.0
            grad[j] = -float(advantage) * ratio * (onehot - probs[j])
    if entropy_coef:
        h, dh = entropy_term(logits)
        loss -= entropy_coef * h
        for j in range(n):
            grad[j] += entropy_coef * dh[j]
    info = {"ratio": ratio, "clipped": not use_unclipped, "entropy": entropy_term(logits)[0]}
    return loss, grad, info


def _math_exp(x):
    return math.exp(x)


def _exp_clip(x):
    if x > 700.0:
        return float("inf")
    if x < -745.0:
        return 0.0
    return math.exp(x)


def _rl_log(x):
    return math.log(x) if x > 0.0 else -745.0


class PolicyNetwork:
    """离散动作策略网络：``MLP(state -> hidden -> num_actions)`` + 行 softmax。"""

    def __init__(self, state_dim, num_actions, hidden=(32,), seed=None):
        for name, v in (("state_dim", state_dim), ("num_actions", num_actions)):
            if not isinstance(v, int) or isinstance(v, bool) or v < 1:
                raise ValueError(f"PolicyNetwork: {name} 必须是 >=1 的整数，收到 {v!r}")
        sizes = [state_dim] + list(hidden) + [num_actions]
        acts = ["relu"] * len(hidden) + ["linear"]
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.model = MLP(sizes, activations=acts)
        finally:
            random.setstate(state)
        self.state_dim = state_dim
        self.num_actions = num_actions
        self.sizes = sizes

    def logits(self, state):
        """返回未归一化的动作分数。"""
        if not isinstance(state, (list, tuple)) or len(state) != self.state_dim:
            raise ValueError(f"PolicyNetwork.logits: state 长度必须是 {self.state_dim}")
        return self.model.forward([float(v) for v in state])

    def probs(self, state):
        """动作概率。"""
        return _rl_softmax(self.logits(state))

    def log_probs(self, state):
        """动作对数概率。"""
        return _rl_log_softmax(self.logits(state))

    def sample(self, state, seed=None):
        """按概率采样一个动作，返回 ``(action, logp)``。"""
        probs = self.probs(state)
        logs = _rl_log_softmax(self.logits(state))
        rng = random.Random(seed) if seed is not None else random
        x = rng.random()
        acc = 0.0
        pick = len(probs) - 1
        for j in range(len(probs)):
            acc += probs[j]
            if x < acc:
                pick = j
                break
        return pick, logs[pick]

    def gradients(self, dlogits):
        """把 ``dlogits`` 反传到参数。"""
        return _mlp_backward(self.model, [float(v) for v in dlogits])

    def copy_from(self, other):
        """复制同形状网络的权重。"""
        if not isinstance(other, PolicyNetwork) or other.sizes != self.sizes:
            raise ValueError("PolicyNetwork.copy_from: 只接受同形状的 PolicyNetwork")
        for dst, src in zip(self.model.layers, other.model.layers):
            for j in range(len(dst.weights)):
                dst.weights[j][:] = src.weights[j]
            dst.biases[:] = src.biases

    def param_count(self):
        """可训练标量个数。"""
        return sum(layer.fan_out * layer.fan_in + layer.fan_out
                   for layer in self.model.layers)


class ValueNetwork:
    """状态价值网络：``MLP(state -> hidden -> 1)``。"""

    def __init__(self, state_dim, hidden=(32,), seed=None):
        if not isinstance(state_dim, int) or isinstance(state_dim, bool) or state_dim < 1:
            raise ValueError(
                f"ValueNetwork: state_dim 必须是 >=1 的整数，收到 {state_dim!r}")
        sizes = [state_dim] + list(hidden) + [1]
        acts = ["relu"] * len(hidden) + ["linear"]
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.model = MLP(sizes, activations=acts)
        finally:
            random.setstate(state)
        self.state_dim = state_dim
        self.sizes = sizes

    def value(self, state):
        """单个状态的 V(s)（标量）。"""
        if not isinstance(state, (list, tuple)) or len(state) != self.state_dim:
            raise ValueError(f"ValueNetwork.value: state 长度必须是 {self.state_dim}")
        return self.model.forward([float(v) for v in state])[0]

    def gradients(self, dvalue):
        """把 ``dvalue`` 反传到参数。"""
        if isinstance(dvalue, bool) or not isinstance(dvalue, (int, float)):
            raise ValueError(f"ValueNetwork.gradients: dvalue 必须是数字，收到 {dvalue!r}")
        return _mlp_backward(self.model, [float(dvalue)])

    def copy_from(self, other):
        """复制同形状网络的权重。"""
        if not isinstance(other, ValueNetwork) or other.sizes != self.sizes:
            raise ValueError("ValueNetwork.copy_from: 只接受同形状的 ValueNetwork")
        for dst, src in zip(self.model.layers, other.model.layers):
            for j in range(len(dst.weights)):
                dst.weights[j][:] = src.weights[j]
            dst.biases[:] = src.biases

    def param_count(self):
        """可训练标量个数。"""
        return sum(layer.fan_out * layer.fan_in + layer.fan_out
                   for layer in self.model.layers)


class PPOAgent:
    """PPO（裁剪目标 + GAE + 熵正则）的离散动作实现。

    ``train(episode)`` 里先把整条轨迹跑完，再按 ``epochs`` 轮、``batch_size``
    随机切分做策略与价值的更新。
    """

    def __init__(self, state_dim, num_actions, hidden=(32,), lr=0.01, gamma=0.99,
                 lam=0.95, clip_ratio=0.2, entropy_coef=0.01, epochs=4,
                 batch_size=8, seed=None):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr <= 0.0:
            raise ValueError(f"PPOAgent: lr 必须 > 0，收到 {lr!r}")
        for name, v in (("gamma", gamma), ("lam", lam)):
            if isinstance(v, bool) or not isinstance(v, (int, float)) \
                    or not (0.0 <= v <= 1.0):
                raise ValueError(f"PPOAgent: {name} 必须在 [0,1] 内，收到 {v!r}")
        if not isinstance(epochs, int) or isinstance(epochs, bool) or epochs < 1:
            raise ValueError(f"PPOAgent: epochs 必须是 >=1 的整数，收到 {epochs!r}")
        if not isinstance(batch_size, int) or isinstance(batch_size, bool) or batch_size < 1:
            raise ValueError(
                f"PPOAgent: batch_size 必须是 >=1 的整数，收到 {batch_size!r}")
        self.state_dim = state_dim
        self.num_actions = num_actions
        self.gamma = gamma
        self.lam = lam
        self.clip_ratio = clip_ratio
        self.entropy_coef = entropy_coef
        self.epochs = epochs
        self.batch_size = batch_size
        self.policy = PolicyNetwork(state_dim, num_actions, hidden, seed=seed)
        self.value = ValueNetwork(state_dim, hidden, seed=seed)
        self.policy_opt = Adam(self.policy.model, lr=lr)
        self.value_opt = Adam(self.value.model, lr=lr)
        self.rng = random.Random(seed)

    def act(self, state):
        """按当前策略采样动作，返回 ``(action, logp)``。"""
        return self.policy.sample(state, seed=self.rng.randrange(1 << 30))

    def collect(self, env, max_steps=None):
        """跑一条完整轨迹，返回训练所需的张量字典。"""
        state = env.reset()
        states, actions, rewards, logps, values, dones = [], [], [], [], [], []
        steps = 0
        while True:
            action, logp = self.act(state)
            next_state, reward, done, info = env.step(action)
            states.append(list(state))
            actions.append(action)
            rewards.append(float(reward))
            logps.append(float(logp))
            values.append(float(self.value.value(state)))
            dones.append(bool(done))
            state = next_state
            steps += 1
            if done or (max_steps is not None and steps >= max_steps):
                break
        adv, returns = gae_advantages(rewards, values, dones, self.gamma, self.lam)
        return {"states": states, "actions": actions, "logps": logps,
                "rewards": rewards, "values": values, "dones": dones,
                "advantages": adv, "returns": returns}

    def train(self, env, max_steps=None):
        """采一条轨迹并做 ``epochs`` 轮更新，返回 ``(policy_loss, value_loss)``。"""
        batch = self.collect(env, max_steps=max_steps)
        n = len(batch["states"])
        adv = list(batch["advantages"])
        mean_adv = sum(adv) / n
        std_adv = (sum((a - mean_adv) ** 2 for a in adv) / n) ** 0.5
        if std_adv > 1e-8:
            adv = [(a - mean_adv) / std_adv for a in adv]
        else:
            adv = [0.0] * n
        p_loss_total = 0.0
        v_loss_total = 0.0
        updates = 0
        for _ in range(self.epochs):
            order = list(range(n))
            self.rng.shuffle(order)
            for start in range(0, n, self.batch_size):
                chunk = order[start:start + self.batch_size]
                if not chunk:
                    continue
                acc_w = [[[0.0] * layer.fan_in for _ in range(layer.fan_out)]
                         for layer in self.policy.model.layers]
                acc_b = [[0.0] * layer.fan_out for layer in self.policy.model.layers]
                vacc_w = [[[0.0] * layer.fan_in for _ in range(layer.fan_out)]
                          for layer in self.value.model.layers]
                vacc_b = [[0.0] * layer.fan_out for layer in self.value.model.layers]
                for i in chunk:
                    logits = self.policy.logits(batch["states"][i])
                    loss, grad, info = ppo_loss(
                        logits, batch["logps"][i], batch["actions"][i], adv[i],
                        self.clip_ratio, self.entropy_coef)
                    p_loss_total += loss
                    grads = self.policy.gradients(grad)
                    for li, (gw, gb) in enumerate(grads):
                        for j in range(len(gw)):
                            row = acc_w[li][j]
                            for k in range(len(gw[j])):
                                row[k] += gw[j][k]
                            acc_b[li][j] += gb[j]
                    v = self.value.value(batch["states"][i])
                    vloss, dv = value_loss([v], [batch["returns"][i]])
                    v_loss_total += vloss
                    vgrads = self.value.gradients(dv[0])
                    for li, (gw, gb) in enumerate(vgrads):
                        for j in range(len(gw)):
                            row = vacc_w[li][j]
                            for k in range(len(gw[j])):
                                row[k] += gw[j][k]
                            vacc_b[li][j] += gb[j]
                inv = 1.0 / len(chunk)
                avg_w = [[[v * inv for v in row] for row in layer] for layer in acc_w]
                avg_b = [[v * inv for v in row] for row in acc_b]
                self.policy_opt.step([(w, b) for w, b in zip(avg_w, avg_b)])
                vavg_w = [[[v * inv for v in row] for row in layer] for layer in vacc_w]
                vavg_b = [[v * inv for v in row] for row in vacc_b]
                self.value_opt.step([(w, b) for w, b in zip(vavg_w, vavg_b)])
                updates += 1
        return p_loss_total / max(1, updates * 1.0), v_loss_total / max(1, updates * 1.0)

    def param_count(self):
        """策略网络 + 价值网络的参数总数。"""
        return self.policy.param_count() + self.value.param_count()

def _mlp_backward_with_input(model: 'MLP', loss_grad: list):
    """对 MLP 反向，返回 (每层 (grad_w, grad_b), 输入梯度)。"""
    delta = [float(v) for v in loss_grad]
    grads = []
    for i in range(len(model.layers) - 1, -1, -1):
        gw, gb, delta = model.layers[i].backward(delta)
        grads.append((gw, gb))
    grads.reverse()
    return grads, delta


def _mlp_zero_grads(model: 'MLP') -> list:
    """按模型层结构分配零梯度容器。"""
    return [[[0.0] * layer.fan_in for _ in range(layer.fan_out)]
            for layer in model.layers]


def _mlp_acc_bias(model: 'MLP') -> list:
    return [[0.0] * layer.fan_out for layer in model.layers]


def _mlp_accumulate(acc_w, acc_b, grads):
    """把一批 (grad_w, grad_b) 累加进容器（调用方自行除以 batch）。"""
    for li, (gw, gb) in enumerate(grads):
        aw = acc_w[li]
        ab = acc_b[li]
        for j in range(len(gw)):
            row = aw[j]
            gj = gw[j]
            for k in range(len(gj)):
                row[k] += gj[k]
            ab[j] += gb[j]


def _soft_update(target, source, tau):
    """目标网络软更新：param = (1-tau)*target + tau*source。"""
    for dl, sl in zip(target.model.layers, source.model.layers):
        for j in range(len(dl.weights)):
            dw, sw = dl.weights[j], sl.weights[j]
            for i in range(len(dw)):
                dw[i] = (1.0 - tau) * dw[i] + tau * sw[i]
            dl.biases[j] = (1.0 - tau) * dl.biases[j] + tau * sl.biases[j]


class ContinuousReplayBuffer:
    """连续动作经验回放：action 是 float 列表（与 ReplayBuffer 的整数动作区分）。"""

    def __init__(self, capacity=10000, seed=None):
        if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < 1:
            raise ValueError(
                f"ContinuousReplayBuffer: capacity 必须是 >=1 的整数，收到 {capacity!r}")
        if seed is not None and (isinstance(seed, bool) or not isinstance(seed, int)):
            raise ValueError(
                f"ContinuousReplayBuffer: seed 必须是 int 或 None，收到 {seed!r}")
        self.capacity = capacity
        self.buffer = []
        self.rng = random.Random(seed)

    def __len__(self):
        return len(self.buffer)

    def add(self, state, action, reward, next_state, done):
        """写入一步经验；action 必须是有限 float 列表。"""
        if not isinstance(state, (list, tuple)) or not state:
            raise ValueError("ContinuousReplayBuffer.add: state 必须是非空列表")
        if not isinstance(next_state, (list, tuple)) or not next_state:
            raise ValueError(
                "ContinuousReplayBuffer.add: next_state 必须是非空列表")
        if not isinstance(action, (list, tuple)) or not action:
            raise ValueError(
                "ContinuousReplayBuffer.add: action 必须是非空 float 列表")
        acts = []
        for v in action:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(
                    f"ContinuousReplayBuffer.add: action 元素必须是数字，收到 {v!r}")
            fv = float(v)
            if not math.isfinite(fv):
                raise ValueError(
                    f"ContinuousReplayBuffer.add: action 元素必须是有限数，收到 {v!r}")
            acts.append(fv)
        if isinstance(reward, bool) or not isinstance(reward, (int, float)):
            raise ValueError(
                f"ContinuousReplayBuffer.add: reward 必须是数字，收到 {reward!r}")
        self.buffer.append(([float(v) for v in state], acts, float(reward),
                            [float(v) for v in next_state], bool(done)))
        if len(self.buffer) > self.capacity:
            del self.buffer[0]

    def sample(self, batch_size):
        """随机采样，返回 (states, actions, rewards, next_states, dones)。"""
        if isinstance(batch_size, bool) or not isinstance(batch_size, int) \
                or batch_size < 1:
            raise ValueError(
                f"ContinuousReplayBuffer.sample: batch_size 必须是 >=1 的整数，收到 {batch_size!r}")
        if len(self.buffer) < batch_size:
            raise ValueError(
                f"ContinuousReplayBuffer.sample: 经验不足（已有 {len(self.buffer)}，"
                f"需要 {batch_size}）")
        picks = self.rng.sample(range(len(self.buffer)), batch_size)
        batch = [self.buffer[i] for i in picks]
        return ([b[0] for b in batch], [b[1] for b in batch],
                [b[2] for b in batch], [b[3] for b in batch],
                [b[4] for b in batch])

    def clear(self):
        """清空回放池。"""
        self.buffer = []


class DeterministicPolicyNetwork:
    """确定性策略：MLP(state -> tanh 挤压的 action)，按 action_scale 缩放。"""

    def __init__(self, state_dim, action_dim, hidden=(64, 64),
                 action_scale=1.0, seed=None):
        for name, v in (("state_dim", state_dim), ("action_dim", action_dim)):
            if not isinstance(v, int) or isinstance(v, bool) or v < 1:
                raise ValueError(
                    f"DeterministicPolicyNetwork: {name} 必须是 >=1 的整数，收到 {v!r}")
        if isinstance(action_scale, bool) or not isinstance(action_scale, (int, float)) \
                or action_scale <= 0.0:
            raise ValueError(
                f"DeterministicPolicyNetwork: action_scale 必须是 >0 的数字，收到 {action_scale!r}")
        sizes = [state_dim] + list(hidden) + [action_dim]
        acts = ["relu"] * len(hidden) + ["linear"]
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.model = MLP(sizes, activations=acts)
        finally:
            random.setstate(state)
        self.state_dim = state_dim
        self.action_dim = action_dim
        self.action_scale = float(action_scale)
        self.sizes = sizes
        self._z = None

    def raw(self, state):
        """未挤压的 actor 输出。"""
        if not isinstance(state, (list, tuple)) or len(state) != self.state_dim:
            raise ValueError(
                f"DeterministicPolicyNetwork.raw: state 长度必须是 {self.state_dim}")
        return self.model.forward([float(v) for v in state])

    def act(self, state):
        """确定性动作（已乘 action_scale）。"""
        z = self.raw(state)
        self._z = z
        return [self.action_scale * math.tanh(v) for v in z]

    def act_noisy(self, state, noise_std=0.1, seed=None):
        """加高斯探索噪声并截断到 [-scale, scale]。"""
        if isinstance(noise_std, bool) or not isinstance(noise_std, (int, float)) \
                or noise_std < 0.0:
            raise ValueError(
                f"DeterministicPolicyNetwork.act_noisy: noise_std 必须是非负数字，收到 {noise_std!r}")
        rng = random.Random(seed) if seed is not None else random
        action = self.act(state)
        scale = self.action_scale
        out = []
        for v in action:
            n = rng.gauss(0.0, float(noise_std)) if noise_std > 0.0 else 0.0
            out.append(min(scale, max(-scale, v + n)))
        return out

    def gradients(self, daction):
        """把 dL/d(缩放后动作) 反传到参数（tanh 导数含在内部）。"""
        if self._z is None:
            raise RuntimeError(
                "DeterministicPolicyNetwork.gradients: 必须先调用 act()")
        if len(daction) != len(self._z):
            raise ValueError(
                f"DeterministicPolicyNetwork.gradients: 梯度长度必须是 {len(self._z)}")
        dpre = []
        for da, z in zip(daction, self._z):
            t = math.tanh(z)
            dpre.append(float(da) * self.action_scale * (1.0 - t * t))
        return _mlp_backward(self.model, dpre)

    def copy_from(self, other):
        """复制同形状策略的权重。"""
        if not isinstance(other, DeterministicPolicyNetwork) or other.sizes != self.sizes:
            raise ValueError(
                "DeterministicPolicyNetwork.copy_from: 只接受同形状的网络")
        for dst, src in zip(self.model.layers, other.model.layers):
            for j in range(len(dst.weights)):
                dst.weights[j][:] = src.weights[j]
            dst.biases[:] = src.biases

    def param_count(self):
        """可训练标量个数。"""
        return sum(layer.fan_out * layer.fan_in + layer.fan_out
                   for layer in self.model.layers)


class ContinuousQNetwork:
    """连续动作 Q 网络：Q(s, a) = MLP([s, a] -> hidden -> 1)。"""

    def __init__(self, state_dim, action_dim, hidden=(64, 64), seed=None):
        for name, v in (("state_dim", state_dim), ("action_dim", action_dim)):
            if not isinstance(v, int) or isinstance(v, bool) or v < 1:
                raise ValueError(
                    f"ContinuousQNetwork: {name} 必须是 >=1 的整数，收到 {v!r}")
        sizes = [state_dim + action_dim] + list(hidden) + [1]
        acts = ["relu"] * len(hidden) + ["linear"]
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.model = MLP(sizes, activations=acts)
        finally:
            random.setstate(state)
        self.state_dim = state_dim
        self.action_dim = action_dim
        self.sizes = sizes

    def q(self, state, action):
        """单个 (s, a) 的 Q 值。"""
        if not isinstance(state, (list, tuple)) or len(state) != self.state_dim:
            raise ValueError(
                f"ContinuousQNetwork.q: state 长度必须是 {self.state_dim}")
        if not isinstance(action, (list, tuple)) or len(action) != self.action_dim:
            raise ValueError(
                f"ContinuousQNetwork.q: action 长度必须是 {self.action_dim}")
        inp = [float(v) for v in state] + [float(v) for v in action]
        return self.model.forward(inp)[0]

    def q_grads(self, state, action, dq):
        """返回 (Q, 参数梯度, dQ/dstate, dQ/daction)。"""
        if isinstance(dq, bool) or not isinstance(dq, (int, float)):
            raise ValueError(
                f"ContinuousQNetwork.q_grads: dq 必须是数字，收到 {dq!r}")
        q = self.q(state, action)
        grads, dinput = _mlp_backward_with_input(self.model, [float(dq)])
        return q, grads, dinput[:self.state_dim], dinput[self.state_dim:]

    def copy_from(self, other):
        """复制同形状 Q 网络的权重。"""
        if not isinstance(other, ContinuousQNetwork) or other.sizes != self.sizes:
            raise ValueError("ContinuousQNetwork.copy_from: 只接受同形状的网络")
        for dst, src in zip(self.model.layers, other.model.layers):
            for j in range(len(dst.weights)):
                dst.weights[j][:] = src.weights[j]
            dst.biases[:] = src.biases

    def param_count(self):
        """可训练标量个数。"""
        return sum(layer.fan_out * layer.fan_in + layer.fan_out
                   for layer in self.model.layers)


class DDPGAgent:
    """DDPG：确定性 actor + 单 Q critic + 目标网络软更新。"""

    def __init__(self, state_dim, action_dim, hidden=(64, 64), actor_lr=1e-3,
                 critic_lr=1e-3, gamma=0.99, tau=0.005, action_scale=1.0,
                 buffer_capacity=10000, batch_size=32, seed=None):
        for name, v in (("actor_lr", actor_lr), ("critic_lr", critic_lr)):
            if isinstance(v, bool) or not isinstance(v, (int, float)) or v <= 0.0:
                raise ValueError(
                    f"DDPGAgent: {name} 必须 >0，收到 {v!r}")
        if isinstance(gamma, bool) or not isinstance(gamma, (int, float)) \
                or not 0.0 <= gamma <= 1.0:
            raise ValueError(f"DDPGAgent: gamma 必须在 [0,1]，收到 {gamma!r}")
        if isinstance(tau, bool) or not isinstance(tau, (int, float)) \
                or not 0.0 < tau <= 1.0:
            raise ValueError(f"DDPGAgent: tau 必须在 (0,1]，收到 {tau!r}")
        if isinstance(batch_size, bool) or not isinstance(batch_size, int) \
                or batch_size < 1:
            raise ValueError(
                f"DDPGAgent: batch_size 必须是 >=1 的整数，收到 {batch_size!r}")
        self.state_dim = state_dim
        self.action_dim = action_dim
        self.gamma = float(gamma)
        self.tau = float(tau)
        self.batch_size = batch_size
        self.action_scale = float(action_scale)
        self.actor = DeterministicPolicyNetwork(
            state_dim, action_dim, hidden, action_scale, seed=seed)
        self.actor_target = DeterministicPolicyNetwork(
            state_dim, action_dim, hidden, action_scale, seed=None)
        self.actor_target.copy_from(self.actor)
        self.critic = ContinuousQNetwork(state_dim, action_dim, hidden, seed=seed)
        self.critic_target = ContinuousQNetwork(
            state_dim, action_dim, hidden, seed=None)
        self.critic_target.copy_from(self.critic)
        self.actor_opt = Adam(self.actor.model, lr=float(actor_lr))
        self.critic_opt = Adam(self.critic.model, lr=float(critic_lr))
        self.buffer = ContinuousReplayBuffer(buffer_capacity, seed=seed)
        self.rng = random.Random(seed)
        self.updates = 0

    def act(self, state, noise_std=0.1):
        """带探索噪声的动作。"""
        return self.actor.act_noisy(state, noise_std, self.rng.randrange(1 << 30))

    def remember(self, state, action, reward, next_state, done):
        """写入一条经验。"""
        self.buffer.add(state, action, reward, next_state, done)

    def _target_action(self, next_state):
        return self.actor_target.act(next_state)

    def update(self, batch_size=None):
        """从回放池取一个 batch，更新 critic 与 actor，返回损失字典。"""
        bs = self.batch_size if batch_size is None else batch_size
        states, actions, rewards, next_states, dones = self.buffer.sample(bs)
        acc_w = _mlp_zero_grads(self.critic.model)
        acc_b = _mlp_acc_bias(self.critic.model)
        aacc_w = _mlp_zero_grads(self.actor.model)
        aacc_b = _mlp_acc_bias(self.actor.model)
        td_total = 0.0
        act_loss_total = 0.0
        inv = 1.0 / bs
        for i in range(bs):
            if dones[i]:
                target = rewards[i]
            else:
                target = rewards[i] + self.gamma * self.critic_target.q(
                    next_states[i], self._target_action(next_states[i]))
            q = self.critic.q(states[i], actions[i])
            _q, cgrads, _dstate, _daction = self.critic.q_grads(
                states[i], actions[i], q - target)
            td_total += (q - target) ** 2
            _mlp_accumulate(acc_w, acc_b, cgrads)
            actor_action = self.actor.act(states[i])
            _q, _cg, _ds, dq_da = self.critic.q_grads(states[i], actor_action, 1.0)
            daction = [-v * inv for v in dq_da]
            agrads = self.actor.gradients(daction)
            act_loss_total += -_q
            _mlp_accumulate(aacc_w, aacc_b, agrads)
        avg_w = [[[v * inv for v in row] for row in layer] for layer in acc_w]
        avg_b = [[v * inv for v in row] for row in acc_b]
        self.critic_opt.step([(w, b) for w, b in zip(avg_w, avg_b)])
        aavg_w = [[[v * inv for v in row] for row in layer] for layer in aacc_w]
        aavg_b = [[v * inv for v in row] for row in aacc_b]
        self.actor_opt.step([(w, b) for w, b in zip(aavg_w, aavg_b)])
        _soft_update(self.actor_target, self.actor, self.tau)
        _soft_update(self.critic_target, self.critic, self.tau)
        self.updates += 1
        return {"critic_loss": td_total * inv, "actor_loss": act_loss_total * inv}

    def train(self, env, episodes=20, batch_size=None, noise_std=0.1,
              max_steps=200, min_buffer=None):
        """在连续动作环境上训练，返回每回合回报列表。"""
        if not hasattr(env, "reset") or not hasattr(env, "step"):
            raise ValueError("DDPGAgent.train: env 必须提供 reset()/step()")
        if isinstance(episodes, bool) or not isinstance(episodes, int) \
                or episodes < 1:
            raise ValueError(
                f"DDPGAgent.train: episodes 必须是 >=1 的整数，收到 {episodes!r}")
        bs = self.batch_size if batch_size is None else batch_size
        need = max(bs, 1 if min_buffer is None else min_buffer)
        returns = []
        for _ in range(episodes):
            state = env.reset()
            total = 0.0
            steps = 0
            while True:
                action = self.act(state, noise_std)
                out = env.step(action)
                if not isinstance(out, (list, tuple)) or len(out) != 4:
                    raise ValueError(
                        "DDPGAgent.train: env.step 必须返回 (next_state, reward, done, info)")
                next_state, reward, done, _info = out
                self.remember(state, action, reward, next_state, done)
                total += float(reward)
                state = next_state
                steps += 1
                if len(self.buffer) >= need:
                    self.update(bs)
                if done or (max_steps is not None and steps >= max_steps):
                    break
            returns.append(total)
        return returns

    def param_count(self):
        """actor + critic 参数量。"""
        return self.actor.param_count() + self.critic.param_count()


class TD3Agent(DDPGAgent):
    """TD3：双 Q 取最小、目标策略平滑、延迟更新 actor。"""

    def __init__(self, state_dim, action_dim, hidden=(64, 64), actor_lr=1e-3,
                 critic_lr=1e-3, gamma=0.99, tau=0.005, action_scale=1.0,
                 buffer_capacity=10000, batch_size=32, policy_delay=2,
                 target_noise=0.2, noise_clip=0.5, seed=None):
        super().__init__(state_dim, action_dim, hidden=hidden,
                         actor_lr=actor_lr, critic_lr=critic_lr, gamma=gamma,
                         tau=tau, action_scale=action_scale,
                         buffer_capacity=buffer_capacity, batch_size=batch_size,
                         seed=seed)
        for name, v in (("policy_delay", policy_delay),):
            if isinstance(v, bool) or not isinstance(v, int) or v < 1:
                raise ValueError(
                    f"TD3Agent: {name} 必须是 >=1 的整数，收到 {v!r}")
        for name, v in (("target_noise", target_noise), ("noise_clip", noise_clip)):
            if isinstance(v, bool) or not isinstance(v, (int, float)) or v < 0.0:
                raise ValueError(
                    f"TD3Agent: {name} 必须是非负数字，收到 {v!r}")
        self.policy_delay = policy_delay
        self.target_noise = float(target_noise)
        self.noise_clip = float(noise_clip)
        self.critic2 = ContinuousQNetwork(state_dim, action_dim, hidden, seed=None)
        self.critic2.copy_from(self.critic)
        self.critic2_target = ContinuousQNetwork(
            state_dim, action_dim, hidden, seed=None)
        self.critic2_target.copy_from(self.critic2)
        self.critic2_opt = Adam(self.critic2.model, lr=float(critic_lr))

    def _target_action(self, next_state):
        action = self.actor_target.act(next_state)
        scale = self.action_scale
        out = []
        for i, v in enumerate(action):
            if self.target_noise > 0.0:
                n = self.rng.gauss(0.0, self.target_noise)
                n = min(self.noise_clip, max(-self.noise_clip, n))
            else:
                n = 0.0
            out.append(min(scale, max(-scale, v + n)))
        return out

    def update(self, batch_size=None):
        """TD3 更新：双 critic、延迟 actor、软更新两个目标 critic。"""
        bs = self.batch_size if batch_size is None else batch_size
        states, actions, rewards, next_states, dones = self.buffer.sample(bs)
        inv = 1.0 / bs
        acc1w = _mlp_zero_grads(self.critic.model)
        acc1b = _mlp_acc_bias(self.critic.model)
        acc2w = _mlp_zero_grads(self.critic2.model)
        acc2b = _mlp_acc_bias(self.critic2.model)
        aacc_w = _mlp_zero_grads(self.actor.model)
        aacc_b = _mlp_acc_bias(self.actor.model)
        q1_loss = 0.0
        q2_loss = 0.0
        actor_loss = 0.0
        for i in range(bs):
            if dones[i]:
                target = rewards[i]
            else:
                t_act = self._target_action(next_states[i])
                q1t = self.critic_target.q(next_states[i], t_act)
                q2t = self.critic2_target.q(next_states[i], t_act)
                target = rewards[i] + self.gamma * min(q1t, q2t)
            q1 = self.critic.q(states[i], actions[i])
            q2 = self.critic2.q(states[i], actions[i])
            err1 = q1 - target
            err2 = q2 - target
            _q1, g1, _ds, _da = self.critic.q_grads(states[i], actions[i], err1)
            _q2, g2, _ds2, _da2 = self.critic2.q_grads(states[i], actions[i], err2)
            q1_loss += err1 ** 2
            q2_loss += err2 ** 2
            _mlp_accumulate(acc1w, acc1b, g1)
            _mlp_accumulate(acc2w, acc2b, g2)
            if self.updates % self.policy_delay == 0:
                actor_action = self.actor.act(states[i])
                _q, _cg, _ds3, dq_da = self.critic.q_grads(
                    states[i], actor_action, 1.0)
                daction = [-v * inv for v in dq_da]
                agrads = self.actor.gradients(daction)
                actor_loss += -_q
                _mlp_accumulate(aacc_w, aacc_b, agrads)
        avg_w = [[[v * inv for v in row] for row in layer] for layer in acc1w]
        avg_b = [[v * inv for v in row] for row in acc1b]
        self.critic_opt.step([(w, b) for w, b in zip(avg_w, avg_b)])
        avg2_w = [[[v * inv for v in row] for row in layer] for layer in acc2w]
        avg2_b = [[v * inv for v in row] for row in acc2b]
        self.critic2_opt.step([(w, b) for w, b in zip(avg2_w, avg2_b)])
        if self.updates % self.policy_delay == 0:
            aavg_w = [[[v * inv for v in row] for row in layer] for layer in aacc_w]
            aavg_b = [[v * inv for v in row] for row in aacc_b]
            self.actor_opt.step([(w, b) for w, b in zip(aavg_w, aavg_b)])
        _soft_update(self.actor_target, self.actor, self.tau)
        _soft_update(self.critic_target, self.critic, self.tau)
        _soft_update(self.critic2_target, self.critic2, self.tau)
        self.updates += 1
        return {"critic_loss": q1_loss * inv, "critic2_loss": q2_loss * inv,
                "actor_loss": actor_loss * inv}

    def param_count(self):
        """actor + 双 critic 参数量。"""
        return (self.actor.param_count() + self.critic.param_count()
                + self.critic2.param_count())


class SquashedGaussianPolicy:
    """SAC 的随机策略：两个 MLP 分别输出均值与对数标准差，tanh 挤压。"""

    def __init__(self, state_dim, action_dim, hidden=(64, 64), action_scale=1.0,
                 log_std_min=-20.0, log_std_max=2.0, seed=None):
        for name, v in (("state_dim", state_dim), ("action_dim", action_dim)):
            if not isinstance(v, int) or isinstance(v, bool) or v < 1:
                raise ValueError(
                    f"SquashedGaussianPolicy: {name} 必须是 >=1 的整数，收到 {v!r}")
        if isinstance(action_scale, bool) or not isinstance(action_scale, (int, float)) \
                or action_scale <= 0.0:
            raise ValueError(
                f"SquashedGaussianPolicy: action_scale 必须是 >0 的数字，收到 {action_scale!r}")
        for name, v in (("log_std_min", log_std_min), ("log_std_max", log_std_max)):
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(
                    f"SquashedGaussianPolicy: {name} 必须是数字，收到 {v!r}")
        if not float(log_std_min) < float(log_std_max):
            raise ValueError(
                "SquashedGaussianPolicy: log_std_min 必须小于 log_std_max")
        self.state_dim = state_dim
        self.action_dim = action_dim
        self.action_scale = float(action_scale)
        self.log_std_min = float(log_std_min)
        self.log_std_max = float(log_std_max)
        sizes = [state_dim] + list(hidden) + [action_dim]
        acts = ["relu"] * len(hidden) + ["linear"]
        state = random.getstate()
        try:
            if seed is not None:
                random.seed(seed)
            self.mu_net = MLP(sizes, activations=acts)
            if seed is not None:
                random.seed(seed + 1)
            self.log_std_net = MLP(sizes, activations=acts)
        finally:
            random.setstate(state)
        self.sizes = sizes
        self._sample_cache = None

    def _check_state(self, state):
        if not isinstance(state, (list, tuple)) or len(state) != self.state_dim:
            raise ValueError(
                f"SquashedGaussianPolicy: state 长度必须是 {self.state_dim}")

    def forward(self, state):
        """返回 (mu, log_std)。"""
        self._check_state(state)
        sx = [float(v) for v in state]
        mu = self.mu_net.forward(sx)
        log_std = [min(self.log_std_max, max(self.log_std_min, v))
                   for v in self.log_std_net.forward(sx)]
        return mu, log_std

    def sample(self, state, seed=None):
        """重参数化采样，返回 (action, log_prob) 并缓存内部量供反向。"""
        mu, log_std = self.forward(state)
        rng = random.Random(seed) if seed is not None else random
        eps = [rng.gauss(0.0, 1.0) for _ in range(self.action_dim)]
        sigma = [math.exp(v) for v in log_std]
        z = [mu[i] + sigma[i] * eps[i] for i in range(self.action_dim)]
        t = [math.tanh(v) for v in z]
        action = [self.action_scale * v for v in t]
        log_prob = 0.0
        for i in range(self.action_dim):
            log_prob += (-0.5 * eps[i] * eps[i] - log_std[i]
                         - 0.5 * math.log(2.0 * math.pi))
            log_prob -= math.log(max(1e-12, 1.0 - t[i] * t[i]))
            log_prob -= math.log(self.action_scale)
        self._sample_cache = (mu, log_std, eps, sigma, z, t)
        return action, log_prob

    def log_prob(self, state, action):
        """给定动作的对数概率（把动作反 tanh）。"""
        self._check_state(state)
        if not isinstance(action, (list, tuple)) or len(action) != self.action_dim:
            raise ValueError(
                f"SquashedGaussianPolicy.log_prob: action 长度必须是 {self.action_dim}")
        mu, log_std = self.forward(state)
        sigma = [math.exp(v) for v in log_std]
        total = 0.0
        for i in range(self.action_dim):
            a = float(action[i]) / self.action_scale
            if not -1.0 < a < 1.0:
                a = min(1.0 - 1e-12, max(-1.0 + 1e-12, a))
            z = math.atanh(a)
            t = math.tanh(z)
            total += (-0.5 * ((z - mu[i]) / sigma[i]) ** 2
                      - log_std[i] - 0.5 * math.log(2.0 * math.pi))
            total -= math.log(max(1e-12, 1.0 - t * t))
            total -= math.log(self.action_scale)
        return total

    def deterministic_action(self, state):
        """均值动作（评估用）。"""
        mu, _log_std = self.forward(state)
        return [self.action_scale * math.tanh(v) for v in mu]

    def gradients(self, dmu, dlog_std):
        """把 dL/dmu、dL/dlog_std 反传到两个网络的参数。"""
        if self._sample_cache is None:
            raise RuntimeError(
                "SquashedGaussianPolicy.gradients: 必须先调用 sample()")
        if len(dmu) != self.action_dim or len(dlog_std) != self.action_dim:
            raise ValueError(
                "SquashedGaussianPolicy.gradients: 梯度长度必须是 action_dim")
        mu_grads = _mlp_backward(self.mu_net, [float(v) for v in dmu])
        std_grads = _mlp_backward(self.log_std_net, [float(v) for v in dlog_std])
        return mu_grads, std_grads

    def param_count(self):
        """可训练标量个数（两个 MLP 之和）。"""
        total = 0
        for net in (self.mu_net, self.log_std_net):
            total += sum(layer.fan_out * layer.fan_in + layer.fan_out
                         for layer in net.layers)
        return total

    def copy_from(self, other):
        """复制同形状策略的权重。"""
        if not isinstance(other, SquashedGaussianPolicy) or other.sizes != self.sizes:
            raise ValueError("SquashedGaussianPolicy.copy_from: 只接受同形状的网络")
        for dst, src in ((self.mu_net, other.mu_net),
                         (self.log_std_net, other.log_std_net)):
            for dl, sl in zip(dst.layers, src.layers):
                for j in range(len(dl.weights)):
                    dl.weights[j][:] = sl.weights[j]
                dl.biases[:] = sl.biases


class SACAgent:
    """SAC：随机 squashed-Gaussian actor + 双 Q critic + 熵正则（固定温度）。"""

    def __init__(self, state_dim, action_dim, hidden=(64, 64), actor_lr=3e-4,
                 critic_lr=3e-4, alpha=0.2, gamma=0.99, tau=0.005,
                 action_scale=1.0, buffer_capacity=10000, batch_size=32,
                 seed=None):
        for name, v in (("actor_lr", actor_lr), ("critic_lr", critic_lr)):
            if isinstance(v, bool) or not isinstance(v, (int, float)) or v <= 0.0:
                raise ValueError(f"SACAgent: {name} 必须 >0，收到 {v!r}")
        if isinstance(alpha, bool) or not isinstance(alpha, (int, float)) \
                or alpha < 0.0:
            raise ValueError(f"SACAgent: alpha 必须是非负数字，收到 {alpha!r}")
        if isinstance(gamma, bool) or not isinstance(gamma, (int, float)) \
                or not 0.0 <= gamma <= 1.0:
            raise ValueError(f"SACAgent: gamma 必须在 [0,1]，收到 {gamma!r}")
        if isinstance(tau, bool) or not isinstance(tau, (int, float)) \
                or not 0.0 < tau <= 1.0:
            raise ValueError(f"SACAgent: tau 必须在 (0,1]，收到 {tau!r}")
        if isinstance(batch_size, bool) or not isinstance(batch_size, int) \
                or batch_size < 1:
            raise ValueError(
                f"SACAgent: batch_size 必须是 >=1 的整数，收到 {batch_size!r}")
        self.state_dim = state_dim
        self.action_dim = action_dim
        self.alpha = float(alpha)
        self.gamma = float(gamma)
        self.tau = float(tau)
        self.batch_size = batch_size
        self.action_scale = float(action_scale)
        self.actor = SquashedGaussianPolicy(
            state_dim, action_dim, hidden, action_scale, seed=seed)
        self.critic1 = ContinuousQNetwork(state_dim, action_dim, hidden, seed=seed)
        self.critic2 = ContinuousQNetwork(state_dim, action_dim, hidden, seed=None)
        self.critic2.copy_from(self.critic1)
        self.target1 = ContinuousQNetwork(state_dim, action_dim, hidden, seed=None)
        self.target1.copy_from(self.critic1)
        self.target2 = ContinuousQNetwork(state_dim, action_dim, hidden, seed=None)
        self.target2.copy_from(self.critic1)
        self.actor_opt = Adam(self.actor.mu_net, lr=float(actor_lr))
        self.actor_std_opt = Adam(self.actor.log_std_net, lr=float(actor_lr))
        self.critic1_opt = Adam(self.critic1.model, lr=float(critic_lr))
        self.critic2_opt = Adam(self.critic2.model, lr=float(critic_lr))
        self.buffer = ContinuousReplayBuffer(buffer_capacity, seed=seed)
        self.rng = random.Random(seed)
        self.updates = 0

    def act(self, state, deterministic=False):
        """采样动作；deterministic=True 时用均值动作。"""
        if deterministic:
            return self.actor.deterministic_action(state)
        action, _logp = self.actor.sample(state, self.rng.randrange(1 << 30))
        return action

    def remember(self, state, action, reward, next_state, done):
        """写入经验。"""
        self.buffer.add(state, action, reward, next_state, done)

    def update(self, batch_size=None):
        """从回放池取一个 batch 更新双 critic 与 actor，返回损失字典。"""
        bs = self.batch_size if batch_size is None else batch_size
        states, actions, rewards, next_states, dones = self.buffer.sample(bs)
        inv = 1.0 / bs
        c1w = _mlp_zero_grads(self.critic1.model)
        c1b = _mlp_acc_bias(self.critic1.model)
        c2w = _mlp_zero_grads(self.critic2.model)
        c2b = _mlp_acc_bias(self.critic2.model)
        aw = _mlp_zero_grads(self.actor.mu_net)
        ab = _mlp_acc_bias(self.actor.mu_net)
        sw = _mlp_zero_grads(self.actor.log_std_net)
        sb = _mlp_acc_bias(self.actor.log_std_net)
        q_loss = 0.0
        actor_loss = 0.0
        for i in range(bs):
            if dones[i]:
                target = rewards[i]
            else:
                next_action, next_logp = self.actor.sample(
                    next_states[i], self.rng.randrange(1 << 30))
                q1t = self.target1.q(next_states[i], next_action)
                q2t = self.target2.q(next_states[i], next_action)
                target = rewards[i] + self.gamma * (
                    min(q1t, q2t) - self.alpha * next_logp)
            q1 = self.critic1.q(states[i], actions[i])
            q2 = self.critic2.q(states[i], actions[i])
            e1 = q1 - target
            e2 = q2 - target
            _q, g1, _ds, _da = self.critic1.q_grads(states[i], actions[i], e1)
            _q, g2, _ds, _da = self.critic2.q_grads(states[i], actions[i], e2)
            _mlp_accumulate(c1w, c1b, g1)
            _mlp_accumulate(c2w, c2b, g2)
            q_loss += e1 * e1 + e2 * e2

            act, logp = self.actor.sample(states[i], self.rng.randrange(1 << 30))
            qa1 = self.critic1.q(states[i], act)
            qa2 = self.critic2.q(states[i], act)
            _, _, _ds, da1 = self.critic1.q_grads(states[i], act, 1.0)
            _, _, _ds, da2 = self.critic2.q_grads(states[i], act, 1.0)
            daction = [-(da1[j] + da2[j]) * 0.5 * inv
                       for j in range(self.action_dim)]
            mu, log_std, eps, sigma, z, t = self.actor._sample_cache
            dmu = []
            dlog_std = []
            for j in range(self.action_dim):
                dz = (daction[j] * self.action_scale * (1.0 - t[j] * t[j])
                      + self.alpha * (-(z[j] - mu[j]) / (sigma[j] * sigma[j])
                                      + 2.0 * t[j]) * inv)
                dmu.append(dz)
                dlog_std.append(dz * eps[j] * sigma[j])
            mu_grads, std_grads = self.actor.gradients(dmu, dlog_std)
            _mlp_accumulate(aw, ab, mu_grads)
            _mlp_accumulate(sw, sb, std_grads)
            actor_loss += (self.alpha * logp - min(qa1, qa2))
        def _avg(w, b):
            return ([[[v * inv for v in row] for row in layer] for layer in w],
                    [[v * inv for v in row] for row in b])
        for opt, w, b in ((self.critic1_opt, c1w, c1b),
                          (self.critic2_opt, c2w, c2b),
                          (self.actor_opt, aw, ab),
                          (self.actor_std_opt, sw, sb)):
            aw2, ab2 = _avg(w, b)
            opt.step([(x, y) for x, y in zip(aw2, ab2)])
        _soft_update(self.target1, self.critic1, self.tau)
        _soft_update(self.target2, self.critic2, self.tau)
        self.updates += 1
        return {"critic_loss": q_loss * inv, "actor_loss": actor_loss * inv}

    def train(self, env, episodes=20, batch_size=None, max_steps=200,
              min_buffer=None):
        """在连续动作环境上训练，返回每回合回报。"""
        if not hasattr(env, "reset") or not hasattr(env, "step"):
            raise ValueError("SACAgent.train: env 必须提供 reset()/step()")
        if isinstance(episodes, bool) or not isinstance(episodes, int) \
                or episodes < 1:
            raise ValueError(
                f"SACAgent.train: episodes 必须是 >=1 的整数，收到 {episodes!r}")
        bs = self.batch_size if batch_size is None else batch_size
        need = max(bs, 1 if min_buffer is None else min_buffer)
        returns = []
        for _ in range(episodes):
            state = env.reset()
            total = 0.0
            steps = 0
            while True:
                action = self.act(state)
                out = env.step(action)
                if not isinstance(out, (list, tuple)) or len(out) != 4:
                    raise ValueError(
                        "SACAgent.train: env.step 必须返回 (next_state, reward, done, info)")
                next_state, reward, done, _info = out
                self.remember(state, action, reward, next_state, done)
                total += float(reward)
                state = next_state
                steps += 1
                if len(self.buffer) >= need:
                    self.update(bs)
                if done or (max_steps is not None and steps >= max_steps):
                    break
            returns.append(total)
        return returns

    def param_count(self):
        """actor + 双 critic 参数量。"""
        return (self.actor.param_count() + self.critic1.param_count()
                + self.critic2.param_count())


def _ssm_check_vec(name, value, rows, cols=None):
    """selective_scan 的形状校验：rows×[cols] 的数值表格。"""
    if not isinstance(value, (list, tuple)) or len(value) != rows:
        raise ValueError(
            f"selective_scan: {name} 必须是长度 {rows} 的列表")
    out = []
    for i, row in enumerate(value):
        if cols is None:
            if isinstance(row, bool) or not isinstance(row, (int, float)):
                raise ValueError(
                    f"selective_scan: {name}[{i}] 必须是数字")
            fv = float(row)
            if not math.isfinite(fv):
                raise ValueError(
                    f"selective_scan: {name}[{i}] 必须是有限数")
            out.append(fv)
            continue
        if not isinstance(row, (list, tuple)) or len(row) != cols:
            raise ValueError(
                f"selective_scan: {name}[{i}] 必须是长度 {cols} 的列表")
        vals = []
        for j, v in enumerate(row):
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(
                    f"selective_scan: {name}[{i}][{j}] 必须是数字")
            fv = float(v)
            if not math.isfinite(fv):
                raise ValueError(
                    f"selective_scan: {name}[{i}][{j}] 必须是有限数")
            vals.append(fv)
        out.append(vals)
    return out


def selective_scan(u, delta, A, B, C, D=None):
    """Mamba 的 S6 选择性扫描（对角 A），返回 (y, backward_handle)。

    u/delta: (T, d_in)；A: (d_in, d_state)；B/C: (T, d_state)；
    D: (d_in,) 或 None。递推：
        h_t = exp(delta_t * A) ⊙ h_{t-1} + delta_t * B_t ⊙ u_t
        y_t = C_t · h_t + D ⊙ u_t
    backward_handle(dy) 返回各输入梯度（含 du/ddelta/dA/dB/dC/dD）。
    """
    who = "selective_scan"
    if not isinstance(u, (list, tuple)) or not u:
        raise ValueError(f"{who}: u 必须是非空 (T, d_in) 列表")
    T = len(u)
    if not isinstance(u[0], (list, tuple)) or not u[0]:
        raise ValueError(f"{who}: u[0] 必须是非空列表")
    d_in = len(u[0])
    uu = _ssm_check_vec("u", u, T, d_in)
    dd = _ssm_check_vec("delta", delta, T, d_in)
    if not isinstance(A, (list, tuple)) or len(A) != d_in:
        raise ValueError(f"{who}: A 必须是 {d_in} 行的列表")
    aa = []
    d_state = None
    for i, row in enumerate(A):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"{who}: A[{i}] 必须是非空列表")
        if d_state is None:
            d_state = len(row)
        elif len(row) != d_state:
            raise ValueError(f"{who}: A 各行长度必须一致")
        vals = []
        for j, v in enumerate(row):
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f"{who}: A[{i}][{j}] 必须是数字")
            vals.append(float(v))
        aa.append(vals)
    bb = _ssm_check_vec("B", B, T, d_state)
    cc = _ssm_check_vec("C", C, T, d_state)
    if D is None:
        dvec = [0.0] * d_in
    else:
        dvec = _ssm_check_vec("D", D, d_in)
    h = [[0.0] * d_state for _ in range(d_in)]
    h_hist = []
    abar_hist = []
    bbar_hist = []
    y = []
    for t in range(T):
        abar = [[0.0] * d_state for _ in range(d_in)]
        bbar = [[0.0] * d_state for _ in range(d_in)]
        h_next = [[0.0] * d_state for _ in range(d_in)]
        uk = uu[t]
        dk = dd[t]
        for i in range(d_in):
            ui = uk[i]
            di = dk[i]
            hi = h[i]
            ai = aa[i]
            hni = h_next[i]
            for s in range(d_state):
                a = math.exp(di * ai[s])
                b = di * bb[t][s]
                abar[i][s] = a
                bbar[i][s] = b
                hni[s] = a * hi[s] + b * ui
        h = h_next
        h_hist.append(h)
        abar_hist.append(abar)
        bbar_hist.append(bbar)
        row = []
        for i in range(d_in):
            acc = dvec[i] * uk[i]
            for s in range(d_state):
                acc += cc[t][s] * h[i][s]
            row.append(acc)
        y.append(row)

    def backward_handle(dy):
        dyv = _ssm_check_vec("dy", dy, T, d_in)
        du = [[0.0] * d_in for _ in range(T)]
        ddelta = [[0.0] * d_in for _ in range(T)]
        dA = [[0.0] * d_state for _ in range(d_in)]
        dB = [[0.0] * d_state for _ in range(T)]
        dC = [[0.0] * d_state for _ in range(T)]
        dD = [0.0] * d_in
        dh_next = [[0.0] * d_state for _ in range(d_in)]
        for t in range(T - 1, -1, -1):
            dh = [[0.0] * d_state for _ in range(d_in)]
            for i in range(d_in):
                dyi = dyv[t][i]
                for s in range(d_state):
                    dh[i][s] = dyi * cc[t][s] + dh_next[i][s]
            ht = h_hist[t]
            for i in range(d_in):
                dyi = dyv[t][i]
                hti = ht[i]
                for s in range(d_state):
                    dC[t][s] += dyi * hti[s]
            for i in range(d_in):
                ui = uu[t][i]
                di = dd[t][i]
                for s in range(d_state):
                    dhi = dh[i][s]
                    du[t][i] += dhi * bbar_hist[t][i][s]
                    ddelta[t][i] += dhi * bb[t][s] * ui
                    if t > 0:
                        hm = h_hist[t - 1][i][s]
                        ddelta[t][i] += dhi * abar_hist[t][i][s] * aa[i][s] * hm
                        dA[i][s] += dhi * abar_hist[t][i][s] * di * hm
                    dB[t][s] += dhi * di * ui
                    dh_next[i][s] = dhi * abar_hist[t][i][s]
            for i in range(d_in):
                du[t][i] += dvec[i] * dyv[t][i]
                if D is not None:
                    dD[i] += dyv[t][i] * uu[t][i]
        return {"du": du, "ddelta": ddelta, "dA": dA, "dB": dB, "dC": dC, "dD": dD}

    return y, backward_handle


class MambaBlock:
    """Mamba 的选择性状态空间块（pre-norm 残差 + 选择性扫描）。

    结构：``in_proj`` → 拆成 x/z → 因果一维卷积 + SiLU → u；
    ``u`` → ``delta_proj`` + softplus、``b_proj``、``c_proj`` → ``selective_scan`` → y；
    ``out = x + out_proj(y ⊙ SiLU(z))``。

    边界：卷积用稠密 ``_CausalConv1d``（非 depthwise）；``A`` 直接作为参数（不做
    ``-exp(A_log)`` 参数化）；不实现硬件感知的并行扫描，时间维顺序递推。
    """

    def __init__(self, d_model, d_state=4, d_conv=4, expand=2, seed=None):
        if not isinstance(d_model, int) or isinstance(d_model, bool) or d_model < 1:
            raise ValueError(f"MambaBlock: d_model 必须是正整数，收到 {d_model!r}")
        if not isinstance(d_state, int) or isinstance(d_state, bool) or d_state < 1:
            raise ValueError(f"MambaBlock: d_state 必须是正整数，收到 {d_state!r}")
        if not isinstance(d_conv, int) or isinstance(d_conv, bool) or d_conv < 1:
            raise ValueError(f"MambaBlock: d_conv 必须是正整数，收到 {d_conv!r}")
        if not isinstance(expand, int) or isinstance(expand, bool) or expand < 1:
            raise ValueError(f"MambaBlock: expand 必须是正整数，收到 {expand!r}")
        self.d_model = d_model
        self.d_state = d_state
        self.d_conv = d_conv
        self.expand = expand
        self.d_inner = expand * d_model
        self.in_proj = Layer(d_model, 2 * self.d_inner, "linear")
        self.conv = _CausalConv1d(self.d_inner, self.d_inner, d_conv, dilation=1, seed=seed)
        self.delta_proj = Layer(self.d_inner, self.d_inner, "linear")
        self.b_proj = Layer(self.d_inner, d_state, "linear")
        self.c_proj = Layer(self.d_inner, d_state, "linear")
        self.A = [[-(1.0 + s) for s in range(d_state)] for _ in range(self.d_inner)]
        self.D = [1.0] * self.d_inner
        self.out_proj = Layer(self.d_inner, d_model, "linear")
        self._cache = None
        self.zero_grad()

    def zero_grad(self):
        self.grads = {}
        for name in ("in_proj", "delta_proj", "b_proj", "c_proj", "out_proj"):
            self.grads[name] = _layer_zero_grads(getattr(self, name))
        self.conv.zero_grad()
        self.grad_A = [[0.0] * self.d_state for _ in range(self.d_inner)]
        self.grad_D = [0.0] * self.d_inner

    def forward(self, x):
        if not isinstance(x, (list, tuple)) or not x:
            raise ValueError("MambaBlock.forward: 输入必须是非空 (T, d_model) 序列")
        for t, row in enumerate(x):
            if not isinstance(row, (list, tuple)) or len(row) != self.d_model:
                raise ValueError(
                    f"MambaBlock.forward: 第 {t} 行长度应为 {self.d_model}")
        T = len(x)
        proj, cache_in = _dense_rows_forward(self.in_proj, x)
        xs = [row[:self.d_inner] for row in proj]
        zs = [row[self.d_inner:] for row in proj]
        conv_out = self.conv.forward(xs)
        us = [[_silu_scalar(v) for v in row] for row in conv_out]
        delta_pre, cache_delta = _dense_rows_forward(self.delta_proj, us)
        deltas = [[_softplus_scalar(v) for v in row] for row in delta_pre]
        B, cache_b = _dense_rows_forward(self.b_proj, us)
        C, cache_c = _dense_rows_forward(self.c_proj, us)
        ys, scan_back = selective_scan(us, deltas, self.A, B, C, self.D)
        gz = [[_silu_scalar(v) for v in row] for row in zs]
        gated = [[ys[t][i] * gz[t][i] for i in range(self.d_inner)] for t in range(T)]
        projected, cache_out = _dense_rows_forward(self.out_proj, gated)
        out = [[x[t][i] + projected[t][i] for i in range(self.d_model)] for t in range(T)]
        self._cache = (T, x, cache_in, zs, conv_out, us, delta_pre, cache_delta,
                       cache_b, cache_c, ys, gz, gated, cache_out, scan_back)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("MambaBlock.backward: 必须先调用 forward()")
        (T, x, cache_in, zs, conv_out, us, delta_pre, cache_delta,
         cache_b, cache_c, ys, gz, gated, cache_out, scan_back) = self._cache
        if len(dout) != T:
            raise ValueError(f"MambaBlock.backward: dout 长度 {len(dout)} 应为 {T}")
        for t, row in enumerate(dout):
            if len(row) != self.d_model:
                raise ValueError(
                    f"MambaBlock.backward: 第 {t} 行梯度长度 {len(row)} 应为 {self.d_model}")
        grad_w, grad_b, dgated = _dense_rows_backward(self.out_proj, cache_out, dout)
        _layer_add_grads(self.grads["out_proj"], (grad_w, grad_b))
        dy = [[dgated[t][i] * gz[t][i] for i in range(self.d_inner)] for t in range(T)]
        dz = [[dgated[t][i] * ys[t][i] * _dsilu_scalar(zs[t][i])
               for i in range(self.d_inner)] for t in range(T)]
        sgrads = scan_back(dy)
        for i in range(self.d_inner):
            for s in range(self.d_state):
                self.grad_A[i][s] += sgrads["dA"][i][s]
            self.grad_D[i] += sgrads["dD"][i]
        ddelta_pre = []
        for t in range(T):
            row = []
            for i in range(self.d_inner):
                z = delta_pre[t][i]
                sig = 1.0 if z > 30.0 else 1.0 / (1.0 + math.exp(-z))
                row.append(sgrads["ddelta"][t][i] * sig)
            ddelta_pre.append(row)
        grad_w, grad_b, du_delta = _dense_rows_backward(
            self.delta_proj, cache_delta, ddelta_pre)
        _layer_add_grads(self.grads["delta_proj"], (grad_w, grad_b))
        grad_w, grad_b, du_b = _dense_rows_backward(self.b_proj, cache_b, sgrads["dB"])
        _layer_add_grads(self.grads["b_proj"], (grad_w, grad_b))
        grad_w, grad_b, du_c = _dense_rows_backward(self.c_proj, cache_c, sgrads["dC"])
        _layer_add_grads(self.grads["c_proj"], (grad_w, grad_b))
        du = [[sgrads["du"][t][i] + du_delta[t][i] + du_b[t][i] + du_c[t][i]
               for i in range(self.d_inner)] for t in range(T)]
        dconv = [[du[t][i] * _dsilu_scalar(conv_out[t][i])
                  for i in range(self.d_inner)] for t in range(T)]
        dxs = self.conv.backward(dconv)
        dproj = [dxs[t] + dz[t] for t in range(T)]
        grad_w, grad_b, dx = _dense_rows_backward(self.in_proj, cache_in, dproj)
        _layer_add_grads(self.grads["in_proj"], (grad_w, grad_b))
        self._cache = None
        return dx

    def param_count(self):
        count = sum(_dense_param_count(getattr(self, name))
                    for name in ("in_proj", "delta_proj", "b_proj", "c_proj", "out_proj"))
        count += (len(self.conv.weights) * len(self.conv.weights[0]) * self.d_conv
                  + len(self.conv.biases))
        count += self.d_inner * self.d_state + self.d_inner
        return count

    def sgd_step(self, lr):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"MambaBlock.sgd_step: lr 必须是非负数，收到 {lr!r}")
        for name in ("in_proj", "delta_proj", "b_proj", "c_proj", "out_proj"):
            _dense_apply_sgd(getattr(self, name), self.grads[name], lr)
        for oc in range(self.conv.out_channels):
            wrow = self.conv.weights[oc]
            grow = self.conv.grad_w[oc]
            for ic in range(self.conv.in_channels):
                for kk in range(self.conv.kernel_size):
                    wrow[ic][kk] -= lr * grow[ic][kk]
            self.conv.biases[oc] -= lr * self.conv.grad_b[oc]
        for i in range(self.d_inner):
            for s in range(self.d_state):
                self.A[i][s] -= lr * self.grad_A[i][s]
            self.D[i] -= lr * self.grad_D[i]

    def train(self):
        return self

    def eval(self):
        return self


class MambaModel:
    """字符级 Mamba 语言模型：Embedding → N×MambaBlock → 线性 LM 头。"""

    def __init__(self, vocab_size, d_model=32, d_state=4, d_conv=4, expand=2,
                 num_layers=2, max_len=64, seed=None):
        if not isinstance(vocab_size, int) or isinstance(vocab_size, bool) or vocab_size < 1:
            raise ValueError(f"MambaModel: vocab_size 必须是正整数，收到 {vocab_size!r}")
        if not isinstance(num_layers, int) or isinstance(num_layers, bool) or num_layers < 1:
            raise ValueError(f"MambaModel: num_layers 必须是正整数，收到 {num_layers!r}")
        if not isinstance(max_len, int) or isinstance(max_len, bool) or max_len < 1:
            raise ValueError(f"MambaModel: max_len 必须是正整数，收到 {max_len!r}")
        self.vocab_size = vocab_size
        self.d_model = d_model
        self.max_len = max_len
        self.embedding = Embedding(vocab_size, d_model)
        self.blocks = [MambaBlock(d_model, d_state, d_conv, expand, seed=seed)
                       for _ in range(num_layers)]
        self.head = Layer(d_model, vocab_size, "linear")
        self.grads = {"head": _layer_zero_grads(self.head)}

    def zero_grad(self):
        self.embedding.zero_grad()
        for block in self.blocks:
            block.zero_grad()
        self.grads["head"] = _layer_zero_grads(self.head)

    def _check_ids(self, ids, who):
        seq = list(ids)
        if not seq:
            raise ValueError(f"{who}: ids 不能为空")
        if len(seq) > self.max_len:
            raise ValueError(f"{who}: 序列长度 {len(seq)} 超过 max_len={self.max_len}")
        for t, idx in enumerate(seq):
            if not isinstance(idx, int) or isinstance(idx, bool) or not 0 <= idx < self.vocab_size:
                raise ValueError(f"{who}: 第 {t} 个 id {idx!r} 越界")
        return seq

    def forward(self, ids):
        seq = self._check_ids(ids, "MambaModel.forward")
        x = self.embedding.forward(seq)
        for block in self.blocks:
            x = block.forward(x)
        self._head_in = x
        logits, self._head_cache = _dense_rows_forward(self.head, x)
        return logits

    def loss_and_backward(self, ids, targets=None):
        seq = list(ids)
        if len(seq) < 2:
            raise ValueError("MambaModel.loss_and_backward: 序列至少需要 2 个 token")
        if targets is None:
            tgt = seq[1:]
        else:
            tgt = list(targets)
            if len(tgt) != len(seq) - 1:
                raise ValueError(
                    f"MambaModel.loss_and_backward: targets 长度 {len(tgt)} 应为 {len(seq) - 1}")
        logits = self.forward(seq)
        T = len(seq)
        n = T - 1
        V = self.vocab_size
        loss = 0.0
        dlogits = [[0.0] * V for _ in range(T)]
        for t in range(n):
            y = tgt[t]
            if not isinstance(y, int) or isinstance(y, bool) or not 0 <= y < V:
                raise ValueError(f"MambaModel.loss_and_backward: 第 {t} 个 target {y!r} 越界")
            p = _softmax_row(logits[t])
            loss -= math.log(max(p[y], 1e-12))
            scale = 1.0 / n
            row = dlogits[t]
            for v in range(V):
                row[v] = (p[v] - (1.0 if v == y else 0.0)) * scale
        loss /= n
        grad_w, grad_b, dh = _dense_rows_backward(self.head, self._head_cache, dlogits)
        _layer_add_grads(self.grads["head"], (grad_w, grad_b))
        for block in reversed(self.blocks):
            dh = block.backward(dh)
        self.embedding.backward(dh)
        return loss

    def sgd_step(self, lr):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"MambaModel.sgd_step: lr 必须是非负数，收到 {lr!r}")
        self.embedding.sgd_step(lr)
        for block in self.blocks:
            block.sgd_step(lr)
        _dense_apply_sgd(self.head, self.grads["head"], lr)

    def param_count(self):
        return (self.vocab_size * self.d_model
                + sum(block.param_count() for block in self.blocks)
                + _dense_param_count(self.head))

    def fit(self, sequences, epochs=1, lr=3e-3, shuffle=True, seed=None, verbose=False):
        if not sequences:
            raise ValueError("MambaModel.fit: sequences 不能为空")
        if not isinstance(epochs, int) or isinstance(epochs, bool) or epochs < 1:
            raise ValueError(f"MambaModel.fit: epochs 必须是正整数，收到 {epochs!r}")
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"MambaModel.fit: lr 必须是非负数，收到 {lr!r}")
        rng = random.Random(seed)
        order = list(range(len(sequences)))
        losses = []
        for epoch in range(epochs):
            if shuffle:
                rng.shuffle(order)
            total = 0.0
            for idx in order:
                self.zero_grad()
                total += self.loss_and_backward(sequences[idx])
                self.sgd_step(lr)
            losses.append(total / len(sequences))
            if verbose:
                print(f"  epoch {epoch + 1}/{epochs} loss={losses[-1]:.6f}")
        return losses

    def generate(self, prompt_ids, max_new_tokens=16, temperature=1.0, top_k=None, seed=None):
        if not isinstance(max_new_tokens, int) or isinstance(max_new_tokens, bool) or max_new_tokens < 0:
            raise ValueError(
                f"MambaModel.generate: max_new_tokens 必须是非负整数，收到 {max_new_tokens!r}")
        if (not isinstance(temperature, (int, float)) or isinstance(temperature, bool)
                or not math.isfinite(temperature) or temperature <= 0):
            raise ValueError(
                f"MambaModel.generate: temperature 必须是正有限数，收到 {temperature!r}")
        rng = random.Random(seed)
        out = self._check_ids(prompt_ids, "MambaModel.generate")
        for _ in range(max_new_tokens):
            ctx = out[-self.max_len:]
            logits = self.forward(ctx)[-1]
            row = [v / temperature for v in logits]
            if top_k is not None:
                if not isinstance(top_k, int) or isinstance(top_k, bool) or top_k < 1:
                    raise ValueError(
                        f"MambaModel.generate: top_k 必须是正整数，收到 {top_k!r}")
                k = min(top_k, len(row))
                order = sorted(range(len(row)), key=lambda j: (-row[j], j))[:k]
                keep = set(order)
                row = [v if j in keep else float("-inf") for j, v in enumerate(row)]
            probs = _softmax_row(row)
            r = rng.random()
            acc = 0.0
            pick = len(probs) - 1
            for j, p in enumerate(probs):
                acc += p
                if r <= acc:
                    pick = j
                    break
            out.append(pick)
        return out

    def train(self):
        return self

    def eval(self):
        return self


class NeuralODE:
    """神经 ODE（Euler 积分 + 离散反向）。

    学习向量场 ``f(t, y)``：``y_{n+1} = y_n + h * f(t_n, y_n)``，只对最终状态做监督。
    反向是「先离散步、再按步反传」的精确链式（不是连续伴随法），因此边界：
    只支持 Euler 积分器、只对终态监督、不估计连续伴随的数值误差。
    """

    def __init__(self, data_dim, hidden_dim=32, t_dim=8, steps=16):
        for name, value in (("data_dim", data_dim), ("hidden_dim", hidden_dim),
                            ("t_dim", t_dim), ("steps", steps)):
            if isinstance(value, bool) or not isinstance(value, int) or value < 1:
                raise ValueError(f"NeuralODE: {name} 必须是 >= 1 的整数，收到 {value!r}")
        self.data_dim = data_dim
        self.hidden_dim = hidden_dim
        self.t_dim = t_dim if t_dim % 2 == 0 else t_dim + 1
        self.steps = steps
        self.l1 = Layer(data_dim + self.t_dim, hidden_dim, activation="relu")
        self.l2 = Layer(hidden_dim, hidden_dim, activation="relu")
        self.l3 = Layer(hidden_dim, data_dim, activation="linear")
        self.layers = [self.l1, self.l2, self.l3]
        self.zero_grad()

    def zero_grad(self):
        self._g = [None] * len(self.layers)

    def _acc(self, i, gw, gb):
        if self._g[i] is None:
            self._g[i] = [gw, gb]
            return
        cur_w, cur_b = self._g[i]
        for r in range(len(cur_w)):
            for c in range(len(cur_w[r])):
                cur_w[r][c] += gw[r][c]
        for k in range(len(cur_b)):
            cur_b[k] += gb[k]

    def param_count(self):
        return sum(_dense_param_count(layer) for layer in self.layers)

    def _field(self, y, t):
        feats = _flow_time_features(t, self.t_dim)
        rows = [list(y) + feats]
        caches = []
        row = rows[0]
        for layer in self.layers:
            out, cache = _dense_rows_forward(layer, [row])
            caches.append(cache)
            row = out[0]
        return row, caches

    def integrate(self, y0, t0, t1, steps=None):
        if steps is None:
            steps = self.steps
        if isinstance(steps, bool) or not isinstance(steps, int) or steps < 1:
            raise ValueError(f"NeuralODE.integrate: steps 必须是 >= 1 的整数，收到 {steps!r}")
        if not isinstance(y0, (list, tuple)) or len(y0) != self.data_dim:
            raise ValueError(f"NeuralODE.integrate: y0 长度必须为 {self.data_dim}")
        for value in (t0, t1):
            if (not isinstance(value, (int, float)) or isinstance(value, bool)
                    or not math.isfinite(value)):
                raise ValueError(f"NeuralODE.integrate: t0/t1 必须是有限数，收到 {value!r}")
        if t1 <= t0:
            raise ValueError(f"NeuralODE.integrate: 需要 t1 > t0，收到 {t0!r} -> {t1!r}")
        h = (t1 - t0) / steps
        y = [float(v) for v in y0]
        traj = [list(y)]
        for n in range(steps):
            t = t0 + n * h
            f, _ = self._field(y, t)
            y = [y[j] + h * f[j] for j in range(self.data_dim)]
            traj.append(list(y))
        return y, traj

    def loss_and_backward(self, y0, t0, t1, target, steps=None):
        if steps is None:
            steps = self.steps
        if isinstance(steps, bool) or not isinstance(steps, int) or steps < 1:
            raise ValueError(
                f"NeuralODE.loss_and_backward: steps 必须是 >= 1 的整数，收到 {steps!r}")
        if not isinstance(target, (list, tuple)) or len(target) != self.data_dim:
            raise ValueError(
                f"NeuralODE.loss_and_backward: target 长度必须为 {self.data_dim}")
        h = (t1 - t0) / steps
        y = [float(v) for v in y0]
        fs = []
        caches_all = []
        for n in range(steps):
            t = t0 + n * h
            f, caches = self._field(y, t)
            fs.append(f)
            caches_all.append(caches)
            y = [y[j] + h * f[j] for j in range(self.data_dim)]
        diff = [y[j] - target[j] for j in range(self.data_dim)]
        loss = sum(v * v for v in diff) / self.data_dim
        dy = [2.0 * diff[j] / self.data_dim for j in range(self.data_dim)]
        for n in range(steps - 1, -1, -1):
            d_f = [h * dy[j] for j in range(self.data_dim)]
            d = d_f
            caches = caches_all[n]
            for li in range(len(self.layers) - 1, -1, -1):
                gw, gb, dx = _dense_rows_backward(self.layers[li], caches[li], [d])
                self._acc(li, gw, gb)
                d = dx[0]
            dy = [dy[j] + d[j] for j in range(self.data_dim)]
        return loss

    def sgd_step(self, lr):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"NeuralODE.sgd_step: lr 必须是非负数，收到 {lr!r}")
        for i, layer in enumerate(self.layers):
            _dense_apply_sgd(layer, self._g[i], lr)

    def fit(self, pairs, t0, t1, epochs=100, lr=1e-2, shuffle=True, seed=None, verbose=False):
        if not pairs:
            raise ValueError("NeuralODE.fit: pairs 不能为空")
        rng = random.Random(seed)
        order = list(range(len(pairs)))
        losses = []
        for epoch in range(epochs):
            if shuffle:
                rng.shuffle(order)
            total = 0.0
            for idx in order:
                y0, y1 = pairs[idx]
                self.zero_grad()
                total += self.loss_and_backward(y0, t0, t1, y1)
                self.sgd_step(lr)
            losses.append(total / len(pairs))
            if verbose:
                print(f"  epoch {epoch + 1}/{epochs} loss={losses[-1]:.6f}")
        return losses


class PINN1D:
    """一维稳态 Poisson 方程的物理信息网络：``u''(x) = f(x)``，边界 u(0)=u(1)=0。

    用试函数 ``u(x) = x(1-x)·NN(x)`` 把边界条件严格吸收进网络输出（无需边界损失），
    二阶导用中心差分近似。训练损失 = 内部采样点残差平方均值：
    ``res = (u(x+h)-2u(x)+u(x-h))/h² - f(x)``。
    边界：只支持一维、零边界、有限差分近似二阶导（非自动微分）。
    """

    def __init__(self, hidden_dim=16, seed=None):
        if isinstance(hidden_dim, bool) or not isinstance(hidden_dim, int) or hidden_dim < 1:
            raise ValueError(f"PINN1D: hidden_dim 必须是 >= 1 的整数，收到 {hidden_dim!r}")
        if seed is not None:
            _old = random.getstate()
            random.seed(seed)
        self.l1 = Layer(1, hidden_dim, activation="silu")
        self.l2 = Layer(hidden_dim, hidden_dim, activation="silu")
        self.l3 = Layer(hidden_dim, 1, activation="linear")
        self.layers = [self.l1, self.l2, self.l3]
        if seed is not None:
            random.setstate(_old)
        self.zero_grad()

    def zero_grad(self):
        self._g = [None] * len(self.layers)

    def _acc(self, i, gw, gb):
        if self._g[i] is None:
            self._g[i] = [gw, gb]
            return
        cur_w, cur_b = self._g[i]
        for r in range(len(cur_w)):
            for c in range(len(cur_w[r])):
                cur_w[r][c] += gw[r][c]
        for k in range(len(cur_b)):
            cur_b[k] += gb[k]

    def param_count(self):
        return sum(_dense_param_count(layer) for layer in self.layers)

    @staticmethod
    def _trial_factor(x):
        return x * (1.0 - x)

    def _raw(self, x):
        row = [float(x)]
        caches = []
        for layer in self.layers:
            out, cache = _dense_rows_forward(layer, [row])
            caches.append(cache)
            row = out[0]
        return row[0], caches

    def _u(self, x):
        raw, caches = self._raw(x)
        return self._trial_factor(x) * raw, caches

    def _backprop_raw(self, caches, dout):
        d = [dout]
        for li in range(len(self.layers) - 1, -1, -1):
            gw, gb, dx = _dense_rows_backward(self.layers[li], caches[li], [d])
            self._acc(li, gw, gb)
            d = dx[0]

    def predict(self, x):
        return self._u(x)[0]

    def loss_and_backward(self, points, f_values, h=1e-3):
        if not points or len(points) != len(f_values):
            raise ValueError("PINN1D: points 与 f_values 必须等长且非空")
        if (not isinstance(h, (int, float)) or isinstance(h, bool)
                or not math.isfinite(h) or h <= 0):
            raise ValueError(f"PINN1D.loss_and_backward: h 必须是正有限数，收到 {h!r}")
        n = len(points)
        loss = 0.0
        plans = []
        for x, f in zip(points, f_values):
            if (not isinstance(x, (int, float)) or isinstance(x, bool)
                    or not math.isfinite(x) or not 0.0 < x < 1.0):
                raise ValueError(f"PINN1D.loss_and_backward: 采样点 x 必须在 (0,1) 内，收到 {x!r}")
            x = float(x)
            fm = self._trial_factor(x - h)
            f0 = self._trial_factor(x)
            fp = self._trial_factor(x + h)
            um, cm = self._raw(x - h)
            u0, c0 = self._raw(x)
            up, cp = self._raw(x + h)
            um *= fm
            u0 *= f0
            up *= fp
            res = (up - 2.0 * u0 + um) / (h * h) - float(f)
            loss += res * res / n
            coef = 2.0 * res / n / (h * h)
            plans.append((cm, coef * fm))
            plans.append((c0, -2.0 * coef * f0))
            plans.append((cp, coef * fp))
        for caches, coef in plans:
            self._backprop_raw(caches, coef)
        return loss

    def sgd_step(self, lr):
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"PINN1D.sgd_step: lr 必须是非负数，收到 {lr!r}")
        for i, layer in enumerate(self.layers):
            _dense_apply_sgd(layer, self._g[i], lr)

    def fit(self, points, f_values, epochs=300, lr=1e-2, shuffle=False, seed=None,
            verbose=False):
        rng = random.Random(seed)
        idxs = list(range(len(points)))
        losses = []
        for epoch in range(epochs):
            self.zero_grad()
            loss = self.loss_and_backward(points, f_values)
            self.sgd_step(lr)
            losses.append(loss)
            if verbose and (epoch + 1) % 50 == 0:
                print(f"  epoch {epoch + 1}/{epochs} loss={loss:.6e}")
        return losses


def _parallel_check_flat(values, who):
    if not isinstance(values, (list, tuple)) or not values:
        raise ValueError(f"{who}: 需要一个非空的一维数值列表")
    out = []
    for v in values:
        if isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v):
            raise ValueError(f"{who}: 只支持有限数值，收到 {v!r}")
        out.append(float(v))
    return out


def _parallel_check_world(world_size, who):
    if isinstance(world_size, bool) or not isinstance(world_size, int) or world_size < 1:
        raise ValueError(f"{who}: world_size 必须是 >= 1 的整数，收到 {world_size!r}")
    return world_size


def _split_ranges(n, world_size, who):
    if not isinstance(n, int) or isinstance(n, bool) or n < 0:
        raise ValueError(f"{who}: n 必须是非负整数，收到 {n!r}")
    world_size = _parallel_check_world(world_size, who)
    base = n // world_size
    rem = n % world_size
    ranges = []
    start = 0
    for rank in range(world_size):
        size = base + (1 if rank < rem else 0)
        ranges.append((start, start + size))
        start += size
    return ranges


def fsdp_shard_flat(flat, world_size):
    """把扁平参数/梯度列表按 rank 切成 world_size 个连续分片（模拟 FSDP 分片）。"""
    flat = _parallel_check_flat(flat, "fsdp_shard_flat")
    ranges = _split_ranges(len(flat), world_size, "fsdp_shard_flat")
    return [(start, end, flat[start:end]) for start, end in ranges]


def fsdp_all_gather(shards):
    """把 fsdp_shard_flat 的分片按 rank 顺序拼回完整扁平参数。"""
    if not shards:
        raise ValueError("fsdp_all_gather: shards 不能为空")
    ordered = sorted(shards, key=lambda item: item[0])
    out = []
    expect = 0
    for start, end, values in ordered:
        if not isinstance(start, int) or not isinstance(end, int) or start != expect or end < start:
            raise ValueError("fsdp_all_gather: 分片区间必须从 0 起连续且不重叠")
        if len(values) != end - start:
            raise ValueError("fsdp_all_gather: 分片长度与区间不一致")
        out.extend(values)
        expect = end
    return out


def zero_optimizer_step(flat_params, flat_grads, lr, world_size):
    """模拟 ZeRO-1/SGD：每个 rank 只对自己参数分片做更新，再 all-gather。

    返回 (new_flat_params, shard_updates)，shard_updates 为每 rank 更新过的区间。
    """
    params = _parallel_check_flat(flat_params, "zero_optimizer_step")
    grads = _parallel_check_flat(flat_grads, "zero_optimizer_step")
    if len(params) != len(grads):
        raise ValueError("zero_optimizer_step: flat_params 与 flat_grads 长度必须一致")
    if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
        raise ValueError(f"zero_optimizer_step: lr 必须是非负数，收到 {lr!r}")
    world_size = _parallel_check_world(world_size, "zero_optimizer_step")
    shards = fsdp_shard_flat(params, world_size)
    updated = list(params)
    updates = []
    for start, end, values in shards:
        for i in range(start, end):
            updated[i] = values[i - start] - lr * grads[i]
        updates.append((start, end))
    return fsdp_all_gather([(s, e, updated[s:e]) for s, e, _ in shards]), updates


def fsdp_reduce_scatter(rank_grads, world_size):
    """模拟 FSDP 的 reduce-scatter：各 rank 先对完整梯度求平均，再按住分片。

    rank_grads 是每个 rank 的完整梯度列表（形状相同）；返回每 rank 的平均梯度分片。
    """
    if not isinstance(rank_grads, (list, tuple)) or not rank_grads:
        raise ValueError("fsdp_reduce_scatter: rank_grads 不能为空")
    world_size = _parallel_check_world(world_size, "fsdp_reduce_scatter")
    if len(rank_grads) != world_size:
        raise ValueError("fsdp_reduce_scatter: rank_grads 的数量必须等于 world_size")
    n = len(rank_grads[0])
    for g in rank_grads:
        if len(g) != n:
            raise ValueError("fsdp_reduce_scatter: 每个 rank 的梯度长度必须一致")
    avg = [sum(g[i] for g in rank_grads) / world_size for i in range(n)]
    shards = fsdp_shard_flat(avg, world_size)
    return [(start, end, [avg[i] for i in range(start, end)]) for start, end, _ in shards]


def tensor_parallel_linear_forward(weight, bias, x, world_size, mode="column"):
    """模拟 Megatron 式张量并行线性层（不做反向，只对照前向数值）。

    mode="column"：按输出维度切权重行/bias，各 rank 算一段输出再拼回；
    mode="row"：按输入维度切权重列与 x，各 rank 算部分和，再相加（bias 只加一次）。
    返回 (full_output, shard_outputs)。
    """
    if not isinstance(weight, (list, tuple)) or not weight:
        raise ValueError("tensor_parallel_linear_forward: weight 不能为空")
    rows = len(weight)
    cols = len(weight[0])
    if any((not isinstance(r, (list, tuple)) or len(r) != cols) for r in weight):
        raise ValueError("tensor_parallel_linear_forward: weight 必须是矩形矩阵")
    if not isinstance(x, (list, tuple)) or len(x) != cols:
        raise ValueError("tensor_parallel_linear_forward: x 的长度必须等于 weight 列数")
    if bias is not None and len(bias) != rows:
        raise ValueError("tensor_parallel_linear_forward: bias 长度必须等于 weight 行数")
    world_size = _parallel_check_world(world_size, "tensor_parallel_linear_forward")
    if mode == "column":
        ranges = _split_ranges(rows, world_size, "tensor_parallel_linear_forward")
        outs = []
        full = []
        for start, end in ranges:
            y = []
            for r in range(start, end):
                acc = sum(weight[r][c] * x[c] for c in range(cols))
                if bias is not None:
                    acc += bias[r]
                y.append(acc)
            outs.append(y)
            full.extend(y)
        return full, outs
    if mode == "row":
        ranges = _split_ranges(cols, world_size, "tensor_parallel_linear_forward")
        partials = []
        for start, end in ranges:
            yshard = [0.0] * rows
            for c in range(start, end):
                xc = x[c]
                for r in range(rows):
                    yshard[r] += weight[r][c] * xc
            partials.append(yshard)
        full = [sum(p[r] for p in partials) for r in range(rows)]
        if bias is not None:
            full = [full[r] + bias[r] for r in range(rows)]
        return full, partials
    raise ValueError(f"tensor_parallel_linear_forward: mode 只支持 'column'/'row'，收到 {mode!r}")


def sequence_parallel_layer_norm(x_seq, eps=1e-5):
    """模拟序列并行下的 LayerNorm：token 沿序列维切给各 rank，逐 token 归一化后再拼回。"""
    if not isinstance(x_seq, (list, tuple)) or not x_seq:
        raise ValueError("sequence_parallel_layer_norm: x_seq 不能为空")
    if (not isinstance(eps, (int, float)) or isinstance(eps, bool)
            or not math.isfinite(eps) or eps <= 0):
        raise ValueError(f"sequence_parallel_layer_norm: eps 必须是正有限数，收到 {eps!r}")
    full = []
    for row in x_seq:
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError("sequence_parallel_layer_norm: 每行 token 必须是非空向量")
        mu = sum(row) / len(row)
        var = sum((v - mu) ** 2 for v in row) / len(row)
        denom = math.sqrt(var + eps)
        full.append([(v - mu) / denom for v in row])
    return full


# ============================================================================
# ============================================================================
#  ELECTRA：生成器 + 判别器的预训练框架
# ============================================================================


class ElectraDiscriminator:
    """ELECTRA 判别器：双向 Transformer 编码 + 逐位置二分类头

    判别器逐位置判断「这个 token 是否被生成器破坏」。
    与 `MaskedLM` 的差别：输出不是词表分布，而是每个位置一个 logit
    （1 表示被替换/被遮罩，0 表示原样）。
    """

    def __init__(self, vocab_size, d_model=32, num_heads=4, d_ff=64,
                 num_layers=2, max_len=32, seed=None):
        if not isinstance(vocab_size, int) or isinstance(vocab_size, bool) or vocab_size < 1:
            raise ValueError(
                f"ElectraDiscriminator: vocab_size 必须是正整数，收到 {vocab_size!r}")
        if not isinstance(d_model, int) or isinstance(d_model, bool) or d_model < 1:
            raise ValueError(
                f"ElectraDiscriminator: d_model 必须是正整数，收到 {d_model!r}")
        if not isinstance(num_heads, int) or isinstance(num_heads, bool) or num_heads < 1:
            raise ValueError(
                f"ElectraDiscriminator: num_heads 必须是正整数，收到 {num_heads!r}")
        if d_model % num_heads != 0:
            raise ValueError(
                f"ElectraDiscriminator: d_model={d_model} 必须能被 num_heads={num_heads} 整除")
        if not isinstance(max_len, int) or isinstance(max_len, bool) or max_len < 1:
            raise ValueError(
                f"ElectraDiscriminator: max_len 必须 >= 1，收到 {max_len!r}")

        self.vocab_size = vocab_size
        self.d_model = d_model
        self.d_ff = d_ff
        self.num_layers = num_layers
        self.max_len = max_len
        self.num_heads = num_heads

        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.embedding = Embedding(vocab_size + 1, d_model)
            std = math.sqrt(2.0 / d_model)
            self.W_d = [[random.gauss(0.0, std) for _ in range(d_model)]
                        for _ in range(2)]
        finally:
            random.setstate(state)

        self.pos = PositionalEncoding(d_model, max_len)
        self.encoder = TransformerEncoder(d_model, num_heads, d_ff, num_layers,
                                          0.0, causal=False)
        self.b_d = [0.0, 0.0]

        self.zero_grad()
        self.h = None
        self.score = None

    def zero_grad(self):
        """清零 embedding / 编码器 / 分类头的梯度"""
        self.embedding.zero_grad()
        self.encoder.zero_grad()
        self.grad_W_d = [[0.0] * self.d_model for _ in range(2)]
        self.grad_b_d = [0.0, 0.0]

    def train(self):
        """训练模式（Dropout 生效，转发给编码器）"""
        self.encoder.train()
        return self

    def eval(self):
        """推理模式（关闭 Dropout）"""
        self.encoder.eval()
        return self

    def forward(self, ids):
        """ids: List[int] → score (T,)（越大越像「被破坏的位置」）"""
        if not isinstance(ids, (list, tuple)) or not ids:
            raise ValueError("ElectraDiscriminator.forward: ids 不能为空")
        ids = _check_token_ids(ids, self.vocab_size + 1, "ElectraDiscriminator.forward")
        if len(ids) > self.max_len:
            raise ValueError(
                f"ElectraDiscriminator.forward: 序列长度 {len(ids)} 超过 max_len={self.max_len}")
        emb = self.embedding.forward(ids)
        x = self.pos.forward(emb)
        h = self.encoder.forward(x)
        self.h = h
        T = len(h)
        score = []
        for t in range(T):
            s = self.b_d[1] - self.b_d[0]
            for j in range(self.d_model):
                s += (self.W_d[1][j] - self.W_d[0][j]) * h[t][j]
            score.append(s)
        self.score = score
        return score

    def probabilities(self, ids):
        """逐位置「被破坏」概率（sigmoid）"""
        score = self.forward(ids)
        return [_sigmoid(v) for v in score]

    def bce_loss_and_backward(self, ids, labels, grad_scale=1.0):
        """逐位置二分类 BCE（logit 形式），反传并累积梯度，返回平均 loss"""
        if not isinstance(labels, (list, tuple)) or not labels:
            raise ValueError("ElectraDiscriminator.bce_loss_and_backward: labels 不能为空")
        if len(labels) != len(ids):
            raise ValueError(
                "ElectraDiscriminator.bce_loss_and_backward: labels 长度 "
                f"{len(labels)} 与 ids 长度 {len(ids)} 不一致")
        for t, y in enumerate(labels):
            if y not in (0, 1) or isinstance(y, bool):
                raise ValueError(
                    "ElectraDiscriminator.bce_loss_and_backward: "
                    f"第 {t} 个标签必须是 0/1，收到 {y!r}")
        if isinstance(grad_scale, bool) or not isinstance(grad_scale, (int, float)) \
                or not math.isfinite(float(grad_scale)) or grad_scale <= 0.0:
            raise ValueError(
                "ElectraDiscriminator.bce_loss_and_backward: "
                f"grad_scale 必须是正有限数，收到 {grad_scale!r}")
        score = self.forward(ids)
        n = len(score)
        loss = 0.0
        ds = [0.0] * n
        for t in range(n):
            s = score[t]
            y = float(labels[t])
            # softplus(s) - y*s，数值稳定写法
            loss += math.log1p(math.exp(-abs(s))) + max(s, 0.0) - y * s
            ds[t] = (_sigmoid(s) - y) * grad_scale
        loss /= n

        h = self.h
        for t in range(n):
            d = ds[t] / n
            for j in range(self.d_model):
                self.grad_W_d[1][j] += d * h[t][j]
                self.grad_W_d[0][j] -= d * h[t][j]
            self.grad_b_d[1] += d
            self.grad_b_d[0] -= d

        dh = [[0.0] * self.d_model for _ in range(n)]
        for t in range(n):
            d = ds[t] / n
            for j in range(self.d_model):
                dh[t][j] = d * (self.W_d[1][j] - self.W_d[0][j])
        dx = self.encoder.backward(dh)
        self.embedding.backward(dx)
        return loss

    def sgd_step(self, lr):
        """SGD 更新编码器 / embedding / 分类头"""
        self.encoder.sgd_step(lr)
        self.embedding.sgd_step(lr)
        for c in range(2):
            for j in range(self.d_model):
                self.W_d[c][j] -= lr * self.grad_W_d[c][j]
            self.b_d[c] -= lr * self.grad_b_d[c]

    def param_count(self):
        """参数总数"""
        d = self.d_model
        ff = self.d_ff
        per_layer = 4 * d * d + 4 * d + 2 * d * ff + ff + d + 4 * d
        return (self.vocab_size + 1) * d + self.num_layers * per_layer + 2 * d + 2


class ElectraModel:
    """ELECTRA 预训练模型：生成器（MaskedLM）+ 判别器（逐位置二分类）

    简化版 ELECTRA：
      * 生成器直接用 `MaskedLM`，破坏方式为「遮罩位置换成 mask_id」
        （不做 80/10/10 随机替换），所以判别器的标签就是「该位置是否被遮罩」；
      * 生成器与判别器分开训练：生成器用 Adam 做掩码语言建模，
        判别器用 SGD 做二分类，两者梯度互不干扰。
    """

    def __init__(self, vocab_size, d_model=32, num_heads=4, d_ff=64,
                 num_layers=2, max_len=32, mask_prob=0.15, seed=None):
        if not isinstance(vocab_size, int) or isinstance(vocab_size, bool) or vocab_size < 1:
            raise ValueError(
                f"ElectraModel: vocab_size 必须是正整数，收到 {vocab_size!r}")
        if isinstance(mask_prob, bool) or not isinstance(mask_prob, (int, float)) \
                or not 0.0 < float(mask_prob) < 1.0:
            raise ValueError(
                f"ElectraModel: mask_prob 必须在 (0,1) 内，收到 {mask_prob!r}")

        self.vocab_size = vocab_size
        self.d_model = d_model
        self.max_len = max_len
        self.mask_prob = float(mask_prob)

        self.generator = MaskedLM(vocab_size, d_model, num_heads, d_ff,
                                  num_layers, max_len, dropout=0.0,
                                  mask_prob=mask_prob, replace_prob=0.1)
        self.discriminator = ElectraDiscriminator(
            vocab_size, d_model, num_heads, d_ff, num_layers, max_len, seed=seed)

    def _check_ids(self, ids, who):
        return _check_token_ids(ids, self.vocab_size, who)

    def _corrupt(self, ids, rng):
        """返回 (corrupted, positions, targets, labels)"""
        ids = self._check_ids(ids, "ElectraModel._corrupt")
        if len(ids) > self.max_len:
            raise ValueError(
                f"ElectraModel._corrupt: 序列长度 {len(ids)} 超过 max_len={self.max_len}")
        if len(ids) < 1:
            raise ValueError("ElectraModel._corrupt: ids 不能为空")
        n_mask = max(1, int(round(len(ids) * self.mask_prob)))
        n_mask = min(n_mask, len(ids) - 1) if len(ids) > 1 else 1
        positions = sorted(rng.sample(range(len(ids)), n_mask))
        corrupted = list(ids)
        labels = [0] * len(ids)
        targets = []
        for p in positions:
            corrupted[p] = self.generator.mask_id
            labels[p] = 1
            targets.append(ids[p])
        return corrupted, positions, targets, labels

    def train_step(self, ids, lr_generator=0.01, lr_discriminator=0.05,
                   seed=None):
        """单条序列一步预训练，返回 (generator_loss, discriminator_loss, accuracy)"""
        rng = random.Random(seed) if seed is not None else random
        corrupted, positions, targets, labels = self._corrupt(ids, rng)

        self.generator.zero_grad()
        g_loss = self.generator._loss_and_backward(corrupted, positions, targets)
        self.generator.adam_step(lr_generator)

        self.discriminator.zero_grad()
        d_loss = self.discriminator.bce_loss_and_backward(corrupted, labels)
        self.discriminator.sgd_step(lr_discriminator)

        probs = [_sigmoid(v) for v in self.discriminator.score]
        correct = 0
        for t, y in enumerate(labels):
            if (1 if probs[t] >= 0.5 else 0) == y:
                correct += 1
        return g_loss, d_loss, correct / len(labels)

    def fit(self, sentences, epochs=10, lr_generator=0.01,
            lr_discriminator=0.05, shuffle=True, seed=None):
        """在若干 token 序列上做 ELECTRA 式预训练，返回每 epoch 统计"""
        if not isinstance(sentences, (list, tuple)) or not sentences:
            raise ValueError("ElectraModel.fit: sentences 不能为空")
        if not isinstance(epochs, int) or isinstance(epochs, bool) or epochs < 1:
            raise ValueError(f"ElectraModel.fit: epochs 必须是正整数，收到 {epochs!r}")
        for name, val in (("lr_generator", lr_generator),
                          ("lr_discriminator", lr_discriminator)):
            if isinstance(val, bool) or not isinstance(val, (int, float)) \
                    or not math.isfinite(float(val)) or val <= 0.0:
                raise ValueError(
                    f"ElectraModel.fit: {name} 必须是正有限数，收到 {val!r}")

        rng = random.Random(seed)
        history = []
        for _ in range(epochs):
            order = list(range(len(sentences)))
            if shuffle:
                rng.shuffle(order)
            g_total = d_total = acc_total = 0.0
            for idx in order:
                step_seed = rng.randrange(2 ** 31)
                g_loss, d_loss, acc = self.train_step(
                    sentences[idx], lr_generator, lr_discriminator,
                    seed=step_seed)
                g_total += g_loss
                d_total += d_loss
                acc_total += acc
            n = len(sentences)
            history.append({
                "generator_loss": g_total / n,
                "discriminator_loss": d_total / n,
                "accuracy": acc_total / n,
            })
        return history

    def detect(self, ids):
        """逐位置「被破坏」概率（0..1）的列表"""
        return self.discriminator.probabilities(ids)


# ============================================================================
#  RWKV：线性注意力式循环语言模型（简化版 RWKV-4）
# ============================================================================


class RWKVBlock:
    """RWKV 风格 block：time-mixing（可学习指数衰减的状态递推）+ channel-mixing

    简化点（docstring 已注明）：
      * 不做 token-shift（把上一 token 的输入混进来），只靠状态递推携带历史；
      * channel-mixing 用 `r ⊙ relu(k)² ⊙ v`，不做 GELU 变体；
      * 无 dropout。其余结构与 RWKV-4 一致：time-mixing 的 `k`/`v` 进入
        逐通道状态 `state = decay*state + k*v`，输出 `r ⊙ (state + u*v)`。
    """

    def __init__(self, d_model, d_ff=None, eps=1e-5, seed=None):
        if not isinstance(d_model, int) or isinstance(d_model, bool) or d_model < 1:
            raise ValueError(f"RWKVBlock: d_model 必须是正整数，收到 {d_model!r}")
        self.d_model = d_model
        self.d_ff = 4 * d_model if d_ff is None else d_ff
        if not isinstance(self.d_ff, int) or isinstance(self.d_ff, bool) or self.d_ff < 1:
            raise ValueError(f"RWKVBlock: d_ff 必须是正整数，收到 {d_ff!r}")

        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.ln1 = LayerNorm(d_model, eps=eps)
            self.Wr = Layer(d_model, d_model, "linear")
            self.Wk = Layer(d_model, d_model, "linear")
            self.Wv = Layer(d_model, d_model, "linear")
            self.Wo = Layer(d_model, d_model, "linear")
            # decay = exp(-exp(w_raw))，初值让 decay≈0.9
            self.w_raw = [math.log(-math.log(0.9)) + random.gauss(0.0, 0.02)
                          for _ in range(d_model)]
            self.u = [0.1] * d_model
            self.ln2 = LayerNorm(d_model, eps=eps)
            self.Wr2 = Layer(d_model, self.d_ff, "linear")
            self.Wk2 = Layer(d_model, self.d_ff, "linear")
            self.Wv2 = Layer(d_model, self.d_ff, "linear")
            self.Wo2 = Layer(self.d_ff, d_model, "linear")
        finally:
            random.setstate(state)

        self.zero_grad()
        self._cache = None

    def zero_grad(self):
        """清零所有参数梯度"""
        self.grads = {
            "Wr": None, "Wk": None, "Wv": None, "Wo": None,
            "Wr2": None, "Wk2": None, "Wv2": None, "Wo2": None,
        }
        self.norm_grads = {"ln1": None, "ln2": None}
        self.grad_w_raw = [0.0] * self.d_model
        self.grad_u = [0.0] * self.d_model

    def train(self):
        return self

    def eval(self):
        return self

    def _decay(self):
        return [math.exp(-math.exp(w)) for w in self.w_raw]

    def forward(self, x):
        """x: (T, d_model) → (T, d_model)"""
        T = len(x)
        d = self.d_model
        h1, c1 = _norm_rows_forward(self.ln1, x)
        r, cr = _dense_rows_forward(self.Wr, h1)
        k, ck = _dense_rows_forward(self.Wk, h1)
        v, cv = _dense_rows_forward(self.Wv, h1)

        decay = self._decay()
        state = [0.0] * d
        states = []
        y = []
        for t in range(T):
            row = [0.0] * d
            for j in range(d):
                state[j] = decay[j] * state[j] + k[t][j] * v[t][j]
                row[j] = r[t][j] * (state[j] + self.u[j] * v[t][j])
            states.append(list(state))
            y.append(row)

        out1, co1 = _dense_rows_forward(self.Wo, y)
        x1 = [[x[t][j] + out1[t][j] for j in range(d)] for t in range(T)]

        h2, c2 = _norm_rows_forward(self.ln2, x1)
        r2, cr2 = _dense_rows_forward(self.Wr2, h2)
        zk, ck2 = _dense_rows_forward(self.Wk2, h2)
        v2, cv2 = _dense_rows_forward(self.Wv2, h2)
        kact = [[max(0.0, zk[t][j]) for j in range(self.d_ff)] for t in range(T)]
        ksq = [[kact[t][j] * kact[t][j] for j in range(self.d_ff)] for t in range(T)]
        y2 = [[r2[t][j] * ksq[t][j] * v2[t][j] for j in range(self.d_ff)]
              for t in range(T)]
        out2, co2 = _dense_rows_forward(self.Wo2, y2)
        out = [[x1[t][j] + out2[t][j] for j in range(d)] for t in range(T)]

        self._cache = {
            "x": x, "h1": h1, "c1": c1,
            "r": r, "cr": cr, "k": k, "ck": ck, "v": v, "cv": cv,
            "decay": decay, "states": states, "y": y,
            "out1": out1, "co1": co1, "x1": x1,
            "h2": h2, "c2": c2, "r2": r2, "cr2": cr2,
            "zk": zk, "ck2": ck2, "v2": v2, "cv2": cv2,
            "kact": kact, "ksq": ksq, "y2": y2, "out2": out2, "co2": co2,
        }
        return out

    def backward(self, dout):
        """dout: (T, d_model) 输出梯度，返回输入梯度"""
        if self._cache is None:
            raise RuntimeError("RWKVBlock.backward: 必须先调用 forward()")
        c = self._cache
        T = len(c["x"])
        d = self.d_model
        ff = self.d_ff

        dx = [list(row) for row in dout]
        d_out2 = dout

        gW2, gb2, d_y2 = _dense_rows_backward(self.Wo2, c["co2"], d_out2)
        self._acc_dense("Wo2", gW2, gb2)

        d_r2 = [[d_y2[t][j] * c["ksq"][t][j] * c["v2"][t][j] for j in range(ff)]
                for t in range(T)]
        d_ksq = [[d_y2[t][j] * c["r2"][t][j] * c["v2"][t][j] for j in range(ff)]
                 for t in range(T)]
        d_v2 = [[d_y2[t][j] * c["r2"][t][j] * c["ksq"][t][j] for j in range(ff)]
                for t in range(T)]
        d_zk = [[d_ksq[t][j] * 2.0 * c["kact"][t][j] *
                 (1.0 if c["zk"][t][j] > 0.0 else 0.0)
                 for j in range(ff)] for t in range(T)]

        gWr2, gbr2, d_h2a = _dense_rows_backward(self.Wr2, c["cr2"], d_r2)
        gWk2, gbk2, d_h2b = _dense_rows_backward(self.Wk2, c["ck2"], d_zk)
        gWv2, gbv2, d_h2c = _dense_rows_backward(self.Wv2, c["cv2"], d_v2)
        self._acc_dense("Wr2", gWr2, gbr2)
        self._acc_dense("Wk2", gWk2, gbk2)
        self._acc_dense("Wv2", gWv2, gbv2)

        d_h2 = [[d_h2a[t][j] + d_h2b[t][j] + d_h2c[t][j] for j in range(d)]
                for t in range(T)]
        g2, b2, d_x1_ln = _norm_rows_backward(self.ln2, c["c2"], d_h2)
        self.norm_grads["ln2"] = (g2, b2)

        d_x1 = [[dx[t][j] + d_x1_ln[t][j] for j in range(d)] for t in range(T)]
        d_out1 = d_x1

        gWo, gbo, d_y = _dense_rows_backward(self.Wo, c["co1"], d_out1)
        self._acc_dense("Wo", gWo, gbo)

        d_r = [[0.0] * d for _ in range(T)]
        d_k = [[0.0] * d for _ in range(T)]
        d_v = [[0.0] * d for _ in range(T)]
        d_decay = [0.0] * d
        for t in range(T):
            for j in range(d):
                d_r[t][j] = d_y[t][j] * (c["states"][t][j] +
                                         self.u[j] * c["v"][t][j])
                d_v[t][j] = d_y[t][j] * c["r"][t][j] * self.u[j]
                self.grad_u[j] += d_y[t][j] * c["r"][t][j] * c["v"][t][j]

        ds_next = [0.0] * d
        for t in range(T - 1, -1, -1):
            ds = [0.0] * d
            for j in range(d):
                ds[j] = d_y[t][j] * c["r"][t][j] + c["decay"][j] * ds_next[j]
            for j in range(d):
                d_k[t][j] += ds[j] * c["v"][t][j]
                d_v[t][j] += ds[j] * c["k"][t][j]
                if t > 0:
                    d_decay[j] += ds[j] * c["states"][t - 1][j]
            ds_next = ds

        for j in range(d):
            w = self.w_raw[j]
            decay = math.exp(-math.exp(w))
            self.grad_w_raw[j] += d_decay[j] * (-math.exp(w) * decay)

        gWr, gbr, d_h1a = _dense_rows_backward(self.Wr, c["cr"], d_r)
        gWk, gbk, d_h1b = _dense_rows_backward(self.Wk, c["ck"], d_k)
        gWv, gbv, d_h1c = _dense_rows_backward(self.Wv, c["cv"], d_v)
        self._acc_dense("Wr", gWr, gbr)
        self._acc_dense("Wk", gWk, gbk)
        self._acc_dense("Wv", gWv, gbv)

        d_h1 = [[d_h1a[t][j] + d_h1b[t][j] + d_h1c[t][j] for j in range(d)]
                for t in range(T)]
        g1, b1, d_x_ln = _norm_rows_backward(self.ln1, c["c1"], d_h1)
        self.norm_grads["ln1"] = (g1, b1)
        for t in range(T):
            for j in range(d):
                dx[t][j] += d_x_ln[t][j]
        return dx

    def _acc_dense(self, name, gw, gb):
        old = self.grads[name]
        if old is None:
            self.grads[name] = (gw, gb)
            return
        ogw, ogb = old
        for i in range(len(gw)):
            for j in range(len(gw[i])):
                ogw[i][j] += gw[i][j]
            ogb[i] += gb[i]

    def sgd_step(self, lr):
        """SGD 更新全部参数"""
        for name in ("Wr", "Wk", "Wv", "Wo", "Wr2", "Wk2", "Wv2", "Wo2"):
            layer = getattr(self, name)
            grads = self.grads[name]
            if grads is not None:
                _dense_apply_sgd(layer, grads, lr)
        for name, norm in (("ln1", self.ln1), ("ln2", self.ln2)):
            grads = self.norm_grads[name]
            if grads is not None:
                _norm_apply_sgd(norm, grads, lr)
        for j in range(self.d_model):
            self.w_raw[j] -= lr * self.grad_w_raw[j]
            self.u[j] -= lr * self.grad_u[j]

    def param_count(self):
        """参数总数"""
        total = 0
        for name in ("Wr", "Wk", "Wv", "Wo", "Wr2", "Wk2", "Wv2", "Wo2"):
            total += _dense_param_count(getattr(self, name))
        total += _norm_param_count(self.ln1) + _norm_param_count(self.ln2)
        total += 2 * self.d_model
        return total


class RWKVModel:
    """RWKV 语言模型：Embedding → N×RWKVBlock → LayerNorm → 词表头"""

    def __init__(self, vocab_size, d_model=32, d_ff=None, num_layers=2,
                 max_len=64, seed=None):
        if not isinstance(vocab_size, int) or isinstance(vocab_size, bool) or vocab_size < 1:
            raise ValueError(f"RWKVModel: vocab_size 必须是正整数，收到 {vocab_size!r}")
        if not isinstance(d_model, int) or isinstance(d_model, bool) or d_model < 1:
            raise ValueError(f"RWKVModel: d_model 必须是正整数，收到 {d_model!r}")
        if not isinstance(num_layers, int) or isinstance(num_layers, bool) or num_layers < 1:
            raise ValueError(f"RWKVModel: num_layers 必须是正整数，收到 {num_layers!r}")
        if not isinstance(max_len, int) or isinstance(max_len, bool) or max_len < 1:
            raise ValueError(f"RWKVModel: max_len 必须 >= 1，收到 {max_len!r}")

        self.vocab_size = vocab_size
        self.d_model = d_model
        self.num_layers = num_layers
        self.max_len = max_len
        std = math.sqrt(2.0 / d_model)
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self._emb = [[random.gauss(0.0, std) for _ in range(d_model)]
                         for _ in range(vocab_size)]
        finally:
            random.setstate(state)
        self._emb_grad = [[0.0] * d_model for _ in range(vocab_size)]
        self._last_ids = []
        self.blocks = [RWKVBlock(d_model, d_ff, seed=None if seed is None else seed + i)
                       for i in range(num_layers)]
        self.ln_out = LayerNorm(d_model)
        self._init_head()

    def _init_head(self):
        std = math.sqrt(2.0 / self.d_model)
        self.W_out = Layer(self.d_model, self.vocab_size, "linear")
        self.grad_W_out = None

    def zero_grad(self):
        for b in self.blocks:
            b.zero_grad()
        self.grad_W_out = None
        self.grad_ln_out = None
        for i in range(self.vocab_size):
            row = self._emb_grad[i]
            for j in range(self.d_model):
                row[j] = 0.0

    def train(self):
        return self

    def eval(self):
        return self

    def _check_ids(self, ids):
        ids = _check_token_ids(ids, self.vocab_size, "RWKVModel")
        if not ids:
            raise ValueError("RWKVModel: ids 不能为空")
        if len(ids) > self.max_len:
            raise ValueError(
                f"RWKVModel: 序列长度 {len(ids)} 超过 max_len={self.max_len}")
        return ids

    def _embed(self, ids):
        self._last_ids = ids
        return [list(self._emb[i]) for i in ids]

    def forward(self, ids):
        ids = self._check_ids(ids)
        x = self._embed(ids)
        for block in self.blocks:
            x = block.forward(x)
        h, c = _norm_rows_forward(self.ln_out, x)
        logits_rows, head_cache = _dense_rows_forward(self.W_out, h)
        return logits_rows

    def embedding_backward(self, dx):
        for t, i in enumerate(self._last_ids):
            for j in range(self.d_model):
                self._emb_grad[i][j] += dx[t][j]

    def _run_loss_and_backward(self, ids, targets):
        ids = self._check_ids(ids)
        T = len(ids)
        n_pred = T - 1
        logits = []
        x = self._embed(ids)
        for block in self.blocks:
            x = block.forward(x)
        h, c = _norm_rows_forward(self.ln_out, x)
        logits, head_cache = _dense_rows_forward(self.W_out, h)

        loss = 0.0
        dlogits = [[0.0] * self.vocab_size for _ in range(T)]
        for t in range(n_pred):
            target = targets[t]
            probs = _softmax_row(logits[t])
            loss += -math.log(probs[target] if probs[target] > 1e-12 else 1e-12)
            drow = dlogits[t]
            for v in range(self.vocab_size):
                drow[v] = probs[v] / n_pred
            drow[target] -= 1.0 / n_pred

        gW, gb, d_h = _dense_rows_backward(self.W_out, head_cache, dlogits)
        self.grad_W_out = (gW, gb)
        g_ln, b_ln, d_x = _norm_rows_backward(self.ln_out, c, d_h)
        self.grad_ln_out = (g_ln, b_ln)

        for block in reversed(self.blocks):
            d_x = block.backward(d_x)
        self.embedding_backward(d_x)
        return loss / n_pred

    def sgd_step(self, lr):
        for block in self.blocks:
            block.sgd_step(lr)
        if self.grad_W_out is not None:
            _dense_apply_sgd(self.W_out, self.grad_W_out, lr)
        if self.grad_ln_out is not None:
            _norm_apply_sgd(self.ln_out, self.grad_ln_out, lr)
        if hasattr(self, "_emb_grad"):
            for i in range(self.vocab_size):
                for j in range(self.d_model):
                    self._emb[i][j] -= lr * self._emb_grad[i][j]

    def param_count(self):
        total = self.vocab_size * self.d_model
        for block in self.blocks:
            total += block.param_count()
        total += _norm_param_count(self.ln_out)
        total += _dense_param_count(self.W_out)
        return total

    def fit(self, sequences, epochs=10, lr=0.01, shuffle=True, seed=None,
            verbose=False):
        """在若干 token 序列上训练，返回每个 epoch 的平均 loss"""
        if not isinstance(sequences, (list, tuple)) or not sequences:
            raise ValueError("RWKVModel.fit: sequences 不能为空")
        if not isinstance(epochs, int) or isinstance(epochs, bool) or epochs < 1:
            raise ValueError(f"RWKVModel.fit: epochs 必须是正整数，收到 {epochs!r}")
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) \
                or not math.isfinite(float(lr)) or lr <= 0.0:
            raise ValueError(f"RWKVModel.fit: lr 必须是正有限数，收到 {lr!r}")
        rng = random.Random(seed)
        history = []
        for ep in range(epochs):
            order = list(range(len(sequences)))
            if shuffle:
                rng.shuffle(order)
            total = 0.0
            for idx in order:
                seq = self._check_ids(list(sequences[idx]))
                if len(seq) < 2:
                    raise ValueError("RWKVModel.fit: 每条序列至少需要 2 个 token")
                self.zero_grad()
                total += self._run_loss_and_backward(seq, seq[1:])
                self.sgd_step(lr)
            avg = total / len(sequences)
            history.append(avg)
            if verbose:
                print(f"epoch {ep + 1}/{epochs} loss={avg:.4f}")
        return history

    def generate(self, prompt_ids, max_new_tokens=8, temperature=1.0,
                 top_k=None, seed=None):
        """自回归采样生成"""
        ids = self._check_ids(list(prompt_ids))
        if not isinstance(max_new_tokens, int) or isinstance(max_new_tokens, bool) \
                or max_new_tokens < 0:
            raise ValueError(
                f"RWKVModel.generate: max_new_tokens 必须是非负整数，收到 {max_new_tokens!r}")
        if isinstance(temperature, bool) or not isinstance(temperature, (int, float)) \
                or not math.isfinite(float(temperature)) or temperature <= 0.0:
            raise ValueError(
                f"RWKVModel.generate: temperature 必须是正有限数，收到 {temperature!r}")
        if top_k is not None and (not isinstance(top_k, int) or isinstance(top_k, bool)
                                  or top_k < 1):
            raise ValueError(
                f"RWKVModel.generate: top_k 必须是正整数或 None，收到 {top_k!r}")
        rng = random.Random(seed)
        out = list(ids)
        for _ in range(max_new_tokens):
            ctx = out[-(self.max_len - 1):] if self.max_len > 1 else out[-1:]
            logits = self.forward(ctx)
            row = logits[-1]
            probs = _softmax_row([v / temperature for v in row])
            if top_k is not None:
                order = sorted(range(len(probs)), key=lambda i: probs[i],
                               reverse=True)[:top_k]
                keep = set(order)
                probs = [p if i in keep else 0.0 for i, p in enumerate(probs)]
                s = sum(probs)
                probs = [p / s for p in probs]
            r = rng.random()
            acc = 0.0
            pick = len(probs) - 1
            for i, p in enumerate(probs):
                acc += p
                if r <= acc:
                    pick = i
                    break
            out.append(pick)
        return out

# ============================================================================
#  RetNet：多尺度保留（multi-scale retention）语言模型（简化版）
# ============================================================================


def _retnet_gammas(num_heads):
    """每头固定的保留衰减 gamma_h = 1 - 2^(-5-h)（论文默认值，不参与训练）"""
    return [1.0 - 2.0 ** (-5.0 - h) for h in range(num_heads)]


def _retention_forward(q, k, v, gamma, scale):
    """多尺度保留（并行形式）

    q/k/v: 每头 (T, head_dim)；返回 (out (T, d), cache)。
    对 t 位置：out[t] = Σ_{j<=t} gamma^(t-j)·(q_t·k_j)·v_j / denom_t
    其中 denom_t = Σ_{j<=t} gamma^(t-j)，scale = 1/sqrt(head_dim)。
    """
    T = len(q)
    dim = len(v[0])
    denom = []
    acc = 0.0
    gpow = 1.0
    for t in range(T):
        if t == 0:
            acc = 1.0
        else:
            acc = acc * gamma + 1.0
        denom.append(acc)
    out = [[0.0] * dim for _ in range(T)]
    scores = [[0.0] * T for _ in range(T)]   # scores[t][j]，j<=t
    for t in range(T):
        row = scores[t]
        for j in range(t + 1):
            s = 0.0
            for i in range(len(q[t])):
                s += q[t][i] * k[j][i]
            row[j] = (s * scale) * (gamma ** (t - j))
        d = denom[t]
        for i in range(dim):
            total = 0.0
            for j in range(t + 1):
                total += row[j] * v[j][i]
            out[t][i] = total / d
    cache = {"q": q, "k": k, "v": v, "gamma": gamma, "scale": scale,
             "denom": denom, "scores": scores}
    return out, cache


def _retention_backward(dout, cache):
    """返回 (dq, dk, dv)"""
    q, k, v = cache["q"], cache["k"], cache["v"]
    gamma, scale = cache["gamma"], cache["scale"]
    denom, scores = cache["denom"], cache["scores"]
    T = len(dout)
    dim = len(v[0])
    dq = [[0.0] * len(q[0]) for _ in range(T)]
    dk = [[0.0] * len(k[0]) for _ in range(T)]
    dv = [[0.0] * dim for _ in range(T)]
    for t in range(T):
        d = denom[t]
        dS = [dout[t][i] / d for i in range(dim)]
        for j in range(t + 1):
            score = scores[t][j]
            # dscore = ∂L/∂score_j = Σ_i dS_t[i]·v_j[i]
            dscore = 0.0
            for i in range(dim):
                dscore += dS[i] * v[j][i]
            if dscore:
                kq = dscore * (gamma ** (t - j)) * scale
                for i in range(len(q[t])):
                    dq[t][i] += kq * k[j][i]
                    dk[j][i] += kq * q[t][i]
            for i in range(dim):
                dv[j][i] += dS[i] * score
    return dq, dk, dv


class RetNetBlock:
    """RetNet block：保留层（retention）+ FFN，两层 pre-norm 残差"""

    def __init__(self, d_model, num_heads, d_ff=None, eps=1e-5, seed=None):
        if not isinstance(d_model, int) or isinstance(d_model, bool) or d_model < 1:
            raise ValueError(f"RetNetBlock: d_model 必须是正整数，收到 {d_model!r}")
        if not isinstance(num_heads, int) or isinstance(num_heads, bool) or num_heads < 1:
            raise ValueError(f"RetNetBlock: num_heads 必须是正整数，收到 {num_heads!r}")
        if d_model % num_heads:
            raise ValueError(
                f"RetNetBlock: d_model={d_model} 必须能被 num_heads={num_heads} 整除")
        self.d_model = d_model
        self.num_heads = num_heads
        self.head_dim = d_model // num_heads
        self.d_ff = 4 * d_model if d_ff is None else d_ff
        if not isinstance(self.d_ff, int) or isinstance(self.d_ff, bool) or self.d_ff < 1:
            raise ValueError(f"RetNetBlock: d_ff 必须是正整数，收到 {d_ff!r}")
        self.gammas = _retnet_gammas(num_heads)
        self.scale = 1.0 / math.sqrt(self.head_dim)

        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.ln1 = LayerNorm(d_model, eps=eps)
            self.Wq = Layer(d_model, d_model, "linear")
            self.Wk = Layer(d_model, d_model, "linear")
            self.Wv = Layer(d_model, d_model, "linear")
            self.Wo = Layer(d_model, d_model, "linear")
            self.ln2 = LayerNorm(d_model, eps=eps)
            self.W1 = Layer(d_model, self.d_ff, "relu")
            self.W2 = Layer(self.d_ff, d_model, "linear")
        finally:
            random.setstate(state)
        self.zero_grad()
        self._cache = None

    def zero_grad(self):
        self.grads = {"Wq": None, "Wk": None, "Wv": None, "Wo": None,
                      "W1": None, "W2": None}
        self.norm_grads = {"ln1": None, "ln2": None}

    def train(self):
        return self

    def eval(self):
        return self

    def _split_heads(self, rows):
        h, dh = self.num_heads, self.head_dim
        return [[rows[t][j * dh:(j + 1) * dh] for j in range(h)]
                for t in range(len(rows))]

    def forward(self, x):
        """x: (T, d_model) → (T, d_model)"""
        T = len(x)
        d = self.d_model
        h1, c1 = _norm_rows_forward(self.ln1, x)
        qflat, cq = _dense_rows_forward(self.Wq, h1)
        kflat, ck = _dense_rows_forward(self.Wk, h1)
        vflat, cv = _dense_rows_forward(self.Wv, h1)
        qh = self._split_heads(qflat)
        kh = self._split_heads(kflat)
        vh = self._split_heads(vflat)

        ret_outs = []
        ret_caches = []
        for h in range(self.num_heads):
            q_h = [qh[t][h] for t in range(T)]
            k_h = [kh[t][h] for t in range(T)]
            v_h = [vh[t][h] for t in range(T)]
            out_h, cache_h = _retention_forward(q_h, k_h, v_h,
                                               self.gammas[h], self.scale)
            ret_outs.append(out_h)
            ret_caches.append(cache_h)

        concat = [[0.0] * d for _ in range(T)]
        for h in range(self.num_heads):
            off = h * self.head_dim
            for t in range(T):
                for i in range(self.head_dim):
                    concat[t][off + i] = ret_outs[h][t][i]
        out1, co1 = _dense_rows_forward(self.Wo, concat)
        x1 = [[x[t][j] + out1[t][j] for j in range(d)] for t in range(T)]

        h2, c2 = _norm_rows_forward(self.ln2, x1)
        a2, ca2 = _dense_rows_forward(self.W1, h2)
        out2, co2 = _dense_rows_forward(self.W2, a2)
        out = [[x1[t][j] + out2[t][j] for j in range(d)] for t in range(T)]

        self._cache = {"x": x, "h1": h1, "c1": c1,
                       "qh": qh, "kh": kh, "vh": vh,
                       "cq": cq, "ck": ck, "cv": cv,
                       "ret_caches": ret_caches, "concat": concat,
                       "co1": co1, "x1": x1, "h2": h2, "c2": c2,
                       "a2": a2, "ca2": ca2, "co2": co2}
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("RetNetBlock.backward: 必须先调用 forward()")
        c = self._cache
        T = len(c["x"])
        d = self.d_model
        head_dim = self.head_dim

        dx = [list(row) for row in dout]
        # FFN 分支
        gW2, gb2, d_a2 = _dense_rows_backward(self.W2, c["co2"], dout)
        self._acc("W2", gW2, gb2)
        gW1, gb1, d_h2 = _dense_rows_backward(self.W1, c["ca2"], d_a2)
        self._acc("W1", gW1, gb1)
        g_ln2, b_ln2, d_x1a = _norm_rows_backward(self.ln2, c["c2"], d_h2)
        self.norm_grads["ln2"] = (g_ln2, b_ln2)

        d_x1 = [[dx[t][j] + d_x1a[t][j] for j in range(d)] for t in range(T)]
        d_concat, d_out1 = None, d_x1
        gWo, gbo, d_concat = _dense_rows_backward(self.Wo, c["co1"], d_out1)
        self._acc("Wo", gWo, gbo)

        head_grads = []
        for h in range(self.num_heads):
            off = h * head_dim
            d_out_h = [[d_concat[t][off + i] for i in range(head_dim)]
                       for t in range(T)]
            head_grads.append(_retention_backward(d_out_h,
                                                  c["ret_caches"][h]))

        dq_flat = [[0.0] * d for _ in range(T)]
        dk_flat = [[0.0] * d for _ in range(T)]
        dv_flat = [[0.0] * d for _ in range(T)]
        for h in range(self.num_heads):
            dq_h, dk_h, dv_h = head_grads[h]
            off = h * head_dim
            for t in range(T):
                for i in range(head_dim):
                    dq_flat[t][off + i] = dq_h[t][i]
                    dk_flat[t][off + i] = dk_h[t][i]
                    dv_flat[t][off + i] = dv_h[t][i]

        gWq, gbq, d_h1a = _dense_rows_backward(self.Wq, c["cq"], dq_flat)
        gWk, gbk, d_h1b = _dense_rows_backward(self.Wk, c["ck"], dk_flat)
        gWv, gbv, d_h1c = _dense_rows_backward(self.Wv, c["cv"], dv_flat)
        self._acc("Wq", gWq, gbq)
        self._acc("Wk", gWk, gbk)
        self._acc("Wv", gWv, gbv)

        d_h1 = [[d_h1a[t][j] + d_h1b[t][j] + d_h1c[t][j] for j in range(d)]
                for t in range(T)]
        g_ln1, b_ln1, d_x_ln = _norm_rows_backward(self.ln1, c["c1"], d_h1)
        self.norm_grads["ln1"] = (g_ln1, b_ln1)
        for t in range(T):
            for j in range(d):
                dx[t][j] += d_x_ln[t][j]
        return dx

    def _acc(self, name, gw, gb):
        old = self.grads[name]
        if old is None:
            self.grads[name] = (gw, gb)
            return
        ogw, ogb = old
        for i in range(len(gw)):
            for j in range(len(gw[i])):
                ogw[i][j] += gw[i][j]
            ogb[i] += gb[i]

    def sgd_step(self, lr):
        for name in ("Wq", "Wk", "Wv", "Wo", "W1", "W2"):
            grads = self.grads[name]
            if grads is not None:
                _dense_apply_sgd(getattr(self, name), grads, lr)
        for name, norm in (("ln1", self.ln1), ("ln2", self.ln2)):
            grads = self.norm_grads[name]
            if grads is not None:
                _norm_apply_sgd(norm, grads, lr)

    def param_count(self):
        total = 0
        for name in ("Wq", "Wk", "Wv", "Wo", "W1", "W2"):
            total += _dense_param_count(getattr(self, name))
        total += _norm_param_count(self.ln1) + _norm_param_count(self.ln2)
        return total


class RetNetModel:
    """RetNet 语言模型：Embedding → N×RetNetBlock → LayerNorm → 词表头"""

    def __init__(self, vocab_size, d_model=32, num_heads=4, d_ff=None,
                 num_layers=2, max_len=64, seed=None):
        if not isinstance(vocab_size, int) or isinstance(vocab_size, bool) or vocab_size < 1:
            raise ValueError(f"RetNetModel: vocab_size 必须是正整数，收到 {vocab_size!r}")
        if not isinstance(d_model, int) or isinstance(d_model, bool) or d_model < 1:
            raise ValueError(f"RetNetModel: d_model 必须是正整数，收到 {d_model!r}")
        if not isinstance(num_heads, int) or isinstance(num_heads, bool) or num_heads < 1:
            raise ValueError(f"RetNetModel: num_heads 必须是正整数，收到 {num_heads!r}")
        if d_model % num_heads:
            raise ValueError(
                f"RetNetModel: d_model={d_model} 必须能被 num_heads={num_heads} 整除")
        if not isinstance(num_layers, int) or isinstance(num_layers, bool) or num_layers < 1:
            raise ValueError(f"RetNetModel: num_layers 必须是正整数，收到 {num_layers!r}")
        if not isinstance(max_len, int) or isinstance(max_len, bool) or max_len < 1:
            raise ValueError(f"RetNetModel: max_len 必须 >= 1，收到 {max_len!r}")
        if d_ff is not None:
            if not isinstance(d_ff, int) or isinstance(d_ff, bool) or d_ff < 1:
                raise ValueError(f"RetNetModel: d_ff 必须是正整数或 None，收到 {d_ff!r}")

        self.vocab_size = vocab_size
        self.d_model = d_model
        self.num_layers = num_layers
        self.max_len = max_len
        std = math.sqrt(2.0 / d_model)
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self._emb = [[random.gauss(0.0, std) for _ in range(d_model)]
                         for _ in range(vocab_size)]
        finally:
            random.setstate(state)
        self._emb_grad = [[0.0] * d_model for _ in range(vocab_size)]
        self._last_ids = []
        self.blocks = [RetNetBlock(d_model, num_heads, d_ff,
                                   seed=None if seed is None else seed + i)
                       for i in range(num_layers)]
        self.ln_out = LayerNorm(d_model)
        self.W_out = Layer(d_model, vocab_size, "linear")

    def zero_grad(self):
        for b in self.blocks:
            b.zero_grad()
        self.grad_W_out = None
        self.grad_ln_out = None
        for i in range(self.vocab_size):
            row = self._emb_grad[i]
            for j in range(self.d_model):
                row[j] = 0.0

    def train(self):
        return self

    def eval(self):
        return self

    def _check_ids(self, ids):
        ids = _check_token_ids(ids, self.vocab_size, "RetNetModel")
        if not ids:
            raise ValueError("RetNetModel: ids 不能为空")
        if len(ids) > self.max_len:
            raise ValueError(
                f"RetNetModel: 序列长度 {len(ids)} 超过 max_len={self.max_len}")
        return ids

    def _embed(self, ids):
        self._last_ids = ids
        return [list(self._emb[i]) for i in ids]

    def forward(self, ids):
        ids = self._check_ids(ids)
        x = self._embed(ids)
        for block in self.blocks:
            x = block.forward(x)
        h, c = _norm_rows_forward(self.ln_out, x)
        logits, head_cache = _dense_rows_forward(self.W_out, h)
        return logits

    def embedding_backward(self, dx):
        for t, i in enumerate(self._last_ids):
            for j in range(self.d_model):
                self._emb_grad[i][j] += dx[t][j]

    def _run_loss_and_backward(self, ids, targets):
        ids = self._check_ids(ids)
        T = len(ids)
        n_pred = T - 1
        x = self._embed(ids)
        for block in self.blocks:
            x = block.forward(x)
        h, c = _norm_rows_forward(self.ln_out, x)
        logits, head_cache = _dense_rows_forward(self.W_out, h)

        loss = 0.0
        dlogits = [[0.0] * self.vocab_size for _ in range(T)]
        for t in range(n_pred):
            target = targets[t]
            probs = _softmax_row(logits[t])
            loss += -math.log(probs[target] if probs[target] > 1e-12 else 1e-12)
            drow = dlogits[t]
            for v in range(self.vocab_size):
                drow[v] = probs[v] / n_pred
            drow[target] -= 1.0 / n_pred

        gW, gb, d_h = _dense_rows_backward(self.W_out, head_cache, dlogits)
        self.grad_W_out = (gW, gb)
        g_ln, b_ln, d_x = _norm_rows_backward(self.ln_out, c, d_h)
        self.grad_ln_out = (g_ln, b_ln)
        for block in reversed(self.blocks):
            d_x = block.backward(d_x)
        self.embedding_backward(d_x)
        return loss / n_pred

    def sgd_step(self, lr):
        for block in self.blocks:
            block.sgd_step(lr)
        if self.grad_W_out is not None:
            _dense_apply_sgd(self.W_out, self.grad_W_out, lr)
        if self.grad_ln_out is not None:
            _norm_apply_sgd(self.ln_out, self.grad_ln_out, lr)
        for i in range(self.vocab_size):
            for j in range(self.d_model):
                self._emb[i][j] -= lr * self._emb_grad[i][j]

    def param_count(self):
        total = self.vocab_size * self.d_model
        for block in self.blocks:
            total += block.param_count()
        total += _norm_param_count(self.ln_out)
        total += _dense_param_count(self.W_out)
        return total

    def fit(self, sequences, epochs=10, lr=0.01, shuffle=True, seed=None,
            verbose=False):
        if not isinstance(sequences, (list, tuple)) or not sequences:
            raise ValueError("RetNetModel.fit: sequences 不能为空")
        if not isinstance(epochs, int) or isinstance(epochs, bool) or epochs < 1:
            raise ValueError(f"RetNetModel.fit: epochs 必须是正整数，收到 {epochs!r}")
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) \
                or not math.isfinite(float(lr)) or lr <= 0.0:
            raise ValueError(f"RetNetModel.fit: lr 必须是正有限数，收到 {lr!r}")
        rng = random.Random(seed)
        history = []
        for ep in range(epochs):
            order = list(range(len(sequences)))
            if shuffle:
                rng.shuffle(order)
            total = 0.0
            for idx in order:
                seq = self._check_ids(list(sequences[idx]))
                if len(seq) < 2:
                    raise ValueError("RetNetModel.fit: 每条序列至少需要 2 个 token")
                self.zero_grad()
                total += self._run_loss_and_backward(seq, seq[1:])
                self.sgd_step(lr)
            avg = total / len(sequences)
            history.append(avg)
            if verbose:
                print(f"epoch {ep + 1}/{epochs} loss={avg:.4f}")
        return history

    def generate(self, prompt_ids, max_new_tokens=8, temperature=1.0,
                 top_k=None, seed=None):
        ids = self._check_ids(list(prompt_ids))
        if not isinstance(max_new_tokens, int) or isinstance(max_new_tokens, bool) \
                or max_new_tokens < 0:
            raise ValueError(
                f"RetNetModel.generate: max_new_tokens 必须是非负整数，收到 {max_new_tokens!r}")
        if isinstance(temperature, bool) or not isinstance(temperature, (int, float)) \
                or not math.isfinite(float(temperature)) or temperature <= 0.0:
            raise ValueError(
                f"RetNetModel.generate: temperature 必须是正有限数，收到 {temperature!r}")
        if top_k is not None and (not isinstance(top_k, int) or isinstance(top_k, bool)
                                  or top_k < 1):
            raise ValueError(
                f"RetNetModel.generate: top_k 必须是正整数或 None，收到 {top_k!r}")
        rng = random.Random(seed)
        out = list(ids)
        for _ in range(max_new_tokens):
            ctx = out[-self.max_len:] if len(out) > self.max_len else out
            logits = self.forward(ctx)
            row = logits[-1]
            probs = _softmax_row([v / temperature for v in row])
            if top_k is not None:
                order = sorted(range(len(probs)), key=lambda i: probs[i],
                               reverse=True)[:top_k]
                keep = set(order)
                probs = [p if i in keep else 0.0 for i, p in enumerate(probs)]
                s = sum(probs)
                probs = [p / s for p in probs]
            r = rng.random()
            acc = 0.0
            pick = len(probs) - 1
            for i, p in enumerate(probs):
                acc += p
                if r <= acc:
                    pick = i
                    break
            out.append(pick)
        return out

# ============================================================================
#  xLSTM：指数门控的 sLSTM block 与语言模型（教学简化版）
# ============================================================================


class _SLSTMCell:
    """sLSTM 风格单元：逐通道标量记忆 c、归一化 n 与指数输入门。

    简化点（docstring 已注明）：
      * 门只由当前输入 x_t 计算（不把 h_{t-1} 拼进输入），序列建模靠记忆递推；
      * 遗忘门用 sigmoid（原论文为 exp 且需 m 稳定化状态），输入门用 exp 但做
        范围裁剪避免溢出；
      * h_t = o_t · c_t / max(|n_t|, eps)。
    """

    def __init__(self, d_model, eps=1e-5, seed=None):
        self.d_model = d_model
        self.eps = eps
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.Wg = Layer(d_model, 4 * d_model, "linear")
            self.Wo = Layer(d_model, d_model, "linear")
        finally:
            random.setstate(state)
        self.zero_grad()
        self._cache = None

    def zero_grad(self):
        self.grad_Wg = None
        self.grad_Wo = None

    def forward(self, x):
        """x: (T, d) → (T, d)"""
        T = len(x)
        d = self.d_model
        gates, cg = _dense_rows_forward(self.Wg, x)
        i_act, f_act, z_act, o_act = [], [], [], []
        c, n, h = [], [], []
        c_prev = [0.0] * d
        n_prev = [0.0] * d
        for t in range(T):
            row = gates[t]
            i_pre = row[0:d]
            f_pre = row[d:2 * d]
            z_pre = row[2 * d:3 * d]
            o_pre = row[3 * d:4 * d]
            i_t = [math.exp(max(-10.0, min(5.0, v))) for v in i_pre]
            f_t = [1.0 / (1.0 + math.exp(-v)) for v in f_pre]
            z_t = [math.tanh(v) for v in z_pre]
            o_t = [1.0 / (1.0 + math.exp(-v)) for v in o_pre]
            c_t = [f_t[j] * c_prev[j] + i_t[j] * z_t[j] for j in range(d)]
            n_t = [f_t[j] * n_prev[j] + i_t[j] for j in range(d)]
            h_t = []
            for j in range(d):
                denom = abs(n_t[j])
                if denom < self.eps:
                    denom = self.eps
                h_t.append(o_t[j] * c_t[j] / denom)
            i_act.append(i_t)
            f_act.append(f_t)
            z_act.append(z_t)
            o_act.append(o_t)
            c.append(c_t)
            n.append(n_t)
            h.append(h_t)
            c_prev, n_prev = c_t, n_t
        out, co = _dense_rows_forward(self.Wo, h)
        self._cache = {"x": x, "gates_cache": cg, "cg": cg, "co": co,
                       "i": i_act, "f": f_act, "z": z_act, "o": o_act,
                       "c": c, "n": n, "h": h}
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("_SLSTMCell.backward: 必须先调用 forward()")
        c = self._cache
        T = len(dout)
        d = self.d_model
        gWo, gbo, d_h = _dense_rows_backward(self.Wo, c["co"], dout)
        self.grad_Wo = (gWo, gbo)

        dgates = [[0.0] * (4 * d) for _ in range(T)]
        dc_next = [0.0] * d
        dn_next = [0.0] * d
        for t in range(T - 1, -1, -1):
            i_t = c["i"][t]
            f_t = c["f"][t]
            z_t = c["z"][t]
            o_t = c["o"][t]
            c_t = c["c"][t]
            n_t = c["n"][t]
            c_prev = c["c"][t - 1] if t > 0 else [0.0] * d
            n_prev = c["n"][t - 1] if t > 0 else [0.0] * d
            dh = d_h[t]
            dc = [dc_next[j] for j in range(d)]
            dn = [dn_next[j] for j in range(d)]
            do = [0.0] * d
            for j in range(d):
                denom = abs(n_t[j])
                if denom < self.eps:
                    denom = self.eps
                inv = 1.0 / denom
                do[j] = dh[j] * c_t[j] * inv
                dc[j] += dh[j] * o_t[j] * inv
                if abs(n_t[j]) > self.eps:
                    dn[j] += -dh[j] * o_t[j] * c_t[j] * inv * inv * \
                        (1.0 if n_t[j] > 0.0 else -1.0)
            # c_t = f*c_prev + i*z ; n_t = f*n_prev + i
            df = [dc[j] * c_prev[j] + dn[j] * n_prev[j] for j in range(d)]
            di = [dc[j] * z_t[j] + dn[j] for j in range(d)]
            dz = [dc[j] * i_t[j] for j in range(d)]
            # 反向到 pre-activation
            row = dgates[t]
            for j in range(d):
                row[j] = di[j] * i_t[j]
                row[d + j] = df[j] * f_t[j] * (1.0 - f_t[j])
                row[2 * d + j] = dz[j] * (1.0 - z_t[j] * z_t[j])
                row[3 * d + j] = do[j] * o_t[j] * (1.0 - o_t[j])
            dc_next = [dc[j] * f_t[j] for j in range(d)]
            dn_next = [dn[j] * f_t[j] for j in range(d)]

        gWg, gbg, dx = _dense_rows_backward(self.Wg, c["cg"], dgates)
        self.grad_Wg = (gWg, gbg)
        return dx

    def sgd_step(self, lr):
        if self.grad_Wg is not None:
            _dense_apply_sgd(self.Wg, self.grad_Wg, lr)
        if self.grad_Wo is not None:
            _dense_apply_sgd(self.Wo, self.grad_Wo, lr)

    def param_count(self):
        return _dense_param_count(self.Wg) + _dense_param_count(self.Wo)


class XLSTMBlock:
    """xLSTM block：pre-norm sLSTM 残差 + pre-norm FFN 残差"""

    def __init__(self, d_model, d_ff=None, eps=1e-5, seed=None):
        if not isinstance(d_model, int) or isinstance(d_model, bool) or d_model < 1:
            raise ValueError(f"XLSTMBlock: d_model 必须是正整数，收到 {d_model!r}")
        self.d_model = d_model
        self.d_ff = 4 * d_model if d_ff is None else d_ff
        if not isinstance(self.d_ff, int) or isinstance(self.d_ff, bool) or self.d_ff < 1:
            raise ValueError(f"XLSTMBlock: d_ff 必须是正整数，收到 {d_ff!r}")
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.ln1 = LayerNorm(d_model, eps=eps)
            self.cell = _SLSTMCell(d_model, eps=eps)
            self.ln2 = LayerNorm(d_model, eps=eps)
            self.W1 = Layer(d_model, self.d_ff, "relu")
            self.W2 = Layer(self.d_ff, d_model, "linear")
        finally:
            random.setstate(state)
        self.zero_grad()
        self._cache = None

    def zero_grad(self):
        self.cell.zero_grad()
        self.grad_W1 = None
        self.grad_W2 = None
        self.norm_grads = {"ln1": None, "ln2": None}

    def train(self):
        return self

    def eval(self):
        return self

    def forward(self, x):
        T = len(x)
        d = self.d_model
        h1, c1 = _norm_rows_forward(self.ln1, x)
        s1 = self.cell.forward(h1)
        x1 = [[x[t][j] + s1[t][j] for j in range(d)] for t in range(T)]
        h2, c2 = _norm_rows_forward(self.ln2, x1)
        a2, ca2 = _dense_rows_forward(self.W1, h2)
        out2, co2 = _dense_rows_forward(self.W2, a2)
        out = [[x1[t][j] + out2[t][j] for j in range(d)] for t in range(T)]
        self._cache = {"x": x, "c1": c1, "c2": c2, "ca2": ca2, "co2": co2,
                       "x1": x1}
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("XLSTMBlock.backward: 必须先调用 forward()")
        c = self._cache
        T = len(dout)
        d = self.d_model
        gW2, gb2, d_a2 = _dense_rows_backward(self.W2, c["co2"], dout)
        self.grad_W2 = (gW2, gb2)
        gW1, gb1, d_h2 = _dense_rows_backward(self.W1, c["ca2"], d_a2)
        self.grad_W1 = (gW1, gb1)
        g_ln2, b_ln2, d_x1a = _norm_rows_backward(self.ln2, c["c2"], d_h2)
        self.norm_grads["ln2"] = (g_ln2, b_ln2)

        d_x1 = [[dout[t][j] + d_x1a[t][j] for j in range(d)] for t in range(T)]
        d_s1 = self.cell.backward(d_x1)
        g_ln1, b_ln1, d_x_ln = _norm_rows_backward(self.ln1, c["c1"], d_s1)
        self.norm_grads["ln1"] = (g_ln1, b_ln1)
        dx = [[dout[t][j] + d_x_ln[t][j] for j in range(d)] for t in range(T)]
        return dx

    def sgd_step(self, lr):
        self.cell.sgd_step(lr)
        if self.grad_W1 is not None:
            _dense_apply_sgd(self.W1, self.grad_W1, lr)
        if self.grad_W2 is not None:
            _dense_apply_sgd(self.W2, self.grad_W2, lr)
        for name, norm in (("ln1", self.ln1), ("ln2", self.ln2)):
            grads = self.norm_grads[name]
            if grads is not None:
                _norm_apply_sgd(norm, grads, lr)

    def param_count(self):
        return (self.cell.param_count() + _dense_param_count(self.W1)
                + _dense_param_count(self.W2)
                + _norm_param_count(self.ln1) + _norm_param_count(self.ln2))


class XLSTMModel:
    """xLSTM 语言模型：Embedding → N×XLSTMBlock → LayerNorm → 词表头"""

    def __init__(self, vocab_size, d_model=32, d_ff=None, num_layers=2,
                 max_len=64, seed=None):
        if not isinstance(vocab_size, int) or isinstance(vocab_size, bool) or vocab_size < 1:
            raise ValueError(f"XLSTMModel: vocab_size 必须是正整数，收到 {vocab_size!r}")
        if not isinstance(d_model, int) or isinstance(d_model, bool) or d_model < 1:
            raise ValueError(f"XLSTMModel: d_model 必须是正整数，收到 {d_model!r}")
        if not isinstance(num_layers, int) or isinstance(num_layers, bool) or num_layers < 1:
            raise ValueError(f"XLSTMModel: num_layers 必须是正整数，收到 {num_layers!r}")
        if not isinstance(max_len, int) or isinstance(max_len, bool) or max_len < 1:
            raise ValueError(f"XLSTMModel: max_len 必须 >= 1，收到 {max_len!r}")
        if d_ff is not None and (not isinstance(d_ff, int)
                                 or isinstance(d_ff, bool) or d_ff < 1):
            raise ValueError(f"XLSTMModel: d_ff 必须是正整数或 None，收到 {d_ff!r}")

        self.vocab_size = vocab_size
        self.d_model = d_model
        self.max_len = max_len
        std = math.sqrt(2.0 / d_model)
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self._emb = [[random.gauss(0.0, std) for _ in range(d_model)]
                         for _ in range(vocab_size)]
        finally:
            random.setstate(state)
        self._emb_grad = [[0.0] * d_model for _ in range(vocab_size)]
        self._last_ids = []
        self.blocks = [XLSTMBlock(d_model, d_ff,
                                  seed=None if seed is None else seed + i)
                       for i in range(num_layers)]
        self.ln_out = LayerNorm(d_model)
        self.W_out = Layer(d_model, vocab_size, "linear")

    def zero_grad(self):
        for b in self.blocks:
            b.zero_grad()
        self.grad_W_out = None
        self.grad_ln_out = None
        for i in range(self.vocab_size):
            for j in range(self.d_model):
                self._emb_grad[i][j] = 0.0

    def train(self):
        return self

    def eval(self):
        return self

    def _check_ids(self, ids):
        ids = _check_token_ids(ids, self.vocab_size, "XLSTMModel")
        if not ids:
            raise ValueError("XLSTMModel: ids 不能为空")
        if len(ids) > self.max_len:
            raise ValueError(
                f"XLSTMModel: 序列长度 {len(ids)} 超过 max_len={self.max_len}")
        return ids

    def _embed(self, ids):
        self._last_ids = ids
        return [list(self._emb[i]) for i in ids]

    def forward(self, ids):
        ids = self._check_ids(ids)
        x = self._embed(ids)
        for block in self.blocks:
            x = block.forward(x)
        h, c = _norm_rows_forward(self.ln_out, x)
        logits, _ = _dense_rows_forward(self.W_out, h)
        return logits

    def _run_loss_and_backward(self, ids, targets):
        ids = self._check_ids(ids)
        T = len(ids)
        n_pred = T - 1
        x = self._embed(ids)
        for block in self.blocks:
            x = block.forward(x)
        h, c = _norm_rows_forward(self.ln_out, x)
        logits, head_cache = _dense_rows_forward(self.W_out, h)
        loss = 0.0
        dlogits = [[0.0] * self.vocab_size for _ in range(T)]
        for t in range(n_pred):
            target = targets[t]
            probs = _softmax_row(logits[t])
            loss += -math.log(probs[target] if probs[target] > 1e-12 else 1e-12)
            drow = dlogits[t]
            for v in range(self.vocab_size):
                drow[v] = probs[v] / n_pred
            drow[target] -= 1.0 / n_pred
        gW, gb, d_h = _dense_rows_backward(self.W_out, head_cache, dlogits)
        self.grad_W_out = (gW, gb)
        g_ln, b_ln, d_x = _norm_rows_backward(self.ln_out, c, d_h)
        self.grad_ln_out = (g_ln, b_ln)
        for block in reversed(self.blocks):
            d_x = block.backward(d_x)
        for t, i in enumerate(self._last_ids):
            for j in range(self.d_model):
                self._emb_grad[i][j] += d_x[t][j]
        return loss / n_pred

    def sgd_step(self, lr):
        for block in self.blocks:
            block.sgd_step(lr)
        if self.grad_W_out is not None:
            _dense_apply_sgd(self.W_out, self.grad_W_out, lr)
        if self.grad_ln_out is not None:
            _norm_apply_sgd(self.ln_out, self.grad_ln_out, lr)
        for i in range(self.vocab_size):
            for j in range(self.d_model):
                self._emb[i][j] -= lr * self._emb_grad[i][j]

    def param_count(self):
        total = self.vocab_size * self.d_model
        for block in self.blocks:
            total += block.param_count()
        total += _norm_param_count(self.ln_out)
        total += _dense_param_count(self.W_out)
        return total

    def fit(self, sequences, epochs=10, lr=0.01, shuffle=True, seed=None,
            verbose=False):
        if not isinstance(sequences, (list, tuple)) or not sequences:
            raise ValueError("XLSTMModel.fit: sequences 不能为空")
        if not isinstance(epochs, int) or isinstance(epochs, bool) or epochs < 1:
            raise ValueError(f"XLSTMModel.fit: epochs 必须是正整数，收到 {epochs!r}")
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) \
                or not math.isfinite(float(lr)) or lr <= 0.0:
            raise ValueError(f"XLSTMModel.fit: lr 必须是正有限数，收到 {lr!r}")
        rng = random.Random(seed)
        history = []
        for ep in range(epochs):
            order = list(range(len(sequences)))
            if shuffle:
                rng.shuffle(order)
            total = 0.0
            for idx in order:
                seq = self._check_ids(list(sequences[idx]))
                if len(seq) < 2:
                    raise ValueError("XLSTMModel.fit: 每条序列至少需要 2 个 token")
                self.zero_grad()
                total += self._run_loss_and_backward(seq, seq[1:])
                self.sgd_step(lr)
            avg = total / len(sequences)
            history.append(avg)
            if verbose:
                print(f"epoch {ep + 1}/{epochs} loss={avg:.4f}")
        return history

    def generate(self, prompt_ids, max_new_tokens=8, temperature=1.0,
                 top_k=None, seed=None):
        ids = self._check_ids(list(prompt_ids))
        if not isinstance(max_new_tokens, int) or isinstance(max_new_tokens, bool) \
                or max_new_tokens < 0:
            raise ValueError(
                f"XLSTMModel.generate: max_new_tokens 必须是非负整数，收到 {max_new_tokens!r}")
        if isinstance(temperature, bool) or not isinstance(temperature, (int, float)) \
                or not math.isfinite(float(temperature)) or temperature <= 0.0:
            raise ValueError(
                f"XLSTMModel.generate: temperature 必须是正有限数，收到 {temperature!r}")
        if top_k is not None and (not isinstance(top_k, int) or isinstance(top_k, bool)
                                  or top_k < 1):
            raise ValueError(
                f"XLSTMModel.generate: top_k 必须是正整数或 None，收到 {top_k!r}")
        rng = random.Random(seed)
        out = list(ids)
        for _ in range(max_new_tokens):
            ctx = out[-self.max_len:] if len(out) > self.max_len else out
            logits = self.forward(ctx)
            probs = _softmax_row([v / temperature for v in logits[-1]])
            if top_k is not None:
                order = sorted(range(len(probs)), key=lambda i: probs[i],
                               reverse=True)[:top_k]
                keep = set(order)
                probs = [p if i in keep else 0.0 for i, p in enumerate(probs)]
                s = sum(probs)
                probs = [p / s for p in probs]
            r = rng.random()
            acc = 0.0
            pick = len(probs) - 1
            for i, p in enumerate(probs):
                acc += p
                if r <= acc:
                    pick = i
                    break
            out.append(pick)
        return out

# ============================================================================
#  DeBERTa：解耦注意力（content-to-content / content-to-position / position-to-content）
# ============================================================================


class DeBERTaBlock:
    """单头解耦注意力 block（教学简化版，docstring 注明与正式 DeBERTa 的差异）。

    注意力分数（因果，j <= t）：
        s(t, j) = scale · ( q_t·k_j + q_t·Rk[d] + k_j·Rq[d] ),  d = t - j
    其中 Rk 为 content-to-position 的相对位置表，Rq 为 position-to-content 表，
    d 截断到 [0, max_rel]。相对位置只建模「过去的距离」，与因果掩码一致。
    正式 DeBERTa 为多头、带位置到内容和内容到位置两套投影；本实现为单头、
    每距离共享一个向量，便于教学与数值校验。
    """

    def __init__(self, d_model, d_ff=None, max_rel=16, eps=1e-5, seed=None):
        if not isinstance(d_model, int) or isinstance(d_model, bool) or d_model < 1:
            raise ValueError(f"DeBERTaBlock: d_model 必须是正整数，收到 {d_model!r}")
        if not isinstance(max_rel, int) or isinstance(max_rel, bool) or max_rel < 1:
            raise ValueError(f"DeBERTaBlock: max_rel 必须是正整数，收到 {max_rel!r}")
        self.d_model = d_model
        self.d_ff = 4 * d_model if d_ff is None else d_ff
        if not isinstance(self.d_ff, int) or isinstance(self.d_ff, bool) or self.d_ff < 1:
            raise ValueError(f"DeBERTaBlock: d_ff 必须是正整数，收到 {d_ff!r}")
        self.max_rel = max_rel
        self.n_rel = 2 * max_rel + 1
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.ln1 = LayerNorm(d_model, eps=eps)
            self.Wq = Layer(d_model, d_model, "linear")
            self.Wk = Layer(d_model, d_model, "linear")
            self.Wv = Layer(d_model, d_model, "linear")
            self.Wo = Layer(d_model, d_model, "linear")
            std = math.sqrt(2.0 / d_model)
            self.Rk = [[random.gauss(0.0, std) for _ in range(d_model)]
                       for _ in range(self.n_rel)]
            self.Rq = [[random.gauss(0.0, std) for _ in range(d_model)]
                       for _ in range(self.n_rel)]
            self.ln2 = LayerNorm(d_model, eps=eps)
            self.W1 = Layer(d_model, self.d_ff, "relu")
            self.W2 = Layer(self.d_ff, d_model, "linear")
        finally:
            random.setstate(state)
        self.zero_grad()
        self._cache = None

    def zero_grad(self):
        self.grad_Wq = None
        self.grad_Wk = None
        self.grad_Wv = None
        self.grad_Wo = None
        self.grad_W1 = None
        self.grad_W2 = None
        self.grad_Rk = [[0.0] * self.d_model for _ in range(self.n_rel)]
        self.grad_Rq = [[0.0] * self.d_model for _ in range(self.n_rel)]
        self.norm_grads = {"ln1": None, "ln2": None}

    def train(self):
        return self

    def eval(self):
        return self

    def _bucket(self, delta):
        if delta > self.max_rel:
            delta = self.max_rel
        return delta

    def forward(self, x):
        T = len(x)
        d = self.d_model
        scale = 1.0 / math.sqrt(d)
        h1, c1 = _norm_rows_forward(self.ln1, x)
        q, cq = _dense_rows_forward(self.Wq, h1)
        k, ck = _dense_rows_forward(self.Wk, h1)
        v, cv = _dense_rows_forward(self.Wv, h1)
        attn = [[0.0] * T for _ in range(T)]
        for t in range(T):
            row = [0.0] * T
            q_t = q[t]
            for j in range(t + 1):
                delta = self._bucket(t - j)
                rk = self.Rk[delta]
                rq = self.Rq[delta]
                k_j = k[j]
                cc = sum(q_t[i] * k_j[i] for i in range(d))
                cp = sum(q_t[i] * rk[i] for i in range(d))
                pc = sum(k_j[i] * rq[i] for i in range(d))
                row[j] = scale * (cc + cp + pc)
            for j in range(t + 1, T):
                row[j] = -1e30
            attn[t] = _softmax_row(row)
        v_mix = [[sum(attn[t][j] * v[j][i] for j in range(t + 1))
                  for i in range(d)] for t in range(T)]
        o_rows, co = _dense_rows_forward(self.Wo, v_mix)
        x1 = [[x[t][j] + o_rows[t][j] for j in range(d)] for t in range(T)]
        h2, c2 = _norm_rows_forward(self.ln2, x1)
        a2, ca2 = _dense_rows_forward(self.W1, h2)
        ffn, cf2 = _dense_rows_forward(self.W2, a2)
        out = [[x1[t][j] + ffn[t][j] for j in range(d)] for t in range(T)]
        self._cache = {"x": x, "h1": h1, "c1": c1, "q": q, "k": k, "v": v,
                       "cq": cq, "ck": ck, "cv": cv, "attn": attn,
                       "v_mix": v_mix, "co": co, "x1": x1, "c2": c2,
                       "ca2": ca2, "cf2": cf2}
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("DeBERTaBlock.backward: 必须先调用 forward()")
        c = self._cache
        T = len(dout)
        d = self.d_model
        scale = 1.0 / math.sqrt(d)

        gW2, gb2, d_a2 = _dense_rows_backward(self.W2, c["cf2"], dout)
        self.grad_W2 = (gW2, gb2)
        gW1, gb1, d_h2 = _dense_rows_backward(self.W1, c["ca2"], d_a2)
        self.grad_W1 = (gW1, gb1)
        g_ln2, b_ln2, d_x1_ln = _norm_rows_backward(self.ln2, c["c2"], d_h2)
        self.norm_grads["ln2"] = (g_ln2, b_ln2)
        d_x1 = [[dout[t][j] + d_x1_ln[t][j] for j in range(d)]
                for t in range(T)]

        gWo, gbo, d_vmix = _dense_rows_backward(self.Wo, c["co"], d_x1)
        self.grad_Wo = (gWo, gbo)

        attn = c["attn"]
        v = c["v"]
        q = c["q"]
        k = c["k"]
        dv = [[0.0] * d for _ in range(T)]
        dq = [[0.0] * d for _ in range(T)]
        dk = [[0.0] * d for _ in range(T)]
        for t in range(T):
            d_out = d_vmix[t]
            d_attn_row = [0.0] * T
            for j in range(t + 1):
                d_attn_row[j] = sum(d_out[i] * v[j][i] for i in range(d))
                for i in range(d):
                    dv[j][i] += attn[t][j] * d_out[i]
            dot = sum(attn[t][j] * d_attn_row[j] for j in range(t + 1))
            q_t = q[t]
            for j in range(t + 1):
                ds = attn[t][j] * (d_attn_row[j] - dot)
                delta = self._bucket(t - j)
                rk = self.Rk[delta]
                rq = self.Rq[delta]
                k_j = k[j]
                for i in range(d):
                    dq[t][i] += ds * scale * (k_j[i] + rk[i])
                    dk[j][i] += ds * scale * (q_t[i] + rq[i])
                    self.grad_Rk[delta][i] += ds * scale * q_t[i]
                    self.grad_Rq[delta][i] += ds * scale * k_j[i]

        gWq, gbq, d_h1a = _dense_rows_backward(self.Wq, c["cq"], dq)
        gWk, gbk, d_h1b = _dense_rows_backward(self.Wk, c["ck"], dk)
        gWv, gbv, d_h1c = _dense_rows_backward(self.Wv, c["cv"], dv)
        self.grad_Wq = (gWq, gbq)
        self.grad_Wk = (gWk, gbk)
        self.grad_Wv = (gWv, gbv)
        d_h1 = [[d_h1a[t][i] + d_h1b[t][i] + d_h1c[t][i] for i in range(d)]
                for t in range(T)]
        g_ln1, b_ln1, d_x_ln = _norm_rows_backward(self.ln1, c["c1"], d_h1)
        self.norm_grads["ln1"] = (g_ln1, b_ln1)
        return [[d_x1[t][j] + d_x_ln[t][j] for j in range(d)]
                for t in range(T)]

    def sgd_step(self, lr):
        for layer, grads in ((self.Wq, self.grad_Wq), (self.Wk, self.grad_Wk),
                             (self.Wv, self.grad_Wv), (self.Wo, self.grad_Wo),
                             (self.W1, self.grad_W1), (self.W2, self.grad_W2)):
            if grads is not None:
                _dense_apply_sgd(layer, grads, lr)
        for name, norm in (("ln1", self.ln1), ("ln2", self.ln2)):
            grads = self.norm_grads[name]
            if grads is not None:
                _norm_apply_sgd(norm, grads, lr)
        for b in range(self.n_rel):
            for i in range(self.d_model):
                self.Rk[b][i] -= lr * self.grad_Rk[b][i]
                self.Rq[b][i] -= lr * self.grad_Rq[b][i]

    def param_count(self):
        return (4 * _dense_param_count(self.Wq) + _dense_param_count(self.W1)
                + _dense_param_count(self.W2)
                + _norm_param_count(self.ln1) + _norm_param_count(self.ln2)
                + 2 * self.n_rel * self.d_model)


class DeBERTaModel:
    """DeBERTa 语言模型：Embedding → N×DeBERTaBlock → LayerNorm → 词表头"""

    def __init__(self, vocab_size, d_model=32, d_ff=None, num_layers=2,
                 max_len=64, max_rel=16, seed=None):
        if not isinstance(vocab_size, int) or isinstance(vocab_size, bool) or vocab_size < 1:
            raise ValueError(f"DeBERTaModel: vocab_size 必须是正整数，收到 {vocab_size!r}")
        if not isinstance(d_model, int) or isinstance(d_model, bool) or d_model < 1:
            raise ValueError(f"DeBERTaModel: d_model 必须是正整数，收到 {d_model!r}")
        if not isinstance(num_layers, int) or isinstance(num_layers, bool) or num_layers < 1:
            raise ValueError(f"DeBERTaModel: num_layers 必须是正整数，收到 {num_layers!r}")
        if not isinstance(max_len, int) or isinstance(max_len, bool) or max_len < 1:
            raise ValueError(f"DeBERTaModel: max_len 必须 >= 1，收到 {max_len!r}")
        if d_ff is not None and (not isinstance(d_ff, int)
                                 or isinstance(d_ff, bool) or d_ff < 1):
            raise ValueError(f"DeBERTaModel: d_ff 必须是正整数或 None，收到 {d_ff!r}")
        self.vocab_size = vocab_size
        self.d_model = d_model
        self.max_len = max_len
        self.max_rel = max_rel
        std = math.sqrt(2.0 / d_model)
        state = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self._emb = [[random.gauss(0.0, std) for _ in range(d_model)]
                         for _ in range(vocab_size)]
        finally:
            random.setstate(state)
        self._emb_grad = [[0.0] * d_model for _ in range(vocab_size)]
        self._last_ids = []
        self.blocks = [DeBERTaBlock(d_model, d_ff, max_rel=max_rel,
                                    seed=None if seed is None else seed + i)
                       for i in range(num_layers)]
        self.ln_out = LayerNorm(d_model)
        self.W_out = Layer(d_model, vocab_size, "linear")

    def zero_grad(self):
        for b in self.blocks:
            b.zero_grad()
        self.grad_W_out = None
        self.grad_ln_out = None
        for i in range(self.vocab_size):
            for j in range(self.d_model):
                self._emb_grad[i][j] = 0.0

    def train(self):
        return self

    def eval(self):
        return self

    def _check_ids(self, ids):
        ids = _check_token_ids(ids, self.vocab_size, "DeBERTaModel")
        if not ids:
            raise ValueError("DeBERTaModel: ids 不能为空")
        if len(ids) > self.max_len:
            raise ValueError(
                f"DeBERTaModel: 序列长度 {len(ids)} 超过 max_len={self.max_len}")
        return ids

    def _embed(self, ids):
        self._last_ids = ids
        return [list(self._emb[i]) for i in ids]

    def forward(self, ids):
        ids = self._check_ids(ids)
        x = self._embed(ids)
        for block in self.blocks:
            x = block.forward(x)
        h, _ = _norm_rows_forward(self.ln_out, x)
        logits, _ = _dense_rows_forward(self.W_out, h)
        return logits

    def _run_loss_and_backward(self, ids, targets):
        ids = self._check_ids(ids)
        T = len(ids)
        n_pred = T - 1
        x = self._embed(ids)
        for block in self.blocks:
            x = block.forward(x)
        h, c = _norm_rows_forward(self.ln_out, x)
        logits, head_cache = _dense_rows_forward(self.W_out, h)
        loss = 0.0
        dlogits = [[0.0] * self.vocab_size for _ in range(T)]
        for t in range(n_pred):
            target = targets[t]
            probs = _softmax_row(logits[t])
            loss += -math.log(probs[target] if probs[target] > 1e-12 else 1e-12)
            drow = dlogits[t]
            for v in range(self.vocab_size):
                drow[v] = probs[v] / n_pred
            drow[target] -= 1.0 / n_pred
        gW, gb, d_h = _dense_rows_backward(self.W_out, head_cache, dlogits)
        self.grad_W_out = (gW, gb)
        g_ln, b_ln, d_x = _norm_rows_backward(self.ln_out, c, d_h)
        self.grad_ln_out = (g_ln, b_ln)
        for block in reversed(self.blocks):
            d_x = block.backward(d_x)
        for t, i in enumerate(self._last_ids):
            for j in range(self.d_model):
                self._emb_grad[i][j] += d_x[t][j]
        return loss / n_pred

    def sgd_step(self, lr):
        for block in self.blocks:
            block.sgd_step(lr)
        if self.grad_W_out is not None:
            _dense_apply_sgd(self.W_out, self.grad_W_out, lr)
        if self.grad_ln_out is not None:
            _norm_apply_sgd(self.ln_out, self.grad_ln_out, lr)
        for i in range(self.vocab_size):
            for j in range(self.d_model):
                self._emb[i][j] -= lr * self._emb_grad[i][j]

    def param_count(self):
        total = self.vocab_size * self.d_model
        for block in self.blocks:
            total += block.param_count()
        total += _norm_param_count(self.ln_out)
        total += _dense_param_count(self.W_out)
        return total

    def fit(self, sequences, epochs=10, lr=0.01, shuffle=True, seed=None,
            verbose=False):
        if not isinstance(sequences, (list, tuple)) or not sequences:
            raise ValueError("DeBERTaModel.fit: sequences 不能为空")
        if not isinstance(epochs, int) or isinstance(epochs, bool) or epochs < 1:
            raise ValueError(f"DeBERTaModel.fit: epochs 必须是正整数，收到 {epochs!r}")
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) \
                or not math.isfinite(float(lr)) or lr <= 0.0:
            raise ValueError(f"DeBERTaModel.fit: lr 必须是正有限数，收到 {lr!r}")
        rng = random.Random(seed)
        history = []
        for ep in range(epochs):
            order = list(range(len(sequences)))
            if shuffle:
                rng.shuffle(order)
            total = 0.0
            for idx in order:
                seq = self._check_ids(list(sequences[idx]))
                if len(seq) < 2:
                    raise ValueError("DeBERTaModel.fit: 每条序列至少需要 2 个 token")
                self.zero_grad()
                total += self._run_loss_and_backward(seq, seq[1:])
                self.sgd_step(lr)
            avg = total / len(sequences)
            history.append(avg)
            if verbose:
                print(f"epoch {ep + 1}/{epochs} loss={avg:.4f}")
        return history

    def generate(self, prompt_ids, max_new_tokens=8, temperature=1.0,
                 top_k=None, seed=None):
        ids = self._check_ids(list(prompt_ids))
        if not isinstance(max_new_tokens, int) or isinstance(max_new_tokens, bool) \
                or max_new_tokens < 0:
            raise ValueError(
                f"DeBERTaModel.generate: max_new_tokens 必须是非负整数，收到 {max_new_tokens!r}")
        if isinstance(temperature, bool) or not isinstance(temperature, (int, float)) \
                or not math.isfinite(float(temperature)) or temperature <= 0.0:
            raise ValueError(
                f"DeBERTaModel.generate: temperature 必须是正有限数，收到 {temperature!r}")
        if top_k is not None and (not isinstance(top_k, int) or isinstance(top_k, bool)
                                  or top_k < 1):
            raise ValueError(
                f"DeBERTaModel.generate: top_k 必须是正整数或 None，收到 {top_k!r}")
        rng = random.Random(seed)
        out = list(ids)
        for _ in range(max_new_tokens):
            ctx = out[-self.max_len:] if len(out) > self.max_len else out
            logits = self.forward(ctx)
            probs = _softmax_row([v / temperature for v in logits[-1]])
            if top_k is not None:
                order = sorted(range(len(probs)), key=lambda i: probs[i],
                               reverse=True)[:top_k]
                keep = set(order)
                probs = [p if i in keep else 0.0 for i, p in enumerate(probs)]
                s = sum(probs)
                probs = [p / s for p in probs]
            r = rng.random()
            acc = 0.0
            pick = len(probs) - 1
            for i, p in enumerate(probs):
                acc += p
                if r <= acc:
                    pick = i
                    break
            out.append(pick)
        return out

# ============================================================================
#  DETR（DEtection TRansformer，简化版）
# ============================================================================


def _detr_log_softmax(row):
    """一行 logits 的 log-softmax（数值稳定）。"""
    m = max(row)
    total = sum(math.exp(v - m) for v in row)
    log_total = math.log(total) + m
    return [v - log_total for v in row]


def _detr_pos_2d(gh, gw, d_model):
    """二维正弦位置编码：前一半通道编码列、后一半编码行。"""
    if d_model % 4 != 0:
        raise ValueError("DETR: d_model 必须是 4 的倍数，才能做二维正弦位置编码")
    half = d_model // 2
    quarter = half // 2
    divs = [10000.0 ** (2.0 * i / quarter) for i in range(quarter)]
    vecs = []
    for r in range(gh):
        for c in range(gw):
            vec = []
            for div in divs:
                vec.append(math.sin(c / div))
                vec.append(math.cos(c / div))
            for div in divs:
                vec.append(math.sin(r / div))
                vec.append(math.cos(r / div))
            vecs.append(vec)
    return vecs


def _detr_hungarian(cost):
    """暴力匈牙利匹配（query 数很少时够用）。

    返回 [(query_index, target_index), ...]，每个 target 恰好匹配一个 query。
    """
    qn = len(cost)
    tn = len(cost[0]) if qn else 0
    if qn == 0 or tn == 0:
        return []
    if tn > qn:
        raise ValueError(
            f"DETR 匹配: target 数 {tn} 多于 query 数 {qn}（每个 target 必须匹配一个 query）"
        )
    best = None
    best_pairs = None
    # 从 qn 个 query 中选 tn 个并排列（tn 通常 1~4，qn 也小）
    for perm in itertools.permutations(range(qn), tn):
        total = sum(cost[perm[g]][g] for g in range(tn))
        if best is None or total < best:
            best = total
            best_pairs = [(perm[g], g) for g in range(tn)]
    return best_pairs


class DETR:
    """简化版 DETR：小 CNN backbone + Transformer encoder-decoder + 集合预测头。"""

    def __init__(self, in_channels: int = 3, num_classes: int = 10,
                 image_size: int = 8, d_model: int = 32,
                 num_heads: int = 4, d_ff: int = 64,
                 num_layers: int = 1, num_queries: int = 100,
                 seed=None):
        if not isinstance(in_channels, int) or in_channels <= 0:
            raise ValueError("DETR: in_channels 必须是正整数")
        if not isinstance(num_classes, int) or num_classes <= 0:
            raise ValueError("DETR: num_classes 必须是正整数")
        if not isinstance(image_size, int) or image_size <= 0:
            raise ValueError("DETR: image_size 必须是正整数")
        if image_size % 4 != 0:
            raise ValueError("DETR: image_size 必须能被 4 整除（backbone 有两次 stride=2）")
        for name, value in (("d_model", d_model), ("num_heads", num_heads),
                            ("d_ff", d_ff), ("num_layers", num_layers),
                            ("num_queries", num_queries)):
            if not isinstance(value, int) or value <= 0:
                raise ValueError(f"DETR: {name} 必须是正整数")
        if d_model % 4 != 0:
            raise ValueError("DETR: d_model 必须是 4 的倍数（二维位置编码）")
        if d_model % num_heads != 0:
            raise ValueError("DETR: d_model 必须能被 num_heads 整除")

        if seed is not None:
            random.seed(seed)
        self.in_channels = in_channels
        self.num_classes = num_classes
        self.image_size = image_size
        self.d_model = d_model
        self.num_heads = num_heads
        self.d_ff = d_ff
        self.num_layers = num_layers
        self.num_queries = num_queries
        self.grid_h = image_size // 4
        self.grid_w = image_size // 4
        self.seq_len = self.grid_h * self.grid_w

        hidden = max(4, d_model // 2)
        self.conv1 = Conv2d(in_channels, hidden, 3, stride=2, padding=1)
        self.conv2 = Conv2d(hidden, d_model, 3, stride=2, padding=1)

        self.pos2d = _detr_pos_2d(self.grid_h, self.grid_w, d_model)

        self.encoder = TransformerEncoder(
            d_model, num_heads, d_ff, num_layers, dropout=0.0, causal=False)
        self.decoder = TransformerDecoder(
            d_model, num_heads, d_ff, num_layers, dropout=0.0, causal=False)

        std = math.sqrt(2.0 / d_model)
        self.queries = [[random.gauss(0.0, std) for _ in range(d_model)]
                        for _ in range(num_queries)]
        self.query_pos = [[0.0] * d_model for _ in range(num_queries)]
        self.grad_queries = [[0.0] * d_model for _ in range(num_queries)]
        self.grad_query_pos = [[0.0] * d_model for _ in range(num_queries)]

        self.cls_head = Layer(d_model, num_classes + 1, "linear")
        self.box_head = Layer(d_model, 4, "linear")
        self.grad_cls_head = None
        self.grad_box_head = None

        self._cache = None

    # ---------- 基础工具 ----------

    def _zero_grads(self):
        self.conv1.zero_grad()
        self.conv2.zero_grad()
        self.encoder.zero_grad()
        self.decoder.zero_grad()
        self.grad_queries = [[0.0] * self.d_model for _ in range(self.num_queries)]
        self.grad_query_pos = [[0.0] * self.d_model for _ in range(self.num_queries)]
        self.grad_cls_head = None
        self.grad_box_head = None

    def _check_image(self, image):
        if not isinstance(image, (list, tuple)) or len(image) != self.in_channels:
            raise ValueError(
                f"DETR: 图像必须是 {self.in_channels} 通道的 (C,H,W) 列表")
        h, w = len(image[0]), len(image[0][0])
        if h != self.image_size or w != self.image_size:
            raise ValueError(
                f"DETR: 图像尺寸必须是 {self.image_size}×{self.image_size}，"
                f"收到 {h}×{w}")
        for c in range(self.in_channels):
            if len(image[c]) != h:
                raise ValueError("DETR: 图像通道高度不一致")
            for row in image[c]:
                if len(row) != w:
                    raise ValueError("DETR: 图像行宽度不一致")
                for v in row:
                    if not isinstance(v, (int, float)) or isinstance(v, bool):
                        raise ValueError("DETR: 图像像素必须是数字")

    def _check_targets(self, targets):
        if not self.in_channels:
            raise ValueError("DETR: 未初始化")
        if not isinstance(targets, (list, tuple)):
            raise ValueError("DETR: targets 必须是 [(label, [cx,cy,w,h]), ...] 列表")
        out = []
        for item in targets:
            if not isinstance(item, (list, tuple)):
                raise ValueError("DETR: 每个 target 必须是 (label, [cx,cy,w,h])")
            if len(item) != 2:
                raise ValueError("DETR: target 必须是 (label, box) 二元组")
            label, box = item
            if not isinstance(label, int) or isinstance(label, bool):
                raise ValueError(f"DETR: target label 必须是 int，收到 {label!r}")
            if label < 0 or label >= self.num_classes:
                raise ValueError(
                    f"DETR: target label 必须在 [0,{self.num_classes})，收到 {label}")
            if not isinstance(box, (list, tuple)) or len(box) != 4:
                raise ValueError("DETR: target box 必须是 [cx,cy,w,h] 四元组")
            vals = []
            for v in box:
                if not isinstance(v, (int, float)) or isinstance(v, bool) or not math.isfinite(v):
                    raise ValueError("DETR: target box 必须是有限数字")
                vals.append(float(v))
            cx, cy, bw, bh = vals
            if not (0.0 <= cx <= 1.0 and 0.0 <= cy <= 1.0):
                raise ValueError("DETR: target 中心点必须在 [0,1]")
            if bw <= 0.0 or bh <= 0.0:
                raise ValueError("DETR: target 宽高必须为正")
            if cx - bw / 2 < -1e-9 or cx + bw / 2 > 1.0 + 1e-9:
                raise ValueError("DETR: target 框越出图像边界")
            if cy - bh / 2 < -1e-9 or cy + bh / 2 > 1.0 + 1e-9:
                raise ValueError("DETR: target 框越出图像边界")
            out.append((label, [cx, cy, bw, bh]))
        return out

    @staticmethod
    def _sigmoid(v):
        if v >= 0:
            return 1.0 / (1.0 + math.exp(-v))
        e = math.exp(v)
        return e / (1.0 + e)

    @staticmethod
    def _l1_box(pred, target):
        return sum(abs(pred[i] - target[i]) for i in range(4))

    # ---------- 前向 ----------

    def _forward_single(self, image):
        """单张图前向，返回 cache（供损失与反向使用）。"""
        self._check_image(image)
        out1 = self.conv1.forward(image)
        mask1 = [[[1.0 if v > 0.0 else 0.0 for v in row] for row in ch]
                 for ch in out1]
        a1 = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in out1]
        out2 = self.conv2.forward(a1)
        mask2 = [[[1.0 if v > 0.0 else 0.0 for v in row] for row in ch]
                 for ch in out2]
        a2 = [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in out2]

        tokens = []
        for r in range(self.grid_h):
            for c in range(self.grid_w):
                tokens.append([a2[k][r][c] for k in range(self.d_model)])
        mem_in = [[tokens[t][k] + self.pos2d[t][k] for k in range(self.d_model)]
                  for t in range(self.seq_len)]
        memory = self.encoder.forward(mem_in)

        q_in = [[self.queries[i][k] + self.query_pos[i][k]
                 for k in range(self.d_model)] for i in range(self.num_queries)]
        dec_out = self.decoder.forward(q_in, memory)

        cls_logits, cls_cache = _dense_rows_forward(self.cls_head, dec_out)
        box_raw, box_cache = _dense_rows_forward(self.box_head, dec_out)
        probs = []
        boxes = []
        for i in range(self.num_queries):
            row = [self._sigmoid(v) for v in box_raw[i]]
            boxes.append(row)
            probs.append([math.exp(v) for v in _detr_log_softmax(cls_logits[i])])
        cache = {
            "image": image, "out1": out1, "mask1": mask1,
            "out2": out2, "mask2": mask2,
            "tokens": tokens, "mem_in": mem_in, "memory": memory,
            "q_in": q_in, "dec_out": dec_out,
            "cls_logits": cls_logits, "cls_cache": cls_cache,
            "box_raw": box_raw, "box_cache": box_cache,
            "boxes": boxes, "probs": probs,
        }
        self._cache = cache
        return cache

    def forward(self, images):
        """前向若干图像，返回每张图的 {probs, boxes}。"""
        if not isinstance(images, (list, tuple)) or not images:
            raise ValueError("DETR.forward: images 必须是非空列表")
        out = []
        for image in images:
            cache = self._forward_single(image)
            out.append({"probs": cache["probs"], "boxes": cache["boxes"]})
        return out

    # ---------- 损失与反向 ----------

    def _loss_and_grads_single(self, image, targets):
        """单图前向 + 匈牙利匹配 + 损失，反传并累积梯度；返回 (loss, 匹配信息)。"""
        targets = self._check_targets(targets)
        cache = self._forward_single(image)
        nq = self.num_queries
        nc = self.num_classes
        cls_logits = cache["cls_logits"]
        log_probs = [_detr_log_softmax(row) for row in cls_logits]
        probs = [[math.exp(v) for v in row] for row in log_probs]
        boxes = cache["boxes"]

        # 匹配代价：目标类 NLL + L1 框距离
        cost = [[0.0] * len(targets) for _ in range(nq)]
        for i in range(nq):
            for g, (label, box) in enumerate(targets):
                cost[i][g] = -log_probs[i][label] + self._l1_box(boxes[i], box)
        pairs = _detr_hungarian(cost) if targets else []
        matched_query = {qi: ti for qi, ti in pairs}

        cls_loss = 0.0
        d_cls = [[0.0] * (nc + 1) for _ in range(nq)]
        for i in range(nq):
            if i in matched_query:
                g = matched_query[i]
                label = targets[g][0]
                cls_loss += -log_probs[i][label]
                for c in range(nc + 1):
                    d_cls[i][c] = probs[i][c]
                d_cls[i][label] -= 1.0
            else:
                cls_loss += -log_probs[i][nc]
                for c in range(nc + 1):
                    d_cls[i][c] = probs[i][c]
                d_cls[i][nc] -= 1.0
        cls_loss /= nq
        for i in range(nq):
            for c in range(nc + 1):
                d_cls[i][c] /= nq

        box_loss = 0.0
        d_box_raw = [[0.0] * 4 for _ in range(nq)]
        if pairs:
            for i, g in pairs:
                label, target_box = targets[g]
                box_loss += self._l1_box(boxes[i], target_box)
            box_loss = 5.0 * box_loss / len(pairs)
            for i, g in pairs:
                target_box = targets[g][1]
                raw = cache["box_raw"][i]
                for k in range(4):
                    sig = boxes[i][k]
                    diff = 1.0 if boxes[i][k] > target_box[k] else -1.0
                    if abs(boxes[i][k] - target_box[k]) <= 1e-12:
                        diff = 0.0
                    d_box_raw[i][k] = (5.0 / len(pairs)) * diff * sig * (1.0 - sig)

        loss = cls_loss + box_loss

        gw_cls, gb_cls, dx_cls = _dense_rows_backward(
            self.cls_head, cache["cls_cache"], d_cls)
        gw_box, gb_box, dx_box = _dense_rows_backward(
            self.box_head, cache["box_cache"], d_box_raw)

        if self.grad_cls_head is None:
            self.grad_cls_head = (gw_cls, gb_cls)
            self.grad_box_head = (gw_box, gb_box)
        else:
            for i in range(len(gw_cls)):
                for j in range(len(gw_cls[i])):
                    self.grad_cls_head[0][i][j] += gw_cls[i][j]
                self.grad_cls_head[1][i] += gb_cls[i]
            for i in range(len(gw_box)):
                for j in range(len(gw_box[i])):
                    self.grad_box_head[0][i][j] += gw_box[i][j]
                self.grad_box_head[1][i] += gb_box[i]

        d_out = [[dx_cls[i][k] + dx_box[i][k] for k in range(self.d_model)]
                 for i in range(nq)]
        d_q, d_memory = self.decoder.backward(d_out)
        d_mem_in = self.encoder.backward(d_memory)

        for i in range(nq):
            for k in range(self.d_model):
                self.grad_queries[i][k] += d_q[i][k]
                self.grad_query_pos[i][k] += d_q[i][k]

        d_tokens = d_mem_in  # pos2d 是常量
        d_grid = [[[0.0] * self.grid_w for _ in range(self.grid_h)]
                  for _ in range(self.d_model)]
        for t in range(self.seq_len):
            r, c = divmod(t, self.grid_w)
            for k in range(self.d_model):
                d_grid[k][r][c] = d_tokens[t][k]
        d_a1 = self.conv2.backward(
            [[[d_grid[k][r][c] * cache["mask2"][k][r][c]
               for c in range(self.grid_w)] for r in range(self.grid_h)]
             for k in range(self.d_model)])
        d_img = self.conv1.backward(
            [[[d_a1[k][r][c] * cache["mask1"][k][r][c]
               for c in range(len(d_a1[0][0]))] for r in range(len(d_a1[0]))]
             for k in range(len(d_a1))])
        return loss, {"pairs": pairs, "boxes": boxes, "probs": probs,
                      "d_img": d_img}

    def loss_and_backward(self, images, targets):
        """批量损失并累积梯度；返回 {"loss","pairs"}。"""
        if not isinstance(images, (list, tuple)) or not images:
            raise ValueError("DETR.loss_and_backward: images 必须是非空列表")
        if not isinstance(targets, (list, tuple)) or len(targets) != len(images):
            raise ValueError("DETR.loss_and_backward: targets 必须与 images 等长")
        total = 0.0
        all_pairs = []
        for image, tgt in zip(images, targets):
            loss, info = self._loss_and_grads_single(image, tgt)
            total += loss
            all_pairs.append(info["pairs"])
        total /= len(images)
        return {"loss": total, "pairs": all_pairs}

    # ---------- 训练 ----------

    def _sgd_step(self, lr):
        _conv_sgd(self.conv1, lr)
        _conv_sgd(self.conv2, lr)
        self.encoder.sgd_step(lr)
        self.decoder.sgd_step(lr)
        _dense_apply_sgd(self.cls_head, self.grad_cls_head, lr)
        _dense_apply_sgd(self.box_head, self.grad_box_head, lr)
        for i in range(self.num_queries):
            for k in range(self.d_model):
                self.queries[i][k] -= lr * self.grad_queries[i][k]
                self.query_pos[i][k] -= lr * self.grad_query_pos[i][k]

    def fit(self, images, targets, epochs=30, lr=0.01, shuffle=True, seed=None):
        """小批量单样本训练；返回每 epoch 平均损失列表。"""
        if not isinstance(images, (list, tuple)) or not images:
            raise ValueError("DETR.fit: images 必须是非空列表")
        if not isinstance(targets, (list, tuple)) or len(targets) != len(images):
            raise ValueError("DETR.fit: targets 必须与 images 等长")
        if not isinstance(epochs, int) or epochs <= 0:
            raise ValueError("DETR.fit: epochs 必须是正整数")
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr <= 0:
            raise ValueError("DETR.fit: lr 必须是正数")
        rng = random.Random(seed)
        order = list(range(len(images)))
        history = []
        for _ in range(epochs):
            if shuffle:
                rng.shuffle(order)
            total = 0.0
            for idx in order:
                self._zero_grads()
                out = self.loss_and_backward([images[idx]], [targets[idx]])
                total += out["loss"]
                self._sgd_step(lr)
            history.append(total / len(images))
        return history

    def predict(self, images):
        """返回每张图 query 的类别概率与框（不做 NMS）。"""
        return self.forward(images)

    def param_count(self):
        d = self.d_model
        ff = self.d_ff
        enc_layer = 4 * d * d + 9 * d + 2 * d * ff + ff
        dec_layer = 8 * d * d + 15 * d + 2 * d * ff + ff
        total = (_conv_param_count(self.conv1) + _conv_param_count(self.conv2)
                 + self.num_layers * (enc_layer + dec_layer)
                 + _dense_param_count(self.cls_head)
                 + _dense_param_count(self.box_head)
                 + 2 * self.num_queries * d)
        return total
# ============================================================================
#  离线强化学习：IQL / CQL（离散动作，基于 ReplayBuffer 的静态数据集）
# ============================================================================
#  说明：
#  - 两者都面向「离线数据集」：Q 网络只从 ReplayBuffer 里采样更新，不做在线探索。
#  - IQL（Implicit Q-Learning）：不做 max 查询，用 expectile 回归拟合 V(s)，
#    再用 AWR 权重做策略提取，避免 OOD 动作被高估。
#  - CQL（Conservative Q-Learning）：在 TD 损失之外加保守项
#    alpha * (logsumexp_a Q(s,a) - Q(s, a_data))，压低数据集外动作的 Q 值。
#  - 复用现有 PolicyNetwork（离散 Q / 策略）与 ValueNetwork（V），
#    优化器用现有 Adam（按层 zip 更新）。


def _offline_zeros_like(model):
    """为 MLP 的每层生成 (grad_w, grad_b) 零梯度。"""
    zeros = []
    for layer in model.layers:
        gw = [[0.0] * layer.fan_in for _ in range(layer.fan_out)]
        gb = [0.0] * layer.fan_out
        zeros.append((gw, gb))
    return zeros


def _offline_accumulate(acc, grads):
    """把单样本梯度累加进累加器。"""
    for li, (gw, gb) in enumerate(grads):
        acc_w, acc_b = acc[li]
        for j in range(len(gw)):
            row = acc_w[j]
            for k in range(len(gw[j])):
                row[k] += gw[j][k]
            acc_b[j] += gb[j]


def _offline_average(acc, n):
    """累加器求平均，返回可直接喂给 Adam.step 的结构。"""
    inv = 1.0 / n
    out = []
    for gw, gb in acc:
        out.append(([[v * inv for v in row] for row in gw],
                    [v * inv for v in gb]))
    return out


def _offline_softmax(row):
    """数值稳定 softmax。"""
    m = max(row)
    ex = [math.exp(v - m) for v in row]
    s = sum(ex)
    return [v / s for v in ex]


def _offline_soft_update(target, source, tau):
    """目标网络软更新：target = tau*target + (1-tau)*source。"""
    for tl, sl in zip(target.model.layers, source.model.layers):
        for j in range(tl.fan_out):
            tw = tl.weights[j]
            sw = sl.weights[j]
            for i in range(tl.fan_in):
                tw[i] = tau * tw[i] + (1.0 - tau) * sw[i]
            tl.biases[j] = tau * tl.biases[j] + (1.0 - tau) * sl.biases[j]


def _offline_check_int(value, name, low, high=None):
    if not isinstance(value, int) or isinstance(value, bool):
        raise ValueError(f"{name} 必须是整数，收到 {value!r}")
    if value < low or (high is not None and value > high):
        bound = f"[{low}, {high}]" if high is not None else f">= {low}"
        raise ValueError(f"{name} 必须在 {bound}，收到 {value}")


def _offline_check_float(value, name, low, high, low_open=False, high_open=False):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{name} 必须是数字，收到 {value!r}")
    v = float(value)
    if not math.isfinite(v):
        raise ValueError(f"{name} 必须是有限数字，收到 {value!r}")
    if low_open and not (v > low):
        raise ValueError(f"{name} 必须 > {low}，收到 {value!r}")
    if not low_open and v < low:
        raise ValueError(f"{name} 必须 >= {low}，收到 {value!r}")
    if high_open and not (v < high):
        raise ValueError(f"{name} 必须 < {high}，收到 {value!r}")
    if high is not None and not high_open and v > high:
        raise ValueError(f"{name} 必须 <= {high}，收到 {value!r}")


class IQLAgent:
    """IQL：expectile V + 无 max 的 Q 回归 + AWR 策略提取（离散动作）。"""

    def __init__(self, state_dim, num_actions, hidden=(32,), actor_lr=1e-3,
                 critic_lr=1e-3, tau=0.7, beta=3.0, gamma=0.99,
                 target_tau=0.005, seed=None):
        _offline_check_int(state_dim, "IQLAgent: state_dim", 1)
        _offline_check_int(num_actions, "IQLAgent: num_actions", 1)
        _offline_check_float(actor_lr, "IQLAgent: actor_lr", 0.0, None, low_open=True)
        _offline_check_float(critic_lr, "IQLAgent: critic_lr", 0.0, None, low_open=True)
        _offline_check_float(tau, "IQLAgent: tau", 0.0, 1.0, low_open=True, high_open=True)
        _offline_check_float(beta, "IQLAgent: beta", 0.0, None, low_open=True)
        _offline_check_float(gamma, "IQLAgent: gamma", 0.0, 1.0)
        _offline_check_float(target_tau, "IQLAgent: target_tau", 0.0, 1.0,
                             low_open=True, high_open=True)
        for v in list(hidden):
            _offline_check_int(v, "IQLAgent: hidden 元素", 1)
        self.state_dim = state_dim
        self.num_actions = num_actions
        self.tau = float(tau)
        self.beta = float(beta)
        self.gamma = float(gamma)
        self.target_tau = float(target_tau)

        self.q = PolicyNetwork(state_dim, num_actions, hidden, seed=seed)
        self.q_target = PolicyNetwork(state_dim, num_actions, hidden, seed=seed)
        self.q_target.copy_from(self.q)
        self.v = ValueNetwork(state_dim, hidden, seed=seed)
        self.v_target = ValueNetwork(state_dim, hidden, seed=seed)
        self.v_target.copy_from(self.v)
        self.policy = PolicyNetwork(state_dim, num_actions, hidden, seed=seed)

        self.q_opt = Adam(self.q.model, lr=critic_lr)
        self.v_opt = Adam(self.v.model, lr=critic_lr)
        self.policy_opt = Adam(self.policy.model, lr=actor_lr)

    def update(self, states, actions, rewards, next_states, dones):
        """对一批转移做一次 IQL 更新，返回损失字典。"""
        n = len(states)
        if n < 1:
            raise ValueError("IQLAgent.update: 批次不能为空")
        for name, seq in (("actions", actions), ("rewards", rewards),
                          ("next_states", next_states), ("dones", dones)):
            if len(seq) != n:
                raise ValueError(f"IQLAgent.update: {name} 长度必须与 states 一致")
        q_acc = _offline_zeros_like(self.q.model)
        v_acc = _offline_zeros_like(self.v.model)
        pi_acc = _offline_zeros_like(self.policy.model)
        q_loss = v_loss = pi_loss = 0.0
        for i in range(n):
            s = list(states[i])
            sp = list(next_states[i])
            a = actions[i]
            _offline_check_int(a, "IQLAgent.update: action", 0, self.num_actions - 1)
            r = float(rewards[i])
            d = bool(dones[i])

            qs = self.q.logits(s)
            q_a = qs[a]
            v = self.v.value(s)

            # V 的 expectile 回归：Q(s,a) 为回归目标，按误差符号加权
            diff = q_a - v
            w = self.tau if diff > 0.0 else (1.0 - self.tau)
            v_loss += w * diff * diff / n
            v_grads = self.v.gradients(-2.0 * w * diff / n)
            _offline_accumulate(v_acc, v_grads)

            # Q 的 TD 目标使用 V_target(s')（IQL 不做 max）
            if d:
                y = r
            else:
                y = r + self.gamma * self.v_target.value(sp)
            q_loss += (q_a - y) * (q_a - y) / n
            dq = [0.0] * self.num_actions
            dq[a] = 2.0 * (q_a - y) / n
            q_grads = self.q.gradients(dq)
            _offline_accumulate(q_acc, q_grads)

            # 策略提取：AWR 加权行为克隆（优势 = Q(s,a) - V(s)）
            adv = q_a - v
            weight = math.exp(min(self.beta * adv, 30.0))
            probs = self.policy.probs(s)
            pi_loss += -weight * math.log(max(probs[a], 1e-12)) / n
            dlogits = [0.0] * self.num_actions
            for j in range(self.num_actions):
                target = 1.0 if j == a else 0.0
                dlogits[j] = weight * (probs[j] - target) / n
            pi_grads = self.policy.gradients(dlogits)
            _offline_accumulate(pi_acc, pi_grads)

        self.v_opt.step(_offline_average(v_acc, n))
        self.q_opt.step(_offline_average(q_acc, n))
        self.policy_opt.step(_offline_average(pi_acc, n))
        _offline_soft_update(self.q_target, self.q, self.target_tau)
        _offline_soft_update(self.v_target, self.v, self.target_tau)
        return {"q_loss": q_loss, "v_loss": v_loss, "policy_loss": pi_loss}

    def fit(self, buffer, steps=100, batch_size=32):
        """从 ReplayBuffer 采样并更新 ``steps`` 轮，返回最后一轮统计。"""
        _offline_check_int(steps, "IQLAgent.fit: steps", 1)
        _offline_check_int(batch_size, "IQLAgent.fit: batch_size", 1)
        if len(buffer) < 1:
            raise ValueError("IQLAgent.fit: ReplayBuffer 不能为空")
        last = None
        for _ in range(steps):
            batch = buffer.sample(batch_size)
            last = self.update(*batch)
        return last

    def act(self, state):
        """贪心动作（用策略网络）。"""
        probs = self.policy.probs(state)
        return max(range(self.num_actions), key=lambda j: probs[j])

    def param_count(self):
        return (self.q.param_count() + self.q_target.param_count()
                + self.v.param_count() + self.v_target.param_count()
                + self.policy.param_count())


class CQLAgent:
    """CQL：TD 损失 + 保守项 alpha*(logsumexp Q - Q(s,a)) 的离线策略学习。"""

    def __init__(self, state_dim, num_actions, hidden=(32,), actor_lr=1e-3,
                 critic_lr=1e-3, alpha=0.5, beta=3.0, gamma=0.99,
                 target_tau=0.005, seed=None):
        _offline_check_int(state_dim, "CQLAgent: state_dim", 1)
        _offline_check_int(num_actions, "CQLAgent: num_actions", 1)
        _offline_check_float(actor_lr, "CQLAgent: actor_lr", 0.0, None, low_open=True)
        _offline_check_float(critic_lr, "CQLAgent: critic_lr", 0.0, None, low_open=True)
        _offline_check_float(alpha, "CQLAgent: alpha", 0.0, None)
        _offline_check_float(beta, "CQLAgent: beta", 0.0, None, low_open=True)
        _offline_check_float(gamma, "CQLAgent: gamma", 0.0, 1.0)
        _offline_check_float(target_tau, "CQLAgent: target_tau", 0.0, 1.0,
                             low_open=True, high_open=True)
        for v in list(hidden):
            _offline_check_int(v, "CQLAgent: hidden 元素", 1)
        self.state_dim = state_dim
        self.num_actions = num_actions
        self.alpha = float(alpha)
        self.beta = float(beta)
        self.gamma = float(gamma)
        self.target_tau = float(target_tau)

        self.q = PolicyNetwork(state_dim, num_actions, hidden, seed=seed)
        self.q_target = PolicyNetwork(state_dim, num_actions, hidden, seed=seed)
        self.q_target.copy_from(self.q)
        self.policy = PolicyNetwork(state_dim, num_actions, hidden, seed=seed)
        self.q_opt = Adam(self.q.model, lr=critic_lr)
        self.policy_opt = Adam(self.policy.model, lr=actor_lr)

    def update(self, states, actions, rewards, next_states, dones):
        n = len(states)
        if n < 1:
            raise ValueError("CQLAgent.update: 批次不能为空")
        for name, seq in (("actions", actions), ("rewards", rewards),
                          ("next_states", next_states), ("dones", dones)):
            if len(seq) != n:
                raise ValueError(f"CQLAgent.update: {name} 长度必须与 states 一致")
        q_acc = _offline_zeros_like(self.q.model)
        pi_acc = _offline_zeros_like(self.policy.model)
        q_loss = pi_loss = 0.0
        for i in range(n):
            s = list(states[i])
            sp = list(next_states[i])
            a = actions[i]
            _offline_check_int(a, "CQLAgent.update: action", 0, self.num_actions - 1)
            r = float(rewards[i])
            d = bool(dones[i])

            qs = self.q.logits(s)
            q_a = qs[a]
            q_next = self.q_target.logits(sp)
            y = r if d else r + self.gamma * max(q_next)
            probs_q = _offline_softmax(qs)
            m = max(qs)
            lse = m + math.log(sum(math.exp(v - m) for v in qs))
            q_loss += (q_a - y) * (q_a - y) / n + self.alpha * (lse - q_a) / n
            dq = [self.alpha * (probs_q[j] - (1.0 if j == a else 0.0)) / n
                  for j in range(self.num_actions)]
            dq[a] += 2.0 * (q_a - y) / n
            q_grads = self.q.gradients(dq)
            _offline_accumulate(q_acc, q_grads)

            adv = q_a - lse
            weight = math.exp(min(self.beta * adv, 30.0))
            probs = self.policy.probs(s)
            pi_loss += -weight * math.log(max(probs[a], 1e-12)) / n
            dlogits = [0.0] * self.num_actions
            for j in range(self.num_actions):
                target = 1.0 if j == a else 0.0
                dlogits[j] = weight * (probs[j] - target) / n
            pi_grads = self.policy.gradients(dlogits)
            _offline_accumulate(pi_acc, pi_grads)

        self.q_opt.step(_offline_average(q_acc, n))
        self.policy_opt.step(_offline_average(pi_acc, n))
        _offline_soft_update(self.q_target, self.q, self.target_tau)
        return {"q_loss": q_loss, "policy_loss": pi_loss}

    def fit(self, buffer, steps=100, batch_size=32):
        _offline_check_int(steps, "CQLAgent.fit: steps", 1)
        _offline_check_int(batch_size, "CQLAgent.fit: batch_size", 1)
        if len(buffer) < 1:
            raise ValueError("CQLAgent.fit: ReplayBuffer 不能为空")
        last = None
        for _ in range(steps):
            batch = buffer.sample(batch_size)
            last = self.update(*batch)
        return last

    def act(self, state):
        """贪心动作（直接取 Q 的最大值）。"""
        qs = self.q.logits(state)
        return max(range(self.num_actions), key=lambda j: qs[j])

    def param_count(self):
        return (self.q.param_count() + self.q_target.param_count()
                + self.policy.param_count())

# ============================================================================
#  E(3) 等变图神经网络（EGNN，教学版）
# ============================================================================
#  说明：
#  - 输入是一张全连接图：节点特征 h（N×d，平移/旋转不变）与坐标 x（N×3，
#    平移/旋转等变）。
#  - 每条边 (i, j) 的特征是 [h_i, h_j, ||x_i - x_j||²]（距离平方，旋转不变），
#    经 phi_e 得到边消息 e_ij；phi_x(e_ij) 给出坐标更新系数 w_ij；
#    phi_h([h_i, Σ_j e_ij]) 给出节点特征更新。
#  - 坐标更新 x_i' = x_i + Σ_j w_ij·(x_i - x_j) 对旋转/平移严格等变，
#    节点特征 h_i' = h_i + phi_h([h_i, m_i]) 对旋转/平移严格不变。
#  - 反向传播手写：对 phi_e / phi_x / phi_h 用行级工具反传，同时给出
#    dh / dx，用于梯度校验与训练。


def _e3_mlp_forward(model, rows):
    """按行前向 MLP，返回 (输出行, 每层 cache)。"""
    acts = [list(row) for row in rows]
    caches = []
    for layer in model.layers:
        acts, cache = _dense_rows_forward(layer, acts)
        caches.append(cache)
    return acts, caches


def _e3_mlp_backward(model, caches, drows):
    """按行反向 MLP，返回 (每层 (grad_w, grad_b), 输入行梯度)。"""
    d_rows = drows
    grads = [None] * len(model.layers)
    for idx in range(len(model.layers) - 1, -1, -1):
        gw, gb, d_rows = _dense_rows_backward(
            model.layers[idx], caches[idx], d_rows)
        grads[idx] = (gw, gb)
    return grads, d_rows


def _e3_zeros_like(model):
    out = []
    for layer in model.layers:
        out.append(([[0.0] * layer.fan_in for _ in range(layer.fan_out)],
                    [0.0] * layer.fan_out))
    return out


def _e3_accumulate(acc, grads):
    for li, (gw, gb) in enumerate(grads):
        acc_w, acc_b = acc[li]
        for j in range(len(gw)):
            row = acc_w[j]
            for k in range(len(gw[j])):
                row[k] += gw[j][k]
            acc_b[j] += gb[j]


def _e3_average(acc, n):
    inv = 1.0 / n
    return [([[v * inv for v in row] for row in gw],
             [v * inv for v in gb]) for gw, gb in acc]


def _e3_apply_sgd(model, grads, lr):
    for layer, (gw, gb) in zip(model.layers, grads):
        for j in range(layer.fan_out):
            w = layer.weights[j]
            g = gw[j]
            for i in range(layer.fan_in):
                w[i] -= lr * g[i]
            layer.biases[j] -= lr * gb[j]


def _e3_param_count(model):
    return sum(layer.fan_in * layer.fan_out + layer.fan_out
               for layer in model.layers)


def _e3_check_matrix(rows, name, width=None):
    if not isinstance(rows, (list, tuple)) or not rows:
        raise ValueError(f"{name} 必须是非空行列表")
    out = []
    for r in rows:
        if not isinstance(r, (list, tuple)) or not r:
            raise ValueError(f"{name} 的每一行必须是非空列表")
        row = []
        for v in r:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f"{name} 的元素必须是数字，收到 {v!r}")
            fv = float(v)
            if not math.isfinite(fv):
                raise ValueError(f"{name} 的元素必须是有限数，收到 {v!r}")
            row.append(fv)
        if width is not None and len(row) != width:
            raise ValueError(f"{name} 的列数必须是 {width}，收到 {len(row)}")
        out.append(row)
    return out


def _e3_make_mlp(sizes, activations, seed):
    """构造 MLP；给定 seed 时临时替换全局 random 状态，构造后恢复。"""
    if seed is None:
        return MLP(sizes, activations)
    state = random.getstate()
    random.seed(seed)
    try:
        return MLP(sizes, activations)
    finally:
        random.setstate(state)


class EGNNLayer:
    """一层 E(3) 等变图卷积（全连接图）。"""

    def __init__(self, d_model, d_ff=None, seed=None):
        if isinstance(d_model, bool) or not isinstance(d_model, int) or d_model < 1:
            raise ValueError(f"EGNNLayer: d_model 必须是 >=1 的整数，收到 {d_model!r}")
        if d_ff is None:
            d_ff = 2 * d_model
        if isinstance(d_ff, bool) or not isinstance(d_ff, int) or d_ff < 1:
            raise ValueError(f"EGNNLayer: d_ff 必须是 >=1 的整数，收到 {d_ff!r}")
        if seed is not None and (isinstance(seed, bool) or not isinstance(seed, int)):
            raise ValueError(f"EGNNLayer: seed 必须是 int 或 None，收到 {seed!r}")
        self.d_model = d_model
        self.d_ff = d_ff
        # 三张 MLP：边消息、坐标系数、节点更新
        self.phi_e = _e3_make_mlp([2 * d_model + 1, d_ff, d_ff],
                                  ["relu"] * 2, seed)
        self.phi_x = _e3_make_mlp([d_ff, 1], ["linear"], seed)
        self.phi_h = _e3_make_mlp([d_model + d_ff, d_ff, d_model],
                                  ["relu"] * 2, seed)
        self.grad_phi_e = _e3_zeros_like(self.phi_e)
        self.grad_phi_x = _e3_zeros_like(self.phi_x)
        self.grad_phi_h = _e3_zeros_like(self.phi_h)
        self._cache = None

    @staticmethod
    def _d2(xi, xj):
        return ((xi[0] - xj[0]) ** 2 + (xi[1] - xj[1]) ** 2
                + (xi[2] - xj[2]) ** 2)

    def forward(self, h, x):
        """h: N×d 节点特征；x: N×3 坐标。返回 (h', x')。"""
        h = _e3_check_matrix(h, "EGNNLayer.forward: h", self.d_model)
        x = _e3_check_matrix(x, "EGNNLayer.forward: x", 3)
        n = len(h)
        if len(x) != n:
            raise ValueError("EGNNLayer.forward: h 与 x 的节点数必须一致")
        pairs = [(i, j) for i in range(n) for j in range(n) if i != j]
        edge_rows = []
        d2s = []
        for (i, j) in pairs:
            d2 = self._d2(x[i], x[j])
            d2s.append(d2)
            edge_rows.append(h[i] + h[j] + [d2])
        if edge_rows:
            e_rows, e_caches = _e3_mlp_forward(self.phi_e, edge_rows)
            w_rows, w_caches = _e3_mlp_forward(self.phi_x, e_rows)
        else:
            e_rows, e_caches = [], []
            w_rows, w_caches = [], []
        m = [[0.0] * self.d_ff for _ in range(n)]
        for p, (i, j) in enumerate(pairs):
            for k in range(self.d_ff):
                m[i][k] += e_rows[p][k]
        node_rows = [h[i] + m[i] for i in range(n)]
        if node_rows:
            dh_rows, h_caches = _e3_mlp_forward(self.phi_h, node_rows)
        else:
            dh_rows, h_caches = [], []
        h_new = [[h[i][k] + dh_rows[i][k] for k in range(self.d_model)]
                 for i in range(n)]
        x_new = [[x[i][k] for k in range(3)] for i in range(n)]
        for p, (i, j) in enumerate(pairs):
            w = w_rows[p][0]
            for k in range(3):
                x_new[i][k] += w * (x[i][k] - x[j][k])
        self._cache = {
            "h": h, "x": x, "pairs": pairs, "d2s": d2s,
            "e_rows": e_rows, "e_caches": e_caches,
            "w_rows": w_rows, "w_caches": w_caches,
            "m": m, "h_caches": h_caches, "dh_rows": dh_rows,
            "n": n,
        }
        return h_new, x_new

    def backward(self, dh_new, dx_new):
        """给定输出梯度，回传并累积三张 MLP 的梯度；返回 (dh, dx)。"""
        c = self._cache
        if c is None:
            raise RuntimeError("EGNNLayer.backward: 必须先调用 forward")
        n = c["n"]
        pairs = c["pairs"]
        h, x = c["h"], c["x"]
        dh_new = _e3_check_matrix(dh_new, "EGNNLayer.backward: dh", self.d_model)
        dx_new = _e3_check_matrix(dx_new, "EGNNLayer.backward: dx", 3)
        if len(dh_new) != n or len(dx_new) != n:
            raise ValueError("EGNNLayer.backward: 梯度节点数必须与 forward 一致")

        dh = [list(dh_new[i]) for i in range(n)]
        dx = [list(dx_new[i]) for i in range(n)]

        # 1) phi_h 反传：node_in = [h_i, m_i]（h 维 d_model，m 维 d_ff）
        d_h_delta_rows = [list(dh_new[i]) for i in range(n)]
        if n:
            h_grads, d_in = _e3_mlp_backward(
                self.phi_h, c["h_caches"], d_h_delta_rows)
            _e3_accumulate(self.grad_phi_h, h_grads)
            for i in range(n):
                for k in range(self.d_model):
                    dh[i][k] += d_in[i][k]
            de_rows = [list(d_in[i][self.d_model:]) for i in range(n)]
        else:
            de_rows = []
        # m_i = Σ_j e_ij，故 de_ij = dm_i
        de_pair = [list(de_rows[i]) for (i, j) in pairs]

        # 2) phi_x 反传：w_ij 只影响 x_new[i]
        d_w_rows = [[0.0] for _ in pairs]
        for p, (i, j) in enumerate(pairs):
            w = c["w_rows"][p][0]
            for k in range(3):
                dx[i][k] += dx_new[i][k] * w
                dx[j][k] -= dx_new[i][k] * w
                d_w_rows[p][0] += (x[i][k] - x[j][k]) * dx_new[i][k]
        if pairs:
            x_grads, d_e_from_x = _e3_mlp_backward(
                self.phi_x, c["w_caches"], d_w_rows)
            _e3_accumulate(self.grad_phi_x, x_grads)
            for p in range(len(pairs)):
                for k in range(self.d_ff):
                    de_pair[p][k] += d_e_from_x[p][k]

        # 3) phi_e 反传：edge_in = [h_i, h_j, d2]
        if pairs:
            e_grads, d_edge_in = _e3_mlp_backward(
                self.phi_e, c["e_caches"], de_pair)
            _e3_accumulate(self.grad_phi_e, e_grads)
            for p, (i, j) in enumerate(pairs):
                for k in range(self.d_model):
                    dh[i][k] += d_edge_in[p][k]
                    dh[j][k] += d_edge_in[p][self.d_model + k]
                dd2 = d_edge_in[p][2 * self.d_model]
                for k in range(3):
                    diff = x[i][k] - x[j][k]
                    dx[i][k] += 2.0 * dd2 * diff
                    dx[j][k] -= 2.0 * dd2 * diff
        return dh, dx

    def zero_grad(self):
        self.grad_phi_e = _e3_zeros_like(self.phi_e)
        self.grad_phi_x = _e3_zeros_like(self.phi_x)
        self.grad_phi_h = _e3_zeros_like(self.phi_h)

    def sgd_step(self, lr):
        _e3_apply_sgd(self.phi_e, self.grad_phi_e, lr)
        _e3_apply_sgd(self.phi_x, self.grad_phi_x, lr)
        _e3_apply_sgd(self.phi_h, self.grad_phi_h, lr)

    def param_count(self):
        return (_e3_param_count(self.phi_e) + _e3_param_count(self.phi_x)
                + _e3_param_count(self.phi_h))


class EGNNModel:
    """多层 EGNN + 均值池化读出（标量输出，E(3) 不变）。"""

    def __init__(self, d_model, num_layers=1, d_ff=None, seed=None):
        if isinstance(d_model, bool) or not isinstance(d_model, int) or d_model < 1:
            raise ValueError(f"EGNNModel: d_model 必须是 >=1 的整数，收到 {d_model!r}")
        if isinstance(num_layers, bool) or not isinstance(num_layers, int) or num_layers < 1:
            raise ValueError(
                f"EGNNModel: num_layers 必须是 >=1 的整数，收到 {num_layers!r}")
        self.d_model = d_model
        self.d_ff = d_ff
        self.layers = [EGNNLayer(d_model, d_ff, seed=seed)
                       for _ in range(num_layers)]
        self.readout = _e3_make_mlp([d_model, d_ff or 2 * d_model, 1],
                                    ["relu", "linear"], seed)
        self.grad_readout = _e3_zeros_like(self.readout)
        self._cache = None

    def _forward_readout(self, h, x):
        h_cur, x_cur = h, x
        for layer in self.layers:
            h_cur, x_cur = layer.forward(h_cur, x_cur)
        n = len(h_cur)
        mean = [sum(h_cur[i][k] for i in range(n)) / n
                for k in range(self.d_model)]
        out, cache = _e3_mlp_forward(self.readout, [mean])
        self._cache = {"h": h_cur, "x": x_cur, "cache": cache, "mean": mean}
        return h_cur, x_cur, out[0][0]

    def forward(self, h, x):
        """返回 (h', x', scalar)；scalar 对旋转/平移不变。"""
        h_out, x_out, scalar = self._forward_readout(h, x)
        return h_out, x_out, scalar

    def loss_and_backward(self, h, x, target):
        """MSE(scalar, target) 并对整个网络反向，返回损失。"""
        if isinstance(target, bool) or not isinstance(target, (int, float)):
            raise ValueError(f"EGNNModel: target 必须是数字，收到 {target!r}")
        if not math.isfinite(float(target)):
            raise ValueError("EGNNModel: target 必须是有限数")
        h_out, x_out, scalar = self._forward_readout(h, x)
        diff = scalar - float(target)
        loss = diff * diff
        d_out = [[2.0 * diff]]
        r_grads, d_mean = _e3_mlp_backward(self.readout, self._cache["cache"], d_out)
        _e3_accumulate(self.grad_readout, r_grads)
        n = len(h_out)
        dh = [[d_mean[0][k] / n for k in range(self.d_model)] for _ in range(n)]
        dx = [[0.0, 0.0, 0.0] for _ in range(n)]
        for layer in reversed(self.layers):
            dh, dx = layer.backward(dh, dx)
        return loss

    def zero_grad(self):
        for layer in self.layers:
            layer.zero_grad()
        self.grad_readout = _e3_zeros_like(self.readout)

    def sgd_step(self, lr):
        for layer in self.layers:
            layer.sgd_step(lr)
        _e3_apply_sgd(self.readout, self.grad_readout, lr)

    def param_count(self):
        return sum(layer.param_count() for layer in self.layers) \
            + _e3_param_count(self.readout)

    def fit(self, graphs, epochs=50, lr=0.05, shuffle=True, seed=None):
        """graphs: [(h, x, target), ...] 的小批量全批训练，返回每轮平均损失。"""
        if not isinstance(graphs, (list, tuple)) or not graphs:
            raise ValueError("EGNNModel.fit: graphs 必须是非空列表")
        if isinstance(epochs, bool) or not isinstance(epochs, int) or epochs < 1:
            raise ValueError(f"EGNNModel.fit: epochs 必须是 >=1 的整数，收到 {epochs!r}")
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr <= 0:
            raise ValueError(f"EGNNModel.fit: lr 必须是正数，收到 {lr!r}")
        rng = random.Random(seed)
        order = list(range(len(graphs)))
        history = []
        for _ in range(epochs):
            self.zero_grad()
            total = 0.0
            if shuffle:
                rng.shuffle(order)
            for idx in order:
                h, x, target = graphs[idx]
                total += self.loss_and_backward(h, x, target)
            self.sgd_step(lr / len(graphs))
            history.append(total / len(graphs))
        return history

"""Medusa / EAGLE 投机解码（轻量教学实现）"""


def _me_check_int(value, name, minimum=None, maximum=None):
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{name} 必须是整数，收到 {value!r}")
    if minimum is not None and value < minimum:
        raise ValueError(f"{name} 必须 >= {minimum}，收到 {value}")
    if maximum is not None and value > maximum:
        raise ValueError(f"{name} 必须 <= {maximum}，收到 {value}")
    return value


def _me_log_softmax(row):
    m = max(row)
    z = [math.exp(v - m) for v in row]
    s = sum(z)
    return [v - m - math.log(s) for v in row]


def _me_softmax(row):
    m = max(row)
    z = [math.exp(v - m) for v in row]
    s = sum(z)
    return [v / s for v in z]


def _me_argmax(row):
    best = 0
    for i in range(1, len(row)):
        if row[i] > row[best]:
            best = i
    return best


def _me_check_ids(ids, vocab_size, name="ids"):
    if not isinstance(ids, (list, tuple)) or not ids:
        raise ValueError(f"{name} 不能为空")
    out = []
    for i, tok in enumerate(ids):
        if isinstance(tok, bool) or not isinstance(tok, int):
            raise TypeError(f"{name}[{i}] 必须是整数，收到 {tok!r}")
        if not 0 <= tok < vocab_size:
            raise ValueError(f"{name}[{i}]={tok} 越界（词表大小 {vocab_size}）")
        out.append(tok)
    return out


class MedusaHeads:
    """Medusa 多分支草稿头：同一个隐藏状态同时预测未来 K 个 token。"""

    def __init__(self, d_model, vocab_size, num_heads=4, seed=None):
        _me_check_int(d_model, "MedusaHeads.d_model", minimum=1)
        _me_check_int(vocab_size, "MedusaHeads.vocab_size", minimum=1)
        _me_check_int(num_heads, "MedusaHeads.num_heads", minimum=1)
        self.d_model = d_model
        self.vocab_size = vocab_size
        self.num_heads = num_heads
        state = None
        if seed is not None:
            state = random.getstate()
            random.seed(seed)
        try:
            self.heads = [Layer(d_model, vocab_size, "linear") for _ in range(num_heads)]
        finally:
            if state is not None:
                random.setstate(state)
        self.grads = None

    def zero_grad(self):
        self.grads = None

    def param_count(self):
        return sum(_dense_param_count(h) for h in self.heads)

    def forward(self, hidden_rows):
        if not isinstance(hidden_rows, (list, tuple)) or not hidden_rows:
            raise ValueError("MedusaHeads.forward: hidden_rows 不能为空")
        outs = []
        caches = []
        for head in self.heads:
            out, cache = _dense_rows_forward(head, hidden_rows)
            outs.append(out)
            caches.append(cache)
        return outs, caches

    def loss_and_backward(self, hidden_rows, targets):
        """targets: 长度 num_heads，每项是与 hidden_rows 等长的目标 token 列表。"""
        outs, caches = self.forward(hidden_rows)
        n_rows = len(hidden_rows)
        if not isinstance(targets, (list, tuple)) or len(targets) != self.num_heads:
            raise ValueError("MedusaHeads.loss_and_backward: targets 必须按头给出一组目标序列")
        total = 0.0
        scale = 1.0 / (self.num_heads * n_rows)
        grads = []
        for k in range(self.num_heads):
            row_targets = targets[k]
            if not isinstance(row_targets, (list, tuple)) or len(row_targets) != n_rows:
                raise ValueError(f"MedusaHeads: 第 {k} 个头的目标长度与 hidden_rows 不一致")
            d_rows = []
            for r in range(n_rows):
                tok = row_targets[r]
                if isinstance(tok, bool) or not isinstance(tok, int) or not 0 <= tok < self.vocab_size:
                    raise ValueError(f"MedusaHeads: targets[{k}][{r}]={tok!r} 不是合法 token")
                logp = _me_log_softmax(outs[k][r])
                total -= logp[tok] * scale
                probs = [math.exp(v) for v in logp]
                probs[tok] -= 1.0
                d_rows.append([v * scale for v in probs])
            gw, gb, _ = _dense_rows_backward(self.heads[k], caches[k], d_rows)
            grads.append((gw, gb))
        self.grads = grads
        return total

    def sgd_step(self, lr):
        for k, head in enumerate(self.heads):
            if self.grads is not None:
                _dense_apply_sgd(head, self.grads[k], lr)

    def predict(self, hidden_row):
        outs, _ = self.forward([hidden_row])
        return [_me_softmax(outs[k][0]) for k in range(self.num_heads)]


class EagleDrafter:
    """EAGLE 风格的特征级草稿器：由目标模型隐藏状态 + 上一 token 嵌入预测下一 token。"""

    def __init__(self, d_model, vocab_size, hidden=64, seed=None):
        _me_check_int(d_model, "EagleDrafter.d_model", minimum=1)
        _me_check_int(vocab_size, "EagleDrafter.vocab_size", minimum=1)
        _me_check_int(hidden, "EagleDrafter.hidden", minimum=1)
        self.d_model = d_model
        self.vocab_size = vocab_size
        self.hidden = hidden
        state = None
        if seed is not None:
            state = random.getstate()
            random.seed(seed)
        try:
            std = math.sqrt(2.0 / (d_model))
            self.Wf = [[random.gauss(0.0, std) for _ in range(d_model)] for _ in range(hidden)]
            self.We = [[random.gauss(0.0, std) for _ in range(d_model)] for _ in range(hidden)]
            self.bh = [0.0] * hidden
            self.Wh = [[random.gauss(0.0, std) for _ in range(hidden)] for _ in range(vocab_size)]
            self.bo = [0.0] * vocab_size
        finally:
            if state is not None:
                random.setstate(state)

    def param_count(self):
        return (self.hidden * self.d_model * 2 + self.hidden + self.vocab_size * self.hidden
                + self.vocab_size)

    def hidden_state(self, feature, prev_emb):
        if not isinstance(feature, (list, tuple)) or len(feature) != self.d_model:
            raise ValueError(f"EagleDrafter: feature 长度必须是 {self.d_model}")
        if not isinstance(prev_emb, (list, tuple)) or len(prev_emb) != self.d_model:
            raise ValueError(f"EagleDrafter: prev_emb 长度必须是 {self.d_model}")
        h = []
        for j in range(self.hidden):
            v = self.bh[j]
            wf = self.Wf[j]
            we = self.We[j]
            for i in range(self.d_model):
                v += wf[i] * feature[i] + we[i] * prev_emb[i]
            h.append(math.tanh(v))
        return h

    def forward(self, feature, prev_emb):
        h = self.hidden_state(feature, prev_emb)
        logits = []
        for v in range(self.vocab_size):
            row = self.Wh[v]
            s = self.bo[v]
            for j in range(self.hidden):
                s += row[j] * h[j]
            logits.append(s)
        return logits

    def draft(self, feature, prev_token, k, embed_weight, vocab_size):
        _me_check_int(k, "EagleDrafter.draft.k", minimum=0)
        if not isinstance(embed_weight, (list, tuple)) or len(embed_weight) < vocab_size:
            raise ValueError("EagleDrafter.draft: embed_weight 与 vocab_size 不匹配")
        out = []
        prev = prev_token
        for _ in range(k):
            logits = self.forward(feature, embed_weight[prev])
            prev = _me_argmax(logits)
            out.append(prev)
        return out


def _me_greedy(target, prompt_ids, max_new_tokens):
    n = _me_check_int(max_new_tokens, "max_new_tokens", minimum=1)
    ids = list(prompt_ids)
    out = []
    for _ in range(n):
        logits = target.forward(ids)
        tok = _me_argmax(logits[-1])
        ids.append(tok)
        out.append(tok)
    return out


def medusa_decode(target, prompt_ids, heads, max_new_tokens=8, eos_id=None):
    """用 Medusa 多头草稿 + 目标模型验证；不接受时回退目标模型的贪心 token。"""
    vocab = getattr(target, "vocab_size", None)
    if vocab is None:
        raise TypeError("medusa_decode: target 必须有 vocab_size")
    prompt = _me_check_ids(prompt_ids, vocab, "prompt_ids")
    if not isinstance(heads, MedusaHeads):
        raise TypeError("medusa_decode: heads 必须是 MedusaHeads")
    if heads.vocab_size != vocab:
        raise ValueError("medusa_decode: heads.vocab_size 与目标模型不一致")
    if heads.d_model != getattr(target, "d_model", heads.d_model):
        raise ValueError("medusa_decode: heads.d_model 与目标模型不一致")
    n = _me_check_int(max_new_tokens, "max_new_tokens", minimum=1)
    if eos_id is not None:
        _me_check_int(eos_id, "eos_id", minimum=0)
    ctx = list(prompt)
    out = []
    drafted = 0
    accepted = 0
    target_calls = 0
    k = heads.num_heads
    max_len = getattr(target, "max_len", None)
    while len(out) < n:
        if max_len is not None and len(ctx) + k + 1 > max_len:
            logits = target.forward(ctx)
            target_calls += 1
            tok = _me_argmax(logits[-1])
            out.append(tok)
            ctx.append(tok)
            if eos_id is not None and tok == eos_id:
                break
            continue
        logits = target.forward(ctx)
        target_calls += 1
        h_last = target.h[-1]
        head_logits, _ = heads.forward([h_last])
        drafts = [_me_argmax(head_logits[h][0]) for h in range(k)]
        drafted += k
        verify = target.forward(ctx + drafts)
        target_calls += 1
        acc = 0
        for i in range(k):
            pos = len(ctx) - 1 + i
            if _me_argmax(verify[pos]) == drafts[i]:
                acc += 1
            else:
                break
        accepted += acc
        stop = False
        for t in drafts[:acc]:
            if len(out) >= n:
                break
            out.append(t)
            ctx.append(t)
            if eos_id is not None and t == eos_id:
                stop = True
                break
        if stop or len(out) >= n:
            break
        tok = _me_argmax(verify[len(ctx) - 1])
        out.append(tok)
        ctx.append(tok)
        if eos_id is not None and tok == eos_id:
            break
    return {
        "ids": list(prompt) + out,
        "tokens": out,
        "stats": {
            "drafted": drafted,
            "accepted": accepted,
            "target_calls": target_calls,
            "accept_rate": (accepted / drafted) if drafted else 0.0,
        },
    }


def eagle_decode(target, prompt_ids, drafter, max_new_tokens=8, gamma=4, eos_id=None):
    """用 EAGLE 风格特征级草稿器生成草稿链，再交目标模型验证。"""
    vocab = getattr(target, "vocab_size", None)
    if vocab is None:
        raise TypeError("eagle_decode: target 必须有 vocab_size")
    prompt = _me_check_ids(prompt_ids, vocab, "prompt_ids")
    if not isinstance(drafter, EagleDrafter):
        raise TypeError("eagle_decode: drafter 必须是 EagleDrafter")
    if drafter.vocab_size != vocab:
        raise ValueError("eagle_decode: drafter.vocab_size 与目标模型不一致")
    if drafter.d_model != getattr(target, "d_model", drafter.d_model):
        raise ValueError("eagle_decode: drafter.d_model 与目标模型不一致")
    n = _me_check_int(max_new_tokens, "max_new_tokens", minimum=1)
    gamma = _me_check_int(gamma, "gamma", minimum=1)
    if eos_id is not None:
        _me_check_int(eos_id, "eos_id", minimum=0)
    ctx = list(prompt)
    out = []
    drafted = 0
    accepted = 0
    target_calls = 0
    max_len = getattr(target, "max_len", None)
    embed_weight = target.embedding.weight
    while len(out) < n:
        if max_len is not None and len(ctx) + gamma + 1 > max_len:
            logits = target.forward(ctx)
            target_calls += 1
            tok = _me_argmax(logits[-1])
            out.append(tok)
            ctx.append(tok)
            if eos_id is not None and tok == eos_id:
                break
            continue
        logits = target.forward(ctx)
        target_calls += 1
        feature = target.h[-1]
        first = _me_argmax(logits[-1])
        drafts = [first]
        prev = first
        for _ in range(gamma - 1):
            d_logits = drafter.forward(feature, embed_weight[prev])
            prev = _me_argmax(d_logits)
            drafts.append(prev)
        drafted += gamma
        verify = target.forward(ctx + drafts)
        target_calls += 1
        acc = 0
        for i in range(gamma):
            pos = len(ctx) - 1 + i
            if _me_argmax(verify[pos]) == drafts[i]:
                acc += 1
            else:
                break
        accepted += acc
        stop = False
        for t in drafts[:acc]:
            if len(out) >= n:
                break
            out.append(t)
            ctx.append(t)
            if eos_id is not None and t == eos_id:
                stop = True
                break
        if stop or len(out) >= n:
            break
        tok = _me_argmax(verify[len(ctx) - 1])
        out.append(tok)
        ctx.append(tok)
        if eos_id is not None and tok == eos_id:
            break
    return {
        "ids": list(prompt) + out,
        "tokens": out,
        "stats": {
            "drafted": drafted,
            "accepted": accepted,
            "target_calls": target_calls,
            "accept_rate": (accepted / drafted) if drafted else 0.0,
        },
    }

#  领域应用：时序（TCN / Informer 简化 / Autoformer 简化 / PatchTST）
# ============================================================================

def _w17_pad_left(x, pad):
    """在序列左侧补零（因果卷积用）。"""
    if pad <= 0:
        return [list(row) for row in x]
    width = len(x[0]) if x else 0
    out = [[0.0] * width for _ in range(pad)]
    out.extend([list(row) for row in x])
    return out


class _CausalConv1d:
    """内部用的因果膨胀一维卷积：``(T, C) -> (T, O)``，权重 ``[O][C][k]``。"""

    def __init__(self, in_channels, out_channels, kernel_size=3, dilation=1, seed=None):
        if out_channels < 1 or in_channels < 1:
            raise ValueError("_CausalConv1d: 通道数必须 >= 1")
        if kernel_size < 1:
            raise ValueError(f"_CausalConv1d: kernel_size 必须 >= 1，收到 {kernel_size!r}")
        if dilation < 1:
            raise ValueError(f"_CausalConv1d: dilation 必须 >= 1，收到 {dilation!r}")
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.dilation = dilation
        rng = random.Random(seed) if seed is not None else random
        std = math.sqrt(2.0 / (in_channels * kernel_size))
        self.weights = [[[rng.gauss(0.0, std) for _ in range(kernel_size)]
                         for _ in range(in_channels)] for _ in range(out_channels)]
        self.biases = [0.0] * out_channels
        self.grad_w = [[[0.0] * kernel_size for _ in range(in_channels)]
                       for _ in range(out_channels)]
        self.grad_b = [0.0] * out_channels
        self._padded = None
        self._length = 0

    def zero_grad(self):
        for oc in range(self.out_channels):
            for ic in range(self.in_channels):
                self.grad_w[oc][ic] = [0.0] * self.kernel_size
        self.grad_b = [0.0] * self.out_channels

    def forward(self, x):
        if not x or not x[0]:
            raise ValueError("_CausalConv1d.forward: 输入必须是非空 (T, C) 序列")
        if len(x[0]) != self.in_channels:
            raise ValueError(
                f"_CausalConv1d.forward: 输入通道 {len(x[0])} 与 in_channels="
                f"{self.in_channels} 不一致")
        t_len = len(x)
        pad = (self.kernel_size - 1) * self.dilation
        xp = _w17_pad_left(x, pad)
        self._padded = xp
        self._length = t_len
        out = []
        for t in range(t_len):
            row = []
            for oc in range(self.out_channels):
                acc = self.biases[oc]
                w_oc = self.weights[oc]
                for ic in range(self.in_channels):
                    w_ic = w_oc[ic]
                    for kk in range(self.kernel_size):
                        acc += w_ic[kk] * xp[t + kk * self.dilation][ic]
                row.append(acc)
            out.append(row)
        return out

    def backward(self, dout):
        if self._padded is None:
            raise RuntimeError("_CausalConv1d.backward: 需要先调用 forward")
        if len(dout) != self._length:
            raise ValueError(
                f"_CausalConv1d.backward: dout 长度 {len(dout)} 与序列长度 {self._length} 不一致")
        pad = (self.kernel_size - 1) * self.dilation
        width = self.in_channels
        dxp = [[0.0] * width for _ in range(len(self._padded))]
        for t in range(self._length):
            drow = dout[t]
            if len(drow) != self.out_channels:
                raise ValueError("_CausalConv1d.backward: dout 通道数与 out_channels 不一致")
            for oc in range(self.out_channels):
                g = drow[oc]
                if g == 0.0:
                    continue
                self.grad_b[oc] += g
                w_oc = self.weights[oc]
                gw_oc = self.grad_w[oc]
                for ic in range(self.in_channels):
                    w_ic = w_oc[ic]
                    gw_ic = gw_oc[ic]
                    for kk in range(self.kernel_size):
                        pos = t + kk * self.dilation
                        gw_ic[kk] += g * self._padded[pos][ic]
                        dxp[pos][ic] += g * w_ic[kk]
        return dxp[pad:]


class TCNBlock:
    """时序卷积块：两段因果膨胀卷积 + 残差（ReLU），带手写反向。"""

    def __init__(self, in_channels, out_channels, kernel_size=3, dilation=1, seed=None):
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.dilation = dilation
        self.conv1 = _CausalConv1d(in_channels, out_channels, kernel_size, dilation, seed)
        self.conv2 = _CausalConv1d(
            out_channels, out_channels, kernel_size, dilation,
            None if seed is None else seed + 1)
        self.proj = None
        if in_channels != out_channels:
            self.proj = _CausalConv1d(in_channels, out_channels, 1, 1, seed)
        self._cache = None

    def zero_grad(self):
        self.conv1.zero_grad()
        self.conv2.zero_grad()
        if self.proj is not None:
            self.proj.zero_grad()

    def forward(self, x):
        h1 = [[max(0.0, v) for v in row] for row in self.conv1.forward(x)]
        pre2 = self.conv2.forward(h1)
        h2 = [[max(0.0, v) for v in row] for row in pre2]
        if self.proj is None:
            residual = [list(row) for row in x]
        else:
            residual = self.proj.forward(x)
        pre_out = [[h2[t][j] + residual[t][j] for j in range(self.out_channels)]
                   for t in range(len(x))]
        out = [[max(0.0, v) for v in row] for row in pre_out]
        self._cache = (x, h1, h2, residual, out)
        return out

    def backward(self, dout):
        if self._cache is None:
            raise RuntimeError("TCNBlock.backward: 需要先调用 forward")
        x, h1, h2, residual, out = self._cache
        dpre = [[dout[t][j] if out[t][j] > 0.0 else 0.0 for j in range(self.out_channels)]
                for t in range(len(dout))]
        # h2 = relu(pre2)：还要再过一道 ReLU 的掩码，否则 conv2 会拿到未经掩码的梯度
        dh2 = [[dpre[t][j] if h2[t][j] > 0.0 else 0.0 for j in range(self.out_channels)]
               for t in range(len(dout))]
        dh1 = self.conv2.backward(dh2)
        dh1 = [[dh1[t][j] if h1[t][j] > 0.0 else 0.0 for j in range(self.out_channels)]
               for t in range(len(dh1))]
        dx1 = self.conv1.backward(dh1)
        if self.proj is None:
            dxp = dpre
        else:
            dxp = self.proj.backward(dpre)
        return [[dx1[t][j] + dxp[t][j] for j in range(self.in_channels)]
                for t in range(len(dout))]

    def param_count(self):
        n = (self.conv1.out_channels * self.conv1.in_channels * self.conv1.kernel_size
             + self.conv1.out_channels)
        n += (self.conv2.out_channels * self.conv2.in_channels * self.conv2.kernel_size
              + self.conv2.out_channels)
        if self.proj is not None:
            n += self.proj.out_channels * self.proj.in_channels + self.proj.out_channels
        return n


class TCN:
    """多层时序卷积网络（膨胀指数 1, 2, 4, ...），``(T, C) -> (T, hidden)``。"""

    def __init__(self, in_channels, hidden=16, levels=3, kernel_size=3, seed=None):
        if levels < 1:
            raise ValueError(f"TCN: levels 必须 >= 1，收到 {levels!r}")
        base = random.Random(seed) if seed is not None else random
        seeds = [base.randrange(1 << 30) for _ in range(levels)]
        self.blocks = []
        cur = in_channels
        for i in range(levels):
            self.blocks.append(
                TCNBlock(cur, hidden, kernel_size, 2 ** i, seeds[i]))
            cur = hidden
        self.hidden = hidden
        self.levels = levels
        self._x = None

    def zero_grad(self):
        for block in self.blocks:
            block.zero_grad()

    def forward(self, x):
        self._x = x
        h = x
        for block in self.blocks:
            h = block.forward(h)
        return h

    def backward(self, dout):
        if self._x is None:
            raise RuntimeError("TCN.backward: 需要先调用 forward")
        d = dout
        for block in reversed(self.blocks):
            d = block.backward(d)
        return d

    def param_count(self):
        return sum(b.param_count() for b in self.blocks)


def prob_sparse_attention(q, k, v, factor=5):
    """Informer 的稀疏注意力（简化）：只让「稀疏度评分最高」的 u 个查询看全部键。

    其余查询退化为「值的均值」。返回 ``(out, stats)``，``stats`` 给
    ``{"u", "total", "selected"}``。这是**前向**近似，不做反向。
    """
    if not q or not k or not v:
        raise ValueError("prob_sparse_attention: q / k / v 必须非空")
    if len(q[0]) != len(k[0]) or len(k) != len(v):
        raise ValueError("prob_sparse_attention: q/k 维度或 k/v 长度不一致")
    if isinstance(factor, bool) or not isinstance(factor, (int, float)) or factor <= 0:
        raise ValueError(f"prob_sparse_attention: factor 必须 > 0，收到 {factor!r}")
    t_len = len(q)
    dim = len(q[0])
    u = max(1, min(t_len, int(factor * math.log(max(2, t_len)))))
    scores = []
    for i in range(t_len):
        row = [sum(q[i][d] * k[j][d] for d in range(dim)) / math.sqrt(dim)
               for j in range(t_len)]
        scores.append((max(row) - sum(row) / t_len, row))
    order = sorted(range(t_len), key=lambda i: (-scores[i][0], i))[:u]
    selected = sorted(order)
    mean_v = [sum(v[j][d] for j in range(t_len)) / t_len for d in range(len(v[0]))]
    out = [list(mean_v) for _ in range(t_len)]
    for i in selected:
        row = scores[i][1]
        m = max(row)
        ex = [math.exp(s - m) for s in row]
        z = sum(ex)
        probs = [e / z for e in ex]
        out[i] = [sum(probs[j] * v[j][d] for j in range(t_len))
                  for d in range(len(v[0]))]
    stats = {"u": u, "total": t_len, "selected": selected}
    return out, stats


def series_decompose(x, kernel=25):
    """Autoformer 式滑动平均分解：返回 ``(trend, seasonal)``，``x`` 是 1D 序列。"""
    if not x:
        raise ValueError("series_decompose: x 必须非空")
    if isinstance(kernel, bool) or not isinstance(kernel, int) or kernel < 1:
        raise ValueError(f"series_decompose: kernel 必须是 >=1 的整数，收到 {kernel!r}")
    half = kernel // 2
    trend = []
    for i in range(len(x)):
        lo = max(0, i - half)
        hi = min(len(x), i + half + 1)
        trend.append(sum(x[lo:hi]) / (hi - lo))
    seasonal = [x[i] - trend[i] for i in range(len(x))]
    return trend, seasonal


def auto_correlation(values, max_lag=None):
    """自相关（0 阶为 1），返回 ``[r_0, r_1, ...]``。"""
    if not values:
        raise ValueError("auto_correlation: values 必须非空")
    n = len(values)
    if max_lag is None:
        max_lag = n - 1
    if isinstance(max_lag, bool) or not isinstance(max_lag, int) or max_lag < 0:
        raise ValueError(f"auto_correlation: max_lag 必须是非负整数，收到 {max_lag!r}")
    if max_lag > n - 1:
        raise ValueError(
            f"auto_correlation: max_lag={max_lag} 超过序列长度减一（{n - 1}）")
    mean = sum(values) / n
    denom = sum((v - mean) ** 2 for v in values)
    if denom <= 0.0:
        raise ValueError("auto_correlation: 常数序列的自相关没有定义")
    out = []
    for lag in range(max_lag + 1):
        num = sum((values[i] - mean) * (values[i + lag] - mean)
                  for i in range(n - lag))
        out.append(num / denom)
    return out


def autoformer_aggregate(seasonal, period, top_k=2, weights=None):
    """按自相关挑 top-k 个周期做加权平移平均（Autoformer 的序列聚合简化）。"""
    if not seasonal:
        raise ValueError("autoformer_aggregate: seasonal 必须非空")
    if isinstance(period, bool) or not isinstance(period, int) or period < 1:
        raise ValueError(f"autoformer_aggregate: period 必须是 >=1 的整数，收到 {period!r}")
    if isinstance(top_k, bool) or not isinstance(top_k, int) or top_k < 1:
        raise ValueError(f"autoformer_aggregate: top_k 必须是 >=1 的整数，收到 {top_k!r}")
    n = len(seasonal)
    if period >= n:
        raise ValueError(
            f"autoformer_aggregate: period={period} 必须小于序列长度 {n}")
    corr = auto_correlation(seasonal, min(n - 1, 3 * period))
    lags = sorted(range(1, len(corr)), key=lambda l: (-corr[l], l))[:top_k]
    if weights is None:
        w = [1.0 / len(lags)] * len(lags)
    else:
        if len(weights) != len(lags):
            raise ValueError(
                f"autoformer_aggregate: weights 长度 {len(weights)} 与 top_k={len(lags)} 不一致")
        total = sum(weights)
        if total <= 0.0:
            raise ValueError("autoformer_aggregate: weights 之和必须 > 0")
        w = [float(v) / total for v in weights]
    out = []
    for t in range(n):
        acc = 0.0
        for lag, ww in zip(lags, w):
            idx = t - lag
            acc += ww * (seasonal[idx] if idx >= 0 else seasonal[0])
        out.append(acc)
    return out, {"lags": lags, "weights": w}


class PatchTSTEmbedding:
    """PatchTST 的 patch 切分 + 线性嵌入 + RevIN（实例归一化）双向变换。"""

    def __init__(self, patch_len=16, stride=8, d_model=32, seed=None):
        if isinstance(patch_len, bool) or not isinstance(patch_len, int) or patch_len < 1:
            raise ValueError(f"PatchTSTEmbedding: patch_len 必须是 >=1 的整数，收到 {patch_len!r}")
        if isinstance(stride, bool) or not isinstance(stride, int) or stride < 1:
            raise ValueError(f"PatchTSTEmbedding: stride 必须是 >=1 的整数，收到 {stride!r}")
        if isinstance(d_model, bool) or not isinstance(d_model, int) or d_model < 1:
            raise ValueError(f"PatchTSTEmbedding: d_model 必须是 >=1 的整数，收到 {d_model!r}")
        self.patch_len = patch_len
        self.stride = stride
        self.d_model = d_model
        rng = random.Random(seed) if seed is not None else random
        std = math.sqrt(2.0 / patch_len)
        self.weights = [[rng.gauss(0.0, std) for _ in range(patch_len)]
                        for _ in range(d_model)]
        self.biases = [0.0] * d_model
        self._stats = None

    def rev_in(self, x):
        """实例归一化：减去均值、除以标准差，返回 ``(normalized, mean, std)``。"""
        n = len(x)
        if n == 0:
            raise ValueError("PatchTSTEmbedding.rev_in: x 必须非空")
        mean = sum(x) / n
        var = sum((v - mean) ** 2 for v in x) / n
        std = math.sqrt(var) if var > 0.0 else 1.0
        return [(v - mean) / std for v in x], mean, std

    @staticmethod
    def rev_inverse(normalized, mean, std=1.0):
        """RevIN 的逆变换。"""
        return [v * std + mean for v in normalized]

    def forward(self, x):
        normed, mean, std = self.rev_in(x)
        self._stats = (mean, std)
        patches = []
        start = 0
        while start + self.patch_len <= len(normed):
            patches.append(normed[start:start + self.patch_len])
            start += self.stride
        if not patches:
            raise ValueError(
                f"PatchTSTEmbedding.forward: 序列长度 {len(normed)} 不足一个 patch "
                f"({self.patch_len})")
        out = []
        for patch in patches:
            row = []
            for d in range(self.d_model):
                acc = self.biases[d]
                w = self.weights[d]
                for i in range(self.patch_len):
                    acc += w[i] * patch[i]
                row.append(acc)
            out.append(row)
        return out

    def param_count(self):
        return self.d_model * self.patch_len + self.d_model

# ============================================================================
#  全模块梯度自检（grad_check_all）
# ============================================================================

_W18A_SKIP_TYPES = (str, bytes, int, float, bool, dict, set, type(None))


def _w18a_is_leaf_layer(obj):
    """判断一个对象是不是「Layer 式」的参数持有者（能单独做局部梯度自检）"""
    if not hasattr(obj, "weights") or not hasattr(obj, "biases"):
        return False
    if not callable(getattr(obj, "forward", None)):
        return False
    if not callable(getattr(obj, "backward", None)):
        return False
    fan_in = getattr(obj, "fan_in", None)
    fan_out = getattr(obj, "fan_out", None)
    return isinstance(fan_in, int) and isinstance(fan_out, int)


def _w18a_collect(obj, out, seen, path, skipped):
    """深度优先收集 Layer 式子模块；容器递归，非 Layer 的参数持有者记进 skipped"""
    if id(obj) in seen:
        return
    seen.add(id(obj))
    if _w18a_is_leaf_layer(obj):
        out.append((path or type(obj).__name__, obj))
        return
    if hasattr(obj, "weights") and not _w18a_is_leaf_layer(obj):
        skipped.append({"name": path or type(obj).__name__,
                        "type": type(obj).__name__,
                        "reason": "参数持有者但不是 Layer 式模块（缺 forward/backward/fan_in）"})
        return
    slots = getattr(obj, "__dict__", None)
    if not isinstance(slots, dict):
        return
    for key in sorted(slots):
        if key.startswith("_") or key in ("optimizer", "loss_fn", "history"):
            continue
        value = slots[key]
        if isinstance(value, _W18A_SKIP_TYPES) or callable(value):
            continue
        child_path = "%s.%s" % (path, key) if path else key
        if isinstance(value, (list, tuple)):
            for i, item in enumerate(value):
                if isinstance(item, _W18A_SKIP_TYPES) or callable(item):
                    continue
                _w18a_collect(item, out, seen, "%s[%d]" % (child_path, i), skipped)
        else:
            _w18a_collect(value, out, seen, child_path, skipped)


def _w18a_dot(a, b):
    total = 0.0
    for i in range(len(a)):
        total += a[i] * b[i]
    return total


def _w18a_check_layer(layer, eps, tol, rng, max_params):
    """对单个 Layer 式模块做局部中心差分校验（输出方向随机取）"""
    x = [rng.uniform(-1.0, 1.0) for _ in range(layer.fan_in)]
    y = layer.forward(x)
    dout = [rng.uniform(-1.0, 1.0) for _ in range(len(y))]
    gw, gb, _ = layer.backward(dout)

    names = []
    for path, _ in _param_leaves(layer.weights):
        names.append(("weight" + "".join("[%d]" % p for p in path),
                      layer.weights, path, gw))
    for path, _ in _param_leaves(layer.biases):
        names.append(("bias" + "".join("[%d]" % p for p in path),
                      layer.biases, path, gb))
    if max_params is not None and len(names) > max_params:
        rng.shuffle(names)
        names = names[:max_params]

    checks = []
    zeros = []
    for name, param, path, grad in names:
        analytic = _pget(grad, path)
        original = _pget(param, path)
        _pset(param, path, original + eps)
        plus = _w18a_dot(dout, layer.forward(x))
        _pset(param, path, original - eps)
        minus = _w18a_dot(dout, layer.forward(x))
        _pset(param, path, original)
        numeric = (plus - minus) / (2.0 * eps)
        if abs(analytic) < 1e-8 and abs(numeric) < 1e-8:
            zeros.append(name)
            continue
        scale = max(abs(analytic), abs(numeric))
        rel = abs(analytic - numeric) / (scale if scale > 0.0 else 1.0)
        checks.append({"name": name, "rel": rel,
                       "analytic": analytic, "numeric": numeric})

    worst = 0.0
    worst_name = ""
    for item in checks:
        if item["rel"] > worst:
            worst = item["rel"]
            worst_name = item["name"]
    return {"ok": worst <= tol, "worst_name": worst_name, "worst_rel": worst,
            "checks": checks, "zeros": zeros, "output_size": len(y)}


def grad_check_all(module, eps: float = 1e-6, tol: float = 1e-5,
                   seed: int = 12345, max_params=None):
    """自动遍历模型里所有「Layer 式」参数持有者，逐个做局部梯度校验。

    和 `grad_check` 的区别：`grad_check` 只支持 MLP / Model / CausalLM / Seq2SeqLM，
    检查的是**整个模型**的输出对参数的梯度；本函数不关心模型的整体结构，沿
    `__dict__` 深度优先遍历，把每个带 `weights` / `biases` / `forward` / `backward`
    的模块挑出来，各自用随机输入与随机上游梯度做一次中心差分：

        x = U(-1, 1)^fan_in          y = layer.forward(x)
        dout = U(-1, 1)^len(y)       gw, gb, _ = layer.backward(dout)
        比对 d<dout, y>/dparam 与解析的 gw/gb

    这样卷积、循环、注意力等**非 Layer 结构**不会被假装检查——它们会进 `skipped`
    并写明原因（缺 forward/backward/fan_in），要用 `grad_check` 或专门的探针覆盖。

    eps:        差分步长
    tol:        相对误差阈值
    seed:       随机输入/方向/抽查的种子（可复现）
    max_params: 每个模块最多抽查多少个标量参数（None = 全查）

    返回 dict：
        {'ok': bool, 'checked': int, 'failed': [名字, ...],
         'worst': {'name','rel'} 或 None,
         'modules': [{'name','type','ok','worst_name','worst_rel','zeros','checks'}],
         'skipped': [{'name','type','reason'}]}
    """
    if not isinstance(eps, float) and not isinstance(eps, int):
        raise TypeError("grad_check_all: eps 必须是数字")
    if isinstance(eps, bool) or eps <= 0.0:
        raise ValueError("grad_check_all: eps 必须为正数")
    if isinstance(tol, bool) or not isinstance(tol, (int, float)) or tol < 0.0:
        raise ValueError("grad_check_all: tol 必须是非负数")
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise TypeError("grad_check_all: seed 必须是整数")
    if max_params is not None:
        if isinstance(max_params, bool) or not isinstance(max_params, int):
            raise TypeError("grad_check_all: max_params 必须是整数或 None")
        if max_params <= 0:
            raise ValueError("grad_check_all: max_params 必须为正数")

    target = getattr(module, "model", module) if hasattr(module, "forward") else module
    rng = random.Random(seed)
    layers = []
    skipped = []
    _w18a_collect(target, layers, set(), "", skipped)
    if not layers:
        raise ValueError("grad_check_all: 没有找到任何 Layer 式子模块"
                         "（本函数只检查带 weights/biases/forward/backward/fan_in 的模块）")

    reports = []
    failed = []
    worst = None
    for path, layer in layers:
        report = _w18a_check_layer(layer, float(eps), float(tol), rng, max_params)
        entry = {"name": path, "type": type(layer).__name__,
                 "ok": report["ok"],
                 "worst_name": report["worst_name"],
                 "worst_rel": report["worst_rel"],
                 "zeros": list(report["zeros"]),
                 "checks": report["checks"]}
        reports.append(entry)
        if not report["ok"]:
            failed.append(path)
        if worst is None or report["worst_rel"] > worst["rel"]:
            worst = {"name": path + "." + report["worst_name"]
                     if report["worst_name"] else path,
                     "rel": report["worst_rel"]}

    return {"ok": not failed, "checked": len(reports), "failed": failed,
            "worst": worst, "modules": reports, "skipped": skipped}


# ============================================================================
#  数值稳定性检测（nan/inf 扫描 + 六类极端输入探针）
# ============================================================================

_W18B_OK_EXCEPTIONS = (ValueError, TypeError, OverflowError,
                       ZeroDivisionError, RuntimeError, AssertionError)


def _w18b_iter_numbers(obj):
    """递归遍历 list / tuple / dict 里的数值叶子（bool 不算）"""
    if isinstance(obj, dict):
        for key in obj:
            for item in _w18b_iter_numbers(obj[key]):
                yield item
    elif isinstance(obj, (list, tuple)):
        for item in obj:
            for value in _w18b_iter_numbers(item):
                yield value
    elif isinstance(obj, (int, float)) and not isinstance(obj, bool):
        yield float(obj)


def numeric_scan(value):
    """扫描任意嵌套结构里的数值：返回计数、NaN 数、Inf 数与最大绝对值。

    返回 dict：{'count', 'nan', 'inf', 'max_abs', 'finite'}
    （空结构算有限：count=0 时 finite=True）
    """
    count = 0
    nans = 0
    infs = 0
    max_abs = 0.0
    for v in _w18b_iter_numbers(value):
        count += 1
        if v != v:
            nans += 1
            continue
        if v == float("inf") or v == float("-inf"):
            infs += 1
            continue
        if abs(v) > max_abs:
            max_abs = abs(v)
    return {"count": count, "nan": nans, "inf": infs,
            "max_abs": max_abs, "finite": nans == 0 and infs == 0}


def is_all_finite(value):
    """`numeric_scan(...)['finite']` 的便捷封装。"""
    return numeric_scan(value)["finite"]


def assert_all_finite(label, value):
    """断言任意嵌套结构里的所有数值都有限，否则抛 ValueError 并指出数量。"""
    scan = numeric_scan(value)
    if scan["finite"]:
        return True
    raise ValueError(
        "%s: 结果里出现非有限数（nan=%d, inf=%d, 共 %d 个数）"
        % (label, scan["nan"], scan["inf"], scan["count"]))


def stability_cases(size: int = 3):
    """六类极端输入：巨大 / 极小 / NaN / Inf / 全零 / 空。"""
    if isinstance(size, bool) or not isinstance(size, int):
        raise TypeError("stability_cases: size 必须是整数")
    if size <= 0:
        raise ValueError("stability_cases: size 必须为正数")
    return [
        ("huge", [1e300] * size),
        ("tiny", [1e-300] * size),
        ("nan", [float("nan")] + [1.0] * (size - 1)),
        ("inf", [float("inf")] + [1.0] * (size - 1)),
        ("zeros", [0.0] * size),
        ("empty", []),
    ]


def stability_probe(fn, cases=None, ok_exceptions=None, allow_inf=False):
    """对 `fn` 逐一喂入极端输入，判定「要么给出可解释的结果，要么显式报错」。

    判定标准（核心是**不静默出 NaN**）：
      - 没有 NaN，且（allow_inf 或没有 inf）  -> outcome='finite'
      - 没有 NaN，但有 ±inf 且 allow_inf=False -> outcome='inf'（不合格）
      - 出现 NaN                               -> outcome='nan'（永远不合格）
      - 抛出了异常                             -> outcome='raised'（合格）

    为什么 inf 可以放行：IEEE 的溢出结果是可见的 ±inf，调用方能用 `math.isfinite`
    一键判断；而 NaN 一旦进入 `x if x > 0 else 0` 这类分支就被吞成 0，问题会藏起来。
    因此 `allow_inf=True` 用于「溢出成 inf 属正常语义」的标量函数（mse / l1 / dft）。

    参数：
        fn:             接受一个 list 的函数
        cases:          [(名字, 输入 list), ...]，默认 `stability_cases()`
        ok_exceptions:  允许的异常类型元组，默认 ValueError/TypeError/
                        OverflowError/ZeroDivisionError/RuntimeError/AssertionError
        allow_inf:      是否接受返回值里出现 ±inf（NaN 永远不接受）

    返回 dict：{'ok', 'failed': [名字], 'cases': [
        {'name', 'outcome', 'exc', 'message', 'nan', 'inf', 'count', 'max_abs'}]}
    """
    if not callable(fn):
        raise TypeError("stability_probe: fn 必须是可调用对象")
    if cases is None:
        cases = stability_cases()
    allowed = _W18B_OK_EXCEPTIONS if ok_exceptions is None else tuple(ok_exceptions)
    if not isinstance(cases, (list, tuple)) or not cases:
        raise ValueError("stability_probe: cases 必须是非空列表")

    reports = []
    failed = []
    for item in cases:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("stability_probe: cases 的每一项必须是 (名字, 输入) 二元组")
        name, payload = item
        if not isinstance(name, str) or not name:
            raise ValueError("stability_probe: case 名字必须是非空字符串")
        entry = {"name": name, "outcome": "finite", "exc": "",
                 "message": "", "nan": 0, "inf": 0, "count": 0, "max_abs": 0.0}
        try:
            out = fn(payload)
        except allowed as exc:
            entry["outcome"] = "raised"
            entry["exc"] = type(exc).__name__
            entry["message"] = str(exc)[:160]
            reports.append(entry)
            continue
        except Exception as exc:                # 不在白名单里的异常也算不合格
            entry["outcome"] = "raised"
            entry["exc"] = type(exc).__name__
            entry["message"] = str(exc)[:160]
            failed.append(name)
            reports.append(entry)
            continue
        scan = numeric_scan(out)
        entry.update({"nan": scan["nan"], "inf": scan["inf"],
                      "count": scan["count"], "max_abs": scan["max_abs"]})
        if scan["nan"] > 0:
            entry["outcome"] = "nan"
            failed.append(name)
        elif scan["inf"] > 0 and not allow_inf:
            entry["outcome"] = "inf"
            failed.append(name)
        reports.append(entry)

    return {"ok": not failed, "failed": failed, "cases": reports}


def _w18b_user_why():
    """占位助手（保持本分节自洽，无外部依赖）"""
    return "要么返回全有限值，要么显式报错——不要静默产生 NaN"


# ============================================================================
#  研究前沿：把 NTK / 双下降 / grokking 当作「已知边界」来测量
# ============================================================================

def _w20e_net(model):
    net = getattr(model, "model", model)
    if getattr(net, "layers", None) is None:
        raise ValueError("empirical_ntk 需要 MLP（或带 .model 的 Model）")
    return net


def _w20e_flat_grads(grads):
    out = []
    for item in grads:
        if item is None:
            continue
        grad_w, grad_b = item
        for row in grad_w:
            out.extend(row)
        out.extend(grad_b)
    return out


def empirical_ntk(model, xs):
    """经验 NTK：`K_ij = <∂f(x_i)/∂θ, ∂f(x_j)/∂θ>`（单输出网络）。

    **这是有限宽网络的经验核，不是无穷宽极限的理论 NTK**：它依赖当前权重，
    训练过程中会变；只有在「网络很宽 + 学习率小」时才近似常数核。
    输入 `xs` 是若干样本（每行一个），返回 `n × n` 对称半正定矩阵。
    """
    net = _w20e_net(model)
    if not isinstance(xs, list) or not xs:
        raise ValueError("empirical_ntk.xs 必须是非空列表")
    rows = []
    for sample in xs:
        if not isinstance(sample, list) or not sample:
            raise ValueError("empirical_ntk.xs 里每个样本必须是非空列表")
        for value in sample:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError("empirical_ntk.xs 里必须是数字")
        out = net.forward(sample)
        if len(out) != 1:
            raise ValueError("empirical_ntk 只支持单输出网络（当前输出 %d 维）" % len(out))
        grads = _mlp_backward(net, [1.0])
        rows.append(_w20e_flat_grads(grads))
    width = len(rows[0])
    for row in rows:
        if len(row) != width:
            raise ValueError("empirical_ntk: 各样本的参数梯度长度不一致")
    matrix = []
    for i in range(len(rows)):
        line = []
        for j in range(len(rows)):
            total = 0.0
            for k in range(width):
                total += rows[i][k] * rows[j][k]
            line.append(total)
        matrix.append(line)
    return matrix


def ntk_kernel_regression(k_train, y_train, k_test, ridge=1e-8):
    """用核岭回归做预测：`α = (K + ridge·I)^{-1} y`，`pred = K_test · α`。

    `k_train` 是训练集自身核矩阵、`k_test` 是「测试 × 训练」核矩阵。
    这是 NTK 视角下的「闭式解」，和梯度下降训练不是同一个东西（只在
    线性化/小步长下才等价）。
    """
    if not isinstance(k_train, list) or not k_train:
        raise ValueError("ntk_kernel_regression.k_train 必须是非空矩阵")
    n = len(k_train)
    for row in k_train:
        if not isinstance(row, list) or len(row) != n:
            raise ValueError("ntk_kernel_regression.k_train 必须是方阵")
    if not isinstance(y_train, list) or len(y_train) != n:
        raise ValueError("ntk_kernel_regression.y_train 长度与 k_train 不一致")
    for k_test_row in k_test:
        if not isinstance(k_test_row, list) or len(k_test_row) != n:
            raise ValueError("ntk_kernel_regression.k_test 每行长度必须是训练样本数")
    if isinstance(ridge, bool) or not isinstance(ridge, (int, float)) or ridge <= 0.0:
        raise ValueError("ntk_kernel_regression.ridge 必须是正数")
    system = [[k_train[i][j] + (ridge if i == j else 0.0) for j in range(n)]
              for i in range(n)]
    alpha = _w11f_solve(system, [float(value) for value in y_train])
    if alpha is None:
        raise ValueError("ntk_kernel_regression: 核矩阵奇异，请增大 ridge")
    return [sum(k_test_row[j] * alpha[j] for j in range(n)) for k_test_row in k_test]


def double_descent_curve(n_samples=30, dims=(4, 8, 16, 24, 30, 40, 60, 120),
                         n_test=200, n_inputs=20, noise=0.1, ridge=1e-10, seed=12345):
    """随机特征模型上的双下降曲线（最小范数解）。

    模型：`f(x) = Σ_{j=1}^{p} a_j · relu(w_j · x)`，`p` 是特征数（模型容量）。
    `p <= n` 时解原始空间 `(ΦᵀΦ + ridge·I)w = Φᵀy`（数值稳定），`p > n` 时解
    对偶空间 `(ΦΦᵀ + ridge·I)α = y`（给出最小范数解）。当 `p ≈ n` 时参数刚好
    够插值训练集，测试误差出现峰值；`p` 继续增大则最小范数解重新变得平滑，
    误差二次下降——这就是「双下降」。

    返回 `{"dims", "train_mse", "test_mse", "peak_dim"}`；
    这是**线性化/闭式解**下的演示，不是用 SGD 训练出来的曲线。
    """
    if isinstance(n_samples, bool) or not isinstance(n_samples, int) or n_samples < 2:
        raise ValueError("double_descent_curve.n_samples 必须是 >= 2 的整数")
    if not isinstance(dims, (list, tuple)) or not dims:
        raise ValueError("double_descent_curve.dims 必须是非空序列")
    for value in dims:
        if isinstance(value, bool) or not isinstance(value, int) or value < 1:
            raise ValueError("double_descent_curve.dims 里必须是 >= 1 的整数")
    if isinstance(n_test, bool) or not isinstance(n_test, int) or n_test < 1:
        raise ValueError("double_descent_curve.n_test 必须是 >= 1 的整数")
    if isinstance(noise, bool) or not isinstance(noise, (int, float)) or noise < 0.0:
        raise ValueError("double_descent_curve.noise 必须是非负数")
    rng = random.Random(seed)
    true_w = [rng.gauss(0.0, 1.0) for _ in range(n_inputs)]

    def sample():
        return [rng.gauss(0.0, 1.0) for _ in range(n_inputs)]

    def target(x):
        return math.tanh(sum(true_w[d] * x[d] for d in range(n_inputs)))

    xs = [sample() for _ in range(n_samples)]
    ys = [target(x) + rng.gauss(0.0, noise) for x in xs]
    test_xs = [sample() for _ in range(n_test)]
    test_ys = [target(x) for x in test_xs]

    out_dims = []
    train_mse = []
    test_mse = []
    for width in dims:
        ws = [[rng.gauss(0.0, 1.0) for _ in range(n_inputs)] for _ in range(width)]
        phi = [[max(0.0, sum(ws[j][d] * x[d] for d in range(n_inputs))) for j in range(width)]
               for x in xs]
        phi_test = [[max(0.0, sum(ws[j][d] * x[d] for d in range(n_inputs))) for j in range(width)]
                    for x in test_xs]
        if width <= n_samples:
            # 欠参数化端：直接解 (ΦᵀΦ + λI) w = Φᵀy。p × p 系统比对偶的 n × n 更稳定：
            # p << n 时 ΦΦᵀ 只有 p 个非零特征值，ridge 再小也会把对偶解放大到 1e7 量级
            # （实测 dims=4、ridge=1e-10 时 test_mse 曾达 7.9e7，把双下降的峰盖掉了）。
            gram = [[sum(phi[i][a] * phi[i][b] for i in range(n_samples)) for b in range(width)]
                    for a in range(width)]
            rhs = [sum(phi[i][j] * ys[i] for i in range(n_samples)) for j in range(width)]
            weights = _w11f_solve([[gram[a][b] + (ridge if a == b else 0.0)
                                    for b in range(width)] for a in range(width)], rhs)
            if weights is None:
                raise ValueError("double_descent_curve: 特征 Gram 矩阵奇异（把 ridge 调大）")
            fit = [sum(phi[i][j] * weights[j] for j in range(width)) for i in range(n_samples)]
            preds = [sum(phi_test[t][j] * weights[j] for j in range(width))
                     for t in range(n_test)]
        else:
            # 过参数化端：对偶形式天然给出最小范数解（p > n 时 Φᵀ(ΦΦᵀ)^{-1} y）
            kernel = [[sum(phi[i][j] * phi[k][j] for j in range(width)) for k in range(n_samples)]
                      for i in range(n_samples)]
            system = [[kernel[i][j] + (ridge if i == j else 0.0) for j in range(n_samples)]
                      for i in range(n_samples)]
            alpha = _w11f_solve(system, ys)
            if alpha is None:
                raise ValueError("double_descent_curve: 核矩阵奇异（把 ridge 调大）")
            fit = [sum(kernel[i][j] * alpha[j] for j in range(n_samples)) for i in range(n_samples)]
            preds = [sum(sum(phi_test[t][j] * phi[i][j] for j in range(width)) * alpha[i]
                         for i in range(n_samples)) for t in range(n_test)]
        out_dims.append(width)
        train_mse.append(sum((fit[i] - ys[i]) ** 2 for i in range(n_samples)) / n_samples)
        test_mse.append(sum((preds[t] - test_ys[t]) ** 2 for t in range(n_test)) / n_test)
    peak_index = max(range(len(out_dims)), key=lambda i: test_mse[i])
    return {"dims": out_dims, "train_mse": train_mse, "test_mse": test_mse,
            "peak_dim": out_dims[peak_index]}

# ============================================================================
#  研究前沿：神经符号（规则约束的候选过滤）
# ============================================================================

def _w20d_sequence(values, what):
    if not isinstance(values, list):
        raise ValueError("%s 必须是列表" % what)
    out = []
    for value in values:
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError("%s 里必须是整数 token" % what)
        if value < 0:
            raise ValueError("%s 里不能有负 token" % what)
        out.append(value)
    return out


def _w20d_mask(mask, vocab_size):
    if not isinstance(mask, list) or not mask:
        raise ValueError("掩码必须是非空列表")
    if len(mask) != vocab_size:
        raise ValueError("掩码长度 %d 与词表 %d 不一致" % (len(mask), vocab_size))
    for value in mask:
        if not isinstance(value, bool):
            raise ValueError("掩码必须是布尔值（isinstance 判断，1 不算 True）")
    return mask


def rule_no_repeat(prefix, token):
    """规则：同一个 token 不重复出现。"""
    return token not in prefix


def rule_max_length(limit):
    """规则工厂：序列长度不超过 `limit`。"""
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 1:
        raise ValueError("rule_max_length 的 limit 必须是 >= 1 的整数")

    def _rule(prefix, token):
        return len(prefix) < limit

    return _rule


def rule_allowed_set(allowed):
    """规则工厂：token 必须属于给定白名单。"""
    if not isinstance(allowed, (list, tuple, set)) or not allowed:
        raise ValueError("rule_allowed_set 的 allowed 必须是非空集合")
    values = set()
    for value in allowed:
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError("rule_allowed_set 里必须是非负整数")
        values.add(value)

    def _rule(prefix, token):
        return token in values

    return _rule


class RuleSet:
    """一组「(名字, 谓词(prefix, token) -> bool)」规则，用来约束解码候选。"""

    def __init__(self, rules=None):
        if rules is None:
            rules = []
        if not isinstance(rules, (list, tuple)):
            raise ValueError("RuleSet 的 rules 必须是列表")
        self.rules = []
        seen = set()
        for item in rules:
            if not isinstance(item, (list, tuple)) or len(item) != 2:
                raise ValueError("每条规则必须是 (名字, 谓词)")
            name, predicate = item
            if not isinstance(name, str) or not name:
                raise ValueError("规则名字必须是非空字符串")
            if name in seen:
                raise ValueError("规则名字重复：%s" % name)
            if not callable(predicate):
                raise ValueError("规则 %s 的谓词必须可调用" % name)
            seen.add(name)
            self.rules.append((name, predicate))

    def names(self):
        return [name for name, _predicate in self.rules]

    def allows(self, prefix, token):
        prefix = _w20d_sequence(prefix, "RuleSet.allows.prefix")
        if isinstance(token, bool) or not isinstance(token, int) or token < 0:
            raise ValueError("RuleSet.allows.token 必须是非负整数")
        for _name, predicate in self.rules:
            if not predicate(prefix, token):
                return False
        return True

    def mask(self, prefix, vocab_size):
        if isinstance(vocab_size, bool) or not isinstance(vocab_size, int) or vocab_size < 1:
            raise ValueError("vocab_size 必须是 >= 1 的整数")
        return [self.allows(prefix, token) for token in range(vocab_size)]

    def filter(self, prefix, candidates):
        candidates = _w20d_sequence(candidates, "RuleSet.filter.candidates")
        return [token for token in candidates if self.allows(prefix, token)]

    def check(self, sequence):
        """检查整条序列：返回 `{ok, violations}`，逐位置列出被哪些规则拒绝。"""
        sequence = _w20d_sequence(sequence, "RuleSet.check.sequence")
        violations = []
        for position, token in enumerate(sequence):
            prefix = sequence[:position]
            broken = [name for name, predicate in self.rules if not predicate(prefix, token)]
            if broken:
                violations.append({"position": position, "token": token, "rules": broken})
        return {"ok": not violations, "violations": violations}


def apply_rule_mask(logits, mask):
    """把 `mask` 为 False 的位置设成 `-inf`（其余原样），返回新列表。

    如果全部被屏蔽，说明规则和模型输出完全不兼容——这是配置错误，
    直接抛 ValueError，而不是返回全 `-inf` 让下游 softmax 变成 NaN。
    """
    if not isinstance(logits, list) or not logits:
        raise ValueError("apply_rule_mask.logits 必须是非空列表")
    mask = _w20d_mask(mask, len(logits))
    values = []
    for value in logits:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("apply_rule_mask.logits 里必须是数字")
        values.append(float(value))
    if not any(mask):
        raise ValueError("apply_rule_mask: 所有候选都被规则屏蔽了")
    return [values[i] if mask[i] else float("-inf") for i in range(len(values))]


def constrained_pick(logits, mask):
    """在允许的候选里取 argmax（同分取小下标），返回 token。"""
    masked = apply_rule_mask(logits, mask)
    best = None
    for index, value in enumerate(masked):
        if value == float("-inf"):
            continue
        if best is None or value > masked[best]:
            best = index
    if best is None:
        raise ValueError("constrained_pick: 没有可选的候选")
    return best


def constrained_generate(step_fn, rules, max_len=8, vocab_size=None, seed_token=None):
    """规则约束的贪心解码。

    `step_fn(prefix)` 返回下一个 token 的 logits；`rules` 是 `RuleSet`；
    `vocab_size` 省略时按第一次 `len(logits)` 推断。返回 `{"tokens", "logits", "steps"}`，
    其中 `logits` 是每步**被屏蔽后**的分布（被屏蔽位置为 `-inf`）。
    """
    if not callable(step_fn):
        raise ValueError("constrained_generate: step_fn 必须可调用")
    if not isinstance(rules, RuleSet):
        raise ValueError("constrained_generate: rules 必须是 RuleSet")
    if isinstance(max_len, bool) or not isinstance(max_len, int) or max_len < 1:
        raise ValueError("constrained_generate: max_len 必须是 >= 1 的整数")
    tokens = [] if seed_token is None else _w20d_sequence([seed_token], "seed_token")
    trace = []
    for _step in range(max_len):
        logits = step_fn(list(tokens))
        if not isinstance(logits, list) or not logits:
            raise ValueError("constrained_generate: step_fn 必须返回非空 logits")
        size = len(logits) if vocab_size is None else vocab_size
        if size != len(logits):
            raise ValueError("constrained_generate: 实际 logits 宽度 %d 与 vocab_size %d 不一致"
                             % (len(logits), size))
        mask = rules.mask(list(tokens), size)
        if not any(mask):
            raise ValueError("constrained_generate: 第 %d 步没有合法候选" % (_step + 1))
        masked = apply_rule_mask(logits, mask)
        tokens.append(constrained_pick(logits, mask))
        trace.append(masked)
    return {"tokens": tokens, "logits": trace, "steps": len(trace)}

# ============================================================================
#  研究前沿：Mixture-of-Depths 路由与 Early Exit
# ============================================================================

def _w20c_numbers(values, what):
    if not isinstance(values, list) or not values:
        raise ValueError("%s 必须是非空列表" % what)
    out = []
    for value in values:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("%s 里必须是数字" % what)
        if value != value or value in (float("inf"), float("-inf")):
            raise ValueError("%s 里不能有 NaN/inf" % what)
        out.append(float(value))
    return out


def _w20c_ratio(value, what, allow_one=True):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError("%s 必须是数字" % what)
    number = float(value)
    upper_ok = number <= 1.0 if allow_one else number < 1.0
    if not 0.0 < number or not upper_ok:
        raise ValueError("%s 必须在 (0, %s] 之间" % (what, "1" if allow_one else "1)"))
    return number


def mix_of_depths_route(scores, capacity_ratio=0.5):
    """MoD 路由：按分数取前 `capacity` 个 token 过这个块，其余走残差直通。

    - `scores`：每个 token 一个路由分数（logit 或概率都可，只用来排序）；
    - `capacity = max(1, ceil(n * capacity_ratio))`；
    - 返回 `{"mask", "capacity", "weights", "kept", "dropped_mass"}`，
      其中 `weights` 是**在入选 token 内**归一化的 softmax（和为 1，未入选为 0），
      `dropped_mass` 是没入选 token 的概率质量（诊断用，越小说明容量越够）。
    """
    values = _w20c_numbers(scores, "mix_of_depths_route.scores")
    ratio = _w20c_ratio(capacity_ratio, "capacity_ratio")
    count = len(values)
    capacity = max(1, int(math.ceil(count * ratio)))
    capacity = min(count, capacity)
    order = sorted(range(count), key=lambda i: (-values[i], i))
    chosen = set(order[:capacity])
    mask = [i in chosen for i in range(count)]
    peak = max(values)
    exps = [math.exp(value - peak) for value in values]
    total = sum(exps)
    probs = [value / total for value in exps]
    kept_denom = sum(probs[i] for i in chosen)
    weights = [(probs[i] / kept_denom) if i in chosen else 0.0 for i in range(count)]
    dropped = sum(probs[i] for i in range(count) if i not in chosen)
    return {"mask": mask, "capacity": capacity, "weights": weights,
            "kept": sorted(chosen), "dropped_mass": dropped}


def apply_mod_block(residual, block_output, mask):
    """按 MoD 掩码把块输出写回残差：入选 token 加 `block_output`，其余原样透传。"""
    if not isinstance(residual, list) or not residual:
        raise ValueError("apply_mod_block.residual 必须是非空列表")
    if not isinstance(block_output, list) or len(block_output) != len(residual):
        raise ValueError("apply_mod_block: block_output 与 residual 长度不一致")
    if not isinstance(mask, list) or len(mask) != len(residual):
        raise ValueError("apply_mod_block: mask 长度与 token 数不一致")
    out = []
    for index, row in enumerate(residual):
        if not isinstance(row, list):
            raise ValueError("apply_mod_block: residual 每行必须是列表")
        if not isinstance(mask[index], bool):
            # 注意用 isinstance 而不是 in (True, False)：
            # Python 里 1 == True，后者会放过整数 1。
            raise ValueError("apply_mod_block: mask 必须是布尔值")
        if mask[index]:
            block_row = block_output[index]
            if not isinstance(block_row, list) or len(block_row) != len(row):
                raise ValueError("apply_mod_block: 第 %d 行的块输出宽度不一致" % index)
            out.append([row[j] + block_row[j] for j in range(len(row))])
        else:
            out.append(list(row))
    return out


def early_exit(layer_probs, threshold=0.9):
    """早退：逐样本看第一个「最大类概率 >= threshold」的层，没有就用最后一层。

    `layer_probs` 形如 `[层][样本][类别]`，每层样本数必须相同、每行概率和为 1（容差 1e-6）。
    返回 `{"predictions", "exit_layer", "confidence"}`，`exit_layer` 是 0 起的层号。
    """
    if not isinstance(layer_probs, list) or not layer_probs:
        raise ValueError("early_exit: 需要至少一层的概率")
    limit = _w20c_ratio(threshold, "threshold")
    n_samples = len(layer_probs[0])
    if n_samples == 0:
        raise ValueError("early_exit: 每层至少一个样本")
    for index, layer in enumerate(layer_probs):
        if not isinstance(layer, list) or len(layer) != n_samples:
            raise ValueError("early_exit: 第 %d 层样本数与第一层不一致" % index)
        for row in layer:
            values = _w20c_numbers(row, "early_exit.layer_probs")
            if abs(sum(values) - 1.0) > 1e-6:
                raise ValueError("early_exit: 第 %d 层有概率和不为 1 的行" % index)
    predictions = []
    exits = []
    confidences = []
    for sample in range(n_samples):
        exit_at = len(layer_probs) - 1
        for index, layer in enumerate(layer_probs):
            row = layer[sample]
            if max(row) >= limit:
                exit_at = index
                break
        row = layer_probs[exit_at][sample]
        best = max(range(len(row)), key=lambda c: (row[c], -c))
        predictions.append(best)
        exits.append(exit_at)
        confidences.append(row[best])
    return {"predictions": predictions, "exit_layer": exits, "confidence": confidences}


def early_exit_savings(exit_layers, n_layers):
    """按早退层号算平均深度与相对全深的计算节省比例。"""
    if isinstance(n_layers, bool) or not isinstance(n_layers, int) or n_layers < 1:
        raise ValueError("n_layers 必须是 >= 1 的整数")
    if not isinstance(exit_layers, list) or not exit_layers:
        raise ValueError("exit_layers 必须是非空列表")
    depths = []
    for value in exit_layers:
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError("exit_layers 里必须是整数层号")
        if not 0 <= value < n_layers:
            raise ValueError("层号 %r 超出 [0, %d)" % (value, n_layers))
        depths.append(value + 1)
    mean_depth = sum(depths) / len(depths)
    full = n_layers * len(depths)
    return {"mean_depth": mean_depth,
            "relative_depth": mean_depth / n_layers,
            "savings": 1.0 - (sum(depths) / full),
            "n_layers": n_layers}

# ============================================================================
#  研究前沿：Lottery Ticket（迭代幅度剪枝 + 掩码内重初始化）
# ============================================================================

def _w20b_net(model):
    net = getattr(model, "model", model)
    layers = getattr(net, "layers", None)
    if not isinstance(layers, list):
        raise ValueError("这个功能需要 MLP（或带 .model 的 Model）")
    return net


def _w20b_ratio(value, what, allow_zero=True, allow_one=False):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError("%s 必须是数字" % what)
    number = float(value)
    if allow_one:
        if not 0.0 <= number <= 1.0:
            raise ValueError("%s 必须在 [0, 1] 之间" % what)
    elif not 0.0 <= number < 1.0:
        raise ValueError("%s 必须在 [0, 1) 之间" % what)
    if number == 0.0 and not allow_zero:
        raise ValueError("%s 必须大于 0" % what)
    return number


def _w20b_masked_layers(model):
    net = _w20b_net(model)
    return [(index, layer) for index, layer in enumerate(net.layers)
            if getattr(layer, "weights", None) is not None]


def weight_mask(model, keep_ratio=0.5):
    """按幅度生成**全局**掩码（跨层统一阈值），返回与 `weights` 同形的 bool 矩阵。

    `keep_ratio=1.0` 表示全保留；`keep_ratio=0.5` 保留绝对值最大的那一半参数。
    同幅度时的取舍按「层号 → 行 → 列」的固定顺序，保证结果可复现。
    """
    keep = _w20b_ratio(keep_ratio, "keep_ratio", allow_one=True)
    entries = []
    for index, layer in _w20b_masked_layers(model):
        for row in range(layer.fan_out):
            for col in range(layer.fan_in):
                entries.append((abs(layer.weights[row][col]), index, row, col))
    if not entries:
        raise ValueError("weight_mask: 模型没有可剪的权重")
    entries.sort(key=lambda item: (-item[0], item[1], item[2], item[3]))
    keep_count = int(round(keep * len(entries)))
    keep_count = max(1, min(len(entries), keep_count)) if keep > 0.0 else 0
    keep_set = {(item[1], item[2], item[3]) for item in entries[:keep_count]}
    masks = {}
    for index, layer in _w20b_masked_layers(model):
        masks[index] = [[(index, row, col) in keep_set for col in range(layer.fan_in)]
                        for row in range(layer.fan_out)]
    return masks


def mask_sparsity(mask):
    """返回掩码的零比例（0 表示全保留、1 表示全剪）。"""
    total = 0
    zeros = 0
    for rows in mask.values():
        for row in rows:
            for value in row:
                total += 1
                if not value:
                    zeros += 1
    if total == 0:
        raise ValueError("mask_sparsity: 掩码里没有参数")
    return zeros / total


def apply_weight_mask(model, mask):
    """把掩码外（False）的权重清零，返回被清零的个数（原地修改）。"""
    if not isinstance(mask, dict) or not mask:
        raise ValueError("apply_weight_mask 需要 weight_mask 返回的 dict")
    pruned = 0
    for index, layer in _w20b_masked_layers(model):
        if index not in mask:
            raise ValueError("掩码缺少第 %d 层" % index)
        rows = mask[index]
        if len(rows) != layer.fan_out or any(len(row) != layer.fan_in for row in rows):
            raise ValueError("第 %d 层掩码形状与权重不一致" % index)
        for row in range(layer.fan_out):
            for col in range(layer.fan_in):
                if not rows[row][col]:
                    if layer.weights[row][col] != 0.0:
                        pruned += 1
                    layer.weights[row][col] = 0.0
    return pruned


def masked_reinit(model, mask, seed=None):
    """在掩码内重新初始化（He 初始化），掩码外清零；返回被重新初始化的个数。

    「彩票假说」的关键一步：结构（掩码）不变、保留下来的权重回到初始分布。
    """
    if not isinstance(mask, dict) or not mask:
        raise ValueError("masked_reinit 需要 weight_mask 返回的 dict")
    rng = random.Random(seed) if seed is not None else random.Random()
    touched = 0
    for index, layer in _w20b_masked_layers(model):
        if index not in mask:
            raise ValueError("掩码缺少第 %d 层" % index)
        rows = mask[index]
        if len(rows) != layer.fan_out or any(len(row) != layer.fan_in for row in rows):
            raise ValueError("第 %d 层掩码形状与权重不一致" % index)
        std = math.sqrt(2.0 / layer.fan_in)
        for row in range(layer.fan_out):
            for col in range(layer.fan_in):
                if rows[row][col]:
                    layer.weights[row][col] = rng.gauss(0.0, std)
                    touched += 1
                else:
                    layer.weights[row][col] = 0.0
    return touched


def lottery_ticket(model, train_fn, score_fn, rounds=3, prune_rate=0.2, reinit=True, seed=None):
    """迭代幅度剪枝：训练 → 评分 → 剪 `prune_rate` → （可选）掩码内重初始化。

    - `train_fn(model)`：把这轮训练跑完（可以什么都不做即「只评估」）；
    - `score_fn(model)`：返回一个标量分数（越大越好，比如验证集准确率）；
    - 掩码是**累积**的：每轮在上一轮保留的集合里再按幅度剪，不会把剪掉的又捡回来。

    返回 `[{"round", "keep_ratio", "score", "pruned", "kept_params"}, ...]`，
    `keep_ratio` 是这一轮**实际**保留的参数比例（向下取整可能让比例略低于理论值）。
    """
    if isinstance(rounds, bool) or not isinstance(rounds, int) or rounds < 1:
        raise ValueError("rounds 必须是 >= 1 的整数")
    if not callable(train_fn) or not callable(score_fn):
        raise ValueError("train_fn / score_fn 必须可调用")
    rate = _w20b_ratio(prune_rate, "prune_rate")
    if rate == 0.0:
        raise ValueError("prune_rate 必须大于 0")
    history = []
    mask = None
    for round_index in range(1, rounds + 1):
        train_fn(model)
        score = score_fn(model)
        if mask is None:
            mask = weight_mask(model, 1.0)
        else:
            # 累积掩码：只在**当前还保留**的参数里再按幅度剪，
            # 否则把已清零的权重也参与排序，剪枝会在第一轮之后失效。
            mask = _w20b_prune_within(model, mask, 1.0 - rate)
        pruned = apply_weight_mask(model, mask)
        kept = sum(1 for rows in mask.values() for row in rows for value in row if value)
        history.append({
            "round": round_index,
            "keep_ratio": kept / max(1, sum(len(rows) * len(rows[0]) if rows else 0
                                            for rows in mask.values())),
            "score": score,
            "pruned": pruned,
            "kept_params": kept,
        })
        if reinit:
            masked_reinit(model, mask, seed=None if seed is None else seed + round_index)
    return history


def _w20b_prune_within(model, mask, keep_ratio):
    """在 `mask` 已保留的参数里再按幅度保留 `keep_ratio`，其余置 False。"""
    entries = []
    for index, layer in _w20b_masked_layers(model):
        if index not in mask:
            raise ValueError("掩码缺少第 %d 层" % index)
        rows = mask[index]
        if len(rows) != layer.fan_out or any(len(row) != layer.fan_in for row in rows):
            raise ValueError("第 %d 层掩码形状与权重不一致" % index)
        for row in range(layer.fan_out):
            for col in range(layer.fan_in):
                if rows[row][col]:
                    entries.append((abs(layer.weights[row][col]), index, row, col))
    if not entries:
        raise ValueError("prune_within: 掩码里已经没有可剪的参数")
    keep_count = int(round(keep_ratio * len(entries)))
    keep_count = max(0, min(len(entries), keep_count))
    keep_set = {(item[1], item[2], item[3]) for item in
                sorted(entries, key=lambda item: (-item[0], item[1], item[2], item[3]))[:keep_count]}
    out = {}
    for index, _layer in _w20b_masked_layers(model):
        out[index] = [[(index, r, c) in keep_set for c in range(len(mask[index][r]))]
                      for r in range(len(mask[index]))]
    return out


def _w20b_intersect(model, old_mask, new_mask):
    out = {}
    for index, _layer in _w20b_masked_layers(model):
        if index not in old_mask or index not in new_mask:
            raise ValueError("掩码层号不一致")
        out[index] = [[old_mask[index][r][c] and new_mask[index][r][c]
                       for c in range(len(new_mask[index][r]))]
                      for r in range(len(new_mask[index]))]
    return out


def ticket_smaller_than(model_a, model_b, keep_ratio=0.5):
    """诊断用：在相同评分下比较「剪枝后」与「同规模随机初始化」的训练曲线。

    只做参数统计，不训练；返回 `{count_a, count_b, ratio}`。
    """
    _w20b_net(model_a)
    _w20b_net(model_b)
    count_a = sum(1 for layer in _w20b_net(model_a).layers
                  if getattr(layer, "weights", None) is not None
                  for row in layer.weights for value in row if value != 0.0)
    count_b = sum(1 for layer in _w20b_net(model_b).layers
                  if getattr(layer, "weights", None) is not None
                  for row in layer.weights for value in row if value != 0.0)
    return {"count_a": count_a, "count_b": count_b,
            "ratio": (count_a / count_b) if count_b else 0.0}

# ============================================================================
#  研究前沿：DP-SGD（裁剪 + 噪声 + 隐私记账）与成员推断
# ============================================================================

def squeeze_grads(grads):
    """把 `_mlp_backward` 的 `(grad_w, grad_b)` 列表摊成数字列表（None 跳过）。"""
    if not isinstance(grads, list):
        raise ValueError("squeeze_grads 需要梯度列表")
    flat = []
    for item in grads:
        if item is None:
            continue
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("每层梯度必须是 (grad_w, grad_b) 二元组")
        for part in item:
            _w20_flatten_into(part, flat)
    return flat


def _w20_flatten_into(value, out):
    if isinstance(value, (list, tuple)):
        for item in value:
            _w20_flatten_into(item, out)
        return
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError("梯度里出现非数值: %r" % (value,))
    out.append(float(value))


def _w20_map(value, fn):
    if isinstance(value, (list, tuple)):
        return [_w20_map(item, fn) for item in value]
    return fn(float(value))


def _w20_pos(value, what, allow_zero=True):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError("%s 必须是数字" % what)
    if value < 0 or (value == 0 and not allow_zero):
        raise ValueError("%s 必须 %s" % (what, "非负" if allow_zero else "为正"))
    return float(value)


def clip_grads_global(grads, max_norm):
    """按**全局 L2 范数**裁剪：超阈值时整体等比缩小。

    返回 `(new_grads, info)`，`info` 含 `norm` / `clip_scale` / `clipped`。
    与逐层裁剪（`clip_grad_by_norm`）不同，这里范数是所有层合并算的，DP-SGD 需要这个口径。
    """
    limit = _w20_pos(max_norm, "max_norm", allow_zero=False)
    flat = squeeze_grads(grads)
    norm = math.sqrt(sum(v * v for v in flat)) if flat else 0.0
    scale = 1.0 if norm <= limit or norm == 0.0 else limit / norm
    new_grads = [None if item is None else (_w20_map(item[0], lambda v: v * scale),
                                            _w20_map(item[1], lambda v: v * scale))
                 for item in grads]
    return new_grads, {"norm": norm, "clip_scale": scale, "clipped": scale < 1.0}


def dp_grads(grads, max_norm, noise_multiplier=1.0, seed=None):
    """一步 DP-SGD 的梯度处理：先全局裁剪，再加 `N(0, (σ·C)²)` 噪声。

    `σ = noise_multiplier`、`C = max_norm`；噪声加在每个坐标上（与裁剪后的敏感度匹配）。
    返回 `(new_grads, info)`，`info` 额外含 `noise_std` 与 `steps` 增量所需的信息。
    """
    sigma = _w20_pos(noise_multiplier, "noise_multiplier")
    clipped, info = clip_grads_global(grads, max_norm)
    std = sigma * float(max_norm)
    rng = random.Random(seed) if seed is not None else random
    noisy = []
    for item in clipped:
        if item is None:
            noisy.append(None)
            continue
        noisy.append((_w20_map(item[0], lambda v: v + rng.gauss(0.0, std)),
                      _w20_map(item[1], lambda v: v + rng.gauss(0.0, std))))
    info = dict(info)
    info["noise_std"] = std
    info["noise_multiplier"] = sigma
    return noisy, info


class PrivacyAccountant:
    """最简隐私预算记账：高斯机制的**简单组合**上界。

    单步：`eps_step = q * sqrt(2 * ln(1.25 / delta)) / sigma`（`q` = 采样率，`delta` 见下）。
    `T` 步简单组合 `eps_total = T * eps_step`（可用 `advanced=True` 换成
    高级组合的 `sqrt(2T ln(1/delta)) * eps_step + T eps_step (e^eps_step - 1)`）。

    这是**上界**且偏松：真实 RDP / 矩记账会给更小的值。本库只保证「口径写清楚、可复现」，
    不声称与 opacus 之类的数字一致。
    """

    def __init__(self, noise_multiplier, sample_rate=1.0, delta=1e-5, advanced=False):
        self.sigma = _w20_pos(noise_multiplier, "noise_multiplier", allow_zero=False)
        self.q = _w20_pos(sample_rate, "sample_rate")
        if not 0.0 < self.q <= 1.0:
            raise ValueError("sample_rate 必须在 (0, 1] 之间")
        if not 0.0 < float(delta) < 1.0:
            raise ValueError("delta 必须在 (0, 1) 之间")
        self.delta = float(delta)
        self.advanced = bool(advanced)
        self.steps = 0

    @property
    def eps_step(self):
        return self.q * math.sqrt(2.0 * math.log(1.25 / self.delta)) / self.sigma

    def step(self, times=1):
        """记账 `times` 步，返回当前累计 epsilon。"""
        if isinstance(times, bool) or not isinstance(times, int) or times < 1:
            raise ValueError("times 必须是 >= 1 的整数")
        self.steps += times
        return self.epsilon

    @property
    def epsilon(self):
        if self.steps == 0:
            return 0.0
        base = self.steps * self.eps_step
        if not self.advanced:
            return base
        adv = self.eps_step * math.sqrt(2.0 * self.steps * math.log(1.0 / self.delta))
        return min(base, adv + self.steps * self.eps_step * math.expm1(self.eps_step))

    def summary(self):
        """返回 `{steps, sigma, sample_rate, delta, eps_step, epsilon, method}`。"""
        return {
            "steps": self.steps,
            "sigma": self.sigma,
            "sample_rate": self.q,
            "delta": self.delta,
            "eps_step": self.eps_step,
            "epsilon": self.epsilon,
            "method": "advanced" if self.advanced else "simple",
        }


def per_sample_losses(model, xs, ys):
    """逐样本损失（分类用交叉熵、回归用平方误差），成员推断的攻击信号就用它。"""
    net = getattr(model, "model", model)
    if not isinstance(xs, list) or not xs:
        raise ValueError("per_sample_losses: xs 不能为空")
    if not isinstance(ys, list) or len(ys) != len(xs):
        raise ValueError("per_sample_losses: ys 长度必须与 xs 一致")
    task = getattr(model, "task", None) or getattr(net, "task", None) or "regression"
    losses = []
    for x, y in zip(xs, ys):
        pred = net.forward(x)
        if task == "classification":
            target = y if isinstance(y, list) else _w20_onehot(y, len(pred))
            if len(target) != len(pred):
                raise ValueError("per_sample_losses: 标签维度与输出不一致")
            value = 0.0
            for p, t in zip(pred, target):
                value -= float(t) * math.log(max(float(p), 1e-300))
            losses.append(value)
        else:
            want = y[0] if isinstance(y, list) and len(y) == 1 else y
            if isinstance(want, list):
                raise ValueError("per_sample_losses: 回归标签必须是标量")
            losses.append((float(pred[0]) - float(want)) ** 2)
    return losses


def _w20_onehot(index, width):
    if isinstance(index, bool) or not isinstance(index, int):
        raise ValueError("分类标签必须是整数下标")
    if not 0 <= index < width:
        raise ValueError("分类标签越界: %d（输出维度 %d）" % (index, width))
    row = [0.0] * width
    row[index] = 1.0
    return row


def membership_inference_attack(member_losses, nonmember_losses, thresholds=None):
    """损失阈值成员推断（Shokri 式最简版）。

    设定：训练集样本的 loss 通常更低，所以规则是 `loss <= t` 判为「成员」。
    返回 `{threshold, accuracy, tpr, fpr, auc, best_accuracy}`：
    - `threshold` 是让 balanced accuracy 最大的阈值（候选来自两侧损失的均值）；
    - `auc` 是 Mann-Whitney 统计量，`P(loss_member < loss_nonmember)`。
    """
    if not isinstance(member_losses, list) or not member_losses:
        raise ValueError("member_losses 不能为空")
    if not isinstance(nonmember_losses, list) or not nonmember_losses:
        raise ValueError("nonmember_losses 不能为空")
    for values, name in ((member_losses, "member_losses"), (nonmember_losses, "nonmember_losses")):
        for value in values:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError("%s 里出现非数值" % name)
            if not math.isfinite(float(value)):
                raise ValueError("%s 里出现 NaN/inf" % name)
    members = [float(v) for v in member_losses]
    others = [float(v) for v in nonmember_losses]
    if thresholds is None:
        candidates = sorted({(a + b) / 2.0 for a in members for b in others})
    else:
        candidates = [float(t) for t in thresholds]
        if not candidates:
            raise ValueError("thresholds 不能为空列表")

    best = None
    for threshold in candidates:
        tpr = sum(1 for v in members if v <= threshold) / len(members)
        fpr = sum(1 for v in others if v <= threshold) / len(others)
        score = 0.5 * (tpr + (1.0 - fpr))
        if best is None or score > best["best_accuracy"] or (
                score == best["best_accuracy"] and threshold < best["threshold"]):
            best = {"threshold": threshold, "tpr": tpr, "fpr": fpr,
                    "accuracy": 0.5 * (tpr + (1.0 - fpr)), "best_accuracy": score}

    wins = 0.0
    for a in members:
        for b in others:
            if a < b:
                wins += 1.0
            elif a == b:
                wins += 0.5
    auc = wins / (len(members) * len(others))
    best["auc"] = auc
    best.pop("best_accuracy")
    return best


def membership_defense_delta(member_losses, nonmember_losses):
    """防御侧的一行结论：`abs(mean_member - mean_nonmember)` 与攻击 AUC 一起看。"""
    attack = membership_inference_attack(member_losses, nonmember_losses)
    mean_member = sum(member_losses) / len(member_losses)
    mean_other = sum(nonmember_losses) / len(nonmember_losses)
    return {
        "loss_gap": abs(mean_member - mean_other),
        "mean_member": mean_member,
        "mean_nonmember": mean_other,
        "attack_auc": attack["auc"],
        "attack_accuracy": attack["accuracy"],
    }

# ============================================================================
#  工程化收尾：配置文件 / 日志 / 内存监控 / 模型注册表
# ============================================================================

_W19C_NAME_RE = re.compile(r"^[A-Za-z0-9_.-]+$")


def _w19c_text(value, what):
    if not isinstance(value, str) or not value.strip():
        raise ValueError("%s 必须是非空字符串" % what)
    return value


def _w19c_scalar(text):
    """把 YAML/JSON 风格的标量文本转成 Python 值。"""
    low = text.lower()
    if low in ("true", "yes", "on"):
        return True
    if low in ("false", "no", "off"):
        return False
    if low in ("null", "none", "~"):
        return None
    if len(text) >= 2 and text[0] == text[-1] and text[0] in ("'", '"'):
        return text[1:-1]
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        pass
    if text.startswith("[") or text.startswith("{"):
        try:
            return json.loads(text)
        except ValueError:
            raise ValueError("配置里的内联 JSON 无法解析: %r" % text)
    return text


def _w19c_strip_comment(line):
    """去掉 `#` 之后的注释，但保留引号里的 `#`。"""
    out = []
    quote = None
    for ch in line:
        if quote:
            out.append(ch)
            if ch == quote:
                quote = None
            continue
        if ch in ("'", '"'):
            quote = ch
            out.append(ch)
            continue
        if ch == "#":
            break
        out.append(ch)
    return "".join(out).rstrip()


def parse_simple_yaml(text):
    """解析 YAML 的一个实用子集：嵌套映射、块列表、标量、`#` 注释。

    明确不支持：锚点/别名、多文档、块标量（`|` / `>`）、复杂键、标签。
    需要完整 YAML 请自己装 PyYAML，本库只保证「配置文件够用」。
    """
    if not isinstance(text, str):
        raise ValueError("parse_simple_yaml 需要字符串")
    raw = []
    for line in text.splitlines():
        stripped = _w19c_strip_comment(line)
        if not stripped.strip():
            continue
        if "\t" in stripped[:len(stripped) - len(stripped.lstrip())]:
            raise ValueError("YAML 缩进不能用制表符")
        indent = len(stripped) - len(stripped.lstrip(" "))
        raw.append((indent, stripped.strip()))
    if not raw:
        return {}

    def parse_block(start, indent):
        if raw[start][1].startswith("- "):
            return parse_list(start, indent)
        return parse_map(start, indent)

    def parse_map(start, indent):
        result = {}
        i = start
        while i < len(raw):
            cur_indent, content = raw[i]
            if cur_indent < indent:
                break
            if cur_indent > indent:
                raise ValueError("第 %d 行缩进不一致: %r" % (i + 1, content))
            if content.startswith("- "):
                break
            if ":" not in content:
                raise ValueError("第 %d 行不是 key: value: %r" % (i + 1, content))
            key, _, rest = content.partition(":")
            key = key.strip()
            rest = rest.strip()
            if not key:
                raise ValueError("第 %d 行缺少键名" % (i + 1))
            if rest:
                result[key] = _w19c_scalar(rest)
                i += 1
                continue
            i += 1
            if i < len(raw) and raw[i][0] > indent:
                result[key], i = parse_block(i, raw[i][0])
            else:
                result[key] = {}
        return result, i

    def parse_list(start, indent):
        result = []
        i = start
        while i < len(raw):
            cur_indent, content = raw[i]
            if cur_indent < indent or not content.startswith("- "):
                break
            if cur_indent > indent:
                raise ValueError("第 %d 行缩进不一致: %r" % (i + 1, content))
            item = content[2:].strip()
            if not item:
                i += 1
                if i < len(raw) and raw[i][0] > indent:
                    value, i = parse_block(i, raw[i][0])
                    result.append(value)
                else:
                    result.append(None)
                continue
            if ":" in item and not item.startswith(("'", '"')):
                key, _, rest = item.partition(":")
                entry = {key.strip(): _w19c_scalar(rest.strip())} if rest.strip() else {key.strip(): {}}
                i += 1
                if rest.strip() == "" and i < len(raw) and raw[i][0] > indent:
                    entry[key.strip()], i = parse_block(i, raw[i][0])
                while i < len(raw) and raw[i][0] > indent and not raw[i][1].startswith("- "):
                    sub_indent, sub = raw[i]
                    if ":" not in sub:
                        raise ValueError("第 %d 行不是 key: value: %r" % (i + 1, sub))
                    k2, _, r2 = sub.partition(":")
                    entry[k2.strip()] = _w19c_scalar(r2.strip()) if r2.strip() else {}
                    i += 1
                result.append(entry)
                continue
            result.append(_w19c_scalar(item))
            i += 1
        return result, i

    value, pos = parse_block(0, raw[0][0])
    if pos != len(raw):
        raise ValueError("YAML 解析在第 %d 行停下，剩余内容无法归并" % (pos + 1))
    return value


def dump_simple_yaml(value, indent=0):
    """把 dict/list/标量写成 `parse_simple_yaml` 能读回的文本。"""
    pad = " " * indent
    lines = []
    if isinstance(value, dict):
        for key in value:
            item = value[key]
            if isinstance(item, (dict, list)) and item:
                lines.append("%s%s:" % (pad, key))
                lines.append(dump_simple_yaml(item, indent + 2))
            else:
                lines.append("%s%s: %s" % (pad, key, _w19c_render(item)))
    elif isinstance(value, list):
        for item in value:
            if isinstance(item, dict) and item:
                keys = list(item)
                first = keys[0]
                rest = item[first]
                if isinstance(rest, (dict, list)) and rest:
                    lines.append("%s- %s:" % (pad, first))
                    lines.append(dump_simple_yaml(rest, indent + 4))
                else:
                    lines.append("%s- %s: %s" % (pad, first, _w19c_render(rest)))
                for key in keys[1:]:
                    sub = item[key]
                    if isinstance(sub, (dict, list)) and sub:
                        lines.append("%s  %s:" % (pad, key))
                        lines.append(dump_simple_yaml(sub, indent + 4))
                    else:
                        lines.append("%s  %s: %s" % (pad, key, _w19c_render(sub)))
            elif isinstance(item, list) and item:
                lines.append("%s-" % pad)
                lines.append(dump_simple_yaml(item, indent + 2))
            else:
                lines.append("%s- %s" % (pad, _w19c_render(item)))
    else:
        lines.append(pad + _w19c_render(value))
    return "\n".join(lines)


def _w19c_render(value):
    if value is None:
        return "null"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, (int, float)):
        if isinstance(value, float) and (value != value or value in (float("inf"), float("-inf"))):
            raise ValueError("配置文件里不能写 NaN/inf")
        return repr(value)
    if isinstance(value, str):
        if value == "" or any(ch in value for ch in ":#'\""):
            return "'%s'" % value.replace("'", "''")
        return value
    if isinstance(value, (dict, list)):
        return json.dumps(value, ensure_ascii=False, sort_keys=True)
    raise ValueError("不支持写进配置的类型: %r" % type(value))


def load_config(path):
    """按扩展名读配置：`.json` / `.yaml` / `.yml` / `.toml` / `.ini` / `.cfg`。

    TOML 走标准库 `tomllib`（Python 3.11+，只读）；INI 走 `configparser`，
    返回 `{section: {key: str}}`，`[DEFAULT]` 段并入每个 section。
    """
    _w19c_text(path, "配置路径")
    if not os.path.exists(path):
        raise ValueError("配置文件不存在: %s" % path)
    suffix = os.path.splitext(path)[1].lower()
    text = io.open(path, encoding="utf-8").read()
    return parse_config_text(text, suffix.lstrip(".") or "json", source=path)


def parse_config_text(text, fmt="json", source=None):
    """把配置文本解析成 dict；`fmt` 取 `json` / `yaml` / `yml` / `toml` / `ini`。"""
    if not isinstance(text, str):
        raise ValueError("parse_config_text 需要字符串")
    if not isinstance(fmt, str) or not fmt.strip():
        raise ValueError("fmt 必须是非空字符串")
    fmt = fmt.strip().lower()
    where = ("（%s）" % source) if source else ""
    if fmt == "json":
        try:
            value = json.loads(text)
        except ValueError as exc:
            raise ValueError("JSON 配置解析失败%s: %s" % (where, exc))
    elif fmt in ("yaml", "yml"):
        value = parse_simple_yaml(text)
    elif fmt == "toml":
        try:
            import tomllib
        except ImportError:  # pragma: no cover - 3.11+ 才有
            raise ValueError("当前 Python 没有 tomllib，TOML 配置需要 3.11+")
        try:
            value = tomllib.loads(text)
        except Exception as exc:
            raise ValueError("TOML 配置解析失败%s: %s" % (where, exc))
    elif fmt in ("ini", "cfg"):
        parser = _configparser().ConfigParser()
        parser.read_string(text)
        value = {section: dict(parser.items(section)) for section in parser.sections()}
        if parser.defaults():
            value["DEFAULT"] = dict(parser.defaults())
    else:
        raise ValueError("不支持的配置格式: %r（可用 json/yaml/toml/ini）" % fmt)
    if not isinstance(value, dict):
        raise ValueError("配置文件的顶层必须是映射（dict），实际是 %s%s" % (type(value).__name__, where))
    return value


def _configparser():
    import configparser
    return configparser


def dump_config(config, fmt="json"):
    """把 dict 写成配置文本；只支持 json 与 yaml（TOML 没有写回是刻意的）。"""
    if not isinstance(config, dict):
        raise ValueError("dump_config 只接受 dict")
    fmt = (fmt or "json").strip().lower()
    if fmt == "json":
        return json.dumps(config, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n"
    if fmt in ("yaml", "yml"):
        return dump_simple_yaml(config) + "\n"
    raise ValueError("dump_config 只支持 json/yaml，收到 %r" % fmt)


def save_config(path, config, fmt=None):
    """写配置文件；`fmt=None` 时按扩展名推断。返回路径。"""
    _w19c_text(path, "配置路径")
    if fmt is None:
        suffix = os.path.splitext(path)[1].lower().lstrip(".")
        fmt = suffix or "json"
    text = dump_config(config, fmt)
    io.open(path, "w", encoding="utf-8", newline="\n").write(text)
    return path


_W19C_LOGGER_NAME = "ai"
_W19C_HANDLER_TAG = "_w19c_handler"


def setup_logging(level="INFO", path=None, fmt="%(asctime)s %(levelname)s %(name)s %(message)s"):
    """给名为 `ai` 的 logger 装一个 stderr（或文件）handler，重复调用不会叠加。

    返回配置好的 logger；`path` 给定时写文件（UTF-8，append），否则写 stderr。
    """
    if not isinstance(level, str):
        raise ValueError("level 必须是字符串，如 'INFO'")
    level_value = getattr(logging, level.strip().upper(), None)
    if not isinstance(level_value, int):
        raise ValueError("未知日志级别: %r" % level)
    logger = logging.getLogger(_W19C_LOGGER_NAME)
    logger.setLevel(level_value)
    for handler in list(logger.handlers):
        if getattr(handler, _W19C_HANDLER_TAG, False):
            logger.removeHandler(handler)
            handler.close()
    if path:
        _w19c_text(path, "日志路径")
        handler = logging.FileHandler(path, mode="a", encoding="utf-8")
    else:
        handler = logging.StreamHandler()
    setattr(handler, _W19C_HANDLER_TAG, True)
    handler.setFormatter(logging.Formatter(fmt))
    logger.addHandler(handler)
    logger.propagate = False
    return logger


def get_logger(name=_W19C_LOGGER_NAME):
    """取（或创建）一个 logger；名字不是 `ai` 时挂在 `ai.` 之下。"""
    if not isinstance(name, str) or not name.strip():
        raise ValueError("logger 名字必须是非空字符串")
    name = name.strip()
    if name != _W19C_LOGGER_NAME and not name.startswith(_W19C_LOGGER_NAME + "."):
        name = _W19C_LOGGER_NAME + "." + name
    return logging.getLogger(name)


def log_metrics(metrics, logger=None, prefix=""):
    """把指标写成一行日志（`key=value` 空格分隔），返回这一行文本。"""
    if not isinstance(metrics, dict):
        raise ValueError("log_metrics 需要 dict")
    parts = []
    for key in sorted(metrics):
        value = metrics[key]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("log_metrics 只收数字，%r 是 %s" % (key, type(value).__name__))
        parts.append("%s=%s" % (key, ("%.6g" % value) if isinstance(value, float) else value))
    line = prefix + " ".join(parts)
    log = logger or get_logger()
    log.info(line)
    return line


class track_memory:
    """上下文管理器：统计这段代码的 `tracemalloc` 增量与峰值。

    with 结束后 `stats` 含 `current` / `peak` / `delta_current` / `started_here` / `seconds`。
    之前没开 `tracemalloc` 时会自己开、退出时自己关（不改变调用方状态）。
    """

    def __init__(self, label=None):
        self.label = label
        self.stats = {}

    def __enter__(self):
        self._started_here = not tracemalloc.is_tracing()
        if self._started_here:
            tracemalloc.start()
        self._base = tracemalloc.get_traced_memory()[0]
        self._t0 = time.perf_counter()
        return self

    def __exit__(self, exc_type, exc, tb):
        current, peak = tracemalloc.get_traced_memory()
        elapsed = time.perf_counter() - self._t0
        if self._started_here:
            tracemalloc.stop()
        self.stats = {
            "label": self.label,
            "started_here": self._started_here,
            "current": current,
            "peak": peak,
            "delta_current": current - self._base,
            "seconds": elapsed,
        }
        return False


def memory_usage():
    """当前 Python 堆用量；没在追踪时返回 `tracing=False` 而不是报错。"""
    if not tracemalloc.is_tracing():
        return {"tracing": False, "current": None, "peak": None}
    current, peak = tracemalloc.get_traced_memory()
    return {"tracing": True, "current": current, "peak": peak}


class ModelRegistry:
    """按名字 + 版本号存模型的目录注册表。

    目录结构：`<root>/index.json` 加 `<root>/<name>/v<version>.json`；
    每次 register 写新版本（自增），旧版本保留，`rollback` 只是把 latest 指回去。
    """

    INDEX = "index.json"

    def __init__(self, directory):
        _w19c_text(directory, "注册表目录")
        self.directory = directory
        if not os.path.isdir(self.directory):
            os.makedirs(self.directory)
        self._index_path = os.path.join(self.directory, self.INDEX)
        self._index = self._load_index()

    def _load_index(self):
        if not os.path.exists(self._index_path):
            return {}
        try:
            data = json.loads(io.open(self._index_path, encoding="utf-8").read())
        except ValueError as exc:
            raise ValueError("注册表索引损坏（%s）: %s" % (self._index_path, exc))
        if not isinstance(data, dict):
            raise ValueError("注册表索引顶层必须是 dict")
        return data

    def _save_index(self):
        text = json.dumps(self._index, ensure_ascii=False, sort_keys=True, indent=2)
        tmp = self._index_path + ".tmp"
        io.open(tmp, "w", encoding="utf-8", newline="\n").write(text + "\n")
        os.replace(tmp, self._index_path)

    @staticmethod
    def _check_name(name):
        if not isinstance(name, str) or not _W19C_NAME_RE.match(name):
            raise ValueError("模型名只能是字母/数字/下划线/点/短横线: %r" % (name,))
        return name

    def register(self, name, model, metrics=None, extra=None):
        """登记一个模型（传 `Model` 实例或已有的 JSON 路径），返回版本号。"""
        self._check_name(name)
        metric_map = _w19c_metric_map(metrics, "registry.metrics")
        if isinstance(model, str):
            if not os.path.exists(model):
                raise ValueError("模型文件不存在: %s" % model)
            payload = io.open(model, encoding="utf-8").read()
        else:
            payload = self._payload_of(model)
        entries = self._index.setdefault(name, [])
        version = 1 + max([int(item["version"]) for item in entries], default=0)
        folder = os.path.join(self.directory, name)
        if not os.path.isdir(folder):
            os.makedirs(folder)
        target = os.path.join(folder, "v%d.json" % version)
        if os.path.exists(target):
            raise ValueError("版本文件已存在: %s" % target)
        io.open(target, "w", encoding="utf-8", newline="\n").write(payload)
        digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()
        entries.append({
            "version": version,
            "path": target,
            "created_at": time.strftime("%Y-%m-%dT%H:%M:%S", time.localtime()),
            "sha256": digest,
            "metrics": metric_map,
            "extra": dict(extra) if extra else {},
        })
        self._save_index()
        return version

    @staticmethod
    def _payload_of(model):
        """把模型变成 JSON 文本：`Model` 走 `save`，MLP 走 `to_save_dict` 风格。"""
        if hasattr(model, "save") and hasattr(model, "predict"):
            import contextlib
            import shutil
            import tempfile
            tmpdir = tempfile.mkdtemp(prefix="w19c_")
            try:
                path = os.path.join(tmpdir, "model.json")
                with track_memory(), contextlib.redirect_stdout(io.StringIO()):
                    model.save(path)
                return io.open(path, encoding="utf-8").read()
            finally:
                shutil.rmtree(tmpdir, ignore_errors=True)
        if hasattr(model, "to_dict"):
            text = json.dumps(model.to_dict(), ensure_ascii=False, sort_keys=True,
                              indent=2, allow_nan=False)
            return text + "\n"
        raise ValueError("register 需要 Model 实例（有 save/predict）或它的 JSON 路径")

    @staticmethod
    def _dict_of(model):
        if hasattr(model, "to_dict"):
            return model.to_dict()
        net = getattr(model, "model", None)
        if net is not None and hasattr(net, "to_dict"):
            return net.to_dict()
        raise ValueError("register 需要 Model 实例或它的 JSON 路径")

    def versions(self, name):
        self._check_name(name)
        return [int(item["version"]) for item in self._index.get(name, [])]

    def latest(self, name):
        self._check_name(name)
        entries = self._index.get(name, [])
        if not entries:
            raise ValueError("注册表里没有模型: %s" % name)
        item = max(entries, key=lambda it: int(it["version"]))
        return int(item["version"]), item["path"]

    def get(self, name, version=None):
        """按名字（可选版本）取回 `Model`；返回 `(version, model)`。"""
        if version is None:
            version, path = self.latest(name)
        else:
            if isinstance(version, bool) or not isinstance(version, int):
                raise ValueError("version 必须是整数")
            matches = [it for it in self._index.get(name, []) if int(it["version"]) == version]
            if not matches:
                raise ValueError("模型 %s 没有版本 %d（已有 %s）"
                                 % (name, version, self.versions(name)))
            path = matches[0]["path"]
        with track_memory():
            model = Model.load(path)
        return version, model

    def describe(self, name=None):
        """返回索引的深拷贝（`name` 给定时只返回该模型的版本列表）。"""
        if name is None:
            return json.loads(json.dumps(self._index, ensure_ascii=False))
        self._check_name(name)
        return json.loads(json.dumps(self._index.get(name, []), ensure_ascii=False))

    def rollback(self, name, version):
        """把某版本重新登记为最新（不删除历史）；返回新版本号。"""
        _, model = self.get(name, version)
        return self.register(name, model, extra={"rollback_from": int(version)})


def _w19c_metric_map(metrics, what):
    if metrics is None:
        return {}
    if not isinstance(metrics, dict):
        raise ValueError("%s 必须是 dict" % what)
    out = {}
    for key, value in metrics.items():
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("%s 只收数字，%r 是 %s" % (what, key, type(value).__name__))
        out[key] = value
    return out

# ==== 实验追踪（JSON：配置 / 指标 / 曲线 / 耗时）与模型元数据 ====

def git_hash(directory=None):
    """尽力取当前 git HEAD；取不到返回 None（不是所有环境都有 git 或仓库）。

    用 `subprocess` 调 `git rev-parse HEAD`，失败/超时/非仓库一律返回 None，
    绝不抛异常——元数据是辅助信息，不该让训练失败。
    """
    import subprocess
    if directory is not None and (not isinstance(directory, str) or not directory):
        raise TypeError("git_hash: directory 必须是非空字符串或 None")
    cmd = ["git", "rev-parse", "HEAD"]
    try:
        out = subprocess.run(cmd, cwd=directory, stdout=subprocess.PIPE,
                             stderr=subprocess.DEVNULL, timeout=5, check=False)
    except (OSError, subprocess.SubprocessError):
        return None
    if out.returncode != 0:
        return None
    text = out.stdout.decode("utf-8", "replace").strip()
    return text or None


def _w19a_number(value, who):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("%s: 指标必须是数字，收到 %r" % (who, value))
    return float(value)


def _w19a_metrics(mapping, who):
    if not isinstance(mapping, dict):
        raise TypeError("%s: 期望 dict，收到 %s" % (who, type(mapping).__name__))
    out = {}
    for key, value in mapping.items():
        if not isinstance(key, str) or not key:
            raise TypeError("%s: 指标名必须是非空字符串，收到 %r" % (who, key))
        out[key] = _w19a_number(value, who)
    return out


class ExperimentTracker:
    """把一次实验写成一个 JSON 文件：配置、指标、曲线、起止时间与耗时。

        with ExperimentTracker("runs", name="xor", config={"lr": 0.05}) as run:
            run.log_metrics({"acc": 0.9})
            run.log_curve("loss", [1.0, 0.5, 0.2])

    文件落在 `<directory>/<name>-<序号>.json`；`clock` 可注入（测试用固定时间）。
    序号由目录里已有的同名前缀文件数决定，因此同一目录多次运行不会互相覆盖。
    """

    def __init__(self, directory, name="run", config=None, clock=None, extra=None):
        if not isinstance(directory, str) or not directory:
            raise TypeError("ExperimentTracker: directory 必须是非空字符串")
        if not isinstance(name, str) or not name:
            raise TypeError("ExperimentTracker: name 必须是非空字符串")
        if any(ch in name for ch in ("/", "\\", ":", "\0")):
            raise ValueError("ExperimentTracker: name 不能包含路径分隔符或冒号")
        if clock is not None and not callable(clock):
            raise TypeError("ExperimentTracker: clock 必须是可调用对象或 None")
        self.directory = directory
        self.name = name
        self._clock = clock if clock is not None else time.time
        self.config = _w19a_metrics(config, "ExperimentTracker.config") if config else {}
        self.extra = dict(extra) if extra else {}
        self.metrics = {}
        self.curves = {}
        self.started_at = None
        self.finished_at = None
        self.path = None
        self._finished = False

    # --- 生命周期 ---
    def __enter__(self):
        self.start()
        return self

    def __exit__(self, exc_type, exc, tb):
        if exc_type is None:
            self.finish()
        else:
            self.finish(status="failed", error="%s: %s" % (exc_type.__name__, exc))
        return False

    def start(self):
        if self.started_at is not None:
            raise RuntimeError("ExperimentTracker: 已经 start 过")
        os.makedirs(self.directory, exist_ok=True)
        index = 0
        while True:
            candidate = os.path.join(self.directory, "%s-%03d.json" % (self.name, index))
            if not os.path.exists(candidate):
                break
            index += 1
        self.path = candidate
        self.started_at = float(self._clock())
        self._write(status="running")
        return self

    def log_metrics(self, mapping):
        if self.started_at is None:
            raise RuntimeError("ExperimentTracker: 请先 start（或用 with）")
        if self._finished:
            raise RuntimeError("ExperimentTracker: 已经 finish，不能再写指标")
        self.metrics.update(_w19a_metrics(mapping, "ExperimentTracker.log_metrics"))
        return self

    def log_curve(self, label, values):
        if self.started_at is None:
            raise RuntimeError("ExperimentTracker: 请先 start（或用 with）")
        if self._finished:
            raise RuntimeError("ExperimentTracker: 已经 finish，不能再写曲线")
        if not isinstance(label, str) or not label:
            raise TypeError("ExperimentTracker.log_curve: label 必须是非空字符串")
        if not isinstance(values, (list, tuple)):
            raise TypeError("ExperimentTracker.log_curve: values 必须是 list/tuple")
        self.curves[label] = [_w19a_number(v, "ExperimentTracker.log_curve") for v in values]
        return self

    def finish(self, status="ok", error=None, **metrics):
        if self.started_at is None:
            raise RuntimeError("ExperimentTracker: 还没 start 就 finish")
        if self._finished:
            raise RuntimeError("ExperimentTracker: 重复 finish")
        if metrics:
            self.metrics.update(_w19a_metrics(metrics, "ExperimentTracker.finish"))
        if status not in ("ok", "failed"):
            raise ValueError("ExperimentTracker.finish: status 只能是 'ok'/'failed'")
        self.finished_at = float(self._clock())
        self._finished = True
        self._write(status=status, error=error)
        return self.path

    # --- 序列化 ---
    def to_dict(self, status="running", error=None):
        record = {
            "format": 1,
            "name": self.name,
            "status": status,
            "config": dict(self.config),
            "metrics": dict(self.metrics),
            "curves": {k: list(v) for k, v in self.curves.items()},
            "extra": dict(self.extra),
            "started_at": self.started_at,
            "finished_at": self.finished_at,
        }
        if self.started_at is not None and self.finished_at is not None:
            record["duration_seconds"] = self.finished_at - self.started_at
        if error is not None:
            record["error"] = str(error)
        return record

    def _write(self, status="running", error=None):
        text = json.dumps(self.to_dict(status, error), sort_keys=True, indent=2,
                          allow_nan=False)
        io.open(self.path, "w", encoding="utf-8", newline="\n").write(text + "\n")

    def __repr__(self):
        return "ExperimentTracker(name=%r, path=%r)" % (self.name, self.path)


def load_experiment(path):
    """读回一次实验记录（JSON）。"""
    if not isinstance(path, str) or not path:
        raise TypeError("load_experiment: path 必须是非空字符串")
    if not os.path.exists(path):
        raise ValueError("load_experiment: 文件不存在 %s" % path)
    try:
        record = json.loads(io.open(path, encoding="utf-8").read())
    except ValueError as exc:
        raise ValueError("load_experiment: 不是合法 JSON（%s）" % exc)
    if not isinstance(record, dict) or "metrics" not in record:
        raise ValueError("load_experiment: 缺少 metrics 字段")
    return record


def summarize_experiments(directory, metric="acc", best="max"):
    """扫目录里所有实验，按某个指标排序，返回 `[{"path","name","value"}, ...]`。

    缺该指标的实验被跳过（不进结果），`best='max'` 降序、`'min'` 升序。
    """
    if not isinstance(directory, str) or not directory:
        raise TypeError("summarize_experiments: directory 必须是非空字符串")
    if best not in ("max", "min"):
        raise ValueError("summarize_experiments: best 只能是 'max'/'min'")
    if not isinstance(metric, str) or not metric:
        raise TypeError("summarize_experiments: metric 必须是非空字符串")
    if not os.path.isdir(directory):
        raise ValueError("summarize_experiments: 目录不存在 %s" % directory)
    rows = []
    for fname in sorted(os.listdir(directory)):
        if not fname.endswith(".json"):
            continue
        path = os.path.join(directory, fname)
        try:
            record = load_experiment(path)
        except ValueError:
            continue
        value = record.get("metrics", {}).get(metric)
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            continue
        rows.append({"path": path, "name": record.get("name"), "value": float(value)})
    rows.sort(key=lambda r: r["value"], reverse=(best == "max"))
    return rows


def model_metadata(model, config=None, metrics=None, extra=None, directory=None):
    """收集模型元数据：时间、git 版本、参数量、配置、指标。

    返回值可以直接 `json.dump`；`git_hash` 取不到时是 None（不报错）。
    """
    net = getattr(model, "model", model)
    count = None
    if hasattr(net, "param_count") and callable(net.param_count):
        count = int(net.param_count())
    elif hasattr(net, "layers"):
        total = 0
        for layer in getattr(net, "layers", []):
            if hasattr(layer, "fan_in") and hasattr(layer, "fan_out"):
                total += int(layer.fan_in) * int(layer.fan_out) + int(layer.fan_out)
        count = total
    meta = {
        "format": 1,
        "created_at": time.strftime("%Y-%m-%dT%H:%M:%S", time.localtime()),
        "python_version": "%d.%d.%d" % sys.version_info[:3],
        "git_hash": git_hash(directory),
        "param_count": count,
        "config": _w19a_metrics(config, "model_metadata.config") if config else {},
        "metrics": _w19a_metrics(metrics, "model_metadata.metrics") if metrics else {},
        "extra": dict(extra) if extra else {},
    }
    return meta


def save_model_metadata(path, metadata):
    """把元数据写成 JSON 文件（UTF-8、末尾换行、禁止 NaN/Inf）。"""
    if not isinstance(path, str) or not path:
        raise TypeError("save_model_metadata: path 必须是非空字符串")
    if not isinstance(metadata, dict):
        raise TypeError("save_model_metadata: metadata 必须是 dict")
    text = json.dumps(metadata, sort_keys=True, indent=2, allow_nan=False)
    io.open(path, "w", encoding="utf-8", newline="\n").write(text + "\n")
    return path


def load_model_metadata(path):
    """读回元数据；要求至少含 param_count 字段以区别于实验记录。"""
    if not isinstance(path, str) or not path:
        raise TypeError("load_model_metadata: path 必须是非空字符串")
    if not os.path.exists(path):
        raise ValueError("load_model_metadata: 文件不存在 %s" % path)
    try:
        meta = json.loads(io.open(path, encoding="utf-8").read())
    except ValueError as exc:
        raise ValueError("load_model_metadata: 不是合法 JSON（%s）" % exc)
    if not isinstance(meta, dict) or "param_count" not in meta:
        raise ValueError("load_model_metadata: 缺少 param_count 字段")
    return meta


# ==== 回归基线快照（固定 seed 下数值存 JSON，CI 比对） ====

_W18C_FORMAT = 1


def _w18c_check_model(model, who):
    """快照只接受有 `layers` 的模型（MLP 或 Model 包装器）。"""
    net = getattr(model, "model", model)
    layers = getattr(net, "layers", None)
    if not isinstance(layers, list) or not layers:
        raise TypeError("%s: 需要 MLP（或带 .model 的 Model 包装器）" % who)
    return net


def _w18c_check_rows(rows, who):
    if not isinstance(rows, (list, tuple)) or not rows:
        raise ValueError("%s: xs 必须是非空的样本列表" % who)
    out = []
    for i, row in enumerate(rows):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError("%s: 第 %d 个样本必须是 非空的 list/tuple" % (who, i))
        vals = []
        for v in row:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("%s: 第 %d 个样本含非数字元素 %r" % (who, i, v))
            vals.append(float(v))
        out.append(vals)
    return out


def _w18c_flat(value):
    """把嵌套 list / None 摊平成 list，用于逐值比较。"""
    if value is None:
        return []
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return [float(value)]
    out = []
    for item in value:
        out.extend(_w18c_flat(item))
    return out


def snapshot_model(model, xs, seed=12345, include_grads=True):
    """固定输入下记录 forward 输出与（可选）backward 梯度，得到可比对的快照。

    快照内容是**纯 JSON 可序列化**的结构：

        {"format": 1, "seed": 12345, "layers": ["relu", "linear"],
         "forward": [[...], ...], "grads": [[[gw, gb], ...], ...]}

    `grads[i][k]` 是第 i 个样本、第 k 层反向得到的 `(grad_w, grad_b)`，
    无参层为 `None`。上游梯度统一取全 1，因此结果只依赖权重与输入。
    调用方负责在快照前后保持模型权重不变（本函数不修改权重）。
    """
    net = _w18c_check_model(model, "snapshot_model")
    rows = _w18c_check_rows(xs, "snapshot_model")
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise TypeError("snapshot_model: seed 必须是整数")
    forward = []
    grads = []
    for row in rows:
        out = net.forward(row)
        forward.append([float(v) for v in out])
        if include_grads:
            flat = _mlp_backward(net, [1.0] * len(out))
            grads.append([None if pair is None else [pair[0], pair[1]] for pair in flat])
    names = []
    for layer in net.layers:
        names.append(getattr(layer, "activation_name", "unknown"))
    snap = {
        "format": _W18C_FORMAT,
        "seed": int(seed),
        "layers": names,
        "forward": forward,
    }
    if include_grads:
        snap["grads"] = grads
    return snap


def snapshot_digest(snapshot):
    """快照的规范化摘要（sha256），适合在测试里当金标准常量。"""
    payload = json.dumps(snapshot, sort_keys=True, separators=(",", ":"), allow_nan=False)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def save_snapshot(path, snapshot):
    """把快照写成 JSON 文件（UTF-8、末尾换行、禁止 NaN/Inf）。"""
    if not isinstance(path, str) or not path:
        raise TypeError("save_snapshot: path 必须是非空字符串")
    text = json.dumps(snapshot, sort_keys=True, indent=2, allow_nan=False)
    io.open(path, "w", encoding="utf-8", newline="\n").write(text + "\n")
    return path


def load_snapshot(path):
    """读回快照并做基本结构校验。"""
    if not isinstance(path, str) or not path:
        raise TypeError("load_snapshot: path 必须是非空字符串")
    if not os.path.exists(path):
        raise ValueError("load_snapshot: 文件不存在 %s" % path)
    try:
        snap = json.loads(io.open(path, encoding="utf-8").read())
    except ValueError as exc:
        raise ValueError("load_snapshot: 不是合法 JSON（%s）" % exc)
    if not isinstance(snap, dict) or "forward" not in snap:
        raise ValueError("load_snapshot: 缺少 forward 字段")
    return snap


def _w18c_walk(current, reference, path, rtol, atol, mismatches, stats):
    if isinstance(reference, dict):
        if not isinstance(current, dict):
            mismatches.append("%s: 期望 dict，实际 %s" % (path, type(current).__name__))
            return
        for key in sorted(reference):
            if key not in current:
                mismatches.append("%s.%s: 缺失" % (path, key))
                continue
            _w18c_walk(current[key], reference[key], "%s.%s" % (path, key),
                       rtol, atol, mismatches, stats)
        for key in sorted(current):
            if key not in reference:
                mismatches.append("%s.%s: 多出" % (path, key))
        return
    if isinstance(reference, (list, tuple)):
        if not isinstance(current, (list, tuple)):
            mismatches.append("%s: 期望 list，实际 %s" % (path, type(current).__name__))
            return
        if len(current) != len(reference):
            mismatches.append("%s: 长度 %d != %d" % (path, len(current), len(reference)))
        for i in range(min(len(current), len(reference))):
            _w18c_walk(current[i], reference[i], "%s[%d]" % (path, i),
                       rtol, atol, mismatches, stats)
        return
    if reference is None:
        if current is not None:
            mismatches.append("%s: 期望 None，实际 %r" % (path, current))
            stats["checked"] += 1
        return
    if isinstance(reference, bool) or not isinstance(reference, (int, float)):
        if current != reference:
            mismatches.append("%s: %r != %r" % (path, current, reference))
        stats["checked"] += 1
        return
    if isinstance(current, bool) or not isinstance(current, (int, float)):
        mismatches.append("%s: 期望数字，实际 %r" % (path, current))
        stats["checked"] += 1
        return
    diff = abs(float(current) - float(reference))
    limit = atol + rtol * abs(float(reference))
    stats["checked"] += 1
    if diff > stats["max_diff"]:
        stats["max_diff"] = diff
        stats["worst"] = path
    if diff > limit:
        mismatches.append("%s: %.17g != %.17g（diff=%.3e > %.3e）"
                          % (path, float(current), float(reference), diff, limit))


def compare_snapshots(current, reference, rtol=1e-9, atol=1e-12):
    """逐值比较两个快照。

    返回 `{"ok", "checked", "max_diff", "worst", "mismatches"}`；
    键结构不一致（缺失/多出/类型不同）也算失败。
    """
    for name, value in (("rtol", rtol), ("atol", atol)):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("compare_snapshots: %s 必须是数字" % name)
        if value < 0:
            raise ValueError("compare_snapshots: %s 不能为负" % name)
    for name, value in (("current", current), ("reference", reference)):
        if not isinstance(value, dict):
            raise TypeError("compare_snapshots: %s 必须是 dict" % name)
    mismatches = []
    stats = {"checked": 0, "max_diff": 0.0, "worst": ""}
    _w18c_walk(current, reference, "", rtol, atol, mismatches, stats)
    return {
        "ok": not mismatches,
        "checked": stats["checked"],
        "max_diff": stats["max_diff"],
        "worst": stats["worst"],
        "mismatches": mismatches,
    }


def compare_snapshot_file(path, snapshot, rtol=1e-9, atol=1e-12):
    """读文件再比较，方便 CI 里一句调用。"""
    return compare_snapshots(snapshot, load_snapshot(path), rtol=rtol, atol=atol)


def baseline_model(layer_sizes=(3, 4, 2), seed=12345,
                   activations=None):
    """构造 CI 基线用的固定模型（同样的 seed 必得同样的权重）。"""
    if not isinstance(layer_sizes, (list, tuple)) or len(layer_sizes) < 2:
        raise ValueError("baseline_model: layer_sizes 至少要有两层")
    for v in layer_sizes:
        if isinstance(v, bool) or not isinstance(v, int) or v <= 0:
            raise ValueError("baseline_model: layer_sizes 必须都是正整数")
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise TypeError("baseline_model: seed 必须是整数")
    if activations is None:
        activations = ["relu"] * (len(layer_sizes) - 2) + ["linear"]
    set_seed(seed)
    return MLP(list(layer_sizes), activations=list(activations))


# ==== 集成测试 / doctest / 属性测试的运行时支撑 ====

def run_doctests(module=None, verbose=False, optionflags=None, require_examples=True):
    """运行 docstring 里的 `>>>` 示例，返回 `{"attempted", "failed", "failures"}`。

    `module` 省略时跑本模块（`AI`）。`failures` 是 `[(测试名, 失败数), ...]`，
    便于定位是哪个函数的 docstring 坏了。CI 里加一条
    `assert AI.run_doctests()["failed"] == 0` 就能防止文档示例腐烂。
    """
    if optionflags is None:
        optionflags = doctest.ELLIPSIS
    if isinstance(optionflags, bool) or not isinstance(optionflags, int):
        raise TypeError("run_doctests: optionflags 必须是整数")
    target = module if module is not None else sys.modules[__name__]
    runner = doctest.DocTestRunner(verbose=bool(verbose), optionflags=optionflags)
    failures = []
    for test in doctest.DocTestFinder().find(target):
        result = runner.run(test)
        if result.failed:
            failures.append((test.name, result.failed))
    if require_examples and runner.tries == 0:
        raise ValueError("run_doctests: 没有找到任何 doctest 示例"
                         "（模块没注册进 sys.modules 也会这样）")
    return {"attempted": runner.tries, "failed": runner.failures, "failures": failures}


def _w18d_check_matrix(rows, who, width=None):
    if not isinstance(rows, (list, tuple)) or not rows:
        raise ValueError("%s: 需要非空的二维列表" % who)
    out = []
    for i, row in enumerate(rows):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError("%s: 第 %d 行必须是 非空 list/tuple" % (who, i))
        vals = []
        for v in row:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("%s: 第 %d 行含非数字元素 %r" % (who, i, v))
            vals.append(float(v))
        if width is not None and len(vals) != width:
            raise ValueError("%s: 第 %d 行长度 %d != %d" % (who, i, len(vals), width))
        out.append(vals)
    return out


def check_probability_rows(probs, tolerance=1e-9):
    """属性检查：每行都是概率分布（非负、和为 1），返回最大偏差。"""
    if isinstance(tolerance, bool) or not isinstance(tolerance, (int, float)):
        raise TypeError("check_probability_rows: tolerance 必须是数字")
    if tolerance < 0:
        raise ValueError("check_probability_rows: tolerance 不能为负")
    rows = _w18d_check_matrix(probs, "check_probability_rows")
    worst = 0.0
    for i, row in enumerate(rows):
        for v in row:
            if v < -tolerance:
                raise ValueError("check_probability_rows: 第 %d 行有负概率 %r" % (i, v))
            worst = max(worst, abs(v - min(max(v, 0.0), 1.0)))
        dev = abs(sum(row) - 1.0)
        if dev > tolerance:
            raise ValueError("check_probability_rows: 第 %d 行概率和偏离 1 达 %.3e" % (i, dev))
        worst = max(worst, dev)
    return worst


def check_shape_consistency(model, x):
    """属性检查：逐层 forward 的维度与声明一致，返回 (out, info)。

    本库的 Layer.forward 吃**单个样本**（一维列表），因此这里逐样本跑完全部层，
    逐层核对 len(输入) == fan_in 与 len(输出) == fan_out；任何一层不匹配
    就抛 ValueError，并把已走过的层记录在 info 里（(样本号, 层号, 入, 出)）。
    """
    net = getattr(model, "model", model)
    layers = getattr(net, "layers", None)
    if not isinstance(layers, list) or not layers:
        raise TypeError("check_shape_consistency: 需要 MLP 或带 .layers 的模型")
    rows = _w18d_check_matrix(x, "check_shape_consistency")
    info = []
    out = []
    for r, sample in enumerate(rows):
        cur = sample
        for idx, layer in enumerate(layers):
            if len(cur) != layer.fan_in:
                raise ValueError("check_shape_consistency: 样本 %d 第 %d 层输入长度 %d != fan_in %d"
                                 % (r, idx, len(cur), layer.fan_in))
            nxt = layer.forward(cur)
            if len(nxt) != layer.fan_out:
                raise ValueError("check_shape_consistency: 样本 %d 第 %d 层输出长度 %d != fan_out %d"
                                 % (r, idx, len(nxt), layer.fan_out))
            info.append((r, idx, len(cur), len(nxt)))
            cur = nxt
        out.append(list(cur))
    return out, info

# ======================================================================
#  领域应用：OCR（CRNN 简化）与检测（YOLO 简化）
# ======================================================================


class _w17e3_relu2d:
    """作用于 `(C, H, W)` 的 ReLU，保存掩码供反向使用。"""

    def __init__(self):
        self._mask = None

    def forward(self, x):
        self._mask = [[[1.0 if v > 0.0 else 0.0 for v in row] for row in ch] for ch in x]
        return [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in x]

    def backward(self, dout):
        if self._mask is None:
            raise RuntimeError("_w17e3_relu2d.backward: 必须先调用 forward")
        return [[[dout[c][h][w] * self._mask[c][h][w]
                  for w in range(len(dout[c][h]))]
                 for h in range(len(dout[c]))]
                for c in range(len(dout))]


class CRNN:
    """简化 CRNN：卷积特征提取 + 逐列分类器（**省略循环层**）+ CTC 贪心解码。

    输入 `(C, H, W)` 灰度/彩色图像，卷积栈把高度压到 1，之后把宽度方向当作
    时间步，每一步用一层 `Layer` 输出 `num_classes` 个 logits。
    真正的 CRNN 在卷积与分类之间还有 BiLSTM/GRU；这里省略，`forward` 的
    `(T, num_classes)` 仍可直接喂给 CTC 损失 `ctc_loss` 或 `ctc_greedy_decode`。
    """

    def __init__(self, in_channels=1, num_classes=10, hidden=16,
                 conv_channels=(4,), kernel_size=3, pool=2, seed=None):
        for name, v in (("in_channels", in_channels), ("num_classes", num_classes),
                        ("hidden", hidden), ("kernel_size", kernel_size),
                        ("pool", pool)):
            if isinstance(v, bool) or not isinstance(v, int) or v < 1:
                raise ValueError(f"CRNN: {name} 必须是 >= 1 的整数，收到 {v!r}")
        if isinstance(conv_channels, bool) \
                or not isinstance(conv_channels, (list, tuple)) or not conv_channels:
            raise ValueError(
                f"CRNN: conv_channels 必须是非空列表，收到 {conv_channels!r}")
        for v in conv_channels:
            if isinstance(v, bool) or not isinstance(v, int) or v < 1:
                raise ValueError(f"CRNN: conv_channels 里的元素必须是正整数，收到 {v!r}")
        if seed is not None and (isinstance(seed, bool) or not isinstance(seed, int)):
            raise ValueError(f"CRNN: seed 必须是整数或 None，收到 {seed!r}")
        saved = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.convs = []
            self.relus = []
            self.pools = []
            prev = in_channels
            for out in conv_channels:
                self.convs.append(Conv2d(prev, out, kernel_size, stride=1,
                                         padding=kernel_size // 2))
                self.relus.append(_w17e3_relu2d())
                self.pools.append(MaxPool2d(pool))
                prev = out
            self.feature_channels = prev
            self.head = Layer(prev, num_classes, activation="linear")
        finally:
            random.setstate(saved)
        self.in_channels = in_channels
        self.num_classes = num_classes
        self.hidden = hidden
        self.kernel_size = kernel_size
        self.pool = pool
        self.conv_channels = tuple(int(v) for v in conv_channels)
        self._cache = None
        self._head_grads = None

    def forward(self, image):
        x = _w17e2b_clip([[list(row) for row in image]], "CRNN.forward",
                         in_channels=None)[0]
        x = [[list(row) for row in ch] for ch in x]
        for conv, relu, pool in zip(self.convs, self.relus, self.pools):
            x = pool.forward(relu.forward(conv.forward(x)))
        c, h, w = len(x), len(x[0]), len(x[0][0])
        if h != 1:
            raise ValueError(
                f"CRNN.forward: 卷积后高度应为 1，实际 {h}（减小 pool 或输入高度）")
        steps = []
        for t in range(w):
            steps.append([x[i][0][t] for i in range(c)])
        logits = [list(self.head.forward(step)) for step in steps]
        self._cache = (c, h, w, steps)
        return logits

    def backward(self, dlogits):
        if self._cache is None:
            raise RuntimeError("CRNN.backward: 必须先调用 forward")
        c, h, w, steps = self._cache
        if not isinstance(dlogits, (list, tuple)) or len(dlogits) != w:
            raise ValueError(f"CRNN.backward: dlogits 时间步数必须是 {w}")
        if self._head_grads is None:
            self._head_grads = ([[0.0] * self.head.fan_in
                                 for _ in range(self.head.fan_out)],
                                [0.0] * self.head.fan_out)
        dcols = [[0.0] * c for _ in range(w)]
        for t in range(w):
            row = list(dlogits[t])
            if len(row) != self.num_classes:
                raise ValueError(
                    f"CRNN.backward: 第 {t} 步梯度长度必须是 {self.num_classes}")
            self.head.forward(steps[t])
            gw, gb, dstep = self.head.backward(row)
            acc_w, acc_b = self._head_grads
            for r in range(len(gw)):
                arow = acc_w[r]
                for col in range(len(gw[r])):
                    arow[col] += gw[r][col]
            for r in range(len(gb)):
                acc_b[r] += gb[r]
            for i in range(c):
                dcols[t][i] = dstep[i]
        delta = [[[dcols[t][i] for t in range(w)]] for i in range(c)]
        for conv, relu, pool in zip(reversed(self.convs), reversed(self.relus),
                                    reversed(self.pools)):
            delta = conv.backward(relu.backward(pool.backward(delta)))
        return delta

    def param_count(self):
        # Conv2d 没有 param_count()（只有 Conv3d 有），用既有的 _conv_param_count
        total = sum(_conv_param_count(conv) for conv in self.convs)
        return total + self.head.fan_in * self.head.fan_out + self.head.fan_out

    def zero_grad(self):
        for conv in self.convs:
            conv.zero_grad()
        self._head_grads = None

    def grads(self):
        conv_grads = [(conv.grad_w, conv.grad_b) for conv in self.convs]
        return conv_grads, self._head_grads


def ctc_greedy_decode(logits, blank=0):
    """CTC 贪心解码：每步取 argmax，合并连续重复，去掉 blank。"""
    if not isinstance(logits, (list, tuple)) or not logits:
        raise ValueError("ctc_greedy_decode: logits 必须是非空序列")
    if isinstance(blank, bool) or not isinstance(blank, int) or blank < 0:
        raise ValueError(f"ctc_greedy_decode: blank 必须是非负整数，收到 {blank!r}")
    width = None
    best = []
    for t, row in enumerate(logits):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"ctc_greedy_decode: 第 {t} 步必须是非空列表")
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError(f"ctc_greedy_decode: 第 {t} 步宽度与首步不一致")
        top = 0
        for i in range(1, len(row)):
            if row[i] > row[top]:
                top = i
        best.append(top)
    if blank >= width:
        raise ValueError(
            f"ctc_greedy_decode: blank={blank} 超出类别数 {width}")
    out = []
    prev = None
    for idx in best:
        if idx != prev and idx != blank:
            out.append(idx)
        prev = idx
    return out


def yolo_grid_targets(boxes, labels, grid=4, num_classes=1):
    """把归一化框 `(cx, cy, w, h)` 编码成 YOLO 风格网格目标。

    返回 `{"obj", "box", "cls"}`：
      `obj[gy][gx]` 为 0/1；
      `box[gy][gx]` 为 `[cx, cy, w, h]`（原图归一化坐标）；
      `cls[gy][gx]` 为 one-hot（同一个格子出现多个框时，后写入的覆盖前者，
      并在返回值里给出 `"conflicts"` 计数）。
    """
    if isinstance(grid, bool) or not isinstance(grid, int) or grid < 1:
        raise ValueError(f"yolo_grid_targets: grid 必须是 >= 1 的整数，收到 {grid!r}")
    if isinstance(num_classes, bool) or not isinstance(num_classes, int) or num_classes < 1:
        raise ValueError(
            f"yolo_grid_targets: num_classes 必须是 >= 1 的整数，收到 {num_classes!r}")
    if not isinstance(boxes, (list, tuple)) or not isinstance(labels, (list, tuple)):
        raise ValueError("yolo_grid_targets: boxes 与 labels 必须是列表")
    if len(boxes) != len(labels):
        raise ValueError(
            f"yolo_grid_targets: boxes {len(boxes)} 个与 labels {len(labels)} 个不一致")
    obj = [[0.0] * grid for _ in range(grid)]
    box = [[[0.0] * 4 for _ in range(grid)] for _ in range(grid)]
    cls = [[[0.0] * num_classes for _ in range(grid)] for _ in range(grid)]
    conflicts = 0
    for i, b in enumerate(boxes):
        if not isinstance(b, (list, tuple)) or len(b) != 4:
            raise ValueError(f"yolo_grid_targets: 第 {i} 个框必须是 (cx, cy, w, h)")
        vals = []
        for v in b:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f"yolo_grid_targets: 第 {i} 个框的坐标不是数字")
            fv = float(v)
            if fv != fv or fv in (float("inf"), float("-inf")):
                raise ValueError(f"yolo_grid_targets: 第 {i} 个框的坐标不是有限数")
            if not (0.0 <= fv <= 1.0):
                raise ValueError(
                    f"yolo_grid_targets: 第 {i} 个框的坐标必须归一化到 [0, 1]，收到 {fv}")
            vals.append(fv)
        if vals[2] <= 0.0 or vals[3] <= 0.0:
            raise ValueError(f"yolo_grid_targets: 第 {i} 个框的宽高必须为正")
        lab = labels[i]
        if isinstance(lab, bool) or not isinstance(lab, int) or lab < 0:
            raise ValueError(f"yolo_grid_targets: 第 {i} 个标签必须是非负整数")
        if lab >= num_classes:
            raise ValueError(
                f"yolo_grid_targets: 第 {i} 个标签 {lab} 超出类别数 {num_classes}")
        gx = min(grid - 1, int(vals[0] * grid))
        gy = min(grid - 1, int(vals[1] * grid))
        if obj[gy][gx] > 0.0:
            conflicts += 1
        obj[gy][gx] = 1.0
        box[gy][gx] = vals
        cls[gy][gx] = [1.0 if k == lab else 0.0 for k in range(num_classes)]
    return {"obj": obj, "box": box, "cls": cls, "conflicts": conflicts}


def yolo_decode(pred, conf_threshold=0.5):
    """把网格预测解码成 `[(cx, cy, w, h, score, class_index)]`（原始归一化坐标）。"""
    for key in ("obj", "box", "cls"):
        if key not in pred:
            raise ValueError(f"yolo_decode: 预测缺少 {key!r}")
    obj, box, cls = pred["obj"], pred["box"], pred["cls"]
    if not isinstance(obj, (list, tuple)) or not obj:
        raise ValueError("yolo_decode: obj 必须是非空二维列表")
    grid = len(obj)
    if not isinstance(conf_threshold, (int, float)) or isinstance(conf_threshold, bool):
        raise ValueError("yolo_decode: conf_threshold 必须是数字")
    if not (0.0 <= float(conf_threshold) <= 1.0):
        raise ValueError("yolo_decode: conf_threshold 必须在 [0, 1] 内")
    out = []
    for gy in range(grid):
        for gx in range(grid):
            score = float(obj[gy][gx])
            if score < float(conf_threshold):
                continue
            vals = box[gy][gx]
            if len(vals) != 4:
                raise ValueError("yolo_decode: box 每个格子必须是 4 个数")
            probs = cls[gy][gx]
            if not probs:
                raise ValueError("yolo_decode: cls 每个格子必须是非空列表")
            best = 0
            for i in range(1, len(probs)):
                if probs[i] > probs[best]:
                    best = i
            out.append((float(vals[0]), float(vals[1]), float(vals[2]),
                        float(vals[3]), score, best))
    return out


def nms(boxes, scores, iou_threshold=0.5):
    """非极大值抑制：返回保留下标（按分数降序）。

    `boxes` 用 `[x1, y1, x2, y2]`（与 `box_iou` / 检测指标同一套坐标），
    `yolo_decode` 输出的是 `(cx, cy, w, h)`，两者不要混用。
    """
    if not isinstance(boxes, (list, tuple)) or not isinstance(scores, (list, tuple)):
        raise ValueError("nms: boxes 与 scores 必须是列表")
    if len(boxes) != len(scores):
        raise ValueError(f"nms: boxes {len(boxes)} 个与 scores {len(scores)} 个不一致")
    if not (0.0 <= float(iou_threshold) <= 1.0):
        raise ValueError("nms: iou_threshold 必须在 [0, 1] 内")
    order = sorted(range(len(boxes)), key=lambda i: (-float(scores[i]), i))
    keep = []
    while order:
        i = order[0]
        keep.append(i)
        rest = []
        for j in order[1:]:
            if box_iou(boxes[i], boxes[j]) <= float(iou_threshold):
                rest.append(j)
        order = rest
    return keep


# ======================================================================
#  领域应用：视频（3D-CNN / Two-Stream 融合）
# ======================================================================


def _w17e2b_clip(clip, who, in_channels=None):
    """校验视频片段 `(C, T, H, W)`：非空、三维、全为有限数字。"""
    if not isinstance(clip, (list, tuple)) or not clip:
        raise ValueError(f"{who}: 片段必须是非空列表，收到 {clip!r}")
    channels = []
    for c, plane in enumerate(clip):
        if not isinstance(plane, (list, tuple)) or not plane:
            raise ValueError(f"{who}: 第 {c} 个通道必须是 `(T, H, W)`，收到 {plane!r}")
        rows = []
        for t, frame in enumerate(plane):
            if not isinstance(frame, (list, tuple)) or not frame:
                raise ValueError(f"{who}: 第 {c} 通道第 {t} 帧必须是 `(H, W)`")
            h_rows = []
            for h, row in enumerate(frame):
                if not isinstance(row, (list, tuple)) or not row:
                    raise ValueError(f"{who}: 第 {c} 通道第 {t} 帧第 {h} 行必须是列表")
                vals = []
                for w, v in enumerate(row):
                    if isinstance(v, bool) or not isinstance(v, (int, float)):
                        raise ValueError(f"{who}: 元素不是数字：{v!r}")
                    fv = float(v)
                    if fv != fv or fv in (float("inf"), float("-inf")):
                        raise ValueError(f"{who}: 元素不是有限数")
                    vals.append(fv)
                if h_rows and len(vals) != len(h_rows[0]):
                    raise ValueError(f"{who}: 行宽不一致")
                h_rows.append(vals)
            if rows and (len(h_rows) != len(rows[0]) or len(h_rows[0]) != len(rows[0][0])):
                raise ValueError(f"{who}: 帧尺寸不一致")
            rows.append(h_rows)
        channels.append(rows)
    if in_channels is not None and len(channels) != in_channels:
        raise ValueError(
            f"{who}: 期望 {in_channels} 个通道，收到 {len(channels)}")
    first = channels[0]
    for c in range(1, len(channels)):
        if len(channels[c]) != len(first) or len(channels[c][0]) != len(first[0]) \
                or len(channels[c][0][0]) != len(first[0][0]):
            raise ValueError(f"{who}: 各通道形状不一致")
    return channels


class _w17e2b_relu3d:
    """作用于 `(C, T, H, W)` 的 ReLU，保存掩码供反向使用。"""

    def __init__(self):
        self._mask = None

    def forward(self, x):
        out = [[[[v if v > 0.0 else 0.0 for v in row] for row in frame]
                for frame in plane] for plane in x]
        self._mask = [[[[1.0 if v > 0.0 else 0.0 for v in row] for row in frame]
                       for frame in plane] for plane in x]
        return out

    def backward(self, dout):
        if self._mask is None:
            raise RuntimeError("_w17e2b_relu3d.backward: 必须先调用 forward")
        return [[[[dout[c][t][h][w] * self._mask[c][t][h][w]
                   for w in range(len(dout[c][t][h]))]
                  for h in range(len(dout[c][t]))]
                 for t in range(len(dout[c]))]
                for c in range(len(dout))]


class Video3DCNN:
    """简化 3D-CNN：`(Conv3d -> ReLU -> MaxPool3d) x 层数 -> 全局平均池化 -> Layer`。

    没有 BatchNorm、没有 Dropout、没有残差；池化后做全局平均得到定长向量，
    再经一层 `Layer` 输出 logits（分类）。
    """

    def __init__(self, in_channels=1, channels=(4, 8), kernel_size=3,
                 pool=2, num_classes=2, seed=None):
        for name, v in (("in_channels", in_channels), ("kernel_size", kernel_size),
                        ("pool", pool), ("num_classes", num_classes)):
            if isinstance(v, bool) or not isinstance(v, int) or v < 1:
                raise ValueError(
                    f"Video3DCNN: {name} 必须是 >= 1 的整数，收到 {v!r}")
        if isinstance(channels, bool) or not isinstance(channels, (list, tuple)) or not channels:
            raise ValueError(
                f"Video3DCNN: channels 必须是非空列表，收到 {channels!r}")
        for v in channels:
            if isinstance(v, bool) or not isinstance(v, int) or v < 1:
                raise ValueError(f"Video3DCNN: channels 里的元素必须是正整数，收到 {v!r}")
        if seed is not None and (isinstance(seed, bool) or not isinstance(seed, int)):
            raise ValueError(f"Video3DCNN: seed 必须是整数或 None，收到 {seed!r}")
        saved = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.convs = []
            self.relus = []
            self.pools = []
            prev = in_channels
            for out in channels:
                conv = Conv3d(prev, out, kernel_size, stride=1,
                              padding=kernel_size // 2)
                self.convs.append(conv)
                self.relus.append(_w17e2b_relu3d())
                self.pools.append(MaxPool3d(pool))
                prev = out
            self.head = Layer(prev, num_classes, activation="linear")
        finally:
            random.setstate(saved)
        self.in_channels = in_channels
        self.channels = tuple(int(v) for v in channels)
        self.kernel_size = kernel_size
        self.pool = pool
        self.num_classes = num_classes
        self._cache = None
        # Layer 只返回 (grad_w, grad_b, next_delta)，没有 grad_w 属性；
        # 这里自己累积 head 的梯度。
        self._head_grads = None

    def forward(self, clip):
        x = _w17e2b_clip(clip, "Video3DCNN.forward", self.in_channels)
        for conv, relu, pool in zip(self.convs, self.relus, self.pools):
            x = pool.forward(relu.forward(conv.forward(x)))
        c, d, h, w = len(x), len(x[0]), len(x[0][0]), len(x[0][0][0])
        flat = []
        for i in range(c):
            total = 0.0
            for a in range(d):
                for b in range(h):
                    for e in range(w):
                        total += x[i][a][b][e]
            flat.append(total / float(d * h * w))
        logits = self.head.forward(flat)
        self._cache = (c, d, h, w)
        return logits

    def backward(self, dlogits):
        if self._cache is None:
            raise RuntimeError("Video3DCNN.backward: 必须先调用 forward")
        if not isinstance(dlogits, (list, tuple)) or len(dlogits) != self.num_classes:
            raise ValueError(
                f"Video3DCNN.backward: dlogits 长度必须是 {self.num_classes}")
        c, d, h, w = self._cache
        gw, gb, dflat = self.head.backward(list(dlogits))
        if self._head_grads is None:
            self._head_grads = ([[0.0] * self.head.fan_in
                                 for _ in range(self.head.fan_out)],
                                [0.0] * self.head.fan_out)
        acc_w, acc_b = self._head_grads
        for r in range(len(gw)):
            arow = acc_w[r]
            for col in range(len(gw[r])):
                arow[col] += gw[r][col]
        for r in range(len(gb)):
            acc_b[r] += gb[r]
        scale = 1.0 / float(d * h * w)
        delta = [[[[dflat[i] * scale for _ in range(w)] for _ in range(h)]
                  for _ in range(d)] for i in range(c)]
        for conv, relu, pool in zip(reversed(self.convs), reversed(self.relus),
                                    reversed(self.pools)):
            delta = conv.backward(relu.backward(pool.backward(delta)))
        return delta

    def predict(self, clip):
        logits = self.forward(clip)
        best = 0
        for i in range(1, len(logits)):
            if logits[i] > logits[best]:
                best = i
        return best

    def param_count(self):
        total = sum(conv.param_count() for conv in self.convs)
        return total + self.head.fan_in * self.head.fan_out + self.head.fan_out

    def zero_grad(self):
        for conv in self.convs:
            conv.zero_grad()
        self._head_grads = None

    def grads(self):
        """返回 `(每层卷积的 (grad_w, grad_b), head 的 (grad_w, grad_b))`。

        未反传过时 head 一侧为 `None`（卷积模块自带 grad_w/grad_b，恒为数组）。
        """
        conv_grads = [(conv.grad_w, conv.grad_b) for conv in self.convs]
        return conv_grads, self._head_grads


class TwoStreamFusion:
    """双流融合：空间流与时间流各投影到 `hidden` 维，拼接后线性分类。

    `spatial` 与 `temporal` 是已经抽好的特征向量（本库不实现光流，
    时间流在这里就是「预先算好的运动特征」）。
    """

    def __init__(self, spatial_dim, temporal_dim, hidden=8, num_classes=2, seed=None):
        for name, v in (("spatial_dim", spatial_dim), ("temporal_dim", temporal_dim),
                        ("hidden", hidden), ("num_classes", num_classes)):
            if isinstance(v, bool) or not isinstance(v, int) or v < 1:
                raise ValueError(
                    f"TwoStreamFusion: {name} 必须是 >= 1 的整数，收到 {v!r}")
        if seed is not None and (isinstance(seed, bool) or not isinstance(seed, int)):
            raise ValueError(f"TwoStreamFusion: seed 必须是整数或 None，收到 {seed!r}")
        saved = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.spatial_proj = Layer(spatial_dim, hidden, activation="leaky_relu")
            self.temporal_proj = Layer(temporal_dim, hidden, activation="leaky_relu")
            self.head = Layer(2 * hidden, num_classes, activation="linear")
        finally:
            random.setstate(saved)
        self.spatial_dim = spatial_dim
        self.temporal_dim = temporal_dim
        self.hidden = hidden
        self.num_classes = num_classes
        self._cache = None
        self._grads = None

    def _check(self, vec, dim, who):
        if not isinstance(vec, (list, tuple)) or len(vec) != dim:
            raise ValueError(f"{who}: 期望长度 {dim} 的向量，收到 {vec!r}")
        out = []
        for v in vec:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f"{who}: 元素不是数字：{v!r}")
            fv = float(v)
            if fv != fv or fv in (float("inf"), float("-inf")):
                raise ValueError(f"{who}: 元素不是有限数")
            out.append(fv)
        return out

    def forward(self, spatial, temporal):
        sp = self._check(spatial, self.spatial_dim, "TwoStreamFusion.forward(spatial)")
        tp = self._check(temporal, self.temporal_dim, "TwoStreamFusion.forward(temporal)")
        hs = self.spatial_proj.forward(sp)
        ht = self.temporal_proj.forward(tp)
        logits = self.head.forward(list(hs) + list(ht))
        self._cache = (hs, ht)
        return logits

    def backward(self, dlogits):
        if self._cache is None:
            raise RuntimeError("TwoStreamFusion.backward: 必须先调用 forward")
        if not isinstance(dlogits, (list, tuple)) or len(dlogits) != self.num_classes:
            raise ValueError(
                f"TwoStreamFusion.backward: dlogits 长度必须是 {self.num_classes}")
        gw, gb, dhidden = self.head.backward(list(dlogits))
        sgw, sgb, dsp = self.spatial_proj.backward(list(dhidden[:self.hidden]))
        tgw, tgb, dtp = self.temporal_proj.backward(list(dhidden[self.hidden:]))
        if self._grads is None:
            self._grads = {}
            for key, layer in (("spatial", self.spatial_proj),
                               ("temporal", self.temporal_proj),
                               ("head", self.head)):
                self._grads[key] = ([[0.0] * layer.fan_in
                                     for _ in range(layer.fan_out)],
                                    [0.0] * layer.fan_out)
        for key, (lw, lb) in (("spatial", (sgw, sgb)),
                              ("temporal", (tgw, tgb)),
                              ("head", (gw, gb))):
            acc_w, acc_b = self._grads[key]
            for r in range(len(lw)):
                arow = acc_w[r]
                for col in range(len(lw[r])):
                    arow[col] += lw[r][col]
            for r in range(len(lb)):
                acc_b[r] += lb[r]
        return dsp, dtp

    def predict(self, spatial, temporal):
        logits = self.forward(spatial, temporal)
        best = 0
        for i in range(1, len(logits)):
            if logits[i] > logits[best]:
                best = i
        return best

    def param_count(self):
        return sum(layer.fan_in * layer.fan_out + layer.fan_out
                   for layer in (self.spatial_proj, self.temporal_proj, self.head))

    def zero_grad(self):
        self._grads = None

    def grads(self):
        """返回 `{"spatial"/"temporal"/"head": (grad_w, grad_b)}`。"""
        return self._grads


# ======================================================================
#  领域应用：点云（FPS / Chamfer / 体素化 / PointNet 简化）
# ======================================================================


def _w17e2_points(points, who, dim=None):
    """校验点云 `[[x, y, z], ...]`：非空、等长、全为有限数字。"""
    if not isinstance(points, (list, tuple)) or not points:
        raise ValueError(f"{who}: 点云必须是非空列表，收到 {points!r}")
    rows = []
    width = None
    for i, p in enumerate(points):
        if not isinstance(p, (list, tuple)) or not p:
            raise ValueError(f"{who}: 第 {i} 个点必须是坐标列表，收到 {p!r}")
        row = []
        for j, v in enumerate(p):
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f"{who}: 第 {i} 个点的第 {j} 维不是数字：{v!r}")
            fv = float(v)
            if fv != fv or fv in (float("inf"), float("-inf")):
                raise ValueError(f"{who}: 第 {i} 个点的第 {j} 维不是有限数")
            row.append(fv)
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError(f"{who}: 第 {i} 个点维度 {len(row)} 与首点 {width} 不一致")
        rows.append(row)
    if dim is not None and width != dim:
        raise ValueError(f"{who}: 期望 {dim} 维坐标，收到 {width} 维")
    return rows


def _w17e2_pos_int(value, who, name):
    if isinstance(value, bool) or not isinstance(value, int) or value < 1:
        raise ValueError(f"{who}: {name} 必须是 >= 1 的整数，收到 {value!r}")
    return value


def _w17e2_sqdist(a, b):
    total = 0.0
    for x, y in zip(a, b):
        d = x - y
        total += d * d
    return total


def farthest_point_indices(points, num_samples, seed=None):
    """最远点采样：返回 `num_samples` 个下标（互不相同），覆盖整片点云。"""
    pts = _w17e2_points(points, "farthest_point_indices")
    n = len(pts)
    k = _w17e2_pos_int(num_samples, "farthest_point_indices", "num_samples")
    if k > n:
        raise ValueError(
            f"farthest_point_indices: num_samples {k} 超过点数 {n}")
    if seed is not None and (isinstance(seed, bool) or not isinstance(seed, int)):
        raise ValueError(
            f"farthest_point_indices: seed 必须是整数或 None，收到 {seed!r}")
    rng = random.Random(0 if seed is None else seed)
    first = rng.randrange(n)
    chosen = [first]
    taken = [False] * n
    taken[first] = True
    best = [_w17e2_sqdist(p, pts[first]) for p in pts]
    while len(chosen) < k:
        pick = -1
        best_val = -1.0
        for i in range(n):
            if taken[i]:
                continue
            if best[i] > best_val:
                best_val, pick = best[i], i
        chosen.append(pick)
        taken[pick] = True
        for i in range(n):
            d = _w17e2_sqdist(pts[i], pts[pick])
            if d < best[i]:
                best[i] = d
    return chosen


def chamfer_distance(a, b):
    """对称 Chamfer 距离：两个方向的「最近点平方距离之和」的平均。"""
    pa = _w17e2_points(a, "chamfer_distance")
    pb = _w17e2_points(b, "chamfer_distance")
    if len(pa[0]) != len(pb[0]):
        raise ValueError(
            f"chamfer_distance: 两组点维度不一致（{len(pa[0])} vs {len(pb[0])}）")
    total = 0.0
    for p in pa:
        total += min(_w17e2_sqdist(p, q) for q in pb)
    for q in pb:
        total += min(_w17e2_sqdist(q, p) for p in pa)
    return total / float(len(pa) + len(pb))


def voxelize_points(points, resolution=8, bounds=None):
    """把点云栅格化成占据网格 `(1, D, H, W)`（0/1）。

    `bounds` 为 `(lo, hi)` 两个坐标（含三维边界）；省略时按每维 `min`/`max`
    取界。落界外的点被夹到边缘格子（不丢点）。
    """
    pts = _w17e2_points(points, "voxelize_points")
    res = _w17e2_pos_int(resolution, "voxelize_points", "resolution")
    dim = len(pts[0])
    if bounds is None:
        lo = [min(p[j] for p in pts) for j in range(dim)]
        hi = [max(p[j] for p in pts) for j in range(dim)]
        # 单一取值（例如只有一个点、或某个维度全相同）时跨度为 0，
        # 直接除会退化；按该维两侧各 0.5 撑开，保证点落在网格中心。
        for j in range(dim):
            if hi[j] - lo[j] <= 0.0:
                lo[j] = lo[j] - 0.5
                hi[j] = hi[j] + 0.5
    else:
        if not isinstance(bounds, (list, tuple)) or len(bounds) != 2:
            raise ValueError(
                f"voxelize_points: bounds 必须是 (lo, hi) 两个坐标，收到 {bounds!r}")
        lo = [float(v) for v in bounds[0]]
        hi = [float(v) for v in bounds[1]]
        if len(lo) != dim or len(hi) != dim:
            raise ValueError(
                f"voxelize_points: bounds 维度 {len(lo)}/{len(hi)} 与点维度 {dim} 不一致")
        if any(hi[j] <= lo[j] for j in range(dim)):
            raise ValueError("voxelize_points: bounds 的 hi 必须严格大于 lo")
    grid = [[[[0.0] * res for _ in range(res)] for _ in range(res)]]
    for p in pts:
        cell = []
        for j in range(dim):
            span = hi[j] - lo[j]
            if span <= 0.0:
                cell.append(0)
                continue
            idx = int((p[j] - lo[j]) / span * res)
            if idx < 0:
                idx = 0
            elif idx >= res:
                idx = res - 1
            cell.append(idx)
        if dim == 3:
            grid[0][cell[0]][cell[1]][cell[2]] = 1.0
        elif dim == 2:
            grid[0][cell[0]][cell[1]][0] = 1.0
        else:
            raise ValueError(
                f"voxelize_points: 只支持 2D/3D 点云，收到 {dim} 维")
    return grid


class PointNetEncoder:
    """简化 PointNet 编码器：逐点 MLP + 全局最大池化（对点序置换不变）。

    结构：`(N, in_channels) -> Layer(hidden[0]) -> Layer(hidden[1]) -> max over N`
    只做「编码」，没有分类头、没有 T-Net、没有 `gamma`/`log` 变换。
    """

    def __init__(self, in_channels=3, hidden=(16, 32), seed=None):
        _w17e2_pos_int(in_channels, "PointNetEncoder", "in_channels")
        if isinstance(hidden, bool) or not isinstance(hidden, (list, tuple)) or not hidden:
            raise ValueError(
                f"PointNetEncoder: hidden 必须是非空列表，收到 {hidden!r}")
        sizes = [in_channels]
        for v in hidden:
            _w17e2_pos_int(v, "PointNetEncoder", "hidden 里的元素")
            sizes.append(int(v))
        if seed is not None and (isinstance(seed, bool) or not isinstance(seed, int)):
            raise ValueError(f"PointNetEncoder: seed 必须是整数或 None，收到 {seed!r}")
        saved = random.getstate()
        if seed is not None:
            random.seed(seed)
        try:
            self.layers = [Layer(sizes[i], sizes[i + 1],
                                 activation=("linear" if i == len(sizes) - 2 else "leaky_relu"))
                           for i in range(len(sizes) - 1)]
        finally:
            random.setstate(saved)
        self.in_channels = in_channels
        self.hidden = tuple(int(v) for v in hidden)
        self._cache = None
        # Layer 自身只返回 (grad_w, grad_b, next_delta)，不保存梯度；
        # 这里按层累积，等价于 Model 的 acc_w / acc_b。
        self._grads = None

    def _forward_one(self, point):
        acts = [list(point)]
        for layer in self.layers:
            acts.append(list(layer.forward(acts[-1])))
        return acts

    def forward(self, points):
        pts = _w17e2_points(points, "PointNetEncoder.forward", self.in_channels)
        feats = [self._forward_one(p)[-1] for p in pts]
        width = len(feats[0])
        argmax = []
        global_feature = []
        for k in range(width):
            best_i = 0
            best_v = feats[0][k]
            for i in range(1, len(feats)):
                if feats[i][k] > best_v:
                    best_v, best_i = feats[i][k], i
            argmax.append(best_i)
            global_feature.append(best_v)
        self._cache = (pts, argmax, width)
        return global_feature, feats

    def backward(self, dglobal, dfeats=None):
        """返回逐点梯度 `dpoints`（`(N, in_channels)`）。

        契约：梯度与**最近一次** `forward` 的点序对齐（池化路由按那次 forward
        记录的最大值位置派发）。若中途换过点序，请重新 `forward` 再反传。
        """
        if self._cache is None:
            raise RuntimeError("PointNetEncoder.backward: 必须先调用 forward")
        pts, argmax, width = self._cache
        if not isinstance(dglobal, (list, tuple)) or len(dglobal) != width:
            raise ValueError(
                f"PointNetEncoder.backward: dglobal 长度必须是 {width}")
        if dfeats is None:
            dfeats = [[0.0] * width for _ in pts]
        else:
            if len(dfeats) != len(pts):
                raise ValueError(
                    f"PointNetEncoder.backward: dfeats 行数 {len(dfeats)} 与点数 {len(pts)} 不一致")
            dfeats = [list(row) for row in dfeats]
        for k in range(width):
            g = float(dglobal[k])
            if g:
                dfeats[argmax[k]][k] += g
        if self._grads is None:
            self._grads = [
                ([[0.0] * layer.fan_in for _ in range(layer.fan_out)],
                 [0.0] * layer.fan_out)
                for layer in self.layers
            ]
        dpoints = []
        for i, point in enumerate(pts):
            self._forward_one(point)
            delta = dfeats[i]
            for j in range(len(self.layers) - 1, -1, -1):
                gw, gb, delta = self.layers[j].backward(delta)
                acc_w, acc_b = self._grads[j]
                for r in range(len(gw)):
                    row, arow = gw[r], acc_w[r]
                    for c in range(len(row)):
                        arow[c] += row[c]
                for r in range(len(gb)):
                    acc_b[r] += gb[r]
            dpoints.append(list(delta))
        return dpoints

    def param_count(self):
        return sum(layer.fan_in * layer.fan_out + layer.fan_out for layer in self.layers)

    def grads(self):
        """返回每层 `(grad_w, grad_b)`；未反传过时返回 `None`。"""
        return self._grads

    def zero_grad(self):
        """清空累积的梯度（下一次 backward 会重新初始化）。"""
        self._grads = None


# ========================================================================
#  领域应用：语音前端（Mel 滤波器 / MFCC）与 Conformer 块（简化）
# ========================================================================


def _w17e_samples(samples, who):
    if not isinstance(samples, (list, tuple)) or not samples:
        raise ValueError("%s: 采样点必须是非空数值列表" % who)
    out = []
    for v in samples:
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError("%s: 采样点必须是数字，收到 %r" % (who, v))
        f = float(v)
        if f != f or f in (float("inf"), float("-inf")):
            raise ValueError("%s: 采样点必须是有限数" % who)
        out.append(f)
    return out


def _w17e_pos_int(value, who, name, minimum=1):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError("%s: %s 必须是整数" % (who, name))
    if value < minimum:
        raise ValueError("%s: %s 必须 >= %d" % (who, name, minimum))
    return value


def hz_to_mel(f):
    """HTK 刻度：2595 * log10(1 + f/700)。

    >>> round(hz_to_mel(1000), 6)
    999.985537
    """
    if isinstance(f, bool) or not isinstance(f, (int, float)):
        raise ValueError("hz_to_mel: 频率必须是数字")
    if f < 0:
        raise ValueError("hz_to_mel: 频率不能为负")
    return 2595.0 * math.log10(1.0 + float(f) / 700.0)


def mel_to_hz(m):
    """HTK 反变换：700 * (10^(m/2595) - 1)。

    >>> round(mel_to_hz(hz_to_mel(1000)), 6)
    1000.0
    """
    if isinstance(m, bool) or not isinstance(m, (int, float)):
        raise ValueError("mel_to_hz: mel 值必须是数字")
    return 700.0 * (10.0 ** (float(m) / 2595.0) - 1.0)


def mel_filterbank(sample_rate=16000, n_fft=256, n_mels=8, fmin=0.0, fmax=None):
    """返回 (n_mels, n_fft//2+1) 的三角滤波器组。

    中心频率在 mel 刻度上等距；每个滤波器在本带上三角加权、带宽外为 0。
    """
    _w17e_pos_int(sample_rate, "mel_filterbank", "sample_rate")
    _w17e_pos_int(n_fft, "mel_filterbank", "n_fft")
    _w17e_pos_int(n_mels, "mel_filterbank", "n_mels")
    if isinstance(fmin, bool) or not isinstance(fmin, (int, float)) or fmin < 0:
        raise ValueError("mel_filterbank: fmin 必须是非负数字")
    if fmax is None:
        fmax = sample_rate / 2.0
    if isinstance(fmax, bool) or not isinstance(fmax, (int, float)):
        raise ValueError("mel_filterbank: fmax 必须是数字")
    if not (fmax > fmin) or fmax > sample_rate / 2.0:
        raise ValueError("mel_filterbank: 需要 fmin < fmax <= sample_rate/2")
    m_lo = hz_to_mel(fmin)
    m_hi = hz_to_mel(fmax)
    mels = [m_lo + (m_hi - m_lo) * i / (n_mels + 1) for i in range(n_mels + 2)]
    hz = [mel_to_hz(m) for m in mels]
    n_bins = n_fft // 2 + 1
    freqs = [i * float(sample_rate) / n_fft for i in range(n_bins)]
    filters = []
    for m in range(n_mels):
        left, center, right = hz[m], hz[m + 1], hz[m + 2]
        row = []
        for f in freqs:
            if f <= left or f >= right:
                row.append(0.0)
            elif f <= center:
                row.append((f - left) / (center - left))
            else:
                row.append((right - f) / (right - center))
        if max(row) <= 0.0:
            raise ValueError(
                "mel_filterbank: 第 %d 个滤波器没有可用频点（n_mels 相对 n_fft 太大）" % m)
        filters.append(row)
    return filters


def frame_signal(samples, frame_length=32, hop_length=8, pad=True):
    """把 1-D 采样切帧，返回 [(frame_length 个采样), ...]。"""
    xs = _w17e_samples(samples, "frame_signal")
    _w17e_pos_int(frame_length, "frame_signal", "frame_length")
    _w17e_pos_int(hop_length, "frame_signal", "hop_length")
    if not isinstance(pad, bool):
        raise ValueError("frame_signal: pad 必须是 bool")
    if len(xs) < frame_length:
        raise ValueError("frame_signal: 采样数 %d 少于帧长 %d" % (len(xs), frame_length))
    data = list(xs)
    if pad:
        need = frame_length + max(0, (len(xs) - frame_length) // hop_length) * hop_length
        while len(data) < need:
            data.append(0.0)
    frames = []
    pos = 0
    while pos + frame_length <= len(data):
        frames.append(data[pos:pos + frame_length])
        pos += hop_length
    return frames


def dft_power(frame):
    """朴素 DFT 的幅度谱（n//2+1 个频点）。

    这是 O(n^2) 的直接求和，不是 FFT——本库不引入数值库，语音前端只在小 n_fft 上跑。
    """
    xs, n = _w17e_samples(frame, "dft_power"), None
    n = len(xs)
    n_bins = n // 2 + 1
    out = []
    for k in range(n_bins):
        re = 0.0
        im = 0.0
        for t in range(n):
            ang = -2.0 * math.pi * k * t / n
            re += xs[t] * math.cos(ang)
            im += xs[t] * math.sin(ang)
        out.append(math.sqrt(re * re + im * im))
    return out


def log_mel_spectrogram(samples, sample_rate=16000, frame_length=32,
                        hop_length=8, n_mels=8, fmin=0.0, fmax=None,
                        eps=1e-10):
    """log(梅尔滤波器组能量 + eps)，返回 (帧数, n_mels)。"""
    frames = frame_signal(samples, frame_length, hop_length)
    filters = mel_filterbank(sample_rate, frame_length, n_mels, fmin, fmax)
    if isinstance(eps, bool) or not isinstance(eps, (int, float)) or eps <= 0:
        raise ValueError("log_mel_spectrogram: eps 必须是正数")
    out = []
    for fr in frames:
        power = dft_power(fr)
        row = []
        for m in range(n_mels):
            acc = 0.0
            for i in range(len(power)):
                acc += filters[m][i] * power[i] * power[i]
            row.append(math.log(acc + eps))
        out.append(row)
    return out


def dct_matrix(n_mels=8, n_mfcc=4):
    """正交 DCT-II 矩阵 (n_mfcc, n_mels)。"""
    _w17e_pos_int(n_mels, "dct_matrix", "n_mels")
    _w17e_pos_int(n_mfcc, "dct_matrix", "n_mfcc")
    if n_mfcc > n_mels:
        raise ValueError("dct_matrix: n_mfcc 不能大于 n_mels")
    rows = []
    for k in range(n_mfcc):
        alpha = math.sqrt(1.0 / n_mels) if k == 0 else math.sqrt(2.0 / n_mels)
        rows.append([alpha * math.cos(math.pi * k * (i + 0.5) / n_mels)
                     for i in range(n_mels)])
    return rows


def mfcc(samples, sample_rate=16000, frame_length=32, hop_length=8,
         n_mels=8, n_mfcc=4, fmin=0.0, fmax=None):
    """MFCC：log-mel 谱再乘 DCT-II，返回 (帧数, n_mfcc)。"""
    spec = log_mel_spectrogram(samples, sample_rate, frame_length, hop_length,
                               n_mels, fmin, fmax)
    mat = dct_matrix(n_mels, n_mfcc)
    return [[sum(mat[k][i] * row[i] for i in range(n_mels)) for k in range(n_mfcc)]
            for row in spec]


class ConformerBlock:
    """单层 Conformer 块（简化）：macaron FFN + 自注意力 + 卷积模块 + 后置 LayerNorm。

    结构（每个子层都是 pre-norm + 残差）：
        x += 0.5 * FFN1(LN(x));  x += MHA(LN(x));  x += Conv(LN(x));  x += 0.5 * FFN2(LN(x));
        out = LN(x)

    诚实说明：**只提供前向**（不做手写反向训练），卷积模块只用一个 same padding 的
    depthwise 卷积 + SiLU，没有 GLU、没有相对位置编码、没有 batch norm。
    """

    def __init__(self, d_model=8, num_heads=2, kernel_size=3, expansion=2, seed=None):
        _w17e_pos_int(d_model, "ConformerBlock", "d_model")
        _w17e_pos_int(num_heads, "ConformerBlock", "num_heads")
        _w17e_pos_int(kernel_size, "ConformerBlock", "kernel_size")
        _w17e_pos_int(expansion, "ConformerBlock", "expansion")
        if d_model % num_heads != 0:
            raise ValueError("ConformerBlock: d_model 必须能被 num_heads 整除")
        if kernel_size % 2 == 0:
            raise ValueError("ConformerBlock: kernel_size 必须是正奇数（same padding）")
        self.d_model = d_model
        self.num_heads = num_heads
        self.kernel_size = kernel_size
        self.expansion = expansion
        hidden = d_model * expansion
        if seed is not None:
            state = random.getstate()
            random.seed(seed)
            try:
                self._build(hidden)
            finally:
                random.setstate(state)
        else:
            self._build(hidden)

    def _build(self, hidden):
        d = self.d_model
        self.norm_ff1 = LayerNorm(d)
        self.norm_attn = LayerNorm(d)
        self.norm_conv = LayerNorm(d)
        self.norm_ff2 = LayerNorm(d)
        self.norm_out = LayerNorm(d)
        self.ff1_in = Layer(d, hidden, activation="silu")
        self.ff1_out = Layer(hidden, d, activation="linear", is_output=True)
        self.ff2_in = Layer(d, hidden, activation="silu")
        self.ff2_out = Layer(hidden, d, activation="linear", is_output=True)
        self.attn = MultiHeadAttention(d, self.num_heads)
        self.conv = Conv1d(d, d, self.kernel_size, padding=self.kernel_size // 2)

    def _ffn(self, x, first, second):
        h = [first.forward(row) for row in x]
        return [second.forward(row) for row in h]

    def _conv_block(self, x):
        """(T, d) -> (T, d)：转成 (d, T) 过 1D 卷积，逐元素 SiLU 后再转回来。"""
        transposed = [[x[t][c] for t in range(len(x))] for c in range(self.d_model)]
        mixed = self.conv.forward(transposed)
        out = []
        for t in range(len(x)):
            row = []
            for c in range(self.d_model):
                v = mixed[c][t]
                row.append(v * (1.0 / (1.0 + math.exp(-v))) if v > -30 else 0.0)
            out.append(row)
        return out

    def param_count(self):
        n = 0
        for mod in (self.ff1_in, self.ff1_out, self.ff2_in, self.ff2_out):
            n += mod.fan_in * mod.fan_out + mod.fan_out
        n += 4 * self.attn.d_model * self.attn.d_model + 4 * self.attn.d_model
        for plane in self.conv.weights:
            for rows in plane:
                n += len(rows)
        n += len(self.conv.biases)
        n += 5 * (2 * self.d_model)
        return n

    def forward(self, x_seq):
        if not isinstance(x_seq, (list, tuple)) or not x_seq:
            raise ValueError("ConformerBlock.forward: 输入必须是 (T, d_model) 的非空序列")
        T = len(x_seq)
        x = []
        for row in x_seq:
            if not isinstance(row, (list, tuple)) or len(row) != self.d_model:
                raise ValueError("ConformerBlock.forward: 每个位置必须是长度 %d 的向量"
                                 % self.d_model)
            x.append([float(v) for v in row])
        half = 0.5
        f1 = self._ffn([self.norm_ff1.forward(row) for row in x],
                       self.ff1_in, self.ff1_out)
        x = [[x[t][c] + half * f1[t][c] for c in range(self.d_model)] for t in range(T)]
        attn_in = [self.norm_attn.forward(row) for row in x]
        attn_out = self.attn.forward(attn_in)
        x = [[x[t][c] + attn_out[t][c] for c in range(self.d_model)] for t in range(T)]
        conv_in = [self.norm_conv.forward(row) for row in x]
        conv_out = self._conv_block(conv_in)
        x = [[x[t][c] + conv_out[t][c] for c in range(self.d_model)] for t in range(T)]
        f2 = self._ffn([self.norm_ff2.forward(row) for row in x],
                       self.ff2_in, self.ff2_out)
        x = [[x[t][c] + half * f2[t][c] for c in range(self.d_model)] for t in range(T)]
        return [self.norm_out.forward(row) for row in x]

# ========================================================================
#  领域应用：向量检索（暴力 / IVF / 单层 NSW 图）
# ========================================================================


def _w17d_vector(vec, who, dim=None):
    if not isinstance(vec, (list, tuple)) or not vec:
        raise ValueError("%s: 向量必须是非空数值列表" % who)
    out = []
    for v in vec:
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError("%s: 向量元素必须是数字，收到 %r" % (who, v))
        f = float(v)
        if f != f or f in (float("inf"), float("-inf")):
            raise ValueError("%s: 向量元素必须是有限数" % who)
        out.append(f)
    if dim is not None and len(out) != dim:
        raise ValueError("%s: 向量维度 %d 与索引维度 %d 不一致" % (who, len(out), dim))
    return out


def _w17d_vectors(vectors, who, dim=None):
    if not isinstance(vectors, (list, tuple)) or not vectors:
        raise ValueError("%s: 向量集合必须是非空列表" % who)
    out = [_w17d_vector(v, who) for v in vectors]
    d = len(out[0])
    for v in out:
        if len(v) != d:
            raise ValueError("%s: 所有向量维度必须一致（期望 %d）" % (who, d))
    if dim is not None and d != dim:
        raise ValueError("%s: 向量维度 %d 与索引维度 %d 不一致" % (who, d, dim))
    return out


def _w17d_l2(a, b):
    acc = 0.0
    for i in range(len(a)):
        diff = a[i] - b[i]
        acc += diff * diff
    return acc


def _w17d_dot(a, b):
    acc = 0.0
    for i in range(len(a)):
        acc += a[i] * b[i]
    return acc


def _w17d_k(query, vectors, metric):
    """返回 (距离, 下标) 列表；l2 距离越小越好，ip 内积越大越好。"""
    if metric == "l2":
        return [(_w17d_l2(query, v), i) for i, v in enumerate(vectors)]
    return [(-_w17d_dot(query, v), i) for i, v in enumerate(vectors)]


def _w17d_topk(pairs, k):
    pairs = sorted(pairs, key=lambda p: (p[0], p[1]))
    return pairs[:k]


def _w17d_check_k(k, n, who):
    if isinstance(k, bool) or not isinstance(k, int):
        raise ValueError("%s: k 必须是整数" % who)
    if k < 1:
        raise ValueError("%s: k 必须 >= 1" % who)
    return min(k, n)


def _w17d_kmeans(vectors, n_clusters, n_iter, rng):
    """k-means（k-means++ 初始化）返回簇心列表。"""
    n = len(vectors)
    if n_clusters > n:
        raise ValueError("向量数 %d 少于簇数 %d" % (n, n_clusters))
    centers = [list(vectors[rng.randrange(n)])]
    while len(centers) < n_clusters:
        d2 = []
        for v in vectors:
            best = min(_w17d_l2(v, c) for c in centers)
            d2.append(best)
        total = sum(d2)
        if total <= 0.0:
            pick = rng.randrange(n)
        else:
            r = rng.random() * total
            acc = 0.0
            pick = n - 1
            for i, val in enumerate(d2):
                acc += val
                if r <= acc:
                    pick = i
                    break
        centers.append(list(vectors[pick]))
    dim = len(vectors[0])
    for _ in range(max(1, n_iter)):
        groups = [[] for _ in range(n_clusters)]
        for v in vectors:
            best_i = 0
            best_d = _w17d_l2(v, centers[0])
            for ci in range(1, n_clusters):
                d = _w17d_l2(v, centers[ci])
                if d < best_d:
                    best_d = d
                    best_i = ci
            groups[best_i].append(v)
        moved = 0.0
        for ci in range(n_clusters):
            if not groups[ci]:
                continue
            new = [0.0] * dim
            for v in groups[ci]:
                for j in range(dim):
                    new[j] += v[j]
            cnt = float(len(groups[ci]))
            new = [x / cnt for x in new]
            moved += _w17d_l2(new, centers[ci])
            centers[ci] = new
        if moved <= 1e-12:
            break
    return centers


class BruteForceIndex:
    """暴力检索：线性扫描所有向量，结果与精确最近邻逐位一致。"""

    def __init__(self, metric="l2", dim=None):
        if metric not in ("l2", "ip"):
            raise ValueError("BruteForceIndex: metric 只能是 'l2' 或 'ip'")
        if dim is not None and (isinstance(dim, bool) or not isinstance(dim, int) or dim < 1):
            raise ValueError("BruteForceIndex: dim 必须是正整数")
        self.metric = metric
        self.dim = dim
        self.vectors = []
        self.ids = []

    def __len__(self):
        return len(self.vectors)

    def add(self, vectors, ids=None):
        vs = _w17d_vectors(vectors, "BruteForceIndex.add", self.dim)
        if self.dim is None:
            self.dim = len(vs[0])
        n = len(vs)
        if ids is None:
            base = len(self.vectors)
            ids = list(range(base, base + n))
        else:
            if not isinstance(ids, (list, tuple)) or len(ids) != n:
                raise ValueError("BruteForceIndex.add: ids 长度必须与 vectors 相同")
            ids = list(ids)
            for i in ids:
                if isinstance(i, bool) or not isinstance(i, int):
                    raise ValueError("BruteForceIndex.add: ids 必须是整数")
            if len(set(ids)) != len(ids):
                raise ValueError("BruteForceIndex.add: ids 不能重复")
            if set(ids) & set(self.ids):
                raise ValueError("BruteForceIndex.add: ids 与已有 id 冲突")
        self.vectors.extend(vs)
        self.ids.extend(ids)
        return self

    def search(self, query, k=5):
        q = _w17d_vector(query, "BruteForceIndex.search", self.dim)
        if not self.vectors:
            raise ValueError("BruteForceIndex.search: 索引为空")
        kk = _w17d_check_k(k, len(self.vectors), "BruteForceIndex.search")
        pairs = _w17d_topk(_w17d_k(q, self.vectors, self.metric), kk)
        return [(self.ids[i], d) for d, i in pairs]


class IVFIndex:
    """倒排文件索引：先 k-means 分簇，再只在最近的 n_probe 个簇里扫描。"""

    def __init__(self, n_clusters=2, n_probe=1, n_iter=10, metric="l2", dim=None,
                 seed=None):
        if isinstance(n_clusters, bool) or not isinstance(n_clusters, int) or n_clusters < 1:
            raise ValueError("IVFIndex: n_clusters 必须是正整数")
        if isinstance(n_probe, bool) or not isinstance(n_probe, int) or n_probe < 1:
            raise ValueError("IVFIndex: n_probe 必须是正整数")
        if metric not in ("l2", "ip"):
            raise ValueError("IVFIndex: metric 只能是 'l2' 或 'ip'")
        self.n_clusters = n_clusters
        self.n_probe = n_probe
        self.n_iter = n_iter
        self.metric = metric
        self.dim = dim
        self.seed = seed
        self.vectors = []
        self.ids = []
        self.centers = []
        self.assign = []

    def __len__(self):
        return len(self.vectors)

    def add(self, vectors, ids=None):
        vs = _w17d_vectors(vectors, "IVFIndex.add", self.dim)
        if self.dim is None:
            self.dim = len(vs[0])
        n = len(vs)
        if ids is None:
            base = len(self.vectors)
            ids = list(range(base, base + n))
        else:
            if not isinstance(ids, (list, tuple)) or len(ids) != n:
                raise ValueError("IVFIndex.add: ids 长度必须与 vectors 相同")
            ids = list(ids)
            if len(set(ids)) != len(ids):
                raise ValueError("IVFIndex.add: ids 不能重复")
            if set(ids) & set(self.ids):
                raise ValueError("IVFIndex.add: ids 与已有 id 冲突")
        self.vectors.extend(vs)
        self.ids.extend(ids)
        return self

    def train(self):
        if not self.vectors:
            raise ValueError("IVFIndex.train: 索引为空")
        rng = random.Random(self.seed)
        self.centers = _w17d_kmeans(self.vectors, self.n_clusters, self.n_iter, rng)
        self.assign = []
        for v in self.vectors:
            best_i = 0
            best_d = _w17d_l2(v, self.centers[0])
            for ci in range(1, len(self.centers)):
                d = _w17d_l2(v, self.centers[ci])
                if d < best_d:
                    best_d = d
                    best_i = ci
            self.assign.append(best_i)
        return self

    def search(self, query, k=5):
        q = _w17d_vector(query, "IVFIndex.search", self.dim)
        if not self.vectors:
            raise ValueError("IVFIndex.search: 索引为空")
        if not self.centers:
            self.train()
        kk = _w17d_check_k(k, len(self.vectors), "IVFIndex.search")
        probe = min(self.n_probe, len(self.centers))
        cdist = _w17d_k(q, self.centers, self.metric)
        chosen = set(i for _, i in _w17d_topk(cdist, probe))
        pairs = []
        for idx, v in enumerate(self.vectors):
            if self.assign[idx] in chosen:
                d = _w17d_l2(q, v) if self.metric == "l2" else -_w17d_dot(q, v)
                pairs.append((d, idx))
        pairs = _w17d_topk(pairs, kk)
        return [(self.ids[i], d) for d, i in pairs]


class NSWIndex:
    """单层可导航小世界图（NSW）近似检索。

    诚实说明：这是**单层**近邻图 + 贪心束搜索，不是论文里的分层 HNSW
    （没有层级、没有启发式邻居剪枝、没有多 ef 参数），召回率低于真正的 HNSW。
    """

    def __init__(self, m=6, ef_search=16, metric="l2", dim=None):
        if isinstance(m, bool) or not isinstance(m, int) or m < 1:
            raise ValueError("NSWIndex: m 必须是正整数")
        if isinstance(ef_search, bool) or not isinstance(ef_search, int) or ef_search < 1:
            raise ValueError("NSWIndex: ef_search 必须是正整数")
        if metric not in ("l2", "ip"):
            raise ValueError("NSWIndex: metric 只能是 'l2' 或 'ip'")
        self.m = m
        self.ef_search = ef_search
        self.metric = metric
        self.dim = dim
        self.vectors = []
        self.ids = []
        self.links = []

    def __len__(self):
        return len(self.vectors)

    def _dist(self, q, v):
        return _w17d_l2(q, v) if self.metric == "l2" else -_w17d_dot(q, v)

    def add(self, vectors, ids=None):
        vs = _w17d_vectors(vectors, "NSWIndex.add", self.dim)
        if self.dim is None:
            self.dim = len(vs[0])
        n = len(vs)
        if ids is None:
            base = len(self.vectors)
            ids = list(range(base, base + n))
        else:
            if not isinstance(ids, (list, tuple)) or len(ids) != n:
                raise ValueError("NSWIndex.add: ids 长度必须与 vectors 相同")
            ids = list(ids)
            if len(set(ids)) != len(ids):
                raise ValueError("NSWIndex.add: ids 不能重复")
            if set(ids) & set(self.ids):
                raise ValueError("NSWIndex.add: ids 与已有 id 冲突")
        for v, vid in zip(vs, ids):
            new_idx = len(self.vectors)
            self.vectors.append(list(v))
            self.ids.append(vid)
            self.links.append([])
            if new_idx == 0:
                continue
            cand = sorted((self._dist(v, self.vectors[j]), j)
                          for j in range(new_idx))[:self.m]
            for _, j in cand:
                self.links[new_idx].append(j)
                self.links[j].append(new_idx)
                if len(self.links[j]) > self.m:
                    keep = sorted(self.links[j],
                                  key=lambda z: (self._dist(self.vectors[j],
                                                            self.vectors[z]), z))
                    self.links[j] = keep[:self.m]
        return self

    def search(self, query, k=5):
        q = _w17d_vector(query, "NSWIndex.search", self.dim)
        if not self.vectors:
            raise ValueError("NSWIndex.search: 索引为空")
        kk = _w17d_check_k(k, len(self.vectors), "NSWIndex.search")
        entry = 0
        best_d = self._dist(q, self.vectors[entry])
        improved = True
        while improved:
            improved = False
            for j in self.links[entry]:
                d = self._dist(q, self.vectors[j])
                if d < best_d:
                    best_d = d
                    entry = j
                    improved = True
        visited = {entry}
        frontier = [(best_d, entry)]
        expanded = 0
        while frontier and expanded < self.ef_search:
            _, cur = heapq.heappop(frontier)
            expanded += 1
            for j in self.links[cur]:
                if j in visited:
                    continue
                visited.add(j)
                heapq.heappush(frontier, (self._dist(q, self.vectors[j]), j))
        pairs = sorted((self._dist(q, self.vectors[i]), i) for i in visited)
        pairs = _w17d_topk(pairs, kk)
        return [(self.ids[i], d) for d, i in pairs]


def retrieval_recall(truth, got):
    """recall@k：truth / got 都是 id 列表（同长度），返回交集比例。"""
    if not isinstance(truth, (list, tuple)) or not isinstance(got, (list, tuple)):
        raise ValueError("retrieval_recall: 两侧都必须是 id 列表")
    if not truth:
        raise ValueError("retrieval_recall: truth 不能为空")
    hits = len(set(truth) & set(got))
    return hits / float(len(truth))

# ========================================================================
#  领域应用：超分（SRCNN 式）/ 去噪（DnCNN 式残差）
# ========================================================================


def _w17c2_image(x, who, min_side=1):
    """校验 (C, H, W) 的嵌套 list，返回 (c, h, w)。"""
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError("%s: 图像必须是 (C,H,W) 的非空嵌套列表" % who)
    c = len(x)
    first = x[0]
    if not isinstance(first, (list, tuple)) or not first:
        raise ValueError("%s: 每个通道必须是非空的行列表" % who)
    h = len(first)
    if not isinstance(first[0], (list, tuple)) or not first[0]:
        raise ValueError("%s: 每行必须是非空的数值列表" % who)
    w = len(first[0])
    if h < min_side or w < min_side:
        raise ValueError("%s: 图像高宽都要 >= %d，收到 %dx%d" % (who, min_side, h, w))
    out = []
    for ch in x:
        if not isinstance(ch, (list, tuple)) or len(ch) != h:
            raise ValueError("%s: 所有通道的行数必须一致（期望 %d）" % (who, h))
        rows = []
        for row in ch:
            if not isinstance(row, (list, tuple)) or len(row) != w:
                raise ValueError("%s: 每行的列数必须一致（期望 %d）" % (who, w))
            vals = []
            for v in row:
                if isinstance(v, bool) or not isinstance(v, (int, float)):
                    raise ValueError("%s: 像素必须是数字，收到 %r" % (who, v))
                vals.append(float(v))
            rows.append(vals)
        out.append(rows)
    return out, c, h, w


def _w17c2_relu(x):
    return [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in x]


def _w17c2_mask(dout, act):
    return [[[dout[c][i][j] if act[c][i][j] > 0.0 else 0.0
              for j in range(len(act[c][i]))]
             for i in range(len(act[c]))]
            for c in range(len(act))]


def _w17c2_conv_count(conv):
    n = len(conv.biases)
    for plane in conv.weights:
        for rows in plane:
            for row in rows:
                n += len(row)
    return n


def _w17c2_mse(pred, target):
    """逐元素 MSE 与 dL/dpred。"""
    c = len(pred)
    h = len(pred[0])
    w = len(pred[0][0])
    total = c * h * w
    acc = 0.0
    grad = []
    for ch in range(c):
        grows = []
        for i in range(h):
            row = []
            for j in range(w):
                diff = pred[ch][i][j] - target[ch][i][j]
                acc += diff * diff
                row.append(2.0 * diff / total)
            grows.append(row)
        grad.append(grows)
    return acc / total, grad


def _w17c2_check_lr(lr, who):
    if isinstance(lr, bool) or not isinstance(lr, (int, float)):
        raise ValueError("%s: lr 必须是数字" % who)
    if not (lr > 0.0) or lr != lr or lr in (float("inf"), float("-inf")):
        raise ValueError("%s: lr 必须是正的有限数" % who)
    return float(lr)


def add_gaussian_noise(image, sigma=0.1, seed=None):
    """给 (C,H,W) 图像加逐像素高斯噪声，返回新图像（不改入参）。"""
    img, c, h, w = _w17c2_image(image, "add_gaussian_noise")
    if isinstance(sigma, bool) or not isinstance(sigma, (int, float)):
        raise ValueError("add_gaussian_noise: sigma 必须是数字")
    if sigma < 0.0:
        raise ValueError("add_gaussian_noise: sigma 不能为负")
    rng = random.Random(seed) if seed is not None else random
    return [[[img[ch][i][j] + rng.gauss(0.0, float(sigma)) for j in range(w)]
             for i in range(h)] for ch in range(c)]


def upscale_bilinear(image, scale=2):
    """双线性放大 (C,H,W) -> (C, H*scale, W*scale)。"""
    img, c, h, w = _w17c2_image(image, "upscale_bilinear")
    if isinstance(scale, bool) or not isinstance(scale, int):
        raise ValueError("upscale_bilinear: scale 必须是整数")
    if scale < 1:
        raise ValueError("upscale_bilinear: scale 必须 >= 1")
    return _resize_bilinear(img, h * scale, w * scale)


class SRCNN:
    """SRCNN 式超分：双线性上采样后接三层卷积（9x9 提取 / 1x1 映射 / 5x5 重建）。

    这不是论文里的 patch 采样训练，而是「一层卷积就作用在整幅上采样图」的等价写法，
    padding 全用 same，所以输出与上采样图同尺寸。训练用 MSE，梯度手写回传。
    """

    def __init__(self, scale=2, channels=1, hidden=8, seed=None):
        if isinstance(scale, bool) or not isinstance(scale, int):
            raise ValueError("SRCNN: scale 必须是整数")
        if scale < 1:
            raise ValueError("SRCNN: scale 必须 >= 1")
        if isinstance(channels, bool) or not isinstance(channels, int) or channels < 1:
            raise ValueError("SRCNN: channels 必须是正整数")
        if isinstance(hidden, bool) or not isinstance(hidden, int) or hidden < 1:
            raise ValueError("SRCNN: hidden 必须是正整数")
        self.scale = scale
        self.channels = channels
        self.hidden = hidden
        if seed is not None:
            state = random.getstate()
            random.seed(seed)
            try:
                self.conv1 = Conv2d(channels, hidden, 9, padding=4)
                self.conv2 = Conv2d(hidden, hidden, 1)
                self.conv3 = Conv2d(hidden, channels, 5, padding=2)
            finally:
                random.setstate(state)
        else:
            self.conv1 = Conv2d(channels, hidden, 9, padding=4)
            self.conv2 = Conv2d(hidden, hidden, 1)
            self.conv3 = Conv2d(hidden, channels, 5, padding=2)
        self.convs = [self.conv1, self.conv2, self.conv3]
        self._a1 = None
        self._a2 = None

    def param_count(self):
        return sum(_w17c2_conv_count(conv) for conv in self.convs)

    def zero_grad(self):
        for conv in self.convs:
            conv.zero_grad()

    def forward(self, upsampled):
        """输入上采样图 (channels,H,W)，返回同尺寸预测。"""
        x, c, h, w = _w17c2_image(upsampled, "SRCNN.forward")
        if c != self.channels:
            raise ValueError("SRCNN.forward: 通道数 %d 与 channels=%d 不一致"
                             % (c, self.channels))
        z1 = self.conv1.forward(x)
        a1 = _w17c2_relu(z1)
        z2 = self.conv2.forward(a1)
        a2 = _w17c2_relu(z2)
        out = self.conv3.forward(a2)
        self._a1 = a1
        self._a2 = a2
        return out

    def loss_and_grads(self, upsampled, target):
        """返回 MSE 损失，并把 dL/dW 累加进三层卷积的 grad_w / grad_b。"""
        pred = self.forward(upsampled)
        tgt, c, h, w = _w17c2_image(target, "SRCNN.loss_and_grads")
        if (c, h, w) != (self.channels, len(pred[0]), len(pred[0][0])):
            raise ValueError(
                "SRCNN.loss_and_grads: 目标尺寸 %dx%dx%d 与预测 %dx%dx%d 不一致"
                % (c, h, w, len(pred), len(pred[0]), len(pred[0][0])))
        loss, dpred = _w17c2_mse(pred, tgt)
        d2 = self.conv3.backward(dpred)
        d2 = _w17c2_mask(d2, self._a2)
        d1 = self.conv2.backward(d2)
        d1 = _w17c2_mask(d1, self._a1)
        self.conv1.backward(d1)
        return loss

    def upscale(self, image):
        """直接把低分辨率图放大并重建。"""
        return self.forward(upscale_bilinear(image, self.scale))

    def fit(self, pairs, epochs=50, lr=0.01):
        """在 (低分辨率, 高分辨率) 对上学，返回每轮平均 MSE。"""
        if not isinstance(pairs, (list, tuple)) or not pairs:
            raise ValueError("SRCNN.fit: pairs 必须是非空列表")
        lr = _w17c2_check_lr(lr, "SRCNN.fit")
        if isinstance(epochs, bool) or not isinstance(epochs, int) or epochs < 1:
            raise ValueError("SRCNN.fit: epochs 必须是正整数")
        prepared = []
        for item in pairs:
            if not isinstance(item, (list, tuple)) or len(item) != 2:
                raise ValueError("SRCNN.fit: 每项必须是 (低分辨率, 高分辨率)")
            low = upscale_bilinear(item[0], self.scale)
            high, _, _, _ = _w17c2_image(item[1], "SRCNN.fit")
            prepared.append((low, high))
        history = []
        for _ in range(epochs):
            self.zero_grad()
            total = 0.0
            for low, high in prepared:
                total += self.loss_and_grads(low, high)
            n = len(prepared)
            for conv in self.convs:
                for oc in range(len(conv.weights)):
                    for ic in range(len(conv.weights[oc])):
                        for kh in range(len(conv.weights[oc][ic])):
                            wrow = conv.weights[oc][ic][kh]
                            grow = conv.grad_w[oc][ic][kh]
                            for kw in range(len(wrow)):
                                wrow[kw] -= lr * grow[kw] / n
                    conv.biases[oc] -= lr * conv.grad_b[oc] / n
            history.append(total / n)
        return history


class DnCNN:
    """DnCNN 式去噪：网络预测噪声残差，`denoise = 输入 - 预测噪声`。

    最后一层不带激活，depth 个 3x3 same 卷积中间夹 ReLU。训练目标是「噪声」(noisy - clean)。
    """

    def __init__(self, channels=1, depth=3, hidden=8, kernel_size=3, seed=None):
        if isinstance(channels, bool) or not isinstance(channels, int) or channels < 1:
            raise ValueError("DnCNN: channels 必须是正整数")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 1:
            raise ValueError("DnCNN: depth 必须是正整数")
        if isinstance(hidden, bool) or not isinstance(hidden, int) or hidden < 1:
            raise ValueError("DnCNN: hidden 必须是正整数")
        if isinstance(kernel_size, bool) or not isinstance(kernel_size, int):
            raise ValueError("DnCNN: kernel_size 必须是整数")
        if kernel_size < 1 or kernel_size % 2 == 0:
            raise ValueError("DnCNN: kernel_size 必须是正奇数（同尺寸卷积需要奇数核）")
        self.channels = channels
        self.depth = depth
        self.hidden = hidden
        self.kernel_size = kernel_size
        pad = (kernel_size - 1) // 2
        convs = []
        if seed is not None:
            state = random.getstate()
            random.seed(seed)
            try:
                for i in range(depth):
                    cin = channels if i == 0 else hidden
                    cout = channels if i == depth - 1 else hidden
                    convs.append(Conv2d(cin, cout, kernel_size, padding=pad))
            finally:
                random.setstate(state)
        else:
            for i in range(depth):
                cin = channels if i == 0 else hidden
                cout = channels if i == depth - 1 else hidden
                convs.append(Conv2d(cin, cout, kernel_size, padding=pad))
        self.convs = convs
        self._acts = []

    def param_count(self):
        return sum(_w17c2_conv_count(conv) for conv in self.convs)

    def zero_grad(self):
        for conv in self.convs:
            conv.zero_grad()

    def predict_noise(self, image):
        x, c, h, w = _w17c2_image(image, "DnCNN.predict_noise")
        if c != self.channels:
            raise ValueError("DnCNN.predict_noise: 通道数 %d 与 channels=%d 不一致"
                             % (c, self.channels))
        acts = []
        cur = x
        for i, conv in enumerate(self.convs):
            z = conv.forward(cur)
            if i == len(self.convs) - 1:
                cur = z
            else:
                cur = _w17c2_relu(z)
                acts.append(cur)
        self._acts = acts
        return cur

    def denoise(self, image):
        img, c, h, w = _w17c2_image(image, "DnCNN.denoise")
        noise = self.predict_noise(img)
        return [[[img[ch][i][j] - noise[ch][i][j] for j in range(w)]
                 for i in range(h)] for ch in range(c)]

    def loss_and_grads(self, noisy, clean):
        """MSE(预测噪声, noisy - clean)，梯度累加进各卷积。"""
        pred = self.predict_noise(noisy)
        tgt, c, h, w = _w17c2_image(clean, "DnCNN.loss_and_grads")
        if (c, h, w) != (self.channels, len(pred[0]), len(pred[0][0])):
            raise ValueError(
                "DnCNN.loss_and_grads: clean 尺寸 %dx%dx%d 与 noisy 的 %dx%dx%d 不一致"
                % (c, h, w, len(pred), len(pred[0]), len(pred[0][0])))
        src, _, _, _ = _w17c2_image(noisy, "DnCNN.loss_and_grads")
        target = [[[src[ch][i][j] - tgt[ch][i][j] for j in range(w)]
                   for i in range(h)] for ch in range(c)]
        loss, dpred = _w17c2_mse(pred, target)
        delta = dpred
        for i in range(len(self.convs) - 1, -1, -1):
            delta = self.convs[i].backward(delta)
            if i > 0:
                delta = _w17c2_mask(delta, self._acts[i - 1])
        return loss

    def fit(self, pairs, epochs=50, lr=0.01):
        """在 (带噪, 干净) 对上学，返回每轮平均 MSE。"""
        if not isinstance(pairs, (list, tuple)) or not pairs:
            raise ValueError("DnCNN.fit: pairs 必须是非空列表")
        lr = _w17c2_check_lr(lr, "DnCNN.fit")
        if isinstance(epochs, bool) or not isinstance(epochs, int) or epochs < 1:
            raise ValueError("DnCNN.fit: epochs 必须是正整数")
        prepared = []
        for item in pairs:
            if not isinstance(item, (list, tuple)) or len(item) != 2:
                raise ValueError("DnCNN.fit: 每项必须是 (带噪, 干净)")
            noisy, _, _, _ = _w17c2_image(item[0], "DnCNN.fit")
            clean, _, _, _ = _w17c2_image(item[1], "DnCNN.fit")
            prepared.append((noisy, clean))
        history = []
        for _ in range(epochs):
            self.zero_grad()
            total = 0.0
            for noisy, clean in prepared:
                total += self.loss_and_grads(noisy, clean)
            n = len(prepared)
            for conv in self.convs:
                for oc in range(len(conv.weights)):
                    for ic in range(len(conv.weights[oc])):
                        for kh in range(len(conv.weights[oc][ic])):
                            wrow = conv.weights[oc][ic][kh]
                            grow = conv.grad_w[oc][ic][kh]
                            for kw in range(len(wrow)):
                                wrow[kw] -= lr * grow[kw] / n
                    conv.biases[oc] -= lr * conv.grad_b[oc] / n
            history.append(total / n)
        return history

# ======================================================================
#  领域应用：神经风格迁移（Gram 矩阵 + 逐层反传到图像）
# ======================================================================


def _w17c_image(x, who, min_side=2):
    """校验 (C, H, W) 的三层嵌套数值列表。"""
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError(f"{who}: 图像需要非空的 (C, H, W) 列表")
    channels = []
    for c, plane in enumerate(x):
        if not isinstance(plane, (list, tuple)) or not plane:
            raise ValueError(f"{who}: 第 {c} 个通道不是非空列表")
        rows = []
        width = None
        for r, row in enumerate(plane):
            if not isinstance(row, (list, tuple)):
                raise TypeError(f"{who}: 第 {c} 个通道第 {r} 行不是列表")
            if width is None:
                width = len(row)
            elif len(row) != width:
                raise ValueError(f"{who}: 第 {c} 个通道的行宽不一致（{len(row)} vs {width}）")
            rows.append([_w17b_float(v, who, f"ch{c} 第 {r} 行") for v in row])
        channels.append(rows)
    h = len(channels[0])
    w = len(channels[0][0])
    if h < min_side or w < min_side:
        raise ValueError(f"{who}: 图像太小（{h}x{w}），至少需要 {min_side}x{min_side}")
    for c, plane in enumerate(channels):
        if len(plane) != h or len(plane[0]) != w:
            raise ValueError(f"{who}: 第 {c} 个通道的形状与其他通道不一致")
    return channels


def _w17c_relu(x):
    return [[[v if v > 0.0 else 0.0 for v in row] for row in plane] for plane in x]


def _w17c_shape(x):
    return (len(x), len(x[0]), len(x[0][0]))


def _w17c_zeros(shape):
    c, h, w = shape
    return [[[0.0] * w for _ in range(h)] for _ in range(c)]


def gram_matrix(features):
    """(C, H, W) 特征图的 Gram 矩阵（按 `H*W` 归一化）。

    返回 `(C, C)`，`G[i][j] = Σ_{h,w} F[i][h][w] * F[j][h][w] / (H*W)`。
    """
    f = _w17c_image(features, "gram_matrix", min_side=1)
    c, h, w = _w17c_shape(f)
    n = float(h * w)
    out = [[0.0] * c for _ in range(c)]
    for i in range(c):
        for j in range(c):
            s = 0.0
            for y in range(h):
                row_i = f[i][y]
                row_j = f[j][y]
                for x in range(w):
                    s += row_i[x] * row_j[x]
            out[i][j] = s / n
    return out


class FeatureExtractor:
    """若干 `Conv2d + ReLU` 组成的特征提取器（权重固定，只用来算 Gram）。"""

    def __init__(self, channels=(3, 8, 8), kernel_size=3, padding=1, seed=None):
        if not isinstance(channels, (list, tuple)) or len(channels) < 2:
            raise ValueError("FeatureExtractor: channels 至少要有两层（含输入通道）")
        self.channels = [_w17b_int(ch, "FeatureExtractor", "channels", 1)
                         for ch in channels]
        if seed is not None:
            _w17b_int(seed, "FeatureExtractor", "seed", 0)
        self.seed = seed
        state = random.getstate()
        try:
            if seed is not None:
                random.seed(seed)
            self.convs = [Conv2d(self.channels[i], self.channels[i + 1],
                                 kernel_size, padding=padding)
                          for i in range(len(self.channels) - 1)]
        finally:
            random.setstate(state)
        self.acts = None
        self.zs = None

    def forward(self, image):
        """返回逐层的 ReLU 后激活（最后一项就是最深层输出）。"""
        x = _w17c_image(image, "FeatureExtractor.forward")
        acts, zs = [], []
        h = x
        for conv in self.convs:
            z = conv.forward(h)
            a = _w17c_relu(z)
            zs.append(z)
            acts.append(a)
            h = a
        self.acts, self.zs = acts, zs
        return acts

    def backward(self, layer_grads):
        """`layer_grads`: `{层号: dL/d(该层 ReLU 后激活)}`，返回 `dL/d输入图像`。"""
        if self.acts is None:
            raise RuntimeError("FeatureExtractor.backward: 必须先调用 forward()")
        cur = {i: g for i, g in layer_grads.items()}
        for idx in range(len(self.convs) - 1, -1, -1):
            g = cur.get(idx)
            if g is None:
                g = _w17c_zeros(_w17c_shape(self.acts[idx]))
            z = self.zs[idx]
            c, h, w = _w17c_shape(z)
            dz = [[[g[c_i][y][x] if z[c_i][y][x] > 0.0 else 0.0
                    for x in range(w)] for y in range(h)] for c_i in range(c)]
            dx = self.convs[idx].backward(dz)
            if idx > 0:
                prev = cur.get(idx - 1)
                if prev is None:
                    cur[idx - 1] = dx
                else:
                    for c_i in range(len(prev)):
                        for y in range(len(prev[0])):
                            row_p = prev[c_i][y]
                            row_d = dx[c_i][y]
                            for x in range(len(row_p)):
                                row_p[x] += row_d[x]
        # 反传到第 0 层后，dx 已经是 dL/d输入图像（cur[0] 只是 dL/d(第 0 层激活)）
        return dx

    def param_count(self):
        """(固定) 卷积权重与偏置总数。"""
        total = 0
        for conv in self.convs:
            total += conv.out_channels * conv.cg * conv.kh * conv.kw + conv.out_channels
        return total


def style_transfer(content, style, extractor=None, steps=50, lr=0.02,
                   style_weight=100.0, content_weight=1.0,
                   style_layers=None, content_layer=None, seed=None,
                   clamp=True):
    """简化版神经风格迁移：只优化**图像本身**，特征提取器固定。

    损失 = `content_weight * MSE(第 content_layer 层激活)` +
           `style_weight * Σ_l MSE(Gram(第 l 层))`。
    梯度沿「Gram -> 特征图 -> 逐层反传到输入」手写回传，每步对图像做
    `img -= lr * dL/dimg`（`clamp=True` 时裁到 `[0, 1]`）。
    """
    if not isinstance(steps, int) or isinstance(steps, bool) or steps < 1:
        raise ValueError("style_transfer: steps 必须是 >=1 的整数")
    lr = _w17b_float(lr, "style_transfer", "lr")
    if lr <= 0.0:
        raise ValueError("style_transfer: lr 必须 > 0")
    style_weight = _w17b_float(style_weight, "style_transfer", "style_weight")
    content_weight = _w17b_float(content_weight, "style_transfer", "content_weight")
    if style_weight < 0.0 or content_weight < 0.0:
        raise ValueError("style_transfer: 两个权重都必须 >= 0")
    if style_weight == 0.0 and content_weight == 0.0:
        raise ValueError("style_transfer: 两个权重不能同时为 0")

    content = _w17c_image(content, "style_transfer.content")
    style = _w17c_image(style, "style_transfer.style")
    if _w17c_shape(content) != _w17c_shape(style):
        raise ValueError(
            "style_transfer: content 与 style 形状必须一致"
            f"（{_w17c_shape(content)} vs {_w17c_shape(style)}）"
        )
    if extractor is None:
        extractor = FeatureExtractor(channels=(3, 8, 8), padding=1, seed=seed)
    if not isinstance(extractor, FeatureExtractor):
        raise TypeError("style_transfer: extractor 必须是 FeatureExtractor")

    n_layers = len(extractor.convs)
    if style_layers is None:
        style_layers = list(range(n_layers))
    else:
        if not isinstance(style_layers, (list, tuple)):
            raise TypeError("style_transfer: style_layers 必须是列表")
        style_layers = [_w17b_int(i, "style_transfer", "style_layers", 0)
                        for i in style_layers]
        for i in style_layers:
            if i >= n_layers:
                raise ValueError(f"style_transfer: style_layers 里的 {i} 越界（共 {n_layers} 层）")
        if not style_layers:
            raise ValueError("style_transfer: style_layers 不能为空")
    if content_layer is None:
        content_layer = n_layers - 1
    else:
        content_layer = _w17b_int(content_layer, "style_transfer", "content_layer", 0)
        if content_layer >= n_layers:
            raise ValueError(f"style_transfer: content_layer {content_layer} 越界（共 {n_layers} 层）")

    content_acts = extractor.forward(content)
    target_content = [[list(row) for row in plane] for plane in content_acts[content_layer]]
    style_acts = extractor.forward(style)
    target_grams = {i: gram_matrix(style_acts[i]) for i in style_layers}

    image = [[list(row) for row in plane] for plane in content]
    losses, content_losses, style_losses = [], [], []
    for _step in range(steps):
        acts = extractor.forward(image)
        c_act = acts[content_layer]
        c_n = float(len(c_act) * len(c_act[0]) * len(c_act[0][0]))
        c_loss = 0.0
        d_c = _w17c_zeros(_w17c_shape(c_act))
        for c_i in range(len(c_act)):
            for y in range(len(c_act[0])):
                for x in range(len(c_act[0][0])):
                    diff = c_act[c_i][y][x] - target_content[c_i][y][x]
                    c_loss += diff * diff
                    d_c[c_i][y][x] = 2.0 * diff / c_n
        c_loss /= c_n

        s_loss = 0.0
        layer_grads = {content_layer: [[[content_weight * v for v in row] for row in plane]
                                       for plane in d_c]}
        for i in style_layers:
            g = gram_matrix(acts[i])
            tg = target_grams[i]
            ch = len(g)
            g_n = float(ch * ch)
            d_g = [[0.0] * ch for _ in range(ch)]
            for a in range(ch):
                for b in range(ch):
                    diff = g[a][b] - tg[a][b]
                    s_loss += diff * diff
                    d_g[a][b] = 2.0 * diff / g_n
            s_loss /= g_n
            # Gram 的梯度：dF = (dG + dG^T) F / (H*W)
            a_i = acts[i]
            _, h_i, w_i = _w17c_shape(a_i)
            n_pix = float(h_i * w_i)
            d_act = _w17c_zeros(_w17c_shape(a_i))
            for c_i in range(ch):
                for y in range(h_i):
                    for x in range(w_i):
                        total = 0.0
                        for j in range(ch):
                            total += (d_g[c_i][j] + d_g[j][c_i]) * a_i[j][y][x]
                        d_act[c_i][y][x] = style_weight * total / n_pix
            if i in layer_grads:
                acc = layer_grads[i]
                for c_i in range(len(acc)):
                    for y in range(len(acc[0])):
                        row_a = acc[c_i][y]
                        row_b = d_act[c_i][y]
                        for x in range(len(row_a)):
                            row_a[x] += row_b[x]
            else:
                layer_grads[i] = d_act

        dx = extractor.backward(layer_grads)
        for c_i in range(len(image)):
            for y in range(len(image[0])):
                for x in range(len(image[0][0])):
                    v = image[c_i][y][x] - lr * dx[c_i][y][x]
                    if clamp:
                        v = 0.0 if v < 0.0 else (1.0 if v > 1.0 else v)
                    image[c_i][y][x] = v
        losses.append(content_weight * c_loss + style_weight * s_loss)
        content_losses.append(c_loss)
        style_losses.append(s_loss)

    return {
        "image": image,
        "losses": losses,
        "content_losses": content_losses,
        "style_losses": style_losses,
        "extractor": extractor,
    }

# ======================================================================
#  领域应用：DeepFM / DIN
# ======================================================================


def _w17b2_field_values(field_ids, field_values, num_fields, who):
    """把 (field_ids, field_values) 变成「每域一个取值」的定长列表（缺域记 0）。"""
    if not isinstance(field_ids, (list, tuple)) or not isinstance(field_values, (list, tuple)):
        raise TypeError(f"{who}: field_ids / field_values 必须是列表")
    if len(field_ids) != len(field_values):
        raise ValueError(f"{who}: field_ids 与 field_values 长度不一致")
    if not field_ids:
        raise ValueError(f"{who}: 至少需要一个特征")
    out = [0.0] * num_fields
    seen = [False] * num_fields
    for idx, (fid, value) in enumerate(zip(field_ids, field_values)):
        f = _w17b_int(fid, who, f"第 {idx} 个 field_id")
        if f >= num_fields:
            raise ValueError(f"{who}: field_id {f} 越界（共 {num_fields} 个域）")
        if seen[f]:
            raise ValueError(f"{who}: 域 {f} 重复出现（本实现每个域只允许一个取值）")
        seen[f] = True
        out[f] = _w17b_float(value, who, f"第 {idx} 个 value")
    return out


class DeepFM:
    """DeepFM：一阶线性 + FM 二阶交叉 + 深侧 MLP，logit 相加。

    输入是「域 id + 取值」两条等长列表，未出现的域按 0 处理，因此深侧输入
    固定为 `num_fields * num_factors` 维（每个域一个嵌入向量乘自己的取值）。
    二阶项用 `0.5 * Σ_k ((Σ_j v_jk)^2 - Σ_j v_jk^2)`，`v_jk = emb[j][k] * value_j`，
    不需要显式枚举交叉对；每个域只允许出现一次（多值域请改成多个域）。
    """

    def __init__(self, num_fields, num_factors=4, hidden=(8,), seed=None):
        self.num_fields = _w17b_int(num_fields, "DeepFM", "num_fields", 1)
        self.num_factors = _w17b_int(num_factors, "DeepFM", "num_factors", 1)
        if not isinstance(hidden, (list, tuple)) or not hidden:
            raise ValueError("DeepFM: hidden 需要非空的层宽列表")
        self.hidden_sizes = [_w17b_int(h, "DeepFM", "hidden", 1) for h in hidden]
        if seed is not None:
            _w17b_int(seed, "DeepFM", "seed", 0)
        self.seed = seed

        rng = _w17b_rng(seed)
        f = self.num_factors
        self.linear_w = [rng.gauss(0.0, 0.1) for _ in range(self.num_fields)]
        self.b0 = 0.0
        self.emb = [[rng.gauss(0.0, 0.1) for _ in range(f)]
                    for _ in range(self.num_fields)]

        state = random.getstate()
        try:
            if seed is not None:
                random.seed(seed + 1)
            self.hidden = []
            fan_in = self.num_fields * f
            for width in self.hidden_sizes:
                self.hidden.append(Layer(fan_in, width, activation="relu"))
                fan_in = width
        finally:
            random.setstate(state)
        self.out_w = [rng.gauss(0.0, 0.1) for _ in range(fan_in)]
        self.out_b = 0.0

    def _vectors(self, values):
        """逐域的 `emb[j] * value_j`（定长 `num_fields` 条）。"""
        return [[self.emb[j][k] * values[j] for k in range(self.num_factors)]
                for j in range(self.num_fields)]

    def _fm(self, vectors):
        f = self.num_factors
        sums = [0.0] * f
        for vec in vectors:
            for k in range(f):
                sums[k] += vec[k]
        total = 0.0
        for k in range(f):
            sq = 0.0
            for vec in vectors:
                sq += vec[k] * vec[k]
            total += sums[k] * sums[k] - sq
        return 0.5 * total, sums

    def logits(self, field_ids, field_values):
        """返回逐样本 logit（两条入参都是「样本列表的列表」）。"""
        if len(field_ids) != len(field_values):
            raise ValueError("DeepFM.logits: field_ids 与 field_values 样本数不一致")
        if not field_ids:
            raise ValueError("DeepFM.logits: 至少需要一个样本")
        out = []
        for ids, values in zip(field_ids, field_values):
            vals = _w17b2_field_values(ids, values, self.num_fields, "DeepFM.logits")
            vectors = self._vectors(vals)
            fm, _sums = self._fm(vectors)
            h = [x for vec in vectors for x in vec]
            for layer in self.hidden:
                h = layer.forward(h)
            logit = self.b0 + fm
            for j in range(self.num_fields):
                logit += self.linear_w[j] * vals[j]
            logit += _w17b_dot(self.out_w, h) + self.out_b
            out.append(logit)
        return out

    def loss_and_grads(self, field_ids, field_values, labels):
        """二分类交叉熵 + 梯度；返回 `(loss, grads)`。"""
        if not isinstance(labels, (list, tuple)):
            raise TypeError("DeepFM.loss_and_grads: labels 必须是列表")
        n = len(labels)
        if n == 0:
            raise ValueError("DeepFM.loss_and_grads: 至少需要一个样本")
        if len(field_ids) != n or len(field_values) != n:
            raise ValueError("DeepFM.loss_and_grads: 样本数与 labels 不一致")
        ys = []
        for idx, y in enumerate(labels):
            v = _w17b_float(y, "DeepFM.loss_and_grads", f"第 {idx} 个 label")
            if v < 0.0 or v > 1.0:
                raise ValueError("DeepFM.loss_and_grads: label 必须在 [0, 1] 内")
            ys.append(v)

        f = self.num_factors
        grads = {
            "linear_w": [0.0] * self.num_fields,
            "b0": 0.0,
            "emb": [[0.0] * f for _ in range(self.num_fields)],
            "hidden": [
                ([[0.0] * layer.fan_in for _ in range(layer.fan_out)],
                 [0.0] * layer.fan_out)
                for layer in self.hidden
            ],
            "out_w": [0.0] * len(self.out_w),
            "out_b": 0.0,
        }
        total_loss = 0.0
        for ids, values, y in zip(field_ids, field_values, ys):
            vals = _w17b2_field_values(ids, values, self.num_fields,
                                       "DeepFM.loss_and_grads")
            vectors = self._vectors(vals)
            fm, sums = self._fm(vectors)
            h = [x for vec in vectors for x in vec]
            for layer in self.hidden:
                h = layer.forward(h)
            logit = self.b0 + fm
            for j in range(self.num_fields):
                logit += self.linear_w[j] * vals[j]
            logit += _w17b_dot(self.out_w, h) + self.out_b

            total_loss += _w17b_bce(logit, y)
            g = 1.0 / (1.0 + math.exp(-logit)) - y

            grads["b0"] += g
            for j in range(self.num_fields):
                grads["linear_w"][j] += g * vals[j]
            for j in range(len(self.out_w)):
                grads["out_w"][j] += g * h[j]
            grads["out_b"] += g

            dh = [g * self.out_w[j] for j in range(len(self.out_w))]
            for idx in range(len(self.hidden) - 1, -1, -1):
                layer = self.hidden[idx]
                gw, gb, dh = layer.backward(dh)
                acc_w, acc_b = grads["hidden"][idx]
                for r in range(layer.fan_out):
                    for c in range(layer.fan_in):
                        acc_w[r][c] += gw[r][c]
                    acc_b[r] += gb[r]

            for j in range(self.num_fields):
                if vals[j] == 0.0:
                    continue
                for k in range(f):
                    dv = g * (sums[k] - vectors[j][k]) + dh[j * f + k]
                    grads["emb"][j][k] += dv * vals[j]

        scale = 1.0 / n
        for j in range(self.num_fields):
            grads["linear_w"][j] *= scale
            for k in range(f):
                grads["emb"][j][k] *= scale
        grads["b0"] *= scale
        for idx, layer in enumerate(self.hidden):
            acc_w, acc_b = grads["hidden"][idx]
            for r in range(layer.fan_out):
                for c in range(layer.fan_in):
                    acc_w[r][c] *= scale
                acc_b[r] *= scale
        for j in range(len(self.out_w)):
            grads["out_w"][j] *= scale
        grads["out_b"] *= scale
        return total_loss / n, grads

    def apply_grads(self, grads, lr=0.05):
        """原地 SGD 一步。"""
        lr = _w17b_float(lr, "DeepFM.apply_grads", "lr")
        if lr < 0.0:
            raise ValueError("DeepFM.apply_grads: lr 必须 >= 0")
        for j in range(self.num_fields):
            self.linear_w[j] -= lr * grads["linear_w"][j]
            for k in range(self.num_factors):
                self.emb[j][k] -= lr * grads["emb"][j][k]
        self.b0 -= lr * grads["b0"]
        for idx, layer in enumerate(self.hidden):
            acc_w, acc_b = grads["hidden"][idx]
            for r in range(layer.fan_out):
                for c in range(layer.fan_in):
                    layer.weights[r][c] -= lr * acc_w[r][c]
                layer.biases[r] -= lr * acc_b[r]
        for j in range(len(self.out_w)):
            self.out_w[j] -= lr * grads["out_w"][j]
        self.out_b -= lr * grads["out_b"]

    def param_count(self):
        """可训练标量个数。"""
        total = self.num_fields + 1 + self.num_fields * self.num_factors
        for layer in self.hidden:
            total += layer.fan_out * layer.fan_in + layer.fan_out
        total += len(self.out_w) + 1
        return total


class DIN:
    """DIN：候选 × 历史序列的注意力池化 + MLP 打分层（无嵌入表）。

    注意力用缩放点积 `s_j = candidate·history_j / sqrt(f)` 再 softmax；
    池化 `p = Σ a_j history_j`，把 `[candidate, p]` 送进 ReLU MLP 出 logit。
    真实 DIN 的 Dice 激活单元与「候选-历史共同输入的外积注意力」未实现；
    `mask` 为 0 的位置被排除在 softmax 之外（权重恰为 0）。
    """

    def __init__(self, num_factors=4, hidden=(8,), seed=None):
        self.num_factors = _w17b_int(num_factors, "DIN", "num_factors", 1)
        if not isinstance(hidden, (list, tuple)) or not hidden:
            raise ValueError("DIN: hidden 需要非空的层宽列表")
        self.hidden_sizes = [_w17b_int(h, "DIN", "hidden", 1) for h in hidden]
        if seed is not None:
            _w17b_int(seed, "DIN", "seed", 0)
        self.seed = seed

        rng = _w17b_rng(seed)
        f = self.num_factors
        state = random.getstate()
        try:
            if seed is not None:
                random.seed(seed + 1)
            self.hidden = []
            fan_in = 2 * f
            for width in self.hidden_sizes:
                self.hidden.append(Layer(fan_in, width, activation="relu"))
                fan_in = width
        finally:
            random.setstate(state)
        self.out_w = [rng.gauss(0.0, 0.1) for _ in range(fan_in)]
        self.out_b = 0.0

    def _check_seq(self, candidate, history, mask, who):
        f = self.num_factors
        cand = _w17b_rows([candidate], f, who)[0]
        if not isinstance(history, (list, tuple)) or not history:
            raise ValueError(f"{who}: history 需要非空的历史序列")
        seq = [_w17b_rows([row], f, who)[0] for row in history]
        if mask is None:
            m = [1.0] * len(seq)
        else:
            if not isinstance(mask, (list, tuple)) or len(mask) != len(seq):
                raise ValueError(f"{who}: mask 长度必须与 history 一致")
            m = []
            for idx, flag in enumerate(mask):
                v = _w17b_float(flag, who, f"mask[{idx}]")
                if v not in (0.0, 1.0):
                    raise ValueError(f"{who}: mask 只能是 0 或 1")
                m.append(v)
            if sum(m) == 0.0:
                raise ValueError(f"{who}: mask 全为 0，没有可注意的历史")
        return cand, seq, m

    def _softmax_attn(self, cand, seq, m):
        scale = 1.0 / math.sqrt(self.num_factors)
        raw = []
        for j, row in enumerate(seq):
            raw.append(-1e30 if m[j] == 0.0 else _w17b_dot(cand, row) * scale)
        top = max(raw)
        exps = [0.0 if r <= -1e29 else math.exp(r - top) for r in raw]
        total = sum(exps)
        return [e / total for e in exps]

    def attention_weights(self, candidate, history, mask=None):
        """返回归一化后的注意力权重（mask 位置恰为 0）。"""
        cand, seq, m = self._check_seq(candidate, history, mask, "DIN.attention_weights")
        return self._softmax_attn(cand, seq, m)

    def _forward_one(self, cand, seq, m):
        attn = self._softmax_attn(cand, seq, m)
        pooled = [0.0] * self.num_factors
        for j, row in enumerate(seq):
            if attn[j] == 0.0:
                continue
            for k in range(self.num_factors):
                pooled[k] += attn[j] * row[k]
        z = cand + pooled
        h = z
        for layer in self.hidden:
            h = layer.forward(h)
        logit = _w17b_dot(self.out_w, h) + self.out_b
        return logit, attn, pooled, h

    def logits(self, candidates, histories, masks=None):
        """批量打分。"""
        n = len(candidates)
        if n == 0:
            raise ValueError("DIN.logits: 至少需要一个样本")
        if masks is None:
            masks = [None] * n
        if len(histories) != n or len(masks) != n:
            raise ValueError("DIN.logits: candidates / histories / masks 样本数不一致")
        out = []
        for cand, hist, mask in zip(candidates, histories, masks):
            c, seq, m = self._check_seq(cand, hist, mask, "DIN.logits")
            out.append(self._forward_one(c, seq, m)[0])
        return out

    def loss_and_grads(self, candidates, histories, labels, masks=None):
        """二分类交叉熵 + 参数梯度；返回 `(loss, grads)`。

        `grads` 除参数外还带 `"dcandidate"` / `"dhistory"`（逐样本输入梯度），
        形状与入参一致，便于对拍与向上游传播。
        """
        if not isinstance(labels, (list, tuple)):
            raise TypeError("DIN.loss_and_grads: labels 必须是列表")
        n = len(labels)
        if n == 0:
            raise ValueError("DIN.loss_and_grads: 至少需要一个样本")
        if len(candidates) != n or len(histories) != n:
            raise ValueError("DIN.loss_and_grads: 样本数与 labels 不一致")
        ys = []
        for idx, y in enumerate(labels):
            v = _w17b_float(y, "DIN.loss_and_grads", f"第 {idx} 个 label")
            if v < 0.0 or v > 1.0:
                raise ValueError("DIN.loss_and_grads: label 必须在 [0, 1] 内")
            ys.append(v)
        if masks is None:
            masks = [None] * n
        if len(masks) != n:
            raise ValueError("DIN.loss_and_grads: masks 样本数不一致")

        f = self.num_factors
        grads = {
            "hidden": [
                ([[0.0] * layer.fan_in for _ in range(layer.fan_out)],
                 [0.0] * layer.fan_out)
                for layer in self.hidden
            ],
            "out_w": [0.0] * len(self.out_w),
            "out_b": 0.0,
            "dcandidate": [],
            "dhistory": [],
        }
        total_loss = 0.0
        for cand_raw, hist_raw, y, mask in zip(candidates, histories, ys, masks):
            cand, seq, m = self._check_seq(cand_raw, hist_raw, mask,
                                           "DIN.loss_and_grads")
            logit, attn, pooled, h = self._forward_one(cand, seq, m)
            total_loss += _w17b_bce(logit, y)
            g = 1.0 / (1.0 + math.exp(-logit)) - y

            for j in range(len(self.out_w)):
                grads["out_w"][j] += g * h[j]
            grads["out_b"] += g
            dh = [g * self.out_w[j] for j in range(len(self.out_w))]
            for idx in range(len(self.hidden) - 1, -1, -1):
                layer = self.hidden[idx]
                gw, gb, dh = layer.backward(dh)
                acc_w, acc_b = grads["hidden"][idx]
                for r in range(layer.fan_out):
                    for c in range(layer.fan_in):
                        acc_w[r][c] += gw[r][c]
                    acc_b[r] += gb[r]

            dcand = list(dh[:f])
            dpool = list(dh[f:])
            dot_dp_pool = _w17b_dot(dpool, pooled)
            scale = 1.0 / math.sqrt(f)
            ds = []
            for j in range(len(seq)):
                ds.append(attn[j] * (_w17b_dot(dpool, seq[j]) - dot_dp_pool))
            dhist = []
            for j in range(len(seq)):
                row = [0.0] * f
                for k in range(f):
                    row[k] = dpool[k] * attn[j] + ds[j] * cand[k] * scale
                dhist.append(row)
            for j in range(len(seq)):
                for k in range(f):
                    dcand[k] += ds[j] * seq[j][k] * scale
            grads["dcandidate"].append(dcand)
            grads["dhistory"].append(dhist)

        scale_all = 1.0 / n
        for idx, layer in enumerate(self.hidden):
            acc_w, acc_b = grads["hidden"][idx]
            for r in range(layer.fan_out):
                for c in range(layer.fan_in):
                    acc_w[r][c] *= scale_all
                acc_b[r] *= scale_all
        for j in range(len(self.out_w)):
            grads["out_w"][j] *= scale_all
        grads["out_b"] *= scale_all
        for idx in range(n):
            for k in range(f):
                grads["dcandidate"][idx][k] *= scale_all
            for row in grads["dhistory"][idx]:
                for k in range(f):
                    row[k] *= scale_all
        return total_loss / n, grads

    def apply_grads(self, grads, lr=0.05):
        """原地 SGD 一步（只更新参数，不碰输入梯度）。"""
        lr = _w17b_float(lr, "DIN.apply_grads", "lr")
        if lr < 0.0:
            raise ValueError("DIN.apply_grads: lr 必须 >= 0")
        for idx, layer in enumerate(self.hidden):
            acc_w, acc_b = grads["hidden"][idx]
            for r in range(layer.fan_out):
                for c in range(layer.fan_in):
                    layer.weights[r][c] -= lr * acc_w[r][c]
                layer.biases[r] -= lr * acc_b[r]
        for j in range(len(self.out_w)):
            self.out_w[j] -= lr * grads["out_w"][j]
        self.out_b -= lr * grads["out_b"]

    def param_count(self):
        """可训练标量个数（不含输入侧）。"""
        total = 0
        for layer in self.hidden:
            total += layer.fan_out * layer.fan_in + layer.fan_out
        total += len(self.out_w) + 1
        return total


# ======================================================================
#  领域应用：推荐（矩阵分解 / NCF / Wide&Deep）
# ======================================================================


def _w17b_rng(seed):
    """局部随机数发生器（不推进全局 random 状态）。"""
    return random.Random(seed) if seed is not None else random.Random()


def _w17b_float(value, who, name="value"):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"{who}: {name} 必须是数字，收到 {type(value).__name__}")
    if value != value or value in (float("inf"), float("-inf")):
        raise ValueError(f"{who}: {name} 不能是 nan/inf")
    return float(value)


def _w17b_int(value, who, name="value", minimum=0):
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{who}: {name} 必须是整数，收到 {type(value).__name__}")
    if value < minimum:
        raise ValueError(f"{who}: {name} 必须 >= {minimum}，收到 {value}")
    return value


def _w17b_rows(rows, width, who):
    """校验「等宽数值矩阵」。"""
    if not isinstance(rows, (list, tuple)) or not rows:
        raise ValueError(f"{who}: 需要一个非空的二维列表")
    out = []
    for r, row in enumerate(rows):
        if not isinstance(row, (list, tuple)):
            raise TypeError(f"{who}: 第 {r} 行不是列表")
        if len(row) != width:
            raise ValueError(f"{who}: 第 {r} 行长度 {len(row)}，应为 {width}")
        out.append([_w17b_float(v, who, f"第 {r} 行") for v in row])
    return out


def _w17b_dot(a, b):
    return sum(x * y for x, y in zip(a, b))


def _w17b_check_ratings(ratings, who):
    """校验 (user, item, value) 三元组列表。"""
    if not isinstance(ratings, (list, tuple)) or not ratings:
        raise ValueError(f"{who}: ratings 需要非空的 (user, item, value) 列表")
    out = []
    for idx, row in enumerate(ratings):
        if not isinstance(row, (list, tuple)) or len(row) != 3:
            raise ValueError(f"{who}: 第 {idx} 条不是 (user, item, value) 三元组")
        user = _w17b_int(row[0], who, f"第 {idx} 条的 user")
        item = _w17b_int(row[1], who, f"第 {idx} 条的 item")
        value = _w17b_float(row[2], who, f"第 {idx} 条的 value")
        out.append((user, item, value))
    return out


def matrix_factorization(ratings, num_factors=8, epochs=100, lr=0.02,
                         reg=0.05, seed=None):
    """矩阵分解（显式反馈，SGD 逐条更新 + L2 正则）。

    `ratings` 是 `(user, item, value)` 三元组列表；返回 dict：
    `{"user_factors", "item_factors", "losses", "num_users", "num_items"}`。
    `losses[e]` 是第 `e` 轮后的全量均方误差（确定性评估，不受采样顺序影响）。

    这是最朴素的 MF：只学 `P[u]·Q[i]`，没有偏置项、没有隐式反馈、没有
    交替最小二乘，`epochs` 轮全量遍历，学习率与正则都是固定值。
    """
    data = _w17b_check_ratings(ratings, "matrix_factorization")
    f = _w17b_int(num_factors, "matrix_factorization", "num_factors", 1)
    n_epochs = _w17b_int(epochs, "matrix_factorization", "epochs", 1)
    lr = _w17b_float(lr, "matrix_factorization", "lr")
    if lr <= 0.0:
        raise ValueError("matrix_factorization: lr 必须 > 0")
    reg = _w17b_float(reg, "matrix_factorization", "reg")
    if reg < 0.0:
        raise ValueError("matrix_factorization: reg 必须 >= 0")

    n_users = max(r[0] for r in data) + 1
    n_items = max(r[1] for r in data) + 1
    rng = _w17b_rng(seed)
    P = [[rng.gauss(0.0, 0.1) for _ in range(f)] for _ in range(n_users)]
    Q = [[rng.gauss(0.0, 0.1) for _ in range(f)] for _ in range(n_items)]

    order = list(range(len(data)))
    losses = []
    for _epoch in range(n_epochs):
        if seed is not None:
            rng.shuffle(order)
        for idx in order:
            u, i, value = data[idx]
            pu, qi = P[u], Q[i]
            err = value - _w17b_dot(pu, qi)
            # 用更新前的 pu 计算 qi 的梯度（标准的「冻结另一侧」写法）
            snapshot = list(pu)
            for k in range(f):
                pu[k] += lr * (err * qi[k] - reg * snapshot[k])
            for k in range(f):
                qi[k] += lr * (err * snapshot[k] - reg * qi[k])
        total = 0.0
        for u, i, value in data:
            diff = value - _w17b_dot(P[u], Q[i])
            total += diff * diff
        losses.append(total / len(data))

    return {
        "user_factors": P,
        "item_factors": Q,
        "losses": losses,
        "num_users": n_users,
        "num_items": n_items,
    }


def mf_predict(user_factors, item_factors, user, item):
    """用学到的因子预测单个 (user, item) 的评分。"""
    if not user_factors or not item_factors:
        raise ValueError("mf_predict: 因子矩阵不能为空")
    u = _w17b_int(user, "mf_predict", "user")
    i = _w17b_int(item, "mf_predict", "item")
    if u >= len(user_factors):
        raise ValueError(f"mf_predict: user 下标 {u} 越界（共 {len(user_factors)} 个）")
    if i >= len(item_factors):
        raise ValueError(f"mf_predict: item 下标 {i} 越界（共 {len(item_factors)} 个）")
    return _w17b_dot(user_factors[u], item_factors[i])


def mf_rmse(ratings, user_factors, item_factors):
    """矩阵分解在给定评分上的 RMSE。"""
    data = _w17b_check_ratings(ratings, "mf_rmse")
    total = 0.0
    for u, i, value in data:
        diff = value - mf_predict(user_factors, item_factors, u, i)
        total += diff * diff
    return math.sqrt(total / len(data))


def _w17b_bce(logit, target):
    """数值稳定的二分类交叉熵。"""
    if logit >= 0.0:
        return logit - target * logit + math.log1p(math.exp(-logit))
    return -target * logit + math.log1p(math.exp(logit))


class NCF:
    """神经协同过滤（GMF + MLP 的双塔融合，逐样本手写反向）。

    `scores` 用的是 GMF 的逐元素积 + 一个隐层 MLP，最终 logit 相加；
    因为 `Layer` 的缓存是「最后一次前向」，批量反传只能逐样本做
    （与本库 `_mlp_backward` 同一策略），`loss_and_grads` 内部已按样本数平均。
    """

    def __init__(self, num_users, num_items, factors=8, hidden=(16,), seed=None):
        self.num_users = _w17b_int(num_users, "NCF", "num_users", 1)
        self.num_items = _w17b_int(num_items, "NCF", "num_items", 1)
        self.factors = _w17b_int(factors, "NCF", "factors", 1)
        if not isinstance(hidden, (list, tuple)) or not hidden:
            raise ValueError("NCF: hidden 需要非空的层宽列表")
        self.hidden_sizes = [_w17b_int(h, "NCF", "hidden", 1) for h in hidden]
        if seed is not None:
            _w17b_int(seed, "NCF", "seed", 0)
        self.seed = seed

        rng = _w17b_rng(seed)
        std = 0.1
        f = self.factors
        self.user_emb = [[rng.gauss(0.0, std) for _ in range(f)]
                         for _ in range(self.num_users)]
        self.item_emb = [[rng.gauss(0.0, std) for _ in range(f)]
                         for _ in range(self.num_items)]
        self.gmf_w = [rng.gauss(0.0, std) for _ in range(f)]
        self.gmf_b = 0.0

        # Layer 用全局 random 初始化，用「保存-设置-恢复」保证可复现
        state = random.getstate()
        try:
            if seed is not None:
                random.seed(seed + 1)
            self.hidden = []
            fan_in = 2 * f
            for width in self.hidden_sizes:
                self.hidden.append(Layer(fan_in, width, activation="relu"))
                fan_in = width
        finally:
            random.setstate(state)
        self.out_w = [rng.gauss(0.0, std) for _ in range(fan_in)]
        self.out_b = 0.0

    # --- 前向 -------------------------------------------------------
    def _forward_one(self, user, item):
        u = _w17b_int(user, "NCF.scores", "user")
        i = _w17b_int(item, "NCF.scores", "item")
        if u >= self.num_users:
            raise ValueError(f"NCF.scores: user 下标 {u} 越界")
        if i >= self.num_items:
            raise ValueError(f"NCF.scores: item 下标 {i} 越界")
        eu, ei = self.user_emb[u], self.item_emb[i]
        g = [eu[k] * ei[k] for k in range(self.factors)]
        logit_gmf = _w17b_dot(self.gmf_w, g) + self.gmf_b
        h = eu + ei
        for layer in self.hidden:
            h = layer.forward(h)
        logit_mlp = _w17b_dot(self.out_w, h) + self.out_b
        return logit_gmf + logit_mlp, g, h

    def scores(self, user_ids, item_ids):
        """返回逐对的 logit（未过 sigmoid）。"""
        if not isinstance(user_ids, (list, tuple)) or not isinstance(item_ids, (list, tuple)):
            raise TypeError("NCF.scores: user_ids / item_ids 必须是列表")
        if len(user_ids) != len(item_ids):
            raise ValueError("NCF.scores: user_ids 与 item_ids 长度不一致")
        if not user_ids:
            raise ValueError("NCF.scores: 至少需要一个样本")
        return [self._forward_one(u, i)[0] for u, i in zip(user_ids, item_ids)]

    def predict_proba(self, user_ids, item_ids):
        """交互概率（sigmoid）。"""
        return [1.0 / (1.0 + math.exp(-z)) for z in self.scores(user_ids, item_ids)]

    # --- 反向 -------------------------------------------------------
    def loss_and_grads(self, user_ids, item_ids, labels):
        """二分类交叉熵 + 逐参数梯度；返回 `(loss, grads)`。"""
        if not isinstance(labels, (list, tuple)):
            raise TypeError("NCF.loss_and_grads: labels 必须是列表")
        if len(labels) != len(user_ids):
            raise ValueError("NCF.loss_and_grads: labels 长度与样本数不一致")
        pairs = list(zip(user_ids, item_ids))
        n = len(pairs)
        if n == 0:
            raise ValueError("NCF.loss_and_grads: 至少需要一个样本")
        ys = []
        for idx, y in enumerate(labels):
            v = _w17b_float(y, "NCF.loss_and_grads", f"第 {idx} 个 label")
            if v < 0.0 or v > 1.0:
                raise ValueError("NCF.loss_and_grads: label 必须在 [0, 1] 内")
            ys.append(v)

        grads = {
            "user_emb": [[0.0] * self.factors for _ in range(self.num_users)],
            "item_emb": [[0.0] * self.factors for _ in range(self.num_items)],
            "gmf_w": [0.0] * self.factors,
            "gmf_b": 0.0,
            "hidden": [
                ([[0.0] * layer.fan_in for _ in range(layer.fan_out)],
                 [0.0] * layer.fan_out)
                for layer in self.hidden
            ],
            "out_w": [0.0] * len(self.out_w),
            "out_b": 0.0,
        }
        total_loss = 0.0
        for (u, i), y in zip(pairs, ys):
            logit, g, h = self._forward_one(u, i)
            total_loss += _w17b_bce(logit, y)
            dlogit = 1.0 / (1.0 + math.exp(-logit)) - y

            for k in range(self.factors):
                grads["gmf_w"][k] += dlogit * g[k]
            grads["gmf_b"] += dlogit
            for j in range(len(self.out_w)):
                grads["out_w"][j] += dlogit * h[j]
            grads["out_b"] += dlogit

            dh = [dlogit * self.out_w[j] for j in range(len(self.out_w))]
            for idx in range(len(self.hidden) - 1, -1, -1):
                layer = self.hidden[idx]
                gw, gb, dh = layer.backward(dh)
                acc_w, acc_b = grads["hidden"][idx]
                for r in range(layer.fan_out):
                    for c in range(layer.fan_in):
                        acc_w[r][c] += gw[r][c]
                    acc_b[r] += gb[r]

            # concat 的梯度：前半给 user，后半给 item
            for k in range(self.factors):
                dg = dlogit * self.gmf_w[k]
                grads["user_emb"][u][k] += dg * self.item_emb[i][k] + dh[k]
                grads["item_emb"][i][k] += dg * self.user_emb[u][k] + dh[k + self.factors]

        scale = 1.0 / n
        for row in grads["user_emb"]:
            for k in range(self.factors):
                row[k] *= scale
        for row in grads["item_emb"]:
            for k in range(self.factors):
                row[k] *= scale
        for k in range(self.factors):
            grads["gmf_w"][k] *= scale
        grads["gmf_b"] *= scale
        for idx, layer in enumerate(self.hidden):
            acc_w, acc_b = grads["hidden"][idx]
            for r in range(layer.fan_out):
                for c in range(layer.fan_in):
                    acc_w[r][c] *= scale
                acc_b[r] *= scale
        for j in range(len(self.out_w)):
            grads["out_w"][j] *= scale
        grads["out_b"] *= scale
        return total_loss / n, grads

    def apply_grads(self, grads, lr=0.05):
        """原地 SGD 一步。"""
        lr = _w17b_float(lr, "NCF.apply_grads", "lr")
        if lr < 0.0:
            raise ValueError("NCF.apply_grads: lr 必须 >= 0")
        for u in range(self.num_users):
            for k in range(self.factors):
                self.user_emb[u][k] -= lr * grads["user_emb"][u][k]
        for i in range(self.num_items):
            for k in range(self.factors):
                self.item_emb[i][k] -= lr * grads["item_emb"][i][k]
        for k in range(self.factors):
            self.gmf_w[k] -= lr * grads["gmf_w"][k]
        self.gmf_b -= lr * grads["gmf_b"]
        for idx, layer in enumerate(self.hidden):
            acc_w, acc_b = grads["hidden"][idx]
            for r in range(layer.fan_out):
                for c in range(layer.fan_in):
                    layer.weights[r][c] -= lr * acc_w[r][c]
                layer.biases[r] -= lr * acc_b[r]
        for j in range(len(self.out_w)):
            self.out_w[j] -= lr * grads["out_w"][j]
        self.out_b -= lr * grads["out_b"]

    def param_count(self):
        """可训练标量个数。"""
        total = (self.num_users + self.num_items) * self.factors
        total += len(self.gmf_w) + 1
        for layer in self.hidden:
            total += layer.fan_out * layer.fan_in + layer.fan_out
        total += len(self.out_w) + 1
        return total


class WideAndDeep:
    """Wide&Deep：线性宽侧 + 单/多层深侧，logit 相加。

    宽侧吃稀疏特征（这里用稠密向量表示），深侧是 ReLU MLP；
    两侧只在 logit 处相加，没有联合训练技巧（也不需要）。
    """

    def __init__(self, num_wide, num_deep, hidden=(8,), seed=None):
        self.num_wide = _w17b_int(num_wide, "WideAndDeep", "num_wide", 1)
        self.num_deep = _w17b_int(num_deep, "WideAndDeep", "num_deep", 1)
        if not isinstance(hidden, (list, tuple)) or not hidden:
            raise ValueError("WideAndDeep: hidden 需要非空的层宽列表")
        self.hidden_sizes = [_w17b_int(h, "WideAndDeep", "hidden", 1) for h in hidden]
        if seed is not None:
            _w17b_int(seed, "WideAndDeep", "seed", 0)
        self.seed = seed

        rng = _w17b_rng(seed)
        self.wide_w = [rng.gauss(0.0, 0.1) for _ in range(self.num_wide)]
        self.wide_b = 0.0
        state = random.getstate()
        try:
            if seed is not None:
                random.seed(seed + 1)
            self.hidden = []
            fan_in = self.num_deep
            for width in self.hidden_sizes:
                self.hidden.append(Layer(fan_in, width, activation="relu"))
                fan_in = width
        finally:
            random.setstate(state)
        self.deep_w = [rng.gauss(0.0, 0.1) for _ in range(fan_in)]
        self.deep_b = 0.0

    def _check_pair(self, wide_x, deep_x, who):
        w = _w17b_rows([wide_x], self.num_wide, who)[0]
        d = _w17b_rows([deep_x], self.num_deep, who)[0]
        return w, d

    def logits(self, wide_features, deep_features):
        """返回逐样本 logit。"""
        if len(wide_features) != len(deep_features):
            raise ValueError("WideAndDeep.logits: 宽侧与深侧样本数不一致")
        if not wide_features:
            raise ValueError("WideAndDeep.logits: 至少需要一个样本")
        out = []
        for wide_x, deep_x in zip(wide_features, deep_features):
            w, d = self._check_pair(wide_x, deep_x, "WideAndDeep.logits")
            h = d
            for layer in self.hidden:
                h = layer.forward(h)
            out.append(_w17b_dot(self.wide_w, w) + self.wide_b
                       + _w17b_dot(self.deep_w, h) + self.deep_b)
        return out

    def loss_and_grads(self, wide_features, deep_features, labels):
        """二分类交叉熵 + 梯度；返回 `(loss, grads)`。"""
        if not isinstance(labels, (list, tuple)):
            raise TypeError("WideAndDeep.loss_and_grads: labels 必须是列表")
        if len(labels) != len(wide_features):
            raise ValueError("WideAndDeep.loss_and_grads: labels 长度与样本数不一致")
        n = len(labels)
        if n == 0:
            raise ValueError("WideAndDeep.loss_and_grads: 至少需要一个样本")
        ys = []
        for idx, y in enumerate(labels):
            v = _w17b_float(y, "WideAndDeep.loss_and_grads", f"第 {idx} 个 label")
            if v < 0.0 or v > 1.0:
                raise ValueError("WideAndDeep.loss_and_grads: label 必须在 [0, 1] 内")
            ys.append(v)

        grads = {
            "wide_w": [0.0] * self.num_wide,
            "wide_b": 0.0,
            "hidden": [
                ([[0.0] * layer.fan_in for _ in range(layer.fan_out)],
                 [0.0] * layer.fan_out)
                for layer in self.hidden
            ],
            "deep_w": [0.0] * len(self.deep_w),
            "deep_b": 0.0,
        }
        total_loss = 0.0
        for wide_x, deep_x, y in zip(wide_features, deep_features, ys):
            w, d = self._check_pair(wide_x, deep_x, "WideAndDeep.loss_and_grads")
            h = d
            for layer in self.hidden:
                h = layer.forward(h)
            logit = (_w17b_dot(self.wide_w, w) + self.wide_b
                     + _w17b_dot(self.deep_w, h) + self.deep_b)
            total_loss += _w17b_bce(logit, y)
            dlogit = 1.0 / (1.0 + math.exp(-logit)) - y

            for j in range(self.num_wide):
                grads["wide_w"][j] += dlogit * w[j]
            grads["wide_b"] += dlogit
            for j in range(len(self.deep_w)):
                grads["deep_w"][j] += dlogit * h[j]
            grads["deep_b"] += dlogit

            dh = [dlogit * self.deep_w[j] for j in range(len(self.deep_w))]
            for idx in range(len(self.hidden) - 1, -1, -1):
                layer = self.hidden[idx]
                gw, gb, dh = layer.backward(dh)
                acc_w, acc_b = grads["hidden"][idx]
                for r in range(layer.fan_out):
                    for c in range(layer.fan_in):
                        acc_w[r][c] += gw[r][c]
                    acc_b[r] += gb[r]

        scale = 1.0 / n
        for j in range(self.num_wide):
            grads["wide_w"][j] *= scale
        grads["wide_b"] *= scale
        for idx, layer in enumerate(self.hidden):
            acc_w, acc_b = grads["hidden"][idx]
            for r in range(layer.fan_out):
                for c in range(layer.fan_in):
                    acc_w[r][c] *= scale
                acc_b[r] *= scale
        for j in range(len(self.deep_w)):
            grads["deep_w"][j] *= scale
        grads["deep_b"] *= scale
        return total_loss / n, grads

    def apply_grads(self, grads, lr=0.05):
        """原地 SGD 一步。"""
        lr = _w17b_float(lr, "WideAndDeep.apply_grads", "lr")
        if lr < 0.0:
            raise ValueError("WideAndDeep.apply_grads: lr 必须 >= 0")
        for j in range(self.num_wide):
            self.wide_w[j] -= lr * grads["wide_w"][j]
        self.wide_b -= lr * grads["wide_b"]
        for idx, layer in enumerate(self.hidden):
            acc_w, acc_b = grads["hidden"][idx]
            for r in range(layer.fan_out):
                for c in range(layer.fan_in):
                    layer.weights[r][c] -= lr * acc_w[r][c]
                layer.biases[r] -= lr * acc_b[r]
        for j in range(len(self.deep_w)):
            self.deep_w[j] -= lr * grads["deep_w"][j]
        self.deep_b -= lr * grads["deep_b"]

    def param_count(self):
        """可训练标量个数。"""
        total = self.num_wide + 1
        for layer in self.hidden:
            total += layer.fan_out * layer.fan_in + layer.fan_out
        total += len(self.deep_w) + 1
        return total


# ============================================================================
#  联邦学习（FedAvg / FedProx / FedBN / 参数摊平）
# ============================================================================

def _fed_check_updates(updates, who):
    """校验「客户端更新列表」：非空、每项是 dict、键集合完全一致。"""
    if not isinstance(updates, (list, tuple)) or not updates:
        raise ValueError(f"{who}: updates 必须是非空列表")
    first = None
    for i, up in enumerate(updates):
        if not isinstance(up, dict) or not up:
            raise ValueError(f"{who}: updates[{i}] 必须是非空 dict")
        keys = set(up.keys())
        if first is None:
            first = keys
        elif keys != first:
            missing = sorted(first - keys)
            extra = sorted(keys - first)
            raise ValueError(
                f"{who}: updates[{i}] 的键与第一个客户端不一致"
                f"（缺 {missing}，多 {extra}）")
        for key, vec in up.items():
            if not isinstance(vec, (list, tuple)) or not vec:
                raise ValueError(f"{who}: updates[{i}][{key!r}] 必须是非空列表")
            for v in vec:
                if isinstance(v, bool) or not isinstance(v, (int, float)):
                    raise ValueError(
                        f"{who}: updates[{i}][{key!r}] 含非数字元素 {v!r}")
    return list(updates[0].keys())


def _fed_check_weights(updates, weights, who):
    """校验客户端权重（省略时为等权）。"""
    if weights is None:
        return [1.0] * len(updates)
    if not isinstance(weights, (list, tuple)) or len(weights) != len(updates):
        raise ValueError(f"{who}: weights 长度必须与 updates 相同")
    out = []
    total = 0.0
    for i, w in enumerate(weights):
        if isinstance(w, bool) or not isinstance(w, (int, float)) or w < 0.0:
            raise ValueError(f"{who}: weights[{i}] 必须是非负数字，收到 {w!r}")
        out.append(float(w))
        total += float(w)
    if total <= 0.0:
        raise ValueError(f"{who}: weights 之和必须 > 0")
    return out


def _fed_same_shape(a, b, who, key):
    if len(a) != len(b):
        raise ValueError(
            f"{who}: 键 {key!r} 的向量长度不一致（{len(a)} vs {len(b)}）")


def fedavg(updates, weights=None):
    """FedAvg：按客户端权重对同名参数做加权平均。"""
    keys = _fed_check_updates(updates, "fedavg")
    ws = _fed_check_weights(updates, weights, "fedavg")
    total = sum(ws)
    out = {}
    for key in keys:
        base = updates[0][key]
        acc = [0.0] * len(base)
        for up, w in zip(updates, ws):
            vec = up[key]
            _fed_same_shape(base, vec, "fedavg", key)
            for i in range(len(vec)):
                acc[i] += w * float(vec[i])
        out[key] = [v / total for v in acc]
    return out


def fedprox_penalty(local, global_params, mu=0.01):
    """FedProx 的近端项 ``0.5*mu*||local-global||^2`` 及其对 local 的梯度。"""
    keys = _fed_check_updates([local], "fedprox_penalty")
    if not isinstance(global_params, dict) or not global_params:
        raise ValueError("fedprox_penalty: global_params 必须是非空 dict")
    if set(global_params.keys()) != set(keys):
        raise ValueError("fedprox_penalty: local 与 global_params 的键不一致")
    if isinstance(mu, bool) or not isinstance(mu, (int, float)) or mu < 0.0:
        raise ValueError(f"fedprox_penalty: mu 必须是非负数字，收到 {mu!r}")
    penalty = 0.0
    grad = {}
    for key in keys:
        loc = local[key]
        glo = global_params[key]
        _fed_same_shape(loc, glo, "fedprox_penalty", key)
        g = [0.0] * len(loc)
        for i in range(len(loc)):
            diff = float(loc[i]) - float(glo[i])
            penalty += 0.5 * float(mu) * diff * diff
            g[i] = float(mu) * diff
        grad[key] = g
    return penalty, grad


def _fed_is_private(key, private_prefixes):
    for prefix in private_prefixes:
        if key.startswith(prefix):
            return True
    return False


def fedbn_split(update, private_prefixes=("bn.", "norm.")):
    """把一份客户端参数拆成「共享」与「私有」（FedBN 的本地 BatchNorm）。"""
    if not isinstance(update, dict) or not update:
        raise ValueError("fedbn_split: update 必须是非空 dict")
    if not isinstance(private_prefixes, (list, tuple)):
        raise ValueError("fedbn_split: private_prefixes 必须是字符串列表")
    for prefix in private_prefixes:
        if not isinstance(prefix, str) or not prefix:
            raise ValueError(
                f"fedbn_split: private_prefixes 里必须是非空字符串，收到 {prefix!r}")
    shared = {}
    private = {}
    for key, vec in update.items():
        (private if _fed_is_private(key, private_prefixes) else shared)[key] = vec
    return shared, private


def fedbn_average(updates, private_prefixes=("bn.", "norm."), weights=None):
    """FedBN：只平均共享参数，私有参数各自保留。

    返回 ``(shared_avg, private_list)``，``private_list`` 与 ``updates`` 等长。
    """
    keys = _fed_check_updates(updates, "fedbn_average")
    ws = _fed_check_weights(updates, weights, "fedbn_average")
    shared_keys = [k for k in keys if not _fed_is_private(k, private_prefixes)]
    if not shared_keys:
        raise ValueError(
            "fedbn_average: 所有键都是私有参数，没有可平均的共享参数")
    shareds = []
    privates = []
    for up in updates:
        s, p = fedbn_split(up, private_prefixes)
        if sorted(s.keys()) != sorted(shared_keys):
            raise ValueError("fedbn_average: 各客户端的共享键集合不一致")
        shareds.append(s)
        privates.append(p)
    avg = fedavg(shareds, ws)
    return avg, privates


def named_params(model):
    """把 MLP 的参数摊平成 ``{"L0.W": [...], "L0.b": [...]}``（行主序）。"""
    mlp = _meta_mlp(model, "named_params")
    out = {}
    for i, layer in enumerate(mlp.layers):
        flat = []
        for row in layer.weights:
            flat.extend(float(v) for v in row)
        out["L%d.W" % i] = flat
        out["L%d.b" % i] = [float(v) for v in layer.biases]
    return out


def load_named_params(model, params):
    """``named_params`` 的逆操作；形状不符直接报错。"""
    mlp = _meta_mlp(model, "load_named_params")
    if not isinstance(params, dict) or not params:
        raise ValueError("load_named_params: params 必须是非空 dict")
    for i, layer in enumerate(mlp.layers):
        wkey = "L%d.W" % i
        bkey = "L%d.b" % i
        if wkey not in params or bkey not in params:
            raise ValueError(f"load_named_params: 缺少 {wkey!r} 或 {bkey!r}")
        wvec = params[wkey]
        bvec = params[bkey]
        if len(wvec) != layer.fan_out * layer.fan_in:
            raise ValueError(
                f"load_named_params: {wkey!r} 长度 {len(wvec)} "
                f"应为 {layer.fan_out * layer.fan_in}")
        if len(bvec) != layer.fan_out:
            raise ValueError(
                f"load_named_params: {bkey!r} 长度 {len(bvec)} 应为 {layer.fan_out}")
        k = 0
        for j in range(layer.fan_out):
            for col in range(layer.fan_in):
                layer.weights[j][col] = float(wvec[k])
                k += 1
        layer.biases[:] = [float(v) for v in bvec]

# ============================================================================
#  元学习（MAML / Reptile / ProtoNet / Matching Networks）
# ============================================================================

def _meta_mlp(model, who):
    """取出内部的 MLP（接受 `MLP` 或 `Model` 包装器）。"""
    mlp = getattr(model, "model", model)
    if not hasattr(mlp, "layers"):
        raise ValueError(f"{who}: 需要 MLP（或带 .model 的 Model），收到 {type(model).__name__}")
    return mlp


def _meta_copy_params(mlp):
    """深拷贝每层的 ``(weights, biases)``。"""
    return [([list(row) for row in layer.weights], list(layer.biases))
            for layer in mlp.layers]


def _meta_load_params(mlp, params):
    """把参数写回模型（逐行原地赋值，保持层对象与优化器引用不变）。"""
    if not isinstance(params, (list, tuple)) or len(params) != len(mlp.layers):
        raise ValueError(
            f"元学习: 参数层数 {len(params) if isinstance(params, (list, tuple)) else '?'} "
            f"与模型层数 {len(mlp.layers)} 不一致")
    for layer, (weights, biases) in zip(mlp.layers, params):
        if len(weights) != layer.fan_out or len(biases) != layer.fan_out:
            raise ValueError("元学习: 参数形状与模型不一致")
        for j in range(layer.fan_out):
            if len(weights[j]) != layer.fan_in:
                raise ValueError("元学习: 权重列数与模型不一致")
            layer.weights[j][:] = weights[j]
        layer.biases[:] = biases


def _meta_grads_to_params(mlp, grads):
    """``[(gw, gb)]`` → 与 ``_meta_copy_params`` 同形的参数列表（方便做加/减）。"""
    out = []
    for (gw, gb) in grads:
        out.append(([list(row) for row in gw], list(gb)))
    return out


def _meta_sub(params, deltas, scale):
    """``params - scale * deltas``（逐元素，返回新列表）。"""
    out = []
    for (w, b), (dw, db) in zip(params, deltas):
        out.append(([[w[j][i] - scale * dw[j][i] for i in range(len(w[j]))]
                     for j in range(len(w))],
                    [b[j] - scale * db[j] for j in range(len(b))]))
    return out


def _meta_add_scaled(base, other, scale):
    """``base + scale * other``（逐元素，返回新列表）。"""
    out = []
    for (w, b), (ow, ob) in zip(base, other):
        out.append(([[w[j][i] + scale * ow[j][i] for i in range(len(w[j]))]
                     for j in range(len(w))],
                    [b[j] + scale * ob[j] for j in range(len(b))]))
    return out


def maml_inner_step(model, xs, ys, inner_lr=0.1, inner_steps=1, loss_fn=None):
    """MAML 的内循环：在给定任务上做 ``inner_steps`` 步 SGD，返回 ``(params, losses)``。

    ``inner_lr`` 是任务内学习率；``params`` 是**适配后**的参数副本（不改动传入模型）。
    """
    mlp = _meta_mlp(model, "maml_inner_step")
    if not isinstance(xs, (list, tuple)) or not xs:
        raise ValueError("maml_inner_step: xs 必须是非空列表")
    if not isinstance(ys, (list, tuple)) or len(ys) != len(xs):
        raise ValueError("maml_inner_step: ys 长度必须与 xs 相同")
    if isinstance(inner_lr, bool) or not isinstance(inner_lr, (int, float)) or inner_lr <= 0.0:
        raise ValueError(f"maml_inner_step: inner_lr 必须 > 0，收到 {inner_lr!r}")
    if isinstance(inner_steps, bool) or not isinstance(inner_steps, int) or inner_steps < 1:
        raise ValueError(
            f"maml_inner_step: inner_steps 必须是 >=1 的整数，收到 {inner_steps!r}")
    original = _meta_copy_params(mlp)
    params = _meta_copy_params(mlp)
    losses = []
    try:
        for _ in range(inner_steps):
            acc_w = [[[0.0] * layer.fan_in for _ in range(layer.fan_out)]
                     for layer in mlp.layers]
            acc_b = [[0.0] * layer.fan_out for layer in mlp.layers]
            total = 0.0
            for i in range(len(xs)):
                _meta_load_params(mlp, params)
                pred = mlp.forward(list(xs[i]))
                if loss_fn is None:
                    loss, grad = mse_loss(pred, list(ys[i]))
                else:
                    loss, grad = loss_fn(pred, list(ys[i]))
                total += loss
                grads = _mlp_backward(mlp, grad)
                for li, (gw, gb) in enumerate(grads):
                    for j in range(len(gw)):
                        row = acc_w[li][j]
                        for k in range(len(gw[j])):
                            row[k] += gw[j][k]
                        acc_b[li][j] += gb[j]
            inv = 1.0 / len(xs)
            avg = [([[v * inv for v in row] for row in layer], [v * inv for v in b])
                   for layer, b in zip(acc_w, acc_b)]
            params = _meta_sub(params, avg, inner_lr)
            losses.append(total / len(xs))
    finally:
        _meta_load_params(mlp, original)
    return params, losses


def maml_outer_grads(model, tasks, inner_lr=0.1, inner_steps=1, loss_fn=None):
    """一阶 MAML 的外循环梯度：每个任务适配后算 query 梯度，按任务平均。

    返回 ``(loss, grads)``，``grads`` 与 ``_mlp_backward`` 同形。**这是一阶近似**
    （不展开内循环的二阶项），docstring 与 README 都写明。
    """
    mlp = _meta_mlp(model, "maml_outer_grads")
    if not isinstance(tasks, (list, tuple)) or not tasks:
        raise ValueError("maml_outer_grads: tasks 必须是非空列表")
    total_loss = 0.0
    acc = None
    original = _meta_copy_params(mlp)
    try:
        for task in tasks:
            if not isinstance(task, (list, tuple)) or len(task) != 4:
                raise ValueError(
                    "maml_outer_grads: 每个任务必须是 (support_x, support_y, query_x, query_y)")
            support_x, support_y, query_x, query_y = task
            adapted, _ = maml_inner_step(mlp, support_x, support_y,
                                         inner_lr=inner_lr, inner_steps=inner_steps,
                                         loss_fn=loss_fn)
            _meta_load_params(mlp, adapted)
            layer_acc_w = [[[0.0] * layer.fan_in for _ in range(layer.fan_out)]
                           for layer in mlp.layers]
            layer_acc_b = [[0.0] * layer.fan_out for layer in mlp.layers]
            for i in range(len(query_x)):
                pred = mlp.forward(list(query_x[i]))
                if loss_fn is None:
                    loss, grad = mse_loss(pred, list(query_y[i]))
                else:
                    loss, grad = loss_fn(pred, list(query_y[i]))
                total_loss += loss
                grads = _mlp_backward(mlp, grad)
                for li, (gw, gb) in enumerate(grads):
                    for j in range(len(gw)):
                        row = layer_acc_w[li][j]
                        for k in range(len(gw[j])):
                            row[k] += gw[j][k]
                        layer_acc_b[li][j] += gb[j]
            inv = 1.0 / len(query_x)
            cur = []
            for li in range(len(mlp.layers)):
                cur.append(([[v * inv for v in row] for row in layer_acc_w[li]],
                            [v * inv for v in layer_acc_b[li]]))
            if acc is None:
                acc = [([list(r) for r in gw], list(gb)) for (gw, gb) in cur]
            else:
                merged = []
                for li in range(len(mlp.layers)):
                    w = [[acc[li][0][j][k] + cur[li][0][j][k]
                          for k in range(len(acc[li][0][j]))]
                         for j in range(len(acc[li][0]))]
                    b = [acc[li][1][j] + cur[li][1][j] for j in range(len(acc[li][1]))]
                    merged.append((w, b))
                acc = merged
    finally:
        _meta_load_params(mlp, original)
    n_tasks = float(len(tasks))
    if not acc:
        raise ValueError("maml_outer_grads: 没有可用的任务梯度")
    grads = [([[v / n_tasks for v in row] for row in gw],
              [v / n_tasks for v in gb]) for (gw, gb) in acc]
    return total_loss / (n_tasks * max(1, len(tasks[0][2]))), grads


def reptile_step(model, tasks, inner_lr=0.1, inner_steps=1, meta_lr=0.1, loss_fn=None):
    """Reptile：对每个任务做内循环，再朝「各任务适配后参数的均值」走一步。

    直接**原地更新**传入模型，返回 ``(meta_loss, mean_delta_norm)``。
    """
    mlp = _meta_mlp(model, "reptile_step")
    if not isinstance(tasks, (list, tuple)) or not tasks:
        raise ValueError("reptile_step: tasks 必须是非空列表")
    if isinstance(meta_lr, bool) or not isinstance(meta_lr, (int, float)) or meta_lr <= 0.0:
        raise ValueError(f"reptile_step: meta_lr 必须 > 0，收到 {meta_lr!r}")
    original = _meta_copy_params(mlp)
    deltas = []
    losses = []
    try:
        for task in tasks:
            if not isinstance(task, (list, tuple)) or len(task) != 4:
                raise ValueError("reptile_step: 每个任务必须是四元组")
            support_x, support_y, _, _ = task
            adapted, task_losses = maml_inner_step(
                mlp, support_x, support_y, inner_lr=inner_lr,
                inner_steps=inner_steps, loss_fn=loss_fn)
            deltas.append((adapted, original))
            losses.append(task_losses[-1])
    finally:
        pass
    mean_delta = []
    for li in range(len(original)):
        w = [[0.0] * original[li][0][0].__len__() for _ in range(len(original[li][0]))]
        for j in range(len(original[li][0])):
            for k in range(len(original[li][0][j])):
                acc = 0.0
                for (adapted, base) in deltas:
                    acc += adapted[li][0][j][k] - base[li][0][j][k]
                w[j][k] = acc / len(deltas)
        b = []
        for j in range(len(original[li][1])):
            acc = 0.0
            for (adapted, base) in deltas:
                acc += adapted[li][1][j] - base[li][1][j]
            b.append(acc / len(deltas))
        mean_delta.append((w, b))
    updated = _meta_add_scaled(original, mean_delta, meta_lr)
    _meta_load_params(mlp, updated)
    norm = 0.0
    for (w, b) in mean_delta:
        for row in w:
            for v in row:
                norm += v * v
        for v in b:
            norm += v * v
    return sum(losses) / len(losses), math.sqrt(norm)


def prototype_embeddings(embeddings, labels):
    """每类嵌入的均值（原型），返回 ``{label: [均值...]}``。"""
    if not isinstance(embeddings, (list, tuple)) or not embeddings:
        raise ValueError("prototype_embeddings: embeddings 必须是非空列表")
    if not isinstance(labels, (list, tuple)) or len(labels) != len(embeddings):
        raise ValueError("prototype_embeddings: labels 长度必须与 embeddings 相同")
    groups = {}
    for i, label in enumerate(labels):
        groups.setdefault(label, []).append([float(v) for v in embeddings[i]])
    out = {}
    for label, rows in groups.items():
        dim = len(rows[0])
        if any(len(r) != dim for r in rows):
            raise ValueError("prototype_embeddings: 同类嵌入维度不一致")
        out[label] = [sum(r[d] for r in rows) / len(rows) for d in range(dim)]
    return out


def prototype_logits(query_embeddings, prototypes, temperature=1.0):
    """负平方距离 → softmax 前的 logits：``-||q - p_c||^2 / T``。"""
    if not isinstance(query_embeddings, (list, tuple)) or not query_embeddings:
        raise ValueError("prototype_logits: query_embeddings 必须是非空列表")
    if not isinstance(prototypes, dict) or not prototypes:
        raise ValueError("prototype_logits: prototypes 必须是非空 dict")
    if isinstance(temperature, bool) or not isinstance(temperature, (int, float)) \
            or temperature <= 0.0:
        raise ValueError(
            f"prototype_logits: temperature 必须 > 0，收到 {temperature!r}")
    labels = list(prototypes.keys())
    out = []
    for i, q in enumerate(query_embeddings):
        dim = len(prototypes[labels[0]])
        if len(q) != dim:
            raise ValueError(f"prototype_logits: 第 {i} 个查询维度 {len(q)} 与原型 {dim} 不一致")
        row = []
        for label in labels:
            p = prototypes[label]
            dist = 0.0
            for d in range(dim):
                diff = float(q[d]) - p[d]
                dist += diff * diff
            row.append(-dist / float(temperature))
        out.append(row)
    return out, labels


def prototypical_loss(query_embeddings, query_labels, support_embeddings,
                      support_labels, temperature=1.0):
    """ProtoNet 损失：负对数 softmax + 对查询嵌入的梯度，返回 ``(loss, dquery)``。"""
    if not isinstance(query_labels, (list, tuple)) \
            or len(query_labels) != len(query_embeddings):
        raise ValueError("prototypical_loss: query_labels 长度必须与查询数相同")
    prototypes = prototype_embeddings(support_embeddings, support_labels)
    logits, labels = prototype_logits(query_embeddings, prototypes, temperature)
    index = {label: i for i, label in enumerate(labels)}
    total = 0.0
    dquery = []
    inv_n = 1.0 / len(query_embeddings)
    for i, label in enumerate(query_labels):
        if label not in index:
            raise ValueError(
                f"prototypical_loss: 查询标签 {label!r} 不在支持集类别里")
        row = logits[i]
        probs = _rl_softmax(row)
        target = index[label]
        total -= _rl_log(max(probs[target], 1e-300))
        grad_row = list(probs)
        grad_row[target] -= 1.0
        dim = len(query_embeddings[i])
        g = [0.0] * dim
        for c, lab in enumerate(labels):
            p = prototypes[lab]
            for d in range(dim):
                diff = float(query_embeddings[i][d]) - p[d]
                g[d] += inv_n * grad_row[c] * (-2.0 * diff / float(temperature))
        dquery.append(g)
    return total / len(query_embeddings), dquery


def matching_attention(query, support, temperature=1.0):
    """Matching Networks 的注意力：对余弦相似度做 softmax。"""
    if not isinstance(query, (list, tuple)) or not query:
        raise ValueError("matching_attention: query 必须是向量")
    if not isinstance(support, (list, tuple)) or not support:
        raise ValueError("matching_attention: support 必须是非空列表")
    if isinstance(temperature, bool) or not isinstance(temperature, (int, float)) \
            or temperature <= 0.0:
        raise ValueError(
            f"matching_attention: temperature 必须 > 0，收到 {temperature!r}")
    qn = _norm_vec([float(v) for v in query], "matching_attention")
    sims = []
    for i, s in enumerate(support):
        if len(s) != len(query):
            raise ValueError(
                f"matching_attention: support[{i}] 维度 {len(s)} 与查询 {len(query)} 不一致")
        sn = _norm_vec([float(v) for v in s], "matching_attention")
        sims.append(sum(qn[d] * sn[d] for d in range(len(qn))) / float(temperature))
    return _rl_softmax(sims)


def _norm_vec(vec, who):
    """L2 归一化（零向量报错）。"""
    total = 0.0
    for v in vec:
        total += v * v
    if total <= 0.0:
        raise ValueError(f"{who}: 向量不能是零向量")
    n = math.sqrt(total)
    return [v / n for v in vec]


def matching_logits(query, support, support_labels, num_classes):
    """Matching Networks 的类概率：support 注意力按标签加权。"""
    if isinstance(num_classes, bool) or not isinstance(num_classes, int) or num_classes < 1:
        raise ValueError(
            f"matching_logits: num_classes 必须是 >=1 的整数，收到 {num_classes!r}")
    if not isinstance(support_labels, (list, tuple)) \
            or len(support_labels) != len(support):
        raise ValueError("matching_logits: support_labels 长度必须与 support 相同")
    weights = matching_attention(query, support)
    out = [0.0] * num_classes
    for i, label in enumerate(support_labels):
        if isinstance(label, bool) or not isinstance(label, int) \
                or not (0 <= label < num_classes):
            raise ValueError(
                f"matching_logits: support_labels[{i}] 必须是 0..{num_classes - 1}，"
                f"收到 {label!r}")
        out[label] += weights[i]
    return out

# ============================================================================
#  RL 环境（GridWorld / CartPole）
# ============================================================================

class GridWorld:
    """最小网格世界：连续动作 0=上 1=右 2=下 3=左。

    state 是 ``(row, col)``；撞墙或越界原地不动（仍然扣一步的 ``step_reward``）；
    到达 ``goal`` 得 ``goal_reward`` 并结束；超过 ``max_steps`` 视为截断
    （``info["truncated"] = True``）。
    """

    def __init__(self, height=5, width=5, start=(0, 0), goal=None,
                 obstacles=None, max_steps=50, step_reward=-0.01,
                 goal_reward=1.0, seed=None):
        for name, v in (("height", height), ("width", width), ("max_steps", max_steps)):
            if not isinstance(v, int) or isinstance(v, bool) or v < 1:
                raise ValueError(
                    f"GridWorld: {name} 必须是 >=1 的整数，收到 {v!r}")
        self.height = height
        self.width = width
        self.max_steps = max_steps
        if not isinstance(step_reward, (int, float)) or isinstance(step_reward, bool):
            raise ValueError("GridWorld: step_reward 必须是数字")
        if not isinstance(goal_reward, (int, float)) or isinstance(goal_reward, bool):
            raise ValueError("GridWorld: goal_reward 必须是数字")
        self.step_reward = float(step_reward)
        self.goal_reward = float(goal_reward)

        def cell(name, v):
            if not isinstance(v, (list, tuple)) or len(v) != 2:
                raise ValueError(f"GridWorld: {name} 必须是 (row, col)，收到 {v!r}")
            r, c = v
            for x in (r, c):
                if not isinstance(x, int) or isinstance(x, bool):
                    raise ValueError(f"GridWorld: {name} 的坐标必须是整数，收到 {v!r}")
            if not (0 <= r < height and 0 <= c < width):
                raise ValueError(
                    f"GridWorld: {name}={v!r} 越界（网格 {height}x{width}）")
            return (r, c)

        self.start = cell("start", start)
        self.goal = cell("goal", goal if goal is not None else (height - 1, width - 1))
        if self.start == self.goal:
            raise ValueError("GridWorld: start 与 goal 不能是同一个格子")
        blocked = []
        if obstacles is not None:
            if not isinstance(obstacles, (list, tuple)):
                raise ValueError("GridWorld: obstacles 必须是 (row, col) 的列表")
            for i, o in enumerate(obstacles):
                blocked.append(cell(f"obstacles[{i}]", o))
        if self.start in blocked or self.goal in blocked:
            raise ValueError("GridWorld: start / goal 不能落在障碍物上")
        self.obstacles = blocked
        self.rng = random.Random(seed)
        self.state = self.start
        self.steps = 0
        self.observation_shape = (2,)
        self.num_actions = 4

    def reset(self, seed=None):
        """回到起点并清零步数；给了 ``seed`` 就重置本地 RNG。"""
        if seed is not None:
            self.rng = random.Random(seed)
        self.state = self.start
        self.steps = 0
        return self.state

    def _move(self, state, action):
        r, c = state
        if action == 0:
            r -= 1
        elif action == 1:
            c += 1
        elif action == 2:
            r += 1
        elif action == 3:
            c -= 1
        return (r, c)

    def step(self, action):
        """返回 ``(state, reward, done, info)``。"""
        if isinstance(action, bool) or not isinstance(action, int) \
                or not (0 <= action < self.num_actions):
            raise ValueError(
                f"GridWorld.step: action 必须是 0..3 的整数，收到 {action!r}")
        self.steps += 1
        nxt = self._move(self.state, action)
        r, c = nxt
        if not (0 <= r < self.height and 0 <= c < self.width) or nxt in self.obstacles:
            nxt = self.state
        self.state = nxt
        if nxt == self.goal:
            return nxt, self.goal_reward, True, {"truncated": False, "steps": self.steps}
        if self.steps >= self.max_steps:
            return nxt, self.step_reward, True, {"truncated": True, "steps": self.steps}
        return nxt, self.step_reward, False, {"truncated": False, "steps": self.steps}

    def render(self):
        """返回字符画：``S`` 起点、``G`` 终点、``#`` 障碍、``A`` 当前智能体。"""
        lines = []
        for r in range(self.height):
            row = []
            for c in range(self.width):
                cell = (r, c)
                if cell == self.state:
                    row.append("A")
                elif cell == self.goal:
                    row.append("G")
                elif cell in self.obstacles:
                    row.append("#")
                elif cell == self.start:
                    row.append("S")
                else:
                    row.append(".")
            lines.append("".join(row))
        return "\n".join(lines)


class CartPole:
    """简化版 CartPole（离散动作 0=左推 1=右推），物理常数照 Gym 的原始取值。

    state 是 ``(x, x_dot, theta, theta_dot)``；``theta`` 用弧度。每步奖励 1.0；
    ``|x| > 2.4`` 或 ``|theta| > 12 度`` 结束，超过 ``max_steps`` 视为截断。
    """

    gravity = 9.8
    masscart = 1.0
    masspole = 0.1
    total_mass = masscart + masspole
    length = 0.5            # 半杆长
    polemass_length = masspole * length
    force_mag = 10.0
    tau = 0.02
    theta_threshold = 12 * 2 * math.pi / 360
    x_threshold = 2.4

    def __init__(self, max_steps=200, seed=None):
        if not isinstance(max_steps, int) or isinstance(max_steps, bool) or max_steps < 1:
            raise ValueError(
                f"CartPole: max_steps 必须是 >=1 的整数，收到 {max_steps!r}")
        self.max_steps = max_steps
        self.rng = random.Random(seed)
        self.state = [0.0, 0.0, 0.0, 0.0]
        self.steps = 0
        self.observation_shape = (4,)
        self.num_actions = 2
        self.reset(seed)

    def reset(self, seed=None):
        """随机初始化到 ±0.05 的小区间内，返回新 state。"""
        if seed is not None:
            self.rng = random.Random(seed)
        self.state = [self.rng.uniform(-0.05, 0.05) for _ in range(4)]
        self.steps = 0
        return list(self.state)

    def step(self, action):
        """返回 ``(state, reward, done, info)``；物理更新照 Gym CartPole 的显式欧拉。"""
        if isinstance(action, bool) or not isinstance(action, int) \
                or not (0 <= action < self.num_actions):
            raise ValueError(
                f"CartPole.step: action 必须是 0 或 1，收到 {action!r}")
        x, x_dot, theta, theta_dot = self.state
        force = self.force_mag if action == 1 else -self.force_mag
        costheta = math.cos(theta)
        sintheta = math.sin(theta)
        temp = (force + self.polemass_length * theta_dot ** 2 * sintheta) / self.total_mass
        thetaacc = (self.gravity * sintheta - costheta * temp) / (
            self.length * (4.0 / 3.0
                           - self.masspole * costheta ** 2 / self.total_mass))
        xacc = temp - self.polemass_length * thetaacc * costheta / self.total_mass
        x = x + self.tau * x_dot
        x_dot = x_dot + self.tau * xacc
        theta = theta + self.tau * theta_dot
        theta_dot = theta_dot + self.tau * thetaacc
        self.state = [x, x_dot, theta, theta_dot]
        self.steps += 1
        failed = (abs(x) > self.x_threshold
                  or abs(theta) > self.theta_threshold)
        if failed:
            return list(self.state), 1.0, True, {"truncated": False, "steps": self.steps}
        if self.steps >= self.max_steps:
            return list(self.state), 1.0, True, {"truncated": True, "steps": self.steps}
        return list(self.state), 1.0, False, {"truncated": False, "steps": self.steps}

    def render(self):
        """极简字符画：杆子倾斜用 ``/`` 或 ``\\`` 表示，小车用 ``[ ]``。"""
        theta = self.state[2]
        if abs(theta) < 0.05:
            pole = "|"
        elif theta > 0:
            pole = "/"
        else:
            pole = "\\"
        pos = int(round((self.state[0] + self.x_threshold) / (2 * self.x_threshold) * 10))
        pos = max(0, min(10, pos))
        line = [" "] * 11
        line[pos] = pole
        return "".join(line) + "\n[ ]".ljust(11)


def discounted_returns(rewards, gamma=0.99):
    """从回报序列算折现回报 ``G_t = r_t + gamma*r_{t+1} + ...``（就地反向累加）。

    >>> discounted_returns([1.0, 1.0, 1.0], 0.5)
    [1.75, 1.5, 1.0]
    """
    if not isinstance(rewards, (list, tuple)) or not rewards:
        raise ValueError("discounted_returns: rewards 必须是非空列表")
    if not isinstance(gamma, (int, float)) or isinstance(gamma, bool) \
            or not (0.0 <= gamma <= 1.0):
        raise ValueError(f"discounted_returns: gamma 必须在 [0,1] 内，收到 {gamma!r}")
    out = [0.0] * len(rewards)
    acc = 0.0
    for t in range(len(rewards) - 1, -1, -1):
        r = rewards[t]
        if isinstance(r, bool) or not isinstance(r, (int, float)):
            raise ValueError(f"discounted_returns: rewards[{t}] 不是数字：{r!r}")
        acc = float(r) + gamma * acc
        out[t] = acc
    return out


def rollout(env, policy, max_steps=None):
    """跑一条轨迹，返回 ``{"states", "actions", "rewards", "dones"}``。

    ``policy`` 是 ``state -> action`` 的可调用对象（随机策略就传 lambda）。
    """
    if not callable(policy):
        raise ValueError("rollout: policy 必须可调用")
    if max_steps is not None:
        if not isinstance(max_steps, int) or isinstance(max_steps, bool) \
                or max_steps < 1:
            raise ValueError(
                f"rollout: max_steps 必须是 >=1 的整数或 None，收到 {max_steps!r}")
    state = env.reset()
    states = [list(state) if isinstance(state, (list, tuple)) else state]
    actions = []
    rewards = []
    dones = []
    limit = max_steps if max_steps is not None else getattr(env, "max_steps", 1000)
    for _ in range(limit):
        action = policy(states[-1])
        state, reward, done, _info = env.step(action)
        actions.append(action)
        rewards.append(reward)
        dones.append(bool(done))
        states.append(list(state) if isinstance(state, (list, tuple)) else state)
        if done:
            break
    return {"states": states, "actions": actions,
            "rewards": rewards, "dones": dones}

# ============================================================================
#  自监督：视觉掩码建模（MAE / SimMIM / BeiT）
# ============================================================================

def patchify(image, patch_size):
    """把 ``(C, H, W)`` 图像切成 ``(H/p)*(W/p)`` 个展平 patch（按行优先）。"""
    if not isinstance(image, (list, tuple)) or not image:
        raise ValueError("patchify: image 必须是非空列表")
    if not isinstance(patch_size, int) or isinstance(patch_size, bool) or patch_size < 1:
        raise ValueError(f"patchify: patch_size 必须是 >=1 的整数，收到 {patch_size!r}")
    rows = []
    for c, chan in enumerate(image):
        if not isinstance(chan, (list, tuple)) or not chan:
            raise ValueError(f"patchify: 第 {c} 个通道必须是非空列表")
        rows.append([list(r) for r in chan])
    channels = len(rows)
    height = len(rows[0])
    width = len(rows[0][0])
    for c in range(channels):
        if len(rows[c]) != height:
            raise ValueError(f"patchify: 第 {c} 个通道行数不一致")
        for r in rows[c]:
            if len(r) != width:
                raise ValueError(f"patchify: 第 {c} 个通道里有宽度不一致的行")
    if height % patch_size != 0 or width % patch_size != 0:
        raise ValueError(
            f"patchify: 高宽 ({height}, {width}) 必须都能被 patch_size={patch_size} 整除"
        )
    gh = height // patch_size
    gw = width // patch_size
    out = []
    for gy in range(gh):
        for gx in range(gw):
            vec = []
            for c in range(channels):
                for dy in range(patch_size):
                    row = rows[c][gy * patch_size + dy]
                    for dx in range(patch_size):
                        vec.append(float(row[gx * patch_size + dx]))
            out.append(vec)
    return out


def unpatchify(patches, channels, height, width, patch_size):
    """``patchify`` 的逆操作：把 patch 列表还原成 ``(C, H, W)`` 图像。"""
    if not isinstance(patches, (list, tuple)) or not patches:
        raise ValueError("unpatchify: patches 必须是非空列表")
    for name, v in (("channels", channels), ("height", height),
                    ("width", width), ("patch_size", patch_size)):
        if not isinstance(v, int) or isinstance(v, bool) or v < 1:
            raise ValueError(f"unpatchify: {name} 必须是 >=1 的整数，收到 {v!r}")
    if height % patch_size != 0 or width % patch_size != 0:
        raise ValueError("unpatchify: 高宽必须都能被 patch_size 整除")
    gh = height // patch_size
    gw = width // patch_size
    if len(patches) != gh * gw:
        raise ValueError(
            f"unpatchify: patch 数 {len(patches)} 与网格 {gh}x{gw} 不一致"
        )
    need = channels * patch_size * patch_size
    for i, p in enumerate(patches):
        if not isinstance(p, (list, tuple)) or len(p) != need:
            raise ValueError(
                f"unpatchify: 第 {i} 个 patch 长度应为 {need}，收到 {len(p) if isinstance(p, (list, tuple)) else type(p).__name__}"
            )
    out = [[[0.0] * width for _ in range(height)] for _ in range(channels)]
    idx = 0
    for gy in range(gh):
        for gx in range(gw):
            vec = patches[idx]
            idx += 1
            k = 0
            for c in range(channels):
                for dy in range(patch_size):
                    for dx in range(patch_size):
                        out[c][gy * patch_size + dy][gx * patch_size + dx] = float(vec[k])
                        k += 1
    return out


def random_masking(num_patches, mask_ratio=0.75, seed=None):
    """MAE 的随机掩码：打乱后保留前 ``ceil(n*(1-ratio))`` 个，返回排好序的下标。

    返回 ``(keep, masked)``：``keep`` 是可见 patch 的原始下标（升序），``masked``
    是要重建的下标（升序）。
    """
    if not isinstance(num_patches, int) or isinstance(num_patches, bool) \
            or num_patches < 1:
        raise ValueError(
            f"random_masking: num_patches 必须是 >=1 的整数，收到 {num_patches!r}"
        )
    if not isinstance(mask_ratio, (int, float)) or not (0.0 <= mask_ratio < 1.0):
        raise ValueError(
            f"random_masking: mask_ratio 必须在 [0, 1) 内，收到 {mask_ratio!r}"
        )
    rng = random.Random(seed)
    order = list(range(num_patches))
    rng.shuffle(order)
    keep_n = int(round(num_patches * (1.0 - mask_ratio)))
    if mask_ratio > 0.0:
        keep_n = max(1, min(num_patches - 1, keep_n)) if num_patches > 1 else 1
    else:
        keep_n = num_patches
    keep = sorted(order[:keep_n])
    masked = sorted(order[keep_n:])
    return keep, masked


def block_mask(height, width, block_h, block_w, num_blocks=4, seed=None):
    """BeiT 风格的块状掩码：在 ``height x width`` 的 patch 网格上放若干个块。

    返回 ``(grid, masked)``：``grid`` 是 0/1 的二维列表（1 = 被遮），``masked`` 是
    被遮位置的展平下标（升序）。
    """
    for name, v in (("height", height), ("width", width), ("block_h", block_h),
                    ("block_w", block_w), ("num_blocks", num_blocks)):
        if not isinstance(v, int) or isinstance(v, bool) or v < 1:
            raise ValueError(f"block_mask: {name} 必须是 >=1 的整数，收到 {v!r}")
    if block_h > height or block_w > width:
        raise ValueError(
            f"block_mask: 块大小 ({block_h}, {block_w}) 超过网格 ({height}, {width})"
        )
    rng = random.Random(seed)
    grid = [[0] * width for _ in range(height)]
    for _ in range(num_blocks):
        y = rng.randrange(height - block_h + 1)
        x = rng.randrange(width - block_w + 1)
        for dy in range(block_h):
            for dx in range(block_w):
                grid[y + dy][x + dx] = 1
    masked = []
    for y in range(height):
        for x in range(width):
            if grid[y][x]:
                masked.append(y * width + x)
    if not masked:
        raise ValueError("block_mask: 一个位置都没遮住")
    return grid, masked


def _mb_check(recon, target, masked, who):
    if not isinstance(recon, (list, tuple)) or not recon:
        raise ValueError(f"{who}: recon 必须是非空列表")
    if not isinstance(target, (list, tuple)) or len(target) != len(recon):
        raise ValueError(f"{who}: recon 与 target 的 patch 数必须一致")
    if not isinstance(masked, (list, tuple)) or not masked:
        raise ValueError(f"{who}: masked 必须是非空下标列表")
    n = len(recon)
    for i, idx in enumerate(masked):
        if isinstance(idx, bool) or not isinstance(idx, int) or not (0 <= idx < n):
            raise ValueError(f"{who}: masked[{i}]={idx!r} 越界（patch 数 {n}）")
    for i in range(n):
        a = recon[i]
        b = target[i]
        if not isinstance(a, (list, tuple)) or not isinstance(b, (list, tuple)) \
                or len(a) != len(b):
            raise ValueError(f"{who}: 第 {i} 个 patch 的 recon/target 形状不一致")
    return n


def mae_loss(recon, target, masked):
    """MAE 的重建损失：只在被遮 patch 上算 MSE，返回 ``(loss, grad_recon)``。"""
    n = _mb_check(recon, target, masked, "mae_loss")
    width = len(recon[0])
    grad = [[0.0] * width for _ in range(n)]
    total = 0.0
    for idx in masked:
        for d in range(width):
            e = float(recon[idx][d]) - float(target[idx][d])
            total += e * e
            grad[idx][d] = 2.0 * e / len(masked)
    return total / len(masked), grad


def simmim_loss(recon, target, masked, beta=1.0):
    """SimMIM 的平滑 L1：``beta`` 内是二次的，外面是线性的。返回 ``(loss, grad)``。"""
    n = _mb_check(recon, target, masked, "simmim_loss")
    if not isinstance(beta, (int, float)) or beta <= 0.0:
        raise ValueError(f"simmim_loss: beta 必须 > 0，收到 {beta!r}")
    width = len(recon[0])
    grad = [[0.0] * width for _ in range(n)]
    total = 0.0
    for idx in masked:
        for d in range(width):
            e = float(recon[idx][d]) - float(target[idx][d])
            if abs(e) < beta:
                total += 0.5 * e * e / beta
                grad[idx][d] = e / beta / len(masked)
            else:
                total += abs(e) - 0.5 * beta
                grad[idx][d] = (1.0 if e > 0 else -1.0) / len(masked)
    return total / len(masked), grad


def beit_loss(logits, targets, masked):
    """BeiT 的掩码 patch 分类损失（交叉熵），返回 ``(loss, grad_logits)``。"""
    if not isinstance(logits, (list, tuple)) or not logits:
        raise ValueError("beit_loss: logits 必须是非空列表")
    n = len(logits)
    if not isinstance(targets, (list, tuple)) or len(targets) != n:
        raise ValueError("beit_loss: targets 长度必须等于 patch 数")
    if not isinstance(masked, (list, tuple)) or not masked:
        raise ValueError("beit_loss: masked 必须是非空下标列表")
    for i, idx in enumerate(masked):
        if isinstance(idx, bool) or not isinstance(idx, int) or not (0 <= idx < n):
            raise ValueError(f"beit_loss: masked[{i}]={idx!r} 越界（patch 数 {n}）")
    for i, idx in enumerate(masked):
        t = targets[idx]
        if isinstance(t, bool) or not isinstance(t, int) or t < 0:
            raise ValueError(f"beit_loss: targets[{idx}] 必须是非负整数，收到 {t!r}")
        if t >= len(logits[idx]):
            raise ValueError(f"beit_loss: targets[{idx}]={t} 超出类别数 {len(logits[idx])}")
    grad = [[0.0] * len(row) for row in logits]
    total = 0.0
    inv = 1.0 / len(masked)
    for idx in masked:
        row = [float(v) for v in logits[idx]]
        mx = max(row)
        exps = [math.exp(v - mx) for v in row]
        s = sum(exps)
        probs = [v / s for v in exps]
        total += -(row[targets[idx]] - mx - math.log(s))
        for j in range(len(row)):
            grad[idx][j] = (probs[j] - (1.0 if j == targets[idx] else 0.0)) * inv
    return total / len(masked), grad

# ============================================================================
#  自监督：对比学习（SimCLR / MoCo / BYOL / BarlowTwins / VICReg / SwAV / DINO）
# ============================================================================

def _ct_rows(z, who):
    if not isinstance(z, (list, tuple)) or not z:
        raise ValueError(f"{who}: 嵌入必须是非空的行列表")
    out = []
    for i, row in enumerate(z):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"{who}: 第 {i} 行必须是非空列表")
        vals = []
        for v in row:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f"{who}: 第 {i} 行里必须全是数字，收到 {v!r}")
            if v != v or v in (float("inf"), float("-inf")):
                raise ValueError(f"{who}: 第 {i} 行里有非有限值")
            vals.append(float(v))
        out.append(vals)
    width = len(out[0])
    for i, row in enumerate(out):
        if len(row) != width:
            raise ValueError(f"{who}: 第 {i} 行宽度 {len(row)} 与 {width} 不一致")
    return out


def _ct_norm(row):
    return math.sqrt(sum(v * v for v in row))


def _ct_unit(z, who):
    out = []
    for i, row in enumerate(z):
        n = _ct_norm(row)
        if n <= 0.0:
            raise ValueError(f"{who}: 第 {i} 行是零向量，无法归一化")
        out.append([v / n for v in row])
    return out


def _ct_dot(a, b):
    return sum(x * y for x, y in zip(a, b))


def nt_xent_loss(z1, z2, temperature=0.5):
    """SimCLR 的 NT-Xent：两路增强的嵌入互相为正样本。

    返回 ``(loss, grad_z1, grad_z2)``，梯度是**对嵌入**的解析梯度（编码器
    自己的反向传播不在本函数范围内）。
    """
    a = _ct_rows(z1, "nt_xent_loss")
    b = _ct_rows(z2, "nt_xent_loss")
    if len(a) != len(b):
        raise ValueError(f"nt_xent_loss: 两路样本数不一致（{len(a)} vs {len(b)}）")
    if not isinstance(temperature, (int, float)) or temperature <= 0.0:
        raise ValueError(f"nt_xent_loss: temperature 必须 > 0，收到 {temperature!r}")
    n = len(a)
    if len(a[0]) != len(b[0]):
        raise ValueError("nt_xent_loss: 两路嵌入维度不一致")
    ua = _ct_unit(a, "nt_xent_loss")
    ub = _ct_unit(b, "nt_xent_loss")
    feat = ua + ub                                   # 2n x d，按行归一化
    m = 2 * n
    sims = [[_ct_dot(feat[i], feat[j]) / temperature for j in range(m)]
            for i in range(m)]
    total = 0.0
    dsim = [[0.0] * m for _ in range(m)]
    for i in range(m):
        # 正样本：i < n 时是 i+n，否则是 i-n
        pos = i + n if i < n else i - n
        row = sims[i]
        mx = max(row[k] for k in range(m) if k != i)
        exps = [0.0] * m
        s = 0.0
        for k in range(m):
            if k == i:
                continue
            exps[k] = math.exp(row[k] - mx)
            s += exps[k]
        total += -(row[pos] - mx - math.log(s))
        for k in range(m):
            if k == i:
                continue
            p = exps[k] / s
            dsim[i][k] += p
        dsim[i][pos] -= 1.0
    scale = 1.0 / (m * temperature)
    for i in range(m):
        for k in range(m):
            if k != i:
                dsim[i][k] *= scale
    g = [[0.0] * len(feat[0]) for _ in range(m)]
    for i in range(m):
        for k in range(m):
            if k == i or dsim[i][k] == 0.0:
                continue
            w = dsim[i][k]
            for d in range(len(feat[0])):
                g[i][d] += w * feat[k][d]
                g[k][d] += w * feat[i][d]
    gz = [[0.0] * len(feat[0]) for _ in range(m)]
    for i in range(m):
        row = a[i] if i < n else b[i - n]
        nz = _ct_norm(row)
        proj = _ct_dot(g[i], feat[i])
        gz[i] = [(g[i][d] - proj * feat[i][d]) / nz for d in range(len(row))]
    return total / m, gz[:n], gz[n:]


class MoCoQueue:
    """MoCo 的动量队列：存历史 key 向量，先进先出。"""

    def __init__(self, dim, size=1024, seed=None):
        if not isinstance(dim, int) or isinstance(dim, bool) or dim < 1:
            raise ValueError(f"MoCoQueue: dim 必须是 >=1 的整数，收到 {dim!r}")
        if not isinstance(size, int) or isinstance(size, bool) or size < 1:
            raise ValueError(f"MoCoQueue: size 必须是 >=1 的整数，收到 {size!r}")
        self.dim = dim
        self.size = size
        self.keys = []
        self.ptr = 0
        self.rng = random.Random(seed)

    def __len__(self):
        return len(self.keys)

    def enqueue(self, keys):
        rows = _ct_rows(keys, "MoCoQueue.enqueue")
        for row in rows:
            if len(row) != self.dim:
                raise ValueError(
                    f"MoCoQueue.enqueue: 维度 {len(row)} 与 {self.dim} 不一致"
                )
            if len(self.keys) < self.size:
                self.keys.append(row)
            else:
                self.keys[self.ptr] = row
                self.ptr = (self.ptr + 1) % self.size
        return self

    def matrix(self):
        return [list(r) for r in self.keys]


def moco_loss(q, k, queue=None, temperature=0.07):
    """MoCo 对比损失：每个 ``q[i]`` 的正样本是 ``k[i]``，负样本是其余 ``k`` 与队列。

    返回 ``(loss, grad_q, grad_k)``（队列视为常数，不产生梯度）。
    """
    qa = _ct_rows(q, "moco_loss")
    ka = _ct_rows(k, "moco_loss")
    if len(qa) != len(ka):
        raise ValueError(f"moco_loss: q 与 k 的样本数不一致（{len(qa)} vs {len(ka)}）")
    if len(qa[0]) != len(ka[0]):
        raise ValueError("moco_loss: q 与 k 的维度不一致")
    if not isinstance(temperature, (int, float)) or temperature <= 0.0:
        raise ValueError(f"moco_loss: temperature 必须 > 0，收到 {temperature!r}")
    qu = _ct_unit(qa, "moco_loss")
    ku = _ct_unit(ka, "moco_loss")
    keys = ku
    if queue is not None:
        qd = _ct_rows(queue, "moco_loss")
        for i, row in enumerate(qd):
            if len(row) != len(ka[0]):
                raise ValueError(f"moco_loss: 队列第 {i} 行维度不一致")
        keys = ku + _ct_unit(qd, "moco_loss")
    n = len(qu)
    m = len(keys)
    if m < 2:
        raise ValueError("moco_loss: 至少需要 2 个 key（1 正 + 1 负）")
    logits = [[_ct_dot(qu[i], keys[j]) / temperature for j in range(m)]
              for i in range(n)]
    total = 0.0
    dlog = [[0.0] * m for _ in range(n)]
    for i in range(n):
        row = logits[i]
        mx = max(row)
        exps = [math.exp(v - mx) for v in row]
        s = sum(exps)
        total += -(row[i] - mx - math.log(s))
        for j in range(m):
            dlog[i][j] = exps[j] / s
        dlog[i][i] -= 1.0
    gq = [[0.0] * len(qu[0]) for _ in range(n)]
    gk = [[0.0] * len(ku[0]) for _ in range(len(ku))]
    inv = 1.0 / (temperature * n)
    for i in range(n):
        for j in range(m):
            w = dlog[i][j] * inv
            if w == 0.0:
                continue
            for d in range(len(qu[0])):
                gq[i][d] += w * keys[j][d]
                if j < len(ku):
                    gk[j][d] += w * qu[i][d]
    nq = [_ct_norm(r) for r in qa]
    nk = [_ct_norm(r) for r in ka]
    gq2 = [[(gq[i][d] - _ct_dot(gq[i], qu[i]) * qu[i][d]) / nq[i]
            for d in range(len(qu[0]))] for i in range(n)]
    gk2 = [[(gk[j][d] - _ct_dot(gk[j], ku[j]) * ku[j][d]) / nk[j]
            for d in range(len(ku[0]))] for j in range(len(ku))]
    return total / n, gq2, gk2


def byol_loss(pred, target):
    """BYOL 的负余弦相似损失 ``mean(2 - 2*cos)``。

    目标是 stop-gradient 分支，所以只返回对 ``pred`` 的梯度：``(loss, grad_pred)``。
    """
    p = _ct_rows(pred, "byol_loss")
    t = _ct_rows(target, "byol_loss")
    if len(p) != len(t):
        raise ValueError(f"byol_loss: 样本数不一致（{len(p)} vs {len(t)}）")
    if len(p[0]) != len(t[0]):
        raise ValueError("byol_loss: 维度不一致")
    pu = _ct_unit(p, "byol_loss")
    tu = _ct_unit(t, "byol_loss")
    total = 0.0
    g = []
    n = len(p)
    for i in range(n):
        cos = _ct_dot(pu[i], tu[i])
        total += 2.0 - 2.0 * cos
        np_ = _ct_norm(p[i])
        proj = -2.0 * _ct_dot(tu[i], pu[i])
        row = [(-2.0 * tu[i][d] - proj * pu[i][d]) / (np_ * n)
               for d in range(len(p[i]))]
        g.append(row)
    return total / n, g


def barlow_twins_loss(z1, z2, lambda_=0.005):
    """Barlow Twins：让互相关矩阵接近单位阵（对角 + 非对角两个惩罚项）。

    只返回损失值——批次标准化让梯度推导容易出错，本库不给出未经核对的梯度。
    """
    a = _ct_rows(z1, "barlow_twins_loss")
    b = _ct_rows(z2, "barlow_twins_loss")
    if len(a) != len(b) or len(a[0]) != len(b[0]):
        raise ValueError("barlow_twins_loss: 两路的样本数或维度不一致")
    if not isinstance(lambda_, (int, float)) or lambda_ < 0.0:
        raise ValueError(f"barlow_twins_loss: lambda_ 必须 >= 0，收到 {lambda_!r}")
    n = len(a)
    d = len(a[0])
    ma = [sum(r[j] for r in a) / n for j in range(d)]
    mb = [sum(r[j] for r in b) / n for j in range(d)]
    sa = [0.0] * d
    sb = [0.0] * d
    for i in range(n):
        for j in range(d):
            sa[j] += (a[i][j] - ma[j]) ** 2
            sb[j] += (b[i][j] - mb[j]) ** 2
    sa = [math.sqrt(v / max(1, n - 1)) for v in sa]
    sb = [math.sqrt(v / max(1, n - 1)) for v in sb]
    total = 0.0
    for i in range(d):
        for j in range(d):
            c = 0.0
            for k in range(n):
                c += ((a[k][i] - ma[i]) / (sa[i] if sa[i] > 0 else 1.0)) * \
                     ((b[k][j] - mb[j]) / (sb[j] if sb[j] > 0 else 1.0))
            c /= n
            if i == j:
                total += (1.0 - c) ** 2
            else:
                total += lambda_ * c * c
    return total


def vicreg_loss(z1, z2, sim_weight=25.0, var_weight=25.0, cov_weight=1.0, eps=1e-4):
    """VICReg：不变项（MSE）+ 方差 hinge + 协方差非对角项。只返回损失值。"""
    a = _ct_rows(z1, "vicreg_loss")
    b = _ct_rows(z2, "vicreg_loss")
    if len(a) != len(b) or len(a[0]) != len(b[0]):
        raise ValueError("vicreg_loss: 两路的样本数或维度不一致")
    for name, w in (("sim_weight", sim_weight), ("var_weight", var_weight),
                    ("cov_weight", cov_weight)):
        if not isinstance(w, (int, float)) or w < 0.0:
            raise ValueError(f"vicreg_loss: {name} 必须 >= 0")
    n = len(a)
    d = len(a[0])
    inv = 0.0
    for i in range(n):
        for j in range(d):
            inv += (a[i][j] - b[i][j]) ** 2
    inv /= n
    var = 0.0
    cov = 0.0
    for branch in (a, b):
        mean = [sum(r[j] for r in branch) / n for j in range(d)]
        sd = [0.0] * d
        for i in range(n):
            for j in range(d):
                sd[j] += (branch[i][j] - mean[j]) ** 2
        sd = [v / n for v in sd]
        for j in range(d):
            var += max(0.0, eps - sd[j])
        for i in range(d):
            for j in range(i + 1, d):
                c = 0.0
                for k in range(n):
                    c += (branch[k][i] - mean[i]) * (branch[k][j] - mean[j])
                cov += (c / n) ** 2
    return sim_weight * inv + var_weight * var + cov_weight * cov


def sinkhorn(logits, epsilon=0.05, n_iters=3):
    """SwAV 用的 Sinkhorn-Knopp 归一化：交替把行和归一化到 `1/N`、列和到 `1/K`。

    交替归一化只能让两个约束同时近似成立（最后一步是列归一化，所以列和精确、
    行和近似）；`n_iters` 越大越接近双随机。
    """
    a = _ct_rows(logits, "sinkhorn")
    if not isinstance(n_iters, int) or isinstance(n_iters, bool) or n_iters < 1:
        raise ValueError(f"sinkhorn: n_iters 必须是 >=1 的整数，收到 {n_iters!r}")
    if not isinstance(epsilon, (int, float)) or epsilon <= 0.0:
        raise ValueError(f"sinkhorn: epsilon 必须 > 0，收到 {epsilon!r}")
    n = len(a)
    k = len(a[0])
    q = [[math.exp(a[i][j] / epsilon) for j in range(k)] for i in range(n)]
    for _ in range(n_iters):
        for i in range(n):
            s = sum(q[i])
            q[i] = [v / (s * n) for v in q[i]]          # 行和 = 1/n
        for j in range(k):
            s = sum(q[i][j] for i in range(n))
            for i in range(n):
                q[i][j] = q[i][j] / (s * k)             # 列和 = 1/k
    return q


def swav_loss(out1, out2, prototypes, temperature=0.1, epsilon=0.05, n_iters=3):
    """SwAV：一路的分配当另一路的软标签（交叉熵）。只返回损失值。"""
    a = _ct_rows(out1, "swav_loss")
    b = _ct_rows(out2, "swav_loss")
    p = _ct_rows(prototypes, "swav_loss")
    if len(a) != len(b):
        raise ValueError("swav_loss: 两路样本数不一致")
    if len(a[0]) != len(p[0]):
        raise ValueError("swav_loss: 嵌入维度与原型维度不一致")
    if not isinstance(temperature, (int, float)) or temperature <= 0.0:
        raise ValueError("swav_loss: temperature 必须 > 0")
    def scores(out):
        return [[_ct_dot(row, proto) / temperature for proto in p] for row in out]
    q1 = sinkhorn(scores(a), epsilon=epsilon, n_iters=n_iters)
    q2 = sinkhorn(scores(b), epsilon=epsilon, n_iters=n_iters)
    def cross(out_scores, q):
        total = 0.0
        for i, row in enumerate(out_scores):
            mx = max(row)
            exps = [math.exp(v - mx) for v in row]
            s = sum(exps)
            for j in range(len(row)):
                if q[i][j] > 0.0:
                    total += -q[i][j] * (row[j] - mx - math.log(s))
        return total / len(out_scores)
    return 0.5 * (cross(scores(b), q1) + cross(scores(a), q2))


def dino_loss(student_logits, teacher_logits, center, teacher_temp=0.04,
             student_temp=0.1):
    """DINO：教师分布去中心化后做软目标交叉熵。只返回损失值。"""
    s = _ct_rows(student_logits, "dino_loss")
    t = _ct_rows(teacher_logits, "dino_loss")
    if len(s) != len(t) or len(s[0]) != len(t[0]):
        raise ValueError("dino_loss: 学生与教师的形状必须一致")
    if not isinstance(center, (list, tuple)) or len(center) != len(s[0]):
        raise ValueError("dino_loss: center 长度必须等于类别数")
    for temp, name in ((teacher_temp, "teacher_temp"), (student_temp, "student_temp")):
        if not isinstance(temp, (int, float)) or temp <= 0.0:
            raise ValueError(f"dino_loss: {name} 必须 > 0")
    total = 0.0
    for i in range(len(s)):
        st = [v / student_temp for v in s[i]]
        mx = max(st)
        e = [math.exp(v - mx) for v in st]
        z = sum(e)
        lp = [v - mx - math.log(z) for v in st]
        tt = [(t[i][j] - center[j]) / teacher_temp for j in range(len(t[i]))]
        mt = max(tt)
        et = [math.exp(v - mt) for v in tt]
        zt = sum(et)
        for j in range(len(s[i])):
            p = et[j] / zt
            if p > 0.0:
                total += -p * lp[j]
    return total / len(s)


def update_dino_center(center, teacher_logits, momentum=0.9):
    """DINO 的中心 EMA：``center = m*center + (1-m)*mean(teacher_logits)``（返回新列表）。"""
    t = _ct_rows(teacher_logits, "update_dino_center")
    if not isinstance(center, (list, tuple)) or len(center) != len(t[0]):
        raise ValueError("update_dino_center: center 长度必须等于类别数")
    if not isinstance(momentum, (int, float)) or not (0.0 <= momentum <= 1.0):
        raise ValueError(
            f"update_dino_center: momentum 必须在 [0,1]，收到 {momentum!r}"
        )
    mean = [sum(r[j] for r in t) / len(t) for j in range(len(t[0]))]
    return [momentum * float(center[j]) + (1.0 - momentum) * mean[j]
            for j in range(len(mean))]

# ============================================================================
#  推理与部署：批内打包与投机解码
# ============================================================================

def pack_decode_batch(sequences, pad_id=0):
    """把多条待解码序列打包成一次前向需要的张量。

    返回 ``{"tokens", "segment_ids", "attention_mask", "lengths"}``：
    ``tokens`` 是 ``sequence_packing`` 的拼接结果，``segment_ids`` 标出每个位置
    属于哪条序列，``attention_mask`` 是 ``packed_causal_mask`` 的段内因果掩码
    （不同序列互相看不见）。``lengths`` 保留原始长度，便于拆分输出。
    """
    if not isinstance(sequences, (list, tuple)) or not sequences:
        raise ValueError("pack_decode_batch: sequences 必须是非空列表")
    lengths = []
    for i, seq in enumerate(sequences):
        if not isinstance(seq, (list, tuple)) or not seq:
            raise ValueError(f"pack_decode_batch: 第 {i} 条序列必须是非空列表")
        lengths.append(len(seq))
    packed = sequence_packing([list(s) for s in sequences], pad_id=pad_id)
    segment_ids = packed["segment_ids"]
    return {
        "tokens": packed["tokens"],
        "segment_ids": segment_ids,
        "position_ids": packed["position_ids"],
        "attention_mask": packed_causal_mask(segment_ids, causal=True),
        "lengths": lengths,
    }


def _w15d_next_probs(model, ids):
    """取「给定 ids 之后」下一个 token 的概率分布。"""
    logits = model.forward(list(ids))
    if isinstance(logits, (list, tuple)) and logits and \
            isinstance(logits[0], (list, tuple)):
        row = logits[-1]
    else:
        row = logits
    vals = []
    for v in row:
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError("_w15d_next_probs: 模型输出必须是数字")
        vals.append(float(v))
    return _softmax_row(vals)


def speculative_generate(draft, target, prompt_ids, max_new_tokens=16, gamma=4,
                         seed=None):
    """投机解码：草稿模型连出 ``gamma`` 个 token，目标模型一次验证。

    每一轮先用 ``draft`` 贪心/采样出至多 ``gamma`` 个候选 token，再逐个位置算
    两个模型的分布，交给 ``speculative_accept`` 做拒绝采样：接受前 ``k`` 个，
    第一个被拒的位置用残差分布 ``max(0, p_target - p_draft)`` 重采样。

    返回 ``(ids, stats)``，``stats`` 里有 ``"rounds"``（轮数）、``"proposed"``
    （草稿提出的 token 数）、``"accepted"``（被接受的 token 数），用于算接受率。
    只在 ``temperature=1.0`` 下保证分布等价，所以不给温度参数。
    """
    if not hasattr(draft, "generate") or not hasattr(target, "forward"):
        raise ValueError("speculative_generate: draft 需要 generate，target 需要 forward")
    if not isinstance(prompt_ids, (list, tuple)) or not prompt_ids:
        raise ValueError("speculative_generate: prompt_ids 必须是非空列表")
    if not isinstance(max_new_tokens, int) or isinstance(max_new_tokens, bool) \
            or max_new_tokens < 1:
        raise ValueError(
            f"speculative_generate: max_new_tokens 必须是 >=1 的整数，收到 {max_new_tokens!r}"
        )
    if not isinstance(gamma, int) or isinstance(gamma, bool) or gamma < 1:
        raise ValueError(f"speculative_generate: gamma 必须是 >=1 的整数，收到 {gamma!r}")
    rng = random.Random(seed)
    ids = [int(t) for t in prompt_ids]
    produced = 0
    rounds = 0
    proposed = 0
    accepted_total = 0
    while produced < max_new_tokens:
        want = min(gamma, max_new_tokens - produced)
        out = draft.generate(ids, max_new_tokens=want, temperature=1.0, rng=rng)
        drafted = [int(t) for t in out[len(ids):]]
        if not drafted:
            break
        rounds += 1
        proposed += len(drafted)
        draft_probs = []
        target_probs = []
        for k in range(len(drafted)):
            prefix = ids + drafted[:k]
            draft_probs.append(_w15d_next_probs(draft, prefix))
            target_probs.append(_w15d_next_probs(target, prefix))
        n_ok, resid = speculative_accept(drafted, draft_probs, target_probs, rng=rng)
        ids.extend(drafted[:n_ok])
        accepted_total += n_ok
        produced += n_ok
        if resid is not None and produced < max_new_tokens:
            ids.append(int(resid))
            produced += 1
    stats = {"rounds": rounds, "proposed": proposed, "accepted": accepted_total}
    stats["accept_rate"] = (accepted_total / proposed) if proposed else 0.0
    return ids, stats

# ============================================================================
#  推理与部署：集成学习（Voting / Bagging / Stacking / AdaBoost）
# ============================================================================

def _w15c_models(models, who):
    if not isinstance(models, (list, tuple)) or not models:
        raise ValueError(f"{who}: models 必须是非空列表")
    for i, m in enumerate(models):
        if not hasattr(m, "forward"):
            raise ValueError(f"{who}: 第 {i} 个模型没有 forward 方法")
    return list(models)


def _w15c_scores(model, x):
    out = model.forward(list(x))
    if not isinstance(out, (list, tuple)) or not out:
        raise ValueError(
            f"_w15c_scores: 模型输出必须是长度 > 0 的列表，收到 {type(out).__name__}"
        )
    vals = []
    for v in out:
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError(f"_w15c_scores: 输出里必须全是数字，收到 {v!r}")
        vals.append(float(v))
    return vals


def _w15c_argmax(values):
    best = 0
    for i in range(1, len(values)):
        if values[i] > values[best]:
            best = i
    return best


def _w15c_proba(model, x):
    """把模型输出当 logits 走 softmax 变成概率。"""
    return _softmax_row(_w15c_scores(model, x))


class VotingEnsemble:
    """投票集成：``voting='soft'`` 平均概率，``'hard'`` 取多数票。

    ``models`` 里每个模型只需有 ``forward(x) -> list[float]``；输出按类别
    顺序对齐，类别数不一致会报错。
    """

    def __init__(self, models, voting="soft"):
        self.models = _w15c_models(models, "VotingEnsemble")
        if voting not in ("soft", "hard"):
            raise ValueError(f"VotingEnsemble: voting 只能是 soft/hard，收到 {voting!r}")
        self.voting = voting

    def predict_proba(self, x):
        probs = [_w15c_proba(m, x) for m in self.models]
        width = len(probs[0])
        for i, p in enumerate(probs):
            if len(p) != width:
                raise ValueError(
                    f"VotingEnsemble: 第 {i} 个模型的类别数 {len(p)} 与 {width} 不一致"
                )
        if self.voting == "soft":
            out = [0.0] * width
            for p in probs:
                for c in range(width):
                    out[c] += p[c]
            return [v / len(probs) for v in out]
        votes = [0.0] * width
        for p in probs:
            votes[_w15c_argmax(p)] += 1.0
        total = float(len(probs))
        return [v / total for v in votes]

    def predict(self, x):
        return _w15c_argmax(self.predict_proba(x))

    def forward(self, x):
        return self.predict_proba(x)


class BaggingEnsemble:
    """Bagging：对训练集做有放回重采样，训练多个同构模型后平均概率。

    ``estimator_factory`` 是无参可调用对象，每次调用返回一个**未训练**的模型
    （需要自带 ``fit(xs, ys, ...)``，例如 ``Model``）。
    """

    def __init__(self, estimator_factory, n_estimators=5, sample_ratio=1.0, seed=None):
        if not callable(estimator_factory):
            raise ValueError("BaggingEnsemble: estimator_factory 必须可调用")
        if not isinstance(n_estimators, int) or isinstance(n_estimators, bool) \
                or n_estimators < 1:
            raise ValueError(
                f"BaggingEnsemble: n_estimators 必须是 >=1 的整数，收到 {n_estimators!r}"
            )
        if not isinstance(sample_ratio, (int, float)) or not (0.0 < sample_ratio <= 1.0):
            raise ValueError(
                f"BaggingEnsemble: sample_ratio 必须在 (0, 1] 内，收到 {sample_ratio!r}"
            )
        self.factory = estimator_factory
        self.n_estimators = n_estimators
        self.sample_ratio = float(sample_ratio)
        self.seed = seed
        self.models = []

    def fit(self, xs, ys, **kwargs):
        if not isinstance(xs, (list, tuple)) or not xs:
            raise ValueError("BaggingEnsemble.fit: xs 不能为空")
        if len(xs) != len(ys):
            raise ValueError(
                f"BaggingEnsemble.fit: xs 有 {len(xs)} 行，ys 有 {len(ys)} 个"
            )
        rng = random.Random(self.seed)
        count = max(1, int(round(len(xs) * self.sample_ratio)))
        self.models = []
        for _ in range(self.n_estimators):
            picked = [rng.randrange(len(xs)) for _ in range(count)]
            sub_x = [xs[i] for i in picked]
            sub_y = [ys[i] for i in picked]
            model = self.factory()
            if not hasattr(model, "fit"):
                raise ValueError("BaggingEnsemble.fit: 子模型必须自带 fit 方法")
            model.fit(sub_x, sub_y, **kwargs)
            self.models.append(model)
        return self

    def _check_fitted(self):
        if not self.models:
            raise ValueError("BaggingEnsemble: 还没有 fit")

    def predict_proba(self, x):
        self._check_fitted()
        probs = [_w15c_proba(m, x) for m in self.models]
        width = len(probs[0])
        out = [0.0] * width
        for p in probs:
            if len(p) != width:
                raise ValueError("BaggingEnsemble: 子模型类别数不一致")
            for c in range(width):
                out[c] += p[c]
        return [v / len(probs) for v in out]

    def predict(self, x):
        return _w15c_argmax(self.predict_proba(x))

    def forward(self, x):
        return self.predict_proba(x)


def stack_features(models, xs):
    """把每个基模型的概率拼成元特征：返回 ``len(xs)`` 行、``n_models*n_classes`` 列。"""
    models = _w15c_models(models, "stack_features")
    if not isinstance(xs, (list, tuple)) or not xs:
        raise ValueError("stack_features: xs 不能为空")
    out = []
    for x in xs:
        row = []
        for m in models:
            row.extend(_w15c_proba(m, x))
        out.append(row)
    return out


class StackingEnsemble:
    """Stacking：用基模型的输出概率作为元特征，再训一个元模型。

    基模型必须**已经训练好**且与元训练数据尽量不相交（本库没有 clone 机制，
    所以不做自动 OOF 切分，文档已写明）。
    """

    def __init__(self, base_models, meta_model, meta_epochs=300, meta_lr=0.05,
                 seed=None):
        self.base_models = _w15c_models(base_models, "StackingEnsemble")
        if not hasattr(meta_model, "fit"):
            raise ValueError("StackingEnsemble: meta_model 必须自带 fit 方法")
        if not isinstance(meta_epochs, int) or isinstance(meta_epochs, bool) \
                or meta_epochs < 1:
            raise ValueError(
                f"StackingEnsemble: meta_epochs 必须是 >=1 的整数，收到 {meta_epochs!r}"
            )
        self.meta_model = meta_model
        self.meta_epochs = meta_epochs
        self.meta_lr = meta_lr
        self.seed = seed

    def fit(self, xs, ys):
        feats = stack_features(self.base_models, xs)
        opt = getattr(self.meta_model, "optimizer", None)
        if self.meta_lr is not None and opt is not None and hasattr(opt, "lr"):
            opt.lr = float(self.meta_lr)
        self.meta_model.fit(feats, ys, epochs=self.meta_epochs)
        return self

    def predict_proba(self, x):
        feats = stack_features(self.base_models, [x])
        return _w15c_proba(self.meta_model, feats[0])

    def predict(self, x):
        return _w15c_argmax(self.predict_proba(x))

    def forward(self, x):
        return self.predict_proba(x)


class AdaBoostStumps:
    """二分类 AdaBoost（决策树桩）：每一轮在单特征阈值上找加权误差最小的桩。

    标签必须是 0/1（内部映射成 -1/+1）。``predict_proba`` 返回
    ``[P(y=0), P(y=1)]``，由 ``sigmoid(2 * margin)`` 得到。
    """

    def __init__(self, n_estimators=10, learning_rate=1.0):
        if not isinstance(n_estimators, int) or isinstance(n_estimators, bool) \
                or n_estimators < 1:
            raise ValueError(
                f"AdaBoostStumps: n_estimators 必须是 >=1 的整数，收到 {n_estimators!r}"
            )
        if not isinstance(learning_rate, (int, float)) or learning_rate <= 0.0:
            raise ValueError(
                f"AdaBoostStumps: learning_rate 必须 > 0，收到 {learning_rate!r}"
            )
        self.n_estimators = n_estimators
        self.learning_rate = float(learning_rate)
        self.stumps = []
        self.alphas = []

    def _stump(self, xs, ys01, weights):
        width = len(xs[0])
        best = None
        for j in range(width):
            values = sorted(set(xs[i][j] for i in range(len(xs))))
            if len(values) < 2:
                continue
            thresholds = [(values[k] + values[k + 1]) / 2.0
                          for k in range(len(values) - 1)]
            for thr in thresholds:
                for polarity in (1.0, -1.0):
                    err = 0.0
                    for i in range(len(xs)):
                        pred = 1.0 if (xs[i][j] - thr) * polarity >= 0.0 else -1.0
                        if pred != ys01[i]:
                            err += weights[i]
                    if best is None or err < best[0]:
                        best = (err, j, thr, polarity)
        if best is None:
            raise ValueError("AdaBoostStumps: 没有可用的特征阈值（特征全为常数）")
        return best

    def fit(self, xs, ys):
        if not isinstance(xs, (list, tuple)) or not xs:
            raise ValueError("AdaBoostStumps.fit: xs 不能为空")
        if len(xs) != len(ys):
            raise ValueError(
                f"AdaBoostStumps.fit: xs 有 {len(xs)} 行，ys 有 {len(ys)} 个"
            )
        for v in ys:
            if v not in (0, 1, 0.0, 1.0):
                raise ValueError(f"AdaBoostStumps.fit: 只支持二分类标签 0/1，收到 {v!r}")
        signed = [1.0 if int(v) == 1 else -1.0 for v in ys]
        n = len(xs)
        weights = [1.0 / n] * n
        self.stumps = []
        self.alphas = []
        for _ in range(self.n_estimators):
            err, j, thr, polarity = self._stump(xs, signed, weights)
            err = min(max(err, 1e-12), 1.0 - 1e-12)
            alpha = self.learning_rate * 0.5 * math.log((1.0 - err) / err)
            self.stumps.append((j, thr, polarity))
            self.alphas.append(alpha)
            for i in range(n):
                pred = 1.0 if (xs[i][j] - thr) * polarity >= 0.0 else -1.0
                weights[i] *= math.exp(-alpha * signed[i] * pred)
            total = sum(weights)
            weights = [w / total for w in weights]
        return self

    def decision_function(self, x):
        if not self.stumps:
            raise ValueError("AdaBoostStumps: 还没有 fit")
        total = 0.0
        for (j, thr, polarity), alpha in zip(self.stumps, self.alphas):
            pred = 1.0 if (float(x[j]) - thr) * polarity >= 0.0 else -1.0
            total += alpha * pred
        return total

    def predict_proba(self, x):
        margin = self.decision_function(x)
        p1 = 1.0 / (1.0 + math.exp(-2.0 * margin))
        return [1.0 - p1, p1]

    def predict(self, x):
        return 1 if self.decision_function(x) > 0.0 else 0

    def forward(self, x):
        return self.predict_proba(x)

# ============================================================================
#  推理与部署：量化（PTQ / QAT / SmoothQuant）
# ============================================================================

def _w15_flat_numbers(value, who="_w15_flat_numbers"):
    """把嵌套结构摊平成一维（只读，返回浮点列表）。"""
    out = []
    stack = [value]
    while stack:
        item = stack.pop()
        if isinstance(item, (list, tuple)):
            for v in reversed(item):
                stack.append(v)
        else:
            if isinstance(item, bool) or not isinstance(item, (int, float)):
                raise ValueError(f"{who}: 需要数字，收到 {item!r}")
            out.append(float(item))
    return out


def _w15_map(value, fn):
    """对嵌套结构逐元素套用 fn，保持结构。"""
    if isinstance(value, (list, tuple)):
        return [_w15_map(v, fn) for v in value]
    return fn(float(value))


def _w15_check_bits(bits, who):
    if not isinstance(bits, int) or isinstance(bits, bool) or not (2 <= bits <= 16):
        raise ValueError(f"{who}: bits 必须是 2..16 的整数，收到 {bits!r}")
    return bits


def _w15_scale_of(value, bits, who):
    flat = _w15_flat_numbers(value, who)
    if not flat:
        raise ValueError(f"{who}: 空结构没有可量化的元素")
    qmax = float((1 << (bits - 1)) - 1)
    peak = max(abs(v) for v in flat)
    if peak <= 0.0:
        return 1.0, qmax
    return peak / qmax, qmax


def fake_quantize(value, bits=8, scale=None):
    """对称均匀量化的「伪量化」：量化后再反量化，返回同结构浮点。

    这是 QAT / PTQ 误差分析的通用工具：数值落在 ``scale * [-qmax, qmax]``
    的整数格点上，形状不变，可直接继续前向。
    """
    _w15_check_bits(bits, "fake_quantize")
    if scale is None:
        scale, qmax = _w15_scale_of(value, bits, "fake_quantize")
    else:
        if isinstance(scale, bool) or not isinstance(scale, (int, float)):
            raise ValueError(f"fake_quantize: scale 必须是数字，收到 {scale!r}")
        if scale <= 0.0:
            raise ValueError(f"fake_quantize: scale 必须 > 0，收到 {scale!r}")
        qmax = float((1 << (bits - 1)) - 1)

    def _one(v):
        q = int(round(v / scale))
        if q > qmax:
            q = int(qmax)
        elif q < -qmax:
            q = -int(qmax)
        return q * scale

    return _w15_map(value, _one)


def quantize_weights(model, bits=8):
    """训练后量化（PTQ）：把每层权重对称量化，写回反量化值并返回编码。

    返回 ``{"bits", "scales", "codes"}``：``codes`` 是每层权重的整型编码
    （真正的 int8 存储），``scales`` 是每层一个缩放因子。注意写回模型的是
    反量化后的浮点，前向不需要额外解包。
    """
    _w15_check_bits(bits, "quantize_weights")
    net = getattr(model, "model", model)
    mods = getattr(net, "layers", None) or getattr(net, "modules", None)
    if mods is None:
        raise ValueError("quantize_weights: 模型既没有 layers 也没有 modules")
    scales = []
    codes = []
    for i, layer in enumerate(mods):
        weight = getattr(layer, "weights", None)
        if weight is None:
            scales.append(None)
            codes.append(None)
            continue
        scale, qmax = _w15_scale_of(weight, bits, "quantize_weights")
        layer_codes = _w15_map(weight, lambda v: max(-int(qmax), min(int(qmax),
                                                                    int(round(v / scale)))))
        layer.weights = _w15_map(layer_codes, lambda q: q * scale)
        scales.append(scale)
        codes.append(layer_codes)
    return {"bits": bits, "scales": scales, "codes": codes}


def quantization_error(model, bits=8):
    """量化前后逐层最大 / 平均绝对误差（不改动模型）。"""
    _w15_check_bits(bits, "quantization_error")
    net = getattr(model, "model", model)
    mods = getattr(net, "layers", None) or getattr(net, "modules", None)
    if mods is None:
        raise ValueError("quantization_error: 模型既没有 layers 也没有 modules")
    out = []
    for i, layer in enumerate(mods):
        weight = getattr(layer, "weights", None)
        if weight is None:
            out.append({"index": i, "max": None, "mean": None})
            continue
        quant = fake_quantize(weight, bits=bits)
        flat_a = _w15_flat_numbers(weight, "quantization_error")
        flat_b = _w15_flat_numbers(quant, "quantization_error")
        diffs = [abs(a - b) for a, b in zip(flat_a, flat_b)]
        out.append({
            "index": i,
            "max": max(diffs),
            "mean": sum(diffs) / float(len(diffs)),
        })
    return out


def qat_grads(model, xs, ys, bits=8):
    """QAT 的「直通估计」梯度：在伪量化权重上前向反传，返回各层平均梯度。

    反向按 STE 处理——梯度穿过量化器不衰减，直接是量化点处的梯度。返回结构
    与 ``_mlp_backward`` 相同（每层 ``(grad_w, grad_b)``）。
    """
    _w15_check_bits(bits, "qat_grads")
    if not isinstance(xs, (list, tuple)) or not xs:
        raise ValueError("qat_grads: xs 不能为空")
    if len(xs) != len(ys):
        raise ValueError(
            f"qat_grads: xs 有 {len(xs)} 行，ys 有 {len(ys)} 个"
        )
    net = getattr(model, "model", model)
    if not hasattr(net, "layers"):
        raise ValueError("qat_grads: 只支持 MLP（需要 _mlp_backward 取参数梯度）")
    saved = []
    for layer in net.layers:
        if hasattr(layer, "weights"):
            saved.append((layer, layer.weights,
                          _w15_map(layer.weights, lambda v: v)))
            layer.weights = fake_quantize(layer.weights, bits=bits)
    try:
        acc = None
        for x, y in zip(xs, ys):
            pred = _w15_flat_numbers(net.forward(list(x)), "qat_grads")
            target = _w15_flat_numbers([y], "qat_grads") if not isinstance(
                y, (list, tuple)) else _w15_flat_numbers(y, "qat_grads")
            if len(pred) != len(target):
                raise ValueError(
                    f"qat_grads: 预测维度 {len(pred)} 与目标 {len(target)} 不一致"
                )
            dloss = [2.0 * (pred[i] - target[i]) for i in range(len(pred))]
            grads = _mlp_backward(net, dloss)
            if acc is None:
                acc = [[(None if gw is None else _w15_map(gw, lambda v: v),
                         _w15_map(gb, lambda v: v)) for gw, gb in grads]]
            else:
                for li, (gw, gb) in enumerate(grads):
                    acc_gw, acc_gb = acc[0][li]
                    if gw is not None and acc_gw is not None:
                        for j in range(len(gw)):
                            for i in range(len(gw[j])):
                                acc_gw[j][i] += gw[j][i]
                    if acc_gb is not None:
                        for j in range(len(gb)):
                            acc_gb[j] += gb[j]
        n = float(len(xs))
        return [(None if gw is None else _w15_map(gw, lambda v: v / n),
                 _w15_map(gb, lambda v: v / n)) for gw, gb in acc[0]]
    finally:
        for layer, original, _copy in saved:
            layer.weights = original


def smooth_quant_scale(activation_peak, weight_peak, alpha=0.5):
    """SmoothQuant 的逐通道缩放因子：``s = max|x|^alpha / max|w|^(1-alpha)``。"""
    for name, v in (("activation_peak", activation_peak), ("weight_peak", weight_peak)):
        if isinstance(v, bool) or not isinstance(v, (int, float)) or v <= 0.0:
            raise ValueError(f"smooth_quant_scale: {name} 必须 > 0，收到 {v!r}")
    if isinstance(alpha, bool) or not isinstance(alpha, (int, float)) \
            or not (0.0 <= alpha <= 1.0):
        raise ValueError(f"smooth_quant_scale: alpha 必须在 [0, 1] 内，收到 {alpha!r}")
    return (float(activation_peak) ** float(alpha)) / (
        float(weight_peak) ** (1.0 - float(alpha))
    )


def smooth_quant_apply(layer, scales):
    """按输入通道做 SmoothQuant 迁移：``W[:, j] *= s_j``（激活端要除以 ``s_j``）。

    数学上 ``(X / s) · (W * s) = X · W``，迁移后激活的动态范围变小，权重变大，
    更不容易被量化截断。调用方负责把对应的输入特征除以 ``s_j``。
    """
    if not hasattr(layer, "weights"):
        raise ValueError("smooth_quant_apply: 该层没有权重")
    rows = _w15_rows(layer.weights)
    scale_list = _w15_flat_numbers(scales, "smooth_quant_apply")
    width = len(rows[0])
    if len(scale_list) != width:
        raise ValueError(
            f"smooth_quant_apply: scales 长度 {len(scale_list)} 与输入维度 {width} 不一致"
        )
    for row in rows:
        for j in range(width):
            row[j] = row[j] * scale_list[j]
    return layer


# ============================================================================
#  推理与部署：结构化剪枝（通道 / 头 / 层）
# ============================================================================

def _w15_rows(value):
    """把嵌套结构按第一维切成「行」。"""
    if not isinstance(value, (list, tuple)) or not value:
        raise ValueError("_w15_rows: 需要非空的行列表")
    return list(value)


def _w15_abs_sum(value):
    """嵌套结构的绝对值之和。"""
    total = 0.0
    stack = [value]
    while stack:
        item = stack.pop()
        if isinstance(item, (list, tuple)):
            for v in reversed(item):
                stack.append(v)
        else:
            if isinstance(item, bool) or not isinstance(item, (int, float)):
                raise ValueError(f"_w15_abs_sum: 需要数字，收到 {item!r}")
            total += abs(float(item))
    return total


def _w15_ratio(ratio, who, allow_zero=True):
    if isinstance(ratio, bool) or not isinstance(ratio, (int, float)):
        raise ValueError(f"{who}: ratio 必须是数字，收到 {ratio!r}")
    lo_ok = ratio >= 0.0 if allow_zero else ratio > 0.0
    if not lo_ok or ratio > 1.0:
        raise ValueError(f"{who}: ratio 必须在 {'[0, 1]' if allow_zero else '(0, 1]'} 内，收到 {ratio!r}")
    return float(ratio)


def _w15_pick(scores, ratio, who, keep_at_least=1):
    """按分数从小到大挑出要剪掉的下标，至少保留 keep_at_least 个。"""
    n = len(scores)
    if n <= 0:
        raise ValueError(f"{who}: 没有可剪的单元")
    if not isinstance(keep_at_least, int) or isinstance(keep_at_least, bool) \
            or keep_at_least < 1:
        raise ValueError(f"{who}: keep_at_least 必须是 >=1 的整数，收到 {keep_at_least!r}")
    if keep_at_least >= n:
        raise ValueError(f"{who}: keep_at_least={keep_at_least} 不小于单元数 {n}，没有可剪的")
    order = sorted(range(n), key=lambda i: (scores[i], i))
    limit = min(n - keep_at_least, int(round(ratio * n)))
    return sorted(order[:limit])


def channel_scores(layer):
    """每个输出通道（``weights`` 的第一维）的绝对值之和。"""
    rows = _w15_rows(getattr(layer, "weights", None))
    return [_w15_abs_sum(row) for row in rows]


def prune_channels(model, layer_index, ratio=0.5, keep_at_least=1):
    """按通道重要性置零最弱的输出通道（**不改变形状**，下游无需改动）。

    返回 ``{"pruned", "kept", "scores"}``。真正的删行需要重建下游层，
    本函数只做掩码式剪枝，README 已写明。
    """
    _w15_ratio(ratio, "prune_channels")
    mods = getattr(model, "modules", None)
    if mods is None:
        mods = getattr(model, "layers", None)
    if mods is None:
        raise ValueError("prune_channels: 模型既没有 modules 也没有 layers")
    mods = list(mods)
    if not isinstance(layer_index, int) or isinstance(layer_index, bool):
        raise ValueError(f"prune_channels: layer_index 必须是整数，收到 {layer_index!r}")
    if not (0 <= layer_index < len(mods)):
        raise ValueError(f"prune_channels: layer_index={layer_index} 超出范围 [0, {len(mods)})")
    layer = mods[layer_index]
    if not hasattr(layer, "weights"):
        raise ValueError(
            f"prune_channels: 第 {layer_index} 层是 {type(layer).__name__}，没有权重"
        )
    scores = channel_scores(layer)
    pruned = _w15_pick(scores, ratio, "prune_channels", keep_at_least)
    for j in pruned:
        for i in range(len(layer.weights[j])):
            layer.weights[j][i] = 0.0
        if hasattr(layer, "biases") and j < len(layer.biases):
            layer.biases[j] = 0.0
    kept = [j for j in range(len(scores)) if j not in pruned]
    return {"pruned": pruned, "kept": kept, "scores": scores}


def prune_channels_structured(model, layer_index, ratio=0.5, keep_at_least=1):
    """按通道重要性**真正删掉**输出通道（同时裁剪下一层的输入列）。

    只支持相邻维度兼容的 MLP / 线性层（``layer.fan_out == next.fan_in``）；
    与 ``prune_channels`` 的掩码式剪枝不同，本函数会物理删除权重行/列并更新
    ``fan_out`` / ``fan_in`` / ``layer_sizes``，因此参数量会真实减少。
    返回 ``{"pruned", "kept", "scores", "layers": (i, i+1)}``。
    """
    _w15_ratio(ratio, "prune_channels_structured")
    if ratio <= 0.0:
        raise ValueError("prune_channels_structured: ratio 必须 > 0（否则什么都不会删）")
    net = getattr(model, "model", model)
    layers = getattr(net, "layers", None)
    if layers is None:
        raise ValueError("prune_channels_structured: 模型需要 layers 列表（MLP）")
    layers = list(layers)
    if not isinstance(layer_index, int) or isinstance(layer_index, bool):
        raise ValueError(
            f"prune_channels_structured: layer_index 必须是整数，收到 {layer_index!r}"
        )
    if not (0 <= layer_index < len(layers) - 1):
        raise ValueError(
            f"prune_channels_structured: layer_index={layer_index} 必须是中间层"
            f"（0 <= index < {len(layers) - 1}）"
        )
    cur, nxt = layers[layer_index], layers[layer_index + 1]
    if not hasattr(cur, "weights") or not hasattr(nxt, "weights"):
        raise ValueError("prune_channels_structured: 只支持带 weights 的线性层")
    if getattr(cur, "fan_out", None) != getattr(nxt, "fan_in", None):
        raise ValueError(
            f"prune_channels_structured: 相邻维度不兼容"
            f"（{getattr(cur, 'fan_out', None)} -> {getattr(nxt, 'fan_in', None)}）"
        )
    scores = channel_scores(cur)
    if not isinstance(keep_at_least, int) or isinstance(keep_at_least, bool)             or keep_at_least < 1:
        raise ValueError("prune_channels_structured: keep_at_least 必须是 >=1 的整数")
    if keep_at_least > len(scores):
        raise ValueError(
            f"prune_channels_structured: keep_at_least={keep_at_least} 超过通道数 {len(scores)}"
        )
    pruned = _w15_pick(scores, ratio, "prune_channels_structured", keep_at_least)
    keep = sorted(j for j in range(len(scores)) if j not in pruned)
    if not keep:
        raise ValueError("prune_channels_structured: keep_at_least 导致没有通道可留")
    cur.weights = [cur.weights[j] for j in keep]
    if hasattr(cur, "biases") and cur.biases:
        cur.biases = [cur.biases[j] for j in keep]
    nxt.weights = [[row[j] for j in keep] for row in nxt.weights]
    cur.fan_out = len(keep)
    nxt.fan_in = len(keep)
    for obj in (cur, nxt):
        for name in ("m_w", "v_w", "m_b", "v_b"):
            if hasattr(obj, name):
                setattr(obj, name, None)
    if getattr(net, "layer_sizes", None):
        net.layer_sizes = [layers[0].fan_in] + [layer.fan_out for layer in layers]
    if hasattr(net, "_fhooks"):
        net._fhooks = {}
    if hasattr(net, "_bhooks"):
        net._bhooks = {}
    return {"pruned": pruned, "kept": keep, "scores": scores,
            "layers": (layer_index, layer_index + 1)}


def head_scores(attention, projection="q"):
    """多头注意力每个头的权重绝对值之和（``projection`` 取 ``q`` / ``k`` / ``v`` / ``o``）。"""
    if projection not in ("q", "k", "v", "o"):
        raise ValueError(f"head_scores: projection 只能是 q/k/v/o，收到 {projection!r}")
    weight = getattr(attention, "W_" + projection, None)
    if weight is None:
        raise ValueError(
            f"head_scores: {type(attention).__name__} 没有 W_{projection} 投影权重"
        )
    heads = getattr(attention, "num_heads", None)
    d_model = getattr(attention, "d_model", None)
    d_k = getattr(attention, "d_k", None)
    if not isinstance(heads, int) or isinstance(heads, bool) or heads < 1:
        raise ValueError("head_scores: attention.num_heads 必须是 >=1 的整数")
    if not isinstance(d_model, int) or d_model < 1 or not isinstance(d_k, int) or d_k < 1:
        raise ValueError("head_scores: attention.d_model / d_k 必须是正整数")
    if heads * d_k != d_model:
        raise ValueError(
            f"head_scores: num_heads*d_k={heads * d_k} 不等于 d_model={d_model}"
        )
    rows = _w15_rows(weight)
    out = []
    for h in range(heads):
        lo, hi = h * d_k, (h + 1) * d_k
        total = 0.0
        if projection == "o":
            for r in range(lo, hi):
                total += _w15_abs_sum(rows[r])
        else:
            for row in rows:
                total += _w15_abs_sum(row[lo:hi])
        out.append(total)
    return out


def prune_heads(attention, ratio=0.5, keep_at_least=1):
    """按头重要性置零最弱的注意力头（同时置零 ``W_o`` 中对应的行）。"""
    _w15_ratio(ratio, "prune_heads")
    heads = getattr(attention, "num_heads", None)
    d_k = getattr(attention, "d_k", None)
    if not isinstance(heads, int) or isinstance(heads, bool) or heads < 2:
        raise ValueError("prune_heads: 头数必须 >=2 才能剪")
    if not isinstance(d_k, int) or d_k < 1:
        raise ValueError("prune_heads: attention.d_k 必须是正整数")
    scores = head_scores(attention, "q")
    pruned = _w15_pick(scores, ratio, "prune_heads", keep_at_least)
    for h in pruned:
        lo, hi = h * d_k, (h + 1) * d_k
        for name in ("W_q", "W_k", "W_v"):
            weight = getattr(attention, name, None)
            if weight is None:
                continue
            for row in weight:
                for c in range(lo, hi):
                    row[c] = 0.0
        out_w = getattr(attention, "W_o", None)
        if out_w is not None:
            for r in range(lo, hi):
                for c in range(len(out_w[r])):
                    out_w[r][c] = 0.0
    kept = [h for h in range(heads) if h not in pruned]
    return {"pruned": pruned, "kept": kept, "scores": scores}


def prune_layers(model, ratio=0.5, keep_at_least=2):
    """按层重要性**真正删除**中间层，返回新的 ``MLP``（原模型不改）。

    只能用于相邻维度互相兼容的 MLP；一旦删层后前后维度对不上就报错，
    不会悄悄改形状。
    """
    _w15_ratio(ratio, "prune_layers")
    net = getattr(model, "model", model)
    if not hasattr(net, "layers") or not hasattr(net, "layer_sizes"):
        raise ValueError("prune_layers: 只支持 MLP（需要 layers 与 layer_sizes）")
    layers = list(net.layers)
    if len(layers) <= keep_at_least:
        raise ValueError(
            f"prune_layers: 只有 {len(layers)} 层，keep_at_least={keep_at_least} 时无可剪"
        )
    if ratio <= 0.0:
        raise ValueError("prune_layers: ratio 必须 > 0（否则什么都不会删）")
    scores = [_w15_abs_sum(layer.weights) for layer in layers]
    candidates = list(range(1, len(layers) - 1))
    if not candidates:
        raise ValueError("prune_layers: 没有可删的中间层")
    order = sorted(candidates, key=lambda i: (scores[i], i))
    limit = min(len(layers) - keep_at_least, int(round(ratio * len(layers))))
    drop = set(order[:max(0, limit)])
    keep = [layer for i, layer in enumerate(layers) if i not in drop]
    for a, b in zip(keep, keep[1:]):
        if getattr(a, "fan_out", None) != getattr(b, "fan_in", None):
            raise ValueError(
                f"prune_layers: 删掉第 {sorted(drop)} 层后维度不兼容"
                f"（{a.fan_out} -> {b.fan_in}）"
            )
    new = MLP.__new__(MLP)
    new.layers = keep
    new.layer_sizes = [keep[0].fan_in] + [layer.fan_out for layer in keep]
    new._fhooks = {}
    new._bhooks = {}
    return new


def sparsity_report(model):
    """逐层统计权重为 0 的比例。"""
    net = getattr(model, "model", model)
    mods = getattr(net, "layers", None) or getattr(net, "modules", None)
    if mods is None:
        raise ValueError("sparsity_report: 模型既没有 layers 也没有 modules")
    out = []
    for i, layer in enumerate(mods):
        weight = getattr(layer, "weights", None)
        if weight is None:
            out.append({"index": i, "kind": type(layer).__name__, "zeros": None,
                        "total": None, "ratio": None})
            continue
        total = 0
        zeros = 0
        stack = [weight]
        while stack:
            item = stack.pop()
            if isinstance(item, (list, tuple)):
                for v in reversed(item):
                    stack.append(v)
            else:
                total += 1
                if float(item) == 0.0:
                    zeros += 1
        out.append({"index": i, "kind": type(layer).__name__, "zeros": zeros,
                    "total": total, "ratio": zeros / float(total) if total else 0.0})
    return out


# ============================================================================
#  可解释性：TCAV / 激活最大化 / 网络解剖 / 反事实 / 原型 / 影响
# ============================================================================

def _w14f_modules(model):
    mods = getattr(model, "modules", None)
    if mods is None:
        mods = getattr(model, "layers", None)
    if mods is None:
        raise ValueError(
            f"_w14f_modules: {type(model).__name__} 既没有 modules 也没有 layers"
        )
    mods = list(mods)
    if not mods:
        raise ValueError("_w14f_modules: 容器里没有模块")
    return mods


def _w14f_net(model):
    return getattr(model, "model", model)


def _w14f_flat(value):
    """把数字/一维/二维/三维结构摊平成一维浮点列表。"""
    out = []
    stack = [value]
    while stack:
        item = stack.pop()
        if isinstance(item, (list, tuple)):
            for v in reversed(item):
                stack.append(v)
        else:
            if isinstance(item, bool) or not isinstance(item, (int, float)):
                raise ValueError(f"_w14f_flat: 需要数字，收到 {item!r}")
            out.append(float(item))
    return out


def _w14f_layer_acts(model, layer_index, rows):
    """取第 layer_index 层在每行输入上的输出（摊平）。"""
    mods = _w14f_modules(model)
    if not isinstance(layer_index, int) or isinstance(layer_index, bool):
        raise ValueError(f"layer_index 必须是整数，收到 {layer_index!r}")
    if not (0 <= layer_index < len(mods)):
        raise ValueError(
            f"layer_index={layer_index} 超出范围 [0, {len(mods)})"
        )
    out = []
    for row in rows:
        a = list(row)
        for i, m in enumerate(mods):
            a = m.forward(a)
            if i == layer_index:
                break
        out.append(_w14f_flat(a))
    return out


def _w14f_check_rows(rows, who):
    if not isinstance(rows, (list, tuple)) or not rows:
        raise ValueError(f"{who}: 需要非空的样本列表")
    width = None
    out = []
    for i, row in enumerate(rows):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"{who}: 第 {i} 个样本必须是非空列表")
        vals = []
        for v in row:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f"{who}: 第 {i} 个样本含非数字 {v!r}")
            vals.append(float(v))
        if width is None:
            width = len(vals)
        elif len(vals) != width:
            raise ValueError(
                f"{who}: 第 {i} 个样本宽度 {len(vals)} 与 {width} 不一致"
            )
        out.append(vals)
    return out


def _w14f_out(net, row):
    out = net.forward(list(row))
    if not isinstance(out, (list, tuple)) or not out:
        raise ValueError(
            f"_w14f_out: 模型输出必须是长度 > 0 的列表，收到 {type(out).__name__}"
        )
    return _w14f_flat(out)


def _w14f_argmax(values):
    best = 0
    for i in range(1, len(values)):
        if values[i] > values[best]:
            best = i
    return best


def _w14f_grad_at_layer(model, layer_index, row, class_index=None):
    """返回 dScore/dLayerOutput（摊平）。"""
    mods = _w14f_modules(model)
    acts, grads, _cls = _cam_grad_output(model, mods, list(row), layer_index,
                                        class_index)
    return _w14f_flat(acts), _w14f_flat(grads)


def _w14f_layer_only(mods, upto, who):
    """梯度回传到输入需要每层都是 Layer（激活是逐元素函数）。"""
    for i, m in enumerate(mods[:upto + 1]):
        if not hasattr(m, "fan_in") or not hasattr(m, "fan_out"):
            raise ValueError(
                f"{who}: 第 {i} 层是 {type(m).__name__}，"
                f"本函数只支持由 Layer 组成的网络（卷积请用 cam_heatmap）"
            )


def _w14f_grad_to_input(model, layer_index, delta_at_layer, row):
    """从第 layer_index 层的梯度回传到输入。"""
    mods = _w14f_modules(model)
    _w14f_layer_only(mods, layer_index, "_w14f_grad_to_input")
    delta = list(delta_at_layer)
    for m in reversed(mods[:layer_index + 1]):
        result = m.backward(delta)
        if result is None:
            continue
        delta = (result[getattr(m, "delta_index", -1)]
                 if isinstance(result, tuple) else result)
    return delta


def _w14f_unit_delta(acts, unit):
    """在第 layer_index 层输出上构造「只抬升第 unit 个元素」的梯度。"""
    if not isinstance(unit, int) or isinstance(unit, bool):
        raise ValueError(f"unit 必须是整数，收到 {unit!r}")
    if not (0 <= unit < len(acts)):
        raise ValueError(f"unit={unit} 超出该层输出长度 {len(acts)}")
    delta = [0.0] * len(acts)
    delta[unit] = 1.0
    return delta


def tcav(model, layer_index, concept, random_set, class_set, class_index=None):
    """TCAV：用概念样本与参照样本的激活差做 CAV，再统计类别敏感度符号比例。

    返回 ``{"cav", "tcav", "sensitivity", "n"}``：``cav`` 是归一化后的概念方向，
    ``sensitivity_i = <dScore/dA, cav>``，``tcav`` 是其中为正的比例。
    """
    concept_rows = _w14f_check_rows(concept, "tcav: concept")
    random_rows = _w14f_check_rows(random_set, "tcav: random_set")
    class_rows = _w14f_check_rows(class_set, "tcav: class_set")
    if not class_rows:
        raise ValueError("tcav: class_set 不能为空")
    if len(concept_rows) < 1 or len(random_rows) < 1:
        raise ValueError("tcav: concept 与 random_set 都不能为空")
    concept_acts = _w14f_layer_acts(model, layer_index, concept_rows)
    random_acts = _w14f_layer_acts(model, layer_index, random_rows)
    dim = len(concept_acts[0])
    if len(random_acts[0]) != dim:
        raise ValueError("tcav: concept 与 random_set 的激活维度不一致")
    cav = [0.0] * dim
    for acts in concept_acts:
        for j in range(dim):
            cav[j] += acts[j] / len(concept_acts)
    for acts in random_acts:
        for j in range(dim):
            cav[j] -= acts[j] / len(random_acts)
    norm = math.sqrt(sum(v * v for v in cav))
    if norm <= 0.0:
        raise ValueError(
            "tcav: 概念样本与参照样本的平均激活完全相同，CAV 方向无定义"
        )
    cav = [v / norm for v in cav]

    sensitivities = []
    for row in class_rows:
        _acts, grad = _w14f_grad_at_layer(model, layer_index, row, class_index)
        if len(grad) != dim:
            raise ValueError(
                f"tcav: 第 {layer_index} 层的梯度维度 {len(grad)} 与激活 {dim} 不一致"
            )
        sensitivities.append(sum(a * b for a, b in zip(grad, cav)))
    positive = sum(1 for s in sensitivities if s > 0.0)
    return {
        "cav": cav,
        "tcav": positive / float(len(sensitivities)),
        "sensitivity": sensitivities,
        "n": len(sensitivities),
    }


def activation_maximization(model, layer_index, unit=0, steps=50, lr=0.1,
                            l2=1e-3, seed=None, image_shape=None):
    """激活最大化：梯度上升让第 ``layer_index`` 层的第 ``unit`` 个单元响应最大。

    只支持由 ``Layer`` 组成的网络（回传到输入需要逐元素激活导数）。返回
    ``{"input", "activation", "history"}``。
    """
    if not isinstance(steps, int) or isinstance(steps, bool) or steps < 1:
        raise ValueError(f"activation_maximization: steps 必须是 >=1 的整数，收到 {steps!r}")
    if not isinstance(lr, (int, float)) or lr <= 0.0:
        raise ValueError(f"activation_maximization: lr 必须 > 0，收到 {lr!r}")
    if not isinstance(l2, (int, float)) or l2 < 0.0:
        raise ValueError(f"activation_maximization: l2 不能为负，收到 {l2!r}")
    mods = _w14f_modules(model)
    if layer_index < 0 or layer_index >= len(mods):
        raise ValueError(
            f"activation_maximization: layer_index={layer_index} 超出范围"
        )
    _w14f_layer_only(mods, layer_index, "activation_maximization")
    if image_shape is not None and len(image_shape) == 3 and layer_index == 0 \
            and hasattr(mods[0], "fan_in"):
        raise ValueError(
            "activation_maximization: image_shape 是 (C, H, W) 但第 0 层是 Layer，"
            "两者形状不匹配"
        )
    first = mods[0]
    if image_shape is not None:
        if not isinstance(image_shape, (list, tuple)) or len(image_shape) < 1:
            raise ValueError(
                "activation_maximization: image_shape 必须是 [n] 或 [C, H, W]"
            )
        if len(image_shape) == 1:
            x = [0.0] * int(image_shape[0])
        elif len(image_shape) == 3:
            c, h, w = (int(v) for v in image_shape)
            x = [[[0.0] * w for _ in range(h)] for _ in range(c)]
        else:
            raise ValueError(
                "activation_maximization: image_shape 只支持 1 维或 (C, H, W)"
            )
    else:
        rows = getattr(first, "weights", None)
        width = len(rows[0]) if rows else 0
        if width <= 0:
            raise ValueError(
                "activation_maximization: 无法推断输入维度，请显式传 image_shape"
            )
        x = [0.0] * width
    rng = random.Random(seed)
    x = [(v + rng.gauss(0.0, 0.1)) for v in x]
    history = []
    for _step in range(steps):
        a = list(x)
        for i, m in enumerate(mods):
            a = m.forward(a)
            if i == layer_index:
                break
        acts = _w14f_flat(a)
        delta = _w14f_unit_delta(acts, unit)
        gx = _w14f_grad_to_input(model, layer_index, delta, x)
        if len(gx) != len(x):
            raise ValueError(
                f"activation_maximization: 输入梯度长度 {len(gx)} 与输入 {len(x)} 不一致"
            )
        x = [x[j] + lr * gx[j] - l2 * x[j] for j in range(len(x))]
        history.append(acts[unit])
    a = list(x)
    for i, m in enumerate(mods):
        a = m.forward(a)
        if i == layer_index:
            break
    return {"input": x, "activation": _w14f_flat(a)[unit], "history": history}


def network_dissection(model, layer_index, data, labels, activation_threshold=0.0,
                       top_k=2):
    """网络解剖：统计每个单元对各类别标签的平均激活与选择性。

    返回 ``{"units": [...], "labels": [...]}``，每个单元含
    ``mean_by_label`` / ``preferred`` / ``selectivity`` / ``activation_rate`` /
    ``kind``（``never`` / ``always`` / ``class-selective`` / ``mixed``）。
    """
    rows = _w14f_check_rows(data, "network_dissection: data")
    if len(rows) != len(labels):
        raise ValueError(
            f"network_dissection: data 有 {len(rows)} 行，labels 有 {len(labels)} 个"
        )
    if not isinstance(top_k, int) or isinstance(top_k, bool) or top_k < 1:
        raise ValueError(f"network_dissection: top_k 必须是 >=1 的整数，收到 {top_k!r}")
    acts = _w14f_layer_acts(model, layer_index, rows)
    dim = len(acts[0])
    classes = []
    for v in labels:
        if v not in classes:
            classes.append(v)
    sums = [[0.0] * len(classes) for _ in range(dim)]
    counts = [0] * len(classes)
    for acts_row, label in zip(acts, labels):
        ci = classes.index(label)
        counts[ci] += 1
        for j in range(dim):
            sums[j][ci] += acts_row[j]
    means = [[s / counts[c] for c, s in enumerate(row)] for row in sums]
    units = []
    for j in range(dim):
        row = means[j]
        order = sorted(range(len(classes)), key=lambda c: (-row[c], c))
        top = order[:top_k]
        best = row[order[0]]
        second = row[order[1]] if len(order) > 1 else 0.0
        selectivity = (best - second) / (abs(best) + 1e-9)
        rate = sum(1 for acts_row in acts
                   if acts_row[j] > activation_threshold) / float(len(acts))
        if rate <= 0.0:
            kind = "never"
        elif rate >= 1.0:
            kind = "always"
        elif selectivity >= 0.3:
            kind = "class-selective"
        else:
            kind = "mixed"
        units.append({
            "index": j,
            "mean_by_label": row,
            "preferred": [classes[c] for c in top],
            "selectivity": selectivity,
            "activation_rate": rate,
            "kind": kind,
        })
    return {"units": units, "labels": classes}


def prototype_examples(model, layer_index, data, labels=None, k=1):
    """原型样本：每个类别激活均值最近（欧氏）的 k 个样本下标。"""
    rows = _w14f_check_rows(data, "prototype_examples: data")
    if labels is None:
        labels = [0] * len(rows)
    if len(labels) != len(rows):
        raise ValueError(
            f"prototype_examples: data 有 {len(rows)} 行，labels 有 {len(labels)} 个"
        )
    if not isinstance(k, int) or isinstance(k, bool) or k < 1:
        raise ValueError(f"prototype_examples: k 必须是 >=1 的整数，收到 {k!r}")
    acts = _w14f_layer_acts(model, layer_index, rows)
    dim = len(acts[0])
    classes = []
    for v in labels:
        if v not in classes:
            classes.append(v)
    out = {}
    for c in classes:
        idxs = [i for i, v in enumerate(labels) if v == c]
        center = [sum(acts[i][j] for i in idxs) / len(idxs) for j in range(dim)]
        scored = []
        for i in idxs:
            d = sum((acts[i][j] - center[j]) ** 2 for j in range(dim))
            scored.append((d, i))
        scored.sort()
        out[c] = [i for _d, i in scored[:k]]
    return out


def counterfactual_example(model, x, class_index=None, steps=100, lr=0.05,
                           l2=1e-3, seed=None):
    """反事实样本：梯度下降把预测改到 ``class_index``，同时用 L2 拉住距离。

    ``class_index=None`` 时取当前概率第二高的类。只支持 ``Layer`` 组成的网络
    （需要回传到输入）。返回 ``{"input", "target", "distance",
    "score_before", "score_after"}``。
    """
    net = _w14f_net(model)
    xr = _w14f_check_rows([x], "counterfactual_example")[0]
    if not isinstance(steps, int) or isinstance(steps, bool) or steps < 1:
        raise ValueError(f"counterfactual_example: steps 必须是 >=1 的整数，收到 {steps!r}")
    if not isinstance(lr, (int, float)) or lr <= 0.0:
        raise ValueError(f"counterfactual_example: lr 必须 > 0，收到 {lr!r}")
    if not isinstance(l2, (int, float)) or l2 < 0.0:
        raise ValueError(f"counterfactual_example: l2 不能为负，收到 {l2!r}")
    mods = _w14f_modules(model)
    _w14f_layer_only(mods, len(mods) - 1, "counterfactual_example")
    out0 = _w14f_out(net, xr)
    if len(out0) == 1:
        raise ValueError(
            "counterfactual_example: 单输出回归模型没有「类别」可换，"
            "请改用 anchored 回归解释"
        )
    current = _w14f_argmax(out0)
    if class_index is None:
        candidates = sorted(range(len(out0)),
                            key=lambda c: (-out0[c], c))
        target = candidates[1] if len(candidates) > 1 else 0
    else:
        if not isinstance(class_index, int) or isinstance(class_index, bool):
            raise ValueError(
                f"counterfactual_example: class_index 必须是整数，收到 {class_index!r}"
            )
        if not (0 <= class_index < len(out0)):
            raise ValueError(
                f"counterfactual_example: class_index={class_index} 超出输出维度 {len(out0)}"
            )
        target = class_index
    if target == current:
        raise ValueError(
            "counterfactual_example: 目标类与当前预测相同，没有可解释的反事实"
        )
    best = list(xr)
    best_gap = None
    z = list(xr)
    for _step in range(steps):
        acts, _grad = _w14f_grad_at_layer(model, len(mods) - 1, z, target)
        delta = _w14f_unit_delta(acts, target)
        cur = _w14f_unit_delta(acts, current)
        delta = [delta[i] - cur[i] for i in range(len(delta))]
        gx = _w14f_grad_to_input(model, len(mods) - 1, delta, z)
        z = [z[j] + lr * gx[j] - l2 * (z[j] - xr[j]) for j in range(len(z))]
        out = _w14f_out(net, z)
        gap = out[current] - out[target]
        if best_gap is None or gap < best_gap:
            best_gap = gap
            best = list(z)
        if _w14f_argmax(out) == target:
            best = list(z)
            break
    out_after = _w14f_out(net, best)
    dist = math.sqrt(sum((best[j] - xr[j]) ** 2 for j in range(len(xr))))
    return {
        "input": best,
        "target": target,
        "distance": dist,
        "score_before": out0[current] - out0[target],
        "score_after": out_after[current] - out_after[target],
    }


def influence_scores(model, x, y, train_x, train_y):
    """一阶 TracIn 影响：``-<∇L(x), ∇L(z_i)>``，正数表示该训练样本有帮助。

    只支持 ``MLP``（用 ``_mlp_backward`` 取参数梯度），损失按 MSE 的
    ``dL/dpred = 2(pred - y)`` 取。返回与 ``train_x`` 对齐的分数列表。
    """
    net = _w14f_net(model)
    if not hasattr(net, "layers"):
        raise ValueError(
            "influence_scores: 只支持 MLP（需要 _mlp_backward 取参数梯度）"
        )
    xr = _w14f_check_rows([x], "influence_scores: x")[0]
    tr = _w14f_check_rows(train_x, "influence_scores: train_x")
    if len(tr) != len(train_y):
        raise ValueError(
            f"influence_scores: train_x 有 {len(tr)} 行，train_y 有 {len(train_y)} 个"
        )

    def _grad(row, target):
        pred = net.forward(list(row))
        pred_v = _w14f_flat(pred)
        if len(pred_v) != 1:
            raise ValueError(
                "influence_scores: 只支持单输出模型（MSE 标量损失）"
            )
        dloss = [2.0 * (pred_v[0] - float(target))]
        grads = _mlp_backward(net, dloss)
        flat = []
        for gw, gb in grads:
            if gw is None:
                continue
            flat.extend(_w14f_flat(gw))
            flat.extend(_w14f_flat(gb))
        return flat

    test_g = _grad(xr, y)
    out = []
    for row, target in zip(tr, train_y):
        g = _grad(row, target)
        if len(g) != len(test_g):
            raise ValueError("influence_scores: 训练样本梯度维度不一致")
        dot = sum(a * b for a, b in zip(test_g, g))
        na = math.sqrt(sum(a * a for a in test_g))
        nb = math.sqrt(sum(b * b for b in g))
        if na <= 0.0 or nb <= 0.0:
            out.append(0.0)
        else:
            out.append(-dot / (na * nb))
    return out


# ============================================================================
#  可解释性：嵌入可视化 / KernelSHAP / LIME / Anchors
# ============================================================================

def _w14e_net(model):
    """取出真正的前向对象（兼容 Model 包装器）。"""
    net = getattr(model, "model", model)
    if not hasattr(net, "forward"):
        raise ValueError(
            f"_w14e_net: {type(model).__name__} 没有 forward()，无法解释"
        )
    return net


def _w14e_row(x, who):
    """校验一维数值样本。"""
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError(f"{who}: 样本必须是长度 > 0 的一维列表")
    out = []
    for v in x:
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError(f"{who}: 样本元素必须是数字，收到 {v!r}")
        out.append(float(v))
    return out


def _w14e_pool(rows, width, who):
    """校验二维数值矩阵，且每行宽度必须等于 width。"""
    if not isinstance(rows, (list, tuple)) or not rows:
        raise ValueError(f"{who}: 需要非空的二维列表")
    out = []
    for i, row in enumerate(rows):
        vals = _w14e_row(row, f"{who}[{i}]")
        if len(vals) != width:
            raise ValueError(
                f"{who}: 第 {i} 行宽度 {len(vals)} 与 {width} 不一致"
            )
        out.append(vals)
    return out


def _w14e_forward(net, row):
    """前向一次，返回数值列表。"""
    out = net.forward(list(row))
    if not isinstance(out, (list, tuple)) or not out:
        raise ValueError(
            f"_w14e_forward: 模型输出必须是长度 > 0 的列表，收到 {type(out).__name__}"
        )
    vals = []
    for v in out:
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError("_w14e_forward: 模型输出里必须全是数字")
        vals.append(float(v))
    return vals


def _w14e_score(net, row, class_index=None):
    """把模型输出压成一个标量分数：单输出直取，多输出取类别概率。"""
    out = _w14e_forward(net, row)
    if len(out) == 1:
        if class_index is not None:
            raise ValueError(
                "_w14e_score: 单输出模型（回归）不接受 class_index"
            )
        return out[0]
    if class_index is None:
        best = 0
        for i in range(1, len(out)):
            if out[i] > out[best]:
                best = i
        class_index = best
    if not isinstance(class_index, int) or isinstance(class_index, bool):
        raise ValueError(
            f"_w14e_score: class_index 必须是整数，收到 {class_index!r}"
        )
    if not (0 <= class_index < len(out)):
        raise ValueError(
            f"_w14e_score: class_index={class_index} 超出输出维度 {len(out)}"
        )
    probs = _softmax_row(out)
    return probs[class_index]


def _w14e_resolve_class(net, row, class_index):
    """多输出模型在 class_index=None 时锁到 argmax，避免解释过程中类别漂移。"""
    out = _w14e_forward(net, row)
    if len(out) == 1:
        if class_index is not None:
            raise ValueError("单输出模型（回归）不接受 class_index")
        return None
    if class_index is None:
        best = 0
        for i in range(1, len(out)):
            if out[i] > out[best]:
                best = i
        return best
    if not isinstance(class_index, int) or isinstance(class_index, bool):
        raise ValueError(f"class_index 必须是整数，收到 {class_index!r}")
    if not (0 <= class_index < len(out)):
        raise ValueError(
            f"class_index={class_index} 超出输出维度 {len(out)}"
        )
    return class_index


def _w14e_masks(n_features, count, rng, skip_trivial=False):
    """生成至多 count 个互不相同的二值掩码。

    二值掩码总共只有 `2^n_features` 种，所以样本数必须被它截断——否则
    「随机抽 + 去重」的循环在特征极少时永远凑不够，会直接挂死。
    """
    if count <= 0:
        return []
    want = count + (2 if skip_trivial else 0)
    out = []
    seen = set()
    if n_features <= 12:
        codes = list(range(1 << n_features))
        rng.shuffle(codes)
        for code in codes:
            mask = [(code >> j) & 1 for j in range(n_features)]
            total = sum(mask)
            if skip_trivial and (total == 0 or total == n_features):
                continue
            key = tuple(mask)
            if key in seen:
                continue
            seen.add(key)
            out.append(mask)
            if len(out) >= want:
                break
        return out[:count]
    attempts = 0
    limit = 200 * want
    while len(out) < want and attempts < limit:
        attempts += 1
        mask = [1 if rng.random() < 0.5 else 0 for _ in range(n_features)]
        total = sum(mask)
        if skip_trivial and (total == 0 or total == n_features):
            continue
        key = tuple(mask)
        if key in seen:
            continue
        seen.add(key)
        out.append(mask)
    return out[:count]


def _w14e_hybrid(x, background, mask):
    """把「不在 mask 里」的特征换成背景值。"""
    return [x[j] if mask[j] else background[j] for j in range(len(x))]


def _w14e_weights_ls(features, targets, weights, ridge=1e-10):
    """加权最小二乘：解 (XᵀWX + ridge·I) β = XᵀWy。"""
    n = len(features)
    m = len(features[0])
    ata = [[0.0] * m for _ in range(m)]
    atb = [0.0] * m
    for i in range(n):
        w = weights[i]
        if w <= 0.0:
            continue
        row = features[i]
        y = targets[i]
        for a in range(m):
            wa = w * row[a]
            if wa == 0.0:
                continue
            atb[a] += wa * y
            ata_row = ata[a]
            for b in range(m):
                ata_row[b] += wa * row[b]
    for a in range(m):
        ata[a][a] += ridge
    sol = _w11f_solve(ata, atb)
    if sol is None:
        raise ValueError(
            "_w14e_weights_ls: 正规方程奇异（样本掩码重复过多），"
            "请增大 n_samples 或检查特征是否常量"
        )
    return sol


def _shap_kernel_weight(n_features, size):
    """KernelSHAP 的 Shapley kernel 权重。"""
    if size == 0 or size == n_features:
        return 1e6
    return (n_features - 1.0) / (
        _binom(n_features, size) * size * (n_features - size)
    )


def _binom(n, k):
    """二项系数（只用在小 n 上，直接连乘）。"""
    if k < 0 or k > n:
        return 0.0
    k = min(k, n - k)
    out = 1.0
    for i in range(k):
        out = out * (n - i) / (i + 1.0)
    return out


def kernel_shap(model, x, background=None, class_index=None, n_samples=100,
                seed=None, feature_names=None):
    """KernelSHAP（简化版）：返回 ``{"base_value", "output_value", "values", "names"}``。

    对每个特征子集 `S` 用「`S` 里保留 x 的值、其余换成背景值」构造混合样本，
    用 Shapley kernel 权重做加权最小二乘拟合线性代理模型；最后按效率公理
    做常数平移，保证 ``sum(values) == output_value - base_value``。
    """
    net = _w14e_net(model)
    xr = _w14e_row(x, "kernel_shap")
    m = len(xr)
    if not isinstance(n_samples, int) or isinstance(n_samples, bool):
        raise ValueError(f"kernel_shap: n_samples 必须是整数，收到 {n_samples!r}")
    if n_samples < 2:
        raise ValueError(f"kernel_shap: n_samples 必须 >= 2，收到 {n_samples}")
    cls = _w14e_resolve_class(net, xr, class_index)
    if background is None:
        bg = [0.0] * m
    else:
        rows = _w14e_pool(background, m, "kernel_shap: background")
        bg = [sum(row[j] for row in rows) / len(rows) for j in range(m)]
    if feature_names is not None:
        names = list(feature_names)
        if len(names) != m:
            raise ValueError(
                f"kernel_shap: feature_names 长度 {len(names)} 与特征数 {m} 不一致"
            )
    else:
        names = [f"f{j}" for j in range(m)]

    rng = random.Random(seed)
    masks = []
    seen = set()
    for mask in ([1] * m, [0] * m):
        key = tuple(mask)
        seen.add(key)
        masks.append(mask)
    # 只有 2^m 种掩码，n_samples 被它截断（空/满两个已经放进去）
    cap = min(n_samples, 1 << m) if m <= 20 else n_samples
    if cap < 3:
        raise ValueError(
            f"kernel_shap: 只有 {m} 个特征时可用的掩码太少，无法拟合线性代理模型"
        )
    for mask in _w14e_masks(m, cap - len(masks), rng):
        key = tuple(mask)
        if key in seen:
            continue
        seen.add(key)
        masks.append(mask)

    rows = []
    targets = []
    weights = []
    for mask in masks:
        row = _w14e_hybrid(xr, bg, mask)
        rows.append([float(v) for v in mask])
        targets.append(_w14e_score(net, row, cls))
        weights.append(_shap_kernel_weight(m, sum(mask)))

    full = _w14e_score(net, xr, cls)
    base = _w14e_score(net, bg, cls)
    values = _w14e_weights_ls(rows, targets, weights)
    drift = (full - base) - sum(values)
    shift = drift / m
    values = [v + shift for v in values]
    return {
        "base_value": base,
        "output_value": full,
        "values": values,
        "names": names,
    }


def lime_explain(model, x, class_index=None, n_samples=200, kernel_width=0.75,
                 seed=None, feature_names=None):
    """LIME（简化版表格）：返回 ``{"intercept", "coefs", "names", "score"}``。

    可解释表示是「该特征是否仍等于 x 的第 j 维」的二值向量；扰动用
    `Bernoulli(0.5)` 决定每维是否保留原值（不保留时取背景 0 或训练均值），
    距离用归一化汉明距离，权重 `exp(-d² / kernel_width²)`。
    """
    net = _w14e_net(model)
    xr = _w14e_row(x, "lime_explain")
    m = len(xr)
    if not isinstance(n_samples, int) or isinstance(n_samples, bool):
        raise ValueError(f"lime_explain: n_samples 必须是整数，收到 {n_samples!r}")
    if n_samples < 2:
        raise ValueError(f"lime_explain: n_samples 必须 >= 2，收到 {n_samples}")
    if not isinstance(kernel_width, (int, float)) or kernel_width <= 0.0:
        raise ValueError(
            f"lime_explain: kernel_width 必须 > 0，收到 {kernel_width!r}"
        )
    cls = _w14e_resolve_class(net, xr, class_index)
    if feature_names is None:
        names = [f"f{j}" for j in range(m)]
    else:
        names = list(feature_names)
        if len(names) != m:
            raise ValueError(
                f"lime_explain: feature_names 长度 {len(names)} 与特征数 {m} 不一致"
            )

    rng = random.Random(seed)
    rows = [[1.0] * m, [0.0] * m]
    targets = [_w14e_score(net, xr, cls), _w14e_score(net, [0.0] * m, cls)]
    weights = [1.0, 1.0]
    # 同样受 2^m 限制：全 0 / 全 1 已经手动放进去了
    cap = min(n_samples, 1 << m) if m <= 20 else n_samples
    for keep in _w14e_masks(m, cap - len(rows), rng, skip_trivial=True):
        sample = [xr[j] if keep[j] else 0.0 for j in range(m)]
        dist = sum(1 for j in range(m) if not keep[j]) / float(m)
        rows.append([float(v) for v in keep])
        targets.append(_w14e_score(net, sample, cls))
        weights.append(math.exp(-(dist * dist) / (kernel_width * kernel_width)))

    coefs = _w14e_weights_ls(rows, targets, weights, ridge=1e-8)
    intercept = _w14e_score(net, [0.0] * m, cls)
    return {
        "intercept": intercept,
        "coefs": coefs,
        "names": names,
        "score": _w14e_score(net, xr, cls),
    }


def _w14e_argmax(net, row):
    out = _w14e_forward(net, row)
    best = 0
    for i in range(1, len(out)):
        if out[i] > out[best]:
            best = i
    return best


def anchor_rule(model, x, pool, class_index=None, threshold=0.9,
                max_features=None, seed=None):
    """Anchors（简化版）：贪心找最小的「特征=取值」组合。

    精度定义：在 pool 里与 x 在该组合上完全一致的样本中，预测类别与 x 相同的
    比例。返回 ``{"features", "values", "precision", "coverage"}``；找不到达到
    ``threshold`` 的组合时抛 ValueError（不返回一个假装达标的规则）。
    """
    net = _w14e_net(model)
    xr = _w14e_row(x, "anchor_rule")
    m = len(xr)
    rows = _w14e_pool(pool, m, "anchor_rule: pool")
    if not isinstance(threshold, (int, float)) or not (0.0 < threshold <= 1.0):
        raise ValueError(
            f"anchor_rule: threshold 必须在 (0, 1] 内，收到 {threshold!r}"
        )
    target = _w14e_argmax(net, xr)
    if max_features is None:
        max_features = m
    if not isinstance(max_features, int) or isinstance(max_features, bool):
        raise ValueError(
            f"anchor_rule: max_features 必须是整数，收到 {max_features!r}"
        )
    if not (1 <= max_features <= m):
        raise ValueError(
            f"anchor_rule: max_features 必须在 [1, {m}] 内，收到 {max_features}"
        )

    def stats(chosen):
        matched = 0
        agree = 0
        for row in rows:
            if all(row[j] == xr[j] for j in chosen):
                matched += 1
                if _w14e_argmax(net, row) == target:
                    agree += 1
        if matched == 0:
            return 0.0, 0.0
        return agree / float(matched), matched / float(len(rows))

    chosen = []
    best_prec, best_cov = stats(chosen)
    while len(chosen) < max_features:
        pick = None
        pick_prec = best_prec
        for j in range(m):
            if j in chosen:
                continue
            prec, _cov = stats(chosen + [j])
            if prec > pick_prec:
                pick = j
                pick_prec = prec
        if pick is None:
            break
        chosen.append(pick)
        best_prec, best_cov = stats(chosen)
        if best_prec >= threshold:
            break
    if best_prec < threshold:
        raise ValueError(
            f"anchor_rule: 最多 {max_features} 个特征也只能到精度 {best_prec:.4f}，"
            f"低于 threshold={threshold}；调小 threshold 或扩大 pool"
        )
    return {
        "features": chosen,
        "values": [xr[j] for j in chosen],
        "precision": best_prec,
        "coverage": best_cov,
    }


def scatter_ascii(points, labels=None, width=48, height=20):
    """把二维点云画成 ASCII 散点；``labels`` 给定时用其首字符区分不同类。"""
    if not isinstance(points, (list, tuple)) or not points:
        raise ValueError("scatter_ascii: points 必须是非空二维列表")
    xs = []
    ys = []
    for i, p in enumerate(points):
        if not isinstance(p, (list, tuple)) or len(p) != 2:
            raise ValueError(f"scatter_ascii: 第 {i} 个点必须是 (x, y)")
        for v in p:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise ValueError(f"scatter_ascii: 第 {i} 个点含非数字 {v!r}")
        xs.append(float(p[0]))
        ys.append(float(p[1]))
    if labels is not None:
        if len(labels) != len(points):
            raise ValueError(
                f"scatter_ascii: labels 长度 {len(labels)} 与点数 {len(points)} 不一致"
            )
    if not isinstance(width, int) or isinstance(width, bool) or width < 4:
        raise ValueError(f"scatter_ascii: width 必须是 >=4 的整数，收到 {width!r}")
    if not isinstance(height, int) or isinstance(height, bool) or height < 3:
        raise ValueError(f"scatter_ascii: height 必须是 >=3 的整数，收到 {height!r}")

    xmin, xmax = min(xs), max(xs)
    ymin, ymax = min(ys), max(ys)
    span_x = (xmax - xmin) or 1.0
    span_y = (ymax - ymin) or 1.0
    grid = [[" "] * width for _ in range(height)]
    for i, (xv, yv) in enumerate(zip(xs, ys)):
        col = int((xv - xmin) / span_x * (width - 1))
        row = height - 1 - int((yv - ymin) / span_y * (height - 1))
        ch = "*"
        if labels is not None:
            text = str(labels[i])
            ch = text[0] if text else "*"
        grid[row][col] = ch
    return "\n".join("".join(r) for r in grid)


def embedding_visualize(data, labels=None, method="tsne", seed=42,
                        width=48, height=20):
    """把高维数据降到二维并画出 ASCII 散点图。

    返回 ``{"coords": [[x, y], ...], "labels": labels, "ascii": 文本}``；
    ``method='tsne'`` 复用 t-SNE，``method='pca'`` 复用 PCA。
    """
    if not isinstance(data, (list, tuple)) or not data:
        raise ValueError("embedding_visualize: data 必须是非空二维列表")
    width_dim = None
    for i, row in enumerate(data):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"embedding_visualize: 第 {i} 行必须是非空列表")
        if width_dim is None:
            width_dim = len(row)
        elif len(row) != width_dim:
            raise ValueError(
                f"embedding_visualize: 第 {i} 行宽度 {len(row)} 与 {width_dim} 不一致"
            )
    if labels is not None and len(labels) != len(data):
        raise ValueError(
            f"embedding_visualize: labels 长度 {len(labels)} 与样本数 {len(data)} 不一致"
        )
    if method == "tsne":
        coords = TSNE(n_components=2, seed=seed).fit_transform(data)
    elif method == "pca":
        coords = PCA(n_components=2).fit_transform(data)
    else:
        raise ValueError(
            f"embedding_visualize: method 必须是 'tsne' 或 'pca'，收到 {method!r}"
        )
    pts = [[float(row[0]), float(row[1])] for row in coords]
    return {
        "coords": pts,
        "labels": labels,
        "ascii": scatter_ascii(pts, labels=labels, width=width, height=height),
    }

#  可解释性：CAM 系列（GradCAM / GradCAM++ / LayerCAM / ScoreCAM）
# ============================================================================

def _cam_modules(model):
    """取出顺序容器里的模块列表（Sequential.modules 或 MLP.layers）。"""
    mods = getattr(model, "modules", None)
    if mods is None:
        mods = getattr(model, "layers", None)
    if mods is None:
        raise ValueError(
            f"_cam_modules: {type(model).__name__} 既没有 modules 也没有 layers，"
            f"无法定位卷积层"
        )
    mods = list(mods)
    if not mods:
        raise ValueError("_cam_modules: 容器里没有模块")
    return mods


def _cam_index(modules, layer_index, who):
    if not isinstance(layer_index, int) or isinstance(layer_index, bool):
        raise ValueError(f"{who}: layer_index 必须是整数，收到 {layer_index!r}")
    if not (0 <= layer_index < len(modules)):
        raise ValueError(
            f"{who}: layer_index={layer_index} 超出范围 [0, {len(modules)})"
        )
    return layer_index


def _cam_is_map(x):
    """判断是不是 (C, H, W) 三层嵌套的浮点张量。"""
    if not isinstance(x, (list, tuple)) or not x:
        return False
    if not isinstance(x[0], (list, tuple)) or not x[0]:
        return False
    if not isinstance(x[0][0], (list, tuple)):
        return False
    return True


def _cam_check_map(t, who):
    if not _cam_is_map(t):
        raise ValueError(f"{who}: 需要 (C, H, W) 形式的特征图，收到 {type(t).__name__}")
    h = len(t[0])
    w = len(t[0][0])
    out = []
    for c, plane in enumerate(t):
        if len(plane) != h:
            raise ValueError(f"{who}: 第 {c} 个通道行数 {len(plane)} 与 {h} 不一致")
        row = []
        for r, line in enumerate(plane):
            if len(line) != w:
                raise ValueError(
                    f"{who}: 第 {c} 通道第 {r} 行列数 {len(line)} 与 {w} 不一致"
                )
            vals = []
            for v in line:
                if isinstance(v, bool) or not isinstance(v, (int, float)):
                    raise ValueError(f"{who}: 特征图元素必须是数字，收到 {v!r}")
                vals.append(float(v))
            row.append(vals)
        out.append(row)
    return out


def _cam_forward_trace(modules, x, stop_index):
    """手工前向到 stop_index（含），返回 (A, logits)。"""
    a = x
    for i, m in enumerate(modules):
        a = m.forward(a)
        if i == stop_index:
            return a, None
    return None, a


def _cam_logits(model, modules, x, stop_index):
    """前向一遍：返回 (target 层输出 A, 最终 logits)。"""
    a = x
    target = None
    for i, m in enumerate(modules):
        a = m.forward(a)
        if i == stop_index:
            target = a
    return target, a


def _cam_grad_output(model, modules, x, stop_index, class_index):
    """返回 dScore/dA（A 是第 stop_index 个模块的输出）。"""
    target, logits = _cam_logits(model, modules, x, stop_index)
    if not isinstance(logits, (list, tuple)) or not logits:
        raise ValueError(
            "_cam_grad_output: 模型最后一层输出必须是 1 维 logits 列表，"
            f"收到 {type(logits).__name__}（CAM 只支持分类输出）"
        )
    for v in logits:
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError("_cam_grad_output: logits 里必须全是数字")
    n = len(logits)
    if class_index is None:
        best = 0
        for i in range(1, n):
            if logits[i] > logits[best]:
                best = i
        class_index = best
    if not isinstance(class_index, int) or isinstance(class_index, bool):
        raise ValueError(f"_cam_grad_output: class_index 必须是整数，收到 {class_index!r}")
    if not (0 <= class_index < n):
        raise ValueError(
            f"_cam_grad_output: class_index={class_index} 超出 logits 维度 {n}"
        )
    delta = [1.0 if i == class_index else 0.0 for i in range(n)]
    for m in reversed(modules[stop_index + 1:]):
        result = m.backward(delta)
        if result is None:
            continue
        delta = (result[getattr(m, "delta_index", -1)]
                 if isinstance(result, tuple) else result)
    return target, delta, class_index


def _cam_normalize(heat):
    """把热图按最大值归一到 [0, 1]（全零时原样返回 0）。"""
    top = None
    for row in heat:
        for v in row:
            if top is None or v > top:
                top = v
    if top is None or top <= 0.0:
        return [[0.0] * len(heat[0]) for _ in range(len(heat))]
    return [[v / top for v in row] for row in heat]


def _cam_relu(v):
    return v if v > 0.0 else 0.0


def gradcam_weights(grads, method="gradcam", acts=None, eps=1e-8):
    """按 CAM 变体算每个通道的权重。

    - ``gradcam``：对梯度取空间平均
    - ``gradcam++``：α = g² / (2g² + Σ_ab A_ab g_ab³)，再对 α·relu(g) 求和
    - ``layercam``：权重退化为逐元素（返回 None，热图直接按元素相乘）
    """
    g = _cam_check_map(grads, "gradcam_weights")
    if method == "layercam":
        return None
    if method == "gradcam":
        out = []
        for plane in g:
            total = 0.0
            count = 0
            for row in plane:
                for v in row:
                    total += v
                    count += 1
            out.append(total / count)
        return out
    if method != "gradcam++":
        raise ValueError(
            f"gradcam_weights: method 必须是 'gradcam' / 'gradcam++' / 'layercam'，"
            f"收到 {method!r}"
        )
    if acts is None:
        raise ValueError("gradcam_weights: gradcam++ 需要同时传入 acts")
    a = _cam_check_map(acts, "gradcam_weights")
    if len(a) != len(g) or len(a[0]) != len(g[0]) or len(a[0][0]) != len(g[0][0]):
        raise ValueError("gradcam_weights: acts 与 grads 形状必须一致")
    if not isinstance(eps, (int, float)) or eps <= 0.0:
        raise ValueError(f"gradcam_weights: eps 必须 > 0，收到 {eps!r}")
    out = []
    for c in range(len(g)):
        total = 0.0
        for r in range(len(g[c])):
            for k in range(len(g[c][r])):
                gg = g[c][r][k]
                denom = 2.0 * gg * gg
                for rr in range(len(a[c])):
                    for kk in range(len(a[c][rr])):
                        denom += a[c][rr][kk] * gg * gg * gg
                alpha = (gg * gg) / (denom + eps)
                total += alpha * _cam_relu(gg)
        out.append(total)
    return out


def cam_heatmap(model, x, layer_index, class_index=None, method="gradcam",
                relu=True):
    """GradCAM / GradCAM++ / LayerCAM 热图（返回 ``(heatmap, weights)``）。

    ``heatmap`` 是 H×W 的 [0,1] 列表（``layer_index`` 那层特征图的空间尺寸），
    ``weights`` 是每通道权重（LayerCAM 为 None）。
    """
    if method not in ("gradcam", "gradcam++", "layercam"):
        raise ValueError(
            f"cam_heatmap: method 必须是 'gradcam' / 'gradcam++' / 'layercam'，"
            f"收到 {method!r}（ScoreCAM 用 scorecam_heatmap）"
        )
    modules = _cam_modules(model)
    idx = _cam_index(modules, layer_index, "cam_heatmap")
    acts, grads, _ = _cam_grad_output(model, modules, x, idx, class_index)
    a = _cam_check_map(acts, "cam_heatmap")
    g = _cam_check_map(grads, "cam_heatmap")
    if len(a) != len(g) or len(a[0]) != len(g[0]) or len(a[0][0]) != len(g[0][0]):
        raise ValueError(
            f"cam_heatmap: 第 {idx} 层的输出与回传梯度形状不一致"
            f"（{len(a)}x{len(a[0])}x{len(a[0][0])} vs "
            f"{len(g)}x{len(g[0])}x{len(g[0][0])}）；该层 backward 必须返回"
            f"与本层输出同形的梯度"
        )
    w = gradcam_weights(g, method=method, acts=a)
    heat = [[0.0] * len(a[0][0]) for _ in range(len(a[0]))]
    if method == "layercam":
        for c in range(len(a)):
            for r in range(len(a[c])):
                for k in range(len(a[c][r])):
                    heat[r][k] += a[c][r][k] * g[c][r][k]
    else:
        for c in range(len(a)):
            wc = w[c]
            for r in range(len(a[c])):
                for k in range(len(a[c][r])):
                    heat[r][k] += wc * a[c][r][k]
    if relu:
        heat = [[_cam_relu(v) for v in row] for row in heat]
    return _cam_normalize(heat), w


def _cam_upsample(plane, height, width):
    """最近邻上采样一张 H×W 平面到 height×width。"""
    h = len(plane)
    w = len(plane[0])
    out = []
    for r in range(height):
        src_r = min(h - 1, r * h // height)
        row = []
        for k in range(width):
            src_k = min(w - 1, k * w // width)
            row.append(plane[src_r][src_k])
        out.append(row)
    return out


def _cam_spatial(x):
    if not _cam_is_map(x):
        raise ValueError(f"_cam_spatial: 输入必须是 (C, H, W)，收到 {type(x).__name__}")
    return len(x[0]), len(x[0][0])


def scorecam_heatmap(model, x, layer_index, class_index=None, n_masks=None,
                     relu=True):
    """ScoreCAM 热图（返回 ``(heatmap, weights)``）。

    用第 ``layer_index`` 层的每个通道上采样后**遮罩输入**，重新前向取目标类
    分数，再对分数做 softmax 得到通道权重。代价是 ``C`` 次额外前向，所以
    ``n_masks`` 可以只取权重最大的前几个通道。
    """
    modules = _cam_modules(model)
    idx = _cam_index(modules, layer_index, "scorecam_heatmap")
    acts, _ = _cam_logits(model, modules, x, idx)
    a = _cam_check_map(acts, "scorecam_heatmap")
    height, width = _cam_spatial(x)
    nchan = len(a)
    if n_masks is None:
        n_masks = nchan
    if not isinstance(n_masks, int) or isinstance(n_masks, bool):
        raise ValueError(f"scorecam_heatmap: n_masks 必须是整数，收到 {n_masks!r}")
    if not (1 <= n_masks <= nchan):
        raise ValueError(
            f"scorecam_heatmap: n_masks 必须在 [1, {nchan}] 内，收到 {n_masks}"
        )
    _, logits = _cam_logits(model, modules, x, idx)
    if class_index is None:
        best = 0
        for i in range(1, len(logits)):
            if logits[i] > logits[best]:
                best = i
        class_index = best
    if not isinstance(class_index, int) or isinstance(class_index, bool):
        raise ValueError(f"scorecam_heatmap: class_index 必须是整数，收到 {class_index!r}")
    if not (0 <= class_index < len(logits)):
        raise ValueError(
            f"scorecam_heatmap: class_index={class_index} 超出 logits 维度 {len(logits)}"
        )

    picked = list(range(nchan))[:n_masks]
    masks = []          # 每个被选通道的上采样遮罩
    scores = []
    for c in picked:
        up = _cam_upsample(a[c], height, width)
        masked = [[[x[ch][r][k] * up[r][k] for k in range(width)]
                   for r in range(height)] for ch in range(len(x))]
        a2 = masked
        for m in modules:
            a2 = m.forward(a2)
        masks.append(up)
        scores.append(a2[class_index])

    top = None
    for v in scores:
        if top is None or v > top:
            top = v
    exps = [0.0] * len(scores)
    if top is None:
        weights = [1.0 / len(scores)] * len(scores)
    else:
        total = 0.0
        for i, v in enumerate(scores):
            exps[i] = math.exp(v - top)
            total += exps[i]
        weights = [e / total for e in exps]

    heat = [[0.0] * width for _ in range(height)]
    for up, wc in zip(masks, weights):
        for r in range(height):
            for k in range(width):
                heat[r][k] += wc * up[r][k]
    if relu:
        heat = [[_cam_relu(v) for v in row] for row in heat]
    return _cam_normalize(heat), weights


def cam_ascii(heatmap, max_width=24):
    """把 [0,1] 热图渲染成 ASCII（复用 ``feature_maps_ascii`` 的字符表）。"""
    return feature_maps_ascii([heatmap], max_width=max_width)

#  可解释性：置换重要性 / 特征图字符画
# ============================================================================

def _w14c_rows(x, who):
    """校验样本矩阵：非空、每行等长、元素是有限数字。"""
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError(f"{who}: 样本不能为空")
    width = None
    rows = []
    for i, row in enumerate(x):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"{who}: 第 {i} 个样本必须是非空序列")
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError(
                f"{who}: 第 {i} 个样本有 {len(row)} 维，与首样本 {width} 维不一致")
        rows.append([_metric_number(v, who, i) for v in row])
    return rows


def permutation_importance(model, x, y, n_repeats=5, seed=None, metric=None,
                           names=None):
    """置换重要性：逐列打乱后指标掉了多少（掉得越多说明该列越重要）。

    `metric` 是 `(x, y) -> float` 的回调，默认用 `model.score`（分类准确率 /
    回归 R²，按 `model.task` 自动选）。返回 `{"baseline", "mean", "std", "names"}`，
    `mean[j]` 是「打乱第 j 列后指标下降量」在 `n_repeats` 次上的平均。
    """
    who = "permutation_importance"
    rows = _w14c_rows(x, who)
    if not isinstance(y, (list, tuple)) or not y:
        raise ValueError(f"{who}: y 不能为空")
    if len(y) != len(rows):
        raise ValueError(
            f"{who}: x 有 {len(rows)} 个样本，y 有 {len(y)} 个，数量必须一致")
    if isinstance(n_repeats, bool) or not isinstance(n_repeats, int):
        raise ValueError(f"{who}: n_repeats 必须是整数，收到 {n_repeats!r}")
    if n_repeats < 1:
        raise ValueError(f"{who}: n_repeats 必须 >= 1，收到 {n_repeats}")
    if metric is not None and not callable(metric):
        raise TypeError(f"{who}: metric 必须可调用")
    width = len(rows[0])
    if names is None:
        names = [f"f{j}" for j in range(width)]
    else:
        if not isinstance(names, (list, tuple)) or len(names) != width:
            raise ValueError(
                f"{who}: names 长度必须等于特征数 {width}")
        names = [str(n) for n in names]
    score = metric if metric is not None else (lambda xs, ys: model.score(xs, ys))
    baseline = float(score(rows, y))
    rng = random.Random(seed)
    means = []
    stds = []
    for j in range(width):
        drops = []
        for _ in range(n_repeats):
            order = list(range(len(rows)))
            rng.shuffle(order)
            col = [rows[i][j] for i in order]
            shuffled = [list(r) for r in rows]
            for i, v in enumerate(col):
                shuffled[i][j] = v
            drops.append(baseline - float(score(shuffled, y)))
        n = float(len(drops))
        mean = sum(drops) / n
        var = sum((d - mean) ** 2 for d in drops) / n
        means.append(mean)
        stds.append(math.sqrt(var))
    return {"baseline": baseline, "mean": means, "std": stds, "names": names}


def _w14c_map(m, who):
    """校验一张二维特征图。"""
    if not isinstance(m, (list, tuple)) or not m:
        raise ValueError(f"{who}: 特征图不能为空")
    width = None
    rows = []
    for i, row in enumerate(m):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"{who}: 第 {i} 行必须是非空序列")
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError(
                f"{who}: 第 {i} 行有 {len(row)} 列，与首行 {width} 列不一致")
        rows.append([_metric_number(v, who, i) for v in row])
    return rows


def _w14c_heat(m, max_width, peak=None):
    """把一张二维图压成字符画（块均值下采样 + 按峰值缩放）。"""
    h = len(m)
    w = len(m[0])
    step_h = max(1, (h + max_width - 1) // max_width)
    step_w = max(1, (w + max_width - 1) // max_width)
    if peak is None:
        peak = max(max(row) for row in m)
    out = []
    for i in range(0, h, step_h):
        chars = []
        for j in range(0, w, step_w):
            total = 0.0
            count = 0
            for a in range(i, min(i + step_h, h)):
                for b in range(j, min(j + step_w, w)):
                    total += m[a][b]
                    count += 1
            v = (total / count) if count else 0.0
            rel = (v / peak) if peak > 0.0 else 0.0
            if rel < 0.0:
                rel = 0.0
            elif rel > 1.0:
                rel = 1.0
            idx = int(rel * (len(_ATTN_RAMP) - 1) + 0.5)
            chars.append(_ATTN_RAMP[idx])
        out.append("".join(chars))
    return out


def feature_maps_ascii(maps, channels=None, max_width=24, max_channels=8):
    """把特征图画成字符热图：`(C, H, W)` 每通道一张，也接受单张 `H×W`。

    字符强度 `0-9` 按**每张图自身**的最大值缩放（负值截到 0）；`max_width`
    是每行最多多少个字符，块均值下采样。返回多行字符串。
    """
    who = "feature_maps_ascii"
    if isinstance(max_width, bool) or not isinstance(max_width, int):
        raise ValueError(f"{who}: max_width 必须是整数，收到 {max_width!r}")
    if max_width < 1:
        raise ValueError(f"{who}: max_width 必须 >= 1，收到 {max_width}")
    if isinstance(max_channels, bool) or not isinstance(max_channels, int):
        raise ValueError(f"{who}: max_channels 必须是整数，收到 {max_channels!r}")
    if max_channels < 1:
        raise ValueError(f"{who}: max_channels 必须 >= 1，收到 {max_channels}")
    if not isinstance(maps, (list, tuple)) or not maps:
        raise ValueError(f"{who}: maps 不能为空")
    first = maps[0]
    if not isinstance(first, (list, tuple)) or not first:
        raise ValueError(f"{who}: maps 的元素必须是二维列表")

    single = not isinstance(first[0], (list, tuple))
    if single:
        planes = [_w14c_map(maps, who)]
        labels = ["map"]
    else:
        planes = []
        for c, plane in enumerate(maps):
            if not isinstance(plane, (list, tuple)) or not plane:
                raise ValueError(f"{who}: 第 {c} 个通道为空")
            if not isinstance(plane[0], (list, tuple)):
                raise ValueError(f"{who}: 第 {c} 个通道不是二维")
            planes.append(_w14c_map(plane, who))
        labels = [f"channel {c}" for c in range(len(planes))]

    if channels is None:
        chosen = list(range(min(len(planes), max_channels)))
    else:
        if not isinstance(channels, (list, tuple)) or not channels:
            raise ValueError(f"{who}: channels 必须是非空列表")
        chosen = []
        for c in channels:
            if isinstance(c, bool) or not isinstance(c, int):
                raise ValueError(f"{who}: channels 里必须都是整数，收到 {c!r}")
            if c < 0 or c >= len(planes):
                raise ValueError(
                    f"{who}: 通道 {c} 越界（共 {len(planes)} 个）")
            chosen.append(c)

    lines = []
    for c in chosen:
        plane = planes[c]
        peak = max(max(row) for row in plane)
        lines.append(f"{labels[c]}  ({len(plane)}x{len(plane[0])}，峰值 {peak:.4g})")
        lines.extend(_w14c_heat(plane, max_width, peak))
        lines.append("")
    lines.append("强度：'" + _ATTN_RAMP.strip() + "' = 0 -> 1（每张图按自身最大值缩放）")
    return "\n".join(lines)

# ============================================================================
#  可解释性：注意力 Rollout / Flow
# ============================================================================

def _w14b_mul(a, b):
    """方阵乘法（T×T）。"""
    n = len(a)
    return [[sum(a[i][k] * b[k][j] for k in range(n)) for j in range(n)]
            for i in range(n)]


def _w14b_fuse(maps, fusion, who):
    """把 `heads × T × T` 融成一张 `T × T`。"""
    if not maps:
        raise ValueError(f"{who}: 注意力图为空")
    heads = len(maps)
    n = len(maps[0])
    out = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            col = [maps[h][i][j] for h in range(heads)]
            if fusion == "mean":
                out[i][j] = sum(col) / float(heads)
            elif fusion == "max":
                out[i][j] = max(col)
            else:
                out[i][j] = min(col)
    return out


def _w14b_matrix(m, who, tag):
    if not isinstance(m, (list, tuple)) or not m:
        raise ValueError(f"{who}: {tag} 必须是非空方阵")
    n = len(m)
    rows = []
    for i, row in enumerate(m):
        if not isinstance(row, (list, tuple)) or len(row) != n:
            raise ValueError(f"{who}: {tag} 第 {i} 行长度应为 {n}")
        rows.append([_metric_number(v, who, i) for v in row])
        if any(v < 0.0 for v in rows[i]):
            raise ValueError(f"{who}: {tag} 第 {i} 行含负权重")
    return rows


def _w14b_discard(m, ratio, who):
    """按行丢掉最小的 `ratio` 比例的权重，再按行重新归一化。"""
    if ratio <= 0.0:
        return [list(row) for row in m]
    n = len(m)
    drop = int(n * ratio)
    if drop <= 0:
        return [list(row) for row in m]
    out = []
    for i, row in enumerate(m):
        order = sorted(range(n), key=lambda j: (row[j], j))
        kept = [0.0] * n
        for j in order[drop:]:
            kept[j] = row[j]
        total = sum(kept)
        if total <= 0.0:
            raise ValueError(
                f"{who}: 第 {i} 行在 discard_ratio={ratio} 下被清空")
        out.append([v / total for v in kept])
    return out


def _w14b_layers(attentions, who, head_fusion):
    """把多种输入形态统一成「每层一张 T×T」。"""
    if head_fusion not in ("mean", "max", "min"):
        raise ValueError(
            f"{who}: head_fusion 必须是 mean/max/min，收到 {head_fusion!r}")
    if isinstance(attentions, dict):
        if "layers" in attentions:
            items = [entry["maps"] for entry in attentions["layers"]]
        elif "maps" in attentions:
            items = [attentions["maps"]]
        else:
            raise ValueError(f"{who}: 字典输入需要 'maps' 或 'layers' 键")
    elif isinstance(attentions, (list, tuple)):
        items = list(attentions)
    else:
        raise TypeError(f"{who}: attentions 必须是列表或 attention_maps 的返回值")
    if not items:
        raise ValueError(f"{who}: 至少需要一层的注意力")
    layers = []
    seq = None
    for k, item in enumerate(items):
        if isinstance(item, dict) and "maps" in item:
            item = item["maps"]
        if not isinstance(item, (list, tuple)) or not item:
            raise ValueError(f"{who}: 第 {k} 层注意力为空")
        first = item[0]
        if isinstance(first, (list, tuple)) and first \
                and isinstance(first[0], (list, tuple)):
            mat = _w14b_fuse(item, head_fusion, who)
        else:
            mat = _w14b_matrix(item, who, f"第 {k} 层")
        if seq is None:
            seq = len(mat)
        elif len(mat) != seq:
            raise ValueError(
                f"{who}: 第 {k} 层的序列长度 {len(mat)} 与首层 {seq} 不一致")
        layers.append(mat)
    return layers


def _w14b_check_ratio(discard_ratio, who):
    ratio = _metric_number(discard_ratio, who, 0)
    if ratio < 0.0 or ratio >= 1.0:
        raise ValueError(
            f"{who}: discard_ratio 必须在 [0, 1) 内，收到 {ratio}")
    return ratio


def attention_rollout(attentions, head_fusion="mean", discard_ratio=0.0):
    """Attention Rollout：把各层注意力连乘，近似「每条路径被平均后的贡献」。

    `attentions` 可以是「每层一张 `T×T`」的列表、每层「`heads×T×T`」的列表，
    或 `attention_maps` 的返回值。每层做 `Ã = 0.5·A + 0.5·I`（给残差留通路），
    然后 `R = Ã_L · … · Ã_1`。返回 `T×T`，第 `t` 行是位置 `t` 对各源位置的
    归一化贡献（行和为 1）。
    """
    who = "attention_rollout"
    ratio = _w14b_check_ratio(discard_ratio, who)
    layers = _w14b_layers(attentions, who, head_fusion)
    n = len(layers[0])
    result = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    for k, mat in enumerate(layers):
        m = _w14b_discard(mat, ratio, who)
        mixed = [[0.5 * m[i][j] + (0.5 if i == j else 0.0) for j in range(n)]
                 for i in range(n)]
        result = _w14b_mul(mixed, result)
    return result


def attention_flow(attentions, head_fusion="mean", discard_ratio=0.0):
    """Attention Flow（简化版）：按**列**归一化后连乘，保持「影响力守恒」。

    与 Rollout 的区别：Rollout 每层按行归一（平均路径），Flow 把每层的
    `A` 除以列和再作用到上一层的流上，使每个源位置收到的总影响力守恒。
    这里不含论文里的梯度项，docstring 明确这是简化版。
    """
    who = "attention_flow"
    ratio = _w14b_check_ratio(discard_ratio, who)
    layers = _w14b_layers(attentions, who, head_fusion)
    n = len(layers[0])
    flow = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    for k, mat in enumerate(layers):
        m = _w14b_discard(mat, ratio, who)
        col = [sum(m[i][j] for i in range(n)) for j in range(n)]
        norm = [[(m[i][j] / col[j]) if col[j] > 0.0 else 1.0 / n
                 for j in range(n)] for i in range(n)]
        flow = _w14b_mul(norm, flow)
    return flow

# ============================================================================
#  可解释性：输入归因
# ============================================================================

def _attr_x(x, who):
    """校验归因输入：非空、扁平、元素是有限数字。"""
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError(f"{who}: x 不能为空")
    out = []
    for i, v in enumerate(x):
        if isinstance(v, (list, tuple)):
            raise ValueError(
                f"{who}: x 必须是单样本扁平向量（第 {i} 个是嵌套列表）")
        out.append(_metric_number(v, who, i))
    return out


def _attr_net(model, who):
    """取出真正的前向网络（`Model` 包装器则取 `.model`）。"""
    net = getattr(model, "model", model)
    layers = getattr(net, "layers", None)
    if layers is None:
        raise TypeError(f"{who}: 需要 MLP 或 Model 包装的 MLP，收到 {type(model).__name__}")
    return net


def _attr_target(pred, class_index, who):
    """目标类：省略时取 argmax；否则校验是非负整数且在范围内。"""
    if class_index is None:
        best = 0
        for i in range(1, len(pred)):
            if pred[i] > pred[best]:
                best = i
        return best
    c = _metric_label(class_index, who, 0)
    if c >= len(pred):
        raise ValueError(
            f"{who}: class_index={c} 越界（输出维度 {len(pred)}）")
    return c


def _attr_grad(net, x, c, who):
    """目标类 logit 对输入的梯度（通过一次前向 + 反向链传到底）。"""
    pred = net.forward(x)
    if len(pred) <= c:
        raise ValueError(f"{who}: 输出维度 {len(pred)} 不足以取第 {c} 类")
    delta = [0.0] * len(pred)
    delta[c] = 1.0
    for layer in reversed(net.layers):
        _, _, delta = layer.backward(delta)
    return delta


def saliency_map(model, x, class_index=None, absolute=True):
    """Saliency：目标类 logit 对输入的梯度（`|∂y_c/∂x_i|`，可关掉绝对值）。"""
    who = "saliency_map"
    net = _attr_net(model, who)
    xs = _attr_x(x, who)
    c = _attr_target(net.forward(xs), class_index, who)
    grad = _attr_grad(net, xs, c, who)
    return [abs(g) for g in grad] if absolute else list(grad)


def gradient_x_input(model, x, class_index=None):
    """Gradient×Input：`x_i · ∂y_c/∂x_i`（保留符号）。"""
    who = "gradient_x_input"
    net = _attr_net(model, who)
    xs = _attr_x(x, who)
    c = _attr_target(net.forward(xs), class_index, who)
    grad = _attr_grad(net, xs, c, who)
    return [xi * gi for xi, gi in zip(xs, grad)]


def smooth_grad(model, x, samples=50, sigma=0.1, seed=None, class_index=None):
    """SmoothGrad：对 `N(x, σ²)` 采样得到的梯度取平均，压低高频噪声。"""
    who = "smooth_grad"
    net = _attr_net(model, who)
    xs = _attr_x(x, who)
    if isinstance(samples, bool) or not isinstance(samples, int):
        raise ValueError(f"{who}: samples 必须是整数，收到 {samples!r}")
    if samples < 1:
        raise ValueError(f"{who}: samples 必须 >= 1，收到 {samples}")
    sigma = _metric_number(sigma, who, 0)
    if sigma < 0.0:
        raise ValueError(f"{who}: sigma 必须 >= 0，收到 {sigma}")
    c = _attr_target(net.forward(xs), class_index, who)
    rng = random.Random(seed)
    total = [0.0] * len(xs)
    for _ in range(samples):
        noisy = [xi + rng.gauss(0.0, sigma) for xi in xs]
        grad = _attr_grad(net, noisy, c, who)
        for i in range(len(total)):
            total[i] += grad[i]
    return [t / float(samples) for t in total]


def integrated_gradients(model, x, baseline=None, steps=64, class_index=None):
    """Integrated Gradients：沿 `baseline → x` 直线做中点黎曼平均再乘位移。

    满足完备性 `Σ attribution ≈ f(x) − f(baseline)`（在 `steps` 足够时）。
    """
    who = "integrated_gradients"
    net = _attr_net(model, who)
    xs = _attr_x(x, who)
    if baseline is None:
        base = [0.0] * len(xs)
    else:
        base = _attr_x(baseline, who)
        if len(base) != len(xs):
            raise ValueError(
                f"{who}: baseline 长度 {len(base)} 与 x 长度 {len(xs)} 不一致")
    if isinstance(steps, bool) or not isinstance(steps, int):
        raise ValueError(f"{who}: steps 必须是整数，收到 {steps!r}")
    if steps < 1:
        raise ValueError(f"{who}: steps 必须 >= 1，收到 {steps}")
    c = _attr_target(net.forward(xs), class_index, who)
    total = [0.0] * len(xs)
    for k in range(steps):
        scale = (k + 0.5) / float(steps)
        point = [b + scale * (xi - b) for xi, b in zip(xs, base)]
        grad = _attr_grad(net, point, c, who)
        for i in range(len(total)):
            total[i] += grad[i]
    return [(xi - b) * t / float(steps) for xi, b, t in zip(xs, base, total)]


def _attr_supported_activation(layer):
    """DeepLIFT 的 rescale 规则要求逐元素激活。"""
    return layer.activation_name in ("linear", "relu", "leaky_relu", "gelu",
                                     "silu", "mish", "elu", "selu", "sigmoid")


def _attr_trace(net, x):
    """手工前向，返回每层的 `(z, a)`（`Layer.forward` 只留最后一次缓存）。"""
    zs = []
    acts = []
    cur = list(x)
    for layer in net.layers:
        z = [layer.biases[j]
             + sum(layer.weights[j][i] * cur[i] for i in range(layer.fan_in))
             for j in range(layer.fan_out)]
        a = layer.act_fn(z)
        zs.append(z)
        acts.append(a)
        cur = a
    return zs, acts


def deep_lift(model, x, baseline=None, class_index=None, eps=1e-12):
    """DeepLIFT（Rescale 规则）：用 `Δa/Δz` 乘子把输出差回传到输入。

    只支持逐元素激活（`softmax` 之类的非对角激活会报错）。`Δz` 接近 0 时
    用该点导数代替（论文里 `δ→0` 的极限近似），这会在 docstring 之外的多层
    非线性上带来小的数值差异；对线性网络与 ReLU 网络都是精确的。
    """
    who = "deep_lift"
    net = _attr_net(model, who)
    xs = _attr_x(x, who)
    if baseline is None:
        base = [0.0] * len(xs)
    else:
        base = _attr_x(baseline, who)
        if len(base) != len(xs):
            raise ValueError(
                f"{who}: baseline 长度 {len(base)} 与 x 长度 {len(xs)} 不一致")
    eps = _metric_number(eps, who, 0)
    if eps <= 0.0:
        raise ValueError(f"{who}: eps 必须 > 0，收到 {eps}")
    for layer in net.layers:
        if not _attr_supported_activation(layer):
            raise ValueError(
                f"{who}: 第 {net.layers.index(layer)} 层激活 "
                f"{layer.activation_name!r} 不是逐元素激活，Rescale 规则不适用")
    zs_x, acts_x = _attr_trace(net, xs)
    zs_b, acts_b = _attr_trace(net, base)
    c = _attr_target(acts_x[-1], class_index, who)
    mult = [0.0] * len(acts_x[-1])
    mult[c] = 1.0
    for l in range(len(net.layers) - 1, -1, -1):
        layer = net.layers[l]
        za = zs_x[l]
        zb = zs_b[l]
        deriv = layer.act_deriv(zb)
        slope = []
        for j in range(layer.fan_out):
            dz = za[j] - zb[j]
            if abs(dz) > eps:
                slope.append((acts_x[l][j] - acts_b[l][j]) / dz)
            else:
                slope.append(deriv[j])
        mz = [mult[j] * slope[j] for j in range(layer.fan_out)]
        mult = [sum(mz[j] * layer.weights[j][i] for j in range(layer.fan_out))
                for i in range(layer.fan_in)]
    return [mult[i] * (xs[i] - base[i]) for i in range(len(xs))]


def fleiss_kappa(ratings, categories=None) -> float:
    """Fleiss' Kappa：多名评分者对同一批对象做**固定类别**标注的一致性。

    `ratings` 行=对象、列=评分者，每行评分者数必须相同且不能有缺失；
    `(P_bar - P_e) / (1 - P_e)`，1 为完全一致。
    """
    who = "fleiss_kappa"
    rows, width = _cf_matrix(ratings, who, allow_none=False)
    if width < 2:
        raise ValueError(f"{who}: 至少需要 2 名评分者，收到 {width}")
    if len(rows) < 1:
        raise ValueError(f"{who}: 至少要有一个评分对象")
    if categories is None:
        seen = set()
        for row in rows:
            seen.update(row)
        categories = sorted(seen)
    else:
        if not isinstance(categories, (list, tuple)) or not categories:
            raise ValueError(f"{who}: categories 必须是非空列表")
        categories = [_metric_label(v, who, i) for i, v in enumerate(categories)]
        if len(set(categories)) != len(categories):
            raise ValueError(f"{who}: categories 有重复值")
    index = {}
    for k, cat in enumerate(categories):
        index[cat] = k
    n_cat = len(categories)
    totals = [0] * n_cat
    p_items = []
    n = float(width)
    for i, row in enumerate(rows):
        counts = [0] * n_cat
        for v in row:
            if v not in index:
                raise ValueError(
                    f"{who}: 第 {i} 行出现未声明的类别 {v!r}")
            counts[index[v]] += 1
        for k in range(n_cat):
            totals[k] += counts[k]
        sq = sum(c * c for c in counts)
        p_items.append((sq - n) / (n * (n - 1.0)))
    p_bar = sum(p_items) / float(len(p_items))
    total = sum(totals)
    p_e = sum((t / float(total)) ** 2 for t in totals)
    if abs(1.0 - p_e) <= 1e-15:
        raise ValueError(f"{who}: 所有评分都落在同一类别，kappa 无定义")
    return (p_bar - p_e) / (1.0 - p_e)


def _kr_delta(level, c, k, counts):
    """Krippendorff 的距离函数 δ²(c, k)。"""
    if c == k:
        return 0.0
    if level == "nominal":
        return 1.0
    if level == "interval":
        return float((c - k) ** 2)
    lo, hi = (c, k) if c < k else (k, c)
    s = 0.0
    for g in range(lo, hi + 1):
        s += counts[g]
    s -= (counts[lo] + counts[hi]) / 2.0
    return s * s


def krippendorff_alpha(ratings, level: str = "nominal") -> float:
    """Krippendorff's Alpha：允许**缺失值**与不同对象评分者数不同的一致性。

    `ratings` 行=对象、列=评分者，缺失写 `None`；`level` 支持
    `'nominal'` / `'ordinal'` / `'interval'`。`1 - D_o/D_e`，1 为完全一致。
    """
    who = "krippendorff_alpha"
    if level not in ("nominal", "ordinal", "interval"):
        raise ValueError(
            f"{who}: level 必须是 nominal/ordinal/interval，收到 {level!r}")
    rows, width = _cf_matrix(ratings, who, allow_none=True)
    values = set()
    pairable = 0
    for row in rows:
        present = [v for v in row if v is not None]
        if len(present) >= 2:
            pairable += len(present)
        values.update(present)
    if len(values) < 2:
        raise ValueError(f"{who}: 至少需要 2 个不同类别才能算 Alpha")
    codes = sorted(values)
    index = {}
    for k, code in enumerate(codes):
        index[code] = k
    n_cat = len(codes)
    coincidence = [[0.0] * n_cat for _ in range(n_cat)]
    n_total = 0.0
    for i, row in enumerate(rows):
        present = [v for v in row if v is not None]
        m = len(present)
        if m < 2:
            continue
        share = 1.0 / (m - 1.0)
        for a in range(m):
            for b in range(m):
                if a == b:
                    continue
                coincidence[index[present[a]]][index[present[b]]] += share
        n_total += m
    if n_total <= 0.0:
        raise ValueError(f"{who}: 没有任何对象被至少两名评分者标注")
    counts = [sum(coincidence[k]) for k in range(n_cat)]
    sum_o = 0.0
    for c in range(n_cat):
        for k in range(n_cat):
            d = _kr_delta(level, c, k, counts)
            if d != 0.0:
                sum_o += coincidence[c][k] * d
    d_o = sum_o / n_total
    sum_e = 0.0
    denom = n_total * (n_total - 1.0)
    for c in range(n_cat):
        for k in range(n_cat):
            d = _kr_delta(level, c, k, counts)
            if d != 0.0:
                sum_e += counts[c] * counts[k] * d
    d_e = sum_e / denom
    if d_e <= 0.0:
        raise ValueError(f"{who}: 期望分歧为 0（所有值同类），Alpha 无定义")
    return 1.0 - d_o / d_e


def _fair_check(y, sensitive, who, tag):
    if not isinstance(y, (list, tuple)) or not y:
        raise ValueError(f"{who}: {tag} 不能为空")
    if not isinstance(sensitive, (list, tuple)):
        raise ValueError(f"{who}: sensitive 必须是列表")
    if len(y) != len(sensitive):
        raise ValueError(
            f"{who}: {tag} 有 {len(y)} 个样本，sensitive 有 {len(sensitive)} 个")
    return list(y), list(sensitive)


def _fair_groups(sensitive, who):
    groups = {}
    for i, g in enumerate(sensitive):
        if isinstance(g, (list, tuple, dict)):
            raise ValueError(f"{who}: sensitive[{i}] 必须是可哈希的标量")
        groups.setdefault(g, []).append(i)
    if len(groups) < 2:
        raise ValueError(f"{who}: 至少需要 2 个分组，收到 {len(groups)}")
    return groups


def _fair_rate(y, idx, positive, who):
    hits = 0
    for i in idx:
        v = _metric_label(y[i], who, i)
        if v == positive:
            hits += 1
    return hits / float(len(idx))


def demographic_parity_difference(y_pred, sensitive, positive_label: int = 1) -> float:
    """人口统计均等差：各分组正预测率的 `max − min`（0 为完全均等）。"""
    who = "demographic_parity_difference"
    y, s = _fair_check(y_pred, sensitive, who, "y_pred")
    groups = _fair_groups(s, who)
    pos = _metric_label(positive_label, who, 0)
    rates = [_fair_rate(y, idx, pos, who) for idx in groups.values()]
    return max(rates) - min(rates)


def equal_opportunity_difference(y_true, y_pred, sensitive,
                                 positive_label: int = 1) -> float:
    """机会均等差：各分组**真阳率**的 `max − min`；无正样本的分组被跳过。"""
    who = "equal_opportunity_difference"
    yt, s1 = _fair_check(y_true, sensitive, who, "y_true")
    yp, s2 = _fair_check(y_pred, sensitive, who, "y_pred")
    groups = _fair_groups(s1, who)
    pos = _metric_label(positive_label, who, 0)
    tprs = []
    for idx in groups.values():
        positives = [i for i in idx
                     if _metric_label(yt[i], who, i) == pos]
        if not positives:
            continue
        hit = sum(1 for i in positives
                  if _metric_label(yp[i], who, i) == pos)
        tprs.append(hit / float(len(positives)))
    if len(tprs) < 2:
        raise ValueError(
            f"{who}: 只有 {len(tprs)} 个分组含正样本，无法比较机会均等")
    return max(tprs) - min(tprs)


def disparate_impact_ratio(y_pred, sensitive, positive_label: int = 1) -> float:
    """差别影响比：各分组正预测率的 `min / max`（0.8 以下常被视为有问题）。"""
    who = "disparate_impact_ratio"
    y, s = _fair_check(y_pred, sensitive, who, "y_pred")
    groups = _fair_groups(s, who)
    pos = _metric_label(positive_label, who, 0)
    rates = [_fair_rate(y, idx, pos, who) for idx in groups.values()]
    hi = max(rates)
    if hi <= 0.0:
        raise ValueError(f"{who}: 所有分组的正预测率都是 0，比值无定义")
    return min(rates) / hi


def equalized_odds_difference(y_true, y_pred, sensitive,
                              positive_label: int = 1) -> float:
    """均等化胜率差：各分组 TPR 差与 FPR 差中的最大值（0 为完全均等）。"""
    who = "equalized_odds_difference"
    yt, s1 = _fair_check(y_true, sensitive, who, "y_true")
    yp, s2 = _fair_check(y_pred, sensitive, who, "y_pred")
    groups = _fair_groups(s1, who)
    pos = _metric_label(positive_label, who, 0)
    tprs = []
    fprs = []
    for idx in groups.values():
        positives = [i for i in idx
                     if _metric_label(yt[i], who, i) == pos]
        negatives = [i for i in idx
                     if _metric_label(yt[i], who, i) != pos]
        if positives:
            hit = sum(1 for i in positives
                      if _metric_label(yp[i], who, i) == pos)
            tprs.append(hit / float(len(positives)))
        if negatives:
            hit = sum(1 for i in negatives
                      if _metric_label(yp[i], who, i) == pos)
            fprs.append(hit / float(len(negatives)))
    gaps = []
    if len(tprs) >= 2:
        gaps.append(max(tprs) - min(tprs))
    if len(fprs) >= 2:
        gaps.append(max(fprs) - min(fprs))
    if not gaps:
        raise ValueError(
            f"{who}: 分组内正/负样本不足，无法比较均等化胜率")
    return max(gaps)


def group_calibration_error(y_true, y_proba, sensitive, n_bins: int = 10,
                            strategy: str = "uniform") -> float:
    """分组校准差：各分组 ECE 的 `max − min`（0 为各组校准一致）。"""
    who = "group_calibration_error"
    yt, s1 = _fair_check(y_true, sensitive, who, "y_true")
    rows, classes = _proba_rows(y_proba, who)
    if len(rows) != len(yt):
        raise ValueError(f"{who}: y_proba 行数 {len(rows)} 与标签数 {len(yt)} 不同")
    groups = _fair_groups(s1, who)
    eces = []
    for idx in groups.values():
        sub_y = [yt[i] for i in idx]
        if len(rows[0]) == 1:
            sub_p = [[1.0 - rows[i][0], rows[i][0]] for i in idx]
        else:
            sub_p = [list(rows[i]) for i in idx]
        eces.append(
            expected_calibration_error(sub_y, sub_p, n_bins, strategy))
    if len(eces) < 2:
        raise ValueError(f"{who}: 至少需要 2 个分组")
    return max(eces) - min(eces)


def psnr_score(a, b, data_range: float = 1.0) -> float:
    """PSNR = `10*log10(range²/MSE)`；完全相同时返回 `inf`。"""
    who = "psnr_score"
    rng = _img_range(data_range, who)
    ia, ib = _img_check(a, b, who)
    total = 0.0
    count = 0
    for ca, cb in zip(ia, ib):
        for ra, rb in zip(ca, cb):
            for va, vb in zip(ra, rb):
                d = va - vb
                total += d * d
                count += 1
    mse = total / float(count)
    if mse <= 0.0:
        return float("inf")
    return 10.0 * math.log10(rng * rng / mse)


def _img_channel_stats(ia, ib):
    """返回 (mean_a, mean_b, var_a, var_b, cov, n)。"""
    total_n = 0
    sum_a = 0.0
    sum_b = 0.0
    for ca, cb in zip(ia, ib):
        for ra, rb in zip(ca, cb):
            for va, vb in zip(ra, rb):
                sum_a += va
                sum_b += vb
                total_n += 1
    mean_a = sum_a / total_n
    mean_b = sum_b / total_n
    var_a = 0.0
    var_b = 0.0
    cov = 0.0
    for ca, cb in zip(ia, ib):
        for ra, rb in zip(ca, cb):
            for va, vb in zip(ra, rb):
                da = va - mean_a
                db = vb - mean_b
                var_a += da * da
                var_b += db * db
                cov += da * db
    var_a /= total_n
    var_b /= total_n
    cov /= total_n
    return mean_a, mean_b, var_a, var_b, cov, total_n


def _ssim_global(ia, ib, rng):
    """无窗口时的全局 SSIM（小图或 win_size 覆盖整幅图）。"""
    mean_a, mean_b, var_a, var_b, cov, _ = _img_channel_stats(ia, ib)
    c1 = (0.01 * rng) ** 2
    c2 = (0.03 * rng) ** 2
    return ((2 * mean_a * mean_b + c1) * (2 * cov + c2)) / \
        ((mean_a * mean_a + mean_b * mean_b + c1) * (var_a + var_b + c2))


def ssim_score(a, b, data_range: float = 1.0, win_size: int = 7) -> float:
    """SSIM：均匀窗口（box）的均值，通道间再平均。

    窗口比图像大时退化为全局统计（README 有说明）；不做高斯加权。
    """
    who = "ssim_score"
    rng = _img_range(data_range, who)
    if isinstance(win_size, bool) or not isinstance(win_size, int):
        raise ValueError(f"{who}: win_size 必须是整数")
    if win_size < 1:
        raise ValueError(f"{who}: win_size 必须 >= 1，收到 {win_size}")
    ia, ib = _img_check(a, b, who)
    height = len(ia[0])
    width = len(ia[0][0])
    if win_size >= height or win_size >= width:
        return _ssim_global(ia, ib, rng)
    c1 = (0.01 * rng) ** 2
    c2 = (0.03 * rng) ** 2
    total = 0.0
    windows = 0
    for ca, cb in zip(ia, ib):
        for r0 in range(height - win_size + 1):
            for c0 in range(width - win_size + 1):
                n = float(win_size * win_size)
                sa = 0.0
                sb = 0.0
                for dr in range(win_size):
                    for dc in range(win_size):
                        sa += ca[r0 + dr][c0 + dc]
                        sb += cb[r0 + dr][c0 + dc]
                ma = sa / n
                mb = sb / n
                va = 0.0
                vb = 0.0
                cv = 0.0
                for dr in range(win_size):
                    for dc in range(win_size):
                        da = ca[r0 + dr][c0 + dc] - ma
                        db = cb[r0 + dr][c0 + dc] - mb
                        va += da * da
                        vb += db * db
                        cv += da * db
                va /= n
                vb /= n
                cv /= n
                num = (2 * ma * mb + c1) * (2 * cv + c2)
                den = (ma * ma + mb * mb + c1) * (va + vb + c2)
                total += num / den
                windows += 1
    return total / float(windows)


def _img_downsample(img):
    """2×2 平均池化（尺寸为奇数时丢掉最后一行/列）。"""
    out = []
    for ch in img:
        h = len(ch) // 2
        w = len(ch[0]) // 2
        rows = []
        for r in range(h):
            row = []
            for c in range(w):
                s = ch[2 * r][2 * c] + ch[2 * r][2 * c + 1] + \
                    ch[2 * r + 1][2 * c] + ch[2 * r + 1][2 * c + 1]
                row.append(s / 4.0)
            rows.append(row)
        out.append(rows)
    return out


def ms_ssim_score(a, b, data_range: float = 1.0,
                  weights=(0.0448, 0.2856, 0.3001, 0.2363, 0.1333)) -> float:
    """MS-SSIM：多尺度对比度-结构项连乘，最后一级再乘亮度项。

    每级用 2×2 平均池化下采样；图像太小时会**减少级数并重新归一化权重**。
    """
    who = "ms_ssim_score"
    rng = _img_range(data_range, who)
    if not isinstance(weights, (list, tuple)) or not weights:
        raise ValueError(f"{who}: weights 必须是非空列表")
    ws = []
    for i, w in enumerate(weights):
        v = _metric_number(w, f"{who}.weights", i)
        if v <= 0.0:
            raise ValueError(f"{who}: weights[{i}] 必须 > 0，收到 {v}")
        ws.append(v)
    ia, ib = _img_check(a, b, who)
    levels = len(ws)
    cur_a = ia
    cur_b = ib
    used = 0
    cs_terms = []
    last_lum = None
    c1 = (0.01 * rng) ** 2
    c2 = (0.03 * rng) ** 2
    for level in range(levels):
        mean_a, mean_b, var_a, var_b, cov, _ = _img_channel_stats(cur_a, cur_b)
        lum = (2 * mean_a * mean_b + c1) / (mean_a * mean_a + mean_b * mean_b + c1)
        cs = (2 * cov + c2) / (var_a + var_b + c2)
        last_lum = lum
        cs_terms.append(cs)
        used += 1
        h = len(cur_a[0])
        w = len(cur_a[0][0])
        if h < 4 or w < 4:
            break
        cur_a = _img_downsample(cur_a)
        cur_b = _img_downsample(cur_b)
    total_w = sum(ws[:used])
    norm = [w / total_w for w in ws[:used]]
    out = 1.0
    for i, cs in enumerate(cs_terms):
        if i == used - 1:
            out *= (cs ** norm[i]) * (last_lum ** norm[i])
        else:
            out *= cs ** norm[i]
    return out


def _feat_check(features, who, tag):
    if not isinstance(features, (list, tuple)) or not features:
        raise ValueError(f"{who}: {tag} 不能为空")
    rows = []
    width = None
    for i, row in enumerate(features):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"{who}: {tag}[{i}] 必须是非空列表")
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError(f"{who}: {tag}[{i}] 维度 {len(row)} 与首个 {width} 不同")
        rows.append([_metric_number(v, f"{who}.{tag}[{i}]", j)
                     for j, v in enumerate(row)])
    return rows, width


def _feat_stats(rows):
    n = len(rows)
    dim = len(rows[0])
    mean = [sum(r[d] for r in rows) / float(n) for d in range(dim)]
    cov = [[0.0] * dim for _ in range(dim)]
    denom = float(n - 1) if n > 1 else 1.0
    for r in rows:
        diff = [r[d] - mean[d] for d in range(dim)]
        for i in range(dim):
            di = diff[i]
            row_i = cov[i]
            for j in range(i, dim):
                row_i[j] += di * diff[j]
    for i in range(dim):
        for j in range(i, dim):
            v = cov[i][j] / denom
            cov[i][j] = v
            cov[j][i] = v
    return mean, cov, n, dim


def _sym_sqrt_trace(m):
    """对称半正定矩阵的 `trace(m^{1/2})`（Jacobi 特征分解）。"""
    vals, _ = _jacobi_eigh(m)
    return sum(math.sqrt(v) for v in vals if v > 0.0)


def _mat_mul_sym(a, b):
    n = len(a)
    out = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            s = 0.0
            for k in range(n):
                s += a[i][k] * b[k][j]
            out[i][j] = s
    return out


def _mat_add(a, b, sign=1.0):
    n = len(a)
    return [[a[i][j] + sign * b[i][j] for j in range(n)] for i in range(n)]


def fid_score(features_a, features_b, max_dim: int = 128) -> float:
    """简化 FID：`‖μa−μb‖² + tr(Σa+Σb−2(Σa Σb)^{1/2})`，直接吃特征向量。

    不做 Inception 前向（本库没有预训练网络），也**不做**协方差的样本量校正。
    """
    who = "fid_score"
    ra, dim_a = _feat_check(features_a, who, "features_a")
    rb, dim_b = _feat_check(features_b, who, "features_b")
    if dim_a != dim_b:
        raise ValueError(f"{who}: 特征维度不同（{dim_a} vs {dim_b}）")
    if isinstance(max_dim, bool) or not isinstance(max_dim, int):
        raise ValueError(f"{who}: max_dim 必须是整数")
    if dim_a > max_dim:
        raise ValueError(
            f"{who}: 特征维度 {dim_a} 超过 max_dim={max_dim}；"
            "请先用 AI.PCA 降维（协方差矩阵是 dim×dim，维度过大不实用）")
    if len(ra) < 2 or len(rb) < 2:
        raise ValueError(f"{who}: 每组至少需要 2 个样本才能估协方差")
    ma, ca, _, _ = _feat_stats(ra)
    mb, cb, _, _ = _feat_stats(rb)
    mean_diff = sum((ma[d] - mb[d]) ** 2 for d in range(dim_a))
    # (Σa Σb) 有 (Σb^{1/2} Σa Σb^{1/2}) 相同的特征值，故可用对称形式取迹
    sqrt_b = [[0.0] * dim_a for _ in range(dim_a)]
    vals, vecs = _jacobi_eigh(cb)
    for k, lam in enumerate(vals):
        if lam <= 0.0:
            continue
        r = math.sqrt(lam)
        for i in range(dim_a):
            for j in range(dim_a):
                sqrt_b[i][j] += r * vecs[i][k] * vecs[j][k]
    inner = _mat_mul_sym(_mat_mul_sym(sqrt_b, ca), sqrt_b)
    cross = _sym_sqrt_trace(inner)
    tr_a = sum(ca[i][i] for i in range(dim_a))
    tr_b = sum(cb[i][i] for i in range(dim_a))
    return mean_diff + tr_a + tr_b - 2.0 * cross


def _rbf_kernel(x, y, sigma):
    s = 0.0
    for a, b in zip(x, y):
        d = a - b
        s += d * d
    return math.exp(-s / (2.0 * sigma * sigma))


def kid_score(features_a, features_b) -> float:
    """简化 KID：RBF 核的无偏 MMD²（`sigma` 取两组间成对距离的中位数）。

    返回的是 MMD² 本身；官方 KID 常乘 1000，README 已说明。
    无偏估计在小样本上**可能给出负值**（两组几乎相同时是正常的采样噪声），
    需要非负值时请自行 `max(value, 0.0)`。
    """
    who = "kid_score"
    ra, dim_a = _feat_check(features_a, who, "features_a")
    rb, dim_b = _feat_check(features_b, who, "features_b")
    if dim_a != dim_b:
        raise ValueError(f"{who}: 特征维度不同（{dim_a} vs {dim_b}）")
    if len(ra) < 2 or len(rb) < 2:
        raise ValueError(f"{who}: 每组至少需要 2 个样本才能算无偏 MMD")
    dists = []
    for x in ra:
        for y in rb:
            d = math.sqrt(sum((p - q) ** 2 for p, q in zip(x, y)))
            dists.append(d)
    dists.sort()
    sigma = dists[len(dists) // 2]
    if sigma <= 0.0:
        sigma = 1.0
    n = len(ra)
    m = len(rb)
    sum_aa = 0.0
    for i in range(n):
        for j in range(n):
            if i != j:
                sum_aa += _rbf_kernel(ra[i], ra[j], sigma)
    sum_bb = 0.0
    for i in range(m):
        for j in range(m):
            if i != j:
                sum_bb += _rbf_kernel(rb[i], rb[j], sigma)
    sum_ab = 0.0
    for x in ra:
        for y in rb:
            sum_ab += _rbf_kernel(x, y, sigma)
    return (sum_aa / float(n * (n - 1)) + sum_bb / float(m * (m - 1)) -
            2.0 * sum_ab / float(n * m))


def inception_score(probs, eps: float = 1e-12) -> float:
    """Inception Score：`exp(mean_i KL(p(y|x_i) ‖ p(y)))`，`probs` 是概率行。"""
    who = "inception_score"
    if isinstance(eps, bool) or not isinstance(eps, (int, float)):
        raise ValueError(f"{who}: eps 必须是数字")
    if not 0.0 < float(eps) < 1.0:
        raise ValueError(f"{who}: eps 必须在 (0, 1)，收到 {eps}")
    rows, width = _feat_check(probs, who, "probs")
    for i, row in enumerate(rows):
        for j, v in enumerate(row):
            if v < 0.0:
                raise ValueError(f"{who}: probs[{i}][{j}] = {v} 为负")
            if v > 1.0 + 1e-9:
                raise ValueError(f"{who}: probs[{i}][{j}] = {v} 超过 1")
    mean_p = [0.0] * width
    for row in rows:
        total = sum(row)
        if total <= 0.0:
            raise ValueError(f"{who}: 有一行概率全为 0")
        for j in range(width):
            mean_p[j] += row[j] / total
    for j in range(width):
        mean_p[j] /= float(len(rows))
    kl = 0.0
    for row in rows:
        total = sum(row)
        p = [v / total for v in row]
        for j in range(width):
            if p[j] > 0.0:
                kl += p[j] * math.log(p[j] / max(mean_p[j], float(eps)))
    kl /= float(len(rows))
    return math.exp(kl)


def box_area(box) -> float:
    """矩形面积（宽或高为 0 时返回 0）。

    >>> box_area([0.0, 0.0, 2.0, 3.0])
    6.0
    >>> box_area([1.0, 1.0, 1.0, 5.0])
    0.0
    """
    b = _det_box(box, "box_area", "box")
    return (b[2] - b[0]) * (b[3] - b[1])


def box_iou(box_a, box_b) -> float:
    """两个轴对齐矩形的 IoU；并集为 0 时返回 0。"""
    a = _det_box(box_a, "box_iou", "box_a")
    b = _det_box(box_b, "box_iou", "box_b")
    ix1 = max(a[0], b[0])
    iy1 = max(a[1], b[1])
    ix2 = min(a[2], b[2])
    iy2 = min(a[3], b[3])
    if ix2 <= ix1 or iy2 <= iy1:
        return 0.0
    inter = (ix2 - ix1) * (iy2 - iy1)
    area_a = (a[2] - a[0]) * (a[3] - a[1])
    area_b = (b[2] - b[0]) * (b[3] - b[1])
    union = area_a + area_b - inter
    if union <= 0.0:
        return 0.0
    return inter / union


def _det_check_images(gt, preds, who):
    if not isinstance(gt, (list, tuple)) or not isinstance(preds, (list, tuple)):
        raise ValueError(f"{who}: gt 与 preds 都必须是列表（每项一张图）")
    if len(gt) != len(preds):
        raise ValueError(
            f"{who}: gt 有 {len(gt)} 张图，preds 有 {len(preds)} 张")
    if not gt:
        raise ValueError(f"{who}: 至少要有一张图")
    gts = []
    for i, item in enumerate(gt):
        if not isinstance(item, dict):
            raise ValueError(f"{who}: gt[{i}] 必须是 {{'boxes','labels'}}")
        boxes = item.get("boxes", [])
        labels = item.get("labels", [])
        if not isinstance(boxes, (list, tuple)) or not isinstance(labels, (list, tuple)):
            raise ValueError(f"{who}: gt[{i}] 的 boxes/labels 必须是列表")
        if len(boxes) != len(labels):
            raise ValueError(
                f"{who}: gt[{i}] 的 boxes 有 {len(boxes)} 个、labels 有 {len(labels)} 个")
        gts.append((
            [_det_box(b, who, f"gt[{i}].boxes[{j}]") for j, b in enumerate(boxes)],
            [_metric_label(v, who, j) for j, v in enumerate(labels)],
        ))
    outs = []
    for i, item in enumerate(preds):
        if not isinstance(item, dict):
            raise ValueError(
                f"{who}: preds[{i}] 必须是 {{'boxes','labels','scores'}}")
        boxes = item.get("boxes", [])
        labels = item.get("labels", [])
        scores = item.get("scores", [])
        for name, seq in (("boxes", boxes), ("labels", labels), ("scores", scores)):
            if not isinstance(seq, (list, tuple)):
                raise ValueError(f"{who}: preds[{i}].{name} 必须是列表")
        if not (len(boxes) == len(labels) == len(scores)):
            raise ValueError(
                f"{who}: preds[{i}] 的 boxes/labels/scores 长度不一致"
                f"（{len(boxes)}/{len(labels)}/{len(scores)}）")
        outs.append((
            [_det_box(b, who, f"preds[{i}].boxes[{j}]") for j, b in enumerate(boxes)],
            [_metric_label(v, who, j) for j, v in enumerate(labels)],
            [_metric_number(v, who, j) for j, v in enumerate(scores)],
        ))
    return gts, outs


def _det_check_iou(iou_threshold, who):
    if isinstance(iou_threshold, bool) or not isinstance(iou_threshold, (int, float)):
        raise ValueError(f"{who}: iou_threshold 必须是数字")
    if not 0.0 <= float(iou_threshold) <= 1.0:
        raise ValueError(
            f"{who}: iou_threshold 必须在 [0, 1]，收到 {iou_threshold}")
    return float(iou_threshold)


def _det_match(gts, preds, iou_threshold, class_id, max_dets=None):
    """贪心匹配一类：返回 (tp 数组, fp 数组, 分数数组, 该类真实框数)。"""
    n_gt = 0
    for boxes, labels in gts:
        for lab in labels:
            if lab == class_id:
                n_gt += 1
    entries = []
    for img, (boxes, labels, scores) in enumerate(preds):
        for j, lab in enumerate(labels):
            if lab == class_id:
                entries.append((scores[j], img, j))
    entries.sort(key=lambda e: (-e[0], e[1], e[2]))
    if max_dets is not None and len(entries) > max_dets:
        entries = entries[:max_dets]
    taken = {}
    tp = []
    fp = []
    conf = []
    for score, img, j in entries:
        gt_boxes, gt_labels = gts[img]
        used = taken.setdefault(img, set())
        best_iou = -1.0
        best_k = -1
        for k, gbox in enumerate(gt_boxes):
            if gt_labels[k] != class_id or k in used:
                continue
            iou = box_iou(preds[img][0][j], gbox)
            if iou > best_iou:
                best_iou = iou
                best_k = k
        if best_k >= 0 and best_iou >= iou_threshold:
            used.add(best_k)
            tp.append(1.0)
            fp.append(0.0)
        else:
            tp.append(0.0)
            fp.append(1.0)
        conf.append(score)
    return tp, fp, conf, n_gt


def _det_ap(tp, fp, n_gt):
    """全点插值 AP（precision 包络 + 逐点 Δrecall 加权）。"""
    if n_gt == 0:
        return 0.0
    tp_run = 0.0
    fp_run = 0.0
    precisions = []
    recalls = []
    for t, f in zip(tp, fp):
        tp_run += t
        fp_run += f
        precisions.append(tp_run / (tp_run + fp_run))
        recalls.append(tp_run / float(n_gt))
    for i in range(len(precisions) - 2, -1, -1):
        if precisions[i] < precisions[i + 1]:
            precisions[i] = precisions[i + 1]
    ap = 0.0
    prev = 0.0
    for p, r in zip(precisions, recalls):
        if r > prev:
            ap += (r - prev) * p
            prev = r
    return ap


def _det_classes(gts):
    out = set()
    for boxes, labels in gts:
        out.update(labels)
    return sorted(out)


def detection_average_precision(gt, preds, iou_threshold: float = 0.5):
    """单类检测的平均精度（AP）。

    `gt` / `preds` 是**每张图一个 dict** 的列表：
    `{"boxes": [[x1,y1,x2,y2], ...], "labels": [...]}`；
    `preds` 另外带 `"scores"`。只支持一个类别（多类请用 `mean_average_precision`）。
    """
    who = "detection_average_precision"
    thr = _det_check_iou(iou_threshold, who)
    gts, outs = _det_check_images(gt, preds, who)
    classes = _det_classes(gts)
    if len(classes) > 1:
        raise ValueError(
            f"{who}: gt 里有 {len(classes)} 个类别 {classes}，"
            "请改用 mean_average_precision")
    class_id = classes[0] if classes else 0
    tp, fp, _, n_gt = _det_match(gts, outs, thr, class_id)
    if n_gt == 0:
        raise ValueError(f"{who}: gt 里没有类别 {class_id} 的真实框")
    return _det_ap(tp, fp, n_gt)


def mean_average_precision(gt, preds, iou_threshold: float = 0.5):
    """多类 mAP：每个类别各自算 AP（全点插值），再对类别取宏平均。"""
    who = "mean_average_precision"
    thr = _det_check_iou(iou_threshold, who)
    gts, outs = _det_check_images(gt, preds, who)
    classes = _det_classes(gts)
    if not classes:
        raise ValueError(f"{who}: gt 里没有任何真实框")
    aps = []
    for class_id in classes:
        tp, fp, _, n_gt = _det_match(gts, outs, thr, class_id)
        aps.append(_det_ap(tp, fp, n_gt))
    return sum(aps) / float(len(aps))


def mean_average_precision_range(gt, preds, thresholds=None):
    """COCO 口径的 mAP@[.5:.95]：默认 10 个 IoU 阈值（0.5 起每 0.05 一档）。"""
    who = "mean_average_precision_range"
    gts, _ = _det_check_images(gt, preds, who)
    if not gts:
        raise ValueError(f"{who}: 至少要有一张图")
    if thresholds is None:
        thresholds = [0.5 + 0.05 * i for i in range(10)]
    if not isinstance(thresholds, (list, tuple)) or not thresholds:
        raise ValueError(f"{who}: thresholds 必须是非空列表")
    vals = []
    for t in thresholds:
        thr = _det_check_iou(t, who)
        vals.append(mean_average_precision(gt, preds, iou_threshold=thr))
    return sum(vals) / float(len(vals))


def average_recall(gt, preds, iou_threshold: float = 0.5, max_dets: int = 100):
    """AR：每个类别取前 `max_dets` 个预测的召回率，再对类别宏平均。"""
    who = "average_recall"
    thr = _det_check_iou(iou_threshold, who)
    if isinstance(max_dets, bool) or not isinstance(max_dets, int):
        raise ValueError(f"{who}: max_dets 必须是整数")
    if max_dets < 1:
        raise ValueError(f"{who}: max_dets 必须 >= 1，收到 {max_dets}")
    gts, outs = _det_check_images(gt, preds, who)
    classes = _det_classes(gts)
    if not classes:
        raise ValueError(f"{who}: gt 里没有任何真实框")
    recalls = []
    for class_id in classes:
        tp, _, _, n_gt = _det_match(gts, outs, thr, class_id, max_dets=max_dets)
        if n_gt == 0:
            continue
        recalls.append(sum(tp) / float(n_gt))
    return sum(recalls) / float(len(recalls))


def _cal_check_bins(n_bins, strategy):
    if isinstance(n_bins, bool) or not isinstance(n_bins, int):
        raise ValueError(f"校准: n_bins 必须是整数，收到 {type(n_bins).__name__}")
    if n_bins < 1:
        raise ValueError(f"校准: n_bins 必须 >= 1，收到 {n_bins}")
    if strategy not in ("uniform", "quantile"):
        raise ValueError(
            f"校准: strategy 必须是 'uniform' 或 'quantile'，收到 {strategy!r}")
    return n_bins


def _cal_prepare(y_true, y_proba, who):
    """返回 (置信度列表, 命中列表, 标签列表, 概率行)。单列按二分类正类概率处理。"""
    if not isinstance(y_true, (list, tuple)):
        raise ValueError(f"{who}: y_true 必须是列表")
    if not y_true:
        raise ValueError(f"{who}: y_true 不能为空")
    rows = _proba_matrix(y_proba, len(y_true), who)
    width = len(rows[0])
    labels = []
    conf = []
    hit = []
    for i, row in enumerate(rows):
        for c, v in enumerate(row):
            if not 0.0 <= v <= 1.0:
                raise ValueError(
                    f"{who}: y_proba[{i}][{c}] = {v} 不在 [0, 1] 内")
        tv = _metric_label(y_true[i], f"{who}.y_true", i)
        if width == 1:
            if tv not in (0, 1):
                raise ValueError(
                    f"{who}: 单列概率要求标签是 0/1，y_true[{i}] = {tv}")
            p = row[0]
            pred = 1 if p > 0.5 else 0
            confidence = p if pred == 1 else 1.0 - p
        else:
            if not 0 <= tv < width:
                raise ValueError(
                    f"{who}: y_true[{i}] = {tv} 超出概率列数 {width}")
            best = 0
            for c in range(1, width):
                if row[c] > row[best]:
                    best = c
            pred = best
            confidence = row[best]
        labels.append(tv)
        conf.append(confidence)
        hit.append(1.0 if pred == tv else 0.0)
    return conf, hit, labels, rows


def _cal_edges(conf, n_bins, strategy):
    """返回分箱边界；uniform 固定 0..1，quantile 用置信度分位点。

    quantile 策略下若置信度大量重复，边界会去重，实际箱数可能少于 n_bins。
    """
    if strategy == "uniform":
        return [i / float(n_bins) for i in range(n_bins + 1)]
    ordered = sorted(conf)
    n = len(ordered)
    edges = [ordered[0]]
    for b in range(1, n_bins):
        pos = int(round(b * n / float(n_bins)))
        if pos >= n:
            pos = n - 1
        if ordered[pos] > edges[-1]:
            edges.append(ordered[pos])
    if ordered[-1] > edges[-1]:
        edges.append(ordered[-1])
    if len(edges) < 2:
        edges = [ordered[0], ordered[0] + 1e-12]
    return edges


def _cal_diagram(y_true, y_proba, n_bins, strategy, who):
    n_bins = _cal_check_bins(n_bins, strategy)
    conf, hit, labels, _ = _cal_prepare(y_true, y_proba, who)
    edges = _cal_edges(conf, n_bins, strategy)
    width = len(edges) - 1
    counts = [0] * width
    conf_sum = [0.0] * width
    hit_sum = [0.0] * width
    for c, h in zip(conf, hit):
        idx = width - 1
        for b in range(width):
            lo, hi = edges[b], edges[b + 1]
            if (c >= lo and c < hi) or (b == width - 1 and c <= hi):
                idx = b
                break
        counts[idx] += 1
        conf_sum[idx] += c
        hit_sum[idx] += h
    out = []
    for b in range(width):
        if counts[b] == 0:
            continue
        out.append({
            "lo": edges[b],
            "hi": edges[b + 1],
            "count": counts[b],
            "confidence": conf_sum[b] / counts[b],
            "accuracy": hit_sum[b] / counts[b],
        })
    return out, len(conf)


def expected_calibration_error(y_true, y_proba, n_bins: int = 10,
                               strategy: str = "uniform") -> float:
    """ECE：`Σ (n_b/N)·|acc_b − conf_b|`，按置信度分箱。"""
    bins, total = _cal_diagram(y_true, y_proba, n_bins, strategy,
                               "expected_calibration_error")
    if total <= 0:
        raise ValueError("expected_calibration_error: 没有样本")
    ece = 0.0
    for b in bins:
        ece += (b["count"] / float(total)) * abs(b["accuracy"] - b["confidence"])
    return ece


def maximum_calibration_error(y_true, y_proba, n_bins: int = 10,
                              strategy: str = "uniform") -> float:
    """MCE：各箱 `|acc_b − conf_b|` 的最大值（只看非空箱）。"""
    bins, total = _cal_diagram(y_true, y_proba, n_bins, strategy,
                               "maximum_calibration_error")
    if total <= 0:
        raise ValueError("maximum_calibration_error: 没有样本")
    return max(abs(b["accuracy"] - b["confidence"]) for b in bins)


def reliability_diagram(y_true, y_proba, n_bins: int = 10,
                        strategy: str = "uniform"):
    """返回非空箱列表：`{"lo","hi","count","confidence","accuracy"}`。"""
    bins, total = _cal_diagram(y_true, y_proba, n_bins, strategy,
                              "reliability_diagram")
    if total <= 0:
        raise ValueError("reliability_diagram: 没有样本")
    return bins

def _proba_matrix(y_proba, n: int, who):
    rows = list(y_proba)
    if not rows:
        raise ValueError(f"{who}: y_proba 不能为空")
    first = rows[0]
    if isinstance(first, (list, tuple)):
        if len(rows) != n:
            raise ValueError(f"{who}: y_proba 行数 {len(rows)} 与标签数 {n} 不同")
        width = len(first)
        out = []
        for i, row in enumerate(rows):
            if not isinstance(row, (list, tuple)):
                raise ValueError(f"{who}: 第 {i} 行不是序列")
            if len(row) != width:
                raise ValueError(f"{who}: 第 {i} 行宽度 {len(row)} 与第 0 行 {width} 不同")
            vals = [_metric_number(v, f"{who}.y_proba[{i}]", j) for j, v in enumerate(row)]
            out.append(vals)
        return out
    if len(rows) != n:
        raise ValueError(f"{who}: y_proba 长度 {len(rows)} 与标签数 {n} 不同")
    return [[_metric_number(v, f"{who}.y_proba", i)] for i, v in enumerate(rows)]


def brier_score(y_true, y_proba) -> float:
    """Brier 分数：`mean(Σ_c (p_c - 1{y=c})²)`（二元时传单列概率即可）。"""
    yt, _ = _metric_pairs(y_true, list(y_true), "brier_score")
    rows = _proba_matrix(y_proba, len(yt), "brier_score")
    width = len(rows[0])
    total = 0.0
    for i, (t, row) in enumerate(zip(yt, rows)):
        tv = _metric_label(t, "brier_score.y_true", i)
        if width == 1:
            if tv not in (0, 1):
                raise ValueError(
                    f"brier_score: 单列概率要求标签是 0/1，y_true[{i}] = {tv}")
            p = row[0]
            total += (p - tv) ** 2
        else:
            if not 0 <= tv < width:
                raise ValueError(
                    f"brier_score: y_true[{i}] = {tv} 超出概率列数 {width}")
            for c in range(width):
                target = 1.0 if c == tv else 0.0
                total += (row[c] - target) ** 2
    return total / len(yt)


def log_loss(y_true, y_proba, eps: float = 1e-15) -> float:
    """对数损失（交叉熵）：`-mean(log(max(p_y, eps)))`。

    概率列数 > 1 时按类别索引取列；单列时视为正类概率，`p(y=1)=p`。
    """
    if not float(eps) > 0.0 or float(eps) >= 1.0:
        raise ValueError(f"log_loss: eps 必须在 (0, 1) 内，收到 {eps}")
    yt, _ = _metric_pairs(y_true, list(y_true), "log_loss")
    rows = _proba_matrix(y_proba, len(yt), "log_loss")
    width = len(rows[0])
    total = 0.0
    for i, (t, row) in enumerate(zip(yt, rows)):
        tv = _metric_label(t, "log_loss.y_true", i)
        if width == 1:
            if tv not in (0, 1):
                raise ValueError(f"log_loss: 单列概率要求标签是 0/1，y_true[{i}] = {tv}")
            p = row[0] if tv == 1 else 1.0 - row[0]
        else:
            if not 0 <= tv < width:
                raise ValueError(f"log_loss: y_true[{i}] = {tv} 超出概率列数 {width}")
            p = row[tv]
        if p < eps:
            p = eps
        total -= math.log(p)
    return total / len(yt)


def pr_auc_score(y_true, y_score) -> float:
    """PR 曲线下面积（平均精确率）：按分数降序累积 `Σ (ΔR)·P`。"""
    yt, _ = _metric_pairs(y_true, list(y_true), "pr_auc_score")
    scores = _proba_matrix(y_score, len(yt), "pr_auc_score")
    pairs = []
    positives = 0
    for i, (t, row) in enumerate(zip(yt, scores)):
        tv = _metric_label(t, "pr_auc_score.y_true", i)
        if tv not in (0, 1):
            raise ValueError(f"pr_auc_score: 标签必须是 0/1，y_true[{i}] = {tv}")
        positives += tv
        pairs.append((row[0], tv, i))
    if positives == 0:
        raise ValueError("pr_auc_score: 没有正类样本")
    pairs.sort(key=lambda item: (-item[0], item[2]))
    tp = 0
    fp = 0
    prev_recall = 0.0
    area = 0.0
    for _score, label, _idx in pairs:
        if label:
            tp += 1
        else:
            fp += 1
        recall = tp / positives
        precision = tp / (tp + fp)
        area += (recall - prev_recall) * precision
        prev_recall = recall
    return area


# ---------------------------------------------------------------------------
#  高级评估：Mahalanobis OOD / Conformal Prediction / 鲁棒性
# ---------------------------------------------------------------------------

def _feature_matrix_rows(features, who):
    """校验特征矩阵：非空、每行非空、等宽、元素为有限数字。"""
    if not isinstance(features, (list, tuple)) or not features:
        raise ValueError(f"{who}: features 必须是非空列表")
    rows = []
    width = None
    for i, row in enumerate(features):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"{who}: 第 {i} 个特征必须是非空列表")
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError(
                f"{who}: 第 {i} 个特征维度 {len(row)} 与第一个 {width} 不一致")
        rows.append(
            [_metric_number(v, f"{who}.features[{i}]", j)
             for j, v in enumerate(row)])
    return rows, width


def _matrix_inverse(a, who):
    """Gauss-Jordan 求逆（部分选主元）；奇异矩阵报错。"""
    n = len(a)
    aug = [list(a[i]) + [1.0 if i == j else 0.0 for j in range(n)]
           for i in range(n)]
    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(aug[r][col]))
        if abs(aug[pivot][col]) < 1e-12:
            raise ValueError(f"{who}: 协方差矩阵奇异，无法求逆")
        if pivot != col:
            aug[col], aug[pivot] = aug[pivot], aug[col]
        pv = aug[col][col]
        aug[col] = [v / pv for v in aug[col]]
        for r in range(n):
            if r == col:
                continue
            f = aug[r][col]
            if f != 0.0:
                aug[r] = [x - f * y for x, y in zip(aug[r], aug[col])]
    return [row[n:] for row in aug]


def _mean_vector(rows):
    """按列求均值。"""
    n = float(len(rows))
    return [sum(row[j] for row in rows) / n for j in range(len(rows[0]))]


def _covariance_matrix(rows, mean, eps):
    """总体协方差（除以 n）+ 对角线 ridge eps。"""
    n = float(len(rows))
    d = len(mean)
    cov = [[0.0] * d for _ in range(d)]
    for row in rows:
        diff = [row[j] - mean[j] for j in range(d)]
        for a in range(d):
            da = diff[a]
            row_cov = cov[a]
            for b in range(d):
                row_cov[b] += da * diff[b]
    inv_n = 1.0 / n
    return [[cov[a][b] * inv_n + (float(eps) if a == b else 0.0)
             for b in range(d)] for a in range(d)]


def fit_mahalanobis(features, eps: float = 1e-6):
    """用特征拟合高斯模型，返回 `{"mean", "inv_cov", "dim"}`。"""
    who = "fit_mahalanobis"
    if isinstance(eps, bool) or not isinstance(eps, (int, float)) or not float(eps) > 0.0:
        raise ValueError(f"{who}: eps 必须是正数，收到 {eps!r}")
    rows, dim = _feature_matrix_rows(features, who)
    mean = _mean_vector(rows)
    cov = _covariance_matrix(rows, mean, eps)
    inv = _matrix_inverse(cov, who)
    return {"mean": mean, "inv_cov": inv, "dim": dim}


def mahalanobis_distance(x, model, who: str = "mahalanobis_distance"):
    """单样本到高斯模型的马氏距离。"""
    if not isinstance(model, dict) or "mean" not in model or "inv_cov" not in model:
        raise ValueError(f"{who}: model 必须是 fit_mahalanobis 的返回值")
    dim = int(model["dim"])
    if not isinstance(x, (list, tuple)) or len(x) != dim:
        raise ValueError(f"{who}: x 必须是长度 {dim} 的向量")
    row = [_metric_number(v, f"{who}.x", j) for j, v in enumerate(x)]
    diff = [row[j] - model["mean"][j] for j in range(dim)]
    quad = 0.0
    for a in range(dim):
        for b in range(dim):
            quad += diff[a] * model["inv_cov"][a][b] * diff[b]
    return math.sqrt(max(0.0, quad))


def mahalanobis_scores(features, model, who: str = "mahalanobis_scores"):
    """批量马氏距离（越小越像 in-distribution）。"""
    rows, _ = _feature_matrix_rows(features, who)
    return [mahalanobis_distance(row, model) for row in rows]


def ood_mahalanobis_auroc(in_features, ood_features, eps: float = 1e-6) -> float:
    """用 in-distribution 特征拟合高斯，返回马氏距离的 OOD AUROC。"""
    who = "ood_mahalanobis_auroc"
    model = fit_mahalanobis(in_features, eps)
    in_scores = mahalanobis_scores(in_features, model, who)
    ood_scores = mahalanobis_scores(ood_features, model, who)
    # ood_detection_auroc 约定分数越大越像 in-distribution，这里距离越小越像
    return ood_detection_auroc([-s for s in in_scores], [-s for s in ood_scores])


def _proba_rows(y_proba, who):
    """概率矩阵 → (rows, 类别数)；单列视为二分类正类概率。"""
    seq = list(y_proba)
    if not seq:
        raise ValueError(f"{who}: y_proba 不能为空")
    rows = _proba_matrix(seq, len(seq), who)
    width = len(rows[0])
    classes = 2 if width == 1 else width
    for i, row in enumerate(rows):
        for c, p in enumerate(row):
            if not 0.0 <= p <= 1.0:
                raise ValueError(
                    f"{who}: y_proba[{i}][{c}] = {p} 不在 [0, 1] 内")
    return rows, classes


def conformal_quantile(scores, alpha: float = 0.1) -> float:
    """split-conformal 的分位数：`ceil((n+1)(1-alpha))` 阶顺序统计量。

    超过样本数时返回 `inf`（保证有限样本覆盖率 ≥ 1-alpha）。
    """
    who = "conformal_quantile"
    if isinstance(alpha, bool) or not isinstance(alpha, (int, float))             or not 0.0 < float(alpha) < 1.0:
        raise ValueError(f"{who}: alpha 必须在 (0, 1) 内，收到 {alpha!r}")
    vals = [_metric_number(v, f"{who}.scores", i) for i, v in enumerate(scores)]
    if not vals:
        raise ValueError(f"{who}: scores 不能为空")
    n = len(vals)
    k = int(math.ceil((n + 1) * (1.0 - float(alpha))))
    if k > n:
        return float("inf")
    return sorted(vals)[k - 1]


def conformal_prediction_sets(y_proba, q) -> list:
    """给定非一致性分位数 q，返回每个样本的预测标签集合。"""
    who = "conformal_prediction_sets"
    if isinstance(q, bool) or not isinstance(q, (int, float)) or float(q) < 0.0:
        raise ValueError(f"{who}: q 必须是非负数，收到 {q!r}")
    rows, _ = _proba_rows(y_proba, who)
    qv = float(q)
    out = []
    for row in rows:
        probs = [1.0 - row[0], row[0]] if len(row) == 1 else row
        out.append([c for c, p in enumerate(probs) if 1.0 - p <= qv + 1e-12])
    return out


def conformal_coverage(y_true, y_proba, q) -> float:
    """经验覆盖率：真实标签落在 conformal 预测集合里的比例。"""
    who = "conformal_coverage"
    yt, _ = _metric_pairs(y_true, list(y_true), who)
    rows, classes = _proba_rows(y_proba, who)
    if len(rows) != len(yt):
        raise ValueError(f"{who}: y_proba 行数 {len(rows)} 与标签数 {len(yt)} 不同")
    sets = conformal_prediction_sets(y_proba, q)
    hits = 0
    for i, (t, s) in enumerate(zip(yt, sets)):
        tv = _metric_label(t, f"{who}.y_true", i)
        if not 0 <= tv < classes:
            raise ValueError(f"{who}: y_true[{i}] = {tv} 超出标签范围 0..{classes - 1}")
        if tv in s:
            hits += 1
    return hits / float(len(yt))


def average_conformal_set_size(y_proba, q) -> float:
    """平均预测集合大小（效率指标，越小越好）。"""
    who = "average_conformal_set_size"
    sets = conformal_prediction_sets(y_proba, q)
    return sum(len(s) for s in sets) / float(len(sets))


def robust_accuracy(y_true, adv_pred) -> float:
    """对抗扰动后的分类准确率。"""
    who = "robust_accuracy"
    yt, yp = _metric_pairs(y_true, adv_pred, who)
    if not yt:
        raise ValueError(f"{who}: 样本不能为空")
    hits = 0
    for i in range(len(yt)):
        tv = _metric_label(yt[i], f"{who}.y_true", i)
        pv = _metric_label(yp[i], f"{who}.adv_pred", i)
        if tv == pv:
            hits += 1
    return hits / float(len(yt))


def adversarial_success_rate(y_true, clean_pred, adv_pred) -> float:
    """攻击成功率：干净样本分类正确、对抗样本分类错误的比例。"""
    who = "adversarial_success_rate"
    yt, cp = _metric_pairs(y_true, clean_pred, who)
    _, ap = _metric_pairs(y_true, adv_pred, who + ".adv")
    clean_ok = []
    for i in range(len(yt)):
        tv = _metric_label(yt[i], f"{who}.y_true", i)
        if _metric_label(cp[i], f"{who}.clean_pred", i) == tv:
            clean_ok.append(i)
    if not clean_ok:
        raise ValueError(f"{who}: 没有干净样本被正确分类，成功率无定义")
    success = 0
    for i in clean_ok:
        tv = _metric_label(yt[i], f"{who}.y_true", i)
        if _metric_label(ap[i], f"{who}.adv_pred", i) != tv:
            success += 1
    return success / float(len(clean_ok))


# ============================================================================
#  排序指标（NDCG@k / MAP@k / MRR / P@k / R@k / HitRate / Coverage）
# ============================================================================

# ============================================================================
#  文本生成指标（语料级 BLEU / ROUGE-1·2 / METEOR / CIDEr / Self-BLEU）
# ============================================================================

# ============================================================================
#  语音识别指标（WER / CER / SER）
# ============================================================================

# ============================================================================
#  聚类指标（Silhouette / CH / DB / ARI / NMI / AMI）
# ============================================================================

def _cluster_matrix(X, who):
    """校验样本矩阵：非空、每行等长、元素是有限数字。"""
    if not isinstance(X, (list, tuple)) or not X:
        raise ValueError(f"{who}: X 必须是非空列表")
    rows = []
    width = None
    for i, row in enumerate(X):
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError(f"{who}: 第 {i} 个样本必须是非空列表")
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError(f"{who}: 第 {i} 个样本维度 {len(row)} 与第一个 {width} 不一致")
        rows.append([_metric_number(v, who, i) for v in row])
    return rows, width


def _cluster_labels(labels, n, who):
    """校验标签：长度等于样本数、非负整数。"""
    if not isinstance(labels, (list, tuple)):
        raise ValueError(f"{who}: labels 必须是列表")
    if len(labels) != n:
        raise ValueError(f"{who}: 标签数 {len(labels)} 与样本数 {n} 不一致")
    return [_metric_label(v, who, i) for i, v in enumerate(labels)]


def _cluster_groups(labels):
    """把标签转成 {簇: [样本下标]}。"""
    groups = {}
    for i, lab in enumerate(labels):
        groups.setdefault(lab, []).append(i)
    return groups


def _euclidean(a, b):
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))


def _cluster_centroids(X, groups):
    out = {}
    for lab, idxs in groups.items():
        dim = len(X[0])
        out[lab] = [sum(X[i][d] for i in idxs) / float(len(idxs)) for d in range(dim)]
    return out


def silhouette_score(X, labels):
    """Silhouette：每个点 (b−a)/max(a,b) 的平均；单点簇记 0，需要 2..n−1 个簇。"""
    who = "silhouette_score"
    rows, _ = _cluster_matrix(X, who)
    lab = _cluster_labels(labels, len(rows), who)
    groups = _cluster_groups(lab)
    k = len(groups)
    if k < 2:
        raise ValueError(f"{who}: 至少需要 2 个簇，收到 {k}")
    if k >= len(rows):
        raise ValueError(f"{who}: 簇数 {k} 不能等于样本数 {len(rows)}")
    vals = []
    for i in range(len(rows)):
        own = lab[i]
        same = [j for j in groups[own] if j != i]
        if not same:
            vals.append(0.0)
            continue
        a = sum(_euclidean(rows[i], rows[j]) for j in same) / float(len(same))
        b = None
        for other, idxs in groups.items():
            if other == own:
                continue
            mean_d = sum(_euclidean(rows[i], rows[j]) for j in idxs) / float(len(idxs))
            if b is None or mean_d < b:
                b = mean_d
        denom = max(a, b)
        vals.append(0.0 if denom <= 0.0 else (b - a) / denom)
    return sum(vals) / float(len(vals))


def _cluster_dispersion(X, labels, groups, centroids):
    """返回 (簇内平方和, 簇间平方和, 全局质心)。"""
    dim = len(X[0])
    n = len(X)
    centroids_all = [sum(row[d] for row in X) / float(n) for d in range(dim)]
    within = 0.0
    between = 0.0
    for lab, idxs in groups.items():
        c = centroids[lab]
        within += sum(sum((X[i][d] - c[d]) ** 2 for d in range(dim)) for i in idxs)
        dist2 = sum((c[d] - centroids_all[d]) ** 2 for d in range(dim))
        between += len(idxs) * dist2
    return within, between, centroids_all


def calinski_harabasz_score(X, labels):
    """Calinski-Harabasz：簇间/簇内离散度之比 × (n−k)/(k−1)，越大越好。"""
    who = "calinski_harabasz_score"
    rows, _ = _cluster_matrix(X, who)
    lab = _cluster_labels(labels, len(rows), who)
    groups = _cluster_groups(lab)
    k = len(groups)
    n = len(rows)
    if k < 2:
        raise ValueError(f"{who}: 至少需要 2 个簇，收到 {k}")
    if k >= n:
        raise ValueError(f"{who}: 簇数 {k} 不能等于样本数 {n}")
    centroids = _cluster_centroids(rows, groups)
    within, between, _ = _cluster_dispersion(rows, lab, groups, centroids)
    if within <= 0.0:
        raise ValueError(f"{who}: 簇内离散度为 0（每个簇内样本完全相同），比值无定义")
    return (between / float(within)) * ((n - k) / float(k - 1))


def davies_bouldin_score(X, labels):
    """Davies-Bouldin：每簇取最相似簇的 (s_i+s_j)/d(c_i,c_j) 再平均，越小越好。"""
    who = "davies_bouldin_score"
    rows, _ = _cluster_matrix(X, who)
    lab = _cluster_labels(labels, len(rows), who)
    groups = _cluster_groups(lab)
    k = len(groups)
    if k < 2:
        raise ValueError(f"{who}: 至少需要 2 个簇，收到 {k}")
    centroids = _cluster_centroids(rows, groups)
    spread = {}
    for lab_id, idxs in groups.items():
        c = centroids[lab_id]
        spread[lab_id] = sum(_euclidean(rows[i], c) for i in idxs) / float(len(idxs))
    keys = list(groups)
    vals = []
    for i, ki in enumerate(keys):
        best = None
        for kj in keys:
            if kj == ki:
                continue
            d = _euclidean(centroids[ki], centroids[kj])
            if d <= 0.0:
                continue
            r = (spread[ki] + spread[kj]) / d
            if best is None or r > best:
                best = r
        vals.append(0.0 if best is None else best)
    return sum(vals) / float(len(vals))


def _contingency(labels_true, labels_pred):
    """返回 (混淆计数矩阵, 行和, 列和, 总数)。"""
    rows_t = []
    rows_p = []
    for i in range(len(labels_true)):
        rows_t.append(labels_true[i])
        rows_p.append(labels_pred[i])
    t_keys = sorted(set(rows_t))
    p_keys = sorted(set(rows_p))
    ti = {v: i for i, v in enumerate(t_keys)}
    pi = {v: i for i, v in enumerate(p_keys)}
    table = [[0] * len(p_keys) for _ in range(len(t_keys))]
    for a, b in zip(rows_t, rows_p):
        table[ti[a]][pi[b]] += 1
    row_sums = [sum(row) for row in table]
    col_sums = [sum(table[i][j] for i in range(len(t_keys))) for j in range(len(p_keys))]
    return table, row_sums, col_sums, float(len(rows_t))


def _comb2(n):
    return n * (n - 1) / 2.0


def _entropy(counts, total):
    h = 0.0
    for c in counts:
        if c > 0:
            p = c / total
            h -= p * math.log(p)
    return h


def _mutual_info(table, row_sums, col_sums, total):
    mi = 0.0
    for i, row in enumerate(table):
        for j, n_ij in enumerate(row):
            if n_ij > 0:
                mi += (n_ij / total) * math.log(
                    (n_ij * total) / (row_sums[i] * col_sums[j]))
    return mi


def adjusted_rand_score(labels_true, labels_pred):
    """ARI：用组合数做机会校正的成对一致率，1 为完全一致、0 为随机。"""
    who = "adjusted_rand_score"
    if not isinstance(labels_true, (list, tuple)) or not isinstance(labels_pred, (list, tuple)):
        raise ValueError(f"{who}: 两个标签序列都必须是列表")
    if len(labels_true) != len(labels_pred):
        raise ValueError(
            f"{who}: 长度不一致（{len(labels_true)} vs {len(labels_pred)}）")
    if not labels_true:
        raise ValueError(f"{who}: 不能是空列表")
    t = [_metric_label(v, who, i) for i, v in enumerate(labels_true)]
    p = [_metric_label(v, who, i) for i, v in enumerate(labels_pred)]
    table, row_sums, col_sums, total_n = _contingency(t, p)
    sum_ij = sum(_comb2(n) for row in table for n in row)
    sum_a = sum(_comb2(n) for n in row_sums)
    sum_b = sum(_comb2(n) for n in col_sums)
    total = _comb2(total_n)
    expected = sum_a * sum_b / total if total > 0 else 0.0
    max_index = 0.5 * (sum_a + sum_b)
    if max_index == expected:
        return 1.0 if sum_ij == expected else 0.0
    return (sum_ij - expected) / (max_index - expected)


def normalized_mutual_info_score(labels_true, labels_pred, average_method="arithmetic"):
    """NMI：互信息 / 两个熵的聚合（arithmetic / geometric / min / max）。"""
    who = "normalized_mutual_info_score"
    if average_method not in ("arithmetic", "geometric", "min", "max"):
        raise ValueError(
            f"{who}: average_method 必须是 arithmetic/geometric/min/max，收到 {average_method!r}")
    if not isinstance(labels_true, (list, tuple)) or not isinstance(labels_pred, (list, tuple)):
        raise ValueError(f"{who}: 两个标签序列都必须是列表")
    if len(labels_true) != len(labels_pred):
        raise ValueError(
            f"{who}: 长度不一致（{len(labels_true)} vs {len(labels_pred)}）")
    if not labels_true:
        raise ValueError(f"{who}: 不能是空列表")
    t = [_metric_label(v, who, i) for i, v in enumerate(labels_true)]
    p = [_metric_label(v, who, i) for i, v in enumerate(labels_pred)]
    table, row_sums, col_sums, total = _contingency(t, p)
    mi = _mutual_info(table, row_sums, col_sums, total)
    h_t = _entropy(row_sums, total)
    h_p = _entropy(col_sums, total)
    if mi <= 0.0:
        return 0.0
    if average_method == "arithmetic":
        denom = 0.5 * (h_t + h_p)
    elif average_method == "geometric":
        denom = math.sqrt(h_t * h_p)
    elif average_method == "min":
        denom = min(h_t, h_p)
    else:
        denom = max(h_t, h_p)
    if denom <= 0.0:
        return 1.0
    return mi / denom


def _expected_mutual_info(table, row_sums, col_sums, total):
    """AMI 的机会校正项：按超几何分布对 (行, 列, n_ij) 三重求和。"""
    n = int(total)
    emi = 0.0
    for i, a_i in enumerate(row_sums):
        for j, b_j in enumerate(col_sums):
            low = max(1, a_i + b_j - n)
            high = min(a_i, b_j)
            for n_ij in range(low, high + 1):
                term = (n_ij / float(n)) * math.log(
                    (n_ij * n) / float(a_i * b_j))
                log_p = (math.lgamma(a_i + 1) + math.lgamma(b_j + 1) +
                         math.lgamma(n - a_i + 1) + math.lgamma(n - b_j + 1) -
                         math.lgamma(n + 1) - math.lgamma(n_ij + 1) -
                         math.lgamma(a_i - n_ij + 1) - math.lgamma(b_j - n_ij + 1) -
                         math.lgamma(n - a_i - b_j + n_ij + 1))
                emi += term * math.exp(log_p)
    return emi


def adjusted_mutual_info_score(labels_true, labels_pred, average_method="arithmetic"):
    """AMI：互信息减去机会期望后归一化；对簇数不敏感，随机标签约 0。"""
    who = "adjusted_mutual_info_score"
    if average_method not in ("arithmetic", "geometric", "min", "max"):
        raise ValueError(
            f"{who}: average_method 必须是 arithmetic/geometric/min/max，收到 {average_method!r}")
    if not isinstance(labels_true, (list, tuple)) or not isinstance(labels_pred, (list, tuple)):
        raise ValueError(f"{who}: 两个标签序列都必须是列表")
    if len(labels_true) != len(labels_pred):
        raise ValueError(
            f"{who}: 长度不一致（{len(labels_true)} vs {len(labels_pred)}）")
    if not labels_true:
        raise ValueError(f"{who}: 不能是空列表")
    t = [_metric_label(v, who, i) for i, v in enumerate(labels_true)]
    p = [_metric_label(v, who, i) for i, v in enumerate(labels_pred)]
    table, row_sums, col_sums, total = _contingency(t, p)
    mi = _mutual_info(table, row_sums, col_sums, total)
    emi = _expected_mutual_info(table, row_sums, col_sums, total)
    h_t = _entropy(row_sums, total)
    h_p = _entropy(col_sums, total)
    if average_method == "arithmetic":
        norm = 0.5 * (h_t + h_p)
    elif average_method == "geometric":
        norm = math.sqrt(h_t * h_p)
    elif average_method == "min":
        norm = min(h_t, h_p)
    else:
        norm = max(h_t, h_p)
    denom = norm - emi
    if abs(denom) <= 1e-15:
        return 1.0 if abs(mi - emi) <= 1e-15 else 0.0
    return (mi - emi) / denom


def _edit_ops(reference, hypothesis):
    """编辑距离的 (替换, 删除, 插入) 计数（把参考变成假设的最短路径）。"""
    n = len(reference)
    m = len(hypothesis)
    # dp[i][j] = 把 reference[:i] 变成 hypothesis[:j] 的最小编辑数
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dp[i][0] = i
    for j in range(1, m + 1):
        dp[0][j] = j
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if reference[i - 1] == hypothesis[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j - 1], dp[i - 1][j], dp[i][j - 1])
    subs = dels = ins = 0
    i, j = n, m
    while i > 0 or j > 0:
        if i > 0 and j > 0 and reference[i - 1] == hypothesis[j - 1]:
            i -= 1
            j -= 1
            continue
        if i > 0 and j > 0 and dp[i][j] == dp[i - 1][j - 1] + 1:
            subs += 1
            i -= 1
            j -= 1
        elif i > 0 and dp[i][j] == dp[i - 1][j] + 1:
            dels += 1
            i -= 1
        else:
            ins += 1
            j -= 1
    return subs, dels, ins


def _speech_check_empty(tokens, who, side):
    if not tokens:
        raise ValueError(f"{who}: {side}不能为空（分母/对齐基准都要求非空）")
    return tokens


def word_error_rate(reference, hypothesis):
    """WER = (替换 + 删除 + 插入) / 参考词数；输入是字符串（按空白切分）或 token 列表。"""
    who = "word_error_rate"
    ref = _speech_check_empty(_as_tokens(reference, who + ".reference"), who, "参考")
    hyp = _as_tokens(hypothesis, who + ".hypothesis")
    subs, dels, ins = _edit_ops(ref, hyp)
    return (subs + dels + ins) / float(len(ref))


def character_error_rate(reference, hypothesis):
    """CER = 字符级编辑距离 / 参考字符数；字符串按字符拆（中文友好），列表按元素。"""
    who = "character_error_rate"
    if isinstance(reference, str):
        ref = list(reference)
    elif isinstance(reference, (list, tuple)):
        ref = list(reference)
    else:
        raise ValueError(f"{who}: reference 必须是字符串或列表")
    if isinstance(hypothesis, str):
        hyp = list(hypothesis)
    elif isinstance(hypothesis, (list, tuple)):
        hyp = list(hypothesis)
    else:
        raise ValueError(f"{who}: hypothesis 必须是字符串或列表")
    _speech_check_empty(ref, who, "参考")
    subs, dels, ins = _edit_ops(ref, hyp)
    return (subs + dels + ins) / float(len(ref))


def slot_error_rate(reference_slots, hypothesis_slots):
    """SER = (值错 + 缺失 + 多出) / 参考槽位数；槽位用 dict 或 (key, value) 对表示。"""
    who = "slot_error_rate"

    def _as_slots(slots, side):
        if isinstance(slots, dict):
            return dict(slots)
        if isinstance(slots, (list, tuple)):
            out = {}
            for i, item in enumerate(slots):
                if not isinstance(item, (list, tuple)) or len(item) != 2:
                    raise ValueError(
                        f"{who}: {side}第 {i} 项必须是 (key, value) 二元组")
                key = item[0]
                if key in out:
                    raise ValueError(f"{who}: {side}出现重复槽位 {key!r}")
                out[key] = item[1]
            return out
        raise ValueError(f"{who}: {side}必须是 dict 或 (key, value) 列表")

    ref = _as_slots(reference_slots, "参考")
    hyp = _as_slots(hypothesis_slots, "假设")
    if not ref:
        raise ValueError(f"{who}: 参考槽位不能为空")
    wrong = 0
    for key, value in ref.items():
        if key not in hyp or hyp[key] != value:
            wrong += 1
    extra = sum(1 for key in hyp if key not in ref)
    return (wrong + extra) / float(len(ref))

def _text_ref_sets(references, who):
    """把「一条候选的参考」规范成 list[list[str|tokens]]（支持单/多参考）。"""
    if not isinstance(references, (list, tuple)):
        raise ValueError(f"{who}: references 必须是列表")
    out = []
    for i, item in enumerate(references):
        if isinstance(item, str):
            out.append([item])
        elif isinstance(item, (list, tuple)):
            if not item:
                raise ValueError(f"{who}: 第 {i} 条参考不能为空")
            if isinstance(item[0], str):
                out.append([list(item)])
            else:
                for j, r in enumerate(item):
                    if not isinstance(r, (str, list, tuple)):
                        raise ValueError(
                            f"{who}: 第 {i} 条参考的第 {j} 项必须是字符串或 token 列表")
                out.append(list(item))
        else:
            raise ValueError(
                f"{who}: 第 {i} 条参考必须是字符串、token 列表或它们的列表")
    return out


def corpus_bleu(candidates, references, max_n=4, smooth=1.0):
    """语料级 BLEU：全语料累计截断 n-gram 计数后再算精度与简短惩罚。

    与句级 `bleu_score` 的区别：句级先算每句精度再平均，短句会被重复惩罚；
    语料级把计数加总，是论文里通常报告的 BLEU。
    `smooth=0` 表示不平滑（n≥2 缺命中时该阶精度记 0）。
    `references` 每条可以是字符串或 token 列表（都表示**单条**参考）；
    多条参考必须写成「列表的列表」，例如 `[[["a", "b"], ["a", "c"]]]`。
    """
    who = "corpus_bleu"
    if isinstance(max_n, bool) or not isinstance(max_n, int) or max_n < 1:
        raise ValueError(f"{who}: max_n 必须是 ≥1 的整数，收到 {max_n!r}")
    if isinstance(smooth, bool) or not isinstance(smooth, (int, float)) or smooth < 0:
        raise ValueError(f"{who}: smooth 必须是非负数，收到 {smooth!r}")
    if not isinstance(candidates, (list, tuple)):
        raise ValueError(f"{who}: candidates 必须是列表")
    if len(candidates) != len(references):
        raise ValueError(
            f"{who}: 候选数 {len(candidates)} 与参考数 {len(references)} 不一致")
    if not candidates:
        raise ValueError(f"{who}: 至少要有一个候选")
    cand = [_as_tokens(c, who + ".candidate") for c in candidates]
    ref_sets = _text_ref_sets(references, who)
    refs = [[_as_tokens(r, who + ".reference") for r in rs] for rs in ref_sets]
    clip = [0] * max_n
    total = [0] * max_n
    c_len = 0
    r_len = 0
    for ct, rts in zip(cand, refs):
        if not ct:
            continue
        c_len += len(ct)
        best = None
        for rt in rts:
            cand_len = abs(len(rt) - len(ct))
            if best is None or cand_len < best[0]:
                best = (cand_len, len(rt))
        r_len += best[1]
        for n in range(1, max_n + 1):
            total[n - 1] += max(0, len(ct) - n + 1)
            c_counts = _ngram_counts(ct, n)
            for key, cnt in c_counts.items():
                hit = 0
                for rt in rts:
                    hit = max(hit, min(cnt, _ngram_counts(rt, n).get(key, 0)))
                clip[n - 1] += hit
    if c_len == 0:
        return 0.0
    if clip[0] == 0:
        return 0.0
    log_sum = 0.0
    used = 0
    for n in range(1, max_n + 1):
        if total[n - 1] <= 0:
            continue
        used += 1
        if clip[n - 1] == 0:
            if smooth <= 0.0:
                prec = 0.0
            else:
                prec = smooth / (total[n - 1] + smooth)
        else:
            prec = clip[n - 1] / float(total[n - 1])
        if prec <= 0.0:
            return 0.0
        log_sum += math.log(prec)
    if used == 0:
        return 0.0
    bp = 1.0
    if c_len < r_len:
        bp = math.exp(1.0 - r_len / float(c_len))
    return bp * math.exp(log_sum / used)


def rouge_n(pred, ref, n=1, beta=1.0):
    """ROUGE-N 的 F 值（n-gram 截断重叠；`beta=1` 时是 F1）。"""
    who = "rouge_n"
    if isinstance(n, bool) or not isinstance(n, int) or n < 1:
        raise ValueError(f"{who}: n 必须是 ≥1 的整数，收到 {n!r}")
    if isinstance(beta, bool) or not isinstance(beta, (int, float)) or beta <= 0:
        raise ValueError(f"{who}: beta 必须是正数，收到 {beta!r}")
    p_tokens = _as_tokens(pred, who + ".pred")
    r_tokens = _as_tokens(ref, who + ".ref")
    if not p_tokens or not r_tokens:
        return 0.0
    p_counts = _ngram_counts(p_tokens, n)
    r_counts = _ngram_counts(r_tokens, n)
    overlap = 0
    for key, cnt in p_counts.items():
        overlap += min(cnt, r_counts.get(key, 0))
    if overlap == 0:
        return 0.0
    precision = overlap / float(sum(p_counts.values()))
    recall = overlap / float(sum(r_counts.values()))
    b2 = beta * beta
    return ((1.0 + b2) * precision * recall) / (b2 * precision + recall)


def rouge_1(pred, ref, beta=1.0):
    """ROUGE-1（unigram 重叠）的 F 值。"""
    return rouge_n(pred, ref, 1, beta)


def rouge_2(pred, ref, beta=1.0):
    """ROUGE-2（bigram 重叠）的 F 值。"""
    return rouge_n(pred, ref, 2, beta)


def rouge_s(pred, ref, beta=1.0, max_gap=None):
    """ROUGE-S 的 F 值（skip-bigram：任意有序 token 对，允许中间有间隔）。

    ``max_gap=None`` 表示不限制间隔（标准 ROUGE-S）；``max_gap=4`` 等价于
    ROUGE-S4。每对按 (前一个 token, 后一个 token) 计数并做截断重叠。
    """
    who = "rouge_s"
    if isinstance(beta, bool) or not isinstance(beta, (int, float)) or beta <= 0:
        raise ValueError(f"{who}: beta 必须是正数，收到 {beta!r}")
    if max_gap is not None and (isinstance(max_gap, bool)
                                or not isinstance(max_gap, int) or max_gap < 0):
        raise ValueError(f"{who}: max_gap 必须是 ≥0 的整数或 None，收到 {max_gap!r}")
    p_tokens = _as_tokens(pred, who + ".pred")
    r_tokens = _as_tokens(ref, who + ".ref")
    if len(p_tokens) < 2 or len(r_tokens) < 2:
        return 0.0

    def _pair_counts(tokens):
        counts = {}
        for i in range(len(tokens) - 1):
            for j in range(i + 1, len(tokens)):
                if max_gap is not None and j - i - 1 > max_gap:
                    continue
                key = (tokens[i], tokens[j])
                counts[key] = counts.get(key, 0) + 1
        return counts

    p_counts = _pair_counts(p_tokens)
    r_counts = _pair_counts(r_tokens)
    overlap = 0
    for key, cnt in p_counts.items():
        overlap += min(cnt, r_counts.get(key, 0))
    if overlap == 0:
        return 0.0
    precision = overlap / float(sum(p_counts.values()))
    recall = overlap / float(sum(r_counts.values()))
    b2 = beta * beta
    return ((1.0 + b2) * precision * recall) / (b2 * precision + recall)


def rouge_w(pred, ref, beta=1.0):
    """ROUGE-W 的 F 值（加权 LCS：连续匹配越长权重越高，f(l)=l^2）。

    使用 Lin (2004) 的近似 DP：匹配时把「当前连续匹配长度 c」的权重增量
    ``2c-1`` 累加；最后按 ``f^{-1}(W)=sqrt(W)`` 还原有效匹配长度再算 P/R/F。
    """
    who = "rouge_w"
    if isinstance(beta, bool) or not isinstance(beta, (int, float)) or beta <= 0:
        raise ValueError(f"{who}: beta 必须是正数，收到 {beta!r}")
    p_tokens = _as_tokens(pred, who + ".pred")
    r_tokens = _as_tokens(ref, who + ".ref")
    if not p_tokens or not r_tokens:
        return 0.0
    m = len(p_tokens)
    n = len(r_tokens)
    score = [[0.0] * (n + 1) for _ in range(m + 1)]
    run = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        pi = p_tokens[i - 1]
        for j in range(1, n + 1):
            if pi == r_tokens[j - 1]:
                c = run[i - 1][j - 1] + 1
                val = score[i - 1][j - 1] + (2 * c - 1)
                best = score[i - 1][j] if score[i - 1][j] >= score[i][j - 1] else score[i][j - 1]
                if val >= best:
                    score[i][j] = val
                    run[i][j] = c
                else:
                    score[i][j] = best
                    run[i][j] = 0
            else:
                score[i][j] = score[i - 1][j] if score[i - 1][j] >= score[i][j - 1] else score[i][j - 1]
                run[i][j] = 0
    weighted = score[m][n]
    if weighted <= 0.0:
        return 0.0
    length = math.sqrt(weighted)
    precision = length / m
    recall = length / n
    b2 = beta * beta
    return ((1.0 + b2) * precision * recall) / (b2 * precision + recall)


def _meteor_chunks(p_tokens, r_tokens):
    """按候选顺序贪心对齐后，统计匹配片段的个数（METEOR 的 fragmentation）。"""
    remain = {}
    for tok in r_tokens:
        remain[tok] = remain.get(tok, 0) + 1
    marks = []
    for tok in p_tokens:
        if remain.get(tok, 0) > 0:
            remain[tok] -= 1
            marks.append(True)
        else:
            marks.append(False)
    chunks = 0
    prev = False
    for m in marks:
        if m and not prev:
            chunks += 1
        prev = m
    return sum(1 for m in marks if m), chunks


def meteor_score(pred, ref, alpha=0.9, beta=3.0, gamma=0.5):
    """METEOR 的简化版：精确匹配 + 片段惩罚（无词干/同义词表）。"""
    who = "meteor_score"
    for name, v in (("alpha", alpha), ("beta", beta), ("gamma", gamma)):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError(f"{who}: {name} 必须是数字，收到 {v!r}")
        if v < 0.0:
            raise ValueError(f"{who}: {name} 必须是非负数，收到 {v}")
    if alpha > 1.0:
        raise ValueError(f"{who}: alpha 必须在 [0, 1]，收到 {alpha}")
    p_tokens = _as_tokens(pred, who + ".pred")
    r_tokens = _as_tokens(ref, who + ".ref")
    if not p_tokens or not r_tokens:
        return 0.0
    matched, chunks = _meteor_chunks(p_tokens, r_tokens)
    if matched == 0:
        return 0.0
    precision = matched / float(len(p_tokens))
    recall = matched / float(len(r_tokens))
    if precision + recall <= 0.0:
        return 0.0
    f_mean = (precision * recall) / (alpha * precision + (1.0 - alpha) * recall)
    penalty = gamma * ((chunks / float(matched)) ** beta)
    return f_mean * (1.0 - penalty)


# ============================================================================
#  文本指标扩展：METEOR（词干/同义词完整版）、chrF、BLEURT-lite、COMET-lite
# ============================================================================


def _mt_norm(token):
    return str(token).lower()


def _mt_stem(token):
    """教学版英文词干：剥离常见后缀（不是完整 Porter）。"""
    w = _mt_norm(token)
    for suf in ("ing", "edly", "ed", "es", "s", "ly", "er", "est"):
        if len(w) > len(suf) + 2 and w.endswith(suf):
            return w[:-len(suf)]
    return w


def _mt_synonym_table(synonyms):
    """把 dict 或「同义词组列表」规范成 token -> 同义词集合 的表。"""
    table = {}
    if synonyms is None:
        return table
    if isinstance(synonyms, dict):
        groups = []
        for key, vals in synonyms.items():
            group = {_mt_norm(key)}
            for v in vals:
                group.add(_mt_norm(v))
            groups.append(group)
        for group in groups:
            for t in group:
                table[t] = group
        return table
    if isinstance(synonyms, (list, tuple)):
        for group in synonyms:
            g = {_mt_norm(t) for t in group}
            for t in g:
                table[t] = g
        return table
    raise ValueError("meteor_score_full: synonyms 必须是 dict、列表或 None")


def _mt_align(p_tokens, r_tokens, table, use_stem=True):
    """贪心对齐：先精确、再词干、最后同义词；返回 [(i, j), ...]。"""
    used = set()
    pairs = []
    remaining = []
    for i, p in enumerate(p_tokens):
        hit = None
        for j, r in enumerate(r_tokens):
            if j in used:
                continue
            if _mt_norm(p) == _mt_norm(r):
                hit = j
                break
        if hit is None:
            remaining.append(i)
        else:
            used.add(hit)
            pairs.append((i, hit))
    if use_stem:
        for i in remaining:
            hit = None
            for j, r in enumerate(r_tokens):
                if j in used:
                    continue
                if _mt_stem(p_tokens[i]) == _mt_stem(r):
                    hit = j
                    break
            if hit is not None:
                used.add(hit)
                pairs.append((i, hit))
        remaining = [i for i in remaining if all(i != p[0] for p in pairs)]
    if table:
        for i in remaining:
            group = table.get(_mt_norm(p_tokens[i]))
            if not group:
                continue
            hit = None
            for j, r in enumerate(r_tokens):
                if j in used:
                    continue
                if _mt_norm(r) in group:
                    hit = j
                    break
            if hit is not None:
                used.add(hit)
                pairs.append((i, hit))
    pairs.sort()
    return pairs


def _mt_chunks(pairs):
    """匹配对在候选与参考中同时连续才算同一个 chunk。"""
    chunks = 0
    prev_i = prev_j = None
    for i, j in pairs:
        if prev_i is None or i != prev_i + 1 or j != prev_j + 1:
            chunks += 1
        prev_i, prev_j = i, j
    return chunks


def meteor_score_full(pred, ref, alpha=0.9, beta=3.0, gamma=0.5,
                      synonyms=None, use_stem=True):
    """METEOR（完整版教学实现）：精确/词干/同义词匹配 + 片段惩罚。

    与 ``meteor_score`` 的区别：支持词干匹配与外部同义词表，片段数按
    「候选与参考中的匹配位置同时连续」计算（原版 METEOR 的 chunk 定义）。
    """
    who = "meteor_score_full"
    for name, v in (("alpha", alpha), ("beta", beta), ("gamma", gamma)):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError(f"{who}: {name} 必须是数字，收到 {v!r}")
        if v < 0.0:
            raise ValueError(f"{who}: {name} 必须是非负数，收到 {v}")
    if alpha > 1.0:
        raise ValueError(f"{who}: alpha 必须在 [0, 1]，收到 {alpha}")
    if not isinstance(use_stem, bool):
        raise ValueError(f"{who}: use_stem 必须是 bool")
    p_tokens = _as_tokens(pred, who + ".pred")
    r_tokens = _as_tokens(ref, who + ".ref")
    if not p_tokens or not r_tokens:
        return 0.0
    table = _mt_synonym_table(synonyms)
    pairs = _mt_align(p_tokens, r_tokens, table, use_stem)
    matched = len(pairs)
    if matched == 0:
        return 0.0
    precision = matched / float(len(p_tokens))
    recall = matched / float(len(r_tokens))
    f_mean = (precision * recall) / (alpha * precision + (1.0 - alpha) * recall)
    chunks = _mt_chunks(pairs)
    penalty = gamma * ((chunks / float(matched)) ** beta)
    score = f_mean * (1.0 - penalty)
    return max(0.0, score)


def chrf_score(pred, ref, max_n=6, beta=2.0):
    """chrF：字符 n-gram（1..max_n）的 F-beta 平均。"""
    who = "chrf_score"
    if isinstance(max_n, bool) or not isinstance(max_n, int) or max_n < 1:
        raise ValueError(f"{who}: max_n 必须是 >=1 的整数，收到 {max_n!r}")
    if isinstance(beta, bool) or not isinstance(beta, (int, float)) or beta <= 0:
        raise ValueError(f"{who}: beta 必须是正数，收到 {beta!r}")
    if isinstance(pred, str):
        p_text = " ".join(pred.lower().split())
    elif isinstance(pred, (list, tuple)):
        p_text = " ".join(str(t).lower() for t in pred)
    else:
        raise ValueError(f"{who}: pred 必须是字符串或 token 列表")
    if isinstance(ref, str):
        r_text = " ".join(ref.lower().split())
    elif isinstance(ref, (list, tuple)):
        r_text = " ".join(str(t).lower() for t in ref)
    else:
        raise ValueError(f"{who}: ref 必须是字符串或 token 列表")
    if not p_text or not r_text:
        return 0.0
    b2 = float(beta) * float(beta)
    total = 0.0
    used = 0
    for n in range(1, max_n + 1):
        p_grams = [p_text[i:i + n] for i in range(len(p_text) - n + 1)]
        r_grams = [r_text[i:i + n] for i in range(len(r_text) - n + 1)]
        if not p_grams or not r_grams:
            continue
        remain = {}
        for g in r_grams:
            remain[g] = remain.get(g, 0) + 1
        overlap = 0
        for g in p_grams:
            c = remain.get(g, 0)
            if c > 0:
                remain[g] = c - 1
                overlap += 1
        precision = overlap / float(len(p_grams))
        recall = overlap / float(len(r_grams))
        if precision + recall <= 0.0:
            continue
        total += ((1.0 + b2) * precision * recall) / (b2 * precision + recall)
        used += 1
    if used == 0:
        return 0.0
    return total / float(used)


def _mt_length_ratio(p_tokens, r_tokens):
    if not p_tokens and not r_tokens:
        return 1.0
    return min(len(p_tokens), len(r_tokens)) / float(max(len(p_tokens), len(r_tokens)))


def bleurt_lite(pred, ref, embed_fn, idf=None, length_penalty=0.1):
    """BLEURT 的轻量代理（无预训练权重）：BERTScore-F + 长度惩罚。

    用 ``embed_fn`` 做词级嵌入、BERTScore 的 F_beta（beta=1）作为语义覆盖，
    再乘 ``1 - length_penalty*(1-min/max)``。分数在 [0, 1]，不是原版 BLEURT
    的 [-2.5, 1] 标度，仅用于排序/教学。
    """
    who = "bleurt_lite"
    if isinstance(length_penalty, bool) or not isinstance(length_penalty, (int, float)):
        raise ValueError(f"{who}: length_penalty 必须是数字")
    if not (0.0 <= float(length_penalty) <= 1.0):
        raise ValueError(f"{who}: length_penalty 必须在 [0, 1]")
    p_tokens = _as_tokens(pred, who + ".pred")
    r_tokens = _as_tokens(ref, who + ".ref")
    if not p_tokens or not r_tokens:
        return 0.0
    bs = bert_score(p_tokens, r_tokens, embed_fn, idf=idf, beta=1.0)
    ratio = _mt_length_ratio(p_tokens, r_tokens)
    score = bs["f_beta"] * (1.0 - float(length_penalty) * (1.0 - ratio))
    return max(0.0, min(1.0, score))


def comet_lite(pred, ref, embed_fn, idf=None, length_penalty=0.1):
    """COMET 的轻量代理（无预训练权重）：偏召回的 BERTScore-F + 长度惩罚。

    与 ``bleurt_lite`` 的区别：用 beta=2 的 F 分数（更看重参考的覆盖/完整性），
    再按长度差异惩罚；分数在 [0, 1]，仅用于排序/教学。
    """
    who = "comet_lite"
    if isinstance(length_penalty, bool) or not isinstance(length_penalty, (int, float)):
        raise ValueError(f"{who}: length_penalty 必须是数字")
    if not (0.0 <= float(length_penalty) <= 1.0):
        raise ValueError(f"{who}: length_penalty 必须在 [0, 1]")
    p_tokens = _as_tokens(pred, who + ".pred")
    r_tokens = _as_tokens(ref, who + ".ref")
    if not p_tokens or not r_tokens:
        return 0.0
    bs = bert_score(p_tokens, r_tokens, embed_fn, idf=idf, beta=2.0)
    ratio = _mt_length_ratio(p_tokens, r_tokens)
    score = bs["f_beta"] * (1.0 - float(length_penalty) * (1.0 - ratio))
    return max(0.0, min(1.0, score))


def _bs_tokens(text, who):
    """bert_score 的输入规整：字符串按空白切，列表按元素转字符串。"""
    if isinstance(text, str):
        toks = text.split()
    elif isinstance(text, (list, tuple)):
        toks = [str(t) for t in text]
    else:
        raise ValueError(f"{who}: 文本必须是字符串或 token 列表")
    return [t for t in toks if t]


def _bs_cosine(a, b):
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(x * x for x in b))
    if na <= 0.0 or nb <= 0.0:
        return 0.0
    return sum(x * y for x, y in zip(a, b)) / (na * nb)


def bert_score(pred, ref, embed_fn, idf=None, beta=1.0):
    """BERTScore：用外部嵌入做贪心余弦匹配的 P/R/F（IDF 可选）。

    embed_fn(token) -> 向量；idf 是 token -> 权重的 dict（缺省全 1）。
    对 pred 的每个 token 找 ref 中最相似的 token（贪心、不要求一一对应），
    以 IDF 加权平均相似度得到 P；R 方向对称；F = (1+β²)PR/(β²P+R)。
    """
    who = "bert_score"
    if not callable(embed_fn):
        raise ValueError(f"{who}: embed_fn 必须可调用")
    if isinstance(beta, bool) or not isinstance(beta, (int, float)):
        raise ValueError(f"{who}: beta 必须是数字")
    beta = float(beta)
    if beta <= 0.0:
        raise ValueError(f"{who}: beta 必须 > 0")
    if idf is not None and not isinstance(idf, dict):
        raise ValueError(f"{who}: idf 必须是 dict 或 None")
    p_tokens = _bs_tokens(pred, who + ".pred")
    r_tokens = _bs_tokens(ref, who + ".ref")
    if not p_tokens and not r_tokens:
        return {"precision": 1.0, "recall": 1.0, "f_beta": 1.0}
    if not p_tokens or not r_tokens:
        return {"precision": 0.0, "recall": 0.0, "f_beta": 0.0}
    p_vecs = [list(embed_fn(t)) for t in p_tokens]
    r_vecs = [list(embed_fn(t)) for t in r_tokens]
    dims = {len(v) for v in p_vecs + r_vecs}
    if len(dims) != 1:
        raise ValueError(f"{who}: 嵌入向量维度不一致，收到 {sorted(dims)}")
    weights = {}
    for t in set(p_tokens + r_tokens):
        w = 1.0 if idf is None else idf.get(t, 1.0)
        if isinstance(w, bool) or not isinstance(w, (int, float)) or w < 0.0:
            raise ValueError(f"{who}: idf[{t!r}] 必须是非负数字")
        weights[t] = float(w)

    def direction(src_tokens, src_vecs, tgt_vecs):
        hit = 0.0
        total = 0.0
        for tok, vec in zip(src_tokens, src_vecs):
            best = max(_bs_cosine(vec, tv) for tv in tgt_vecs)
            w = weights[tok]
            hit += w * best
            total += w
        return hit / total if total > 0.0 else 0.0

    precision = direction(p_tokens, p_vecs, r_vecs)
    recall = direction(r_tokens, r_vecs, p_vecs)
    if precision + recall <= 0.0:
        f_beta = 0.0
    else:
        f_beta = (1.0 + beta * beta) * precision * recall / (
            beta * beta * precision + recall)
    return {"precision": precision, "recall": recall, "f_beta": f_beta}


def _tfidf_vector(tokens, n, idf):
    """n-gram 的 TF-IDF 向量（TF 用原始计数，与 CIDEr 一致）。"""
    vec = {}
    counts = _ngram_counts(tokens, n)
    total = float(sum(counts.values())) or 1.0
    for key, cnt in counts.items():
        weight = idf.get(key)
        if weight is None:
            continue
        vec[key] = (cnt / total) * weight
    return vec


def cider_score(candidate, references, n=4):
    """CIDEr 的简化版：1..n gram 的 TF-IDF 余弦相似度平均 × 10。

    IDF 只用**这条候选**的参考集统计（不跨语料），所以绝对值偏乐观，
    适合在同一组参考下比较多个候选，不适合跨数据集报数。
    """
    who = "cider_score"
    if isinstance(n, bool) or not isinstance(n, int) or n < 1:
        raise ValueError(f"{who}: n 必须是 ≥1 的整数，收到 {n!r}")
    if not isinstance(references, (list, tuple)) or not references:
        raise ValueError(f"{who}: references 必须是非空列表")
    cand = _as_tokens(candidate, who + ".candidate")
    if not cand:
        return 0.0
    ref_tokens = [_as_tokens(r, who + ".reference") for r in references]
    if not any(ref_tokens):
        raise ValueError(f"{who}: 参考全是空串，CIDEr 无定义")
    scores = []
    for order in range(1, n + 1):
        df = {}
        for rt in ref_tokens:
            for key in _ngram_counts(rt, order):
                df[key] = df.get(key, 0) + 1
        total_docs = float(len(ref_tokens))
        idf = {}
        for key, d in df.items():
            idf[key] = math.log((total_docs + 1.0) / (d + 1.0)) + 1.0
        cv = _tfidf_vector(cand, order, idf)
        c_norm = math.sqrt(sum(v * v for v in cv.values()))
        if c_norm <= 0.0:
            scores.append(0.0)
            continue
        best = 0.0
        for rt in ref_tokens:
            rv = _tfidf_vector(rt, order, idf)
            r_norm = math.sqrt(sum(v * v for v in rv.values()))
            if r_norm <= 0.0:
                continue
            dot = 0.0
            for key, v in cv.items():
                r_val = rv.get(key)
                if r_val is not None:
                    dot += v * r_val
            best = max(best, dot / (c_norm * r_norm))
        scores.append(best)
    return 10.0 * sum(scores) / float(len(scores))


def self_bleu(candidates, max_n=4):
    """Self-BLEU：每个候选以其余候选为参考算 BLEU，取平均；越高越不多样。"""
    who = "self_bleu"
    if not isinstance(candidates, (list, tuple)):
        raise ValueError(f"{who}: candidates 必须是列表")
    if len(candidates) < 2:
        raise ValueError(f"{who}: 至少需要两个候选，收到 {len(candidates)}")
    vals = []
    for i, cand in enumerate(candidates):
        others = [c for j, c in enumerate(candidates) if j != i]
        vals.append(max(bleu_score(cand, ref, max_n=max_n) for ref in others))
    return sum(vals) / float(len(vals))


def _rank_k(k, n, who):
    """把 k 归一化到 [1, n]；None 表示全取。"""
    if k is None:
        return n
    if isinstance(k, bool) or not isinstance(k, int):
        raise ValueError(f"{who}: k 必须是整数，收到 {k!r}")
    if k <= 0:
        raise ValueError(f"{who}: k 必须大于 0，收到 {k}")
    return min(k, n)


def _rank_query(y_relevance, y_score, who, graded=False):
    """校验一条查询的相关性/分数，返回 (相关性列表, 按分数降序的下标)。"""
    if not isinstance(y_relevance, (list, tuple)) or not isinstance(y_score, (list, tuple)):
        raise ValueError(f"{who}: y_relevance / y_score 必须是列表")
    if len(y_relevance) != len(y_score):
        raise ValueError(
            f"{who}: 相关性长度 {len(y_relevance)} 与分数长度 {len(y_score)} 不一致")
    if not y_relevance:
        raise ValueError(f"{who}: 不能是空列表")
    rel = []
    for i, v in enumerate(y_relevance):
        x = _metric_number(v, who, i)
        if graded:
            if x < 0.0:
                raise ValueError(f"{who}: 第 {i} 个相关性不能是负数，收到 {x}")
        elif x not in (0.0, 1.0):
            raise ValueError(f"{who}: 第 {i} 个相关性必须是 0 或 1，收到 {x}")
        rel.append(x)
    score = [_metric_number(v, who, i) for i, v in enumerate(y_score)]
    order = sorted(range(len(score)), key=lambda i: (-score[i], i))
    return rel, order


def _rank_top(rel, order, k):
    return [rel[i] for i in order[:k]]


# ============================================================================
#  分割指标（mIoU / Dice / FW-IoU / PixelAcc / BoundaryF1 / HD95）
# ============================================================================

def _seg_check_ignore(ignore_index, who):
    """忽略标签必须是整数（允许负数，bool 不算）；None 表示不忽略。"""
    if ignore_index is None:
        return None
    if isinstance(ignore_index, bool) or not isinstance(ignore_index, int):
        raise ValueError(f"{who}: ignore_index 必须是整数或 None，收到 {ignore_index!r}")
    return ignore_index


def _seg_maps(y_true, y_pred, who, ignore_index=None):
    """校验两张同形的二维标签图，返回 list[list[int]] 副本。"""
    ignore_index = _seg_check_ignore(ignore_index, who)
    if not isinstance(y_true, (list, tuple)) or not isinstance(y_pred, (list, tuple)):
        raise ValueError(f"{who}: y_true / y_pred 必须是「行列表」的二维标签图")
    if not y_true or not y_pred:
        raise ValueError(f"{who}: 标签图不能为空")
    if len(y_true) != len(y_pred):
        raise ValueError(f"{who}: 高度不一致（{len(y_true)} vs {len(y_pred)}）")
    rows_t, rows_p = [], []
    width = None
    for i, (rt, rp) in enumerate(zip(y_true, y_pred)):
        if not isinstance(rt, (list, tuple)) or not isinstance(rp, (list, tuple)):
            raise ValueError(f"{who}: 第 {i} 行必须是列表")
        if len(rt) != len(rp):
            raise ValueError(
                f"{who}: 第 {i} 行宽度不一致（{len(rt)} vs {len(rp)}）")
        if not rt:
            raise ValueError(f"{who}: 第 {i} 行不能为空")
        if width is None:
            width = len(rt)
        elif len(rt) != width:
            raise ValueError(f"{who}: 第 {i} 行宽度 {len(rt)} 与第一行 {width} 不一致")
        rows_t.append([_metric_label(v, who, j) for j, v in enumerate(rt)])
        rows_p.append([_metric_label(v, who, j) for j, v in enumerate(rp)])
    return rows_t, rows_p, ignore_index


def _seg_confusion(y_true, y_pred, num_classes, ignore_index, who):
    """按像素统计 num_classes×num_classes 混淆矩阵，返回 (矩阵, 类别数)。"""
    rows_t, rows_p, ignore_index = _seg_maps(y_true, y_pred, who, ignore_index)
    labels = []
    for rt, rp in zip(rows_t, rows_p):
        for a, b in zip(rt, rp):
            if ignore_index is not None and a == ignore_index:
                continue
            labels.append(a)
            labels.append(b)
    if not labels:
        raise ValueError(f"{who}: 有效像素为 0（全被 ignore_index 排除了）")
    if num_classes is None:
        num_classes = max(labels) + 1
    else:
        if isinstance(num_classes, bool) or not isinstance(num_classes, int):
            raise ValueError(f"{who}: num_classes 必须是整数或 None")
        if num_classes <= 0:
            raise ValueError(f"{who}: num_classes 必须大于 0")
        top = max(labels)
        if top >= num_classes:
            raise ValueError(
                f"{who}: 标签 {top} 超出 num_classes={num_classes} 的范围")
    cm = [[0] * num_classes for _ in range(num_classes)]
    for rt, rp in zip(rows_t, rows_p):
        for a, b in zip(rt, rp):
            if ignore_index is not None and a == ignore_index:
                continue
            cm[a][b] += 1
    return cm, num_classes


def _seg_counts(cm, k):
    """第 k 类的 (tp, fp, fn)。"""
    tp = cm[k][k]
    fp = sum(cm[i][k] for i in range(len(cm))) - tp
    fn = sum(cm[k]) - tp
    return tp, fp, fn


def pixel_accuracy(y_true, y_pred, ignore_index=None):
    """PixelAcc：逐像素预测正确的比例（跳过 ignore_index）。"""
    who = "pixel_accuracy"
    cm, _ = _seg_confusion(y_true, y_pred, None, ignore_index, who)
    total = sum(sum(row) for row in cm)
    diag = sum(cm[k][k] for k in range(len(cm)))
    return diag / float(total)


def mean_iou(y_true, y_pred, num_classes=None, ignore_index=None):
    """mIoU：每类 IoU 的平均，只对「联合集非空」的类取平均。"""
    who = "mean_iou"
    cm, n = _seg_confusion(y_true, y_pred, num_classes, ignore_index, who)
    vals = []
    for k in range(n):
        tp, fp, fn = _seg_counts(cm, k)
        union = tp + fp + fn
        if union > 0:
            vals.append(tp / float(union))
    if not vals:
        raise ValueError(f"{who}: 所有类别的联合集都为空，mIoU 无定义")
    return sum(vals) / float(len(vals))


def dice_score(y_true, y_pred, num_classes=None, ignore_index=None):
    """Dice：每类 2TP/(2TP+FP+FN) 的平均（同样只统计联合集非空的类）。"""
    who = "dice_score"
    cm, n = _seg_confusion(y_true, y_pred, num_classes, ignore_index, who)
    vals = []
    for k in range(n):
        tp, fp, fn = _seg_counts(cm, k)
        denom = 2 * tp + fp + fn
        if denom > 0:
            vals.append(2.0 * tp / float(denom))
    if not vals:
        raise ValueError(f"{who}: 所有类别的联合集都为空，Dice 无定义")
    return sum(vals) / float(len(vals))


def frequency_weighted_iou(y_true, y_pred, num_classes=None, ignore_index=None):
    """FW-IoU：按真实像素频率加权的 IoU（权重只在联合集非空的类上归一化）。"""
    who = "frequency_weighted_iou"
    cm, n = _seg_confusion(y_true, y_pred, num_classes, ignore_index, who)
    ious, weights = [], []
    for k in range(n):
        tp, fp, fn = _seg_counts(cm, k)
        union = tp + fp + fn
        if union > 0:
            ious.append(tp / float(union))
            weights.append(float(sum(cm[k])))
    total = sum(weights)
    if total <= 0.0:
        raise ValueError(f"{who}: 没有可加权的前景像素，FW-IoU 无定义")
    return sum(i * w for i, w in zip(ious, weights)) / total


def _seg_boundary(labels, ignore_index=None):
    """返回边界像素坐标集合：与四邻域标签不同的像素（图像外的邻域视为相同）。"""
    h = len(labels)
    w = len(labels[0])
    pts = set()
    for i in range(h):
        for j in range(w):
            cur = labels[i][j]
            if ignore_index is not None and cur == ignore_index:
                continue
            for di, dj in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                ni, nj = i + di, j + dj
                if ni < 0 or ni >= h or nj < 0 or nj >= w:
                    continue
                other = labels[ni][nj]
                if ignore_index is not None and other == ignore_index:
                    continue
                if other != cur:
                    pts.add((i, j))
                    break
    return pts


def _seg_min_dist(pt, pts):
    best = float("inf")
    for q in pts:
        d = (pt[0] - q[0]) ** 2 + (pt[1] - q[1]) ** 2
        if d < best:
            best = d
    return math.sqrt(best)


def boundary_f1(y_true, y_pred, tolerance=2.0, ignore_index=None):
    """Boundary F1：预测边界在 tolerance 像素内命中真实边界的 precision/recall 调和均值。"""
    who = "boundary_f1"
    rows_t, rows_p, ignore_index = _seg_maps(y_true, y_pred, who, ignore_index)
    if isinstance(tolerance, bool) or not isinstance(tolerance, (int, float)):
        raise ValueError(f"{who}: tolerance 必须是数字")
    tolerance = float(tolerance)
    if tolerance < 0.0 or tolerance != tolerance:
        raise ValueError(f"{who}: tolerance 必须是有限的非负数，收到 {tolerance}")
    gt = _seg_boundary(rows_t, ignore_index)
    pd = _seg_boundary(rows_p, ignore_index)
    if not gt and not pd:
        return 1.0
    if not gt or not pd:
        return 0.0
    hit_t = sum(1 for q in pd if _seg_min_dist(q, gt) <= tolerance)
    hit_p = sum(1 for q in gt if _seg_min_dist(q, pd) <= tolerance)
    precision = hit_t / float(len(pd))
    recall = hit_p / float(len(gt))
    if precision + recall <= 0.0:
        return 0.0
    return 2.0 * precision * recall / (precision + recall)


def hd95(y_true, y_pred, ignore_index=None):
    """HD95：两组边界点双向最近距离合并后的第 95 百分位（像素单位）。"""
    who = "hd95"
    rows_t, rows_p, ignore_index = _seg_maps(y_true, y_pred, who, ignore_index)
    gt = _seg_boundary(rows_t, ignore_index)
    pd = _seg_boundary(rows_p, ignore_index)
    if not gt and not pd:
        return 0.0
    if not gt or not pd:
        raise ValueError(f"{who}: 一侧没有任何边界像素，HD95 无定义")
    dists = [_seg_min_dist(q, pd) for q in gt]
    dists += [_seg_min_dist(q, gt) for q in pd]
    dists.sort()
    idx = int(math.ceil(0.95 * len(dists))) - 1
    if idx < 0:
        idx = 0
    return dists[idx]


def assd_score(y_true, y_pred, ignore_index=None):
    """ASSD：两组边界像素双向最近邻距离的平均（平均对称表面距离，像素单位）。"""
    who = "assd_score"
    rows_t, rows_p, ignore_index = _seg_maps(y_true, y_pred, who, ignore_index)
    gt = _seg_boundary(rows_t, ignore_index)
    pd = _seg_boundary(rows_p, ignore_index)
    if not gt and not pd:
        return 0.0
    if not gt or not pd:
        raise ValueError(f"{who}: 一侧没有任何边界像素，ASSD 无定义")
    total = sum(_seg_min_dist(q, pd) for q in gt)
    total += sum(_seg_min_dist(q, gt) for q in pd)
    return total / float(len(gt) + len(pd))


def nsd_score(y_true, y_pred, tolerance=1.0, ignore_index=None):
    """NSD：两组边界像素在 tolerance 内互相命中的比例平均（归一化表面距离）。"""
    who = "nsd_score"
    rows_t, rows_p, ignore_index = _seg_maps(y_true, y_pred, who, ignore_index)
    if isinstance(tolerance, bool) or not isinstance(tolerance, (int, float)):
        raise ValueError(f"{who}: tolerance 必须是数字")
    tolerance = float(tolerance)
    if tolerance < 0.0 or tolerance != tolerance:
        raise ValueError(f"{who}: tolerance 必须是有限的非负数，收到 {tolerance}")
    gt = _seg_boundary(rows_t, ignore_index)
    pd = _seg_boundary(rows_p, ignore_index)
    if not gt and not pd:
        return 1.0
    if not gt or not pd:
        return 0.0
    hit_t = sum(1 for q in pd if _seg_min_dist(q, gt) <= tolerance)
    hit_p = sum(1 for q in gt if _seg_min_dist(q, pd) <= tolerance)
    return 0.5 * (hit_t / float(len(pd)) + hit_p / float(len(gt)))


def surface_dice(y_true, y_pred, tolerance=1.0, ignore_index=None):
    """Surface Dice：NSD 的别名（边界命中率平均，常与 HD95/ASSD 一起报告）。"""
    return nsd_score(y_true, y_pred, tolerance=tolerance, ignore_index=ignore_index)


def _mot_frame(item, who, tag):
    if not isinstance(item, dict):
        raise ValueError(f"{who}: {tag} 必须是 {{'boxes','ids'}} 字典")
    boxes = item.get("boxes", [])
    ids = item.get("ids", [])
    if not isinstance(boxes, (list, tuple)) or not isinstance(ids, (list, tuple)):
        raise ValueError(f"{who}: {tag} 的 boxes/ids 必须是列表")
    if len(boxes) != len(ids):
        raise ValueError(f"{who}: {tag} 的 boxes 有 {len(boxes)} 个、ids 有 {len(ids)} 个")
    out_boxes = [_det_box(b, who, f"{tag}.boxes[{j}]") for j, b in enumerate(boxes)]
    out_ids = []
    for j, v in enumerate(ids):
        if isinstance(v, bool) or not isinstance(v, int):
            raise ValueError(f"{who}: {tag}.ids[{j}] 必须是整数轨迹 id")
        out_ids.append(v)
    if len(set(out_ids)) != len(out_ids):
        raise ValueError(f"{who}: {tag} 的轨迹 id 有重复")
    return out_boxes, out_ids


def mota_motp_idf1(gt_frames, pred_frames, iou_threshold=0.5):
    """MOTA / MOTP / IDF1：多目标跟踪的关联指标。

    每帧的 gt 是 ``{'boxes': [...], 'ids': [...]}``，pred 同形（pred 可另带
    ``scores``，本函数不使用）。按 IoU 贪心逐帧匹配（同帧内不重复用框），
    MOTA = 1 - (FN+FP+IDSW)/GT，MOTP = 已匹配框的平均 IoU，
    IDF1 用「gt id × pred id」共现矩阵的贪心二分匹配求 IDTP 后
    2·IDTP/(2·IDTP+IDFP+IDFN)。
    """
    who = "mota_motp_idf1"
    if not isinstance(gt_frames, (list, tuple)) or not isinstance(pred_frames, (list, tuple)):
        raise ValueError(f"{who}: gt_frames/pred_frames 必须都是列表")
    if len(gt_frames) != len(pred_frames):
        raise ValueError(f"{who}: 帧数不一致（{len(gt_frames)} vs {len(pred_frames)}）")
    if not gt_frames:
        raise ValueError(f"{who}: 至少要有一帧")
    thr = _det_check_iou(iou_threshold, who)
    n_gt = 0
    n_pred = 0
    n_fn = 0
    n_fp = 0
    n_match = 0
    n_idsw = 0
    iou_sum = 0.0
    pair_counts = {}
    for f, (gt, pred) in enumerate(zip(gt_frames, pred_frames)):
        gb, gid = _mot_frame(gt, who, f"gt_frames[{f}]")
        pb, pid = _mot_frame(pred, who, f"pred_frames[{f}]")
        n_gt += len(gb)
        n_pred += len(pb)
        pairs = []
        for i in range(len(gb)):
            for j in range(len(pb)):
                iou = box_iou(gb[i], pb[j])
                if iou >= thr:
                    pairs.append((iou, i, j))
        pairs.sort(key=lambda t: (-t[0], t[1], t[2]))
        used_g, used_p = set(), set()
        for iou, i, j in pairs:
            if i in used_g or j in used_p:
                continue
            used_g.add(i)
            used_p.add(j)
            n_match += 1
            iou_sum += iou
            if gid[i] != pid[j]:
                n_idsw += 1
            key = (gid[i], pid[j])
            pair_counts[key] = pair_counts.get(key, 0) + 1
        n_fn += len(gb) - len(used_g)
        n_fp += len(pb) - len(used_p)
    if n_gt == 0:
        raise ValueError(f"{who}: 没有任何真实框，MOTA/IDF1 无定义")
    mota = 1.0 - (n_fn + n_fp + n_idsw) / float(n_gt)
    motp = (iou_sum / n_match) if n_match else 0.0
    idtp = 0
    used_gt, used_pd = set(), set()
    for (g, p), cnt in sorted(pair_counts.items(), key=lambda kv: (-kv[1], kv[0])):
        if g in used_gt or p in used_pd:
            continue
        used_gt.add(g)
        used_pd.add(p)
        idtp += cnt
    idfp = n_pred - idtp
    idfn = n_gt - idtp
    denom = 2 * idtp + idfp + idfn
    idf1 = (2.0 * idtp / float(denom)) if denom else 0.0
    return {
        "mota": mota,
        "motp": motp,
        "idf1": idf1,
        "idtp": idtp,
        "idfp": idfp,
        "idfn": idfn,
        "idswitches": n_idsw,
        "gt": n_gt,
        "pred": n_pred,
    }


def precision_at_k(y_relevance, y_score, k=None):
    """P@k：前 k 个里相关文档所占比例（分母是 min(k, 文档数)）。"""
    who = "precision_at_k"
    rel, order = _rank_query(y_relevance, y_score, who)
    k = _rank_k(k, len(rel), who)
    return sum(_rank_top(rel, order, k)) / float(k)


def recall_at_k(y_relevance, y_score, k=None):
    """R@k：前 k 个里命中的相关文档占全部相关文档的比例。"""
    who = "recall_at_k"
    rel, order = _rank_query(y_relevance, y_score, who)
    k = _rank_k(k, len(rel), who)
    total = sum(rel)
    if total <= 0.0:
        raise ValueError(f"{who}: 该查询没有任何相关文档，召回率无定义")
    return sum(_rank_top(rel, order, k)) / total


def hit_rate_at_k(y_relevance, y_score, k=None):
    """HitRate@k：前 k 个里至少命中一个相关文档则为 1.0，否则 0.0。"""
    who = "hit_rate_at_k"
    rel, order = _rank_query(y_relevance, y_score, who)
    k = _rank_k(k, len(rel), who)
    return 1.0 if sum(_rank_top(rel, order, k)) > 0.0 else 0.0


def reciprocal_rank(y_relevance, y_score):
    """RR：第一个相关文档的排名倒数；一个都没有则为 0.0。"""
    who = "reciprocal_rank"
    rel, order = _rank_query(y_relevance, y_score, who)
    for rank, i in enumerate(order, 1):
        if rel[i] > 0.0:
            return 1.0 / rank
    return 0.0


def average_precision_at_k(y_relevance, y_score, k=None):
    """AP@k：每个命中位置的 P@i 取平均，再除以 min(相关总数, k)。"""
    who = "average_precision_at_k"
    rel, order = _rank_query(y_relevance, y_score, who)
    k = _rank_k(k, len(rel), who)
    total = sum(rel)
    if total <= 0.0:
        raise ValueError(f"{who}: 该查询没有任何相关文档，AP 无定义")
    hits = 0
    acc = 0.0
    for rank, r in enumerate(_rank_top(rel, order, k), 1):
        if r > 0.0:
            hits += 1
            acc += hits / float(rank)
    return acc / min(total, float(k))


def ndcg_at_k(y_relevance, y_score, k=None):
    """NDCG@k：增益 2^rel−1、折扣 1/log2(rank+1)，用理想排序归一化。"""
    who = "ndcg_at_k"
    rel, order = _rank_query(y_relevance, y_score, who, graded=True)
    k = _rank_k(k, len(rel), who)
    dcg = 0.0
    for rank, r in enumerate(_rank_top(rel, order, k), 1):
        dcg += (2.0 ** r - 1.0) / math.log2(rank + 1.0)
    ideal = sorted(rel, reverse=True)[:k]
    idcg = 0.0
    for rank, r in enumerate(ideal, 1):
        idcg += (2.0 ** r - 1.0) / math.log2(rank + 1.0)
    if idcg <= 0.0:
        raise ValueError(f"{who}: 该查询的相关性全为 0，NDCG 无定义")
    return dcg / idcg


def _rank_batches(y_relevance, y_score, who):
    """校验「多条查询」的输入形状，返回 list 副本。"""
    if not isinstance(y_relevance, (list, tuple)) or not isinstance(y_score, (list, tuple)):
        raise ValueError(f"{who}: y_relevance / y_score 必须是「每条查询一个列表」的列表")
    if len(y_relevance) != len(y_score):
        raise ValueError(
            f"{who}: 查询数不一致（{len(y_relevance)} vs {len(y_score)}）")
    if not y_relevance:
        raise ValueError(f"{who}: 至少要有一条查询")
    rel_out, score_out = [], []
    for i, (a, b) in enumerate(zip(y_relevance, y_score)):
        if not isinstance(a, (list, tuple)) or not isinstance(b, (list, tuple)):
            raise ValueError(f"{who}: 第 {i} 条查询的相关性/分数必须是列表")
        if len(a) != len(b):
            raise ValueError(
                f"{who}: 第 {i} 条查询的相关性长度 {len(a)} 与分数长度 {len(b)} 不一致")
        rel_out.append(list(a))
        score_out.append(list(b))
    return rel_out, score_out


def mean_average_precision_at_k(y_relevance, y_score, k=None):
    """MAP@k：各查询 AP@k 的平均。"""
    who = "mean_average_precision_at_k"
    rel, score = _rank_batches(y_relevance, y_score, who)
    vals = [average_precision_at_k(a, b, k) for a, b in zip(rel, score)]
    return sum(vals) / float(len(vals))


def mean_ndcg_at_k(y_relevance, y_score, k=None):
    """平均 NDCG@k。"""
    who = "mean_ndcg_at_k"
    rel, score = _rank_batches(y_relevance, y_score, who)
    vals = [ndcg_at_k(a, b, k) for a, b in zip(rel, score)]
    return sum(vals) / float(len(vals))


def mean_reciprocal_rank(y_relevance, y_score):
    """MRR：各查询 RR 的平均。"""
    who = "mean_reciprocal_rank"
    rel, score = _rank_batches(y_relevance, y_score, who)
    vals = [reciprocal_rank(a, b) for a, b in zip(rel, score)]
    return sum(vals) / float(len(vals))


def coverage_at_k(y_score, k=None):
    """Coverage@k：所有查询的 top-k 合起来覆盖了多少比例的物品。

    传「每条查询一行分数」的矩阵，列下标即物品编号；覆盖率 =
    曾进入任一 top-k 的物品数 / 物品总数。k=None 时等于全量。
    """
    who = "coverage_at_k"
    if not isinstance(y_score, (list, tuple)):
        raise ValueError(f"{who}: y_score 必须是「每条查询一行分数」的列表")
    if not y_score:
        raise ValueError(f"{who}: 至少要有一条查询")
    rows = []
    for i, row in enumerate(y_score):
        if not isinstance(row, (list, tuple)):
            raise ValueError(f"{who}: 第 {i} 行必须是列表")
        if not row:
            raise ValueError(f"{who}: 第 {i} 行不能为空")
        rows.append([_metric_number(v, who, j) for j, v in enumerate(row)])
    width = len(rows[0])
    for i, row in enumerate(rows):
        if len(row) != width:
            raise ValueError(
                f"{who}: 第 {i} 行宽度 {len(row)} 与第一行 {width} 不一致")
    k = _rank_k(k, width, who)
    seen = set()
    for row in rows:
        order = sorted(range(width), key=lambda j: (-row[j], j))
        seen.update(order[:k])
    return len(seen) / float(width)


def median_absolute_error(y_true, y_pred) -> float:
    """MedAE：绝对误差的中位数（比 MAE 抗离群点）。"""
    yt, yp = _regression_pairs(y_true, y_pred, "median_absolute_error")
    errs = sorted(abs(t - p) for t, p in zip(yt, yp))
    n = len(errs)
    mid = n // 2
    if n % 2:
        return errs[mid]
    return 0.5 * (errs[mid - 1] + errs[mid])


def _nonneg_targets(y_true, y_pred, who):
    yt, yp = _regression_pairs(y_true, y_pred, who)
    for i, v in enumerate(yt):
        if v < 0.0:
            raise ValueError(f"{who}: y_true[{i}] = {v} 为负，对数空间的指标要求非负")
    for i, v in enumerate(yp):
        if v < 0.0:
            raise ValueError(f"{who}: y_pred[{i}] = {v} 为负，对数空间的指标要求非负")
    return yt, yp


def mean_squared_log_error(y_true, y_pred) -> float:
    """MSLE = mean((log1p(y_true) - log1p(y_pred))^2)，要求两者非负。"""
    yt, yp = _nonneg_targets(y_true, y_pred, "mean_squared_log_error")
    return sum((math.log1p(t) - math.log1p(p)) ** 2
               for t, p in zip(yt, yp)) / len(yt)


def root_mean_squared_log_error(y_true, y_pred) -> float:
    """RMSLE = sqrt(MSLE)。"""
    return math.sqrt(mean_squared_log_error(y_true, y_pred))


def explained_variance_score(y_true, y_pred) -> float:
    """ExplainedVariance = 1 - Var(y_true - y_pred) / Var(y_true)。

    与 R² 的区别：不惩罚系统性偏移（偏差项被消掉）。真实标签方差为 0 时，
    完全预测返回 1.0，否则返回 0.0（与 R² 的常量目标约定一致）。
    """
    yt, yp = _regression_pairs(y_true, y_pred, "explained_variance_score")
    n = len(yt)
    mean_t = sum(yt) / n
    diffs = [t - p for t, p in zip(yt, yp)]
    mean_d = sum(diffs) / n
    var_t = sum((t - mean_t) ** 2 for t in yt) / n
    var_d = sum((d - mean_d) ** 2 for d in diffs) / n
    if var_t == 0.0:
        return 1.0 if var_d == 0.0 else 0.0
    return 1.0 - var_d / var_t


def adjusted_r2_score(y_true, y_pred, n_features: int) -> float:
    """调整 R²：1 - (1-R²)(n-1)/(n-p-1)，n 是展平后的样本数、p 是特征数。"""
    if isinstance(n_features, bool) or not isinstance(n_features, int):
        raise TypeError(f"adjusted_r2_score: n_features 必须是 int，收到 {type(n_features).__name__}")
    if n_features < 1:
        raise ValueError(f"adjusted_r2_score: n_features 必须 >= 1，收到 {n_features}")
    yt, _ = _regression_pairs(y_true, y_pred, "adjusted_r2_score")
    n = len(yt)
    if n <= n_features + 1:
        raise ValueError(
            f"adjusted_r2_score: 样本数 {n} 不足以估计 {n_features} 个特征"
            f"（需要 n > p + 1）")
    r2 = r2_score(y_true, y_pred)
    return 1.0 - (1.0 - r2) * (n - 1) / (n - n_features - 1)


def mean_pinball_loss(y_true, y_pred, quantile: float = 0.5) -> float:
    """分位数损失（数值口径），与 `quantile_loss` 的损失定义一致。"""
    if isinstance(quantile, bool) or not isinstance(quantile, (int, float)):
        raise TypeError(f"mean_pinball_loss: quantile 必须是数字，收到 {type(quantile).__name__}")
    if not 0.0 < float(quantile) < 1.0:
        raise ValueError(f"mean_pinball_loss: quantile 必须在 (0, 1) 内，收到 {quantile}")
    yt, yp = _regression_pairs(y_true, y_pred, "mean_pinball_loss")
    q = float(quantile)
    total = 0.0
    for t, p in zip(yt, yp):
        err = t - p
        total += q * err if err >= 0.0 else (q - 1.0) * err
    return total / len(yt)


def _bench_param_count(model) -> int:
    core = getattr(model, "model", model)
    total = 0
    for layer in getattr(core, "layers", ()) or ():
        for w in getattr(layer, "weights", ()) or ():
            total += len(w)
        total += len(getattr(layer, "biases", ()) or ())
    return total


def inference_benchmark(model, x, repeats: int = 50, warmup: int = 5,
                        batch_size: int = None) -> dict:
    """测量前向推理的时间 / 吞吐 / Python 峰值内存。

    - `repeats` 次计时取总计，`warmup` 次预热不计时；
    - `batch_size=None` 时把 `x` 当作单个样本；否则 `x` 是样本列表，按批前向；
    - `peak_memory_bytes` 来自 `tracemalloc`，只统计 Python 堆分配（本库全是
      list[float]，因此可信；不含解释器与 C 扩展的常驻内存）；
    - `params` 是 `weights`/`biases` 的标量总数（非 MLP 层记为 0）。
    """
    if isinstance(repeats, bool) or not isinstance(repeats, int):
        raise TypeError(f"inference_benchmark: repeats 必须是 int，收到 {type(repeats).__name__}")
    if repeats < 1:
        raise ValueError(f"inference_benchmark: repeats 必须 >= 1，收到 {repeats}")
    if isinstance(warmup, bool) or not isinstance(warmup, int):
        raise TypeError(f"inference_benchmark: warmup 必须是 int，收到 {type(warmup).__name__}")
    if warmup < 0:
        raise ValueError(f"inference_benchmark: warmup 必须 >= 0，收到 {warmup}")
    if batch_size is not None:
        if isinstance(batch_size, bool) or not isinstance(batch_size, int):
            raise TypeError(
                f"inference_benchmark: batch_size 必须是 int 或 None，收到 {type(batch_size).__name__}")
        if batch_size < 1:
            raise ValueError(f"inference_benchmark: batch_size 必须 >= 1，收到 {batch_size}")

    if batch_size is None:
        samples = [x]
    else:
        samples = list(x)
        if not samples:
            raise ValueError("inference_benchmark: x 不能是空列表")

    def run_once():
        if batch_size is None:
            return model.forward(samples[0])
        return [model.forward(s) for s in samples]

    for _ in range(warmup):
        run_once()

    tracemalloc.start()
    started = time.perf_counter()
    for _ in range(repeats):
        run_once()
    elapsed = time.perf_counter() - started
    _current, peak = tracemalloc.get_traced_memory()
    tracemalloc.stop()

    calls = repeats
    return {
        "repeats": repeats,
        "warmup": warmup,
        "total_seconds": elapsed,
        "per_call_ms": elapsed * 1000.0 / calls,
        "throughput_per_s": calls / elapsed if elapsed > 0.0 else float("inf"),
        "peak_memory_bytes": peak,
        "params": _bench_param_count(model),
    }


def mean_absolute_error(y_true, y_pred) -> float:
    """MAE（多输出时按全部元素平均）。"""
    yt, yp = _regression_pairs(y_true, y_pred, "mean_absolute_error")
    return sum(abs(t - p) for t, p in zip(yt, yp)) / len(yt)


def root_mean_squared_error(y_true, y_pred) -> float:
    """RMSE（多输出时按全部元素平均）。"""
    yt, yp = _regression_pairs(y_true, y_pred, "root_mean_squared_error")
    return math.sqrt(sum((t - p) ** 2 for t, p in zip(yt, yp)) / len(yt))


def mean_absolute_percentage_error(y_true, y_pred, eps: float = 1e-12) -> float:
    """MAPE（百分比，0.1 表示 10%）；真实值为 0 时用 eps 兜底，避免除零。"""
    if not isinstance(eps, (int, float)) or isinstance(eps, bool) or eps <= 0:
        raise ValueError(f"mean_absolute_percentage_error: eps 必须是正数，收到 {eps!r}")
    yt, yp = _regression_pairs(y_true, y_pred, "mean_absolute_percentage_error")
    total = 0.0
    for t, p in zip(yt, yp):
        denom = abs(t) if abs(t) > eps else eps
        total += abs(t - p) / denom
    return 100.0 * total / len(yt)


def r2_score(y_true, y_pred) -> float:
    """决定系数 R²（多输出时按全部元素统一计算）。

    真实值恒定时返回值与 `Model.score` 一致：完全预测对返回 1.0，否则 0.0
    （原来的 `-1e15` 兜底会让结果无法解读）。
    """
    yt, yp = _regression_pairs(y_true, y_pred, "r2_score")
    mean = sum(yt) / len(yt)
    ss_tot = 0.0
    ss_res = 0.0
    for t, p in zip(yt, yp):
        d = t - mean
        ss_tot += d * d
        r = t - p
        ss_res += r * r
    if not (ss_tot < float("inf") and ss_res < float("inf")):
        raise ValueError(
            "r2_score: 平方和溢出（目标值量级过大），请先把 y 归一化")
    if ss_tot == 0.0:
        return 1.0 if ss_res == 0.0 else 0.0
    return 1.0 - ss_res / ss_tot


def sequence_accuracy(preds, targets) -> float:
    """整条序列全对才算对（Seq2Seq 常用）。"""
    yt, yp = _metric_pairs(targets, preds, "sequence_accuracy")
    hit = 0
    for i, (t, p) in enumerate(zip(yt, yp)):
        if not isinstance(t, (list, tuple)) or not isinstance(p, (list, tuple)):
            raise ValueError(f"sequence_accuracy: 第 {i} 个样本必须是序列")
        if list(t) == list(p):
            hit += 1
    return hit / len(yt)


def _as_tokens(x, who):
    """字符串按空白切分；list/tuple 原样转成 str 列表。"""
    if isinstance(x, str):
        return x.split()
    if isinstance(x, (list, tuple)):
        return [str(t) for t in x]
    raise ValueError(f"{who}: 需要字符串或 token 列表，收到 {type(x).__name__}")


def _ngram_counts(tokens, n):
    counts = {}
    for i in range(len(tokens) - n + 1):
        key = tuple(tokens[i:i + n])
        counts[key] = counts.get(key, 0) + 1
    return counts


def bleu_score(pred, ref, max_n: int = 4) -> float:
    """BLEU（1-4 gram 几何平均 + 简短惩罚，缺失的 n-gram 用 add-1 平滑）。

    pred / ref 可以是字符串（按空白切分）或 token 列表。
    语料级 BLEU 请对多条分别调用后取平均，或自行拼接。
    """
    if isinstance(max_n, bool) or not isinstance(max_n, int) or max_n < 1:
        raise ValueError(f"bleu_score: max_n 必须是 ≥1 的整数，收到 {max_n!r}")
    p_tokens = _as_tokens(pred, "bleu_score.pred")
    r_tokens = _as_tokens(ref, "bleu_score.ref")
    if not p_tokens or not r_tokens:
        return 0.0
    log_sum = 0.0
    for n in range(1, max_n + 1):
        p_counts = _ngram_counts(p_tokens, n)
        r_counts = _ngram_counts(r_tokens, n)
        overlap = 0
        total = max(0, len(p_tokens) - n + 1)
        for key, cnt in p_counts.items():
            overlap += min(cnt, r_counts.get(key, 0))
        if n == 1 and overlap == 0:
            # 连一个词都不重叠：直接判 0，否则 add-1 平滑会让无关句子拿到 0.3+
            return 0.0
        # add-1 平滑只用在 n>=2：短句子的 3/4-gram 常常一个都不命中，
        # 不平滑会让 BLEU 恒为 0（这也是 BLEU 在小样本上的已知缺陷）
        precision = (overlap + 1.0) / (total + 1.0) if n >= 2 else overlap / total
        log_sum += math.log(precision)
    bp = 1.0
    if len(p_tokens) < len(r_tokens):
        bp = math.exp(1.0 - len(r_tokens) / len(p_tokens))
    return bp * math.exp(log_sum / max_n)


def rouge_l(pred, ref) -> float:
    """ROUGE-L 的 F1（基于最长公共子序列）。"""
    p_tokens = _as_tokens(pred, "rouge_l.pred")
    r_tokens = _as_tokens(ref, "rouge_l.ref")
    if not p_tokens or not r_tokens:
        return 0.0
    m, n = len(p_tokens), len(r_tokens)
    # 只存两行，避免长序列吃内存
    prev = [0] * (n + 1)
    for i in range(1, m + 1):
        cur = [0] * (n + 1)
        pi = p_tokens[i - 1]
        for j in range(1, n + 1):
            if pi == r_tokens[j - 1]:
                cur[j] = prev[j - 1] + 1
            else:
                cur[j] = prev[j] if prev[j] >= cur[j - 1] else cur[j - 1]
        prev = cur
    lcs = prev[n]
    if lcs == 0:
        return 0.0
    precision = lcs / m
    recall = lcs / n
    return 2 * precision * recall / (precision + recall)


def evaluate_all(model, x, y) -> dict:
    """按模型任务一次性算出常用指标，返回 dict。

    - 回归：mae / rmse / mape / r2
    - 分类：accuracy / precision / recall / f1（macro）/ confusion_matrix，
           二分类另给 roc_auc；输出是概率时给 top_k_accuracy
    - 其它：只给 loss
    模型类型支持 Model（用它的 task）以及 MLP（按回归处理）。
    """
    if not hasattr(model, "forward"):
        raise TypeError(f"evaluate_all: model 需要 forward()，收到 {type(model).__name__}")
    if not isinstance(x, (list, tuple)) or not isinstance(y, (list, tuple)):
        raise ValueError("evaluate_all: x / y 必须是列表")
    if len(x) != len(y):
        raise ValueError(f"evaluate_all: x 与 y 长度不一致（{len(x)} vs {len(y)}）")
    if not x:
        raise ValueError("evaluate_all: x / y 不能为空")

    task = getattr(model, "task", None)
    result = {"task": task or "unknown", "n_samples": len(x)}

    if task == "regression" or (task is None and not _looks_like_probs(model, x[0])):
        preds = [model.predict(xi) for xi in x]
        result.update({
            "mae": mean_absolute_error(y, preds),
            "rmse": root_mean_squared_error(y, preds),
            "mape": mean_absolute_percentage_error(y, preds),
            "r2": r2_score(y, preds),
        })
        return result

    # 分类：一次前向拿到概率行
    probs = [model.forward(xi) for xi in x]
    n_cls = max(len(row) for row in probs)
    for i, row in enumerate(probs):
        if len(row) != n_cls:
            raise ValueError(
                f"evaluate_all: 第 {i} 个样本输出 {len(row)} 维，其它样本是 {n_cls} 维"
            )
    preds = [max(range(len(row)), key=lambda c: (row[c], -c)) for row in probs]
    labels = [_metric_label(v, "evaluate_all.y", i) for i, v in enumerate(y)]
    for i, t in enumerate(labels):
        if t >= n_cls:
            raise ValueError(
                f"evaluate_all: 第 {i} 个真实类别 {t} 超出输出维度 {n_cls}"
            )

    prf = precision_recall_f1(labels, preds, average="macro")
    result.update({
        "accuracy": accuracy_score(labels, preds),
        "precision": prf["precision"],
        "recall": prf["recall"],
        "f1": prf["f1"],
        "confusion_matrix": confusion_matrix(labels, preds, n_cls),
        "mcc": matthews_corrcoef(labels, preds, n_cls),
    })
    if n_cls > 1:
        result["top_k_accuracy"] = top_k_accuracy(labels, probs, k=min(2, n_cls))
    if n_cls == 2:
        result["roc_auc"] = roc_auc_score(labels, [row[1] for row in probs])
    return result


def _looks_like_probs(model, sample) -> bool:
    """模型没有 task 时，靠输出和是否为 1、是否非负来判断「像不像概率」。"""
    out = model.forward(sample)
    if not isinstance(out, (list, tuple)) or len(out) < 2:
        return False
    total = sum(float(v) for v in out)
    return all(float(v) >= 0.0 for v in out) and abs(total - 1.0) < 1e-9



# ============================================================================
#  模型保存 / 加载 (JSON)
# ============================================================================



def _optimizer_state(optimizer):
    """把 Adam / AdamW 的动量与步数导出成可 JSON 化的 dict。

    其它优化器（SGD / SGDMomentum / RMSprop）的缓冲结构不同，返回 None，
    对应文件里就不写 optimizer 字段（保持向后兼容）。
    """
    name = type(optimizer).__name__
    if name not in ("Adam", "AdamW"):
        return None
    model = optimizer.model
    return {
        "type": name.lower(),
        "lr": optimizer.lr,
        "beta1": optimizer.beta1,
        "beta2": optimizer.beta2,
        "eps": optimizer.eps,
        "step_count": getattr(optimizer, "step_count", 0),
        "m_w": [layer.m_w for layer in model.layers],
        "v_w": [layer.v_w for layer in model.layers],
        "m_b": [layer.m_b for layer in model.layers],
        "v_b": [layer.v_b for layer in model.layers],
    }


def load_optimizer_state(optimizer, state):
    """把 save_model 写下的 optimizer 状态灌回优化器（同类型、同形状才行）。

    返回 True 表示恢复成功；state 为 None 时返回 False。类型或形状不匹配会
    raise ValueError——静默忽略会让人以为「续训」了，其实动量是空的。
    """
    if state is None:
        return False
    want = str(state.get("type", "")).lower()
    got = type(optimizer).__name__.lower()
    if want != got:
        raise ValueError(
            f"load_optimizer_state: 文件里是 {want!r} 的状态，当前优化器是 {got!r}；"
            f"请用 optimizer={want!r} 加载模型"
        )
    model = optimizer.model
    for key in ("m_w", "v_w", "m_b", "v_b"):
        saved = state.get(key)
        if saved is None or len(saved) != len(model.layers):
            raise ValueError(
                f"load_optimizer_state: {key} 的层数 {0 if saved is None else len(saved)}"
                f" 与模型层数 {len(model.layers)} 不一致"
            )
    for i, layer in enumerate(model.layers):
        for attr, key in (("m_w", "m_w"), ("v_w", "v_w"),
                          ("m_b", "m_b"), ("v_b", "v_b")):
            saved_layer = state[key][i]
            cur = getattr(layer, attr)
            # 权重缓冲是二维、偏置缓冲是一维：分别校验形状
            if isinstance(cur[0], list):
                ok = len(saved_layer) == len(cur) and all(
                    isinstance(a, list) and len(a) == len(b)
                    for a, b in zip(saved_layer, cur)
                )
            else:
                ok = len(saved_layer) == len(cur) and all(
                    not isinstance(a, list) for a in saved_layer
                )
            if not ok:
                raise ValueError(
                    f"load_optimizer_state: 第 {i} 层 {key} 形状不匹配"
                )
            setattr(layer, attr, [[float(v) for v in row] for row in saved_layer]
                    if isinstance(cur[0], list)
                    else [float(v) for v in saved_layer])
    optimizer.step_count = int(state.get("step_count", 0))
    return True


def save_model(model, filepath: str, task: str = None, optimizer=None,
               quiet: bool = False, loss: str = None, loss_kwargs: dict = None):
    """将 MLP 模型保存为 JSON 文件

    task: 可选，"regression" / "classification"。会写进文件，供旧格式（没有逐层
          activation 记录）加载时判断输出层该用 linear 还是 softmax。
    每层还会写入 activation 字段，因此新格式文件不依赖 task 也能正确还原。
    optimizer: 可选，传入 Adam / AdamW 时同时保存动量与步数，配合
          load_optimizer_state 可以精确续训（不传则文件与旧版完全一致）。
    quiet: True 时不打印保存提示（checkpoint 每轮保存会刷屏）。
    """
    data = {
        "type": "MLP",
        "layer_sizes": model.layer_sizes,
        # task 用于加载时判断是分类器还是回归器（旧文件没有该字段）
        "task": task,
        "layers": []
    }
    # 损失函数名与参数（如 focal 的 gamma、CE 的 label_smoothing）：
    # 旧文件没有这两个字段，读的时候缺省即可
    if loss is not None:
        data["loss"] = loss
    if loss_kwargs:
        data["loss_kwargs"] = dict(loss_kwargs)
    for layer in model.layers:
        # 推断激活函数类型名称：优先用 Layer 自己记录的名字
        act_name = getattr(layer, "activation_name", None)
        if act_name is None:
            # 兼容没有 activation_name 属性的旧对象
            act_name = "linear"
            if layer.act_fn == layer._leaky_relu:
                act_name = "leaky_relu"
            elif layer.act_fn == layer._relu:
                act_name = "relu"
            elif layer.act_fn == layer._softmax:
                act_name = "softmax"

        layer_data = {
            "fan_in": layer.fan_in,
            "fan_out": layer.fan_out,
            "is_output": layer.is_output,
            "activation": act_name,
            "weights": layer.weights,
            "biases": layer.biases,
        }
        data["layers"].append(layer_data)

    if optimizer is not None:
        state = _optimizer_state(optimizer)
        if state is not None:
            data["optimizer"] = state

    try:
        with open(filepath, "w", encoding="utf-8") as f:
            # allow_nan=False：否则会写出 RFC-4627 不合法的 NaN / Infinity 字面量，
            # 严格 JSON 解析器（以及大多数其它语言）读不了
            json.dump(data, f, indent=2, ensure_ascii=False, allow_nan=False)
    except ValueError as e:
        raise ValueError(
            f"save_model: 权重里含 NaN / Inf，无法写出合法 JSON（{e}）；"
            "训练可能发散了"
        ) from None
    if not quiet:
        print(f"模型已保存到: {filepath}")


def load_model(filepath: str, default_output_activation: Optional[str] = None) -> MLP:
    """从 JSON 文件加载 MLP 模型

    default_output_activation:
        只对**旧格式**（没有逐层 activation 记录）生效；带 activation 的文件会忽略它。
        旧文件无法判断输出层原本是 softmax 还是 linear，回退优先级为：
            显式传入的参数  >  文件里记录的 task（== "classification" 时用 softmax）
            >  "linear"
        也就是说：不传参数时，一个没有 activation、也没有 task 的旧分类器
        会被当成 linear 输出，从而被上层判定为回归模型——这种情况请显式传 "softmax"。

    加载后会校验层数与每层形状（含 weights 实际行列数）是否与 layer_sizes 自洽，
    不一致直接抛 ValueError，不会带着坏权重返回。
    """
    with open(filepath, "r", encoding="utf-8") as f:
        data = json.load(f)

    if data.get("type") != "MLP":
        raise ValueError(f"不支持的类型: {data.get('type')}")
    for _k in ("layer_sizes", "layers"):
        if _k not in data:
            raise ValueError(f"load_model: 文件缺少必需字段 {_k!r}")
    for _i, _ld in enumerate(data["layers"]):
        for _k in ("fan_in", "fan_out", "weights", "biases"):
            if _k not in _ld:
                raise ValueError(f"load_model: 第 {_i} 层缺少字段 {_k!r}")

    # 从保存的数据中读取各层激活函数，兼容旧版（无 activation 字段）
    activations = []
    n_layers = len(data["layers"])
    for i, ld in enumerate(data["layers"]):
        if "activation" in ld:
            activations.append(ld["activation"])
        else:
            # 旧版兼容：最后一层按调用方指定回退，其余按隐层处理
            if i == n_layers - 1:
                # 旧文件没有逐层 activation：优先用调用方指定，其次用 task 推断
                fallback = default_output_activation
                if fallback is None and data.get("task") == "classification":
                    fallback = "softmax"
                activations.append(fallback or "linear")
            else:
                activations.append("leaky_relu")

    # 先校验、后构造：层数偏少时若先造 MLP，会在内部抛裸 IndexError 而非可读信息
    layer_sizes = data["layer_sizes"]
    saved = data["layers"]
    if len(layer_sizes) < 2:
        raise ValueError(
            f"load_model: layer_sizes={layer_sizes} 至少需要 2 个维度（输入+输出）；"
            "0 层的模型没有任何投影，等于恒等映射"
        )
    expect = len(layer_sizes) - 1
    if len(saved) != expect:
        raise ValueError(
            f"load_model: 文件里有 {len(saved)} 层，但 layer_sizes={layer_sizes} 需要 {expect} 层"
        )
    for i, ld in enumerate(saved):
        exp_in, exp_out = layer_sizes[i], layer_sizes[i + 1]
        if ld["fan_in"] != exp_in or ld["fan_out"] != exp_out:
            raise ValueError(
                f"load_model: 第 {i} 层声明形状 {ld['fan_in']}x{ld['fan_out']}，"
                f"与 layer_sizes 推出的 {exp_in}x{exp_out} 不一致"
            )
        w = ld["weights"]
        if len(w) != exp_out or any(len(row) != exp_in for row in w):
            raise ValueError(
                f"load_model: 第 {i} 层 weights 实际形状与声明不符"
                f"（应为 {exp_out} 行 × {exp_in} 列）"
            )
        # 值类型也要校验：JSON 里可能是字符串，读进来不会报错，等到 forward 才
        # TypeError: can't multiply sequence by non-int of type 'float'
        for row in w:
            for v in row:
                if not isinstance(v, (int, float)) or isinstance(v, bool):
                    raise ValueError(
                        f"load_model: 第 {i} 层 weights 含非数值 {v!r}（应为数字）"
                    )
        b = ld["biases"]
        if len(b) != exp_out:
            raise ValueError(
                f"load_model: 第 {i} 层 biases 长度 {len(b)} != fan_out={exp_out}"
            )
        for v in b:
            if not isinstance(v, (int, float)) or isinstance(v, bool):
                raise ValueError(f"load_model: 第 {i} 层 biases 含非数值 {v!r}")

    model = MLP(layer_sizes, activations=activations)
    for i, layer in enumerate(model.layers):
        layer.weights = saved[i]["weights"]
        layer.biases = saved[i]["biases"]

    # 供 Model.load 判断 task 用（MLP 本身没有 task 概念）
    model.saved_task = data.get("task")
    # 损失配置同理（旧文件没有这两个键，get 到 None）
    model.saved_loss = data.get("loss")
    model.saved_loss_kwargs = data.get("loss_kwargs")

    print(f"模型已从 {filepath} 加载")
    return model


"""把本库的 MLP 导出成 ONNX（ModelProto 字节流），并提供最小解析/执行器。

本项目只依赖标准库，所以这里手写 protobuf 编码，而不是引入 onnx/onnxruntime：
- `export_onnx_mlp(model, path=None)`：把一个 `MLP` 导出为 ONNX ModelProto 字节；
  图中每层是一个 `Gemm(transB=1)` + 激活（linear/relu/leaky_relu/tanh/sigmoid/softmax）。
- `onnx_mlp_to_dict(data)`：解析导出的字节，返回 python 字典（用于测试/检查）。
- `onnx_mlp_forward(data, rows)`：执行导出的图，按批计算输出。

边界：只覆盖 MLP（没有 Conv/Attention/RNN），也只支持上述六种激活；
GELU/SiLU/Mish/ELU/SELU 会被拒绝（ONNX 图里没有对应简化节点）。
"""

_OX_ONNX_OPSET = 13
_OX_IR_VERSION = 8
_OX_PRODUCER = "python-standard-library-only-ai"
_OX_ACT_SUPPORTED = ("linear", "relu", "leaky_relu", "tanh", "sigmoid", "softmax")
_OX_ACT_OPS = {
    "linear": "Identity",
    "relu": "Relu",
    "leaky_relu": "LeakyRelu",
    "tanh": "Tanh",
    "sigmoid": "Sigmoid",
    "softmax": "Softmax",
}


# ---------- protobuf 基础编码 ----------

def _ox_varint(n):
    if n < 0:
        n += 1 << 64
    out = bytearray()
    while True:
        b = n & 0x7F
        n >>= 7
        if n:
            out.append(b | 0x80)
        else:
            out.append(b)
            return bytes(out)


def _ox_tag(field, wire):
    return _ox_varint((field << 3) | wire)


def _ox_int(field, value):
    return _ox_tag(field, 0) + _ox_varint(int(value))


def _ox_bytes(field, data):
    return _ox_tag(field, 2) + _ox_varint(len(data)) + data


def _ox_str(field, s):
    return _ox_bytes(field, s.encode("utf-8"))


def _ox_float32(field, value):
    return _ox_tag(field, 5) + struct.pack("<f", float(value))


def _ox_signed_int64_field(field, value):
    return _ox_tag(field, 0) + _ox_varint(int(value) & ((1 << 64) - 1))


# ---------- protobuf 基础解码 ----------

def _ox_read_varint(data, pos):
    shift = 0
    result = 0
    while True:
        if pos >= len(data):
            raise ValueError("onnx: protobuf varint 越界")
        b = data[pos]
        pos += 1
        result |= (b & 0x7F) << shift
        if not (b & 0x80):
            return result, pos
        shift += 7
        if shift > 70:
            raise ValueError("onnx: protobuf varint 过长")


def _ox_decode_message(data):
    """把一段 protobuf 解成 {field: [values]}；wire=0 是 int，2 是 bytes，5 是 float。"""
    out = {}
    pos = 0
    while pos < len(data):
        key, pos = _ox_read_varint(data, pos)
        field = key >> 3
        wire = key & 7
        if wire == 0:
            val, pos = _ox_read_varint(data, pos)
        elif wire == 2:
            ln, pos = _ox_read_varint(data, pos)
            if pos + ln > len(data):
                raise ValueError("onnx: protobuf 长度越界")
            val = data[pos:pos + ln]
            pos += ln
        elif wire == 5:
            if pos + 4 > len(data):
                raise ValueError("onnx: protobuf float32 越界")
            val = struct.unpack("<f", data[pos:pos + 4])[0]
            pos += 4
        elif wire == 1:
            if pos + 8 > len(data):
                raise ValueError("onnx: protobuf float64 越界")
            val = struct.unpack("<d", data[pos:pos + 8])[0]
            pos += 8
        else:
            raise ValueError("onnx: 不支持的 wire type %d" % wire)
        out.setdefault(field, []).append(val)
    return out


def _ox_first(msg, field, default=None):
    vals = msg.get(field)
    return vals[0] if vals else default


def _ox_int_value(msg, field, default=0):
    vals = msg.get(field)
    if not vals:
        return default
    v = vals[0]
    if v >= (1 << 63):
        v -= 1 << 64
    return v


def _ox_packed_ints(data):
    out = []
    pos = 0
    while pos < len(data):
        v, pos = _ox_read_varint(data, pos)
        out.append(v)
    return out


# ---------- ONNX 子结构编码 ----------

def _ox_tensor(name, dims, values):
    body = b""
    packed = b"".join(_ox_varint(d) for d in dims)
    body += _ox_bytes(1, packed)          # dims（packed）
    body += _ox_int(2, 1)                 # data_type = FLOAT
    body += _ox_bytes(9, struct.pack("<%df" % len(values), *[float(v) for v in values]))
    body += _ox_str(8, name)
    return body


def _ox_dim(shape_dim):
    if isinstance(shape_dim, str):
        return _ox_str(2, shape_dim)          # dim_param
    return _ox_int(1, int(shape_dim))          # dim_value


def _ox_tensor_shape(dims):
    body = b"".join(_ox_bytes(1, _ox_dim(d)) for d in dims)
    return body


def _ox_value_info(name, dims):
    tensor_type = _ox_int(1, 1) + _ox_bytes(2, _ox_tensor_shape(dims))
    type_proto = _ox_bytes(1, tensor_type)
    return _ox_str(1, name) + _ox_bytes(2, type_proto)


def _ox_attribute_int(name, value):
    body = _ox_str(1, name) + _ox_signed_int64_field(3, value) + _ox_int(20, 2)
    return body


def _ox_attribute_float(name, value):
    body = _ox_str(1, name) + _ox_float32(2, value) + _ox_int(20, 1)
    return body


def _ox_node(op_type, inputs, outputs, name, attributes=()):
    body = b""
    for inp in inputs:
        body += _ox_str(1, inp)
    for out in outputs:
        body += _ox_str(2, out)
    body += _ox_str(3, name)
    body += _ox_str(4, op_type)
    for attr in attributes:
        body += _ox_bytes(5, attr)
    return body


def _ox_operator_set(domain, version):
    body = _ox_str(1, domain) + _ox_int(2, version)
    return body


# ---------- 导出 ----------

def _ox_check_mlp(model):
    if not isinstance(model, MLP):
        raise TypeError("export_onnx_mlp: model 必须是 MLP")
    for i, layer in enumerate(model.layers):
        act = layer.activation_name
        if act not in _OX_ACT_SUPPORTED:
            raise ValueError(
                "export_onnx_mlp: 第 %d 层激活 %r 暂不支持导出（支持 %s）"
                % (i + 1, act, "/".join(_OX_ACT_SUPPORTED)))


def export_onnx_mlp(model, path=None):
    """把 `MLP` 导出为 ONNX ModelProto 字节（可选写入 `path`），返回 bytes。"""
    _ox_check_mlp(model)
    if path is not None and not isinstance(path, str):
        raise TypeError("export_onnx_mlp: path 必须是字符串或 None")
    nodes = []
    inits = []
    current = "input"
    for i, layer in enumerate(model.layers):
        w_name = "W%d" % i
        b_name = "b%d" % i
        z_name = "z%d" % i
        y_name = "y%d" % i
        flat_w = [float(v) for row in layer.weights for v in row]
        inits.append(_ox_tensor(w_name, [layer.fan_out, layer.fan_in], flat_w))
        inits.append(_ox_tensor(b_name, [layer.fan_out], [float(v) for v in layer.biases]))
        attrs = [_ox_attribute_int("transB", 1)]
        nodes.append(_ox_node("Gemm", [current, w_name, b_name], [z_name],
                              "gemm%d" % i, attrs))
        act = layer.activation_name
        op = _OX_ACT_OPS[act]
        act_attrs = []
        if act == "leaky_relu":
            act_attrs.append(_ox_attribute_float("alpha", 0.01))
        elif act == "softmax":
            act_attrs.append(_ox_attribute_int("axis", -1))
        nodes.append(_ox_node(op, [z_name], [y_name], "act%d" % i, act_attrs))
        current = y_name
    graph = b""
    for node in nodes:
        graph += _ox_bytes(1, node)
    graph += _ox_str(2, "mlp")
    for init in inits:
        graph += _ox_bytes(5, init)
    graph += _ox_bytes(11, _ox_value_info("input", ["batch", model.layer_sizes[0]]))
    graph += _ox_bytes(12, _ox_value_info(current, ["batch", model.layer_sizes[-1]]))
    model_proto = b""
    model_proto += _ox_int(1, _OX_IR_VERSION)
    opset = _ox_operator_set("", _OX_ONNX_OPSET)
    model_proto += _ox_bytes(2, opset)
    model_proto += _ox_str(3, _OX_PRODUCER)
    model_proto += _ox_str(4, "1.0")
    model_proto += _ox_bytes(7, graph)
    data = model_proto
    if path is not None:
        with open(path, "wb") as f:
            f.write(data)
    return data


# ---------- 解析 ----------

def _ox_parse_value_info(raw):
    msg = _ox_decode_message(raw)
    name = _ox_first(msg, 1, b"").decode("utf-8")
    dims = []
    type_raw = _ox_first(msg, 2)
    if type_raw is not None:
        type_msg = _ox_decode_message(type_raw)
        tensor_raw = _ox_first(type_msg, 1)
        if tensor_raw is not None:
            tmsg = _ox_decode_message(tensor_raw)
            shape_raw = _ox_first(tmsg, 2)
            if shape_raw is not None:
                shape_msg = _ox_decode_message(shape_raw)
                for dim_raw in shape_msg.get(1, []):
                    dmsg = _ox_decode_message(dim_raw)
                    if 1 in dmsg:
                        dims.append(_ox_int_value(dmsg, 1))
                    else:
                        dims.append(_ox_first(dmsg, 2, b"").decode("utf-8"))
    return {"name": name, "dims": dims}


def _ox_parse_attribute(raw):
    msg = _ox_decode_message(raw)
    name = _ox_first(msg, 1, b"").decode("utf-8")
    attr_type = _ox_int_value(msg, 20, 0)
    if attr_type == 1:
        return name, float(_ox_first(msg, 2, 0.0))
    if attr_type == 2:
        return name, _ox_int_value(msg, 3, 0)
    if attr_type == 3:
        return name, _ox_first(msg, 4, b"").decode("utf-8")
    return name, None


def _ox_parse_tensor(raw):
    msg = _ox_decode_message(raw)
    dims = []
    for chunk in msg.get(1, []):
        if isinstance(chunk, bytes):
            dims.extend(_ox_packed_ints(chunk))
        else:
            dims.append(chunk)
    name = _ox_first(msg, 8, b"").decode("utf-8")
    raw_data = _ox_first(msg, 9, b"")
    values = list(struct.unpack("<%df" % (len(raw_data) // 4), raw_data)) if raw_data else []
    return {"name": name, "dims": dims, "values": values}


def onnx_mlp_to_dict(data):
    """解析 `export_onnx_mlp` 产出的字节，返回结构化字典（用于检查/测试）。"""
    if not isinstance(data, (bytes, bytearray)):
        raise TypeError("onnx_mlp_to_dict: data 必须是 bytes")
    msg = _ox_decode_message(bytes(data))
    graph_raw = _ox_first(msg, 7)
    if graph_raw is None:
        raise ValueError("onnx_mlp_to_dict: 缺少 graph 字段")
    gmsg = _ox_decode_message(graph_raw)
    nodes = []
    for node_raw in gmsg.get(1, []):
        nmsg = _ox_decode_message(node_raw)
        nodes.append({
            "op_type": _ox_first(nmsg, 4, b"").decode("utf-8"),
            "name": _ox_first(nmsg, 3, b"").decode("utf-8"),
            "inputs": [v.decode("utf-8") for v in nmsg.get(1, [])],
            "outputs": [v.decode("utf-8") for v in nmsg.get(2, [])],
            "attributes": dict(_ox_parse_attribute(a) for a in nmsg.get(5, [])),
        })
    inits = {}
    for init_raw in gmsg.get(5, []):
        t = _ox_parse_tensor(init_raw)
        inits[t["name"]] = t
    inputs = [_ox_parse_value_info(v) for v in gmsg.get(11, [])]
    outputs = [_ox_parse_value_info(v) for v in gmsg.get(12, [])]
    opset_raw = _ox_first(msg, 2)
    opset = 0
    if opset_raw is not None:
        omsg = _ox_decode_message(opset_raw)
        opset = _ox_int_value(omsg, 2, 0)
    return {
        "ir_version": _ox_int_value(msg, 1, 0),
        "opset": opset,
        "producer": _ox_first(msg, 3, b"").decode("utf-8"),
        "graph": {
            "name": _ox_first(gmsg, 2, b"").decode("utf-8"),
            "nodes": nodes,
            "initializers": inits,
            "inputs": inputs,
            "outputs": outputs,
        },
    }


# ---------- 执行 ----------

def _ox_matmul(a, b):
    n = len(a)
    k = len(a[0])
    m = len(b[0])
    if len(b) != k:
        raise ValueError("onnx_mlp_forward: 矩阵维度不匹配")
    out = []
    for r in range(n):
        row = [0.0] * m
        ar = a[r]
        for c in range(m):
            acc = 0.0
            for i in range(k):
                acc += ar[i] * b[i][c]
            row[c] = acc
        out.append(row)
    return out


def _ox_softmax_rows(mat):
    out = []
    for row in mat:
        mx = max(row)
        ex = [math.exp(v - mx) for v in row]
        tot = sum(ex)
        out.append([v / tot for v in ex])
    return out


def onnx_mlp_forward(data, rows):
    """执行导出的 ONNX 字节，`rows` 是 (样本数, 输入维度)；返回输出矩阵。"""
    parsed = onnx_mlp_to_dict(data)
    graph = parsed["graph"]
    inits = graph["initializers"]
    in_dim = graph["inputs"][0]["dims"][-1]
    n = len(rows)
    if n < 1:
        raise ValueError("onnx_mlp_forward: rows 不能为空")
    tensors = {}
    for name, tensor in inits.items():
        dims = tensor["dims"]
        vals = tensor["values"]
        if len(dims) == 2:
            rows_n, cols_n = dims
            tensors[name] = [vals[i * cols_n:(i + 1) * cols_n] for i in range(rows_n)]
        else:
            tensors[name] = list(vals)
    for r in rows:
        if not isinstance(r, (list, tuple)) or len(r) != in_dim:
            raise ValueError("onnx_mlp_forward: 每行长度必须等于输入维度 %d" % in_dim)
        for v in r:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("onnx_mlp_forward: 输入必须是数字")
    tensors["input"] = [[float(v) for v in r] for r in rows]
    for node in graph["nodes"]:
        op = node["op_type"]
        args = [tensors[name] for name in node["inputs"]]
        if op == "Gemm":
            a, w, b = args
            tr = node["attributes"].get("transB", 0)
            wm = [list(col) for col in zip(*w)] if tr else w
            out = _ox_matmul(a, wm)
            for r in range(len(out)):
                for c in range(len(out[0])):
                    out[r][c] += b[c]
        elif op == "MatMul":
            out = _ox_matmul(args[0], args[1])
        elif op == "Add":
            a, b = args
            out = [[a[r][c] + b[c] for c in range(len(a[0]))] for r in range(len(a))]
        elif op == "Identity":
            out = [list(r) for r in args[0]]
        elif op == "Relu":
            out = [[max(0.0, v) for v in r] for r in args[0]]
        elif op == "LeakyRelu":
            alpha = node["attributes"].get("alpha", 0.01)
            out = [[v if v > 0 else alpha * v for v in r] for r in args[0]]
        elif op == "Tanh":
            out = [[math.tanh(v) for v in r] for r in args[0]]
        elif op == "Sigmoid":
            out = [[1.0 / (1.0 + math.exp(-v)) for v in r] for r in args[0]]
        elif op == "Softmax":
            out = _ox_softmax_rows(args[0])
        else:
            raise ValueError("onnx_mlp_forward: 不支持的节点 %r" % op)
        tensors[node["outputs"][0]] = out
    return tensors[graph["outputs"][0]["name"]]

def save_conv_model(conv_layers, fc_model, filepath: str):
    """保存 CNN + MLP 组合模型

    限制（加载方必须知道）：
      - 只接受 Conv2d 作为卷积层，其它模块（MaxPool2d / Flatten 等）会直接抛
        ValueError —— 它们是**无参数**的，存档里不保留其超参数；
      - 因此 load_conv_model 只能恢复 Conv2d 与 MLP，加载方要按自己的结构
        重新构造 pool / flatten（顺序与参数须与保存时一致）。
    """
    data = {
        "type": "CNN_MLP",
        "conv": [],
        "mlp": {
            "layer_sizes": fc_model.layer_sizes,
            "layers": []
        }
    }
    for k, conv in enumerate(conv_layers):
        if not isinstance(conv, Conv2d):
            # 原先静默跳过：MaxPool2d 之类的模块会悄悄从存档里消失，拓扑被改变
            raise ValueError(
                f"save_conv_model: 第 {k} 个模块是 {type(conv).__name__}，"
                f"目前只支持 Conv2d（其余模块无法序列化，静默跳过会丢失拓扑）"
            )
        if isinstance(conv, Conv2d):
            data["conv"].append({
                "cls": "Conv2d",
                "in_channels": conv.in_channels,
                "out_channels": conv.out_channels,
                "kernel_size": conv.kernel_size,
                "stride": conv.stride,
                "padding": conv.padding,
                "groups": conv.groups,
                "dilation": list(conv.dilation),
                "weights": conv.weights,
                "biases": conv.biases,
            })

    for layer in fc_model.layers:
        # 与 save_model 一致：必须记录激活函数，否则 softmax 分类头
        # 重新加载后会退回 MLP 默认的 linear，静默变成回归器
        act_name = getattr(layer, "activation_name", None)
        if act_name is None:
            act_name = "linear"
            if layer.act_fn == layer._leaky_relu:
                act_name = "leaky_relu"
            elif layer.act_fn == layer._relu:
                act_name = "relu"
            elif layer.act_fn == layer._softmax:
                act_name = "softmax"
        data["mlp"]["layers"].append({
            "fan_in": layer.fan_in,
            "fan_out": layer.fan_out,
            "is_output": layer.is_output,
            "activation": act_name,
            "weights": layer.weights,
            "biases": layer.biases,
        })

    with open(filepath, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)
    print(f"CNN+MLP 模型已保存到: {filepath}")


def load_conv_model(filepath: str, default_output_activation: Optional[str] = None):
    """加载 CNN + MLP 组合模型

    default_output_activation:
        只对旧格式（mlp.layers 里没有 activation）生效；旧文件无法判断输出层
        原本是否是 softmax，不传时按 linear 处理，分类头会退化成回归输出。
    """
    with open(filepath, "r", encoding="utf-8") as f:
        data = json.load(f)

    for _k in ("conv", "mlp"):
        if _k not in data:
            raise ValueError(f"load_conv_model: 文件缺少必需字段 {_k!r}（不是 CNN_MLP 存档？）")
    if "layer_sizes" not in data["mlp"] or "layers" not in data["mlp"]:
        raise ValueError("load_conv_model: mlp 缺少 layer_sizes 或 layers 字段")
    for _i, _ld in enumerate(data["mlp"]["layers"]):
        for _k in ("fan_in", "fan_out", "weights", "biases"):
            if _k not in _ld:
                raise ValueError(f"load_conv_model: 第 {_i} 层缺少字段 {_k!r}")

    # 重建 CNN 层（先校验形状，坏文件在加载期就报错）
    conv_layers = []
    for k, cd in enumerate(data["conv"]):
        # groups 是后加的字段：旧存档没有它，按 1 处理
        conv = Conv2d(cd["in_channels"], cd["out_channels"],
                       cd["kernel_size"], cd["stride"], cd["padding"],
                       groups=int(cd.get("groups", 1)),
                       dilation=tuple(cd.get("dilation", (1, 1))))
        oc, ic, kh, kw = conv.out_channels, conv.cg, conv.kh, conv.kw
        cw = cd["weights"]
        shape_ok = (len(cw) == oc
                    and all(len(ch) == ic for ch in cw)
                    and all(len(row) == kw for ch in cw for m in ch for row in m)
                    and all(len(m) == kh for ch in cw for m in ch))
        if not shape_ok:
            raise ValueError(
                f"load_conv_model: 第 {k} 个 Conv2d 的 weights 形状与超参数不符"
                f"（应为 {oc}×{ic}×{kh}×{kw}，注意分组卷积每个输出通道只连 {ic} 个输入通道）"
            )
        if len(cd["biases"]) != oc:
            raise ValueError(
                f"load_conv_model: 第 {k} 个 Conv2d 的 biases 长度 "
                f"{len(cd['biases'])} != out_channels={oc}"
            )
        conv.weights = cw
        conv.biases = cd["biases"]
        conv_layers.append(conv)

    # 重建 MLP（带激活函数）：先校验结构，再构造
    layer_sizes = data["mlp"]["layer_sizes"]
    saved_layers = data["mlp"]["layers"]
    if len(layer_sizes) < 2:
        raise ValueError(
            f"load_conv_model: mlp.layer_sizes={layer_sizes} 至少需要 2 个维度"
        )
    expect = len(layer_sizes) - 1
    if len(saved_layers) != expect:
        raise ValueError(
            f"load_conv_model: 文件里有 {len(saved_layers)} 层，"
            f"但 mlp.layer_sizes={layer_sizes} 需要 {expect} 层"
        )
    for i, ld in enumerate(saved_layers):
        exp_in, exp_out = layer_sizes[i], layer_sizes[i + 1]
        if ld["fan_in"] != exp_in or ld["fan_out"] != exp_out:
            raise ValueError(
                f"load_conv_model: 第 {i} 层声明形状 {ld['fan_in']}x{ld['fan_out']}，"
                f"与 mlp.layer_sizes 推出的 {exp_in}x{exp_out} 不一致"
            )
        w = ld["weights"]
        if len(w) != exp_out or any(len(row) != exp_in for row in w):
            raise ValueError(f"load_conv_model: 第 {i} 层 weights 实际形状与声明不符")
        if len(ld["biases"]) != exp_out:
            raise ValueError(
                f"load_conv_model: 第 {i} 层 biases 长度 {len(ld['biases'])} != fan_out={exp_out}"
            )

    activations = []
    legacy = any("activation" not in ld for ld in saved_layers)
    for i, ld in enumerate(saved_layers):
        if "activation" in ld:
            activations.append(ld["activation"])
        elif i == len(saved_layers) - 1:
            activations.append(default_output_activation or "linear")
        else:
            activations.append("leaky_relu")
    if legacy:
        print("提示: 该文件是旧格式（没有激活记录），隐层按 leaky_relu、"
              f"输出层按 {activations[-1]} 处理；分类头请用 "
              "default_output_activation='softmax' 重新加载")

    model = MLP(layer_sizes, activations=activations)
    for i, layer in enumerate(model.layers):
        layer.weights = saved_layers[i]["weights"]
        layer.biases = saved_layers[i]["biases"]

    print(f"CNN+MLP 模型已从 {filepath} 加载")
    return conv_layers, model


# ============================================================================
#  序列标注 / 多标签分类头
# ============================================================================

def _sigmoid_scalar(z: float) -> float:
    """数值稳定的 sigmoid（与 Layer 的 sigmoid 分支同写法）。"""
    if z >= 0.0:
        return 1.0 / (1.0 + math.exp(-z))
    e = math.exp(z)
    return e / (1.0 + e)


class TokenClassificationHead:
    """Token 级分类头：把 (T, d_model) 序列映射成 (T, num_labels) logits。

    典型用法是接在 `TransformerEncoder` / `CausalLM` 的隐状态之后做 NER、词性标注：

        head = TokenClassificationHead(d_model=32, num_labels=5)
        logits = head.forward(hidden)                 # (T, 5)
        loss, d_logits = head.loss_grad(logits, tags, mask=valid)
        d_hidden = head.backward(d_logits)            # (T, d_model)
        head.adam_step(lr)

    `mask` 为 False 的位置不参与 loss，梯度也恰为 0（右填充时直接用 `mask`）。
    """

    def __init__(self, d_model: int, num_labels: int):
        for name, value in (("d_model", d_model), ("num_labels", num_labels)):
            if isinstance(value, bool) or not isinstance(value, int) or value < 1:
                raise ValueError(f"TokenClassificationHead: {name} 必须是 >= 1 的整数")
        self.d_model = d_model
        self.num_labels = num_labels
        std = math.sqrt(2.0 / d_model)
        self.W = [[random.gauss(0.0, std) for _ in range(d_model)] for _ in range(num_labels)]
        self.b = [0.0] * num_labels
        self.x = None
        self._init_adam()
        self.zero_grad()

    # ---- 参数与状态
    def _named_params(self):
        yield "W", self.W, self.grad_W
        yield "b", self.b, self.grad_b

    def zero_grad(self):
        self.grad_W = _zeros_like(self.W)
        self.grad_b = _zeros_like(self.b)
        self._sync_adam()

    def _init_adam(self):
        self.m = {}
        self.v = {}
        self.step_count = 0
        self._sync_adam()

    def _sync_adam(self):
        for name, param in (("W", self.W), ("b", self.b)):
            if self.m.get(name) is None or len(self.m[name]) != len(param):
                self.m[name] = _zeros_like(param)
                self.v[name] = _zeros_like(param)

    def _init_adam_buffers(self):  # 兼容旧调用名
        self._init_adam()

    def param_count(self):
        return sum(len(row) for row in self.W) + len(self.b)

    # ---- 前向 / 反向
    def forward(self, x_seq):
        if not isinstance(x_seq, (list, tuple)) or not x_seq:
            raise ValueError("TokenClassificationHead.forward: 输入必须是非空序列")
        T = len(x_seq)
        for t, row in enumerate(x_seq):
            if not isinstance(row, (list, tuple)) or len(row) != self.d_model:
                raise ValueError(
                    f"TokenClassificationHead.forward: 第 {t} 个位置维度应为 {self.d_model}")
        self.x = [list(row) for row in x_seq]
        out = []
        for t in range(T):
            xt = self.x[t]
            out.append([sum(map(_mul, self.W[l], xt)) + self.b[l] for l in range(self.num_labels)])
        return out

    def loss_grad(self, logits, targets, mask=None):
        """softmax + 交叉熵，按有效 token 取平均；返回 (loss, d_logits)。"""
        if not isinstance(logits, (list, tuple)) or not logits:
            raise ValueError("TokenClassificationHead.loss_grad: logits 必须是非空序列")
        T = len(logits)
        if not isinstance(targets, (list, tuple)) or len(targets) != T:
            raise ValueError(
                f"TokenClassificationHead.loss_grad: targets 长度应为 {T}，收到 "
                f"{len(targets) if isinstance(targets, (list, tuple)) else type(targets).__name__}")
        if mask is None:
            mask = [True] * T
        if not isinstance(mask, (list, tuple)) or len(mask) != T:
            raise ValueError(
                f"TokenClassificationHead.loss_grad: mask 长度应为 {T}")
        valid = [1 if m else 0 for m in mask]
        n = sum(valid)
        if n == 0:
            raise ValueError("TokenClassificationHead.loss_grad: mask 全为 0，没有可训练的 token")
        loss = 0.0
        d_logits = []
        for t in range(T):
            target = targets[t]
            if isinstance(target, bool) or not isinstance(target, int):
                raise ValueError(
                    f"TokenClassificationHead.loss_grad: 第 {t} 个标签必须是整数，"
                    f"收到 {type(target).__name__}")
            if not 0 <= target < self.num_labels:
                raise ValueError(
                    f"TokenClassificationHead.loss_grad: 第 {t} 个标签 {target} 超出 "
                    f"[0, {self.num_labels})")
            probs = _softmax_row(logits[t])
            if not valid[t]:
                d_logits.append([0.0] * self.num_labels)
                continue
            p = probs[target]
            loss += -math.log(p if p > 1e-12 else 1e-12)
            row = list(probs)
            row[target] -= 1.0
            d_logits.append([v / n for v in row])
        loss /= n
        return loss, d_logits

    def backward(self, d_logits):
        if self.x is None:
            raise RuntimeError("TokenClassificationHead.backward: 必须先 forward")
        if not isinstance(d_logits, (list, tuple)) or len(d_logits) != len(self.x):
            raise ValueError(
                f"TokenClassificationHead.backward: d_logits 长度应为 {len(self.x)}")
        T = len(self.x)
        dx = [[0.0] * self.d_model for _ in range(T)]
        for t in range(T):
            drow = d_logits[t]
            if len(drow) != self.num_labels:
                raise ValueError(
                    f"TokenClassificationHead.backward: 第 {t} 行梯度维度应为 {self.num_labels}")
            xt = self.x[t]
            for l in range(self.num_labels):
                d = drow[l]
                if d == 0.0:
                    continue
                self.grad_b[l] += d
                gw = self.grad_W[l]
                for j in range(self.d_model):
                    gw[j] += d * xt[j]
                for j in range(self.d_model):
                    dx[t][j] += d * self.W[l][j]
        return dx

    def predict(self, logits, mask=None):
        T = len(logits)
        mask = [True] * T if mask is None else mask
        return [max(range(self.num_labels), key=lambda l: logits[t][l]) if mask[t] else -1
                for t in range(T)]

    # ---- 优化
    def sgd_step(self, lr: float = 0.01):
        for name, param, grad in self._named_params():
            if isinstance(param[0], list):
                for i in range(len(param)):
                    for j in range(len(param[i])):
                        param[i][j] -= lr * grad[i][j]
            else:
                for i in range(len(param)):
                    param[i] -= lr * grad[i]

    def adam_step(self, lr: float = 1e-3, b1: float = 0.9, b2: float = 0.999,
                  eps: float = 1e-8):
        self.step_count += 1
        t = self.step_count
        for name, param, grad in self._named_params():
            _adam_apply(param, grad, self.m[name], self.v[name], t, lr, b1, b2, eps)

    def train(self):
        return self

    def eval(self):
        return self


class MultiLabelHead:
    """多标签分类头：每个标签独立 sigmoid，用 BCE-with-logits 计算损失。

    与 `Layer(activation='softmax')` 的区别：多标签允许一个样本同时命中多个类别，
    标签之间不竞争，因此逐标签做二分类。
    """

    def __init__(self, fan_in: int, num_labels: int):
        for name, value in (("fan_in", fan_in), ("num_labels", num_labels)):
            if isinstance(value, bool) or not isinstance(value, int) or value < 1:
                raise ValueError(f"MultiLabelHead: {name} 必须是 >= 1 的整数")
        self.fan_in = fan_in
        self.num_labels = num_labels
        std = math.sqrt(2.0 / fan_in)
        self.W = [[random.gauss(0.0, std) for _ in range(fan_in)] for _ in range(num_labels)]
        self.b = [0.0] * num_labels
        self.x = None
        self._init_adam()
        self.zero_grad()

    def _named_params(self):
        yield "W", self.W, self.grad_W
        yield "b", self.b, self.grad_b

    def zero_grad(self):
        self.grad_W = _zeros_like(self.W)
        self.grad_b = _zeros_like(self.b)
        self._sync_adam()

    def _init_adam(self):
        self.m = {}
        self.v = {}
        self.step_count = 0
        self._sync_adam()

    def _sync_adam(self):
        for name, param in (("W", self.W), ("b", self.b)):
            if self.m.get(name) is None or len(self.m[name]) != len(param):
                self.m[name] = _zeros_like(param)
                self.v[name] = _zeros_like(param)

    def param_count(self):
        return sum(len(row) for row in self.W) + len(self.b)

    def forward(self, x):
        if not isinstance(x, (list, tuple)) or len(x) != self.fan_in:
            raise ValueError(f"MultiLabelHead.forward: 输入维度应为 {self.fan_in}")
        self.x = [float(v) for v in x]
        self.logits = [sum(map(_mul, self.W[l], self.x)) + self.b[l]
                       for l in range(self.num_labels)]
        self.probs = [_sigmoid_scalar(z) for z in self.logits]
        return list(self.probs)

    def loss_grad(self, probs, targets):
        """BCE-with-logits（数值稳定），返回 (loss, d_logits)。"""
        if not isinstance(probs, (list, tuple)) or len(probs) != self.num_labels:
            raise ValueError(f"MultiLabelHead.loss_grad: probs 长度应为 {self.num_labels}")
        if not isinstance(targets, (list, tuple)) or len(targets) != self.num_labels:
            raise ValueError(f"MultiLabelHead.loss_grad: targets 长度应为 {self.num_labels}")
        loss = 0.0
        d_logits = []
        for l in range(self.num_labels):
            y = targets[l]
            if y not in (0, 1, True, False):
                raise ValueError(
                    f"MultiLabelHead.loss_grad: 第 {l} 个标签必须是 0/1 或布尔，收到 {y!r}")
            y = 1.0 if y else 0.0
            z = self.logits[l]
            loss += max(z, 0.0) - z * y + math.log1p(math.exp(-abs(z)))
            d_logits.append((self.probs[l] - y) / self.num_labels)
        return loss / self.num_labels, d_logits

    def backward(self, d_logits):
        if self.x is None:
            raise RuntimeError("MultiLabelHead.backward: 必须先 forward")
        if not isinstance(d_logits, (list, tuple)) or len(d_logits) != self.num_labels:
            raise ValueError(f"MultiLabelHead.backward: d_logits 长度应为 {self.num_labels}")
        dx = [0.0] * self.fan_in
        for l in range(self.num_labels):
            d = d_logits[l]
            if d == 0.0:
                continue
            self.grad_b[l] += d
            gw = self.grad_W[l]
            for j in range(self.fan_in):
                gw[j] += d * self.x[j]
                dx[j] += d * self.W[l][j]
        return dx

    def predict(self, probs=None, threshold: float = 0.5):
        probs = self.probs if probs is None else probs
        if not 0.0 < threshold < 1.0:
            raise ValueError("MultiLabelHead.predict: threshold 必须在 (0, 1) 内")
        return [1 if p >= threshold else 0 for p in probs]

    def sgd_step(self, lr: float = 0.01):
        for _name, param, grad in self._named_params():
            if isinstance(param[0], list):
                for i in range(len(param)):
                    for j in range(len(param[i])):
                        param[i][j] -= lr * grad[i][j]
            else:
                for i in range(len(param)):
                    param[i] -= lr * grad[i]

    def adam_step(self, lr: float = 1e-3, b1: float = 0.9, b2: float = 0.999,
                  eps: float = 1e-8):
        self.step_count += 1
        t = self.step_count
        for name, param, grad in self._named_params():
            _adam_apply(param, grad, self.m[name], self.v[name], t, lr, b1, b2, eps)

    def train(self):
        return self

    def eval(self):
        return self


# ============================================================================
#  PyTorch 数值对齐对比
# ============================================================================

def compare_with_pytorch():
    """
    可选：安装 torch 后运行此函数，逐层对比前向/反向传播数值。
    如果未安装 torch，会自动跳过。
    """
    try:
        import torch
        import torch.nn as nn
    except ImportError:
        print("[跳过] 未安装 PyTorch，无法进行数值对比。pip install torch 后可重试。")
        return

    print("\n" + "=" * 60)
    print("PyTorch 数值对齐验证")
    print("=" * 60)

# ============================================================================
#  设定相同随机种子 & 初始化
# ============================================================================
    torch.manual_seed(42)
    random.seed(42)

    input_dim = 4
    hidden_dim = 6
    output_dim = 2

# ============================================================================
#  PyTorch 模型
# ============================================================================
    pt_model = nn.Sequential(
        nn.Linear(input_dim, hidden_dim, bias=True),
        nn.LeakyReLU(0.01),
        nn.Linear(hidden_dim, hidden_dim, bias=True),
        nn.LeakyReLU(0.01),
        nn.Linear(hidden_dim, output_dim, bias=True),
    )

# ============================================================================
#  我们的模型
# ============================================================================
    our_model = MLP([input_dim, hidden_dim, hidden_dim, output_dim],
                    activations=["leaky_relu", "leaky_relu", "linear"])

    # 对齐权重
    pt_layers = [m for m in pt_model if isinstance(m, nn.Linear)]
    with torch.no_grad():
        for i, (pt_linear, our_layer) in enumerate(zip(pt_layers, our_model.layers)):
            w = pt_linear.weight.data.numpy()
            b = pt_linear.bias.data.numpy()
            # PyTorch Linear: (fan_out, fan_in)
            for j in range(our_layer.fan_out):
                our_layer.weights[j] = w[j].tolist()
                our_layer.biases[j] = float(b[j])

# ============================================================================
#  前向对齐
# ============================================================================
    x_np = [random.uniform(-1, 1) for _ in range(input_dim)]
    x_pt = torch.tensor(x_np, dtype=torch.float32).unsqueeze(0)  # (1, input_dim)

    our_out = our_model.forward(x_np)
    with torch.no_grad():
        pt_out = pt_model(x_pt).squeeze(0).numpy()

    print(f"\n输入: {[round(v, 4) for v in x_np]}")
    print(f"PyTorch 前向: {[round(v, 6) for v in pt_out.tolist()]}")
    print(f"Ours   前向: {[round(v, 6) for v in our_out]}")
    fwd_diff = sum(abs(a - b) for a, b in zip(our_out, pt_out))
    print(f"前向 |Δ| 总和: {fwd_diff:.2e}  {'✓ 通过' if fwd_diff < 1e-5 else '✗ 偏差较大'}")

# ============================================================================
#  反向对齐
# ============================================================================
    target_np = [random.uniform(-1, 1) for _ in range(output_dim)]
    target_pt = torch.tensor(target_np, dtype=torch.float32).unsqueeze(0)

    # PyTorch
    pt_model.zero_grad()
    pt_out2 = pt_model(x_pt)
    pt_loss = nn.functional.mse_loss(pt_out2, target_pt)
    pt_loss.backward()

    # Ours
    our_out2 = our_model.forward(x_np)
    our_loss, our_grad = mse_loss(our_out2, target_np)
    delta = our_grad
    our_grads = []
    for layer in reversed(our_model.layers):
        gw, gb, delta = layer.backward(delta)
        our_grads.insert(0, (gw, gb))

    print(f"\n损失对齐:")
    print(f"  PyTorch loss: {pt_loss.item():.10f}")
    print(f"  Ours   loss:  {our_loss:.10f}")

    all_grad_ok = True
    for i, ((gw, gb), pt_linear) in enumerate(zip(our_grads, pt_layers)):
        pt_gw = pt_linear.weight.grad.numpy()
        pt_gb = pt_linear.bias.grad.numpy()

        gw_flat = [w for row in gw for w in row]
        pt_gw_flat = pt_gw.flatten().tolist()
        diff_w = sum(abs(a - b) for a, b in zip(gw_flat, pt_gw_flat))
        diff_b = sum(abs(a - b) for a, b in zip(gb, pt_gb.tolist()))

        status = "✓" if (diff_w < 1e-5 and diff_b < 1e-5) else "✗"
        if status == "✗":
            all_grad_ok = False
        print(f"  第 {i + 1} 层 grad_w |Δ|={diff_w:.2e}  grad_b |Δ|={diff_b:.2e}  {status}")

    print(f"\n{'全部通过 ✓' if all_grad_ok else '存在偏差 ✗'}")
    return fwd_diff < 1e-5 and all_grad_ok


# ============================================================================
#  训练基础设施：seed / Callback / 形状推断 / 批量推理 / 诊断
# ============================================================================


def set_seed(seed: int):
    """固定全局随机种子（对应 PyTorch 的 torch.manual_seed）。

    只影响 `random` 模块。想让「训练完全可复现」还要给 fit / quick_train /
    train_from_config 传 seed —— 它们用局部 Random，不受这里影响。
    """
    if not isinstance(seed, int) or isinstance(seed, bool):
        raise TypeError(f"set_seed: seed 必须是整数，收到 {type(seed).__name__}")
    random.seed(seed)


class Callback:
    """训练回调基类：继承后按需覆盖钩子，传给 fit(callbacks=[...])。

    钩子：
        on_train_begin(model, info)   info: epochs/batch_size/lr/task/n_train/n_val/resumed_step
        on_epoch_begin(epoch, info)   info: epoch/epochs/lr
        on_epoch_end(epoch, logs)     logs: epoch/train_loss/val_loss/grad_norm/layer_grad_norm/lr
        on_train_end(history)
    回调里抛异常会中断训练（不吞异常）。
    """

    def on_train_begin(self, model, info):
        pass

    def on_epoch_begin(self, epoch, info):
        pass

    def on_epoch_end(self, epoch, logs):
        pass

    def on_train_end(self, history):
        pass


class EarlyStopping(Callback):
    """监控指标，连续 `patience` 轮没有改善就请求 `fit` 停止。

    `mode="min"` 用于 loss（越小越好），`"max"` 用于 accuracy（越大越好）。
    只发出停止请求，不负责回滚权重——要回滚最优权重请用 `fit(restore_best_weights=True)`。
    """

    def __init__(self, monitor='val_loss', patience=5, min_delta=0.0, mode='min'):
        if monitor not in ('train_loss', 'val_loss', 'grad_norm'):
            raise ValueError(
                f"EarlyStopping: monitor 只能是 train_loss/val_loss/grad_norm，收到 {monitor!r}")
        if not isinstance(patience, int) or isinstance(patience, bool) or patience < 1:
            raise ValueError(f"EarlyStopping: patience 必须是 >=1 的整数，收到 {patience!r}")
        if float(min_delta) < 0.0:
            raise ValueError("EarlyStopping: min_delta 不能为负")
        if mode not in ('min', 'max'):
            raise ValueError(f"EarlyStopping: mode 只能是 'min' 或 'max'，收到 {mode!r}")
        self.monitor = monitor
        self.patience = patience
        self.min_delta = float(min_delta)
        self.mode = mode
        self.best = None
        self.bad_epochs = 0
        self.should_stop = False
        self.stopped_epoch = None

    def on_train_begin(self, model, info):
        self.best = None
        self.bad_epochs = 0
        self.should_stop = False
        self.stopped_epoch = None

    def on_epoch_end(self, epoch, logs):
        cur = logs.get(self.monitor)
        if cur is None:
            return
        if self.best is None:
            self.best = cur
            return
        improved = (cur < self.best - self.min_delta) if self.mode == 'min' \
            else (cur > self.best + self.min_delta)
        if improved:
            self.best = cur
            self.bad_epochs = 0
            return
        self.bad_epochs += 1
        if self.bad_epochs >= self.patience:
            self.should_stop = True
            self.stopped_epoch = epoch


class ModelCheckpoint(Callback):
    """每隔 `every` 轮把模型（含优化器状态）存一份；`save_best_only=True` 时只存最优。

    存出来的文件可以直接 `Model.load(path, restore_optimizer=True)`，
    也可以作为 `fit(resume_from=...)` 的输入。
    """

    def __init__(self, path, every=1, monitor='val_loss', save_best_only=False, mode='min'):
        if not isinstance(path, str) or not path:
            raise ValueError("ModelCheckpoint: path 必须是非空字符串")
        if not isinstance(every, int) or isinstance(every, bool) or every < 1:
            raise ValueError(f"ModelCheckpoint: every 必须是 >=1 的整数，收到 {every!r}")
        if mode not in ('min', 'max'):
            raise ValueError(f"ModelCheckpoint: mode 只能是 'min' 或 'max'，收到 {mode!r}")
        self.path = path
        self.every = every
        self.monitor = monitor
        self.save_best_only = bool(save_best_only)
        self.mode = mode
        self.best = None
        self.saved_epochs = []

    def on_train_begin(self, model, info):
        self.best = None
        self.saved_epochs = []
        self._model = model

    def _save(self, model):
        save_model(model.model, self.path, task=model.task,
                   optimizer=model.optimizer, quiet=True)

    def on_epoch_end(self, epoch, logs):
        if not hasattr(self, '_model'):
            return
        model = self._model
        if self.save_best_only:
            cur = logs.get(self.monitor)
            if cur is None:
                return
            better = self.best is None or (
                cur < self.best if self.mode == 'min' else cur > self.best)
            if better:
                self.best = cur
                self._save(model)
                self.saved_epochs.append(epoch)
            return
        if epoch % self.every == 0:
            self._save(model)
            self.saved_epochs.append(epoch)


class LoggingCallback(Callback):
    """把每轮指标写进标准库 `logging`（默认 logger 名 `ai.train`）。"""

    def __init__(self, logger=None, level=logging.INFO):
        self.logger = logger or logging.getLogger('ai.train')
        self.level = level

    def on_train_begin(self, model, info):
        self.logger.log(self.level, "训练开始: epochs=%s batch=%s lr=%s n_train=%s",
                        info.get('epochs'), info.get('batch_size'),
                        info.get('lr'), info.get('n_train'))

    def on_epoch_end(self, epoch, logs):
        self.logger.log(self.level, "epoch %s: train=%.6f val=%s lr=%.6g",
                        epoch, logs['train_loss'],
                        'None' if logs['val_loss'] is None else "%.6f" % logs['val_loss'],
                        logs['lr'])

    def on_train_end(self, history):
        self.logger.log(self.level, "训练结束: %s 轮", len(history.get('train_loss', [])))


class HistoryCallback(Callback):
    """把每轮的 logs 原样收进 `self.records`（画曲线、导出 CSV 都够用）。"""

    def __init__(self):
        self.records = []

    def on_train_begin(self, model, info):
        self.records = []

    def on_epoch_end(self, epoch, logs):
        self.records.append(dict(logs))


_CALLBACK_HOOKS = ('on_train_begin', 'on_epoch_begin', 'on_epoch_end', 'on_train_end')


class EMACallback(Callback):
    """每个 epoch 结束更新一次 EMA 影子权重"""

    def __init__(self, model=None, decay: float = 0.999, warmup: int = 0):
        if model is None:
            raise ValueError("EMACallback: 需要传入 model")
        mlp = getattr(model, "model", model)  # 允许传 Model 包装器
        self.ema = EMA(mlp, decay=decay, warmup=warmup)

    def on_train_begin(self, model, info):
        mlp = getattr(model, "model", model)
        if mlp is not self.ema.model:
            self.ema = EMA(mlp, decay=self.ema.decay, warmup=self.ema.warmup)

    def on_epoch_end(self, epoch, logs):
        self.ema.update()


class SWACallback(Callback):
    """每个 epoch 结束收集一次快照（等价于对 epoch 权重取平均）"""

    def __init__(self, model=None):
        if model is None:
            raise ValueError("SWACallback: 需要传入 model")
        self.swa = SWA(getattr(model, "model", model))

    def on_train_begin(self, model, info):
        mlp = getattr(model, "model", model)
        if mlp is not self.swa.model:
            self.swa = SWA(mlp)

    def on_epoch_end(self, epoch, logs):
        self.swa.update()


def _normalize_callbacks(callbacks):
    """None / 单个回调 / 回调列表 → 列表，并校验四个钩子齐备"""
    if callbacks is None:
        return []
    items = list(callbacks) if isinstance(callbacks, (list, tuple)) else [callbacks]
    for cb in items:
        for hook in _CALLBACK_HOOKS:
            if not callable(getattr(cb, hook, None)):
                raise TypeError(
                    f"fit: 回调 {type(cb).__name__} 缺少可调用的 {hook}()"
                    "（继承 AI.Callback 即可获得默认空实现）"
                )
    return items


def _as_mlp(model, who):
    """Model 或 MLP → MLP"""
    mlp = model.model if isinstance(model, Model) else model
    if not isinstance(mlp, MLP):
        raise TypeError(f"{who}: 需要 MLP 或 Model，收到 {type(model).__name__}")
    if not mlp.layers:
        raise ValueError(f"{who}: 模型没有层")
    return mlp


def _check_samples(x, mlp, who):
    """校验样本列表并转成 list[list[float]]"""
    if isinstance(x, (str, bytes)) or not isinstance(x, (list, tuple)) or not x:
        raise ValueError(f"{who}: x 必须是非空样本列表（单个样本请写成 [x]）")
    n_in = mlp.layers[0].fan_in
    samples = []
    for i, xi in enumerate(x):
        if isinstance(xi, (int, float, bool)) or not isinstance(xi, (list, tuple)):
            raise ValueError(f"{who}: 第 {i} 个样本不是序列（应为 list[float]）")
        if len(xi) != n_in:
            raise ValueError(
                f"{who}: 第 {i} 个样本维度 {len(xi)} 与模型输入维度 {n_in} 不一致"
            )
        samples.append(list(xi))
    return samples


def infer_shapes(model, x):
    """跑一次前向，报告每层的输入/输出维度、激活名、参数量与真实输出。

    不训练、不改权重、不建图。x 是样本列表（单个样本写成 [x]）。
    """
    mlp = _as_mlp(model, "infer_shapes")
    samples = _check_samples(x, mlp, "infer_shapes")
    out = mlp.forward(samples[0])
    layers = []
    total = 0
    for i, layer in enumerate(mlp.layers):
        n = layer.fan_in * layer.fan_out + layer.fan_out
        total += n
        layers.append({
            "layer": i,
            "in": layer.fan_in,
            "out": layer.fan_out,
            "activation": getattr(layer, "activation_name", "unknown"),
            "params": n,
            "output": list(layer.a),
        })
    return {
        "input_shape": [mlp.layers[0].fan_in],
        "output_shape": [mlp.layers[-1].fan_out],
        "params": total,
        "layers": layers,
        "output": list(out),
    }


def predict_batch(model, x, batch_size: int = 64):
    """分块推理：结果与 predict 相同（单样本→list，多样本→list[list]）。

    只是把样本切块逐个前向，数值与逐个 predict 完全一致（同一条计算路径）。
    """
    if not isinstance(batch_size, int) or isinstance(batch_size, bool) or batch_size < 1:
        raise ValueError(f"predict_batch: batch_size 必须是 >=1 的整数，收到 {batch_size!r}")
    is_model = isinstance(model, Model)
    if not is_model and not isinstance(model, MLP):
        raise TypeError(f"predict_batch: 需要 MLP 或 Model，收到 {type(model).__name__}")
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError("predict_batch: x 必须非空（单个样本请写成 [x]）")
    if not isinstance(x[0], (list, tuple)):        # 单个样本
        return model.predict(list(x)) if is_model else model.forward(list(x))
    out = []
    for i in range(0, len(x), batch_size):
        chunk = [list(xi) for xi in x[i:i + batch_size]]
        if is_model:
            out.extend(model.predict(chunk))
        else:
            out.extend(model.forward(xi) for xi in chunk)
    return out


def _collect_activations(model, x, who):
    """跑前向并收集每层的激活输出 → (samples, per_layer[list[float]])"""
    mlp = _as_mlp(model, who)
    samples = _check_samples(x, mlp, who)
    per_layer = [[] for _ in mlp.layers]
    for xi in samples:
        mlp.forward(xi)
        for i, layer in enumerate(mlp.layers):
            per_layer[i].extend(layer.a)
    return samples, mlp, per_layer


def activation_stats(model, x):
    """统计各层激活输出的分布：均值 / 标准差 / 最小 / 最大 / 零值比例。

    用来判断「某层是不是整体死掉了/饱和了」：std 接近 0 或 zero_ratio 接近 1
    通常说明这一层没在学东西。
    """
    samples, mlp, per_layer = _collect_activations(model, x, "activation_stats")
    layers = []
    for i, layer in enumerate(mlp.layers):
        vals = per_layer[i]
        n = len(vals)
        mean = sum(vals) / n
        var = sum((v - mean) ** 2 for v in vals) / n
        zeros = sum(1 for v in vals if v == 0.0)
        layers.append({
            "layer": i,
            "activation": getattr(layer, "activation_name", "unknown"),
            "mean": mean,
            "std": math.sqrt(var),
            "min": min(vals),
            "max": max(vals),
            "zero_ratio": zeros / n,
        })
    return {"samples": len(samples), "layers": layers}


def dead_units(model, x, atol: float = 1e-12):
    """找出「对这批输入从不激活」的单元（按层返回索引与比例）。

    判据：该单元在所有样本上的 |激活| 都 <= atol。对 ReLU 家族这意味着
    「永远不点火」（典型是学习率过大或初始化不当）；linear / softmax 层照算，
    但零激活不代表死亡，结果里用 note 标注。
    """
    if not isinstance(atol, (int, float)) or isinstance(atol, bool) or atol < 0:
        raise ValueError(f"dead_units: atol 必须是 >=0 的数字，收到 {atol!r}")
    samples, mlp, per_layer = _collect_activations(model, x, "dead_units")
    atol = float(atol)
    layers = []
    for i, layer in enumerate(mlp.layers):
        vals = per_layer[i]
        n_samples = len(samples)
        dead = []
        for j in range(layer.fan_out):
            worst = 0.0
            for k in range(n_samples):
                a = abs(vals[k * layer.fan_out + j])
                if a > worst:
                    worst = a
            if worst <= atol:
                dead.append(j)
        act = getattr(layer, "activation_name", "unknown")
        note = None
        if act in ("linear", "softmax"):
            note = f"{act} 层的零激活不代表死亡，仅作参考"
        layers.append({
            "layer": i,
            "activation": act,
            "dead": dead,
            "dead_ratio": len(dead) / layer.fan_out,
            "note": note,
        })
    return {"samples": len(samples), "atol": atol, "layers": layers}


def _layer_norms(grads):
    """每层的梯度范数（层内先平方和再开根号，求和顺序与 _grads_norm 一致）"""
    out = []
    for gw_l, gb_l in grads:
        sq = 0.0
        for row in gw_l:
            for v in row:
                sq += v * v
        for v in gb_l:
            sq += v * v
        out.append(math.sqrt(sq))
    return out


def _accum_layer_norms(dst, grads):
    """把一层的梯度范数累加进 dst"""
    for i, v in enumerate(_layer_norms(grads)):
        dst[i] += v


# ============================================================================
#  High-Level API: Model 封装（sklearn 风格） + 工厂函数
# ============================================================================

def _param_leaves(param):
    """枚举嵌套 list 的叶子路径：[(path, value), ...]"""
    if isinstance(param, list):
        out = []
        for i, item in enumerate(param):
            for path, value in _param_leaves(item):
                out.append(((i,) + path, value))
        return out
    return [((), param)]


def _pget(param, path):
    for i in path:
        param = param[i]
    return param


def _pset(param, path, value):
    for i in path[:-1]:
        param = param[i]
    param[path[-1]] = value


def grad_check(module, x, y=None, loss_fn=None, eps: float = 1e-6,
               tol: float = 1e-5, max_params=None):
    """用中心差分校验解析梯度（纯标准库实现，方便在任意模型上自检）。

    支持三类对象：
        grad_check(mlp, x, y)         # MLP，默认 mse_loss
        grad_check(model, x, y)       # Model（MLP 包装），默认用 model 自己的损失
        grad_check(lm, ids)           # CausalLM，用下一个 token 的交叉熵
        grad_check(s2s, (src, tgt))   # Seq2SeqLM，用 teacher forcing 的交叉熵

    eps:        差分步长
    tol:        相对误差阈值
    max_params: 最多抽查多少个标量参数（None = MLP/Model 全查、CausalLM 抽查 24 个）

    返回 dict：{'ok': bool, 'worst_name': str, 'worst_rel': float,
                'checks': [{'name','rel','analytic','numeric'}, ...],
                'zeros': [名字, ...]}

    解析与数值都 < 1e-8 的参数视为「本应为 0」（如 softmax 前的 b_k：
    给整行加常数不改变输出），只记进 `zeros`、不参与相对误差判断；
    只有一边接近 0 时仍按相对误差严格比较。
    """
    if isinstance(module, CausalLM):
        return _grad_check_lm(module, x, eps, tol, max_params)
    if isinstance(module, Seq2SeqLM):
        return _grad_check_seq2seq(module, x, eps, tol, max_params)

    if isinstance(module, MLP):
        forward = module.forward
        params = module.get_parameters()

        def backward(dloss):
            return _mlp_backward(module, dloss)
        default_loss = mse_loss
    elif isinstance(module, Model):
        forward = module.forward
        params = module.model.get_parameters()

        def backward(dloss):
            return module.backward(dloss)
        default_loss = None
    else:
        raise TypeError(
            f"grad_check: 支持 MLP / Model / CausalLM / Seq2SeqLM，"
                f"收到 {type(module).__name__}"
        )

    if default_loss is None and loss_fn is None:
        loss_fn = module._loss

        def loss_of(xx, yy):
            return loss_fn(forward(xx), yy)
    else:
        loss_fn = loss_fn or default_loss

        def loss_of(xx, yy):
            return loss_fn(forward(xx), yy)

    _, dloss = loss_of(x, y)
    grads = backward(dloss)

    leaves = []
    for li, (weights, biases) in enumerate(params):
        for path, _ in _param_leaves(weights):
            leaves.append((f"layers{li}.weight" + "".join(f"[{p}]" for p in path),
                           weights, path, grads[li][0], path))
        for path, _ in _param_leaves(biases):
            leaves.append((f"layers{li}.bias" + "".join(f"[{p}]" for p in path),
                           biases, path, grads[li][1], path))

    if max_params is not None:
        leaves = leaves[:int(max_params)]

    checks = []
    zeros = []
    worst_name, worst_rel = "", 0.0
    for name, holder, path, grad_holder, gpath in leaves:
        orig = _pget(holder, path)
        ana = _pget(grad_holder, gpath)
        _pset(holder, path, orig + eps)
        lp, _ = loss_of(x, y)
        _pset(holder, path, orig - eps)
        lm_, _ = loss_of(x, y)
        _pset(holder, path, orig)
        num = (lp - lm_) / (2.0 * eps)
        if abs(ana) < _GRAD_CHECK_ZERO and abs(num) < _GRAD_CHECK_ZERO:
            zeros.append(name)
            continue
        rel = abs(ana - num) / max(1e-12, abs(ana) + abs(num))
        checks.append({"name": name, "rel": rel, "analytic": ana, "numeric": num})
        if rel > worst_rel:
            worst_name, worst_rel = name, rel

    return {
        "ok": worst_rel <= tol,
        "worst_name": worst_name,
        "worst_rel": worst_rel,
        "checks": checks,
        "zeros": zeros,
    }


# 解析与数值梯度都小于该阈值时视为「本应为 0」，跳过相对误差判断：
# 例如偏置 b_k 对 softmax 等价于「给整行加常数」，真实梯度恰好为 0，
# 数值差分只剩 1e-10 级浮点噪声，此时相对误差必然算成 1 而误报。
_GRAD_CHECK_ZERO = 1e-8


def _lm_training_state(lm):
    """读当前是不是训练模式（取编码器第一层的注意力标志）"""
    try:
        return bool(lm.encoder.layers[0].self_attn.training)
    except (AttributeError, IndexError, TypeError):
        return None


def _lm_restore_mode(lm, was_training):
    """把模型恢复成调用 grad_check 之前的状态（None 表示无法判断，保持不动）"""
    if was_training is None:
        return
    if was_training:
        lm.train()
    else:
        lm.eval()


def _grad_check_named(lm, loss_fn, eps: float, tol: float, max_params):
    """按参数块名抽查数值梯度（CausalLM / Seq2SeqLM 共用）

    loss_fn() 负责「清零梯度 → 前向+反向 → 返回标量 loss」，
    且必须可重复调用（中心差分要正负各一次）。
    """
    lm.zero_grad()
    loss_fn()
    named = lm._named_params()  # (name, param, grad)

    leaves = []
    for name, param, grad in named:
        for path, _ in _param_leaves(param):
            leaves.append((name + "".join(f"[{p}]" for p in path),
                           param, path, grad, path))
    if max_params is None:
        max_params = 24
    max_params = int(max_params)
    if max_params < len(leaves):
        rng = random.Random(0)
        leaves = rng.sample(leaves, max_params)

    def loss_now():
        return loss_fn()

    checks = []
    zeros = []
    worst_name, worst_rel = "", 0.0
    for name, holder, path, grad_holder, gpath in leaves:
        orig = _pget(holder, path)
        ana = _pget(grad_holder, gpath)
        _pset(holder, path, orig + eps)
        lp = loss_now()
        _pset(holder, path, orig - eps)
        lm_ = loss_now()
        _pset(holder, path, orig)
        num = (lp - lm_) / (2.0 * eps)
        if abs(ana) < _GRAD_CHECK_ZERO and abs(num) < _GRAD_CHECK_ZERO:
            zeros.append(name)
            continue
        rel = abs(ana - num) / max(1e-12, abs(ana) + abs(num))
        checks.append({"name": name, "rel": rel, "analytic": ana, "numeric": num})
        if rel > worst_rel:
            worst_name, worst_rel = name, rel
    loss_now()  # 复原缓存/grads 状态
    return {
        "ok": worst_rel <= tol,
        "worst_name": worst_name,
        "worst_rel": worst_rel,
        "checks": checks,
        "zeros": zeros,
    }


def _grad_check_lm(lm, ids, eps: float, tol: float, max_params):
    """CausalLM 的梯度自检：按参数块名抽查（默认 24 个标量）"""
    was_training = _lm_training_state(lm)
    lm.eval()  # 关掉 dropout，否则固定 seed 也未必复现
    try:
        def loss_fn():
            lm.zero_grad()
            return lm._loss_and_backward(list(ids))

        return _grad_check_named(lm, loss_fn, eps, tol, max_params)
    finally:
        _lm_restore_mode(lm, was_training)


def _grad_check_seq2seq(lm, pair, eps: float, tol: float, max_params):
    """Seq2SeqLM 的梯度自检：pair 是 (src_ids, tgt_ids)"""
    if not isinstance(pair, (list, tuple)) or len(pair) != 2:
        raise TypeError(
            "grad_check: Seq2SeqLM 的 x 必须是 (src_ids, tgt_ids) 二元组，"
            f"收到 {pair!r}"
        )
    src_ids, tgt_ids = pair
    was_training = _lm_training_state(lm)
    lm.eval()
    try:
        def loss_fn():
            lm.zero_grad()
            return lm._loss_and_backward(list(src_ids), list(tgt_ids))

        return _grad_check_named(lm, loss_fn, eps, tol, max_params)
    finally:
        _lm_restore_mode(lm, was_training)


def _mlp_backward(model: 'MLP', loss_grad: list) -> list:
    """内部工具：对 MLP 执行反向传播，返回每层的 (grad_w, grad_b) 列表"""
    delta = loss_grad
    grads = []
    fhooks = model._bhooks
    for i in range(len(model.layers) - 1, -1, -1):
        layer = model.layers[i]
        gw, gb, delta = layer.backward(delta)
        if fhooks:
            fn = fhooks.get(i)
            if fn is not None:
                fn(layer, delta, gw, gb)
        grads.append((gw, gb))
    grads.reverse()
    return grads


# ============================================================================
#  梯度检查点（activation checkpointing）与混合精度模拟
# ============================================================================

def _w10f_segments(n_layers, segments):
    """把 n 层切成 segments 段，返回每段的 [start, end) 列表（最后一段收到末尾）"""
    if isinstance(segments, bool) or not isinstance(segments, int) or segments < 1:
        raise ValueError(f"梯度检查点: segments 必须是 >=1 的整数，收到 {segments!r}")
    if segments > n_layers:
        segments = n_layers
    base = n_layers // segments
    extra = n_layers % segments
    bounds = []
    start = 0
    for i in range(segments):
        size = base + (1 if i < extra else 0)
        bounds.append((start, start + size))
        start += size
    return bounds


def _release_layer_cache(layer):
    """丢弃层的标准前向缓存（梯度检查点 release=True 时真正释放中间激活）。"""
    for name in ("input", "z", "a"):
        if hasattr(layer, name):
            setattr(layer, name, None)


def checkpoint_grads(model, xs, ys, segments=2, loss_fn=None, release=False):
    """用**梯度检查点**算一批样本的梯度，返回 ``(loss, grads)``

    做法：前向只保留每段**边界处**的激活（以 ``x`` 的形式），段内的中间激活丢掉；
    反向时逐段重放前向、重建该段的层缓存再反传。与 ``_mlp_backward`` 的差别只是
    「用时间换显存」。

    ``release=True`` 时每段前向结束后调用 ``_release_layer_cache`` 丢掉段内层的
    标准缓存（input/z/a），反向重放时再重建 —— 这样中间激活的峰值确实降到
    O(段数) 份边界激活 + 当前段缓存，而不只是「重放机制本身」。默认 ``False``
    保持旧行为（不额外清理）；两种模式梯度都应与普通反传逐位一致。
    ``loss_fn`` 省略时用 ``model._loss``。
    """
    net = getattr(model, "model", model)
    layers = net.layers
    if not layers:
        raise ValueError("checkpoint_grads: 模型没有层")
    if not xs:
        raise ValueError("checkpoint_grads: xs 不能为空")
    if len(xs) != len(ys):
        raise ValueError(
            f"checkpoint_grads: xs 有 {len(xs)} 个，ys 有 {len(ys)} 个"
        )
    bounds = _w10f_segments(len(layers), segments)
    use = model._loss if loss_fn is None else loss_fn
    acc = [(None, None) for _ in layers]
    total = 0.0
    for x, y in zip(xs, ys):
        h = list(x)
        for s, e in bounds:
            for i in range(s, e):
                h = layers[i].forward(h)
            if release:
                for i in range(s, e):
                    _release_layer_cache(layers[i])
        loss, grad = use(h, y)
        total += loss
        delta = list(grad)
        for s, e in reversed(bounds):
            h = list(x)
            for i in range(0, s):
                h = layers[i].forward(h)
            for i in range(s, e):
                h = layers[i].forward(h)
            for i in range(e - 1, s - 1, -1):
                gw, gb, delta = layers[i].backward(delta)
                if gw is None and gb is None:
                    continue
                aw, ab = acc[i]
                if gw is not None:
                    if aw is None:
                        aw = [[0.0] * len(r) for r in gw]
                    for j, row in enumerate(gw):
                        for k, v in enumerate(row):
                            aw[j][k] += v
                if gb is not None:
                    if ab is None:
                        ab = [0.0] * len(gb)
                    for j, v in enumerate(gb):
                        ab[j] += v
                acc[i] = (aw, ab)
            if release:
                for i in range(s, e):
                    _release_layer_cache(layers[i])
    n = float(len(xs))
    grads = []
    for gw, gb in acc:
        if gw is not None:
            gw = [[v / n for v in row] for row in gw]
        if gb is not None:
            gb = [v / n for v in gb]
        grads.append((gw, gb))
    return total / n, grads


def fp16_round(value):
    """把浮点数舍入到 IEEE 半精度（fp16）能表示的最接近值（返回 float）

    溢出（绝对值大于 65504）返回 ``inf``，下溢到次正规以下返回 0.0 ——
    这正是模拟半精度训练时要注意的两件事。
    """
    import struct
    v = float(value)
    try:
        return struct.unpack("<e", struct.pack("<e", v))[0]
    except OverflowError:
        return float("inf") if v > 0 else float("-inf")


def bf16_round(value):
    """把浮点数舍入到 bfloat16（8 位指数 + 7 位尾数，round-half-to-even）"""
    v = float(value)
    if v != v or v in (float("inf"), float("-inf")):
        return v
    if v == 0.0:
        return v
    import struct
    bits = struct.unpack("<I", struct.pack("<f", v))[0]
    lsb = (bits >> 16) & 1
    bias = 0x7FFF + lsb
    bits = (bits + bias) & 0xFFFF0000
    return struct.unpack("<f", struct.pack("<I", bits))[0]


_FP8_FORMATS = {
    "fp8_e4m3": (4, 3, -6, 8, 448.0),
    "fp8_e5m2": (5, 2, -14, 15, 57344.0),
}


def fp8_round(value, fmt="e4m3"):
    """把浮点数舍入到 FP8（E4M3 或 E5M2）能表示的最接近值（返回 float）。

    E4M3：4 位指数 / 3 位尾数，最大有限值 448；E5M2：5 位指数 / 2 位尾数，
    最大有限值 57344。超出最大值的数按饱和处理（FP8 没有 inf），
    低于最小次正规的数舍入到 0；``fmt`` 也接受 ``fp8_e4m3`` / ``fp8_e5m2``。
    """
    if fmt == "e4m3":
        fmt = "fp8_e4m3"
    elif fmt == "e5m2":
        fmt = "fp8_e5m2"
    spec = _FP8_FORMATS.get(fmt)
    if spec is None:
        raise ValueError(
            f"fp8_round: fmt 只能是 e4m3 / e5m2 / fp8_e4m3 / fp8_e5m2，收到 {fmt!r}"
        )
    _, mant_bits, emin, _emax, maxval = spec
    v = float(value)
    if v != v or v in (float("inf"), float("-inf")) or v == 0.0:
        return v
    sign = -1.0 if v < 0.0 else 1.0
    a = abs(v)
    if a >= maxval:
        return sign * maxval
    if a < 2.0 ** emin:
        step = 2.0 ** (emin - mant_bits)
        return sign * round(a / step) * step
    _, exp = math.frexp(a)
    exp = exp - 1
    step = 2.0 ** (exp - mant_bits)
    q = round(a / step) * step
    return sign * min(q, maxval)


def quantize_model(model, dtype="fp16"):
    """把模型权重与偏置**原地**舍入到 ``fp16`` / ``bf16`` / FP8 精度（模拟用）"""
    if dtype not in ("fp16", "bf16", "fp8_e4m3", "fp8_e5m2"):
        raise ValueError(
            "quantize_model: dtype 只能是 'fp16' / 'bf16' / 'fp8_e4m3' / 'fp8_e5m2'，"
            f"收到 {dtype!r}"
        )
    if dtype == "fp16":
        fn = fp16_round
    elif dtype == "bf16":
        fn = bf16_round
    else:
        fn = lambda v, _fmt=dtype: fp8_round(v, _fmt)
    net = getattr(model, "model", model)
    for layer in net.layers:
        if not hasattr(layer, "weights"):
            continue
        for row in layer.weights:
            for k in range(len(row)):
                row[k] = fn(row[k])
        for k in range(len(layer.biases)):
            layer.biases[k] = fn(layer.biases[k])
    return model


def mixed_precision_grads(model, xs, ys, scale=1024.0, dtype="fp16"):
    """模拟「loss scaling + 低精度梯度存储」的一步梯度，返回 ``(loss, grads)``

    流程：正常 fp32 前向反传 → 梯度乘 ``scale`` → 舍入到 ``fp16``/``bf16``
    → 除回 ``scale``。这正是 AMP 里 ``GradScaler`` 保护小梯度不下溢的做法。
    这里**只模拟舍入**，不做真正的半精度矩阵乘，因此速度不会变快——docstring
    在 README 里也写明「模拟无真收益」。
    """
    if isinstance(scale, bool) or not isinstance(scale, (int, float)) \
            or scale != scale or scale <= 0.0 or scale == float("inf"):
        raise ValueError(f"mixed_precision_grads: scale 必须是正的有限实数，收到 {scale!r}")
    if dtype not in ("fp16", "bf16", "fp8_e4m3", "fp8_e5m2"):
        raise ValueError(
            "mixed_precision_grads: dtype 只能是 'fp16' / 'bf16' / 'fp8_e4m3' / "
            f"'fp8_e5m2'，收到 {dtype!r}"
        )
    if not xs:
        raise ValueError("mixed_precision_grads: xs 不能为空")
    if len(xs) != len(ys):
        raise ValueError(
            f"mixed_precision_grads: xs 有 {len(xs)} 个，ys 有 {len(ys)} 个"
        )
    net = getattr(model, "model", model)
    if dtype == "fp16":
        fn = fp16_round
    elif dtype == "bf16":
        fn = bf16_round
    else:
        fn = lambda v, _fmt=dtype: fp8_round(v, _fmt)
    acc = [(None, None) for _ in net.layers]
    total = 0.0
    for x, y in zip(xs, ys):
        pred = net.forward(list(x))
        loss, grad = model._loss(pred, y)
        total += loss
        delta = list(grad)
        for i in range(len(net.layers) - 1, -1, -1):
            gw, gb, delta = net.layers[i].backward(delta)
            if gw is None and gb is None:
                continue
            aw, ab = acc[i]
            if gw is not None:
                if aw is None:
                    aw = [[0.0] * len(r) for r in gw]
                for j, row in enumerate(gw):
                    for k, v in enumerate(row):
                        aw[j][k] += v
            if gb is not None:
                if ab is None:
                    ab = [0.0] * len(gb)
                for j, v in enumerate(gb):
                    ab[j] += v
            acc[i] = (aw, ab)
    n = float(len(xs))
    grads = []
    for gw, gb in acc:
        if gw is not None:
            gw = [[fn(v * scale / n) / scale for v in row] for row in gw]
        if gb is not None:
            gb = [fn(v * scale / n) / scale for v in gb]
        grads.append((gw, gb))
    return total / n, grads


# ============================================================================
#  半监督学习（VAT / 伪标签 / 一致性正则 / FixMatch / MixMatch / MeanTeacher）
# ============================================================================

def softmax_rows(logits):
    """把若干行 logits 转成概率（逐行 softmax，返回新列表、不改入参）"""
    if not isinstance(logits, (list, tuple)) or not logits:
        raise ValueError("softmax_rows: logits 必须是非空的行列表")
    out = []
    for row in logits:
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError("softmax_rows: 每一行都必须是非空序列")
        out.append(_softmax_row(list(row)))
    return out


def _semi_check_confidence(confidence, who):
    """校验置信度阈值"""
    if isinstance(confidence, bool) or not isinstance(confidence, (int, float)) \
            or confidence != confidence or not 0.0 <= confidence <= 1.0:
        raise ValueError(f"{who}: confidence 必须是 [0, 1] 内的实数，收到 {confidence!r}")


def _semi_check_temperature(temperature, who):
    """校验锐化温度"""
    if isinstance(temperature, bool) or not isinstance(temperature, (int, float)) \
            or temperature != temperature or temperature <= 0.0 \
            or temperature == float("inf"):
        raise ValueError(f"{who}: temperature 必须是正的有限实数，收到 {temperature!r}")


def _semi_argmax(row):
    """返回 (最大值下标, 最大值)"""
    best = 0
    for i in range(1, len(row)):
        if row[i] > row[best]:
            best = i
    return best, row[best]


def _semi_norm(v):
    return math.sqrt(sum(x * x for x in v))


def _semi_copy(x):
    """内部工具：嵌套 list 深拷贝（权重是二维、偏置是一维）"""
    if isinstance(x, list):
        return [_semi_copy(v) for v in x]
    return x


def _semi_backward(model, pairs):
    """内部工具：逐个 ``(x, dlogits)`` 前向 + 反向并累加每层梯度

    返回与 ``layers`` 等长的列表，每项 ``(grad_w, grad_b)``，无参数层为
    ``(None, None)`` —— 与 ``_mlp_backward`` 同形，可直接喂给 ``optimizer.step``。
    """
    net = getattr(model, "model", model)
    acc = [(None, None) for _ in net.layers]
    for x, dlogits in pairs:
        net.forward(list(x))
        delta = list(dlogits)
        for i in range(len(net.layers) - 1, -1, -1):
            gw, gb, delta = net.layers[i].backward(delta)
            if gw is None and gb is None:
                continue
            aw, ab = acc[i]
            if gw is not None:
                if aw is None:
                    aw = [[0.0] * len(r) for r in gw]
                for j, row in enumerate(gw):
                    for k, v in enumerate(row):
                        aw[j][k] += v
            if gb is not None:
                if ab is None:
                    ab = [0.0] * len(gb)
                for j, v in enumerate(gb):
                    ab[j] += v
            acc[i] = (aw, ab)
    return acc


def _semi_mse_parts(pa, pb):
    """MSE 一致性：返回 (loss, dpa, dpb) —— 对**概率**的梯度"""
    rows = len(pa)
    cols = len(pa[0])
    n = float(rows * cols)
    lp = 0.0
    dpa = []
    dpb = []
    for ra, rb in zip(pa, pb):
        da = []
        db = []
        for a, b in zip(ra, rb):
            d = a - b
            lp += d * d
            da.append(2.0 * d / n)
            db.append(-2.0 * d / n)
        dpa.append(da)
        dpb.append(db)
    return lp / n, dpa, dpb


def _semi_kl_parts(la, lb):
    """KL(pa || pb)：返回 (loss, dla, dlb) —— 对 **logits** 的梯度（闭式）"""
    rows = len(la)
    loss = 0.0
    dla = []
    dlb = []
    for ra, rb in zip(la, lb):
        lp = _log_softmax_row(list(ra))
        lq = _log_softmax_row(list(rb))
        kl = 0.0
        for a, b in zip(lp, lq):
            kl += math.exp(a) * (a - b)
        loss += kl
        da = []
        db = []
        for a, b in zip(lp, lq):
            p = math.exp(a)
            da.append(p * (a - b - kl) / rows)
            db.append((math.exp(b) - p) / rows)
        dla.append(da)
        dlb.append(db)
    return loss / rows, dla, dlb


def _semi_dlogits(la, lb, kind):
    """两个分支的一致性损失与其对各自 logits 的梯度"""
    if kind == "kl":
        return _semi_kl_parts(la, lb)
    pa = [_softmax_row(list(r)) for r in la]
    pb = [_softmax_row(list(r)) for r in lb]
    loss, dpa, dpb = _semi_mse_parts(pa, pb)
    dla = []
    dlb = []
    for r, pa_r, dpa_r in zip(la, pa, dpa):
        s = sum(a * b for a, b in zip(pa_r, dpa_r))
        dla.append([pa_i * (d_i - s) for pa_i, d_i in zip(pa_r, dpa_r)])
    for r, pb_r, dpb_r in zip(lb, pb, dpb):
        s = sum(a * b for a, b in zip(pb_r, dpb_r))
        dlb.append([pb_i * (d_i - s) for pb_i, d_i in zip(pb_r, dpb_r)])
    return loss, dla, dlb


def consistency_loss(logits_a, logits_b, kind="mse"):
    """两个分支的**一致性损失**（纯函数，返回标量）

    ``kind='mse'``：``mean((softmax(a) - softmax(b))²)``，逐元素、按元素总个数取均值；
    ``kind='kl'``：``mean_rows(KL(softmax(a) || softmax(b)))``，逐行 KL 再按行取均值。
    同一组 logits 传给两边时损失恒为 0。
    """
    if kind not in ("mse", "kl"):
        raise ValueError(f"consistency_loss: kind 只能是 'mse' 或 'kl'，收到 {kind!r}")
    if not logits_a or not logits_b:
        raise ValueError("consistency_loss: logits 不能为空")
    if len(logits_a) != len(logits_b):
        raise ValueError(
            f"consistency_loss: 两组 logits 行数不一致（{len(logits_a)} vs {len(logits_b)}）"
        )
    for ra, rb in zip(logits_a, logits_b):
        if len(ra) != len(rb):
            raise ValueError(
                f"consistency_loss: 同一行长度不一致（{len(ra)} vs {len(rb)}）"
            )
    loss, _, _ = _semi_dlogits([list(r) for r in logits_a],
                               [list(r) for r in logits_b], kind)
    return loss


def consistency_regularizer(model, xs, kind="mse", sigma=0.05, seed=None, aug=None):
    """一致性正则：同一样本的两个视图预测应当一致，返回 ``(loss, grads)``

    视图二默认是「输入加 ``N(0, sigma²)`` 噪声」，也可以传 ``aug(x) -> x'`` 自己
    定义（如翻转、缩放）。``grads`` 与 ``_mlp_backward`` 同形，可以直接
    ``optimizer.step(grads)``，或与监督梯度逐项相加后再更新。

    这是**批级**接口（签名要模型），不能直接传给 ``Model(loss_fn=)``。
    """
    if kind not in ("mse", "kl"):
        raise ValueError(f"consistency_regularizer: kind 只能是 'mse' 或 'kl'，收到 {kind!r}")
    if isinstance(sigma, bool) or not isinstance(sigma, (int, float)) \
            or sigma != sigma or sigma < 0.0 or sigma == float("inf"):
        raise ValueError(f"consistency_regularizer: sigma 必须是非负有限实数，收到 {sigma!r}")
    if aug is not None and not callable(aug):
        raise TypeError("consistency_regularizer: aug 必须可调用或 None")
    if not xs:
        raise ValueError("consistency_regularizer: xs 不能为空")
    net = getattr(model, "model", model)
    rng = random.Random(seed) if seed is not None else random
    xs_b = []
    for x in xs:
        xb = list(aug(list(x))) if aug is not None else \
            [v + rng.gauss(0.0, sigma) for v in x]
        if len(xb) != len(x):
            raise ValueError(
                f"consistency_regularizer: aug 改变了样本长度（{len(x)} -> {len(xb)}）"
            )
        xs_b.append(xb)
    za = [net.forward(list(x)) for x in xs]
    zb = [net.forward(xb) for xb in xs_b]
    loss, dla, dlb = _semi_dlogits(za, zb, kind)
    n = float(len(xs))
    pairs = [(x, [v / n for v in d]) for x, d in zip(xs, dla)]
    pairs += [(xb, [v / n for v in d]) for xb, d in zip(xs_b, dlb)]
    return loss, _semi_backward(model, pairs)


def _vat_r_adv(model, x, eps, xi, power, rng):
    """内部工具：单样本的 VAT 对抗扰动（power 次幂迭代）"""
    net = getattr(model, "model", model)
    p = _softmax_row(list(net.forward(list(x))))
    r = [rng.gauss(0.0, 1.0) for _ in x]
    n = _semi_norm(r)
    if n <= 0.0:
        return [0.0] * len(x)
    r = [xi * v / n for v in r]
    for _ in range(power):
        q = _softmax_row(list(net.forward([a + b for a, b in zip(x, r)])))
        g = _adv_input_grad(model, [qi - pi for pi, qi in zip(p, q)])
        gn = _semi_norm(g)
        if gn <= 0.0:
            return [0.0] * len(x)
        r = [eps * v / gn for v in g]
    return r


def vat_perturbation(model, xs, eps=2.0, xi=1e-6, power=1, seed=None):
    """VAT 的对抗扰动：返回 ``x + r_adv`` 的列表（``eps=0`` 时原样返回）

    ``r_adv`` 的求法：先在半径 ``xi`` 上取随机方向，再用 ``power`` 次幂迭代把它
    转到「使 KL(p(x) || p(x+r)) 最大」的方向，长度归一到 ``eps``（L2）。
    """
    if isinstance(eps, bool) or not isinstance(eps, (int, float)) \
            or eps != eps or eps < 0.0 or eps == float("inf"):
        raise ValueError(f"vat_perturbation: eps 必须是非负有限实数，收到 {eps!r}")
    if isinstance(xi, bool) or not isinstance(xi, (int, float)) \
            or xi != xi or xi <= 0.0 or xi == float("inf"):
        raise ValueError(f"vat_perturbation: xi 必须是正的有限实数，收到 {xi!r}")
    if isinstance(power, bool) or not isinstance(power, int) or power < 1:
        raise ValueError(f"vat_perturbation: power 必须是 >=1 的整数，收到 {power!r}")
    if not xs:
        raise ValueError("vat_perturbation: xs 不能为空")
    if eps == 0.0:
        return [list(x) for x in xs]
    rng = random.Random(seed) if seed is not None else random
    out = []
    for x in xs:
        r = _vat_r_adv(model, list(x), eps, xi, power, rng)
        out.append([a + b for a, b in zip(x, r)])
    return out


def vat_regularizer(model, xs, eps=2.0, xi=1e-6, power=1, seed=None):
    """VAT（虚拟对抗训练）正则项，返回 ``(loss, grads)``

    ``loss = mean_rows(KL(p(x) || p(x + r_adv)))``；参数梯度按「干净分支」与
    「对抗分支」分别反传后累加（两个分支的闭式梯度都已用有限差分核对）。

    注意：每算一个样本要 4~5 次前向（求扰动 + 两个分支），比普通损失贵。
    """
    if not xs:
        raise ValueError("vat_regularizer: xs 不能为空")
    adv = vat_perturbation(model, xs, eps=eps, xi=xi, power=power, seed=seed)
    net = getattr(model, "model", model)
    pairs = []
    total = 0.0
    n = float(len(xs))
    for x, xa in zip(xs, adv):
        la = net.forward(list(x))
        lb = net.forward(list(xa))
        kl, dla, dlb = _semi_kl_parts([la], [lb])
        total += kl
        pairs.append((list(x), [v / n for v in dla[0]]))
        pairs.append((list(xa), [v / n for v in dlb[0]]))
    return total / n, _semi_backward(model, pairs)


def pseudo_label_targets(probs, confidence=0.0):
    """伪标签：取每行 argmax 作为硬标签，置信度低于阈值的位置权重记 0

    返回 ``(labels, weights)``；``weights`` 可直接当样本权重用于后面的
    ``soft_target_ce`` / ``fixmatch_regularizer``。
    """
    _semi_check_confidence(confidence, "pseudo_label_targets")
    if not probs:
        raise ValueError("pseudo_label_targets: probs 不能为空")
    labels = []
    weights = []
    for row in probs:
        if not row:
            raise ValueError("pseudo_label_targets: 每一行都必须非空")
        idx, best = _semi_argmax(list(row))
        labels.append(idx)
        weights.append(1.0 if best >= confidence else 0.0)
    return labels, weights


def fixmatch_targets(probs_weak, confidence=0.95):
    """FixMatch 的伪标签（与 ``pseudo_label_targets`` 同义，语义更明确）"""
    _semi_check_confidence(confidence, "fixmatch_targets")
    return pseudo_label_targets(probs_weak, confidence=confidence)


def _semi_onehot(label, n):
    out = [0.0] * n
    out[label] = 1.0
    return out


def soft_target_ce(logits, soft_targets, weights=None):
    """软标签交叉熵及其对 logits 的梯度（纯函数，返回 ``(loss, dlogits)``）

    ``loss = -Σ_i w_i Σ_c t_ic log p_ic / Σ_i w_i``；``weights=None`` 时等权。
    给定 ``weights`` 全 0 时返回 ``(0.0, 全零梯度)`` 而不是报错。
    """
    if not logits or not soft_targets:
        raise ValueError("soft_target_ce: logits 与 soft_targets 不能为空")
    if len(logits) != len(soft_targets):
        raise ValueError(
            f"soft_target_ce: 行数不一致（{len(logits)} vs {len(soft_targets)}）"
        )
    if weights is not None and len(weights) != len(logits):
        raise ValueError(
            f"soft_target_ce: weights 长度 {len(weights)} 与行数 {len(logits)} 不一致"
        )
    w = list(weights) if weights is not None else [1.0] * len(logits)
    wsum = 0.0
    for v in w:
        if isinstance(v, bool) or not isinstance(v, (int, float)) or v != v or v < 0.0:
            raise ValueError(f"soft_target_ce: 权重必须是非负实数，收到 {v!r}")
        wsum += v
    rows = len(logits)
    loss = 0.0
    dlogits = []
    if wsum <= 0.0:
        for la in logits:
            dlogits.append([0.0] * len(la))
        return 0.0, dlogits
    for la, ta, wi in zip(logits, soft_targets, w):
        if len(la) != len(ta):
            raise ValueError(
                f"soft_target_ce: 同一行长度不一致（{len(la)} vs {len(ta)}）"
            )
        lp = _log_softmax_row(list(la))
        p = [math.exp(v) for v in lp]
        row_loss = 0.0
        for t, v in zip(ta, lp):
            if t:
                row_loss -= t * v
        loss += wi * row_loss
        dlogits.append([wi * (pi - ti) / wsum for pi, ti in zip(p, ta)])
    return loss / wsum, dlogits


def fixmatch_regularizer(model, xs_weak, xs_strong, confidence=0.95):
    """FixMatch：弱增强分支出伪标签，强增强分支学习它，返回 ``(loss, grads)``

    ``xs_strong`` 由调用方用强增强（如大幅平移/旋转）生成；置信度不足的样本
    权重为 0（不计入 loss 也不贡献梯度）。``xs_weak`` 用当前模型前向取标签，
    因此调用前模型应处于 ``eval()``（否则 Dropout/BatchNorm 会污染伪标签）。
    """
    _semi_check_confidence(confidence, "fixmatch_regularizer")
    if not xs_weak or not xs_strong:
        raise ValueError("fixmatch_regularizer: xs_weak / xs_strong 不能为空")
    if len(xs_weak) != len(xs_strong):
        raise ValueError(
            f"fixmatch_regularizer: 两个分支样本数不一致"
            f"（{len(xs_weak)} vs {len(xs_strong)}）"
        )
    net = getattr(model, "model", model)
    probs = [_softmax_row(list(net.forward(list(x)))) for x in xs_weak]
    labels, weights = fixmatch_targets(probs, confidence=confidence)
    logits_strong = [net.forward(list(x)) for x in xs_strong]
    targets = [_semi_onehot(lb, len(lg)) for lb, lg in zip(labels, logits_strong)]
    loss, dlogits = soft_target_ce(logits_strong, targets, weights=weights)
    return loss, _semi_backward(model, list(zip(xs_strong, dlogits)))


def mixmatch_targets(probs_list, temperature=0.5):
    """MixMatch 的目标分布：多个增强的平均概率按 ``temperature`` 锐化（纯函数）

    ``p̄ = mean_k p_k``，``q_c = p̄_c^(1/T) / Σ p̄^(1/T)``；注意这里直接对
    **概率**锐化（与 ``_softmax_with_temp`` 对 logits 锐化的写法不同）。
    """
    _semi_check_temperature(temperature, "mixmatch_targets")
    if not isinstance(probs_list, (list, tuple)) or not probs_list:
        raise ValueError("mixmatch_targets: probs_list 必须是非空的列表")
    rows = len(probs_list[0]) if isinstance(probs_list[0], (list, tuple)) else 0
    if rows == 0:
        raise ValueError("mixmatch_targets: 每条增强结果必须是非空的行列表")
    cols = len(probs_list[0][0])
    if cols == 0:
        raise ValueError("mixmatch_targets: 概率行不能为空")
    for probs in probs_list:
        if len(probs) != rows:
            raise ValueError(
                f"mixmatch_targets: 各次增强的样本数不一致（{len(probs)} vs {rows}）"
            )
        for row in probs:
            if len(row) != cols:
                raise ValueError(
                    f"mixmatch_targets: 同一行类别数不一致（{len(row)} vs {cols}）"
                )
    out = []
    for i in range(rows):
        avg = [0.0] * cols
        for probs in probs_list:
            for c in range(cols):
                avg[c] += probs[i][c]
        for c in range(cols):
            avg[c] /= float(len(probs_list))
        powered = []
        for v in avg:
            if v < 0.0:
                raise ValueError("mixmatch_targets: 概率不能为负")
            powered.append(0.0 if v == 0.0 else v ** (1.0 / temperature))
        s = sum(powered)
        if s <= 0.0:
            out.append([1.0 / cols] * cols)
        else:
            out.append([v / s for v in powered])
    return out


class MeanTeacher:
    """Mean Teacher：在**学生**之外维护一份教师权重的指数滑动平均

    ``update(student=None, decay=None)`` 把学生当前权重混进教师
    （``t = decay * t + (1 - decay) * s``）；``forward(x)`` / ``logits(xs)`` 用
    教师权重前向。教师前向的做法是「临时换上教师权重 → 前向 → 换回学生权重」，
    因此调用会覆盖学生的 ``Layer`` 缓存（下一次前向会重建，不影响正确性）；
    也正因如此，不要在给教师打分与用学生反向之间穿插别的前向。
    """

    def __init__(self, model, decay=0.999):
        self._check_decay(decay, "MeanTeacher")
        net = getattr(model, "model", model)
        self.model = model
        self.decay = float(decay)
        self._state = []
        for layer in net.layers:
            if hasattr(layer, "weights"):
                self._state.append([_semi_copy(layer.weights), list(layer.biases)])
            else:
                self._state.append(None)

    @staticmethod
    def _check_decay(decay, who):
        if isinstance(decay, bool) or not isinstance(decay, (int, float)) \
                or decay != decay or not 0.0 <= decay < 1.0:
            raise ValueError(f"{who}: decay 必须是 [0, 1) 内的实数，收到 {decay!r}")

    def update(self, student=None, decay=None):
        """把学生的当前权重混进教师（``student`` 省略时用构造时的模型）"""
        d = self.decay if decay is None else decay
        self._check_decay(d, "MeanTeacher.update")
        src = getattr(student if student is not None else self.model, "model",
                      student if student is not None else self.model)
        for i, layer in enumerate(src.layers):
            t = self._state[i]
            if t is None:
                continue
            if not hasattr(layer, "weights"):
                raise ValueError(
                    f"MeanTeacher.update: 第 {i} 层在教师里有权重、在学生里没有"
                )
            for j, row in enumerate(layer.weights):
                for k, v in enumerate(row):
                    t[0][j][k] = d * t[0][j][k] + (1.0 - d) * v
            for j, v in enumerate(layer.biases):
                t[1][j] = d * t[1][j] + (1.0 - d) * v
        return self

    def _swap_in(self, net):
        saved = []
        for i, layer in enumerate(net.layers):
            t = self._state[i]
            if t is None:
                saved.append(None)
                continue
            saved.append([_semi_copy(layer.weights), list(layer.biases)])
            for j in range(len(layer.weights)):
                layer.weights[j][:] = t[0][j]
            layer.biases[:] = t[1]
        return saved

    @staticmethod
    def _swap_out(net, saved):
        for i, layer in enumerate(net.layers):
            s = saved[i]
            if s is None:
                continue
            for j in range(len(layer.weights)):
                layer.weights[j][:] = s[0][j]
            layer.biases[:] = s[1]

    def forward(self, x):
        """用教师权重前向一个样本（返回 logits）"""
        net = getattr(self.model, "model", self.model)
        saved = self._swap_in(net)
        try:
            return net.forward(list(x))
        finally:
            self._swap_out(net, saved)

    def logits(self, xs):
        """用教师权重前向一批样本"""
        if not xs:
            raise ValueError("MeanTeacher.logits: xs 不能为空")
        return [self.forward(x) for x in xs]


def mean_teacher_regularizer(student, teacher, xs, kind="mse"):
    """Mean Teacher 的一致性损失：学生向教师看齐，返回 ``(loss, grads)``

    教师一侧不传梯度（它靠 EMA 更新，不参与反向）。``kind`` 语义同
    ``consistency_loss``。
    """
    if kind not in ("mse", "kl"):
        raise ValueError(
            f"mean_teacher_regularizer: kind 只能是 'mse' 或 'kl'，收到 {kind!r}"
        )
    if not xs:
        raise ValueError("mean_teacher_regularizer: xs 不能为空")
    net = getattr(student, "model", student)
    lg_t = teacher.logits(xs) if hasattr(teacher, "logits") else list(teacher)
    lg_s = [net.forward(list(x)) for x in xs]
    n = float(len(xs))
    if kind == "kl":
        loss, dla, _ = _semi_kl_parts(lg_s, lg_t)
        pairs = [(x, [v / n for v in d]) for x, d in zip(xs, dla)]
        return loss, _semi_backward(student, pairs)
    ps = [_softmax_row(list(r)) for r in lg_s]
    pt = [_softmax_row(list(r)) for r in lg_t]
    loss, dps, _ = _semi_mse_parts(ps, pt)
    pairs = []
    for x, p, dp in zip(xs, ps, dps):
        s = sum(a * b for a, b in zip(p, dp))
        pairs.append((x, [p_i * (d_i - s) / n for p_i, d_i in zip(p, dp)]))
    return loss, _semi_backward(student, pairs)


# ============================================================================
#  噪声注入 / 课程学习 / Manifold Mixup / Snapshot Ensembles
# ============================================================================

def _noise_check(sigma, who):
    """校验噪声强度"""
    if isinstance(sigma, bool) or not isinstance(sigma, (int, float)) \
            or sigma != sigma or sigma < 0 or sigma == float("inf"):
        raise ValueError(f"{who}: sigma 必须是非负有限实数，收到 {sigma!r}")


def _noise_layers(model):
    """内部工具：取出有 weights 的层（Flatten 之类没有）"""
    return [l for l in getattr(model, "model", model).layers if hasattr(l, "weights")]


def inject_weight_noise(model, sigma=0.01, seed=None):
    """给权重与偏置**原地**加高斯噪声 ``N(0, sigma²)``（返回 ``model`` 便于链式）

    每次调用都会重新抽噪声；``sigma=0`` 时不动任何数值（与不加等价）。
    这是正则化手段（等价于权重空间的随机扰动），训练中途调用即可。
    """
    _noise_check(sigma, "inject_weight_noise")
    if sigma == 0.0:
        return model
    rng = random.Random(seed) if seed is not None else random
    for layer in _noise_layers(model):
        for j in range(layer.fan_out):
            wj = layer.weights[j]
            for k in range(len(wj)):
                wj[k] += rng.gauss(0.0, sigma)
            layer.biases[j] += rng.gauss(0.0, sigma)
    return model


def add_gradient_noise(grads, sigma=0.01, seed=None):
    """**返回**加噪后的梯度列表（不改动入参）；``grads`` 是 ``[(grad_w, grad_b), ...]``

    与权重噪声不同，梯度噪声不改变参数分布，常用于探索平坦极小值。
    """
    _noise_check(sigma, "add_gradient_noise")
    if not isinstance(grads, (list, tuple)) or not grads:
        raise ValueError("add_gradient_noise: grads 必须是非空列表")
    rng = random.Random(seed) if seed is not None else random
    out = []
    for gw, gb in grads:
        new_w = [[v + rng.gauss(0.0, sigma) for v in row] for row in gw]
        new_b = [v + rng.gauss(0.0, sigma) for v in gb]
        out.append((new_w, new_b))
    return out


def input_noise(x, sigma=0.01, seed=None):
    """**返回**加噪后的输入（不改动入参）"""
    _noise_check(sigma, "input_noise")
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError("input_noise: x 必须是非空列表")
    rng = random.Random(seed) if seed is not None else random
    return [v + rng.gauss(0.0, sigma) for v in x]


def curriculum_fraction(epoch: int, total_epochs: int = 10, schedule: str = "linear"):
    """课程学习的「进度比例」：第 ``epoch`` 轮（从 1 起）用多大比例的**最简单**样本

    - ``linear``: ``min(1, epoch/total_epochs)``
    - ``exp``:    ``min(1, 2 ** (epoch - total_epochs))``（后期才放开）
    - ``step``:   每 ``max(1, total_epochs // 4)`` 轮跳一档（0.25/0.5/0.75/1.0）
    """
    if isinstance(epoch, bool) or not isinstance(epoch, int) or epoch < 1:
        raise ValueError(f"curriculum_fraction: epoch 必须是 >=1 的整数，收到 {epoch!r}")
    if isinstance(total_epochs, bool) or not isinstance(total_epochs, int) or total_epochs < 1:
        raise ValueError(
            f"curriculum_fraction: total_epochs 必须是 >=1 的整数，收到 {total_epochs!r}"
        )
    if schedule not in ("linear", "exp", "step"):
        raise ValueError(
            f"curriculum_fraction: schedule 只能是 'linear'/'exp'/'step'，收到 {schedule!r}"
        )
    if schedule == "linear":
        frac = epoch / total_epochs
    elif schedule == "exp":
        frac = 2.0 ** (epoch - total_epochs)
    else:
        step = max(1, total_epochs // 4)
        frac = (epoch + step - 1) // step / 4.0
    if frac > 1.0:
        return 1.0
    if frac < 0.0:
        return 0.0
    return frac


class CurriculumSampler:
    """按难度从易到难放量的索引采样器

    ``difficulty`` 是与数据集等长的分数列表（越小越简单；可用 loss、序列长度等）。
    每个 epoch 调 ``set_epoch(e)``，迭代时只取**最简单的**
    ``curriculum_fraction(e, total_epochs, schedule)`` 比例，返回它们的下标
    （默认再打乱，保证同难度的样本顺序不固定）。

    用法::

        sampler = CurriculumSampler(difficulty, total_epochs=20)
        for epoch in range(1, 21):
            sampler.set_epoch(epoch)
            for i in sampler:
                ...
    """

    def __init__(self, difficulty, total_epochs=10, schedule="linear",
                 shuffle=True, seed=None, min_fraction=0.1):
        if not isinstance(difficulty, (list, tuple)) or not difficulty:
            raise ValueError("CurriculumSampler: difficulty 必须是非空列表")
        vals = []
        for v in difficulty:
            if isinstance(v, bool) or not isinstance(v, (int, float)) or v != v:
                raise ValueError(
                    f"CurriculumSampler: difficulty 里必须都是数字，收到 {v!r}"
                )
            vals.append(float(v))
        if isinstance(total_epochs, bool) or not isinstance(total_epochs, int) \
                or total_epochs < 1:
            raise ValueError("CurriculumSampler: total_epochs 必须是 >=1 的整数")
        if isinstance(min_fraction, bool) or not isinstance(min_fraction, (int, float)) \
                or not (0.0 < min_fraction <= 1.0):
            raise ValueError("CurriculumSampler: min_fraction 必须在 (0, 1] 内")
        if schedule not in ("linear", "exp", "step"):
            raise ValueError(
                f"CurriculumSampler: schedule 只能是 'linear'/'exp'/'step'，收到 {schedule!r}"
            )
        self.difficulty = vals
        self.total_epochs = total_epochs
        self.schedule = schedule
        self.shuffle = shuffle
        self.min_fraction = float(min_fraction)
        self.seed = seed
        self.epoch = 1
        # 稳定排序：同分数保持原始下标顺序，便于复现
        self._order = sorted(range(len(vals)), key=lambda i: (vals[i], i))

    def set_epoch(self, epoch: int):
        if isinstance(epoch, bool) or not isinstance(epoch, int) or epoch < 1:
            raise ValueError(f"CurriculumSampler.set_epoch: epoch 必须是 >=1 的整数，收到 {epoch!r}")
        self.epoch = epoch
        return self

    def fraction(self):
        frac = curriculum_fraction(self.epoch, self.total_epochs, self.schedule)
        return max(self.min_fraction, frac)

    def __len__(self):
        n = int(round(len(self._order) * self.fraction()))
        return max(1, min(len(self._order), n))

    def __iter__(self):
        k = len(self)
        idx = list(self._order[:k])
        if self.shuffle:
            rng = random.Random(None if self.seed is None else self.seed * 100003 + self.epoch)
            rng.shuffle(idx)
        return iter(idx)


def manifold_mixup(fa, fb, lam):
    """隐空间 mixup：把两组特征按 ``lam`` 线性插值（支持任意嵌套 list）

    ``fa``/``fb`` 形状必须一致（会逐层校验），返回新列表，不改动入参。
    ``lam`` 通常是 ``Beta(alpha, alpha)`` 的样本，与输入空间 mixup 相同。
    """
    if isinstance(lam, bool) or not isinstance(lam, (int, float)) or lam != lam \
            or not (0.0 <= lam <= 1.0):
        raise ValueError(f"manifold_mixup: lam 必须在 [0, 1] 内，收到 {lam!r}")

    def _mix(a, b):
        if isinstance(a, list) or isinstance(b, list):
            if not isinstance(a, list) or not isinstance(b, list) or len(a) != len(b):
                raise ValueError("manifold_mixup: 两组特征结构不一致")
            return [_mix(p, q) for p, q in zip(a, b)]
        return lam * a + (1.0 - lam) * b

    if not isinstance(fa, (list, tuple)) or not isinstance(fb, (list, tuple)):
        raise ValueError("manifold_mixup: 输入必须是 list（特征向量或嵌套特征图）")
    return _mix(list(fa), list(fb))


class SnapshotEnsemble:
    """快照集成：把训练过程中若干时刻的权重存下来，预测时对输出取平均

    与 ``SnapshotCallback`` 配合使用（周期性快照），也可以手动 ``capture()``。
    预测时会把每份权重复写进模板模型、前向一次、最后恢复原权重。
    """

    def __init__(self, model):
        self.model = getattr(model, "model", model)
        self.snapshots = []

    def capture(self):
        """把当前权重/偏置深拷贝进快照列表"""
        snap = []
        for layer in _noise_layers(self.model):
            snap.append((_w9_copy(layer.weights), _w9_copy(layer.biases)))
        self.snapshots.append(snap)
        return self

    def __len__(self):
        return len(self.snapshots)

    def predict(self, x):
        """对每份快照各前向一次，返回逐元素平均输出"""
        if not self.snapshots:
            raise ValueError("SnapshotEnsemble.predict: 还没有任何快照（先 capture()）")
        layers = _noise_layers(self.model)
        backup = [(_w9_copy(l.weights), list(l.biases)) for l in layers]

        def _load(layer, w, b):
            for j in range(len(layer.weights)):
                layer.weights[j][:] = w[j]
            layer.biases[:] = b

        try:
            total = None
            for snap in self.snapshots:
                for layer, (w, b) in zip(layers, snap):
                    _load(layer, w, b)
                out = self.model.forward(list(x))
                if total is None:
                    total = [float(v) for v in out]
                else:
                    for i, v in enumerate(out):
                        total[i] += v
            n = float(len(self.snapshots))
            return [v / n for v in total]
        finally:
            for layer, (w, b) in zip(layers, backup):
                _load(layer, w, b)


class SnapshotCallback(Callback):
    """每 ``every`` 轮把权重快照进一个 `SnapshotEnsemble`（``every<=0`` 关闭）"""

    def __init__(self, every=10):
        if isinstance(every, bool) or not isinstance(every, int):
            raise TypeError(f"SnapshotCallback: every 必须是整数，收到 {type(every).__name__}")
        self.every = every
        self.ensemble = None

    def on_train_begin(self, model, info):
        self.ensemble = SnapshotEnsemble(getattr(model, "model", model))

    def on_epoch_end(self, epoch, logs):
        if self.every > 0 and epoch % self.every == 0:
            self.ensemble.capture()


# ============================================================================
#  对抗训练（FGSM / PGD / TRADES / MART / FreeLB / SMART）
# ============================================================================

def _adv_check(eps, alpha, steps, clip_low, clip_high):
    """校验对抗攻击的超参"""
    if isinstance(eps, bool) or not isinstance(eps, (int, float)) or eps != eps or eps < 0:
        raise ValueError(f"对抗攻击: eps 必须是非负实数，收到 {eps!r}")
    if alpha is not None:
        if isinstance(alpha, bool) or not isinstance(alpha, (int, float)) \
                or alpha != alpha or alpha <= 0:
            raise ValueError(f"对抗攻击: alpha 必须是正实数或 None，收到 {alpha!r}")
    if isinstance(steps, bool) or not isinstance(steps, int) or steps < 1:
        raise ValueError(f"对抗攻击: steps 必须是 >=1 的整数，收到 {steps!r}")
    if clip_low is not None and clip_high is not None and clip_low > clip_high:
        raise ValueError(
            f"对抗攻击: clip_low={clip_low} 大于 clip_high={clip_high}"
        )


def _adv_project(x_adv, x, eps, clip_low, clip_high):
    """把扰动投影回 L∞ 球（以及可选的取值区间）"""
    out = []
    for a, b in zip(x_adv, x):
        d = a - b
        if d > eps:
            d = eps
        elif d < -eps:
            d = -eps
        v = b + d
        if clip_low is not None and v < clip_low:
            v = clip_low
        if clip_high is not None and v > clip_high:
            v = clip_high
        out.append(v)
    return out


def _adv_input_grad(model, loss_grad):
    """内部工具：损失对**输入**的梯度（沿各层 backward 链式传到底）

    既接受 `MLP` 也接受 `Model`（后者取 `.model`）。
    """
    delta = loss_grad
    for layer in reversed(getattr(model, "model", model).layers):
        _, _, delta = layer.backward(delta)
    return delta


def _adv_example(model, x, y, eps, alpha, steps, rng,
                 random_start, clip_low, clip_high):
    """内部工具：单样本 FGSM/PGD 攻击，返回扰动后的输入"""
    if random_start and rng is not None:
        x_adv = [xi + rng.uniform(-eps, eps) for xi in x]
    else:
        x_adv = list(x)
    x_adv = _adv_project(x_adv, x, eps, clip_low, clip_high)
    for _ in range(steps):
        pred = model.forward(x_adv)
        _, grad = model._loss(pred, y)
        g = _adv_input_grad(model, grad)
        x_adv = [xi + (alpha if gi > 0.0 else (-alpha if gi < 0.0 else 0.0))
                 for xi, gi in zip(x_adv, g)]
        x_adv = _adv_project(x_adv, x, eps, clip_low, clip_high)
    return x_adv


def pgd_examples(model, xs, ys, eps=0.03, alpha=None, steps=5, random_start=True,
                 seed=None, clip_low=None, clip_high=None):
    """用 PGD 生成对抗样本（批量，返回与 ``xs`` 等长的输入列表）

    `alpha` 默认 ``2.5*eps/steps``（PGD 常用的步长），`random_start=True` 时先在
    半径 ``eps`` 的 L∞ 球内均匀取起点（更接近 "radii" 版 PGD）。扰动每一步都
    投影回 ``||x_adv - x||_∞ <= eps``，最后按需夹到 ``[clip_low, clip_high]``。

    这是**批级**接口：签名里要模型本身，因此不能直接传给 ``Model(loss_fn=)``；
    训练时用 ``Model.fit(adv_eps=...)`` 或自己在外层循环调用。
    """
    _adv_check(eps, alpha, steps, clip_low, clip_high)
    if len(xs) != len(ys):
        raise ValueError(f"pgd_examples: xs 有 {len(xs)} 个，ys 有 {len(ys)} 个")
    if alpha is None:
        alpha = 2.5 * eps / steps
    rng = random.Random(seed) if seed is not None else random
    if eps == 0.0:
        return [list(x) for x in xs]
    return [_adv_example(model, list(x), y, eps, alpha, steps, rng,
                         random_start, clip_low, clip_high)
            for x, y in zip(xs, ys)]


def fgsm_examples(model, xs, ys, eps=0.03, seed=None,
                  clip_low=None, clip_high=None):
    """FGSM：单步、步长等于 ``eps`` 的符号梯度攻击（`pgd_examples` 的特例）"""
    return pgd_examples(model, xs, ys, eps=eps, alpha=eps if eps > 0 else None,
                        steps=1, random_start=False, seed=seed,
                        clip_low=clip_low, clip_high=clip_high)


def freelb_examples(model, xs, ys, eps=0.03, alpha=None, steps=3, seed=None,
                    clip_low=None, clip_high=None):
    """FreeLB 的**扰动**部分：不带随机起点、把各步扰动累积下来

    真正的 FreeLB 还会把每一步的梯度累积起来只更新一次参数（省 forward/backward
    轮数）。纯 Python 版没有单独的参数更新时机，所以这里只做扰动累积；梯度累积
    用 ``Model.fit(grad_accum=steps)`` 近似即可（docstring 里写明这一点）。
    """
    if alpha is None:
        alpha = eps if eps > 0 else None
    return pgd_examples(model, xs, ys, eps=eps, alpha=alpha, steps=steps,
                        random_start=False, seed=seed,
                        clip_low=clip_low, clip_high=clip_high)


def _adv_kl(p_logits, q_logits):
    """内部工具：逐行 KL(softmax(p) || softmax(q)) 的均值"""
    if len(p_logits) != len(q_logits):
        raise ValueError(
            f"对抗正则: 两组 logits 的行数不一致（{len(p_logits)} vs {len(q_logits)}）"
        )
    if not p_logits:
        raise ValueError("对抗正则: logits 不能为空")
    total = 0.0
    for lp, lq in zip(p_logits, q_logits):
        if len(lp) != len(lq):
            raise ValueError(
                f"对抗正则: 同一行 logits 长度不一致（{len(lp)} vs {len(lq)}）"
            )
        a = _log_softmax_row(lp)
        b = _log_softmax_row(lq)
        for pa, pb in zip(a, b):
            total += math.exp(pa) * (pa - pb)
    return total / len(p_logits)


def trades_regularizer(logits_clean, logits_adv, beta=1.0):
    """TRADES 的鲁棒项：``beta * KL(p_clean || p_adv)``

    与 ``loss_natural + beta * 本项`` 一起用，其中 ``loss_natural`` 用干净样本算。
    TRADES 的对抗样本应当由**最大化同一个 KL** 生成（`pgd_examples` 用的是任务
    损失，属于 PGD-AT 的写法；要严格复现 TRADES 的攻击目标请自己在外层循环里
    用本函数做上升，本文档不假装两者等价）。
    """
    if isinstance(beta, bool) or not isinstance(beta, (int, float)) or beta < 0:
        raise ValueError(f"trades_regularizer: beta 必须是非负实数，收到 {beta!r}")
    return beta * _adv_kl(logits_clean, logits_adv)


def mart_regularizer(logits_clean, logits_adv, beta=6.0):
    """MART 的鲁棒项：``beta * mean((1 - p_max_clean) * KL(p_clean || p_adv))``

    ``1 - p_max`` 让「模型已经很自信的样本」权重更低（MART 的误分类感知加权），
    与原文的 ``(1 - y_max)`` 同义（这里用干净预测的最大概率近似）。
    """
    if isinstance(beta, bool) or not isinstance(beta, (int, float)) or beta < 0:
        raise ValueError(f"mart_regularizer: beta 必须是非负实数，收到 {beta!r}")
    if len(logits_clean) != len(logits_adv):
        raise ValueError("mart_regularizer: 两组 logits 的行数不一致")
    total = 0.0
    for lp, lq in zip(logits_clean, logits_adv):
        a = _log_softmax_row(lp)
        b = _log_softmax_row(lq)
        kl = 0.0
        for pa, pb in zip(a, b):
            kl += math.exp(pa) * (pa - pb)
        total += (1.0 - math.exp(max(a))) * kl
    return beta * total / len(logits_clean)


def smart_regularizer(logits_clean, logits_adv, beta=1.0):
    """SMART 的**输出**光滑项：``beta * KL(p_clean || p_adv)``（对称化可选）

    SMART 原文还包含输入空间的 Bregman 散度项；纯 Python 版只实现输出项，
    因此这里叫「输出光滑项」，不声称等价于完整 SMART。
    """
    return trades_regularizer(logits_clean, logits_adv, beta)


class Model:
    """
    高层封装：将模型、损失函数、优化器打包为 sklearn 风格 API。

    ── 快速开始 ──────────────────────────────────────────────
        # 一行创建并训练
        model = quick_train(x, y, task='classification', epochs=200)
        print(model.score(x_test, y_test))

        # 工厂函数
        model = make_classifier(input_dim=10, num_classes=5, hidden_layers=(64, 32))
        model = make_regressor(input_dim=5, output_dim=2, hidden_layers=(64, 32))

        # 手动创建
        model = Model(MLP([5, 16, 8, 2]), loss_fn='mse', optimizer='adam', lr=0.01)
        history = model.fit(x, y, epochs=300, batch_size=8, patience=30)
        pred = model.predict(x_test)

        # 保存 / 加载
        model.save("model.json")
        model2 = Model.load("model.json")
    ──────────────────────────────────────────────────────────
    """

    _OPTIMIZER_MAP = {
        'adam': Adam,
        'adamw': AdamW,
        'sgd': SGD,
        'sgd_momentum': SGDMomentum,
        'rmsprop': RMSprop,
        'adagrad': AdaGrad,
        'adadelta': AdaDelta,
        'nadam': Nadam,
        'radam': RAdam,
        'lars': LARS,
        'lamb': LAMB,
        'ranger': Ranger,
        'sgdw': SGDW,
        'nesterov': NesterovSGD,
        'adan': Adan,
        'prodigy': Prodigy,
        'came': CAME,
        'shampoo': Shampoo,
        'sophia': Sophia,
        'lbfgs': LBFGS,
    }

    _LOSS_MAP = {
        'mse': mse_loss,
        'cross_entropy': cross_entropy_loss,
        'ce': cross_entropy_loss,
        'focal': focal_loss,
        'bce': bce_loss,
        'bce_with_logits': bce_with_logits_loss,
        'huber': huber_loss,
        'smooth_l1': smooth_l1_loss,
        'l1': l1_loss,
        'log_cosh': log_cosh_loss,
        'quantile': quantile_loss,
        'class_balanced': class_balanced_loss,
        'distill': distill_loss,
        'ldam': ldam_loss,
    }

    # 目标按「类别索引」解释的损失（其余按数值向量解释）
    # 注意：ldam 虽然也吃类别索引，但它额外需要 class_counts，无法走这里统一的
    # 索引包装（见 __init__ 里的 ldam 分支），因此不放进本元组。
    _INDEX_LOSSES = ('cross_entropy', 'ce', 'focal', 'class_balanced')
    # 目标按数值向量解释的损失（标量会被包成 [target]）
    _NUMERIC_LOSSES = ('mse', 'bce', 'bce_with_logits', 'huber', 'distill', 'smooth_l1',
                       'l1', 'log_cosh', 'quantile')

    def __init__(self, model, loss_fn=None, optimizer=None, lr=0.01,
                 opt_kwargs=None, task='auto', loss_kwargs=None):
        """
        model:       MLP 实例（必传）
        loss_fn:     'mse' / 'cross_entropy' / 'ce' / 'focal' / 'class_balanced' /
                     'ldam' / 'bce' / 'bce_with_logits' / 'huber' / 'smooth_l1' /
                     'l1' / 'log_cosh' / 'quantile' / 'distill' /
                     callable(pred, target) -> (loss, grad)
                     （kl_divergence 不在此列：它要求 pred 是概率分布，而 softmax 层的
                     反向是 softmax+CE 的联合梯度，非 CE 损失叠在 softmax 上梯度不自洽；
                     需要 KL 时请手动调用 AI.kl_divergence 并自己反传）
                     'ldam' 需要 loss_kwargs={'class_counts': [...]}；
                     'distill' 的 target 必须是 teacher logits 向量（长度 = 输出维度）。
        loss_kwargs: dict，传给损失函数的额外参数（如交叉熵的 label_smoothing、
                     focal 的 gamma/alpha、huber 的 delta、ldam 的 class_counts）
        optimizer:   'adam' / 'sgd' / 'sgd_momentum' / 'rmsprop' / 优化器实例
        lr:          学习率（optimizer 为字符串时生效）
        opt_kwargs:  dict，传给优化器构造函数的额外参数（如 weight_decay）
        task:        'regression' / 'classification' / 'auto'（自动推断）
        """
        if not isinstance(model, MLP):
            raise TypeError(f"model 必须是 MLP 实例，当前类型: {type(model).__name__}")
        if len(model.layers) == 0:
            raise ValueError("Model: model 至少要有 1 层（MLP 的层数 = 维度数-1）")

        # 隐藏层 softmax 兜底拦截：MLP 构造时已拒绝，这里再拦一层，
        # 防止手工拼装 / 反序列化出的模型绕过构造校验后静默训歪。
        for i, layer in enumerate(model.layers[:-1]):
            act = getattr(layer, "activation_name", None)
            if act is None:
                act_fn = getattr(layer, "act_fn", None)
                if act_fn is not None and act_fn == getattr(layer, "_softmax", None):
                    act = "softmax"
            if act == "softmax":
                raise ValueError(
                    f"Model: 第 {i + 1} 层是隐藏层却使用 softmax 激活——"
                    "softmax 只能作为输出层，并搭配 cross_entropy / focal 等"
                    "联合梯度损失；隐藏层请改用 relu / leaky_relu / tanh 等。"
                )

        self.model = model
        self.lr = lr
        self.opt_kwargs = opt_kwargs or {}
        if loss_kwargs is not None and not isinstance(loss_kwargs, dict):
            raise TypeError(f"loss_kwargs 必须是 dict 或 None，收到 {type(loss_kwargs).__name__}")
        self.loss_kwargs = dict(loss_kwargs or {})

        # 自动推断任务类型
        if task == 'auto':
            last_layer = model.layers[-1]
            self.task = 'classification' if last_layer.act_fn == last_layer._softmax else 'regression'
        else:
            self.task = task

        # 单类分类：softmax 只有 1 个单元时输出恒为 1，CE 的 loss 与梯度恒为 0，
        # 模型永远学不到东西，但 score 会报 100% —— 必须拒绝（sklearn 同样报错）
        if self.task == 'classification' and model.layers[-1].fan_out < 2:
            raise ValueError(
                f"分类模型的输出维度必须 >= 2（当前 {model.layers[-1].fan_out}）；"
                "单类 softmax 的交叉熵恒为 0，模型无法学习"
            )

        # 损失函数
        if loss_fn is None:
            loss_fn = 'cross_entropy' if self.task == 'classification' else 'mse'
        if isinstance(loss_fn, str):
            key = loss_fn.lower()
            if key not in self._LOSS_MAP:
                raise ValueError(f"未知损失函数: {loss_fn}，可选 {list(self._LOSS_MAP.keys())}")
            self._loss_name = key
            self.loss_fn = self._LOSS_MAP[key]
        else:
            self._loss_name = 'custom'
            self.loss_fn = loss_fn

        # 构建带 target 规范化的损失函数
        kw = self.loss_kwargs

        def _as_numeric_target(target):
            """标量目标包成 [target]；list/tuple 原样复制（向量/概率向量目标）"""
            if isinstance(target, (list, tuple)):
                return list(target)
            return [target]

        if self._loss_name in self._INDEX_LOSSES:
            # 标量 / float / 长度 1 的列表归一化成类别索引；
            # 长度等于类数的 one-hot / 概率向量直接交给 CE 的软标签分支，
            # 不再 argmax 硬化（否则软目标、label smoothing、蒸馏信息全被丢弃）
            num_classes = model.layers[-1].fan_out

            def _wrap_index_loss(pred, target):
                idx = target
                if isinstance(target, (list, tuple)):
                    if len(target) == num_classes:
                        # focal 是按类别索引定义的（没有软标签形式），one-hot 先硬化成索引；
                        # 真正的软目标（概率向量）只交给支持软标签的 CE 家族
                        if self._loss_name == 'focal':
                            ones = [j for j, v in enumerate(target) if float(v) == 1.0]
                            zeros_ok = all(
                                float(v) == 0.0 for j, v in enumerate(target) if j not in ones
                            )
                            if len(ones) != 1 or not zeros_ok:
                                raise ValueError(
                                    "focal_loss 不支持软标签：target 必须是类别索引或严格 one-hot，"
                                    f"收到 {list(target)}"
                                )
                            return self.loss_fn(pred, ones[0], **kw)
                        # 1 类分类器：[1.0] 是唯一的 one-hot，也必须按软标签走，
                        # 否则会被当成索引 1 而越界
                        if num_classes == 1:
                            return self.loss_fn(pred, [float(target[0])], **kw)
                        return self.loss_fn(pred, target, **kw)
                    if len(target) != 1:
                        raise ValueError(
                            f"{self._loss_name} 的 target 长度 {len(target)} 与模型输出维度 "
                            f"{num_classes} 不一致（应传类别索引、one-hot 或长度 1 的列表）"
                        )
                    idx = target[0]
                if isinstance(idx, float):
                    if not idx.is_integer():
                        raise ValueError(
                            f"{self._loss_name} 的 target 必须是整数类别索引，收到 {idx}"
                        )
                    idx = int(idx)
                if not isinstance(idx, int):
                    try:
                        idx = operator.index(idx)  # 兼容 numpy 等实现了 __index__ 的整数类型
                    except TypeError:
                        raise TypeError(
                            f"{self._loss_name} 的 target 必须是类别索引或 one-hot 列表，收到 {target!r}"
                        )
                if not 0 <= idx < num_classes:
                    raise ValueError(
                        f"类别索引 {idx} 越界（模型输出维度 {num_classes}）"
                    )
                return self.loss_fn(pred, idx, **kw)

            self._loss = _wrap_index_loss
        elif self._loss_name == 'ldam':
            # LDAM 的目标也是类别索引，但 class_counts（每个类的训练样本数）
            # 无法从 pred/target 推断，必须由调用方显式提供，因此在构造时就校验。
            if 'class_counts' not in kw:
                raise ValueError(
                    "loss_fn='ldam' 需要 loss_kwargs={'class_counts': [...]}"
                    "（每个类别的训练样本数）：ldam_loss 用类频率计算间隔，"
                    "无法从 pred/target 推断。"
                )

            def _wrap_ldam_loss(pred, target):
                # target 保持调用方传入的类别索引（ldam_loss 自己会校验合法性）
                return self.loss_fn(pred, target, **kw)

            self._loss = _wrap_ldam_loss
        elif self._loss_name in self._NUMERIC_LOSSES:
            if self._loss_name == 'distill':
                # distill 的 target 契约与普通数值损失不同：它必须是 teacher logits
                # 向量（长度 = 输出维度），而不是类别索引。在这里提前拦截并给出
                # 可操作的报错，避免到 loss 内部才暴露「长度 1 != pred 长度 C」。
                def _wrap_numeric_loss(pred, target):
                    vec = _as_numeric_target(target)
                    if len(vec) != len(pred):
                        raise ValueError(
                            "loss_fn='distill' 的 target 必须是 teacher logits 向量"
                            f"（长度 = 模型输出维度 {len(pred)}），收到长度 {len(vec)}；"
                            "普通类别标签请改用 loss_fn='cross_entropy'。"
                        )
                    return self.loss_fn(pred, vec, **kw)
            else:
                def _wrap_numeric_loss(pred, target):
                    return self.loss_fn(pred, _as_numeric_target(target), **kw)
            self._loss = _wrap_numeric_loss
        else:
            if kw:
                def _wrap_custom_loss(pred, target):
                    return self.loss_fn(pred, target, **kw)
                self._loss = _wrap_custom_loss
            else:
                self._loss = self.loss_fn  # custom 原样

        # 输出层激活函数与损失函数的搭配校验：
        # Layer._softmax_deriv 返回全 1，隐含假设是「softmax + cross_entropy 联合梯度」，
        # 与 MSE 组合会得到静默错误的梯度，因此这里直接报错而不是让它训歪。
        # 只拦截明确已知的 mse；自定义 callable 无法判断其内部实现，交给用户自己负责。
        last_layer = model.layers[-1]
        last_act = getattr(last_layer, "activation_name", None)
        if last_act is None and last_layer.act_fn == last_layer._softmax:
            last_act = "softmax"  # 兼容没有 activation_name 属性的旧对象
        # 传函数对象（loss_fn=mse_loss）时 _loss_name 是 'custom'，
        # 也要落到同一个守卫里，否则两条路径行为不一致
        _is_mse = (self._loss_name == 'mse') or (self.loss_fn is mse_loss) \
            or (getattr(self.loss_fn, 'func', None) is mse_loss)
        if self._loss_name in self._INDEX_LOSSES and last_act != "softmax":
            raise ValueError(
                f"输出层激活是 {last_act!r}，但 loss_fn='{self._loss_name}'："
                "内置交叉熵假设 pred 是 softmax 概率，并直接使用 softmax+CE（或 focal）的联合梯度，"
                "与非 softmax 输出层不匹配（算出的 loss 与梯度不自洽）。"
                "请把输出层激活设为 'softmax'，或改用自定义 loss_fn。"
            )
        # 其余损失对「输出层激活」也有硬性要求，配错会在第一批就抛错或静默训歪，
        # 因此在构造时就拒绝（与上面 CE/mse 的守卫同一套风格）
        _LOSS_ACT_C = {
            'bce': ('sigmoid', "bce_loss 期望 pred 是概率（[0,1]），输出层激活请用 'sigmoid'"),
            'bce_with_logits': ('linear', "bce_with_logits_loss 期望 logits，输出层激活请用 'linear'"),
            'l1': ('linear', "l1_loss 是回归损失，输出层激活请用 'linear'"),
            'log_cosh': ('linear', "log_cosh_loss 是回归损失，输出层激活请用 'linear'"),
            'quantile': ('linear', "quantile_loss 是回归损失，输出层激活请用 'linear'"),
            'smooth_l1': ('linear', "smooth_l1_loss 是回归损失，输出层激活请用 'linear'"),
            'class_balanced': ('softmax', "class_balanced_loss 期望 softmax 概率，输出层激活请用 'softmax'"),
            'ldam': ('linear', "ldam_loss 直接吃 logits，输出层激活请用 'linear'"),
            'distill': ('linear', "distill_loss 吃学生 logits，输出层激活请用 'linear'"),
        }
        want_act = _LOSS_ACT_C.get(self._loss_name)
        if want_act is not None and last_act != want_act[0]:
            raise ValueError(
                f"输出层激活是 {last_act!r}，但 loss_fn='{self._loss_name}'："
                f"{want_act[1]}。"
            )

        if last_act == "softmax" and _is_mse:
            raise ValueError(
                "输出层使用 softmax 时不能搭配 mse 损失："
                "softmax 的反向用的是 softmax+cross_entropy 的联合梯度，"
                "与 mse 组合会静默产生错误梯度。"
                "请改用 loss_fn='cross_entropy'，或把输出层激活改成 'linear'。"
            )

        # 优化器
        if optimizer is None:
            optimizer = 'adam'
        if isinstance(optimizer, str):
            key = optimizer.lower()
            if key not in self._OPTIMIZER_MAP:
                raise ValueError(f"未知优化器: {optimizer}，可选 {list(self._OPTIMIZER_MAP.keys())}")
            self.optimizer = self._OPTIMIZER_MAP[key](model, lr=lr, **self.opt_kwargs)
        else:
            # 优化器实例必须绑定到同一个模型：否则 fit 会更新**别人的**参数，
            # 本模型的 loss 从头到尾不变（静默训练错对象，最隐蔽的一类错误）
            owner = getattr(optimizer, 'model', None)
            if owner is not None and owner is not model:
                raise ValueError(
                    "Model: 传入的优化器绑定的不是这个 model（例如 Adam(A) 传给了 Model(B)）。"
                    "优化器只更新自己持有的 model 参数，这样训练会静默地改错对象；"
                    "请传字符串（如 'adam'）或为本 model 新建优化器。"
                )
            self.optimizer = optimizer

        self.history = {'train_loss': [], 'val_loss': []}
        self._is_trained = False

# ── 核心操作

    def forward(self, x):
        """前向传播：接受单样本 list，返回输出 list"""
        return self.model.forward(x if isinstance(x, list) else list(x))

    def backward(self, loss_grad):
        """反向传播：返回 [(gw, gb), ...] 梯度列表（逐层）"""
        return _mlp_backward(self.model, loss_grad)

    def register_forward_hook(self, index: int, fn):
        """转发到 MLP：在第 index 层前向后调用 fn(layer, output)"""
        return self.model.register_forward_hook(index, fn)

    def register_backward_hook(self, index: int, fn):
        """转发到 MLP：在第 index 层反向后调用 fn(layer, delta, grad_w, grad_b)"""
        return self.model.register_backward_hook(index, fn)

    def clear_hooks(self):
        """转发到 MLP：注销全部 hook"""
        return self.model.clear_hooks()

# ── 训练

    def _load_checkpoint(self, path):
        """从 checkpoint 恢复权重与优化器动量，返回恢复的 step_count。"""
        if not isinstance(path, str) or not path:
            raise ValueError(f"fit: resume_from 必须是文件路径字符串，收到 {path!r}")
        try:
            with io.open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except FileNotFoundError:
            raise FileNotFoundError(f"fit: resume_from 文件不存在: {path}")
        except (ValueError, UnicodeDecodeError) as exc:
            raise ValueError(f"fit: resume_from 解析失败（{exc}）: {path}")
        if not isinstance(data, dict) or data.get("type") != "MLP":
            raise ValueError(f"fit: resume_from 的文件不是 MLP 存档: {path}")
        saved = data.get("layers")
        if not isinstance(saved, list) or len(saved) != len(self.model.layers):
            raise ValueError(
                f"fit: resume_from 的层数与当前模型不一致"
                f"（存档 {len(saved) if isinstance(saved, list) else '?'} 层，"
                f"当前 {len(self.model.layers)} 层）"
            )
        for i, (layer, ld) in enumerate(zip(self.model.layers, saved)):
            if not isinstance(ld, dict):
                raise ValueError(f"fit: resume_from 第 {i} 层不是对象")
            w, b = ld.get("weights"), ld.get("biases")
            if (not isinstance(w, list) or len(w) != layer.fan_out
                    or any(not isinstance(row, list) or len(row) != layer.fan_in for row in w)):
                raise ValueError(
                    f"fit: resume_from 第 {i} 层权重形状与当前模型不符"
                    f"（应为 {layer.fan_out}×{layer.fan_in}）"
                )
            if not isinstance(b, list) or len(b) != layer.fan_out:
                raise ValueError(
                    f"fit: resume_from 第 {i} 层偏置形状与当前模型不符"
                    f"（应为 {layer.fan_out} 个）"
                )
            for j in range(layer.fan_out):
                layer.weights[j] = [float(v) for v in w[j]]
            layer.biases[:] = [float(v) for v in b]
        state = data.get("optimizer")
        if isinstance(state, dict):
            load_optimizer_state(self.optimizer, state)
            return int(state.get("step_count", 0))
        return 0

    def _mixup_batch(self, batch, alpha, rng):
        """把一个 batch 变成 mixup 后的 (x_mix, y_soft) 列表（长度不变）。"""
        num_classes = self.model.layers[-1].fan_out

        def _label_vec(y, k):
            if isinstance(y, (list, tuple)):
                if len(y) != num_classes:
                    raise ValueError(
                        f"fit(mixup_alpha): 第 {k} 个样本的软标签长度 {len(y)}"
                        f" 与输出维度 {num_classes} 不一致"
                    )
                vec = [float(v) for v in y]
                total = sum(vec)
                if abs(total - 1.0) > 1e-6:
                    raise ValueError(
                        f"fit(mixup_alpha): 第 {k} 个样本的软标签和为 {total:.6f}，应为 1"
                    )
                return vec
            if isinstance(y, bool) or not isinstance(y, int):
                raise ValueError(
                    f"fit(mixup_alpha): 目标必须是类别索引或 one-hot 向量，"
                    f"第 {k} 个样本收到 {type(y).__name__}"
                )
            if not (0 <= y < num_classes):
                raise ValueError(
                    f"fit(mixup_alpha): 第 {k} 个样本的类别索引 {y} 越界"
                    f"（应为 0..{num_classes - 1}）"
                )
            vec = [0.0] * num_classes
            vec[y] = 1.0
            return vec

        xs = [list(x) for x, _ in batch]
        ys = [_label_vec(y, k) for k, (_, y) in enumerate(batch)]
        n = len(xs)
        mixed = []
        for k in range(n):
            j = rng.randrange(n)
            lam = _beta_lam(alpha, rng, "fit(mixup_alpha)")
            x1, x2 = xs[k], xs[j]
            y1, y2 = ys[k], ys[j]
            xm = [lam * a + (1.0 - lam) * b for a, b in zip(x1, x2)]
            ym = [lam * a + (1.0 - lam) * b for a, b in zip(y1, y2)]
            mixed.append((xm, ym))
        return mixed

    def _normalize_val_data(self, val_data):
        """把 val_data 规范化为 [(x, y), ...]，并做维度校验。

        支持的写法：
            {'x': x_arr, 'y': y_arr}   显式并行数组（推荐，无歧义）
            (x_arr, y_arr)             并行数组
            [(x, y), ...]              样本对列表
        歧义处理：恰好 2 个元素且两种解释都成立时（无法从结构上区分），
        按容器类型决定——list 视为样本对，tuple 视为并行数组，与上面两条写法一致。
        拿不准时请用 dict 写法。
        """
        def as_pairs(x_arr, y_arr):
            x_arr, y_arr = list(x_arr), list(y_arr)
            if len(x_arr) != len(y_arr):
                raise ValueError(
                    f"val_data: x 有 {len(x_arr)} 个样本，y 有 {len(y_arr)} 个，数量必须一致"
                )
            return [(list(xi), yi) for xi, yi in zip(x_arr, y_arr)]

        def looks_like_parallel_arrays(vd):
            return (isinstance(vd, (list, tuple)) and len(vd) == 2
                    and isinstance(vd[0], (list, tuple)) and isinstance(vd[1], (list, tuple))
                    and len(vd[0]) == len(vd[1]) and len(vd[0]) > 0
                    and all(isinstance(e, (list, tuple)) for e in vd[0]))

        def looks_like_pairs(vd):
            return (isinstance(vd, (list, tuple)) and len(vd) > 0
                    and all(isinstance(it, (list, tuple)) and len(it) == 2
                            and isinstance(it[0], (list, tuple)) for it in vd))

        if isinstance(val_data, (list, tuple, dict)) and len(val_data) == 0:
            return []  # 空验证集 → 等同不做验证（保持旧行为）

        if isinstance(val_data, dict):
            x_arr = val_data.get('x', val_data.get('X'))
            y_arr = val_data.get('y', val_data.get('Y'))
            if x_arr is None or y_arr is None:
                raise ValueError("val_data 为 dict 时必须提供 'x' 和 'y' 两个键")
            pairs = as_pairs(x_arr, y_arr)
        elif looks_like_parallel_arrays(val_data) and (
                not looks_like_pairs(val_data) or isinstance(val_data, tuple)):
            pairs = as_pairs(val_data[0], val_data[1])
        elif looks_like_pairs(val_data):
            pairs = [(list(xi), yi) for xi, yi in val_data]
        else:
            raise ValueError(
                "val_data 格式无法识别，支持三种写法："
                "{'x': x_arr, 'y': y_arr}、(x_arr, y_arr)、[(x, y), ...]"
            )

        # 维度校验：尽早暴露形状错误，而不是让后面的 zip 静默截断
        n_in = self.model.layers[0].fan_in
        n_out = self.model.layers[-1].fan_out
        for k, (xi, yi) in enumerate(pairs):
            if len(xi) != n_in:
                raise ValueError(
                    f"val_data 第 {k} 个样本的特征维度是 {len(xi)}，模型输入维度是 {n_in}"
                )
            if isinstance(yi, (list, tuple)) and len(yi) != n_out:
                raise ValueError(
                    f"val_data 第 {k} 个样本的 target 维度是 {len(yi)}，模型输出维度是 {n_out}"
                )
        return pairs

    def fit(self, x=None, y=None, data=None, epochs=100, batch_size=32,
            val_split=0.1, val_data=None, patience=50, verbose=True,
            shuffle=True, lr_scheduler=None, grad_clip=None,
            early_stop_metric='val', restore_best_weights=False,
            checkpoint_path=None, checkpoint_every=1, grad_accum: int = 1,
            seed=None, callbacks=None, resume_from=None, mixup_alpha: float = 0.0,
            record_layer_norms: bool = False, adv_eps: float = 0.0,
            adv_steps: int = 5, adv_alpha: float = None, train_augment=None):
        """
        训练模型。

        数据传入方式（二选一）：
            model.fit(x=[[1,2],[3,4]], y=[0, 1])        ← 分开传
            model.fit(data=[([1,2],0), ([3,4],1)])       ← 元组列表
            (data 优先级高于 x/y)

        epochs:       训练轮数
        batch_size:   批次大小（设为 -1 = 全批量）
        val_split:    验证集比例（仅 val_data 未提供时从训练集切分）
        val_data:     自定义验证集 {'x':…, 'y':…} / (x_arr, y_arr) / [(x, y), ...]
        patience:     Early stopping 耐心值（0 = 不使用）
        verbose:      打印进度
        shuffle:      每轮打乱数据
        lr_scheduler: StepLR/ExponentialLR/CosineAnnealingLR 实例
        grad_clip:    float，梯度范数裁剪阈值（None = 不裁剪）
            early_stop_metric: 'val'（默认，盯验证损失）或 'train'（盯训练损失，且不依赖验证集）
            restore_best_weights: True 时在训练结束后回滚到「被监控指标最好」的那一轮权重
                （早停只在指标变差时停止，**不会自动回滚**；需要最优权重时打开这个开关）
            checkpoint_path: 每 checkpoint_every 轮把权重 + 优化器状态写到该路径
                （中断后可用 Model.load(path, restore_optimizer=True) 续训）
            seed:         打乱数据的随机种子（None = 用全局 random，与旧版行为一致）。
                传了整数就改用局部 Random：再跑一次同样的 fit 结果完全相同，
                也不会推进调用方的全局随机状态。
            grad_accum:   梯度累积步数（1 = 每个 batch 更新一次）。大于 1 时先累加
                grad_accum 个 batch 的**平均梯度**，再更新一次；代价是更新次数变少，
                收益是等效 batch 更大而显存不变。每个 epoch 末尾会把剩余不足
                grad_accum 的 batch 也更新一次（不会白算）。
            callbacks:    训练回调列表（继承 AI.Callback，钩子见该类 docstring）
            resume_from:  checkpoint 路径：训练前先恢复权重与优化器动量（含 step_count），
                再用给定的 epochs 继续训练（epoch 编号从 1 重新开始）
            mixup_alpha:  >0 时对每个 batch 做 mixup（仅分类任务、仅索引型损失），
                lam ~ Beta(alpha, alpha)；0（默认）表示关闭，关闭时数值完全不变
            record_layer_norms: True 时把每层梯度范数记进 history['layer_grad_norm']
            adv_eps:      >0 时对每个 batch 做 PGD 对抗训练（先用 `pgd_examples` 攻击
                当前权重，再在被扰动的样本上算损失与梯度）；0（默认）关闭，关闭时
                数值与旧版完全一致。与 mixup_alpha 互斥
            adv_steps:    对抗攻击的步数（越大越强、越慢）
            adv_alpha:    对抗攻击每步步长（None = 2.5*adv_eps/adv_steps）
            train_augment: 可选的批级数据增强回调 `fn(xs, ys) -> (xs, ys)`，
                每个 batch 在 mixup / 对抗攻击**之前**调用一次，输入输出都是
                「批内样本列表 + 标签列表」，样本数必须保持不变。默认 None
                （关闭），关闭时数值与旧版完全一致。
                用途：`Compose`/`RandomCrop`/`ColorJitter` 等图像增强、
                `augment_cutout`、或自定义的「x 加噪」——它们都是逐样本变换，
                先增强再混合才符合 CutMix/Cutout 的语义（早先只接 mixup 的顺序
                问题在这里解决）。
        """
        if train_augment is not None and not callable(train_augment):
            raise ValueError(
                f"fit: train_augment 必须可调用，收到 {train_augment!r}")
        # === 规范化数据 ===
        if data is not None:
            dataset = [(list(x_i), y_i) for x_i, y_i in data]
            if not dataset:
                raise ValueError("fit: 训练集为空")
        elif x is not None and y is not None:
            # 训练集同样要校验：zip 会静默截断到较短的一方
            # 标量 y（如 y=0.5）广播到每个样本，与 train(data=[(x, 0.5)]) 的语义一致
            if isinstance(y, (int, float)) and not isinstance(y, bool):
                y = [y] * len(x)
            if len(x) != len(y):
                raise ValueError(
                    f"fit: x 有 {len(x)} 个样本，y 有 {len(y)} 个，数量必须一致"
                )
            if len(x) == 0:
                raise ValueError("fit: 训练集为空")
            n_in = self.model.layers[0].fan_in
            if len(x[0]) != n_in:
                raise ValueError(
                    f"fit: 训练样本特征维度 {len(x[0])} 与模型输入维度 {n_in} 不一致"
                )
            dataset = [(list(x_i), y_i) for x_i, y_i in zip(x, y)]
        else:
            raise ValueError("请提供 data 或 (x, y)")

        # 复校验：optimizer.model 可能在构造之后被替换，step 前再确认一次
        _owner = getattr(self.optimizer, 'model', None)
        if _owner is not None and _owner is not self.model:
            raise ValueError(
                "fit: 当前优化器绑定的不是 self.model（被替换过？）；"
                "请重建优化器，否则会更新错误对象的参数"
            )

        if early_stop_metric not in ('val', 'train'):
            raise ValueError(
                f"fit: early_stop_metric 只能是 'val' 或 'train'，收到 {early_stop_metric!r}"
            )
        if not isinstance(val_split, (int, float)) or not (0.0 <= val_split < 1.0):
            raise ValueError(
                f"fit: val_split 必须在 [0, 1) 内，收到 {val_split!r}"
                "（与 split_data 的校验保持一致；原实现会把 >=1 静默钳成 n-1）"
            )

        rng = random.Random(seed) if seed is not None else random

        # === 验证集 ===
        if val_data is not None:
            val_set = self._normalize_val_data(val_data)
        elif val_split > 0:
            n_val = max(1, int(len(dataset) * val_split))
            # 至少要留 1 个训练样本：样本数很少时 max(1,...) 会把训练集切空，
            # 随后 train_loss /= len(dataset) 抛 ZeroDivisionError
            if n_val >= len(dataset):
                n_val = len(dataset) - 1
            if n_val <= 0:
                val_set = None
            elif shuffle:
                rng.shuffle(dataset)
                val_set = dataset[:n_val]
                dataset = dataset[n_val:]
            else:
                # shuffle=False 时不能为了切验证集而打乱训练顺序：取尾部当验证集
                val_set = dataset[-n_val:]
                dataset = dataset[:-n_val]
        else:
            val_set = None

        if batch_size is None or batch_size <= 0:
            batch_size = len(dataset)

        if not isinstance(grad_accum, int) or isinstance(grad_accum, bool) or grad_accum < 1:
            raise ValueError(f"fit: grad_accum 必须是 >=1 的整数，收到 {grad_accum!r}")

        callbacks = _normalize_callbacks(callbacks)

        if isinstance(adv_eps, bool) or not isinstance(adv_eps, (int, float)) \
                or adv_eps != adv_eps or adv_eps < 0:
            raise ValueError(f"fit: adv_eps 必须是非负实数，收到 {adv_eps!r}")
        if isinstance(adv_steps, bool) or not isinstance(adv_steps, int) or adv_steps < 1:
            raise ValueError(f"fit: adv_steps 必须是 >=1 的整数，收到 {adv_steps!r}")
        if adv_alpha is not None:
            if isinstance(adv_alpha, bool) or not isinstance(adv_alpha, (int, float)) \
                    or adv_alpha != adv_alpha or adv_alpha <= 0:
                raise ValueError(f"fit: adv_alpha 必须是正实数或 None，收到 {adv_alpha!r}")
        if adv_eps > 0 and mixup_alpha > 0:
            raise ValueError(
                "fit: adv_eps 与 mixup_alpha 不能同时启用（mixup 的软标签没有对应的"
                "对抗目标；要两者都做请自己在回调里实现）"
            )

        if not isinstance(mixup_alpha, (int, float)) or isinstance(mixup_alpha, bool) \
                or mixup_alpha != mixup_alpha or mixup_alpha < 0:
            raise ValueError(f"fit: mixup_alpha 必须是 >=0 的数字，收到 {mixup_alpha!r}")
        if mixup_alpha > 0.0:
            if self.task != 'classification':
                raise ValueError(
                    f"fit: mixup_alpha 只支持分类任务（需要 one-hot 软标签），当前 task={self.task!r}"
                )
            if self._loss_name not in self._INDEX_LOSSES:
                raise ValueError(
                    f"fit: mixup_alpha 需要索引型损失（{list(self._INDEX_LOSSES)}），"
                    f"当前 {self._loss_name!r} 不支持软标签"
                )

        self.history = {'train_loss': [], 'val_loss': [], 'grad_norm': []}
        if record_layer_norms:
            self.history['layer_grad_norm'] = []
        best_val_loss = float('inf')
        no_improve = 0
        best_snapshot = None      # restore_best_weights 用的最优权重快照

        _resumed_step = 0
        if resume_from is not None:
            _resumed_step = self._load_checkpoint(resume_from)
            if verbose:
                print(f"已恢复权重与优化器状态：{resume_from}（优化器步数 {_resumed_step}）")

        for _cb in callbacks:
            _cb.on_train_begin(self, {
                'epochs': epochs, 'batch_size': batch_size, 'lr': self.lr,
                'task': self.task, 'n_train': len(dataset),
                'n_val': len(val_set) if val_set else 0,
                'resumed_step': _resumed_step,
            })

        for epoch in range(1, epochs + 1):
            for _cb in callbacks:
                _cb.on_epoch_begin(epoch, {'epoch': epoch, 'epochs': epochs, 'lr': self.lr})
            ln_sum = [0.0] * len(self.model.layers) if record_layer_norms else None
            ln_n = 0
            if shuffle:
                rng.shuffle(dataset)

            train_loss = 0.0
            gn_sum = 0.0   # 本轮各次更新的梯度范数之和（裁剪前）
            gn_n = 0
            pending = None      # grad_accum > 1 时的累加缓冲
            pending_n = 0
            for b in range(0, len(dataset), batch_size):
                batch = dataset[b:b + batch_size]
                if train_augment is not None:
                    # 逐样本增强必须在 mixup / 对抗攻击**之前**：Cutout、随机裁剪
                    # 这类变换作用在单个样本上，先混合再增强会把两份样本的语义搅在一起。
                    aug_x = [xi for xi, _ in batch]
                    aug_y = [yi for _, yi in batch]
                    out = train_augment(aug_x, aug_y)
                    if not isinstance(out, tuple) or len(out) != 2:
                        raise ValueError(
                            "fit(train_augment): 必须返回 (xs, ys) 二元组，"
                            f"收到 {type(out).__name__}")
                    new_x, new_y = out
                    if len(new_x) != len(aug_x):
                        raise ValueError(
                            "fit(train_augment): 样本数从 %d 变成 %d（不允许多删少补）"
                            % (len(aug_x), len(new_x)))
                    if len(new_y) != len(aug_y):
                        raise ValueError(
                            "fit(train_augment): 标签数从 %d 变成 %d（不允许多删少补）"
                            % (len(aug_y), len(new_y)))
                    batch = [(list(new_x[i]), new_y[i]) for i in range(len(aug_x))]
                if mixup_alpha > 0.0:
                    batch = self._mixup_batch(batch, mixup_alpha, rng)
                if adv_eps > 0.0:
                    # 用当前权重攻击这一批样本，再在被扰动的样本上训练
                    _adv_seed = rng.randrange(1 << 30) if seed is not None else None
                    _x_adv = pgd_examples(
                        self, [xi for xi, _ in batch], [yi for _, yi in batch],
                        eps=adv_eps, alpha=adv_alpha, steps=adv_steps,
                        random_start=True, seed=_adv_seed,
                    )
                    batch = [(_x_adv[i], batch[i][1]) for i in range(len(batch))]

                # 直接在反向传播时把各样本梯度累加到 buffer：
                #   1) 不再保存 batch 内每个样本的完整梯度（省下 B×参数量 的中间结构）
                #   2) 不再对每个 (层, j, k) 都遍历一遍 batch 求和（那是 O(B) 倍重复）
                acc_w = [[[0.0] * layer.fan_in for _ in range(layer.fan_out)]
                         for layer in self.model.layers]
                acc_b = [[0.0] * layer.fan_out for layer in self.model.layers]

                # 逐样本前向 + 反向
                for xi, yi in batch:
                    pred = self.forward(xi)
                    loss, grad = self._loss(pred, yi)
                    train_loss += loss

                    delta = grad
                    idx = len(self.model.layers) - 1
                    for layer in reversed(self.model.layers):
                        gw, gb, delta = layer.backward(delta)
                        gw_acc, gb_acc = acc_w[idx], acc_b[idx]
                        for j in range(layer.fan_out):
                            gwj, gwaj = gw[j], gw_acc[j]
                            for k in range(layer.fan_in):
                                gwaj[k] += gwj[k]
                            gb_acc[j] += gb[j]
                        idx -= 1

                # 平均梯度（累加顺序与逐样本求和一致，数值与原来完全等价）
                B = len(batch)
                avg_grads = [
                    ([[v / B for v in row] for row in acc_w[i]],
                     [v / B for v in acc_b[i]])
                    for i in range(len(self.model.layers))
                ]

                if grad_accum == 1:
                    # 记录梯度范数（裁剪前，用来判断训练是否发散/爆炸）
                    gn_sum += _grads_norm(avg_grads)
                    gn_n += 1
                    if ln_sum is not None:
                        _accum_layer_norms(ln_sum, avg_grads)
                        ln_n += 1

                    # 梯度裁剪
                    if grad_clip is not None:
                        clip_grad_by_norm(avg_grads, max_norm=grad_clip)

                    self.optimizer.step(avg_grads)
                else:
                    # 先累加各 batch 的**平均梯度**（等价于把 batch 拼大，
                    # 但不需要同时把它们的前向缓存都留在内存里）
                    if pending is None:
                        pending = [([row[:] for row in gw], gb[:])
                                   for gw, gb in avg_grads]
                    else:
                        for (pw, pb), (gw, gb) in zip(pending, avg_grads):
                            for j in range(len(gw)):
                                pwj, gwj = pw[j], gw[j]
                                for k in range(len(gwj)):
                                    pwj[k] += gwj[k]
                                pb[j] += gb[j]
                    pending_n += 1
                    if pending_n >= grad_accum:
                        merged = [
                            ([[v / pending_n for v in row] for row in pw],
                             [v / pending_n for v in pb])
                            for pw, pb in pending
                        ]
                        gn_sum += _grads_norm(merged)
                        gn_n += 1
                        if ln_sum is not None:
                            _accum_layer_norms(ln_sum, merged)
                            ln_n += 1
                        if grad_clip is not None:
                            clip_grad_by_norm(merged, max_norm=grad_clip)
                        self.optimizer.step(merged)
                        pending = None
                        pending_n = 0

            # 收尾：把本 epoch 剩下的不足 grad_accum 个 batch 也更新掉
            if grad_accum > 1 and pending is not None and pending_n > 0:
                merged = [
                    ([[v / pending_n for v in row] for row in pw],
                     [v / pending_n for v in pb])
                    for pw, pb in pending
                ]
                gn_sum += _grads_norm(merged)
                gn_n += 1
                if ln_sum is not None:
                    _accum_layer_norms(ln_sum, merged)
                    ln_n += 1
                if grad_clip is not None:
                    clip_grad_by_norm(merged, max_norm=grad_clip)
                self.optimizer.step(merged)
                pending = None
                pending_n = 0

            train_loss /= len(dataset)
            self.history['train_loss'].append((epoch, train_loss))
            self.history['grad_norm'].append((epoch, gn_sum / max(gn_n, 1)))
            if record_layer_norms:
                self.history['layer_grad_norm'].append(
                    (epoch, [v / max(ln_n, 1) for v in ln_sum])
                )

            # 验证
            val_loss = None
            if not val_set and verbose and patience > 0 and \
                    early_stop_metric != 'train' and epoch == 1:
                print("提示: 没有验证集，early_stop_metric='val' 不会触发早停"
                      "（可用 val_split 或 early_stop_metric='train'）")
            if val_set:
                val_loss = self.evaluate(data=val_set)
                self.history['val_loss'].append((epoch, val_loss))

            for _cb in callbacks:
                _cb.on_epoch_end(epoch, {
                    'epoch': epoch,
                    'train_loss': train_loss,
                    'val_loss': val_loss,
                    'grad_norm': gn_sum / max(gn_n, 1),
                    'layer_grad_norm': None if ln_sum is None
                    else [v / max(ln_n, 1) for v in ln_sum],
                    'lr': self.lr,
                })
            if any(getattr(_cb, 'should_stop', False) for _cb in callbacks):
                if verbose:
                    print("回调请求停止训练（EarlyStopping）")
                break

            # 早停判据：默认盯验证损失（需要验证集）；
            # early_stop_metric='train' 时改盯训练损失，此时不依赖验证集
            # （与 C 引擎 FitConfig.early_stop_on_train 同一语义）
            # 被监控指标：'train' 用训练损失，否则用验证损失（没有验证集则不监控）。
            # 注意：快照与「是否早停」解耦——patience=0 只关闭早停，不关闭最优权重回滚。
            if early_stop_metric == 'train':
                monitored = train_loss
            elif val_set:
                monitored = val_loss
            else:
                monitored = None
            if monitored is not None:
                if monitored < best_val_loss - 1e-12:
                    best_val_loss = monitored
                    no_improve = 0
                    if restore_best_weights:
                        best_snapshot = [
                            ([row[:] for row in l.weights], l.biases[:])
                            for l in self.model.layers
                        ]
                else:
                    no_improve += 1
                if patience > 0 and no_improve >= patience:
                    if verbose:
                        print(f"Early stopping at epoch {epoch}")
                    break

            # 学习率调度
            if lr_scheduler is not None:
                lr_scheduler.step(epoch)

            # 落盘 checkpoint（含优化器动量，可精确续训）
            if checkpoint_path is not None and epoch % max(int(checkpoint_every), 1) == 0:
                save_model(self.model, checkpoint_path, task=self.task,
                           optimizer=self.optimizer, quiet=True)

            # 打印
            if verbose and epoch % max(1, epochs // 10) == 0:
                parts = [f"Epoch {epoch}/{epochs}", f"loss={train_loss:.6f}"]
                if val_loss is not None:
                    parts.append(f"val_loss={val_loss:.6f}")
                print(" | ".join(parts))

        if restore_best_weights and best_snapshot is not None:
            # 回滚到被监控指标最好的那一轮（早停本身不会回滚权重）
            for layer, (w, b) in zip(self.model.layers, best_snapshot):
                for j in range(layer.fan_out):
                    layer.weights[j][:] = w[j]
                layer.biases[:] = b
            if verbose:
                print(f"已回滚到最优权重（monitored={best_val_loss:.6f}）")

        for _cb in callbacks:
            _cb.on_train_end(self.history)

        # epochs=0 时什么都没训练，不能标记为已训练
        self._is_trained = epochs > 0
        return self.history

# ── 推理

    def predict(self, x):
        """预测：单样本返回 list，多样本返回 list[list]"""
        if len(x) > 0 and isinstance(x[0], (list, tuple)):
            return [self.forward(list(xi)) for xi in x]
        return self.forward(list(x))

    def predict_classes(self, x):
        """分类任务专用：返回预测类别索引（单样本 int / 多样本 list[int]）"""
        probs = self.predict(x)
        if isinstance(probs[0], list):
            return [max(range(len(p)), key=lambda i: p[i]) for p in probs]
        return max(range(len(probs)), key=lambda i: probs[i])

# ── 评估

    def evaluate(self, x=None, y=None, data=None):
        """计算平均损失"""
        if x and not isinstance(x[0], (list, tuple)):
            raise ValueError(
                "evaluate: x 必须是样本列表（每个样本是一个序列）；单个样本请写成 [x]"
            )
        if data is not None:
            dataset = [(list(xi), yi) for xi, yi in data]
        elif x is not None and y is not None:
            if len(x) != len(y):
                raise ValueError(
                    f"evaluate: x 有 {len(x)} 个样本，y 有 {len(y)} 个，数量必须一致"
                )
            dataset = [(list(xi), yi) for xi, yi in zip(x, y)]
        else:
            raise ValueError("请提供 data 或 (x, y)")
        if not dataset:
            raise ValueError("evaluate: 数据集为空")

        total = 0.0
        for xi, yi in dataset:
            pred = self.forward(xi)
            loss, _ = self._loss(pred, yi)
            total += loss
        return total / len(dataset)

    def score(self, x, y):
        """分类：准确率 | 回归：R² 决定系数"""
        if x and not isinstance(x[0], (list, tuple)):
            raise ValueError(
                "score: x 必须是样本列表（每个样本是一个序列）；单个样本请写成 [x]"
            )
        if len(x) != len(y):
            raise ValueError(
                f"score: x 有 {len(x)} 个样本，y 有 {len(y)} 个，数量必须一致"
            )
        if not x:
            raise ValueError("score: 数据集为空")
        if self.task == 'classification':
            preds = self.predict_classes(x)
            # y 可能是类别索引，也可能是 one-hot / 概率分布，统一取 argmax 后再比
            targets = [
                max(range(len(yi)), key=lambda i: yi[i]) if isinstance(yi, (list, tuple)) else yi
                for yi in y
            ]
            correct = sum(1 for p, t in zip(preds, targets) if p == t)
            return correct / len(y)
        else:
            preds = self.predict(x)
            # 多输出回归：对每个输出维度分别算 R² 再取平均（单输出时与原来完全一致，
            # 原来是只取第 0 维、静默忽略其余维度）
            n_out = len(preds[0]) if preds and isinstance(preds[0], (list, tuple)) else 1
            if n_out > 1 and not isinstance(y[0], (list, tuple)):
                raise ValueError(
                    f"score: 模型是 {n_out} 维输出，但 y 是标量；"
                    f"请传同维度的目标（多输出不能只对一个维度打分）"
                )
            scores = []
            for d in range(n_out):
                y_d = [(yi if not isinstance(yi, (list, tuple)) else yi[d]) for yi in y]
                p_d = [(pi if not isinstance(pi, (list, tuple)) else pi[d]) for pi in preds]
                ss_res = sum((a - b) ** 2 for a, b in zip(y_d, p_d))
                y_mean = sum(y_d) / len(y_d)
                ss_tot = sum((a - y_mean) ** 2 for a in y_d)
                if ss_tot == 0.0:
                    # 目标恒定：完全预测对是 1，否则 0（原先 max(ss_tot,1e-15)
                    # 会给出 -1e15 量级的荒谬值）
                    scores.append(1.0 if ss_res == 0.0 else 0.0)
                else:
                    scores.append(1 - ss_res / ss_tot)
            return sum(scores) / len(scores)

# ── 评估指标

    def evaluate_all(self, x, y):
        """一次算出常用指标：回归给 mae/rmse/mape/r2，分类给 accuracy/precision/recall/f1、
        confusion_matrix、mcc，二分类另给 roc_auc。详见模块级 `evaluate_all`。"""
        return evaluate_all(self, x, y)

# ── 持久化

    def save(self, filepath):
        """保存模型到 JSON 文件（Adam/AdamW 会连动量与步数一起存）

        除结构与权重外，还会记下损失函数名与 `loss_kwargs`（用 focal / Focal 的
        gamma、CE 的 label_smoothing 训练时，重新加载后不会悄悄退回默认损失）。
        """
        save_model(self.model, filepath, task=self.task, optimizer=self.optimizer,
                   loss=None if self._loss_name == 'custom' else self._loss_name,
                   loss_kwargs=self.loss_kwargs or None)

    @staticmethod
    def load(filepath, loss_fn=None, optimizer='adam', lr=0.01,
             task='auto', default_output_activation=None,
             restore_optimizer=False, loss_kwargs=None):
        """从 JSON 加载，返回 Model 实例

        default_output_activation:
            仅对旧格式（无逐层 activation）文件生效，用来还原旧的 softmax 分类器；
            不传时其输出层会退回 linear，从而被当成回归模型。
        task:
            'auto'（默认）时优先采用文件中记录的 task，其次按输出层激活推断。
        restore_optimizer:
            True 时把文件里的 Adam/AdamW 动量与 step_count 恢复进新优化器，
            这样接着 fit 就是「精确续训」而不是重新热身；文件里没有该字段时忽略。
        loss_fn / loss_kwargs:
            不传时优先采用文件里记录的值（save 会写入），这样用 focal(gamma=…)
            或 CE(label_smoothing=…) 训练的模型重新加载后损失配置不变；
            显式传入则覆盖文件里的值。旧文件没有这些字段时退回默认。
        """
        mlp = load_model(filepath, default_output_activation=default_output_activation)
        if task == 'auto':
            saved = getattr(mlp, "saved_task", None)
            if saved in ('regression', 'classification'):
                task = saved
        # 输出层是 softmax 时只能是分类（softmax + mse 会触发守卫）。
        # 文件里记录的 task 若与激活矛盾，以激活为准，避免自己写出的文件反而加载失败。
        last_act = getattr(mlp.layers[-1], "activation_name", None)
        if last_act == "softmax" and task != 'classification':
            print("提示: 输出层是 softmax，按分类加载（文件里的 task 与输出层激活矛盾）")
            task = 'classification'
        if loss_fn is None:
            saved_loss = getattr(mlp, "saved_loss", None)
            if isinstance(saved_loss, str) and saved_loss in Model._LOSS_MAP:
                loss_fn = saved_loss
        if loss_kwargs is None:
            saved_kw = getattr(mlp, "saved_loss_kwargs", None)
            if isinstance(saved_kw, dict):
                loss_kwargs = saved_kw
        obj = Model(mlp, loss_fn=loss_fn, optimizer=optimizer, lr=lr, task=task,
                    loss_kwargs=loss_kwargs)
        if restore_optimizer:
            try:
                with open(filepath, "r", encoding="utf-8") as f:
                    raw = json.load(f)
            except (OSError, ValueError):
                raw = {}
            state = raw.get("optimizer")
            if state is not None:
                load_optimizer_state(obj.optimizer, state)
                if getattr(obj.optimizer, "step_count", 1) > 1:
                    print(f"已恢复优化器状态（step_count={obj.optimizer.step_count}）")
        return obj

# ── 信息

    def summary(self):
        """打印模型结构摘要"""
        print(f"{'='*50}")
        print(f"  Model ({self.task})")
        print(f"  Loss: {self._loss_name}  |  Optimizer: {type(self.optimizer).__name__}(lr={self.lr})")
        print(f"  {'='*50}")
        total = 0
        _ACT_DISPLAY = {
            'leaky_relu': 'LeakyReLU', 'relu': 'ReLU', 'softmax': 'Softmax',
            'linear': 'Linear', 'gelu': 'GELU', 'sigmoid': 'Sigmoid',
        }
        for i, layer in enumerate(self.model.layers):
            # 优先用 Layer 自己记下的名字：gelu/sigmoid 原来会被显示成 Linear
            act = _ACT_DISPLAY.get(getattr(layer, 'activation_name', None))
            if act is None:
                if layer.act_fn == layer._leaky_relu:
                    act = 'LeakyReLU'
                elif layer.act_fn == layer._relu:
                    act = 'ReLU'
                elif layer.act_fn == layer._softmax:
                    act = 'Softmax'
                elif layer.act_fn == getattr(layer, '_gelu', None):
                    act = 'GELU'
                elif layer.act_fn == getattr(layer, '_sigmoid', None):
                    act = 'Sigmoid'
                else:
                    act = 'Linear'
            params = layer.fan_in * layer.fan_out + layer.fan_out
            total += params
            print(f"  [{i}] Linear({layer.fan_in} → {layer.fan_out}) + {act}   [{params:,}]")
        print(f"  {'='*50}")
        print(f"  Total params: {total:,}")

    def __repr__(self):
        return f"Model(task={self.task}, loss={self._loss_name}, " \
               f"optimizer={type(self.optimizer).__name__}, lr={self.lr})"


# ============================================================================
#  生成模型：VAE / GAN / DDPM
# ============================================================================

def _gauss_vec(n, rng):
    r = rng or random
    return [r.gauss(0.0, 1.0) for _ in range(n)]


def _time_features(t, steps, dim=8):
    """把扩散步 t 编成 sinusoidal 特征（与位置编码同思路）。"""
    out = []
    for i in range(dim // 2):
        freq = 1.0 / (10000.0 ** (2.0 * i / max(1, dim)))
        out.append(math.sin(t * freq))
        out.append(math.cos(t * freq))
    return out


class VAE:
    """变分自编码器（MLP encoder/decoder，2 维潜空间常用来做可视化）

    损失 = 重构 MSE（对维度取平均） + beta * KL(q(z|x) || N(0,1))，
    KL 按维求和、按样本取平均。重参数化 z = mu + eps*exp(logvar/2)。
    """

    def __init__(self, input_dim: int, hidden_dim: int = 32, latent_dim: int = 2,
                 beta: float = 1.0):
        for name, value in (("input_dim", input_dim), ("hidden_dim", hidden_dim),
                            ("latent_dim", latent_dim)):
            if isinstance(value, bool) or not isinstance(value, int) or value < 1:
                raise ValueError(f"VAE: {name} 必须是 >= 1 的整数")
        if not isinstance(beta, (int, float)) or isinstance(beta, bool) or beta < 0:
            raise ValueError("VAE: beta 必须是 >= 0 的数")
        self.input_dim = input_dim
        self.hidden_dim = hidden_dim
        self.latent_dim = latent_dim
        self.beta = float(beta)
        self.enc1 = Layer(input_dim, hidden_dim, activation="relu")
        self.enc2 = Layer(hidden_dim, 2 * latent_dim, activation="linear")
        self.dec1 = Layer(latent_dim, hidden_dim, activation="relu")
        self.dec2 = Layer(hidden_dim, input_dim, activation="linear")
        self.layers = [self.enc1, self.enc2, self.dec1, self.dec2]
        self.step_count = 0

    def _zeros(self):
        return [None] * len(self.layers)

    def zero_grad(self):
        self._g = self._zeros()

    def _acc(self, i, gw, gb):
        if self._g[i] is None:
            self._g[i] = [gw, gb]
        else:
            cur_w, cur_b = self._g[i]
            for r in range(len(cur_w)):
                row_c, row_n = cur_w[r], gw[r]
                for c in range(len(row_c)):
                    row_c[c] += row_n[c]
            for k in range(len(cur_b)):
                cur_b[k] += gb[k]

    def encode(self, x):
        h = self.enc1.forward(x)
        out = self.enc2.forward(h)
        mu = out[:self.latent_dim]
        logvar = out[self.latent_dim:]
        return mu, logvar

    def decode(self, z):
        return self.dec2.forward(self.dec1.forward(z))

    def forward(self, x, eps=None, rng=None):
        mu, logvar = self.encode(x)
        if eps is None:
            eps = _gauss_vec(self.latent_dim, rng)
        if len(eps) != self.latent_dim:
            raise ValueError(f"VAE.forward: eps 维度应为 {self.latent_dim}")
        std = [math.exp(0.5 * v) for v in logvar]
        z = [mu[i] + eps[i] * std[i] for i in range(self.latent_dim)]
        x_hat = self.decode(z)
        self._x, self._mu, self._logvar, self._eps, self._std, self._z = \
            list(x), mu, logvar, list(eps), std, z
        return x_hat

    def loss_and_backward(self, x, eps=None, rng=None):
        if not isinstance(x, (list, tuple)) or len(x) != self.input_dim:
            raise ValueError(f"VAE.loss_and_backward: x 维度应为 {self.input_dim}")
        x_hat = self.forward(x, eps=eps, rng=rng)
        n = self.input_dim
        recon = sum((x_hat[j] - x[j]) ** 2 for j in range(n)) / n
        kl = 0.5 * sum(self._mu[i] ** 2 + math.exp(self._logvar[i])
                       - 1.0 - self._logvar[i] for i in range(self.latent_dim))
        loss = recon + self.beta * kl

        # 重构项 → decoder
        d_x_hat = [2.0 * (x_hat[j] - x[j]) / n for j in range(n)]
        gw2, gb2, d_h = self.dec2.backward(d_x_hat)
        gw1, gb1, d_z = self.dec1.backward(d_h)
        # 重参数化 + KL → encoder 输出（mu 在前、logvar 在后）
        d_mu = [d_z[i] + self.beta * self._mu[i] for i in range(self.latent_dim)]
        d_logvar = [d_z[i] * self._eps[i] * 0.5 * self._std[i]
                    + self.beta * 0.5 * (math.exp(self._logvar[i]) - 1.0)
                    for i in range(self.latent_dim)]
        gwe, gbe, d_hidden = self.enc2.backward(d_mu + d_logvar)
        gw0, gb0, _ = self.enc1.backward(d_hidden)

        self._acc(0, gw0, gb0)
        self._acc(1, gwe, gbe)
        self._acc(2, gw1, gb1)
        self._acc(3, gw2, gb2)
        return loss

    def fit(self, data, epochs=200, lr=1e-2, batch_size=None, seed=None,
            verbose=False):
        if not data:
            raise ValueError("VAE.fit: data 不能为空")
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr <= 0:
            raise ValueError("VAE.fit: lr 必须为正数")
        if isinstance(epochs, bool) or not isinstance(epochs, int) or epochs < 0:
            raise ValueError("VAE.fit: epochs 必须是非负整数")
        rng = random.Random(seed) if seed is not None else random
        history = []
        for _epoch in range(epochs):
            total = 0.0
            self.zero_grad()
            for x in data:
                total += self.loss_and_backward(x, eps=_gauss_vec(self.latent_dim, rng))
            self._scale_grads(1.0 / len(data))
            self.adam_step(lr)
            history.append(total / len(data))
        return history

    def _scale_grads(self, factor):
        if factor == 1.0:
            return
        for item in self._g:
            if item is None:
                continue
            gw, gb = item
            for row in gw:
                for c in range(len(row)):
                    row[c] *= factor
            for k in range(len(gb)):
                gb[k] *= factor

    def adam_step(self, lr=1e-3, b1=0.9, b2=0.999, eps=1e-8):
        self.step_count += 1
        t = self.step_count
        for i, layer in enumerate(self.layers):
            if self._g[i] is None:
                continue
            gw, gb = self._g[i]
            _adam_apply(layer.weights, gw, layer.m_w, layer.v_w, t, lr, b1, b2, eps)
            _adam_apply(layer.biases, gb, layer.m_b, layer.v_b, t, lr, b1, b2, eps)

    def sgd_step(self, lr=1e-2):
        for i, layer in enumerate(self.layers):
            if self._g[i] is None:
                continue
            gw, gb = self._g[i]
            _sgd_apply(layer.weights, gw, lr)
            _sgd_apply(layer.biases, gb, lr)

    def sample(self, n=1, rng=None):
        if isinstance(n, bool) or not isinstance(n, int) or n < 1:
            raise ValueError("VAE.sample: n 必须是 >= 1 的整数")
        return [self.decode(_gauss_vec(self.latent_dim, rng)) for _ in range(n)]


class VQVAE:
    """VQ-VAE（向量量化自编码器，1 维输入）

    encoder 输出连续向量 ``z_e``，在码本里找**最近**的码字 ``e_k`` 替换成 ``z_q``，
    decoder 从 ``z_q`` 重建。反向用 straight-through：``dL/dz_e = dL/dz_q``；
    码本损失 ``||sg[z_e] - e_k||^2`` 与 commitment ``beta * ||z_e - sg[e_k]||^2``
    分别把码字拉向编码、把编码拉向码字。

    - ``encode(x)`` → ``z_e``；``quantize(z_e)`` → ``(z_q, idx, code)``
    - ``decode(z_q)`` → 重建；``forward(x)`` → 重建（记住 ``idx``）
    - ``loss_and_backward(x)`` → 总损失（重构 + 码本 + commitment），并累积梯度
    - ``codebook_histogram()``：最近一次 forward 里码字的使用情况

    已知限制：没有 EMA 码本更新、也没有 dead-code restart，小数据上码本容易
    塌缩（多个样本落到同一个码字）。``fit(warmup=N)`` 前 N 轮只训重构、
    不更新码本，能缓解但不根治。
    """

    def __init__(self, input_dim: int, hidden_dim: int = 32, latent_dim: int = 2,
                 num_codes: int = 8, beta: float = 0.25, seed: int = 0):
        for name, value in (("input_dim", input_dim), ("hidden_dim", hidden_dim),
                            ("latent_dim", latent_dim), ("num_codes", num_codes)):
            if isinstance(value, bool) or not isinstance(value, int) or value < 1:
                raise ValueError(f"VQVAE: {name} 必须是 >= 1 的整数")
        if isinstance(beta, bool) or not isinstance(beta, (int, float)) or beta < 0:
            raise ValueError("VQVAE: beta 必须是 >= 0 的数")
        self.input_dim = input_dim
        self.hidden_dim = hidden_dim
        self.latent_dim = latent_dim
        self.num_codes = num_codes
        self.beta = float(beta)
        self.enc1 = Layer(input_dim, hidden_dim, activation="relu")
        self.enc2 = Layer(hidden_dim, latent_dim, activation="linear")
        self.dec1 = Layer(latent_dim, hidden_dim, activation="relu")
        self.dec2 = Layer(hidden_dim, input_dim, activation="linear")
        self.layers = [self.enc1, self.enc2, self.dec1, self.dec2]

        r = random.Random(seed)
        self.codebook = [[r.gauss(0.0, 1.0) for _ in range(latent_dim)]
                         for _ in range(num_codes)]
        self._cb_m = [[0.0] * latent_dim for _ in range(num_codes)]
        self._cb_v = [[0.0] * latent_dim for _ in range(num_codes)]
        self.step_count = 0
        self.zero_grad()

    # ---------- 梯度缓冲 ----------
    def zero_grad(self):
        self._g = [None] * len(self.layers)
        self._g_cb = [[0.0] * self.latent_dim for _ in range(self.num_codes)]

    def _acc(self, i, gw, gb):
        if self._g[i] is None:
            self._g[i] = [gw, gb]
            return
        cur_w, cur_b = self._g[i]
        for r in range(len(cur_w)):
            for c in range(len(cur_w[r])):
                cur_w[r][c] += gw[r][c]
        for k in range(len(cur_b)):
            cur_b[k] += gb[k]

    # ---------- 前向 ----------
    @staticmethod
    def _check_vec(v, n, name, who):
        if not isinstance(v, (list, tuple)) or len(v) != n:
            raise ValueError(f"{who}: {name} 维度应为 {n}")

    def encode(self, x):
        self._check_vec(x, self.input_dim, "x", "VQVAE.encode")
        return self.enc2.forward(self.enc1.forward(x))

    def quantize(self, z_e):
        """返回 ``(z_q, idx, code)``：L2 距离最近的码字（平局取编号小的）"""
        self._check_vec(z_e, self.latent_dim, "z_e", "VQVAE.quantize")
        best, best_d = 0, None
        for k in range(self.num_codes):
            d = sum((z_e[i] - self.codebook[k][i]) ** 2
                    for i in range(self.latent_dim))
            if best_d is None or d < best_d:
                best, best_d = k, d
        return list(self.codebook[best]), best, list(self.codebook[best])

    def decode(self, z_q):
        self._check_vec(z_q, self.latent_dim, "z_q", "VQVAE.decode")
        return self.dec2.forward(self.dec1.forward(z_q))

    def forward(self, x):
        z_e = self.encode(x)
        z_q, idx, code = self.quantize(z_e)
        x_hat = self.decode(z_q)
        self._x = list(x)
        self._z_e, self._z_q, self._idx, self._code = z_e, z_q, idx, code
        return x_hat

    # ---------- 损失与反向 ----------
    def loss_and_backward(self, x, use_commitment: bool = True):
        """重构 + 码本 + commitment 三项；返回总损失（各项另存在 ``self.last_parts``）"""
        x_hat = self.forward(x)
        n = self.input_dim
        recon = sum((x_hat[j] - x[j]) ** 2 for j in range(n)) / n
        code_loss = sum((self._code[i] - self._z_e[i]) ** 2
                        for i in range(self.latent_dim))
        commit = (self.beta * sum((self._z_e[i] - self._code[i]) ** 2
                                  for i in range(self.latent_dim))
                  if use_commitment else 0.0)
        loss = recon + code_loss + commit
        self.last_parts = {"recon": recon, "codebook": code_loss,
                           "commitment": commit}

        # 重构项 → decoder → z_q
        d_x_hat = [2.0 * (x_hat[j] - x[j]) / n for j in range(n)]
        gw2, gb2, d_h = self.dec2.backward(d_x_hat)
        gw1, gb1, d_z_q = self.dec1.backward(d_h)

        # straight-through：dL/dz_e = dL/dz_q，再加 commitment 项
        d_z_e = list(d_z_q)
        if use_commitment:
            for i in range(self.latent_dim):
                d_z_e[i] += 2.0 * self.beta * (self._z_e[i] - self._code[i])

        # 码本：被选中的码字收到「解码器梯度 + 码本损失梯度」
        for i in range(self.latent_dim):
            self._g_cb[self._idx][i] += d_z_q[i] + 2.0 * (self._code[i] - self._z_e[i])

        gwe, gbe, d_hidden = self.enc2.backward(d_z_e)
        gw0, gb0, _ = self.enc1.backward(d_hidden)
        self._acc(0, gw0, gb0)
        self._acc(1, gwe, gbe)
        self._acc(2, gw1, gb1)
        self._acc(3, gw2, gb2)
        return loss

    def codebook_histogram(self):
        """最近一次 forward 的码字使用情况（长度 num_codes 的计数）"""
        hist = [0] * self.num_codes
        idx = getattr(self, "_idx", None)
        if isinstance(idx, int):
            hist[idx] += 1
        return hist

    # ---------- 训练 ----------
    def sgd_step(self, lr=1e-2):
        for i, layer in enumerate(self.layers):
            if self._g[i] is None:
                continue
            gw, gb = self._g[i]
            _sgd_apply(layer.weights, gw, lr)
            _sgd_apply(layer.biases, gb, lr)
        _sgd_apply(self.codebook, self._g_cb, lr)

    def adam_step(self, lr=1e-3, b1=0.9, b2=0.999, eps=1e-8):
        _check_adam_betas(b1, b2, "VQVAE.adam_step")
        if isinstance(eps, bool) or not isinstance(eps, (int, float)) or eps <= 0:
            raise ValueError("VQVAE.adam_step: eps 必须是 > 0 的数")
        self.step_count += 1
        t = self.step_count
        for i, layer in enumerate(self.layers):
            if self._g[i] is None:
                continue
            gw, gb = self._g[i]
            _adam_apply(layer.weights, gw, layer.m_w, layer.v_w, t, lr, b1, b2, eps)
            _adam_apply(layer.biases, gb, layer.m_b, layer.v_b, t, lr, b1, b2, eps)
        _adam_apply(self.codebook, self._g_cb, self._cb_m, self._cb_v,
                    t, lr, b1, b2, eps)

    def fit(self, data, epochs=200, lr=1e-3, seed=None, warmup=20, verbose=False):
        """先只训重构（码本不动）``warmup`` 轮，让 encoder 先找到结构"""
        if not data:
            raise ValueError("VQVAE.fit: data 不能为空")
        for row in data:
            self._check_vec(row, self.input_dim, "data 行", "VQVAE.fit")
        rng = random.Random(seed)
        history = []
        for epoch in range(epochs):
            total = 0.0
            self.zero_grad()
            for x in data:
                total += self.loss_and_backward(x, use_commitment=epoch >= warmup)
            for item in self._g:
                if item is None:
                    continue
                gw, gb = item
                for row in gw:
                    for c in range(len(row)):
                        row[c] /= len(data)
                for k in range(len(gb)):
                    gb[k] /= len(data)
            if epoch >= warmup:
                for k in range(self.num_codes):
                    for i in range(self.latent_dim):
                        self._g_cb[k][i] /= len(data)
            else:
                # warmup：只训重构，码本一步不动
                for k in range(self.num_codes):
                    for i in range(self.latent_dim):
                        self._g_cb[k][i] = 0.0
            self.adam_step(lr)
            history.append(total / len(data))
        return history


_GAN_VARIANTS = ("bce", "lsgan", "wgan", "hinge")


def _gan_check_variant(variant, who):
    if variant not in _GAN_VARIANTS:
        raise ValueError(f"{who}: variant 只能是 {_GAN_VARIANTS} 之一，"
                         f"收到 {variant!r}")
    return variant


def _gan_d_loss(score, is_real, variant="bce"):
    """判别器在**单个样本**上的损失与 dL/d(score)。

    ``score`` 是判别器的原始输出（bce 变体下是 logit，其余变体是裸分数）。
    - ``bce``：``-log sigma(s)`` / ``-log(1-sigma(s))``
    - ``lsgan``：最小二乘，真样本 ``0.5(s-1)^2``、假样本 ``0.5 s^2``
    - ``wgan``：Wasserstein，真样本 ``-s``、假样本 ``s``
    - ``hinge``：真样本 ``max(0, 1-s)``、假样本 ``max(0, 1+s)``
    """
    _gan_check_variant(variant, "_gan_d_loss")
    if isinstance(score, bool) or not isinstance(score, (int, float)):
        raise ValueError("_gan_d_loss: score 必须是数字")
    if variant == "bce":
        p = _sigmoid_scalar(score)
        if is_real:
            return -math.log(max(p, 1e-12)), p - 1.0
        return -math.log(max(1.0 - p, 1e-12)), p
    if variant == "lsgan":
        if is_real:
            return 0.5 * (score - 1.0) ** 2, score - 1.0
        return 0.5 * score ** 2, score
    if variant == "wgan":
        return (-score, -1.0) if is_real else (score, 1.0)
    # hinge
    if is_real:
        return (max(0.0, 1.0 - score), -1.0 if score < 1.0 else 0.0)
    return (max(0.0, 1.0 + score), 1.0 if score > -1.0 else 0.0)


def _gan_g_loss(score, variant="bce"):
    """生成器损失与 dL/d(score)（score 是假样本的判别器原始输出）。"""
    _gan_check_variant(variant, "_gan_g_loss")
    if variant == "bce":
        p = _sigmoid_scalar(score)
        return -math.log(max(p, 1e-12)), -(1.0 - p)
    if variant == "lsgan":
        return 0.5 * (score - 1.0) ** 2, score - 1.0
    return -score, -1.0            # wgan / hinge 同形


def r1_penalty(d_scores, lam=10.0):
    """R1（或把点换成插值点即 R2）罚项值 ``lam/2 * mean(||dD/dx||^2)``。

    只返回**数值**：本库的反向传播是手写的单阶实现，没有二阶图，
    无法把罚项再回传进参数（PyTorch 的 ``autograd.grad`` 可以）。因此它在这里
    是**诊断量** —— 训练时打印/记录，判断判别器是否过于陡峭，而不是加进损失。
    """
    if not d_scores:
        raise ValueError("r1_penalty: d_scores 不能为空")
    if isinstance(lam, bool) or not isinstance(lam, (int, float)) or lam < 0:
        raise ValueError("r1_penalty: lam 必须是 >= 0 的数")
    total = 0.0
    for g in d_scores:
        total += sum(v * v for v in g)
    return 0.5 * lam * total / len(d_scores)


def r2_penalty(d_scores, lam=10.0):
    """R2 罚项数值：``lam/2 * mean(||dD/dx̂||^2)``，``x̂`` 应取 real/fake 插值点。

    数学形式与 R1 相同，区别只在采样点：R1 用真实样本、R2 用生成样本或两者插值点。
    本库没有二阶图，因此返回值是**诊断量**：训练时记录/打印以判断判别器是否过陡，
    不能直接加进损失反传（PyTorch 的 autograd.grad 才能做到）。
    """
    if not isinstance(d_scores, (list, tuple)) or not d_scores:
        raise ValueError("r2_penalty: d_scores 不能为空")
    if isinstance(lam, bool) or not isinstance(lam, (int, float)) or lam < 0:
        raise ValueError("r2_penalty: lam 必须是 >= 0 的数")
    total = 0.0
    for g in d_scores:
        total += sum(float(v) * float(v) for v in g)
    return 0.5 * lam * total / len(d_scores)


def _r1_r2_check_discriminator(discriminator):
    if not isinstance(discriminator, DCGANDiscriminator):
        raise TypeError("R1/R2 诊断: discriminator 必须是 DCGANDiscriminator")


def _r1_r2_input_grad(discriminator, image):
    """对给定输入算一次 ∇_x D(x)（会污染判别的参数梯度缓冲，调用方负责清零）。"""
    discriminator.forward(image)
    d = discriminator.backward(1.0)
    flat = [float(v) for ch in d for row in ch for v in row]
    norm = math.sqrt(sum(v * v for v in flat))
    return flat, norm


def r1_diagnostics(discriminator, real, lam=10.0):
    """在真实样本上诊断 R1：返回 ``{"r1", "grad_norms"}``。

    R1 = ``lam/2 * mean(||∇_x D(x)||²)``。注意会调用 ``discriminator.backward``，
    从而把该次梯度累积进判别器参数梯度缓冲；建议先 ``zero_grad()``、取完数值后再清零。
    """
    _r1_r2_check_discriminator(discriminator)
    if isinstance(lam, bool) or not isinstance(lam, (int, float)) or lam < 0:
        raise ValueError("r1_diagnostics: lam 必须是 >= 0 的数")
    d, norm = _r1_r2_input_grad(discriminator, real)
    return {"r1": r1_penalty([d], lam), "grad_norms": norm}


def r2_diagnostics(discriminator, real, fake, lam=10.0, alpha=0.5):
    """在 real/fake 插值点 ``x̂ = alpha·real + (1-alpha)·fake`` 上诊断 R2。

    返回 ``{"r2", "grad_norms", "alpha"}``；与 R1 一样会污染判别器参数梯度缓冲。
    """
    _r1_r2_check_discriminator(discriminator)
    if isinstance(lam, bool) or not isinstance(lam, (int, float)) or lam < 0:
        raise ValueError("r2_diagnostics: lam 必须是 >= 0 的数")
    if isinstance(alpha, bool) or not isinstance(alpha, (int, float)) or not (0.0 <= alpha <= 1.0):
        raise ValueError("r2_diagnostics: alpha 必须在 [0, 1]")
    x_hat = _w8a_interpolate(real, fake, float(alpha))
    d, norm = _r1_r2_input_grad(discriminator, x_hat)
    return {"r2": r2_penalty([d], lam), "grad_norms": norm, "alpha": float(alpha)}


def gan_penalty_diagnostics(discriminator, real, fake, lam=10.0, alpha=0.5):
    """一次取回 R1/R2 两个诊断量：``{"r1","r2","grad_norms_real","grad_norms_hat","alpha"}``。"""
    _r1_r2_check_discriminator(discriminator)
    r1 = r1_diagnostics(discriminator, real, lam=lam)
    r2 = r2_diagnostics(discriminator, real, fake, lam=lam, alpha=alpha)
    return {"r1": r1["r1"], "r2": r2["r2"],
            "grad_norms_real": r1["grad_norms"],
            "grad_norms_hat": r2["grad_norms"], "alpha": float(alpha)}

_LOG_2PI = math.log(2.0 * math.pi)


def _realnvp_masks(data_dim, num_layers):
    """交替掩码：偶数维用棋盘格，奇数维用前后半区轮换"""
    if data_dim < 2:
        raise ValueError("RealNVP: data_dim 必须 >= 2")
    masks = []
    if data_dim % 2 == 0:
        a = [1 if i % 2 == 0 else 0 for i in range(data_dim)]
        b = [1 - v for v in a]
    else:
        h = data_dim // 2
        a = [1 if i < h else 0 for i in range(data_dim)]
        b = [1 - v for v in a]
    for layer in range(num_layers):
        masks.append(a if layer % 2 == 0 else b)
    return masks


def _glow_lu(a):
    """对 n x n 矩阵做带部分主元的 LU，返回 (LU, perm, det_sign)"""
    n = len(a)
    m = [row[:] for row in a]
    perm = list(range(n))
    sign = 1.0
    for k in range(n):
        pivot = k
        best = abs(m[k][k])
        for i in range(k + 1, n):
            if abs(m[i][k]) > best:
                best = abs(m[i][k])
                pivot = i
        if best < 1e-14:
            raise ValueError("Glow: 矩阵不可逆（主元过小）")
        if pivot != k:
            m[k], m[pivot] = m[pivot], m[k]
            perm[k], perm[pivot] = perm[pivot], perm[k]
            sign = -sign
        for i in range(k + 1, n):
            f = m[i][k] / m[k][k]
            m[i][k] = f
            for j in range(k + 1, n):
                m[i][j] -= f * m[k][j]
    return m, perm, sign


def _glow_det(a):
    m, _perm, sign = _glow_lu(a)
    d = sign
    for i in range(len(m)):
        d *= m[i][i]
    return d


def _glow_solve(a, b):
    """解 a x = b（a 为 n x n，b 为长度 n）"""
    n = len(a)
    m, perm, _sign = _glow_lu(a)
    rhs = [b[perm[i]] for i in range(n)]
    y = [0.0] * n
    for i in range(n):
        acc = rhs[i]
        for j in range(i):
            acc -= m[i][j] * y[j]
        y[i] = acc
    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        acc = y[i]
        for j in range(i + 1, n):
            acc -= m[i][j] * x[j]
        x[i] = acc / m[i][i]
    return x


def _glow_inverse_matrix(a):
    n = len(a)
    cols = []
    for j in range(n):
        e = [0.0] * n
        e[j] = 1.0
        cols.append(_glow_solve(a, e))
    return [[cols[j][i] for j in range(n)] for i in range(n)]


class ActNorm:
    """ActNorm：逐维仿射 ``y = (x - b) * exp(log_s)``，可数据初始化。

    ``data_init(batch)`` 把 ``b`` 设成首批均值、``log_s`` 设成 ``-log(std)``，
    这是 Glow 论文里的 data-dependent 初始化（让第一层输出零均值单位方差）。
    ``logdet = sum(log_s)`` 与输入无关，所以整层的行列式是常数。
    """

    def __init__(self, dim: int, eps: float = 1e-8):
        if isinstance(dim, bool) or not isinstance(dim, int) or dim < 1:
            raise ValueError("ActNorm: dim 必须是 >= 1 的整数")
        if not isinstance(eps, (int, float)) or isinstance(eps, bool) or not (eps > 0):
            raise ValueError("ActNorm: eps 必须是正数")
        self.dim = dim
        self.eps = float(eps)
        self.b = [0.0] * dim
        self.log_s = [0.0] * dim
        self.g_b = [0.0] * dim
        self.g_log_s = [0.0] * dim
        self._initialized = False

    def data_init(self, batch):
        if not batch:
            raise ValueError("ActNorm.data_init: batch 不能为空")
        n = len(batch)
        for j in range(self.dim):
            mean = sum(row[j] for row in batch) / n
            var = sum((row[j] - mean) ** 2 for row in batch) / n
            self.b[j] = mean
            self.log_s[j] = -0.5 * math.log(var + self.eps)
        self._initialized = True
        return self

    def forward(self, x):
        if len(x) != self.dim:
            raise ValueError(f"ActNorm.forward: 输入维度应为 {self.dim}")
        s = [math.exp(v) for v in self.log_s]
        y = [(x[j] - self.b[j]) * s[j] for j in range(self.dim)]
        self._cache = (list(x), s)
        return y

    def inverse(self, y):
        if len(y) != self.dim:
            raise ValueError(f"ActNorm.inverse: 输入维度应为 {self.dim}")
        s = [math.exp(v) for v in self.log_s]
        return [y[j] / s[j] + self.b[j] for j in range(self.dim)]

    def logdet(self):
        return sum(self.log_s)

    def backward(self, g_y, g_logdet=0.0):
        if getattr(self, "_cache", None) is None:
            raise RuntimeError("ActNorm.backward: 必须先调用 forward()")
        if len(g_y) != self.dim:
            raise ValueError("ActNorm.backward: g_y 维度不符")
        x, s = self._cache
        dx = [g_y[j] * s[j] for j in range(self.dim)]
        for j in range(self.dim):
            self.g_b[j] += -g_y[j] * s[j]
            self.g_log_s[j] += g_y[j] * s[j] * (x[j] - self.b[j]) + g_logdet
        return dx

    def zero_grad(self):
        self.g_b = [0.0] * self.dim
        self.g_log_s = [0.0] * self.dim

    def param_count(self):
        return 2 * self.dim

    def sgd_step(self, lr=1e-3):
        _sgd_apply(self.b, self.g_b, lr)
        _sgd_apply(self.log_s, self.g_log_s, lr)

    def adam_step(self, lr=1e-3, beta1=0.9, beta2=0.999, eps=1e-8):
        _check_adam_betas(beta1, beta2, "ActNorm.adam_step")
        if not hasattr(self, "_am"):
            self._am = ([0.0] * self.dim, [0.0] * self.dim,
                        [0.0] * self.dim, [0.0] * self.dim, 0)
        mb, vb, ms, vs, t = self._am
        t += 1
        c1, c2 = 1.0 - beta1 ** t, 1.0 - beta2 ** t
        for j in range(self.dim):
            for grad, par, m_, v_ in ((self.g_b[j], self.b, mb, vb),
                                      (self.g_log_s[j], self.log_s, ms, vs)):
                m_[j] = beta1 * m_[j] + (1 - beta1) * grad
                v_[j] = beta2 * v_[j] + (1 - beta2) * grad * grad
                par[j] -= lr * (m_[j] / c1) / (math.sqrt(v_[j] / c2) + eps)
        self._am = (mb, vb, ms, vs, t)


class InvertibleLinear:
    """可逆线性层 ``y = W x``，``log|det J| = log|det W|``（精确）。

    ``W`` 初始化为 ``I + 0.05·N(0,1)``（小扰动保证可逆、det 接近 1）。
    ``inverse`` 用带部分主元的高斯消元求解（不是矩阵求逆再相乘，数值更稳）。
    """

    def __init__(self, dim: int, noise: float = 0.05, seed: int = 0):
        if isinstance(dim, bool) or not isinstance(dim, int) or dim < 1:
            raise ValueError("InvertibleLinear: dim 必须是 >= 1 的整数")
        if isinstance(noise, bool) or not isinstance(noise, (int, float))                 or not (0 <= noise < 1):
            raise ValueError("InvertibleLinear: noise 必须在 [0,1) 内")
        if isinstance(seed, bool) or not isinstance(seed, int):
            raise ValueError("InvertibleLinear: seed 必须是整数")
        self.dim = dim
        r = random.Random(seed)
        self.W = [[(1.0 if i == j else 0.0) + noise * r.gauss(0.0, 1.0)
                   for j in range(dim)] for i in range(dim)]
        self.g_W = [[0.0] * dim for _ in range(dim)]

    def forward(self, x):
        if len(x) != self.dim:
            raise ValueError(f"InvertibleLinear.forward: 输入维度应为 {self.dim}")
        y = [sum(self.W[i][j] * x[j] for j in range(self.dim))
             for i in range(self.dim)]
        det = _glow_det(self.W)
        if abs(det) < 1e-14:
            raise ValueError("InvertibleLinear: W 不可逆")
        self._cache = list(x)
        self._logdet = math.log(abs(det))
        return y

    def inverse(self, y):
        if len(y) != self.dim:
            raise ValueError(f"InvertibleLinear.inverse: 输入维度应为 {self.dim}")
        return _glow_solve(self.W, list(y))

    def logdet(self):
        if getattr(self, "_cache", None) is None:
            raise RuntimeError("InvertibleLinear.logdet: 必须先调用 forward()")
        return self._logdet

    def backward(self, g_y, g_logdet=0.0):
        if getattr(self, "_cache", None) is None:
            raise RuntimeError("InvertibleLinear.backward: 必须先调用 forward()")
        if len(g_y) != self.dim:
            raise ValueError("InvertibleLinear.backward: g_y 维度不符")
        x = self._cache
        dx = [sum(self.W[i][j] * g_y[i] for i in range(self.dim))
              for j in range(self.dim)]
        for i in range(self.dim):
            for j in range(self.dim):
                self.g_W[i][j] += g_y[i] * x[j]
        if g_logdet != 0.0:
            winv_t = _glow_inverse_matrix(self.W)
            for i in range(self.dim):
                for j in range(self.dim):
                    # d log|det W| / dW = (W^{-1})^T
                    self.g_W[i][j] += g_logdet * winv_t[j][i]
        return dx

    def zero_grad(self):
        self.g_W = [[0.0] * self.dim for _ in range(self.dim)]

    def param_count(self):
        return self.dim * self.dim

    def sgd_step(self, lr=1e-3):
        for i in range(self.dim):
            row = self.W[i]
            grow = self.g_W[i]
            for j in range(self.dim):
                row[j] -= lr * grow[j]

    def adam_step(self, lr=1e-3, beta1=0.9, beta2=0.999, eps=1e-8):
        _check_adam_betas(beta1, beta2, "InvertibleLinear.adam_step")
        if not hasattr(self, "_am"):
            self._am = (_zeros_like(self.W), _zeros_like(self.W), 0)
        mw, vw, t = self._am
        t += 1
        c1, c2 = 1.0 - beta1 ** t, 1.0 - beta2 ** t
        for i in range(self.dim):
            for j in range(self.dim):
                g = self.g_W[i][j]
                mw[i][j] = beta1 * mw[i][j] + (1 - beta1) * g
                vw[i][j] = beta2 * vw[i][j] + (1 - beta2) * g * g
                self.W[i][j] -= lr * (mw[i][j] / c1) / (
                    math.sqrt(vw[i][j] / c2) + eps)
        self._am = (mw, vw, t)


class RealNVP:
    """RealNVP：仿射耦合流，可逆且能算**精确**对数似然。

    ``y`` 的构造（每层，掩码 ``m`` 选出「被保留」的那一半 ``x_a``）：

        s = scale_limit * tanh(W_s2 sigmoid(W_s1 x_a + b_s1) + b_s2)
        t = W_t2 tanh(W_t1 x_a + b_t1) + b_t2
        y_a = x_a,  y_b = x_b * exp(s) + t

    因此 ``log|det J| = sum(s)``（三角雅可比，精确无近似）；``inverse`` 用
    ``x_b = (y_b - t) * exp(-s)`` 逐层逆推。``log_prob`` 把 ``y`` 当标准正态。

    与 DDPM/FlowMatching 的区别：这两者是「采样器」，只能在积分意义上近似
    似然；RealNVP 是**精确似然模型**，可直接做最大似然训练与密度评估。
    ``tanh`` 把 scale 限制在 ±``scale_limit``，避免 exp 溢出（这是教学简化，
    原论文用普通实值 scale）。
    """

    def __init__(self, data_dim: int = 2, hidden_dim: int = 16,
                 num_layers: int = 4, scale_limit: float = 1.0, seed: int = 0):
        for name, value in (("data_dim", data_dim), ("hidden_dim", hidden_dim),
                            ("num_layers", num_layers)):
            if isinstance(value, bool) or not isinstance(value, int) or value < 1:
                raise ValueError(f"RealNVP: {name} 必须是 >= 1 的整数")
        if isinstance(scale_limit, bool) or not isinstance(scale_limit, (int, float)):
            raise ValueError("RealNVP: scale_limit 必须是正数")
        if not (scale_limit > 0 and math.isfinite(scale_limit)):
            raise ValueError(f"RealNVP: scale_limit 必须有限且 > 0，收到 {scale_limit!r}")
        self.data_dim = data_dim
        self.hidden_dim = hidden_dim
        self.num_layers = num_layers
        self.scale_limit = float(scale_limit)
        self.masks = _realnvp_masks(data_dim, num_layers)
        if isinstance(seed, bool) or not isinstance(seed, int):
            raise ValueError("RealNVP: seed 必须是整数")
        # Layer 用全局 random 初始化；这里临时播种再恢复状态，避免污染调用方
        _saved = random.getstate()
        random.seed(seed)
        try:
            self.layers = []
            for mask in self.masks:
                dim_a = sum(mask)
                dim_b = data_dim - dim_a
                self.layers.append({
                    "mask": mask,
                    "dim_a": dim_a,
                    "dim_b": dim_b,
                    "s1": Layer(dim_a, hidden_dim, activation="sigmoid"),
                    "s2": Layer(hidden_dim, dim_b, activation="linear"),
                    "t1": Layer(dim_a, hidden_dim, activation="sigmoid"),
                    "t2": Layer(hidden_dim, dim_b, activation="linear"),
                })
        finally:
            random.setstate(_saved)
        self._grads = None
        self._adam_t = 0
        self._adam = None
        self._init_adam()

    # ---- 参数与状态 -------------------------------------------------
    def _params(self):
        out = []
        for lay in self.layers:
            for key in ("s1", "s2", "t1", "t2"):
                out.append(lay[key])
        return out

    def _init_adam(self):
        self._adam = []
        for layer in self._params():
            self._adam.append((_zeros_like(layer.weights),
                               _zeros_like(layer.weights),
                               [0.0] * len(layer.biases),
                               [0.0] * len(layer.biases)))

    def zero_grad(self):
        self._grads = None

    def param_count(self):
        total = 0
        for layer in self._params():
            total += len(layer.weights) * len(layer.weights[0]) + len(layer.biases)
        return total

    # ---- 前向 / 反向 -----------------------------------------------
    def _split(self, x, mask):
        xa = [x[i] for i in range(len(x)) if mask[i]]
        xb = [x[i] for i in range(len(x)) if not mask[i]]
        return xa, xb

    def _merge(self, xa, xb, mask):
        out = [0.0] * len(mask)
        ia = ib = 0
        for i in range(len(mask)):
            if mask[i]:
                out[i] = xa[ia]
                ia += 1
            else:
                out[i] = xb[ib]
                ib += 1
        return out

    def _coupling_forward(self, lay, x):
        mask = lay["mask"]
        xa, xb = self._split(x, mask)
        hs = lay["s1"].forward(xa)
        pre_s = lay["s2"].forward(hs)
        lim = self.scale_limit
        s = [lim * math.tanh(v) for v in pre_s]
        ht = lay["t1"].forward(xa)
        t = lay["t2"].forward(ht)
        yb = [xb[i] * math.exp(s[i]) + t[i] for i in range(lay["dim_b"])]
        return self._merge(xa, yb, mask), s, t, xa, xb, hs, ht, pre_s

    def forward(self, x):
        """返回 ``(y, logdet)``"""
        self._check_x(x)
        y = list(x)
        logdet = 0.0
        caches = []
        for lay in self.layers:
            y, s, t, xa, xb, hs, ht, pre_s = self._coupling_forward(lay, y)
            logdet += sum(s)
            caches.append((s, t, xa, xb, hs, ht, pre_s))
        self._cache = caches
        self._x = list(x)
        return y, logdet

    def _check_x(self, x):
        if not isinstance(x, (list, tuple)) or len(x) != self.data_dim:
            raise ValueError(f"RealNVP: x 维度应为 {self.data_dim}")
        for v in x:
            if isinstance(v, bool) or not isinstance(v, (int, float)) \
                    or not math.isfinite(v):
                raise ValueError("RealNVP: x 的元素必须是有限数字")

    def backward(self, g_y, g_logdet=0.0):
        """返回 ``(dL/dx, 参数梯度已累加到 self._grads)``"""
        if getattr(self, "_cache", None) is None:
            raise RuntimeError("RealNVP.backward: 必须先调用 forward()")
        if len(g_y) != self.data_dim:
            raise ValueError(
                f"RealNVP.backward: g_y 长度 {len(g_y)} 与 data_dim {self.data_dim} 不一致")
        grad = g_y
        lim = self.scale_limit
        grads = [] if self._grads is None else self._grads
        acc = {}

        def add(key, gw, gb):
            if key not in acc:
                acc[key] = ([row[:] for row in gw], list(gb))
            else:
                aw, ab = acc[key]
                for i in range(len(gw)):
                    for j in range(len(gw[0])):
                        aw[i][j] += gw[i][j]
                for i in range(len(gb)):
                    ab[i] += gb[i]

        for idx in range(len(self.layers) - 1, -1, -1):
            lay = self.layers[idx]
            mask = lay["mask"]
            s, t, xa, xb, hs, ht, pre_s = self._cache[idx]
            db = sum(mask)
            g_a_in, g_b_in = self._split(grad, mask)
            exp_s = [math.exp(v) for v in s]
            dxb = [g_b_in[i] * exp_s[i] for i in range(db)]
            # -1 来自 -logdet 对 s 的偏导；这里 g_logdet 是 dL/dlogdet
            d_s = [g_b_in[i] * xb[i] * exp_s[i] + g_logdet for i in range(db)]
            d_t = list(g_b_in)
            # s = lim*tanh(pre_s) -> dpre = d_s*lim*(1-tanh^2)
            d_pre_s = [d_s[i] * lim * (1.0 - (s[i] / lim) ** 2) for i in range(db)]
            gw2s, gb2s, dhs_s = lay["s2"].backward(d_pre_s)
            gw2t, gb2t, dht = lay["t2"].backward(d_t)
            gw1s, gb1s, dxa_s = lay["s1"].backward(dhs_s)
            gw1t, gb1t, dxa_t = lay["t1"].backward(dht)
            add((idx, "s2"), gw2s, gb2s)
            add((idx, "t2"), gw2t, gb2t)
            add((idx, "s1"), gw1s, gb1s)
            add((idx, "t1"), gw1t, gb1t)
            dxa = [g_a_in[i] + dxa_s[i] + dxa_t[i] for i in range(len(g_a_in))]
            grad = self._merge(dxa, dxb, mask)

        self._grads = []
        for idx, lay in enumerate(self.layers):
            for key in ("s1", "s2", "t1", "t2"):
                if (idx, key) in acc:
                    self._grads.append(acc[(idx, key)])
                else:
                    layer = lay[key]
                    self._grads.append(
                        (_zeros_like(layer.weights), [0.0] * len(layer.biases)))
        return grad

    # ---- 逆变换 / 似然 ---------------------------------------------
    def inverse(self, y):
        """把 ``y`` 映射回数据空间（与 ``forward`` 精确互逆，误差 ~1e-15）"""
        self._check_x(y)
        x = list(y)
        for idx in range(len(self.layers) - 1, -1, -1):
            lay = self.layers[idx]
            mask = lay["mask"]
            ya, yb = self._split(x, mask)
            hs = lay["s1"].forward(ya)
            pre_s = lay["s2"].forward(hs)
            lim = self.scale_limit
            s = [lim * math.tanh(v) for v in pre_s]
            ht = lay["t1"].forward(ya)
            t = lay["t2"].forward(ht)
            xb = [(yb[i] - t[i]) * math.exp(-s[i]) for i in range(lay["dim_b"])]
            x = self._merge(ya, xb, mask)
        return x

    def log_prob(self, x):
        """标准正态基分布 + 精确 log|det J|"""
        y, logdet = self.forward(x)
        base = -0.5 * sum(v * v for v in y) - 0.5 * self.data_dim * _LOG_2PI
        return base + logdet

    def nll(self, x):
        return -self.log_prob(x)

    def sample(self, n=1, rng=None):
        if isinstance(n, bool) or not isinstance(n, int) or n < 1:
            raise ValueError("RealNVP.sample: n 必须是 >= 1 的整数")
        r = rng or random
        out = []
        for _ in range(n):
            z = [r.gauss(0.0, 1.0) for _ in range(self.data_dim)]
            out.append(self.inverse(z))
        return out

    # ---- 训练 -------------------------------------------------------
    def train_step(self, x, lr=1e-3):
        """一步最大似然：最小化 nll = -log_prob(x)"""
        y, logdet = self.forward(x)
        # nll = 0.5|y|^2 + 0.5*d*log(2pi) - logdet
        # 所以 dL/dy = y、dL/dlogdet = -1
        self.backward(y, -1.0)
        self.adam_step(lr)
        return -(-0.5 * sum(v * v for v in y)
                 - 0.5 * self.data_dim * _LOG_2PI + logdet)

    def fit(self, data, epochs=200, lr=1e-2, seed=None, verbose=False):
        if not data:
            raise ValueError("RealNVP.fit: data 不能为空")
        r = random.Random(seed) if seed is not None else random
        order = list(range(len(data)))
        last = 0.0
        for epoch in range(epochs):
            r.shuffle(order)
            total = 0.0
            for i in order:
                total += self.train_step(data[i], lr=lr)
            last = total / len(data)
            if verbose and (epoch % 50 == 0 or epoch == epochs - 1):
                print(f"  RealNVP epoch {epoch + 1}/{epochs}: nll={last:.4f}")
        return last

    def sgd_step(self, lr=1e-3):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError("RealNVP.sgd_step: lr 必须是 >= 0 的数")
        if self._grads is None:
            raise RuntimeError("RealNVP.sgd_step: 没有梯度（先 backward）")
        for (gw, gb), layer in zip(self._grads, self._params()):
            for i in range(len(layer.weights)):
                wi = layer.weights[i]
                gi = gw[i]
                for j in range(len(wi)):
                    wi[j] -= lr * gi[j]
                layer.biases[i] -= lr * gb[i]

    def adam_step(self, lr=1e-3, beta1=0.9, beta2=0.999, eps=1e-8):
        _check_adam_betas(beta1, beta2, "RealNVP.adam_step")
        c1, c2 = 1.0 - beta1, 1.0 - beta2
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError("RealNVP.adam_step: lr 必须是 >= 0 的数")
        if self._grads is None:
            raise RuntimeError("RealNVP.adam_step: 没有梯度（先 backward）")
        self._adam_t += 1
        t = self._adam_t
        bc1 = 1.0 - beta1 ** t
        bc2 = 1.0 - beta2 ** t
        for k, ((gw, gb), layer) in enumerate(zip(self._grads, self._params())):
            mw, vw, mb, vb = self._adam[k]
            for i in range(len(layer.weights)):
                wi = layer.weights[i]
                for j in range(len(wi)):
                    g = gw[i][j]
                    mw[i][j] = beta1 * mw[i][j] + (1 - beta1) * g
                    vw[i][j] = beta2 * vw[i][j] + (1 - beta2) * g * g
                    wi[j] -= lr * (mw[i][j] / bc1) / (
                        math.sqrt(vw[i][j] / bc2) + eps)
                g = gb[i]
                mb[i] = beta1 * mb[i] + (1 - beta1) * g
                vb[i] = beta2 * vb[i] + (1 - beta2) * g * g
                layer.biases[i] -= lr * (mb[i] / bc1) / (
                    math.sqrt(vb[i] / bc2) + eps)


class GAN:
    """最小可训练 GAN（MLP 生成器 / 判别器，BCE 损失）

    判别器：D(x) = sigmoid(MLP(x))；生成器：G(z) 直接输出样本。
    训练时 D 用「真实样本 + 生成样本」各一次损失，G 只走判别器的生成分支
    （梯度穿过 D 但不更新 D 的参数）。

    ``variant`` 选判别器损失：``bce``（默认，与原实现逐位一致）/ ``lsgan`` /
    ``wgan`` / ``hinge``。非 bce 时 ``d2`` 输出裸分数，``score(x)`` 拿原始输出、
    ``discriminate(x)`` 仍然返回 ``sigmoid(score)``（便于统一观察）。
    ``wgan`` 变体在每步更新判别器后把权重裁到 ``[-clip_value, clip_value]``
    （默认 0.01）——没有这个约束 WGAN 的分数会一路发散，实测 400 步后
    判别器损失到 -71。R1/R2 罚项见模块函数 ``r1_penalty``：只手写单阶反向、
    没有二阶图，因此是**诊断量**（训练时监控判别器陡峭程度），不参与参数更新。
    """

    def __init__(self, input_dim: int, hidden_dim: int = 32, latent_dim: int = 2,
                 variant: str = "bce"):
        for name, value in (("input_dim", input_dim), ("hidden_dim", hidden_dim),
                            ("latent_dim", latent_dim)):
            if isinstance(value, bool) or not isinstance(value, int) or value < 1:
                raise ValueError(f"GAN: {name} 必须是 >= 1 的整数")
        self.variant = _gan_check_variant(variant, "GAN")
        self.input_dim = input_dim
        self.hidden_dim = hidden_dim
        self.latent_dim = latent_dim
        self.d1 = Layer(input_dim, hidden_dim, activation="leaky_relu")
        # bce 变体保留 sigmoid 输出（与原实现逐位一致）；其余变体要裸分数
        self.d2 = Layer(hidden_dim, 1,
                        activation="sigmoid" if self.variant == "bce" else "linear")
        self.g1 = Layer(latent_dim, hidden_dim, activation="relu")
        self.g2 = Layer(hidden_dim, input_dim, activation="linear")

    # ---- 判别器
    def discriminate(self, x):
        """判别器输出概率：bce 变体直接用 sigmoid 层，其余变体对裸分数取 sigmoid"""
        if not isinstance(x, (list, tuple)) or len(x) != self.input_dim:
            raise ValueError(f"GAN.discriminate: x 维度应为 {self.input_dim}")
        h = self.d1.forward(x)
        out = self.d2.forward(h)
        if self.variant == "bce":
            return out[0]
        return _sigmoid_scalar(out[0])

    def score(self, x):
        """判别器的**原始输出**（bce 变体是 logit，其余变体是裸分数）。"""
        if not isinstance(x, (list, tuple)) or len(x) != self.input_dim:
            raise ValueError(f"GAN.score: x 维度应为 {self.input_dim}")
        self.d2.forward(self.d1.forward(x))
        return self.d2.z[0]

    def _d_grads(self, x, target):
        p = self.discriminate(x)
        p = min(max(p, 1e-12), 1.0 - 1e-12)
        loss = -(target * math.log(p) + (1.0 - target) * math.log(1.0 - p))
        d_out = [-(target / p) + (1.0 - target) / (1.0 - p)]
        gw2, gb2, d_h = self.d2.backward(d_out)
        gw1, gb1, d_x = self.d1.backward(d_h)
        return loss, (gw1, gb1), (gw2, gb2), d_x

    # ---- 生成器
    def generate(self, z):
        if not isinstance(z, (list, tuple)) or len(z) != self.latent_dim:
            raise ValueError(f"GAN.generate: z 维度应为 {self.latent_dim}")
        return self.g2.forward(self.g1.forward(z))

    def _g_grads(self, z):
        """生成样本的 D 分数对 G 的梯度（希望 D 判为 1）。"""
        x_fake = self.generate(z)
        p = self.discriminate(x_fake)
        p = min(max(p, 1e-12), 1.0 - 1e-12)
        d_out = [-1.0 / p]
        gw2, gb2, d_h = self.d2.backward(d_out)
        _gw1, _gb1, d_x = self.d1.backward(d_h)
        gw_g2, gb_g2, d_h1 = self.g2.backward(d_x)
        gw_g1, gb_g1, _ = self.g1.backward(d_h1)
        return (gw_g1, gb_g1), (gw_g2, gb_g2)

    def _d_grads_ex(self, x, is_real):
        """变体路径的判别器梯度：返回 (loss, (gw1, gb1), (gw2, gb2), d_x)"""
        _ = self.d1.forward(x)
        _ = self.d2.forward(_)
        score = self.d2.z[0]
        loss, d_score = _gan_d_loss(score, is_real, self.variant)
        gw2, gb2, d_h = self.d2.backward([d_score])
        gw1, gb1, d_x = self.d1.backward(d_h)
        return loss, (gw1, gb1), (gw2, gb2), d_x

    def _g_grads_ex(self, z):
        """变体路径的生成器梯度：返回 ((gw_g1, gb_g1), (gw_g2, gb_g2))"""
        x_fake = self.generate(z)
        _ = self.d1.forward(x_fake)
        _ = self.d2.forward(_)
        score = self.d2.z[0]
        _loss, d_score = _gan_g_loss(score, self.variant)
        gw2, gb2, d_h = self.d2.backward([d_score])
        _gw1, _gb1, d_x = self.d1.backward(d_h)
        gw_g2, gb_g2, d_h1 = self.g2.backward(d_x)
        gw_g1, gb_g1, _ = self.g1.backward(d_h1)
        return (gw_g1, gb_g1), (gw_g2, gb_g2)

    def step(self, real_batch, rng=None, lr_d=1e-3, lr_g=1e-3, adam=True,
             variant=None, clip_value=None):
        if not real_batch:
            raise ValueError("GAN.step: real_batch 不能为空")
        v = _gan_check_variant(variant or self.variant, "GAN.step")
        if v != "bce":
            return self._step_variant(real_batch, v, rng=rng, lr_d=lr_d,
                                      lr_g=lr_g, adam=adam,
                                      clip_value=clip_value)
        r = rng or random
        # 1) 判别器：真实 + 生成各一次
        d_loss = 0.0
        accs = {"d1": None, "d2": None}
        for x in real_batch:
            loss, (w1, b1), (w2, b2), _ = self._d_grads(x, 1.0)
            d_loss += loss
            self._acc_pair(accs, "d1", w1, b1)
            self._acc_pair(accs, "d2", w2, b2)
        for _ in real_batch:
            z = _gauss_vec(self.latent_dim, r)
            loss, (w1, b1), (w2, b2), _ = self._d_grads(self.generate(z), 0.0)
            d_loss += loss
            self._acc_pair(accs, "d1", w1, b1)
            self._acc_pair(accs, "d2", w2, b2)
        scale = 1.0 / (2 * len(real_batch))
        self._apply(self.d1, accs["d1"], lr_d, scale, adam, "d1")
        self._apply(self.d2, accs["d2"], lr_d, scale, adam, "d2")

        # 2) 生成器：只更新 g1/g2
        g_loss = 0.0
        gaccs = {"g1": None, "g2": None}
        for _ in real_batch:
            z = _gauss_vec(self.latent_dim, r)
            (w1, b1), (w2, b2) = self._g_grads(z)
            g_loss += -math.log(max(1e-12, self.discriminate(self.generate(z))))
            self._acc_pair(gaccs, "g1", w1, b1)
            self._acc_pair(gaccs, "g2", w2, b2)
        scale_g = 1.0 / len(real_batch)
        self._apply(self.g1, gaccs["g1"], lr_g, scale_g, adam, "g1")
        self._apply(self.g2, gaccs["g2"], lr_g, scale_g, adam, "g2")
        return d_loss / (2 * len(real_batch)), g_loss / len(real_batch)

    def _step_variant(self, real_batch, variant, rng=None, lr_d=1e-3,
                      lr_g=1e-3, adam=True, clip_value=None):
        """LSGAN / WGAN / Hinge 的一步：损失不同，梯度结构相同"""
        r = rng or random
        d_loss = 0.0
        accs = {"d1": None, "d2": None}
        for x in real_batch:
            loss, (w1, b1), (w2, b2), _dx = self._d_grads_ex(x, True)
            d_loss += loss
            self._acc_pair(accs, "d1", w1, b1)
            self._acc_pair(accs, "d2", w2, b2)
        for _ in real_batch:
            z = _gauss_vec(self.latent_dim, r)
            loss, (w1, b1), (w2, b2), _dx = self._d_grads_ex(
                self.generate(z), False)
            d_loss += loss
            self._acc_pair(accs, "d1", w1, b1)
            self._acc_pair(accs, "d2", w2, b2)
        scale = 1.0 / (2 * len(real_batch))
        self._apply(self.d1, accs["d1"], lr_d, scale, adam, "d1")
        self._apply(self.d2, accs["d2"], lr_d, scale, adam, "d2")

        # WGAN 的 Lipschitz 约束：默认把判别器权重裁到 [-0.01, 0.01]
        if variant == "wgan":
            c = 0.01 if clip_value is None else clip_value
            if isinstance(c, bool) or not isinstance(c, (int, float)) or c <= 0:
                raise ValueError(
                    "GAN.step: WGAN 的 clip_value 必须是 > 0 的数")
            self._clip_weights(self.d1, c)
            self._clip_weights(self.d2, c)

        g_loss = 0.0
        gaccs = {"g1": None, "g2": None}
        for _ in real_batch:
            z = _gauss_vec(self.latent_dim, r)
            (w1, b1), (w2, b2) = self._g_grads_ex(z)
            g_loss += _gan_g_loss(self.score(self.generate(z)), variant)[0]
            self._acc_pair(gaccs, "g1", w1, b1)
            self._acc_pair(gaccs, "g2", w2, b2)
        scale_g = 1.0 / len(real_batch)
        self._apply(self.g1, gaccs["g1"], lr_g, scale_g, adam, "g1")
        self._apply(self.g2, gaccs["g2"], lr_g, scale_g, adam, "g2")
        return d_loss / (2 * len(real_batch)), g_loss / len(real_batch)

    @staticmethod
    def _clip_weights(layer, clip):
        """把层权重逐元素夹到 [-clip, clip]（WGAN 的原始 Lipschitz 约束）"""
        for row in layer.weights:
            for i in range(len(row)):
                row[i] = min(clip, max(-clip, row[i]))

    @staticmethod
    def _acc_pair(accs, key, gw, gb):
        if accs[key] is None:
            accs[key] = [[[v for v in row] for row in gw], list(gb)]
        else:
            cur = accs[key]
            for r_ in range(len(cur[0])):
                for c in range(len(cur[0][r_])):
                    cur[0][r_][c] += gw[r_][c]
            for k in range(len(cur[1])):
                cur[1][k] += gb[k]

    def _apply(self, layer, acc, lr, scale, adam, tag):
        if acc is None:
            return
        gw, gb = acc
        for row in gw:
            for c in range(len(row)):
                row[c] *= scale
        for k in range(len(gb)):
            gb[k] *= scale
        self._adam_t = getattr(self, "_adam_t", 0)
        if adam:
            self._adam_t += 1
            _adam_apply(layer.weights, gw, layer.m_w, layer.v_w, self._adam_t, lr)
            _adam_apply(layer.biases, gb, layer.m_b, layer.v_b, self._adam_t, lr)
        else:
            _sgd_apply(layer.weights, gw, lr)
            _sgd_apply(layer.biases, gb, lr)

    def fit(self, data, epochs=200, lr_d=1e-3, lr_g=1e-3, seed=None,
            verbose=False):
        if not data:
            raise ValueError("GAN.fit: data 不能为空")
        rng = random.Random(seed) if seed is not None else random
        history = []
        for _epoch in range(epochs):
            d_loss, g_loss = self.step(data, rng=rng, lr_d=lr_d, lr_g=lr_g)
            history.append((d_loss, g_loss))
        return history


class DDPM:
    """最小 DDPM（去噪扩散概率模型）

    前向：x_t = sqrt(abar_t)*x0 + sqrt(1-abar_t)*noise
    训练：给网络 (x_t, t) 让它预测 ``prediction`` 指定的量（噪声 / v / x0），损失是逐维 MSE
    采样：``sample()`` 是 DDPM（随机，用全部 steps）；``ddim_sample()`` 是 DDIM
    （``eta=0`` 时确定性、可只走 ``steps`` 中的一部分子序列）
    min-SNR：``train_step(..., min_snr_gamma=g)`` 按 ``min(SNR, g)/SNR`` 加权
    """

    def __init__(self, data_dim: int, hidden_dim: int = 32, steps: int = 50,
                 beta_start: float = 1e-4, beta_end: float = 0.02, t_dim: int = 8,
                 prediction: str = "eps"):
        for name, value in (("data_dim", data_dim), ("hidden_dim", hidden_dim),
                            ("steps", steps), ("t_dim", t_dim)):
            if isinstance(value, bool) or not isinstance(value, int) or value < 1:
                raise ValueError(f"DDPM: {name} 必须是 >= 1 的整数")
        if not 0.0 < beta_start < beta_end < 1.0:
            raise ValueError("DDPM: 需要 0 < beta_start < beta_end < 1")
        if prediction not in ("eps", "v", "x0"):
            raise ValueError("DDPM: prediction 只能是 'eps' / 'v' / 'x0'，"
                             f"收到 {prediction!r}")
        self.prediction = prediction
        self.data_dim = data_dim
        self.hidden_dim = hidden_dim
        self.steps = steps
        self.t_dim = t_dim if t_dim % 2 == 0 else t_dim + 1

        self.betas = [beta_start + (beta_end - beta_start) * i / max(1, steps - 1)
                      for i in range(steps)]
        self.alphas = [1.0 - b for b in self.betas]
        self.abar = []
        prod = 1.0
        for a in self.alphas:
            prod *= a
            self.abar.append(prod)

        self.l1 = Layer(data_dim + self.t_dim, hidden_dim, activation="relu")
        self.l2 = Layer(hidden_dim, hidden_dim, activation="relu")
        self.l3 = Layer(hidden_dim, data_dim, activation="linear")
        self.layers = [self.l1, self.l2, self.l3]
        self.step_count = 0
        self.zero_grad()

    def zero_grad(self):
        self._g = [None] * len(self.layers)

    def _acc(self, i, gw, gb):
        if self._g[i] is None:
            self._g[i] = [gw, gb]
            return
        cur_w, cur_b = self._g[i]
        for r in range(len(cur_w)):
            for c in range(len(cur_w[r])):
                cur_w[r][c] += gw[r][c]
        for k in range(len(cur_b)):
            cur_b[k] += gb[k]

    def _grid(self, x, t):
        if t < 0 or t >= self.steps:
            raise ValueError(f"DDPM: 步数 t 必须在 [0, {self.steps})")
        if not isinstance(x, (list, tuple)) or len(x) != self.data_dim:
            raise ValueError(f"DDPM: x 维度应为 {self.data_dim}")
        return list(x) + _time_features(t, self.steps, self.t_dim)

    def q_sample(self, x0, t, noise):
        """前向加噪：x_t = sqrt(abar_t) * x0 + sqrt(1 - abar_t) * noise。"""
        if isinstance(t, bool) or not isinstance(t, int):
            raise TypeError("DDPM.q_sample: t 必须是整数")
        if t < 0 or t >= self.steps:
            raise ValueError(f"DDPM.q_sample: 步数 t 必须在 [0, {self.steps})")
        for name, v in (("x0", x0), ("noise", noise)):
            if not isinstance(v, (list, tuple)) or len(v) != self.data_dim:
                raise ValueError(f"DDPM.q_sample: {name} 维度应为 {self.data_dim}")
        a = math.sqrt(self.abar[t])
        b = math.sqrt(1.0 - self.abar[t])
        return [a * x0[i] + b * noise[i] for i in range(self.data_dim)]

    def predict_noise(self, x_t, t):
        inp = self._grid(x_t, t)
        h1 = self.l1.forward(inp)
        h2 = self.l2.forward(h1)
        return self.l3.forward(h2)

    def target(self, x0, noise, t):
        """训练目标：``eps`` 预测噪声、``v`` 预测 ``sqrt(abar)*eps - sqrt(1-abar)*x0``、
        ``x0`` 直接预测原样本"""
        if t < 0 or t >= self.steps:
            raise ValueError(f"DDPM.target: 步数 t 必须在 [0, {self.steps})")
        a = math.sqrt(self.abar[t])
        b = math.sqrt(1.0 - self.abar[t])
        if self.prediction == "eps":
            return list(noise)
        if self.prediction == "v":
            return [a * noise[i] - b * x0[i] for i in range(self.data_dim)]
        return list(x0)

    def min_snr_weight(self, t, gamma: float = 5.0):
        """min-SNR 损失权重 ``min(SNR, gamma) / SNR``（eps 预测）；``x0`` 预测用互补形式"""
        if t < 0 or t >= self.steps:
            raise ValueError(f"DDPM.min_snr_weight: 步数 t 必须在 [0, {self.steps})")
        if isinstance(gamma, bool) or not isinstance(gamma, (int, float)):
            raise ValueError("DDPM.min_snr_weight: gamma 必须是数字")
        gamma = float(gamma)
        if not gamma > 0.0:
            raise ValueError("DDPM.min_snr_weight: gamma 必须 > 0")
        ab = self.abar[t]
        snr = ab / max(1e-12, 1.0 - ab)
        if self.prediction == "x0":
            # x0 预测的信噪比倒数：低噪声步权重更大
            snr = 1.0 / max(1e-12, snr)
        return min(snr, gamma) / max(1e-12, snr)

    def pred_to_x0_eps(self, pred, x_t, t):
        """把网络输出（按 ``prediction`` 解释）换成 ``(x0, eps)`` 两个量"""
        a = math.sqrt(self.abar[t])
        b = math.sqrt(1.0 - self.abar[t])
        if self.prediction == "eps":
            eps = list(pred)
            x0 = [(x_t[i] - b * eps[i]) / max(1e-12, a) for i in range(self.data_dim)]
            return x0, eps
        if self.prediction == "v":
            x0 = [a * x_t[i] - b * pred[i] for i in range(self.data_dim)]
            eps = [a * pred[i] + b * x_t[i] for i in range(self.data_dim)]
            return x0, eps
        x0 = list(pred)
        eps = [(x_t[i] - a * x0[i]) / max(1e-12, b) for i in range(self.data_dim)]
        return x0, eps

    def train_step(self, x0, rng=None, t=None, noise=None, min_snr_gamma=None):
        """一步训练：随机取 t 与噪声，按 ``prediction`` 求目标并累积梯度。

        `t` / `noise` 显式给出时用于测试（固定随机性做中心差分）。
        ``min_snr_gamma`` 给定时按 min-SNR 加权（eps 预测）。
        """
        if not isinstance(x0, (list, tuple)) or len(x0) != self.data_dim:
            raise ValueError(f"DDPM.train_step: x0 维度应为 {self.data_dim}")
        r = rng or random
        if t is None:
            t = r.randrange(self.steps)
        if noise is None:
            noise = _gauss_vec(self.data_dim, r)
        x_t = self.q_sample(x0, t, noise)
        pred = self.predict_noise(x_t, t)
        tgt = self.target(x0, noise, t)
        n = self.data_dim
        w = 1.0 if min_snr_gamma is None else self.min_snr_weight(
            t, min_snr_gamma)
        loss = w * sum((pred[i] - tgt[i]) ** 2 for i in range(n)) / n
        d_pred = [2.0 * w * (pred[i] - tgt[i]) / n for i in range(n)]
        gw3, gb3, d2 = self.l3.backward(d_pred)
        gw2, gb2, d1 = self.l2.backward(d2)
        gw1, gb1, _ = self.l1.backward(d1)
        self._acc(0, gw1, gb1)
        self._acc(1, gw2, gb2)
        self._acc(2, gw3, gb3)
        return loss

    def fit(self, data, epochs=200, lr=1e-3, seed=None, verbose=False):
        if not data:
            raise ValueError("DDPM.fit: data 不能为空")
        rng = random.Random(seed) if seed is not None else random
        history = []
        for _epoch in range(epochs):
            total = 0.0
            self.zero_grad()
            for x in data:
                total += self.train_step(x, rng=rng)
            for item in self._g:
                if item is None:
                    continue
                gw, gb = item
                for row in gw:
                    for c in range(len(row)):
                        row[c] /= len(data)
                for k in range(len(gb)):
                    gb[k] /= len(data)
            self.adam_step(lr)
            history.append(total / len(data))
        return history

    def adam_step(self, lr=1e-3, b1=0.9, b2=0.999, eps=1e-8):
        self.step_count += 1
        t = self.step_count
        for i, layer in enumerate(self.layers):
            if self._g[i] is None:
                continue
            gw, gb = self._g[i]
            _adam_apply(layer.weights, gw, layer.m_w, layer.v_w, t, lr, b1, b2, eps)
            _adam_apply(layer.biases, gb, layer.m_b, layer.v_b, t, lr, b1, b2, eps)

    def sgd_step(self, lr=1e-2):
        for i, layer in enumerate(self.layers):
            if self._g[i] is None:
                continue
            gw, gb = self._g[i]
            _sgd_apply(layer.weights, gw, lr)
            _sgd_apply(layer.biases, gb, lr)

    def sample(self, n=1, rng=None):
        if isinstance(n, bool) or not isinstance(n, int) or n < 1:
            raise ValueError("DDPM.sample: n 必须是 >= 1 的整数")
        r = rng or random
        out = []
        for _ in range(n):
            x = _gauss_vec(self.data_dim, r)
            for t in range(self.steps - 1, -1, -1):
                _x0_pred, eps_pred = self.pred_to_x0_eps(
                    self.predict_noise(x, t), x, t)
                a = self.alphas[t]
                mean = [(x[i] - (1.0 - a) / math.sqrt(max(1e-12, 1.0 - self.abar[t]))
                         * eps_pred[i]) / math.sqrt(a) for i in range(self.data_dim)]
                if t > 0:
                    sigma = math.sqrt(self.betas[t])
                    z = _gauss_vec(self.data_dim, r)
                    x = [mean[i] + sigma * z[i] for i in range(self.data_dim)]
                else:
                    x = mean
            out.append(x)
        return out

    def ddim_sample(self, n=1, rng=None, steps=None, eta=0.0):
        """DDIM 采样：``eta=0`` 完全确定性，且可以只走 ``steps`` 个时间点的子序列

        更新式：``x_prev = sqrt(abar_prev)*x0_pred
        + sqrt(1-abar_prev-sigma^2)*eps_pred + sigma*z``，
        ``sigma = eta*sqrt((1-abar_prev)/(1-abar_t))*sqrt(1-abar_t/abar_prev)``。
        """
        if isinstance(n, bool) or not isinstance(n, int) or n < 1:
            raise ValueError("DDPM.ddim_sample: n 必须是 >= 1 的整数")
        if isinstance(eta, bool) or not isinstance(eta, (int, float)):
            raise ValueError("DDPM.ddim_sample: eta 必须是数字")
        eta = float(eta)
        if not 0.0 <= eta <= 1.0:
            raise ValueError("DDPM.ddim_sample: eta 必须在 [0, 1]")
        if steps is None:
            seq = list(range(self.steps - 1, -1, -1))
        else:
            if isinstance(steps, bool) or not isinstance(steps, int) or steps < 1:
                raise ValueError("DDPM.ddim_sample: steps 必须是 >= 1 的整数")
            if steps > self.steps:
                raise ValueError("DDPM.ddim_sample: steps 不能超过训练步数")
            # 等距子序列，必须包含 t=0
            seq = sorted({int(round(i * (self.steps - 1) / max(1, steps - 1)))
                          for i in range(steps)}, reverse=True)
        r = rng or random
        out = []
        for _ in range(n):
            x = _gauss_vec(self.data_dim, r)
            for idx, t in enumerate(seq):
                x0_pred, eps_pred = self.pred_to_x0_eps(
                    self.predict_noise(x, t), x, t)
                if idx + 1 < len(seq):
                    t_prev = seq[idx + 1]
                    ab_prev = self.abar[t_prev]
                else:
                    t_prev = -1
                    ab_prev = 1.0
                ab_t = self.abar[t]
                sigma = 0.0
                if eta > 0.0 and t > 0:
                    sigma = eta * math.sqrt(
                        max(0.0, (1.0 - ab_prev) / max(1e-12, 1.0 - ab_t))
                        * max(0.0, 1.0 - ab_t / max(1e-12, ab_prev)))
                dir_coef = math.sqrt(max(0.0, 1.0 - ab_prev - sigma ** 2))
                x = [math.sqrt(ab_prev) * x0_pred[i] + dir_coef * eps_pred[i]
                     for i in range(self.data_dim)]
                if sigma > 0.0:
                    z = _gauss_vec(self.data_dim, r)
                    x = [x[i] + sigma * z[i] for i in range(self.data_dim)]
            out.append(x)
        return out


# ============================================================================
#  EDM / DPM-Solver / Consistency Model 采样器（VE 参数化，纯数值）
# ============================================================================

def _diffusion_sigmas(steps, sigma_min, sigma_max, rho=7.0):
    """EDM 的 sigma 调度：对数间隔 + rho 弯曲，返回 [sigma_max, ..., sigma_min]。"""
    if isinstance(steps, bool) or not isinstance(steps, int) or steps < 2:
        raise ValueError(f"_diffusion_sigmas: steps 必须是 >= 2 的整数，收到 {steps!r}")
    for name, value in (("sigma_min", sigma_min), ("sigma_max", sigma_max), ("rho", rho)):
        if (not isinstance(value, (int, float)) or isinstance(value, bool)
                or not math.isfinite(value) or value <= 0):
            raise ValueError(f"_diffusion_sigmas: {name} 必须是正有限数，收到 {value!r}")
    if sigma_min >= sigma_max:
        raise ValueError(
            f"_diffusion_sigmas: sigma_min={sigma_min} 必须小于 sigma_max={sigma_max}")
    lo, hi = sigma_min ** (1.0 / rho), sigma_max ** (1.0 / rho)
    sigmas = []
    for i in range(steps):
        s = hi + (lo - hi) * i / (steps - 1)
        sigmas.append(s ** rho)
    sigmas.append(0.0)
    return sigmas


def _diffusion_denoise(denoise_fn, x, sigma, who):
    """调用去噪函数并校验返回向量（x: List[float] → List[float]）。"""
    if not callable(denoise_fn):
        raise ValueError(f"{who}: denoise_fn 必须可调用")
    if not isinstance(x, (list, tuple)) or not x:
        raise ValueError(f"{who}: x 必须是非空向量")
    out = denoise_fn(list(x), float(sigma))
    if not isinstance(out, (list, tuple)) or len(out) != len(x):
        raise ValueError(
            f"{who}: denoise_fn 返回长度 {len(out) if isinstance(out, (list, tuple)) else '?'}"
            f" 与 x 长度 {len(x)} 不一致")
    return [float(v) for v in out]


def _edm_euler_step(x, x0, sigma, sigma_next):
    if sigma <= 0.0:
        return list(x0)
    return [x[i] + (sigma_next - sigma) * (x[i] - x0[i]) / sigma for i in range(len(x))]


def edm_euler_sampler(denoise_fn, x, steps=18, sigma_min=0.002, sigma_max=80.0, rho=7.0):
    """EDM 的一阶 Euler 采样器（VE 参数化）：dx/dsigma = (x - D(x,sigma)) / sigma。"""
    sigmas = _diffusion_sigmas(steps, sigma_min, sigma_max, rho)
    cur = [float(v) for v in x]
    for i in range(steps):
        x0 = _diffusion_denoise(denoise_fn, cur, sigmas[i], "edm_euler_sampler")
        cur = _edm_euler_step(cur, x0, sigmas[i], sigmas[i + 1])
    return cur


def edm_heun_sampler(denoise_fn, x, steps=18, sigma_min=0.002, sigma_max=80.0, rho=7.0):
    """EDM 的二阶 Heun 采样器：Euler 预测 + 端点平均校正。"""
    sigmas = _diffusion_sigmas(steps, sigma_min, sigma_max, rho)
    cur = [float(v) for v in x]
    for i in range(steps):
        sigma, sigma_next = sigmas[i], sigmas[i + 1]
        x0 = _diffusion_denoise(denoise_fn, cur, sigma, "edm_heun_sampler")
        pred = _edm_euler_step(cur, x0, sigma, sigma_next)
        if sigma_next > 0.0:
            x0_next = _diffusion_denoise(denoise_fn, pred, sigma_next, "edm_heun_sampler")
            cur = [cur[j] + (sigma_next - sigma) * 0.5 * (
                (cur[j] - x0[j]) / sigma + (pred[j] - x0_next[j]) / sigma_next)
                for j in range(len(cur))]
        else:
            cur = pred
    return cur


def dpm_solver_sampler(denoise_fn, x, steps=20, sigma_min=0.002, sigma_max=80.0,
                       rho=7.0):
    """DPM-Solver 的一阶指数积分器（VE 参数化）。

    对区间内假设 x0 恒定的 ODE，精确解是
    ``x(sigma_next) = x0 + (sigma_next / sigma) * (x - x0)``；
    本函数就是逐步使用该解的确定性采样器，等价于 DDIM 式指数积分。
    """
    sigmas = _diffusion_sigmas(steps, sigma_min, sigma_max, rho)
    cur = [float(v) for v in x]
    for i in range(steps):
        sigma, sigma_next = sigmas[i], sigmas[i + 1]
        x0 = _diffusion_denoise(denoise_fn, cur, sigma, "dpm_solver_sampler")
        if sigma_next <= 0.0:
            cur = list(x0)
        else:
            ratio = sigma_next / sigma
            cur = [x0[j] + ratio * (cur[j] - x0[j]) for j in range(len(cur))]
    return cur


def consistency_training_loss(student_fn, teacher_fn, x, sigma, sigma_next):
    """一致性蒸馏（CD）的逐样本损失：student(x,sigma) 对齐 teacher 的两步 Euler 目标。"""
    for name, fn in (("student_fn", student_fn), ("teacher_fn", teacher_fn)):
        if not callable(fn):
            raise ValueError(f"consistency_training_loss: {name} 必须可调用")
    if (not isinstance(sigma, (int, float)) or isinstance(sigma, bool)
            or not math.isfinite(sigma) or sigma <= 0):
        raise ValueError(f"consistency_training_loss: sigma 必须是正有限数，收到 {sigma!r}")
    if (not isinstance(sigma_next, (int, float)) or isinstance(sigma_next, bool)
            or not math.isfinite(sigma_next) or sigma_next < 0 or sigma_next >= sigma):
        raise ValueError(
            f"consistency_training_loss: sigma_next 必须在 [0, sigma) 内，收到 {sigma_next!r}")
    x = [float(v) for v in x]
    pred = _diffusion_denoise(student_fn, x, sigma, "consistency_training_loss")
    teacher_x0 = _diffusion_denoise(teacher_fn, x, sigma, "consistency_training_loss")
    if sigma_next > 0.0:
        ratio = sigma_next / sigma
        x_next = [teacher_x0[j] + ratio * (x[j] - teacher_x0[j]) for j in range(len(x))]
        target = _diffusion_denoise(teacher_fn, x_next, sigma_next,
                                    "consistency_training_loss")
    else:
        target = teacher_x0
    diff = [pred[j] - target[j] for j in range(len(x))]
    return sum(v * v for v in diff) / len(diff)


def consistency_sampler(student_fn, x, steps=8, sigma_min=0.02, sigma_max=80.0,
                        rho=7.0):
    """一致性模型采样：按 sigma 调度逐级用 student 预测 x0 并重新加噪。"""
    if not callable(student_fn):
        raise ValueError("consistency_sampler: student_fn 必须可调用")
    sigmas = _diffusion_sigmas(steps, sigma_min, sigma_max, rho)
    cur = [float(v) for v in x]
    for i in range(steps):
        sigma, sigma_next = sigmas[i], sigmas[i + 1]
        x0 = _diffusion_denoise(student_fn, cur, sigma, "consistency_sampler")
        if sigma_next <= 0.0:
            cur = list(x0)
        else:
            ratio = sigma_next / sigma
            cur = [x0[j] + ratio * (cur[j] - x0[j]) for j in range(len(cur))]
    return cur


# ── 工厂函数

def _flow_time_features(t, dim=8):
    """把连续时间 t∈[0,1] 编成 sin/cos 特征（每个频率一项，低频在前）。

    与 ``_time_features`` 的区别：后者把整数扩散步当成「角度」，这里的输入是
    **连续** 的 t，所以频率按 ``2π * 2^i`` 递增，保证 t=0 与 t=1 的编码差异明显。
    """
    out = []
    for i in range(dim // 2):
        f = 2.0 ** i
        out.append(math.sin(math.pi * f * t))
        out.append(math.cos(math.pi * f * t))
    return out


class FlowMatching:
    """Flow Matching / Rectified Flow（学习速度场 v(x,t)，从噪声沿直线路径走到数据）

    训练路径取最简单的**直线插值**：x_t = (1-t)*x0 + t*noise，目标速度
    ``v* = noise - x0``（constant velocity，对应 Rectified Flow 的 1-rectified 形式）。
    损失是速度的逐维 MSE；采样从 t=1 的噪声出发，用 ``solver`` 指定的积分器
    解 dx/dt = v(x,t) 到 t=0。

    - ``interpolate(x0, noise, t)`` → x_t；``flow_target(x0, noise)`` → noise - x0
    - ``velocity(x_t, t)`` → 网络输出（同时缓存中间量供反向）
    - ``train_step(x0, rng=None, t=None, noise=None)`` → 一步损失并累积梯度
    - ``sample(n=1, steps=20, solver='euler'|'heun', rng=None)``
    - ``fit(data, epochs=200, lr=1e-3, seed=None)``
    """

    def __init__(self, data_dim: int, hidden_dim: int = 32, t_dim: int = 8):
        for name, value in (("data_dim", data_dim), ("hidden_dim", hidden_dim),
                            ("t_dim", t_dim)):
            if isinstance(value, bool) or not isinstance(value, int) or value < 1:
                raise ValueError(f"FlowMatching: {name} 必须是 >= 1 的整数")
        self.data_dim = data_dim
        self.hidden_dim = hidden_dim
        self.t_dim = t_dim if t_dim % 2 == 0 else t_dim + 1
        self.l1 = Layer(data_dim + self.t_dim, hidden_dim, activation="relu")
        self.l2 = Layer(hidden_dim, hidden_dim, activation="relu")
        self.l3 = Layer(hidden_dim, data_dim, activation="linear")
        self.layers = [self.l1, self.l2, self.l3]
        self.step_count = 0
        self.zero_grad()

    # ---------- 梯度缓冲 ----------
    def zero_grad(self):
        self._g = [None] * len(self.layers)

    def _acc(self, i, gw, gb):
        if self._g[i] is None:
            self._g[i] = [gw, gb]
            return
        cur_w, cur_b = self._g[i]
        for r in range(len(cur_w)):
            for c in range(len(cur_w[r])):
                cur_w[r][c] += gw[r][c]
        for k in range(len(cur_b)):
            cur_b[k] += gb[k]

    # ---------- 校验 ----------
    def _check_vec(self, v, name, who):
        if not isinstance(v, (list, tuple)) or len(v) != self.data_dim:
            raise ValueError(f"{who}: {name} 维度应为 {self.data_dim}")
        return list(v)

    @staticmethod
    def _check_t(t, who):
        if isinstance(t, bool) or not isinstance(t, (int, float)):
            raise TypeError(f"{who}: t 必须是数字")
        if not 0.0 <= float(t) <= 1.0:
            raise ValueError(f"{who}: t 必须在 [0, 1] 内，收到 {t!r}")
        return float(t)

    # ---------- 路径与目标 ----------
    def interpolate(self, x0, noise, t):
        """直线插值：x_t = (1-t)*x0 + t*noise（t=0 是数据、t=1 是噪声）"""
        x0 = self._check_vec(x0, "x0", "FlowMatching.interpolate")
        noise = self._check_vec(noise, "noise", "FlowMatching.interpolate")
        t = self._check_t(t, "FlowMatching.interpolate")
        return [(1.0 - t) * x0[i] + t * noise[i] for i in range(self.data_dim)]

    def flow_target(self, x0, noise):
        """目标速度 v* = noise - x0（直线路径的导数，与 t 无关）"""
        x0 = self._check_vec(x0, "x0", "FlowMatching.flow_target")
        noise = self._check_vec(noise, "noise", "FlowMatching.flow_target")
        return [noise[i] - x0[i] for i in range(self.data_dim)]

    # ---------- 前向 ----------
    def velocity(self, x_t, t):
        """网络预测的速度场（缓存供反向用）"""
        x_t = self._check_vec(x_t, "x_t", "FlowMatching.velocity")
        t = self._check_t(t, "FlowMatching.velocity")
        feat = x_t + _flow_time_features(t, self.t_dim)
        h1 = self.l1.forward(feat)
        h2 = self.l2.forward(h1)
        out = self.l3.forward(h2)
        self._t = t
        return out

    # ---------- 训练 ----------
    def train_step(self, x0, rng=None, t=None, noise=None):
        """一步训练：随机取 t 与噪声，回归速度场，累积梯度并返回 MSE"""
        x0 = self._check_vec(x0, "x0", "FlowMatching.train_step")
        r = rng or random
        if t is None:
            t = r.random()
        t = self._check_t(t, "FlowMatching.train_step")
        if noise is None:
            noise = _gauss_vec(self.data_dim, r)
        noise = self._check_vec(noise, "noise", "FlowMatching.train_step")
        x_t = self.interpolate(x0, noise, t)
        pred = self.velocity(x_t, t)
        tgt = self.flow_target(x0, noise)
        n = self.data_dim
        loss = sum((pred[i] - tgt[i]) ** 2 for i in range(n)) / n
        d_pred = [2.0 * (pred[i] - tgt[i]) / n for i in range(n)]
        gw3, gb3, d2 = self.l3.backward(d_pred)
        gw2, gb2, d1 = self.l2.backward(d2)
        gw1, gb1, _ = self.l1.backward(d1)
        self._acc(0, gw1, gb1)
        self._acc(1, gw2, gb2)
        self._acc(2, gw3, gb3)
        return loss

    def fit(self, data, epochs=200, lr=1e-3, seed=None, verbose=False):
        if not data:
            raise ValueError("FlowMatching.fit: data 不能为空")
        for row in data:
            self._check_vec(row, "data 行", "FlowMatching.fit")
        rng = random.Random(seed) if seed is not None else random
        history = []
        for _epoch in range(epochs):
            total = 0.0
            self.zero_grad()
            for x in data:
                total += self.train_step(x, rng=rng)
            for item in self._g:
                if item is None:
                    continue
                gw, gb = item
                for row in gw:
                    for c in range(len(row)):
                        row[c] /= len(data)
                for k in range(len(gb)):
                    gb[k] /= len(data)
            self.adam_step(lr)
            history.append(total / len(data))
        return history

    # ---------- 优化器 ----------
    def adam_step(self, lr=1e-3, b1=0.9, b2=0.999, eps=1e-8):
        _check_adam_betas(b1, b2, "FlowMatching.adam_step")
        if isinstance(eps, bool) or not isinstance(eps, (int, float)) or eps <= 0:
            raise ValueError("FlowMatching.adam_step: eps 必须是 > 0 的数")
        self.step_count += 1
        t = self.step_count
        for i, layer in enumerate(self.layers):
            if self._g[i] is None:
                continue
            gw, gb = self._g[i]
            _adam_apply(layer.weights, gw, layer.m_w, layer.v_w, t, lr, b1, b2, eps)
            _adam_apply(layer.biases, gb, layer.m_b, layer.v_b, t, lr, b1, b2, eps)

    def sgd_step(self, lr=1e-2):
        for i, layer in enumerate(self.layers):
            if self._g[i] is None:
                continue
            gw, gb = self._g[i]
            _sgd_apply(layer.weights, gw, lr)
            _sgd_apply(layer.biases, gb, lr)

    # ---------- 采样 ----------
    def sample(self, n=1, steps=20, solver="euler", rng=None):
        """从 t=1 的噪声积分到 t=0；``solver='heun'`` 是二阶（RK2）"""
        if isinstance(n, bool) or not isinstance(n, int) or n < 1:
            raise ValueError("FlowMatching.sample: n 必须是 >= 1 的整数")
        if isinstance(steps, bool) or not isinstance(steps, int) or steps < 1:
            raise ValueError("FlowMatching.sample: steps 必须是 >= 1 的整数")
        if solver not in ("euler", "heun"):
            raise ValueError("FlowMatching.sample: solver 只能是 'euler' 或 'heun'，"
                             f"收到 {solver!r}")
        r = rng or random
        dt = 1.0 / steps
        out = []
        for _ in range(n):
            x = _gauss_vec(self.data_dim, r)
            for k in range(steps):
                t = 1.0 - k * dt
                v1 = self.velocity(x, t)
                if solver == "euler":
                    x = [x[i] - dt * v1[i] for i in range(self.data_dim)]
                else:
                    mid = [x[i] - dt * v1[i] for i in range(self.data_dim)]
                    v2 = self.velocity(mid, max(0.0, t - dt))
                    x = [x[i] - 0.5 * dt * (v1[i] + v2[i])
                         for i in range(self.data_dim)]
            out.append(x)
        return out


def distill(teacher, student, x, y, epochs=400, batch_size=16,
            val_split=0.1, patience=50, verbose=True):
    """蒸馏：让 student 去拟合 teacher 的输出（软目标）

    与 C 引擎 ai_cli 的 distill 子命令同一套做法：先用教师生成软目标，再训练学生。
    返回 (student, 与教师的一致率)。分类按类别一致率算，回归按误差 <= 1e-2 判定。

    用法:
        teacher = make_regressor(1, 1, hidden_layers=(16, 16)); teacher.fit(x, y)
        student = make_regressor(1, 1, hidden_layers=(4,))
        student, agree = distill(teacher, student, x, y)
    """
    cls = getattr(teacher, 'task', 'regression') == 'classification'
    if cls:
        # 用教师的**软输出**（概率分布）当目标：argmax 硬标签会丢掉教师的不确定性，
        # 与 README 里「用教师输出当软目标」的描述也不一致
        soft_y = teacher.predict(x)                   # list[list] 概率分布
        student.fit(x, soft_y, epochs=epochs, batch_size=batch_size,
                    val_split=val_split, patience=patience, verbose=False)
        agree = sum(1 for xi, yi in zip(x, soft_y)
                    if student.predict_classes([xi])[0]
                    == max(range(len(yi)), key=lambda i: yi[i]))
    else:
        soft_y = teacher.predict(x)                  # 多样本 -> list[list]
        student.fit(x, soft_y, epochs=epochs, batch_size=batch_size,
                    val_split=val_split, patience=patience, verbose=False)
        agree = sum(1 for xi, yi in zip(x, soft_y)
                    if max(abs(a - b) for a, b in
                           zip(student.predict([xi])[0], yi)) <= 1e-2)

    rate = agree / len(x) if x else 0.0
    if verbose:
        print(f"蒸馏完成: 教师 {teacher.model.param_count()} 参数 -> "
              f"学生 {student.model.param_count()} 参数，与教师一致率 {rate * 100:.1f}%")
    return student, rate


def make_classifier(input_dim, num_classes, hidden_layers=(32,),
                    act='leaky_relu', lr=0.01, optimizer='adam',
                    opt_kwargs=None):
    """
    快速创建分类模型（Softmax + CrossEntropy）。

    用法:
        model = make_classifier(input_dim=10, num_classes=5, hidden_layers=(64, 32))
        model.fit(x, y, epochs=200)
        print(model.score(x_test, y_test))  # 准确率
    """
    sizes = [input_dim] + list(hidden_layers) + [num_classes]
    activations = [act] * (len(sizes) - 2) + ['softmax']
    mlp = MLP(sizes, activations=activations)
    return Model(mlp, loss_fn='cross_entropy', optimizer=optimizer,
                 lr=lr, opt_kwargs=opt_kwargs, task='classification')


def make_regressor(input_dim, output_dim=1, hidden_layers=(32,),
                   act='leaky_relu', lr=0.01, optimizer='adam',
                   opt_kwargs=None):
    """
    快速创建回归模型（MSE）。

    用法:
        model = make_regressor(input_dim=5, output_dim=2, hidden_layers=(64, 32))
        model.fit(x, y, epochs=300)
        print(model.score(x_test, y_test))  # R²
    """
    sizes = [input_dim] + list(hidden_layers) + [output_dim]
    activations = [act] * (len(sizes) - 2) + ['linear']
    mlp = MLP(sizes, activations=activations)
    return Model(mlp, loss_fn='mse', optimizer=optimizer,
                 lr=lr, opt_kwargs=opt_kwargs, task='regression')


_CONFIG_KEYS = frozenset({
    "input_dim", "output_dim", "hidden", "activations", "output_activation", "task",
    "loss", "loss_kwargs", "optimizer", "lr", "opt_kwargs",
    "epochs", "batch_size", "val_split", "patience", "seed", "shuffle",
    "grad_clip", "grad_accum", "restore_best_weights", "verbose",
    "lr_scheduler", "checkpoint_path", "checkpoint_every",
})

_SCHEDULER_KEYS = frozenset({
    "type", "step_size", "gamma", "t_max", "eta_min",
    "warmup_epochs", "start_factor", "base_scheduler",
    "factor", "patience", "min_lr", "mode", "threshold", "max_reductions",
})


def _config_mapping(config, who):
    if isinstance(config, str):
        with io.open(config, "r", encoding="utf-8") as f:
            config = json.load(f)
    if not isinstance(config, dict):
        raise TypeError(f"{who}: 配置必须是 dict 或 JSON 文件路径")
    unknown = sorted(set(config) - _CONFIG_KEYS)
    if unknown:
        raise ValueError(
            f"{who}: 不认识的配置项 {unknown}；可用项见 AI._CONFIG_KEYS")
    return dict(config)


def _config_int(config, key, default, minimum=None, who="config"):
    value = config.get(key, default)
    if value is None:
        value = default
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{who}: {key} 必须是 int，收到 {value!r}")
    if minimum is not None and value < minimum:
        raise ValueError(f"{who}: {key} 必须 >= {minimum}，收到 {value}")
    return value


def _config_number(config, key, default, who="config"):
    value = config.get(key, default)
    if value is None:
        value = default
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"{who}: {key} 必须是数字，收到 {value!r}")
    if not math.isfinite(value):
        raise ValueError(f"{who}: {key} 必须是有限数，收到 {value!r}")
    return float(value)


def _config_bool(config, key, default, who="config"):
    value = config.get(key, default)
    if isinstance(value, bool):
        return value
    raise TypeError(f"{who}: {key} 必须是 bool，收到 {value!r}")


def _build_scheduler(spec, optimizer, who="config"):
    """把 {"type": "step", ...} 这样的描述变成调度器对象。"""
    if spec is None:
        return None
    if not isinstance(spec, dict):
        raise TypeError(f"{who}: lr_scheduler 必须是 dict 或 None")
    unknown = sorted(set(spec) - _SCHEDULER_KEYS)
    if unknown:
        raise ValueError(f"{who}: lr_scheduler 里有不认识的键 {unknown}")
    kind = spec.get("type")
    if not isinstance(kind, str):
        raise TypeError(f"{who}: lr_scheduler.type 必须是字符串")
    kind = kind.lower()
    if kind == "step":
        return StepLR(optimizer,
                      step_size=_config_int(spec, "step_size", 30, 1, who),
                      gamma=_config_number(spec, "gamma", 0.1, who))
    if kind == "exponential":
        return ExponentialLR(optimizer, gamma=_config_number(spec, "gamma", 0.99, who))
    if kind == "cosine":
        return CosineAnnealingLR(optimizer,
                                 T_max=_config_int(spec, "t_max", 10, 1, who),
                                 eta_min=_config_number(spec, "eta_min", 0.0, who))
    if kind == "warmup":
        base_spec = spec.get("base_scheduler")
        base = None
        if base_spec is not None:
            if not isinstance(base_spec, dict):
                raise TypeError(f"{who}: warmup.base_scheduler 必须是 dict 或 None")
            base = _build_scheduler(base_spec, optimizer, who)
        return WarmupLR(optimizer,
                        warmup_epochs=_config_int(spec, "warmup_epochs", 5, 1, who),
                        start_factor=_config_number(spec, "start_factor", 0.0, who),
                        base_scheduler=base)
    if kind == "plateau":
        return ReduceLROnPlateau(optimizer,
                                 factor=_config_number(spec, "factor", 0.5, who),
                                 patience=_config_int(spec, "patience", 10, 0, who),
                                 min_lr=_config_number(spec, "min_lr", 0.0, who),
                                 mode=spec.get("mode", "min"),
                                 threshold=_config_number(spec, "threshold", 1e-4, who),
                                 max_reductions=spec.get("max_reductions"))
    raise ValueError(
        f"{who}: 未知的 lr_scheduler.type {kind!r}（可选 step / exponential / cosine / warmup / plateau）")


def _infer_dims(data):
    """从 [(x, y), ...] 推断输入/输出维度。"""
    if not isinstance(data, (list, tuple)) or not data:
        raise ValueError("build_model: 没有给 input_dim/output_dim 时必须提供非空 data")
    first = data[0]
    if not isinstance(first, (list, tuple)) or len(first) != 2:
        raise ValueError("build_model: data 的每个样本必须是 (x, y)")
    x, y = first
    x = x if isinstance(x, (list, tuple)) else [x]
    y = y if isinstance(y, (list, tuple)) else [y]
    if not x or not y:
        raise ValueError("build_model: 样本的 x / y 不能为空")
    return len(x), len(y)


def build_model(config, data=None):
    """按配置字典（或 JSON 文件路径）建一个 `Model`。

    必需：`input_dim` / `output_dim`（也可以给 `data` 让函数推断）。
    `hidden` 缺省 `[16]`；`activations` 缺省全部 `relu`；
    `output_activation` 缺省按 `task` 取（分类 softmax、回归 linear）。
    """
    cfg = _config_mapping(config, "build_model")
    in_dim, out_dim = cfg.get("input_dim"), cfg.get("output_dim")
    if in_dim is None or out_dim is None:
        guessed_in, guessed_out = _infer_dims(data)
        in_dim = guessed_in if in_dim is None else in_dim
        out_dim = guessed_out if out_dim is None else out_dim
    in_dim = _config_int({"v": in_dim}, "v", 1, 1, "build_model")
    out_dim = _config_int({"v": out_dim}, "v", 1, 1, "build_model")

    hidden = cfg.get("hidden", [16])
    if not isinstance(hidden, (list, tuple)):
        raise TypeError("build_model: hidden 必须是 list")
    if not hidden:
        raise ValueError("build_model: hidden 不能为空（至少一层隐藏层）")
    hidden = [_config_int({"h": h}, "h", 1, 1, "build_model") for h in hidden]

    task = cfg.get("task", "auto")
    if task not in ("auto", "regression", "classification"):
        raise ValueError(f"build_model: task 只能是 auto/regression/classification，收到 {task!r}")
    if task == "auto":
        task = "classification" if out_dim > 1 else "regression"

    default_out = "softmax" if task == "classification" else "linear"
    out_act = cfg.get("output_activation", default_out)

    n_hidden = len(hidden)
    activations = cfg.get("activations")
    if activations is None:
        activations = ["relu"] * n_hidden
    if not isinstance(activations, (list, tuple)):
        raise TypeError("build_model: activations 必须是 list")
    if len(activations) != n_hidden:
        raise ValueError(
            f"build_model: activations 有 {len(activations)} 项，但 hidden 有 {n_hidden} 层")
    activations = list(activations) + [out_act]

    mlp = MLP([in_dim] + hidden + [out_dim], activations=activations)
    return Model(
        mlp,
        loss_fn=cfg.get("loss"),
        optimizer=cfg.get("optimizer", "adam"),
        lr=_config_number(cfg, "lr", 0.01, "build_model"),
        opt_kwargs=cfg.get("opt_kwargs"),
        task=task,
        loss_kwargs=cfg.get("loss_kwargs"),
    )


def train_from_config(config, data=None, x=None, y=None, verbose=None):
    """按配置建模型并训练，返回训练好的 `Model`（`model.history` 里有曲线）。

    `data` 与 `x`/`y` 二选一；给了 `data` 时若配置里没有维度就自动推断。
    `verbose` 不传时用配置里的 `verbose`（缺省 True）。
    """
    cfg = _config_mapping(config, "train_from_config")
    if data is not None and (x is not None or y is not None):
        raise ValueError("train_from_config: data 与 x/y 不能同时给")

    seed = cfg.get("seed")
    if seed is not None:
        # 与 quick_train 一致：seed 同时固定初始化与打乱，
        # 且只在初始化期间临时改全局 random，之后原样恢复。
        _saved_state = random.getstate()
        try:
            random.seed(seed)
            model = build_model(cfg, data=data)
        finally:
            random.setstate(_saved_state)
    else:
        model = build_model(cfg, data=data)

    if verbose is None:
        verbose = cfg.get("verbose", True)
    if not isinstance(verbose, bool):
        raise TypeError("train_from_config: verbose 必须是 bool")

    scheduler = _build_scheduler(cfg.get("lr_scheduler"), model.optimizer,
                                 "train_from_config")

    fit_kwargs = dict(
        epochs=_config_int(cfg, "epochs", 100, 0, "train_from_config"),
        batch_size=_config_int(cfg, "batch_size", 32, 1, "train_from_config"),
        patience=_config_int(cfg, "patience", 50, 0, "train_from_config"),
        grad_accum=_config_int(cfg, "grad_accum", 1, 1, "train_from_config"),
        shuffle=_config_bool(cfg, "shuffle", True, "train_from_config"),
        restore_best_weights=_config_bool(cfg, "restore_best_weights", False,
                                          "train_from_config"),
        verbose=verbose,
        lr_scheduler=scheduler,
        checkpoint_path=cfg.get("checkpoint_path"),
        checkpoint_every=_config_int(cfg, "checkpoint_every", 1, 1, "train_from_config"),
        seed=seed,
    )
    if cfg.get("val_split") is not None:
        fit_kwargs["val_split"] = _config_number(cfg, "val_split", 0.1, "train_from_config")
    if cfg.get("grad_clip") is not None:
        fit_kwargs["grad_clip"] = _config_number(cfg, "grad_clip", 0.0, "train_from_config")

    if data is not None:
        model.fit(data=data, **fit_kwargs)
    else:
        if x is None or y is None:
            raise ValueError("train_from_config: 必须给 data 或同时给 x 和 y")
        model.fit(x=x, y=y, **fit_kwargs)
    return model


_SEARCH_METRICS = {
    "val_loss": "min", "train_loss": "min", "grad_norm": "min",
    "accuracy": "max",
}


def _search_score(model, metric, x, y):
    """按指标名从训练结果里取分；accuracy 需要 x/y。"""
    hist = model.history
    if metric in ("val_loss", "train_loss", "grad_norm"):
        if metric == "val_loss" and not hist.get("val_loss"):
            raise ValueError(
                "hyperparameter_search: 配置里没有验证集（val_split=0），无法用 val_loss 评分")
        series = hist.get(metric) or []
        if not series:
            raise ValueError(f"hyperparameter_search: history 里没有 {metric}")
        return float(series[-1][1] if isinstance(series[-1], tuple) else series[-1])
    if metric == "accuracy":
        if x is None or y is None:
            raise ValueError("hyperparameter_search: 用 accuracy 评分时必须提供 x 和 y")
        preds = []
        for xi in x:
            out = model.predict(xi)
            out = out if isinstance(out, (list, tuple)) else [out]
            preds.append(max(range(len(out)), key=lambda k: out[k]) if len(out) > 1
                         else (1 if out[0] > 0.5 else 0))
        truth = []
        for yi in y:
            if isinstance(yi, (list, tuple)):
                truth.append(max(range(len(yi)), key=lambda k: yi[k]))
            elif isinstance(yi, bool):
                truth.append(1 if yi else 0)
            else:
                truth.append(int(yi))
        hit = sum(1 for p, t in zip(preds, truth) if p == t)
        return hit / max(1, len(truth))
    raise ValueError(f"hyperparameter_search: 未知指标 {metric!r}")


def hyperparameter_search(base_config, grid, data=None, x=None, y=None,
                          method="grid", n_trials=16, metric="val_loss",
                          seed=None, verbose=False):
    """在配置空间里搜超参，返回最优配置与全部试验记录。

    base_config: 基础配置（同 `train_from_config`），必须含维度或给 `data`。
    grid:        {参数名: [候选值, ...]}，参数名必须是合法配置项。
    method:      "grid" 全组合；"random" 随机抽 `n_trials` 组（去重后不足则按顺序补）。
    metric:      "val_loss" / "train_loss" / "grad_norm"（越小越好）或 "accuracy"（越大越好）。
    seed:        随机搜索与训练共用的种子；给了就整轮可复现。

    返回 {"best": {...}, "trials": [...], "metric", "mode", "params_names"}。
    每次试验都用 `train_from_config` 训练，`verbose` 默认关掉以免刷屏。
    """
    if not isinstance(grid, dict) or not grid:
        raise ValueError("hyperparameter_search: grid 必须是非空 dict")
    base = _config_mapping(base_config, "hyperparameter_search")
    unknown = sorted(set(grid) - _CONFIG_KEYS)
    if unknown:
        raise ValueError(f"hyperparameter_search: grid 里有不认识的配置项 {unknown}")
    values = {}
    for key, options in grid.items():
        if not isinstance(options, (list, tuple)) or not options:
            raise ValueError(f"hyperparameter_search: grid[{key!r}] 必须是非空 list")
        values[key] = list(options)
    if method not in ("grid", "random"):
        raise ValueError(f"hyperparameter_search: method 只能是 grid/random，收到 {method!r}")
    if isinstance(n_trials, bool) or not isinstance(n_trials, int) or n_trials < 1:
        raise ValueError(f"hyperparameter_search: n_trials 必须是 >= 1 的 int")
    if metric not in _SEARCH_METRICS:
        raise ValueError(
            f"hyperparameter_search: 未知指标 {metric!r}（可选 {sorted(_SEARCH_METRICS)}）")
    mode = _SEARCH_METRICS[metric]

    keys = list(values)
    if method == "grid":
        combos = [dict(zip(keys, picks)) for picks in itertools.product(*(values[k] for k in keys))]
    else:
        rng = random.Random(seed) if seed is not None else random
        seen = set()
        combos = []
        while len(combos) < n_trials:
            picks = tuple(rng.choice(values[k]) for k in keys)
            if picks in seen:
                if len(seen) >= len(list(itertools.product(*(values[k] for k in keys)))):
                    break
                continue
            seen.add(picks)
            combos.append(dict(zip(keys, picks)))

    trials = []
    best = None
    for trial_no, combo in enumerate(combos):
        cfg = dict(base)
        cfg.update(combo)
        model = train_from_config(cfg, data=data, x=x, y=y, verbose=verbose)
        score = _search_score(model, metric, x, y)
        item = {"trial": trial_no, "params": dict(combo), "score": score,
                "history": model.history}
        trials.append(item)
        if best is None or (score < best["score"] if mode == "min" else score > best["score"]):
            best = item
    return {"best": best, "trials": trials, "metric": metric, "mode": mode,
            "params_names": keys}


def _hpo_check_space(space, who):
    """校验 TPE 空间描述并归一化成内部结构。"""
    if not isinstance(space, dict) or not space:
        raise ValueError(f"{who}: space 必须是非空 dict")
    specs = {}
    for name, spec in space.items():
        if not isinstance(name, str) or not name:
            raise ValueError(f"{who}: 参数名必须是非空字符串")
        if not isinstance(spec, dict):
            raise ValueError(f"{who}: space[{name!r}] 必须是 dict")
        kind = spec.get("type")
        if kind == "float":
            low, high = spec.get("low"), spec.get("high")
            for tag, v in (("low", low), ("high", high)):
                if isinstance(v, bool) or not isinstance(v, (int, float)):
                    raise ValueError(f"{who}: space[{name!r}].{tag} 必须是数字")
                if v != v or v in (float("inf"), float("-inf")):
                    raise ValueError(f"{who}: space[{name!r}].{tag} 必须是有限数")
            if float(low) >= float(high):
                raise ValueError(f"{who}: space[{name!r}] 的 low 必须小于 high")
            is_log = bool(spec.get("log", False))
            if is_log and float(low) <= 0.0:
                raise ValueError(f"{who}: space[{name!r}] 取 log 时 low 必须 > 0")
            specs[name] = {"type": "float", "low": float(low), "high": float(high),
                           "log": is_log}
        elif kind == "int":
            low, high = spec.get("low"), spec.get("high")
            for tag, v in (("low", low), ("high", high)):
                if isinstance(v, bool) or not isinstance(v, int):
                    raise ValueError(f"{who}: space[{name!r}].{tag} 必须是 int")
            if int(low) >= int(high):
                raise ValueError(f"{who}: space[{name!r}] 的 low 必须小于 high")
            specs[name] = {"type": "int", "low": int(low), "high": int(high)}
        elif kind == "choice":
            values = spec.get("values")
            if not isinstance(values, (list, tuple)) or not values:
                raise ValueError(f"{who}: space[{name!r}].values 必须是非空列表")
            if len(set(values)) != len(values):
                raise ValueError(f"{who}: space[{name!r}].values 不能有重复值")
            specs[name] = {"type": "choice", "values": list(values)}
        else:
            raise ValueError(
                f"{who}: space[{name!r}].type 只能是 float/int/choice，收到 {kind!r}")
    return specs


def _hpo_sample(specs, rng):
    """从空间里随机采一组参数。"""
    params = {}
    for name, spec in specs.items():
        if spec["type"] == "float":
            if spec["log"]:
                params[name] = math.exp(rng.uniform(math.log(spec["low"]),
                                                    math.log(spec["high"])))
            else:
                params[name] = rng.uniform(spec["low"], spec["high"])
        elif spec["type"] == "int":
            params[name] = rng.randint(spec["low"], spec["high"])
        else:
            params[name] = rng.choice(spec["values"])
    return params


def _hpo_encode(specs, params):
    """把参数编码成 [0,1] 数值向量 + 类别取值（供 TPE 密度估计）。"""
    vec = []
    cats = {}
    for name, spec in specs.items():
        value = params[name]
        if spec["type"] == "float":
            if spec["log"]:
                lo, hi = math.log(spec["low"]), math.log(spec["high"])
                vec.append((math.log(value) - lo) / (hi - lo))
            else:
                vec.append((value - spec["low"]) / (spec["high"] - spec["low"]))
        elif spec["type"] == "int":
            vec.append((value - spec["low"]) / float(spec["high"] - spec["low"]))
        else:
            cats[name] = value
    return vec, cats


def _hpo_gauss(x, mu, bw):
    """一维高斯（截断由调用方处理），bw 是标准差。"""
    z = (x - mu) / bw
    return math.exp(-0.5 * z * z) / (bw * math.sqrt(2.0 * math.pi))


def _hpo_cat_prob(spec, values, counts, value):
    """类别参数的拉普拉斯平滑频率。"""
    k = len(spec["values"])
    return (counts.get(value, 0) + 1.0) / (sum(counts.values()) + k)


def tpe_search(objective, space, n_trials=30, n_startup=10, gamma=0.25,
               maximize=False, seed=None):
    """TPE（Tree-structured Parzen Estimator）超参搜索。

    space 的项是 {"type": "float", "low": .., "high": .., "log": bool}
    / {"type": "int", "low": .., "high": ..} / {"type": "choice", "values": [...]}。
    objective(params) -> float 的评分（默认越小越好，maximize=True 时越大越好）。
    前 n_startup 次均匀随机；之后用「好组/差组」的截断高斯与类别频率构造
    密度 l(x)/g(x)，在从好组派生的候选里挑 g/l 比值最大的点继续采样。
    返回 {"best": {...}, "best_score": float, "trials": [{"params","score"}...],
    "mode": "max"/"min", "n_trials": n}。
    """
    who = "tpe_search"
    if not callable(objective):
        raise ValueError(f"{who}: objective 必须可调用")
    specs = _hpo_check_space(space, who)
    for tag, v in (("n_trials", n_trials), ("n_startup", n_startup)):
        if isinstance(v, bool) or not isinstance(v, int) or v < 1:
            raise ValueError(f"{who}: {tag} 必须是 >= 1 的 int")
    if n_startup > n_trials:
        raise ValueError(f"{who}: n_startup 不能大于 n_trials")
    if isinstance(gamma, bool) or not isinstance(gamma, (int, float)):
        raise ValueError(f"{who}: gamma 必须是数字")
    gamma = float(gamma)
    if not 0.0 < gamma < 1.0:
        raise ValueError(f"{who}: gamma 必须在 (0, 1)")
    if isinstance(seed, bool) or (seed is not None and not isinstance(seed, int)):
        raise ValueError(f"{who}: seed 必须是 int 或 None")
    rng = random.Random(seed) if seed is not None else random
    sign = -1.0 if maximize else 1.0

    trials = []
    encoded = []
    for _ in range(n_startup):
        params = _hpo_sample(specs, rng)
        score = float(objective(dict(params)))
        trials.append({"params": params, "score": score})
        encoded.append(_hpo_encode(specs, params))

    n_dims = len(encoded[0][0]) if encoded else 0
    while len(trials) < n_trials:
        order = sorted(range(len(trials)),
                       key=lambda i: sign * trials[i]["score"])
        n_good = max(1, int(math.ceil(gamma * len(order))))
        good_idx = order[:n_good]
        bad_idx = order[n_good:]
        if not bad_idx:
            bad_idx = good_idx
        good_vecs = [encoded[i][0] for i in good_idx]
        bad_vecs = [encoded[i][0] for i in bad_idx]
        bw = max(0.05, 1.0 / math.sqrt(len(good_idx) + 1))
        cat_counts = {}
        for name, spec in specs.items():
            if spec["type"] != "choice":
                continue
            counts = {}
            for i in good_idx:
                value = encoded[i][1].get(name)
                counts[value] = counts.get(value, 0) + 1
            cat_counts[name] = counts
        best_candidate = None
        best_ratio = -1.0
        num_names = [name for name, spec in specs.items() if spec["type"] != "choice"]
        for _ in range(24):
            pick = good_idx[rng.randrange(len(good_idx))]
            position = good_idx.index(pick)
            params = {}
            for name, spec in specs.items():
                if spec["type"] == "choice":
                    counts = cat_counts[name]
                    if rng.random() < 0.2:
                        params[name] = rng.choice(spec["values"])
                    else:
                        weights = [_hpo_cat_prob(spec, spec["values"], counts, v)
                                   for v in spec["values"]]
                        total = sum(weights)
                        r = rng.random() * total
                        acc = 0.0
                        for v, w in zip(spec["values"], weights):
                            acc += w
                            if r <= acc:
                                params[name] = v
                                break
                        else:
                            params[name] = spec["values"][-1]
                    continue
                d = num_names.index(name)
                base = good_vecs[position][d]
                v = rng.gauss(base, bw)
                v = min(1.0, max(0.0, v))
                if spec["type"] == "float":
                    if spec["log"]:
                        lo, hi = math.log(spec["low"]), math.log(spec["high"])
                        params[name] = math.exp(lo + v * (hi - lo))
                    else:
                        params[name] = spec["low"] + v * (spec["high"] - spec["low"])
                else:
                    params[name] = int(round(spec["low"] + v * (spec["high"] - spec["low"])))
            score = float(objective(dict(params)))
            # EI（对数域，按 minimization 定义：好组密度大、差组密度小）
            log_l = 0.0
            log_g = 0.0
            vec, catv = _hpo_encode(specs, params)
            for d in range(len(vec)):
                l_d = sum(_hpo_gauss(vec[d], g[d], bw) for g in good_vecs) / len(good_vecs)
                g_d = sum(_hpo_gauss(vec[d], b[d], bw) for b in bad_vecs) / len(bad_vecs)
                log_l += math.log(max(l_d, 1e-12))
                log_g += math.log(max(g_d, 1e-12))
            for name, spec in specs.items():
                if spec["type"] != "choice":
                    continue
                counts_l = cat_counts[name]
                counts_g = {}
                for i in bad_idx:
                    value = encoded[i][1].get(name)
                    counts_g[value] = counts_g.get(value, 0) + 1
                log_l += math.log(max(_hpo_cat_prob(spec, spec["values"], counts_l,
                                                   catv[name]), 1e-12))
                log_g += math.log(max(_hpo_cat_prob(spec, spec["values"], counts_g,
                                                   catv[name]), 1e-12))
            ratio = log_g - log_l
            if ratio > best_ratio or best_candidate is None:
                best_ratio = ratio
                best_candidate = (params, score)
        trials.append({"params": best_candidate[0], "score": best_candidate[1]})
        encoded.append(_hpo_encode(specs, best_candidate[0]))
    best = min(trials, key=lambda t: sign * t["score"])
    return {"best": dict(best["params"]), "best_score": best["score"],
            "trials": trials, "mode": "max" if maximize else "min",
            "n_trials": n_trials}


def successive_halving(objective, configs, reduction=3, maximize=False, seed=None):
    """逐轮减半（Hyperband 的核心调度）：每轮按 budget 评估剩余配置，
    只保留前 ceil(n/reduction) 名进入下一轮，budget 逐轮乘 reduction。

    objective(config, budget) -> float。返回 {"best": ..., "best_score": ...,
    "rounds": [{"budget": b, "scores": [{"params","score"}...]}...]}。
    """
    who = "successive_halving"
    if not callable(objective):
        raise ValueError(f"{who}: objective 必须可调用")
    if not isinstance(configs, (list, tuple)) or not configs:
        raise ValueError(f"{who}: configs 必须是非空列表")
    if any(not isinstance(c, dict) for c in configs):
        raise ValueError(f"{who}: configs 里每一项都必须是 dict")
    if isinstance(reduction, bool) or not isinstance(reduction, int) or reduction < 2:
        raise ValueError(f"{who}: reduction 必须是 >= 2 的 int")
    if seed is not None and (isinstance(seed, bool) or not isinstance(seed, int)):
        raise ValueError(f"{who}: seed 必须是 int 或 None")
    sign = -1.0 if maximize else 1.0
    survivors = [dict(c) for c in configs]
    rounds = []
    budget = 1
    while True:
        scored = []
        for cfg in survivors:
            score = float(objective(dict(cfg), budget))
            scored.append({"params": dict(cfg), "score": score})
        rounds.append({"budget": budget, "scores": scored})
        if len(scored) <= 1:
            break
        scored.sort(key=lambda item: sign * item["score"])
        keep = max(1, int(math.ceil(len(scored) / float(reduction))))
        if keep <= 1:
            break
        survivors = [dict(item["params"]) for item in scored[:keep]]
        budget *= reduction
    all_scores = [item for rnd in rounds for item in rnd["scores"]]
    best = min(all_scores, key=lambda item: sign * item["score"])
    return {"best": dict(best["params"]), "best_score": best["score"],
            "rounds": rounds,
            "mode": "max" if maximize else "min"}


def quick_train(x, y, task='regression', hidden_layers=(32,), epochs=200,
                batch_size=32, lr=0.01, val_split=0.1, patience=30,
                optimizer='adam', verbose=True, seed=None):
    """
    一行代码训练并返回模型。

    task='classification' 时 y 可以是整数类别索引（允许非连续，如 [0, 2]），
    也可以是 one-hot / 概率向量——类数按向量长度或 max+1 推断，不会因为
    某个类在本批数据里没出现而少建输出单元。小数标签与负索引会直接报错。

    seed: 传整数时，「权重初始化」与「每轮打乱」都用这个种子，同样的调用
          再跑一次得到的模型权重与 loss 曲线完全相同；初始化期间会临时设置
          全局 random 并在结束后恢复，不会推进调用方的随机状态。

    用法:
        model = quick_train(x, y, task='classification', epochs=300)
        model = quick_train(x, y, task='regression', hidden_layers=(64, 32, 16))
    """
    if not x:
        raise ValueError("quick_train: x 不能为空")
    if not y:
        raise ValueError("quick_train: y 不能为空")
    input_dim = len(x[0])

    if task == 'classification':
        # 标签既可以是类别索引 int，也可以是 one-hot / 概率向量；
        # 后者直接 set(y) 会抛 unhashable，这里统一转成索引
        if not y:
            raise ValueError("quick_train: 分类任务的 y 不能为空")
        if isinstance(y[0], (list, tuple)):
            # 类数 = 向量长度（用 len(set(标签)) 会漏掉本批没出现的类）
            num_classes = len(y[0])
            if len({isinstance(v, (list, tuple)) for v in y}) > 1:
                raise ValueError("quick_train: y 中不能混用向量标签与整数标签")
            # 概率 / one-hot 向量原样保留：Model 的 CE 路径会把等长向量直通给
            # cross_entropy_loss 的软标签分支，argmax 硬化会丢掉软标签信息
            y = [list(row) for row in y]
        else:
            if any(isinstance(v, (list, tuple)) for v in y):
                raise ValueError("quick_train: y 中不能混用向量标签与整数标签")
            # 整数标签：类数 = max+1（不能用 len(set(y))：标签 [0,2] 会越界）。
            # 注意不能直接 int(v)：那会把 1.5 静默截成 1、把 -0.5 截成 0，
            # 让非法标签混进训练集。
            labels = []
            for v in y:
                fv = float(v)
                if not fv.is_integer():
                    raise ValueError(
                        f"quick_train: 分类标签必须是整数类别索引，收到 {v!r}"
                    )
                if fv < 0:
                    raise ValueError(f"quick_train: 类别索引不能为负（发现 {fv}）")
                labels.append(int(fv))
            y = labels
            num_classes = max(y) + 1
        build = lambda: make_classifier(input_dim, num_classes,
                                        hidden_layers=hidden_layers, lr=lr,
                                        optimizer=optimizer)
    else:
        output_dim = len(y[0]) if isinstance(y[0], (list, tuple)) else 1
        build = lambda: make_regressor(input_dim, output_dim,
                                       hidden_layers=hidden_layers, lr=lr,
                                       optimizer=optimizer)

    # 权重初始化也吃同一个 seed：临时设置全局 random，构造完立刻恢复原状态
    if seed is not None:
        _saved_state = random.getstate()
        try:
            random.seed(seed)
            model = build()
        finally:
            random.setstate(_saved_state)
    else:
        model = build()

    model.fit(x, y, epochs=epochs, batch_size=batch_size,
              val_split=val_split, patience=patience, verbose=verbose,
              seed=seed)
    return model



# ============================================================================
#  组合模型：LLaMA / ResNet（把现成构件拼成完整网络）
# ============================================================================
# 这两类只做「拼装 + forward/backward 转发」，不重复实现任何子模块：
# LlamaModel 组合 Embedding + LlamaBlock(RMSNorm/MultiHeadAttention/SwiGLU)，
# ResNet 组合 Conv2d/BatchNorm2d/Bottleneck2d/AdaptiveAvgPool2d/Flatten。


class LlamaBlock:
    """LLaMA 解码器块（pre-norm）：

        h1 = RMSNorm1(x)
        x  = x + GQA_Attn(h1)      # 因果 + RoPE（可选）
        h2 = RMSNorm2(x)
        out = x + SwiGLU(h2)

    归一化放在子层之前（pre-norm），归一化用 RMSNorm，FFN 用 SwiGLU——
    与 `TransformerEncoderLayer`（post-norm + LayerNorm + ReLU-FFN）的区别就在这里。
    """

    def __init__(self, d_model: int, num_heads: int, d_ff: int,
                 num_kv_heads: Optional[int] = None, dropout: float = 0.0,
                 rope: bool = True):
        for name, value in (("d_model", d_model), ("d_ff", d_ff)):
            if isinstance(value, bool) or not isinstance(value, int) or value < 1:
                raise ValueError(f"LlamaBlock: {name} 必须是正整数，收到 {value!r}")
        if not isinstance(num_heads, int) or isinstance(num_heads, bool) or num_heads < 1:
            raise ValueError(f"LlamaBlock: num_heads 必须是正整数，收到 {num_heads!r}")
        if d_model % num_heads != 0:
            raise ValueError(
                f"LlamaBlock: d_model={d_model} 必须能被 num_heads={num_heads} 整除")
        self.d_model = d_model
        self.attn = MultiHeadAttention(d_model, num_heads, dropout,
                                       causal=True, rope=rope,
                                       num_kv_heads=num_kv_heads)
        self.ln1 = RMSNorm(d_model)
        self.ln2 = RMSNorm(d_model)
        self.ffn = SwiGLU(d_model, d_ff)
        self._cache = None
        self.zero_grad()

    def zero_grad(self):
        """重置子模块梯度与两个 RMSNorm 的 gamma 梯度"""
        self.attn.zero_grad()
        self.ffn.zero_grad()
        self.grads = {
            "ln1_gamma": [0.0] * self.d_model,
            "ln2_gamma": [0.0] * self.d_model,
        }

    def train(self):
        self.attn.train()
        return self

    def eval(self):
        self.attn.eval()
        return self

    def forward(self, x_seq):
        """x_seq: (T, d_model) → (T, d_model)"""
        if not x_seq:
            raise ValueError("LlamaBlock.forward: 输入序列为空")
        d = self.d_model
        if len(x_seq[0]) != d:
            raise ValueError(
                f"LlamaBlock.forward: 输入维度 {len(x_seq[0])} 与 d_model={d} 不一致")
        seq = [list(row) for row in x_seq]
        h1 = [self.ln1.forward(v) for v in seq]
        attn_out = self.attn.forward(h1)
        res1 = [[seq[t][j] + attn_out[t][j] for j in range(d)]
                for t in range(len(seq))]
        h2 = [self.ln2.forward(v) for v in res1]
        ffn_out = self.ffn.forward(h2)
        res2 = [[res1[t][j] + ffn_out[t][j] for j in range(d)]
                for t in range(len(seq))]
        self._cache = (seq, h1, res1, h2, res2)
        return res2

    def backward(self, dout_seq):
        """dout_seq: (T, d_model) → dx: (T, d_model)"""
        if self._cache is None:
            raise RuntimeError("LlamaBlock.backward: 必须先调用 forward()")
        seq, h1, res1, h2, res2 = self._cache
        T, d = len(seq), self.d_model
        if len(dout_seq) != T or any(len(row) != d for row in dout_seq):
            raise ValueError("LlamaBlock.backward: dout 形状与 forward 输入不一致")

        # ---- FFN 分支：out = res2 的直通 + SwiGLU(ln2(res1))
        d_res1 = [list(row) for row in dout_seq]
        d_h2 = self.ffn.backward(dout_seq)
        g_ln2 = self.grads["ln2_gamma"]
        for t in range(T):
            self.ln2.forward(h2[t])          # 重放该 token 的缓存
            gg, dx = self.ln2.backward(d_h2[t])
            for j in range(d):
                g_ln2[j] += gg[j]
                d_res1[t][j] += dx[j]

        # ---- 注意力分支：res1 的直通 + Attn(ln1(seq))
        d_ln1_out = self.attn.backward(d_res1)
        g_ln1 = self.grads["ln1_gamma"]
        d_x = [list(row) for row in d_res1]
        for t in range(T):
            self.ln1.forward(h1[t])
            gg, dx = self.ln1.backward(d_ln1_out[t])
            for j in range(d):
                g_ln1[j] += gg[j]
                d_x[t][j] += dx[j]
        return d_x


class LlamaModel:
    """完整 LLaMA 式因果语言模型（教学用组合类）

    结构：Embedding → N × LlamaBlock → RMSNorm → 词表头（W_out / b_out）。
    RoPE 由 `MultiHeadAttention(rope=True)` 提供，因此默认不叠加绝对位置编码
    （与 Llama 一致）；GQA 通过 `num_kv_heads` 控制。

    训练接口与 `CausalLM` 对齐：`loss_and_backward` 做 teacher-forcing 交叉熵，
    `fit` / `generate` / `adam_step` 可直接用。参数更新由本类的 adam_step 统一处理。

    用法::

        lm = LlamaModel(vocab_size=8, d_model=16, num_heads=2, d_ff=32,
                        num_layers=2, num_kv_heads=1, max_len=32)
        lm.fit([[0, 1, 2, 3, 0, 1, 2, 3]], epochs=40, lr=0.01)
        lm.generate([0, 1, 2], max_new_tokens=8)
    """

    def __init__(self, vocab_size: int, d_model: int = 32, num_heads: int = 4,
                 d_ff: int = 64, num_layers: int = 2, num_kv_heads: Optional[int] = None,
                 max_len: int = 256, dropout: float = 0.0, rope: bool = True):
        if isinstance(vocab_size, bool) or not isinstance(vocab_size, int) or vocab_size < 1:
            raise ValueError(f"LlamaModel: vocab_size 必须是正整数，收到 {vocab_size!r}")
        if isinstance(max_len, bool) or not isinstance(max_len, int) or max_len < 1:
            raise ValueError(f"LlamaModel: max_len 必须 >= 1，收到 {max_len!r}")
        if isinstance(num_layers, bool) or not isinstance(num_layers, int) or num_layers < 1:
            raise ValueError(f"LlamaModel: num_layers 必须是正整数，收到 {num_layers!r}")
        if isinstance(d_model, bool) or not isinstance(d_model, int) or d_model < 1:
            raise ValueError(f"LlamaModel: d_model 必须是正整数，收到 {d_model!r}")
        if isinstance(num_heads, bool) or not isinstance(num_heads, int) or num_heads < 1:
            raise ValueError(f"LlamaModel: num_heads 必须是正整数，收到 {num_heads!r}")
        if d_model % num_heads != 0:
            raise ValueError(
                f"LlamaModel: d_model={d_model} 必须能被 num_heads={num_heads} 整除")

        self.vocab_size = vocab_size
        self.d_model = d_model
        self.num_heads = num_heads
        self.d_ff = d_ff
        self.num_layers = num_layers
        self.num_kv_heads = num_kv_heads
        self.max_len = max_len
        self.dropout = dropout
        self.rope = bool(rope)

        self.embedding = Embedding(vocab_size, d_model)
        self.blocks = [
            LlamaBlock(d_model, num_heads, d_ff, num_kv_heads=num_kv_heads,
                       dropout=dropout, rope=self.rope)
            for _ in range(num_layers)
        ]
        self.norm = RMSNorm(d_model)
        std = math.sqrt(2.0 / d_model)
        self.W_out = [[random.gauss(0.0, std) for _ in range(d_model)]
                      for _ in range(vocab_size)]
        self.b_out = [0.0] * vocab_size
        self._adam_m = {}
        self._adam_v = {}
        self.step_count = 0
        self._norm_in = None
        self._norm_out = None
        self.zero_grad()

    # ---- 参数 / 梯度 --------------------------------------------------------
    def zero_grad(self):
        self.embedding.zero_grad()
        for block in self.blocks:
            block.zero_grad()
        self.grads = {
            "norm_gamma": [0.0] * self.d_model,
            "W_out": [[0.0] * self.d_model for _ in range(self.vocab_size)],
            "b_out": [0.0] * self.vocab_size,
        }

    def _named_params(self):
        """产出 (名字, 参数, 梯度)；名字用于跨步保持 Adam 的一阶/二阶矩"""
        yield "emb.weight", self.embedding.weight, self.embedding.grad_weight
        for li, block in enumerate(self.blocks):
            attn = block.attn
            for key in ("W_q", "W_k", "W_v", "W_o", "b_q", "b_k", "b_v", "b_o"):
                yield f"L{li}.attn.{key}", getattr(attn, key), attn.grads[key]
            ffn = block.ffn
            for key in ("W1", "b1", "Wg", "bg", "W2", "b2"):
                yield f"L{li}.ffn.{key}", getattr(ffn, key), ffn.grads[key]
            yield f"L{li}.ln1.gamma", block.ln1.gamma, block.grads["ln1_gamma"]
            yield f"L{li}.ln2.gamma", block.ln2.gamma, block.grads["ln2_gamma"]
        yield "norm.gamma", self.norm.gamma, self.grads["norm_gamma"]
        yield "out.W", self.W_out, self.grads["W_out"]
        yield "out.b", self.b_out, self.grads["b_out"]

    def param_count(self):
        def count(p):
            if p and isinstance(p[0], (list, tuple)):
                return sum(len(row) for row in p)
            return len(p)
        return sum(count(p) for _, p, _ in self._named_params())

    def train(self):
        for block in self.blocks:
            block.train()
        return self

    def eval(self):
        for block in self.blocks:
            block.eval()
        return self

    # ---- 前向 / 反向 --------------------------------------------------------
    def forward(self, ids):
        """ids: List[int] → logits (T, vocab_size)（未 softmax）"""
        if not ids:
            raise ValueError("LlamaModel.forward: ids 不能为空")
        if len(ids) > self.max_len:
            raise ValueError(
                f"LlamaModel.forward: 序列长度 {len(ids)} 超过 max_len={self.max_len}")
        emb = self.embedding.forward(ids)
        x = emb
        for block in self.blocks:
            x = block.forward(x)
        self._norm_in = x
        norm_out = [self.norm.forward(v) for v in x]
        self._norm_out = norm_out
        logits = _matmul(norm_out, _transpose(self.W_out))
        for t in range(len(norm_out)):
            row = logits[t]
            for v in range(self.vocab_size):
                row[v] += self.b_out[v]
        return logits

    def _backward_from_logits(self, dlogits):
        """把 logits 的梯度传回所有参数（梯度累加到 self.grads / 子模块 grads）"""
        if self._norm_out is None:
            raise RuntimeError("LlamaModel._backward_from_logits: 必须先调用 forward()")
        T = len(dlogits)
        V = self.vocab_size
        d = self.d_model
        norm_out = self._norm_out

        grad_W = [[sum(dlogits[t][v] * norm_out[t][j] for t in range(T))
                   for j in range(d)] for v in range(V)]
        grad_b = [sum(dlogits[t][v] for t in range(T)) for v in range(V)]
        for v in range(V):
            row = self.grads["W_out"][v]
            for j in range(d):
                row[j] += grad_W[v][j]
            self.grads["b_out"][v] += grad_b[v]

        d_norm = _matmul(dlogits, self.W_out)      # (T, d)
        g_norm = self.grads["norm_gamma"]
        d = []
        for t in range(T):
            self.norm.forward(self._norm_in[t])    # 重放该 token 的缓存
            gg, dx = self.norm.backward(d_norm[t])
            for j in range(self.d_model):
                g_norm[j] += gg[j]
            d.append(dx)

        for block in reversed(self.blocks):
            d = block.backward(d)
        self.embedding.backward(d)

    def loss_and_backward(self, ids, targets=None):
        """teacher-forcing 交叉熵：位置 t 的 logits 预测 ids[t+1]

        targets 省略时用 ids[1:]；给定 targets 时必须长度 = len(ids)-1。
        返回平均 loss（对 T-1 个位置取平均），梯度已累积。
        """
        seq = list(ids)
        if len(seq) < 2:
            raise ValueError("LlamaModel.loss_and_backward: 序列至少需要 2 个 token")
        if targets is None:
            tgt = list(seq[1:])
        else:
            tgt = list(targets)
            if len(tgt) != len(seq) - 1:
                raise ValueError(
                    f"LlamaModel.loss_and_backward: targets 长度 {len(tgt)} "
                    f"应为 {len(seq) - 1}")
        logits = self.forward(seq)
        T = len(seq)
        n = T - 1
        V = self.vocab_size
        loss = 0.0
        dlogits = [[0.0] * V for _ in range(T)]
        for t in range(n):
            y = tgt[t]
            if not isinstance(y, int) or isinstance(y, bool) or not 0 <= y < V:
                raise ValueError(f"LlamaModel.loss_and_backward: 第 {t} 个 target {y!r} 越界")
            p = _softmax_row(logits[t])
            loss -= math.log(max(p[y], 1e-12))
            scale = 1.0 / n
            row = dlogits[t]
            for v in range(V):
                row[v] = (p[v] - (1.0 if v == y else 0.0)) * scale
        loss /= n
        self._backward_from_logits(dlogits)
        return loss

    def adam_step(self, lr: float):
        """对全部参数做一次 Adam 更新（梯度已由 loss_and_backward 累积）"""
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"LlamaModel.adam_step: lr 必须是非负数，收到 {lr!r}")
        self.step_count += 1
        t = self.step_count
        for name, param, grad in self._named_params():
            m = self._adam_m.get(name)
            v = self._adam_v.get(name)
            if m is None:
                m = _zeros_like(param)
                v = _zeros_like(param)
                self._adam_m[name] = m
                self._adam_v[name] = v
            _adam_apply(param, grad, m, v, t, lr)

    def fit(self, sequences, epochs: int = 1, lr: float = 3e-3,
            shuffle: bool = True, seed=None, verbose: bool = False):
        """在若干条 token 序列上训练，返回每个 epoch 的平均 loss"""
        if not isinstance(sequences, (list, tuple)) or not sequences:
            raise ValueError("LlamaModel.fit: sequences 必须是非空列表")
        seqs = []
        for i, s in enumerate(sequences):
            if not isinstance(s, (list, tuple)) or len(s) < 2:
                raise ValueError(f"LlamaModel.fit: 第 {i} 条序列至少需要 2 个 token")
            if len(s) > self.max_len:
                raise ValueError(
                    f"LlamaModel.fit: 第 {i} 条序列长度 {len(s)} 超过 max_len={self.max_len}")
            seqs.append(list(s))
        if not isinstance(epochs, int) or isinstance(epochs, bool) or epochs < 1:
            raise ValueError(f"LlamaModel.fit: epochs 必须是正整数，收到 {epochs!r}")
        rng = random.Random(seed)
        order = list(range(len(seqs)))
        history = []
        for ep in range(epochs):
            if shuffle:
                rng.shuffle(order)
            total = 0.0
            for idx in order:
                self.zero_grad()
                total += self.loss_and_backward(seqs[idx])
                self.adam_step(lr)
            avg = total / len(seqs)
            history.append(avg)
            if verbose:
                print(f"  Llama epoch {ep + 1}/{epochs} | loss {avg:.4f}")
        return history

    def generate(self, prompt_ids, max_new_tokens: int = 16,
                 temperature: float = 1.0, top_k: int = 0, seed=None):
        """自回归生成（每步整段重算，未接 KV cache；教学用）"""
        if not prompt_ids:
            raise ValueError("LlamaModel.generate: prompt_ids 不能为空")
        if not isinstance(max_new_tokens, int) or isinstance(max_new_tokens, bool) \
                or max_new_tokens < 0:
            raise ValueError(
                f"LlamaModel.generate: max_new_tokens 必须是非负整数，收到 {max_new_tokens!r}")
        rng = random.Random(seed)
        out = [int(x) for x in prompt_ids][-self.max_len:]
        for _ in range(max_new_tokens):
            ctx = out[-self.max_len:]
            logits = self.forward(ctx)[-1]
            out.append(self._sample(logits, temperature, top_k, rng))
        return out

    def _sample(self, logits, temperature, top_k, rng):
        V = self.vocab_size
        if temperature is None or temperature <= 0:
            return max(range(V), key=lambda i: logits[i])
        scaled = [v / temperature for v in logits]
        if top_k and top_k > 0:
            cand = sorted(range(V), key=lambda i: (-scaled[i], i))[:top_k]
            row = [scaled[i] for i in cand]
        else:
            cand = list(range(V))
            row = scaled
        p = _softmax_row(row)
        r = rng.random()
        acc = 0.0
        for tok, prob in zip(cand, p):
            acc += prob
            if r <= acc:
                return tok
        return cand[-1]


class ResNet:
    """完整 ResNet（CIFAR 风格）组合类：

        stem: Conv2d(3×3) → BatchNorm2d → ReLU
        stage: 若干 Bottleneck2d（每个 stage 的第一个用 stride=2 下采样）
        head : AdaptiveAvgPool2d((1,1)) → Flatten → 全连接分类头

    只支持单样本输入 (C, H, W)；批量训练由调用者循环（与 Conv2d 的约定一致）。
    参数更新（Conv / BatchNorm / 分类头）由 `adam_step` 统一处理。
    """

    def __init__(self, in_channels: int = 3, num_classes: int = 10,
                 stem_channels: int = 16, channel_plan=(16, 32, 64),
                 blocks_per_stage=(2, 2, 2)):
        for name, value in (("in_channels", in_channels), ("num_classes", num_classes),
                            ("stem_channels", stem_channels)):
            if isinstance(value, bool) or not isinstance(value, int) or value < 1:
                raise ValueError(f"ResNet: {name} 必须是正整数，收到 {value!r}")
        channel_plan = tuple(channel_plan)
        blocks_per_stage = tuple(blocks_per_stage)
        if not channel_plan or len(channel_plan) != len(blocks_per_stage):
            raise ValueError(
                "ResNet: channel_plan 与 blocks_per_stage 必须等长且非空")
        for c, n in zip(channel_plan, blocks_per_stage):
            if not isinstance(c, int) or isinstance(c, bool) or c < 1:
                raise ValueError(f"ResNet: channel_plan 里的 {c!r} 必须是正整数")
            if not isinstance(n, int) or isinstance(n, bool) or n < 1:
                raise ValueError(f"ResNet: blocks_per_stage 里的 {n!r} 必须是正整数")

        self.in_channels = in_channels
        self.num_classes = num_classes
        self.stem_channels = stem_channels
        self.stem = Conv2d(in_channels, stem_channels, 3, stride=1, padding=1)
        self.stem_bn = BatchNorm2d(stem_channels)

        self.stages = []
        cin = stem_channels
        for si, (c_out, n) in enumerate(zip(channel_plan, blocks_per_stage)):
            blocks = []
            for bi in range(n):
                stride = 2 if (si > 0 and bi == 0) else 1
                blocks.append(Bottleneck2d(cin if bi == 0 else c_out, c_out, stride))
            self.stages.append(blocks)
            cin = c_out
        self.head_in = cin
        self.pool = AdaptiveAvgPool2d((1, 1))
        self.flatten = Flatten()

        std = math.sqrt(2.0 / self.head_in)
        self.W_out = [[random.gauss(0.0, std) for _ in range(self.head_in)]
                      for _ in range(num_classes)]
        self.b_out = [0.0] * num_classes
        self._adam_m = {}
        self._adam_v = {}
        self.step_count = 0
        self._cache = None
        self.zero_grad()

    # ---- 参数 / 梯度 --------------------------------------------------------
    def zero_grad(self):
        self.stem.zero_grad()
        for stage in self.stages:
            for block in stage:
                block.zero_grad()
        n_bn = len(self.stem_bn.gamma)
        self.grads = {
            "stem_bn_gamma": [0.0] * n_bn,
            "stem_bn_beta": [0.0] * n_bn,
            "W_out": [[0.0] * self.head_in for _ in range(self.num_classes)],
            "b_out": [0.0] * self.num_classes,
        }

    def param_count(self):
        total = _conv_param_count(self.stem) + 2 * len(self.stem_bn.gamma)
        for stage in self.stages:
            for block in stage:
                total += block.param_count()
        total += self.num_classes * self.head_in + self.num_classes
        return total

    def train(self):
        self.stem_bn.train()
        for stage in self.stages:
            for block in stage:
                block.train()
        return self

    def eval(self):
        self.stem_bn.eval()
        for stage in self.stages:
            for block in stage:
                block.eval()
        return self

    # ---- 前向 / 反向 --------------------------------------------------------
    @staticmethod
    def _relu3(x):
        return [[[v if v > 0.0 else 0.0 for v in row] for row in ch] for ch in x]

    def _check_image(self, x, who):
        if not isinstance(x, (list, tuple)) or not x:
            raise ValueError(f"{who}: 输入不能为空")
        c = len(x)
        if c != self.in_channels:
            raise ValueError(f"{who}: 通道数 {c} != in_channels={self.in_channels}")
        h = len(x[0])
        if h < 1:
            raise ValueError(f"{who}: H 不能为 0")
        w = len(x[0][0])
        if w < 1:
            raise ValueError(f"{who}: W 不能为 0")
        for ch in x:
            if len(ch) != h or any(len(row) != w for row in ch):
                raise ValueError(f"{who}: 各通道的 H/W 必须一致")
        return c, h, w

    def logits(self, x):
        """x: (C, H, W) → logits (num_classes,)"""
        self._check_image(x, "ResNet.forward")
        stem_out = self.stem.forward(x)
        bn_out = self.stem_bn.forward(stem_out)
        act = self._relu3(bn_out)
        h = act
        for stage in self.stages:
            for block in stage:
                h = block.forward(h)
        pooled = self.pool.forward(h)
        flat = self.flatten.forward(pooled)
        self._cache = (stem_out, bn_out, flat)
        return [sum(map(_mul, self.W_out[v], flat)) + self.b_out[v]
                for v in range(self.num_classes)]

    def loss_and_backward(self, x, label: int):
        """softmax 交叉熵；返回 loss，梯度已累积（分类头 / BN / Conv）"""
        if not isinstance(label, int) or isinstance(label, bool) \
                or not 0 <= label < self.num_classes:
            raise ValueError(f"ResNet.loss_and_backward: label {label!r} 越界")
        logits = self.logits(x)
        p = _softmax_row(logits)
        loss = -math.log(max(p[label], 1e-12))
        dlogits = [p[v] - (1.0 if v == label else 0.0) for v in range(self.num_classes)]
        stem_out, bn_out, flat = self._cache

        for v in range(self.num_classes):
            row = self.grads["W_out"][v]
            for j in range(self.head_in):
                row[j] += dlogits[v] * flat[j]
            self.grads["b_out"][v] += dlogits[v]

        d_flat = [sum(dlogits[v] * self.W_out[v][j] for v in range(self.num_classes))
                  for j in range(self.head_in)]
        dpool = self.flatten.backward(d_flat)       # (C, 1, 1)
        dh = self.pool.backward(dpool)              # (C, H, W)
        for stage in reversed(self.stages):
            for block in reversed(stage):
                dh = block.backward(dh)
        # stem: BN → ReLU（用 BN 输出做 ReLU mask）
        d_bn = [[[dh[c][h][w] if bn_out[c][h][w] > 0.0 else 0.0
                  for w in range(len(dh[c][h]))]
                 for h in range(len(dh[c]))] for c in range(len(dh))]
        d_stem, g_bn, b_bn = self.stem_bn.backward(d_bn)
        for c in range(len(g_bn)):
            self.grads["stem_bn_gamma"][c] += g_bn[c]
            self.grads["stem_bn_beta"][c] += b_bn[c]
        self.stem.backward(d_stem)
        return loss

    def _adam_param(self, name, param, grad, t, lr):
        m = self._adam_m.get(name)
        v = self._adam_v.get(name)
        if m is None:
            m = _zeros_like(param)
            v = _zeros_like(param)
            self._adam_m[name] = m
            self._adam_v[name] = v
        _adam_apply(param, grad, m, v, t, lr)

    def adam_step(self, lr: float, beta1: float = 0.9, beta2: float = 0.999,
                  eps: float = 1e-8):
        """更新 Conv / BatchNorm / 分类头（梯度已由 loss_and_backward 累积）"""
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0:
            raise ValueError(f"ResNet.adam_step: lr 必须是非负数，收到 {lr!r}")
        self.step_count += 1
        t = self.step_count
        _conv_adam(self.stem, lr, beta1, beta2, eps)
        for stage in self.stages:
            for block in stage:
                block.adam_step(lr, beta1, beta2, eps)
        self._adam_param("stem_bn.gamma", self.stem_bn.gamma,
                         self.grads["stem_bn_gamma"], t, lr)
        self._adam_param("stem_bn.beta", self.stem_bn.beta,
                         self.grads["stem_bn_beta"], t, lr)
        for si, stage in enumerate(self.stages):
            for bi, block in enumerate(stage):
                for tag, bn in (("bn1", block.bn1), ("bn2", block.bn2),
                                ("bn3", block.bn3), ("short", block.short_bn)):
                    if bn is None:
                        continue
                    self._adam_param(f"L{si}.{bi}.{tag}.gamma", bn.gamma,
                                     block.bn_grads[tag + "_gamma"], t, lr)
                    self._adam_param(f"L{si}.{bi}.{tag}.beta", bn.beta,
                                     block.bn_grads[tag + "_beta"], t, lr)
        self._adam_param("head.W", self.W_out, self.grads["W_out"], t, lr)
        self._adam_param("head.b", self.b_out, self.grads["b_out"], t, lr)

    def fit(self, images, labels, epochs: int = 1, lr: float = 3e-3,
            shuffle: bool = True, seed=None, verbose: bool = False):
        """在若干张 (C,H,W) 图像上训练分类头，返回每个 epoch 的平均 loss"""
        if not isinstance(images, (list, tuple)) or not images:
            raise ValueError("ResNet.fit: images 必须是非空列表")
        if not isinstance(labels, (list, tuple)) or len(labels) != len(images):
            raise ValueError("ResNet.fit: labels 必须与 images 等长")
        if not isinstance(epochs, int) or isinstance(epochs, bool) or epochs < 1:
            raise ValueError(f"ResNet.fit: epochs 必须是正整数，收到 {epochs!r}")
        for i, img in enumerate(images):
            self._check_image(img, f"ResNet.fit 第 {i} 张图")
            lab = labels[i]
            if not isinstance(lab, int) or isinstance(lab, bool) \
                    or not 0 <= lab < self.num_classes:
                raise ValueError(f"ResNet.fit: 第 {i} 个 label {lab!r} 越界")
        rng = random.Random(seed)
        order = list(range(len(images)))
        history = []
        for ep in range(epochs):
            if shuffle:
                rng.shuffle(order)
            total = 0.0
            for idx in order:
                self.zero_grad()
                total += self.loss_and_backward(images[idx], labels[idx])
                self.adam_step(lr)
            avg = total / len(images)
            history.append(avg)
            if verbose:
                print(f"  ResNet epoch {ep + 1}/{epochs} | loss {avg:.4f}")
        return history


class T5Model(Seq2SeqLM):
    """T5 式编码器-解码器：自注意力注入可学习相对位置偏置（T5RelativeBias）

    与 Seq2SeqLM 的唯一区别是每层自注意力额外带一个相对位置偏置表：
    encoder 用双向桶（bidirectional=True），decoder 用因果桶
    （bidirectional=False）；交叉注意力与 T5 论文一致，不加相对偏置。
    其余前向、训练、评估、生成逻辑全部复用 Seq2SeqLM。

    用法::

        model = T5Model(src_vocab=10, tgt_vocab=10, d_model=16, num_heads=2)
        model.fit([([1, 2, 3], [4, 5, 6])], epochs=20, lr=0.01)
    """

    def __init__(self, src_vocab: int, tgt_vocab: int, d_model: int = 32,
                 num_heads: int = 4, d_ff: int = 64, num_layers: int = 2,
                 max_len: int = 64, dropout: float = 0.0,
                 num_buckets: int = 32, max_distance: int = 128):
        # 先占位，父类 __init__ 末尾会调用 zero_grad（基类版本，不碰这两个列表）
        self.enc_bias = []
        self.dec_bias = []
        super().__init__(src_vocab, tgt_vocab, d_model=d_model,
                         num_heads=num_heads, d_ff=d_ff, num_layers=num_layers,
                         max_len=max_len, dropout=dropout)
        for layer in self.encoder.layers:
            op = T5RelativeBias(num_heads, num_buckets, max_distance,
                                bidirectional=True)
            layer.self_attn.relative_bias = op
            self.enc_bias.append(op)
        for layer in self.decoder.layers:
            op = T5RelativeBias(num_heads, num_buckets, max_distance,
                                bidirectional=False)
            layer.self_attn.relative_bias = op
            self.dec_bias.append(op)
        self.zero_grad()

    def _named_params(self):
        """父类参数 + 各层相对偏置表（每桶一行作为 1D 参数参与 Adam）"""
        for item in super()._named_params():
            yield item
        for tag, ops in (("enc", self.enc_bias), ("dec", self.dec_bias)):
            for li, op in enumerate(ops):
                for b in range(op.num_buckets):
                    yield (f"{tag}.L{li}.t5_bias.b{b}",
                           op.table[b], op.grad_table[b])

    def param_count(self):
        """参数总数（标量个数；父类实现已遍历本类的 _named_params，含相对偏置表）"""
        return super().param_count()


class BertModel:
    """BERT 式掩码语言模型：MLM + NSP 双头

    结构::

        token_embedding + seg_embedding → PositionalEncoding → TransformerEncoder ─┬→ MLM 头（全词表）
                                                                                   └→ NSP 头（取 [CLS] 位置）

    与 MaskedLM 的区别：这里同时训练 NSP（下一句预测），并且由调用者完全掌控
    哪些位置被 mask（便于教学和可控实验）。训练样本是五元组::

        (input_ids, mask_positions, mask_labels, segment_ids, nsp_label)

    - ``mask_positions``：被 mask 的位置下标列表（MLM 只在这些位置算损失）
    - ``mask_labels``：与之一一对应的正确 token id
    - ``segment_ids``：与 input_ids 等长的 0/1 列表（句 A / 句 B），None 视为全 0
    - ``nsp_label``：0 或 1；None 表示这条样本不计算 NSP 损失
    """

    def __init__(self, vocab_size: int, d_model: int = 32, num_heads: int = 4,
                 d_ff: int = 64, num_layers: int = 2, max_len: int = 64,
                 dropout: float = 0.0):
        if isinstance(vocab_size, bool) or not isinstance(vocab_size, int) \
                or vocab_size < 1:
            raise ValueError(f"BertModel: vocab_size 必须是正整数，收到 {vocab_size!r}")
        self.vocab_size = vocab_size
        self.d_model = d_model
        self.max_len = max_len
        self.step_count = 0
        self._adam_m = {}
        self._adam_v = {}

        self.token_embedding = Embedding(vocab_size, d_model)
        self.seg_embedding = Embedding(2, d_model)
        self.pos = PositionalEncoding(d_model, max_len)
        self.encoder = TransformerEncoder(d_model, num_heads, d_ff, num_layers,
                                          dropout)

        std = math.sqrt(2.0 / d_model)
        self.W_mlm = [[random.gauss(0, std) for _ in range(d_model)]
                      for _ in range(vocab_size)]
        self.b_mlm = [0.0] * vocab_size
        self.W_nsp = [[random.gauss(0, std) for _ in range(d_model)]
                      for _ in range(2)]
        self.b_nsp = [0.0] * 2

        self.zero_grad()
        self.h = None            # 最近一次前向的编码器输出（反向要用）
        self._seg_ids = None     # 最近一次前向的 segment ids（反向要用）

    def train(self):
        """训练模式：编码器 Dropout 生效"""
        self.encoder.train()
        return self

    def eval(self):
        """推理模式：关闭 Dropout"""
        self.encoder.eval()
        return self

    def zero_grad(self):
        """清零全部梯度（两个 embedding、编码器、MLM/NSP 头）"""
        self.token_embedding.zero_grad()
        self.seg_embedding.zero_grad()
        self.encoder.zero_grad()
        self.grads = {
            "W_mlm": [[0.0] * self.d_model for _ in range(self.vocab_size)],
            "b_mlm": [0.0] * self.vocab_size,
            "W_nsp": [[0.0] * self.d_model for _ in range(2)],
            "b_nsp": [0.0] * 2,
        }

    def _named_params(self):
        """产出 (名字, 参数, 梯度)；名字保证 Adam 的矩跨步稳定"""
        yield ("tok_emb.weight", self.token_embedding.weight,
               self.token_embedding.grad_weight)
        yield ("seg_emb.weight", self.seg_embedding.weight,
               self.seg_embedding.grad_weight)
        for li, layer in enumerate(self.encoder.layers):
            attn = layer.self_attn
            for k in ("W_q", "W_k", "W_v", "W_o", "b_q", "b_k", "b_v", "b_o"):
                yield (f"enc.L{li}.attn.{k}", getattr(attn, k), attn.grads[k])
            ffn = layer.ffn
            for k in ("W1", "b1", "W2", "b2"):
                yield (f"enc.L{li}.ffn.{k}", getattr(ffn, k), ffn.grads[k])
            for ln in ("ln1", "ln2"):
                mod = getattr(layer, ln)
                yield (f"enc.L{li}.{ln}.gamma", mod.gamma,
                       layer.grads[ln + "_gamma"])
                yield (f"enc.L{li}.{ln}.beta", mod.beta,
                       layer.grads[ln + "_beta"])
        yield ("mlm.W", self.W_mlm, self.grads["W_mlm"])
        yield ("mlm.b", self.b_mlm, self.grads["b_mlm"])
        yield ("nsp.W", self.W_nsp, self.grads["W_nsp"])
        yield ("nsp.b", self.b_nsp, self.grads["b_nsp"])

    def param_count(self):
        """参数总数（标量个数）"""
        return sum(len(p) if not isinstance(p[0], list) else
                   sum(len(r) for r in p)
                   for _, p, _ in self._named_params())

    def forward(self, input_ids, segment_ids=None):
        """返回编码器输出 hidden (T, d_model)；segment_ids 长度须与输入一致"""
        if not input_ids:
            raise ValueError("BertModel.forward: input_ids 不能为空")
        if len(input_ids) > self.max_len:
            raise ValueError(
                f"BertModel.forward: 序列长度 {len(input_ids)} 超过 max_len={self.max_len}")
        ids = _check_token_ids(input_ids, self.vocab_size, "BertModel.forward")
        if segment_ids is None:
            seg = [0] * len(ids)
        else:
            if len(segment_ids) != len(ids):
                raise ValueError(
                    "BertModel.forward: segment_ids 长度必须与 input_ids 一致")
            seg = []
            for s in segment_ids:
                if isinstance(s, bool) or not isinstance(s, int) or s not in (0, 1):
                    raise ValueError(
                        f"BertModel.forward: segment id 只能是 0/1，收到 {s!r}")
                seg.append(s)
        tok = self.token_embedding.forward(ids)
        segv = self.seg_embedding.forward(seg)
        emb = [[tok[t][j] + segv[t][j] for j in range(self.d_model)]
               for t in range(len(ids))]
        x = self.pos.forward(emb)
        self.h = self.encoder.forward(x)
        self._seg_ids = list(seg)
        return self.h

    def masked_lm_logits(self, positions=None):
        """返回 MLM 头 logits：positions=None 时对全部位置，否则只取指定位置"""
        if self.h is None:
            raise RuntimeError("BertModel.masked_lm_logits: 需要先 forward")
        if positions is None:
            positions = list(range(len(self.h)))
        out = []
        for pos in positions:
            if isinstance(pos, bool) or not isinstance(pos, int) \
                    or not 0 <= pos < len(self.h):
                raise ValueError(
                    f"BertModel.masked_lm_logits: 位置 {pos!r} 越界")
            hv = self.h[pos]
            out.append([sum(map(_mul, self.W_mlm[v], hv)) + self.b_mlm[v]
                        for v in range(self.vocab_size)])
        return out

    def nsp_logits(self):
        """返回 NSP 头 logits（长度 2，输入是 [CLS] 位置的隐状态）"""
        if self.h is None:
            raise RuntimeError("BertModel.nsp_logits: 需要先 forward")
        hv = self.h[0]
        return [sum(map(_mul, self.W_nsp[v], hv)) + self.b_nsp[v]
                for v in range(2)]

    def loss_and_backward(self, input_ids, mask_positions, mask_labels,
                          segment_ids=None, nsp_label=None,
                          lm_weight: float = 1.0, nsp_weight: float = 1.0):
        """一次前向 + MLM/NSP 联合损失反向，返回 loss（标量）"""
        if lm_weight < 0.0 or nsp_weight < 0.0:
            raise ValueError("BertModel.loss_and_backward: 权重必须是非负数")
        h = self.forward(input_ids, segment_ids)
        d_h = [[0.0] * self.d_model for _ in range(len(h))]
        loss = 0.0

        # ---- MLM：只在给定位置算交叉熵 ----
        mask_positions = list(mask_positions or [])
        mask_labels = list(mask_labels or [])
        if len(mask_positions) != len(mask_labels):
            raise ValueError(
                "BertModel.loss_and_backward: mask_positions 与 mask_labels 长度不一致")
        for pos, label in zip(mask_positions, mask_labels):
            if isinstance(pos, bool) or not isinstance(pos, int) \
                    or not 0 <= pos < len(h):
                raise ValueError(
                    f"BertModel.loss_and_backward: mask 位置 {pos!r} 越界")
            if isinstance(label, bool) or not isinstance(label, int) \
                    or not 0 <= label < self.vocab_size:
                raise ValueError(
                    f"BertModel.loss_and_backward: mask 标签 {label!r} 越界")
            hv = h[pos]
            logits = [sum(map(_mul, self.W_mlm[v], hv)) + self.b_mlm[v]
                      for v in range(self.vocab_size)]
            probs = _softmax_row(logits)
            loss += -math.log(max(probs[label], 1e-12)) * lm_weight
            didx = [probs[v] - (1.0 if v == label else 0.0)
                    for v in range(self.vocab_size)]
            for v in range(self.vocab_size):
                dv = didx[v]
                if dv == 0.0:
                    continue
                wrow = self.W_mlm[v]
                grad_row = self.grads["W_mlm"][v]
                dvw = dv * lm_weight
                for j in range(self.d_model):
                    grad_row[j] += dvw * hv[j]
                    d_h[pos][j] += dvw * wrow[j]
                self.grads["b_mlm"][v] += dvw

        # ---- NSP：取第 0 个位置（[CLS]）的二分类 ----
        if nsp_label is not None:
            if isinstance(nsp_label, bool) or not isinstance(nsp_label, int) \
                    or nsp_label not in (0, 1):
                raise ValueError(
                    f"BertModel.loss_and_backward: nsp_label 只能是 0/1，收到 {nsp_label!r}")
            hv = h[0]
            logits = self.nsp_logits()
            probs = _softmax_row(logits)
            loss += -math.log(max(probs[nsp_label], 1e-12)) * nsp_weight
            for v in range(2):
                dv = (probs[v] - (1.0 if v == nsp_label else 0.0)) * nsp_weight
                if dv == 0.0:
                    continue
                wrow = self.W_nsp[v]
                grad_row = self.grads["W_nsp"][v]
                for j in range(self.d_model):
                    grad_row[j] += dv * hv[j]
                    d_h[0][j] += dv * wrow[j]
                self.grads["b_nsp"][v] += dv

        # ---- 反向穿过编码器与 embedding ----
        d_enc = self.encoder.backward(d_h)
        self.token_embedding.backward(d_enc)
        self.seg_embedding.backward(d_enc)
        return loss

    def adam_step(self, lr: float):
        """对全部参数做一次 Adam 更新（梯度由 loss_and_backward 累积）"""
        if not isinstance(lr, (int, float)) or isinstance(lr, bool) or lr < 0.0:
            raise ValueError(f"BertModel.adam_step: lr 必须是非负数，收到 {lr!r}")
        self.step_count += 1
        t = self.step_count
        for name, param, grad in self._named_params():
            m = self._adam_m.get(name)
            v = self._adam_v.get(name)
            if m is None:
                m = _zeros_like(param)
                v = _zeros_like(param)
                self._adam_m[name] = m
                self._adam_v[name] = v
            _adam_apply(param, grad, m, v, t, lr)

    def fit(self, samples, epochs: int = 1, lr: float = 3e-3,
            shuffle: bool = True, seed=None, verbose: bool = False):
        """在若干五元组样本上训练，返回每个 epoch 的平均 loss"""
        items = list(samples)
        if not items:
            raise ValueError("BertModel.fit: samples 不能为空")
        if isinstance(epochs, bool) or not isinstance(epochs, int) or epochs < 0:
            raise ValueError(f"BertModel.fit: epochs 不能为负，收到 {epochs!r}")
        rng = random.Random(seed) if seed is not None else random
        history = []
        self.train()
        for ep in range(epochs):
            order = list(range(len(items)))
            if shuffle:
                rng.shuffle(order)
            total = 0.0
            for idx in order:
                ids, positions, labels, seg, nsp = items[idx]
                self.zero_grad()
                total += self.loss_and_backward(ids, positions, labels,
                                                seg, nsp)
                self.adam_step(lr)
            avg = total / len(items)
            history.append(avg)
            if verbose:
                print(f"epoch {ep + 1}/{epochs} loss={avg:.4f}")
        return history


class ConvNeXt:
    """ConvNeXt（完整网络）：patchify stem -> 多 stage 堆叠 -> 全局池化 -> 分类头

    结构（channels-first，输入 `(C,H,W)`）：

        stem:  Conv2d(C -> c0, k=2, stride=2) -> GELU
        stage: 每个 stage 由 `blocks_per_stage[i]` 个 `ConvNeXtBlock(c_i)` 组成；
               stage 之间用 `Conv2d(c_i -> c_{i+1}, k=2, stride=2)` 下采样
        head:  全局平均池化 -> `Conv2d(c_last -> num_classes, k=1)`

    `forward` 返回长度 `num_classes` 的 logits；`backward(dlogits)` 返回输入梯度，
    内部梯度就地累加（调用前先 `zero_grad()`）。输入 H、W 必须能被
    `2 ** len(channel_plan)` 整除（stem 一次 + 每个 stage 之间一次下采样）。
    """

    def __init__(self, in_channels: int = 3, num_classes: int = 10,
                 channel_plan=(8, 16, 32), blocks_per_stage=(1, 1, 1),
                 kernel_size: int = 7, expansion: int = 4, eps: float = 1e-6):
        for name, val in (("in_channels", in_channels),
                          ("num_classes", num_classes)):
            if isinstance(val, bool) or not isinstance(val, int) or val < 1:
                raise ValueError(
                    f"ConvNeXt: {name} 必须是 >=1 的整数，收到 {val!r}")
        if (not isinstance(channel_plan, (tuple, list)) or not channel_plan
                or any(isinstance(v, bool) or not isinstance(v, int) or v < 1
                       for v in channel_plan)):
            raise ValueError("ConvNeXt: channel_plan 必须是非空的 >=1 整数序列")
        if (not isinstance(blocks_per_stage, (tuple, list))
                or len(blocks_per_stage) != len(channel_plan)
                or any(isinstance(v, bool) or not isinstance(v, int) or v < 1
                       for v in blocks_per_stage)):
            raise ValueError(
                "ConvNeXt: blocks_per_stage 必须与 channel_plan 等长且全为正整数")
        self.in_channels = in_channels
        self.num_classes = num_classes
        self.channel_plan = [int(v) for v in channel_plan]
        self.blocks_per_stage = [int(v) for v in blocks_per_stage]
        self.kernel_size = kernel_size
        self.expansion = expansion
        self.eps = eps
        c0 = self.channel_plan[0]
        self.stem = Conv2d(in_channels, c0, 2, stride=2)
        self.blocks = []
        for i, c in enumerate(self.channel_plan):
            self.blocks.append([
                ConvNeXtBlock(c, kernel_size, expansion, eps)
                for _ in range(self.blocks_per_stage[i])
            ])
        self.downs = [
            Conv2d(self.channel_plan[i], self.channel_plan[i + 1], 2, stride=2)
            for i in range(len(self.channel_plan) - 1)
        ]
        self.head = Conv2d(self.channel_plan[-1], num_classes, 1)
        self.training = True
        self._cache = None

    # ---------- 形状校验 ----------
    def _check_image(self, x, who):
        if not isinstance(x, (list, tuple)) or not x:
            raise ValueError(
                f"ConvNeXt.{who}: 输入必须是 (C,H,W) 非空嵌套 list")
        C = len(x)
        if C != self.in_channels:
            raise ValueError(
                f"ConvNeXt.{who}: 输入通道数 {C} 与 in_channels="
                f"{self.in_channels} 不符")
        H = len(x[0]) if isinstance(x[0], (list, tuple)) else 0
        if H < 1 or not isinstance(x[0][0], (list, tuple)) or not x[0][0]:
            raise ValueError(f"ConvNeXt.{who}: 输入必须是 (C,H,W) 非空嵌套 list")
        W = len(x[0][0])
        for c in range(C):
            ch = x[c]
            if not isinstance(ch, (list, tuple)) or len(ch) != H:
                raise ValueError(
                    f"ConvNeXt.{who}: 第 {c} 个通道行数不一致（应为 {H}）")
            for h in range(H):
                row = ch[h]
                if not isinstance(row, (list, tuple)) or len(row) != W:
                    raise ValueError(
                        f"ConvNeXt.{who}: 第 {c} 通道第 {h} 行长度不一致（应为 {W}）")
        factor = 2 ** len(self.channel_plan)
        if H % factor != 0 or W % factor != 0:
            raise ValueError(
                f"ConvNeXt.{who}: 输入 {H}x{W} 必须能被下采样倍数 {factor} 整除")
        return H, W

    # ---------- 前向 / 反向 ----------
    def forward(self, x):
        self._check_image(x, "forward")
        s = self.stem.forward(x)
        cur = [[[_gelu_scalar(v) for v in row] for row in ch] for ch in s]
        for i in range(len(self.channel_plan)):
            for block in self.blocks[i]:
                cur = block.forward(cur)
            if i < len(self.downs):
                cur = self.downs[i].forward(cur)
        Cf, Hf, Wf = len(cur), len(cur[0]), len(cur[0][0])
        pooled = [sum(sum(row) for row in ch) / (Hf * Wf) for ch in cur]
        head_in = [[[pooled[c]]] for c in range(Cf)]
        out = self.head.forward(head_in)
        self._cache = (s, (Hf, Wf))
        return [out[c][0][0] for c in range(self.num_classes)]

    def backward(self, dlogits):
        if self._cache is None:
            raise RuntimeError("ConvNeXt.backward: 必须先调用 forward()")
        if len(dlogits) != self.num_classes:
            raise ValueError(
                f"ConvNeXt.backward: dlogits 长度 {len(dlogits)} 与 "
                f"num_classes={self.num_classes} 不一致")
        s, (Hf, Wf) = self._cache
        dhead = [[[float(dlogits[c])]] for c in range(self.num_classes)]
        dpool = self.head.backward(dhead)
        C = len(dpool)
        dcur = [[[dpool[c][0][0] / (Hf * Wf) for _ in range(Wf)]
                 for _ in range(Hf)] for c in range(C)]
        for i in range(len(self.channel_plan) - 1, -1, -1):
            for block in reversed(self.blocks[i]):
                dcur = block.backward(dcur)
            if i > 0:
                dcur = self.downs[i - 1].backward(dcur)
        H = len(s[0])
        W = len(s[0][0])
        dstem = [[[dcur[c][h][w] * _dgelu_scalar(s[c][h][w])
                   for w in range(W)] for h in range(H)]
                  for c in range(len(dcur))]
        return self.stem.backward(dstem)

    # ---------- 参数 / 优化器 ----------
    def zero_grad(self):
        self.stem.zero_grad()
        self.head.zero_grad()
        for bl in self.blocks:
            for block in bl:
                block.zero_grad()
        for down in self.downs:
            down.zero_grad()

    def param_count(self):
        total = _conv_param_count(self.stem) + _conv_param_count(self.head)
        for bl in self.blocks:
            for block in bl:
                total += block.param_count()
        for down in self.downs:
            total += _conv_param_count(down)
        return total

    def train(self):
        self.training = True
        for bl in self.blocks:
            for block in bl:
                block.train()
        return self

    def eval(self):
        self.training = False
        for bl in self.blocks:
            for block in bl:
                block.eval()
        return self

    def _check_lr(self, lr, who):
        if isinstance(lr, bool) or not isinstance(lr, (int, float)) or lr < 0:
            raise ValueError(f"ConvNeXt.{who}: lr 必须是非负数，收到 {lr!r}")
        return float(lr)

    def sgd_step(self, lr):
        lr = self._check_lr(lr, "sgd_step")
        _conv_sgd(self.stem, lr)
        _conv_sgd(self.head, lr)
        for bl in self.blocks:
            for block in bl:
                block.sgd_step(lr)
        for down in self.downs:
            _conv_sgd(down, lr)

    def adam_step(self, lr=1e-3, beta1=0.9, beta2=0.999, eps=1e-8):
        lr = self._check_lr(lr, "adam_step")
        _conv_adam(self.stem, lr, beta1, beta2, eps)
        _conv_adam(self.head, lr, beta1, beta2, eps)
        for bl in self.blocks:
            for block in bl:
                block.adam_step(lr, beta1, beta2, eps)
        for down in self.downs:
            _conv_adam(down, lr, beta1, beta2, eps)

    # ---------- 训练循环 ----------
    def fit(self, images, labels, epochs=50, lr=1e-3, shuffle=True,
            seed=None, verbose=False):
        if not isinstance(images, (list, tuple)) or not images:
            raise ValueError("ConvNeXt.fit: images 不能为空")
        if not isinstance(labels, (list, tuple)) or not labels:
            raise ValueError("ConvNeXt.fit: labels 不能为空")
        if len(images) != len(labels):
            raise ValueError(
                f"ConvNeXt.fit: images={len(images)} 与 labels={len(labels)} 数量不一致")
        if isinstance(epochs, bool) or not isinstance(epochs, int) or epochs < 1:
            raise ValueError(f"ConvNeXt.fit: epochs 必须是 >=1 的整数，收到 {epochs!r}")
        lr = self._check_lr(lr, "fit")
        for img in images:
            self._check_image(img, "fit")
        for y in labels:
            if isinstance(y, bool) or not isinstance(y, int) or not (0 <= y < self.num_classes):
                raise ValueError(
                    f"ConvNeXt.fit: 标签必须是 0..{self.num_classes - 1} 的整数，收到 {y!r}")
        rng = random.Random(seed) if seed is not None else random
        order = list(range(len(images)))
        history = []
        for ep in range(epochs):
            if shuffle:
                rng.shuffle(order)
            total = 0.0
            for idx in order:
                self.zero_grad()
                logits = self.forward(images[idx])
                probs = _softmax_row(logits)
                loss = -math.log(max(probs[labels[idx]], 1e-12))
                dlogits = list(probs)
                dlogits[labels[idx]] -= 1.0
                self.backward(dlogits)
                self.adam_step(lr)
                total += loss
            avg = total / len(images)
            history.append(avg)
            if verbose:
                print(f"epoch {ep + 1}/{epochs} loss={avg:.4f}")
        return history


